_PRIVATE_EVALUATOR_PERSISTENCE_LOCK = threading.RLock()
_PRIVATE_EVALUATOR_PERSISTENCE_DEPTH = 0


@contextmanager
def private_evaluator_persistence_scope() -> Iterable[None]:
    """Keep a private evaluator process from teaching or retiming Eve.

    Private probes may call the same resident models and critic used by live
    replies, but their prompts, latency, failures, and temporary call state are
    evaluator evidence, not lived experience.  The process-global scope is
    intentional: reply faculties can use worker threads, while the private CLI
    runs in its own process and cannot overlap ordinary live traffic there.
    """
    global _PRIVATE_EVALUATOR_PERSISTENCE_DEPTH
    with _PRIVATE_EVALUATOR_PERSISTENCE_LOCK:
        _PRIVATE_EVALUATOR_PERSISTENCE_DEPTH += 1
    try:
        yield
    finally:
        with _PRIVATE_EVALUATOR_PERSISTENCE_LOCK:
            _PRIVATE_EVALUATOR_PERSISTENCE_DEPTH = max(
                0, _PRIVATE_EVALUATOR_PERSISTENCE_DEPTH - 1
            )


def private_evaluator_persistence_active() -> bool:
    with _PRIVATE_EVALUATOR_PERSISTENCE_LOCK:
        return _PRIVATE_EVALUATOR_PERSISTENCE_DEPTH > 0


def isolate_private_audit_persistence(
    function: Callable[..., int],
) -> Callable[..., int]:
    """Decorate a command whose ``args.private_audit`` must be read-only."""

    @wraps(function)
    def wrapped(args: argparse.Namespace, *values: object, **kwargs: object) -> int:
        if not bool(getattr(args, "private_audit", False)):
            return function(args, *values, **kwargs)
        with private_evaluator_persistence_scope():
            return function(args, *values, **kwargs)

    return wrapped


def integrated_private_chat_guard_response(
    prompt: str,
    config: Dict[str, object],
) -> Optional[Dict[str, str]]:
    """Run Eve Chat's read-only deterministic guards in live route order.

    The resolver list intentionally excludes parent continuations, bounded
    action choice, and every execution surface.  Resolve lazily so a matched
    guard cannot trigger lower-priority inspection as a side effect.
    """
    resolvers: List[Tuple[str, Callable[[object, Dict[str, object]], object]]] = [
        ("route-contract-diagnostic", route_contract_diagnostic_response),
        ("terse-followup-continuity-guard", terse_followup_continuation_response),
        ("provided-status-bundle-anomaly-guard", provided_status_bundle_anomaly_response),
        ("external-evaluator-probe-guard", external_evaluator_probe_response),
        ("source-runtime-attribution-guard", source_runtime_attribution_response),
        ("stale-action-evidence-guard", stale_action_evidence_response),
        ("fresh-action-no-fit-guard", no_fit_fresh_verification_response),
    ]
    for guard_model, resolver in resolvers:
        guard_result = resolver(prompt, config)
        if guard_result is None:
            continue
        if isinstance(guard_result, dict):
            guard_response = str(guard_result.get("response") or "")
        else:
            guard_response = str(guard_result)
        return {"model": guard_model, "response": guard_response}
    return None

