def resolve_routing_dir(root: Path, extra_candidates: Optional[Iterable[Path]] = None) -> Path:
    candidates: List[Path] = [root / "docs" / "routing"]
    if extra_candidates:
        candidates.extend(extra_candidates)
    for env_name in ("EVE_SOURCE_DIR", "EVE_PROJECT_ROOT"):
        raw = os.environ.get(env_name, "").strip()
        if raw:
            candidates.append(Path(raw).expanduser() / "docs" / "routing")
    candidates.append(Path.home() / "Documents" / "Finances" / "Eve" / "docs" / "routing")
    seen: Set[str] = set()
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except OSError:
            resolved = candidate
        key = str(resolved)
        if key in seen:
            continue
        seen.add(key)
        if (resolved / "route_contracts.json").exists():
            return resolved
    return root / "docs" / "routing"


