# Top-level dirs that may be mirrored as Python packages into the runtime bundle.
#
# The daemon should auto-pick up new first-party Eve packages so a new import
# cannot silently miss runtime sync again. The auto rule is intentionally narrow:
# runtime package roots must either be existing explicit runtime packages or use
# the `eve_` prefix. This keeps sidecars/generated trees such as openclaw/,
# memory/, backups, docs, UI folders, and vendor/lab worktrees out of the daemon
# bundle even if they later gain an incidental __init__.py.
RUNTIME_SYNC_PACKAGE_ALLOWLIST = {"dagster_lab"}
RUNTIME_SYNC_PACKAGE_PREFIXES = ("eve_",)
RUNTIME_SYNC_PACKAGE_EXCLUDES = {
    "EveBackups",
    "__pycache__",
    "bin",
    "build",
    "coordination",
    "data",
    "design",
    "docs",
    "experiments",
    "go",
    "launchd",
    "mac",
    "memory",
    "models",
    "openclaw",
    "reviews",
    "rust",
    "script",
    "tests",
    "vendor",
    "web",
}


def is_runtime_sync_package_name(name: str) -> bool:
    return name in RUNTIME_SYNC_PACKAGE_ALLOWLIST or name.startswith(RUNTIME_SYNC_PACKAGE_PREFIXES)


def first_party_package_dirs() -> "List[Path]":
    """Auto-discover top-level Python packages (dirs with __init__.py) that the
    runtime bundle must mirror. Discovering them — instead of hardcoding each —
    means a NEW package can never be silently omitted from the daemon's runtime,
    which is exactly the omission that caused the May 2026 ModuleNotFound outage."""
    packages: "List[Path]" = []
    try:
        children = sorted(ROOT.iterdir())
    except OSError:
        return packages
    for child in children:
        name = child.name
        if name.startswith(".") or name in RUNTIME_SYNC_PACKAGE_EXCLUDES:
            continue
        if not is_runtime_sync_package_name(name):
            continue
        try:
            if child.is_dir() and not child.is_symlink() and (child / "__init__.py").is_file():
                packages.append(child)
        except OSError:
            continue
    return packages


def live_admitted_epistemic_event_bundle_pairs(
    *,
    manifest_path: Optional[Path] = None,
    runtime_root: Optional[Path] = None,
) -> "List[Tuple[str, Path, Path]]":
    """Return deployable source/runtime pairs for the optional event percept.

    A public lab candidate is evidence, not live code.  It must therefore stay
    out of runtime drift and sync decisions until its manifest contains the
    complete public/private promotion receipt.  Once admitted, the manifest and
    every model file named by its immutable digest contract travel together.
    """
    source_manifest_path = Path(manifest_path or EPISTEMIC_EVENT_MANIFEST_PATH)
    destination_root = Path(runtime_root or RUNTIME_DIR)
    manifest = eve_epistemic.load_event_manifest(source_manifest_path)
    if not manifest or not eve_epistemic.event_manifest_live_admitted(manifest):
        return []
    model_relative = Path(str(manifest.get("model_path") or ""))
    if (
        not str(model_relative)
        or model_relative.is_absolute()
        or ".." in model_relative.parts
    ):
        raise RuntimeError("admitted epistemic event model_path must be runtime-relative")
    model_files = (
        manifest.get("model_files_sha256")
        if isinstance(manifest.get("model_files_sha256"), dict)
        else {}
    )
    pairs: "List[Tuple[str, Path, Path]]" = []
    for relative_text in sorted(str(value) for value in model_files):
        relative = Path(relative_text)
        if relative.is_absolute() or ".." in relative.parts:
            raise RuntimeError("admitted epistemic event model bundle path is invalid")
        source = ROOT / model_relative / relative
        destination = destination_root / model_relative / relative
        pairs.append((str(model_relative / relative), source, destination))
    pairs.append(
        (
            EPISTEMIC_EVENT_MANIFEST_NAME,
            source_manifest_path,
            destination_root / EPISTEMIC_EVENT_MANIFEST_NAME,
        )
    )
    return pairs


def epistemic_event_admission_record(path: Path) -> Dict[str, object]:
    """Describe one event-model manifest without turning candidacy into drift."""
    candidate = Path(path)
    exists = candidate.is_file()
    manifest = eve_epistemic.load_event_manifest(candidate) if exists else None
    admission = (
        manifest.get("admission")
        if isinstance(manifest, dict) and isinstance(manifest.get("admission"), dict)
        else {}
    )
    public_gate = (
        admission.get("public_validation_gate")
        if isinstance(admission.get("public_validation_gate"), dict)
        else {}
    )
    return {
        "path": str(candidate),
        "exists": exists,
        "valid": bool(manifest),
        "status": str(admission.get("status") or ("invalid" if exists else "missing")),
        "public_gate_passed": public_gate.get("passed") is True,
        "private_receipt_present": isinstance(admission.get("private_holdout_receipt"), dict),
        "live_admitted": bool(
            manifest and eve_epistemic.event_manifest_live_admitted(manifest)
        ),
        "artifact_sha256": str((manifest or {}).get("artifact_sha256") or ""),
    }


def epistemic_event_deployment_truth() -> Dict[str, object]:
    """Report lab/live event-percept boundaries independently of code drift."""
    source = epistemic_event_admission_record(EPISTEMIC_EVENT_MANIFEST_PATH)
    runtime = epistemic_event_admission_record(
        RUNTIME_DIR / EPISTEMIC_EVENT_MANIFEST_NAME
    )
    source_live = bool(source.get("live_admitted"))
    runtime_live = bool(runtime.get("live_admitted"))
    hashes_match = bool(
        source_live
        and runtime_live
        and source.get("artifact_sha256")
        and source.get("artifact_sha256") == runtime.get("artifact_sha256")
    )
    if source_live:
        deployment_status = "live_synced" if hashes_match else "admitted_source_not_live"
    elif source.get("exists"):
        deployment_status = (
            "source_candidate_isolated_runtime_live"
            if runtime_live
            else "source_candidate_isolated"
        )
    elif runtime_live:
        deployment_status = "runtime_live_without_source_manifest"
    else:
        deployment_status = "not_available"
    return {
        "status": deployment_status,
        "blocks_core_runtime_sync": False,
        "source": source,
        "runtime": runtime,
    }


def first_party_python_source_pairs() -> "List[Tuple[str, Path, Path]]":
    """Source/runtime pairs for first-party code and required learned artifacts.

    The doctor source/runtime truth check derives its coverage from this same
    manifest, so a valid model file cannot silently differ between the source
    checkout and the live Eve runtime.
    """
    pairs: "List[Tuple[str, Path, Path]]" = []
    for source in sorted(ROOT.glob("*.py")):
        pairs.append((source.name, source, RUNTIME_DIR / source.name))
    for package_dir in first_party_package_dirs():
        for source in sorted(package_dir.rglob("*.py")):
            if "__pycache__" in source.parts:
                continue
            try:
                rel = source.relative_to(ROOT)
            except ValueError:
                continue
            pairs.append((str(rel), source, RUNTIME_DIR / rel))
    if EPISTEMIC_MODEL_PATH.exists():
        pairs.append(
            (
                EPISTEMIC_MODEL_ARTIFACT_NAME,
                EPISTEMIC_MODEL_PATH,
                RUNTIME_DIR / EPISTEMIC_MODEL_ARTIFACT_NAME,
            )
        )
    pairs.extend(live_admitted_epistemic_event_bundle_pairs())
    return pairs


