def utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def utc_timestamp_for_filename() -> str:
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")


def materialize_local_store() -> None:
    if APP_DIR.exists() and not APP_DIR.is_symlink():
        return

    temp_dir = ROOT / ".eve.materialized"
    if temp_dir.exists():
        if temp_dir.is_dir():
            shutil.rmtree(temp_dir)
        else:
            temp_dir.unlink()
    temp_dir.mkdir(parents=True, exist_ok=True)

    source_dir: Optional[Path] = None
    if APP_DIR.is_symlink():
        source_dir = APP_DIR.resolve()
    elif not APP_DIR.exists() and RUNTIME_APP_DIR.exists():
        source_dir = RUNTIME_APP_DIR

    if source_dir is not None and source_dir.exists():
        for filename in STORE_FILENAMES:
            source = source_dir / filename
            if source.exists():
                shutil.copy2(source, temp_dir / filename)
        source_logs = source_dir / "logs"
        if source_logs.exists():
            shutil.copytree(source_logs, temp_dir / "logs", dirs_exist_ok=True)

    if APP_DIR.is_symlink():
        APP_DIR.unlink()
    elif APP_DIR.exists():
        shutil.rmtree(APP_DIR)

    temp_dir.rename(APP_DIR)


