def load_config() -> Dict[str, object]:
    ensure_store()
    raw = CONFIG_REPOSITORY.load(default=DEFAULT_CONFIG)
    config = dict(DEFAULT_CONFIG)
    config.update(raw)
    config["model_backend"] = normalize_model_backend(config.get("model_backend"))
    config["fast_model_backend"] = normalize_optional_model_backend(config.get("fast_model_backend"))
    config["deep_model_backend"] = normalize_optional_model_backend(config.get("deep_model_backend"))
    config["resident_models"] = [normalize_model_name(item) for item in config.get("resident_models") or [] if normalize_model_name(item)]
    if raw.get("loop_sleep_seconds") in {None, 60}:
        config["loop_sleep_seconds"] = 15
    return config


def save_config(config: Dict[str, object], snapshot_source: str = "config_update") -> None:
    ensure_store()
    merged = dict(DEFAULT_CONFIG)
    merged.update(config)
    CONFIG_REPOSITORY.save(merged)
    ensure_version_snapshot(snapshot_source)


def configured_model_names(config: Dict[str, object]) -> List[str]:
    names: List[str] = []
    for field, value in config.items():
        if field == "model" or field.endswith("_model"):
            candidate = normalize_model_name(value)
            if candidate and candidate not in names:
                names.append(candidate)
    for candidate in [normalize_model_name(item) for item in config.get("resident_models") or []]:
        if candidate and candidate not in names:
            names.append(candidate)
    return names


def code_bundle_should_include(relative_path: Path) -> bool:
    parts = relative_path.parts
    if not parts:
        return False
    if relative_path in CODE_SYNC_EXCLUDED_PATHS:
        return False
    if any(part.startswith((".eve", ".venv")) for part in parts):
        return False
    if any(part in CODE_SYNC_EXCLUDED_NAMES for part in parts):
        return False
    head = parts[0]
    if head == "openclaw" and len(parts) > 1 and parts[1] in {
        "context",
        "dreams",
        "memory",
        "state",
        "wiki",
    }:
        return False
    if relative_path.suffix in {".pyc", ".pyo"}:
        return False
    if len(parts) == 1:
        return (
            relative_path.name in CODE_SYNC_INCLUDED_ROOT_FILES
            or (relative_path.suffix == ".py" and relative_path.name.startswith("eve"))
        )
    if head == "docs":
        return len(parts) > 1 and parts[1] == "routing"
    return head in CODE_SYNC_INCLUDED_ROOT_DIRS


def iter_code_bundle_paths() -> List[Path]:
    paths: List[Path] = []
    for path in ROOT.rglob("*"):
        if not path.is_file():
            continue
        relative = path.relative_to(ROOT)
        if code_bundle_should_include(relative):
            paths.append(relative)
    paths.sort()
    return paths


def build_code_bundle_archive() -> bytes:
    stream = io.BytesIO()
    with zipfile.ZipFile(stream, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        manifest = {
            "version": CODE_BUNDLE_VERSION,
            "generated_at": utc_now(),
            "files": [str(path).replace(os.sep, "/") for path in iter_code_bundle_paths()],
        }
        archive.writestr("_manifest.json", json.dumps(manifest, indent=2) + "\n")
        for relative in iter_code_bundle_paths():
            archive.writestr(str(relative).replace(os.sep, "/"), (ROOT / relative).read_bytes())
    return stream.getvalue()


def build_update_manifest(
    primary_host: str = "",
    api_port: int = 8787,
    ollama_port: int = 11434,
) -> Dict[str, object]:
    code_bundle = build_code_bundle_archive()
    code_manifest: Dict[str, object] = {}
    with zipfile.ZipFile(io.BytesIO(code_bundle), "r") as archive:
        try:
            payload = json.loads(archive.read("_manifest.json").decode("utf-8"))
        except (KeyError, json.JSONDecodeError, UnicodeDecodeError):
            payload = {}
        if isinstance(payload, dict):
            code_manifest = payload

    bootstrap = bootstrap_bundle_payload(
        primary_host=primary_host,
        api_port=api_port,
        ollama_port=ollama_port,
    )
    bootstrap_stable = dict(bootstrap)
    bootstrap_stable.pop("generated_at", None)
    return {
        "version": UPDATE_MANIFEST_VERSION,
        "generated_at": utc_now(),
        "primary_host": normalize_text_value(primary_host, fallback="", limit=200),
        "primary_eve_url": str(bootstrap.get("primary_eve_url") or ""),
        "primary_ollama_url": str(bootstrap.get("primary_ollama_url") or ""),
        "code_bundle": {
            "sha256": hashlib.sha256(code_bundle).hexdigest(),
            "bytes": len(code_bundle),
            "version": code_manifest.get("version") or CODE_BUNDLE_VERSION,
            "generated_at": code_manifest.get("generated_at") or "",
            "file_count": len(code_manifest.get("files") or []) if isinstance(code_manifest.get("files"), list) else 0,
        },
        "bootstrap": {
            "sha256": sha256_text(json.dumps(bootstrap_stable, ensure_ascii=True, sort_keys=True)),
            "models": list(bootstrap.get("models") or []),
        },
    }


def apply_code_bundle_archive(archive_bytes: bytes) -> Dict[str, object]:
    ensure_store()
    backup_root = APP_DIR / "code_update_backups" / utc_timestamp_for_filename()
    updated_files: List[str] = []
    backed_up_files: List[str] = []
    added_files: List[str] = []

    with zipfile.ZipFile(io.BytesIO(archive_bytes), "r") as archive:
        names = archive.namelist()
        if "_manifest.json" not in names:
            raise SystemExit("Code bundle is missing _manifest.json.")
        for name in names:
            if name.endswith("/"):
                continue
            if name == "_manifest.json":
                continue
            relative = Path(name)
            if relative.is_absolute() or ".." in relative.parts:
                raise SystemExit(f"Unsafe code bundle path: {name}")
            if not code_bundle_should_include(relative):
                continue
            destination = ROOT / relative
            content = archive.read(name)
            existed = destination.exists()
            previous = destination.read_bytes() if existed else None
            if previous == content:
                continue
            if existed:
                backup_path = backup_root / relative
                backup_path.parent.mkdir(parents=True, exist_ok=True)
                backup_path.write_bytes(previous or b"")
                backed_up_files.append(str(relative).replace(os.sep, "/"))
            temp_path = destination.with_name(f".{destination.name}.tmp.{os.getpid()}")
            destination.parent.mkdir(parents=True, exist_ok=True)
            temp_path.write_bytes(content)
            temp_path.replace(destination)
            updated_files.append(str(relative).replace(os.sep, "/"))
            if not existed:
                added_files.append(str(relative).replace(os.sep, "/"))

    append_entry(
        "code_bundle_applied",
        f"Applied code bundle with {len(updated_files)} updated file(s).",
        metadata={
            "updated_files": updated_files[:20],
            "backed_up_files": backed_up_files[:20],
            "backup_root": str(backup_root) if backed_up_files else "",
        },
    )
    return {
        "updated_files": updated_files,
        "backed_up_files": backed_up_files,
        "added_files": added_files,
        "backup_root": str(backup_root) if backed_up_files else "",
    }


def component_upstreams_dir(config: Dict[str, object]) -> Path:
    raw = str(config.get("component_update_upstreams_dir") or COMPONENT_UPSTREAMS_DIR)
    return Path(raw).expanduser().resolve()


def component_slug(value: object) -> str:
    slug = re.sub(r"[^a-z0-9._-]+", "-", str(value or "").strip().lower()).strip("-")
    return slug or "component"


