def load_capability_intelligence(prefer_runtime: bool = False) -> Dict[str, object]:
    path = resolve_store_read_path(
        CAPABILITY_INTELLIGENCE_PATH,
        prefer_runtime=prefer_runtime,
    )
    payload = eve_store.load_json_dict(path, default={})
    if not isinstance(payload, dict):
        return {}
    payload["subsystems"] = payload.get("subsystems") if isinstance(payload.get("subsystems"), dict) else {}
    payload["release_feeds"] = payload.get("release_feeds") if isinstance(payload.get("release_feeds"), list) else []
    payload["opportunities"] = payload.get("opportunities") if isinstance(payload.get("opportunities"), list) else []
    payload["feature_reviews"] = payload.get("feature_reviews") if isinstance(payload.get("feature_reviews"), list) else []
    payload["feature_review_summary"] = payload.get("feature_review_summary") if isinstance(payload.get("feature_review_summary"), dict) else {}
    payload["configuration_reviews"] = payload.get("configuration_reviews") if isinstance(payload.get("configuration_reviews"), list) else []
    payload["feature_family_reviews"] = payload.get("feature_family_reviews") if isinstance(payload.get("feature_family_reviews"), list) else []
    payload["feature_family_review_summary"] = payload.get("feature_family_review_summary") if isinstance(payload.get("feature_family_review_summary"), dict) else {}
    payload["effective_configuration_attestations"] = payload.get("effective_configuration_attestations") if isinstance(payload.get("effective_configuration_attestations"), list) else []
    payload["effective_configuration_summary"] = payload.get("effective_configuration_summary") if isinstance(payload.get("effective_configuration_summary"), dict) else {}
    payload["changes"] = payload.get("changes") if isinstance(payload.get("changes"), dict) else {}
    return payload


