def build_hermes_feature_policy(
    *,
    status: Optional[Dict[str, object]] = None,
    inventory: Optional[Dict[str, object]] = None,
    save: bool = True,
) -> Dict[str, object]:
    ensure_store()
    status = status or detect_hermes_learning_organ(timeout=10)
    inventory = inventory or latest_hermes_capability_inventory(prefer_runtime=False)
    family_statuses = {
        "model_route": hermes_inventory_family_status(inventory, "model_route"),
        "skills": hermes_inventory_family_status(inventory, "skills"),
        "plugins": hermes_inventory_family_status(inventory, "plugins"),
        "mcp": hermes_inventory_family_status(inventory, "mcp"),
        "gateway_messaging": hermes_inventory_family_status(inventory, "gateway_messaging"),
        "cron_hooks": hermes_inventory_family_status(inventory, "cron_hooks"),
        "browser_voice_media_code_rl": hermes_inventory_family_status(inventory, "browser_voice_media_code_rl"),
        "memory_and_session_search": hermes_inventory_family_status(inventory, "memory_and_session_search"),
        "model_orchestration": hermes_inventory_family_status(inventory, "model_orchestration"),
        "skill_curator": hermes_inventory_family_status(inventory, "skill_curator"),
        "insights_and_journey": hermes_inventory_family_status(inventory, "insights_and_journey"),
        "checkpoints_and_backup": hermes_inventory_family_status(inventory, "checkpoints_and_backup"),
        "acp_editor_bridge": hermes_inventory_family_status(inventory, "acp_editor_bridge"),
        "projects_kanban_worktrees": hermes_inventory_family_status(inventory, "projects_kanban_worktrees"),
        "computer_use": hermes_inventory_family_status(inventory, "computer_use"),
        "config_and_prompt_hygiene": hermes_inventory_family_status(inventory, "config_and_prompt_hygiene"),
        "supply_chain_security": hermes_inventory_family_status(inventory, "supply_chain_security"),
        "source_update": hermes_inventory_family_status(inventory, "source_update"),
    }
    security_summary = (
        inventory.get("security_summary")
        if isinstance(inventory.get("security_summary"), dict)
        else {}
    )
    config_text = ""
    config_path = HERMES_EVE_PROFILE_HOME / "config.yaml"
    if config_path.exists():
        try:
            config_text = config_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            config_text = ""
    current_state_by_feature = {
        "identity_profile_soul": "guardrail_ok" if status.get("soul_guardrail_ok") else "guardrail_missing",
        "memory_user_notes": family_statuses["memory_and_session_search"],
        "insights_analytics": "read_only_available",
        "snapshot_rollback_branch": "checkpoints_enabled" if "enabled: true" in config_text else "unknown",
        "approval_bypass_modes": "not_admitted",
        "model_provider_switching": family_statuses["model_route"],
        "auxiliary_models_compression": "not_admitted",
        "skills_slash_commands": family_statuses["skills"],
        "tools_plugins_mcp_browser_code": ",".join(
            [
                f"plugins={family_statuses['plugins']}",
                f"mcp={family_statuses['mcp']}",
                f"tools={family_statuses['browser_voice_media_code_rl']}",
            ]
        ),
        "gateway_messaging": family_statuses["gateway_messaging"],
        "cron_webhooks": family_statuses["cron_hooks"],
        "config_prompt_hygiene": family_statuses["config_and_prompt_hygiene"],
        "supply_chain_security": family_statuses["supply_chain_security"],
        "skill_curator_lifecycle": family_statuses["skill_curator"],
        "moa_fallback_orchestration": family_statuses["model_orchestration"],
        "projects_kanban_worktrees": family_statuses["projects_kanban_worktrees"],
        "acp_editor_bridge": family_statuses["acp_editor_bridge"],
        "shell_hooks": family_statuses["cron_hooks"],
        "computer_use_driver": family_statuses["computer_use"],
        "profile_checkpoints_backup": family_statuses["checkpoints_and_backup"],
        "dashboard_desktop_api": "available_keep_stopped",
        "secrets_auth_connectors": "optional_credentials_unset",
        "voice_mode": "not_admitted",
    }
    features: List[Dict[str, object]] = []
    for definition in HERMES_FEATURE_POLICY_DEFINITIONS:
        item = dict(definition)
        feature_id = str(item.get("id") or "")
        item["current_state"] = current_state_by_feature.get(feature_id, "unknown")
        item["direct_eve_authority"] = False
        item["writes_eve_state"] = False
        item["adds_chat_lane"] = False
        features.append(item)

    watch_items: List[str] = []
    if not status.get("soul_guardrail_ok"):
        watch_items.append("Hermes SOUL guardrail is missing or too weak.")
    model_base_url = str(status.get("model_base_url") or "")
    if model_base_url and not model_base_url.startswith("http://127.0.0.1"):
        watch_items.append("Hermes profile points at a non-local provider route; explicit approval is required.")
    if family_statuses["gateway_messaging"] == "running":
        watch_items.append("Hermes gateway is running; OpenClaw should remain Eve's primary body unless a specific exception is approved.")
    if family_statuses["cron_hooks"] == "configured":
        watch_items.append("Hermes cron jobs are configured; schedules need Eve ledger/risk-gate ownership.")
    if family_statuses["mcp"] == "configured":
        watch_items.append("Hermes MCP servers are configured; require MCP admission before Eve use.")
    if family_statuses["plugins"] == "enabled":
        watch_items.append("Hermes plugins appear enabled; require capability admission before Eve use.")
    security_match = re.fullmatch(r"findings_(\d+)", family_statuses["supply_chain_security"])
    if security_match and int(security_match.group(1)) > 0:
        blocking_findings = int(security_summary.get("blocking_severity_count") or 0)
        severity_counts = (
            security_summary.get("severity_counts")
            if isinstance(security_summary.get("severity_counts"), dict)
            else {}
        )
        severity_detail = ", ".join(
            f"{str(key).lower()}={value}"
            for key, value in sorted(severity_counts.items())
            if int(value or 0) > 0
        )
        watch_items.append(
            f"Hermes supply-chain audit reports {security_match.group(1)} known vulnerability findings"
            f" ({severity_detail or 'severity unavailable'}; blocking={blocking_findings}); "
            + (
                "stage dependency fixes through a canary."
                if blocking_findings
                else "monitor the remaining non-blocking advisory until Hermes' declared dependency bounds admit its fixed version."
            )
        )
    update_match = re.fullmatch(r"update_available_(\d+)_commits", family_statuses["source_update"])
    if update_match and int(update_match.group(1)) > 0:
        watch_items.append(
            f"Hermes is {update_match.group(1)} upstream commits behind; preserve and rebase the local one-shot toolset repair in a canary."
        )
    if family_statuses["config_and_prompt_hygiene"] == "migration_available":
        watch_items.append("Hermes config schema migration is available; back up and migrate the Eve learning profile.")
    if family_statuses["model_orchestration"] == "active_requires_eval":
        watch_items.append("Hermes MoA or fallback routing is active; it requires Eve route/provenance evaluation.")
    if family_statuses["projects_kanban_worktrees"] == "configured":
        watch_items.append("Hermes project/Kanban state is configured; do not let it become a second Eve task authority.")
    if family_statuses["computer_use"] == "installed_not_admitted":
        watch_items.append("Hermes computer-use is installed but not admitted; OpenClaw remains Eve's embodied action layer.")

    policy = {
        "schema_version": "eve_hermes_feature_policy.v2",
        "generated_at": utc_now(),
        "artifact_path": str(HERMES_FEATURE_POLICY_PATH),
        "status": "watch" if watch_items else "clear",
        "profile": HERMES_EVE_PROFILE_NAME,
        "profile_home": str(HERMES_EVE_PROFILE_HOME),
        "principle": "Hermes can learn and propose; Eve owns identity, memory, permissions, channels, and final state.",
        "default_decision": "inventory_or_proposal_only",
        "summary": {
            "feature_count": len(features),
            "allowed_now_count": sum(1 for item in features if item.get("allowed_now")),
            "blocked_or_lab_only_count": sum(1 for item in features if not item.get("allowed_now")),
            "direct_eve_authority_count": sum(1 for item in features if item.get("direct_eve_authority")),
            "watch_item_count": len(watch_items),
        },
        "hermes_status": {
            "status": status.get("status"),
            "soul_guardrail_ok": bool(status.get("soul_guardrail_ok")),
            "model_provider": status.get("model_provider") or "",
            "model_default": status.get("model_default") or "",
            "model_base_url": status.get("model_base_url") or "",
            "model_context_length": status.get("model_context_length") or 0,
        },
        "family_statuses": family_statuses,
        "security_summary": security_summary,
        "watch_items": watch_items,
        "features": features,
        "next_commands": [
            "python3 eve.py hermes inventory --refresh --full",
            "python3 eve.py hermes feature-policy --full",
            "python3 eve.py hermes skill-admission --skill <name> --purpose <bounded-purpose> --test <smoke> --evidence <ref>",
            "python3 eve.py governance watchers --limit 20 --full",
        ],
    }
    if save:
        eve_store.write_json_dict(HERMES_FEATURE_POLICY_PATH, policy, sort_keys=True)
        mirror_store_file_to_runtime(HERMES_FEATURE_POLICY_PATH)
    return policy


def format_hermes_feature_policy(policy: Dict[str, object], *, full: bool = False) -> str:
    summary = policy.get("summary") if isinstance(policy.get("summary"), dict) else {}
    lines = [
        "Hermes feature policy",
        f"status: {policy.get('status') or 'unknown'}",
        f"generated_at: {policy.get('generated_at') or ''}",
        f"artifact: {policy.get('artifact_path') or HERMES_FEATURE_POLICY_PATH}",
        f"principle: {policy.get('principle') or ''}",
        f"features: {summary.get('feature_count') or 0}",
        f"allowed_now: {summary.get('allowed_now_count') or 0}",
        f"blocked_or_lab_only: {summary.get('blocked_or_lab_only_count') or 0}",
        f"direct_eve_authority: {summary.get('direct_eve_authority_count') or 0}",
    ]
    watch_items = policy.get("watch_items") if isinstance(policy.get("watch_items"), list) else []
    if watch_items:
        lines.append("watch_items:")
        lines.extend(f"- {item}" for item in watch_items)
    features = policy.get("features") if isinstance(policy.get("features"), list) else []
    for feature in features if full else features[:8]:
        if not isinstance(feature, dict):
            continue
        lines.append(
            f"- {feature.get('id')}: {feature.get('posture')} | state={feature.get('current_state')} "
            f"| allowed_now={'yes' if feature.get('allowed_now') else 'no'} | authority=no"
        )
        if full:
            lines.append(f"  gate: {feature.get('required_gate') or ''}")
            lines.append(f"  next: {feature.get('recommendation') or ''}")
    if not full and len(features) > 8:
        lines.append(f"... {len(features) - 8} more features; rerun with --full.")
    return "\n".join(lines)


HERMES_SKILL_PERMISSION_RISK = {
    "read_only": 1,
    "operator_safe": 2,
    "system_touching": 3,
    "external_send": 4,
    "credentialed": 4,
}


def evaluate_hermes_skill_admission_request(
    *,
    skill_name: str,
    purpose: str,
    tests: List[str],
    evidence: List[str],
    permission_class: str = "read_only",
    source: str = "hermes",
    skill_path: str = "",
    filesystem_boundary: str = "",
    network_boundary: str = "",
    credential_boundary: str = "",
) -> Dict[str, object]:
    normalized_skill = normalize_text_value(skill_name, fallback="", limit=160)
    normalized_purpose = normalize_text_value(purpose, fallback="", limit=500)
    normalized_permission = permission_class if permission_class in HERMES_SKILL_PERMISSION_RISK else "system_touching"
    normalized_tests = unique_compact([str(item) for item in tests if str(item).strip()], limit=12)
    normalized_evidence = unique_compact([str(item) for item in evidence if str(item).strip()], limit=12)
    risk = HERMES_SKILL_PERMISSION_RISK.get(normalized_permission, 3)
    blockers: List[str] = []
    warnings: List[str] = []
    if not normalized_skill:
        blockers.append("skill_name_required")
    if not normalized_purpose:
        blockers.append("purpose_required")
    if not normalized_tests:
        blockers.append("tests_required")
    if not normalized_evidence:
        blockers.append("evidence_required")
    if normalized_permission in {"external_send", "credentialed"} and not credential_boundary:
        warnings.append("credential_or_external_boundary_should_be_explicit")
    payload = {
        "skill_name": normalized_skill,
        "operation": "admit_candidate",
        "purpose": normalized_purpose,
        "permission_class": normalized_permission,
        "skill_path": normalize_text_value(skill_path, fallback="", limit=500),
        "tests": normalized_tests,
        "filesystem_boundary": normalize_text_value(filesystem_boundary, fallback="not specified", limit=500),
        "network_boundary": normalize_text_value(network_boundary, fallback="not specified", limit=500),
        "credential_boundary": normalize_text_value(credential_boundary, fallback="no credentials approved", limit=500),
        "enabled_for_eve": False,
        "adds_chat_lane": False,
        "admission_required": True,
        "notes": "This is an admission proposal only; it does not install, enable, or grant the skill.",
    }
    proposal = eve_governance.proposal_envelope(
        "SkillPatchProposal",
        source=source,
        payload=payload,
        evidence=normalized_evidence,
        risk_level=risk,
        requires_approval=True,
    )
    reviewed = eve_governance.reviewed_proposal(proposal)
    if blockers:
        status = "blocked_missing_admission_requirements"
    elif risk >= 3:
        status = "needs_approval_and_canary"
    else:
        status = "ready_for_governance_queue"
    return {
        "schema_version": "eve_hermes_skill_admission.v1",
        "generated_at": utc_now(),
        "status": status,
        "blockers": blockers,
        "warnings": warnings,
        "enabled_for_eve": False,
        "adds_chat_lane": False,
        "candidate": payload,
        "proposal": reviewed,
        "next_step": (
            "Add missing purpose, evidence, and tests before queueing."
            if blockers
            else "Queue with --enqueue, then require approval/canary before any enablement."
            if risk >= 3
            else "Queue with --enqueue for governance review; do not enable the skill directly."
        ),
    }


def format_hermes_skill_admission(report: Dict[str, object], *, full: bool = False) -> str:
    candidate = report.get("candidate") if isinstance(report.get("candidate"), dict) else {}
    proposal = report.get("proposal") if isinstance(report.get("proposal"), dict) else {}
    review = proposal.get("review") if isinstance(proposal.get("review"), dict) else {}
    lines = [
        "Hermes skill admission",
        f"status: {report.get('status') or 'unknown'}",
        f"skill: {candidate.get('skill_name') or ''}",
        f"permission_class: {candidate.get('permission_class') or ''}",
        f"enabled_for_eve: {'yes' if report.get('enabled_for_eve') else 'no'}",
        f"adds_chat_lane: {'yes' if report.get('adds_chat_lane') else 'no'}",
        f"proposal_id: {proposal.get('id') or ''}",
        f"review_decision: {review.get('decision') or proposal.get('review_status') or ''}",
        f"next_step: {report.get('next_step') or ''}",
    ]
    blockers = report.get("blockers") if isinstance(report.get("blockers"), list) else []
    warnings = report.get("warnings") if isinstance(report.get("warnings"), list) else []
    if blockers:
        lines.append("blockers: " + ", ".join(str(item) for item in blockers))
    if warnings:
        lines.append("warnings: " + ", ".join(str(item) for item in warnings))
    if full:
        findings = review.get("findings") if isinstance(review.get("findings"), list) else []
        for finding in findings:
            if isinstance(finding, dict):
                lines.append(f"- finding: {finding.get('code')} | {finding.get('message')}")
        lines.append(f"payload: {json.dumps(candidate, ensure_ascii=True, sort_keys=True)}")
    return "\n".join(lines)


