def hermes_smoke_gate_reasons(status: Dict[str, object], *, allow_non_local: bool = False) -> List[str]:
    reasons: List[str] = []
    if not status.get("version_ok"):
        reasons.append("hermes_command_unavailable")
    if not status.get("profile_exists"):
        reasons.append("evelearning_profile_missing")
    if not status.get("config_exists"):
        reasons.append("evelearning_config_missing")
    if not status.get("soul_guardrail_ok"):
        reasons.append("evelearning_soul_guardrail_missing")
    model_context_length = int(status.get("model_context_length") or 0)
    hermes_minimum = int(status.get("hermes_minimum_context_length") or 64000)
    if model_context_length <= 0:
        reasons.append("model_context_length_unknown")
    elif model_context_length < hermes_minimum:
        reasons.append("model_context_below_hermes_minimum")
    if status.get("model_endpoint_checked") and not status.get("model_endpoint_reachable"):
        reasons.append("model_endpoint_unreachable")
    base_url = str(status.get("model_base_url") or "").strip()
    if base_url:
        hostname = urlparse(base_url).hostname
        if hostname not in {"127.0.0.1", "localhost", "::1"} and not allow_non_local:
            reasons.append("non_local_model_provider_requires_explicit_approval")
    if str(status.get("status") or "") == "missing":
        reasons.append("hermes_missing")
    return unique_compact(reasons, limit=12)


