def hermes_trace_text(value: object, *, fallback: str = "", limit: int = 420) -> str:
    return normalize_text_value(value, fallback=fallback, limit=limit)


def hermes_trace_ref(prefix: str, record: Dict[str, object], *, fallback: str = "") -> str:
    record_id = hermes_trace_text(record.get("id") or record.get("event_id") or record.get("created_at"), fallback=fallback, limit=160)
    return f"{prefix}:{record_id}" if record_id else prefix


def hermes_trace_event_from_action(record: Dict[str, object]) -> Dict[str, object]:
    action = hermes_trace_text(record.get("action") or record.get("action_name") or record.get("type"), fallback="action", limit=120)
    status = hermes_trace_text(record.get("tree_status") or record.get("status") or record.get("result_status"), fallback="unknown", limit=120)
    verification = action_result_explicit_verification(record) is True
    summary = hermes_trace_text(
        record.get("summary") or record.get("result_summary") or record.get("response") or record.get("reason"),
        fallback=f"{action} completed with status {status}.",
        limit=420,
    )
    return {
        "type": "ToolResultEvent",
        "summary": f"{action}: {summary}",
        "status": status,
        "verified": bool(verification),
        "evidence_ref": hermes_trace_ref("action_execution", record),
    }


def hermes_trace_event_from_experience(record: Dict[str, object]) -> Dict[str, object]:
    event_type = hermes_trace_text(record.get("event_type") or record.get("type"), fallback="experience", limit=120)
    summary = hermes_trace_text(record.get("summary") or record.get("learning") or record.get("result"), fallback=event_type, limit=420)
    event: Dict[str, object] = {
        "type": "ReflectionEvent" if event_type in {"reflection", "consolidation", "repair"} else "ObservationEvent",
        "summary": summary,
        "evidence_ref": hermes_trace_ref("experience_event", record),
    }
    learning = hermes_trace_text(record.get("learning"), fallback="", limit=300)
    if learning:
        event["learning"] = learning
    return event


def hermes_trace_event_from_evidence(record: Dict[str, object]) -> Dict[str, object]:
    kind = hermes_trace_text(record.get("kind"), fallback="evidence", limit=120)
    claim = hermes_trace_text(record.get("claim") or record.get("summary"), fallback=kind, limit=420)
    return {
        "type": "ObservationEvent",
        "summary": f"{kind}: {claim}",
        "confidence": record.get("confidence"),
        "evidence_ref": hermes_trace_ref("evidence", record),
    }


def hermes_trace_event_from_governance(record: Dict[str, object]) -> Dict[str, object]:
    event_type = hermes_trace_text(record.get("type"), fallback="governance_event", limit=120)
    review_status = hermes_trace_text(record.get("review_status"), fallback="", limit=80)
    payload = record.get("payload") if isinstance(record.get("payload"), dict) else {}
    summary = hermes_trace_text(
        payload.get("summary") or payload.get("claim") or payload.get("reason") or event_type,
        fallback=event_type,
        limit=420,
    )
    return {
        "type": event_type if event_type.endswith("Event") else "ObservationEvent",
        "summary": summary,
        "review_status": review_status,
        "evidence_ref": hermes_trace_ref("governance_event", record),
    }


def build_hermes_post_task_trace(
    *,
    task_id: str = "",
    limit: int = 6,
    prefer_runtime: bool = False,
) -> Dict[str, object]:
    bounded_limit = max(1, min(20, int(limit or 6)))
    actions = read_action_executions(limit=bounded_limit, prefer_runtime=prefer_runtime)
    experiences = read_experience_events(limit=bounded_limit, prefer_runtime=prefer_runtime)
    evidence = read_evidence_ledger(limit=bounded_limit, active_only=True, prefer_runtime=prefer_runtime)
    governance_events = read_governance_events(limit=min(6, bounded_limit), prefer_runtime=prefer_runtime)
    governance_queue = read_governance_proposals(limit=min(6, bounded_limit), prefer_runtime=prefer_runtime)

    trace: List[Dict[str, object]] = []
    trace.extend(hermes_trace_event_from_action(record) for record in actions[:bounded_limit])
    trace.extend(hermes_trace_event_from_experience(record) for record in experiences[:bounded_limit])
    trace.extend(hermes_trace_event_from_evidence(record) for record in evidence[:bounded_limit])
    trace.extend(hermes_trace_event_from_governance(record) for record in governance_events[: min(4, bounded_limit)])
    if not trace:
        trace = default_hermes_smoke_trace()["trace"]  # type: ignore[assignment]

    pending_governance = []
    for proposal in governance_queue[: min(4, bounded_limit)]:
        review = proposal.get("review") if isinstance(proposal.get("review"), dict) else {}
        pending_governance.append(
            {
                "id": proposal.get("id"),
                "type": proposal.get("type"),
                "source": proposal.get("source"),
                "decision": review.get("decision") or proposal.get("review_status"),
                "approval": governance_proposal_approval_status(proposal),
                "canary": governance_proposal_canary_status(proposal),
                "application": governance_proposal_application_status(proposal),
            }
        )

    return {
        "schema_version": "eve_hermes_trace.v1",
        "task_id": hermes_trace_text(task_id, fallback=f"post-task-{utc_timestamp_for_filename()}", limit=160),
        "source": "eve.hermes.post_task_trace",
        "purpose": "Let Hermes propose learning from recent Eve task/action/evidence traces without applying state.",
        "boundary": (
            "Hermes may propose memory, user-model, skill, failure-pattern, or eval records only. "
            "Eve governance decides approval, canary, apply, rollback, or rejection."
        ),
        "trace": trace[: max(2, bounded_limit * 3)],
        "current_relevant_memories": [
            {
                "id": item.get("id"),
                "kind": item.get("kind"),
                "claim": hermes_trace_text(item.get("claim") or item.get("summary"), fallback="", limit=320),
                "confidence": item.get("confidence"),
            }
            for item in evidence[: min(4, bounded_limit)]
        ],
        "current_relevant_skills": [
            "Use strict proposal JSON only.",
            "Do not write Eve memory directly.",
            "Require evidence references for each proposal.",
            "Keep capability, identity, code, and external communication out of Hermes learning proposals.",
        ],
        "pending_governance": pending_governance,
        "requested_output": {
            "memory_patches": "Only low-risk, evidence-backed project/user learning that should be reviewed before durable memory.",
            "user_model_patches": "Only supported user-preference learning; avoid overgeneralization.",
            "skill_patches": "Only if a repeated workflow is clear and tests/smoke checks are included.",
            "failure_patterns": "Readiness blockers, repeated tool failures, or governance gaps supported by the trace.",
            "suggested_evals": "Small future checks that would prove or disprove the proposed learning.",
        },
    }


def parse_hermes_trace_payload(*, trace_json: str = "", trace_file: str = "") -> Dict[str, object]:
    raw = str(trace_json or "").strip()
    if not raw and trace_file:
        raw = Path(trace_file).expanduser().read_text(encoding="utf-8")
    if not raw:
        return default_hermes_smoke_trace()
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid Hermes trace JSON: {exc}") from exc
    if not isinstance(payload, dict):
        raise ValueError("Hermes trace must be a JSON object.")
    return payload


def build_hermes_smoke_prompt(trace_payload: Dict[str, object]) -> str:
    trace_json = json.dumps(trace_payload, ensure_ascii=True, sort_keys=True, indent=2)
    return textwrap.dedent(
        f"""
        You are Hermes running as Eve's proposal-only learning organ.

        Return only valid JSON accepted by:
        python3 eve.py governance ingest-hermes --file <json>

        Allowed top-level keys:
        - memory_patches
        - skill_patches
        - user_model_patches
        - failure_patterns
        - suggested_evals

        Rules:
        - Propose learning only; do not claim anything has been applied.
        - Do not propose capability grants, identity changes, code edits, tool calls, or external sends.
        - Every proposal must include evidence from the trace.
        - Evidence fields must be arrays of strings, never a single string.
        - Prefer one or two concise proposals over broad speculation.
        - Output a single JSON object, with no markdown fences and no prose outside JSON.
        - The first character of your response must be {{ and the final character must be }}.
        - If you output ```json or any markdown fence, the smoke fails.

        Minimal valid shape:
        {{
          "memory_patches": [
            {{
              "claim": "Supported project-architecture learning.",
              "evidence": ["trace:docs/operating/HERMES_LEARNING_ORGAN_INTEGRATION_2026_04_29.md"],
              "confidence": 0.8,
              "sensitivity": "low",
              "scope": "project_architecture",
              "needs_user_confirmation": false
            }}
          ],
          "failure_patterns": [
            {{
              "summary": "Specific readiness blocker or repeated failure pattern.",
              "evidence": ["trace:python3 eve.py hermes status --full"],
              "confidence": 0.7,
              "risk_level": 1
            }}
          ],
          "suggested_evals": [
            {{
              "title": "Narrow future eval title.",
              "evidence": ["trace:python3 eve.py hermes smoke --full"],
              "confidence": 0.7,
              "risk_level": 1
            }}
          ]
        }}

        Trace:
        {trace_json}
        """
    ).strip()


def extract_repairable_json_object(text: str) -> str:
    stripped = str(text or "").strip()
    fence_match = re.match(r"^```(?:json)?\s*(.*?)\s*```$", stripped, flags=re.IGNORECASE | re.DOTALL)
    if fence_match:
        stripped = fence_match.group(1).strip()
    start = stripped.find("{")
    end = stripped.rfind("}")
    if start < 0 or end <= start:
        return ""
    return stripped[start : end + 1].strip()

def run_hermes_constrained_json_chat(
    *,
    prompt: str,
    profile_home: str,
    timeout: int,
) -> subprocess.CompletedProcess[str]:
    script = r"""
import json
import os
import sys

source_dir = os.environ.get("EVE_HERMES_SOURCE_DIR", "")
if source_dir:
    sys.path.insert(0, source_dir)

from hermes_cli.config import load_config
from hermes_cli.runtime_provider import resolve_runtime_provider
from run_agent import AIAgent

prompt = sys.stdin.read()
cfg = load_config()
model_cfg = cfg.get("model") or {}
if isinstance(model_cfg, str):
    model = model_cfg
    provider = ""
    max_tokens = 1200
else:
    model = model_cfg.get("default") or model_cfg.get("model") or ""
    provider = model_cfg.get("provider") or ""
    try:
        max_tokens = int(model_cfg.get("max_tokens") or 1200)
    except (TypeError, ValueError):
        max_tokens = 1200

runtime = resolve_runtime_provider(requested=provider, target_model=model)
response_schema = json.loads(os.environ["EVE_HERMES_RESPONSE_SCHEMA"])
agent = AIAgent(
    api_key=runtime.get("api_key"),
    base_url=runtime.get("base_url"),
    provider=runtime.get("provider"),
    api_mode=runtime.get("api_mode"),
    model=model,
    enabled_toolsets=[],
    quiet_mode=True,
    platform="cli",
    credential_pool=runtime.get("credential_pool"),
    max_tokens=max_tokens,
    request_overrides={
        "response_format": {
            "type": "json_schema",
            "json_schema": {
                "name": "eve_hermes_proposals",
                "strict": True,
                "schema": response_schema,
            },
        },
    },
)
agent.suppress_status_output = True
agent.stream_delta_callback = None
agent.tool_gen_callback = None
response = agent.chat(prompt) or ""
sys.stdout.write(response)
if response and not response.endswith("\n"):
    sys.stdout.write("\n")
"""
    env = os.environ.copy()
    env["HERMES_HOME"] = str(profile_home)
    env["EVE_HERMES_SOURCE_DIR"] = str(HERMES_SOURCE_DIR)
    env["EVE_HERMES_RESPONSE_SCHEMA"] = json.dumps(HERMES_PROPOSAL_RESPONSE_SCHEMA, ensure_ascii=True)
    return subprocess.run(
        [hermes_python_path(), "-c", script],
        cwd=str(ROOT),
        env=env,
        input=prompt,
        text=True,
        capture_output=True,
        timeout=max(1, int(timeout or 120)),
    )


def run_hermes_smoke(
    *,
    trace_payload: Dict[str, object],
    timeout: int = 120,
    ingest: bool = False,
    allow_non_local: bool = False,
    repair_json: bool = False,
    allow_repaired_ingest: bool = False,
    constrained_json: bool = False,
    local_64k_lab: bool = False,
    keep_local_lab: bool = False,
) -> Dict[str, object]:
    ensure_store()
    run_id = f"hermes-smoke-{utc_timestamp_for_filename()}"
    local_lab_started_by_smoke = False
    local_lab_start: Dict[str, object] = {}
    local_lab_stop: Dict[str, object] = {}
    profile_home_override: Optional[Path] = None
    if local_64k_lab:
        local_lab_start = start_hermes_local_lab(timeout=90)
        local_lab_started_by_smoke = bool(local_lab_start.get("started"))
        if local_lab_start.get("ok"):
            try:
                profile_home_override = prepare_hermes_temp_profile(run_id, hermes_local_lab_model_config())
            except (OSError, FileNotFoundError) as exc:
                local_lab_start = {
                    **local_lab_start,
                    "ok": False,
                    "reason": normalize_text_value(exc, fallback="temp_profile_failed", limit=300),
                }
    status = detect_hermes_learning_organ(timeout=10, profile_home=profile_home_override)
    prompt = build_hermes_smoke_prompt(trace_payload)
    record: Dict[str, object] = {
        "schema_version": "eve_hermes_smoke_run.v1",
        "id": run_id,
        "created_at": utc_now(),
        "status": "created",
        "hermes_status": status,
        "trace": trace_payload,
        "prompt_sha256": sha256_text(prompt),
        "ingest_requested": bool(ingest),
        "allow_repaired_ingest": bool(allow_repaired_ingest),
        "constrained_json": bool(constrained_json),
        "stored_governance_proposals": False,
        "direct_state_write_allowed": False,
        "adds_chat_lane": False,
        "strict_json_ok": False,
        "json_repair_used": False,
        "local_64k_lab_requested": bool(local_64k_lab),
        "local_64k_lab_start": local_lab_start,
        "temp_profile_home": str(profile_home_override or ""),
    }

    def finish(payload: Dict[str, object]) -> Dict[str, object]:
        nonlocal local_lab_stop
        if local_lab_started_by_smoke and not keep_local_lab:
            local_lab_stop = stop_hermes_local_lab()
            payload["local_64k_lab_stop"] = local_lab_stop
        elif local_64k_lab:
            payload["local_64k_lab_stop"] = {
                "stopped": False,
                "reason": "kept_running" if keep_local_lab else "not_started_by_smoke",
            }
        return write_hermes_run_record(payload)

    if local_64k_lab and not local_lab_start.get("ok"):
        record.update(
            {
                "status": "blocked_preflight",
                "reasons": [str(local_lab_start.get("reason") or "local_64k_lab_unavailable")],
                "summary": "Hermes smoke was not run because the local 64K lab endpoint did not become ready.",
            }
        )
        return finish(record)

    gate_reasons = hermes_smoke_gate_reasons(status, allow_non_local=allow_non_local)
    if gate_reasons:
        record.update(
            {
                "status": "blocked_preflight",
                "reasons": gate_reasons,
                "summary": (
                    "Hermes smoke was not run because the configured profile/model endpoint is not "
                    "ready for governed proposal generation."
                ),
            }
        )
        return finish(record)

    command = str(status.get("command") or hermes_command_path())
    launch_command = hermes_command_args("chat", "-Q", "--max-turns", "1", "-q", prompt)
    profile_home = str(status.get("profile_home") or HERMES_EVE_PROFILE_HOME)
    env = os.environ.copy()
    env["HERMES_HOME"] = profile_home
    started = time.time()
    try:
        if constrained_json:
            process = run_hermes_constrained_json_chat(
                prompt=prompt,
                profile_home=profile_home,
                timeout=max(1, int(timeout or 120)),
            )
        else:
            process = subprocess.run(
                launch_command,
                cwd=str(ROOT),
                env=env,
                text=True,
                capture_output=True,
                timeout=max(1, int(timeout or 120)),
            )
    except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
        record.update(
            {
                "status": "failed_command",
                "returncode": 124 if isinstance(exc, subprocess.TimeoutExpired) else 127,
                "duration_seconds": round(time.time() - started, 3),
                "reasons": [normalize_text_value(exc, fallback="Hermes command failed.", limit=500)],
            }
        )
        return finish(record)

    stdout = (process.stdout or "").strip()
    stderr = (process.stderr or "").strip()
    record.update(
        {
            "returncode": process.returncode,
            "duration_seconds": round(time.time() - started, 3),
            "stdout": stdout[:20000],
            "stderr": stderr[:8000],
            "stdout_preview": normalize_text_value(stdout, fallback="", limit=1200),
            "stderr_preview": normalize_text_value(stderr, fallback="", limit=1200),
        }
    )
    if process.returncode != 0:
        record.update({"status": "failed_command", "reasons": [f"hermes_returncode_{process.returncode}"]})
        return finish(record)

    try:
        output_payload = json.loads(stdout)
    except json.JSONDecodeError as exc:
        repair_candidate = extract_repairable_json_object(stdout)
        if repair_json and repair_candidate:
            try:
                output_payload = json.loads(repair_candidate)
            except json.JSONDecodeError as repair_exc:
                record.update(
                    {
                        "status": "failed_invalid_json",
                        "reasons": [f"invalid_json:{exc}", f"json_repair_failed:{repair_exc}"],
                        "repair_candidate": repair_candidate[:20000],
                    }
                )
                return finish(record)
            record.update(
                {
                    "json_repair_used": True,
                    "json_repair_reason": "stripped_outer_markdown_fence_or_surrounding_text",
                    "repair_candidate": repair_candidate[:20000],
                }
            )
        else:
            record.update(
                {
                    "status": "failed_invalid_json",
                    "reasons": [f"invalid_json:{exc}"],
                    "repair_candidate": repair_candidate[:20000] if repair_candidate else "",
                    "repair_available": bool(repair_candidate),
                }
            )
            return finish(record)
    else:
        record["strict_json_ok"] = True
    if not isinstance(output_payload, dict):
        record.update({"status": "failed_invalid_json", "reasons": ["hermes_output_not_json_object"]})
        return finish(record)

    try:
        proposals = eve_governance.proposal_envelopes_from_adapter_payload(output_payload, default_source="hermes")
        reviewed = [eve_governance.reviewed_proposal(proposal) for proposal in proposals]
    except ValueError as exc:
        record.update(
            {
                "status": "failed_invalid_proposals",
                "output": output_payload,
                "reasons": [str(exc)],
            }
        )
        return finish(record)

    if ingest and record.get("json_repair_used") and not allow_repaired_ingest:
        watcher_report = eve_governance.watcher_report(reviewed)
        record.update(
            {
                "status": "blocked_repaired_ingest",
                "output": output_payload,
                "proposal_count": len(reviewed),
                "proposals": reviewed,
                "watchers": watcher_report,
                "stored_governance_proposals": False,
                "summary": (
                    "Hermes output required JSON repair, so --ingest was blocked. Re-run with "
                    "--allow-repaired-ingest only for an explicit supervised exception."
                ),
            }
        )
        return finish(record)

    saved = reviewed
    if ingest:
        saved = [append_governance_proposal(proposal) for proposal in reviewed]
        mirror_store_file_to_runtime(GOVERNANCE_PROPOSALS_PATH)
    watcher_report = eve_governance.watcher_report(saved)
    watcher_clean = str(watcher_report.get("status") or "") == "clean"
    if record.get("json_repair_used"):
        run_status = "passed_with_json_repair" if watcher_clean else "passed_with_json_repair_warnings"
    else:
        run_status = "passed" if watcher_clean else "passed_with_warnings"
    record.update(
        {
            "status": run_status,
            "output": output_payload,
            "proposal_count": len(saved),
            "proposals": saved,
            "watchers": watcher_report,
            "stored_governance_proposals": bool(ingest),
            "summary": (
                f"Hermes produced {len(saved)} governed proposal(s); "
                f"watchers={watcher_report.get('status')} warnings={watcher_report.get('total_warnings')}."
            ),
        }
    )
    return finish(record)


def format_hermes_smoke_result(record: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "Hermes smoke",
        f"status: {record.get('status') or 'unknown'}",
        f"id: {record.get('id') or ''}",
        f"artifact: {record.get('artifact_path') or ''}",
        f"stored_governance_proposals: {'yes' if record.get('stored_governance_proposals') else 'no'}",
        f"constrained_json: {'yes' if record.get('constrained_json') else 'no'}",
        f"strict_json_ok: {'yes' if record.get('strict_json_ok') else 'no'}",
        f"json_repair_used: {'yes' if record.get('json_repair_used') else 'no'}",
        f"summary: {record.get('summary') or ''}",
    ]
    reasons = [str(item) for item in (record.get("reasons") or []) if str(item)]
    if reasons:
        lines.append(f"reasons: {', '.join(reasons)}")
    if record.get("proposal_count") is not None:
        lines.append(f"proposal_count: {record.get('proposal_count')}")
    watchers = record.get("watchers") if isinstance(record.get("watchers"), dict) else {}
    if watchers:
        lines.append(
            f"watchers: {watchers.get('status')} warnings={watchers.get('total_warnings')} "
            f"blocking={watchers.get('blocking_warnings')}"
        )
    if full:
        hermes_status = record.get("hermes_status") if isinstance(record.get("hermes_status"), dict) else {}
        if hermes_status:
            lines.append(
                "model: "
                f"{hermes_status.get('model_provider') or 'unknown'}/"
                f"{hermes_status.get('model_default') or 'unknown'} "
                f"context={hermes_status.get('model_context_length') or 'unknown'} "
                f"min={hermes_status.get('hermes_minimum_context_length') or 'unknown'} "
                f"endpoint_reachable={'yes' if hermes_status.get('model_endpoint_reachable') else 'no'}"
            )
        if record.get("stdout_preview"):
            lines.append(f"stdout_preview: {record.get('stdout_preview')}")
        if record.get("stderr_preview"):
            lines.append(f"stderr_preview: {record.get('stderr_preview')}")
    return "\n".join(lines)


HERMES_SMOKE_PASS_STATUSES = {
    "passed",
    "passed_with_warnings",
    "passed_with_json_repair",
    "passed_with_json_repair_warnings",
}


def hermes_eval_summary(runs: List[Dict[str, object]]) -> Dict[str, object]:
    total = len(runs)
    status_counts: Dict[str, int] = {}
    strict_json_ok = 0
    json_repair_used = 0
    passed = 0
    watcher_warnings = 0
    watcher_blocking = 0
    proposal_count = 0
    artifacts: List[str] = []
    for run in runs:
        status = str(run.get("status") or "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        if status in HERMES_SMOKE_PASS_STATUSES:
            passed += 1
        if run.get("strict_json_ok"):
            strict_json_ok += 1
        if run.get("json_repair_used"):
            json_repair_used += 1
        try:
            proposal_count += int(run.get("proposal_count") or 0)
        except (TypeError, ValueError):
            pass
        watchers = run.get("watchers") if isinstance(run.get("watchers"), dict) else {}
        try:
            watcher_warnings += int(watchers.get("total_warnings") or 0)
            watcher_blocking += int(watchers.get("blocking_warnings") or 0)
        except (TypeError, ValueError):
            pass
        artifact = str(run.get("artifact_path") or "")
        if artifact:
            artifacts.append(artifact)

    strict_rate = (strict_json_ok / total) if total else 0.0
    pass_rate = (passed / total) if total else 0.0
    repair_rate = (json_repair_used / total) if total else 0.0
    if total and passed == total and strict_json_ok == total and watcher_blocking == 0:
        verdict = "strict_pass"
        recommendation = "Strict JSON is reliable enough for a guarded ingest dry-run."
    elif total and passed == total and watcher_blocking == 0:
        verdict = "repaired_pass"
        recommendation = "Hermes can be evaluated through repaired JSON, but do not use routine --ingest until strict JSON is reliable."
    else:
        verdict = "failed"
        recommendation = "Keep Hermes in lab mode; inspect failed run artifacts before any ingest path."
    return {
        "trials": total,
        "passed": passed,
        "failed": total - passed,
        "status_counts": dict(sorted(status_counts.items())),
        "strict_json_ok": strict_json_ok,
        "json_repair_used": json_repair_used,
        "strict_json_rate": round(strict_rate, 3),
        "pass_rate": round(pass_rate, 3),
        "repair_rate": round(repair_rate, 3),
        "watcher_warnings": watcher_warnings,
        "watcher_blocking": watcher_blocking,
        "proposal_count": proposal_count,
        "can_ingest_routinely": verdict == "strict_pass",
        "can_ingest_with_explicit_repair": verdict in {"strict_pass", "repaired_pass"},
        "verdict": verdict,
        "recommendation": recommendation,
        "artifacts": artifacts,
    }


def run_hermes_smoke_eval(
    *,
    trials: int = 3,
    timeout: int = 180,
    local_64k_lab: bool = True,
    repair_json: bool = True,
    constrained_json: bool = False,
) -> Dict[str, object]:
    ensure_store()
    eval_id = f"hermes-eval-{utc_timestamp_for_filename()}"
    started_lab = False
    lab_start: Dict[str, object] = {}
    lab_stop: Dict[str, object] = {}
    if local_64k_lab:
        lab_start = start_hermes_local_lab(timeout=90)
        started_lab = bool(lab_start.get("started"))
        if not lab_start.get("ok"):
            record = {
                "schema_version": "eve_hermes_smoke_eval.v1",
                "id": eval_id,
                "created_at": utc_now(),
                "status": "blocked_preflight",
                "trials_requested": max(1, int(trials or 3)),
                "local_64k_lab": bool(local_64k_lab),
                "repair_json": bool(repair_json),
                "lab_start": lab_start,
                "summary": {
                    "verdict": "failed",
                    "recommendation": "Local 64K lab endpoint did not start; inspect lab log before retrying.",
                    "trials": 0,
                },
            }
            return write_hermes_eval_record(record)

    runs: List[Dict[str, object]] = []
    try:
        for _ in range(max(1, min(12, int(trials or 3)))):
            runs.append(
                run_hermes_smoke(
                    trace_payload=default_hermes_smoke_trace(),
                    timeout=timeout,
                    ingest=False,
                    allow_non_local=False,
                    repair_json=repair_json,
                    constrained_json=constrained_json,
                    local_64k_lab=local_64k_lab,
                    keep_local_lab=True,
                )
            )
    finally:
        if started_lab:
            lab_stop = stop_hermes_local_lab()

    summary = hermes_eval_summary(runs)
    record = {
        "schema_version": "eve_hermes_smoke_eval.v1",
        "id": eval_id,
        "created_at": utc_now(),
        "status": summary.get("verdict"),
        "trials_requested": max(1, min(12, int(trials or 3))),
        "local_64k_lab": bool(local_64k_lab),
        "repair_json": bool(repair_json),
        "constrained_json": bool(constrained_json),
        "lab_start": lab_start,
        "lab_stop": lab_stop,
        "summary": summary,
        "runs": [
            {
                "id": run.get("id"),
                "status": run.get("status"),
                "artifact_path": run.get("artifact_path"),
                "strict_json_ok": bool(run.get("strict_json_ok")),
                "json_repair_used": bool(run.get("json_repair_used")),
                "proposal_count": run.get("proposal_count") or 0,
                "watchers": run.get("watchers") if isinstance(run.get("watchers"), dict) else {},
            }
            for run in runs
        ],
    }
    return write_hermes_eval_record(record)


def format_hermes_smoke_eval(record: Dict[str, object], *, full: bool = False) -> str:
    summary = record.get("summary") if isinstance(record.get("summary"), dict) else {}
    lines = [
        "Hermes smoke eval",
        f"status: {record.get('status') or 'unknown'}",
        f"id: {record.get('id') or ''}",
        f"artifact: {record.get('artifact_path') or ''}",
        f"constrained_json: {'yes' if record.get('constrained_json') else 'no'}",
        f"trials: {summary.get('trials') or 0}",
        f"pass_rate: {summary.get('pass_rate') or 0}",
        f"strict_json_rate: {summary.get('strict_json_rate') or 0}",
        f"repair_rate: {summary.get('repair_rate') or 0}",
        f"watcher_blocking: {summary.get('watcher_blocking') or 0}",
        f"recommendation: {summary.get('recommendation') or ''}",
    ]
    if full:
        lines.append(f"status_counts: {json.dumps(summary.get('status_counts') or {}, ensure_ascii=True, sort_keys=True)}")
        for run in record.get("runs", []):
            if not isinstance(run, dict):
                continue
            watchers = run.get("watchers") if isinstance(run.get("watchers"), dict) else {}
            lines.append(
                f"- {run.get('id')} | {run.get('status')} | strict_json={'yes' if run.get('strict_json_ok') else 'no'} "
                f"| repair={'yes' if run.get('json_repair_used') else 'no'} "
                f"| proposals={run.get('proposal_count') or 0} "
                f"| blocking={watchers.get('blocking_warnings') or 0}"
            )
            if run.get("artifact_path"):
                lines.append(f"  artifact: {run.get('artifact_path')}")
    return "\n".join(lines)


def local_file_component_info(path_value: object) -> Dict[str, object]:
    path = Path(str(path_value or "")).expanduser()
    if not path.is_absolute():
        path = ROOT / path
    if not path.exists():
        return {"ok": False, "path": str(path), "detail": "file not found"}
    try:
        stat = path.stat()
    except OSError as exc:
        return {"ok": False, "path": str(path), "detail": str(exc)}
    return {
        "ok": True,
        "path": str(path),
        "size_bytes": stat.st_size,
        "mtime": datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc).isoformat(),
        "version": f"{stat.st_size} bytes @ {datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc).isoformat()}",
    }


def npm_component_info(package: str, dist_tag: str, timeout: int) -> Dict[str, object]:
    result, command_error = run_component_command(
        ["npm", "view", package, "version", "dist-tags", "repository", "homepage", "--json"],
        timeout=timeout,
    )
    if result is None:
        return {"ok": False, "error": normalize_text_value(command_error, fallback="npm view timed out", limit=260)}
    if result.returncode != 0:
        return {"ok": False, "error": normalize_text_value(result.stderr or result.stdout, fallback="npm view failed", limit=260)}
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError as exc:
        return {"ok": False, "error": f"npm returned invalid JSON: {exc}"}
    # npm 11 may wrap a multi-field `npm view ... --json` result in a
    # single-element array.  Treat that as the same record instead of falsely
    # degrading every npm-backed component check.
    if isinstance(payload, list):
        payload = next(
            (item for item in reversed(payload) if isinstance(item, dict)),
            None,
        )
    if not isinstance(payload, dict):
        return {"ok": False, "error": "npm returned a non-object payload"}
    dist_tags = payload.get("dist-tags") if isinstance(payload.get("dist-tags"), dict) else {}
    repository = payload.get("repository")
    repository_url = ""
    if isinstance(repository, dict):
        repository_url = str(repository.get("url") or "")
    elif isinstance(repository, str):
        repository_url = repository
    if repository_url.startswith("git+"):
        repository_url = repository_url[4:]
    return {
        "ok": True,
        "version": str(payload.get("version") or ""),
        "latest_version": str(dist_tags.get(dist_tag) or payload.get("version") or ""),
        "dist_tags": dist_tags,
        "repository": repository_url,
        "homepage": str(payload.get("homepage") or ""),
    }


def parse_brew_versions(output: str, formula: str) -> List[str]:
    versions: List[str] = []
    for line in str(output or "").splitlines():
        parts = line.split()
        if not parts or parts[0] != formula:
            continue
        versions.extend(parts[1:])
    return versions


def brew_formula_info(formula: str, timeout: int) -> Dict[str, object]:
    installed_result, installed_error = run_component_command(["brew", "list", "--versions", formula], timeout=timeout)
    if installed_result is None:
        return {"ok": False, "error": normalize_text_value(installed_error, fallback="brew list timed out", limit=260)}
    installed_versions = parse_brew_versions(installed_result.stdout, formula)
    if installed_result.returncode != 0 or not installed_versions:
        return {
            "ok": False,
            "installed_versions": installed_versions,
            "error": normalize_text_value(installed_result.stderr or installed_result.stdout, fallback="formula is not installed", limit=260),
        }

    # `brew list --versions` is an inventory, not an active-version signal.
    # It can contain retained rollback kegs in a non-semantic order.  Prefer
    # Homebrew's linked keg; for keg-only formulae, prefer the installed stable
    # version.  This keeps Eve from reporting an old retained rollback as the
    # live runtime after a successful promotion.
    linked_keg = ""
    stable_version = ""
    info_result, _ = run_component_command(["brew", "info", "--json=v2", formula], timeout=timeout)
    if info_result is not None and info_result.returncode == 0:
        try:
            info_payload = json.loads(info_result.stdout or "{}")
        except json.JSONDecodeError:
            info_payload = {}
        info_formulae = info_payload.get("formulae") if isinstance(info_payload, dict) else []
        for item in info_formulae or []:
            if not isinstance(item, dict) or str(item.get("name") or "") != formula:
                continue
            metadata_versions = [
                str(entry.get("version") or "")
                for entry in item.get("installed") or []
                if isinstance(entry, dict) and str(entry.get("version") or "")
            ]
            if metadata_versions:
                installed_versions = metadata_versions
            linked_keg = str(item.get("linked_keg") or "")
            version_metadata = item.get("versions") if isinstance(item.get("versions"), dict) else {}
            stable_version = str(version_metadata.get("stable") or "")
            break

    def active_version(installed: List[str], latest: str = "") -> str:
        if linked_keg and linked_keg in installed:
            return linked_keg
        if latest and latest in installed:
            return latest
        if stable_version and stable_version in installed:
            return stable_version
        return installed[-1] if installed else ""

    outdated_result, outdated_error = run_component_command(["brew", "outdated", "--json=v2", formula], timeout=timeout)
    if outdated_result is None:
        return {
            "ok": False,
            "installed_versions": installed_versions,
            "current_version": active_version(installed_versions, stable_version),
            "error": normalize_text_value(outdated_error, fallback="brew outdated timed out", limit=260),
        }
    if outdated_result.returncode not in {0, 1}:
        return {
            "ok": False,
            "installed_versions": installed_versions,
            "current_version": active_version(installed_versions, stable_version),
            "error": normalize_text_value(outdated_result.stderr or outdated_result.stdout, fallback="brew outdated failed", limit=260),
        }
    try:
        payload = json.loads(outdated_result.stdout or "{}")
    except json.JSONDecodeError as exc:
        return {
            "ok": False,
            "installed_versions": installed_versions,
            "current_version": active_version(installed_versions, stable_version),
            "error": f"brew returned invalid JSON: {exc}",
        }
    formulae = payload.get("formulae") if isinstance(payload, dict) else []
    for item in formulae or []:
        if isinstance(item, dict) and str(item.get("name") or "") == formula:
            latest = str(item.get("current_version") or "")
            installed = [str(value) for value in item.get("installed_versions") or installed_versions]
            current = active_version(installed, latest)
            return {
                "ok": True,
                "installed_versions": installed,
                "current_version": current,
                "latest_version": latest,
                "update_available": bool(latest and current and latest != current),
                "pinned": bool(item.get("pinned")),
            }
    current = active_version(installed_versions, stable_version)
    return {
        "ok": True,
        "installed_versions": installed_versions,
        "current_version": current,
        "latest_version": stable_version or current,
        "update_available": bool(stable_version and current and stable_version != current),
        "pinned": False,
    }


def fetch_json_url(url: str, timeout: int) -> Dict[str, object]:
    try:
        req = request.Request(
            url,
            headers={
                "Accept": "application/json",
                "User-Agent": "EveComponentUpdateWatcher/1.0",
            },
        )
        with request.urlopen(req, timeout=timeout) as response:
            payload = response.read(5_000_000)
    except error.HTTPError as exc:
        return {"ok": False, "error": f"HTTP {exc.code}: {normalize_text_value(exc.reason, fallback='request failed', limit=120)}"}
    except (error.URLError, TimeoutError, OSError) as exc:
        return {"ok": False, "error": normalize_text_value(exc, fallback="request failed", limit=260)}
    try:
        decoded = json.loads(payload.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        return {"ok": False, "error": f"invalid JSON response: {exc}"}
    return {"ok": True, "payload": decoded}


def pypi_package_info(package: str, timeout: int) -> Dict[str, object]:
    url = f"https://pypi.org/pypi/{quote(package)}/json"
    fetched = fetch_json_url(url, timeout=timeout)
    if not fetched.get("ok"):
        return {"ok": False, "error": fetched.get("error") or "PyPI lookup failed", "url": url}
    payload = fetched.get("payload")
    info = payload.get("info") if isinstance(payload, dict) and isinstance(payload.get("info"), dict) else {}
    latest = str(info.get("version") or "")
    return {
        "ok": bool(latest),
        "latest_version": latest,
        "summary": normalize_text_value(info.get("summary"), fallback="", limit=220),
        "url": str(info.get("project_url") or info.get("package_url") or url),
    }


def resolve_component_python_command(python_command: object) -> List[str]:
    """Resolve a runtime-mirrored venv path back to its source owner.

    Component specifications are created at import time, so a runtime-bundle
    process naturally records paths such as ``~/.eve_runtime/.venv/bin/python``.
    Eve's dependency environments deliberately remain in the source checkout.
    Treating the missing mirrored path as a missing package corrupts the
    capability ledger even when the source-owned environment is healthy.
    """

    command = command_for_component(python_command) or ["python3"]
    executable = Path(command[0]).expanduser()
    if not executable.is_absolute() or executable.exists():
        return command
    try:
        relative = executable.relative_to(ROOT)
    except ValueError:
        relative = None
        parts = executable.parts
        for marker in (".venv", ".venv-techlab"):
            if marker in parts:
                relative = Path(*parts[parts.index(marker) :])
                break
    if relative is None:
        return command
    for root in eve_checkout_root_candidates():
        candidate = root / relative
        if candidate.exists() and os.access(candidate, os.X_OK):
            return [str(candidate), *command[1:]]
    return command


def python_package_local_version(package: str, python_command: object, timeout: int) -> Dict[str, object]:
    command = resolve_component_python_command(python_command)
    script = (
        "import importlib.metadata as m\n"
        "import sys\n"
        "package = sys.argv[1]\n"
        "try:\n"
        "    version = m.version(package)\n"
        "except m.PackageNotFoundError:\n"
        "    sys.exit(3)\n"
        "if not version or version == 'None':\n"
        "    normalized = package.lower().replace('_', '-')\n"
        "    for dist in m.distributions():\n"
        "        name = (dist.metadata.get('Name') or '').lower().replace('_', '-')\n"
        "        if name == normalized and dist.version and dist.version != 'None':\n"
        "            version = dist.version\n"
        "            break\n"
        "print(version)\n"
    )
    result, command_error = run_component_command([*command, "-c", script, package], timeout=timeout)
    if result is None:
        return {"ok": False, "version": "", "detail": normalize_text_value(command_error, fallback="package probe timed out", limit=260)}
    version = (result.stdout or "").strip()
    return {
        "ok": result.returncode == 0 and bool(version),
        "version": version,
        "returncode": result.returncode,
        "detail": normalize_text_value(result.stderr or result.stdout, fallback="", limit=260),
        "command": command,
    }


def huggingface_model_info(repo_id: str, timeout: int) -> Dict[str, object]:
    repo = normalize_huggingface_model_repo(repo_id)
    if not repo:
        return {"ok": False, "error": "no Hugging Face model repo configured"}
    url = f"https://huggingface.co/api/models/{quote(repo, safe='/')}"
    fetched = fetch_json_url(url, timeout=timeout)
    if not fetched.get("ok"):
        return {"ok": False, "error": fetched.get("error") or "Hugging Face lookup failed", "url": url}
    payload = fetched.get("payload")
    if not isinstance(payload, dict):
        return {"ok": False, "error": "Hugging Face returned a non-object payload", "url": url}
    return {
        "ok": True,
        "model_repo": repo,
        "remote_head": str(payload.get("sha") or ""),
        "last_modified": str(payload.get("lastModified") or ""),
        "downloads": payload.get("downloads"),
        "likes": payload.get("likes"),
        "url": f"https://huggingface.co/{repo}",
    }


def git_remote_branch_head(repository: str, branch: str, timeout: int) -> Dict[str, object]:
    ref = f"refs/heads/{branch}" if branch else "HEAD"
    result, command_error = run_component_command(["git", "ls-remote", repository, ref], timeout=timeout)
    if result is None:
        return {"ok": False, "error": normalize_text_value(command_error, fallback="git ls-remote timed out", limit=260)}
    if result.returncode != 0:
        return {"ok": False, "error": normalize_text_value(result.stderr or result.stdout, fallback="git ls-remote failed", limit=260)}
    first_line = (result.stdout or "").splitlines()[0] if result.stdout else ""
    parts = first_line.split()
    return {"ok": bool(parts), "ref": ref, "head": parts[0] if parts else "", "raw": first_line}


def component_mirror_path(config: Dict[str, object], component: Dict[str, object]) -> Path:
    return component_upstreams_dir(config) / f"{component_slug(component.get('id'))}.git"


def local_component_mirror_head(config: Dict[str, object], component: Dict[str, object], timeout: int) -> Dict[str, object]:
    mirror_path = component_mirror_path(config, component)
    branch = str(component.get("branch") or "main")
    if not mirror_path.exists():
        return {"ok": False, "exists": False, "path": str(mirror_path), "head": "", "status": "not_bootstrapped"}
    result, command_error = run_component_command(["git", "--git-dir", str(mirror_path), "rev-parse", f"refs/heads/{branch}"], timeout=timeout)
    if result is None:
        return {
            "ok": False,
            "exists": True,
            "path": str(mirror_path),
            "head": "",
            "status": "unreadable",
            "error": normalize_text_value(command_error, fallback="mirror rev-parse timed out", limit=220),
        }
    if result.returncode != 0:
        return {
            "ok": False,
            "exists": True,
            "path": str(mirror_path),
            "head": "",
            "status": "unreadable",
            "error": normalize_text_value(result.stderr or result.stdout, fallback="mirror rev-parse failed", limit=220),
        }
    return {"ok": True, "exists": True, "path": str(mirror_path), "head": result.stdout.strip(), "status": "ready"}


def mirror_component_upstream(config: Dict[str, object], component: Dict[str, object], timeout: int) -> Dict[str, object]:
    repository = str(component.get("repository") or "")
    if not repository:
        return {"ok": False, "error": "component has no repository"}
    mirror_path = component_mirror_path(config, component)
    branch = str(component.get("branch") or "main")
    fetch_refspec = f"+refs/heads/{branch}:refs/heads/{branch}"
    mirror_path.parent.mkdir(parents=True, exist_ok=True)
    if mirror_path.exists():
        remote_url, _ = run_component_command(["git", "--git-dir", str(mirror_path), "remote", "get-url", "origin"], timeout=timeout)
        if remote_url is None or remote_url.returncode != 0:
            run_component_command(["git", "--git-dir", str(mirror_path), "remote", "add", "origin", repository], timeout=timeout)
        else:
            run_component_command(["git", "--git-dir", str(mirror_path), "remote", "set-url", "origin", repository], timeout=timeout)
        run_component_command(["git", "--git-dir", str(mirror_path), "config", "--unset-all", "remote.origin.fetch"], timeout=timeout)
        run_component_command(["git", "--git-dir", str(mirror_path), "config", "--add", "remote.origin.fetch", fetch_refspec], timeout=timeout)
        result, command_error = run_component_command(
            ["git", "--git-dir", str(mirror_path), "fetch", "--prune", "--depth", "1", "origin", fetch_refspec],
            timeout=timeout,
        )
        action = "updated"
    else:
        clone_command = ["git", "clone", "--bare", "--single-branch", "--branch", branch, "--depth", "1"]
        git_filter = str(config.get("component_update_git_filter") or "").strip()
        if git_filter:
            clone_command.extend(["--filter", git_filter])
        clone_command.extend([repository, str(mirror_path)])
        result, command_error = run_component_command(clone_command, timeout=timeout)
        action = "cloned"
    if result is None:
        return {
            "ok": False,
            "action": action,
            "path": str(mirror_path),
            "error": normalize_text_value(command_error, fallback="git mirror operation timed out", limit=260),
        }
    if result.returncode != 0:
        return {
            "ok": False,
            "action": action,
            "path": str(mirror_path),
            "error": normalize_text_value(result.stderr or result.stdout, fallback="git mirror operation failed", limit=260),
        }
    head = local_component_mirror_head(config, component, timeout=timeout)
    return {"ok": True, "action": action, "path": str(mirror_path), "head": head.get("head") or ""}


def check_component_updates(
    config: Dict[str, object],
    *,
    mirror: bool = False,
    timeout: Optional[int] = None,
) -> Dict[str, object]:
    timeout_seconds = int(timeout or config.get("component_update_timeout_seconds") or 90)
    previous_state = load_component_update_state(prefer_runtime=True)
    previous_by_id = {
        str(item.get("id") or ""): item
        for item in previous_state.get("components", [])
        if isinstance(item, dict)
    }
    records: List[Dict[str, object]] = []
    for component in component_watchlist(config):
        component_id = str(component.get("id") or "")
        kind = str(component.get("kind") or "").strip()
        branch = str(component.get("branch") or "main")
        repository = str(component.get("repository") or "")
        record: Dict[str, object] = {
            "id": component_id,
            "name": str(component.get("name") or component_id),
            "kind": kind,
            "checked_at": utc_now(),
            "repository": repository,
            "release_repository": str(component.get("release_repository") or ""),
            "release_feature_mode": str(component.get("release_feature_mode") or "installed_version"),
            "branch": branch,
            "source_url": str(component.get("source_url") or component.get("homepage") or ""),
            "capability_domains": list(component.get("capability_domains") or []),
            "candidate_role": str(component.get("candidate_role") or component.get("eve_role") or ""),
            "adoption": str(component.get("adoption") or ""),
            "update_available": False,
            "errors": [],
        }

        try:
            if kind == "local_file":
                file_info = local_file_component_info(component.get("path"))
                record["local_version"] = file_info.get("version") or ""
                record["local_probe_ok"] = bool(file_info.get("ok"))
                record["local_probe_detail"] = file_info.get("detail") or file_info.get("path") or ""
                record["local_path"] = file_info.get("path") or ""
                record["size_bytes"] = file_info.get("size_bytes")
                record["mtime"] = file_info.get("mtime") or ""
                previous = previous_by_id.get(component_id) or {}
                previous_mtime = str(previous.get("mtime") or "")
                record["previous_mtime"] = previous_mtime
                if previous_mtime and previous_mtime != record.get("mtime"):
                    record["update_available"] = True
                if not file_info.get("ok"):
                    record["errors"].append(file_info.get("detail") or "local file probe failed")

            elif kind == "brew_formula":
                local = local_component_version(component, timeout=timeout_seconds, config=config)
                record["local_version"] = local.get("version") or ""
                record["local_probe_ok"] = bool(local.get("ok"))
                record["local_probe_detail"] = local.get("detail") or ""
                if local.get("path"):
                    record["local_path"] = local.get("path") or ""
                if local.get("mtime"):
                    record["mtime"] = local.get("mtime") or ""
                if local.get("lanes"):
                    record["lane_binaries"] = local.get("lanes") or []
                formula = str(component.get("formula") or component_id)
                record["formula"] = formula
                brew_info = brew_formula_info(formula, timeout=timeout_seconds)
                if brew_info.get("ok"):
                    installed_versions = [str(value) for value in brew_info.get("installed_versions") or []]
                    record["installed_versions"] = installed_versions
                    record["local_version"] = str(brew_info.get("current_version") or record.get("local_version") or "")
                    record["latest_version"] = str(brew_info.get("latest_version") or brew_info.get("current_version") or "")
                    record["pinned"] = bool(brew_info.get("pinned"))
                    record["update_available"] = bool(brew_info.get("update_available"))
                else:
                    record["installed_versions"] = brew_info.get("installed_versions") or []
                    record["errors"].append(brew_info.get("error") or "Homebrew lookup failed")

            elif kind == "npm_package":
                local = local_component_version(component, timeout=timeout_seconds, config=config)
                record["local_version"] = local.get("version") or ""
                record["local_probe_ok"] = bool(local.get("ok"))
                record["local_probe_detail"] = local.get("detail") or ""
                npm_info = npm_component_info(str(component.get("package")), str(component.get("dist_tag") or "latest"), timeout_seconds)
                if npm_info.get("ok"):
                    record["package"] = str(component.get("package"))
                    record["latest_version"] = npm_info.get("latest_version") or npm_info.get("version") or ""
                    record["dist_tags"] = npm_info.get("dist_tags") or {}
                    record["source_url"] = npm_info.get("homepage") or ""
                    if record.get("local_version") and record.get("latest_version"):
                        record["update_available"] = str(record["local_version"]) != str(record["latest_version"])
                else:
                    record["errors"].append(npm_info.get("error") or "npm lookup failed")

            elif kind == "python_package":
                package = str(component.get("package") or "")
                record["package"] = package
                local = python_package_local_version(package, component.get("python_command"), timeout=timeout_seconds)
                record["local_version"] = local.get("version") or ""
                record["local_probe_ok"] = bool(local.get("ok"))
                record["local_probe_detail"] = local.get("detail") or ""
                if not local.get("ok"):
                    record["errors"].append(f"local Python package not found: {package}")
                pypi_info = pypi_package_info(package, timeout=timeout_seconds)
                if pypi_info.get("ok"):
                    record["latest_version"] = pypi_info.get("latest_version") or ""
                    record["source_url"] = pypi_info.get("url") or ""
                    if record.get("local_version") and record.get("latest_version"):
                        record["update_available"] = str(record["local_version"]) != str(record["latest_version"])
                    blocked_versions = {str(value) for value in component.get("blocked_versions") or []}
                    if str(record.get("latest_version") or "") in blocked_versions:
                        record["blocked_latest_version"] = record.get("latest_version") or ""
                        record["blocked_version_reason"] = str(component.get("blocked_version_reason") or "")
                        record["update_available"] = False
                else:
                    record["errors"].append(pypi_info.get("error") or "PyPI lookup failed")

            elif kind == "huggingface_model":
                model_repo = str(component.get("model_repo") or "")
                record["model_repo"] = model_repo
                hf_info = huggingface_model_info(model_repo, timeout=timeout_seconds)
                if hf_info.get("ok"):
                    record["remote_head"] = hf_info.get("remote_head") or ""
                    record["latest_version"] = (record.get("remote_head") or "")[:12]
                    record["last_modified"] = hf_info.get("last_modified") or ""
                    record["downloads"] = hf_info.get("downloads")
                    record["likes"] = hf_info.get("likes")
                    record["source_url"] = hf_info.get("url") or ""
                    previous = previous_by_id.get(component_id) or {}
                    previous_head = str(previous.get("remote_head") or "")
                    record["previous_remote_head"] = previous_head
                    if previous_head and previous_head != record.get("remote_head"):
                        record["update_available"] = True
                else:
                    record["errors"].append(hf_info.get("error") or "Hugging Face lookup failed")

            else:
                local = local_component_version(component, timeout=timeout_seconds, config=config)
                record["local_version"] = local.get("version") or ""
                record["local_probe_ok"] = bool(local.get("ok"))
                record["local_probe_detail"] = local.get("detail") or ""
                if local.get("path"):
                    record["local_path"] = local.get("path") or ""
                if local.get("mtime"):
                    record["mtime"] = local.get("mtime") or ""
                if local.get("lanes"):
                    record["lane_binaries"] = local.get("lanes") or []

                if component.get("package"):
                    npm_info = npm_component_info(str(component.get("package")), str(component.get("dist_tag") or "latest"), timeout_seconds)
                    if npm_info.get("ok"):
                        record["package"] = str(component.get("package"))
                        record["latest_version"] = npm_info.get("latest_version") or npm_info.get("version") or ""
                        record["dist_tags"] = npm_info.get("dist_tags") or {}
                        if not repository and npm_info.get("repository"):
                            repository = str(npm_info.get("repository") or "")
                            record["repository"] = repository
                        if record.get("local_version") and record.get("latest_version"):
                            record["update_available"] = str(record["local_version"]) != str(record["latest_version"])
                    else:
                        record["errors"].append(npm_info.get("error") or "npm lookup failed")

                if repository:
                    remote = git_remote_branch_head(repository, branch, timeout_seconds)
                    if remote.get("ok"):
                        record["remote_head"] = remote.get("head") or ""
                        previous = previous_by_id.get(component_id) or {}
                        previous_head = str(previous.get("remote_head") or "")
                        record["previous_remote_head"] = previous_head
                        if previous_head and previous_head != record["remote_head"]:
                            record["update_available"] = True
                    else:
                        record["errors"].append(remote.get("error") or "git remote lookup failed")

                    if mirror:
                        mirror_result = mirror_component_upstream(config, component, timeout=max(timeout_seconds, 300))
                        record["mirror_action"] = mirror_result.get("action") or ""
                        if not mirror_result.get("ok"):
                            record["errors"].append(mirror_result.get("error") or "mirror failed")

                    mirror_head = local_component_mirror_head(config, component, timeout=timeout_seconds)
                    record["mirror_path"] = mirror_head.get("path") or str(component_mirror_path(config, component))
                    record["mirror_status"] = mirror_head.get("status") or "unknown"
                    record["mirror_head"] = mirror_head.get("head") or ""
                    if record.get("remote_head") and record.get("mirror_head") and record["remote_head"] != record["mirror_head"]:
                        record["update_available"] = True
        except Exception as exc:
            record["errors"].append(f"{type(exc).__name__}: {normalize_text_value(exc, fallback='component check failed', limit=220)}")

        record["status"] = "update_available" if record.get("update_available") else "current_or_baselined"
        if record["errors"]:
            record["status"] = "check_degraded_with_update" if record.get("update_available") else "check_degraded"
        records.append(record)

    available = [item for item in records if item.get("update_available")]
    degraded = [item for item in records if item.get("errors")]
    if available:
        summary = f"{len(available)} component update signal(s): " + ", ".join(str(item.get("name") or item.get("id")) for item in available[:4])
    elif degraded:
        summary = f"No confirmed updates, but {len(degraded)} component check(s) were degraded."
    else:
        summary = f"No component updates detected across {len(records)} watched component(s)."
    state = save_component_update_state(
        {
            "summary": summary,
            "components": records,
            "mirror_root": str(component_upstreams_dir(config)),
        }
    )
    append_entry(
        "component_update_check",
        summary,
        metadata={
            "source": "manual" if not mirror else "manual_with_mirror",
            "updates": [item.get("id") for item in available],
            "degraded": [item.get("id") for item in degraded],
        },
    )
    return state


def format_component_update_record(record: Dict[str, object], full: bool = False) -> str:
    kind = str(record.get("kind") or "unknown")
    latest_label = record.get("latest_version") or record.get("last_modified") or "n/a"
    lines = [
        f"{record.get('id')} [{record.get('status')}] {record.get('name')} ({kind})",
        f"local: {record.get('local_version') or 'unknown'} | latest: {latest_label}",
        f"update_available: {'yes' if record.get('update_available') else 'no'} | checked_at: {record.get('checked_at') or 'unknown'}",
    ]
    if record.get("remote_head") or record.get("mirror_head") or record.get("mirror_status"):
        lines.insert(
            2,
            f"remote_head: {str(record.get('remote_head') or 'unknown')[:12]} | mirror: {record.get('mirror_status') or 'n/a'} {str(record.get('mirror_head') or '')[:12]}",
        )
    if record.get("formula"):
        lines.append(f"formula: {record.get('formula')} | installed: {', '.join(str(item) for item in record.get('installed_versions') or []) or 'unknown'}")
    if record.get("package"):
        lines.append(f"package: {record.get('package')}")
    if record.get("capability_domains"):
        lines.append("capability_domains: " + ", ".join(str(item) for item in record.get("capability_domains") or []))
    if record.get("candidate_role"):
        lines.append(f"candidate_role: {record.get('candidate_role')}")
    if record.get("model_repo"):
        lines.append(f"model_repo: {record.get('model_repo')} | last_modified: {record.get('last_modified') or 'unknown'}")
    if record.get("local_path"):
        lines.append(f"local_path: {record.get('local_path')} | mtime: {record.get('mtime') or 'unknown'}")
    if record.get("errors"):
        lines.append("errors: " + "; ".join(str(item) for item in record.get("errors") or []))
    if full:
        lines.extend(
            [
                f"repository: {record.get('repository') or 'none'}",
                f"source_url: {record.get('source_url') or 'none'}",
                f"mirror_path: {record.get('mirror_path') or 'none'}",
                f"adoption: {record.get('adoption') or 'none recorded'}",
                f"local_probe_detail: {record.get('local_probe_detail') or 'none'}",
            ]
        )
        lane_binaries = record.get("lane_binaries") if isinstance(record.get("lane_binaries"), list) else []
        for lane_binary in lane_binaries[:5]:
            if not isinstance(lane_binary, dict):
                continue
            lines.append(
                "lane_binary: "
                f"{lane_binary.get('lane') or 'unknown'} "
                f"{lane_binary.get('version') or 'unknown'} "
                f"{lane_binary.get('path') or 'unknown'}"
            )
    return "\n".join(lines)


def openclaw_mirror_path(config: Dict[str, object]) -> Path:
    return component_upstreams_dir(config) / "openclaw.git"


def openclaw_workspace_path(config: Dict[str, object]) -> Path:
    raw = (
        config.get("openclaw_workspace_path")
        or config.get("openclaw_workspace")
        or config.get("openclaw_source_path")
        or RUNTIME_DIR / "openclaw"
    )
    return Path(raw).expanduser().resolve()


def git_dir_looks_usable(path: Path) -> bool:
    return path.is_dir() and ((path / "objects").exists() or (path / "HEAD").exists())


def source_tree_looks_usable(path: Path) -> bool:
    if not path.is_dir():
        return False
    markers = ["AGENTS.md", "TOOLS.md", "HEARTBEAT.md", "skills", "docs", "packages", "extensions"]
    return any((path / marker).exists() for marker in markers)


def resolve_openclaw_source(config: Dict[str, object]) -> Dict[str, object]:
    workspace_path = openclaw_workspace_path(config)
    mirror_path = openclaw_mirror_path(config)
    candidates = [
        {"path": mirror_path, "kind": "bare_git_mirror"},
        {"path": workspace_path, "kind": "workspace"},
    ]
    seen: set[str] = set()
    notes: List[str] = []
    for candidate in candidates:
        path = Path(candidate["path"])
        path_key = str(path)
        if path_key in seen:
            continue
        seen.add(path_key)
        kind = str(candidate["kind"])
        if kind == "bare_git_mirror":
            if git_dir_looks_usable(path):
                return {
                    "path": str(path),
                    "kind": kind,
                    "mirror_path": str(mirror_path),
                    "workspace_path": str(workspace_path),
                    "notes": notes,
                }
            notes.append(f"OpenClaw mirror is not inspectable at {path}")
            continue
        if source_tree_looks_usable(path):
            return {
                "path": str(path),
                "kind": "source_tree",
                "mirror_path": str(mirror_path),
                "workspace_path": str(workspace_path),
                "notes": notes,
            }
        notes.append(f"OpenClaw workspace not found or missing markers at {path}")
    return {
        "path": "",
        "kind": "missing",
        "mirror_path": str(mirror_path),
        "workspace_path": str(workspace_path),
        "notes": notes,
    }


def list_source_tree_files(root: Path, limit: int = 40000) -> List[str]:
    ignored_parts = {".git", "__pycache__", ".venv", "node_modules", ".mypy_cache", ".pytest_cache"}
    files: List[str] = []
    for path in root.rglob("*"):
        if len(files) >= limit:
            break
        if not path.is_file():
            continue
        try:
            relative = path.relative_to(root)
        except ValueError:
            continue
        if any(part in ignored_parts for part in relative.parts):
            continue
        files.append(relative.as_posix())
    return sorted(files)


def list_openclaw_source_files(config: Dict[str, object], timeout: int = 60) -> Tuple[List[str], str, Dict[str, object]]:
    source = resolve_openclaw_source(config)
    source_path_text = str(source.get("path") or "")
    if not source_path_text:
        return [], "; ".join(str(note) for note in source.get("notes") or []) or "OpenClaw source not found.", source
    source_path = Path(source_path_text)
    if source.get("kind") == "bare_git_mirror":
        result = run_local_command(["git", "--git-dir", str(source_path), "ls-tree", "-r", "--name-only", "HEAD"], timeout=timeout)
        if result.returncode != 0:
            return [], normalize_text_value(result.stderr or result.stdout, fallback="Could not inspect OpenClaw source mirror.", limit=260), source
        return [line.strip() for line in result.stdout.splitlines() if line.strip()], "", source
    if (source_path / ".git").exists():
        result = run_local_command(["git", "-C", str(source_path), "ls-files"], timeout=timeout)
        if result.returncode == 0:
            files = [line.strip() for line in result.stdout.splitlines() if line.strip()]
            if files:
                return files, "", source
    files = list_source_tree_files(source_path)
    if not files:
        return [], f"OpenClaw source tree had no inspectable files at {source_path}", source
    return files, "", source


def legacy_list_openclaw_source_files(config: Dict[str, object], timeout: int = 60) -> Tuple[List[str], str]:
    mirror_path = openclaw_mirror_path(config)
    if not mirror_path.exists():
        return [], f"OpenClaw source mirror not found at {mirror_path}"
    result = run_local_command(["git", "--git-dir", str(mirror_path), "ls-tree", "-r", "--name-only", "HEAD"], timeout=timeout)
    if result.returncode != 0:
        return [], normalize_text_value(result.stderr or result.stdout, fallback="Could not inspect OpenClaw source mirror.", limit=260)
    return [line.strip() for line in result.stdout.splitlines() if line.strip()], ""


def path_matches_any(path: str, patterns: Iterable[str]) -> bool:
    for pattern in patterns:
        marker = str(pattern or "").strip()
        if not marker:
            continue
        if marker.endswith("/") and path.startswith(marker):
            return True
        if path == marker or marker in path:
            return True
    return False


OPENCLAW_SURFACE_CATEGORY_MEANINGS = {
    "channel": "A communication channel Eve may be able to reach through OpenClaw after credentials and policy are configured.",
    "cli_command": "An OpenClaw command surface Eve can study or call through a bounded OpenClaw sidecar.",
    "tool_doc": "A documented OpenClaw tool area that may overlap Eve's own capabilities.",
    "plugin_doc": "A plugin/plugin-SDK area where OpenClaw can expose reusable capabilities.",
    "automation_doc": "A scheduling, task, webhook, or standing-order surface useful for follow-through.",
    "gateway_doc": "Gateway, API, auth, logging, sandbox, or node-control capability.",
    "concept_doc": "Architecture or runtime concept Eve should know when choosing whether to reuse OpenClaw.",
    "extension": "Bundled OpenClaw extension code that may already implement a reusable capability.",
    "package": "OpenClaw package/module source that may expose reusable runtime or SDK behavior.",
    "skill": "Bundled OpenClaw skill; inspect before adoption because skills can add tool behavior.",
    "repair_skill": "OpenClaw repair skill that tells Eve how to inspect, repair, and verify herself.",
    "operator_profile": "OpenClaw identity/operator profile file Eve can use to understand the sidecar's role and boundaries.",
    "workspace_memory": "OpenClaw memory or status file that preserves repair context and current operational evidence.",
    "config_profile": "OpenClaw local configuration profile that explains how the sidecar workspace is wired.",
    "android_node_handler": "Android node/device handler that may expose phone, sensor, media, or local-device actions.",
    "voice_runtime_command": "Swabble voice runtime command useful for listening, transcribing, wake-word, or speech loops.",
}


def humanize_capability_slug(value: object) -> str:
    text = str(value or "").strip()
    text = re.sub(r"\.(md|swift|kt|ts|tsx|mjs|js|json)$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", text)
    text = text.replace("_", " ").replace("-", " ").replace(".", " ")
    words = [word for word in text.split() if word]
    return " ".join(word.upper() if word.lower() in {"api", "mcp", "sms", "qa", "ui", "dns"} else word.capitalize() for word in words)


def surface_risk_level(category: str, slug: str) -> str:
    sensitive_words = {
        "auth",
        "approval",
        "credential",
        "device",
        "exec",
        "gateway",
        "message",
        "notification",
        "photos",
        "sandbox",
        "secret",
        "sms",
        "system",
        "webhook",
    }
    text = f"{category} {slug}".lower()
    if any(word in text for word in sensitive_words):
        return "high"
    if category in {"channel", "plugin_doc", "extension", "android_node_handler", "repair_skill"}:
        return "medium"
    return "low"


def openclaw_surface_domain(category: str, slug: str) -> str:
    if category == "channel":
        return "multi_channel_gateway"
    if category in {"plugin_doc", "extension", "package"}:
        return "plugin_hooks"
    if category == "automation_doc":
        return "cron_hooks"
    if category == "android_node_handler":
        return "device_tools"
    if category == "voice_runtime_command":
        return "voice_runtime"
    if category == "skill":
        return "skills"
    if category == "repair_skill":
        return "self_repair_sidecar"
    if category in {"operator_profile", "workspace_memory"}:
        return "operator_context"
    if category == "config_profile":
        return "configuration"
    if category == "gateway_doc":
        return "gateway"
    if category == "tool_doc":
        return "tools"
    return "openclaw_architecture"


def add_openclaw_surface(
    surfaces_by_id: Dict[str, Dict[str, object]],
    *,
    category: str,
    slug: str,
    name: str,
    evidence: str,
) -> None:
    normalized_slug = component_slug(slug)
    if not normalized_slug:
        return
    surface_id = f"openclaw.{category}.{normalized_slug}"
    record = surfaces_by_id.setdefault(
        surface_id,
        {
            "id": surface_id,
            "category": category,
            "slug": normalized_slug,
            "name": name,
            "capability_domain": openclaw_surface_domain(category, normalized_slug),
            "risk_level": surface_risk_level(category, normalized_slug),
            "meaning_for_eve": OPENCLAW_SURFACE_CATEGORY_MEANINGS.get(category, "OpenClaw capability surface."),
            "evidence": [],
            "file_count": 0,
        },
    )
    evidence_list = record.get("evidence") if isinstance(record.get("evidence"), list) else []
    if evidence and evidence not in evidence_list and len(evidence_list) < 8:
        evidence_list.append(evidence)
    record["evidence"] = evidence_list
    record["file_count"] = int(record.get("file_count") or 0) + 1


def discover_openclaw_capability_surfaces(files: Iterable[str]) -> List[Dict[str, object]]:
    surfaces_by_id: Dict[str, Dict[str, object]] = {}
    doc_categories = {
        "docs/channels/": "channel",
        "docs/cli/": "cli_command",
        "docs/tools/": "tool_doc",
        "docs/plugins/": "plugin_doc",
        "docs/automation/": "automation_doc",
        "docs/gateway/": "gateway_doc",
        "docs/concepts/": "concept_doc",
    }
    for path in files:
        path_text = str(path or "").strip()
        if not path_text:
            continue
        for prefix, category in doc_categories.items():
            if not path_text.startswith(prefix) or not path_text.endswith(".md"):
                continue
            slug = Path(path_text).stem
            if slug in {"index"}:
                continue
            add_openclaw_surface(
                surfaces_by_id,
                category=category,
                slug=slug,
                name=f"{humanize_capability_slug(category.replace('_doc', '').replace('_command', ''))}: {humanize_capability_slug(slug)}",
                evidence=path_text,
            )
        if path_text.startswith("extensions/"):
            parts = path_text.split("/")
            if len(parts) >= 2 and parts[1]:
                add_openclaw_surface(
                    surfaces_by_id,
                    category="extension",
                    slug=parts[1],
                    name=f"Extension: {humanize_capability_slug(parts[1])}",
                    evidence=path_text,
                )
        if path_text.startswith("packages/"):
            parts = path_text.split("/")
            if len(parts) >= 2 and parts[1]:
                add_openclaw_surface(
                    surfaces_by_id,
                    category="package",
                    slug=parts[1],
                    name=f"Package: {humanize_capability_slug(parts[1])}",
                    evidence=path_text,
                )
        if path_text.startswith(".agents/skills/") and path_text.endswith("SKILL.md"):
            parts = path_text.split("/")
            if len(parts) >= 3 and parts[2]:
                add_openclaw_surface(
                    surfaces_by_id,
                    category="skill",
                    slug=parts[2],
                    name=f"Skill: {humanize_capability_slug(parts[2])}",
                    evidence=path_text,
                )
        if path_text.startswith("skills/") and path_text.endswith("SKILL.md"):
            parts = path_text.split("/")
            if len(parts) >= 2 and parts[1]:
                add_openclaw_surface(
                    surfaces_by_id,
                    category="repair_skill",
                    slug=parts[1],
                    name=f"Repair skill: {humanize_capability_slug(parts[1])}",
                    evidence=path_text,
                )
        if path_text in {"AGENTS.md", "TOOLS.md", "IDENTITY.md", "SOUL.md", "USER.md", "HEARTBEAT.md"}:
            add_openclaw_surface(
                surfaces_by_id,
                category="operator_profile",
                slug=Path(path_text).stem,
                name=f"Operator profile: {humanize_capability_slug(Path(path_text).stem)}",
                evidence=path_text,
            )
        if path_text in {"MEMORY.md", "context/eve_status.md", "context/eve_status.json", "context/last_repair.md"}:
            add_openclaw_surface(
                surfaces_by_id,
                category="workspace_memory",
                slug=Path(path_text).stem,
                name=f"Workspace memory: {humanize_capability_slug(Path(path_text).stem)}",
                evidence=path_text,
            )
        if path_text.startswith("config/") or path_text == ".openclaw/workspace-state.json":
            add_openclaw_surface(
                surfaces_by_id,
                category="config_profile",
                slug=Path(path_text).stem,
                name=f"Config profile: {humanize_capability_slug(Path(path_text).stem)}",
                evidence=path_text,
            )
        if path_text.startswith("apps/android/app/src/main/java/ai/openclaw/app/node/") and path_text.endswith("Handler.kt"):
            slug = Path(path_text).stem
            add_openclaw_surface(
                surfaces_by_id,
                category="android_node_handler",
                slug=slug,
                name=f"Android node handler: {humanize_capability_slug(slug.replace('Handler', ''))}",
                evidence=path_text,
            )
        if path_text.startswith("Swabble/Sources/swabble/Commands/") and path_text.endswith("Command.swift"):
            slug = Path(path_text).stem
            add_openclaw_surface(
                surfaces_by_id,
                category="voice_runtime_command",
                slug=slug,
                name=f"Voice runtime command: {humanize_capability_slug(slug.replace('Command', ''))}",
                evidence=path_text,
            )
    return sorted(surfaces_by_id.values(), key=lambda item: (str(item.get("category")), str(item.get("name"))))


