MODEL_TOTAL_SOFT_WEIGHT_GIB = 35.0
MODEL_TOTAL_HARD_WEIGHT_GIB = 42.0
MODEL_LANE_ROLE_HINTS = {
    "fast": "chat",
    "deep": "reflection",
    "observer": "general",
    "planner": "general",
    "relationship": "general",
}


def watchdog_loaded_model_map(status: Dict[str, object]) -> Dict[str, Dict[str, object]]:
    records: Dict[str, Dict[str, object]] = {}
    loaded_models = status.get("loaded_models") if isinstance(status.get("loaded_models"), list) else []
    for item in loaded_models:
        if not isinstance(item, dict):
            continue
        name = normalize_model_name(item.get("name"))
        if not name:
            continue
        records[name] = item
        records.setdefault(name.split(":")[0], item)
    return records


def watchdog_llama_host_map(status: Dict[str, object]) -> Dict[str, Dict[str, object]]:
    records: Dict[str, Dict[str, object]] = {}
    for item in status.get("llama_hosts") or []:
        if not isinstance(item, dict):
            continue
        host = normalize_text_value(item.get("host"), fallback="", limit=200).rstrip("/")
        if host:
            records[host] = item
    return records


def model_probe_latency_ms(probe: Dict[str, object]) -> Optional[float]:
    if not isinstance(probe, dict):
        return None
    for key in ["wall_ms", "total_ms", "load_ms"]:
        try:
            value = float(probe.get(key))
        except (TypeError, ValueError):
            continue
        if value > 0:
            return value
    return None


def configured_lane_usage(config: Dict[str, object], lane: str, alias: str) -> List[str]:
    normalized_alias = normalize_model_name(alias)
    if not normalized_alias:
        return MODEL_LANE_USAGE.get(lane, [])
    role_candidates = [
        ("fallback", config.get("model")),
        ("chat", config.get("fast_model")),
        ("reflection", config.get("deep_model")),
        ("proposal", config.get("deep_model")),
        ("awareness", config.get("deep_model")),
        ("reply listener", config.get("reply_stream_listener_model")),
        ("reply factual", config.get("reply_stream_factual_model")),
        ("reply skeptic", config.get("reply_stream_skeptic_model")),
        ("reply synthesis", config.get("reply_stream_synthesis_model")),
        ("mind observer", config.get("mind_stream_observer_model")),
        ("mind planner", config.get("mind_stream_planner_model")),
        ("mind relationship", config.get("mind_stream_relationship_model")),
        ("mind grounding", config.get("mind_stream_grounding_model")),
        ("mind self-check", config.get("mind_stream_self_check_model")),
        ("mind synthesis", config.get("mind_stream_synthesis_model")),
    ]
    uses: List[str] = []
    for role, model in role_candidates:
        normalized_model = normalize_model_name(model)
        if normalized_model and normalized_model == normalized_alias and role not in uses:
            uses.append(role)
    return uses or MODEL_LANE_USAGE.get(lane, [])


def model_lane_records(
    config: Dict[str, object],
    watchdog_status: Optional[Dict[str, object]] = None,
) -> List[Dict[str, object]]:
    status = watchdog_status if isinstance(watchdog_status, dict) else {}
    loaded_map = watchdog_loaded_model_map(status)
    host_map = watchdog_llama_host_map(status)
    probes = status.get("probes") if isinstance(status.get("probes"), dict) else {}
    probe_timestamps = status.get("probe_timestamps") if isinstance(status.get("probe_timestamps"), dict) else {}
    records: List[Dict[str, object]] = []

    service_routes = {
        str(route.get("logical_lane") or ""): route
        for route in eve_model_topology.logical_routes(config)
    }
    for lane in MODEL_LANE_ORDER:
        route = service_routes.get(lane, {})
        model = normalize_model_name(route.get("substrate_model"))
        nominal_model = normalize_model_name(route.get("nominal_model"))
        substrate_profile = normalize_text_value(
            route.get("substrate_profile"), fallback=lane, limit=40
        )
        host = normalize_text_value(
            route.get("substrate_host"), fallback="", limit=200
        ).rstrip("/")
        backend = (
            configured_model_backend(
                config,
                model,
                MODEL_LANE_ROLE_HINTS.get(substrate_profile, "general"),
            )
            if substrate_profile in {"fast", "deep"}
            else "llama_cpp"
        )
        loaded = loaded_map.get(model) or loaded_map.get(model.split(":")[0] if model else "")
        probe = probes.get(model) if isinstance(probes.get(model), dict) else {}
        host_state = host_map.get(host) or {}
        visible_models = [normalize_model_name(item) for item in host_state.get("models") or [] if normalize_model_name(item)]
        records.append(
            {
                "lane": lane,
                "label": MODEL_LANE_LABELS.get(lane, lane.title()),
                "model": model,
                "nominal_model": nominal_model,
                "topology_mode": route.get("topology_mode"),
                "substrate_profile": substrate_profile,
                "shared_substrate_lanes": list(route.get("shared_lanes") or [lane]),
                "backend": backend,
                "host": host,
                "uses": configured_lane_usage(config, lane, nominal_model or model),
                "loaded": bool(loaded),
                "probe_ok": bool(probe.get("ok")) if probe else False,
                "latency_ms": model_probe_latency_ms(probe),
                "probe": probe,
                "probe_updated_at": probe_timestamps.get(model),
                "context_length": loaded.get("context_length") if isinstance(loaded, dict) else None,
                "size_vram": loaded.get("size_vram") if isinstance(loaded, dict) else None,
                "error": normalize_text_value(
                    probe.get("error") if isinstance(probe, dict) else "",
                    fallback="",
                    limit=220,
                ),
                "host_ready": bool(host_state.get("ready")) if host_state else None,
                "visible_models": visible_models,
            }
        )

    return records


def model_lane_summary_text(record: Dict[str, object]) -> str:
    latency = format_duration_ms(record.get("latency_ms")) if record.get("latency_ms") is not None else "unknown"
    resident = "resident" if record.get("loaded") else "not resident"
    signal = "ok" if record.get("probe_ok") else "probe pending"
    return f"{record.get('label')}: {record.get('model')} · {resident} · {latency} · {signal}"


def model_host_records(
    config: Dict[str, object],
    watchdog_status: Optional[Dict[str, object]] = None,
) -> List[Dict[str, object]]:
    records: List[Dict[str, object]] = []
    seen: set[tuple[str, str]] = set()
    for lane in model_lane_records(config, watchdog_status=watchdog_status):
        host = normalize_text_value(lane.get("host"), fallback="", limit=200).rstrip("/")
        backend = normalize_model_backend(lane.get("backend"))
        if not host or (backend, host) in seen:
            continue
        seen.add((backend, host))
        records.append(
            {
                "backend": backend,
                "host": host,
                "ready": lane.get("host_ready"),
                "visible_models": lane.get("visible_models") or [],
                "lanes": [lane.get("lane")],
            }
        )
    host_map = watchdog_llama_host_map(watchdog_status or {})
    for record in records:
        extra = host_map.get(record["host"]) or {}
        if extra and not record["visible_models"]:
            record["visible_models"] = [normalize_model_name(item) for item in extra.get("models") or [] if normalize_model_name(item)]
        peer_lanes = [lane.get("lane") for lane in model_lane_records(config, watchdog_status=watchdog_status) if lane.get("host") == record["host"]]
        record["lanes"] = [item for item in peer_lanes if item]
    return records


def model_lanes_summary(records: List[Dict[str, object]]) -> str:
    if not records:
        return "No model lanes configured."
    resident_count = sum(1 for item in records if item.get("loaded"))
    probe_count = sum(1 for item in records if item.get("probe_ok"))
    return f"{len(records)} lanes · {resident_count} resident · {probe_count} probed"


def apply_transient_model_override(config: Dict[str, object], model: Optional[str]) -> Dict[str, object]:
    normalized = normalize_model_name(model)
    if normalized:
        config["_model_override"] = normalized
        config["model"] = normalized
    return config


def resolve_model(
    config: Dict[str, object],
    role: str = "general",
    explicit_model: Optional[str] = None,
) -> str:
    explicit = normalize_model_name(explicit_model)
    if explicit:
        return explicit

    override = normalize_model_name(config.get("_model_override"))
    if override:
        return override

    fallback = normalize_model_name(config.get("model")) or str(DEFAULT_CONFIG["model"])
    fast_model = normalize_model_name(config.get("fast_model"))
    deep_model = normalize_model_name(config.get("deep_model"))
    normalized_role = " ".join(str(role or "general").lower().split()) or "general"

    if normalized_role in FAST_MODEL_ROLES and fast_model:
        return fast_model
    if normalized_role in DEEP_MODEL_ROLES and deep_model:
        return deep_model
    return fallback


def reply_stream_model_config_key(stream_name: str) -> str:
    normalized = " ".join(str(stream_name or "").lower().split())
    if normalized not in {"listener", "factual", "skeptic", "synthesis"}:
        normalized = "listener"
    return f"reply_stream_{normalized}_model"


def resolve_reply_stream_model(
    config: Dict[str, object],
    stream_name: str,
    explicit_model: Optional[str] = None,
) -> str:
    explicit = normalize_model_name(explicit_model)
    if explicit:
        return explicit
    configured = normalize_model_name(config.get(reply_stream_model_config_key(stream_name)))
    if configured:
        return configured
    if stream_name in {"skeptic", "synthesis"}:
        return resolve_model(config, "reflection")
    return resolve_model(config, "reply_stream")


def resolve_integrated_reply_synthesis(
    config: Dict[str, object],
    *,
    reply_council: Optional[Dict[str, object]] = None,
    turn_contract: Optional[Dict[str, object]] = None,
    explicit_model: Optional[str] = None,
) -> Dict[str, object]:
    """Choose one outward generator that can preserve admitted cognition.

    Lane packets are only causally useful if the final generator can bind them
    into one answer. A configured fast synthesizer remains the ordinary direct
    path. Once an evaluated council admits multiple faculties, the deep model
    becomes the final integrator even when it was not also asked for a separate
    packet. Reflective/analytical/strategic or epistemic turns that explicitly
    admitted ``deep`` use the same integrator rule. This changes one attention
    allocation inside Eve; it does not create another voice.
    """
    explicit = normalize_model_name(explicit_model)
    baseline = resolve_reply_stream_model(
        config,
        "synthesis",
        explicit_model=explicit or None,
    )
    council = reply_council if isinstance(reply_council, dict) else {}
    contract = turn_contract if isinstance(turn_contract, dict) else {}
    budget = normalize_text_value(
        contract.get("route_contract_budget")
        or council.get("route_contract_budget"),
        fallback="",
        limit=40,
    ).lower()
    active_lanes = {
        str(value)
        for value in council.get("active_lanes") or []
        if str(value)
    }
    result = {
        "model": baseline,
        "baseline_model": baseline,
        "budget": budget,
        "active_lanes": sorted(active_lanes),
        "reason": "explicit_override" if explicit else "configured_or_default_synthesis",
        "integrated_selected": False,
        "budget_selected": False,
    }
    if explicit or not parse_boolish(
        config.get("reply_stream_integrated_synthesis_enabled", True)
    ):
        return result
    deep_admitted = "deep" in active_lanes
    deep_budget = budget in {"analytical", "strategic", "reflective", "frontier"}
    epistemic_deep = bool(
        contract.get("epistemic_boundary")
        or contract.get("learned_epistemic_deep_revision")
    )
    deep_lane_record = next(
        (
            item
            for item in council.get("lanes") or []
            if isinstance(item, dict) and str(item.get("lane") or "") == "deep"
        ),
        {},
    )
    deep_available = not bool(deep_lane_record.get("quarantined"))
    multi_lane_council = bool(
        council.get("enabled")
        and council.get("evaluated")
        and not council.get("allow_tools")
        and (
            (
                "fast" in active_lanes
                and bool(active_lanes - {"fast"})
            )
            or (
                council.get("evaluator_intervention")
                and len(active_lanes) >= 2
            )
        )
    )
    if deep_available and (
        multi_lane_council or (deep_admitted and (deep_budget or epistemic_deep))
    ):
        selected = resolve_reply_council_lane_model(config, "deep")
        result.update(
            {
                "model": selected,
                "reason": (
                    "deep_selected_for_multi_lane_integration"
                    if multi_lane_council
                    else (
                        "deep_admitted_for_epistemic_boundary"
                        if epistemic_deep and not deep_budget
                        else "deep_admitted_for_cognition_budget"
                    )
                ),
                "integrated_selected": selected != baseline,
                "budget_selected": selected != baseline,
            }
        )
    return result


def reply_stream_model_assignments(
    config: Dict[str, object],
    stream_specs: List[tuple],
    model_override: Optional[str] = None,
) -> Dict[str, str]:
    assignments: Dict[str, str] = {}
    for spec in stream_specs:
        stream_name = str(spec[0])
        explicit_model = spec[2] if len(spec) > 2 else model_override
        assignments[stream_name] = resolve_reply_stream_model(config, stream_name, explicit_model=explicit_model)
    return assignments


def reply_stream_final_model(
    stream_result: Optional[Dict[str, object]],
    fallback_model: object,
) -> str:
    """Attribute a streamed answer to its actual final generator."""
    return normalize_model_name(
        (stream_result or {}).get("synthesis_model")
    ) or normalize_model_name(fallback_model)


