def normalize_reply_council_lane_names(values: object) -> List[str]:
    if values is None:
        return []
    raw_values: List[object]
    if isinstance(values, str):
        raw_values = re.split(r"[,\s]+", values)
    elif isinstance(values, Iterable):
        raw_values = []
        for value in values:
            if isinstance(value, str):
                raw_values.extend(re.split(r"[,\s]+", value))
            else:
                raw_values.append(value)
    else:
        raw_values = [values]
    normalized = unique_compact(
        [str(value or "").strip().lower() for value in raw_values],
        limit=len(REPLY_COUNCIL_LANE_ORDER),
    )
    invalid = [
        value for value in normalized if value not in REPLY_COUNCIL_LANE_ORDER
    ]
    if invalid:
        raise ValueError(
            "unknown reply council lane(s): "
            + ", ".join(invalid)
            + "; expected "
            + ", ".join(REPLY_COUNCIL_LANE_ORDER)
        )
    return [lane for lane in REPLY_COUNCIL_LANE_ORDER if lane in normalized]

