def record_evidence(
    *,
    source: str,
    kind: str,
    claim: str,
    summary: str = "",
    confidence: float = 1.0,
    ttl_hours: int = eve_evidence.DEFAULT_TTL_HOURS,
    supports: Optional[Iterable[str]] = None,
    contradicts: Optional[Iterable[str]] = None,
    supersedes: Optional[Iterable[str]] = None,
    supersede_matching: bool = False,
    actionability: str = "watch",
    metadata: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    ensure_store()
    metadata_payload = dict(metadata or {})
    superseded_ids = [str(item) for item in (supersedes or []) if str(item)]
    if supersede_matching:
        auto_candidates = find_evidence_supersession_candidates(
            claim=claim,
            kind=kind,
            source=source,
            prefer_runtime=False,
            limit=4,
        )
        auto_superseded_ids = [
            str(item.get("id") or "")
            for item in auto_candidates
            if str(item.get("id") or "") and str(item.get("id") or "") not in superseded_ids
        ]
        superseded_ids.extend(auto_superseded_ids)
        metadata_payload["auto_superseded_ids"] = auto_superseded_ids
        metadata_payload["auto_supersession_candidates"] = auto_candidates
    record = eve_evidence.create_evidence_record(
        source=source,
        kind=kind,
        claim=claim,
        summary=summary,
        confidence=confidence,
        ttl_hours=ttl_hours,
        supports=supports,
        contradicts=contradicts,
        supersedes=superseded_ids,
        actionability=actionability,
        metadata=metadata_payload,
    )
    if superseded_ids:
        with store_lock(EVIDENCE_LEDGER_PATH):
            records = read_jsonl_records(EVIDENCE_LEDGER_PATH)
            records = eve_evidence.supersede_records(
                records,
                superseded_ids=superseded_ids,
                superseding_id=str(record.get("id") or ""),
            )
            records.append(record)
            write_jsonl_records(EVIDENCE_LEDGER_PATH, records)
    else:
        eve_evidence.append_evidence_record(EVIDENCE_LEDGER_PATH, record)
    mirror_store_file_to_runtime(EVIDENCE_LEDGER_PATH)
    return record


def read_evidence_ledger(
    limit: Optional[int] = None,
    *,
    source: Optional[str] = None,
    kind: Optional[str] = None,
    active_only: bool = False,
    min_freshness: int = 1,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(EVIDENCE_LEDGER_PATH, prefer_runtime=prefer_runtime)
    return eve_evidence.read_evidence_records(
        path,
        limit=limit,
        source=source,
        kind=kind,
        active_only=active_only,
        min_freshness=min_freshness,
    )


EVIDENCE_TOPIC_STOPWORDS = {
    "a",
    "about",
    "after",
    "again",
    "all",
    "an",
    "and",
    "are",
    "as",
    "at",
    "be",
    "because",
    "been",
    "but",
    "by",
    "can",
    "current",
    "currently",
    "did",
    "do",
    "does",
    "for",
    "from",
    "has",
    "have",
    "i",
    "in",
    "is",
    "it",
    "latest",
    "now",
    "of",
    "on",
    "or",
    "status",
    "that",
    "the",
    "this",
    "to",
    "was",
    "were",
    "with",
}


def evidence_topic_tokens(text: object) -> Set[str]:
    words = re.findall(r"[a-z0-9_]+", str(text or "").lower())
    return {word for word in words if len(word) >= 3 and word not in EVIDENCE_TOPIC_STOPWORDS}


def evidence_record_topic_text(record: Dict[str, object]) -> str:
    metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
    subject = normalize_text_value(metadata.get("subject"), fallback="", limit=240)
    claim = normalize_text_value(record.get("claim"), fallback="", limit=500)
    summary = normalize_text_value(record.get("summary"), fallback="", limit=500)
    return " ".join(part for part in [subject, claim, summary] if part)


def find_evidence_supersession_candidates(
    *,
    claim: object,
    kind: Optional[str] = None,
    source: Optional[str] = None,
    prefer_runtime: bool = False,
    limit: int = 8,
    min_overlap: float = 0.34,
) -> List[Dict[str, object]]:
    claim_tokens = evidence_topic_tokens(claim)
    if not claim_tokens:
        return []
    records = read_evidence_ledger(
        limit=250,
        kind=kind,
        active_only=True,
        min_freshness=1,
        prefer_runtime=prefer_runtime,
    )
    candidates: List[Dict[str, object]] = []
    for record in records:
        if source and str(record.get("source") or "") != source:
            continue
        record_tokens = evidence_topic_tokens(evidence_record_topic_text(record))
        if not record_tokens:
            continue
        overlap_tokens = sorted(claim_tokens.intersection(record_tokens))
        overlap = len(overlap_tokens) / max(1, min(len(claim_tokens), len(record_tokens)))
        if overlap < min_overlap:
            continue
        candidates.append(
            {
                "id": record.get("id"),
                "kind": record.get("kind"),
                "source": record.get("source"),
                "claim": record.get("claim"),
                "summary": record.get("summary"),
                "observed_at": record.get("observed_at"),
                "freshness": eve_evidence.evidence_freshness_score(record),
                "topic_overlap": round(overlap, 3),
                "overlap_tokens": overlap_tokens[:10],
            }
        )
    candidates.sort(
        key=lambda item: (
            float(item.get("topic_overlap") or 0),
            str(item.get("observed_at") or ""),
        ),
        reverse=True,
    )
    return candidates[: max(1, int(limit or 8))]


