USER_CORRECTION_CUES = {
    "missed_question": [
        "not answering",
        "didn't answer",
        "didnt answer",
        "answer my question",
        "answer the previous question",
        "not what i asked",
        "what i asked",
    ],
    "stale_or_wrong_context": [
        "wrong conversation",
        "stale",
        "old evidence",
        "keeps repeating",
        "looping",
        "why did she say",
        "why is she",
    ],
    "overclaim_or_uncertain": [
        "are you sure",
        "is that true",
        "you claimed",
        "you said you did",
        "did you actually",
    ],
    "capability_gap": [
        "why didn't she do",
        "why didnt she do",
        "can eve not",
        "does she have the ability",
        "she needs the ability",
    ],
}


def classify_user_correction(text: object) -> Optional[Dict[str, str]]:
    lowered = " ".join(str(text or "").lower().replace("’", "'").split())
    if not lowered:
        return None
    if re.match(
        r"^(?:no[,.! ]+)?(?:i mean|what i mean is|not just|not merely|the point is|that's not the point|that is not the point)\b",
        lowered,
    ):
        return {
            "issue_type": "goal_or_scope_correction",
            "severity": "high",
            "summary": normalize_text_value(text, fallback="", limit=240),
        }
    for issue_type, cues in USER_CORRECTION_CUES.items():
        if any(cue in lowered for cue in cues):
            return {
                "issue_type": issue_type,
                "severity": "high" if issue_type in {"missed_question", "stale_or_wrong_context"} else "medium",
                "summary": normalize_text_value(text, fallback="", limit=240),
            }
    if re.search(r"\b(wrong|incorrect|broken|fix this|diagnose this)\b", lowered):
        return {
            "issue_type": "general_correction",
            "severity": "medium",
            "summary": normalize_text_value(text, fallback="", limit=240),
        }
    return None


def normalize_user_correction_record(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    data = payload or {}
    return {
        "id": normalize_text_value(data.get("id"), fallback=str(uuid.uuid4()), limit=80),
        "created_at": normalize_text_value(data.get("created_at"), fallback=utc_now(), limit=80),
        "updated_at": normalize_text_value(data.get("updated_at"), fallback=utc_now(), limit=80),
        "source": normalize_text_value(data.get("source"), fallback="manual", limit=80),
        "thread_id": normalize_text_value(data.get("thread_id"), fallback="", limit=100),
        "message_id": normalize_text_value(data.get("message_id"), fallback="", limit=100),
        "target_message_id": normalize_text_value(data.get("target_message_id"), fallback="", limit=100),
        "issue_type": normalize_text_value(data.get("issue_type"), fallback="general_correction", limit=80),
        "severity": normalize_text_value(data.get("severity"), fallback="medium", limit=40),
        "status": normalize_text_value(data.get("status"), fallback="open", limit=40),
        "summary": normalize_text_value(data.get("summary"), fallback="", limit=360),
        "raw_text": normalize_text_value(data.get("raw_text"), fallback="", limit=800),
        "evidence_ids": [str(item) for item in data.get("evidence_ids", []) if str(item)] if isinstance(data.get("evidence_ids"), list) else [],
        "episode_id": normalize_text_value(data.get("episode_id"), fallback="", limit=80),
        "metadata": data.get("metadata") if isinstance(data.get("metadata"), dict) else {},
    }


def read_user_corrections(
    *,
    limit: Optional[int] = None,
    status: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(USER_CORRECTIONS_PATH, prefer_runtime=prefer_runtime)
    records = [normalize_user_correction_record(item) for item in read_jsonl_records(path)]
    if status:
        records = [item for item in records if item.get("status") == status]
    records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    return maybe_limit(records, limit)


def normalize_relationship_episode_record(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    data = payload or {}
    user_care = data.get("what_user_cared_about")
    if user_care in {None, ""}:
        # Read older personalized schemas without preserving a person's name in
        # the public contract. New writes always use the generic field.
        for key, value in data.items():
            normalized_key = str(key or "").strip().lower()
            if normalized_key.startswith("what_") and normalized_key.endswith("_cared_about"):
                user_care = value
                break
    return {
        "id": normalize_text_value(data.get("id"), fallback=str(uuid.uuid4()), limit=80),
        "created_at": normalize_text_value(data.get("created_at"), fallback=utc_now(), limit=80),
        "updated_at": normalize_text_value(data.get("updated_at"), fallback=utc_now(), limit=80),
        "source": normalize_text_value(data.get("source"), fallback="manual", limit=80),
        "thread_id": normalize_text_value(data.get("thread_id"), fallback="", limit=100),
        "what_happened": normalize_text_value(data.get("what_happened"), fallback="", limit=500),
        "what_user_cared_about": normalize_text_value(user_care, fallback="", limit=500),
        "what_eve_got_wrong": normalize_text_value(data.get("what_eve_got_wrong"), fallback="", limit=500),
        "what_changed_afterward": normalize_text_value(data.get("what_changed_afterward"), fallback="", limit=500),
        "evidence_ids": [str(item) for item in data.get("evidence_ids", []) if str(item)] if isinstance(data.get("evidence_ids"), list) else [],
        "correction_ids": [str(item) for item in data.get("correction_ids", []) if str(item)] if isinstance(data.get("correction_ids"), list) else [],
        "metadata": data.get("metadata") if isinstance(data.get("metadata"), dict) else {},
    }


def record_relationship_episode(
    *,
    what_happened: object,
    what_user_cared_about: object = "",
    what_eve_got_wrong: object = "",
    what_changed_afterward: object = "",
    source: str = "manual",
    thread_id: object = "",
    evidence_ids: Optional[List[str]] = None,
    correction_ids: Optional[List[str]] = None,
    metadata: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    record = normalize_relationship_episode_record(
        {
            "id": str(uuid.uuid4()),
            "created_at": utc_now(),
            "updated_at": utc_now(),
            "source": source,
            "thread_id": thread_id,
            "what_happened": what_happened,
            "what_user_cared_about": what_user_cared_about,
            "what_eve_got_wrong": what_eve_got_wrong,
            "what_changed_afterward": what_changed_afterward,
            "evidence_ids": evidence_ids or [],
            "correction_ids": correction_ids or [],
            "metadata": metadata or {},
        }
    )
    append_jsonl_record(RELATIONSHIP_EPISODES_PATH, record)
    mirror_store_file_to_runtime(RELATIONSHIP_EPISODES_PATH)
    record_experience_event(
        event_type="relationship_episode",
        source=source,
        summary=record["what_happened"] or "Relationship episode recorded.",
        actor="eve",
        subject="relationship_continuity",
        result="recorded",
        learning=record["what_changed_afterward"],
        evidence_ids=list(record.get("evidence_ids") or []),
        metadata={
            "relationship_episode_id": record["id"],
            "correction_ids": record.get("correction_ids") or [],
        },
    )
    return record


def message_is_substantive_user_turn(message: Dict[str, object]) -> bool:
    if conversation_message_is_synthetic(message):
        return False
    if str(message.get("sender") or "").strip().lower() != "user":
        return False
    if message_is_background_context(message):
        return False
    body = normalize_text_value(message.get("body"), fallback="", limit=400)
    if not body:
        return False
    lowered = body.lower()
    if greeting_like_text(lowered) or focus_indicates_operational_recap(body):
        return False
    return len(body.split()) >= 6 or "?" in body


def extract_significant_episodes(
    config: Dict[str, object],
    *,
    limit: Optional[int] = None,
    source: str = "daemon_episode_extraction",
) -> List[Dict[str, object]]:
    """Positive/significant episode formation: record real relational exchanges,
    not only corrections. Eve's autobiography was deficit-only (one episode ever,
    from a correction) — a self that only remembers its mistakes. This captures
    substantive exchanges with the user (deduped by message id, capped, recent window,
    operational/greeting turns excluded) so memory carries a life, not a defect log."""
    if not parse_boolish(config.get("episode_extraction_enabled", True)):
        return []
    try:
        max_per_run = int(limit if limit is not None else config.get("episode_extraction_max_per_run") or 2)
    except (TypeError, ValueError):
        max_per_run = 2
    max_per_run = max(1, min(5, max_per_run))
    # Wide scan: a burst of autonomous Eve messages must not push a handful of real
    # user turns out of view.
    messages = read_lived_messages(limit=200)
    if not messages:
        return []
    recorded_ids: set[str] = set()
    for episode in read_relationship_episodes(limit=200):
        meta = episode.get("metadata") if isinstance(episode.get("metadata"), dict) else {}
        sid = str(meta.get("source_message_id") or "")
        if sid:
            recorded_ids.add(sid)
    cutoff = utc_now_datetime() - timedelta(hours=48)
    created: List[Dict[str, object]] = []
    for idx in range(len(messages) - 1, -1, -1):
        if len(created) >= max_per_run:
            break
        msg = messages[idx]
        if not message_is_substantive_user_turn(msg):
            continue
        mid = str(msg.get("id") or "")
        if not mid or mid in recorded_ids:
            continue
        when = parse_iso_datetime(msg.get("timestamp") or msg.get("created_at"))
        if when is None or when < cutoff:
            continue
        thread_id = str(msg.get("thread_id") or "")
        # Pair with Eve's reply: prefer a same-thread reply, else the next outbound
        # message to the user (daemon replies are flagged "background", which used
        # to block all pairing). A substantive user turn still forms a one-sided
        # episode ("the user asked X") when no reply is found — a real moment either way.
        reply = None
        for later in messages[idx + 1:]:
            if str(later.get("sender") or "").strip().lower() != "eve":
                continue
            same_thread = str(later.get("thread_id") or "") == thread_id and thread_id
            if same_thread or message_is_outbound_to_user(later):
                reply = later
                break
        user_gist = normalize_text_value(msg.get("body"), fallback="", limit=200)
        if reply is not None:
            reply_gist = normalize_text_value(reply.get("body"), fallback="", limit=200)
            what_happened = f"The user said: {user_gist} — I responded: {reply_gist}"
        else:
            what_happened = f"The user said: {user_gist}"
        reply_id = str(reply.get("id") or "") if reply is not None else ""
        episode = record_relationship_episode(
            what_happened=what_happened,
            what_user_cared_about=user_gist,
            source=source,
            thread_id=thread_id,
            evidence_ids=[item for item in [mid, reply_id] if item],
            metadata={
                "source_message_id": mid,
                "reply_message_id": reply_id,
                "significance": "substantive_exchange" if reply is not None else "user_turn_unanswered",
            },
        )
        created.append(episode)
        recorded_ids.add(mid)
    return created


def read_relationship_episodes(
    *,
    limit: Optional[int] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(RELATIONSHIP_EPISODES_PATH, prefer_runtime=prefer_runtime)
    records = [normalize_relationship_episode_record(item) for item in read_jsonl_records(path)]
    records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    return maybe_limit(records, limit)


def presence_cycle_episode_already_recorded(presence_cycle_id: str, *, prefer_runtime: bool = False) -> bool:
    if not presence_cycle_id:
        return True
    for episode in read_relationship_episodes(limit=500, prefer_runtime=prefer_runtime):
        metadata = episode.get("metadata") if isinstance(episode.get("metadata"), dict) else {}
        if str(metadata.get("source_presence_cycle_id") or "") == presence_cycle_id:
            return True
    return False


def presence_cycle_is_episode_worthy(record: Dict[str, object]) -> bool:
    if normalize_text_value(record.get("status"), fallback="", limit=80) != "verified":
        return False
    if action_result_explicit_verification(record) is not True:
        return False
    if record.get("action_matched_contract") is not True:
        return False
    if not isinstance(record.get("action_contract_before"), dict):
        return False
    return bool(normalize_text_value(record.get("capability_attempted"), fallback="", limit=80))


def presence_cycle_episode_text(record: Dict[str, object]) -> Dict[str, str]:
    capability = normalize_text_value(record.get("capability_attempted"), fallback="bounded action", limit=100)
    cycle_id = normalize_text_value(record.get("id"), fallback="", limit=80)
    summary = normalize_text_value(record.get("summary"), fallback="", limit=220)
    result = normalize_text_value(record.get("result"), fallback=summary, limit=260)
    contract = record.get("action_contract_before") if isinstance(record.get("action_contract_before"), dict) else {}
    expected = normalize_text_value(contract.get("bounded_action"), fallback=capability, limit=100)
    organ = normalize_text_value(contract.get("organ_id"), fallback="admitted organ", limit=100)
    verification = normalize_text_value(contract.get("expected_verification_signal"), fallback="verified consequence", limit=180)
    return {
        "what_happened": (
            f"Eve completed presence cycle {cycle_id or 'unknown'} by selecting `{expected}`, "
            f"acting through `{capability}`, and verifying the consequence."
        ),
        "what_user_cared_about": (
            "The user wants Eve's claimed presence to stay grounded in current focus, pressure, organs, "
            "a bounded action, and evidence rather than decorative self-description."
        ),
        "what_eve_got_wrong": "",
        "what_changed_afterward": (
            f"The lived loop now has matched action contract evidence from {organ}: {verification}. "
            f"Result: {result}"
        ),
    }


def extract_presence_cycle_episodes(
    config: Dict[str, object],
    *,
    limit: Optional[int] = None,
    source: str = "quiet_consolidation_presence_episode_extraction",
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    """Create positive autobiographical episodes from verified lived loops.

    Relationship episodes were historically biased toward corrections. Presence
    cycles are Eve's lived observe-act-verify loop, so a verified cycle with a
    matched action contract should become an episode and later a semantic marker.
    """
    if not parse_boolish(config.get("episode_extraction_enabled", True)):
        return []
    try:
        max_per_run = int(limit if limit is not None else config.get("episode_extraction_max_per_run") or 2)
    except (TypeError, ValueError):
        max_per_run = 2
    max_per_run = max(1, min(5, max_per_run))
    created: List[Dict[str, object]] = []
    for cycle in read_presence_cycles(limit=50, prefer_runtime=prefer_runtime):
        if len(created) >= max_per_run:
            break
        if not presence_cycle_is_episode_worthy(cycle):
            continue
        cycle_id = normalize_text_value(cycle.get("id"), fallback="", limit=80)
        if presence_cycle_episode_already_recorded(cycle_id, prefer_runtime=prefer_runtime):
            continue
        text = presence_cycle_episode_text(cycle)
        developmental = cycle.get("developmental_cycle") if isinstance(cycle.get("developmental_cycle"), dict) else {}
        pulse = cycle.get("presence_pulse") if isinstance(cycle.get("presence_pulse"), dict) else {}
        evidence_ids = unique_compact(
            [
                cycle_id,
                normalize_text_value(developmental.get("id"), fallback="", limit=80),
                normalize_text_value(pulse.get("generated_at"), fallback="", limit=80),
            ],
            limit=5,
        )
        episode = record_relationship_episode(
            source=source,
            thread_id="presence",
            evidence_ids=evidence_ids,
            metadata={
                "source_presence_cycle_id": cycle_id,
                "significance": "verified_presence_cycle",
                "capability_attempted": normalize_text_value(cycle.get("capability_attempted"), fallback="", limit=80),
                "verification_ok": action_result_explicit_verification(cycle),
                "action_matched_contract": bool(cycle.get("action_matched_contract")),
                "presence_status_after": (
                    (cycle.get("presence_after") or {}).get("status")
                    if isinstance(cycle.get("presence_after"), dict)
                    else ""
                ),
            },
            **text,
        )
        created.append(episode)
    return created


def distill_presence_cycle_episodes_to_human_context(
    episodes: List[Dict[str, object]],
    *,
    source: str = "presence_cycle_episode_distillation",
    prefer_runtime: bool = False,
) -> Dict[str, object]:
    if not episodes:
        return {}
    context = load_human_context(prefer_runtime=prefer_runtime)
    memory_v2 = context.get("memory_v2") if isinstance(context.get("memory_v2"), dict) else {}
    semantic = list(memory_v2.get("semantic_understanding") or [])
    existing_episodic_markers = list(memory_v2.get("episodic_markers") or [])
    procedural = list(memory_v2.get("procedural_preferences") or [])
    trust = list(memory_v2.get("trust_ledger") or [])
    new_episodic_markers: List[str] = []
    for episode in episodes[:5]:
        metadata = episode.get("metadata") if isinstance(episode.get("metadata"), dict) else {}
        cycle_id = normalize_text_value(metadata.get("source_presence_cycle_id"), fallback="", limit=80)
        capability = normalize_text_value(metadata.get("capability_attempted"), fallback="bounded action", limit=80)
        new_episodic_markers.append(
            normalize_text_value(
                f"Presence cycle {cycle_id or 'unknown'} verified `{capability}` with a matched action contract.",
                fallback="",
                limit=180,
            )
        )
    new_semantic = (
        "Eve's presence is stronger when current focus becomes a bounded action contract, the action runs, and verification evidence is recorded."
    )
    new_procedural = (
        "For presence loops, name the expected action and verify whether the actual action matched before claiming progress."
    )
    new_trust = "Verified presence cycles are operational evidence for integration, not proof of subjective experience."
    memory_v2["semantic_understanding"] = unique_compact([new_semantic, *semantic], limit=8)
    memory_v2["episodic_markers"] = unique_compact([*new_episodic_markers, *existing_episodic_markers], limit=8)
    memory_v2["procedural_preferences"] = unique_compact([new_procedural, *procedural], limit=8)
    memory_v2["trust_ledger"] = unique_compact([new_trust, *trust], limit=8)
    context["memory_v2"] = memory_v2
    context["updated_at"] = utc_now()
    context["source"] = source
    save_human_context(context, snapshot_source=source)
    return normalize_human_context(context)


def record_user_correction(
    text: object,
    *,
    source: str = "manual",
    thread_id: object = "",
    message_id: object = "",
    target_message_id: object = "",
    metadata: Optional[Dict[str, object]] = None,
    record_outcome: bool = True,
) -> Optional[Dict[str, object]]:
    classification = classify_user_correction(text)
    if not classification:
        return None
    if message_id:
        for existing in read_user_corrections(limit=20, prefer_runtime=False):
            if str(existing.get("message_id") or "") == str(message_id) and str(existing.get("source") or "") == source:
                return existing
    correction = normalize_user_correction_record(
        {
            "id": str(uuid.uuid4()),
            "created_at": utc_now(),
            "updated_at": utc_now(),
            "source": source,
            "thread_id": thread_id,
            "message_id": message_id,
            "target_message_id": target_message_id,
            "issue_type": classification["issue_type"],
            "severity": classification["severity"],
            "status": "open",
            "summary": classification["summary"],
            "raw_text": text,
            "metadata": metadata or {},
        }
    )
    append_jsonl_record(USER_CORRECTIONS_PATH, correction)
    episode = record_relationship_episode(
        what_happened=f"The user corrected Eve: {correction['summary']}",
        what_user_cared_about="The user wanted Eve to preserve the live conversational objective and fix the underlying cause.",
        what_eve_got_wrong=correction["issue_type"],
        what_changed_afterward="Treat this as lived evidence for routing, grounding, and relationship continuity.",
        source=source,
        thread_id=thread_id,
        correction_ids=[correction["id"]],
        metadata={"user_correction_id": correction["id"]},
    )
    correction["episode_id"] = str(episode.get("id") or "")
    with store_lock(USER_CORRECTIONS_PATH):
        records = [normalize_user_correction_record(item) for item in read_jsonl_records(USER_CORRECTIONS_PATH)]
        for index, item in enumerate(records):
            if item.get("id") == correction["id"]:
                records[index] = correction
                break
        write_jsonl_records(USER_CORRECTIONS_PATH, records)
    mirror_store_file_to_runtime(USER_CORRECTIONS_PATH)
    if record_outcome:
        try:
            create_outcome(
                target_kind="reply",
                target_id=str(target_message_id or message_id or correction["id"]),
                direction="negative",
                outcome="user_correction",
                summary=correction["summary"],
                evidence=normalize_text_value(text, fallback="", limit=240),
                source=source,
                thread_id=str(thread_id or ""),
                allow_duplicate=True,
            )
        except Exception:
            pass
    append_entry(
        "user_correction_logged",
        f"{correction['issue_type']}: {correction['summary']}",
        metadata={
            "user_correction_id": correction["id"],
            "relationship_episode_id": correction["episode_id"],
            "severity": correction["severity"],
            "source": source,
        },
    )
    return correction


def record_commitment(
    *,
    source: str,
    text: str,
    kind: str = "commitment",
    status: str = "proposed",
    action: str = "",
    supported_action: str = "",
    result_summary: str = "",
    verification: str = "",
    evidence_ids: Optional[List[str]] = None,
    experience_event_ids: Optional[List[str]] = None,
    action_execution_ids: Optional[List[str]] = None,
    capability_gap_id: str = "",
    proposal_id: str = "",
    thread_id: str = "",
    inbound_message_id: str = "",
    reply_message_id: str = "",
    metadata: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    ensure_store()
    record = eve_commitments.create_commitment_record(
        source=source,
        text=text,
        kind=kind,
        status=status,
        action=action,
        supported_action=supported_action,
        result_summary=result_summary,
        verification=verification,
        evidence_ids=evidence_ids,
        experience_event_ids=experience_event_ids,
        action_execution_ids=action_execution_ids,
        capability_gap_id=capability_gap_id,
        proposal_id=proposal_id,
        thread_id=thread_id,
        inbound_message_id=inbound_message_id,
        reply_message_id=reply_message_id,
        metadata=metadata,
    )
    eve_commitments.append_commitment_record(COMMITMENT_LEDGER_PATH, record)
    mirror_store_file_to_runtime(COMMITMENT_LEDGER_PATH)
    return record


def update_commitment_record(commitment_id: str, **changes: object) -> Dict[str, object]:
    """Update one durable commitment without appending a contradictory duplicate."""
    clean_id = normalize_text_value(commitment_id, fallback="", limit=100)
    if not clean_id:
        raise SystemExit("Commitment id is required.")
    with store_lock(COMMITMENT_LEDGER_PATH):
        records = read_jsonl_records(COMMITMENT_LEDGER_PATH)
        index = find_record_index(records, clean_id)
        record = dict(records[index])
        if isinstance(changes.get("metadata"), dict):
            existing_metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
            changes = {
                **changes,
                "metadata": {**existing_metadata, **changes["metadata"]},
            }
        record.update(changes)
        record["id"] = clean_id
        record["updated_at"] = utc_now()
        normalized = eve_commitments.normalize_commitment_record(record)
        records[index] = normalized
        write_jsonl_records(COMMITMENT_LEDGER_PATH, records)
    mirror_store_file_to_runtime(COMMITMENT_LEDGER_PATH)
    return normalized


def read_commitments(
    limit: Optional[int] = None,
    *,
    status: Optional[str] = None,
    source: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(COMMITMENT_LEDGER_PATH, prefer_runtime=prefer_runtime)
    return eve_commitments.read_commitment_records(path, limit=limit, status=status, source=source)


def read_action_executions(
    limit: Optional[int] = None,
    since_days: Optional[int] = None,
    *,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(ACTION_EXECUTIONS_PATH, prefer_runtime=prefer_runtime)
    if limit is not None and since_days is None:
        records = read_jsonl_tail_records(path, limit)
    else:
        records = filter_records_by_days(read_jsonl_records(path), "created_at", since_days)
    records.sort(key=lambda item: item.get("created_at") or item.get("updated_at") or "", reverse=True)
    if limit is not None:
        records = records[:limit]
    return records


def read_developmental_cycles(
    limit: Optional[int] = None,
    since_days: Optional[int] = None,
    *,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(DEVELOPMENTAL_CYCLES_PATH, prefer_runtime=prefer_runtime)
    records = filter_records_by_days(read_jsonl_records(path), "timestamp", since_days)
    records.sort(
        key=lambda item: parse_iso_datetime(item.get("timestamp") or item.get("created_at"))
        or datetime.min.replace(tzinfo=timezone.utc),
        reverse=True,
    )
    if limit is not None:
        records = records[:limit]
    return records


def sync_developmental_cycle_state_from_log(
    state: Dict[str, object],
    *,
    prefer_runtime: bool = False,
) -> bool:
    cycles = read_developmental_cycles(limit=1, prefer_runtime=prefer_runtime)
    if not cycles:
        return False
    latest = cycles[0]
    latest_at = normalize_text_value(latest.get("timestamp"), fallback="", limit=80)
    latest_dt = parse_iso_datetime(latest_at)
    state_dt = parse_iso_datetime(state.get("last_developmental_cycle_at"))
    if latest_dt is None or (state_dt is not None and latest_dt <= state_dt):
        return False
    action = normalize_text_value(latest.get("capability_attempted"), fallback="", limit=80)
    result = normalize_text_value(latest.get("result"), fallback="", limit=320)
    failure_mode = normalize_text_value(latest.get("failure_mode_if_any"), fallback="", limit=220)
    action_result = latest.get("action_result") if isinstance(latest.get("action_result"), dict) else {}
    verified = not failure_mode and bool(
        action_result.get("execution_verification_ok")
        or action_result.get("ok")
        or not action_result
    )
    state["last_developmental_cycle_at"] = latest_at
    state["last_developmental_cycle_id"] = normalize_text_value(latest.get("id"), fallback="", limit=80)
    state["last_developmental_cycle_action"] = action
    state["last_developmental_cycle_result"] = "verified" if verified else "needs_repair"
    state["developmental_cycle_summary"] = f"{action}: {result}" if action or result else result
    return True


def append_developmental_cycle_record(record: Dict[str, object]) -> Dict[str, object]:
    saved = append_jsonl_record(DEVELOPMENTAL_CYCLES_PATH, record)
    mirror_store_file_to_runtime(DEVELOPMENTAL_CYCLES_PATH)
    return saved


def safe_jsonl_count(path: Path) -> int:
    try:
        return count_jsonl_records(path)
    except Exception:
        return 0


def compact_model_list(items: object, limit: int = 4) -> List[str]:
    return normalize_text_list(items, limit=limit)


def build_developmental_failure_modes(config: Dict[str, object], state: Dict[str, object]) -> List[str]:
    modes: List[str] = []
    try:
        daemon_diag = daemon_health_diagnostics(config)
        if daemon_diag.get("degraded"):
            modes.append(
                normalize_text_value(
                    daemon_diag.get("part"),
                    fallback="daemon health is degraded",
                    limit=180,
                )
            )
    except Exception:
        pass

    try:
        for cluster in read_failure_clusters(limit=3, status="open", since_days=30):
            modes.append(
                f"open failure cluster: {normalize_text_value(cluster.get('title'), fallback='unknown', limit=120)}"
            )
    except Exception:
        pass

    try:
        for action in read_action_executions(limit=5, since_days=7, prefer_runtime=not running_from_runtime_bundle()):
            if action_execution_verified(action):
                continue
            modes.append(
                "unverified action: "
                + normalize_text_value(action.get("action"), fallback="unknown action", limit=120)
            )
    except Exception:
        pass

    if normalize_text_value(state.get("success_pattern_repair_summary"), fallback="", limit=120):
        modes.append("success-pattern repair thread still needs upstream attention")

    deduped: List[str] = []
    seen = set()
    for mode in modes:
        if mode and mode not in seen:
            seen.add(mode)
            deduped.append(mode)
    return deduped[:6]


