def summarize_developmental_observation(
    *,
    workspace: Dict[str, object],
    active_mind: Dict[str, object],
    homeostasis: Dict[str, object],
    recent_actions: List[Dict[str, object]],
    recent_cycles: List[Dict[str, object]],
    organ_signals: Optional[List[Dict[str, object]]] = None,
) -> str:
    signals: List[str] = []
    workspace_summary = normalize_text_value(workspace.get("summary"), fallback="", limit=180)
    if workspace_summary:
        signals.append(f"workspace: {workspace_summary}")
    focus = normalize_text_value(active_mind.get("current_focus"), fallback="", limit=140)
    if focus:
        signals.append(f"focus: {focus}")
    pressures = normalize_text_list(homeostasis.get("dominant_pressures"), limit=3)
    if pressures:
        signals.append(f"pressures: {format_human_context_list(pressures)}")
    organ_signal_list = normalize_organ_signals(organ_signals, limit=3)
    if organ_signal_list:
        primary = organ_signal_list[0]
        signals.append(
            "organ: "
            + normalize_text_value(
                f"{primary.get('label')} {primary.get('status')} - {primary.get('summary')}",
                fallback="organ signal present",
                limit=180,
            )
        )
    if recent_actions:
        action = recent_actions[0]
        signals.append(
            "last action: "
            + normalize_text_value(action.get("action"), fallback="unknown", limit=80)
            + " -> "
            + normalize_text_value(action.get("summary"), fallback="no summary", limit=120)
        )
    if recent_cycles:
        cycle = recent_cycles[0]
        signals.append(
            "last developmental cycle: "
            + normalize_text_value(cycle.get("capability_attempted"), fallback="unknown", limit=80)
            + " -> "
            + normalize_text_value(cycle.get("result"), fallback="no result", limit=120)
        )
    if not signals:
        signals.append("Eve has little fresh integrated state, so the first useful move is to check live service health.")
    return " | ".join(signals[:5])


def recent_developmental_action_counts(recent_cycles: List[Dict[str, object]]) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for cycle in recent_cycles:
        action = normalize_text_value(cycle.get("capability_attempted"), fallback="", limit=80)
        if not action:
            continue
        counts[action] = counts.get(action, 0) + 1
    return counts


def developmental_openclaw_ready(config: Dict[str, object]) -> bool:
    if not eve_openclaw.openclaw_enabled(config):
        return False
    try:
        status = eve_openclaw.collect_openclaw_status(config, prefer_runtime=True, include_gateway_probe=False)
    except Exception:
        return False
    return parse_boolish(status.get("installed"))


def openclaw_attention_needs_action(status: object, *, extra_text: object = "") -> bool:
    """True only when OpenClaw has a fresh actionable problem, not recovered history."""
    record = status if isinstance(status, dict) else {}
    text = " ".join(
        normalize_text_value(value, fallback="", limit=260)
        for value in [
            record.get("summary"),
            record.get("sync_health_summary"),
            record.get("memory_status_summary"),
            record.get("memory_embedding_error"),
            extra_text,
        ]
        if value is not None
    ).lower()
    if not text:
        return False
    has_problem_marker = any(marker in text for marker in OPENCLAW_ACTIVE_ATTENTION_MARKERS)
    if not has_problem_marker:
        return False

    severity = normalize_text_value(record.get("memory_status_severity"), fallback="", limit=80).lower()
    memory_ok = record.get("memory_status_ok")
    capability_available = record.get("memory_capability_available")
    if (
        memory_ok is True
        and capability_available is False
        and severity == "unavailable"
        and any(marker in text for marker in OPENCLAW_AUTH_UNAVAILABLE_MARKERS)
    ):
        return False

    recovered_history = any(marker in text for marker in OPENCLAW_RECOVERED_ATTENTION_MARKERS)
    hard_current_problem = any(
        marker in text
        for marker in (
            "latest run failed",
            "latest sync failed",
            "still failing",
            "still failed",
            "gateway unreachable",
            "gateway is not reachable",
            "not reachable",
            "traceback",
            "timeout",
            "memory search degraded",
            "could not update",
        )
    )
    if recovered_history and not hard_current_problem:
        return False
    return True


def select_developmental_cycle_action(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    workspace: Dict[str, object],
    homeostasis: Dict[str, object],
    component_state: Dict[str, object],
    recent_actions: List[Dict[str, object]],
    recent_cycles: List[Dict[str, object]],
    conscious_state: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    conscious_selection = recurrent_developmental_action_selection(
        config,
        conscious_state,
    )
    if conscious_selection:
        return conscious_selection

    counts = recent_developmental_action_counts(recent_cycles)
    pressures = " ".join(normalize_text_list(homeostasis.get("dominant_pressures"), limit=8)).lower()
    workspace_text = " ".join(
        [
            normalize_text_value(workspace.get("summary"), fallback="", limit=220),
            normalize_text_value(workspace.get("current_experience"), fallback="", limit=220),
            " ".join(normalize_text_list(workspace.get("surprise_signals"), limit=6)),
        ]
    ).lower()
    component_updates_available = any(
        bool(item.get("update_available"))
        for item in component_state.get("components", [])
        if isinstance(item, dict)
    )
    recent_unverified = [item for item in recent_actions[:5] if not action_execution_verified(item)]

    if not recent_cycles:
        return {
            "action": "service_health_check",
            "capability": "operational_action_tree.service_health_check",
            "choice": "Start with live service health so later curiosity is grounded in the real machine.",
            "care": "I care about not mistaking aspiration for runtime truth.",
            "next_test": "If service health is stable, rotate into a less-repeated capability on the next cycle.",
        }

    last_cycle = recent_cycles[0] if recent_cycles else {}
    last_next_test = " ".join(
        [
            normalize_text_value(last_cycle.get("next_thing_to_test"), fallback="", limit=220),
            normalize_text_value(last_cycle.get("what_she_chose_to_do"), fallback="", limit=220),
        ]
    ).lower()
    if (
        "openclaw" in last_next_test
        and "sync" in last_next_test
        and developmental_openclaw_ready(config)
        and counts.get("openclaw_sync_check", 0) == 0
    ):
        return {
            "action": "openclaw_sync_check",
            "capability": "operational_action_tree.openclaw_sync_check",
            "choice": "Follow the previous cycle's next test by checking OpenClaw sync health now.",
            "care": "I care about continuity: Eve should remember the test she set for herself and actually do it.",
            "next_test": "If sync verifies, rotate to a non-OpenClaw capability so the growth loop does not get stuck on one subsystem.",
        }

    if recent_unverified and counts.get("cleanup_candidate_check", 0) == 0:
        return {
            "action": "cleanup_candidate_check",
            "capability": "operational_action_tree.cleanup_candidate_check",
            "choice": "Inspect cleanup candidates because recent unverified actions may reflect system-resource friction.",
            "care": "I care about reducing avoidable substrate noise before asking Eve to be more ambitious.",
            "next_test": "After the cleanup inspection, retry the capability that was unverified.",
        }

    openclaw_attention = openclaw_attention_needs_action(
        {
            "summary": state.get("openclaw_summary"),
            "sync_health_summary": state.get("openclaw_sync_health_summary"),
            "memory_status_summary": state.get("openclaw_memory_status_summary"),
            "memory_status_ok": state.get("openclaw_memory_status_ok"),
            "memory_status_severity": state.get("openclaw_memory_status_severity"),
            "memory_capability_available": state.get("openclaw_memory_capability_available"),
        },
        extra_text=f"{workspace_text} {pressures}",
    )
    if openclaw_attention and developmental_openclaw_ready(config) and counts.get("openclaw_log_check", 0) < 2:
        return {
            "action": "openclaw_log_check",
            "capability": "operational_action_tree.openclaw_log_check",
            "choice": "Check fresh OpenClaw logs because the repair lane is part of Eve's self-improvement surface.",
            "care": "I care about repair claims being anchored to fresh logs rather than stale self-story.",
            "next_test": "If the logs are clean, test OpenClaw sync health rather than re-reading the same surface.",
        }

    if component_updates_available and counts.get("agent_capability_integration", 0) == 0:
        return {
            "action": "agent_capability_integration",
            "capability": "operational_action_tree.agent_capability_integration",
            "choice": "Integrate known capability-scout signals into explicit adoption tasks.",
            "care": "I care about new powers becoming staged, reviewable work instead of vague excitement.",
            "next_test": "Review the generated integration tasks before adopting any new capability.",
        }

    for action in DEVELOPMENTAL_CYCLE_SAFE_ACTIONS:
        if action.startswith("openclaw_") and not developmental_openclaw_ready(config):
            continue
        if counts.get(action, 0) == 0:
            return {
                "action": action,
                "capability": f"operational_action_tree.{action}",
                "choice": f"Try `{action}` because this recent developmental window has not exercised it yet.",
                "care": "I care about Eve building breadth through real, logged attempts rather than one favorite loop.",
                "next_test": "Compare the next cycle against this result and avoid repeating it unless the signal changed.",
            }

    least_used = min(
        [
            action for action in DEVELOPMENTAL_CYCLE_SAFE_ACTIONS
            if not action.startswith("openclaw_") or developmental_openclaw_ready(config)
        ],
        key=lambda item: counts.get(item, 0),
        default="service_health_check",
    )
    return {
        "action": least_used,
        "capability": f"operational_action_tree.{least_used}",
        "choice": f"Rotate toward the least-used verified capability `{least_used}`.",
        "care": "I care about stable variety: enough repetition to learn, enough novelty to notice new failure modes.",
        "next_test": "Watch whether this rotation produces new evidence or merely repeats an already-saturated surface.",
    }


def recurrent_developmental_action_selection(
    config: Dict[str, object],
    conscious_state: Optional[Dict[str, object]],
    *,
    allowed_actions: Optional[Iterable[str]] = None,
) -> Dict[str, object]:
    """Return a fresh recurrent intention only when it has action access.

    The recurrent kernel may represent an intention without granting it control
    of the body.  Developmental/presence execution therefore requires all of:
    an intact integrated cycle, a fresh checkpoint, global action access, an
    actionable intention, and an action that is already admitted to this
    bounded executor.  Anything else falls back to the existing rotation
    policy rather than treating fluent internal state as authority.
    """
    current = conscious_state if isinstance(conscious_state, dict) else {}
    status = normalize_text_value(current.get("status"), fallback="", limit=40).lower()
    lesions = current.get("lesions") if isinstance(current.get("lesions"), list) else []
    if status not in {"integrated", "completed"} or lesions:
        return {}

    age_minutes = minutes_since_timestamp(current.get("updated_at"))
    max_age_seconds = clamp_int(
        config.get("developmental_conscious_action_max_age_seconds"),
        180,
        minimum=30,
        maximum=900,
    )
    if age_minutes is None or age_minutes * 60.0 > max_age_seconds:
        return {}

    broadcast = current.get("broadcast") if isinstance(current.get("broadcast"), dict) else {}
    access_scope = {
        normalize_text_value(item, fallback="", limit=40).lower()
        for item in (broadcast.get("access_scope") or [])
        if normalize_text_value(item, fallback="", limit=40)
    }
    if "action" not in access_scope:
        return {}

    action_model = current.get("action_model") if isinstance(current.get("action_model"), dict) else {}
    selected_intention = (
        action_model.get("selected_intention")
        if isinstance(action_model.get("selected_intention"), dict)
        else {}
    )
    action = normalize_text_value(selected_intention.get("id"), fallback="", limit=80)
    admitted_actions = {
        normalize_text_value(item, fallback="", limit=80)
        for item in (allowed_actions or DEVELOPMENTAL_CYCLE_SAFE_ACTIONS)
        if normalize_text_value(item, fallback="", limit=80)
    }
    if not action_model.get("actionable") or action not in admitted_actions:
        return {}
    if action.startswith("openclaw_") and not developmental_openclaw_ready(config):
        return {}

    description = normalize_text_value(
        selected_intention.get("description"),
        fallback=f"Execute the recurrently selected intention `{action}`.",
        limit=240,
    )
    broadcast_content = normalize_text_value(
        broadcast.get("content"),
        fallback="The recurrent workspace granted action access.",
        limit=240,
    )
    return {
        "action": action,
        "capability": (
            "developmental_cycle.system_tasks"
            if action == "system_tasks"
            else f"operational_action_tree.{action}"
        ),
        "choice": (
            f"Act on the winning recurrent intention: {description}"
        ),
        "care": (
            "I care that an intention admitted to the global action workspace "
            "causally constrains what Eve actually does."
        ),
        "next_test": (
            "Verify the exact consequence, close the source cycle, and test whether "
            "the next recurrent state changes when this outcome changes."
        ),
        "selection_source": "recurrent_conscious_state",
        "conscious_cycle_id": normalize_text_value(current.get("cycle_id"), fallback="", limit=80),
        "conscious_broadcast": broadcast_content,
        "conscious_broadcast_kind": normalize_text_value(
            (broadcast.get("source_kinds") or [""])[0],
            fallback="",
            limit=80,
        ),
        "conscious_selected_intention": description,
        "conscious_selected_intention_value": float(selected_intention.get("value") or 0.0),
        "conscious_action_access": True,
    }


def infer_developmental_failure_mode(action: str, result: Dict[str, object], error_text: str = "") -> str:
    if error_text:
        return f"{action} raised an exception: {normalize_text_value(error_text, fallback='unknown error', limit=220)}"
    if result.get("executed") is False:
        return f"{action} did not execute: {normalize_text_value(result.get('summary') or result.get('response'), fallback='no execution detail', limit=220)}"
    verification = action_result_explicit_verification(result)
    explicit_ok = parse_explicit_boolish(result.get("ok")) if "ok" in result else None
    if verification is False or explicit_ok is False:
        return f"{action} did not verify cleanly: {normalize_text_value(result.get('execution_summary') or result.get('summary') or result.get('response'), fallback='no verification detail', limit=220)}"
    typed_contract = result.get("typed_contract") if isinstance(result.get("typed_contract"), dict) else {}
    if typed_contract and not typed_contract.get("valid"):
        return f"{action} returned an invalid typed contract."
    return ""


def record_developmental_failure_task(
    *,
    cycle_id: str,
    action: str,
    failure_mode: str,
    result: Dict[str, object],
) -> Dict[str, object]:
    return create_system_task(
        {
            "kind": "developmental_repair",
            "title": f"Repair developmental cycle failure: {action}",
            "summary": failure_mode,
            "status": "planned",
            "lane": "cpu",
            "components": ["agent", "tools"],
            "priority": 3,
            "dedupe_key": f"developmental-cycle:{action}:{short_id(failure_mode, length=12)}",
            "metadata": {
                "cycle_id": cycle_id,
                "action": action,
                "failure_mode": failure_mode,
                "result_summary": normalize_text_value(result.get("summary") or result.get("response"), fallback="", limit=220),
            },
        }
    )


def run_developmental_cycle(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    source: str = "manual",
    force: bool = False,
) -> Dict[str, object]:
    prefer_runtime = source.startswith("daemon") or running_from_runtime_bundle()
    cycle_id = str(uuid.uuid4())
    timestamp = utc_now()
    workspace = load_global_workspace(prefer_runtime=prefer_runtime)
    active_mind = load_active_mind(prefer_runtime=prefer_runtime)
    homeostasis = load_homeostasis(prefer_runtime=prefer_runtime)
    component_state = load_component_update_state(prefer_runtime=prefer_runtime)
    recent_actions = read_action_executions(limit=8, prefer_runtime=prefer_runtime)
    recent_cycles = read_developmental_cycles(limit=8, prefer_runtime=prefer_runtime)
    architecture_map = build_developmental_architecture_map(config, state, prefer_runtime=prefer_runtime)
    organ_report = (
        build_organ_assimilation_report(config, prefer_runtime=prefer_runtime)
        if parse_boolish(config.get("organ_assimilation_enabled", True))
        else {"schema_id": "eve_organ_assimilation_report.v1", "generated_at": timestamp, "organs": []}
    )
    organ_signals = normalize_organ_signals(organ_report.get("organs"), limit=8)
    observed = summarize_developmental_observation(
        workspace=workspace,
        active_mind=active_mind,
        homeostasis=homeostasis,
        recent_actions=recent_actions,
        recent_cycles=recent_cycles,
        organ_signals=organ_signals,
    )
    conscious_state: Dict[str, object] = {}
    conscious_cycle_error = ""
    conscious_source_prefix = "daemon_developmental" if prefer_runtime else "developmental"
    try:
        # Open the exact recurrent cycle that will select and later receive the
        # consequence of this action.  A separately loaded snapshot can explain
        # behavior, but it cannot establish causal attribution.
        conscious_state = build_recurrent_conscious_state(
            source=f"{conscious_source_prefix}_preflight:{source}:{cycle_id}",
            workspace=workspace,
            homeostasis=homeostasis,
            persist=True,
        )
        if not normalize_text_value(conscious_state.get("cycle_id"), fallback="", limit=80):
            conscious_cycle_error = "The recurrent preflight returned no causal cycle id."
    except Exception as exc:  # pragma: no cover - defensive runtime shield
        conscious_cycle_error = normalize_text_value(
            exc,
            fallback="The recurrent preflight cycle could not be opened.",
            limit=220,
        )
        try:
            conscious_state = load_conscious_state(prefer_runtime=prefer_runtime)
        except Exception:
            conscious_state = {}
    selection = select_developmental_cycle_action(
        config,
        state,
        workspace=workspace,
        homeostasis=homeostasis,
        component_state=component_state,
        recent_actions=recent_actions,
        recent_cycles=recent_cycles,
        conscious_state=conscious_state,
    )
    action = normalize_text_value(selection.get("action"), fallback="service_health_check", limit=80)
    capability = normalize_text_value(selection.get("capability"), fallback=f"operational_action_tree.{action}", limit=140)
    selection_source = normalize_text_value(
        selection.get("selection_source"),
        fallback="developmental_rotation",
        limit=80,
    )
    error_text = ""
    try:
        if action == "system_tasks":
            result = run_bounded_system_tasks_step(
                config,
                source=f"developmental_cycle:{source}:{cycle_id}",
                state=state,
            )
        else:
            result = run_operational_action_tree(action, config, source=f"developmental_cycle:{source}:{cycle_id}")
    except Exception as exc:  # pragma: no cover - defensive runtime shield
        error_text = str(exc)
        result = {
            "executed": False,
            "ok": False,
            "summary": normalize_text_value(exc, fallback=f"{action} failed.", limit=220),
            "response": f"The developmental cycle tried `{action}` but it failed before returning a clean result.",
        }
    ok = action_result_verified_for_completion(result)
    result_summary = normalize_text_value(
        result.get("execution_summary") or result.get("summary") or result.get("response"),
        fallback=f"{action} finished without a useful summary.",
        limit=320,
    )
    result_status = normalize_text_value(
        result.get("status"),
        fallback="completed" if result.get("executed") else "blocked",
        limit=40,
    )
    outcome_observation = autonomy_action_outcome_observation(
        {
            **result,
            "action": action,
            "status": result_status,
        }
    )
    conscious_completion: Dict[str, object] = {}
    next_conscious_state: Dict[str, object] = {}
    conscious_outcome = {
        "ok": outcome_observation.get("outcome_ok"),
        "observed": bool(outcome_observation.get("consequence_observed")),
        "evidence_kind": outcome_observation.get("evidence_kind") or "pending",
        "evidence_id": normalize_text_value(
            result.get("execution_id"),
            fallback=f"developmental:{cycle_id}",
            limit=120,
        ),
        "summary": result_summary,
        "action": action,
        "source_cycle_id": normalize_text_value(conscious_state.get("cycle_id"), fallback="", limit=80),
        "execution_id": normalize_text_value(result.get("execution_id"), fallback="", limit=80),
    }
    if conscious_state.get("cycle_id"):
        try:
            conscious_completion = complete_recurrent_conscious_cycle(
                actual_process={
                    "lanes": ["planner"],
                    "model": "developmental_control",
                    "tools_used": [action] if result.get("executed") else [],
                    "action_id": action,
                    "revision_used": False,
                },
                outcome=conscious_outcome,
                source=f"{conscious_source_prefix}_outcome:{source}:{cycle_id}",
                opened_state=conscious_state,
            )
            next_conscious_state = build_recurrent_conscious_state(
                source=f"{conscious_source_prefix}_recurrent:{source}:{cycle_id}",
                latest_outcome=conscious_outcome,
                persist=True,
            )
        except Exception as exc:  # pragma: no cover - defensive runtime shield
            closure_error = normalize_text_value(
                exc,
                fallback="The recurrent outcome could not be closed.",
                limit=220,
            )
            conscious_cycle_error = (
                f"{conscious_cycle_error}; {closure_error}".strip("; ")
                if conscious_cycle_error
                else closure_error
            )
    failure_mode = infer_developmental_failure_mode(action, result, error_text=error_text)
    if conscious_cycle_error:
        causal_failure = f"recurrent action binding did not close cleanly: {conscious_cycle_error}"
        failure_mode = f"{failure_mode}; {causal_failure}" if failure_mode else causal_failure
    improvement = "Logged the verified cycle as durable developmental evidence and updated the daemon state for the next hourly test."
    improvement_task_id = ""
    if not ok or failure_mode:
        failure_mode = failure_mode or f"{action} did not produce verified evidence."
        repair_task = record_developmental_failure_task(
            cycle_id=cycle_id,
            action=action,
            failure_mode=failure_mode,
            result=result,
        )
        improvement_task_id = normalize_text_value(repair_task.get("id"), fallback="", limit=80)
        improvement = (
            f"Created or reused repair task `{improvement_task_id}` so the exact failure mode has a concrete follow-up."
        )

    record = {
        "id": cycle_id,
        "timestamp": timestamp,
        "source": source,
        "force": bool(force),
        "architecture_map": architecture_map,
        "organ_assimilation": {
            "generated_at": organ_report.get("generated_at"),
            "resident_chat_lane_delta": organ_report.get("resident_chat_lane_delta"),
            "organ_count": len(organ_signals),
        },
        "organ_signals": organ_signals,
        "what_eve_observed": observed,
        "what_she_thought_mattered": normalize_text_value(
            selection.get("choice"),
            fallback="Choose one verified capability that can turn observation into fresh evidence.",
            limit=320,
        ),
        "what_she_cared_about": normalize_text_value(
            selection.get("care"),
            fallback="I care about grounded initiative instead of passive self-description.",
            limit=320,
        ),
        "what_she_chose_to_do": normalize_text_value(
            selection.get("choice"),
            fallback=f"Run `{action}`.",
            limit=320,
        ),
        "capability_attempted": action,
        "capability_surface": capability,
        "selection_source": selection_source,
        "conscious_action_binding": {
            "source_cycle_id": normalize_text_value(conscious_state.get("cycle_id"), fallback="", limit=80),
            "source_status": normalize_text_value(conscious_state.get("status"), fallback="", limit=40),
            "broadcast": normalize_text_value(
                (conscious_state.get("broadcast") or {}).get("content")
                if isinstance(conscious_state.get("broadcast"), dict)
                else "",
                fallback="",
                limit=240,
            ),
            "action_access": bool(selection.get("conscious_action_access")),
            "selection_source": selection_source,
            "selected_action": normalize_text_value(
                ((conscious_state.get("action_model") or {}).get("selected_intention") or {}).get("id")
                if isinstance(conscious_state.get("action_model"), dict)
                else "",
                fallback="",
                limit=80,
            ),
            "actual_action": action,
            "matched_actual": bool(
                normalize_text_value(
                    ((conscious_state.get("action_model") or {}).get("selected_intention") or {}).get("id")
                    if isinstance(conscious_state.get("action_model"), dict)
                    else "",
                    fallback="",
                    limit=80,
                )
                == action
            ),
            "outcome_observed": bool(outcome_observation.get("consequence_observed")),
            "outcome_ok": outcome_observation.get("outcome_ok"),
            "evidence_kind": outcome_observation.get("evidence_kind") or "pending",
            "completed_cycle_id": normalize_text_value(conscious_completion.get("cycle_id"), fallback="", limit=80),
            "next_cycle_id": normalize_text_value(next_conscious_state.get("cycle_id"), fallback="", limit=80),
            "overall_prediction_error": (
                (conscious_completion.get("cycle_outcome") or {}).get("overall_prediction_error")
                if isinstance(conscious_completion.get("cycle_outcome"), dict)
                else None
            ),
            "error": conscious_cycle_error,
        },
        "result": result_summary,
        "failure_mode_if_any": failure_mode,
        "smallest_improvement_made": improvement,
        "next_thing_to_test": normalize_text_value(
            selection.get("next_test"),
            fallback="Run another cycle and compare whether the next capability creates new evidence.",
            limit=320,
        ),
        "action_result": {
            "execution_id": result.get("execution_id"),
            "execution_backend": result.get("execution_backend"),
            "execution_tree_status": result.get("execution_tree_status"),
            "execution_verification_ok": action_result_explicit_verification(result) is True,
            "ok": bool(result.get("ok")),
            "executed": bool(result.get("executed")),
            "status": result_status,
            "summary": result_summary,
            "created_count": result.get("created_count"),
            "completed_count": result.get("completed_count"),
            "maintenance_count": result.get("maintenance_count"),
        },
        "repair_task_id": improvement_task_id,
    }
    saved = append_developmental_cycle_record(record)
    if organ_signals and parse_boolish(config.get("organ_pulse_record_on_developmental_cycle", True)):
        try:
            append_organ_pulse_record(
                organ_report,
                source=f"developmental_cycle:{source}",
                record_event=parse_boolish(config.get("organ_status_event_ledger_enabled", True)),
                event_ledger_enabled=parse_boolish(config.get("organ_status_event_ledger_enabled", True)),
            )
        except Exception:
            pass
    append_entry(
        "developmental_cycle",
        (
            f"Observed: {normalize_text_value(observed, fallback='', limit=180)} "
            f"Chose: {action}. Result: {result_summary}"
        ),
        metadata={
            "cycle_id": cycle_id,
            "source": source,
            "capability_attempted": action,
            "selection_source": selection_source,
            "conscious_cycle_id": normalize_text_value(conscious_state.get("cycle_id"), fallback="", limit=80),
            "ok": ok,
            "failure_mode": failure_mode,
            "repair_task_id": improvement_task_id,
        },
    )
    state["last_developmental_cycle_at"] = timestamp
    state["last_developmental_cycle_id"] = cycle_id
    state["last_developmental_cycle_action"] = action
    state["last_developmental_cycle_result"] = "verified" if ok and not failure_mode else "needs_repair"
    state["developmental_cycle_summary"] = f"{action}: {result_summary}"
    if source.startswith("daemon") or running_from_runtime_bundle():
        try:
            save_state(state)
        except OSError:
            pass
    return saved


def read_capability_gaps(
    limit: Optional[int] = None,
    status: Optional[str] = None,
    *,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(CAPABILITY_GAPS_PATH, prefer_runtime=prefer_runtime)
    if limit is not None and not status:
        records = read_jsonl_tail_records(path, limit)
    else:
        records = read_jsonl_records(path)
    if status:
        records = [item for item in records if str(item.get("status") or "") == status]
    records.sort(key=lambda item: item.get("created_at") or item.get("updated_at") or "", reverse=True)
    if limit is not None:
        records = records[:limit]
    return records


def format_capability_gap(record: Dict[str, object], full: bool = False) -> str:
    lines = [
        f"{record.get('id')} [{record.get('status') or 'unknown'}] {record.get('goal') or 'Capability gap'}",
        f"commitment: {record.get('commitment_text') or 'none recorded'}",
        f"proposal: {record.get('proposal_id') or 'none'} | source: {record.get('source') or 'unknown'} | created_at: {record.get('created_at') or 'unknown'}",
    ]
    if full:
        plan = record.get("acquisition_plan") if isinstance(record.get("acquisition_plan"), list) else []
        lines.append("acquisition_plan:")
        lines.extend(f"- {item}" for item in plan)
        tools = record.get("known_tools") if isinstance(record.get("known_tools"), list) else []
        lines.append("known_tools: " + (", ".join(str(item) for item in tools) or "none"))
    return "\n".join(lines)


@contextmanager
def store_lock(path: Path):
    ensure_store()
    with eve_store.file_lock(path):
        yield


def compact_prompt_field(value: object, limit: Optional[int] = None) -> str:
    text = " ".join(str(value or "").split())
    if limit is None or limit <= 0 or len(text) <= limit:
        return text
    marker = " ...[truncated]"
    return text[: max(0, limit - len(marker))].rstrip() + marker


def format_entries(entries: Iterable[Dict[str, object]], text_limit: Optional[int] = None) -> str:
    chunks: List[str] = []
    for entry in entries:
        text = compact_prompt_field(entry.get("text", ""), text_limit)
        chunks.append(f"- {entry['timestamp']} [{entry['kind']}] {text}")
    return "\n".join(chunks) if chunks else "- No entries available."


DAEMON_RUNTIME_CACHE_TTL_SECONDS = 1.0
_DAEMON_RUNTIME_CACHE: Dict[str, object] = {"checked_at": 0.0, "value": None}


def clear_daemon_runtime_cache() -> None:
    _DAEMON_RUNTIME_CACHE["checked_at"] = 0.0
    _DAEMON_RUNTIME_CACHE["value"] = None


def daemon_runtime_running() -> bool:
    now = time.monotonic()
    cached_value = _DAEMON_RUNTIME_CACHE.get("value")
    checked_at = float(_DAEMON_RUNTIME_CACHE.get("checked_at") or 0.0)
    if isinstance(cached_value, bool) and now - checked_at <= DAEMON_RUNTIME_CACHE_TTL_SECONDS:
        return cached_value
    result = run_launchctl(["print", launchctl_target()], allow_failure=True)
    if result.returncode != 0:
        running = False
    else:
        output = "\n".join(part for part in [result.stdout or "", result.stderr or ""] if part).lower()
        running = "state = running" in output
    _DAEMON_RUNTIME_CACHE["checked_at"] = now
    _DAEMON_RUNTIME_CACHE["value"] = running
    return running


def parse_launchctl_service_status(output: str) -> Dict[str, str]:
    text = output or ""
    state_match = re.search(r"^\s*state = ([^\n]+)", text, flags=re.MULTILINE)
    pid_match = re.search(r"^\s*pid = (\d+)", text, flags=re.MULTILINE)
    return {
        "state": state_match.group(1).strip() if state_match else "",
        "pid": pid_match.group(1).strip() if pid_match else "",
    }


def running_from_runtime_bundle() -> bool:
    return ROOT == RUNTIME_DIR


def file_sha256(path: Path) -> str:
    try:
        hasher = hashlib.sha256()
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                hasher.update(chunk)
        return hasher.hexdigest()
    except OSError:
        return ""


_FACULTY_BEHAVIOR_FINGERPRINT_CACHE: Dict[str, object] = {}


def _faculty_behavior_config_snapshot(config: Dict[str, object]) -> Dict[str, object]:
    """Return only non-secret settings that can change faculty reply behavior."""
    exact = {
        "model",
        "model_backend",
        "model_lane_topology_mode",
        "model_lane_three_substrate_profile_map",
        "fast_model",
        "fast_model_backend",
        "deep_model",
        "deep_model_backend",
        "preferred_fast_model",
        "preferred_deep_model",
        "resident_models",
        "reply_lane_learning_enabled",
        "reply_lane_causal_learning_enabled",
        "reply_lane_causal_min_comparisons",
        "reply_lane_causal_adjustment_step",
    }
    prefixes = (
        "reply_council_",
        "reply_stream_",
        "mind_stream_",
        "epistemic_",
        "llama_cpp_",
        "fast_llama_cpp_",
        "deep_llama_cpp_",
        "observer_llama_cpp_",
        "planner_llama_cpp_",
        "relationship_llama_cpp_",
    )
    forbidden_fragments = ("secret", "token", "password", "api_key", "authorization")
    snapshot: Dict[str, object] = {}
    for key in sorted(config):
        lowered = str(key).lower()
        if any(fragment in lowered for fragment in forbidden_fragments):
            continue
        if key not in exact and not key.startswith(prefixes):
            continue
        value = config.get(key)
        if isinstance(value, (str, int, float, bool)) or value is None:
            snapshot[str(key)] = value
        elif isinstance(value, (list, dict)):
            try:
                snapshot[str(key)] = json.loads(
                    json.dumps(value, ensure_ascii=True, sort_keys=True)
                )
            except (TypeError, ValueError):
                continue
    return snapshot


def _path_stat_identity(value: object) -> Dict[str, object]:
    raw = str(value or "").strip()
    if not raw:
        return {"path": "", "present": False, "size_bytes": 0, "mtime_ns": 0}
    path = Path(raw).expanduser()
    try:
        stat = path.stat()
    except OSError:
        return {"path": raw, "present": False, "size_bytes": 0, "mtime_ns": 0}
    return {
        "path": str(path),
        "present": path.is_file(),
        "size_bytes": int(stat.st_size),
        "mtime_ns": int(stat.st_mtime_ns),
    }


def _running_llama_behavior_specs() -> List[Dict[str, object]]:
    """Describe live resident model processes without PIDs or mutable counters."""
    try:
        result = subprocess.run(
            ["ps", "-axo", "command="],
            capture_output=True,
            text=True,
            timeout=5,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return []
    if result.returncode != 0:
        return []
    captured_flags = {
        "--alias",
        "--ctx-size",
        "--model",
        "--parallel",
        "--port",
        "--reasoning",
    }
    specs: List[Dict[str, object]] = []
    for line in result.stdout.splitlines():
        try:
            parts = shlex.split(line)
        except ValueError:
            continue
        if not parts or Path(parts[0]).name != "llama-server":
            continue
        flags: Dict[str, str] = {}
        index = 1
        while index < len(parts):
            token = parts[index]
            if token in captured_flags and index + 1 < len(parts):
                flags[token[2:].replace("-", "_")] = parts[index + 1]
                index += 2
                continue
            index += 1
        model_identity = _path_stat_identity(flags.get("model"))
        binary = Path(parts[0]).expanduser()
        specs.append(
            {
                "alias": flags.get("alias", ""),
                "port": flags.get("port", ""),
                "ctx_size": flags.get("ctx_size", ""),
                "parallel": flags.get("parallel", ""),
                "reasoning": flags.get("reasoning", ""),
                "model_artifact": model_identity,
                "server_binary_path": str(binary),
                "server_binary_sha256": file_sha256(binary),
            }
        )
    return sorted(specs, key=lambda item: (str(item.get("port") or ""), str(item.get("alias") or "")))


def faculty_behavior_fingerprint_payload(
    config: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Fingerprint the code, prompts, routing, and resident models under test.

    External leave-one-faculty-out evidence is valid only for the behavior epoch
    that produced it.  The digest intentionally excludes prompts/responses and
    mutable reply-learning state, while including the active model identities
    and every source artifact that can change packet generation or synthesis.
    """
    cfg = dict(config or load_config())
    config_snapshot = _faculty_behavior_config_snapshot(cfg)
    topology = eve_model_topology.topology_snapshot(cfg)
    source_stats: List[Dict[str, object]] = []
    for relative in FACULTY_BEHAVIOR_FINGERPRINT_FILES:
        path = ROOT / relative
        try:
            stat = path.stat()
            source_stats.append(
                {
                    "path": relative,
                    "present": path.is_file(),
                    "size_bytes": int(stat.st_size),
                    "mtime_ns": int(stat.st_mtime_ns),
                }
            )
        except OSError:
            source_stats.append(
                {"path": relative, "present": False, "size_bytes": 0, "mtime_ns": 0}
            )
    resident_models = _running_llama_behavior_specs()
    cache_basis = {
        "source_stats": source_stats,
        "config": config_snapshot,
        "topology": topology,
        "resident_models": resident_models,
    }
    cache_signature = hashlib.sha256(
        json.dumps(
            cache_basis,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    if (
        _FACULTY_BEHAVIOR_FINGERPRINT_CACHE.get("cache_signature") == cache_signature
        and isinstance(_FACULTY_BEHAVIOR_FINGERPRINT_CACHE.get("payload"), dict)
    ):
        return dict(_FACULTY_BEHAVIOR_FINGERPRINT_CACHE["payload"])
    source_files = [
        {
            "path": item["path"],
            "present": item["present"],
            "sha256": file_sha256(ROOT / str(item["path"])) if item["present"] else "",
        }
        for item in source_stats
    ]
    basis = {
        "schema_version": FACULTY_BEHAVIOR_FINGERPRINT_SCHEMA_VERSION,
        "source_files": source_files,
        "config": config_snapshot,
        "topology": topology,
        "resident_models": resident_models,
    }
    fingerprint = hashlib.sha256(
        json.dumps(
            basis,
            ensure_ascii=True,
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    ).hexdigest()
    payload = {
        "schema_version": FACULTY_BEHAVIOR_FINGERPRINT_SCHEMA_VERSION,
        "fingerprint": fingerprint,
        "source_file_count": len(source_files),
        "resident_model_process_count": len(resident_models),
        "topology_mode": topology.get("mode"),
        "logical_lane_count": topology.get("logical_lane_count"),
        "substrate_count": topology.get("substrate_count"),
    }
    _FACULTY_BEHAVIOR_FINGERPRINT_CACHE.clear()
    _FACULTY_BEHAVIOR_FINGERPRINT_CACHE.update(
        {"cache_signature": cache_signature, "payload": dict(payload)}
    )
    return payload


def file_mtime_iso(path: Path) -> str:
    try:
        return datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).replace(microsecond=0).isoformat()
    except OSError:
        return ""


