def runtime_state_authority_records(
    catalog: Optional[List[Dict[str, object]]] = None,
    *,
    runtime_live: Optional[bool] = None,
) -> Dict[str, object]:
    runtime_is_live = daemon_runtime_running() if runtime_live is None else bool(runtime_live)
    records: List[Dict[str, object]] = []
    for item in catalog or runtime_state_authority_catalog():
        source_path = Path(item["path"])
        runtime_path = runtime_store_path(source_path)
        authority = str(item.get("authority") or STATE_AUTHORITY_SOURCE_OWNED)
        source_exists = source_path.exists()
        runtime_exists = bool(runtime_path and runtime_path.exists())
        source_hash = file_sha256(source_path) if source_exists and source_path.is_file() else ""
        runtime_hash = file_sha256(runtime_path) if runtime_path and runtime_exists and runtime_path.is_file() else ""
        matches = bool(source_exists and runtime_exists and source_hash and source_hash == runtime_hash)
        runtime_authority = authority in STATE_AUTHORITY_RUNTIME_AUTHORITIES
        live_runtime_authority = runtime_authority and runtime_is_live
        source_mtime_ns = 0
        runtime_mtime_ns = 0
        try:
            source_mtime_ns = source_path.stat().st_mtime_ns if source_exists else 0
        except OSError:
            source_mtime_ns = 0
        try:
            runtime_mtime_ns = runtime_path.stat().st_mtime_ns if runtime_path and runtime_exists else 0
        except OSError:
            runtime_mtime_ns = 0

        selection_reason = "source_owned_contract"
        if live_runtime_authority:
            authoritative_side = "runtime" if runtime_exists else "missing_runtime"
            selection_reason = "live_runtime_contract" if runtime_exists else "live_runtime_copy_missing"
        elif runtime_authority:
            # A stopped daemon does not transfer ownership of Eve's lived state
            # back to the checkout.  Recovery must preserve the newest persisted
            # copy instead of blindly overwriting a later runtime history with an
            # older source mirror.  Normal source-side writes mirror to runtime,
            # so a newer source copy is still honored when it is the only recent
            # evidence (for example, an operator restore while Eve is stopped).
            if runtime_exists and source_exists:
                if runtime_mtime_ns >= source_mtime_ns:
                    authoritative_side = "runtime"
                    selection_reason = "offline_newest_persisted_runtime"
                else:
                    authoritative_side = "source"
                    selection_reason = "offline_newest_persisted_source"
            elif runtime_exists:
                authoritative_side = "runtime"
                selection_reason = "offline_only_persisted_runtime"
            elif source_exists:
                authoritative_side = "source"
                selection_reason = "offline_only_persisted_source"
            else:
                authoritative_side = "missing_persisted_state"
                selection_reason = "offline_persisted_state_missing"
        else:
            authoritative_side = "source" if source_exists else "missing_source"
            selection_reason = "source_owned_contract" if source_exists else "source_owned_copy_missing"
        mirror_side = "source" if authoritative_side == "runtime" else "runtime"
        mismatch = bool(source_exists and runtime_exists and source_hash and runtime_hash and source_hash != runtime_hash)
        missing_mirror = bool(
            authority != STATE_AUTHORITY_ARTIFACT_ONLY
            and authoritative_side in {"source", "runtime"}
            and ((authoritative_side == "runtime" and not source_exists) or (authoritative_side == "source" and not runtime_exists))
        )
        missing_authoritative = bool(authoritative_side in {"missing_runtime", "missing_source", "missing_persisted_state"})
        live_runtime_authority = bool(live_runtime_authority and runtime_exists)
        mirror_lag = bool(live_runtime_authority and (mismatch or missing_mirror))
        offline_recovery_lag = bool(
            runtime_authority
            and not runtime_is_live
            and authoritative_side in {"source", "runtime"}
            and (mismatch or missing_mirror)
        )
        blocks_truth = bool(
            authority != STATE_AUTHORITY_ARTIFACT_ONLY
            and (
                missing_authoritative
                or ((mismatch or missing_mirror) and not mirror_lag and not offline_recovery_lag)
            )
        )
        needs_reconcile = bool(
            authority != STATE_AUTHORITY_ARTIFACT_ONLY
            and (mismatch or missing_mirror or missing_authoritative)
        )
        authoritative_path = (
            runtime_path
            if authoritative_side == "runtime"
            else source_path
            if authoritative_side == "source"
            else None
        )
        mirror_path = source_path if authoritative_side == "runtime" else runtime_path if authoritative_side == "source" else None
        records.append(
            {
                "id": item.get("id"),
                "authority": authority,
                "contract": item.get("contract") or "",
                "source_path": str(source_path),
                "runtime_path": str(runtime_path) if runtime_path else "",
                "source_exists": source_exists,
                "runtime_exists": runtime_exists,
                "source_mtime": file_mtime_iso(source_path),
                "runtime_mtime": file_mtime_iso(runtime_path) if runtime_path else "",
                "source_sha256": source_hash,
                "runtime_sha256": runtime_hash,
                "matches": matches,
                "authoritative_side": authoritative_side,
                "authoritative_path": str(authoritative_path) if authoritative_path else "",
                "selection_reason": selection_reason,
                "mirror_side": mirror_side,
                "mirror_path": str(mirror_path) if mirror_path else "",
                "needs_reconcile": needs_reconcile,
                "blocks_truth": blocks_truth,
                "mirror_lag": mirror_lag,
                "offline_recovery_lag": offline_recovery_lag,
                "mismatch": mismatch,
                "missing_mirror": missing_mirror,
                "missing_authoritative": missing_authoritative,
            }
        )
    reconcile_records = [item for item in records if item.get("needs_reconcile")]
    blocking_records = [item for item in records if item.get("blocks_truth")]
    mirror_lag_records = [item for item in records if item.get("mirror_lag")]
    offline_recovery_records = [item for item in records if item.get("offline_recovery_lag")]
    status = "ok"
    if blocking_records:
        status = "state_authority_mismatch"
    elif mirror_lag_records:
        status = "live_mirror_lag"
    elif offline_recovery_records:
        status = "offline_recovery_lag"
    return {
        "status": status,
        "runtime_live": runtime_is_live,
        "needs_reconcile": bool(reconcile_records),
        "blocks_truth": bool(blocking_records),
        "reconcile_count": len(reconcile_records),
        "blocking_reconcile_count": len(blocking_records),
        "mirror_lag_count": len(mirror_lag_records),
        "offline_recovery_lag_count": len(offline_recovery_records),
        "records": records,
    }


def reconcile_runtime_state_authority(
    *,
    catalog: Optional[List[Dict[str, object]]] = None,
    store_ids: Optional[Set[str]] = None,
    apply: bool = False,
) -> Dict[str, object]:
    authority = runtime_state_authority_records(catalog)
    actions: List[Dict[str, object]] = []
    selected_ids = {str(item) for item in store_ids or set()}
    for record in authority.get("records") or []:
        if not isinstance(record, dict) or not record.get("needs_reconcile"):
            continue
        record_id = str(record.get("id") or "")
        if selected_ids and record_id not in selected_ids:
            continue
        authoritative_path = Path(str(record.get("authoritative_path") or ""))
        mirror_path = Path(str(record.get("mirror_path") or ""))
        action = {
            "id": record_id,
            "authority": record.get("authority"),
            "authoritative_side": record.get("authoritative_side"),
            "authoritative_path": str(authoritative_path),
            "mirror_side": record.get("mirror_side"),
            "mirror_path": str(mirror_path),
            "applied": False,
            "status": "dry_run",
        }
        if record.get("missing_authoritative") or not record.get("authoritative_path") or not authoritative_path.exists():
            action["status"] = "missing_authoritative"
            actions.append(action)
            continue
        if not record.get("mirror_path"):
            action["status"] = "missing_mirror_path"
            actions.append(action)
            continue
        if apply:
            mirror_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(authoritative_path, mirror_path)
            action["applied"] = True
            action["status"] = "copied"
        actions.append(action)
    return {
        "checked_at": utc_now(),
        "dry_run": not apply,
        "applied_count": sum(1 for item in actions if item.get("applied")),
        "pending_count": sum(1 for item in actions if not item.get("applied")),
        "actions": actions,
        "state_authority": authority,
    }


def record_has_test_metadata_source(record: Dict[str, object]) -> bool:
    metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
    return str(record.get("source") or "") == "test" or str(metadata.get("source") or "") == "test"


def test_metadata_guard_paths() -> List[Path]:
    local_paths = [
        ENTRIES_PATH,
        MESSAGES_PATH,
        EVIDENCE_LEDGER_PATH,
        EXPERIENCE_EVENTS_PATH,
        ACTION_EXECUTIONS_PATH,
        DEVELOPMENTAL_CYCLES_PATH,
    ]
    paths: List[Path] = []
    seen: Set[str] = set()
    for path in local_paths:
        for candidate in [path, runtime_store_path(path)]:
            if candidate is None:
                continue
            key = str(candidate)
            if key in seen:
                continue
            seen.add(key)
            paths.append(candidate)
    return paths


def scan_test_metadata_leaks(paths: Optional[List[Path]] = None, *, limit: int = 20) -> Dict[str, object]:
    examples: List[Dict[str, object]] = []
    total = 0
    for path in paths or test_metadata_guard_paths():
        if not path.exists() or not path.is_file():
            continue
        try:
            with path.open("r", encoding="utf-8") as handle:
                for line_number, line in enumerate(handle, start=1):
                    record = eve_store.parse_jsonl_line(line)
                    if record is None or not record_has_test_metadata_source(record):
                        continue
                    total += 1
                    if len(examples) < limit:
                        examples.append(
                            {
                                "path": str(path),
                                "line": line_number,
                                "id": record.get("id") or "",
                                "timestamp": record.get("timestamp") or record.get("created_at") or "",
                                "kind": record.get("kind") or record.get("event_type") or "",
                                "source": record.get("source") or "",
                                "metadata_source": (
                                    record.get("metadata", {}).get("source")
                                    if isinstance(record.get("metadata"), dict)
                                    else ""
                                ),
                            }
                        )
        except OSError:
            continue
    return {
        "checked_at": utc_now(),
        "status": "failed" if total else "ok",
        "leak_count": total,
        "examples": examples,
    }


def quarantine_test_metadata_leaks(paths: Optional[List[Path]] = None) -> Dict[str, object]:
    checked_paths = paths or test_metadata_guard_paths()
    changed_paths: List[Dict[str, object]] = []
    total = 0
    quarantined_at = utc_now()
    for path in checked_paths:
        if not path.exists() or not path.is_file():
            continue
        changed = 0
        records: List[Dict[str, object]] = []
        malformed_lines: List[str] = []
        try:
            with path.open("r", encoding="utf-8") as handle:
                for line in handle:
                    record = eve_store.parse_jsonl_line(line)
                    if record is None:
                        malformed_lines.append(line)
                        continue
                    if record_has_test_metadata_source(record):
                        metadata = dict(record.get("metadata") if isinstance(record.get("metadata"), dict) else {})
                        if str(record.get("source") or "") == "test":
                            record["source"] = "historical_test_quarantined"
                            metadata.setdefault("original_source", "test")
                        if str(metadata.get("source") or "") == "test":
                            metadata["source"] = "historical_test_quarantined"
                            metadata.setdefault("original_metadata_source", "test")
                        metadata["test_metadata_quarantined_at"] = quarantined_at
                        record["metadata"] = metadata
                        changed += 1
                    records.append(record)
        except OSError:
            continue
        if changed:
            eve_store.write_jsonl_records(path, records)
            if malformed_lines:
                with path.open("a", encoding="utf-8") as handle:
                    handle.writelines(malformed_lines)
            changed_paths.append({"path": str(path), "quarantined": changed})
            total += changed
    return {
        "checked_at": quarantined_at,
        "status": "quarantined" if total else "ok",
        "quarantined_count": total,
        "paths": changed_paths,
    }


def runtime_source_truth_check(
    pairs: Optional[List[Tuple[str, Path, Path]]] = None,
    *,
    include_daemon: bool = True,
    include_state_authority: bool = True,
    state_catalog: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    # Cover ALL synced first-party Python (top-level modules + every package file),
    # derived from the same discovery the sync uses — so drift in any module is
    # detected, not just three hardcoded files.
    source_runtime_pairs = pairs or first_party_python_source_pairs()
    file_records: List[Dict[str, object]] = []
    for label, source_path, runtime_path in source_runtime_pairs:
        source_exists = source_path.exists()
        runtime_exists = runtime_path.exists()
        source_hash = file_sha256(source_path) if source_exists else ""
        runtime_hash = file_sha256(runtime_path) if runtime_exists else ""
        try:
            runtime_older = source_exists and runtime_exists and runtime_path.stat().st_mtime < source_path.stat().st_mtime
        except OSError:
            runtime_older = False
        file_records.append(
            {
                "label": label,
                "source_path": str(source_path),
                "runtime_path": str(runtime_path),
                "source_exists": source_exists,
                "runtime_exists": runtime_exists,
                "source_mtime": file_mtime_iso(source_path),
                "runtime_mtime": file_mtime_iso(runtime_path),
                "source_sha256": source_hash,
                "runtime_sha256": runtime_hash,
                "matches": bool(source_exists and runtime_exists and source_hash == runtime_hash),
                "runtime_older_than_source": bool(runtime_older),
            }
        )
    mismatches = [item for item in file_records if not item.get("matches")]
    missing = [item for item in file_records if not item.get("source_exists") or not item.get("runtime_exists")]
    state_authority = (
        runtime_state_authority_records(state_catalog, runtime_live=daemon_runtime_running() if include_daemon else False)
        if include_state_authority
        else {"status": "skipped", "needs_reconcile": False, "records": []}
    )
    status = "ok"
    if missing:
        status = "missing_runtime_or_source"
    elif mismatches:
        status = "runtime_source_mismatch"
    elif state_authority.get("blocks_truth"):
        status = "state_authority_mismatch"
    return {
        "checked_at": utc_now(),
        "status": status,
        "running_from_runtime_bundle": running_from_runtime_bundle(),
        "daemon_runtime_running": daemon_runtime_running() if include_daemon else None,
        "needs_runtime_sync": bool(mismatches or missing),
        "needs_state_reconcile": bool(state_authority.get("blocks_truth")),
        "state_reconcile_available": bool(state_authority.get("needs_reconcile")),
        "files": file_records,
        "state_authority": state_authority,
        "epistemic_event_deployment": epistemic_event_deployment_truth(),
    }


def format_runtime_source_truth_check(check: Dict[str, object]) -> str:
    lines = [
        "Runtime source-of-truth",
        f"- status: {check.get('status') or 'unknown'}",
        f"- daemon_runtime_running: {check.get('daemon_runtime_running')}",
        f"- needs_runtime_sync: {'yes' if check.get('needs_runtime_sync') else 'no'}",
    ]
    for item in check.get("files") or []:
        if not isinstance(item, dict):
            continue
        match_text = "match" if item.get("matches") else "DIFF"
        older_text = " | runtime older" if item.get("runtime_older_than_source") else ""
        source_hash = str(item.get("source_sha256") or "")[:12] or "missing"
        runtime_hash = str(item.get("runtime_sha256") or "")[:12] or "missing"
        lines.append(
            f"- {item.get('label')}: {match_text}{older_text} | source {source_hash} | runtime {runtime_hash}"
        )
    event_deployment = (
        check.get("epistemic_event_deployment")
        if isinstance(check.get("epistemic_event_deployment"), dict)
        else {}
    )
    if event_deployment:
        source_event = (
            event_deployment.get("source")
            if isinstance(event_deployment.get("source"), dict)
            else {}
        )
        runtime_event = (
            event_deployment.get("runtime")
            if isinstance(event_deployment.get("runtime"), dict)
            else {}
        )
        lines.append(
            "- epistemic_event_deployment: "
            f"{event_deployment.get('status') or 'unknown'}"
            f" | source={source_event.get('status') or 'missing'}"
            f"/live:{'yes' if source_event.get('live_admitted') else 'no'}"
            f" | runtime={runtime_event.get('status') or 'missing'}"
            f"/live:{'yes' if runtime_event.get('live_admitted') else 'no'}"
            " | blocks_core_sync=no"
        )
    state_authority = check.get("state_authority") if isinstance(check.get("state_authority"), dict) else {}
    if state_authority:
        lines.append(
            f"- state_authority: {state_authority.get('status') or 'unknown'}"
            f" | reconcile_count: {state_authority.get('reconcile_count', 0)}"
            f" | mirror_lag_count: {state_authority.get('mirror_lag_count', 0)}"
            f" | offline_recovery_lag_count: {state_authority.get('offline_recovery_lag_count', 0)}"
        )
        for record in state_authority.get("records") or []:
            if not isinstance(record, dict) or not record.get("needs_reconcile"):
                continue
            source_hash = str(record.get("source_sha256") or "")[:12] or "missing"
            runtime_hash = str(record.get("runtime_sha256") or "")[:12] or "missing"
            lines.append(
                "- "
                f"{record.get('id')}: reconcile {record.get('authoritative_side')} -> {record.get('mirror_side')}"
                f" | authority {record.get('authority')}"
                f" | reason {record.get('selection_reason') or 'unknown'}"
                f" | source {source_hash} | runtime {runtime_hash}"
            )
    if check.get("needs_runtime_sync"):
        lines.append("- next_bounded_move: run `python3 eve.py runtime sync` before trusting live Monitor behavior.")
    if check.get("needs_state_reconcile"):
        lines.append(
            "- next_bounded_move: run `python3 eve.py runtime reconcile --dry-run` before trusting live state mirrors."
        )
    elif check.get("state_reconcile_available"):
        lines.append(
            "- note: live daemon state has source-mirror lag; run `python3 eve.py runtime reconcile --dry-run` when you need fresh source mirrors."
        )
    return "\n".join(lines)


def delegate_cli_to_runtime(arguments: List[str], timeout_seconds: Optional[int] = None) -> Optional[int]:
    if running_from_runtime_bundle() or not daemon_runtime_running() or not RUNTIME_SCRIPT_PATH.exists():
        return None
    try:
        result = subprocess.run(
            [sys.executable, str(RUNTIME_SCRIPT_PATH), *arguments],
            cwd=str(RUNTIME_DIR),
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired as exc:
        if exc.stdout:
            sys.stdout.write(exc.stdout)
        if exc.stderr:
            sys.stderr.write(exc.stderr)
        command_label = " ".join(arguments[:2]).strip() or "runtime command"
        if timeout_seconds is not None:
            sys.stderr.write(
                f"Runtime delegation timed out after {int(timeout_seconds)}s while running `{command_label}`.\n"
            )
        else:
            sys.stderr.write(f"Runtime delegation timed out while running `{command_label}`.\n")
        return 124
    if result.stdout:
        sys.stdout.write(result.stdout)
    if result.stderr:
        sys.stderr.write(result.stderr)
    if arguments and arguments[0] in {"awareness", "awareness-battery", "awareness-perturb", "consciousness-test"}:
        sync_runtime_capability_tests_to_source()
    return result.returncode


def runtime_store_path(local_path: Path) -> Optional[Path]:
    try:
        relative = local_path.relative_to(APP_DIR)
    except ValueError:
        return None
    return RUNTIME_APP_DIR / relative


def resolve_store_read_path(local_path: Path, prefer_runtime: bool = False) -> Path:
    ensure_store()
    if not prefer_runtime:
        return local_path
    candidate = runtime_store_path(local_path)
    if candidate is None or not candidate.exists():
        return local_path
    if candidate == local_path:
        return local_path
    if daemon_runtime_running():
        return candidate
    if not local_path.exists():
        return candidate
    try:
        if candidate.stat().st_mtime >= local_path.stat().st_mtime:
            return candidate
    except OSError:
        return local_path
    return local_path


def mirror_store_file_to_runtime(local_path: Path) -> None:
    if running_from_runtime_bundle():
        return
    candidate = runtime_store_path(local_path)
    if candidate is None or candidate == local_path:
        return
    try:
        candidate.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(local_path, candidate)
    except OSError:
        return


def source_store_path(runtime_path: Path) -> Optional[Path]:
    try:
        relative = runtime_path.relative_to(RUNTIME_APP_DIR)
    except ValueError:
        return None
    return APP_DIR / relative


def mirror_runtime_store_file_to_source(runtime_path: Path) -> None:
    candidate = source_store_path(runtime_path)
    if candidate is None or candidate == runtime_path:
        return
    try:
        candidate.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(runtime_path, candidate)
    except OSError:
        return


def mirror_authoritative_store_file(write_path: Path, source_path: Path) -> None:
    if write_path == source_path:
        mirror_store_file_to_runtime(source_path)
    else:
        mirror_runtime_store_file_to_source(write_path)


def mirror_store_tree_to_runtime(local_path: Path) -> None:
    if running_from_runtime_bundle():
        return
    candidate = runtime_store_path(local_path)
    if candidate is None or candidate == local_path or not local_path.exists():
        return
    try:
        shutil.copytree(local_path, candidate, dirs_exist_ok=True)
    except OSError:
        return


def sync_runtime_capability_tests_to_source() -> None:
    runtime_artifact_dir = RUNTIME_APP_DIR / "capability_tests"
    local_artifact_dir = APP_DIR / "capability_tests"
    if not runtime_artifact_dir.exists() or runtime_artifact_dir == local_artifact_dir:
        return
    try:
        local_artifact_dir.mkdir(parents=True, exist_ok=True)
        candidates: List[Tuple[int, int, Path, Path]] = []
        for artifact_path in runtime_artifact_dir.rglob("*"):
            if artifact_path.is_symlink() or not artifact_path.is_file():
                continue
            try:
                stat = artifact_path.stat()
                relative_path = artifact_path.relative_to(runtime_artifact_dir)
            except OSError:
                continue
            if stat.st_size > 2 * 1024 * 1024 or runtime_bundle_file_is_dataless(artifact_path):
                continue
            priority = 0 if artifact_path.name.startswith("latest") else 1
            candidates.append((priority, -stat.st_mtime_ns, artifact_path, relative_path))
        for _priority, _mtime, artifact_path, relative_path in sorted(candidates)[:40]:
            copy_runtime_bundle_data_file_preserving_newer_runtime(artifact_path, local_artifact_dir / relative_path)
    except OSError:
        return


