def load_json_object(path: Path, label: str, prefer_runtime: bool = False) -> Dict[str, object]:
    read_path = resolve_store_read_path(path, prefer_runtime=prefer_runtime)
    if not read_path.exists():
        return {}
    try:
        payload = json.loads(read_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise SystemExit(f"Invalid {label} file at {read_path}: {exc}")
    return payload if isinstance(payload, dict) else {}


def benign_context_gap(message: object) -> bool:
    text = str(message or "").lower()
    return "not enough eve context" in text or "no recent entries found" in text


def context_window_error(message: object) -> bool:
    text = str(message or "").lower()
    return (
        "exceed_context_size_error" in text
        or "exceeds the available context size" in text
        or "recent context-window failure" in text
    )


def format_tensions(tensions: Iterable[Dict[str, object]], text_limit: Optional[int] = None) -> str:
    chunks: List[str] = []
    for tension in tensions:
        values = compact_prompt_field(", ".join(tension.get("values", [])) or "none recorded", text_limit)
        chunks.append(
            "- "
            f"{tension['timestamp']} [{tension['status']}] {compact_prompt_field(tension.get('summary'), text_limit)} | "
            f"A: {compact_prompt_field(tension.get('side_a'), text_limit)} | "
            f"B: {compact_prompt_field(tension.get('side_b'), text_limit)} | "
            f"values: {values} | question: {compact_prompt_field(tension.get('question'), text_limit)} | "
            f"next: {compact_prompt_field(tension.get('next_step'), text_limit)}"
        )
    return "\n".join(chunks) if chunks else "- No tensions recorded."


def format_experiments(experiments: Iterable[Dict[str, object]], text_limit: Optional[int] = None) -> str:
    chunks: List[str] = []
    for experiment in experiments:
        outcome = experiment.get("outcome") or "in progress"
        chunks.append(
            "- "
            f"{experiment['created_at']} [{experiment['status']}] {compact_prompt_field(experiment.get('name'), text_limit)} | "
            f"hypothesis: {compact_prompt_field(experiment.get('hypothesis'), text_limit)} | "
            f"action: {compact_prompt_field(experiment.get('action'), text_limit)} | "
            f"success: {compact_prompt_field(experiment.get('success_criteria'), text_limit)} | "
            f"outcome: {compact_prompt_field(outcome, text_limit)}"
        )
    return "\n".join(chunks) if chunks else "- No experiments recorded."


def format_proposals(proposals: Iterable[Dict[str, object]], text_limit: Optional[int] = None) -> str:
    chunks: List[str] = []
    for proposal in proposals:
        chunks.append(
            "- "
            f"{proposal['created_at']} [{proposal['status']}] {compact_prompt_field(proposal.get('title'), text_limit)} | "
            f"source: {compact_prompt_field(proposal.get('source'), text_limit)} | "
            f"summary: {compact_prompt_field(proposal.get('summary'), text_limit)}"
        )
    return "\n".join(chunks) if chunks else "- No proposals recorded."


def normalize_message_record(message: Optional[Dict[str, object]]) -> Dict[str, object]:
    record = dict(message or {})
    timestamp = ""
    for field in ["timestamp", "created_at", "updated_at"]:
        value = " ".join(str(record.get(field) or "").split()).strip()
        if value:
            timestamp = value
            break
    if timestamp:
        record["timestamp"] = timestamp
    created_at = " ".join(str(record.get("created_at") or "").split()).strip()
    if not created_at and timestamp:
        record["created_at"] = timestamp
        created_at = timestamp
    updated_at = " ".join(str(record.get("updated_at") or "").split()).strip()
    if not updated_at and (created_at or timestamp):
        record["updated_at"] = created_at or timestamp
    if not " ".join(str(record.get("status") or "").split()).strip():
        record["status"] = "unread"
    if not isinstance(record.get("metadata"), dict):
        record["metadata"] = {}
    return record


def normalize_message_records(records: Iterable[Dict[str, object]]) -> tuple[List[Dict[str, object]], bool]:
    normalized: List[Dict[str, object]] = []
    changed = False
    for record in records:
        cleaned = normalize_message_record(record)
        normalized.append(cleaned)
        if cleaned != record:
            changed = True
    return normalized, changed


def message_record_timestamp(message: Dict[str, object]) -> str:
    normalized = normalize_message_record(message)
    value = normalize_text_value(normalized.get("timestamp"), fallback="", limit=40)
    return value or "unknown"


def format_messages(messages: Iterable[Dict[str, object]], body_limit: Optional[int] = None) -> str:
    chunks: List[str] = []
    for message in messages:
        subject = compact_prompt_field(message.get("subject") or "(no subject)", 160 if body_limit else None)
        body = compact_prompt_field(reply_effective_inbound_body(message.get("body", "")), body_limit)
        chunks.append(
            "- "
            f"{message_record_timestamp(message)} [{message.get('sender') or 'unknown'}->{message.get('recipient') or 'unknown'}] "
            f"{subject} | {body}"
        )
    return "\n".join(chunks) if chunks else "- No messages recorded."


SYNTHETIC_REPLAY_PROMPT_MARKERS = (
    "what is the next grounded runtime step here",
    "next grounded runtime step",
    "what is the next grounded step here",
)


def conversation_trace_id(thread_id: object, message_id: object) -> str:
    seed = f"{thread_id or ''}:{message_id or ''}".encode("utf-8", errors="ignore")
    return hashlib.sha256(seed).hexdigest()[:32]


def message_metadata_is_synthetic(metadata: object) -> bool:
    if not isinstance(metadata, dict):
        return False
    conversation_class = str(metadata.get("conversation_class") or "").strip().lower()
    if conversation_class in {"synthetic", "synthetic_eval", "evaluation", "fixture", "replay", "probe"}:
        return True
    for key in ("synthetic", "is_synthetic", "test", "eval", "replay", "probe", "fixture"):
        if parse_explicit_trueish(metadata.get(key)):
            return True
    source = str(metadata.get("source") or metadata.get("origin") or "").lower()
    return any(token in source for token in ("synthetic", "fixture", "replay", "eval", "probe", "test"))


def conversation_message_role(message: Dict[str, object]) -> str:
    sender = str(message.get("sender") or "").strip().lower()
    recipient = str(message.get("recipient") or "").strip().lower()
    if recipient == "eve" and sender != "eve":
        return "user"
    if sender == "eve" and recipient == "user":
        return "assistant"
    if sender == "eve":
        return "internal_eve"
    return "other"


def conversation_message_is_synthetic(message: Dict[str, object]) -> bool:
    metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else {}
    if message_metadata_is_synthetic(metadata):
        return True
    # Unit/integration fixtures use readable paired ids; live mailbox messages
    # are UUIDs. Treat only a matched fixture-shaped message/thread pair as
    # synthetic so local regression runs cannot become Eve's lived state merely
    # because they exercise the production reply function.
    message_id = str(message.get("id") or "").strip().lower()
    thread_id = str(message.get("thread_id") or "").strip().lower()
    fixture_prefixes = ("msg-", "message-", "test-", "fixture-", "probe-")
    fixture_threads = ("thread-", "test-thread-", "fixture-thread-", "probe-thread-")
    if message_id.startswith(fixture_prefixes) and thread_id.startswith(fixture_threads):
        return True
    try:
        if message_is_synthetic_continuity(message) or message_is_background_context(message):
            return True
    except Exception:
        return False
    return False


def build_conversation_spine_record(
    message: Dict[str, object],
    *,
    source: str = "messages",
    trace_id: str = "",
    reply_turn_replay_id: str = "",
    reply_council_turn_id: str = "",
) -> Dict[str, object]:
    metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else {}
    message_id = str(message.get("id") or "")
    thread_id = str(message.get("thread_id") or "")
    timestamp = normalize_text_value(message.get("timestamp") or message.get("created_at"), fallback=utc_now(), limit=40)
    body = str(message.get("body") or "")
    role = conversation_message_role(message)
    synthetic = conversation_message_is_synthetic(message)
    return {
        "schema_id": "eve_conversation_turn.v1",
        "id": str(uuid.uuid4()),
        "timestamp": timestamp,
        "created_at": utc_now(),
        "trace_id": trace_id or conversation_trace_id(thread_id, message_id),
        "thread_id": thread_id,
        "message_id": message_id,
        "reply_to": str(message.get("reply_to") or ""),
        "role": role,
        "direction": "inbound" if role == "user" else ("outbound" if role == "assistant" else "internal"),
        "sender": str(message.get("sender") or ""),
        "recipient": str(message.get("recipient") or ""),
        "kind": normalize_text_value(message.get("kind"), fallback="message", limit=60),
        "subject": normalize_text_value(message.get("subject"), fallback="", limit=220),
        "body": body,
        "body_preview": normalize_text_value(body, fallback="", limit=260),
        "source": normalize_text_value(source, fallback="messages", limit=80),
        "source_ledger": "messages.jsonl",
        "source_message_id": message_id,
        "reply_turn_replay_id": normalize_text_value(reply_turn_replay_id, fallback="", limit=80),
        "reply_council_turn_id": normalize_text_value(reply_council_turn_id, fallback="", limit=80),
        "synthetic": synthetic,
        "conversation_visible": role in {"user", "assistant"} and not synthetic,
        "privacy_tier": normalize_text_value(metadata.get("privacy_tier"), fallback="local_private", limit=80),
        "model": normalize_model_name(metadata.get("model") or metadata.get("used_model") or ""),
        "runtime": "runtime_bundle" if running_from_runtime_bundle() else "source_checkout",
        "metadata": {
            "message_kind": normalize_text_value(message.get("kind"), fallback="message", limit=60),
            "synthetic_source": bool(message_metadata_is_synthetic(metadata)),
        },
    }


def record_conversation_spine_trace_span(record: Dict[str, object]) -> None:
    name = "conversation.receive"
    if record.get("direction") == "outbound":
        name = "conversation.send"
    elif record.get("direction") == "internal":
        name = "conversation.internal"
    try:
        eve_tracing.record_span(
            OPERATIONAL_DB_PATH,
            name=name,
            category="conversation",
            started_at=record.get("timestamp"),
            duration_ms=0.0,
            ok=True,
            attributes={
                "thread_id": record.get("thread_id") or "",
                "message_id": record.get("message_id") or "",
                "role": record.get("role") or "",
                "direction": record.get("direction") or "",
                "kind": record.get("kind") or "",
                "synthetic": bool(record.get("synthetic")),
                "conversation_visible": bool(record.get("conversation_visible")),
                "source": record.get("source") or "",
            },
            trace_id_value=str(record.get("trace_id") or "") or None,
        )
    except Exception:
        return


def record_conversation_spine_turn(
    message: Dict[str, object],
    *,
    source: str = "messages",
    trace_id: str = "",
    reply_turn_replay_id: str = "",
    reply_council_turn_id: str = "",
) -> Dict[str, object]:
    record = build_conversation_spine_record(
        message,
        source=source,
        trace_id=trace_id,
        reply_turn_replay_id=reply_turn_replay_id,
        reply_council_turn_id=reply_council_turn_id,
    )
    saved = append_jsonl_record(CONVERSATION_SPINE_PATH, record)
    mirror_store_file_to_runtime(CONVERSATION_SPINE_PATH)
    record_conversation_spine_trace_span(saved)
    return saved


def record_conversation_spine_turn_safe(message: Dict[str, object], *, source: str = "messages") -> None:
    try:
        record_conversation_spine_turn(message, source=source)
    except Exception as exc:
        try:
            append_entry(
                "conversation_spine_record_error",
                f"Could not record conversation spine turn: {exc}",
                metadata={"message_id": message.get("id"), "source": source},
            )
        except Exception:
            pass


def read_conversation_spine_turns(
    *,
    limit: int = 20,
    thread_id: Optional[str] = None,
    role: Optional[str] = None,
    direction: Optional[str] = None,
    include_synthetic: bool = True,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(CONVERSATION_SPINE_PATH, prefer_runtime=prefer_runtime)
    if not path.exists():
        return []
    bounded_limit = max(1, int(limit or 20))
    scan_limit = min(2000, max(bounded_limit * 6, bounded_limit))
    records = read_jsonl_tail_records(path, scan_limit)
    normalized_thread = normalize_text_value(thread_id, fallback="", limit=160)
    normalized_role = normalize_text_value(role, fallback="", limit=80)
    normalized_direction = normalize_text_value(direction, fallback="", limit=80)
    selected: List[Dict[str, object]] = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if normalized_thread and str(record.get("thread_id") or "") != normalized_thread:
            continue
        if normalized_role and str(record.get("role") or "") != normalized_role:
            continue
        if normalized_direction and str(record.get("direction") or "") != normalized_direction:
            continue
        if not include_synthetic and bool(record.get("synthetic")):
            continue
        selected.append(record)
    selected.sort(
        key=lambda item: (
            str(item.get("timestamp") or ""),
            str(item.get("created_at") or ""),
            str(item.get("message_id") or item.get("id") or ""),
        ),
        reverse=True,
    )
    return selected[:bounded_limit]


def parse_boolish(value: object) -> bool:
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() not in {"false", "0", "no", "off"}


def parse_explicit_trueish(value: object) -> bool:
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    text = str(value or "").strip().lower()
    return text in {"true", "1", "yes", "y", "on", "ok", "verified", "success", "passed"}


def parse_explicit_boolish(value: object) -> Optional[bool]:
    """Parse only an explicit boolean signal; unknown/missing stays unknown."""
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)) and value in {0, 1}:
        return bool(value)
    text = str(value or "").strip().lower()
    if text in {"true", "1", "yes", "y", "on", "ok", "verified", "success", "passed"}:
        return True
    if text in {"false", "0", "no", "n", "off", "unverified", "failure", "failed"}:
        return False
    return None


def action_result_explicit_verification(result: Dict[str, object]) -> Optional[bool]:
    """Return the highest-authority explicit verification value.

    An execution wrapper's ``execution_verification_ok`` outranks a raw tool's
    ``verification_ok`` and both outrank ``ok``.  In particular, an explicit
    false must never be changed into success by ``ok=True`` or optimistic prose.
    """
    for key in ("execution_verification_ok", "verification_ok"):
        if key not in result:
            continue
        parsed = parse_explicit_boolish(result.get(key))
        if parsed is not None:
            return parsed
    return None


def action_result_reports_verified(result: Dict[str, object]) -> bool:
    return action_result_explicit_verification(result) is True


def maybe_limit(records: List[Dict[str, object]], limit: Optional[int]) -> List[Dict[str, object]]:
    if limit is None:
        return records
    return records[-limit:]


def append_perf_event(
    category: str,
    name: str,
    duration_ms: float,
    ok: bool = True,
    metadata: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    event = {
        "id": str(uuid.uuid4()),
        "timestamp": utc_now(),
        "category": category,
        "name": name,
        "duration_ms": round(float(duration_ms), 2),
        "ok": bool(ok),
        "metadata": metadata or {},
    }
    if private_evaluator_persistence_active():
        event["evaluator_private"] = True
        event["persisted"] = False
        return event
    record = append_jsonl_record(PERF_EVENTS_PATH, event)
    try:
        eve_db.record_perf_event(OPERATIONAL_DB_PATH, record)
        eve_tracing.record_span(
            OPERATIONAL_DB_PATH,
            name=f"{category}:{name}",
            category=category,
            started_at=record.get("timestamp"),
            duration_ms=float(record.get("duration_ms") or 0.0),
            ok=bool(record.get("ok", True)),
            attributes=record.get("metadata") if isinstance(record.get("metadata"), dict) else {},
        )
    except Exception:
        pass
    return record


def read_perf_events(
    limit: Optional[int] = None,
    since_minutes: Optional[int] = None,
    category: Optional[str] = None,
    name: Optional[str] = None,
    ok: Optional[bool] = None,
) -> List[Dict[str, object]]:
    if limit is not None and since_minutes is None and not category and not name and ok is None:
        records = read_jsonl_tail_records(PERF_EVENTS_PATH, limit)
    else:
        records = read_jsonl_records(PERF_EVENTS_PATH)
    if since_minutes is not None:
        cutoff = datetime.now(timezone.utc) - timedelta(minutes=since_minutes)
        records = [item for item in records if (parse_iso_datetime(item.get("timestamp")) or datetime.min.replace(tzinfo=timezone.utc)) >= cutoff]
    if category:
        records = [item for item in records if str(item.get("category")) == category]
    if name:
        records = [item for item in records if str(item.get("name")) == name]
    if ok is not None:
        records = [item for item in records if bool(item.get("ok")) is ok]
    return maybe_limit(records, limit)


def percentile(values: List[float], pct: float) -> float:
    if not values:
        return 0.0
    ordered = sorted(values)
    if len(ordered) == 1:
        return ordered[0]
    rank = max(0, min(len(ordered) - 1, int(round((pct / 100) * (len(ordered) - 1)))))
    return ordered[rank]


def summarize_perf_events(events: List[Dict[str, object]]) -> List[Dict[str, object]]:
    grouped: Dict[tuple[str, str], List[Dict[str, object]]] = {}
    for event in events:
        key = (str(event.get("category") or "unknown"), str(event.get("name") or "unknown"))
        grouped.setdefault(key, []).append(event)

    rows: List[Dict[str, object]] = []
    for (category, name), group in grouped.items():
        durations = [float(item.get("duration_ms") or 0.0) for item in group]
        failures = [item for item in group if not bool(item.get("ok", True))]
        rows.append(
            {
                "category": category,
                "name": name,
                "count": len(group),
                "failures": len(failures),
                "avg_ms": sum(durations) / len(durations),
                "p95_ms": percentile(durations, 95),
                "min_ms": min(durations),
                "max_ms": max(durations),
                "latest_at": group[-1].get("timestamp"),
            }
        )
    rows.sort(key=lambda item: (item["category"], -float(item["avg_ms"]), item["name"]))
    return rows


def request_json_url(url: str, timeout: int = 10, headers: Optional[Dict[str, str]] = None) -> Dict[str, object]:
    request_headers = {"Accept": "application/json"}
    if headers:
        request_headers.update(headers)
    req = request.Request(url, headers=request_headers)
    with request.urlopen(req, timeout=timeout) as resp:
        payload = json.loads(resp.read().decode("utf-8"))
    if not isinstance(payload, dict):
        raise SystemExit(f"Unexpected non-object response from {url}")
    return payload


def post_json_url(
    url: str,
    payload: Dict[str, object],
    *,
    timeout: int,
    headers: Optional[Dict[str, str]] = None,
) -> Dict[str, object]:
    request_headers = {"Accept": "application/json", "Content-Type": "application/json"}
    if headers:
        request_headers.update(headers)
    req = request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers=request_headers,
        method="POST",
    )
    try:
        with request.urlopen(req, timeout=timeout) as resp:
            body = json.loads(resp.read().decode("utf-8"))
    except error.HTTPError as exc:
        raw_body = exc.read().decode("utf-8", errors="replace")
        try:
            body = json.loads(raw_body)
        except json.JSONDecodeError as json_exc:
            raise SystemExit(f"{url} returned HTTP {exc.code}: {raw_body[:240]}") from json_exc
        if isinstance(body, dict):
            body.setdefault("_http_status", exc.code)
        else:
            raise SystemExit(f"{url} returned unexpected HTTP {exc.code} response.")
    if not isinstance(body, dict):
        raise SystemExit(f"Unexpected non-object response from {url}")
    return body


def format_perf_summary_rows(rows: List[Dict[str, object]]) -> str:
    if not rows:
        return "No matching perf events found."
    lines: List[str] = []
    for row in rows:
        lines.append(
            f"{row['category']}/{row['name']}: "
            f"count={row['count']} fail={row['failures']} "
            f"avg={float(row['avg_ms']):.1f}ms p95={float(row['p95_ms']):.1f}ms "
            f"min={float(row['min_ms']):.1f}ms max={float(row['max_ms']):.1f}ms "
            f"latest={row.get('latest_at') or 'unknown'}"
        )
    return "\n".join(lines)


def format_perf_failure_events(events: List[Dict[str, object]], limit: int = 5) -> str:
    if not events:
        return "No recent perf failures."
    lines: List[str] = []
    for event in events[-limit:]:
        metadata = event.get("metadata") if isinstance(event.get("metadata"), dict) else {}
        error_text = normalize_text_value(metadata.get("error"), fallback="unknown", limit=220)
        lines.append(
            f"{event.get('timestamp') or 'unknown'} "
            f"{event.get('category')}/{event.get('name')}: {error_text}"
        )
    return "\n".join(lines)


def probe_json_endpoint(name: str, url: str, timeout: int = 10) -> Dict[str, object]:
    started = time.perf_counter()
    metadata: Dict[str, object] = {"url": url}
    try:
        payload = request_json_url(url, timeout=timeout)
    except SystemExit as exc:
        duration_ms = (time.perf_counter() - started) * 1000
        metadata["error"] = str(exc)
        event = append_perf_event("api_probe", name, duration_ms, ok=False, metadata=metadata)
        return {**event, "payload": None}
    except Exception as exc:
        duration_ms = (time.perf_counter() - started) * 1000
        metadata["error"] = str(exc)
        event = append_perf_event("api_probe", name, duration_ms, ok=False, metadata=metadata)
        return {**event, "payload": None}

    duration_ms = (time.perf_counter() - started) * 1000
    payload_ok = payload.get("ok") is not False
    if payload.get("ok") is False and payload.get("error"):
        metadata["error"] = normalize_text_value(payload.get("error"), fallback="request_failed", limit=220)
    data = payload.get("data")
    if isinstance(data, list):
        metadata["item_count"] = len(data)
    elif isinstance(data, dict):
        metadata["keys"] = sorted(str(key) for key in data.keys())[:12]
    event = append_perf_event("api_probe", name, duration_ms, ok=payload_ok, metadata=metadata)
    return {**event, "payload": payload}


def read_tensions(limit: Optional[int] = None, status: Optional[str] = None) -> List[Dict[str, object]]:
    tensions = read_jsonl_records(TENSIONS_PATH)
