def read_experiments(limit: Optional[int] = None, status: Optional[str] = None) -> List[Dict[str, object]]:
    experiments = read_jsonl_records(EXPERIMENTS_PATH)
    if status:
        experiments = [item for item in experiments if item.get("status") == status]
