def normalize_applied_repair_status(value: object) -> str:
    status = str(value or "active").strip().lower()
    if status not in {"active", "archived"}:
        return "active"
    return status


def normalize_applied_repair(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    prompt_targets = [
        target
        for target in normalize_text_list(payload.get("prompt_targets"), limit=6)
        if target in {"reply", "proposal", "reflection", "thought"}
    ]
    guardrail_targets = normalize_text_list(payload.get("guardrail_targets"), limit=8)
    directives = normalize_text_list(payload.get("directives"), limit=6)
    cautions = normalize_text_list(payload.get("cautions"), limit=5)
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    return {
        "id": str(payload.get("id") or uuid.uuid4()),
        "created_at": str(payload.get("created_at") or utc_now()),
        "updated_at": str(payload.get("updated_at") or payload.get("created_at") or utc_now()),
        "applied_at": str(payload.get("applied_at") or payload.get("updated_at") or payload.get("created_at") or utc_now()),
        "proposal_id": normalize_text_value(payload.get("proposal_id"), fallback="", limit=80),
        "pattern_id": normalize_text_value(payload.get("pattern_id"), fallback="", limit=80),
        "title": normalize_text_value(payload.get("title"), fallback="Applied repair", limit=180),
        "summary": normalize_text_value(payload.get("summary"), fallback="No summary.", limit=240),
        "status": normalize_applied_repair_status(payload.get("status")),
        "prompt_targets": prompt_targets,
        "guardrail_targets": guardrail_targets,
        "directives": directives,
        "cautions": cautions,
        "source": normalize_text_value(payload.get("source"), fallback="manual", limit=80),
        "metadata": metadata,
    }


def read_applied_repairs(
    limit: Optional[int] = None,
    status: Optional[str] = "active",
    prompt_target: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(APPLIED_REPAIRS_PATH, prefer_runtime=prefer_runtime)
    records = [normalize_applied_repair(item) for item in read_jsonl_records(path)]
    if status:
        records = [item for item in records if item.get("status") == status]
    if prompt_target:
        records = [item for item in records if prompt_target in (item.get("prompt_targets") or [])]
    records.sort(key=lambda item: str(item.get("updated_at") or item.get("created_at") or ""), reverse=True)
    if limit is not None:
        return records[:limit]
    return records


def upsert_applied_repair(payload: Dict[str, object]) -> tuple[Dict[str, object], bool, bool]:
    record = normalize_applied_repair(payload)
    with store_lock(APPLIED_REPAIRS_PATH):
        records = [normalize_applied_repair(item) for item in read_jsonl_records(APPLIED_REPAIRS_PATH)]
        existing_index = None
        proposal_id = str(record.get("proposal_id") or "")
        for index in range(len(records) - 1, -1, -1):
            if str(records[index].get("proposal_id") or "") == proposal_id and proposal_id:
                existing_index = index
                break
        if existing_index is None:
            records.append(record)
            write_jsonl_records(APPLIED_REPAIRS_PATH, records)
            mirror_store_file_to_runtime(APPLIED_REPAIRS_PATH)
            return record, True, True
        existing = records[existing_index]
        merged = normalize_applied_repair({**existing, **record, "id": existing["id"], "created_at": existing["created_at"], "updated_at": utc_now()})
        if merged == existing:
            return existing, False, False
        records[existing_index] = merged
        write_jsonl_records(APPLIED_REPAIRS_PATH, records)
    mirror_store_file_to_runtime(APPLIED_REPAIRS_PATH)
    return merged, False, True


def read_messages(
    limit: Optional[int] = None,
    sender: Optional[str] = None,
    recipient: Optional[str] = None,
    status: Optional[str] = None,
    thread_id: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    changed = False
    read_path = resolve_store_read_path(MESSAGES_PATH, prefer_runtime=prefer_runtime)
    if limit is not None and not sender and not recipient and not status and not thread_id:
        messages, _ = normalize_message_records(read_jsonl_tail_records(read_path, limit))
        return messages[-limit:]
    if read_path != MESSAGES_PATH:
        messages, _ = normalize_message_records(read_jsonl_records(read_path))
    else:
        try:
            with store_lock(MESSAGES_PATH):
                messages, changed = normalize_message_records(read_jsonl_records(MESSAGES_PATH))
                if changed:
                    write_jsonl_records(MESSAGES_PATH, messages)
        except PermissionError:
            if not prefer_runtime:
                raise
            messages, _ = normalize_message_records(read_jsonl_records(MESSAGES_PATH))
    if changed and read_path == MESSAGES_PATH:
        mirror_store_file_to_runtime(MESSAGES_PATH)
    if sender:
        messages = [item for item in messages if item.get("sender") == sender]
    if recipient:
        messages = [item for item in messages if item.get("recipient") == recipient]
    if status:
        messages = [item for item in messages if item.get("status") == status]
    if thread_id:
        messages = [item for item in messages if item.get("thread_id") == thread_id]
    return maybe_limit(messages, limit)


def read_lived_messages(
    limit: int,
    *,
    prefer_runtime: bool = False,
    scan_multiplier: int = 4,
) -> List[Dict[str, object]]:
    """Return human-lived turns for cognition, excluding eval and daemon noise."""
    bounded_limit = max(1, int(limit or 1))
    messages = read_messages(
        limit=max(bounded_limit, bounded_limit * max(1, int(scan_multiplier or 1))),
        prefer_runtime=prefer_runtime,
    )
    return [
        item
        for item in messages
        if not conversation_message_is_synthetic(item) and not message_is_background_context(item)
    ][-bounded_limit:]


def short_id(value: object, length: int = 8) -> str:
    text = str(value or "").strip()
    return text[:length] if text else "unknown"


def valid_score_value(value: object) -> Optional[int]:
    try:
        score = int(value)
    except (TypeError, ValueError):
        return None
    if 1 <= score <= 5:
        return score
    return None


def format_score_average(value: Optional[float]) -> str:
    if value is None:
        return "n/a"
    return f"{value:.1f}/5"


def scorecard_from_record(record: Dict[str, object]) -> Dict[str, int]:
    payload = record.get("scorecard") if isinstance(record.get("scorecard"), dict) else {}
    normalized: Dict[str, int] = {}
    for field in SCORECARD_FIELDS:
        score = valid_score_value(payload.get(field))
        if score is not None:
            normalized[field] = score
    return normalized


def format_scorecard(scorecard: Dict[str, int]) -> str:
    chunks = []
    for field in SCORECARD_FIELDS:
        score = scorecard.get(field)
        if score is None:
            continue
        chunks.append(f"{SCORECARD_LABELS[field]} {score}/5")
    return " | ".join(chunks) if chunks else "No scorecard recorded."


def filter_records_by_days(
    records: List[Dict[str, object]],
    timestamp_field: str,
    since_days: Optional[int],
) -> List[Dict[str, object]]:
    if since_days is None:
        return records
    cutoff = datetime.now(timezone.utc) - timedelta(days=since_days)
    filtered: List[Dict[str, object]] = []
    for record in records:
        record_dt = parse_iso_datetime(record.get(timestamp_field))
        if record_dt is None or record_dt >= cutoff:
            filtered.append(record)
    return filtered


