    payload = payload or {}
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    return {
        "id": str(payload.get("id") or uuid.uuid4()),
        "created_at": str(payload.get("created_at") or utc_now()),
        "updated_at": str(payload.get("updated_at") or payload.get("created_at") or utc_now()),
        "source": normalize_text_value(payload.get("source"), fallback="reply", limit=80),
        "thread_id": normalize_text_value(payload.get("thread_id"), fallback="", limit=80),
        "source_message_id": normalize_text_value(payload.get("source_message_id"), fallback="", limit=80),
        "reply_message_id": normalize_text_value(payload.get("reply_message_id"), fallback="", limit=80),
        "reply_posture": normalize_text_value(payload.get("reply_posture"), fallback="general", limit=40),
        "route_profile": normalize_text_value(payload.get("route_profile"), fallback="user_general", limit=40),
        "route_reason": normalize_text_value(payload.get("route_reason"), fallback="", limit=220),
        "uncertainty_kinds": normalize_text_list(payload.get("uncertainty_kinds"), limit=6),
        "summary": normalize_text_value(payload.get("summary"), fallback="Eve encountered uncertainty.", limit=220),
        "why_it_matters": normalize_text_value(payload.get("why_it_matters"), fallback="", limit=240),
        "suggested_followup": normalize_text_value(payload.get("suggested_followup"), fallback="", limit=220),
        "signals": normalize_text_list(payload.get("signals"), limit=8),
        "status": normalize_uncertainty_status(payload.get("status")),
        "resolution_summary": normalize_text_value(payload.get("resolution_summary"), fallback="", limit=220),
        "linked_evaluation_ids": normalize_text_list(payload.get("linked_evaluation_ids"), limit=12),
        "linked_outcome_ids": normalize_text_list(payload.get("linked_outcome_ids"), limit=12),
        "metadata": metadata,
    }


