def uncertainty_record_is_material(payload: Optional[Dict[str, object]]) -> bool:
    """Return whether an uncertainty deserves durable control pressure.

    A short turn, a multi-question turn, or a heuristic route is ordinary
    ambiguity.  Persisting each occurrence made routine conversation look like
    hundreds of unresolved epistemic failures.  Material uncertainty requires
    an additional failure/contradiction kind such as stream divergence,
    recovery, a routing-contract failure, or another explicitly named signal.
    """
    record = normalize_uncertainty_record(payload)
    kinds = {
        normalize_text_value(item, fallback="", limit=80).lower()
        for item in record.get("uncertainty_kinds") or []
        if normalize_text_value(item, fallback="", limit=80)
    }
    return bool(kinds - ROUTINE_UNCERTAINTY_KINDS)


def judgment_call_is_material(payload: Optional[Dict[str, object]]) -> bool:
    """Return whether a judgment represents a real choice worth carrying.

    Generic response shaping and tone selection happen on almost every reply;
    they are execution traces, not unresolved judgments.  Durable judgment
    records are reserved for repair, intent conflicts, clarity repair, or
    genuinely divergent multi-signal synthesis.
    """
    record = normalize_judgment_call(payload)
    decision_type = normalize_text_value(
        record.get("decision_type"), fallback="", limit=80
    ).lower()
    return decision_type in MATERIAL_JUDGMENT_TYPES


def self_learning_record_attention_expired(
    payload: Optional[Dict[str, object]],
    *,
    max_age_hours: float = SELF_LEARNING_PENDING_MAX_AGE_HOURS,
) -> bool:
    """Return whether an unresolved learning trace has left active attention.

    The durable ledger remains intact, but a record without linked consequence
    cannot occupy Eve's recurrent working state forever.  This is an attention
    timeout, not evidence that the original uncertainty was resolved.
    """
    record = payload or {}
    moment = parse_iso_datetime(record.get("updated_at") or record.get("created_at"))
    if moment is None:
        return False
    age_hours = max(0.0, (utc_now_datetime() - moment).total_seconds() / 3600.0)
    return age_hours > max(1.0, float(max_age_hours or 1.0))


def _working_set_sort_key(record: Dict[str, object]) -> str:
    return normalize_text_value(
        record.get("updated_at") or record.get("created_at"),
        fallback="",
        limit=80,
    )


def active_pending_uncertainty_records(
    records: Iterable[Dict[str, object]],
    *,
    limit: int = SELF_LEARNING_WORKING_SET_LIMIT,
) -> List[Dict[str, object]]:
    """Project the durable uncertainty ledger into a bounded working set."""
    candidates = [
        normalize_uncertainty_record(item)
        for item in records
        if isinstance(item, dict)
        and normalize_uncertainty_status(item.get("status")) == "pending"
        and uncertainty_record_is_material(item)
        and not self_learning_record_attention_expired(item)
    ]
    candidates.sort(key=_working_set_sort_key, reverse=True)
    unique: List[Dict[str, object]] = []
    seen: set[tuple[object, ...]] = set()
    for record in candidates:
        signature = (
            record.get("source"),
            record.get("thread_id"),
            tuple(record.get("uncertainty_kinds") or []),
            record.get("summary"),
        )
        if signature in seen:
            continue
        seen.add(signature)
        unique.append(record)
        if len(unique) >= max(1, int(limit or 1)):
            break
    return unique


def active_pending_judgment_calls(
    records: Iterable[Dict[str, object]],
    *,
    limit: int = SELF_LEARNING_WORKING_SET_LIMIT,
) -> List[Dict[str, object]]:
    """Project the durable judgment ledger into a bounded working set."""
    candidates = [
        normalize_judgment_call(item)
        for item in records
        if isinstance(item, dict)
        and normalize_judgment_call_status(item.get("status")) == "pending"
        and judgment_call_is_material(item)
        and not self_learning_record_attention_expired(item)
    ]
    candidates.sort(key=_working_set_sort_key, reverse=True)
    unique: List[Dict[str, object]] = []
    seen: set[tuple[object, ...]] = set()
    for record in candidates:
        signature = (
            record.get("source"),
            record.get("thread_id"),
            record.get("decision_type"),
            record.get("summary"),
        )
        if signature in seen:
            continue
        seen.add(signature)
        unique.append(record)
        if len(unique) >= max(1, int(limit or 1)):
            break
    return unique


