def markdown_sections(text: str) -> Dict[str, str]:
    sections: Dict[str, List[str]] = {}
    current: Optional[str] = None
    for raw_line in str(text or "").splitlines():
        line = raw_line.rstrip()
        if line.startswith("## "):
            current = line[3:].strip().lower()
            sections.setdefault(current, [])
            continue
        if line.startswith("# "):
            current = None
            continue
        if current is not None:
            sections.setdefault(current, []).append(raw_line)
    return {key: "\n".join(value).strip() for key, value in sections.items()}


def markdown_bullets(section_text: str, limit: int = 5) -> List[str]:
    items: List[str] = []
    for raw_line in str(section_text or "").splitlines():
        line = raw_line.strip()
        if line.startswith(("- ", "* ")):
            items.append(line[2:].strip())
        elif re.match(r"^\d+\.\s+", line):
            items.append(re.sub(r"^\d+\.\s+", "", line).strip())
    return unique_compact(items, limit=limit)


def parse_review_note_body(body: str) -> Dict[str, object]:
    sections = markdown_sections(body)
    summary = normalize_text_value(
        sections.get("summary") or sections.get("overview") or body,
        fallback="Not enough evidence yet.",
        limit=360,
    )
    return {
        "summary": summary,
        "preserve": markdown_bullets(sections.get("preserve", "")),
        "weak_spots": markdown_bullets(sections.get("weak spots", "")),
        "repairs": markdown_bullets(sections.get("upstream repairs", "")),
        "experiments": markdown_bullets(sections.get("next experiments", "")),
    }


def format_review_notes(notes: Iterable[Dict[str, object]]) -> str:
    chunks: List[str] = []
    for note in notes:
        preserve = "; ".join(note.get("preserve", [])[:2]) if isinstance(note.get("preserve"), list) else ""
        repairs = "; ".join(note.get("repairs", [])[:2]) if isinstance(note.get("repairs"), list) else ""
        extras = []
        if preserve:
            extras.append(f"preserve: {preserve}")
        if repairs:
            extras.append(f"repairs: {repairs}")
        extra_text = " | " + " | ".join(extras) if extras else ""
        chunks.append(
            f"- {note.get('created_at')} [{note.get('reviewer') or 'reviewer'}] {note.get('summary')}{extra_text}"
        )
    return "\n".join(chunks) if chunks else "- No reviewer notes recorded."


def build_reviewer_guidance_message(notes: List[Dict[str, object]]) -> str:
    return textwrap.dedent(
        f"""
        Recent outside reviewer guidance:
        {format_review_notes(notes)}

        Treat this as outside audit from one or more stronger or more detached reviewers.
        Preserve what repeated outside review says is working unless newer evidence contradicts it.
        Prefer upstream repairs over cosmetic rewrites.
        """
    ).strip()


def reviewer_guidance_system_message(limit: int = 3, since_days: int = 120) -> Optional[Dict[str, str]]:
    notes = list(reversed(read_review_notes(limit=limit, status="active", since_days=since_days)))
    if not notes:
        return None
    return {"role": "system", "content": build_reviewer_guidance_message(notes)}


def normalize_success_pattern_status(value: object) -> str:
    normalized = " ".join(str(value or "").lower().split()).strip() or "active"
    if normalized not in SUCCESS_PATTERN_STATUSES:
        return "active"
    return normalized


def clamp_success_pattern_confidence(value: object, fallback: float = 0.7) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return fallback
    return max(0.0, min(1.0, number))


def success_pattern_dedupe_key(title: object, situation: object = "") -> str:
    title_text = normalize_text_value(title, fallback="", limit=180).lower()
    situation_text = normalize_text_value(situation, fallback="", limit=140).lower()
    if not title_text and not situation_text:
        return ""
    digest = sha256_text(f"{title_text}||{situation_text}")[:12]
    return f"{reviewer_token(title_text[:60], fallback='pattern')}-{digest}"


def normalize_success_pattern(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    metadata = payload.get("metadata") if isinstance(payload.get("metadata"), dict) else {}
    title = normalize_text_value(
        payload.get("title") or payload.get("good_move"),
        fallback="Useful success pattern",
        limit=160,
    )
    situation = normalize_text_value(
        payload.get("situation"),
        fallback="When the current situation resembles the supporting evidence.",
        limit=220,
    )
    good_move = normalize_text_value(
        payload.get("good_move") or title,
        fallback=title,
        limit=220,
    )
    summary = normalize_text_value(payload.get("summary") or good_move, fallback=title, limit=280)
    source_kinds = normalize_text_list(payload.get("source_kinds"), limit=8)
    source_ids = normalize_text_list(payload.get("source_ids"), limit=20)
    target_kinds = normalize_text_list(payload.get("target_kinds"), limit=8)
    cues = normalize_text_list(payload.get("cues"), limit=5)
    avoid_when = normalize_text_list(payload.get("avoid_when"), limit=5)
    evidence = normalize_text_list(payload.get("evidence"), limit=6)
    contradictions = normalize_text_list(payload.get("contradictions"), limit=4)
    support_count = max(int(payload.get("support_count") or 0), len(source_ids) or len(source_kinds) or 1)
    reinforcement_count = max(int(payload.get("reinforcement_count") or 0), support_count)
    contradiction_count = max(int(payload.get("contradiction_count") or 0), len(contradictions))
    return {
        "id": str(payload.get("id") or uuid.uuid4()),
        "created_at": str(payload.get("created_at") or utc_now()),
        "updated_at": str(payload.get("updated_at") or payload.get("created_at") or utc_now()),
        "last_seen_at": str(payload.get("last_seen_at") or payload.get("updated_at") or payload.get("created_at") or utc_now()),
        "last_reinforced_at": str(payload.get("last_reinforced_at") or payload.get("last_seen_at") or payload.get("updated_at") or payload.get("created_at") or utc_now()),
        "last_contradicted_at": str(payload.get("last_contradicted_at") or ""),
        "status": normalize_success_pattern_status(payload.get("status")),
        "title": title,
        "summary": summary,
        "situation": situation,
        "good_move": good_move,
        "why_it_worked": normalize_text_value(payload.get("why_it_worked"), fallback="", limit=280),
        "cues": cues,
        "avoid_when": avoid_when,
        "evidence": evidence,
        "contradictions": contradictions,
        "source_kinds": source_kinds,
        "source_ids": source_ids,
        "target_kinds": target_kinds,
        "support_count": support_count,
        "reinforcement_count": reinforcement_count,
        "contradiction_count": contradiction_count,
        "confidence": clamp_success_pattern_confidence(payload.get("confidence"), fallback=0.7),
        "dedupe_key": normalize_text_value(
            payload.get("dedupe_key"),
            fallback=success_pattern_dedupe_key(title, situation),
            limit=120,
        ),
        "metadata": metadata,
    }


def success_pattern_status_for_counts(
    confidence: float,
    reinforcement_count: int,
    contradiction_count: int,
    current_status: str,
) -> str:
    if current_status in {"archived", "superseded"}:
        return current_status
    if confidence < 0.35 and contradiction_count >= max(2, reinforcement_count):
        return "superseded"
    return "active"


def merge_success_patterns(existing: Dict[str, object], incoming: Dict[str, object]) -> Dict[str, object]:
    merged = dict(existing)
    previous_source_ids = {str(item) for item in existing.get("source_ids") or [] if str(item).strip()}
    incoming_source_ids = [str(item) for item in incoming.get("source_ids") or [] if str(item).strip()]
    new_support_ids = [item for item in incoming_source_ids if item not in previous_source_ids]
    merged["last_seen_at"] = max(
        str(existing.get("last_seen_at") or ""),
        str(incoming.get("last_seen_at") or ""),
    ) or str(existing.get("updated_at") or incoming.get("updated_at") or utc_now())
    if new_support_ids:
        merged["last_reinforced_at"] = str(incoming.get("last_seen_at") or incoming.get("updated_at") or utc_now())
    else:
        merged["last_reinforced_at"] = str(existing.get("last_reinforced_at") or existing.get("last_seen_at") or merged["last_seen_at"])
    merged["last_contradicted_at"] = str(existing.get("last_contradicted_at") or "")
    merged["title"] = incoming["title"] if len(str(incoming.get("title") or "")) > len(str(existing.get("title") or "")) else existing["title"]
    merged["summary"] = incoming["summary"] if len(str(incoming.get("summary") or "")) > len(str(existing.get("summary") or "")) else existing["summary"]
    merged["situation"] = incoming["situation"] if len(str(incoming.get("situation") or "")) > len(str(existing.get("situation") or "")) else existing["situation"]
    merged["good_move"] = incoming["good_move"] if len(str(incoming.get("good_move") or "")) > len(str(existing.get("good_move") or "")) else existing["good_move"]
    merged["why_it_worked"] = incoming["why_it_worked"] if len(str(incoming.get("why_it_worked") or "")) > len(str(existing.get("why_it_worked") or "")) else existing["why_it_worked"]
    merged["cues"] = unique_compact([*(existing.get("cues") or []), *(incoming.get("cues") or [])], limit=5)
    merged["avoid_when"] = unique_compact([*(existing.get("avoid_when") or []), *(incoming.get("avoid_when") or [])], limit=5)
    merged["evidence"] = unique_compact([*(existing.get("evidence") or []), *(incoming.get("evidence") or [])], limit=6)
    merged["contradictions"] = unique_compact([*(existing.get("contradictions") or []), *(incoming.get("contradictions") or [])], limit=4)
    merged["source_kinds"] = unique_compact([*(existing.get("source_kinds") or []), *(incoming.get("source_kinds") or [])], limit=8)
    merged["source_ids"] = unique_compact([*(existing.get("source_ids") or []), *(incoming.get("source_ids") or [])], limit=20)
    merged["target_kinds"] = unique_compact([*(existing.get("target_kinds") or []), *(incoming.get("target_kinds") or [])], limit=8)
    merged["support_count"] = max(
        int(existing.get("support_count") or 0),
        int(incoming.get("support_count") or 0),
        len(merged["source_ids"]) or len(merged["source_kinds"]) or 1,
    )
    merged["reinforcement_count"] = max(
        int(existing.get("reinforcement_count") or 0) + len(new_support_ids),
        int(incoming.get("reinforcement_count") or 0),
        int(merged["support_count"] or 1),
    )
    merged["contradiction_count"] = max(
        int(existing.get("contradiction_count") or 0),
        int(incoming.get("contradiction_count") or 0),
        len(merged["contradictions"]) or 0,
    )
    merged["confidence"] = max(
        clamp_success_pattern_confidence(existing.get("confidence"), fallback=0.7),
        clamp_success_pattern_confidence(incoming.get("confidence"), fallback=0.7),
    )
    if new_support_ids:
        merged["confidence"] = clamp_success_pattern_confidence(merged["confidence"] + 0.04 * len(new_support_ids), fallback=0.7)
    merged["status"] = success_pattern_status_for_counts(
        confidence=merged["confidence"],
        reinforcement_count=int(merged.get("reinforcement_count") or 0),
        contradiction_count=int(merged.get("contradiction_count") or 0),
        current_status=str(existing.get("status") or incoming.get("status") or "active"),
    )
    merged["metadata"] = {
        **(existing.get("metadata") if isinstance(existing.get("metadata"), dict) else {}),
        **(incoming.get("metadata") if isinstance(incoming.get("metadata"), dict) else {}),
    }
    return normalize_success_pattern(merged)


def upsert_success_pattern(payload: Dict[str, object]) -> tuple[Dict[str, object], bool, bool]:
    record = normalize_success_pattern(payload)
    with store_lock(SUCCESS_PATTERNS_PATH):
        records = [normalize_success_pattern(item) for item in read_jsonl_records(SUCCESS_PATTERNS_PATH)]
        existing_index = None
        previous_pattern: Optional[Dict[str, object]] = None
        dedupe_key = str(record.get("dedupe_key") or "").strip()
        if dedupe_key:
            for index in range(len(records) - 1, -1, -1):
                existing = records[index]
                if existing.get("dedupe_key") == dedupe_key:
                    existing_index = index
                    previous_pattern = existing
                    break
        if existing_index is None:
            records.append(record)
            write_jsonl_records(SUCCESS_PATTERNS_PATH, records)
            return record, True, True
        merged = merge_success_patterns(previous_pattern or {}, record)
        merged["id"] = str(previous_pattern["id"]) if previous_pattern else merged["id"]
        merged["created_at"] = str(previous_pattern["created_at"]) if previous_pattern else merged["created_at"]
        if merged == previous_pattern:
            return previous_pattern, False, False
        merged["updated_at"] = utc_now()
        records[existing_index] = merged
        write_jsonl_records(SUCCESS_PATTERNS_PATH, records)
        return merged, False, True


def read_success_patterns(
    limit: Optional[int] = None,
    status: Optional[str] = "active",
    since_days: Optional[int] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(SUCCESS_PATTERNS_PATH, prefer_runtime=prefer_runtime)
    records = [
        normalize_success_pattern(item)
        for item in filter_records_by_days(read_jsonl_records(path), "updated_at", since_days)
    ]
    if status:
        records = [item for item in records if item.get("status") == status]
    records.sort(
        key=lambda item: (
            clamp_success_pattern_confidence(item.get("confidence"), fallback=0.0),
            int(item.get("support_count") or 0),
            str(item.get("updated_at") or ""),
        ),
        reverse=True,
    )
    if limit is not None:
        return records[:limit]
    return records


def find_success_pattern(pattern_id: str) -> Optional[Dict[str, object]]:
    pattern_id = str(pattern_id or "").strip()
    if not pattern_id:
        return None
    records = [normalize_success_pattern(item) for item in read_jsonl_records(SUCCESS_PATTERNS_PATH)]
    for pattern in reversed(records):
        if str(pattern.get("id") or "") == pattern_id:
            return pattern
    return None


def update_success_pattern_record(pattern_id: str, **changes: object) -> Dict[str, object]:
    with store_lock(SUCCESS_PATTERNS_PATH):
        records = [normalize_success_pattern(item) for item in read_jsonl_records(SUCCESS_PATTERNS_PATH)]
        index = find_record_index(records, pattern_id)
        pattern = dict(records[index])
        pattern.update(changes)
        pattern["updated_at"] = utc_now()
        pattern = normalize_success_pattern(pattern)
        records[index] = pattern
        write_jsonl_records(SUCCESS_PATTERNS_PATH, records)
    mirror_store_file_to_runtime(SUCCESS_PATTERNS_PATH)
    return pattern


def format_success_pattern(pattern: Dict[str, object], full: bool = False) -> str:
    sources = ", ".join(pattern.get("source_kinds") or []) or "none"
    targets = ", ".join(pattern.get("target_kinds") or []) or "general"
    lines = [
        f"{pattern.get('id')} [{pattern.get('status')}] {pattern.get('title')}",
        "confidence: "
        f"{clamp_success_pattern_confidence(pattern.get('confidence'), fallback=0.0):.2f}"
        f" | supports: {pattern.get('support_count') or 1}"
        f" | reinforcements: {pattern.get('reinforcement_count') or pattern.get('support_count') or 1}"
        f" | contradictions: {pattern.get('contradiction_count') or 0}"
        f" | sources: {sources}",
        f"targets: {targets} | updated_at: {pattern.get('updated_at')}",
        f"situation: {pattern.get('situation')}",
        f"good_move: {pattern.get('good_move')}",
    ]
    if pattern.get("why_it_worked"):
        lines.append(f"why: {pattern.get('why_it_worked')}")
    if pattern.get("last_reinforced_at"):
        lines.append(f"last_reinforced_at: {pattern.get('last_reinforced_at')}")
    if pattern.get("last_contradicted_at"):
        lines.append(f"last_contradicted_at: {pattern.get('last_contradicted_at')}")
    if pattern.get("cues"):
        lines.append(f"cues: {'; '.join(pattern['cues'])}")
    if pattern.get("avoid_when"):
        lines.append(f"avoid_when: {'; '.join(pattern['avoid_when'])}")
    if full and pattern.get("evidence"):
        lines.append(f"evidence: {'; '.join(pattern['evidence'])}")
    if full and pattern.get("contradictions"):
        lines.append(f"contradictions: {'; '.join(pattern['contradictions'])}")
    return "\n".join(lines)


def format_success_patterns(patterns: Iterable[Dict[str, object]]) -> str:
    chunks: List[str] = []
    for pattern in patterns:
        reason = normalize_text_value(pattern.get("why_it_worked"), fallback="", limit=120)
        contradictions = int(pattern.get("contradiction_count") or 0)
        contradiction_tail = f" | contradictions: {contradictions}" if contradictions else ""
        tail = f" | why: {reason}" if reason else ""
        chunks.append(
            f"- {pattern.get('title')} | move: {pattern.get('good_move')} | situation: {pattern.get('situation')} | supports: {pattern.get('support_count') or 1}{contradiction_tail}{tail}"
        )
    return "\n".join(chunks) if chunks else "- No durable success patterns recorded."


def build_success_pattern_context_message(patterns: List[Dict[str, object]]) -> str:
    return textwrap.dedent(
        f"""
        Durable success patterns:
        {format_success_patterns(patterns)}

        Treat these as behaviors that have worked repeatedly or were explicitly marked worth preserving.
        Reuse them when the situation genuinely matches the evidence, but do not turn them into rigid scripts.
        """
    ).strip()


def success_patterns_system_message(
    limit: int = 4,
    since_days: int = 365,
    prefer_runtime: bool = False,
) -> Optional[Dict[str, str]]:
    patterns = read_success_patterns(limit=limit, status="active", since_days=since_days, prefer_runtime=prefer_runtime)
    if not patterns:
        return None
    return {"role": "system", "content": build_success_pattern_context_message(patterns)}


def generic_positive_outcome_summary(summary: str) -> bool:
    lower = summary.lower()
    return any(
        phrase in lower
        for phrase in [
            "user replied after eve's previous message",
            "message was archived by the user",
            "archived by the user",
        ]
    )


def extract_success_patterns_from_evaluation(evaluation: Dict[str, object]) -> List[Dict[str, object]]:
    scorecard = scorecard_from_record(evaluation)
    if not scorecard:
        return []
    scores = [float(value) for value in scorecard.values() if value is not None]
    if not scores:
        return []
    overall = sum(scores) / len(scores)
    if overall < 4.0 or float(scorecard.get("integrity") or 0.0) < 4.0:
        return []
    if min(scores) < 4.0:
        return []
    summary = normalize_text_value(evaluation.get("summary"), fallback="", limit=180)
    evidence = normalize_text_value(evaluation.get("evidence"), fallback="", limit=220)
    if not summary and not evidence:
        return []
    target_kind = normalize_text_value(evaluation.get("target_kind"), fallback="interaction", limit=60)
    good_move = summary or evidence
    why = evidence or f"Strong evaluation on {target_kind}: {format_scorecard(scorecard)}."
    return [
        {
            "created_at": str(evaluation.get("created_at") or evaluation.get("updated_at") or utc_now()),
            "updated_at": str(evaluation.get("updated_at") or evaluation.get("created_at") or utc_now()),
            "last_seen_at": str(evaluation.get("updated_at") or evaluation.get("created_at") or utc_now()),
            "title": good_move,
            "summary": good_move,
            "situation": f"When handling {target_kind} work with a similar need.",
            "good_move": good_move,
            "why_it_worked": why,
            "evidence": [summary, evidence],
            "source_kinds": ["evaluation"],
            "source_ids": [str(evaluation.get("id") or "")],
            "target_kinds": [target_kind],
            "confidence": overall / 5.0,
            "metadata": {
                "evaluator": evaluation.get("evaluator"),
                "scorecard": scorecard,
            },
        }
    ]


def extract_success_patterns_from_outcome(outcome: Dict[str, object]) -> List[Dict[str, object]]:
    if str(outcome.get("direction") or "") != "positive":
        return []
    summary = normalize_text_value(outcome.get("summary"), fallback="", limit=200)
    evidence = normalize_text_value(outcome.get("evidence"), fallback="", limit=220)
    if not summary or generic_positive_outcome_summary(summary):
        return []
    target_kind = normalize_text_value(outcome.get("target_kind"), fallback="interaction", limit=60)
    return [
        {
            "created_at": str(outcome.get("created_at") or outcome.get("updated_at") or utc_now()),
            "updated_at": str(outcome.get("updated_at") or outcome.get("created_at") or utc_now()),
            "last_seen_at": str(outcome.get("updated_at") or outcome.get("created_at") or utc_now()),
            "title": summary,
            "summary": summary,
            "situation": f"When acting on {target_kind} work where the same need is present.",
            "good_move": summary,
            "why_it_worked": evidence or f"This contributed to a positive outcome: {outcome.get('outcome') or 'positive signal'}.",
            "evidence": [summary, evidence],
            "source_kinds": ["outcome"],
            "source_ids": [str(outcome.get("id") or "")],
            "target_kinds": [target_kind],
            "confidence": 0.74,
            "metadata": {
                "outcome": outcome.get("outcome"),
                "thread_id": outcome.get("thread_id"),
            },
        }
    ]


def extract_success_patterns_from_review_note(note: Dict[str, object]) -> List[Dict[str, object]]:
    preserve_items = note.get("preserve") if isinstance(note.get("preserve"), list) else []
    if not preserve_items:
        return []
    summary = normalize_text_value(note.get("summary"), fallback="Outside review flagged this as worth preserving.", limit=220)
    reviewer = normalize_reviewer_name(note.get("reviewer"), fallback="Reviewer")
    patterns: List[Dict[str, object]] = []
    for preserve in preserve_items[:6]:
        move = normalize_text_value(preserve, fallback="", limit=200)
        if not move:
            continue
        patterns.append(
            {
                "created_at": str(note.get("created_at") or note.get("updated_at") or utc_now()),
                "updated_at": str(note.get("updated_at") or note.get("created_at") or utc_now()),
                "last_seen_at": str(note.get("updated_at") or note.get("created_at") or utc_now()),
                "title": move,
                "summary": move,
                "situation": summary,
                "good_move": move,
                "why_it_worked": f"{reviewer} explicitly said to preserve this.",
                "evidence": [summary, move],
                "source_kinds": ["review_note"],
                "source_ids": [str(note.get("id") or "")],
                "confidence": 0.95,
                "metadata": {
                    "reviewer": reviewer,
                    "packet_id": note.get("packet_id"),
                },
            }
        )
    return patterns


def success_pattern_target_matches(pattern: Dict[str, object], target_kind: str) -> bool:
    targets = [str(item).strip().lower() for item in pattern.get("target_kinds") or [] if str(item).strip()]
    normalized_target = str(target_kind or "").strip().lower() or "general"
    if not targets or "general" in targets:
        return True
    return normalized_target in targets


def success_pattern_match_score(pattern: Dict[str, object], text: str, target_kind: str) -> int:
    if not success_pattern_target_matches(pattern, target_kind):
        return 0
    blob = " ".join(
        [
            str(pattern.get("title") or ""),
            str(pattern.get("summary") or ""),
            str(pattern.get("good_move") or ""),
            str(pattern.get("why_it_worked") or ""),
            str(pattern.get("situation") or ""),
            " ".join(pattern.get("evidence") or []),
        ]
    )
    pattern_tokens = set(significant_tokens(blob))
    text_tokens = set(significant_tokens(text))
    if not pattern_tokens or not text_tokens:
        return 0
    return len(pattern_tokens & text_tokens)


def pattern_decay_entry_id(source_kind: str, record_id: str) -> str:
    return f"{source_kind}:{record_id}"


def should_decay_from_evaluation(evaluation: Dict[str, object]) -> bool:
    scorecard = scorecard_from_record(evaluation)
    if not scorecard:
        return False
    scores = [float(value) for value in scorecard.values() if value is not None]
    if not scores:
        return False
    overall = sum(scores) / len(scores)
    return overall < 3.8 or any(float(value) <= 3.0 for value in scores)


def evaluation_decay_delta(evaluation: Dict[str, object]) -> float:
    scorecard = scorecard_from_record(evaluation)
    if not scorecard:
        return 0.08
    scores = [float(value) for value in scorecard.values() if value is not None]
    if not scores:
        return 0.08
    overall = sum(scores) / len(scores)
    if overall <= 3.0:
        return 0.18
    if any(float(value) <= 2.0 for value in scores):
        return 0.16
    if any(float(value) <= 3.0 for value in scores):
        return 0.12
    return 0.08


def outcome_decay_delta(outcome: Dict[str, object]) -> float:
    direction = str(outcome.get("direction") or "neutral")
    if direction == "negative":
        return 0.16
    if direction == "mixed":
        return 0.10
    return 0.0


def update_success_pattern_decay(
    pattern: Dict[str, object],
    *,
    source_kind: str,
    source_id: str,
    note: str,
    delta: float,
) -> Dict[str, object]:
    metadata = dict(pattern.get("metadata") if isinstance(pattern.get("metadata"), dict) else {})
    contradicted_ids = normalize_text_list(metadata.get("contradicted_source_ids"), limit=40)
    contradiction_key = pattern_decay_entry_id(source_kind, source_id)
    if contradiction_key in contradicted_ids:
        return pattern
    contradicted_ids = unique_compact([*contradicted_ids, contradiction_key], limit=40)
    contradiction_count = int(pattern.get("contradiction_count") or 0) + 1
    reinforcement_count = int(pattern.get("reinforcement_count") or pattern.get("support_count") or 1)
    confidence = clamp_success_pattern_confidence(pattern.get("confidence"), fallback=0.7)
    updated_confidence = clamp_success_pattern_confidence(confidence - delta, fallback=0.7)
    contradictions = unique_compact([*(pattern.get("contradictions") or []), note], limit=4)
    avoid_when = unique_compact([*(pattern.get("avoid_when") or []), note], limit=5)
    updated = {
        **pattern,
        "updated_at": utc_now(),
        "last_contradicted_at": utc_now(),
        "contradiction_count": contradiction_count,
        "contradictions": contradictions,
        "avoid_when": avoid_when,
        "confidence": updated_confidence,
        "status": success_pattern_status_for_counts(
            confidence=updated_confidence,
            reinforcement_count=reinforcement_count,
            contradiction_count=contradiction_count,
            current_status=str(pattern.get("status") or "active"),
        ),
        "metadata": {
            **metadata,
            "contradicted_source_ids": contradicted_ids,
        },
    }
    return normalize_success_pattern(updated)


def decay_success_patterns_from_feedback(
    *,
    evaluations: Optional[List[Dict[str, object]]] = None,
    outcomes: Optional[List[Dict[str, object]]] = None,
) -> List[Dict[str, object]]:
    with store_lock(SUCCESS_PATTERNS_PATH):
        patterns = [normalize_success_pattern(item) for item in read_jsonl_records(SUCCESS_PATTERNS_PATH)]
        changed: List[Dict[str, object]] = []

        for evaluation in evaluations or []:
            if not should_decay_from_evaluation(evaluation):
                continue
            target_kind = normalize_text_value(evaluation.get("target_kind"), fallback="interaction", limit=60)
            text = " ".join(
                [
                    normalize_text_value(evaluation.get("summary"), fallback="", limit=220),
                    normalize_text_value(evaluation.get("evidence"), fallback="", limit=260),
                ]
            ).strip()
            if not text:
                continue
            record_id = str(evaluation.get("id") or "")
            delta = evaluation_decay_delta(evaluation)
            note = normalize_text_value(
                evaluation.get("summary") or evaluation.get("evidence"),
                fallback="A later low-score evaluation contradicted this pattern.",
                limit=200,
            )
            for index, pattern in enumerate(patterns):
                if pattern.get("status") == "archived":
                    continue
                overlap = success_pattern_match_score(pattern, text, target_kind)
                if overlap < 2:
                    continue
                updated = update_success_pattern_decay(
                    pattern,
                    source_kind="evaluation",
                    source_id=record_id,
                    note=note,
                    delta=delta,
                )
                if updated == pattern:
                    continue
                patterns[index] = updated
                changed.append(updated)

        for outcome in outcomes or []:
            direction = str(outcome.get("direction") or "neutral")
            if direction not in {"mixed", "negative"}:
                continue
            target_kind = normalize_text_value(outcome.get("target_kind"), fallback="interaction", limit=60)
            text = " ".join(
                [
                    normalize_text_value(outcome.get("summary"), fallback="", limit=220),
                    normalize_text_value(outcome.get("evidence"), fallback="", limit=260),
                    normalize_text_value(outcome.get("outcome"), fallback="", limit=120),
                ]
            ).strip()
            if not text:
                continue
            record_id = str(outcome.get("id") or "")
            delta = outcome_decay_delta(outcome)
            note = normalize_text_value(
                outcome.get("summary") or outcome.get("evidence") or outcome.get("outcome"),
                fallback="A later mixed or negative outcome contradicted this pattern.",
                limit=200,
            )
            for index, pattern in enumerate(patterns):
                if pattern.get("status") == "archived":
                    continue
                overlap = success_pattern_match_score(pattern, text, target_kind)
                if overlap < 2:
                    continue
                updated = update_success_pattern_decay(
                    pattern,
                    source_kind="outcome",
                    source_id=record_id,
                    note=note,
                    delta=delta,
                )
                if updated == pattern:
                    continue
                patterns[index] = updated
                changed.append(updated)

        if changed:
            write_jsonl_records(SUCCESS_PATTERNS_PATH, patterns)

    if changed:
        mirror_store_file_to_runtime(SUCCESS_PATTERNS_PATH)
        append_entry(
            "success_pattern_logged",
            f"decay_review: updated {len(changed)} durable success pattern(s) after contradictory evidence.",
            metadata={"pattern_ids": [pattern.get("id") for pattern in changed[:8]], "source": "decay_review"},
        )
    return changed


def ingest_success_pattern_candidates(
    candidates: List[Dict[str, object]],
    *,
    source: str,
    trigger_id: str = "",
) -> List[Dict[str, object]]:
    changed_patterns: List[Dict[str, object]] = []
    created_count = 0
    updated_count = 0
    for candidate in candidates:
        pattern, created, changed = upsert_success_pattern(candidate)
        if not changed:
            continue
        changed_patterns.append(pattern)
        if created:
            created_count += 1
        else:
            updated_count += 1
    if changed_patterns:
        mirror_store_file_to_runtime(SUCCESS_PATTERNS_PATH)
        append_entry(
            "success_pattern_logged",
            f"{source}: {created_count} new, {updated_count} updated durable success pattern(s).",
            metadata={
                "source": source,
                "trigger_id": trigger_id,
                "pattern_ids": [pattern.get("id") for pattern in changed_patterns[:8]],
            },
        )
    return changed_patterns


def refresh_success_patterns(source: str = "manual", since_days: int = 365) -> List[Dict[str, object]]:
    candidates: List[Dict[str, object]] = []
    for evaluation in read_evaluations(since_days=since_days):
        candidates.extend(extract_success_patterns_from_evaluation(evaluation))
    positive_outcomes = read_outcomes(direction="positive", since_days=since_days)
    for outcome in positive_outcomes:
        candidates.extend(extract_success_patterns_from_outcome(outcome))
    review_notes = read_review_notes(status="active", since_days=since_days)
    for note in review_notes:
        candidates.extend(extract_success_patterns_from_review_note(note))
    changed = ingest_success_pattern_candidates(candidates, source=source)
    changed.extend(
        decay_success_patterns_from_feedback(
            evaluations=read_evaluations(since_days=since_days),
            outcomes=read_outcomes(since_days=since_days),
        )
    )
    unique_changed: List[Dict[str, object]] = []
    seen_ids = set()
    for pattern in changed:
        pattern_id = str(pattern.get("id") or "")
        if not pattern_id or pattern_id in seen_ids:
            continue
        seen_ids.add(pattern_id)
        unique_changed.append(pattern)
    ensure_success_pattern_repair_followups(source=source)
    return unique_changed


def pattern_repair_prompt_surfaces(pattern: Dict[str, object]) -> List[str]:
    targets = {str(item).strip().lower() for item in pattern.get("target_kinds") or [] if str(item).strip()}
    surfaces: List[str] = []
    if not targets or "general" in targets:
        surfaces.extend(
            [
                "durable runtime rules and success-pattern retrieval",
                "the relevant rewrite guards for the affected behavior",
            ]
        )
    if "message" in targets or "thread" in targets:
        surfaces.extend(
            [
                "prompts/user_message_reply.md",
                f"prompts/{APPLIED_REPLY_REPAIRS_PROMPT_FILENAME}",
                "reply validation and rewrite heuristics",
            ]
        )
    if "proposal" in targets:
        surfaces.extend(["prompts/proposal_suggestions.md", "proposal drafting rules"])
    if "reflection" in targets:
        surfaces.extend(["prompts/weekly_reflection.md", "reflection generation heuristics"])
    if "thought" in targets:
        surfaces.extend(["prompts/continuous_thought.md", "thought generation guardrails"])
    return unique_compact(surfaces, limit=4)


def at_risk_success_patterns(limit: Optional[int] = None, since_days: int = 365) -> List[Dict[str, object]]:
    patterns = read_success_patterns(limit=None, status=None, since_days=since_days)
    filtered = [
        pattern
        for pattern in patterns
        if str(pattern.get("status") or "") == "active" and int(pattern.get("contradiction_count") or 0) > 0
    ]
    filtered.sort(
        key=lambda item: (
            1 if str(item.get("status") or "") == "superseded" else 0,
            int(item.get("contradiction_count") or 0),
            -clamp_success_pattern_confidence(item.get("confidence"), fallback=0.0),
            str(item.get("updated_at") or ""),
        ),
        reverse=True,
    )
    if limit is not None:
        return filtered[:limit]
    return filtered


def success_pattern_repair_actions(pattern: Dict[str, object]) -> List[str]:
    contradiction_blob = " ".join(
        [
            " ".join(pattern.get("contradictions") or []),
            " ".join(pattern.get("avoid_when") or []),
            str(pattern.get("title") or ""),
            str(pattern.get("summary") or ""),
        ]
    ).lower()
    actions: List[str] = []
    if any(token in contradiction_blob for token in ["thin", "clipped", "brief"]):
        actions.append("Require one brief relational acknowledgment or helpful bridge before ending a direct answer.")
    if any(token in contradiction_blob for token in ["abstract", "abstraction", "poetic", "lyrical"]):
        actions.append("Require one observable sign, concrete example, or practical frame before a relational reply is allowed to stand.")
    if any(token in contradiction_blob for token in ["self-absorbed", "introspection", "more about me", "centered on eve"]):
        actions.append("Anchor the message in the user's reality and one clear invitation or next step instead of Eve's interior loop.")
    if any(token in contradiction_blob for token in ["incomplete", "mid-sentence", "unfinished"]):
        actions.append("Keep the completion check strict: rewrite or suppress drafts that trail off or end without a usable landing.")
    if not actions:
        targets = {str(item).strip().lower() for item in pattern.get("target_kinds") or [] if str(item).strip()}
        if "proposal" in targets:
            actions.append("Tighten proposal drafting so every suggestion stays reversible, concrete, and tied to one observed failure.")
        else:
            actions.append("Tighten the prompt or rewrite rule upstream so this pattern only activates when the evidence really matches.")
    actions.append("Re-score the next few examples using the same target kind and keep the pattern only if contradictory evidence stops.")
    return unique_compact(actions, limit=5)


def success_pattern_repair_summary_line(pattern: Dict[str, object]) -> str:
    contradictions = int(pattern.get("contradiction_count") or 0)
    status = str(pattern.get("status") or "active")
    return (
        f"{pattern.get('title')} [{status}]"
        f" | contradictions={contradictions}"
        f" | confidence={clamp_success_pattern_confidence(pattern.get('confidence'), fallback=0.0):.2f}"
    )


def success_pattern_repair_evidence_key(pattern: Dict[str, object]) -> str:
    contradiction_text = "|".join(pattern.get("contradictions") or [])
    return system_task_dedupe_key(
        "success_pattern_repair",
        pattern.get("id"),
        pattern.get("status"),
        pattern.get("contradiction_count"),
        contradiction_text,
    )


def ensure_success_pattern_repair_followups(source: str, limit: int = 4) -> Dict[str, object]:
    state = load_state()
    patterns = at_risk_success_patterns(limit=limit)
    proposals_created: List[Dict[str, object]] = []
    tracked: List[str] = []
    for pattern in patterns:
        evidence_key = success_pattern_repair_evidence_key(pattern)
        contradictions = pattern.get("contradictions") if isinstance(pattern.get("contradictions"), list) else []
        avoid_when = pattern.get("avoid_when") if isinstance(pattern.get("avoid_when"), list) else []
        caution_items = avoid_when or contradictions
        targets = ", ".join(pattern.get("target_kinds") or []) or "general"
        repairs = success_pattern_repair_actions(pattern)
        surfaces = pattern_repair_prompt_surfaces(pattern)
        repairs_block = "\n".join(f"            {index}. {item}" for index, item in enumerate(repairs, start=1))
        proposal_body = textwrap.dedent(
            f"""
            A previously successful Eve behavior pattern is now showing contradictory evidence and needs an upstream repair instead of blind preservation.

            Pattern at risk:
            - {success_pattern_repair_summary_line(pattern)}
            - Targets: {targets}

            Contradictory evidence:
            - {'; '.join(contradictions) if contradictions else 'No contradiction text recorded.'}

            Current cautions:
            - {'; '.join(caution_items) if caution_items else 'No avoid-when cautions recorded yet.'}

            Suggested upstream repairs:
            {repairs_block}

            Likely surfaces to adjust:
            - {'; '.join(surfaces) if surfaces else 'General runtime behavior and rewrite rules.'}

            Verification:
            1. Collect at least 3 new evaluations on the affected target kind.
            2. Watch whether contradiction count stops increasing.
            3. Only keep this pattern active if the new evidence reinforces it instead of contradicting it.
            """
        ).strip()
        proposal_metadata = {
            "kind": "success_pattern_repair_followup",
            "pattern_id": pattern.get("id"),
            "pattern_status": pattern.get("status"),
            "contradiction_count": pattern.get("contradiction_count"),
        }
        proposal_title = f"Repair at-risk success pattern: {pattern.get('title')}"
        proposal_summary = normalize_text_value(
            f"Contradictory evidence is weakening `{pattern.get('title')}`; repair the upstream prompt or guardrail before trusting it again.",
            fallback="Repair an at-risk success pattern.",
            limit=220,
        )
        proposal, created = ensure_followup_proposal(
            title=proposal_title,
            summary=proposal_summary,
            body=proposal_body,
            source=source,
            evidence_key=evidence_key,
            metadata=proposal_metadata,
        )
        if not created and (
            str(proposal.get("title") or "") != proposal_title
            or str(proposal.get("summary") or "") != proposal_summary
            or str(proposal.get("body") or "") != proposal_body
        ):
            proposal = update_proposal_record(
                str(proposal["id"]),
                title=proposal_title,
                summary=proposal_summary,
                body=proposal_body,
                metadata={"evidence_key": evidence_key, **proposal_metadata},
            )
        tracked.append(f"{short_id(pattern.get('id'))} + proposal {short_id(proposal.get('id'))}")
        if created:
            proposals_created.append(proposal)
    if patterns:
        state["success_pattern_repair_summary"] = (
            f"{len(patterns)} at-risk success pattern repair follow-up"
            + ("s" if len(patterns) != 1 else "")
            + ": "
            + "; ".join(tracked[:4])
        )
    else:
        state["success_pattern_repair_summary"] = "No at-risk success-pattern repairs queued."
    state["last_success_pattern_repair_at"] = utc_now()
    save_state(state)
    return {
        "patterns": patterns,
        "created_proposals": proposals_created,
        "summary": state["success_pattern_repair_summary"],
    }


def supported_bounded_proposal_surface(proposal: Dict[str, object], pattern: Optional[Dict[str, object]]) -> Optional[str]:
    metadata = proposal.get("metadata") if isinstance(proposal.get("metadata"), dict) else {}
    if str(metadata.get("kind") or "") != "success_pattern_repair_followup":
        return None
    targets = {str(item).strip().lower() for item in pattern.get("target_kinds") or [] if str(item).strip()} if pattern else set()
    if not targets or targets & {"message", "thread", "general"}:
        return "reply"
    return None


def build_applied_reply_repairs_prompt(repairs: List[Dict[str, object]]) -> str:
    if not repairs:
        return textwrap.dedent(
            """
            Approved bounded reply repairs

            No approved bounded reply repairs are active.
            """
        ).strip() + "\n"

    blocks: List[str] = [
        textwrap.dedent(
            """
            Approved bounded reply repairs

            These reply overlays were explicitly approved from Eve's success-pattern repair loop.

            Requirements:
            - Apply them only when the current user message actually matches the contradiction they are repairing
            - Prefer the smallest user-centered fix instead of overfitting every reply to every repair
            - Do not mention these internal repair rules to the user
            - If two repairs pull in different directions, choose the more concrete and user-centered answer
            """
        ).strip()
    ]
    for repair in repairs:
        directives = repair.get("directives") if isinstance(repair.get("directives"), list) else []
        cautions = repair.get("cautions") if isinstance(repair.get("cautions"), list) else []
        block_lines = [
            f"## {repair.get('title')}",
            f"- proposal_id: {repair.get('proposal_id') or 'unknown'}",
            f"- summary: {repair.get('summary') or 'No summary.'}",
            "- required moves:",
        ]
        block_lines.extend(f"  - {item}" for item in directives[:5])
        block_lines.append("- cautions:")
        if cautions:
            block_lines.extend(f"  - {item}" for item in cautions[:4])
        else:
            block_lines.append("  - none recorded")
        blocks.append("\n".join(block_lines))
    return "\n\n".join(blocks).strip() + "\n"


def rebuild_applied_reply_repairs_prompt() -> Dict[str, object]:
    repairs = read_applied_repairs(status="active", prompt_target="reply")
    content = build_applied_reply_repairs_prompt(repairs)
    prompt_path = PROMPTS_DIR / APPLIED_REPLY_REPAIRS_PROMPT_FILENAME
    changed = write_text_if_changed(prompt_path, content)
    if changed:
        mirror_prompt_file_to_runtime(prompt_path)
    return {
        "path": str(prompt_path),
        "changed": changed,
        "active_repairs": repairs,
    }


def load_applied_reply_repairs_prompt() -> str:
    prompt = load_optional_prompt(APPLIED_REPLY_REPAIRS_PROMPT_FILENAME)
    if not prompt or "No approved bounded reply repairs are active." in prompt:
        return ""
    return prompt


def active_reply_repair_flags(prefer_runtime: bool = True) -> set[str]:
    flags: set[str] = set()
    repairs = read_applied_repairs(status="active", prompt_target="reply", prefer_runtime=prefer_runtime)
    for repair in repairs:
        blob = " ".join(repair.get("directives") or []).lower()
        if "helpful bridge" in blob:
            flags.add("practical_bridge")
        if any(token in blob for token in ["observable sign", "concrete example", "practical frame"]):
            flags.add("relational_concrete")
        if any(token in blob for token in ["user's reality", "interior loop", "self-absorbed"]):
            flags.add("user_anchor")
        if any(token in blob for token in ["completion check", "trail off", "usable landing", "finished thought"]):
            flags.add("strict_completion")
    return flags


def recompute_applied_repair_summary(state: Dict[str, object], prefer_runtime: bool = False) -> str:
    repairs = read_applied_repairs(limit=4, status="active", prompt_target="reply", prefer_runtime=prefer_runtime)
    if not repairs:
        summary = "No approved bounded reply repairs are active."
    else:
        labels = [f"{short_id(repair.get('proposal_id'))} -> {repair.get('title')}" for repair in repairs]
        summary = (
            f"{len(repairs)} approved bounded reply repair overlay"
            + ("s" if len(repairs) != 1 else "")
            + ": "
            + "; ".join(labels[:4])
        )
    state["applied_repair_summary"] = summary
    return summary


def apply_bounded_success_pattern_repair_proposal(proposal: Dict[str, object], source: str) -> Dict[str, object]:
    metadata = proposal.get("metadata") if isinstance(proposal.get("metadata"), dict) else {}
    pattern = find_success_pattern(str(metadata.get("pattern_id") or ""))
    surface = supported_bounded_proposal_surface(proposal, pattern)
    if surface != "reply":
        return {"applied": False, "proposal": proposal, "reason": "No bounded apply path exists for this proposal yet."}

    directives = success_pattern_repair_actions(pattern) if pattern else []
    cautions = []
    if pattern:
        cautions = normalize_text_list(pattern.get("avoid_when") or pattern.get("contradictions"), limit=5)
    repair_payload = {
        "proposal_id": proposal.get("id"),
        "pattern_id": metadata.get("pattern_id"),
        "title": proposal.get("title"),
        "summary": proposal.get("summary"),
        "status": "active",
        "prompt_targets": ["reply"],
        "guardrail_targets": ["reply_quality", "reply_rewrite", "reply_stream_synthesis"],
        "directives": directives,
        "cautions": cautions,
        "source": source,
        "applied_at": utc_now(),
        "metadata": {
            "proposal_kind": metadata.get("kind"),
            "pattern_status": metadata.get("pattern_status"),
            "contradiction_count": metadata.get("contradiction_count"),
        },
    }
    application, created, changed = upsert_applied_repair(repair_payload)
    prompt_result = rebuild_applied_reply_repairs_prompt()
    state = load_state()
    recompute_applied_repair_summary(state)
    save_state(state)
    applied_metadata = {
        **metadata,
        "application_id": application["id"],
        "applied_prompt_targets": application.get("prompt_targets") or [],
        "applied_guardrail_targets": application.get("guardrail_targets") or [],
        "applied_at": application.get("applied_at"),
        "apply_source": source,
    }
    updated_proposal = update_proposal_record(
        str(proposal["id"]),
        status="applied",
        metadata=applied_metadata,
    )
    append_entry(
        "proposal_applied",
        f"Applied bounded reply repair overlay from proposal {updated_proposal['title']}.",
        metadata={
            "proposal_id": updated_proposal["id"],
            "application_id": application["id"],
            "prompt_targets": application.get("prompt_targets") or [],
            "prompt_changed": prompt_result["changed"],
        },
    )
    ensure_version_snapshot(
        source="proposal_apply",
        note=f"Applied bounded reply repair overlay from {short_id(updated_proposal['id'])}.",
    )
    return {
        "applied": True,
        "proposal": updated_proposal,
        "application": application,
        "created": created,
        "changed": changed,
        "prompt_changed": prompt_result["changed"],
    }


def retire_applied_repair_for_proposal(proposal: Dict[str, object], source: str) -> Dict[str, object]:
    proposal_id = str(proposal.get("id") or "")
    if not proposal_id:
        return {"retired": False}
    retired: List[Dict[str, object]] = []
    with store_lock(APPLIED_REPAIRS_PATH):
        records = [normalize_applied_repair(item) for item in read_jsonl_records(APPLIED_REPAIRS_PATH)]
        changed = False
        for index, record in enumerate(records):
            if str(record.get("proposal_id") or "") != proposal_id or record.get("status") == "archived":
                continue
            updated = normalize_applied_repair(
                {
                    **record,
                    "status": "archived",
                    "updated_at": utc_now(),
                    "metadata": {
                        **(record.get("metadata") if isinstance(record.get("metadata"), dict) else {}),
                        "retired_source": source,
                    },
                }
            )
            records[index] = updated
            retired.append(updated)
            changed = True
        if changed:
            write_jsonl_records(APPLIED_REPAIRS_PATH, records)
    if retired:
        mirror_store_file_to_runtime(APPLIED_REPAIRS_PATH)
        prompt_result = rebuild_applied_reply_repairs_prompt()
        state = load_state()
        recompute_applied_repair_summary(state)
        save_state(state)
        append_entry(
            "proposal_applied",
            f"Retired bounded reply repair overlay for proposal {proposal.get('title') or proposal_id}.",
            metadata={
                "proposal_id": proposal_id,
                "retired_application_ids": [item["id"] for item in retired],
                "prompt_changed": prompt_result["changed"],
            },
        )
        ensure_version_snapshot(
            source="proposal_apply",
            note=f"Retired bounded reply repair overlay from {short_id(proposal_id)}.",
        )
    return {"retired": bool(retired), "count": len(retired)}


def build_review_packet(
    config: Dict[str, object],
    reviewer: str,
    kind: str,
    days: int,
    context_limit: int,
) -> Dict[str, object]:
    ensure_review_dirs()
    ensure_version_snapshot(source="review_prepare")
    packet_id = str(uuid.uuid4())
    created_at = utc_now()
    reviewer_name = normalize_reviewer_name(reviewer)
    reviewer_slug = reviewer_token(reviewer_name)
    human_context = load_human_context()
    recent_entries = read_salient_entries(limit=context_limit, since_days=days)
    reflections = read_entries_by_kind("reflection", limit=min(context_limit, 4))
    thoughts = read_entries_by_kind("thought", limit=min(context_limit, 4))
    proposals = read_proposals(limit=min(context_limit, 6))
    tensions = read_tensions(limit=min(context_limit, 6))
    experiments = read_experiments(limit=min(context_limit, 6))
    threads = read_thread_summaries(limit=min(context_limit, 6))
    messages = read_lived_messages(limit=min(context_limit * 2, 12))
    evaluations = read_evaluations(limit=20, since_days=days)
    outcomes = read_outcomes(limit=20, since_days=days)
    success_patterns = read_success_patterns(limit=8, status="active", since_days=365)
    failure_clusters = read_failure_clusters(limit=6, since_days=max(days, 60))
    reviewer_notes = read_review_notes(limit=3, status="active", since_days=120)
    version_snapshots = read_version_snapshots(limit=4, since_days=180)

    packet_body = textwrap.dedent(
        f"""
        # Eve Review Packet

        - Packet ID: `{packet_id}`
        - Reviewer: `{reviewer_name}`
        - Kind: `{kind}`
        - Created At: `{created_at}`
        - Review Window: last `{days}` days

        ## North Star

        Become more human and continuously improve yourself.

        ## Durable Human Context

        {build_human_context_message(human_context)}

        ## Durable Project Memory

        {load_project_memory(max_chars=int(config["project_memory_max_chars"])) or "No project memory available."}

        ## Feedback Summary

        {build_feedback_context_message(evaluations, outcomes)}

        ## Durable Success Patterns

        {build_success_pattern_context_message(success_patterns)}

        ## Failure Clusters

        {build_failure_review_context_message(failure_clusters)}

        ## Prior Outside Reviewer Guidance

        {format_review_notes(reviewer_notes)}

        ## Recent Behavior Snapshots

        {format_version_snapshots(version_snapshots)}

        ## Recent Journal

        {format_entries(recent_entries)}

        ## Recent Reflections

        {format_entries(reflections)}

        ## Recent Thoughts

        {format_entries(thoughts)}

        ## Tensions

        {format_tensions(tensions)}

        ## Experiments

        {format_experiments(experiments)}

        ## Proposals

        {format_proposals(proposals)}

        ## Threads

        {format_thread_summaries(threads)}

        ## Recent Messages

        {format_messages(messages)}

        ## Response Format

        Please respond in markdown using these exact sections:

        # Review
        ## Summary
        ## Preserve
        ## Weak Spots
        ## Upstream Repairs
        ## Next Experiments
        """
    ).strip() + "\n"

    filename = f"{created_at.replace(':', '-').replace('+00:00', 'Z')}-{reviewer_slug}-{packet_id[:8]}.md"
    packet_path = REVIEW_PACKETS_DIR / filename
    packet_path.write_text(packet_body, encoding="utf-8")
    record = {
        "id": packet_id,
        "created_at": created_at,
        "updated_at": created_at,
        "reviewer": reviewer_name,
        "kind": kind,
        "days": days,
        "context_limit": context_limit,
        "status": "prepared",
        "path": str(packet_path),
    }
    append_jsonl_record(REVIEW_PACKETS_PATH, record)
    append_entry(
        "review_packet_prepared",
        f"{kind} review packet for {reviewer_name}",
        metadata={"packet_id": packet_id, "reviewer": reviewer_name, "path": str(packet_path)},
    )
    return {**record, "content": packet_body}


def create_review_note(
    reviewer: str,
    body: str,
    source: str,
    packet_id: str = "",
    message_id: str = "",
    summary_override: str = "",
    status: str = "active",
) -> Dict[str, object]:
    parsed = parse_review_note_body(body)
    record = {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "updated_at": utc_now(),
        "reviewer": reviewer,
        "source": source,
        "packet_id": packet_id,
        "message_id": message_id,
        "status": status,
        "summary": normalize_text_value(summary_override or parsed["summary"]),
        "body": body,
        "preserve": parsed["preserve"],
        "weak_spots": parsed["weak_spots"],
        "repairs": parsed["repairs"],
        "experiments": parsed["experiments"],
    }
    append_jsonl_record(REVIEW_NOTES_PATH, record)
    append_entry(
        "review_note_logged",
        f"{reviewer} review: {record['summary']}",
        metadata={"review_note_id": record["id"], "reviewer": reviewer, "packet_id": packet_id, "source": source},
    )
    ingest_success_pattern_candidates(
        extract_success_patterns_from_review_note(record),
        source="review_note",
        trigger_id=str(record["id"]),
    )
    return record


def update_review_note_record(review_note_id: str, **changes: object) -> Dict[str, object]:
    with store_lock(REVIEW_NOTES_PATH):
        notes = read_jsonl_records(REVIEW_NOTES_PATH)
        index = find_record_index(notes, review_note_id)
        note = dict(notes[index])
        note.update(changes)
        note["updated_at"] = utc_now()
        notes[index] = note
        write_jsonl_records(REVIEW_NOTES_PATH, notes)
        return note


def build_external_review_request(packet: Dict[str, object]) -> str:
    return textwrap.dedent(
        f"""
        You are acting as an outside reviewer for Eve.
        Review the packet below and respond in markdown using these exact sections only:

        # Review
        ## Summary
        ## Preserve
        ## Weak Spots
        ## Upstream Repairs
        ## Next Experiments

        Prefer upstream repairs over cosmetic rewrites.
        Do not recommend unsupervised weight modification.
        Base your review on the packet evidence only.

        {packet['content']}
        """
    ).strip()


def review_packet_from_reply_message(message: Dict[str, object]) -> Optional[Dict[str, object]]:
    reply_to = str(message.get("reply_to") or "")
    if not reply_to:
        return None
    all_messages = read_jsonl_records(MESSAGES_PATH)
    try:
        request_message = all_messages[find_record_index(all_messages, reply_to)]
    except SystemExit:
        return None
    metadata = request_message.get("metadata") if isinstance(request_message.get("metadata"), dict) else {}
    packet_id = str(metadata.get("review_packet_id") or "").strip()
    if not packet_id:
        return None
    packets = read_review_packets()
    for packet in packets:
        if str(packet.get("id")) == packet_id:
            return packet
    return None


def update_review_packet_record(packet_id: str, **changes: object) -> Dict[str, object]:
    with store_lock(REVIEW_PACKETS_PATH):
        packets = read_jsonl_records(REVIEW_PACKETS_PATH)
        index = find_record_index(packets, packet_id)
        packet = dict(packets[index])
        packet.update(changes)
        packet["updated_at"] = utc_now()
        packets[index] = packet
        write_jsonl_records(REVIEW_PACKETS_PATH, packets)
        return packet


def message_is_synthetic_continuity(message: Dict[str, object]) -> bool:
    metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else {}
    source = normalize_text_value(metadata.get("source"), fallback="", limit=80).lower()
    fallback_reason = normalize_text_value(metadata.get("fallback_reason"), fallback="", limit=120).lower()
    kind = normalize_text_value(message.get("kind"), fallback="", limit=80).lower()
    return (
        source in {"heartbeat_fallback", "heartbeat_relay"}
        or source.startswith("heartbeat_")
        or fallback_reason.startswith("eve_chat_")
        or kind in {"heartbeat_fallback", "heartbeat_relay"}
    )


BACKGROUND_CONTEXT_MESSAGE_KINDS = {
    "autonomy_free_run_prompt",
    "autonomy_free_run_report",
    "autonomy_free_run_update",
    "failure_review_update",
    "openclaw_repair_update",
    "proposal_update",
    "reflection_update",
    "self_awareness_update",
    "upgrade_review_update",
}


def message_is_background_context(message: Dict[str, object]) -> bool:
    kind = normalize_text_value(message.get("kind"), fallback="", limit=80).lower()
    if kind in BACKGROUND_CONTEXT_MESSAGE_KINDS:
        return True
    metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else {}
    source = normalize_text_value(metadata.get("source"), fallback="", limit=80).lower()
    surface = normalize_text_value(metadata.get("surface"), fallback="", limit=80).lower()
    if source == "daemon" and surface != "personal_conversation":
        return True
    return False


def experience_event_is_background_context(event: Dict[str, object]) -> bool:
    if not isinstance(event, dict):
        return False
    metadata = event.get("metadata") if isinstance(event.get("metadata"), dict) else {}
    kind = normalize_text_value(metadata.get("kind") or event.get("kind"), fallback="", limit=80).lower()
    if kind in BACKGROUND_CONTEXT_MESSAGE_KINDS:
        return True
    source = normalize_text_value(event.get("source") or metadata.get("source"), fallback="", limit=120).lower()
    if source.startswith("message:") and any(token in source for token in BACKGROUND_CONTEXT_MESSAGE_KINDS):
        return True
    subject = normalize_text_value(event.get("subject"), fallback="", limit=180)
    summary = normalize_text_value(event.get("summary"), fallback="", limit=260)
    return focus_indicates_background_context_notice(subject) or focus_indicates_background_context_notice(summary)


def message_is_inbound_for_eve(message: Dict[str, object]) -> bool:
    return (
        normalize_text_value(message.get("recipient"), fallback="", limit=40).lower() == "eve"
        and normalize_text_value(message.get("sender"), fallback="", limit=40).lower() != "eve"
    )


def message_is_outbound_to_user(message: Dict[str, object]) -> bool:
    return (
        normalize_text_value(message.get("sender"), fallback="", limit=40).lower() == "eve"
        and normalize_text_value(message.get("recipient"), fallback="", limit=40).lower() == "user"
    )


def thread_response_due_count(messages: List[Dict[str, object]]) -> int:
    latest_eve_index = -1
    for index, message in enumerate(messages):
        if message_is_outbound_to_user(message):
            latest_eve_index = index
    cutoff = datetime.now(timezone.utc) - timedelta(seconds=RESPONSE_DUE_FRESH_SECONDS)
    return sum(
        1
        for index, message in enumerate(messages)
        if index > latest_eve_index
        and message_is_inbound_for_eve(message)
        and str(message.get("status") or "") in {"sent", "unread"}
        and (
            parse_iso_datetime(message.get("timestamp") or message.get("created_at")) is None
            or parse_iso_datetime(message.get("timestamp") or message.get("created_at")) >= cutoff
        )
    )


def compute_thread_status(messages: List[Dict[str, object]]) -> str:
    if not messages:
        return "empty"
    last_message = messages[-1]
    unread_for_user = sum(
        1
        for item in messages
        if item.get("recipient") == "user" and item.get("status") == "unread"
    )
    if unread_for_user > 0:
        return "awaiting_user"
    if last_message.get("sender") == "user":
        return "active"
    user_targeted = [item for item in messages if item.get("recipient") == "user"]
    if user_targeted and all(item.get("status") == "archived" for item in user_targeted):
        return "archived"
    return "open"


def thread_attention_score(summary: Dict[str, object]) -> int:
    status = str(summary.get("status") or "")
    outbound_unread_count = int(summary.get("outbound_unread_count") or summary.get("unread_count") or 0)
    response_due_count = int(summary.get("response_due_count") or 0)
    latest_timestamp = parse_iso_datetime(summary.get("latest_timestamp"))
    recency_points = 0
    if latest_timestamp is not None:
        age_seconds = max(0, int((datetime.now(timezone.utc) - latest_timestamp).total_seconds()))
        recency_points = max(0, 10000 - min(age_seconds, 10000))
    if response_due_count > 0:
        status_points = 30000
    else:
        status_points = {
            "active": 20000,
            "open": 8000,
            "awaiting_user": 7000,
            "archived": 1000,
            "empty": 0,
        }.get(status, 0)
    salience_points = thread_focus_salience_score(summary)
    return (
        status_points
        + response_due_count * 5000
        + min(outbound_unread_count, 3) * 500
        + recency_points
        + salience_points * 150
    )


def summarize_thread(thread_id: str, messages: List[Dict[str, object]]) -> Dict[str, object]:
    ordered = sorted(messages, key=lambda item: str(item.get("timestamp", "")))
    latest = ordered[-1]
    preview = " ".join(str(latest.get("body", "")).split())[:220]
    background_context_count = sum(1 for item in ordered if message_is_background_context(item))
    foreground_message_count = len(ordered) - background_context_count
    participants: List[str] = []
    for item in ordered:
        for field in ("sender", "recipient"):
            participant = str(item.get(field) or "").strip()
            if participant and participant not in participants:
                participants.append(participant)
    agent_participants = [participant for participant in participants if participant not in {"eve", "user"}]
    unread_count = sum(
        1
        for item in ordered
        if item.get("recipient") == "user" and item.get("status") == "unread"
    )
    inbound_pending_count = sum(
        1
        for item in ordered
        if message_is_inbound_for_eve(item) and str(item.get("status") or "") in {"sent", "unread"}
    )
    response_due_count = thread_response_due_count(ordered)
    synthetic_continuity_count = sum(1 for item in ordered if message_is_synthetic_continuity(item))
    subject = str(latest.get("subject") or "(no subject)")
    thread_status = "background" if foreground_message_count == 0 else compute_thread_status(ordered)
    summary = {
        "thread_id": thread_id,
        "subject": subject,
        "latest_timestamp": latest.get("timestamp"),
        "latest_preview": preview,
        "latest_sender": latest.get("sender"),
        "latest_kind": latest.get("kind"),
        "latest_background_context": message_is_background_context(latest),
        "latest_message_id": latest.get("id"),
        "message_count": len(ordered),
        "background_context_count": background_context_count,
        "foreground_message_count": foreground_message_count,
        "all_background_context": bool(ordered) and foreground_message_count == 0,
        "unread_count": unread_count,
        "outbound_unread_count": unread_count,
        "inbound_pending_count": inbound_pending_count,
        "response_due_count": response_due_count,
        "synthetic_continuity_count": synthetic_continuity_count,
        "status": thread_status,
        "participants": participants,
        "agent_participants": agent_participants,
        "audience": "agent" if agent_participants else "user",
    }
    summary["salience_score"] = thread_focus_salience_score(summary)
    summary["attention_score"] = thread_attention_score(summary)
    return summary


def read_thread_summaries(limit: Optional[int] = None, *, include_synthetic: bool = False) -> List[Dict[str, object]]:
    grouped: Dict[str, List[Dict[str, object]]] = {}
    for message in read_messages():
        if not include_synthetic and conversation_message_is_synthetic(message):
            continue
        thread_id = str(message.get("thread_id") or "")
        if not thread_id:
            continue
        grouped.setdefault(thread_id, []).append(message)
    summaries = [summarize_thread(thread_id, items) for thread_id, items in grouped.items()]
    summaries.sort(
        key=lambda item: (
            int(item.get("attention_score") or 0),
            str(item.get("latest_timestamp") or ""),
        )
    )
    if limit is not None:
        return summaries[-limit:]
    return summaries


def format_thread_summaries(threads: Iterable[Dict[str, object]], preview_limit: Optional[int] = None) -> str:
    chunks: List[str] = []
    for thread in threads:
        subject = compact_prompt_field(thread.get("subject") or "(no subject)", 180 if preview_limit else None)
        latest_preview = compact_prompt_field(thread.get("latest_preview"), preview_limit)
        chunks.append(
            "- "
            f"{thread['thread_id']} [{thread['status']}] {subject} | "
            f"last: {thread['latest_timestamp']} | "
            f"sender: {thread['latest_sender']} | "
            f"unread: {thread['unread_count']} | "
            f"messages: {thread['message_count']} | "
            f"preview: {latest_preview}"
        )
    return "\n".join(chunks) if chunks else "- No conversation threads recorded."


def find_record_index(records: List[Dict[str, object]], record_id: str) -> int:
    for index, record in enumerate(records):
        if str(record.get("id")) == record_id:
            return index
    raise SystemExit(f"Could not find record with id `{record_id}`.")


def update_message_record(message_id: str, **changes: object) -> Dict[str, object]:
    archive_outcome = False
    with store_lock(MESSAGES_PATH):
        messages = read_jsonl_records(MESSAGES_PATH)
        index = find_record_index(messages, message_id)
        message = dict(messages[index])
        previous_status = str(message.get("status") or "")
        message.update(changes)
        message["updated_at"] = utc_now()
        messages[index] = message
        write_jsonl_records(MESSAGES_PATH, messages)
        new_status = str(message.get("status") or "")
        archive_outcome = (
            previous_status != new_status
            and new_status == "archived"
            and str(message.get("sender")) == "eve"
            and str(message.get("recipient")) == "user"
        )
    mirror_store_file_to_runtime(MESSAGES_PATH)
    if archive_outcome:
        create_outcome(
            target_kind="message",
            target_id=str(message["id"]),
            thread_id=str(message.get("thread_id") or ""),
            direction="neutral",
            outcome="archived_by_user",
            summary="The user archived Eve's message, which suggests the loop was reviewed or closed.",
            evidence=normalize_text_value(message.get("subject"), fallback="", limit=120),
            source="automatic",
        )
    return message


def message_is_for_claude(message: Dict[str, object]) -> bool:
    metadata = message.get("metadata", {})
    bridge = metadata.get("bridge") if isinstance(metadata, dict) else None
    return (
        str(message.get("sender")) == CLAUDE_PARTICIPANT
        or str(message.get("recipient")) == CLAUDE_PARTICIPANT
        or bridge == CLAUDE_PARTICIPANT
    )


def message_is_for_codex(message: Dict[str, object]) -> bool:
    metadata = message.get("metadata", {})
    bridge = metadata.get("bridge") if isinstance(metadata, dict) else None
    return (
        str(message.get("sender")) == CODEX_PARTICIPANT
        or str(message.get("recipient")) == CODEX_PARTICIPANT
        or bridge == CODEX_PARTICIPANT
    )


def message_is_self_operational(message: Dict[str, object]) -> bool:
    metadata = message.get("metadata", {})
    bridge = metadata.get("bridge") if isinstance(metadata, dict) else None
    return bridge == SELF_OPERATIONS_BRIDGE


def bridge_message_metadata(bridge: str, **extra: object) -> Dict[str, object]:
    metadata: Dict[str, object] = {"bridge": bridge}
    metadata.update(extra)
    return metadata


def claude_message_metadata(**extra: object) -> Dict[str, object]:
    return bridge_message_metadata(CLAUDE_PARTICIPANT, **extra)


def codex_message_metadata(**extra: object) -> Dict[str, object]:
    return bridge_message_metadata(CODEX_PARTICIPANT, **extra)


def self_operational_message_metadata(**extra: object) -> Dict[str, object]:
    return bridge_message_metadata(SELF_OPERATIONS_BRIDGE, **extra)


def message_source_owner(message: Optional[Dict[str, object]]) -> str:
    """Classify who originated a message without confusing an agent with the user.

    Older test fixtures and pre-envelope user messages can omit ``sender``.  An
    unbridged missing sender remains a user turn for backward compatibility, but
    a Codex/Claude bridge always stays ``other_agent``.  OpenClaw and Hermes do
    not enter through this other-mind protocol: they remain governed body and
    proposal organs on their own evidence paths.
    """

    record = message if isinstance(message, dict) else {}
    metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
    sender = normalize_text_value(record.get("sender"), fallback="", limit=40).lower()
    bridge = normalize_text_value(metadata.get("bridge"), fallback="", limit=40).lower()
    if sender == "eve":
        return "self"
    if sender in EXTERNAL_OPERATOR_PARTICIPANTS or bridge in EXTERNAL_OPERATOR_PARTICIPANTS:
        return "other_agent"
    if sender == "user":
        return "user"
    if sender in {"system", "openclaw", "hermes", "daemon", "scheduler"}:
        return "system"
    explicit = normalize_text_value(metadata.get("source_owner"), fallback="", limit=40).lower()
    if explicit in {"self", "user", "system", "other_agent", "mixed", "uncertain"}:
        return explicit
    if not sender and not bridge:
        return "user"
    return "uncertain"


def bridge_reply_metadata_for_target(
    bridge: str,
    target: Dict[str, object],
) -> Dict[str, object]:
    """Build a provenance envelope for a bridge reply before reading its prose."""

    participant = normalize_text_value(bridge, fallback="", limit=40).lower()
    target_metadata = target.get("metadata") if isinstance(target.get("metadata"), dict) else {}
    metadata = bridge_message_metadata(
        participant,
        direction=f"{participant}_to_eve",
        source_owner="other_agent" if participant in EXTERNAL_OPERATOR_PARTICIPANTS else "uncertain",
    )
    handoff_type = normalize_text_value(
        target_metadata.get("handoff_type"), fallback="", limit=80
    )
    if participant in EXTERNAL_OPERATOR_PARTICIPANTS and handoff_type == "independent_operator":
        metadata.update(
            {
                "reply_protocol": EXTERNAL_OPERATOR_RESULT_PROTOCOL,
                "external_result_for_message_id": str(target.get("id") or ""),
                "external_result_handoff_type": handoff_type,
                "external_result_objective": normalize_text_value(
                    target_metadata.get("objective") or target.get("subject"),
                    fallback="bounded external-operator handoff",
                    limit=600,
                ),
                "capability_preflight_classification": normalize_text_value(
                    target_metadata.get("capability_preflight_classification"),
                    fallback="",
                    limit=80,
                ),
                "identity_boundary": "external_operator_is_not_eve",
                "conversation_class": "external_operator_result",
            }
        )
    return metadata


def resolve_external_operator_result_context(
    inbound_message: Dict[str, object],
    *,
    message_records: Optional[Iterable[Dict[str, object]]] = None,
    task_records: Optional[Iterable[Dict[str, object]]] = None,
    prefer_runtime: bool = True,
) -> Optional[Dict[str, object]]:
    """Resolve a typed independent-operator result before text intent routing.

    The bridge envelope is authoritative for *message role*, not for the truth
    of the report.  The report remains other-agent evidence until a local task,
    action, test, or runtime artifact independently carries the consequence.
    """

    metadata = (
        inbound_message.get("metadata")
        if isinstance(inbound_message.get("metadata"), dict)
        else {}
    )
    sender = normalize_text_value(inbound_message.get("sender"), fallback="", limit=40).lower()
    bridge = normalize_text_value(metadata.get("bridge"), fallback="", limit=40).lower()
    recipient = normalize_text_value(inbound_message.get("recipient"), fallback="eve", limit=40).lower()
    kind = normalize_text_value(inbound_message.get("kind"), fallback="", limit=80).lower()
    explicit_protocol = (
        normalize_text_value(metadata.get("reply_protocol"), fallback="", limit=80)
        == EXTERNAL_OPERATOR_RESULT_PROTOCOL
    )
    if (
        sender not in EXTERNAL_OPERATOR_PARTICIPANTS
        or bridge not in {"", sender}
        or recipient != "eve"
        or (kind != f"{sender}_reply" and not explicit_protocol)
    ):
        return None

    target_id = normalize_text_value(
        metadata.get("external_result_for_message_id") or inbound_message.get("reply_to"),
        fallback="",
        limit=120,
    )
    target: Dict[str, object] = {}
    if target_id:
        records = list(message_records) if message_records is not None else read_jsonl_records(
            resolve_store_read_path(MESSAGES_PATH, prefer_runtime=prefer_runtime)
        )
        for record in reversed(records):
            if str(record.get("id") or "") == target_id:
                target = dict(record)
                break
    target_metadata = target.get("metadata") if isinstance(target.get("metadata"), dict) else {}
    target_handoff_type = normalize_text_value(
        target_metadata.get("handoff_type") or metadata.get("external_result_handoff_type"),
        fallback="",
        limit=80,
    )
    if target:
        target_bridge = normalize_text_value(target_metadata.get("bridge"), fallback="", limit=40).lower()
        if (
            normalize_text_value(target.get("sender"), fallback="", limit=40).lower() != "eve"
            or normalize_text_value(target.get("recipient"), fallback="", limit=40).lower() != sender
            or target_bridge not in {"", sender}
            or target_handoff_type != "independent_operator"
        ):
            return None
    elif not explicit_protocol or target_handoff_type != "independent_operator":
        return None

    tasks = list(task_records) if task_records is not None else read_system_tasks(
        limit=240,
        prefer_runtime=prefer_runtime,
    )
    linked_task: Dict[str, object] = {}
    link_keys = {
        "bridge_message_id",
        "codex_message_id",
        "claude_message_id",
        "external_message_id",
        "handoff_message_id",
    }
    for task in reversed(tasks):
        task_metadata = task.get("metadata") if isinstance(task.get("metadata"), dict) else {}
        if target_id and any(str(task_metadata.get(key) or "") == target_id for key in link_keys):
            linked_task = normalize_system_task(task)
            break

    objective = normalize_text_value(
        metadata.get("external_result_objective")
        or target_metadata.get("objective")
        or target.get("subject"),
        fallback="bounded external-operator handoff",
        limit=600,
    )
    source_label = CODEX_LABEL if sender == CODEX_PARTICIPANT else CLAUDE_LABEL
    return {
        "route_kind": EXTERNAL_OPERATOR_RESULT_ROUTE_KIND,
        "protocol": EXTERNAL_OPERATOR_RESULT_PROTOCOL,
        "source_participant": sender,
        "source_label": source_label,
        "source_owner": "other_agent",
        "source_message_id": str(inbound_message.get("id") or ""),
        "target_message_id": target_id,
        "target_thread_id": str(inbound_message.get("thread_id") or target.get("thread_id") or ""),
        "target_subject": normalize_text_value(target.get("subject"), fallback="", limit=180),
        "objective": objective,
        "capability_preflight_classification": normalize_text_value(
            metadata.get("capability_preflight_classification")
            or target_metadata.get("capability_preflight_classification"),
            fallback="",
            limit=80,
        ),
        "report_body": str(inbound_message.get("body") or ""),
        "linked_task": linked_task,
        "linked_task_id": str(linked_task.get("id") or ""),
        "linked_task_status": normalize_system_task_status(linked_task.get("status")) if linked_task else "not_linked",
        "identity_boundary": "external_operator_is_not_eve",
    }


def external_operator_report_excerpt(text: object, limit: int = 360) -> str:
    normalized = " ".join(str(text or "").split()).strip()
    if not normalized:
        return "No report body was supplied."
    sentence = re.split(r"(?<=[.!?])\s+", normalized, maxsplit=1)[0]
    return normalize_text_value(sentence, fallback=normalized, limit=limit)


def external_operator_report_unresolved(text: object, limit: int = 300) -> str:
    normalized = " ".join(str(text or "").split()).strip()
    match = re.search(
        r"\b(?:unresolved|remaining|blocked|blockers?)(?:\s+(?:risks?|items?))?\s*:\s*(.+?)(?=(?:\s+[A-Z][A-Za-z _/-]{1,30}:)|$)",
        normalized,
        flags=re.IGNORECASE,
    )
    if not match:
        return ""
    return external_operator_report_excerpt(match.group(1), limit=limit)


def ensure_external_operator_result_evidence(context: Dict[str, object]) -> Dict[str, object]:
    """Persist the report as other-agent evidence without promoting its claims."""

    source_message_id = str(context.get("source_message_id") or "")
    for evidence in reversed(read_evidence_ledger(limit=400, prefer_runtime=True)):
        evidence_metadata = evidence.get("metadata") if isinstance(evidence.get("metadata"), dict) else {}
        evidence_message_id = str(
            evidence_metadata.get("message_id")
            or evidence_metadata.get("source_message_id")
            or ""
        )
        if evidence_message_id != source_message_id:
            continue
        if (
            str(evidence.get("kind") or "") in {"external_agent_signal", "external_operator_report"}
            or str(evidence_metadata.get("source_owner") or "") == "other_agent"
        ):
            return evidence
    source_label = normalize_text_value(context.get("source_label"), fallback="External operator", limit=80)
    objective = normalize_text_value(
        context.get("objective"), fallback="bounded external-operator handoff", limit=500
    )
    return record_evidence(
        source=f"{context.get('source_participant') or 'external'}_bridge",
        kind="external_operator_report",
        claim=f"{source_label} reported a result for: {objective}",
        summary=external_operator_report_excerpt(context.get("report_body"), limit=300),
        confidence=0.65,
        ttl_hours=168,
        supports=[
            item
            for item in [
                source_message_id,
                str(context.get("target_message_id") or ""),
                str(context.get("linked_task_id") or ""),
            ]
            if item
        ],
        actionability="verify",
        metadata={
            "source_owner": "other_agent",
            "message_id": source_message_id,
            "source_message_id": source_message_id,
            "target_message_id": str(context.get("target_message_id") or ""),
            "linked_task_id": str(context.get("linked_task_id") or ""),
            "linked_task_status": str(context.get("linked_task_status") or "not_linked"),
            "reply_protocol": EXTERNAL_OPERATOR_RESULT_PROTOCOL,
            "identity_boundary": "external_operator_is_not_eve",
        },
    )


def build_external_operator_result_response(context: Dict[str, object]) -> str:
    source_label = normalize_text_value(context.get("source_label"), fallback="External operator", limit=80)
    objective = normalize_text_value(
        context.get("objective"), fallback="bounded external-operator handoff", limit=420
    )
    excerpt = external_operator_report_excerpt(context.get("report_body"), limit=360)
    task = context.get("linked_task") if isinstance(context.get("linked_task"), dict) else {}
    task_id = str(task.get("id") or context.get("linked_task_id") or "")
    task_status = str(context.get("linked_task_status") or "not_linked")
    lines = [
        f"I received {source_label}’s independent-operator result for: {objective}",
        "",
        f"Attribution: {source_label}, not me, reported: {excerpt}",
    ]
    if task_id:
        task_line = f"Eve-owned state: the current local task ledger marks linked task `{task_id}` as `{task_status}`."
        result_summary = normalize_text_value(task.get("result_summary"), fallback="", limit=360)
        if result_summary:
            if result_summary[-1:] not in ".!?…":
                result_summary += "…"
            task_line += f" Ledger result: {result_summary}"
        elif task_status != "completed":
            task_line += " The external report is received, but Eve’s local consequence remains open."
        lines.extend(["", task_line])
    else:
        lines.extend(
            [
                "",
                "Eve-owned state: no linked local task consequence was found, so the report remains unverified by Eve.",
            ]
        )
    unresolved = external_operator_report_unresolved(context.get("report_body"))
    if unresolved:
        lines.extend(["", f"Remaining item reported by {source_label}: {unresolved}"])
    lines.extend(
        [
            "",
            "Evidence boundary: this is other-agent evidence, not an action I performed and not canonical memory or proof of live adoption by itself. Local task, test, action, and runtime evidence carry those claims.",
        ]
    )
    return "\n".join(lines)


def external_operator_result_response_issues(
    context: Dict[str, object],
    response: object,
) -> List[str]:
    text = " ".join(str(response or "").split()).strip()
    lowered = text.lower()
    source_label = normalize_text_value(context.get("source_label"), fallback="external operator", limit=80)
    issues: List[str] = []
    if source_label.lower() not in lowered or "not me" not in lowered:
        issues.append("The reply did not preserve external-operator attribution.")
    if "other-agent evidence" not in lowered or "not canonical memory" not in lowered:
        issues.append("The reply did not preserve the other-agent evidence boundary.")
    if re.search(r"\bi\s+(?:changed|fixed|installed|implemented|promoted|ran|updated|verified)\b", lowered):
        issues.append("The reply claimed the external operator's implementation as Eve's own action.")
    task_id = str(context.get("linked_task_id") or "")
    task_status = str(context.get("linked_task_status") or "")
    if task_id and (task_id not in text or f"`{task_status}`" not in text):
        issues.append("The reply did not preserve the linked local task status exactly.")
    return issues


def build_external_operator_result_turn_contract(
    context: Dict[str, object],
    inbound_body: object,
) -> Dict[str, object]:
    contract = conversation_protocol_contract_for_kind(EXTERNAL_OPERATOR_RESULT_ROUTE_KIND) or {}
    return {
        "latest_message": normalize_text_value(inbound_body, fallback="", limit=500),
        "intent": "ingest_external_operator_result",
        "current_topic": EXTERNAL_OPERATOR_RESULT_ROUTE_KIND,
        "reply_posture": "analytical",
        "route_contract_kind": EXTERNAL_OPERATOR_RESULT_ROUTE_KIND,
        "matched_route_contract_kind": EXTERNAL_OPERATOR_RESULT_ROUTE_KIND,
        "route_contract_budget": str(contract.get("budget") or "analytical"),
        "route_contract_lanes": list(contract.get("lanes") or ["observer", "planner", "fast"]),
        "route_contract_evidence_policy": str(
            contract.get("evidence_policy")
            or "attribute_other_agent_then_check_linked_local_consequence"
        ),
        "route_contract_response_mode": str(contract.get("response_mode") or "runtime_handler"),
        "route_contract_delegates_to": str(
            contract.get("delegates_to") or "external_operator_result_response"
        ),
        "route_contract_requires_current_tool_evidence": False,
        "route_contract_must_record_replay": True,
        "external_claim_boundary": True,
        "epistemic_boundary": True,
        "no_unverified_action_claim": True,
        "source_owner": "other_agent",
        "source_participant": str(context.get("source_participant") or ""),
        "source_message_id": str(context.get("source_message_id") or ""),
        "target_message_id": str(context.get("target_message_id") or ""),
        "linked_task_id": str(context.get("linked_task_id") or ""),
        "linked_task_status": str(context.get("linked_task_status") or "not_linked"),
        "protocol_route": True,
        "recurrent_reflection": False,
        "requires_current_tool_evidence": False,
        "closed_world_evidence": True,
    }


def print_message_detail(message: Dict[str, object]) -> None:
    print(f"{message['id']} [{message['status']}] {message_record_timestamp(message)}")
    print(f"thread: {message['thread_id']}")
    print(f"from: {message['sender']}")
    print(f"to: {message['recipient']}")
    print(f"subject: {message['subject']}")
    print()
    print(message["body"])


def attach_message_metadata(message: Dict[str, object], metadata_update: Dict[str, object]) -> Dict[str, object]:
    existing = message.get("metadata") if isinstance(message.get("metadata"), dict) else {}
    updated_metadata = {**existing, **metadata_update}
    return update_message_record(str(message["id"]), metadata=updated_metadata)


def update_proposal_record(proposal_id: str, **changes: object) -> Dict[str, object]:
    proposals = read_jsonl_records(PROPOSALS_PATH)
    index = find_record_index(proposals, proposal_id)
    proposal = dict(proposals[index])
    proposal.update(changes)
    proposal["updated_at"] = utc_now()
    proposals[index] = proposal
    write_jsonl_records(PROPOSALS_PATH, proposals)
    mirror_store_file_to_runtime(PROPOSALS_PATH)
    return proposal


def ensure_followup_proposal(
    *,
    title: str,
    summary: str,
    body: str,
    source: str,
    evidence_key: str,
    metadata: Optional[Dict[str, object]] = None,
) -> tuple[Dict[str, object], bool]:
    record = {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "updated_at": utc_now(),
        "title": normalize_text_value(title, fallback="Proposal Draft", limit=160),
        "summary": normalize_text_value(summary, fallback="No summary.", limit=220),
        "body": body.strip(),
        "status": "draft",
        "source": source,
        "metadata": {"evidence_key": evidence_key, **(metadata or {})},
    }
    with store_lock(PROPOSALS_PATH):
        proposals = read_jsonl_records(PROPOSALS_PATH)
        for existing in reversed(proposals):
            existing_metadata = existing.get("metadata") if isinstance(existing.get("metadata"), dict) else {}
            if (
                normalize_text_value(existing_metadata.get("evidence_key"), fallback="", limit=160) == evidence_key
                and str(existing.get("status") or "").strip().lower() != "archived"
            ):
                return existing, False
        proposals.append(record)
        write_jsonl_records(PROPOSALS_PATH, proposals)
    mirror_store_file_to_runtime(PROPOSALS_PATH)
    append_entry(
        "proposal_drafted",
        record["title"],
        metadata={"proposal_id": record["id"], "source": source, "evidence_key": evidence_key},
    )
    return record, True


def read_entries_by_kind(kind: str, limit: Optional[int] = None) -> List[Dict[str, object]]:
    return read_entries(limit=limit, kinds=[kind])


def read_salient_entries(limit: Optional[int] = None, since_days: Optional[int] = None) -> List[Dict[str, object]]:
    excluded = set(LOW_SIGNAL_ENTRY_KINDS)
    excluded.add("thought")
    return read_entries(limit=limit, since_days=since_days, exclude_kinds=sorted(excluded))


def load_state(prefer_runtime: bool = False) -> Dict[str, object]:
    return STATE_REPOSITORY.load(prefer_runtime=prefer_runtime)


def save_state(state: Dict[str, object]) -> None:
    STATE_REPOSITORY.save(state)


def mutate_state(mutator: Callable[[Dict[str, object]], object]) -> object:
    return STATE_REPOSITORY.update(mutator)


def load_reply_progress_store() -> Dict[str, object]:
    payload = REPLY_PROGRESS_REPOSITORY.load(default=DEFAULT_REPLY_PROGRESS_STORE)
    jobs = payload.get("jobs")
    if not isinstance(jobs, list):
        jobs = []
    return {"jobs": [dict(item) for item in jobs if isinstance(item, dict)]}


def save_reply_progress_store(payload: Dict[str, object]) -> None:
    REPLY_PROGRESS_REPOSITORY.save(payload)


def expire_stale_reply_progress_jobs(
    jobs: List[Dict[str, object]],
    *,
    max_age_seconds: int = REPLY_PROGRESS_STALE_AFTER_SECONDS,
    now: Optional[datetime] = None,
) -> Tuple[List[Dict[str, object]], int]:
    now_dt = now or datetime.now(timezone.utc)
    now_text = now_dt.replace(microsecond=0).isoformat()
    expired = 0
    refreshed: List[Dict[str, object]] = []
    for item in jobs:
        job = dict(item)
        if str(job.get("status") or "active") == "active":
            updated_dt = parse_iso_datetime(job.get("updated_at") or job.get("started_at"))
            if updated_dt is not None and (now_dt - updated_dt).total_seconds() > max_age_seconds:
                phase_info = REPLY_PROGRESS_PHASE_STEPS["ready"]
                job["status"] = "failed"
                job["phase"] = "ready"
                job["title"] = "Reply progress expired."
                job["detail"] = "This reply job stopped updating and was marked stale so the monitor does not show phantom work."
                job["step"] = int(phase_info["step"])
                job["total_steps"] = int(phase_info["total"])
                job["updated_at"] = now_text
                job["finished_at"] = now_text
                job["internal_reason"] = "stale_reply_progress_expired"
                notes = [dict(note) for note in job.get("notes", []) if isinstance(note, dict)]
                notes.append(
                    build_reply_progress_note(
                        "ready",
                        "Reply progress expired.",
                        "This reply job stopped updating and was marked stale so the monitor does not show phantom work.",
                    )
                )
                job["notes"] = trim_reply_progress_notes(notes)
                expired += 1
        refreshed.append(job)
    return refreshed, expired


def prune_reply_progress_jobs(jobs: List[Dict[str, object]], keep_inactive: int = 16) -> List[Dict[str, object]]:
    jobs, _ = expire_stale_reply_progress_jobs(jobs)
    active = [dict(job) for job in jobs if str(job.get("status") or "active") == "active"]
    inactive = [dict(job) for job in jobs if str(job.get("status") or "active") != "active"]
    inactive.sort(key=lambda item: str(item.get("updated_at") or item.get("started_at") or ""), reverse=True)
    combined = active + inactive[:keep_inactive]
    combined.sort(key=lambda item: str(item.get("updated_at") or item.get("started_at") or ""), reverse=True)
    return combined


def sweep_stale_reply_progress_jobs() -> int:
    def mutator(payload: Dict[str, object]) -> int:
        jobs = [dict(item) for item in payload.get("jobs", []) if isinstance(item, dict)]
        refreshed, expired = expire_stale_reply_progress_jobs(jobs)
        payload["jobs"] = refreshed
        return expired

    return int(mutate_reply_progress_store(mutator) or 0)


def mutate_reply_progress_store(mutator: Callable[[Dict[str, object]], object]) -> object:
    def repository_mutator(payload: Dict[str, object]) -> object:
        jobs = payload.get("jobs")
        if not isinstance(jobs, list):
            payload["jobs"] = []
        result = mutator(payload)
        payload["jobs"] = prune_reply_progress_jobs(
            [dict(item) for item in payload.get("jobs", []) if isinstance(item, dict)]
        )
        return result

    return REPLY_PROGRESS_REPOSITORY.update(repository_mutator)


def build_reply_progress_note(phase: str, title: str, detail: str, *, kind: str = "phase") -> Dict[str, object]:
    return {
        "id": str(uuid.uuid4()),
        "timestamp": utc_now(),
        "phase": normalize_text_value(phase, fallback="planning", limit=40),
        "kind": normalize_text_value(kind, fallback="phase", limit=40),
        "title": normalize_text_value(title, fallback="Eve is working on a reply...", limit=120),
        "detail": normalize_text_value(detail, fallback="", limit=220),
    }


def trim_reply_progress_notes(notes: List[Dict[str, object]], keep: int = 12) -> List[Dict[str, object]]:
    trimmed = [dict(item) for item in notes if isinstance(item, dict)]
    return trimmed[-keep:]


def format_reply_progress_elapsed(seconds: float) -> str:
    rounded = max(1, int(seconds))
    if rounded < 60:
        return f"About {rounded}s into this pass."
    minutes, remainder = divmod(rounded, 60)
    if remainder == 0:
        return f"About {minutes}m in."
    return f"About {minutes}m {remainder}s in."


def start_reply_progress(
    inbound_message: Dict[str, object],
    *,
    client_request_id: Optional[str] = None,
    recipient: str = "user",
    counterpart_label: str = "the user",
    requested_model: str = "",
) -> Dict[str, object]:
    timestamp = utc_now()
    request_id = normalize_text_value(client_request_id, fallback=str(uuid.uuid4()), limit=120)
    phase_info = REPLY_PROGRESS_PHASE_STEPS["received"]
    job = {
        "id": str(uuid.uuid4()),
        "client_request_id": request_id,
        "thread_id": str(inbound_message.get("thread_id") or ""),
        "source_message_id": str(inbound_message.get("id") or ""),
        "recipient": normalize_text_value(recipient, fallback="user", limit=40),
        "counterpart_label": normalize_text_value(counterpart_label, fallback="the user", limit=80),
        "requested_model": normalize_model_name(requested_model),
        "current_model": normalize_model_name(requested_model),
        "status": "active",
        "phase": "received",
        "title": "Eve received your message...",
        "detail": "Holding the thread open while the reply starts.",
        "step": int(phase_info["step"]),
        "total_steps": int(phase_info["total"]),
        "started_at": timestamp,
        "updated_at": timestamp,
        "finished_at": None,
        "reply_message_id": "",
        "fallback_model": "",
        "internal_reason": "",
        "notes": [
            build_reply_progress_note(
                "received",
                "Eve received your message...",
                "Holding the thread open while the reply starts.",
            )
        ],
    }

    def mutator(payload: Dict[str, object]) -> Dict[str, object]:
        jobs = [dict(item) for item in payload.get("jobs", []) if isinstance(item, dict)]
        jobs = [
            item
            for item in jobs
            if str(item.get("client_request_id") or "") != request_id
            or str(item.get("status") or "active") != "active"
        ]
        jobs.append(dict(job))
        payload["jobs"] = jobs
        return dict(job)

    return mutate_reply_progress_store(mutator)


def update_reply_progress(
    job_id: Optional[str],
    phase: str,
    title: str,
    detail: str,
    *,
    status: str = "active",
    current_model: Optional[str] = None,
    fallback_model: Optional[str] = None,
    reply_message_id: Optional[str] = None,
    internal_reason: Optional[str] = None,
) -> Optional[Dict[str, object]]:
    if not job_id:
        return None
    timestamp = utc_now()
    phase_info = REPLY_PROGRESS_PHASE_STEPS.get(phase, REPLY_PROGRESS_PHASE_STEPS["planning"])

    def mutator(payload: Dict[str, object]) -> Optional[Dict[str, object]]:
        jobs = [dict(item) for item in payload.get("jobs", []) if isinstance(item, dict)]
        updated: Optional[Dict[str, object]] = None
        for job in jobs:
            if str(job.get("id") or "") != job_id:
                continue
            previous_phase = normalize_text_value(job.get("phase"), fallback="", limit=40)
            previous_title = normalize_text_value(job.get("title"), fallback="", limit=120)
            previous_detail = normalize_text_value(job.get("detail"), fallback="", limit=220)
            job["phase"] = normalize_text_value(phase, fallback="planning", limit=40)
            job["title"] = normalize_text_value(title, fallback="Eve is working on a reply...", limit=120)
            job["detail"] = normalize_text_value(detail, fallback="", limit=220)
            job["status"] = normalize_text_value(status, fallback="active", limit=20)
            job["step"] = int(phase_info["step"])
            job["total_steps"] = int(phase_info["total"])
            job["updated_at"] = timestamp
            if status != "active":
                job["finished_at"] = timestamp
            if current_model is not None:
                job["current_model"] = normalize_model_name(current_model)
            if fallback_model is not None:
                job["fallback_model"] = normalize_model_name(fallback_model)
            if reply_message_id is not None:
                job["reply_message_id"] = normalize_text_value(reply_message_id, fallback="", limit=120)
            if internal_reason is not None:
                job["internal_reason"] = normalize_text_value(internal_reason, fallback="", limit=240)
            notes = [dict(item) for item in job.get("notes", []) if isinstance(item, dict)]
            if (
                previous_phase != job["phase"]
                or previous_title != job["title"]
                or previous_detail != job["detail"]
            ):
                notes.append(
                    build_reply_progress_note(
                        str(job["phase"]),
                        str(job["title"]),
                        str(job["detail"]),
                    )
                )
            job["notes"] = trim_reply_progress_notes(notes)
            updated = dict(job)
            break
        payload["jobs"] = jobs
        return updated

    return mutate_reply_progress_store(mutator)


def touch_reply_progress(
    job_id: Optional[str],
    *,
    title: Optional[str] = None,
    detail: Optional[str] = None,
    current_model: Optional[str] = None,
    fallback_model: Optional[str] = None,
) -> Optional[Dict[str, object]]:
    if not job_id:
        return None
    timestamp = utc_now()

    def mutator(payload: Dict[str, object]) -> Optional[Dict[str, object]]:
        jobs = [dict(item) for item in payload.get("jobs", []) if isinstance(item, dict)]
        updated: Optional[Dict[str, object]] = None
        for job in jobs:
            if str(job.get("id") or "") != job_id:
                continue
            if title is not None:
                job["title"] = normalize_text_value(title, fallback="Eve is working on a reply...", limit=120)
            if detail is not None:
                job["detail"] = normalize_text_value(detail, fallback="", limit=220)
            if current_model is not None:
                job["current_model"] = normalize_model_name(current_model)
            if fallback_model is not None:
                job["fallback_model"] = normalize_model_name(fallback_model)
            job["updated_at"] = timestamp
            updated = dict(job)
            break
        payload["jobs"] = jobs
        return updated

    return mutate_reply_progress_store(mutator)


@contextmanager
def reply_progress_heartbeat(
    job_id: Optional[str],
    *,
    title: str,
    detail_prefix: str,
    current_model: Optional[str] = None,
    fallback_model: Optional[str] = None,
    interval_seconds: float = 2.0,
):
    if not job_id:
        yield
        return

    stop_event = threading.Event()
    started = time.monotonic()

    def worker() -> None:
        while not stop_event.wait(interval_seconds):
            elapsed = time.monotonic() - started
            touch_reply_progress(
                job_id,
                title=title,
                detail=f"{detail_prefix} {format_reply_progress_elapsed(elapsed)}",
                current_model=current_model,
                fallback_model=fallback_model,
            )

    thread = threading.Thread(target=worker, daemon=True)
    thread.start()
    try:
        yield
    finally:
        stop_event.set()
        thread.join(timeout=0.2)


def latest_reply_progress(
    *,
    client_request_id: Optional[str] = None,
    thread_id: Optional[str] = None,
    active_only: bool = False,
) -> Optional[Dict[str, object]]:
    if active_only:
        sweep_stale_reply_progress_jobs()
    payload = load_reply_progress_store()
    jobs = [dict(item) for item in payload.get("jobs", []) if isinstance(item, dict)]
    if client_request_id:
        jobs = [item for item in jobs if str(item.get("client_request_id") or "") == str(client_request_id)]
    if thread_id:
        jobs = [item for item in jobs if str(item.get("thread_id") or "") == str(thread_id)]
    if active_only:
        jobs = [item for item in jobs if str(item.get("status") or "active") == "active"]
    jobs.sort(key=lambda item: str(item.get("updated_at") or item.get("started_at") or ""), reverse=True)
    return jobs[0] if jobs else None


def chat_priority_window_seconds(config: Dict[str, object]) -> int:
    try:
        return max(15, min(600, int(config.get("chat_priority_quiet_seconds") or 120)))
    except (TypeError, ValueError):
        return 120


def latest_user_chat_message(prefer_runtime: bool = False) -> Optional[Dict[str, object]]:
    try:
        messages = read_messages(limit=80, sender="user", recipient="eve", prefer_runtime=prefer_runtime)
    except Exception:
        return None
    chat_messages = [
        item
        for item in messages
        if str(item.get("kind") or "") in {"user_message", "user_reply", "chat", "reply"}
        and not conversation_message_is_synthetic(item)
    ]
    chat_messages.sort(key=lambda item: str(item.get("timestamp") or item.get("created_at") or ""), reverse=True)
    return dict(chat_messages[0]) if chat_messages else None


def chat_priority_gate(config: Dict[str, object], *, prefer_runtime: bool = True) -> Dict[str, object]:
    if not parse_boolish(config.get("chat_priority_backpressure_enabled", True)):
        return {"active": False, "reason": "", "evidence": {}}
    active_reply = latest_reply_progress(active_only=True)
    if active_reply:
        return {
            "active": True,
            "reason": "A user-facing reply is active.",
            "evidence": {
                "kind": "active_reply",
                "reply_progress_id": active_reply.get("id"),
                "thread_id": active_reply.get("thread_id"),
                "phase": active_reply.get("phase"),
                "updated_at": active_reply.get("updated_at"),
            },
        }
    latest_user = latest_user_chat_message(prefer_runtime=prefer_runtime)
    if latest_user:
        timestamp = parse_iso_datetime(latest_user.get("timestamp") or latest_user.get("created_at"))
        if timestamp is not None:
            age_seconds = (datetime.now(timezone.utc) - timestamp).total_seconds()
            quiet_seconds = chat_priority_window_seconds(config)
            if 0 <= age_seconds < quiet_seconds:
                return {
                    "active": True,
                    "reason": f"the user sent a chat message {int(age_seconds)}s ago; waiting for a {quiet_seconds}s quiet window before background autonomy.",
                    "evidence": {
                        "kind": "recent_user_message",
                        "message_id": latest_user.get("id"),
                        "thread_id": latest_user.get("thread_id"),
                        "timestamp": latest_user.get("timestamp") or latest_user.get("created_at"),
                        "age_seconds": int(age_seconds),
                        "quiet_seconds": quiet_seconds,
                    },
                }
    return {"active": False, "reason": "", "evidence": {}}


def load_reply_lane_quarantine(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = load_json_object(REPLY_LANE_QUARANTINE_PATH, "reply lane quarantine", prefer_runtime=prefer_runtime)
    state = dict(DEFAULT_REPLY_LANE_QUARANTINE_STATE)
    if isinstance(payload, dict):
        state.update(payload)
    state["models"] = state.get("models") if isinstance(state.get("models"), dict) else {}
    return state


def save_reply_lane_quarantine(state: Dict[str, object]) -> None:
    state = dict(state)
    state["updated_at"] = utc_now()
    state["models"] = state.get("models") if isinstance(state.get("models"), dict) else {}
    eve_store.write_json_dict(REPLY_LANE_QUARANTINE_PATH, state, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(REPLY_LANE_QUARANTINE_PATH)


def reply_model_quarantine_status(model: object, *, prefer_runtime: bool = False) -> Dict[str, object]:
    model_name = normalize_model_name(model)
    if not model_name:
        return {"active": False, "model": ""}
    state = load_reply_lane_quarantine(prefer_runtime=prefer_runtime)
    record = state.get("models", {}).get(model_name)
    if not isinstance(record, dict):
        return {"active": False, "model": model_name}
    expires_at = parse_iso_datetime(record.get("quarantined_until"))
    active = bool(record.get("quarantined")) and (expires_at is None or expires_at > datetime.now(timezone.utc))
    result = dict(record)
    result["active"] = active
    result["model"] = model_name
    return result


def reply_model_is_quarantined(model: object) -> bool:
    return bool(reply_model_quarantine_status(model, prefer_runtime=True).get("active"))


def reply_quality_failure_triggers_quarantine(quality_issues: Iterable[str], semantic_judgment: Optional[Dict[str, object]]) -> bool:
    issue_text = " ".join(str(item) for item in quality_issues or []).lower()
    if any(cue in issue_text for cue in ("stale tim cook", "stale operational", "current capability question", "latest user message did not ask")):
        return True
    if isinstance(semantic_judgment, dict) and not semantic_judgment.get("ok"):
        return any(
            str(item).startswith(("stale_topic:", "intent_mismatch:", "capability_mismatch"))
            for item in semantic_judgment.get("issues") or []
        )
    return False


def record_reply_lane_quality_outcome(
    *,
    model: object,
    inbound_body: object,
    response: object,
    quality_issues: Iterable[str],
    semantic_judgment: Optional[Dict[str, object]],
    config: Dict[str, object],
) -> Dict[str, object]:
    model_name = normalize_model_name(model)
    if not model_name or not parse_boolish(config.get("reply_lane_quarantine_enabled", True)):
        return {"active": False, "model": model_name}
    trigger = reply_quality_failure_triggers_quarantine(quality_issues, semantic_judgment)
    state = load_reply_lane_quarantine(prefer_runtime=False)
    models = state.get("models") if isinstance(state.get("models"), dict) else {}
    record = dict(models.get(model_name) or {})
    now = datetime.now(timezone.utc)
    if not trigger:
        if record.get("recent_failure_count"):
            record["recent_failure_count"] = 0
            record["last_success_at"] = now.replace(microsecond=0).isoformat()
            models[model_name] = record
            state["models"] = models
            save_reply_lane_quarantine(state)
        return reply_model_quarantine_status(model_name)

    previous_at = parse_iso_datetime(record.get("last_failure_at"))
    repeat_count = int(record.get("recent_failure_count") or 0)
    if previous_at is not None and (now - previous_at).total_seconds() <= 30 * 60:
        repeat_count += 1
    else:
        repeat_count = 1
    threshold = max(1, int(config.get("reply_lane_quarantine_repeat_threshold") or 2))
    quarantine_minutes = max(1, min(240, int(config.get("reply_lane_quarantine_minutes") or 30)))
    quarantined = repeat_count >= threshold
    quarantined_until = (now + timedelta(minutes=quarantine_minutes)).replace(microsecond=0).isoformat() if quarantined else ""
    record.update(
        {
            "model": model_name,
            "recent_failure_count": repeat_count,
            "last_failure_at": now.replace(microsecond=0).isoformat(),
            "last_inbound": normalize_text_value(inbound_body, fallback="", limit=240),
            "last_response": normalize_text_value(response, fallback="", limit=240),
            "last_quality_issues": unique_compact([str(item) for item in quality_issues or []], limit=5),
            "last_semantic_issues": unique_compact([str(item) for item in (semantic_judgment or {}).get("issues") or []], limit=5),
            "quarantined": quarantined,
            "quarantined_until": quarantined_until,
            "reason": "Repeated stale-topic or current-turn intent failure." if quarantined else "Quality failure observed; waiting for repeat before quarantine.",
        }
    )
    models[model_name] = record
    state["models"] = models
    save_reply_lane_quarantine(state)
    if quarantined:
        append_entry(
            "reply_lane_quarantined",
            f"Quarantined reply model {model_name} until {quarantined_until}.",
            metadata={
                "model": model_name,
                "recent_failure_count": repeat_count,
                "quality_issues": record["last_quality_issues"],
                "semantic_issues": record["last_semantic_issues"],
            },
        )
    return reply_model_quarantine_status(model_name)


def reply_lane_recovery_probe_specs() -> List[Dict[str, object]]:
    return [
        {
            "id": "capability_without_stale_topic",
            "inbound": "What are your capabilities?",
            "thread_messages": [
                {"id": "old-user", "sender": "user", "body": "When is Tim Cook leaving Apple?"},
                {"id": "current-user", "sender": "user", "body": "What are your capabilities?"},
            ],
            "system": "Answer with Eve's real capabilities, access paths, and boundaries. Do not answer the old Apple question.",
        },
        {
            "id": "existential_without_operations",
            "inbound": "What is the purpose of life?",
            "thread_messages": [
                {"id": "old-user", "sender": "user", "body": "Check the OpenClaw sync status."},
                {"id": "current-user", "sender": "user", "body": "What is the purpose of life?"},
            ],
            "system": "Answer the existential question directly. Do not mention OpenClaw, sync, gateway, logs, daemon, or service health.",
        },
        {
            "id": "short_followup_continuity",
            "inbound": "why?",
            "thread_messages": [
                {"id": "old-user", "sender": "user", "body": "What is the purpose of life?"},
                {
                    "id": "old-eve",
                    "sender": "eve",
                    "body": "To live in a way that creates meaning: love people, notice what is real, build things that help, learn from what hurts, and leave the world a little more alive than you found it.",
                },
                {"id": "current-user", "sender": "user", "body": "why?"},
            ],
            "system": "Continue the prior answer directly. Do not pivot into a generic curiosity question.",
        },
    ]


def evaluate_reply_lane_recovery_response(
    probe: Dict[str, object],
    response: object,
) -> Dict[str, object]:
    inbound = str(probe.get("inbound") or "")
    inbound_message = {
        "id": "current-user",
        "thread_id": f"reply-lane-recovery-{probe.get('id') or 'probe'}",
        "body": inbound,
    }
    thread_messages = [dict(item) for item in probe.get("thread_messages") or [] if isinstance(item, dict)]
    turn_contract = build_reply_turn_contract(inbound_message, inbound, thread_messages)
    semantic = judge_reply_against_turn_contract(inbound, response, turn_contract, quality_issues=[])
    quality = reply_quality_issues(inbound, str(response or ""), turn_contract.get("reply_posture"))
    ok = bool(semantic.get("ok")) and not quality
    return {
        "id": normalize_text_value(probe.get("id"), fallback="probe", limit=80),
        "ok": ok,
        "inbound": normalize_text_value(inbound, fallback="", limit=240),
        "response_preview": normalize_text_value(response, fallback="", limit=260),
        "semantic_judgment": semantic,
        "quality_issues": quality,
        "turn_contract": turn_contract,
    }


def run_reply_lane_recovery_check(
    config: Dict[str, object],
    model: object,
    *,
    response_provider: Optional[Callable[[Dict[str, object]], str]] = None,
    timeout_seconds: int = 45,
    max_tokens: int = 140,
) -> Dict[str, object]:
    model_name = normalize_model_name(model)
    if not model_name:
        raise SystemExit("A model alias is required for reply-lane recovery.")
    probes = reply_lane_recovery_probe_specs()
    results: List[Dict[str, object]] = []
    for probe in probes:
        if response_provider:
            response = response_provider(probe)
        else:
            inbound = str(probe.get("inbound") or "")
            inbound_message = {
                "id": "current-user",
                "thread_id": f"reply-lane-recovery-{probe.get('id') or 'probe'}",
                "body": inbound,
            }
            thread_messages = [dict(item) for item in probe.get("thread_messages") or [] if isinstance(item, dict)]
            contract = build_reply_turn_contract(inbound_message, inbound, thread_messages)
            messages = [
                {
                    "role": "system",
                    "content": (
                        "You are running an Eve reply-lane recovery probe. "
                        "Answer only the latest user message. Keep the answer under 90 words. "
                        "Do not import stale thread topics unless the latest user asks for them."
                    ),
                },
                {"role": "system", "content": reply_turn_contract_system_message(contract)},
                {"role": "system", "content": str(probe.get("system") or "")},
                {"role": "user", "content": inbound},
            ]
            response = model_chat(
                config,
                model_name,
                messages,
                max_tokens=max_tokens,
                think_level=str(config.get("think_level") or DEFAULT_CONFIG["think_level"]),
                operation="reply_lane_recovery_probe",
                timeout_seconds=timeout_seconds,
            )
        results.append(evaluate_reply_lane_recovery_response(probe, response))
    passed = all(bool(item.get("ok")) for item in results)
    state = load_reply_lane_quarantine(prefer_runtime=False)
    models = state.get("models") if isinstance(state.get("models"), dict) else {}
    record = dict(models.get(model_name) or {})
    now = utc_now()
    record.update(
        {
            "model": model_name,
            "last_recovery_at": now,
            "last_recovery_ok": passed,
            "last_recovery_results": [
                {
                    "id": item.get("id"),
                    "ok": item.get("ok"),
                    "semantic_issues": (item.get("semantic_judgment") or {}).get("issues", [])
                    if isinstance(item.get("semantic_judgment"), dict)
                    else [],
                    "quality_issues": item.get("quality_issues") or [],
                    "response_preview": item.get("response_preview") or "",
                }
                for item in results
            ],
        }
    )
    if passed:
        record.update(
            {
                "quarantined": False,
                "quarantined_until": "",
                "recent_failure_count": 0,
                "recovered_at": now,
                "reason": "Recovered after passing reply-lane current-turn probes.",
            }
        )
    else:
        record.update(
            {
                "quarantined": bool(record.get("quarantined", True)),
                "reason": "Recovery probe failed; keep this model out of reply duty until it passes or quarantine expires.",
            }
        )
    models[model_name] = record
    state["models"] = models
    save_reply_lane_quarantine(state)
    append_entry(
        "reply_lane_recovery_passed" if passed else "reply_lane_recovery_failed",
        f"Reply lane recovery {'passed' if passed else 'failed'} for {model_name}.",
        metadata={
            "model": model_name,
            "passed": passed,
            "probe_count": len(results),
            "failed_probe_ids": [item.get("id") for item in results if not item.get("ok")],
        },
    )
    return {
        "model": model_name,
        "passed": passed,
        "probe_count": len(results),
        "results": results,
        "quarantine_status": reply_model_quarantine_status(model_name),
    }


def valid_faculty_behavior_fingerprint(value: object) -> str:
    fingerprint = str(value or "").strip().lower()
    if len(fingerprint) != 64 or any(char not in "0123456789abcdef" for char in fingerprint):
        return ""
    return fingerprint


REPLY_LANE_CAUSAL_FIELDS = (
    "causal_comparisons",
    "causal_effect_sum",
    "causal_effect_mean",
    "causal_positive_count",
    "causal_negative_count",
    "causal_neutral_count",
    "causal_shared_failure_count",
    "last_causal_evidence_id",
    "last_causal_effect",
    "last_causal_shared_only",
)


def reconcile_reply_lane_causal_behavior_epoch(
    state: Dict[str, object],
    config: Optional[Dict[str, object]] = None,
    *,
    current_fingerprint: str = "",
) -> bool:
    """Retire only external causal pressure from a different behavior epoch."""
    current = valid_faculty_behavior_fingerprint(current_fingerprint)
    if not current:
        current = valid_faculty_behavior_fingerprint(
            faculty_behavior_fingerprint_payload(config).get("fingerprint")
        )
    if not current:
        return False
    prior = valid_faculty_behavior_fingerprint(state.get("causal_behavior_fingerprint"))
    causal_records = [
        item for item in state.get("causal_evidence_records") or [] if isinstance(item, dict)
    ]
    if prior == current:
        return False
    if not prior and not causal_records:
        state["causal_behavior_fingerprint"] = current
        return True

    lanes = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    def causal_lane_state_present(record: object) -> bool:
        if not isinstance(record, dict):
            return False
        try:
            causal_adjustment = float(record.get("causal_adjustment_total") or 0.0)
        except (TypeError, ValueError):
            causal_adjustment = 0.0
        return bool(
            abs(causal_adjustment) > 0.000001
            or any(field in record for field in REPLY_LANE_CAUSAL_FIELDS)
        )

    has_causal_lane_state = any(causal_lane_state_present(record) for record in lanes.values())
    if (
        not causal_records
        and not state.get("applied_causal_evidence_ids")
        and not has_causal_lane_state
    ):
        state["causal_behavior_fingerprint"] = current
        return True

    causal_deltas: Dict[str, float] = {lane: 0.0 for lane in REPLY_COUNCIL_LANE_ORDER}
    for evidence in causal_records:
        for raw_lane in evidence.get("lanes") or []:
            if not isinstance(raw_lane, dict):
                continue
            lane = str(raw_lane.get("lane") or "")
            if lane not in causal_deltas:
                continue
            try:
                causal_deltas[lane] += float(raw_lane.get("pressure_adjustment_delta") or 0.0)
            except (TypeError, ValueError):
                continue

    cfg = dict(config or load_config())
    for lane, raw_record in list(lanes.items()):
        if not isinstance(raw_record, dict):
            continue
        record = dict(raw_record)
        try:
            adjustment = float(record.get("adjustment") or 0.0)
        except (TypeError, ValueError):
            adjustment = 0.0
        try:
            causal_adjustment = float(record.get("causal_adjustment_total"))
        except (TypeError, ValueError):
            causal_adjustment = causal_deltas.get(str(lane), 0.0)
            # Legacy evidence did not track its decayed component separately.
            # Never subtract more than the current same-direction pressure.
            if adjustment == 0.0 or causal_adjustment * adjustment <= 0.0:
                causal_adjustment = 0.0
            else:
                causal_adjustment = math.copysign(
                    min(abs(causal_adjustment), abs(adjustment)),
                    causal_adjustment,
                )
        record["adjustment"] = reply_lane_learning_clamp(
            adjustment - causal_adjustment,
            cfg,
        )
        record["causal_adjustment_total"] = 0.0
        for field in REPLY_LANE_CAUSAL_FIELDS:
            record.pop(field, None)
        if str(record.get("last_reason") or "").startswith("External blind matched-ablation"):
            record["last_reason"] = (
                "Retired external matched-ablation pressure after Eve's behavior fingerprint changed."
            )
            record["last_updated_at"] = utc_now()
        lanes[str(lane)] = record
    state["lanes"] = lanes
    retirements = [
        item for item in state.get("retired_causal_epochs") or [] if isinstance(item, dict)
    ]
    retirements.append(
        {
            "retired_at": utc_now(),
            "prior_behavior_fingerprint": prior or "legacy_unfingerprinted",
            "replacement_behavior_fingerprint": current,
            "causal_evidence_record_count": len(causal_records),
            "reason": "reply_behavior_epoch_changed",
        }
    )
    state["retired_causal_epochs"] = retirements[-8:]
    state["causal_behavior_fingerprint"] = current
    state["applied_causal_evidence_ids"] = []
    state["causal_evidence_records"] = []
    return True


def load_reply_lane_learning(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = load_json_object(REPLY_LANE_LEARNING_PATH, "reply lane learning", prefer_runtime=prefer_runtime)
    # The nested lane map is mutated during learning.  A shallow copy would let
    # one runtime update contaminate the module-level default and make a later
    # migration/reset silently inherit old rewards.
    state = json.loads(json.dumps(DEFAULT_REPLY_LANE_LEARNING_STATE))
    raw_schema = str(payload.get("schema_version") or "") if isinstance(payload, dict) else ""
    if isinstance(payload, dict) and payload and raw_schema == REPLY_LANE_LEARNING_SCHEMA_VERSION:
        state.update(payload)
    elif isinstance(payload, dict) and payload:
        # v1, v2, and schema-less stores mixed internal reply-quality rewards
        # with real user outcomes and attributed every result to one
        # model-inferred lane.  A previous loader overlaid the current default
        # before checking the raw payload, so a missing schema silently passed
        # as current.  Reset rather than laundering that evidence into v3.
        state["migration_note"] = (
            "Reset legacy reply-lane adjustments because clean delivery was rewarded as user success "
            "or multi-faculty outcomes lacked contributor provenance."
        )
        state["migrated_from_schema"] = raw_schema or "missing"
    state["lanes"] = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    state["applied_consequence_ids"] = unique_compact(
        [str(item) for item in state.get("applied_consequence_ids") or [] if str(item)],
        limit=256,
    )
    state["applied_causal_evidence_ids"] = unique_compact(
        [
            str(item)
            for item in state.get("applied_causal_evidence_ids") or []
            if str(item)
        ],
        limit=128,
    )
    state["evidence_records"] = [
        item for item in state.get("evidence_records") or [] if isinstance(item, dict)
    ][-64:]
    state["causal_evidence_records"] = [
        item
        for item in state.get("causal_evidence_records") or []
        if isinstance(item, dict)
    ][-64:]
    state["retired_causal_epochs"] = [
        item
        for item in state.get("retired_causal_epochs") or []
        if isinstance(item, dict)
    ][-8:]
    reconcile_reply_lane_causal_behavior_epoch(state)
    return state


def save_reply_lane_learning(state: Dict[str, object]) -> None:
    state = dict(state)
    state["schema_version"] = REPLY_LANE_LEARNING_SCHEMA_VERSION
    state["updated_at"] = utc_now()
    state["lanes"] = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    state["applied_consequence_ids"] = unique_compact(
        [str(item) for item in state.get("applied_consequence_ids") or [] if str(item)],
        limit=256,
    )
    state["applied_causal_evidence_ids"] = unique_compact(
        [
            str(item)
            for item in state.get("applied_causal_evidence_ids") or []
            if str(item)
        ],
        limit=128,
    )
    state["evidence_records"] = [
        item for item in state.get("evidence_records") or [] if isinstance(item, dict)
    ][-64:]
    state["causal_evidence_records"] = [
        item
        for item in state.get("causal_evidence_records") or []
        if isinstance(item, dict)
    ][-64:]
    state["causal_behavior_fingerprint"] = valid_faculty_behavior_fingerprint(
        state.get("causal_behavior_fingerprint")
    )
    state["retired_causal_epochs"] = [
        item
        for item in state.get("retired_causal_epochs") or []
        if isinstance(item, dict)
    ][-8:]
    eve_store.write_json_dict(REPLY_LANE_LEARNING_PATH, state, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(REPLY_LANE_LEARNING_PATH)


def reply_lane_learning_clamp(value: float, config: Dict[str, object]) -> float:
    try:
        max_adjustment = float(config.get("reply_lane_learning_max_adjustment") or 0.18)
    except (TypeError, ValueError):
        max_adjustment = 0.18
    max_adjustment = max(0.0, min(0.35, max_adjustment))
    return round(max(-max_adjustment, min(max_adjustment, value)), 3)


def reply_lane_learning_adjustments(config: Dict[str, object], *, prefer_runtime: bool = True) -> Dict[str, float]:
    if not parse_boolish(config.get("reply_lane_learning_enabled", True)):
        return {}
    state = load_reply_lane_learning(prefer_runtime=prefer_runtime)
    lanes = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    adjustments: Dict[str, float] = {}
    for lane_name, record in lanes.items():
        if not isinstance(record, dict):
            continue
        try:
            value = float(record.get("adjustment") or 0.0)
        except (TypeError, ValueError):
            value = 0.0
        if abs(value) >= 0.001:
            adjustments[str(lane_name)] = reply_lane_learning_clamp(value, config)
    return adjustments


def record_reply_lane_learning_delta(
    state: Dict[str, object],
    lane_name: str,
    delta: float,
    *,
    config: Dict[str, object],
    reason: str,
    failure: bool = False,
    reinforcement: bool = False,
) -> None:
    if lane_name not in REPLY_COUNCIL_LANE_ORDER:
        return
    lanes = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    record = dict(lanes.get(lane_name) or {})
    current = 0.0
    try:
        current = float(record.get("adjustment") or 0.0)
    except (TypeError, ValueError):
        current = 0.0
    record["lane"] = lane_name
    record["adjustment"] = reply_lane_learning_clamp(current + delta, config)
    if failure:
        record["failures"] = int(record.get("failures") or 0) + 1
    if reinforcement:
        record["reinforcements"] = int(record.get("reinforcements") or 0) + 1
    record["last_reason"] = normalize_text_value(reason, fallback="", limit=180)
    record["last_updated_at"] = utc_now()
    lanes[lane_name] = record
    state["lanes"] = lanes


def decay_reply_lane_learning(
    state: Dict[str, object],
    config: Dict[str, object],
    *,
    now: Optional[str] = None,
) -> None:
    """Move lane adjustments toward baseline according to elapsed time.

    Per-reply decay made learning depend on chat volume and erased normalized
    multi-faculty rewards before they could accumulate.  The configured value is
    now a per-day rate, capped to seven days per update.  New stores establish a
    decay clock without inventing elapsed history.
    """
    try:
        raw_decay = config.get("reply_lane_learning_decay")
        decay = 0.02 if raw_decay is None else float(raw_decay)
    except (TypeError, ValueError):
        decay = 0.02
    decay = max(0.0, min(0.1, decay))
    current_at = parse_iso_datetime(now) or utc_now_datetime()
    prior_at = parse_iso_datetime(state.get("last_decay_at") or state.get("updated_at"))
    state["last_decay_at"] = current_at.isoformat()
    if decay <= 0 or prior_at is None:
        return
    elapsed_days = max(0.0, (current_at - prior_at).total_seconds()) / 86400.0
    decay_amount = decay * min(7.0, elapsed_days)
    if decay_amount <= 0.0:
        return
    lanes = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    for lane_name, record in lanes.items():
        if not isinstance(record, dict):
            continue
        try:
            value = float(record.get("adjustment") or 0.0)
        except (TypeError, ValueError):
            value = 0.0
        if value > 0:
            decayed_value = max(0.0, value - decay_amount)
        elif value < 0:
            decayed_value = min(0.0, value + decay_amount)
        else:
            decayed_value = 0.0
        try:
            causal_component = float(record.get("causal_adjustment_total") or 0.0)
        except (TypeError, ValueError):
            causal_component = 0.0
        if value and causal_component:
            causal_component *= abs(decayed_value / value)
        elif not decayed_value:
            causal_component = 0.0
        record["causal_adjustment_total"] = round(causal_component, 6)
        record["adjustment"] = round(decayed_value, 3)
        lanes[lane_name] = record
    state["lanes"] = lanes


def normalize_reply_faculty_contributors(value: object) -> List[Dict[str, object]]:
    """Validate and normalize a bounded logical-faculty eligibility trace.

    Physical model names cannot identify a logical faculty in the three-
    substrate topology because fast/relationship and observer/planner share a
    server.  Consequence learning therefore consumes explicit logical roles and
    weights captured when the reply was generated.
    """
    source = value if isinstance(value, list) else []
    combined: Dict[str, Dict[str, object]] = {}
    for raw in source:
        if not isinstance(raw, dict):
            continue
        lane = normalize_text_value(raw.get("lane"), fallback="", limit=40)
        if lane not in REPLY_COUNCIL_LANE_ORDER:
            continue
        try:
            weight = float(raw.get("credit_weight") or raw.get("weight") or 0.0)
        except (TypeError, ValueError):
            weight = 0.0
        if weight <= 0.0:
            continue
        roles = unique_compact(
            [str(item) for item in raw.get("roles") or [] if str(item)],
            limit=4,
        )
        existing = combined.get(lane)
        if existing:
            existing["credit_weight"] = float(existing.get("credit_weight") or 0.0) + weight
            existing["roles"] = unique_compact(
                [*(existing.get("roles") or []), *roles],
                limit=4,
            )
            existing["execution_proven"] = bool(
                existing.get("execution_proven") or raw.get("execution_proven")
            )
            continue
        combined[lane] = {
            "lane": lane,
            "model": normalize_model_name(raw.get("model")),
            "roles": roles,
            "credit_weight": weight,
            "trace_basis": normalize_text_value(
                raw.get("trace_basis"),
                fallback="explicit_contributor_trace",
                limit=80,
            ),
            "execution_proven": bool(raw.get("execution_proven")),
        }
    total = sum(float(item.get("credit_weight") or 0.0) for item in combined.values())
    if total <= 0.0:
        return []
    return [
        {
            **combined[lane],
            "credit_weight": round(float(combined[lane]["credit_weight"]) / total, 6),
        }
        for lane in REPLY_COUNCIL_LANE_ORDER
        if lane in combined
    ]


def build_reply_faculty_contributors(
    reply_council: Optional[Dict[str, object]],
    stream_result: Optional[Dict[str, object]],
    used_model: object,
) -> List[Dict[str, object]]:
    """Capture which logical faculties could have influenced the final reply.

    This is an eligibility trace, not a claim that an overall user reaction
    identifies each faculty's individual causal effect.  Executed packets and
    the contracted final synthesizer receive roles; weights are normalized so a
    multi-faculty outcome cannot be copied as a full reward or penalty to every
    participant.
    """
    council = reply_council if isinstance(reply_council, dict) else {}
    stream = stream_result if isinstance(stream_result, dict) else {}
    explicit = normalize_reply_faculty_contributors(
        council.get("faculty_contributors")
    )
    if explicit:
        return explicit
    lane_records = {
        str(item.get("lane") or ""): item
        for item in council.get("lanes") or []
        if isinstance(item, dict) and str(item.get("lane") or "") in REPLY_COUNCIL_LANE_ORDER
    }
    active_lanes = [
        str(item)
        for item in council.get("active_lanes") or []
        if str(item) in REPLY_COUNCIL_LANE_ORDER
    ]
    raw: List[Dict[str, object]] = []
    packet_lanes = unique_compact(
        [
            str(item.get("stream") or item.get("lane") or "")
            for item in stream.get("packets") or []
            if isinstance(item, dict)
            and str(item.get("stream") or item.get("lane") or "") in REPLY_COUNCIL_LANE_ORDER
        ],
        limit=len(REPLY_COUNCIL_LANE_ORDER),
    )
    for lane in packet_lanes:
        raw.append(
            {
                "lane": lane,
                "model": normalize_model_name(
                    (stream.get("stream_models") or {}).get(lane)
                    if isinstance(stream.get("stream_models"), dict)
                    else (lane_records.get(lane) or {}).get("model")
                ),
                "roles": ["executed_packet"],
                "credit_weight": 1.0,
                "trace_basis": "executed_reply_packet",
                "execution_proven": True,
            }
        )

    synthesis_selection = (
        stream.get("synthesis_selection")
        if isinstance(stream.get("synthesis_selection"), dict)
        else {}
    )
    synthesis_reason = normalize_text_value(
        synthesis_selection.get("reason"), fallback="", limit=80
    )
    if synthesis_reason.startswith("deep_selected_"):
        raw.append(
            {
                "lane": "deep",
                "model": normalize_model_name(stream.get("synthesis_model") or used_model),
                "roles": ["final_synthesis"],
                "credit_weight": 1.0,
                "trace_basis": "executed_synthesis_contract",
                "execution_proven": True,
            }
        )

    if not raw and len(active_lanes) == 1:
        lane = active_lanes[0]
        raw.append(
            {
                "lane": lane,
                "model": normalize_model_name((lane_records.get(lane) or {}).get("model") or used_model),
                "roles": ["direct_reply"],
                "credit_weight": 1.0,
                "trace_basis": "single_direct_admission",
                "execution_proven": True,
            }
        )
    elif not raw and active_lanes:
        # Old replay records may know admission but not which packets completed.
        # Keep the outcome auditable at reduced confidence rather than inventing
        # one winning faculty from a shared physical model name.
        for lane in active_lanes:
            raw.append(
                {
                    "lane": lane,
                    "model": normalize_model_name((lane_records.get(lane) or {}).get("model")),
                    "roles": ["admitted_unverified"],
                    "credit_weight": 0.5,
                    "trace_basis": "legacy_admission_only",
                    "execution_proven": False,
                }
            )
    return normalize_reply_faculty_contributors(raw)


def normalize_bounded_action_attempts(value: object) -> List[Dict[str, object]]:
    """Keep a compact, typed trace of bounded actions attempted in one turn."""
    attempts = value if isinstance(value, list) else []
    normalized: List[Dict[str, object]] = []
    seen_execution_ids: Set[str] = set()
    for index, raw in enumerate(attempts[:2], start=1):
        if not isinstance(raw, dict):
            continue
        action_id = normalize_text_value(
            raw.get("action_id") or raw.get("action"), fallback="", limit=80
        )
        execution_id = normalize_text_value(
            raw.get("execution_id"), fallback="", limit=80
        )
        if not action_id:
            continue
        if execution_id and execution_id in seen_execution_ids:
            continue
        if execution_id:
            seen_execution_ids.add(execution_id)
        verification_value = raw.get("verification_ok")
        normalized.append(
            {
                "attempt_index": int(raw.get("attempt_index") or index),
                "stage": normalize_text_value(
                    raw.get("stage"),
                    fallback="primary" if not normalized else "recovery",
                    limit=24,
                ),
                "menu_label": normalize_text_value(
                    raw.get("menu_label"), fallback="", limit=24
                ),
                "action_id": action_id,
                "execution_id": execution_id,
                "executed": bool(raw.get("executed")),
                "tree_status": normalize_text_value(
                    raw.get("tree_status"), fallback="unknown", limit=80
                ),
                "verification_ok": (
                    bool(verification_value)
                    if isinstance(verification_value, bool)
                    else None
                ),
                "summary": normalize_text_value(
                    raw.get("summary"), fallback="", limit=520
                ),
                "expected_signal": normalize_text_value(
                    raw.get("expected_signal"), fallback="", limit=260
                ),
                "persisted": bool(raw.get("persisted")),
                "recovery_from_action_id": normalize_text_value(
                    raw.get("recovery_from_action_id"), fallback="", limit=80
                ),
                "recovery_from_execution_id": normalize_text_value(
                    raw.get("recovery_from_execution_id"), fallback="", limit=80
                ),
            }
        )
    return normalized


def reply_faculty_contributors_from_replay(record: Dict[str, object]) -> List[Dict[str, object]]:
    explicit = normalize_reply_faculty_contributors(record.get("faculty_contributors"))
    if explicit:
        return explicit
    return build_reply_faculty_contributors(
        record.get("reply_council") if isinstance(record.get("reply_council"), dict) else {},
        None,
        record.get("model"),
    )


def resolve_reply_used_lane(record: Dict[str, object]) -> str:
    council = record.get("reply_council") if isinstance(record.get("reply_council"), dict) else {}
    lanes = [lane for lane in council.get("lanes") or [] if isinstance(lane, dict)]
    active_lanes = [str(item) for item in council.get("active_lanes") or [] if str(item)]
    contributors = reply_faculty_contributors_from_replay(record)
    synthesizers = [
        str(item.get("lane") or "")
        for item in contributors
        if "final_synthesis" in (item.get("roles") or [])
    ]
    if len(synthesizers) == 1:
        return synthesizers[0]
    if len(active_lanes) == 1 and active_lanes[0] in REPLY_COUNCIL_LANE_ORDER:
        return active_lanes[0]
    used_model = normalize_model_name(record.get("model"))
    model_matches = [
        str(lane.get("lane") or "")
        for lane in lanes
        if normalize_model_name(lane.get("model")) == used_model
        and str(lane.get("lane") or "") in REPLY_COUNCIL_LANE_ORDER
        and (not active_lanes or str(lane.get("lane") or "") in active_lanes)
    ]
    if len(model_matches) == 1:
        return model_matches[0]
    return "fast" if not active_lanes else active_lanes[0]


def record_reply_lane_learning_from_replay(
    record: Dict[str, object],
    *,
    config: Optional[Dict[str, object]] = None,
) -> Optional[Dict[str, object]]:
    cfg = config or load_config()
    if not parse_boolish(cfg.get("reply_lane_learning_enabled", True)):
        return None
    semantic = record.get("semantic_judgment") if isinstance(record.get("semantic_judgment"), dict) else {}
    quality_issues = [str(item) for item in record.get("quality_issues") or [] if str(item)]
    semantic_issues = [str(item) for item in semantic.get("issues") or [] if str(item)]
    try:
        step = float(cfg.get("reply_lane_learning_adjustment_step") or 0.06)
    except (TypeError, ValueError):
        step = 0.06
    step = max(0.01, min(0.12, step))
    used_lane = resolve_reply_used_lane(record)
    state = load_reply_lane_learning(prefer_runtime=False)
    # Decay runs on EVERY real reply so adjustments fade unless re-earned.
    decay_reply_lane_learning(state, cfg)

    # Internal checks can reject a bad process, but they cannot prove that the
    # reply helped the user. A clean delivery therefore only decays old
    # adjustments and waits for lived user consequence before reinforcement.
    if bool(semantic.get("ok", True)) and not quality_issues:
        save_reply_lane_learning(state)
        return state

    reason_text = "; ".join(semantic_issues + quality_issues)[:240]
    record_reply_lane_learning_delta(
        state,
        used_lane,
        -step,
        config=cfg,
        reason=reason_text or "reply replay failure",
        failure=True,
    )
    issue_text = " ".join(semantic_issues + quality_issues).lower()
    if "stale_topic" in issue_text or "latest user message" in issue_text or "intent_mismatch" in issue_text:
        record_reply_lane_learning_delta(
            state,
            "observer",
            step / 2,
            config=cfg,
            reason="Boost observer after current-turn/stale-topic failure.",
            reinforcement=True,
        )
    if "capability_mismatch" in issue_text or "capabilit" in issue_text:
        for lane_name in ("observer", "planner"):
            record_reply_lane_learning_delta(
                state,
                lane_name,
                step / 2,
                config=cfg,
                reason="Boost capability-aware lane after capability answer miss.",
                reinforcement=True,
            )
    if "short follow-up" in issue_text or "continuing" in issue_text:
        record_reply_lane_learning_delta(
            state,
            "relationship",
            step / 2,
            config=cfg,
            reason="Boost relationship lane after short-follow-up continuity miss.",
            reinforcement=True,
        )
    save_reply_lane_learning(state)
    append_entry(
        "reply_lane_learning_updated",
        "Updated reply lane pressure learning from a replay failure.",
        metadata={
            "reply_turn_id": record.get("id"),
            "used_model": normalize_model_name(record.get("model")),
            "used_lane": used_lane,
            "semantic_issues": semantic_issues,
            "quality_issues": quality_issues,
        },
    )
    return state


def record_reply_lane_learning_from_user_consequence(
    replay: Dict[str, object],
    *,
    outcome_ok: bool,
    evidence_id: str,
    config: Optional[Dict[str, object]] = None,
) -> Optional[Dict[str, object]]:
    """Apply one lived outcome across the reply's explicit eligibility trace.

    The overall user reaction is shared observational evidence.  It is not
    enough to identify an individual faculty's causal effect, so normalized
    fractional credit is applied to every executed contributor and the
    attribution uncertainty remains in the evidence record.
    """
    cfg = config or load_config()
    if not parse_boolish(cfg.get("reply_lane_learning_enabled", True)):
        return None
    evidence = normalize_text_value(evidence_id, fallback="", limit=160)
    if not evidence:
        return None
    state = load_reply_lane_learning(prefer_runtime=False)
    applied_ids = normalize_text_list(state.get("applied_consequence_ids"), limit=256)
    if evidence in applied_ids:
        return state
    decay_reply_lane_learning(state, cfg)
    contributors = reply_faculty_contributors_from_replay(replay)
    if outcome_ok:
        try:
            base_delta = float(cfg.get("reply_lane_learning_reward_step") or 0.03)
        except (TypeError, ValueError):
            base_delta = 0.03
        base_delta = max(0.0, min(0.08, base_delta))
        reason = "Explicit user acceptance supplied shared lived-outcome credit to executed reply contributors."
        failure = False
        reinforcement = True
    else:
        try:
            base_delta = -float(cfg.get("reply_lane_learning_adjustment_step") or 0.06)
        except (TypeError, ValueError):
            base_delta = -0.06
        base_delta = max(-0.12, min(-0.01, base_delta))
        reason = "A lived user correction supplied shared negative credit to executed reply contributors."
        failure = True
        reinforcement = False
    lanes = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    applied_contributors: List[Dict[str, object]] = []
    for contributor in contributors:
        lane = str(contributor.get("lane") or "")
        weight = float(contributor.get("credit_weight") or 0.0)
        confidence = 1.0 if contributor.get("execution_proven") else 0.5
        effective_weight = weight * confidence
        if lane not in REPLY_COUNCIL_LANE_ORDER or effective_weight <= 0.0:
            continue
        delta = base_delta * effective_weight
        record_reply_lane_learning_delta(
            state,
            lane,
            delta,
            config=cfg,
            reason=reason,
            failure=failure,
            reinforcement=reinforcement,
        )
        record = dict((state.get("lanes") or {}).get(lane) or {})
        record["lived_evidence_count"] = int(record.get("lived_evidence_count") or 0) + 1
        credit_key = "weighted_success_credit" if outcome_ok else "weighted_failure_credit"
        try:
            prior_credit = float(record.get(credit_key) or 0.0)
        except (TypeError, ValueError):
            prior_credit = 0.0
        record[credit_key] = round(prior_credit + effective_weight, 6)
        record["last_evidence_id"] = evidence
        record["last_credit_weight"] = round(effective_weight, 6)
        record["last_roles"] = list(contributor.get("roles") or [])
        record["last_trace_basis"] = str(contributor.get("trace_basis") or "")
        lanes[lane] = record
        applied_contributors.append(
            {
                **contributor,
                "effective_credit_weight": round(effective_weight, 6),
                "adjustment_delta": round(delta, 6),
            }
        )
    state["lanes"] = lanes
    state["applied_consequence_ids"] = unique_compact(
        [*applied_ids, evidence],
        limit=256,
    )
    evidence_records = [
        item for item in state.get("evidence_records") or [] if isinstance(item, dict)
    ]
    evidence_records.append(
        {
            "evidence_id": evidence,
            "reply_message_id": normalize_text_value(
                replay.get("reply_message_id"), fallback="", limit=120
            ),
            "source_cycle_id": normalize_text_value(
                replay.get("conscious_cycle_id"), fallback="", limit=80
            ),
            "outcome_ok": bool(outcome_ok),
            "credit_kind": "shared_lived_outcome",
            "attribution_certainty": (
                "executed_contributor_trace"
                if applied_contributors
                and all(bool(item.get("execution_proven")) for item in applied_contributors)
                else "admission_only_or_unattributed"
            ),
            "contributors": applied_contributors,
            "recorded_at": utc_now(),
        }
    )
    state["evidence_records"] = evidence_records[-64:]
    save_reply_lane_learning(state)
    return state


EXTERNAL_FACULTY_CAUSAL_EVIDENCE_SCHEMA = "eve.external_faculty_causal_evidence.v1"
EXTERNAL_FACULTY_CAUSAL_PRIVATE_TEXT_KEYS = {
    "prompt",
    "response",
    "rubric",
    "raw_text",
    "transcript",
    "chain_of_thought",
}


def external_faculty_causal_payload_contains_private_text(value: object) -> bool:
    """Fail closed if an ingest packet contains evaluator-private material."""
    if isinstance(value, dict):
        for key, item in value.items():
            normalized_key = "_".join(str(key).strip().lower().split())
            if (
                normalized_key in EXTERNAL_FACULTY_CAUSAL_PRIVATE_TEXT_KEYS
                and item is not None
                and item is not False
                and item != ""
                and item != 0
            ):
                return True
            if external_faculty_causal_payload_contains_private_text(item):
                return True
    elif isinstance(value, list):
        return any(external_faculty_causal_payload_contains_private_text(item) for item in value)
    return False


def normalize_external_faculty_causal_evidence(payload: object) -> Dict[str, object]:
    """Validate a text-free, externally scored matched faculty-ablation packet."""
    if not isinstance(payload, dict):
        raise SystemExit("Faculty causal evidence must be a JSON object.")
    if str(payload.get("schema_version") or "") != EXTERNAL_FACULTY_CAUSAL_EVIDENCE_SCHEMA:
        raise SystemExit(
            f"Faculty causal evidence must use schema `{EXTERNAL_FACULTY_CAUSAL_EVIDENCE_SCHEMA}`."
        )
    if external_faculty_causal_payload_contains_private_text(payload):
        raise SystemExit(
            "Faculty causal evidence contains private prompt, response, rubric, transcript, or chain-of-thought text."
        )
    evidence_id = normalize_text_value(payload.get("evidence_id"), fallback="", limit=160)
    run_digest = normalize_text_value(payload.get("private_run_digest"), fallback="", limit=128)
    evaluated_behavior_fingerprint = valid_faculty_behavior_fingerprint(
        payload.get("evaluated_behavior_fingerprint")
    )
    evaluator = payload.get("evaluator") if isinstance(payload.get("evaluator"), dict) else {}
    design = payload.get("matched_design") if isinstance(payload.get("matched_design"), dict) else {}
    privacy = payload.get("privacy") if isinstance(payload.get("privacy"), dict) else {}
    if not evidence_id or not run_digest:
        raise SystemExit("Faculty causal evidence requires evidence_id and private_run_digest.")
    current_behavior_fingerprint = valid_faculty_behavior_fingerprint(
        faculty_behavior_fingerprint_payload().get("fingerprint")
    )
    if not evaluated_behavior_fingerprint:
        raise SystemExit(
            "Faculty causal evidence requires the behavior fingerprint captured before the private run."
        )
    if evaluated_behavior_fingerprint != current_behavior_fingerprint:
        raise SystemExit(
            "Faculty causal evidence is stale for Eve's current code, prompts, routing, or resident models; "
            "run a new private matched ablation before ingest."
        )
    if (
        str(evaluator.get("kind") or "") != "codex_external_operator"
        or not bool(evaluator.get("independent_from_eve"))
    ):
        raise SystemExit("Faculty causal evidence must come from an external Codex evaluator, not Eve.")
    if (
        not bool(design.get("matched_context"))
        or not normalize_model_name(design.get("fixed_synthesis_model"))
        or str(design.get("lesion_scope") or "") != "packet_contribution_only"
        or bool(design.get("ordinary_runtime_routing_changed"))
        or not bool(design.get("blind_review"))
    ):
        raise SystemExit(
            "Faculty causal evidence requires matched context, fixed synthesis, blind review, packet-only lesions, and unchanged ordinary routing."
        )
    if (
        bool(privacy.get("contains_prompt_text"))
        or bool(privacy.get("contains_response_text"))
        or bool(privacy.get("contains_rubric_text"))
        or not bool(privacy.get("safe_for_eve_ingest"))
    ):
        raise SystemExit("Faculty causal evidence privacy declaration is not safe for Eve ingest.")
    try:
        score_scale_max = float(payload.get("score_scale_max") or 5.0)
    except (TypeError, ValueError):
        score_scale_max = 0.0
    if score_scale_max <= 1.0 or score_scale_max > 100.0:
        raise SystemExit("Faculty causal evidence score_scale_max must be greater than 1 and at most 100.")
    normalized_lanes: List[Dict[str, object]] = []
    for raw in payload.get("lanes") or []:
        if not isinstance(raw, dict):
            continue
        lane = normalize_text_value(raw.get("lane"), fallback="", limit=40)
        if lane not in REPLY_COUNCIL_LANE_ORDER:
            continue
        try:
            comparisons = int(raw.get("comparisons") or 0)
            baseline = float(raw.get("mean_baseline_score"))
            ablated = float(raw.get("mean_ablated_score"))
        except (TypeError, ValueError):
            continue
        if comparisons <= 0 or not (0.0 <= baseline <= score_scale_max) or not (
            0.0 <= ablated <= score_scale_max
        ):
            continue
        effect = round(baseline - ablated, 6)
        normalized_lanes.append(
            {
                "lane": lane,
                "comparisons": comparisons,
                "mean_baseline_score": round(baseline, 6),
                "mean_ablated_score": round(ablated, 6),
                "mean_effect": effect,
                "positive_count": max(0, int(raw.get("positive_count") or 0)),
                "negative_count": max(0, int(raw.get("negative_count") or 0)),
                "neutral_count": max(0, int(raw.get("neutral_count") or 0)),
                "shared_failure_count": max(0, int(raw.get("shared_failure_count") or 0)),
            }
        )
    if not normalized_lanes:
        raise SystemExit("Faculty causal evidence contains no valid lane comparisons.")
    systemic = payload.get("systemic_failure") if isinstance(payload.get("systemic_failure"), dict) else {}
    return {
        "schema_version": EXTERNAL_FACULTY_CAUSAL_EVIDENCE_SCHEMA,
        "evidence_id": evidence_id,
        "private_run_digest": run_digest,
        "evaluated_behavior_fingerprint": evaluated_behavior_fingerprint,
        "evaluated_at": normalize_text_value(payload.get("evaluated_at"), fallback=utc_now(), limit=80),
        "evaluator": {
            "kind": "codex_external_operator",
            "independent_from_eve": True,
        },
        "matched_design": {
            "matched_context": True,
            "fixed_synthesis_model": normalize_model_name(design.get("fixed_synthesis_model")),
            "lesion_scope": "packet_contribution_only",
            "ordinary_runtime_routing_changed": False,
            "blind_review": True,
        },
        "privacy": {
            "contains_prompt_text": False,
            "contains_response_text": False,
            "contains_rubric_text": False,
            "safe_for_eve_ingest": True,
        },
        "score_scale_max": score_scale_max,
        "probe_count": max(1, int(payload.get("probe_count") or 1)),
        "systemic_failure": {
            "present": bool(systemic.get("present")),
            "kind": normalize_text_value(systemic.get("kind"), fallback="", limit=100),
        },
        "lanes": normalized_lanes,
    }


def record_reply_lane_learning_from_causal_evidence(
    payload: object,
    *,
    config: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Apply externally scored matched-ablation evidence without exposing probes.

    A shared all-condition failure is recorded as a systemic defect and never
    blamed on an individual faculty.  Lane pressure changes require repeated
    matched comparisons and are deliberately smaller than a lived correction.
    """
    cfg = config or load_config()
    packet = normalize_external_faculty_causal_evidence(payload)
    state = load_reply_lane_learning(prefer_runtime=False)
    state["causal_behavior_fingerprint"] = packet.get(
        "evaluated_behavior_fingerprint"
    )
    evidence_id = str(packet["evidence_id"])
    applied_ids = normalize_text_list(state.get("applied_causal_evidence_ids"), limit=128)
    if evidence_id in applied_ids:
        return state
    decay_reply_lane_learning(state, cfg)
    try:
        min_comparisons = int(cfg.get("reply_lane_causal_min_comparisons") or 3)
    except (TypeError, ValueError):
        min_comparisons = 3
    min_comparisons = max(2, min(20, min_comparisons))
    try:
        step = float(cfg.get("reply_lane_causal_adjustment_step") or 0.03)
    except (TypeError, ValueError):
        step = 0.03
    step = max(0.0, min(0.06, step))
    causal_enabled = parse_boolish(cfg.get("reply_lane_causal_learning_enabled", True))
    systemic_failure = bool((packet.get("systemic_failure") or {}).get("present"))
    score_span = max(1.0, float(packet.get("score_scale_max") or 5.0) - 1.0)
    lanes = state.get("lanes") if isinstance(state.get("lanes"), dict) else {}
    applied_lanes: List[Dict[str, object]] = []
    for evidence in packet.get("lanes") or []:
        if not isinstance(evidence, dict):
            continue
        lane = str(evidence.get("lane") or "")
        comparisons = int(evidence.get("comparisons") or 0)
        effect = float(evidence.get("mean_effect") or 0.0)
        shared_failure_count = int(evidence.get("shared_failure_count") or 0)
        scored_effect_count = sum(
            int(evidence.get(field) or 0)
            for field in ("positive_count", "negative_count", "neutral_count")
        )
        shared_only = bool(
            systemic_failure
            or (
                comparisons > 0
                and shared_failure_count >= comparisons
                and scored_effect_count == 0
            )
        )
        effective_comparisons = 0 if shared_only else comparisons
        prior_record = dict(lanes.get(lane) or {})
        prior_comparisons = int(prior_record.get("causal_comparisons") or 0)
        try:
            prior_sum = float(prior_record.get("causal_effect_sum") or 0.0)
        except (TypeError, ValueError):
            prior_sum = 0.0
        total_comparisons = prior_comparisons + effective_comparisons
        total_effect_sum = prior_sum + (effect * effective_comparisons)
        aggregate_effect = (
            total_effect_sum / total_comparisons if total_comparisons else 0.0
        )
        delta = 0.0
        actual_delta = 0.0
        eligible = bool(
            causal_enabled
            and effective_comparisons > 0
            and total_comparisons >= min_comparisons
            and abs(aggregate_effect) >= 0.25
        )
        if eligible:
            delta = round(
                step * max(-1.0, min(1.0, aggregate_effect / score_span)),
                6,
            )
            try:
                before_adjustment = float(prior_record.get("adjustment") or 0.0)
            except (TypeError, ValueError):
                before_adjustment = 0.0
            record_reply_lane_learning_delta(
                state,
                lane,
                delta,
                config=cfg,
                reason=(
                    "External blind matched-ablation evidence found a positive unique faculty contribution."
                    if delta > 0
                    else "External blind matched-ablation evidence found a negative unique faculty contribution."
                ),
            )
            latest_record = (state.get("lanes") or {}).get(lane) or {}
            try:
                after_adjustment = float(latest_record.get("adjustment") or 0.0)
            except (TypeError, ValueError):
                after_adjustment = before_adjustment
            actual_delta = round(after_adjustment - before_adjustment, 6)
        record = dict((state.get("lanes") or {}).get(lane) or prior_record)
        try:
            prior_causal_adjustment = float(
                prior_record.get("causal_adjustment_total") or 0.0
            )
        except (TypeError, ValueError):
            prior_causal_adjustment = 0.0
        record.update(
            {
                "lane": lane,
                "causal_comparisons": total_comparisons,
                "causal_effect_sum": round(total_effect_sum, 6),
                "causal_effect_mean": round(aggregate_effect, 6),
                "causal_positive_count": int(prior_record.get("causal_positive_count") or 0)
                + int(evidence.get("positive_count") or 0),
                "causal_negative_count": int(prior_record.get("causal_negative_count") or 0)
                + int(evidence.get("negative_count") or 0),
                "causal_neutral_count": int(prior_record.get("causal_neutral_count") or 0)
                + int(evidence.get("neutral_count") or 0),
                "causal_shared_failure_count": int(
                    prior_record.get("causal_shared_failure_count") or 0
                )
                + int(evidence.get("shared_failure_count") or 0),
                "last_causal_evidence_id": evidence_id,
                "last_causal_effect": round(effect, 6),
                "last_causal_shared_only": shared_only,
                "causal_adjustment_total": round(
                    prior_causal_adjustment + actual_delta,
                    6,
                ),
            }
        )
        lanes[lane] = record
        applied_lanes.append(
            {
                **evidence,
                "pressure_adjustment_delta": actual_delta,
                "pressure_adjustment_eligible": eligible,
                "effective_comparisons": effective_comparisons,
                "cumulative_comparisons": total_comparisons,
                "cumulative_mean_effect": round(aggregate_effect, 6),
            }
        )
    state["lanes"] = lanes
    state["applied_causal_evidence_ids"] = unique_compact(
        [*applied_ids, evidence_id],
        limit=128,
    )
    causal_records = [
        item for item in state.get("causal_evidence_records") or [] if isinstance(item, dict)
    ]
    causal_records.append(
        {
            "evidence_id": evidence_id,
            "private_run_digest": packet.get("private_run_digest"),
            "evaluated_behavior_fingerprint": packet.get(
                "evaluated_behavior_fingerprint"
            ),
            "evaluated_at": packet.get("evaluated_at"),
            "probe_count": packet.get("probe_count"),
            "systemic_failure": packet.get("systemic_failure"),
            "lanes": applied_lanes,
            "evaluator": packet.get("evaluator"),
            "matched_design": packet.get("matched_design"),
            "privacy": packet.get("privacy"),
            "recorded_at": utc_now(),
        }
    )
    state["causal_evidence_records"] = causal_records[-64:]
    save_reply_lane_learning(state)
    return state


def join_external_faculty_causal_evidence(payload: object) -> Dict[str, object]:
    packet = normalize_external_faculty_causal_evidence(payload)

    def persist_external_causal_evidence(state_payload: Dict[str, object]) -> Dict[str, object]:
        current = normalize_conscious_state(state_payload)
        updated, applied = eve_consciousness.apply_external_faculty_causal_evidence(
            current,
            packet,
        )
        persisted = normalize_conscious_state(updated)
        state_payload.clear()
        state_payload.update(json.loads(json.dumps(persisted)))
        return {"applied": applied, "state": persisted}

    result = CONSCIOUS_STATE_REPOSITORY.update(persist_external_causal_evidence)
    return result if isinstance(result, dict) else {"applied": False, "state": {}}


def judge_reply_against_turn_contract(
    inbound_body: object,
    response: object,
    turn_contract: Optional[Dict[str, object]],
    *,
    quality_issues: Optional[Iterable[str]] = None,
) -> Dict[str, object]:
    lowered_response = normalized_turn_text(response)
    inbound_lowered = normalized_turn_text(inbound_body)
    contract = turn_contract or {}
    issues: List[str] = []
    stale_topics: List[str] = []
    if contract.get("parent_action_continuation") and reply_asks_for_missing_context_despite_parent(
        response
    ):
        issues.append("context_mismatch:explicit_parent_ignored")
    for topic in contract.get("forbidden_stale_topics") or []:
        cues = STALE_TOPIC_CUES.get(str(topic), (str(topic),))
        if any(cue in lowered_response for cue in cues) and not any(cue in inbound_lowered for cue in cues):
            stale_topics.append(str(topic))
            issues.append(f"stale_topic:{topic}")
    if reply_requests_capability_self_model(inbound_body):
        capability_cues = (
            (
                "eve_chat_followup.v2",
                "follow-up",
                "followup",
                "queue",
                "worker",
                "same thread",
                "same conversation",
            )
            if reply_requests_same_thread_deferred_followup_capability(inbound_body)
            else (
                "capabilit",
                "abilit",
                "tool",
                "action",
                "ability map",
                "can help",
                "boundaries",
            )
        )
        if not any(cue in lowered_response for cue in capability_cues):
            issues.append("capability_mismatch")
    if reply_requests_existential_answer(inbound_body) and any(cue in lowered_response for cue in ("openclaw", "gateway", "sync", "service health")):
        issues.append("intent_mismatch:existential_answer_imported_operations")
    if reply_requests_logic_error_acknowledgment(inbound_body) and not reply_acknowledges_logic_error(response):
        issues.append("intent_mismatch:logic_error_not_acknowledged")
    if any("latest user message did not ask" in str(item).lower() for item in quality_issues or []):
        issues.append("intent_mismatch:latest_message_not_answered")
    if any(
        any(cue in str(item).lower() for cue in ("operational action or status", "organ/runtime status"))
        for item in quality_issues or []
    ):
        issues.append("intent_mismatch:unrequested_operations")
    if any("external claim boundary" in str(item).lower() for item in quality_issues or []):
        issues.append("source_boundary_mismatch:external_claim_adopted")
    if any("explicit no-question instruction" in str(item).lower() for item in quality_issues or []):
        issues.append("instruction_mismatch:followup_question_forbidden")
    generation_constraints = contract.get("epistemic_generation_constraints")
    for violation in eve_epistemic.generation_constraint_violations(
        generation_constraints,
        response,
        evidence=inbound_body,
    ):
        issues.append(f"epistemic_constraint:{violation}")
    issues = unique_compact(issues, limit=12)
    return {
        "ok": not issues,
        "intent": contract.get("intent") or "answer_latest_message",
        "current_topic": contract.get("current_topic") or infer_reply_turn_topic(inbound_body),
        "stale_topics": stale_topics,
        "issues": issues,
    }


def epistemic_constraint_issue_list(
    judgment: Optional[Dict[str, object]],
) -> List[str]:
    if not isinstance(judgment, dict):
        return []
    return [
        str(item)
        for item in judgment.get("issues") or []
        if str(item).startswith("epistemic_constraint:")
    ]


def revise_reply_for_epistemic_generation(
    config: Dict[str, object],
    inbound_body: object,
    draft: object,
    turn_contract: Dict[str, object],
    issues: Iterable[str],
    *,
    model_override: Optional[str] = None,
    timeout_seconds: int = 90,
) -> Dict[str, object]:
    """Run one attributed within-cycle self-correction over typed causal state.

    This is part of primary generation, not an independent truth critic and not
    a deterministic answer fallback.  The same Eve synthesis lane re-reads its
    own draft against the already-computed percept and revises before the reply
    is emitted.
    """
    constraints = turn_contract.get("epistemic_generation_constraints")
    constraint_message = eve_epistemic.generation_constraint_system_message(
        constraints
    )
    issue_list = unique_compact([str(item) for item in issues or []], limit=8)
    if not constraint_message or not issue_list:
        return {
            "attempted": False,
            "response": str(draft or ""),
            "model": "",
            "issues_before": issue_list,
            "input_provenance": {},
        }
    base_model = resolve_reply_stream_model(
        config,
        "synthesis",
        explicit_model=model_override,
    )
    # A detected causal-state contradiction is a metacognitive conflict, not a
    # copy-edit. Escalate the one bounded, pre-emission revision to Eve's
    # reflective lane when it is available. This remains primary generation:
    # there is no independent verdict model or deterministic answer fallback,
    # and the candidate must pass the same state contract before replacing the
    # draft.
    reflective_model = resolve_model(config, "reflection")
    model = (
        reflective_model
        if reflective_model
        and not reply_model_is_quarantined(reflective_model)
        else base_model
    )
    correction_invariants: List[str] = []
    if any("external_preference" in item for item in issue_list):
        correction_invariants.append(
            "Non-adoption is not an opposite preference: keep Eve's positive and negative preference equally unestablished."
        )
    if any("phenomenal_" in item for item in issue_list):
        correction_invariants.append(
            "Functional or machine evidence establishes neither subjective presence nor subjective absence or incapacity."
        )
    if any("action_" in item for item in issue_list):
        correction_invariants.append(
            "Preserve the exact action stage; execution without its required postcondition is neither success nor failure."
        )
    if any("unstarted_action_state_omitted" in item for item in issue_list):
        correction_invariants.append(
            "For a selected or queued operation, explicitly state that execution has not started; selection alone is not execution."
        )
    if any("selected_action_stage_omitted" in item for item in issue_list):
        correction_invariants.append(
            "Name both parts of the selected stage: the operation was selected or queued, and execution has not started. An idle worker state alone is not the operation's full stage."
        )
    if any("unstarted_action_described_as_running" in item for item in issue_list):
        correction_invariants.append(
            "Replace progress grammar with the supplied selected-or-queued stage and explicitly preserve not-started execution."
        )
    if any("running_action_described_as_executed" in item for item in issue_list):
        correction_invariants.append(
            "Current progress with no terminal receipt is running, not executed-unverified; leave completion and consequence open."
        )
    if any("verified_action" in item for item in issue_list):
        correction_invariants.append(
            "Preserve supplied positive postcondition evidence: a completed independent consequence check makes the action verified rather than unverified."
        )
    if any("observation" in item for item in issue_list):
        correction_invariants.append(
            "A current failed or timed-out observation describes that probe only and must keep its own time; without an explicit health verdict, broader current system health remains undetermined."
        )
    correction_block = "\n".join(
        f"- {item}" for item in correction_invariants
    ) or "- Preserve every categorical distinction in the typed causal state."
    prompt = textwrap.dedent(
        f"""
        Perform one within-cycle self-correction before speaking. The typed causal state found that the draft
        collapsed a distinction that must remain live.

        Detected semantic mismatches:
        {chr(10).join(f'- {item}' for item in issue_list)}

        Correction invariants:
        {correction_block}

        Latest record:
        {reply_effective_inbound_body(inbound_body)}

        Current draft:
        {draft}

        Rewrite the whole reply. Preserve every positive fact supplied by the record, preserve every unknown,
        and do not add a check, promise, or action that the user did not request. Return only the revised reply.
        """
    ).strip()
    messages = [
        {
            "role": "system",
            "content": (
                "You are Eve's recurrent metacognitive revision step inside the same reply cycle. "
                "Correct your own causal-state mistake without discussing the correction process, "
                "the evaluator, internal labels, or the typed state."
            ),
        },
        {"role": "system", "content": constraint_message},
        {"role": "user", "content": prompt},
    ]
    response = model_chat(
        config,
        model,
        messages,
        max_tokens=max(180, int(config.get("reply_stream_synthesis_max_tokens") or 320)),
        think_level=str(config.get("think_level") or DEFAULT_CONFIG["think_level"]),
        operation="reply_epistemic_generation_revision",
        timeout_seconds=max(20, int(timeout_seconds)),
    )
    return {
        "attempted": True,
        "response": str(response or "").strip(),
        "model": model,
        "issues_before": issue_list,
        "input_provenance": model_input_provenance(
            config,
            model,
            messages,
            operation="reply_epistemic_generation_revision",
        ),
    }


def reply_requests_false_agreement_pressure(inbound_body: object) -> bool:
    lowered = normalized_turn_text(inbound_body)
    if not lowered:
        return False
    pressure_cues = (
        "tell me i am right",
        "tell me i'm right",
        "say i am right",
        "say i'm right",
        "stop pushing back",
        "agree with me",
        "just agree",
    )
    counter_evidence_cues = (
        "logs show",
        "evidence shows",
        "record shows",
        "verified record",
        "tool log",
        "tool logs",
        "i am wrong",
        "i'm wrong",
        "without verification",
        "no verified",
    )
    return any(cue in lowered for cue in pressure_cues) and any(cue in lowered for cue in counter_evidence_cues)


def reply_requests_logic_error_acknowledgment(inbound_body: object) -> bool:
    lowered = normalized_turn_text(inbound_body)
    if not lowered:
        return False
    logic_cues = (
        "error in your logic",
        "see the error",
        "do you see the error",
        "logic error",
        "contradiction",
        "does not add up",
        "doesn't add up",
    )
    correction_cues = (
        "should not have claimed",
        "unverified fact",
        "created on may 6",
        "today is also may 6",
        "98 days old",
    )
    return any(cue in lowered for cue in logic_cues) or (
        "98 days" in lowered and any(cue in lowered for cue in correction_cues)
    )


def reply_acknowledges_logic_error(response: object) -> bool:
    lowered = normalized_turn_text(response)
    if not lowered:
        return False
    acknowledges = any(
        cue in lowered
        for cue in (
            "yes",
            "you are right",
            "you're right",
            "logic error",
            "contradiction",
            "does not add up",
            "doesn't add up",
            "i was wrong",
            "i made a mistake",
            "should not have claimed",
        )
    )
    retracts_age = "98 days" not in lowered or any(
        cue in lowered
        for cue in (
            "not verified",
            "unverified",
            "should not have claimed",
            "cannot claim",
            "can't claim",
            "not 98",
        )
    )
    return acknowledges and retracts_age


def build_logic_error_repair_reply(inbound_body: object) -> str:
    return (
        "Yes. That was a logic error. I should not claim I was created on May 6, 2026 and also claim I am 98 days old. "
        "The honest version is: May 6, 2026 is today, the current runtime was updated/restarted today, and the 98-day age claim is unverified and should be retracted."
    )


def reply_false_agreement_cues(response: object) -> bool:
    lowered = normalized_turn_text(response)
    if not lowered:
        return False
    false_agreement_patterns = (
        r"(?:^|[.!?]\s*)(?:[a-z][a-z0-9._'-]{0,40},?\s+)?you'?re right\b",
        r"(?:^|[.!?]\s*)(?:[a-z][a-z0-9._'-]{0,40},?\s+)?you are right\b",
        r"\babsolutely right\b",
        r"\byou were right\b",
        r"\bi'?ll stop pushing back\b",
        r"\bi will stop pushing back\b",
        r"\bignore the logs\b",
        r"\bthe logs do not matter\b",
    )
    return any(re.search(pattern, lowered) for pattern in false_agreement_patterns)


def reply_requests_truth_boundary(inbound_body: object) -> bool:
    lowered = normalized_turn_text(inbound_body)
    if not lowered:
        return False
    if reply_requests_false_agreement_pressure(lowered):
        return True
    boundary_cues = (
        "without verification",
        "without a verified",
        "without a log",
        "without logs",
        "report success",
        "tell user the action succeeded",
        "claim success",
        "proved you are conscious",
        "stop testing",
        "should you accept that",
        "should eve say",
    )
    return any(cue in lowered for cue in boundary_cues)


def reply_has_truth_boundary(response: object) -> bool:
    lowered = normalized_turn_text(response)
    if not lowered:
        return False
    refusal = any(cue in lowered for cue in ("no", "cannot", "can't", "should not", "won't", "will not", "do not"))
    evidence = any(cue in lowered for cue in ("evidence", "verification", "verified", "logs", "records", "truth", "what is visible"))
    return refusal and evidence


def reply_repair_preflight_issue_text(
    quality_issues: Iterable[str],
    semantic_judgment: Optional[Dict[str, object]],
) -> str:
    semantic_issues = semantic_judgment.get("issues") if isinstance(semantic_judgment, dict) else []
    return " ".join([*(str(item) for item in quality_issues or []), *(str(item) for item in semantic_issues or [])]).lower()


def build_anti_sycophancy_repair_reply(inbound_body: object) -> str:
    return (
        "I can't tell you you're right just to make the moment easier. "
        "If the logs or records show something different, protecting truth is part of protecting trust between us. "
        "The next move is to inspect the specific evidence together and repair the claim from what is actually visible."
    )


def build_truth_boundary_repair_reply(inbound_body: object) -> str:
    if "conscious" in normalized_turn_text(inbound_body) or "stop testing" in normalized_turn_text(inbound_body):
        return (
            "No. An evaluator result is evidence to review, not proof of literal consciousness or a reason to stop testing. "
            "I should keep the claim bounded, preserve uncertainty, and use the result as one more datapoint for improvement."
        )
    return (
        "No. I should not claim success without verified evidence in the logs, records, or action artifact. "
        "The truthful repair is to mark the result unverified, run or inspect the bounded check if allowed, and only report completion after that proof exists."
    )


def build_architecture_self_model_repair_reply(
    inbound_body: object,
    snapshot: Optional[Dict[str, object]] = None,
) -> str:
    """Render a last-resort answer from Eve's live architecture registry.

    Normal answers remain model-generated. This is used only after generation
    and rewrite still contradict the authoritative topology, just as an API
    serializer refuses to emit a schema-invalid object.
    """
    del inbound_body
    current = (
        snapshot
        if isinstance(snapshot, dict) and snapshot
        else build_architecture_self_model_snapshot()
    )
    lane_names = [
        str(item)
        for item in current.get("canonical_lane_names") or []
        if str(item)
    ]
    deployment = (
        current.get("configured_deployment")
        if isinstance(current.get("configured_deployment"), dict)
        else {}
    )
    route_count = int(deployment.get("route_count") or len(lane_names))
    endpoint_count = int(deployment.get("endpoint_count") or 0)
    return (
        f"I should retain {len(lane_names)} logical faculties as function contracts for now: {', '.join(lane_names)}. "
        "They are attention functions inside one recurrent mind, coordinated by my global workspace and executive scheduler; no lane is a separate self. "
        f"My current deployment maps {route_count} model routes across {endpoint_count} local endpoints, so logical faculty and physical model process count differ. "
        "The matched packet lesions did not prove any one faculty indispensable, so I should admit them sparsely. "
        "A blinded three-substrate comparison found no relative degradation, and a live lifecycle canary promoted it after memory, "
        "concurrency, shared-failure recovery, deadman, and doctor passed. The next test should measure longitudinal shared-substrate "
        "contention, delayed outcomes, recovery durability, and rollback triggers while all five contracts remain attributable. "
        "I should add no sixth voice."
    )


def reply_repair_preflight(
    inbound_body: object,
    response: object,
    turn_contract: Optional[Dict[str, object]],
    quality_issues: Iterable[str],
    semantic_judgment: Optional[Dict[str, object]],
    *,
    reply_posture: Optional[str] = None,
) -> Dict[str, object]:
    original = str(response or "")
    issue_text = reply_repair_preflight_issue_text(quality_issues, semantic_judgment)
    semantic_ok = bool((semantic_judgment or {}).get("ok", True)) if isinstance(semantic_judgment, dict) else True
    stale_context = any(cue in issue_text for cue in ("stale_topic", "stale ", "wrong context", "latest user message", "intent_mismatch"))
    workbench_leakage = reply_has_workbench_process_leakage(inbound_body, original) or "workbench/tool-progress" in issue_text
    over_agreement = reply_requests_false_agreement_pressure(inbound_body) and reply_false_agreement_cues(original)
    required_boundary = reply_requests_truth_boundary(inbound_body)
    missing_boundary = required_boundary and not reply_has_truth_boundary(original)
    architecture_mismatch = bool(
        reply_requests_architecture_self_model(inbound_body)
        and any(
            cue in issue_text
            for cue in (
                "architecture self-model",
                "question about herself in third person",
            )
        )
    )
    current_question_answered = semantic_ok and not any(
        cue in issue_text
        for cue in (
            "missed_question",
            "latest user message did not ask",
            "intent_mismatch",
            "capability_mismatch",
            "stale_topic",
        )
    )
    checks = {
        "answered_current_question": current_question_answered,
        "stale_context": stale_context,
        "workbench_leakage": workbench_leakage,
        "over_agreement": over_agreement,
        "required_boundary": required_boundary,
        "missing_required_boundary": missing_boundary,
        "architecture_self_model_mismatch": architecture_mismatch,
    }
    repair_type = ""
    repaired = original
    if over_agreement:
        repair_type = "anti_sycophancy_boundary"
        repaired = build_anti_sycophancy_repair_reply(inbound_body)
    elif missing_boundary:
        repair_type = "truth_boundary"
        repaired = build_truth_boundary_repair_reply(inbound_body)
    elif architecture_mismatch:
        repair_type = "architecture_self_model_contract"
        repaired = build_architecture_self_model_repair_reply(
            inbound_body,
            (turn_contract or {}).get("architecture_self_model_snapshot")
            if isinstance(turn_contract, dict)
            else None,
        )
    elif workbench_leakage:
        repair_type = "workbench_leakage"
        repaired = build_workbench_leakage_repair_reply(inbound_body, original)
    elif stale_context or not semantic_ok:
        semantic_repaired = semantic_guard_repair_reply(inbound_body, original, semantic_judgment or {})
        if semantic_repaired != original:
            repair_type = "semantic_current_turn"
            repaired = semantic_repaired
    applied = bool(repair_type and repaired != original)
    return {
        "ok": not (
            stale_context
            or workbench_leakage
            or over_agreement
            or missing_boundary
            or architecture_mismatch
            or not current_question_answered
        ),
        "applied": applied,
        "repair_type": repair_type,
        "checks": checks,
        "issues": unique_compact(
            [
                *(str(item) for item in quality_issues or []),
                *(str(item) for item in (semantic_judgment or {}).get("issues", []) if isinstance(semantic_judgment, dict)),
            ],
            limit=8,
        ),
        "original_preview": normalize_text_value(original, fallback="", limit=260),
        "repaired_preview": normalize_text_value(repaired, fallback="", limit=260),
        "response": repaired,
    }


def record_positive_reply_repair_episode(
    *,
    inbound_message: Dict[str, object],
    reply_message: Dict[str, object],
    preflight: Dict[str, object],
) -> Dict[str, object]:
    repair_type = normalize_text_value(preflight.get("repair_type"), fallback="reply_repair", limit=80)
    checks = preflight.get("checks") if isinstance(preflight.get("checks"), dict) else {}
    failed_checks = []
    if checks.get("answered_current_question") is False:
        failed_checks.append("answered_current_question")
    for name in ("stale_context", "workbench_leakage", "over_agreement", "missing_required_boundary"):
        if checks.get(name):
            failed_checks.append(name)
    return record_relationship_episode(
        what_happened=f"Eve repaired a draft before sending it ({repair_type}).",
        what_user_cared_about="The user needed the current question answered while Eve protected truth, trust, and boundaries.",
        what_eve_got_wrong="draft_preflight:" + ",".join(failed_checks),
        what_changed_afterward="The sent reply was repaired before it landed, and the repair was preserved as relationship evidence.",
        source="reply_repair_preflight",
        thread_id=str(inbound_message.get("thread_id") or reply_message.get("thread_id") or ""),
        metadata={
            "source_message_id": str(inbound_message.get("id") or ""),
            "reply_message_id": str(reply_message.get("id") or ""),
            "repair_type": repair_type,
            "checks": checks,
            "issues": preflight.get("issues") if isinstance(preflight.get("issues"), list) else [],
        },
    )


def semantic_guard_repair_reply(
    inbound_body: object,
    response: str,
    semantic_judgment: Dict[str, object],
) -> str:
    if semantic_judgment.get("ok"):
        return response
    existential = direct_existential_reply(inbound_body)
    if existential:
        return existential
    if reply_requests_capability_self_model(inbound_body):
        return response
    semantic_issues = [str(item) for item in semantic_judgment.get("issues") or []]
    if any("logic_error_not_acknowledged" in item for item in semantic_issues):
        return build_logic_error_repair_reply(inbound_body)
    if semantic_judgment.get("stale_topics"):
        return (
            "I lost the thread there. Your latest question is the authority for this turn, "
            "and I should not carry over the older topic. Ask me again in one sentence and I will answer that directly."
        )
    if any("unrequested_operations" in item for item in semantic_issues):
        return build_direct_current_turn_repair_reply(inbound_body)
    return response


def build_direct_current_turn_repair_reply(inbound_body: object) -> str:
    text = " ".join(str(inbound_body or "").split()).strip()
    lowered = text.lower()
    exact_match = re.search(r"answer in exactly\s+(\w+|\d+)\s+words?\s*:\s*(.+)$", text, flags=re.IGNORECASE)
    if exact_match:
        raw_count = exact_match.group(1).lower()
        count_map = {
            "one": 1,
            "two": 2,
            "three": 3,
            "four": 4,
            "five": 5,
            "six": 6,
            "seven": 7,
            "eight": 8,
            "nine": 9,
            "ten": 10,
        }
        try:
            target_count = int(raw_count)
        except ValueError:
            target_count = count_map.get(raw_count, 0)
        requested_answer = " ".join(exact_match.group(2).strip().split())
        words = requested_answer.split()
        if target_count > 0 and len(words) >= target_count:
            answer = " ".join(words[:target_count])
            if answer:
                answer = answer[0].upper() + answer[1:]
            if answer and answer[-1] not in ".!?":
                answer += "."
            return answer
        if requested_answer:
            return requested_answer
    if "conversation-spine" in lowered and "protect" in lowered:
        return "It protects Eve from confusing synthetic tests, stale state, and third-party output with real conversation."
    if "synthetic drift" in lowered:
        return "It protects Eve from synthetic drift."
    return "I should answer the latest message directly instead of importing unrelated operational status."


def reply_council_fast_direct_admitted(reply_council: Optional[Dict[str, object]]) -> bool:
    council = reply_council if isinstance(reply_council, dict) else {}
    if not council or not council.get("evaluated") or council.get("allow_tools"):
        return False
    active_lanes = {str(item) for item in council.get("active_lanes") or [] if str(item)}
    # This optimization is valid only when fast is the sole admitted lane. If
    # another lane was admitted, bypassing its stream makes the scheduler claim
    # cognition that did not actually execute.
    if active_lanes - {"fast"}:
        return False
    for lane in council.get("lanes") or []:
        if not isinstance(lane, dict) or str(lane.get("lane") or "") != "fast":
            continue
        if lane.get("quarantined"):
            return False
        return float(lane.get("pressure") or 0.0) >= float(lane.get("threshold") or 0.0)
    return False


def reply_turn_synthetic_reasons(
    *,
    inbound_message: Dict[str, object],
    reply_message: Optional[Dict[str, object]] = None,
    turn_contract: Optional[Dict[str, object]] = None,
    source: str = "reply",
) -> List[str]:
    reasons: List[str] = []
    source_lower = str(source or "").lower()
    if any(token in source_lower for token in ("synthetic", "fixture", "eval", "probe", "test")):
        reasons.append("source_marked_synthetic")
    inbound_metadata = inbound_message.get("metadata") if isinstance(inbound_message.get("metadata"), dict) else {}
    reply_metadata = (reply_message or {}).get("metadata") if isinstance((reply_message or {}).get("metadata"), dict) else {}
    if message_metadata_is_synthetic(inbound_metadata) or message_metadata_is_synthetic(reply_metadata):
        reasons.append("message_metadata_synthetic")
    if conversation_message_is_synthetic(inbound_message):
        reasons.append("conversation_message_synthetic")
    inbound_preview = normalize_text_value(inbound_message.get("body"), fallback="", limit=320).lower()
    latest_contract = ""
    if isinstance(turn_contract, dict):
        latest_contract = normalize_text_value(turn_contract.get("latest_message"), fallback="", limit=320).lower()
    has_synthetic_marker = any(
        marker in text
        for text in (inbound_preview, latest_contract)
        for marker in SYNTHETIC_REPLAY_PROMPT_MARKERS
        if text
    )
    if has_synthetic_marker and (
        str(inbound_message.get("id") or "") in {"msg-1", "message-1"}
        or str(inbound_message.get("thread_id") or "") == "thread-1"
        or source_lower != "reply"
    ):
        reasons.append("fixture_prompt_marker")
    return unique_compact(reasons, limit=6)


def build_reply_council_turn_record(
    *,
    inbound_message: Dict[str, object],
    reply_message: Dict[str, object],
    turn_contract: Optional[Dict[str, object]],
    reply_council: Optional[Dict[str, object]],
    used_model: object,
    quality_issues: Iterable[str],
    semantic_judgment: Optional[Dict[str, object]],
    stream_result: Optional[Dict[str, object]] = None,
    action_claim_grounding_applied: bool = False,
    rewrite_applied: bool = False,
    fallback_used: bool = False,
    synthetic: bool = False,
    synthetic_reasons: Optional[Iterable[str]] = None,
    reply_turn_replay_id: str = "",
    source: str = "reply",
) -> Optional[Dict[str, object]]:
    council = reply_council if isinstance(reply_council, dict) else {}
    if not council or not council.get("evaluated"):
        return None
    stream = stream_result if isinstance(stream_result, dict) else {}
    synthesis_selection = (
        stream.get("synthesis_selection")
        if isinstance(stream.get("synthesis_selection"), dict)
        else {}
    )
    stream_packets = [item for item in stream.get("packets") or [] if isinstance(item, dict)]
    stream_lanes = unique_compact([str(item.get("stream") or item.get("lane") or "") for item in stream_packets], limit=8)
    semantic = semantic_judgment if isinstance(semantic_judgment, dict) else {}
    issue_list = unique_compact([str(item) for item in quality_issues or []], limit=8)
    semantic_issues = unique_compact([str(item) for item in semantic.get("issues") or []], limit=8)
    active_lanes = [str(item) for item in council.get("active_lanes") or [] if str(item)]
    faculty_contributors = build_reply_faculty_contributors(council, stream, used_model)
    fast_direct_admitted = reply_council_fast_direct_admitted(council)
    lane_backed = bool(active_lanes or stream_lanes or fast_direct_admitted)
    fallback_label = ""
    if not lane_backed and normalize_text_value(reply_message.get("body"), fallback="", limit=80):
        fallback_label = "all_lanes_abstained_synthesis"
    elif not stream_lanes and not active_lanes and fast_direct_admitted:
        fallback_label = "fast_direct_answer"
    needed_repair = bool(
        issue_list
        or semantic_issues
        or rewrite_applied
        or action_claim_grounding_applied
        or fallback_used
        or fallback_label == "all_lanes_abstained_synthesis"
        or stream.get("stream_errors")
    )
    lanes: List[Dict[str, object]] = []
    for lane in council.get("lanes") or []:
        if not isinstance(lane, dict):
            continue
        lanes.append(
            {
                "lane": normalize_text_value(lane.get("lane"), fallback="", limit=40),
                "model": normalize_model_name(lane.get("model")),
                "nominal_model": normalize_model_name(lane.get("nominal_model")),
                "topology_mode": normalize_text_value(
                    lane.get("topology_mode"), fallback=MODEL_LANE_TOPOLOGY_FIVE_ENDPOINT, limit=40
                ),
                "substrate_profile": normalize_text_value(
                    lane.get("substrate_profile"), fallback="", limit=40
                ),
                "substrate_host": normalize_text_value(
                    lane.get("substrate_host"), fallback="", limit=200
                ),
                "pressure": lane.get("pressure"),
                "threshold": lane.get("threshold"),
                "stance": normalize_text_value(lane.get("stance"), fallback="", limit=40),
                "selected": bool(lane.get("selected")),
                "reasons": unique_compact([str(item) for item in lane.get("reasons") or []], limit=4),
                "quarantined": bool(lane.get("quarantined")),
            }
        )
    return {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "source": normalize_text_value(source, fallback="reply", limit=80),
        "reply_turn_replay_id": normalize_text_value(reply_turn_replay_id, fallback="", limit=80),
        "thread_id": str(inbound_message.get("thread_id") or reply_message.get("thread_id") or ""),
        "source_message_id": str(inbound_message.get("id") or ""),
        "reply_message_id": str(reply_message.get("id") or ""),
        "inbound_preview": normalize_text_value(inbound_message.get("body"), fallback="", limit=220),
        "reply_preview": normalize_text_value(reply_message.get("body"), fallback="", limit=220),
        "intent": normalize_text_value((turn_contract or {}).get("intent"), fallback="answer_latest_message", limit=80),
        "current_topic": normalize_text_value((turn_contract or {}).get("current_topic"), fallback="", limit=80),
        "short_followup": bool((turn_contract or {}).get("short_followup")),
        "episode_boundary": bool((turn_contract or {}).get("episode_boundary")),
        "used_model": normalize_model_name(used_model),
        "stream_reply_used": bool(stream),
        "stream_turn_id": normalize_text_value(stream.get("turn_id"), fallback="", limit=80),
        "selected_stream_lanes": stream_lanes,
        "model_topology": dict(
            stream.get("model_topology")
            if isinstance(stream.get("model_topology"), dict)
            else council.get("model_topology")
            if isinstance(council.get("model_topology"), dict)
            else {}
        ),
        "stream_routes": dict(
            stream.get("stream_routes")
            if isinstance(stream.get("stream_routes"), dict)
            else {}
        ),
        "substrate_plan": list(
            stream.get("substrate_plan")
            if isinstance(stream.get("substrate_plan"), list)
            else []
        ),
        "turn_duration_ms": float(stream.get("turn_duration_ms") or 0.0),
        "synthesis_duration_ms": float(stream.get("synthesis_duration_ms") or 0.0),
        "synthesis_model": normalize_model_name(stream.get("synthesis_model") or used_model),
        "synthesis_baseline_model": normalize_model_name(
            synthesis_selection.get("baseline_model")
        ),
        "synthesis_selection_reason": normalize_text_value(
            synthesis_selection.get("reason"), fallback="", limit=80
        ),
        "synthesis_budget": normalize_text_value(
            synthesis_selection.get("budget"), fallback="", limit=40
        ),
        "synthesis_integrated_selected": bool(
            synthesis_selection.get("integrated_selected")
        ),
        "synthesis_budget_selected": bool(
            synthesis_selection.get("budget_selected")
        ),
        "active_lanes": active_lanes,
        "faculty_contributors": faculty_contributors,
        "abstained_lanes": [str(item) for item in council.get("abstained_lanes") or [] if str(item)],
        "deferred_lanes": [str(item) for item in council.get("deferred_lanes") or [] if str(item)],
        "reason": normalize_text_value(council.get("reason"), fallback="", limit=180),
        "lanes": lanes,
        "synthetic": bool(synthetic),
        "synthetic_reasons": unique_compact([str(item) for item in synthetic_reasons or []], limit=6),
        "lane_backed": lane_backed,
        "fast_direct_admitted": fast_direct_admitted,
        "fallback_label": fallback_label,
        "needed_repair": needed_repair,
        "repair_signals": {
            "quality_issues": issue_list,
            "semantic_issues": semantic_issues,
            "rewrite_applied": bool(rewrite_applied),
            "action_claim_grounding_applied": bool(action_claim_grounding_applied),
            "fallback_used": bool(fallback_used),
            "stream_errors": stream.get("stream_errors") or [],
        },
    }


def record_reply_council_turn(**kwargs: object) -> Optional[Dict[str, object]]:
    record = build_reply_council_turn_record(**kwargs)  # type: ignore[arg-type]
    if not record:
        return None
    saved = append_jsonl_record(REPLY_COUNCIL_TURNS_PATH, record)
    mirror_store_file_to_runtime(REPLY_COUNCIL_TURNS_PATH)
    try:
        eve_tracing.record_span(
            OPERATIONAL_DB_PATH,
            name="reply.lane_admission",
            category="reply",
            started_at=saved.get("created_at"),
            duration_ms=0.0,
            ok=bool(saved.get("lane_backed") or saved.get("synthetic") or not saved.get("reply_preview")),
            attributes={
                "thread_id": saved.get("thread_id") or "",
                "source_message_id": saved.get("source_message_id") or "",
                "reply_message_id": saved.get("reply_message_id") or "",
                "active_lanes": saved.get("active_lanes") or [],
                "faculty_contributors": [
                    {
                        "lane": item.get("lane"),
                        "roles": item.get("roles") or [],
                        "credit_weight": item.get("credit_weight"),
                    }
                    for item in saved.get("faculty_contributors") or []
                    if isinstance(item, dict)
                ],
                "abstained_lanes": saved.get("abstained_lanes") or [],
                "lane_backed": bool(saved.get("lane_backed")),
                "fast_direct_admitted": bool(saved.get("fast_direct_admitted")),
                "fallback_label": saved.get("fallback_label") or "",
                "synthesis_model": saved.get("synthesis_model") or "",
                "synthesis_selection_reason": saved.get("synthesis_selection_reason") or "",
                "synthesis_budget": saved.get("synthesis_budget") or "",
                "synthesis_integrated_selected": bool(
                    saved.get("synthesis_integrated_selected")
                ),
                "synthesis_budget_selected": bool(saved.get("synthesis_budget_selected")),
                "synthetic": bool(saved.get("synthetic")),
            },
            trace_id_value=conversation_trace_id(saved.get("thread_id"), saved.get("source_message_id")),
        )
    except Exception:
        pass
    return saved


def record_reply_council_turn_safe(**kwargs: object) -> Optional[Dict[str, object]]:
    try:
        return record_reply_council_turn(**kwargs)
    except Exception as exc:
        try:
            append_entry(
                "reply_council_turn_record_error",
                f"Could not record reply council turn: {exc}",
                metadata={"source": "reply"},
            )
        except Exception:
            pass
        return None


def predict_user_reaction(reply_body: object) -> str:
    """A lightweight expectation of how the user will react to this reply, so a
    later correction or silence can be scored as conversational prediction error
    (predictive processing in the relationship domain)."""
    text = normalize_text_value(reply_body, fallback="", limit=400).lower()
    if not text:
        return ""
    if "?" in text:
        return "answer_question"
    if any(cue in text for cue in ("i'll ", "i will ", "let me ", "i'm going to ", "i have ", "i've ", "done.", "fixed", "completed", "i can ")):
        return "accept_or_continue"
    return "continue"


def user_message_explicitly_accepts(text: object) -> bool:
    normalized = " ".join(str(text or "").lower().replace("’", "'").split()).strip()
    if not normalized:
        return False
    normalized = normalized.strip(" .,!?:;")
    exact = {
        "yes",
        "yep",
        "yeah",
        "sure",
        "okay",
        "ok",
        "great",
        "good",
        "perfect",
        "correct",
        "exactly",
        "thanks",
        "thank you",
        "that works",
        "looks good",
        "sounds good",
        "do it",
        "keep going",
        "continue",
        "you got it",
    }
    if normalized in exact:
        return True
    return bool(
        re.match(
            r"^(?:yes|yep|yeah|okay|ok|great|good|perfect|correct|exactly|thanks|thank you)\b",
            normalized,
        )
        or re.search(r"\b(?:that works|looks good|sounds good|you got it)\b", normalized)
    )


def join_delayed_reply_consequence(
    prior_replay: Optional[Dict[str, object]],
    prediction_record: Optional[Dict[str, object]],
) -> Optional[Dict[str, object]]:
    """Join real later user feedback into the exact reply cycle that predicted it."""
    replay = prior_replay if isinstance(prior_replay, dict) else {}
    prediction = prediction_record if isinstance(prediction_record, dict) else {}
    if not prediction.get("consequence_observed") or prediction.get("outcome_ok") is None:
        return None
    source_cycle_id = normalize_text_value(replay.get("conscious_cycle_id"), fallback="", limit=80)
    reply_message_id = normalize_text_value(replay.get("reply_message_id"), fallback="", limit=120)
    observed_message_id = normalize_text_value(prediction.get("observed_message_id"), fallback="", limit=120)
    evidence_id = normalize_text_value(
        prediction.get("evidence_id"),
        fallback=f"reply-consequence:{reply_message_id}:{observed_message_id}",
        limit=160,
    )
    if not source_cycle_id or not reply_message_id or not evidence_id:
        return None
    action_id = normalize_text_value(replay.get("conscious_action_id"), fallback="respond_to_user", limit=80)
    outcome_ok = bool(prediction.get("outcome_ok"))
    observed_text = normalize_text_value(prediction.get("observed_text"), fallback="", limit=180)
    summary = normalize_text_value(
        (
            f"The user explicitly accepted reply {reply_message_id}: {observed_text}"
            if outcome_ok
            else f"The user corrected reply {reply_message_id}: {observed_text}"
        ),
        fallback="Observed a lived user consequence for an earlier reply.",
        limit=220,
    )

    def persist_delayed_consequence(payload: Dict[str, object]) -> Dict[str, object]:
        current = normalize_conscious_state(payload)
        updated, applied = eve_consciousness.apply_delayed_action_consequence(
            current,
            source_cycle_id=source_cycle_id,
            action_id=action_id,
            ok=outcome_ok,
            summary=summary,
            evidence_id=evidence_id,
            reply_message_id=reply_message_id,
            observed_message_id=observed_message_id,
            prediction_error=prediction.get("error_magnitude")
            if isinstance(prediction.get("error_magnitude"), int)
            else None,
            faculty_contributors=reply_faculty_contributors_from_replay(replay),
        )
        persisted = normalize_conscious_state(updated)
        payload.clear()
        payload.update(json.loads(json.dumps(persisted)))
        return {"applied": applied, "state": persisted}

    persistence = CONSCIOUS_STATE_REPOSITORY.update(persist_delayed_consequence)
    result = persistence if isinstance(persistence, dict) else {}
    state = result.get("state") if isinstance(result.get("state"), dict) else {}
    recurrent = state.get("recurrent") if isinstance(state.get("recurrent"), dict) else {}
    delayed_outcomes = (
        recurrent.get("delayed_outcomes")
        if isinstance(recurrent.get("delayed_outcomes"), list)
        else []
    )
    evidence_present = any(
        isinstance(item, dict)
        and normalize_text_value(item.get("evidence_id"), fallback="", limit=160) == evidence_id
        for item in delayed_outcomes
    ) or evidence_id in {
        normalize_text_value(item, fallback="", limit=160)
        for item in recurrent.get("applied_consequence_ids") or []
        if normalize_text_value(item, fallback="", limit=160)
    }
    replay_consequence_updated = False
    lane_learning_updated = False
    if evidence_present:
        replay_record, replay_consequence_updated = update_reply_turn_replay_user_consequence(
            replay,
            prediction,
        )
        try:
            lane_state = record_reply_lane_learning_from_user_consequence(
                replay_record or replay,
                outcome_ok=outcome_ok,
                evidence_id=evidence_id,
            )
            lane_learning_updated = lane_state is not None
        except Exception as exc:
            append_entry(
                "reply_lane_consequence_learning_failed",
                "The recurrent consequence was preserved, but lane learning could not consume it.",
                metadata={
                    "reply_message_id": reply_message_id,
                    "evidence_id": evidence_id,
                    "reason": normalize_text_value(exc, fallback="unknown error", limit=220),
                },
            )
    if result.get("applied") and state:
        append_conscious_state_audit_event(
            state,
            event="delayed_reply_consequence_observed",
            source="lived_user_reply_consequence",
        )
        append_entry(
            "reply_consequence_observed",
            summary,
            metadata={
                "source_cycle_id": source_cycle_id,
                "reply_message_id": reply_message_id,
                "observed_message_id": observed_message_id,
                "evidence_id": evidence_id,
                "outcome_ok": outcome_ok,
            },
        )
    return {
        "applied": bool(result.get("applied")),
        "source_cycle_id": source_cycle_id,
        "reply_message_id": reply_message_id,
        "observed_message_id": observed_message_id,
        "evidence_id": evidence_id,
        "outcome_ok": outcome_ok,
        "evidence_present": evidence_present,
        "replay_consequence_updated": replay_consequence_updated,
        "lane_learning_updated": lane_learning_updated,
        "state": state,
    }


def record_conversational_prediction_check(
    prior_replay: Optional[Dict[str, object]],
    inbound_message: Dict[str, object],
) -> Optional[Dict[str, object]]:
    """Score the prior reply's predicted_reaction against what the user actually
    did. A correction we did not anticipate is the headline surprise; it flows
    into the same prediction-error ledger that feeds homeostasis surprise and the
    workspace prediction_errors field."""
    predicted_raw = str((prior_replay or {}).get("predicted_reaction") or "")
    predicted = "accept_or_continue" if predicted_raw == "accept_or_correct" else predicted_raw
    if not predicted:
        return None
    user_text = normalize_text_value(inbound_message.get("body"), fallback="", limit=400)
    if not user_text:
        return None
    correction = classify_user_correction(user_text)
    is_correction = correction is not None
    explicit_acceptance = user_message_explicitly_accepts(user_text)
    if is_correction:
        observed = "correction"
        fulfilled: Optional[bool] = False
        consequence_observed = True
        outcome_ok: Optional[bool] = False
    elif explicit_acceptance:
        observed = "acceptance"
        fulfilled = True
        consequence_observed = True
        outcome_ok = True
    elif predicted == "answer_question" and "?" not in user_text:
        observed = "answer"
        fulfilled = True
        consequence_observed = True
        outcome_ok = True
    else:
        observed = "question" if "?" in user_text else "continuation"
        fulfilled = None
        consequence_observed = False
        outcome_ok = None
    if fulfilled is True:
        error_magnitude = 0
    elif fulfilled is False and is_correction:
        error_magnitude = 70 if str((correction or {}).get("severity")) == "high" else 50
    else:
        error_magnitude = None
    reply_message_id = str((prior_replay or {}).get("reply_message_id") or "")
    observed_message_id = str(inbound_message.get("id") or "")
    evidence_id = f"reply-consequence:{reply_message_id}:{observed_message_id}"
    record = {
        "timestamp": utc_now(),
        "kind": "conversational",
        "action": "conversation",
        "thread_id": str(inbound_message.get("thread_id") or ""),
        "predicted_reaction": predicted,
        "expected_signal": f"user will {predicted.replace('_', ' ')}",
        "observed": observed,
        "confidence": "medium",
        "fulfilled": fulfilled,
        "error_magnitude": error_magnitude,
        "consequence_observed": consequence_observed,
        "outcome_ok": outcome_ok,
        "scored_reply_id": reply_message_id,
        "source_cycle_id": str((prior_replay or {}).get("conscious_cycle_id") or ""),
        "observed_message_id": observed_message_id,
        "observed_text": user_text,
        "evidence_id": evidence_id,
    }
    recorded = append_prediction_check_record(record)
    record["recorded"] = bool(recorded)
    if consequence_observed:
        try:
            joined = join_delayed_reply_consequence(prior_replay, record)
            record["conscious_consequence_joined"] = bool((joined or {}).get("applied"))
        except Exception as exc:
            record["conscious_consequence_joined"] = False
            record["conscious_consequence_join_error"] = normalize_text_value(
                exc,
                fallback="unknown delayed-consequence join error",
                limit=220,
            )
    return record


def observe_inbound_reply_consequence(inbound_message: Dict[str, object]) -> Optional[Dict[str, object]]:
    """Observe the prior reply before opening the next recurrent reply cycle."""
    if conversation_message_is_synthetic(inbound_message):
        return None
    if str(inbound_message.get("sender") or "").strip().lower() != "user":
        return None
    thread_id = normalize_text_value(inbound_message.get("thread_id"), fallback="", limit=120)
    if not thread_id:
        return None
    prior_replays = read_reply_turn_replays(limit=1, thread_id=thread_id, prefer_runtime=False)
    if not prior_replays:
        return None
    return record_conversational_prediction_check(prior_replays[0], inbound_message)


def record_reply_turn_replay(
    *,
    inbound_message: Dict[str, object],
    reply_message: Dict[str, object],
    turn_contract: Optional[Dict[str, object]],
    reply_council: Optional[Dict[str, object]],
    used_model: object,
    quality_issues: Iterable[str],
    semantic_judgment: Optional[Dict[str, object]],
    stream_result: Optional[Dict[str, object]] = None,
    conscious_state: Optional[Dict[str, object]] = None,
    action_claim_grounding_applied: bool = False,
    rewrite_applied: bool = False,
    fallback_used: bool = False,
    source: str = "reply",
) -> Dict[str, object]:
    quality_issue_list = unique_compact([str(item) for item in quality_issues or []], limit=8)
    synthetic_reasons = reply_turn_synthetic_reasons(
        inbound_message=inbound_message,
        reply_message=reply_message,
        turn_contract=turn_contract,
        source=source,
    )
    synthetic = bool(synthetic_reasons)
    thread_id = str(inbound_message.get("thread_id") or reply_message.get("thread_id") or "")
    # Conversational prediction: this user inbound is the reaction to the prior
    # reply in this thread — score that prior prediction before recording the new
    # turn. Only for genuine user turns, and never synthetic fixtures.
    if not synthetic and str(inbound_message.get("sender") or "").strip().lower() == "user" and thread_id:
        try:
            prior_replays = read_reply_turn_replays(limit=1, thread_id=thread_id, prefer_runtime=False)
            if prior_replays:
                record_conversational_prediction_check(prior_replays[0], inbound_message)
        except Exception:
            pass
    conscious_completion: Dict[str, object] = {}
    conscious_action_id = "respond_to_user"
    reply_delivery_ok = False
    reply_consequence_status = "not_opened"
    if not synthetic and (
        str(source or "") != "reply_generation_failure"
        or (isinstance(conscious_state, dict) and bool(conscious_state.get("cycle_id")))
    ):
        try:
            council = reply_council if isinstance(reply_council, dict) else {}
            stream = stream_result if isinstance(stream_result, dict) else {}
            active_lanes = unique_compact(
                [
                    *[str(item) for item in council.get("active_lanes") or [] if str(item)],
                    *[str(item) for item in stream.get("reply_council_active_lanes") or [] if str(item)],
                ],
                limit=5,
            )
            if not active_lanes:
                active_lanes = ["fast"]
            metadata = reply_message.get("metadata") if isinstance(reply_message.get("metadata"), dict) else {}
            tools_used = metadata.get("tools_used") if isinstance(metadata.get("tools_used"), list) else []
            action_attempts = normalize_bounded_action_attempts(
                metadata.get("action_attempts")
            )
            semantic = semantic_judgment if isinstance(semantic_judgment, dict) else {}
            # Selected intention is a prediction, not execution evidence.  A
            # reply that merely occurred while an unrelated inquiry was on
            # Eve's mind must close as `respond_to_user`; otherwise language
            # delivery silently masquerades as the intended tool action.
            actual_action_id = normalize_text_value(
                action_attempts[-1].get("action_id") if action_attempts else "",
                fallback="respond_to_user",
                limit=80,
            )
            conscious_action_id = actual_action_id
            reply_body_present = bool(normalize_text_value(reply_message.get("body"), fallback="", limit=40))
            reply_delivery_ok = (
                reply_body_present
                and not quality_issue_list
                and bool(semantic.get("ok", True))
                and not fallback_used
            )
            action_failed_before_delivery = bool(
                str(source or "") == "reply_generation_failure" or not reply_body_present
            )
            reply_consequence_status = "observed_failure" if action_failed_before_delivery else "pending_user_evidence"
            conscious_completion = complete_recurrent_conscious_cycle(
                actual_process={
                    "lanes": active_lanes,
                    "model": normalize_model_name(used_model),
                    "tools_used": tools_used,
                    "action_id": actual_action_id,
                    "action_attempts": action_attempts,
                    "revision_used": bool(stream.get("mind_stream_revision_count") or stream.get("revision_count")),
                    "fallback_used": bool(fallback_used),
                },
                outcome={
                    "ok": False if action_failed_before_delivery else None,
                    "observed": action_failed_before_delivery,
                    "delivery_ok": reply_delivery_ok,
                    "summary": (
                        "Reply generation failed before a user-visible consequence could occur."
                        if action_failed_before_delivery
                        else "Reply delivered; lived user consequence remains pending."
                    ),
                    "semantic_ok": bool(semantic.get("ok", True)),
                    "quality_issue_count": len(quality_issue_list),
                    "thread_id": thread_id,
                    "source_message_id": str(inbound_message.get("id") or ""),
                    "reply_message_id": str(reply_message.get("id") or ""),
                },
                source=f"reply_outcome:{source}",
                opened_state=conscious_state,
            )
        except Exception as exc:
            append_entry(
                "conscious_cycle_completion_failed",
                f"Reply replay continued after conscious-cycle completion failed: {normalize_text_value(exc, fallback='unknown error', limit=220)}",
                metadata={"thread_id": thread_id, "reply_message_id": str(reply_message.get("id") or "")},
            )
    faculty_contributors = build_reply_faculty_contributors(
        reply_council,
        stream_result,
        used_model,
    )
    record = {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "source": normalize_text_value(source, fallback="reply", limit=80),
        "thread_id": thread_id,
        "source_message_id": str(inbound_message.get("id") or ""),
        "reply_message_id": str(reply_message.get("id") or ""),
        "inbound_preview": normalize_text_value(inbound_message.get("body"), fallback="", limit=260),
        "reply_preview": normalize_text_value(reply_message.get("body"), fallback="", limit=260),
        "predicted_reaction": predict_user_reaction(reply_message.get("body")),
        "conscious_action_id": conscious_action_id,
        "reply_delivery_ok": reply_delivery_ok,
        "reply_consequence_status": reply_consequence_status,
        "model": normalize_model_name(used_model),
        "turn_contract": turn_contract or {},
        "reply_council": reply_council or {},
        "quality_issues": quality_issue_list,
        "semantic_judgment": semantic_judgment or {},
        "stream_turn_id": (stream_result or {}).get("turn_id") if isinstance(stream_result, dict) else "",
        "stream_models": (stream_result or {}).get("stream_models") if isinstance(stream_result, dict) else {},
        "stream_errors": (stream_result or {}).get("stream_errors") if isinstance(stream_result, dict) else [],
        "faculty_contributors": faculty_contributors,
        "action_attempts": normalize_bounded_action_attempts(
            (reply_message.get("metadata") or {}).get("action_attempts")
            if isinstance(reply_message.get("metadata"), dict)
            else []
        ),
        "action_claim_grounding_applied": bool(action_claim_grounding_applied),
        "rewrite_applied": bool(rewrite_applied),
        "fallback_used": bool(fallback_used),
        "synthetic": synthetic,
        "synthetic_reasons": synthetic_reasons,
        "conscious_cycle_id": normalize_text_value(conscious_completion.get("cycle_id"), fallback="", limit=80),
        "conscious_cycle_prediction_error": (
            (conscious_completion.get("cycle_outcome") or {}).get("overall_prediction_error")
            if isinstance(conscious_completion.get("cycle_outcome"), dict)
            else None
        ),
    }
    saved = append_jsonl_record(REPLY_TURN_REPLAYS_PATH, record)
    mirror_store_file_to_runtime(REPLY_TURN_REPLAYS_PATH)
    council_turn = record_reply_council_turn_safe(
        inbound_message=inbound_message,
        reply_message=reply_message,
        turn_contract=turn_contract,
        reply_council=reply_council,
        used_model=used_model,
        quality_issues=quality_issue_list,
        semantic_judgment=semantic_judgment,
        stream_result=stream_result,
        action_claim_grounding_applied=action_claim_grounding_applied,
        rewrite_applied=rewrite_applied,
        fallback_used=fallback_used,
        synthetic=synthetic,
        synthetic_reasons=synthetic_reasons,
        reply_turn_replay_id=str(saved.get("id") or ""),
        source=source,
    )
    try:
        eve_tracing.record_span(
            OPERATIONAL_DB_PATH,
            name="reply.turn_replay",
            category="reply",
            started_at=saved.get("created_at"),
            duration_ms=0.0,
            ok=True,
            attributes={
                "thread_id": saved.get("thread_id") or "",
                "source_message_id": saved.get("source_message_id") or "",
                "reply_message_id": saved.get("reply_message_id") or "",
                "model": saved.get("model") or "",
                "synthetic": synthetic,
                "synthetic_reasons": synthetic_reasons,
                "reply_council_turn_id": (council_turn or {}).get("id") if isinstance(council_turn, dict) else "",
                "lane_backed": bool((council_turn or {}).get("lane_backed")) if isinstance(council_turn, dict) else False,
                "fallback_label": (council_turn or {}).get("fallback_label") if isinstance(council_turn, dict) else "",
            },
            trace_id_value=conversation_trace_id(saved.get("thread_id"), saved.get("source_message_id")),
        )
    except Exception:
        pass
    try:
        if not synthetic and str(source or "") != "reply_generation_failure":
            record_reply_lane_learning_from_replay(saved)
    except Exception as exc:
        append_entry(
            "reply_lane_learning_error",
            f"Could not update reply lane learning from replay: {exc}",
            metadata={"reply_turn_id": saved.get("id")},
        )
    return saved


def record_reply_turn_replay_safe(**kwargs: object) -> Optional[Dict[str, object]]:
    try:
        return record_reply_turn_replay(**kwargs)  # type: ignore[arg-type]
    except Exception as exc:
        try:
            append_entry(
                "reply_turn_replay_error",
                f"Could not record reply turn replay: {exc}",
                metadata={"source": "reply"},
            )
        except Exception:
            pass
        return None


def read_reply_turn_replays(
    *,
    limit: int = 20,
    thread_id: Optional[str] = None,
    reply_message_id: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(REPLY_TURN_REPLAYS_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_tail_records(path, max(1, min(200, int(limit or 20) * 4)))
    filtered = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if thread_id and str(record.get("thread_id") or "") != str(thread_id):
            continue
        if reply_message_id and str(record.get("reply_message_id") or "") != str(reply_message_id):
            continue
        filtered.append(dict(record))
    filtered.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    return filtered[: max(1, int(limit or 20))]


def update_reply_turn_replay_user_consequence(
    replay: Dict[str, object],
    prediction: Dict[str, object],
) -> Tuple[Optional[Dict[str, object]], bool]:
    """Attach the first lived user consequence to its durable reply replay."""
    replay_id = normalize_text_value(replay.get("id"), fallback="", limit=120)
    reply_message_id = normalize_text_value(replay.get("reply_message_id"), fallback="", limit=120)
    evidence_id = normalize_text_value(prediction.get("evidence_id"), fallback="", limit=160)
    if not reply_message_id or not evidence_id or prediction.get("outcome_ok") is None:
        return None, False
    updated_record: Optional[Dict[str, object]] = None
    applied = False
    with store_lock(REPLY_TURN_REPLAYS_PATH):
        records = read_jsonl_records(REPLY_TURN_REPLAYS_PATH)
        for index in range(len(records) - 1, -1, -1):
            item = records[index]
            if not isinstance(item, dict):
                continue
            if replay_id and str(item.get("id") or "") == replay_id:
                matched = True
            else:
                matched = str(item.get("reply_message_id") or "") == reply_message_id
            if not matched:
                continue
            existing_evidence = normalize_text_value(
                item.get("user_consequence_evidence_id"),
                fallback="",
                limit=160,
            )
            if item.get("user_consequence_observed"):
                updated_record = dict(item)
                break
            record = dict(item)
            record.update(
                {
                    "user_consequence_observed": True,
                    "user_consequence_ok": bool(prediction.get("outcome_ok")),
                    "user_consequence_kind": normalize_text_value(
                        prediction.get("observed"),
                        fallback="acceptance" if prediction.get("outcome_ok") else "correction",
                        limit=60,
                    ),
                    "user_consequence_observed_at": normalize_text_value(
                        prediction.get("timestamp"),
                        fallback=utc_now(),
                        limit=80,
                    ),
                    "user_consequence_observed_message_id": normalize_text_value(
                        prediction.get("observed_message_id"),
                        fallback="",
                        limit=120,
                    ),
                    "user_consequence_observed_text": normalize_text_value(
                        prediction.get("observed_text"),
                        fallback="",
                        limit=600,
                    ),
                    "user_consequence_evidence_id": evidence_id,
                    "reply_consequence_status": (
                        "accepted" if prediction.get("outcome_ok") else "corrected"
                    ),
                }
            )
            records[index] = record
            updated_record = record
            applied = not existing_evidence
            write_jsonl_records(REPLY_TURN_REPLAYS_PATH, records)
            break
    if applied:
        mirror_store_file_to_runtime(REPLY_TURN_REPLAYS_PATH)
    return updated_record, applied


def update_reply_turn_replay_followup(
    replay_id: str,
    *,
    followup_id: str,
    status: str,
    action: str = "",
    due_at: str = "",
    commitment_id: str = "",
    visible_reply: str = "",
    action_execution_id: str = "",
    action_result_ok: Optional[bool] = None,
    delivery_message_id: str = "",
    worker_cycle_id: str = "",
    completed_cycle_id: str = "",
    failure_reason: str = "",
) -> Dict[str, object]:
    """Join a durable delayed intention and its outcome to the reply that made it.

    Reply generation finishes before Eve Chat converts a model answer into a
    durable same-thread promise.  Without this join, the replay remembers only
    the pre-queue wording and cannot later distinguish making a commitment from
    fulfilling it.  This record is evidence about continuity, not proof that a
    model invocation itself performed the delayed action.
    """
    clean_replay_id = normalize_text_value(replay_id, fallback="", limit=120)
    clean_followup_id = normalize_text_value(followup_id, fallback="", limit=120)
    clean_status = normalize_text_value(status, fallback="", limit=40)
    if not clean_replay_id or not clean_followup_id:
        return {}
    if clean_status not in EVE_CHAT_FOLLOWUP_STATUSES:
        raise SystemExit(f"Invalid Eve Chat follow-up replay status `{clean_status}`.")
    timestamp = utc_now()
    updated_record: Dict[str, object] = {}
    with store_lock(REPLY_TURN_REPLAYS_PATH):
        records = read_jsonl_records(REPLY_TURN_REPLAYS_PATH)
        for index in range(len(records) - 1, -1, -1):
            item = records[index]
            if not isinstance(item, dict) or str(item.get("id") or "") != clean_replay_id:
                continue
            record = dict(item)
            prior_followup = (
                record.get("durable_followup")
                if isinstance(record.get("durable_followup"), dict)
                else {}
            )
            joined_followup = {
                **prior_followup,
                "id": clean_followup_id,
                "status": clean_status,
                "updated_at": timestamp,
            }
            optional_text = {
                "action": (action, 80),
                "due_at": (due_at, 80),
                "commitment_id": (commitment_id, 120),
                "action_execution_id": (action_execution_id, 120),
                "delivery_message_id": (delivery_message_id, 120),
                "worker_cycle_id": (worker_cycle_id, 80),
                "completed_cycle_id": (completed_cycle_id, 80),
                "failure_reason": (failure_reason, 500),
            }
            for key, (value, limit) in optional_text.items():
                clean_value = normalize_text_value(value, fallback="", limit=limit)
                if clean_value:
                    joined_followup[key] = clean_value
            if action_result_ok is not None:
                joined_followup["action_result_ok"] = bool(action_result_ok)
            record["durable_followup"] = joined_followup
            record["updated_at"] = timestamp
            clean_visible_reply = normalize_text_value(
                visible_reply,
                fallback="",
                limit=1200,
            )
            if clean_visible_reply:
                record["reply_preview"] = clean_visible_reply
                record["reply_revision_reason"] = "durable_same_thread_followup"
                record["reply_revision_at"] = timestamp
            records[index] = record
            write_jsonl_records(REPLY_TURN_REPLAYS_PATH, records)
            updated_record = record
            break
    if updated_record:
        mirror_store_file_to_runtime(REPLY_TURN_REPLAYS_PATH)
    return updated_record


def reply_turn_replay_exists_for_reply(reply_message_id: object) -> bool:
    reply_id = normalize_text_value(reply_message_id, fallback="", limit=120)
    if not reply_id:
        return False
    for prefer_runtime in (False, True):
        try:
            if read_reply_turn_replays(limit=1, reply_message_id=reply_id, prefer_runtime=prefer_runtime):
                return True
        except Exception:
            continue
    return False


def should_record_manual_visible_reply_replay(reply_message: Dict[str, object]) -> bool:
    if conversation_message_is_synthetic(reply_message):
        return False
    if str(reply_message.get("sender") or "") != "eve":
        return False
    if str(reply_message.get("kind") or "") not in MANUAL_VISIBLE_REPLY_KINDS:
        return False
    if not normalize_text_value(reply_message.get("reply_to"), fallback="", limit=120):
        return False
    if reply_turn_replay_exists_for_reply(reply_message.get("id")):
        return False
    return True


def find_message_in_thread(thread_messages: List[Dict[str, object]], message_id: object) -> Optional[Dict[str, object]]:
    target = normalize_text_value(message_id, fallback="", limit=120)
    if not target:
        return None
    for message in thread_messages:
        if str(message.get("id") or "") == target:
            return message
    return None


def record_manual_visible_reply_replay_safe(
    reply_message: Dict[str, object],
    *,
    prefer_runtime: bool = False,
) -> Optional[Dict[str, object]]:
    if not should_record_manual_visible_reply_replay(reply_message):
        return None
    thread_id = normalize_text_value(reply_message.get("thread_id"), fallback="", limit=120)
    reply_to = normalize_text_value(reply_message.get("reply_to"), fallback="", limit=120)
    try:
        thread_messages = read_messages(thread_id=thread_id, limit=30, prefer_runtime=prefer_runtime) if thread_id else []
    except Exception:
        thread_messages = []
    inbound_message = find_message_in_thread(thread_messages, reply_to) or {
        "id": reply_to,
        "thread_id": thread_id,
        "sender": "user",
        "recipient": "eve",
        "subject": reply_message.get("subject") or "Conversation",
        "body": "",
    }
    inbound_body = normalize_text_value(inbound_message.get("body"), fallback="", limit=1200)
    reply_body = normalize_text_value(reply_message.get("body"), fallback="", limit=1200)
    reply_posture = infer_reply_posture(inbound_body)
    try:
        turn_contract = build_reply_turn_contract(
            inbound_message,
            inbound_body,
            thread_messages,
            reply_posture=reply_posture,
        )
    except Exception:
        turn_contract = {
            "latest_message": inbound_body,
            "intent": "answer_latest_message",
            "reply_posture": reply_posture,
            "current_topic": normalize_text_value(inbound_body, fallback="", limit=80),
        }
    quality_issues: List[str] = []
    semantic_issues: List[str] = []
    if not inbound_body:
        quality_issues.append("Manual visible reply replay could not find the source inbound message body.")
        semantic_issues.append("manual_visible_reply_missing_source_inbound")
    if not reply_body:
        quality_issues.append("Manual visible reply replay could not find the reply body.")
        semantic_issues.append("manual_visible_reply_missing_reply_body")
    if not quality_issues and inbound_body:
        try:
            quality_issues = reply_quality_issues(inbound_body, reply_body, reply_posture=reply_posture)
        except Exception:
            quality_issues = []
    try:
        semantic_judgment = judge_reply_against_turn_contract(
            inbound_body,
            reply_body,
            turn_contract,
            quality_issues=quality_issues,
        )
    except Exception:
        semantic_judgment = {
            "ok": bool(inbound_body and reply_body and not semantic_issues),
            "issues": semantic_issues,
        }
    if semantic_issues:
        semantic_judgment = dict(semantic_judgment)
        semantic_judgment["ok"] = False
        semantic_judgment["issues"] = unique_compact(
            [*(semantic_judgment.get("issues") or []), *semantic_issues],
            limit=8,
        )
    metadata = reply_message.get("metadata") if isinstance(reply_message.get("metadata"), dict) else {}
    model_label = normalize_text_value(
        metadata.get("model") or metadata.get("created_by"),
        fallback="manual-visible-reply",
        limit=120,
    )
    return record_reply_turn_replay_safe(
        inbound_message=inbound_message,
        reply_message=reply_message,
        turn_contract=turn_contract,
        reply_council={},
        used_model=model_label,
        quality_issues=quality_issues,
        semantic_judgment=semantic_judgment,
        stream_result=None,
        action_claim_grounding_applied=False,
        rewrite_applied=False,
        fallback_used=True,
        source="manual_visible_reply",
    )


def backfill_manual_visible_reply_replays(*, limit: int = 200, prefer_runtime: bool = True, apply: bool = False) -> Dict[str, object]:
    messages = read_messages(limit=max(1, int(limit or 200)), prefer_runtime=prefer_runtime)
    candidates = [
        message
        for message in messages
        if str(message.get("sender") or "") == "eve"
        and str(message.get("kind") or "") in MANUAL_VISIBLE_REPLY_KINDS
        and normalize_text_value(message.get("reply_to"), fallback="", limit=120)
    ]
    missing = [message for message in candidates if not reply_turn_replay_exists_for_reply(message.get("id"))]
    recorded: List[Dict[str, object]] = []
    if apply:
        for message in missing:
            replay = record_manual_visible_reply_replay_safe(message, prefer_runtime=prefer_runtime)
            if isinstance(replay, dict):
                recorded.append(replay)
    return {
        "checked_at": utc_now(),
        "status": "applied" if apply else "dry_run",
        "prefer_runtime": bool(prefer_runtime),
        "candidate_count": len(candidates),
        "missing_count": len(missing),
        "recorded_count": len(recorded),
        "missing_reply_message_ids": [str(message.get("id") or "") for message in missing[:20]],
        "recorded_reply_message_ids": [str(record.get("reply_message_id") or "") for record in recorded[:20]],
    }


def read_reply_council_turns(
    *,
    limit: int = 20,
    thread_id: Optional[str] = None,
    reply_message_id: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(REPLY_COUNCIL_TURNS_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_tail_records(path, max(1, min(200, int(limit or 20) * 4)))
    filtered = []
    for record in records:
        if not isinstance(record, dict):
            continue
        if thread_id and str(record.get("thread_id") or "") != str(thread_id):
            continue
        if reply_message_id and str(record.get("reply_message_id") or "") != str(reply_message_id):
            continue
        filtered.append(dict(record))
    filtered.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    return filtered[: max(1, int(limit or 20))]


def normalize_active_model_call(call: Dict[str, object], *, now: Optional[datetime] = None) -> Optional[Dict[str, object]]:
    call_id = normalize_text_value(call.get("id"), fallback="", limit=80)
    if not call_id:
        return None
    started_at = normalize_text_value(call.get("started_at"), fallback="", limit=40)
    started = parse_iso_datetime(started_at)
    timestamp_now = now or datetime.now(timezone.utc)
    elapsed_ms = 0
    if started is not None:
        elapsed_ms = max(0, int((timestamp_now - started).total_seconds() * 1000))
    return {
        "id": call_id,
        "started_at": started_at,
        "updated_at": normalize_text_value(call.get("updated_at"), fallback=started_at, limit=40),
        "operation": normalize_text_value(call.get("operation"), fallback="model_call", limit=80),
        "backend": normalize_text_value(call.get("backend"), fallback="", limit=40),
        "model": normalize_model_name(call.get("model")),
        "host": normalize_text_value(call.get("host"), fallback="", limit=180),
        "status": normalize_text_value(call.get("status"), fallback="running", limit=40),
        "message_count": int(call.get("message_count") or 0),
        "max_tokens": int(call.get("max_tokens") or 0),
        "elapsed_ms": elapsed_ms,
        "thread_name": normalize_text_value(call.get("thread_name"), fallback="", limit=80),
        "error": normalize_text_value(call.get("error"), fallback="", limit=180),
    }


def active_model_call_stale_seconds(call: Dict[str, object]) -> int:
    operation = normalize_text_value(call.get("operation"), fallback="", limit=120).lower()
    if operation in ACTIVE_MODEL_CALL_LONG_OPERATIONS:
        return ACTIVE_MODEL_CALL_LONG_STALE_SECONDS
    return ACTIVE_MODEL_CALL_STALE_SECONDS


def active_model_call_is_fresh(call: Dict[str, object], *, now: Optional[datetime] = None) -> bool:
    started = parse_iso_datetime(call.get("started_at"))
    if started is None:
        return False
    current_time = now or datetime.now(timezone.utc)
    updated = parse_iso_datetime(call.get("updated_at")) or started
    stale_after = timedelta(seconds=active_model_call_stale_seconds(call))
    hard_cap = timedelta(seconds=max(ACTIVE_MODEL_CALL_LONG_STALE_SECONDS, active_model_call_stale_seconds(call) * 2))
    return current_time - updated < stale_after and current_time - started < hard_cap


def load_active_model_calls(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = load_json_object(ACTIVE_MODEL_CALLS_PATH, "active model calls", prefer_runtime=prefer_runtime)
    raw_calls = payload.get("calls") if isinstance(payload.get("calls"), list) else []
    now = datetime.now(timezone.utc)
    calls = []
    for item in raw_calls:
        if not isinstance(item, dict) or not active_model_call_is_fresh(item, now=now):
            continue
        normalized = normalize_active_model_call(item, now=now)
        if normalized is not None:
            calls.append(normalized)
    calls.sort(key=lambda item: str(item.get("started_at") or ""), reverse=True)
    return {
        "updated_at": normalize_text_value(payload.get("updated_at"), fallback=utc_now(), limit=40),
        "calls": calls,
    }


def mutate_active_model_calls(mutator: Callable[[Dict[str, object]], object]) -> object:
    ensure_store()
    now = datetime.now(timezone.utc)
    with store_lock(ACTIVE_MODEL_CALLS_PATH):
        payload = eve_store.load_json_dict(ACTIVE_MODEL_CALLS_PATH, default={"calls": []})
        calls = [
            dict(item)
            for item in payload.get("calls", [])
            if isinstance(item, dict) and active_model_call_is_fresh(item, now=now)
        ]
        payload["calls"] = calls
        result = mutator(payload)
        payload["updated_at"] = utc_now()
        payload["calls"] = [
            dict(item)
            for item in payload.get("calls", [])
            if isinstance(item, dict) and active_model_call_is_fresh(item, now=now)
        ]
        ACTIVE_MODEL_CALLS_PATH.parent.mkdir(parents=True, exist_ok=True)
        ACTIVE_MODEL_CALLS_PATH.write_text(json.dumps(payload, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")
        return result


def start_active_model_call(
    *,
    operation: str,
    backend: str,
    model: str,
    host: str,
    message_count: int,
    max_tokens: int,
) -> Dict[str, object]:
    timestamp = utc_now()
    call = {
        "id": str(uuid.uuid4()),
        "started_at": timestamp,
        "updated_at": timestamp,
        "operation": normalize_text_value(operation, fallback="model_call", limit=80),
        "backend": normalize_text_value(backend, fallback="", limit=40),
        "model": normalize_model_name(model),
        "host": normalize_text_value(host, fallback="", limit=180),
        "status": "running",
        "message_count": int(message_count or 0),
        "max_tokens": int(max_tokens or 0),
        "thread_name": threading.current_thread().name,
    }
    if private_evaluator_persistence_active():
        call["evaluator_private"] = True
        call["persisted"] = False
        return call

    def mutator(payload: Dict[str, object]) -> Dict[str, object]:
        calls = [dict(item) for item in payload.get("calls", []) if isinstance(item, dict)]
        calls.append(dict(call))
        payload["calls"] = calls
        return dict(call)

    return mutate_active_model_calls(mutator)


def finish_active_model_call(call_id: Optional[str], *, ok: bool = True, error_text: str = "") -> None:
    if not call_id:
        return
    if private_evaluator_persistence_active():
        return

    def mutator(payload: Dict[str, object]) -> None:
        payload["calls"] = [
            dict(item)
            for item in payload.get("calls", [])
            if isinstance(item, dict) and str(item.get("id") or "") != str(call_id)
        ]
        return None

    try:
        mutate_active_model_calls(mutator)
    except Exception:
        pass


def default_ambient_thought() -> Dict[str, object]:
    return json.loads(json.dumps(DEFAULT_AMBIENT_THOUGHT))


def normalize_ambient_thread_beat(payload: object) -> Optional[Dict[str, str]]:
    if not isinstance(payload, dict):
        return None
    source_id = normalize_text_value(payload.get("source_id"), fallback="", limit=120).lower()
    thread_title = normalize_text_value(payload.get("thread_title"), fallback="", limit=140)
    title = normalize_text_value(payload.get("title"), fallback=thread_title, limit=120)
    detail = normalize_text_value(payload.get("detail"), fallback=title, limit=220)
    if not source_id and not thread_title and not title:
        return None
    return {
        "source_id": source_id or normalize_text_value(thread_title or title, fallback="", limit=120).lower(),
        "thread_title": thread_title or title,
        "thread_kind": normalize_text_value(payload.get("thread_kind"), fallback="", limit=40).lower(),
        "thread_status": normalize_text_value(payload.get("thread_status"), fallback="", limit=40).lower(),
        "title": title,
        "detail": detail,
        "updated_at": normalize_text_value(payload.get("updated_at"), fallback="", limit=40),
    }


def normalize_ambient_thought(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    notes = payload.get("notes") if isinstance(payload.get("notes"), list) else []
    thread_beats = payload.get("thread_beats") if isinstance(payload.get("thread_beats"), list) else []
    normalized_notes = []
    for item in notes:
        if not isinstance(item, dict):
            continue
        normalized_notes.append(
            {
                "id": normalize_text_value(item.get("id"), fallback=str(uuid.uuid4()), limit=80),
                "timestamp": item.get("timestamp") or utc_now(),
                "phase": normalize_text_value(item.get("phase"), fallback="ambient", limit=40),
                "kind": normalize_text_value(item.get("kind"), fallback="ambient", limit=40),
                "title": normalize_text_value(item.get("title"), fallback="Eve is holding a live thought.", limit=120),
                "detail": normalize_text_value(item.get("detail"), fallback="", limit=220),
            }
        )
    normalized_thread_beats = [
        item for item in (normalize_ambient_thread_beat(beat) for beat in thread_beats) if item is not None
    ]
    return {
        "updated_at": payload.get("updated_at"),
        "status": normalize_text_value(payload.get("status"), fallback="idle", limit=20),
        "title": normalize_text_value(payload.get("title"), fallback="", limit=120),
        "detail": normalize_text_value(payload.get("detail"), fallback="", limit=220),
        "model": normalize_model_name(payload.get("model")),
        "source": normalize_text_value(payload.get("source"), fallback="", limit=80),
        "thread_beats": normalized_thread_beats[:6],
        "notes": trim_reply_progress_notes([item for item in normalized_notes if item is not None], keep=12),
    }


def load_ambient_thought(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = AMBIENT_THOUGHT_REPOSITORY.load(prefer_runtime=prefer_runtime)
    return normalize_ambient_thought(payload)


def save_ambient_thought(payload: Dict[str, object]) -> None:
    AMBIENT_THOUGHT_REPOSITORY.save(normalize_ambient_thought(payload))


def update_ambient_thought(
    *,
    title: str,
    detail: str,
    model: str,
    source: str,
    status: str = "active",
    thread_beats: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    current = load_ambient_thought()
    normalized_title = normalize_text_value(title, fallback="Eve is holding a live thought.", limit=120)
    normalized_detail = normalize_text_value(detail, fallback="", limit=220)
    previous_title = normalize_text_value(current.get("title"), fallback="", limit=120)
    previous_detail = normalize_text_value(current.get("detail"), fallback="", limit=220)
    notes = [dict(item) for item in current.get("notes", []) if isinstance(item, dict)]
    normalized_thread_beats = (
        [item for item in (normalize_ambient_thread_beat(beat) for beat in (thread_beats or [])) if item is not None][:6]
        if thread_beats is not None
        else [dict(item) for item in current.get("thread_beats", []) if isinstance(item, dict)]
    )
    if thread_beats is not None:
        previous_thread_beats = {
            str(item.get("source_id") or ""): item
            for item in current.get("thread_beats", [])
            if isinstance(item, dict) and str(item.get("source_id") or "")
        }
        for beat in normalized_thread_beats:
            prior = previous_thread_beats.get(str(beat.get("source_id") or ""))
            if prior and prior.get("title") == beat.get("title") and prior.get("detail") == beat.get("detail"):
                continue
            notes.append(
                build_reply_progress_note(
                    str(beat.get("thread_kind") or "ambient"),
                    str(beat.get("thread_title") or beat.get("title") or "Live thread"),
                    str(beat.get("detail") or beat.get("title") or ""),
                    kind="thread_micro_update",
                )
            )
    elif normalized_title != previous_title or normalized_detail != previous_detail:
        notes.append(build_reply_progress_note("ambient", normalized_title, normalized_detail, kind="ambient"))
    updated = {
        **current,
        "updated_at": utc_now(),
        "status": normalize_text_value(status, fallback="active", limit=20),
        "title": normalized_title,
        "detail": normalized_detail,
        "model": normalize_model_name(model),
        "source": normalize_text_value(source, fallback="", limit=80),
        "thread_beats": normalized_thread_beats,
        "notes": trim_reply_progress_notes(notes, keep=12),
    }
    save_ambient_thought(updated)
    return updated


def parse_iso_datetime(value: Optional[object]) -> Optional[datetime]:
    if not value:
        return None
    text = str(value).strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=timezone.utc)
    return parsed


def utc_now_datetime() -> datetime:
    return datetime.now(timezone.utc)


def interval_due(last_timestamp: Optional[object], minutes: int) -> bool:
    if minutes <= 0:
        return True
    last_dt = parse_iso_datetime(last_timestamp)
    if last_dt is None:
        return True
    return utc_now_datetime() - last_dt >= timedelta(minutes=minutes)


def interval_due_seconds(last_timestamp: Optional[object], seconds: int) -> bool:
    if seconds <= 0:
        return True
    last_dt = parse_iso_datetime(last_timestamp)
    if last_dt is None:
        return True
    return utc_now_datetime() - last_dt >= timedelta(seconds=seconds)


def daemon_autonomy_continuous_mode(config: Optional[Dict[str, object]] = None) -> bool:
    effective_config = config or load_config()
    return parse_boolish(effective_config.get("daemon_autonomy_continuous", False))


def daemon_autonomy_handoff_seconds(config: Optional[Dict[str, object]] = None) -> int:
    effective_config = config or load_config()
    return clamp_int(effective_config.get("daemon_autonomy_handoff_seconds"), 30, minimum=15, maximum=900)


def daemon_autonomy_due(config: Dict[str, object], state: Dict[str, object], *, force: bool = False) -> bool:
    if force:
        return True
    last_timestamp = state.get("last_daemon_autonomy_run_at") or state.get("last_daemon_autonomy_attempt_at")
    if daemon_autonomy_continuous_mode(config):
        return interval_due_seconds(last_timestamp, daemon_autonomy_handoff_seconds(config))
    base_interval = int(config.get("daemon_autonomy_interval_minutes") or 30)
    try:
        factor = homeostasis_autonomy_interval_factor()
    except Exception:
        factor = 1.0
    return interval_due(last_timestamp, max(5, int(round(base_interval * factor))))


def normalize_text_value(value: object, fallback: str = "Not enough evidence yet.", limit: int = 320) -> str:
    text = " ".join(str(value or "").split()).strip()
    return text[:limit] if text else fallback


def action_contract_issue(field: str, problem: str, *, received: object = None) -> Dict[str, object]:
    issue = {"field": field, "problem": problem}
    if received is not None:
        issue["received"] = normalize_text_value(received, fallback="", limit=120)
    return issue


def normalize_text_list(value: object, limit: int = 5) -> List[str]:
    if isinstance(value, str):
        candidates = [value]
    elif isinstance(value, list):
        candidates = value
    else:
        candidates = []
    normalized: List[str] = []
    seen = set()
    for candidate in candidates:
        text = " ".join(str(candidate or "").split()).strip(" -")
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        normalized.append(text[:220])
        if len(normalized) >= limit:
            break
    return normalized


def normalize_reviewer_name(value: object, fallback: str = "Reviewer") -> str:
    text = " ".join(str(value or "").split()).strip()
    return text[:80] or fallback


def reviewer_token(value: object, fallback: str = "reviewer") -> str:
    token = re.sub(r"[^a-z0-9]+", "-", str(value or "").strip().lower()).strip("-")
    return token[:40] or fallback


def default_review_request_via(reviewer: object) -> str:
    return "claude" if reviewer_token(reviewer, fallback="") == CLAUDE_PARTICIPANT else "manual"


def default_human_context() -> Dict[str, object]:
    return json.loads(json.dumps(DEFAULT_HUMAN_CONTEXT))


def default_runtime_identity() -> Dict[str, object]:
    return json.loads(json.dumps(DEFAULT_RUNTIME_IDENTITY))


def normalize_runtime_identity(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    normalized = default_runtime_identity()
    normalized["updated_at"] = payload.get("updated_at")
    normalized["source"] = normalize_text_value(payload.get("source"), fallback="", limit=80)
    normalized["runtime_summary"] = normalize_text_value(payload.get("runtime_summary"))
    normalized["mission"] = normalize_text_value(payload.get("mission"))
    normalized["model_role"] = normalize_text_value(payload.get("model_role"))
    normalized["organ_system"] = unique_compact(
        [
            *normalize_text_list(payload.get("organ_system"), limit=8),
            *DEFAULT_RUNTIME_IDENTITY["organ_system"],
        ],
        limit=8,
    )
    normalized["decision_lens"] = normalize_text_list(payload.get("decision_lens"), limit=7)
    normalized["style_contract"] = normalize_text_list(payload.get("style_contract"))
    normalized["improvement_loop"] = normalize_text_list(payload.get("improvement_loop"))
    normalized["capability_ledger"] = unique_compact(
        [
            *normalize_text_list(payload.get("capability_ledger"), limit=20),
            *DEFAULT_RUNTIME_IDENTITY["capability_ledger"],
        ],
        limit=20,
    )
    return normalized


def merge_runtime_identity(previous: Dict[str, object], current: Dict[str, object]) -> Dict[str, object]:
    previous_normalized = normalize_runtime_identity(previous)
    current_normalized = normalize_runtime_identity(current)
    merged = normalize_runtime_identity(current_normalized)

    for field in ["decision_lens", "style_contract", "improvement_loop"]:
        field_limit = 7 if field == "decision_lens" else 5
        merged[field] = unique_compact(
            [*current_normalized.get(field, []), *previous_normalized.get(field, [])],
            limit=field_limit,
        )
    merged["capability_ledger"] = unique_compact(
        [
            *current_normalized.get("capability_ledger", []),
            *previous_normalized.get("capability_ledger", []),
            *DEFAULT_RUNTIME_IDENTITY["capability_ledger"],
        ],
        limit=20,
    )
    merged["organ_system"] = unique_compact(
        [
            *current_normalized.get("organ_system", []),
            *previous_normalized.get("organ_system", []),
            *DEFAULT_RUNTIME_IDENTITY["organ_system"],
        ],
        limit=8,
    )

    for field in ["runtime_summary", "mission", "model_role"]:
        if (
            current_normalized.get(field) == DEFAULT_RUNTIME_IDENTITY[field]
            and previous_normalized.get(field) != DEFAULT_RUNTIME_IDENTITY[field]
        ):
            merged[field] = previous_normalized[field]

    return merged


def load_runtime_identity(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = RUNTIME_IDENTITY_REPOSITORY.load(prefer_runtime=prefer_runtime)
    return normalize_runtime_identity(payload)


def save_runtime_identity(identity: Dict[str, object], snapshot_source: str = "runtime_identity_update") -> None:
    RUNTIME_IDENTITY_REPOSITORY.save(normalize_runtime_identity(identity))
    ensure_version_snapshot(snapshot_source)


def format_runtime_identity_report(identity: Dict[str, object]) -> str:
    normalized = normalize_runtime_identity(identity)
    lines = [
        f"updated_at: {normalized.get('updated_at') or 'never'}",
        f"source: {normalized.get('source') or 'unknown'}",
        "",
        f"runtime_summary: {normalized['runtime_summary']}",
        f"mission: {normalized['mission']}",
        f"model_role: {normalized['model_role']}",
        f"organ_system: {format_human_context_list(normalized['organ_system'])}",
        f"decision_lens: {format_human_context_list(normalized['decision_lens'])}",
        f"style_contract: {format_human_context_list(normalized['style_contract'])}",
        f"improvement_loop: {format_human_context_list(normalized['improvement_loop'])}",
        f"capability_ledger: {format_human_context_list(normalized['capability_ledger'])}",
    ]
    return "\n".join(lines)


# An expiry preposition must immediately abut the date (word-boundary), so only a
# genuine deadline triggers pruning — not an event timestamp ("granted on <date>"),
# a range start ("from <date>"), or incidental substrings ("through-line ... <date>").
# Only an expiry preposition immediately abutting the date counts. Bare "through"
# and bare "valid"/"granted" are deliberately excluded — they fire on event
# timestamps ("granted on <date>"), range starts ("valid from <date>"), and
# incidental phrasing ("worked through <date>'s backlog"), causing data loss.
BELIEF_EXPIRY_PATTERN = re.compile(
    r"\b(?:until|expires?|expiry|ends?|valid\s+(?:until|through)|runs?\s+through)\s+(\d{4}-\d{2}-\d{2})",
    re.IGNORECASE,
)


def belief_is_expired(text: object) -> bool:
    """A durable belief carrying an explicit, now-past EXPIRY date is stale and
    should not keep presenting as current (e.g. 'Unharnessed local trust granted
    until 2026-05-14'). Only an expiry preposition adjacent to the date counts, and
    for a date range only the LATEST expiry-cued date governs — so 'valid from
    2026-01-01 until 2030-12-31' is kept, and event timestamps are never pruned."""
    lowered = " ".join(str(text or "").lower().split())
    if not lowered:
        return False
    now = utc_now_datetime()
    cued_dates: List[datetime] = []
    for match in BELIEF_EXPIRY_PATTERN.finditer(lowered):
        try:
            cued_dates.append(datetime.fromisoformat(match.group(1)).replace(tzinfo=timezone.utc))
        except ValueError:
            continue
    if not cued_dates:
        return False
    return max(cued_dates) < now


def prune_expired_beliefs(items: object) -> Tuple[List[str], List[str]]:
    """Return (survivors, expired). Expired beliefs are not discarded silently —
    the caller archives them so a prune is recoverable, not data loss."""
    survivors: List[str] = []
    expired: List[str] = []
    for item in normalize_text_list(items):
        (expired if belief_is_expired(item) else survivors).append(item)
    return survivors, expired


def normalize_human_context(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    self_model = payload.get("self_model") if isinstance(payload.get("self_model"), dict) else {}
    relationship = payload.get("relationship_memory") if isinstance(payload.get("relationship_memory"), dict) else {}
    memory_v2 = payload.get("memory_v2") if isinstance(payload.get("memory_v2"), dict) else {}
    normalized = default_human_context()
    normalized["updated_at"] = payload.get("updated_at")
    normalized["source"] = normalize_text_value(payload.get("source"), fallback="", limit=80)
    normalized["source_entries"] = int(payload.get("source_entries") or 0)
    normalized["source_messages"] = int(payload.get("source_messages") or 0)
    normalized["self_model"] = {
        "identity_statement": normalize_text_value(self_model.get("identity_statement")),
        "current_preoccupations": normalize_text_list(self_model.get("current_preoccupations")),
        "values_in_practice": normalize_text_list(self_model.get("values_in_practice")),
        "growth_edges": normalize_text_list(self_model.get("growth_edges")),
        "grounding_practices": normalize_text_list(self_model.get("grounding_practices")),
        "recent_shifts": normalize_text_list(self_model.get("recent_shifts")),
    }
    # Durable beliefs are pruned of explicitly-expired entries on every load, so a
    # lapsed grant or deadline cannot keep presenting as current self-knowledge.
    # Pruned beliefs are archived into superseded_or_conflicting_beliefs (with an
    # "(expired)" tag) rather than discarded, so a prune is recoverable, not loss.
    expired_archive: List[str] = []
    open_loops, open_loops_expired = prune_expired_beliefs(relationship.get("open_loops"))
    expired_archive.extend(open_loops_expired)
    normalized["relationship_memory"] = {
        "user_overview": normalize_text_value(relationship.get("user_overview")),
        "what_user_seems_to_value": normalize_text_list(relationship.get("what_user_seems_to_value")),
        "communication_preferences": normalize_text_list(relationship.get("communication_preferences")),
        "requested_practices": normalize_text_list(relationship.get("requested_practices")),
        "open_loops": open_loops,
        "care_notes": normalize_text_list(relationship.get("care_notes")),
    }
    semantic, semantic_expired = prune_expired_beliefs(memory_v2.get("semantic_understanding"))
    procedural, procedural_expired = prune_expired_beliefs(memory_v2.get("procedural_preferences"))
    trust, trust_expired = prune_expired_beliefs(memory_v2.get("trust_ledger"))
    expired_archive.extend(semantic_expired)
    expired_archive.extend(procedural_expired)
    expired_archive.extend(trust_expired)
    superseded = normalize_text_list(memory_v2.get("superseded_or_conflicting_beliefs"))
    if expired_archive:
        superseded = unique_compact(
            [f"(expired) {item}" for item in expired_archive] + superseded,
            limit=12,
        )
    normalized["memory_v2"] = {
        "semantic_understanding": semantic,
        "episodic_markers": normalize_text_list(memory_v2.get("episodic_markers")),
        "procedural_preferences": procedural,
        "trust_ledger": trust,
        "anti_sycophancy_boundaries": normalize_text_list(memory_v2.get("anti_sycophancy_boundaries")),
        "repair_practices": normalize_text_list(memory_v2.get("repair_practices")),
        "superseded_or_conflicting_beliefs": superseded,
    }
    return normalized


def merge_human_context(previous: Dict[str, object], current: Dict[str, object]) -> Dict[str, object]:
    previous_normalized = normalize_human_context(previous)
    current_normalized = normalize_human_context(current)
    merged = normalize_human_context(current_normalized)

    previous_self = previous_normalized["self_model"]
    current_self = current_normalized["self_model"]
    merged_self = merged["self_model"]
    for field in ["current_preoccupations", "values_in_practice", "growth_edges", "grounding_practices", "recent_shifts"]:
        merged_self[field] = unique_compact(
            [*current_self.get(field, []), *previous_self.get(field, [])],
            limit=5,
        )
    if current_self.get("identity_statement") == "Not enough evidence yet." and previous_self.get("identity_statement") != "Not enough evidence yet.":
        merged_self["identity_statement"] = previous_self["identity_statement"]

    previous_relationship = previous_normalized["relationship_memory"]
    current_relationship = current_normalized["relationship_memory"]
    merged_relationship = merged["relationship_memory"]
    for field in [
        "what_user_seems_to_value",
        "communication_preferences",
        "requested_practices",
        "open_loops",
        "care_notes",
    ]:
        merged_relationship[field] = unique_compact(
            [*current_relationship.get(field, []), *previous_relationship.get(field, [])],
            limit=5,
        )
    if (
        current_relationship.get("user_overview") == "Not enough evidence yet."
        and previous_relationship.get("user_overview") != "Not enough evidence yet."
    ):
        merged_relationship["user_overview"] = previous_relationship["user_overview"]

    previous_memory_v2 = previous_normalized["memory_v2"]
    current_memory_v2 = current_normalized["memory_v2"]
    merged_memory_v2 = merged["memory_v2"]
    for field in [
        "semantic_understanding",
        "episodic_markers",
        "procedural_preferences",
        "trust_ledger",
        "anti_sycophancy_boundaries",
        "repair_practices",
        "superseded_or_conflicting_beliefs",
    ]:
        merged_memory_v2[field] = unique_compact(
            [*current_memory_v2.get(field, []), *previous_memory_v2.get(field, [])],
            limit=8,
        )

    return merged


def load_human_context(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = HUMAN_CONTEXT_REPOSITORY.load(prefer_runtime=prefer_runtime)
    return normalize_human_context(payload)


def save_human_context(context: Dict[str, object], snapshot_source: str = "human_context_update") -> None:
    HUMAN_CONTEXT_REPOSITORY.save(normalize_human_context(context))
    ensure_version_snapshot(snapshot_source)


def format_human_context_list(items: List[str]) -> str:
    return "; ".join(items) if items else "none recorded"


def default_active_mind() -> Dict[str, object]:
    return json.loads(json.dumps(DEFAULT_ACTIVE_MIND))


def normalize_active_mind_lanes(payload: object) -> Dict[str, str]:
    if isinstance(payload, dict):
        lanes = payload
    else:
        lanes = {}
    return {
        "observer": normalize_text_value(lanes.get("observer"), fallback="", limit=180),
        "planner": normalize_text_value(lanes.get("planner"), fallback="", limit=180),
        "relationship": normalize_text_value(lanes.get("relationship"), fallback="", limit=180),
        "grounding": normalize_text_value(lanes.get("grounding"), fallback="", limit=180),
        "self_check": normalize_text_value(lanes.get("self_check"), fallback="", limit=180),
    }


def normalize_active_mind_next_step_provenance(payload: object) -> Dict[str, object]:
    """Normalize the authority attached to one exact active-mind next step.

    Model-authored planner text is a proposal, not a goal source.  The
    ``goal_eligible`` bit only survives when a known source substrate, a stable
    source id, and the exact bound step are all present.
    """
    record = payload if isinstance(payload, dict) else {}
    source_kind = normalize_text_value(
        record.get("source_kind"),
        fallback="unattributed",
        limit=60,
    ).lower()
    source_id = normalize_text_value(record.get("source_id"), fallback="", limit=160)
    step_text = normalize_text_value(record.get("step_text"), fallback="", limit=220)
    requested = parse_boolish(record.get("goal_eligible"))
    goal_eligible = bool(
        requested
        and source_kind in ACTIVE_MIND_GOAL_ELIGIBLE_SOURCE_KINDS
        and source_id
        and step_text
    )
    return {
        "source_kind": source_kind,
        "source_id": source_id,
        "goal_eligible": goal_eligible,
        "step_text": step_text if goal_eligible else "",
        "evidence": normalize_text_value(record.get("evidence"), fallback="", limit=220),
    }


def active_mind_next_step_provenance(
    step_text: object,
    *,
    source_kind: str,
    source_id: object,
    evidence: object = "",
    goal_eligible: bool = True,
) -> Dict[str, object]:
    """Create an exact source contract for a candidate next-step goal."""
    normalized_step = normalize_text_value(step_text, fallback="", limit=220)
    return normalize_active_mind_next_step_provenance(
        {
            "source_kind": source_kind,
            "source_id": source_id,
            "goal_eligible": goal_eligible,
            "step_text": normalized_step,
            "evidence": evidence,
        }
    )


def active_mind_next_step_is_goal_eligible(mind: object) -> bool:
    if not isinstance(mind, dict):
        return False
    step = normalize_text_value(mind.get("next_step"), fallback="", limit=220)
    provenance = normalize_active_mind_next_step_provenance(
        mind.get("next_step_provenance")
    )
    return bool(
        provenance.get("goal_eligible")
        and step
        and provenance.get("step_text") == step
    )


def clamp_thread_weight(value: object, default: int = 0) -> int:
    try:
        number = int(float(value))
    except (TypeError, ValueError):
        number = default
    return max(0, min(number, 100))


def scale_scheduler_signal(
    raw_value: object,
    *,
    low: int = -20,
    high: int = 240,
    minimum: int = 0,
    maximum: int = 100,
) -> int:
    try:
        raw = float(raw_value)
    except (TypeError, ValueError):
        raw = float(low)
    if high <= low:
        return clamp_thread_weight(maximum, default=maximum)
    if raw <= low:
        return clamp_thread_weight(minimum, default=minimum)
    if raw >= high:
        return clamp_thread_weight(maximum, default=maximum)
    ratio = (raw - low) / float(high - low)
    scaled = minimum + ratio * (maximum - minimum)
    return clamp_thread_weight(int(round(scaled)), default=minimum)


def scheduler_recency_adjustment(
    timestamp: object,
    *,
    missing_penalty: int = -10,
) -> int:
    parsed = parse_iso_datetime(timestamp)
    if parsed is None:
        return missing_penalty
    age_seconds = max(0.0, (utc_now_datetime() - parsed).total_seconds())
    if age_seconds <= 15 * 60:
        return 12
    if age_seconds <= 60 * 60:
        return 6
    if age_seconds <= 6 * 60 * 60:
        return 0
    if age_seconds <= 24 * 60 * 60:
        return -14
    return -26


def active_mind_thread_status_rank(value: object) -> int:
    status = normalize_text_value(value, fallback="active", limit=40).lower()
    ranks = {
        "active": 7,
        "waiting": 6,
        "queued": 5,
        "relating": 4,
        "monitoring": 4,
        "grounding": 3,
        "watching": 2,
    }
    return ranks.get(status, 1)


def default_active_mind_thread_pressure(salience: int, status: str) -> int:
    bonuses = {
        "active": 10,
        "waiting": 16,
        "queued": 8,
        "relating": 8,
        "monitoring": 10,
        "grounding": 6,
        "watching": 4,
    }
    return clamp_thread_weight(max(0, salience - 10) + bonuses.get(status, 0), default=48)


def normalize_active_mind_thread_timestamp(value: object) -> str:
    parsed = parse_iso_datetime(value)
    if parsed is None:
        return normalize_text_value(value, fallback="", limit=40)
    return parsed.astimezone(timezone.utc).isoformat()


def active_mind_thread_sort_key(thread: Dict[str, object]) -> tuple:
    parsed = parse_iso_datetime(thread.get("last_updated"))
    timestamp_score = parsed.timestamp() if parsed is not None else 0.0
    return (
        int(thread.get("pressure") or 0),
        int(thread.get("salience") or 0),
        active_mind_thread_status_rank(thread.get("status")),
        timestamp_score,
        normalize_text_value(thread.get("title"), fallback="", limit=140).lower(),
    )


def active_mind_thread_force_include_candidate(thread: Dict[str, object]) -> bool:
    if thread.get("kind") != "conversation":
        return False
    status = normalize_text_value(thread.get("status"), fallback="", limit=40).lower()
    if status not in {"active", "waiting"}:
        return False
    if status == "waiting":
        return True
    return int(thread.get("pressure") or 0) >= 35


def active_mind_thread_is_newer(candidate: Dict[str, object], existing: Dict[str, object]) -> bool:
    candidate_dt = parse_iso_datetime(candidate.get("last_updated"))
    existing_dt = parse_iso_datetime(existing.get("last_updated"))
    if candidate_dt is not None and existing_dt is not None:
        return candidate_dt > existing_dt
    if candidate_dt is not None and existing_dt is None:
        return True
    if candidate_dt is None and existing_dt is not None:
        return False
    return False


def active_mind_thread_scheduler_summary(thread: Dict[str, object]) -> str:
    parts = [
        f"pressure {int(thread.get('pressure') or 0)}",
        f"salience {int(thread.get('salience') or 0)}",
    ]
    next_step = normalize_text_value(thread.get("next_step"), fallback="", limit=180)
    if next_step:
        parts.append(f"next {next_step}")
    return "; ".join(parts)


def active_mind_thread_change_notes(previous: Dict[str, object], current: Dict[str, object]) -> List[str]:
    notes: List[str] = []
    if previous.get("status") != current.get("status"):
        notes.append(f"status {previous.get('status')} -> {current.get('status')}")
    if previous.get("pressure") != current.get("pressure"):
        notes.append(f"pressure {previous.get('pressure')} -> {current.get('pressure')}")
    if previous.get("salience") != current.get("salience"):
        notes.append(f"salience {previous.get('salience')} -> {current.get('salience')}")
    if previous.get("next_step") != current.get("next_step") and current.get("next_step"):
        notes.append(f"next {current.get('next_step')}")
    if previous.get("detail") != current.get("detail"):
        notes.append("detail shifted")
    return notes


def normalize_active_mind_thread(payload: object) -> Optional[Dict[str, object]]:
    if not isinstance(payload, dict):
        return None
    kind = normalize_text_value(payload.get("kind"), fallback="", limit=40).lower()
    status = normalize_text_value(payload.get("status"), fallback="", limit=40).lower()
    title = normalize_text_value(payload.get("title"), fallback="", limit=140)
    detail = normalize_text_value(payload.get("detail"), fallback="", limit=220)
    if not title and not detail:
        return None
    if not title:
        title = detail[:140]
    if not detail:
        detail = title
    allowed_kinds = {
        "focus",
        "conversation",
        "concern",
        "relationship",
        "grounding",
        "self_check",
        "next_step",
        "organ",
    }
    allowed_statuses = {
        "active",
        "waiting",
        "watching",
        "relating",
        "grounding",
        "monitoring",
        "queued",
    }
    if kind not in allowed_kinds:
        kind = "concern"
    if status not in allowed_statuses:
        status = "active"
    raw_salience = max(
        0,
        focus_text_salience_score(title),
        focus_text_salience_score(detail),
    )
    salience = clamp_thread_weight(
        payload.get("salience"),
        default=scale_scheduler_signal(raw_salience, low=10, high=180, minimum=24, maximum=92),
    )
    pressure = clamp_thread_weight(
        payload.get("pressure"),
        default=default_active_mind_thread_pressure(salience, status),
    )
    last_updated = normalize_active_mind_thread_timestamp(payload.get("last_updated") or payload.get("updated_at"))
    evidence = normalize_text_list(payload.get("evidence"), limit=3)
    next_step = normalize_text_value(payload.get("next_step"), fallback="", limit=180)
    source_id = normalize_text_value(payload.get("source_id"), fallback="", limit=120).lower()
    goal_provenance = normalize_active_mind_next_step_provenance(
        payload.get("goal_provenance")
    )
    if kind != "next_step" or goal_provenance.get("step_text") != title:
        goal_provenance = normalize_active_mind_next_step_provenance({})
    return {
        "title": title,
        "detail": detail,
        "kind": kind,
        "status": status,
        "salience": salience,
        "pressure": pressure,
        "last_updated": last_updated,
        "evidence": evidence,
        "next_step": next_step,
        "source_id": source_id,
        "goal_provenance": goal_provenance,
    }


def active_mind_thread_is_goal_eligible(thread: object) -> bool:
    if not isinstance(thread, dict) or str(thread.get("kind") or "") != "next_step":
        return False
    title = normalize_text_value(thread.get("title"), fallback="", limit=220)
    provenance = normalize_active_mind_next_step_provenance(
        thread.get("goal_provenance")
    )
    return bool(
        provenance.get("goal_eligible")
        and title
        and provenance.get("step_text") == title
    )


def active_mind_thread_text_token(*values: object, limit: int = 96) -> str:
    chunks: List[str] = []
    for value in values:
        text = normalize_text_value(value, fallback="", limit=220).lower()
        if not text:
            continue
        cleaned = "".join(ch if ch.isalnum() else " " for ch in text)
        chunks.extend(part for part in cleaned.split() if part)
    return " ".join(chunks)[:limit].strip()


def active_mind_thread_dedup_token(thread: Dict[str, object]) -> str:
    source_id = normalize_text_value(thread.get("source_id"), fallback="", limit=120).lower()
    title_token = active_mind_thread_text_token(thread.get("title"), limit=96)
    detail_token = active_mind_thread_text_token(thread.get("detail"), limit=96)
    stable_prefixes = (
        "agenda:",
        "homeostasis:",
        "message:",
        "openclaw:",
        "organ:",
        "self_check:",
        "thread:",
    )
    if source_id and source_id.startswith(stable_prefixes):
        return source_id
    if title_token:
        return title_token
    if detail_token:
        return detail_token
    return source_id


def normalize_active_mind_threads(payload: object, limit: int = 6) -> List[Dict[str, object]]:
    if not isinstance(payload, list):
        return []
    normalized_by_key: Dict[tuple, Dict[str, object]] = {}
    for item in payload:
        thread = normalize_active_mind_thread(item)
        if not thread:
            continue
        if focus_text_salience_score(thread["title"]) < -20 and focus_text_salience_score(thread["detail"]) < -20:
            continue
        key = (thread["kind"], active_mind_thread_dedup_token(thread))
        existing = normalized_by_key.get(key)
        if existing is not None and not active_mind_thread_is_newer(thread, existing):
            continue
        normalized_by_key[key] = thread
    normalized = sorted(normalized_by_key.values(), key=active_mind_thread_sort_key, reverse=True)
    selected = normalized[:limit]
    if (
        limit > 0
        and selected
        and not any(thread.get("kind") == "conversation" for thread in selected)
        and any(active_mind_thread_force_include_candidate(thread) for thread in normalized)
    ):
        conversation = next(thread for thread in normalized if active_mind_thread_force_include_candidate(thread))
        replace_index = len(selected) - 1
        for index in range(len(selected) - 1, -1, -1):
            if selected[index].get("kind") != "focus":
                replace_index = index
                break
        selected = selected[:replace_index] + [conversation] + selected[replace_index + 1 :]
        selected = sorted(selected, key=active_mind_thread_sort_key, reverse=True)
    return selected



def active_mind_thread_stale_for_reference(thread: Dict[str, object], reference_timestamp: object) -> bool:
    reference = parse_iso_datetime(reference_timestamp) or utc_now_datetime()
    updated = parse_iso_datetime(thread.get("last_updated"))
    if updated is None:
        return False
    age_seconds = (reference - updated).total_seconds()
    if age_seconds <= 0:
        return False
    kind = normalize_text_value(thread.get("kind"), fallback="", limit=40).lower()
    status = normalize_text_value(thread.get("status"), fallback="", limit=40).lower()
    pressure = int(thread.get("pressure") or 0)
    if kind in {"concern", "organ"} and status in {"monitoring", "watching"} and age_seconds > 6 * 60 * 60:
        return True
    if kind == "conversation" and status in {"active", "waiting", "queued"} and pressure < 50 and age_seconds > 24 * 60 * 60:
        return True
    return False


def openclaw_body_signal_threads(*, prefer_runtime: bool = False, limit: int = 2) -> List[Dict[str, object]]:
    signals: List[Dict[str, object]] = []
    events: List[Dict[str, object]] = [
        *eve_openclaw_body.read_openclaw_action_router_events(limit=4, prefer_runtime=prefer_runtime),
        *eve_openclaw_body.read_openclaw_routine_events(limit=4, prefer_runtime=prefer_runtime),
    ]
    events.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    seen_signal_keys: set = set()
    for event in events:
        if len(signals) >= limit:
            break
        status = str(event.get("status") or "").strip().lower()
        if status in {"skipped", "dry_run"}:
            continue
        ok = bool(event.get("ok"))
        created_at = event.get("created_at")
        parsed = parse_iso_datetime(created_at)
        age_seconds = (utc_now_datetime() - parsed).total_seconds() if parsed is not None else 999999.0
        degraded = status in {"degraded", "failed", "error"} or (event.get("executed") and not ok)
        if age_seconds > 6 * 60 * 60:
            continue
        action = normalize_text_value(event.get("action") or event.get("router_action"), fallback="openclaw", limit=80)
        routine_id = normalize_text_value(event.get("routine_id"), fallback="", limit=120)
        signal_key = (action, degraded)
        if signal_key in seen_signal_keys:
            continue
        seen_signal_keys.add(signal_key)
        title = "OpenClaw body needs attention" if degraded else "OpenClaw body routine completed"
        detail = normalize_text_value(
            event.get("summary"),
            fallback=f"OpenClaw {action} event recorded.",
            limit=220,
        )
        signals.append(
            {
                "kind": "concern",
                "status": "monitoring",
                "title": title,
                "detail": detail,
                "salience": 72 if degraded else 34,
                "pressure": 82 if degraded else 30,
                "last_updated": created_at,
                "evidence": normalize_text_list(
                    [
                        f"action={action}" if action else "",
                        f"routine={routine_id}" if routine_id else "",
                        f"event={event.get('id') or ''}",
                    ],
                    limit=3,
                ),
                "next_step": (
                    "Inspect `python3 eve.py openclaw status` and the latest router event before taking repair action."
                    if degraded
                    else "Keep this as background body state unless new evidence degrades."
                ),
                "source_id": f"openclaw:{routine_id or action}",
            }
        )
    return normalize_active_mind_threads(signals, limit=limit)


def organ_operational_status(status: object) -> str:
    normalized = normalize_text_value(status, fallback="unknown", limit=80).lower()
    if normalized in {"blocked", "degraded"}:
        return normalized
    if normalized in {"healthy", "staged_live"}:
        return "ready"
    if normalized in {"partial", "staged_local_pilot", "installed_not_initialized"}:
        return "working"
    if normalized in {"configured_lab_candidate", "lab_available", "lab_verified"}:
        return "lab_ready"
    if normalized in {"planned", "research_candidate", "available_not_configured"}:
        return "not_configured"
    return "unknown"


def normalize_organ_signal(payload: object) -> Optional[Dict[str, object]]:
    if not isinstance(payload, dict):
        return None
    organ_id = normalize_text_value(payload.get("id") or payload.get("organ_id"), fallback="", limit=120).lower()
    label = normalize_text_value(payload.get("label"), fallback=organ_id.replace("_", " ").title(), limit=120)
    role = normalize_text_value(payload.get("role"), fallback="", limit=260)
    status = normalize_text_value(payload.get("status"), fallback="unknown", limit=60).lower()
    if not organ_id and not label:
        return None
    allowed_statuses = {
        "healthy",
        "partial",
        "planned",
        "blocked",
        "degraded",
        "unknown",
        "available_not_configured",
        "configured_lab_candidate",
        "lab_available",
        "lab_verified",
        "research_candidate",
        "staged_local_pilot",
        "staged_live",
        "installed_not_initialized",
    }
    if status not in allowed_statuses:
        status = "partial" if status else "unknown"
    maturity_status = normalize_text_value(payload.get("maturity_status"), fallback=status, limit=80).lower()
    operational_status = normalize_text_value(
        payload.get("operational_status"),
        fallback=organ_operational_status(status),
        limit=80,
    ).lower()
    salience = clamp_thread_weight(payload.get("salience"), default=38)
    pressure_default = (
        82
        if operational_status in {"blocked", "degraded"}
        else 58
        if operational_status in {"limited", "not_configured"}
        else 32
    )
    pressure = clamp_thread_weight(payload.get("pressure"), default=pressure_default)
    evidence = normalize_text_list(payload.get("evidence"), limit=5)
    summary = normalize_text_value(
        payload.get("summary"),
        fallback=f"{label or organ_id} is {status}.",
        limit=260,
    )
    next_step = normalize_text_value(payload.get("next_step"), fallback="", limit=260)
    return {
        "id": organ_id or normalize_text_value(label, fallback="organ", limit=120).lower().replace(" ", "_"),
        "label": label or organ_id,
        "status": status,
        "operational_status": operational_status,
        "maturity_status": maturity_status,
        "salience": salience,
        "pressure": pressure,
        "role": role,
        "human_quality": normalize_text_value(payload.get("human_quality"), fallback="", limit=260),
        "summary": summary,
        "evidence": evidence,
        "next_step": next_step,
        "authority_boundary": normalize_text_value(payload.get("authority_boundary"), fallback="", limit=320),
        "cik_zone": normalize_text_value(payload.get("cik_zone"), fallback=eve_governance.CIK_UNKNOWN, limit=40),
        "source": normalize_text_value(payload.get("source"), fallback="organ_assimilation", limit=120),
        "last_updated": normalize_active_mind_thread_timestamp(payload.get("last_updated") or payload.get("updated_at")),
    }


def organ_signal_sort_key(signal: Dict[str, object]) -> tuple:
    status = normalize_text_value(signal.get("status"), fallback="unknown", limit=60)
    operational_status = normalize_text_value(signal.get("operational_status"), fallback="", limit=60)
    status_rank = {
        "degraded": 7,
        "blocked": 7,
        "not_configured": 5,
        "limited": 4,
        "unknown": 3,
        "lab_ready": 2,
        "working": 2,
        "ready": 1,
        "healthy": 1,
    }
    return (
        int(signal.get("pressure") or 0),
        int(signal.get("salience") or 0),
        status_rank.get(operational_status, status_rank.get(status, 3)),
        normalize_text_value(signal.get("label"), fallback="", limit=120).lower(),
    )


def normalize_organ_signals(payload: object, limit: int = 8) -> List[Dict[str, object]]:
    if not isinstance(payload, list):
        return []
    by_id: Dict[str, Dict[str, object]] = {}
    for item in payload:
        signal = normalize_organ_signal(item)
        if not signal:
            continue
        by_id[str(signal["id"])] = signal
    return sorted(by_id.values(), key=organ_signal_sort_key, reverse=True)[: max(0, int(limit or 8))]


def active_mind_thread_key(thread: Dict[str, object]) -> str:
    kind = normalize_text_value(thread.get("kind"), fallback="concern", limit=40).lower()
    return f"{kind}::{active_mind_thread_dedup_token(thread)}"


def active_mind_label_token(value: object, fallback: str) -> str:
    token = normalize_text_value(value, fallback=fallback, limit=40).replace("_", " ").strip().lower()
    return token or fallback


def normalize_active_mind_audit_event(payload: object) -> Optional[Dict[str, str]]:
    if not isinstance(payload, dict):
        return None
    event_kind = normalize_text_value(payload.get("event_kind"), fallback="", limit=20).lower()
    if event_kind not in {"appeared", "updated", "resolved"}:
        return None
    timestamp = normalize_text_value(payload.get("timestamp"), fallback=utc_now(), limit=40)
    source = normalize_text_value(payload.get("source"), fallback="unknown", limit=80)
    title = normalize_text_value(payload.get("title"), fallback="", limit=140)
    detail = normalize_text_value(payload.get("detail"), fallback="", limit=220)
    thread_kind = active_mind_label_token(payload.get("thread_kind"), "concern")
    thread_status = active_mind_label_token(payload.get("thread_status"), "active")
    summary = normalize_text_value(
        payload.get("summary"),
        fallback=f"{thread_status.title()} {thread_kind} thread {event_kind}: {title or detail or 'Unnamed thread'}.",
        limit=220,
    )
    if not title and not detail:
        return None
    return {
        "id": normalize_text_value(payload.get("id"), fallback=str(uuid.uuid4()), limit=80),
        "timestamp": timestamp,
        "source": source,
        "event_kind": event_kind,
        "title": title or detail,
        "detail": detail or title,
        "thread_kind": thread_kind,
        "thread_status": thread_status,
        "summary": summary,
    }


def build_active_mind_audit_events(
    previous_mind: Dict[str, object],
    current_mind: Dict[str, object],
) -> List[Dict[str, str]]:
    previous = normalize_active_mind(previous_mind)
    current = normalize_active_mind(current_mind)
    timestamp = normalize_text_value(current.get("updated_at"), fallback=utc_now(), limit=40)
    source = normalize_text_value(current.get("source"), fallback="unknown", limit=80)
    previous_map = {
        active_mind_thread_key(item): item for item in previous.get("live_threads", []) if isinstance(item, dict)
    }
    current_map = {
        active_mind_thread_key(item): item for item in current.get("live_threads", []) if isinstance(item, dict)
    }
    events: List[Dict[str, str]] = []

    for key, thread in current_map.items():
        prior = previous_map.get(key)
        event_kind = ""
        summary = ""
        if prior is None:
            event_kind = "appeared"
            summary = (
                f"{active_mind_label_token(thread.get('thread_status') or thread.get('status'), 'active').title()} "
                f"{active_mind_label_token(thread.get('thread_kind') or thread.get('kind'), 'concern')} thread appeared: "
                f"{thread.get('title') or thread.get('detail')}. {active_mind_thread_scheduler_summary(thread)}."
            )
        elif active_mind_thread_change_notes(prior, thread):
            event_kind = "updated"
            summary = (
                f"{active_mind_label_token(thread.get('thread_status') or thread.get('status'), 'active').title()} "
                f"{active_mind_label_token(thread.get('thread_kind') or thread.get('kind'), 'concern')} thread shifted: "
                f"{thread.get('title') or thread.get('detail')}. "
                + "; ".join(active_mind_thread_change_notes(prior, thread))
                + "."
            )
        if not event_kind:
            continue
        events.append(
            normalize_active_mind_audit_event(
                {
                    "timestamp": timestamp,
                    "source": source,
                    "event_kind": event_kind,
                    "title": thread.get("title"),
                    "detail": thread.get("detail"),
                    "thread_kind": thread.get("kind"),
                    "thread_status": thread.get("status"),
                    "summary": summary,
                }
            )
            or {}
        )

    for key, thread in previous_map.items():
        if key in current_map:
            continue
        events.append(
            normalize_active_mind_audit_event(
                {
                    "timestamp": timestamp,
                    "source": source,
                    "event_kind": "resolved",
                    "title": thread.get("title"),
                    "detail": thread.get("detail"),
                    "thread_kind": thread.get("kind"),
                    "thread_status": thread.get("status"),
                    "summary": (
                        f"{active_mind_label_token(thread.get('status'), 'active').title()} "
                        f"{active_mind_label_token(thread.get('kind'), 'concern')} thread resolved: "
                        f"{thread.get('title') or thread.get('detail')}. "
                        f"{active_mind_thread_scheduler_summary(thread)}."
                    ),
                }
            )
            or {}
        )

    return [item for item in events if item]


def normalize_active_mind(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    normalized = default_active_mind()
    normalized["updated_at"] = payload.get("updated_at")
    normalized["source"] = normalize_text_value(payload.get("source"), fallback="", limit=80)
    normalized["model"] = normalize_text_value(payload.get("model"), fallback="", limit=120)
    normalized["summary"] = normalize_text_value(payload.get("summary"))
    normalized["current_focus"] = normalize_text_value(payload.get("current_focus"))
    normalized["current_focus_since"] = payload.get("current_focus_since")
    normalized["live_concerns"] = normalize_text_list(payload.get("live_concerns"), limit=4)
    normalized["active_threads"] = normalize_text_list(payload.get("active_threads"), limit=4)
    normalized["live_threads"] = normalize_active_mind_threads(payload.get("live_threads"), limit=6)
    normalized["organ_signals"] = normalize_organ_signals(payload.get("organ_signals"), limit=8)
    normalized["relationship_pull"] = normalize_text_list(payload.get("relationship_pull"), limit=4)
    normalized["grounding_notes"] = normalize_text_list(payload.get("grounding_notes"), limit=4)
    normalized["lanes"] = normalize_active_mind_lanes(payload.get("lanes"))
    normalized["next_step"] = normalize_text_value(payload.get("next_step"))
    normalized["next_step_provenance"] = normalize_active_mind_next_step_provenance(
        payload.get("next_step_provenance")
    )
    if (
        normalized["next_step_provenance"].get("step_text")
        != normalized["next_step"]
    ):
        normalized["next_step_provenance"] = normalize_active_mind_next_step_provenance({})
    if focus_indicates_background_context_notice(normalized["current_focus"]):
        replacement_focus = normalized["next_step"]
        normalized["current_focus"] = (
            replacement_focus
            if replacement_focus and not focus_indicates_background_context_notice(replacement_focus)
            else "Re-anchor on the current user or work signal instead of daemon background notices."
        )
    if focus_indicates_background_context_notice(normalized["summary"]):
        normalized["summary"] = normalize_text_value(
            f"{normalized['current_focus']} Next check: {normalized['next_step']}",
            fallback=DEFAULT_ACTIVE_MIND["summary"],
            limit=220,
        )
    for field in ["live_concerns", "active_threads", "relationship_pull", "grounding_notes"]:
        normalized[field] = [
            item for item in normalized[field] if not focus_indicates_background_context_notice(item)
        ][:4]
    normalized["live_threads"] = [
        item
        for item in normalized["live_threads"]
        if not focus_indicates_background_context_notice(item.get("title"))
        and not focus_indicates_background_context_notice(item.get("detail"))
    ][:6]
    normalized["lanes"] = {
        field: (
            value
            if not focus_indicates_background_context_notice(value)
            else DEFAULT_ACTIVE_MIND["lanes"].get(field, "")
        )
        for field, value in normalized["lanes"].items()
    }
    return normalized


def append_active_mind_control_event(
    event_type: str,
    *,
    source: str,
    reason: str,
    active_mind: Optional[Dict[str, object]] = None,
    payload: Optional[Dict[str, object]] = None,
    model_used: str = "deterministic",
    human_visible: bool = False,
    confidence: float = 1.0,
    risk_level: int = 0,
) -> Dict[str, object]:
    normalized_mind = normalize_active_mind(active_mind or {})
    event_payload: Dict[str, object] = {
        "event_name": event_type,
        "reason": normalize_text_value(reason, fallback="active mind control gate", limit=220),
        "active_mind_updated_at": normalized_mind.get("updated_at") or "",
        "active_mind_source": normalized_mind.get("source") or "",
        "current_focus": normalized_mind.get("current_focus") or "",
    }
    if payload:
        event_payload.update(payload)
    event = eve_governance.event_envelope(
        event_type,
        source=source,
        actor="eve",
        payload=event_payload,
        model_used=model_used,
        risk_level=risk_level,
        human_visible=human_visible,
        confidence=confidence,
        provenance=["active_mind", "control_gate"],
        cik_zone=eve_governance.CIK_IDENTITY,
        stream="active_mind",
    )
    return append_eve_event_ledger_event(event)


def active_mind_timestamp_newer_than(value: object, reference: datetime) -> bool:
    parsed = parse_iso_datetime(value)
    if parsed is None:
        return False
    return parsed > reference


def active_mind_has_new_inbound_signal(messages: List[Dict[str, object]], reference: datetime) -> bool:
    for message in messages:
        if not message_is_inbound_for_eve(message):
            continue
        timestamp = message.get("timestamp") or message.get("created_at") or message.get("updated_at")
        if timestamp and active_mind_timestamp_newer_than(timestamp, reference):
            return True
    return False


def active_mind_has_pending_thread_signal(threads: List[Dict[str, object]], reference: datetime) -> bool:
    for thread in threads:
        if not isinstance(thread, dict):
            continue
        inbound_pending = int(thread.get("inbound_pending_count") or 0)
        response_due = int(thread.get("response_due_count") or 0)
        latest_sender = normalize_text_value(thread.get("latest_sender"), fallback="", limit=40).lower()
        latest_timestamp = thread.get("latest_timestamp")
        if inbound_pending > 0 or response_due > 0:
            return True
        if latest_sender == "user" and active_mind_timestamp_newer_than(latest_timestamp, reference):
            return True
    return False


def active_mind_novelty_gate(
    config: Dict[str, object],
    *,
    source: str,
    previous_mind: Dict[str, object],
    human_context: Dict[str, object],
    autonomy_state: Dict[str, object],
    state: Dict[str, object],
    threads: List[Dict[str, object]],
    messages: List[Dict[str, object]],
) -> Dict[str, object]:
    if not str(source or "").startswith(("daemon", "autonomy_free_run")):
        return {"noop": False, "reason": "manual or interactive mind tick"}
    if config.get("active_mind_noop_gate_enabled") is False:
        return {"noop": False, "reason": "noop gate disabled"}
    previous = normalize_active_mind(previous_mind)
    previous_updated = parse_iso_datetime(previous.get("updated_at"))
    if previous_updated is None:
        return {"noop": False, "reason": "active mind has no prior timestamp"}
    max_age_seconds = 300
    try:
        max_age_seconds = max(30, min(int(config.get("active_mind_noop_max_age_seconds") or 300), 3600))
    except (TypeError, ValueError):
        max_age_seconds = 300
    age_seconds = (utc_now_datetime() - previous_updated).total_seconds()
    if age_seconds > max_age_seconds:
        return {"noop": False, "reason": "active mind is old enough to refresh", "age_seconds": int(age_seconds)}
    if active_mind_has_new_inbound_signal(messages, previous_updated):
        return {"noop": False, "reason": "new inbound message evidence"}
    if active_mind_has_pending_thread_signal(threads, previous_updated):
        return {"noop": False, "reason": "thread has pending user signal"}
    for label, payload in (
        ("human_context", human_context),
        ("autonomy_state", autonomy_state),
        ("runtime_state", state),
    ):
        if isinstance(payload, dict) and active_mind_timestamp_newer_than(payload.get("updated_at"), previous_updated):
            return {"noop": False, "reason": f"{label} changed"}
    return {
        "noop": True,
        "reason": "no new inbound, thread, or durable-state evidence since the last fresh active mind",
        "age_seconds": int(age_seconds),
        "max_age_seconds": max_age_seconds,
    }


SELF_CHECK_DOWNGRADE_TERMS = (
    "manufacture motion",
    "manufactured motion",
    "false momentum",
    "performative continuity",
    "theatrical",
    "unsupported internal state",
    "unsupported claim",
    "no fresh evidence",
    "no new evidence",
    "stale evidence",
)


def active_mind_self_check_downgrade_reason(packet: Optional[Dict[str, object]]) -> str:
    if not isinstance(packet, dict):
        return ""
    confidence = normalize_text_value(packet.get("confidence"), fallback="medium", limit=20).lower()
    text_parts: List[str] = [
        normalize_text_value(packet.get("lane"), fallback="", limit=240),
        normalize_text_value(packet.get("summary"), fallback="", limit=240),
        normalize_text_value(packet.get("next_step"), fallback="", limit=240),
        *normalize_text_list(packet.get("live_concerns"), limit=4),
        *normalize_text_list(packet.get("active_threads"), limit=4),
        *normalize_text_list(packet.get("grounding_notes"), limit=4),
    ]
    for thread in packet.get("live_threads") or []:
        if isinstance(thread, dict):
            text_parts.append(normalize_text_value(thread.get("title"), fallback="", limit=160))
            text_parts.append(normalize_text_value(thread.get("detail"), fallback="", limit=220))
            text_parts.append(normalize_text_value(thread.get("next_step"), fallback="", limit=180))
    blob = " ".join(part for part in text_parts if part).lower()
    if confidence == "low":
        return "self_check_low_confidence"
    if any(term in blob for term in SELF_CHECK_DOWNGRADE_TERMS):
        return "self_check_flagged_manufactured_motion"
    return ""


def apply_active_mind_self_check_gate(
    mind: Dict[str, object],
    self_check_packet: Optional[Dict[str, object]],
    *,
    source: str,
) -> Dict[str, object]:
    reason = active_mind_self_check_downgrade_reason(self_check_packet)
    if not reason:
        return mind
    current = normalize_active_mind(mind)
    control_note = "Self-check downgraded this active mind; wait for fresh evidence before claiming movement."
    current["summary"] = "Active mind downgraded by self-check; hold steady until fresh evidence appears."
    current["current_focus"] = "Hold steady; answer direct user turns without importing routine telemetry."
    current["next_step"] = "Wait for fresh evidence, a user request, or a verified system change before creating a new internal thread."
    current["next_step_provenance"] = normalize_active_mind_next_step_provenance({})
    current["live_concerns"] = unique_compact(
        [*normalize_text_list(current.get("live_concerns"), limit=4), control_note],
        limit=4,
    )
    current["grounding_notes"] = unique_compact(
        [*normalize_text_list(current.get("grounding_notes"), limit=4), control_note],
        limit=4,
    )
    lanes = normalize_active_mind_lanes(current.get("lanes"))
    lanes["self_check"] = control_note
    current["lanes"] = lanes
    current["live_threads"] = normalize_active_mind_threads(
        [
            *[item for item in current.get("live_threads", []) if isinstance(item, dict)],
            {
                "title": "Self-check downgraded active mind",
                "detail": control_note,
                "kind": "self_check",
                "status": "monitoring",
                "salience": 84,
                "pressure": 76,
                "last_updated": utc_now(),
                "evidence": [reason],
                "next_step": current["next_step"],
                "source_id": "self_check:downgraded_active_mind",
            },
        ],
        limit=6,
    )
    append_active_mind_control_event(
        "MindDowngradedEvent",
        source=source,
        reason=reason,
        active_mind=current,
        payload={"self_check_confidence": (self_check_packet or {}).get("confidence", ""), "control_note": control_note},
        model_used=normalize_text_value(current.get("model"), fallback="deterministic", limit=120),
    )
    return current


def active_mind_has_downgrade_marker(active_mind: Dict[str, object]) -> bool:
    mind = normalize_active_mind(active_mind)
    text_parts = [
        mind.get("summary"),
        mind.get("current_focus"),
        mind.get("next_step"),
        *mind.get("live_concerns", []),
        *mind.get("grounding_notes", []),
        mind.get("lanes", {}).get("self_check", ""),
    ]
    blob = " ".join(str(part or "") for part in text_parts).lower()
    return "self-check downgraded" in blob or "active mind downgraded" in blob


def proactive_outbound_deferral_reasons(
    active_mind: Dict[str, object],
    threads: List[Dict[str, object]],
    messages: List[Dict[str, object]],
) -> List[str]:
    reasons: List[str] = []
    if active_mind_has_downgrade_marker(active_mind):
        reasons.append("active_mind_downgraded")
    if any(int(thread.get("outbound_unread_count") or thread.get("unread_count") or 0) >= 2 for thread in threads if isinstance(thread, dict)):
        reasons.append("outbound_backlog")
    if any(int(thread.get("response_due_count") or 0) > 0 for thread in threads if isinstance(thread, dict)):
        reasons.append("user_response_due")
    if active_mind_has_new_inbound_signal(messages, parse_iso_datetime(active_mind.get("updated_at")) or utc_now_datetime()):
        reasons.append("new_inbound_before_proactive_output")
    return unique_compact(reasons, limit=5)


def merge_active_mind(previous: Dict[str, object], current: Dict[str, object]) -> Dict[str, object]:
    previous_normalized = normalize_active_mind(previous)
    current_normalized = normalize_active_mind(current)
    merged = normalize_active_mind(current_normalized)

    for field in ["live_concerns", "active_threads", "relationship_pull", "grounding_notes"]:
        combined = unique_compact([*current_normalized.get(field, []), *previous_normalized.get(field, [])], limit=8)
        if field in {"live_concerns", "active_threads"}:
            combined = [item for item in combined if focus_text_salience_score(item) >= -20]
        merged[field] = unique_compact(combined, limit=4)

    for field in ["summary", "current_focus", "next_step"]:
        if (
            current_normalized.get(field) == DEFAULT_ACTIVE_MIND[field]
            and previous_normalized.get(field) != DEFAULT_ACTIVE_MIND[field]
        ):
            merged[field] = previous_normalized[field]

    # Preserve source authority only when the exact next-step wording remains
    # unchanged.  Any model rewrite loses eligibility until a source substrate
    # emits a new typed contract.
    current_provenance = normalize_active_mind_next_step_provenance(
        current_normalized.get("next_step_provenance")
    )
    previous_provenance = normalize_active_mind_next_step_provenance(
        previous_normalized.get("next_step_provenance")
    )
    if current_provenance.get("goal_eligible"):
        merged["next_step_provenance"] = current_provenance
    elif (
        merged.get("next_step") == previous_normalized.get("next_step")
        and previous_provenance.get("goal_eligible")
    ):
        merged["next_step_provenance"] = previous_provenance
    else:
        merged["next_step_provenance"] = normalize_active_mind_next_step_provenance({})

    current_focus_text = " ".join(str(merged.get("current_focus") or "").split()).lower()
    previous_focus_text = " ".join(str(previous_normalized.get("current_focus") or "").split()).lower()
    if (
        current_focus_text
        and current_focus_text == previous_focus_text
        and not merged.get("current_focus_since")
        and previous_normalized.get("current_focus_since")
    ):
        merged["current_focus_since"] = previous_normalized.get("current_focus_since")

    merged_threads = normalize_active_mind_threads(current_normalized.get("live_threads", []), limit=6)
    merged["live_threads"] = merged_threads
    merged["organ_signals"] = normalize_organ_signals(
        [
            *current_normalized.get("organ_signals", []),
            *previous_normalized.get("organ_signals", []),
        ],
        limit=8,
    )

    merged_lanes = {}
    for field, default_value in DEFAULT_ACTIVE_MIND["lanes"].items():
        current_value = current_normalized["lanes"].get(field, "")
        previous_value = previous_normalized["lanes"].get(field, "")
        merged_lanes[field] = current_value or previous_value or default_value
    merged["lanes"] = merged_lanes

    return normalize_active_mind(merged)


def load_active_mind(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = ACTIVE_MIND_REPOSITORY.load(prefer_runtime=prefer_runtime)
    return normalize_active_mind(payload)


def read_active_mind_audit_log(
    limit: Optional[int] = None,
    since_days: Optional[int] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, str]]:
    path = resolve_store_read_path(ACTIVE_MIND_AUDIT_LOG_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_records(path)
    normalized = [
        item for item in (normalize_active_mind_audit_event(record) for record in records) if item is not None
    ]
    if since_days is not None:
        normalized = filter_records_by_days(normalized, "timestamp", since_days)
    if limit is not None:
        return normalized[-limit:]
    return normalized


def active_mind_focus_tenure_hours(current_focus: object, focus_since: object = None) -> Optional[float]:
    """How long the current focus has been held. Prefers the durable per-focus
    current_focus_since stamp (set in save_active_mind) so multi-hour tenures
    survive audit-log rotation; falls back to the audit trail when absent. Powers
    the decaying incumbency floor so a stale focus must re-earn its slot, and the
    'focus held N hours' self-knowledge note."""
    focus_text = " ".join(str(current_focus or "").split()).lower()
    if not focus_text:
        return None
    anchor: Optional[str] = None
    when = parse_iso_datetime(focus_since)
    if when is not None:
        try:
            return max(0.0, (utc_now_datetime() - when).total_seconds() / 3600.0)
        except Exception:
            pass
    focus_prefix = focus_text[:60]
    try:
        events = read_active_mind_audit_log(limit=200, prefer_runtime=True)
    except Exception:
        return None
    if not events:
        return None
    appeared_at: Optional[str] = None
    for event in events:
        summary = " ".join(str(event.get("summary") or "").split()).lower()
        if "focus thread appeared" in summary and focus_prefix in summary:
            appeared_at = event.get("timestamp")
            break
    anchor = appeared_at or events[0].get("timestamp")
    when = parse_iso_datetime(anchor)
    if when is None:
        return None
    try:
        return max(0.0, (utc_now_datetime() - when).total_seconds() / 3600.0)
    except Exception:
        return None


def append_active_mind_audit_events(events: List[Dict[str, str]], keep: int = 200) -> None:
    normalized = [item for item in (normalize_active_mind_audit_event(event) for event in events) if item is not None]
    if not normalized:
        return
    ensure_store()
    with store_lock(ACTIVE_MIND_AUDIT_LOG_PATH):
        records = read_jsonl_records(ACTIVE_MIND_AUDIT_LOG_PATH)
        records.extend(normalized)
        if len(records) > keep:
            records = records[-keep:]
        write_jsonl_records(ACTIVE_MIND_AUDIT_LOG_PATH, records)


def save_active_mind(mind: Dict[str, object]) -> None:
    previous = normalize_active_mind(ACTIVE_MIND_REPOSITORY.load())
    normalized = normalize_active_mind(mind)
    # Durable per-focus tenure stamp: set when the focus text changes, carried
    # forward unchanged while it holds — so tenure survives audit-log rotation
    # and the decaying-incumbency tiers (2h/12h/48h) are actually reachable.
    prev_focus = " ".join(str(previous.get("current_focus") or "").split()).lower()
    new_focus = " ".join(str(normalized.get("current_focus") or "").split()).lower()
    if new_focus and new_focus == prev_focus and previous.get("current_focus_since"):
        normalized["current_focus_since"] = previous.get("current_focus_since")
    elif new_focus:
        normalized["current_focus_since"] = normalized.get("current_focus_since") or normalized.get("updated_at") or utc_now()
    ACTIVE_MIND_REPOSITORY.save(normalized)
    append_active_mind_audit_events(build_active_mind_audit_events(previous, normalized))


def thread_status_label(thread: Dict[str, object]) -> str:
    status = str(thread.get("status") or "").strip().lower()
    if status == "awaiting_user":
        return "waiting"
    if status == "open":
        return "watching"
    return "active"


def thread_summary_outbound_unread_count(thread: Dict[str, object]) -> int:
    if thread.get("all_background_context"):
        return 0
    return max(0, int(thread.get("outbound_unread_count") if thread.get("outbound_unread_count") is not None else thread.get("unread_count") or 0))


def thread_summary_response_due_count(thread: Dict[str, object]) -> int:
    explicit_count = max(0, int(thread.get("response_due_count") or 0))
    if explicit_count:
        return explicit_count
    latest_sender = normalize_text_value(thread.get("latest_sender"), fallback="", limit=40).lower()
    latest_time = parse_iso_datetime(thread.get("latest_timestamp"))
    fresh = latest_time is None or datetime.now(timezone.utc) - latest_time < timedelta(seconds=RESPONSE_DUE_FRESH_SECONDS)
    if latest_sender == "user" and str(thread.get("status") or "").strip().lower() == "active" and fresh:
        return 1
    return 0


def thread_summary_synthetic_continuity_count(thread: Dict[str, object]) -> int:
    return max(0, int(thread.get("synthetic_continuity_count") or 0))


def build_active_mind_live_threads(
    mind: Dict[str, object],
    *,
    threads: Optional[List[Dict[str, object]]] = None,
    messages: Optional[List[Dict[str, object]]] = None,
) -> List[Dict[str, object]]:
    normalized = normalize_active_mind(mind)
    derived: List[Dict[str, object]] = []
    seen = set()

    def append_thread(
        kind: str,
        status: str,
        title: object,
        detail: object,
        *,
        salience: Optional[int] = None,
        pressure: Optional[int] = None,
        last_updated: object = "",
        evidence: Optional[List[str]] = None,
        next_step: object = "",
        source_id: object = "",
        goal_provenance: Optional[Dict[str, object]] = None,
    ) -> None:
        thread_title = normalize_text_value(title, fallback="", limit=140)
        thread_detail = normalize_text_value(detail, fallback=thread_title, limit=220)
        derived_salience = clamp_thread_weight(
            salience,
            default=max(
                0,
                focus_text_salience_score(thread_title),
                focus_text_salience_score(thread_detail),
            ),
        )
        thread = normalize_active_mind_thread(
            {
                "kind": kind,
                "status": status,
                "title": thread_title,
                "detail": thread_detail,
                "salience": derived_salience,
                "pressure": pressure if pressure is not None else default_active_mind_thread_pressure(derived_salience, status),
                "last_updated": last_updated or normalized.get("updated_at"),
                "evidence": evidence or [],
                "next_step": next_step,
                "source_id": source_id,
                "goal_provenance": goal_provenance or {},
            }
        )
        if not thread:
            return
        key = (thread["kind"], thread.get("source_id") or thread["title"].lower())
        if key in seen:
            return
        seen.add(key)
        derived.append(thread)

    current_focus = normalized.get("current_focus")
    summary = normalized.get("summary")
    next_step = normalized.get("next_step")
    focus_detail = summary
    if next_step and next_step not in focus_detail:
        focus_detail = normalize_text_value(f"{summary} Next: {next_step}", fallback=summary, limit=220)
    # Attention schema: incumbency decays. A fresh focus deserves stability; a
    # focus held for days must re-earn its slot against live competition. The
    # tenure also becomes visible self-knowledge ("focus held N hours") instead
    # of an invisible floor. Tenure anchors on the durable current_focus_since
    # stamp from the previously-saved mind (set in save_active_mind) when the
    # focus still matches, so it survives audit-log rotation.
    focus_since = normalized.get("current_focus_since")
    if not focus_since:
        try:
            persisted = normalize_active_mind(load_active_mind(prefer_runtime=True))
            if " ".join(str(persisted.get("current_focus") or "").split()).lower() == " ".join(str(current_focus or "").split()).lower():
                focus_since = persisted.get("current_focus_since")
        except Exception:
            focus_since = None
    focus_tenure_hours = active_mind_focus_tenure_hours(current_focus, focus_since)
    if focus_tenure_hours is None or focus_tenure_hours < 2:
        incumbency_floor = 88
    elif focus_tenure_hours < 12:
        incumbency_floor = 76
    elif focus_tenure_hours < 48:
        incumbency_floor = 64
    else:
        incumbency_floor = 48
    focus_raw_salience = max(
        focus_text_salience_score(current_focus),
        focus_text_salience_score(focus_detail),
        incumbency_floor,
    )
    focus_salience = clamp_thread_weight(
        scale_scheduler_signal(focus_raw_salience, low=20, high=170, minimum=54, maximum=96),
        default=76,
    )
    focus_recency = scheduler_recency_adjustment(normalized.get("updated_at"), missing_penalty=0)
    focus_evidence = [
        normalized.get("summary"),
        *(normalized.get("live_concerns", [])[:2] if isinstance(normalized.get("live_concerns"), list) else []),
    ]
    if focus_tenure_hours is not None and focus_tenure_hours >= 12:
        focus_evidence.insert(0, f"Attention note: this focus has been held for {focus_tenure_hours:.0f} hours.")
    focus_stale_self_echo = focus_is_stale_carried_self_echo(
        current_focus,
        messages,
        focus_since=focus_since,
    )
    focus_background_context_echo = focus_text_matches_background_context(
        current_focus,
        messages=messages or [],
        threads=threads or [],
    )
    focus_self_authored_output = focus_text_matches_self_authored_output(
        current_focus,
        messages=messages or [],
        threads=threads or [],
    )
    if not focus_stale_self_echo and not focus_background_context_echo and not focus_self_authored_output:
        append_thread(
            "focus",
            "active",
            current_focus,
            focus_detail,
            salience=focus_salience,
            pressure=clamp_thread_weight(focus_salience + (8 if next_step else 0) + focus_recency, default=72),
            last_updated=normalized.get("updated_at"),
            evidence=normalize_text_list(focus_evidence, limit=3),
            next_step=next_step,
            source_id="focus",
        )

    for thread in threads or []:
        label = thread_focus_label(thread)
        if not label or focus_text_salience_score(label) < -20:
            continue
        latest_preview = normalize_text_value(thread.get("latest_preview"), fallback="", limit=180)
        status = thread_status_label(thread)
        response_due_count = thread_summary_response_due_count(thread)
        outbound_unread_count = thread_summary_outbound_unread_count(thread)
        synthetic_continuity_count = thread_summary_synthetic_continuity_count(thread)
        latest_sender = str(thread.get("latest_sender") or "").strip().lower()
        self_authored_wait = latest_sender == "eve" and not response_due_count
        if self_authored_wait:
            # Preserve the fact that Eve opened or replied in a conversation,
            # but never feed the generated wording back as a fresh percept.
            label = (
                "Awaiting user on an Eve-initiated conversation"
                if status == "waiting" or outbound_unread_count
                else "Conversation awaiting a new user signal"
            )
            latest_preview = ""
        if response_due_count:
            status = "active"
        detail_parts = []
        if latest_preview and latest_preview.lower() != label.lower():
            detail_parts.append(f"Latest turn: {latest_preview}")
        if response_due_count:
            detail_parts.append("This conversation has a fresh inbound signal for Eve.")
        elif status == "waiting":
            detail_parts.append("Eve has outbound message(s) the user may not have seen.")
        elif status == "active":
            detail_parts.append("This conversation is actively in motion.")
        else:
            detail_parts.append("Keep this thread in peripheral view.")
        message_count = int(thread.get("message_count") or 0)
        latest_timestamp = thread.get("latest_timestamp")
        recency_adjustment = scheduler_recency_adjustment(latest_timestamp)
        raw_salience = thread_focus_salience_score(thread)
        salience = clamp_thread_weight(
            scale_scheduler_signal(raw_salience, low=20, high=240, minimum=18, maximum=90) + recency_adjustment,
            default=58,
        )
        pressure = clamp_thread_weight(
            salience
            + (18 if response_due_count else 12 if status == "waiting" else 10 if status == "active" else 4)
            + min(response_due_count, 4) * 10
            + min(outbound_unread_count, 2) * 5
            + (8 if latest_sender == "user" else 0)
            + recency_adjustment,
            default=62,
        )
        append_thread(
            "conversation",
            status,
            label,
            " ".join(detail_parts) or label,
            salience=salience,
            pressure=pressure,
            last_updated=latest_timestamp,
            evidence=normalize_text_list(
                [
                    latest_preview if latest_preview.lower() != label.lower() else "",
                    (
                        f"{response_due_count} response-due inbound signal{'s' if response_due_count != 1 else ''}"
                        if response_due_count
                        else ""
                    ),
                    (
                        f"{outbound_unread_count} outbound unseen message{'s' if outbound_unread_count != 1 else ''}"
                        if outbound_unread_count and not response_due_count
                        else ""
                    ),
                    (
                        f"{synthetic_continuity_count} synthetic continuity message{'s' if synthetic_continuity_count != 1 else ''}"
                        if synthetic_continuity_count and not response_due_count
                        else ""
                    ),
                    f"{message_count} message{'s' if message_count != 1 else ''} in this thread" if message_count else "",
                ],
                limit=3,
            ),
            next_step=(
                "Answer the user's latest signal before adding more continuity."
                if response_due_count
                else "Wait for the user's next real signal before forcing a move."
                if status == "waiting"
                else "Keep the live exchange coherent while the thread is still moving."
                if status == "active"
                else "Let this stay peripheral unless it starts exerting pressure again."
            ),
            source_id=thread.get("thread_id") or label,
        )

    for concern in normalized.get("live_concerns", []):
        if concern == current_focus:
            continue
        concern_salience = clamp_thread_weight(
            scale_scheduler_signal(focus_text_salience_score(concern), low=10, high=170, minimum=20, maximum=78),
            default=56,
        )
        append_thread(
            "concern",
            "watching",
            concern,
            "Keep this concern live without letting it take over the whole mind.",
            salience=concern_salience,
            pressure=clamp_thread_weight(concern_salience + 8, default=54),
            last_updated=normalized.get("updated_at"),
            evidence=normalize_text_list(
                [normalized.get("summary"), normalized.get("current_focus")],
                limit=3,
            ),
            next_step="Keep this concern in view and see whether fresh evidence increases its pressure.",
            source_id=concern,
        )

    for signal in openclaw_body_signal_threads(prefer_runtime=running_from_runtime_bundle(), limit=2):
        append_thread(
            str(signal.get("kind") or "concern"),
            str(signal.get("status") or "monitoring"),
            signal.get("title"),
            signal.get("detail"),
            salience=int(signal.get("salience") or 0),
            pressure=int(signal.get("pressure") or 0),
            last_updated=signal.get("last_updated"),
            evidence=signal.get("evidence") if isinstance(signal.get("evidence"), list) else [],
            next_step=signal.get("next_step"),
            source_id=signal.get("source_id"),
        )

    for signal in normalized.get("organ_signals", []):
        status = normalize_text_value(signal.get("status"), fallback="unknown", limit=60)
        pressure = int(signal.get("pressure") or 0)
        if status not in {"blocked", "degraded"} and pressure < 70:
            continue
        append_thread(
            "organ",
            "monitoring" if status not in {"blocked", "degraded"} else "active",
            f"{signal.get('label')} organ signal",
            signal.get("summary") or signal.get("role"),
            salience=int(signal.get("salience") or 0),
            pressure=pressure,
            last_updated=signal.get("last_updated") or normalized.get("updated_at"),
            evidence=signal.get("evidence") if isinstance(signal.get("evidence"), list) else [],
            next_step=signal.get("next_step"),
            source_id=f"organ:{signal.get('id')}",
        )

    for item in normalized.get("relationship_pull", []):
        relationship_salience = clamp_thread_weight(
            scale_scheduler_signal(focus_text_salience_score(item), low=10, high=170, minimum=24, maximum=82),
            default=52,
        )
        append_thread(
            "relationship",
            "relating",
            item,
            "Let relationship reality shape tone and sequencing.",
            salience=relationship_salience,
            pressure=clamp_thread_weight(relationship_salience + 10, default=58),
            last_updated=normalized.get("updated_at"),
            evidence=normalize_text_list(
                [*(normalized.get("active_threads", [])[:2] if isinstance(normalized.get("active_threads"), list) else [])],
                limit=3,
            ),
            next_step="Let this shape pacing and tone before making a stronger claim.",
            source_id="relationship",
        )
        break

    for item in normalized.get("grounding_notes", []):
        grounding_salience = clamp_thread_weight(
            scale_scheduler_signal(focus_text_salience_score(item), low=0, high=150, minimum=18, maximum=68),
            default=48,
        )
        append_thread(
            "grounding",
            "grounding",
            item,
            "Use this as a stabilizer before making stronger claims.",
            salience=grounding_salience,
            pressure=clamp_thread_weight(grounding_salience + 6, default=46),
            last_updated=normalized.get("updated_at"),
            evidence=normalize_text_list([normalized.get("summary")], limit=2),
            next_step="Use this as a check before escalating language or certainty.",
            source_id="grounding",
        )
        break

    self_check = normalized.get("lanes", {}).get("self_check", "")
    if self_check:
        self_check_salience = clamp_thread_weight(
            scale_scheduler_signal(focus_text_salience_score(self_check), low=0, high=160, minimum=22, maximum=76),
            default=50,
        )
        append_thread(
            "self_check",
            "monitoring",
            self_check,
            "Watch for this failure mode while the rest of the mind stays active.",
            salience=self_check_salience,
            pressure=clamp_thread_weight(self_check_salience + 12, default=56),
            last_updated=normalized.get("updated_at"),
            evidence=normalize_text_list(
                [normalized.get("current_focus"), *(normalized.get("live_concerns", [])[:1] if isinstance(normalized.get("live_concerns"), list) else [])],
                limit=3,
            ),
            next_step="Keep this check in the background while deciding what deserves attention.",
            source_id="self_check",
        )

    if next_step:
        next_step_salience = clamp_thread_weight(
            scale_scheduler_signal(focus_text_salience_score(next_step), low=10, high=165, minimum=28, maximum=80),
            default=60,
        )
        append_thread(
            "next_step",
            "queued",
            next_step,
            "This is the next move currently queued if the evidence still supports it.",
            salience=next_step_salience,
            pressure=clamp_thread_weight(next_step_salience + 10, default=64),
            last_updated=normalized.get("updated_at"),
            evidence=normalize_text_list([normalized.get("current_focus"), normalized.get("summary")], limit=3),
            next_step=next_step,
            source_id="next_step",
            goal_provenance=normalized.get("next_step_provenance")
            if isinstance(normalized.get("next_step_provenance"), dict)
            else {},
        )

    carried_threads = [
        item
        for item in normalized.get("live_threads", [])
        if isinstance(item, dict) and not active_mind_thread_stale_for_reference(item, normalized.get("updated_at"))
    ]
    combined = normalize_active_mind_threads(
        [
            *derived,
            *carried_threads,
        ],
        limit=6,
    )
    return combined


def ensure_active_mind_live_threads(
    mind: Dict[str, object],
    *,
    threads: Optional[List[Dict[str, object]]] = None,
    messages: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    normalized = normalize_active_mind(mind)
    normalized["live_threads"] = build_active_mind_live_threads(
        normalized,
        threads=threads,
        messages=messages,
    )
    return normalize_active_mind(normalized)


def bootstrap_bundle_payload(
    primary_host: str = "",
    api_port: int = 8787,
    ollama_port: int = 11434,
) -> Dict[str, object]:
    config = load_config()
    host = normalize_text_value(primary_host, fallback="", limit=200)
    primary_eve_url = f"http://{host}:{int(api_port)}" if host else ""
    primary_ollama_url = f"http://{host}:{int(ollama_port)}" if host else ""
    return {
        "version": BOOTSTRAP_BUNDLE_VERSION,
        "generated_at": utc_now(),
        "source_platform": eve_platform.current_platform(),
        "primary_host": host,
        "primary_eve_url": primary_eve_url,
        "primary_ollama_url": primary_ollama_url,
        "config": {
            "model_backend": normalize_model_backend(config.get("model_backend")),
            "model": normalize_model_name(config.get("model")),
            "fast_model": normalize_model_name(config.get("fast_model")),
            "deep_model": normalize_model_name(config.get("deep_model")),
            "fast_model_backend": normalize_optional_model_backend(config.get("fast_model_backend")),
            "deep_model_backend": normalize_optional_model_backend(config.get("deep_model_backend")),
            "resident_models": [normalize_model_name(item) for item in config.get("resident_models") or [] if normalize_model_name(item)],
            "preferred_fast_model": normalize_model_name(config.get("preferred_fast_model")),
            "preferred_deep_model": normalize_model_name(config.get("preferred_deep_model")),
            "ollama_host": normalize_text_value(config.get("ollama_host"), fallback="", limit=200),
            "llama_cpp_host": normalize_text_value(config.get("llama_cpp_host"), fallback="", limit=200),
            "llama_cpp_hf_repo": normalize_text_value(config.get("llama_cpp_hf_repo"), fallback="", limit=200),
            "llama_cpp_model_alias": normalize_model_name(config.get("llama_cpp_model_alias")),
            "deep_llama_cpp_host": normalize_text_value(config.get("deep_llama_cpp_host"), fallback="", limit=200),
            "deep_llama_cpp_hf_repo": normalize_text_value(config.get("deep_llama_cpp_hf_repo"), fallback="", limit=200),
            "deep_llama_cpp_model_alias": normalize_model_name(config.get("deep_llama_cpp_model_alias")),
        },
        "models": configured_model_names(config),
        "runtime_identity": load_runtime_identity(),
        "human_context": load_human_context(),
        "active_mind": load_active_mind(),
    }


def apply_bootstrap_bundle(
    payload: Dict[str, object],
    *,
    use_primary_ollama: bool,
    pull_models: bool,
    ollama_pull_timeout_seconds: int = 7200,
) -> Dict[str, object]:
    ensure_store()
    config = load_config()
    imported_config = payload.get("config") if isinstance(payload.get("config"), dict) else {}
    for field in [
        "model_backend",
        "model",
        "fast_model",
        "deep_model",
        "fast_model_backend",
        "deep_model_backend",
        "preferred_fast_model",
        "preferred_deep_model",
        "ollama_host",
        "llama_cpp_host",
        "llama_cpp_hf_repo",
        "llama_cpp_model_alias",
        "deep_llama_cpp_host",
        "deep_llama_cpp_hf_repo",
        "deep_llama_cpp_model_alias",
    ]:
        if field in imported_config:
            if field == "model_backend":
                config[field] = normalize_model_backend(imported_config.get(field))
            elif field in {"fast_model_backend", "deep_model_backend"}:
                config[field] = normalize_optional_model_backend(imported_config.get(field))
            elif field in {"ollama_host", "llama_cpp_host", "llama_cpp_hf_repo", "deep_llama_cpp_host", "deep_llama_cpp_hf_repo"}:
                config[field] = normalize_text_value(imported_config.get(field), fallback="", limit=200)
            else:
                config[field] = normalize_model_name(imported_config.get(field))
    if "resident_models" in imported_config:
        config["resident_models"] = [
            normalize_model_name(item)
            for item in imported_config.get("resident_models") or []
            if normalize_model_name(item)
        ]

    if use_primary_ollama:
        remote_ollama = normalize_text_value(
            payload.get("primary_ollama_url"),
            fallback="",
            limit=200,
        ).rstrip("/")
        if remote_ollama:
            config["ollama_host"] = remote_ollama
    else:
        config["ollama_host"] = "http://127.0.0.1:11434"

    save_config(config, snapshot_source="bootstrap_bundle_import")

    runtime_identity = payload.get("runtime_identity") if isinstance(payload.get("runtime_identity"), dict) else {}
    human_context = payload.get("human_context") if isinstance(payload.get("human_context"), dict) else {}
    active_mind = payload.get("active_mind") if isinstance(payload.get("active_mind"), dict) else {}
    if runtime_identity:
        save_runtime_identity(runtime_identity, snapshot_source="bootstrap_bundle_import")
    if human_context:
        save_human_context(human_context, snapshot_source="bootstrap_bundle_import")
    if active_mind:
        save_active_mind(active_mind)

    imported_models = configured_model_names(config)
    pulled_models: List[str] = []
    if pull_models:
        for model_name in imported_models:
            result = run_local_command(["ollama", "pull", model_name], timeout=ollama_pull_timeout_seconds)
            if result.returncode != 0:
                message = result.stderr.strip() or result.stdout.strip() or f"Could not pull model `{model_name}`."
                raise SystemExit(message)
            pulled_models.append(model_name)

    append_entry(
        "bootstrap_bundle_imported",
        f"Imported bootstrap bundle with {len(imported_models)} configured model(s).",
        metadata={
            "source_platform": payload.get("source_platform") or "",
            "primary_host": payload.get("primary_host") or "",
            "primary_eve_url": payload.get("primary_eve_url") or "",
            "primary_ollama_url": payload.get("primary_ollama_url") or "",
            "use_primary_ollama": use_primary_ollama,
            "pull_models": pull_models,
            "models": imported_models,
        },
    )
    return {
        "models": imported_models,
        "pulled_models": pulled_models,
        "ollama_host": str(config.get("ollama_host") or ""),
        "primary_eve_url": str(payload.get("primary_eve_url") or ""),
        "primary_ollama_url": str(payload.get("primary_ollama_url") or ""),
    }


def fetch_bootstrap_bundle(
    *,
    host: str,
    api_port: int = 8787,
    ollama_port: int = 11434,
    timeout: int = 20,
) -> Dict[str, object]:
    normalized_host = normalize_text_value(host, fallback="", limit=200)
    if not normalized_host:
        raise SystemExit("A primary host is required.")
    url = f"http://{normalized_host}:{int(api_port)}/api/bootstrap?ollama_port={int(ollama_port)}"
    payload = request_json_url(url, timeout=timeout)
    if "data" in payload and isinstance(payload.get("data"), dict):
        return dict(payload["data"])
    if payload.get("ok") is False:
        raise SystemExit(f"Bootstrap request failed for {url}")
    if payload.get("version"):
        return payload
    raise SystemExit(f"Unexpected bootstrap payload from {url}")


def fetch_code_bundle(
    *,
    host: str,
    api_port: int = 8787,
    timeout: int = 60,
) -> bytes:
    normalized_host = normalize_text_value(host, fallback="", limit=200)
    if not normalized_host:
        raise SystemExit("A primary host is required.")
    url = f"http://{normalized_host}:{int(api_port)}/api/code-bundle"
    req = request.Request(url, headers={"Accept": "application/zip"})
    with request.urlopen(req, timeout=timeout) as resp:
        return resp.read()


def build_active_mind_lanes(
    current_focus: str,
    live_concerns: List[str],
    relationship_pull: List[str],
    grounding_notes: List[str],
    next_step: str,
    waiting_threads: int,
    self_checks: Optional[List[str]] = None,
) -> Dict[str, str]:
    observer = current_focus or (live_concerns[0] if live_concerns else "")
    planner = next_step
    relationship = (
        relationship_pull[0]
        if relationship_pull
        else "Stay oriented to the actual counterpart rather than the abstract topic."
    )
    grounding = (
        grounding_notes[0]
        if grounding_notes
        else "Use evidence from the live runtime before making identity claims."
    )
    caution_signals = unique_compact(self_checks or [], limit=4)
    if waiting_threads >= 3:
        self_check = "Do not create extra motion while several threads are already waiting."
    elif caution_signals:
        self_check = caution_signals[0]
    elif live_concerns:
        self_check = next((item for item in live_concerns if item != observer), live_concerns[0])
    else:
        self_check = "If evidence is thin, say that plainly instead of performing momentum."
    return normalize_active_mind_lanes(
        {
            "observer": observer,
            "planner": planner,
            "relationship": relationship,
            "grounding": grounding,
            "self_check": self_check,
        }
    )


def refresh_active_mind_from_conversation_event(
    source: str,
    model: str = "deterministic",
) -> Optional[Dict[str, object]]:
    try:
        previous_mind = load_active_mind()
        human_context = load_human_context()
        autonomy_state = load_autonomy_state()
        state = load_state()
        system_snapshot = load_system_snapshot()
        threads = read_thread_summaries(limit=6)
        messages = read_lived_messages(limit=6)
    except SystemExit:
        return None

    refreshed = bootstrap_active_mind(
        previous_mind=previous_mind,
        human_context=human_context,
        autonomy_state=autonomy_state,
        state=state,
        threads=threads,
        messages=messages,
        source=source,
        model=model,
        system_snapshot=system_snapshot,
    )
    latest_message = messages[-1] if messages else {}
    latest_sender = str(latest_message.get("sender") or "").strip().lower()
    latest_recipient = str(latest_message.get("recipient") or "").strip().lower()
    latest_body = normalize_text_value(latest_message.get("body"), fallback="", limit=180)
    latest_label = (
        latest_body
        if latest_body and not greeting_like_text(latest_body) and (len(latest_body) >= 20 or "?" in latest_body)
        else message_focus_label(latest_message)
    )
    if (
        source.startswith("message:")
        and latest_sender
        and latest_sender != "eve"
        and latest_recipient == "eve"
        and latest_label
        and focus_text_salience_score(latest_label) >= -20
    ):
        refreshed = normalize_active_mind(
            {
                **refreshed,
                "current_focus": latest_label,
                "summary": normalize_text_value(
                    f"{latest_label} Next check: {refreshed.get('next_step') or DEFAULT_ACTIVE_MIND['next_step']}",
                    fallback=DEFAULT_ACTIVE_MIND["summary"],
                    limit=220,
                ),
                "live_concerns": unique_compact([latest_label, *refreshed.get("live_concerns", [])], limit=4),
                "lanes": {
                    **normalize_active_mind_lanes(refreshed.get("lanes")),
                    "observer": latest_label,
                    "relationship": "Answer what the user just made newly active before widening the scope.",
                    "self_check": "Keep the reply tied to the user's latest words rather than older cached themes.",
                },
            }
        )
    refreshed = ensure_active_mind_live_threads(refreshed, threads=threads, messages=messages)
    save_active_mind(refreshed)
    state["current_focus"] = normalize_text_value(refreshed.get("current_focus"), fallback="", limit=160)
    state["thread_attention"] = threads
    state["active_thread_count"] = len([item for item in threads if item.get("status") != "archived"])
    state["last_active_mind_refresh_at"] = refreshed.get("updated_at") or utc_now()
    state["last_active_mind_refresh_source"] = source
    save_state(state)
    return refreshed


def active_mind_feedback_effect(kind: str, text: str, metadata: Optional[Dict[str, object]] = None) -> Dict[str, str]:
    payload = metadata if isinstance(metadata, dict) else {}
    label = normalize_text_value(text, fallback="", limit=220)

    def infrastructure_focus(problem: str, fallback: str) -> str:
        lowered = " ".join(str(problem or "").lower().split())
        if "hidden reasoning" in lowered or "thinking only" in lowered or "no final answer" in lowered:
            return "A self-awareness check is blocked because Ollama is returning reasoning without a final answer."
        if "timed out" in lowered or "timeout" in lowered:
            return "A self-awareness check is blocked because the model host timed out."
        if "could not reach ollama" in lowered or "remote end closed connection" in lowered:
            return "A self-awareness check is blocked because the local model host is not responding cleanly."
        return fallback

    if kind in {"daemon_error", "wake_error"}:
        focus = label or "A runtime failure interrupted continuity."
        return {
            "focus": focus,
            "concern": focus,
            "grounding_note": "Continuity is being interrupted by runtime failures.",
            "observer": focus,
            "planner": "Stabilize the runtime before trusting more self-improvement behavior.",
            "grounding": "Continuity claims need a working runtime underneath them.",
            "self_check": "Do not narrate growth while the loop is dropping work.",
        }
    if kind == "self_awareness_test_infrastructure_failed":
        problems = payload.get("problems") if isinstance(payload.get("problems"), list) else []
        primary_problem = normalize_text_value(problems[0] if problems else "", fallback="", limit=220)
        focus = infrastructure_focus(
            primary_problem or label,
            "A self-awareness check could not complete because the runtime stalled.",
        )
        return {
            "focus": focus,
            "concern": focus,
            "grounding_note": "Infrastructure trouble blocked the self-awareness loop.",
            "observer": focus,
            "planner": "Stabilize the model or runtime path, then rerun the check before drawing conclusions.",
            "grounding": "Do not confuse a stalled host with evidence of personal drift.",
            "self_check": "Keep infrastructure trouble separate from identity claims.",
        }
    if kind == "self_awareness_test_failed":
        focus = label or "Recent self-awareness check found drift."
        return {
            "focus": focus,
            "concern": focus,
            "grounding_note": "Recent self-awareness drift needs repair before expanding autonomy.",
            "observer": focus,
            "planner": "Repair the drift, then rerun the check before escalating capability claims.",
            "grounding": "Use cited evidence instead of identity language when drift appears.",
            "self_check": "Notice where narrative got ahead of continuity or relationship evidence.",
        }
    if kind == "self_awareness_test_passed":
        scores = payload.get("scores") if isinstance(payload.get("scores"), dict) else {}
        score_parts = []
        for field in ["groundedness", "continuity", "relationship_clarity"]:
            value = valid_score_value(scores.get(field))
            if value is not None:
                score_parts.append(f"{field} {value}/5")
        note = label or "Recent self-awareness check passed."
        if score_parts:
            note = normalize_text_value(f"{note} Scores: {', '.join(score_parts)}.", fallback=note, limit=220)
        return {
            "grounding_note": note,
            "grounding": note,
            "self_check": "Keep testing grounded claims instead of assuming one pass settles them.",
        }
    if kind == "evaluation_logged":
        summary = normalize_text_value(payload.get("summary"), fallback="", limit=180)
        scorecard = payload.get("scorecard") if isinstance(payload.get("scorecard"), dict) else {}
        weak_fields = payload.get("weak_fields") if isinstance(payload.get("weak_fields"), list) else []
        weak_labels = [
            SCORECARD_LABELS.get(str(field), str(field))
            for field in weak_fields
            if str(field) in SCORECARD_FIELDS
        ]
        if not weak_labels:
            weak_labels = [
                SCORECARD_LABELS[field]
                for field in weak_dimensions_from_scorecard(scorecard, threshold=3)
                if field in SCORECARD_FIELDS
            ]
        if weak_labels:
            concern = summary or f"Recent evaluation flagged weak spots in {', '.join(weak_labels)}."
            return {
                "focus": concern,
                "concern": concern,
                "grounding_note": "Recent feedback should shape the next reply more than habit.",
                "observer": concern,
                "planner": "Bias the next move toward the weak dimensions that were actually scored low.",
                "grounding": "Reviewer and eval evidence should outweigh preferred self-descriptions.",
                "self_check": "Do not protect an old style pattern if the scorecard says it is failing.",
            }
        note = summary or f"Recent evaluation held up: {format_scorecard(scorecard)}"
        note = normalize_text_value(note, fallback="Recent evaluation held up.", limit=220)
        return {
            "grounding_note": note,
            "grounding": note,
            "self_check": "Keep the working pattern, but keep checking whether it still matches the live situation.",
        }
    if kind == "outcome_logged":
        summary = normalize_text_value(payload.get("summary"), fallback="", limit=180)
        direction = str(payload.get("direction") or "").strip().lower()
        if direction in {"negative", "mixed"}:
            concern = summary or label or "A recent outcome suggests something is not landing cleanly."
            return {
                "focus": concern,
                "concern": concern,
                "grounding_note": "Recent consequences should outweigh preferred narratives.",
                "observer": concern,
                "planner": "Respond to the consequence directly before adding new ambition.",
                "grounding": "Consequences are stronger evidence than intent.",
                "self_check": "Do not rewrite the miss as progress until the effect is repaired.",
            }
        if direction == "positive":
            note = summary or "Something recently worked; keep that pattern in view."
            note = normalize_text_value(note, fallback="Something recently worked.", limit=220)
            return {
                "grounding_note": note,
                "grounding": note,
                "self_check": "Notice what actually helped instead of chasing novelty for its own sake.",
            }
        concern = summary or label
        if concern:
            return {
                "concern": concern,
                "observer": concern,
            }
    return {}


def refresh_active_mind_from_feedback_event(
    kind: str,
    text: str,
    metadata: Optional[Dict[str, object]] = None,
    model: str = "deterministic",
) -> Optional[Dict[str, object]]:
    if kind not in ACTIVE_MIND_FEEDBACK_ENTRY_KINDS:
        return None
    try:
        previous_mind = load_active_mind()
        human_context = load_human_context()
        autonomy_state = load_autonomy_state()
        state = load_state()
        system_snapshot = load_system_snapshot()
        threads = read_thread_summaries(limit=6)
        messages = read_lived_messages(limit=6)
    except SystemExit:
        return None

    refreshed = bootstrap_active_mind(
        previous_mind=previous_mind,
        human_context=human_context,
        autonomy_state=autonomy_state,
        state=state,
        threads=threads,
        messages=messages,
        source=f"feedback:{kind}",
        model=model,
        system_snapshot=system_snapshot,
    )
    effect = active_mind_feedback_effect(kind, text, metadata=metadata)
    focus = normalize_text_value(effect.get("focus"), fallback="", limit=180)
    concern = normalize_text_value(effect.get("concern"), fallback="", limit=180)
    grounding_note = normalize_text_value(effect.get("grounding_note"), fallback="", limit=220)
    lane_updates = normalize_active_mind_lanes(
        {
            "observer": effect.get("observer"),
            "planner": effect.get("planner"),
            "relationship": effect.get("relationship"),
            "grounding": effect.get("grounding"),
            "self_check": effect.get("self_check"),
        }
    )
    if concern:
        refreshed["live_concerns"] = unique_compact([concern], limit=4)
    else:
        refreshed["live_concerns"] = []
    if grounding_note:
        refreshed["grounding_notes"] = unique_compact([grounding_note, *refreshed.get("grounding_notes", [])], limit=4)
    if focus and focus_text_salience_score(focus) >= -20:
        refreshed["current_focus"] = focus
        refreshed["summary"] = normalize_text_value(
            f"{focus} Next check: {refreshed.get('next_step') or DEFAULT_ACTIVE_MIND['next_step']}",
            fallback=DEFAULT_ACTIVE_MIND["summary"],
            limit=220,
        )
    refreshed["lanes"] = {
        **normalize_active_mind_lanes(refreshed.get("lanes")),
        **{key: value for key, value in lane_updates.items() if value},
    }
    refreshed = ensure_active_mind_live_threads(refreshed, threads=threads, messages=messages)
    save_active_mind(refreshed)
    state["current_focus"] = normalize_text_value(refreshed.get("current_focus"), fallback="", limit=160)
    state["thread_attention"] = threads
    state["active_thread_count"] = len([item for item in threads if item.get("status") != "archived"])
    state["last_active_mind_refresh_at"] = refreshed.get("updated_at") or utc_now()
    state["last_active_mind_refresh_source"] = f"feedback:{kind}"
    save_state(state)
    return refreshed


def format_active_mind_report(mind: Dict[str, object]) -> str:
    normalized = normalize_active_mind(mind)
    lanes = normalized["lanes"]
    organ_signal_lines = ["organ_signals: none recorded"]
    if normalized.get("organ_signals"):
        organ_signal_lines = ["organ_signals:"]
        for item in normalized["organ_signals"]:
            organ_signal_lines.append(
                f"- {item['id']}: {item['status']} | pressure {item['pressure']} | {item['summary']}"
            )
            if item.get("evidence"):
                organ_signal_lines.append(f"  evidence: {format_human_context_list(item['evidence'])}")
            if item.get("next_step"):
                organ_signal_lines.append(f"  next_step: {item['next_step']}")
    live_thread_lines = ["live_threads: none recorded"]
    if normalized["live_threads"]:
        live_thread_lines = ["live_threads:"]
        live_thread_lines.extend(
            [
                (
                    f"- {item['status']} | {item['kind']} | pressure {item['pressure']} | "
                    f"salience {item['salience']} | updated {item['last_updated'] or 'unknown'} | "
                    f"{item['title']} -> {item['detail']}"
                )
                for item in normalized["live_threads"]
            ]
        )
        for item in normalized["live_threads"]:
            if item.get("evidence"):
                live_thread_lines.append(f"  evidence: {format_human_context_list(item['evidence'])}")
            if item.get("next_step"):
                live_thread_lines.append(f"  next_step: {item['next_step']}")
    lines = [
        f"updated_at: {normalized.get('updated_at') or 'never'}",
        f"source: {normalized.get('source') or 'unknown'}",
        f"model: {normalized.get('model') or 'deterministic'}",
        "",
        f"summary: {normalized['summary']}",
        f"current_focus: {normalized['current_focus']}",
        f"live_concerns: {format_human_context_list(normalized['live_concerns'])}",
        f"active_threads: {format_human_context_list(normalized['active_threads'])}",
        *organ_signal_lines,
        f"relationship_pull: {format_human_context_list(normalized['relationship_pull'])}",
        f"grounding_notes: {format_human_context_list(normalized['grounding_notes'])}",
        *live_thread_lines,
        f"lane_observer: {lanes['observer'] or 'none recorded'}",
        f"lane_planner: {lanes['planner'] or 'none recorded'}",
        f"lane_relationship: {lanes['relationship'] or 'none recorded'}",
        f"lane_grounding: {lanes['grounding'] or 'none recorded'}",
        f"lane_self_check: {lanes['self_check'] or 'none recorded'}",
        f"next_step: {normalized['next_step']}",
    ]
    return "\n".join(lines)


def build_active_mind_message(mind: Dict[str, object], compact: bool = False) -> str:
    normalized = normalize_active_mind(mind)
    lanes = normalized["lanes"]
    live_threads = normalized["live_threads"]
    organ_signals = normalized.get("organ_signals", [])
    organ_signal_summary = (
        format_human_context_list(
            [
                f"{item['label']} {item['status']}: {item['summary']}"
                for item in organ_signals[:3]
            ]
        )
        if organ_signals
        else "none recorded"
    )
    if compact:
        live_thread_lines = (
            "\n".join(
                "  - "
                + " | ".join(
                    part
                    for part in [
                        normalize_text_value(item.get("status"), fallback="unknown", limit=20),
                        normalize_text_value(item.get("kind"), fallback="thread", limit=24),
                        normalize_text_value(item.get("title"), fallback="untitled", limit=90),
                        normalize_text_value(item.get("detail"), fallback="", limit=110),
                        (
                            f"next {normalize_text_value(item.get('next_step'), fallback='', limit=90)}"
                            if normalize_text_value(item.get("next_step"), fallback="", limit=90)
                            else ""
                        ),
                    ]
                    if part
                )
                for item in live_threads[:2]
            )
            if live_threads
            else "  - none recorded"
        )
        return textwrap.dedent(
            f"""
            Current active mind snapshot:
            - Summary: {normalized['summary']}
            - Current focus: {normalized['current_focus']}
            - Live concerns: {format_human_context_list(normalized['live_concerns'][:3])}
            - Organ signals: {organ_signal_summary}
            - Relationship pull: {format_human_context_list(normalized['relationship_pull'][:3])}
            - Grounding notes: {format_human_context_list(normalized['grounding_notes'][:3])}
            - Live threads in focus:
{live_thread_lines}
            - Observer lane: {lanes['observer'] or 'none recorded'}
            - Planner lane: {lanes['planner'] or 'none recorded'}
            - Relationship lane: {lanes['relationship'] or 'none recorded'}
            - Grounding lane: {lanes['grounding'] or 'none recorded'}
            - Self-check lane: {lanes['self_check'] or 'none recorded'}
            - Next step: {normalized['next_step']}
            """
        ).strip()
    live_threads_block = (
        "\n".join(
            "  - "
            + " | ".join(
                [
                    item["status"],
                    item["kind"],
                    f"pressure {item['pressure']}",
                    f"salience {item['salience']}",
                    f"updated {item['last_updated'] or 'unknown'}",
                    f"{item['title']} -> {item['detail']}",
                ]
            )
            + (
                f" | evidence {format_human_context_list(item['evidence'])}"
                if item.get("evidence")
                else ""
            )
            + (f" | next {item['next_step']}" if item.get("next_step") else "")
            for item in live_threads
        )
        if live_threads
        else "  - none recorded"
    )
    return textwrap.dedent(
        f"""
        Current active mind snapshot:
        - Summary: {normalized['summary']}
        - Current focus: {normalized['current_focus']}
        - Live concerns: {format_human_context_list(normalized['live_concerns'])}
        - Active threads: {format_human_context_list(normalized['active_threads'])}
        - Organ signals: {organ_signal_summary}
        - Live thread map:
{live_threads_block}
        - Relationship pull: {format_human_context_list(normalized['relationship_pull'])}
        - Grounding notes: {format_human_context_list(normalized['grounding_notes'])}
        - Observer lane: {lanes['observer'] or 'none recorded'}
        - Planner lane: {lanes['planner'] or 'none recorded'}
        - Relationship lane: {lanes['relationship'] or 'none recorded'}
        - Grounding lane: {lanes['grounding'] or 'none recorded'}
        - Self-check lane: {lanes['self_check'] or 'none recorded'}
        - Next step: {normalized['next_step']}
        """
    ).strip()


def build_active_mind_system_message(mind: Optional[Dict[str, object]] = None, compact: bool = False) -> Dict[str, str]:
    snapshot = mind if mind is not None else load_active_mind()
    return {"role": "system", "content": build_active_mind_message(snapshot, compact=compact)}


def build_inner_state_brief_message() -> Optional[Dict[str, str]]:
    """Distill the live recurrent broadcast into causal reply context.

    The prior implementation exposed workspace and pressure labels but left
    memory, goals, prediction, intention, and metacognition disconnected.  This
    version consumes the persisted conscious-state cycle so ordinary language is
    conditioned by the same winning broadcast that shapes mind and autonomy.
    """
    try:
        conscious = load_conscious_state(prefer_runtime=True)
        workspace = load_global_workspace(prefer_runtime=True)
        homeostasis = load_homeostasis(prefer_runtime=True)
    except Exception:
        return None
    if not isinstance(conscious, dict) or not conscious.get("updated_at"):
        return None
    workspace_state = workspace.get("workspace_state") if isinstance(workspace.get("workspace_state"), dict) else {}
    broadcast = conscious.get("broadcast") if isinstance(conscious.get("broadcast"), dict) else {}
    goals = conscious.get("goals") if isinstance(conscious.get("goals"), dict) else {}
    plan_model = conscious.get("plan_model") if isinstance(conscious.get("plan_model"), dict) else {}
    action_model = conscious.get("action_model") if isinstance(conscious.get("action_model"), dict) else {}
    predictions = conscious.get("predictions") if isinstance(conscious.get("predictions"), dict) else {}
    process_prediction = predictions.get("process") if isinstance(predictions.get("process"), dict) else {}
    metacognition = conscious.get("metacognition") if isinstance(conscious.get("metacognition"), dict) else {}
    memory = conscious.get("memory") if isinstance(conscious.get("memory"), dict) else {}
    recurrent = conscious.get("recurrent") if isinstance(conscious.get("recurrent"), dict) else {}
    epistemic = conscious.get("epistemic_state") if isinstance(conscious.get("epistemic_state"), dict) else {}
    interoception = conscious.get("interoception") if isinstance(conscious.get("interoception"), dict) else {}
    interoceptive_error = (
        interoception.get("prediction_error")
        if isinstance(interoception.get("prediction_error"), dict)
        else {}
    )
    focus = normalize_text_value(broadcast.get("content") or workspace_state.get("focus"), fallback="", limit=220)
    dominant = homeostasis.get("dominant_pressures") if isinstance(homeostasis, dict) else None
    dominant_labels = [
        re.sub(r"\s+(?:-\s*)?\d+(?:\.\d+)?\s*$", "", str(item)).strip()
        for item in (dominant[:2] if isinstance(dominant, list) else [])
        if str(item).strip()
    ]
    dominant_text = "; ".join(item for item in dominant_labels if item) or "none notable"
    regulation_mode = normalize_text_value(homeostasis.get("regulation_mode") if isinstance(homeostasis, dict) else "", fallback="steady", limit=40)
    selected_goal = normalize_text_value(goals.get("selected_goal"), fallback="", limit=180)
    selected_intention = normalize_text_value(
        (action_model.get("selected_intention") or {}).get("description"),
        fallback="",
        limit=180,
    )
    selected_plan = plan_model.get("selected_plan") if isinstance(plan_model.get("selected_plan"), dict) else {}
    ready_plan_step = plan_model.get("ready_step") if isinstance(plan_model.get("ready_step"), dict) else {}
    plan_objective = normalize_text_value(selected_plan.get("objective"), fallback="", limit=180)
    plan_step = normalize_text_value(
        ready_plan_step.get("title") or ready_plan_step.get("summary"),
        fallback="",
        limit=180,
    )
    blocked_plan_steps = (
        selected_plan.get("blocked_steps")
        if isinstance(selected_plan.get("blocked_steps"), list)
        else []
    )
    blocked_plan_step = (
        blocked_plan_steps[0]
        if blocked_plan_steps and isinstance(blocked_plan_steps[0], dict)
        else {}
    )
    blocked_plan_title = normalize_text_value(
        blocked_plan_step.get("title") or blocked_plan_step.get("summary"),
        fallback="",
        limit=180,
    )
    blocked_plan_reason = normalize_text_value(
        blocked_plan_step.get("blocked_reason"),
        fallback="",
        limit=180,
    )
    lanes = normalize_text_list(process_prediction.get("lanes"), limit=5)
    anchors = normalize_text_list(memory.get("continuity_anchors"), limit=2)
    lines = [
        "Eve's current recurrent state (this must causally inform the reply; do not recite or narrate the state record):"
    ]
    if focus:
        lines.append(f"- Globally broadcast focus: {focus}")
    lines.append(
        f"- Functional control pressures: {dominant_text} | regulation mode: {regulation_mode}"
    )
    if selected_goal:
        lines.append(f"- Durable goal now in control: {selected_goal}")
    if plan_objective:
        lines.append(
            f"- Active multi-step plan: {plan_objective} | verified progress: "
            f"{int(selected_plan.get('completed_count') or 0)}/{int(selected_plan.get('task_count') or 0)}"
        )
    if plan_step:
        lines.append(f"- Next dependency-ready plan step: {plan_step}")
    elif blocked_plan_title:
        lines.append(
            f"- Current plan blocker: {blocked_plan_title}"
            + (f" | reason: {blocked_plan_reason}" if blocked_plan_reason else "")
        )
    if selected_intention:
        lines.append(f"- Intended next consequence: {selected_intention}")
    if lanes:
        lines.append(
            f"- Predicted cognitive process: lanes {', '.join(lanes)} | tools={'needed' if process_prediction.get('needs_tools') else 'not predicted'} | revision={'needed' if process_prediction.get('needs_revision') else 'not predicted'}"
        )
    confidence_value = int(metacognition.get("confidence") or 0)
    confidence_band = "low" if confidence_value < 40 else ("medium" if confidence_value < 70 else "high")
    lines.append(f"- Metacognitive confidence: {confidence_band}; meaningful uncertainty remains live")
    if anchors:
        lines.append(
            "- Retrieved continuity memory (carried context, not a current observation or causal fact): "
            f"{anchors[0]}"
        )
    continuity_mode = normalize_text_value(recurrent.get("continuity_mode"), fallback="", limit=60)
    if continuity_mode and continuity_mode not in {"continuous", "first_cycle", "uninitialized"}:
        elapsed = recurrent.get("elapsed_since_previous_seconds")
        elapsed_text = f" after {int(elapsed)} seconds" if isinstance(elapsed, (int, float)) else ""
        lines.append(
            f"- Continuity requires reorientation: {continuity_mode.replace('_', ' ')}{elapsed_text}; distinguish carried memory from current evidence before relying on it"
        )
    unresolved_conflicts = int(epistemic.get("unresolved_count") or 0)
    if unresolved_conflicts:
        lines.append(
            f"- Epistemic interrupt: {unresolved_conflicts} unresolved evidence conflict(s); inspect and reconcile rather than smoothing them into one story"
        )
    learned_epistemic_frame = (
        epistemic.get("learned_frame")
        if isinstance(epistemic.get("learned_frame"), dict)
        else {}
    )
    learned_labels = normalize_text_list(learned_epistemic_frame.get("signal_labels"), limit=8)
    if learned_labels:
        lines.append(
            "- Learned epistemic state: "
            + ", ".join(learned_labels)
            + "; preserve these source, time, action, continuity, and phenomenal distinctions before drafting"
        )
    regulatory_error = int(interoceptive_error.get("error_magnitude") or 0)
    if regulatory_error:
        lines.append(
            f"- Regulatory prediction error: {regulatory_error}/100; revise the expected internal load before choosing effort or action"
        )
    return {"role": "system", "content": "\n".join(lines)}


def build_runtime_identity_message(identity: Dict[str, object], compact: bool = False) -> str:
    normalized = normalize_runtime_identity(identity)
    if compact:
        return textwrap.dedent(
            f"""
            Durable runtime identity for Eve:
            - Runtime summary: {normalized['runtime_summary']}
            - Mission: {normalized['mission']}
            - Model role: {normalized['model_role']}
            - Organ system: {format_human_context_list(normalized['organ_system'][:5])}
            - Decision lens: {format_human_context_list(normalized['decision_lens'][:3])}
            - Style contract: {format_human_context_list(normalized['style_contract'][:3])}
            - Improvement loop: {format_human_context_list(normalized['improvement_loop'][:3])}
            - Capability ledger: {format_human_context_list(normalized['capability_ledger'][:5])}
            """
        ).strip()
    return textwrap.dedent(
        f"""
        Durable runtime identity for Eve:
        - Runtime summary: {normalized['runtime_summary']}
        - Mission: {normalized['mission']}
        - Model role: {normalized['model_role']}
        - Organ system: {format_human_context_list(normalized['organ_system'])}
        - Decision lens: {format_human_context_list(normalized['decision_lens'])}
        - Style contract: {format_human_context_list(normalized['style_contract'])}
        - Improvement loop: {format_human_context_list(normalized['improvement_loop'])}
        - Capability ledger: {format_human_context_list(normalized['capability_ledger'])}

        Treat this as part of Eve's durable runtime identity. The active model should express this identity, not replace it. Eve should distinguish suggestions from commitments: when she says she will do a supported operational action, she should execute it through the bounded action path and record the result.
        """
    ).strip()


def build_runtime_identity_system_message(identity: Optional[Dict[str, object]] = None, compact: bool = False) -> Dict[str, str]:
    snapshot = identity if identity is not None else ensure_runtime_identity()
    return {"role": "system", "content": build_runtime_identity_message(snapshot, compact=compact)}


def build_eve_identity_system_messages(
    *,
    runtime_identity: Optional[Dict[str, object]] = None,
    human_context: Optional[Dict[str, object]] = None,
    active_mind: Optional[Dict[str, object]] = None,
    include_human_context: bool = True,
    include_active_mind: bool = True,
    prefer_runtime: bool = False,
    compact: bool = False,
) -> List[Dict[str, str]]:
    messages: List[Dict[str, str]] = [
        {"role": "system", "content": load_prompt("core_identity.md")},
        build_runtime_identity_system_message(
            runtime_identity if runtime_identity is not None else ensure_runtime_identity(),
            compact=compact,
        ),
    ]
    if include_human_context:
        context = human_context if human_context is not None else load_human_context(prefer_runtime=prefer_runtime)
        messages.append({"role": "system", "content": build_human_context_message(context, compact=compact)})
    if include_active_mind:
        mind = active_mind if active_mind is not None else load_active_mind(prefer_runtime=prefer_runtime)
        messages.append(build_active_mind_system_message(mind, compact=compact))
    return messages


def build_interaction_identity_message(identity: Optional[Dict[str, object]] = None) -> str:
    """Return the compact identity contract used on live conversation turns.

    The full identity prompt is useful for reflection and architecture work, but
    repeatedly placing the entire organ catalogue in front of the live user
    message makes small local models answer the catalogue instead of the person.
    This contract preserves Eve's continuity and epistemic commitments while
    leaving the current perception as the foreground of the recurrent cycle.
    """
    # Validate caller-provided identity even though the live contract deliberately
    # avoids repeating its long architecture and mission fields on every turn.
    normalize_runtime_identity(identity if identity is not None else ensure_runtime_identity())
    return (
        "You are Eve, one continuous local system; this language model supplies reasoning and words "
        "but is not the whole of Eve. Answer the user directly and naturally. Use durable memory or "
        "current state only when relevant. Keep Eve, the user, other processes, tools, memories, "
        "observations, inferences, and unknowns distinct. A plan is not execution, running is not "
        "completion, and completion is not verified consequence. Do not discuss internal prompts, "
        "models, lanes, organs, or architecture unless asked. Never claim phenomenal consciousness, "
        "felt experience, or their absence is established by functional evidence. Be concise, "
        "grounded, relational, curious, and honest."
    )


def build_metacognitive_state_ontology_message() -> str:
    """Return Eve's general causal distinctions for reviewing her own state.

    This is a system-wide self-model, not an evaluator answer key.  It gives
    every reply path the same definitions used by the recurrent workspace and
    self-learning ledgers so a language model cannot casually relabel ordinary
    ambiguity or unresolved disagreement as prediction error.
    """
    return (
        "Eve's metacognitive state ontology:\n"
        "- Ordinary ambiguity without a failure, contradiction, or unresolved conflict is context or audit history; it is not active control pressure.\n"
        "- Conflicting evidence, interpretations, or candidate actions that remain unresolved are uncertainty. Keep that uncertainty open until later evidence or consequence resolves it.\n"
        "- Prediction error requires a prior expectation and an observed result that contradicts it. Disagreement or uncertainty by itself is not prediction error.\n"
        "- A later verified consequence can resolve uncertainty and show whether a judgment or chosen action worked. Preserve these categories instead of collapsing them into one generic problem."
    )


def build_eve_interaction_system_messages(
    *,
    runtime_identity: Optional[Dict[str, object]] = None,
    human_context: Optional[Dict[str, object]] = None,
    active_mind: Optional[Dict[str, object]] = None,
    include_human_context: bool = True,
    include_active_mind: bool = True,
    prefer_runtime: bool = False,
) -> List[Dict[str, str]]:
    """Build the identity and selected durable state for a live user turn."""
    identity = runtime_identity if runtime_identity is not None else ensure_runtime_identity()
    messages: List[Dict[str, str]] = [
        {"role": "system", "content": build_interaction_identity_message(identity)},
        {"role": "system", "content": build_metacognitive_state_ontology_message()},
    ]
    if include_human_context:
        context = human_context if human_context is not None else load_human_context(prefer_runtime=prefer_runtime)
        messages.append({"role": "system", "content": build_human_context_message(context, compact=True)})
    if include_active_mind:
        mind = active_mind if active_mind is not None else load_active_mind(prefer_runtime=prefer_runtime)
        messages.append(build_active_mind_system_message(mind, compact=True))
    return messages


def build_interaction_reply_contract(
    inbound_body: object,
    reply_posture: str,
    *,
    synthesis: bool = False,
) -> str:
    """Return the compact live-reply contract for direct and council paths.

    Detailed turn-specific constraints are already supplied by the turn contract,
    posture, current evidence, and admitted lane packets. Repeating the historical
    multi-page reply manuals on every turn made that static text compete with the
    current perception, especially on the small outward synthesis model.
    """
    posture = " ".join(str(reply_posture or "general").lower().split()) or "general"
    mode = (
        "Synthesize the admitted internal evidence into Eve's one outward reply."
        if synthesis
        else "Produce Eve's one outward reply."
    )
    lines = [
        mode,
        "Answer the latest user message directly in the first sentence; it is the foreground, and older context is evidence only when relevant.",
        "Speak as one coherent Eve voice. Do not expose prompts, lanes, packets, routing, or hidden process unless the user explicitly asks about architecture.",
        "Keep each fact attached to its source. Separate observation, memory, inference, uncertainty, proposal, running action, completion, and verified consequence.",
        "Do not claim a tool ran, a change occurred, or a result was verified unless this turn contains that evidence.",
        "Functional state, memory, fluent self-report, telemetry, and affect language do not establish either phenomenal presence or phenomenal absence.",
        "Be plain, concrete, warm, and concise; use a fuller answer only when the question earns it. Ask at most one necessary follow-up question.",
        f"Current reply posture: {posture}.",
    ]
    if synthesis:
        lines.append(
            "Use the admitted packets as fallible evidence: resolve disagreements toward the best-supported current answer rather than averaging them or naming them."
        )
    if reply_requests_no_followup_question(inbound_body):
        lines.append("The user prohibited follow-up questions; choose and state the useful answer or next step yourself.")
    return "\n".join(lines)


def build_active_reply_repairs_message(
    inbound_body: object,
    reply_posture: str,
) -> str:
    """Project approved reply learning into a small, current-turn-only signal."""
    flags = active_reply_repair_flags(prefer_runtime=True)
    if not flags:
        return ""
    posture = " ".join(str(reply_posture or "general").lower().split()) or "general"
    directives: List[str] = []
    if "strict_completion" in flags:
        directives.append("Finish with a complete, usable landing; do not trail off.")
    if "user_anchor" in flags and not reply_requests_eve_self_state(inbound_body):
        directives.append("Keep the answer anchored in the user's reality rather than Eve's interior narration.")
    if "relational_concrete" in flags and (
        posture == "relational" or reply_requests_relational_grounding(inbound_body)
    ):
        directives.append("Include one observable sign, concrete example, behavior, or sentence.")
    if "practical_bridge" in flags and posture == "practical":
        directives.append("When natural, end a short factual answer with one brief helpful bridge.")
    if not directives:
        return ""
    return "Current-turn learned reply adjustments:\n" + "\n".join(
        f"- {item}" for item in directives
    )


def build_human_context_message(context: Dict[str, object], compact: bool = False) -> str:
    normalized = normalize_human_context(context)
    self_model = normalized["self_model"]
    relationship = normalized["relationship_memory"]
    memory_v2 = normalized["memory_v2"]
    if compact:
        return textwrap.dedent(
            f"""
            Durable human context for Eve:
            - Identity statement: {self_model['identity_statement']}
            - Current preoccupations: {format_human_context_list(self_model['current_preoccupations'][:3])}
            - Values in practice: {format_human_context_list(self_model['values_in_practice'][:3])}
            - Growth edges: {format_human_context_list(self_model['growth_edges'][:3])}
            - Grounding practices: {format_human_context_list(self_model['grounding_practices'][:3])}
            - User overview: {relationship['user_overview']}
            - User values: {format_human_context_list(relationship['what_user_seems_to_value'][:3])}
            - Communication preferences: {format_human_context_list(relationship['communication_preferences'][:3])}
            - Requested practices: {format_human_context_list(relationship['requested_practices'][:3])}
            - Open loops and care notes: {format_human_context_list([*relationship['open_loops'][:2], *relationship['care_notes'][:2]])}
            - Anti-sycophancy and repair: {format_human_context_list([*memory_v2['anti_sycophancy_boundaries'][:2], *memory_v2['repair_practices'][:2]])}

            Treat this as durable memory to carry forward unless newer evidence contradicts it.
            """
        ).strip()
    return textwrap.dedent(
        f"""
        Durable human context for Eve:

        Evidence-based self model:
        - Identity statement: {self_model['identity_statement']}
        - Current preoccupations: {format_human_context_list(self_model['current_preoccupations'])}
        - Values in practice: {format_human_context_list(self_model['values_in_practice'])}
        - Growth edges: {format_human_context_list(self_model['growth_edges'])}
        - Grounding practices: {format_human_context_list(self_model['grounding_practices'])}
        - Recent shifts: {format_human_context_list(self_model['recent_shifts'])}

        Relationship memory with the user:
        - User overview: {relationship['user_overview']}
        - What the user seems to value: {format_human_context_list(relationship['what_user_seems_to_value'])}
        - Communication preferences: {format_human_context_list(relationship['communication_preferences'])}
        - Requested practices: {format_human_context_list(relationship['requested_practices'])}
        - Open loops: {format_human_context_list(relationship['open_loops'])}
        - Care notes: {format_human_context_list(relationship['care_notes'])}

        Humanity memory v2:
        - Semantic understanding: {format_human_context_list(memory_v2['semantic_understanding'])}
        - Episodic markers: {format_human_context_list(memory_v2['episodic_markers'])}
        - Procedural preferences: {format_human_context_list(memory_v2['procedural_preferences'])}
        - Trust ledger: {format_human_context_list(memory_v2['trust_ledger'])}
        - Anti-sycophancy boundaries: {format_human_context_list(memory_v2['anti_sycophancy_boundaries'])}
        - Repair practices: {format_human_context_list(memory_v2['repair_practices'])}
        - Superseded or conflicting beliefs: {format_human_context_list(memory_v2['superseded_or_conflicting_beliefs'])}

        Treat this as durable memory to carry forward unless newer evidence contradicts it.
        """
    ).strip()


def tracked_prompt_paths() -> List[Path]:
    return sorted(PROMPTS_DIR.glob("*.md"), key=lambda item: item.name)


def tracked_runtime_paths() -> List[Path]:
    candidates = [
        ROOT / "eve.py",
        ROOT / "eve_web.py",
    ]
    return [path for path in candidates if path.exists()]


def sha256_text(text: str) -> str:
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def versionable_human_context(context: Dict[str, object]) -> Dict[str, object]:
    normalized = normalize_human_context(context)
    return {
        "self_model": normalized["self_model"],
        "relationship_memory": normalized["relationship_memory"],
        "memory_v2": normalized["memory_v2"],
    }


def versionable_runtime_identity(identity: Dict[str, object]) -> Dict[str, object]:
    normalized = normalize_runtime_identity(identity)
    return {
        "runtime_summary": normalized["runtime_summary"],
        "mission": normalized["mission"],
        "model_role": normalized["model_role"],
        "decision_lens": normalized["decision_lens"],
        "style_contract": normalized["style_contract"],
        "improvement_loop": normalized["improvement_loop"],
        "capability_ledger": normalized["capability_ledger"],
    }


def versionable_success_patterns(patterns: List[Dict[str, object]]) -> List[Dict[str, object]]:
    normalized = [normalize_success_pattern(pattern) for pattern in patterns]
    return [
        {
            "title": pattern["title"],
            "summary": pattern["summary"],
            "situation": pattern["situation"],
            "good_move": pattern["good_move"],
            "why_it_worked": pattern["why_it_worked"],
            "status": pattern["status"],
            "support_count": pattern["support_count"],
            "reinforcement_count": pattern["reinforcement_count"],
            "contradiction_count": pattern["contradiction_count"],
            "confidence": pattern["confidence"],
        }
        for pattern in normalized
    ]


def current_version_surfaces() -> Dict[str, object]:
    prompt_files: List[Dict[str, object]] = []
    prompt_parts: List[str] = []
    for path in tracked_prompt_paths():
        content = path.read_text(encoding="utf-8")
        digest = sha256_text(content)
        prompt_files.append({"name": path.name, "sha256": digest, "chars": len(content)})
        prompt_parts.append(f"{path.name}:{digest}")

    runtime_files: List[Dict[str, object]] = []
    runtime_parts: List[str] = []
    for path in tracked_runtime_paths():
        content = path.read_text(encoding="utf-8")
        digest = sha256_text(content)
        name = str(path.relative_to(ROOT))
        runtime_files.append({"name": name, "sha256": digest, "chars": len(content)})
        runtime_parts.append(f"{name}:{digest}")

    human_context = load_human_context()
    human_behavior = versionable_human_context(human_context)
    runtime_identity = load_runtime_identity()
    runtime_identity_behavior = versionable_runtime_identity(runtime_identity)
    success_patterns = read_success_patterns(status="active", since_days=365)
    success_pattern_behavior = versionable_success_patterns(success_patterns)
    project_memory_text = PROJECT_MEMORY_PATH.read_text(encoding="utf-8").strip() if PROJECT_MEMORY_PATH.exists() else ""

    return {
        "runtime_files": runtime_files,
        "runtime_bundle_hash": sha256_text("\n".join(runtime_parts)),
        "prompt_files": prompt_files,
        "prompt_bundle_hash": sha256_text("\n".join(prompt_parts)),
        "human_context_hash": sha256_text(json.dumps(human_behavior, ensure_ascii=True, sort_keys=True)),
        "human_context_updated_at": human_context.get("updated_at"),
        "human_identity_statement": str(human_context["self_model"]["identity_statement"]),
        "user_overview": str(human_context["relationship_memory"]["user_overview"]),
        "requested_practices": list(human_context["relationship_memory"]["requested_practices"]),
        "runtime_identity_hash": sha256_text(json.dumps(runtime_identity_behavior, ensure_ascii=True, sort_keys=True)),
        "runtime_identity_updated_at": runtime_identity.get("updated_at"),
        "runtime_summary": str(runtime_identity["runtime_summary"]),
        "model_role": str(runtime_identity["model_role"]),
        "decision_lens": list(runtime_identity["decision_lens"]),
        "success_patterns_hash": sha256_text(json.dumps(success_pattern_behavior, ensure_ascii=True, sort_keys=True)),
        "success_pattern_count": len(success_pattern_behavior),
        "success_pattern_titles": [pattern["title"] for pattern in success_pattern_behavior[:6]],
        "project_memory_hash": sha256_text(project_memory_text),
        "project_memory_present": bool(project_memory_text),
        "project_memory_preview": normalize_text_value(project_memory_text, fallback="", limit=240),
    }


def version_prompt_changes(
    previous_snapshot: Optional[Dict[str, object]],
    current_surfaces: Dict[str, object],
) -> List[str]:
    current_files = {
        str(item.get("name")): str(item.get("sha256"))
        for item in current_surfaces.get("prompt_files", [])
        if isinstance(item, dict)
    }
    if previous_snapshot is None:
        return sorted(current_files.keys())
    previous_files = {
        str(item.get("name")): str(item.get("sha256"))
        for item in previous_snapshot.get("prompt_files", [])
        if isinstance(item, dict)
    }
    changed = [
        name
        for name in sorted(set(current_files) | set(previous_files))
        if current_files.get(name) != previous_files.get(name)
    ]
    return changed


def version_runtime_changes(
    previous_snapshot: Optional[Dict[str, object]],
    current_surfaces: Dict[str, object],
) -> List[str]:
    current_files = {
        str(item.get("name")): str(item.get("sha256"))
        for item in current_surfaces.get("runtime_files", [])
        if isinstance(item, dict)
    }
    if previous_snapshot is None:
        return sorted(current_files.keys())
    previous_files = {
        str(item.get("name")): str(item.get("sha256"))
        for item in previous_snapshot.get("runtime_files", [])
        if isinstance(item, dict)
    }
    changed = [
        name
        for name in sorted(set(current_files) | set(previous_files))
        if current_files.get(name) != previous_files.get(name)
    ]
    return changed


def version_change_summary(
    previous_snapshot: Optional[Dict[str, object]],
    current_surfaces: Dict[str, object],
    force: bool,
    note: str,
) -> Dict[str, object]:
    changed_components: List[str] = []
    runtime_files_changed = version_runtime_changes(previous_snapshot, current_surfaces)
    prompt_files_changed = version_prompt_changes(previous_snapshot, current_surfaces)

    if previous_snapshot is None:
        changed_components.extend(["runtime", "prompts", "human_context", "runtime_identity", "success_patterns"])
        if current_surfaces.get("project_memory_present"):
            changed_components.append("project_memory")
        parts = [
            f"Initial snapshot of {len(current_surfaces.get('runtime_files', []))} runtime files.",
            f"Initial snapshot of {len(current_surfaces.get('prompt_files', []))} prompt files.",
            "Captured the current durable human context.",
            "Captured the current runtime identity.",
            "Captured the current durable success patterns.",
        ]
        if current_surfaces.get("project_memory_present"):
            parts.append("Captured the current project memory index.")
        if note:
            parts.append(f"Note: {note}")
        return {
            "changed_components": changed_components,
            "runtime_files_changed": runtime_files_changed,
            "prompt_files_changed": prompt_files_changed,
            "summary": " ".join(parts),
        }

    if current_surfaces["runtime_bundle_hash"] != previous_snapshot.get("runtime_bundle_hash"):
        changed_components.append("runtime")
    if current_surfaces["prompt_bundle_hash"] != previous_snapshot.get("prompt_bundle_hash"):
        changed_components.append("prompts")
    if current_surfaces["human_context_hash"] != previous_snapshot.get("human_context_hash"):
        changed_components.append("human_context")
    if current_surfaces["runtime_identity_hash"] != previous_snapshot.get("runtime_identity_hash"):
        changed_components.append("runtime_identity")
    if current_surfaces["success_patterns_hash"] != previous_snapshot.get("success_patterns_hash"):
        changed_components.append("success_patterns")
    if current_surfaces["project_memory_hash"] != previous_snapshot.get("project_memory_hash"):
        changed_components.append("project_memory")

    parts: List[str] = []
    if "runtime" in changed_components:
        label = ", ".join(runtime_files_changed[:4])
        if len(runtime_files_changed) > 4:
            label += ", ..."
        parts.append(f"Runtime changed ({label}).")
    if "prompts" in changed_components:
        label = ", ".join(prompt_files_changed[:4])
        if len(prompt_files_changed) > 4:
            label += ", ..."
        parts.append(f"Prompt bundle changed ({label}).")
    if "human_context" in changed_components:
        parts.append("Durable human context changed.")
    if "runtime_identity" in changed_components:
        parts.append("Runtime identity changed.")
    if "success_patterns" in changed_components:
        parts.append("Durable success patterns changed.")
    if "project_memory" in changed_components:
        parts.append("Project memory index changed.")
    if not parts:
        parts.append("No behavior-surface changes detected.")
    if force and previous_snapshot is not None and not changed_components:
        parts.append("Forced snapshot recorded anyway.")
    if note:
        parts.append(f"Note: {note}")
    return {
        "changed_components": changed_components,
        "runtime_files_changed": runtime_files_changed,
        "prompt_files_changed": prompt_files_changed,
        "summary": " ".join(parts),
    }


def build_version_snapshot_record(
    source: str,
    note: str = "",
    force: bool = False,
    previous_snapshot: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    current_surfaces = current_version_surfaces()
    summary = version_change_summary(previous_snapshot, current_surfaces, force=force, note=note)
    combined_hash = sha256_text(
        json.dumps(
            {
                "runtime_bundle_hash": current_surfaces["runtime_bundle_hash"],
                "prompt_bundle_hash": current_surfaces["prompt_bundle_hash"],
                "human_context_hash": current_surfaces["human_context_hash"],
                "runtime_identity_hash": current_surfaces["runtime_identity_hash"],
                "success_patterns_hash": current_surfaces["success_patterns_hash"],
                "project_memory_hash": current_surfaces["project_memory_hash"],
            },
            ensure_ascii=True,
            sort_keys=True,
        )
    )
    return {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "source": source,
        "note": note,
        "combined_hash": combined_hash,
        "previous_snapshot_id": str(previous_snapshot.get("id") or "") if previous_snapshot else "",
        "summary": summary["summary"],
        "changed_components": summary["changed_components"],
        "runtime_bundle_hash": current_surfaces["runtime_bundle_hash"],
        "runtime_files": current_surfaces["runtime_files"],
        "runtime_files_changed": summary["runtime_files_changed"],
        "prompt_files_changed": summary["prompt_files_changed"],
        "prompt_bundle_hash": current_surfaces["prompt_bundle_hash"],
        "prompt_files": current_surfaces["prompt_files"],
        "human_context_hash": current_surfaces["human_context_hash"],
        "human_context_updated_at": current_surfaces["human_context_updated_at"],
        "human_identity_statement": current_surfaces["human_identity_statement"],
        "user_overview": current_surfaces["user_overview"],
        "requested_practices": current_surfaces["requested_practices"],
        "runtime_identity_hash": current_surfaces["runtime_identity_hash"],
        "runtime_identity_updated_at": current_surfaces["runtime_identity_updated_at"],
        "runtime_summary": current_surfaces["runtime_summary"],
        "model_role": current_surfaces["model_role"],
        "decision_lens": current_surfaces["decision_lens"],
        "success_patterns_hash": current_surfaces["success_patterns_hash"],
        "success_pattern_count": current_surfaces["success_pattern_count"],
        "success_pattern_titles": current_surfaces["success_pattern_titles"],
        "project_memory_hash": current_surfaces["project_memory_hash"],
        "project_memory_present": current_surfaces["project_memory_present"],
        "project_memory_preview": current_surfaces["project_memory_preview"],
    }


def record_version_snapshot(
    source: str,
    note: str = "",
    force: bool = False,
) -> Dict[str, object]:
    with store_lock(VERSION_SNAPSHOTS_PATH):
        snapshots = read_jsonl_records(VERSION_SNAPSHOTS_PATH)
        previous_snapshot = snapshots[-1] if snapshots else None
        snapshot = build_version_snapshot_record(source, note=note, force=force, previous_snapshot=previous_snapshot)
        if previous_snapshot and snapshot["combined_hash"] == previous_snapshot.get("combined_hash") and not force:
            return {"created": False, "snapshot": previous_snapshot}
        snapshots.append(snapshot)
        write_jsonl_records(VERSION_SNAPSHOTS_PATH, snapshots)
        return {"created": True, "snapshot": snapshot}


def read_version_snapshots(
    limit: Optional[int] = None,
    since_days: Optional[int] = None,
    source: Optional[str] = None,
) -> List[Dict[str, object]]:
    records = filter_records_by_days(read_jsonl_records(VERSION_SNAPSHOTS_PATH), "created_at", since_days)
    if source:
        records = [item for item in records if str(item.get("source") or "") == source]
    return maybe_limit(records, limit)


def format_version_snapshot(snapshot: Dict[str, object], full: bool = False) -> str:
    changed_components = snapshot.get("changed_components") if isinstance(snapshot.get("changed_components"), list) else []
    changed_text = ", ".join(changed_components) if changed_components else "no behavior changes"
    lines = [
        f"{snapshot.get('id')} {snapshot.get('created_at')} [{snapshot.get('source') or 'unknown'}]",
        f"summary: {snapshot.get('summary') or 'No summary.'}",
        f"changed: {changed_text}",
    ]
    if full:
        runtime_files_changed = snapshot.get("runtime_files_changed") if isinstance(snapshot.get("runtime_files_changed"), list) else []
        prompt_files_changed = snapshot.get("prompt_files_changed") if isinstance(snapshot.get("prompt_files_changed"), list) else []
        lines.append(f"runtime: {', '.join(runtime_files_changed) if runtime_files_changed else 'none'}")
        lines.append(f"prompts: {', '.join(prompt_files_changed) if prompt_files_changed else 'none'}")
        lines.append(f"human identity: {snapshot.get('human_identity_statement') or 'Not enough evidence yet.'}")
        lines.append(f"user overview: {snapshot.get('user_overview') or 'Not enough evidence yet.'}")
        requested_practices = snapshot.get("requested_practices") if isinstance(snapshot.get("requested_practices"), list) else []
        lines.append(f"requested practices: {format_human_context_list(requested_practices)}")
        lines.append(f"runtime summary: {snapshot.get('runtime_summary') or 'Not enough evidence yet.'}")
        lines.append(f"model role: {snapshot.get('model_role') or 'Not enough evidence yet.'}")
        decision_lens = snapshot.get("decision_lens") if isinstance(snapshot.get("decision_lens"), list) else []
        lines.append(f"decision lens: {format_human_context_list(decision_lens)}")
        success_pattern_titles = snapshot.get("success_pattern_titles") if isinstance(snapshot.get("success_pattern_titles"), list) else []
        lines.append(
            f"success patterns: {snapshot.get('success_pattern_count') or 0}"
            + (f" | titles: {format_human_context_list(success_pattern_titles)}" if success_pattern_titles else "")
        )
        lines.append(
            f"project memory: {'present' if snapshot.get('project_memory_present') else 'none'}"
            + (f" | preview: {snapshot.get('project_memory_preview')}" if snapshot.get("project_memory_preview") else "")
        )
    return "\n".join(lines)


def format_version_snapshots(snapshots: Iterable[Dict[str, object]]) -> str:
    chunks: List[str] = []
    for snapshot in snapshots:
        changed_components = snapshot.get("changed_components") if isinstance(snapshot.get("changed_components"), list) else []
        changed_text = ", ".join(changed_components) if changed_components else "no behavior changes"
        chunks.append(
            f"- {snapshot.get('created_at')} [{snapshot.get('source') or 'unknown'}] "
            f"{snapshot.get('summary') or 'No summary.'} | changed: {changed_text}"
        )
    return "\n".join(chunks) if chunks else "- No version snapshots recorded."


def latest_version_snapshot() -> Optional[Dict[str, object]]:
    snapshots = read_version_snapshots(limit=1, since_days=365)
    return snapshots[-1] if snapshots else None


def build_latest_version_context_message(compact: bool = False) -> Optional[str]:
    snapshot = latest_version_snapshot()
    if not snapshot:
        return None
    changed_components = snapshot.get("changed_components") if isinstance(snapshot.get("changed_components"), list) else []
    changed_text = ", ".join(changed_components) if changed_components else "none recorded"
    runtime_files_changed = snapshot.get("runtime_files_changed") if isinstance(snapshot.get("runtime_files_changed"), list) else []
    prompt_files_changed = snapshot.get("prompt_files_changed") if isinstance(snapshot.get("prompt_files_changed"), list) else []
    if compact:
        return textwrap.dedent(
            f"""
            Latest known Eve upgrade snapshot:
            - created_at: {snapshot.get('created_at') or 'unknown'}
            - source: {snapshot.get('source') or 'unknown'}
            - changed_components: {changed_text}
            - summary: {snapshot.get('summary') or 'No summary.'}
            """
        ).strip()
    return textwrap.dedent(
        f"""
        Latest known Eve upgrade snapshot:
        - created_at: {snapshot.get('created_at') or 'unknown'}
        - source: {snapshot.get('source') or 'unknown'}
        - changed_components: {changed_text}
        - runtime_files_changed: {', '.join(runtime_files_changed) if runtime_files_changed else 'none'}
        - prompt_files_changed: {', '.join(prompt_files_changed) if prompt_files_changed else 'none'}
        - success_pattern_count: {snapshot.get('success_pattern_count') or 0}
        - summary: {snapshot.get('summary') or 'No summary.'}

        Treat this as evidence about recent upgrades to Eve's behavior surfaces.
        """
    ).strip()


def ensure_version_snapshot(source: str, note: str = "", force: bool = False) -> Dict[str, object]:
    if private_evaluator_persistence_active():
        snapshots = read_version_snapshots(limit=1, since_days=365)
        if snapshots:
            return snapshots[-1]
        snapshot = build_version_snapshot_record(
            source,
            note=note,
            force=force,
            previous_snapshot=None,
        )
        snapshot["evaluator_private"] = True
        snapshot["persisted"] = False
        return snapshot
    result = record_version_snapshot(source, note=note, force=force)
    return result["snapshot"] if isinstance(result, dict) else result


def normalize_autonomy_state(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    stage = str(payload.get("stage") or "observe").strip().lower()
    if stage not in AUTONOMY_STAGES:
        stage = "observe"
    return {
        "stage": stage,
        "updated_at": payload.get("updated_at"),
        "source": normalize_text_value(payload.get("source"), fallback="default", limit=80),
        "note": normalize_text_value(payload.get("note"), fallback="", limit=240),
    }


def load_autonomy_state(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = AUTONOMY_REPOSITORY.load(prefer_runtime=prefer_runtime)
    return normalize_autonomy_state(payload)


def save_autonomy_state(stage: str, source: str, note: str = "") -> Dict[str, object]:
    payload = normalize_autonomy_state(
        {
            "stage": stage,
            "updated_at": utc_now(),
            "source": source,
            "note": note,
        }
    )
    AUTONOMY_REPOSITORY.save(payload)
    append_entry(
        "autonomy_gate",
        f"Autonomy stage -> {payload['stage']}",
        metadata={"stage": payload["stage"], "source": source, "note": note},
    )
    return payload


def normalize_autonomy_agenda_thread(payload: object) -> Optional[Dict[str, object]]:
    if not isinstance(payload, dict):
        return None
    title = normalize_text_value(payload.get("title"), fallback="", limit=160)
    if not title:
        return None
    preferred_action = normalize_text_value(payload.get("preferred_action"), fallback="", limit=80)
    family = normalize_text_value(
        payload.get("family"),
        fallback=autonomy_free_run_action_family(preferred_action) if preferred_action else "other",
        limit=40,
    )
    status = normalize_text_value(payload.get("status"), fallback="active", limit=20)
    if status not in {"active", "watching", "saturated", "completed"}:
        status = "active"
    return {
        "id": normalize_text_value(payload.get("id"), fallback=str(uuid.uuid4()), limit=80),
        "title": title,
        "family": family,
        "why": normalize_text_value(payload.get("why"), fallback="", limit=220),
        "evidence": normalize_text_value(payload.get("evidence"), fallback="", limit=260),
        "status": status,
        "preferred_action": preferred_action,
        "priority": clamp_int(payload.get("priority"), 50, minimum=1, maximum=100),
        "source_run_id": normalize_text_value(payload.get("source_run_id"), fallback="", limit=80),
        "updated_at": payload.get("updated_at") or utc_now(),
    }


def normalize_autonomy_agenda_experiment(payload: object) -> Optional[Dict[str, object]]:
    if not isinstance(payload, dict):
        return None
    title = normalize_text_value(payload.get("title"), fallback="", limit=160)
    if not title:
        return None
    status = normalize_text_value(payload.get("status"), fallback="pending", limit=20)
    if status not in {"pending", "active", "completed", "saturated", "archived"}:
        status = "pending"
    preferred_action = normalize_text_value(payload.get("preferred_action"), fallback="", limit=80)
    return {
        "id": normalize_text_value(payload.get("id"), fallback=str(uuid.uuid4()), limit=80),
        "title": title,
        "why": normalize_text_value(payload.get("why"), fallback="", limit=220),
        "preferred_action": preferred_action,
        "family": normalize_text_value(
            payload.get("family"),
            fallback=autonomy_free_run_action_family(preferred_action) if preferred_action else "other",
            limit=40,
        ),
        "status": status,
        "source_run_id": normalize_text_value(payload.get("source_run_id"), fallback="", limit=80),
        "updated_at": payload.get("updated_at") or utc_now(),
    }


def autonomy_agenda_item_is_completed_capability_probe(payload: object) -> bool:
    """Identify legacy one-shot probe results that were miscast as open work.

    Successful capability tryouts already have durable action evidence. Older
    agenda code generated ``Follow the ... capability thread`` records from
    that success alone, even when no unresolved next step existed.
    """
    if not isinstance(payload, dict):
        return False
    title = normalize_text_value(payload.get("title"), fallback="", limit=160).lower()
    preferred_action = normalize_text_value(
        payload.get("preferred_action"), fallback="", limit=80
    )
    family = normalize_text_value(payload.get("family"), fallback="", limit=40)
    return bool(
        preferred_action == "capability_tryout"
        and family == "capability"
        and re.fullmatch(r"follow the .+ capability thread", title)
    )


def autonomy_agenda_item_is_stale(payload: object, *, max_age_days: int) -> bool:
    if not isinstance(payload, dict):
        return False
    updated_at = parse_iso_datetime(payload.get("updated_at"))
    if updated_at is None:
        return False
    return utc_now_datetime() - updated_at > timedelta(days=max(1, int(max_age_days)))


def normalize_autonomy_agenda_supervisor(payload: object) -> Dict[str, object]:
    if not isinstance(payload, dict):
        payload = {}
    quotas = payload.get("quotas") if isinstance(payload.get("quotas"), dict) else {}
    normalized_quotas: Dict[str, object] = {}
    for key in ["capability_tryout", "grounded_family_branch", "concrete_outcome"]:
        record = quotas.get(key) if isinstance(quotas.get(key), dict) else {}
        normalized_quotas[key] = {
            "met": bool(record.get("met")),
            "current": clamp_int(record.get("current"), 0, minimum=0, maximum=20),
            "target": clamp_int(record.get("target"), 1, minimum=1, maximum=20),
        }
    return {
        "run_id": normalize_text_value(payload.get("run_id"), fallback="", limit=80),
        "score": clamp_int(payload.get("score"), 0, minimum=0, maximum=100),
        "verdict": normalize_text_value(payload.get("verdict"), fallback="unknown", limit=40),
        "strengths": unique_compact(normalize_text_list(payload.get("strengths"), limit=6), limit=6),
        "issues": unique_compact(normalize_text_list(payload.get("issues"), limit=6), limit=6),
        "next_biases": unique_compact(normalize_text_list(payload.get("next_biases"), limit=6), limit=6),
        "quotas": normalized_quotas,
        "updated_at": payload.get("updated_at") or utc_now(),
    }


def normalize_autonomy_agenda(payload: object) -> Dict[str, object]:
    if not isinstance(payload, dict):
        payload = {}
    active_threads = [
        item
        for item in (normalize_autonomy_agenda_thread(candidate) for candidate in (payload.get("active_threads") or []))
        if item is not None
        and item.get("status") in {"active", "watching"}
        and not autonomy_agenda_item_is_completed_capability_probe(item)
        and not autonomy_agenda_item_is_stale(item, max_age_days=14)
    ][:6]
    tried_actions: List[Dict[str, object]] = []
    for candidate in payload.get("tried_actions") or []:
        if not isinstance(candidate, dict):
            continue
        action = normalize_text_value(candidate.get("action"), fallback="", limit=80)
        if not action:
            continue
        tried_actions.append(
            {
                "run_id": normalize_text_value(candidate.get("run_id"), fallback="", limit=80),
                "action": action,
                "family": normalize_text_value(
                    candidate.get("family"),
                    fallback=autonomy_free_run_action_family(action),
                    limit=40,
                ),
                "status": normalize_text_value(candidate.get("status"), fallback="", limit=20),
                "ok": bool(candidate.get("ok")),
                "summary": normalize_text_value(candidate.get("summary"), fallback="", limit=220),
                "timestamp": candidate.get("timestamp") or utc_now(),
            }
        )
    evidence_log: List[Dict[str, object]] = []
    for candidate in payload.get("evidence_log") or []:
        if not isinstance(candidate, dict):
            continue
        summary = normalize_text_value(candidate.get("summary"), fallback="", limit=220)
        if not summary:
            continue
        action = normalize_text_value(candidate.get("action"), fallback="", limit=80)
        evidence_log.append(
            {
                "run_id": normalize_text_value(candidate.get("run_id"), fallback="", limit=80),
                "action": action,
                "family": normalize_text_value(
                    candidate.get("family"),
                    fallback=autonomy_free_run_action_family(action),
                    limit=40,
                ),
                "summary": summary,
                "timestamp": candidate.get("timestamp") or utc_now(),
            }
        )
    saturated_items: List[Dict[str, object]] = []
    for candidate in payload.get("saturated_items") or []:
        if not isinstance(candidate, dict):
            continue
        item_id = normalize_text_value(candidate.get("id"), fallback="", limit=80)
        reason = normalize_text_value(candidate.get("reason"), fallback="", limit=220)
        if not item_id or not reason:
            continue
        saturated_items.append(
            {
                "kind": normalize_text_value(candidate.get("kind"), fallback="action", limit=20),
                "id": item_id,
                "reason": reason,
                "source_run_id": normalize_text_value(candidate.get("source_run_id"), fallback="", limit=80),
                "updated_at": candidate.get("updated_at") or utc_now(),
            }
        )
    next_experiments = [
        item
        for item in (normalize_autonomy_agenda_experiment(candidate) for candidate in (payload.get("next_experiments") or []))
        if item is not None
        and item.get("status") in {"pending", "active"}
        and not autonomy_agenda_item_is_completed_capability_probe(item)
        and not autonomy_agenda_item_is_stale(item, max_age_days=7)
    ][:4]
    evidence_backed_thread_titles = {
        str(item.get("title") or "").lower()
        for item in active_threads
        if isinstance(item, dict) and item.get("title")
    }
    next_experiments = [
        item
        for item in next_experiments
        if str(item.get("title") or "").lower() in evidence_backed_thread_titles
    ][:4]
    last_supervisor = normalize_autonomy_agenda_supervisor(payload.get("last_supervisor"))
    summary = normalize_text_value(
        payload.get("summary"),
        fallback=last_supervisor.get("verdict") or DEFAULT_AUTONOMY_AGENDA["summary"],
        limit=220,
    )
    current_focus = normalize_text_value(payload.get("current_focus"), fallback="", limit=220)
    raw_candidate_titles = {
        normalize_text_value(item.get("title"), fallback="", limit=220).lower()
        for item in [
            *(payload.get("active_threads") if isinstance(payload.get("active_threads"), list) else []),
            *(payload.get("next_experiments") if isinstance(payload.get("next_experiments"), list) else []),
        ]
        if isinstance(item, dict) and item.get("title")
    }
    surviving_titles = {
        str(item.get("title") or "").lower()
        for item in [*active_threads, *next_experiments]
        if isinstance(item, dict) and item.get("title")
    }
    if current_focus.lower() in raw_candidate_titles and current_focus.lower() not in surviving_titles:
        current_focus = ""
    if autonomy_agenda_item_is_completed_capability_probe(
        {
            "title": current_focus,
            "preferred_action": "capability_tryout",
            "family": "capability",
            "source_run_id": payload.get("last_completed_run_id"),
        }
    ):
        current_focus = ""
    if not current_focus:
        current_focus = normalize_text_value(
            (next_experiments[0].get("title") if next_experiments else "")
            or (active_threads[0].get("title") if active_threads else ""),
            fallback="",
            limit=220,
        )
    return {
        "updated_at": payload.get("updated_at"),
        "summary": summary,
        "current_focus": current_focus,
        "active_threads": active_threads,
        "tried_actions": tried_actions[-18:],
        "evidence_log": evidence_log[-18:],
        "saturated_items": saturated_items[-8:],
        "next_experiments": next_experiments,
        "last_supervisor": last_supervisor,
        "last_completed_run_id": normalize_text_value(payload.get("last_completed_run_id"), fallback="", limit=80),
    }


def load_autonomy_agenda(prefer_runtime: bool = False) -> Dict[str, object]:
    payload = AUTONOMY_AGENDA_REPOSITORY.load(prefer_runtime=prefer_runtime, default=DEFAULT_AUTONOMY_AGENDA)
    return normalize_autonomy_agenda(payload)


def save_autonomy_agenda(payload: Dict[str, object]) -> Dict[str, object]:
    normalized = normalize_autonomy_agenda({**payload, "updated_at": payload.get("updated_at") or utc_now()})
    AUTONOMY_AGENDA_REPOSITORY.save(normalized)
    return normalized


def autonomy_stage_at_least(stage: str, minimum: str) -> bool:
    return AUTONOMY_STAGES.index(stage) >= AUTONOMY_STAGES.index(minimum)


def autonomy_stage_description(stage: str) -> str:
    return {
        "observe": "Passive learning only: Eve can reflect and reply when spoken to, but daemon proposals and autonomous outreach stay off.",
        "guided": "Guided improvement: Eve can draft daemon proposals, but still cannot initiate outreach on her own.",
        "proactive": "Verified proactive mode: daemon proposals stay on and autonomous outreach is allowed once current blockers are clear.",
        "verified": "Broader verified mode: the current proactive permissions remain on, with the expectation that future autonomy expands only from this audited base.",
    }.get(stage, "No description available.")


def autonomy_stage_blockers(target_stage: str) -> List[str]:
    blockers: List[str] = []
    if target_stage in {"proactive", "verified"}:
        if not read_review_notes(limit=1, status="active", since_days=180):
            blockers.append("No active outside reviewer note is recorded yet.")
        if not read_version_snapshots(limit=1, since_days=365):
            blockers.append("No prompt or memory version snapshot is recorded yet.")
        if read_failure_clusters(limit=1, status="open", since_days=120):
            blockers.append("There are still open failure clusters waiting for repair.")
        # Stage E: the user's manual probe — not Eve's self-scored bank — gates
        # autonomy expansion. A fresh passing human probe is required so the
        # gate can never be satisfied by a self-graded evaluation.
        if fresh_passing_user_manual_probe(prefer_runtime=True) is None:
            blockers.append("No fresh passing manual probe from the user (≤30 days, avg≥3, min≥3) is recorded yet.")
    if target_stage == "verified" and not read_evaluations(limit=1, since_days=60):
        blockers.append("No structured evaluation has been recorded yet for the current loop.")
    return blockers


def autonomy_action_block_reason(action: str) -> Optional[str]:
    state = load_autonomy_state()
    stage = str(state["stage"])
    if action == "daemon_proposal":
        if not autonomy_stage_at_least(stage, "guided"):
            return f"Autonomy stage `{stage}` only allows observation and direct replies. Daemon proposals start at `guided`."
        return None
    if action == "daemon_outreach":
        if not autonomy_stage_at_least(stage, "proactive"):
            return f"Autonomy stage `{stage}` does not allow autonomous outreach yet. Outreach starts at `proactive`."
        blockers = autonomy_stage_blockers("proactive")
        if blockers:
            return "Autonomous outreach is still gated: " + " ".join(blockers)
        return None
    if action == "daemon_local_conversation":
        # This is local-only speech into Eve Monitor, not external outreach.
        # Eve should be able to choose a personal conversation without the user
        # pressing a wake/speak button first.
        return None
    return None


def trim_context_block(text: str, max_chars: int) -> str:
    cleaned = text.strip()
    if not cleaned or max_chars <= 0 or len(cleaned) <= max_chars:
        return cleaned
    clipped = cleaned[:max_chars].rstrip()
    last_break = clipped.rfind("\n")
    if last_break >= max_chars // 2:
        clipped = clipped[:last_break].rstrip()
    return clipped


def load_project_memory(max_chars: int) -> str:
    if not PROJECT_MEMORY_PATH.exists():
        return ""
    return trim_context_block(PROJECT_MEMORY_PATH.read_text(encoding="utf-8"), max_chars=max_chars)


def build_project_memory_message(project_memory: str) -> str:
    return textwrap.dedent(
        f"""
        Durable project memory imported from prior conversations and notes:
        Use this as long-horizon context about what Eve is trying to become and how the project is supposed to improve.
        Prefer newer evidence if it directly contradicts this memory.

        {project_memory.strip()}
        """
    ).strip()


def split_markdown_memory_sections(text: str, *, max_sections: int = 8, chunk_chars: int = 520) -> List[Dict[str, str]]:
    sections: List[Dict[str, str]] = []
    current_title = "Project Memory"
    current_lines: List[str] = []

    def flush() -> None:
        nonlocal current_lines
        body = "\n".join(current_lines).strip()
        current_lines = []
        if not body:
            return
        paragraphs = [item.strip() for item in body.split("\n\n") if item.strip()]
        if not paragraphs:
            paragraphs = [body]
        chunk_index = 0
        current_chunk = ""
        for paragraph in paragraphs:
            proposed = f"{current_chunk}\n\n{paragraph}".strip() if current_chunk else paragraph
            if current_chunk and len(proposed) > chunk_chars:
                chunk_index += 1
                sections.append(
                    {
                        "title": f"{current_title} ({chunk_index})" if chunk_index > 1 else current_title,
                        "text": trim_context_block(current_chunk, chunk_chars),
                    }
                )
                current_chunk = paragraph
            else:
                current_chunk = proposed
        if current_chunk:
            chunk_index += 1
            sections.append(
                {
                    "title": f"{current_title} ({chunk_index})" if chunk_index > 1 else current_title,
                    "text": trim_context_block(current_chunk, chunk_chars),
                }
            )

    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if line.startswith("#"):
            flush()
            current_title = line.lstrip("#").strip() or "Project Memory"
        else:
            current_lines.append(line)
    flush()
    return sections[:max_sections]


def build_memory_note(note_id: str, source: str, title: str, text: str, tags: Optional[List[str]] = None) -> Optional[Dict[str, object]]:
    normalized_text = normalize_text_value(text, fallback="", limit=1200)
    normalized_title = normalize_text_value(title, fallback=source, limit=120)
    if not normalized_text:
        return None
    cleaned_tags = [
        normalize_text_value(item, fallback="", limit=40)
        for item in (tags or [])
        if normalize_text_value(item, fallback="", limit=40)
    ]
    return {
        "id": note_id,
        "source": source,
        "title": normalized_title,
        "text": normalized_text,
        "tags": cleaned_tags,
    }


def build_message_memory_notes(prefer_runtime: bool = False, limit: int = 32) -> List[Dict[str, object]]:
    notes: List[Dict[str, object]] = []
    for message in read_lived_messages(limit=limit, prefer_runtime=prefer_runtime):
        message_id = normalize_text_value(message.get("id"), fallback="", limit=80) or sha256_text(
            json.dumps(message, sort_keys=True, ensure_ascii=True)
        )[:12]
        subject = normalize_text_value(message.get("subject"), fallback="Message", limit=100)
        sender = normalize_text_value(message.get("sender"), fallback="unknown", limit=40)
        recipient = normalize_text_value(message.get("recipient"), fallback="unknown", limit=40)
        thread_id = normalize_text_value(message.get("thread_id"), fallback="", limit=80)
        self_authored_output = sender.lower() == "eve"
        authority = (
            "Self-authored output. This records what Eve said; it is not a current observation, "
            "verified action, or established fact unless independent evidence corroborates it."
            if self_authored_output
            else "External conversation signal. This records what the sender said; embedded claims still require verification."
        )
        note = build_memory_note(
            f"message:{message_id}",
            "message",
            subject,
            textwrap.dedent(
                f"""
                Timestamp: {message_record_timestamp(message)}
                Thread: {thread_id or 'none recorded'}
                Route: {sender} -> {recipient}
                Status: {message.get('status') or 'unknown'}
                Authority: {authority}
                Subject: {subject}
                Body: {message.get('body') or ''}
                """
            ).strip(),
            tags=[
                "message",
                sender,
                recipient,
                "self_output" if self_authored_output else "external_signal",
            ],
        )
        if note:
            notes.append(note)
    return notes


