def build_experience_memory_notes(prefer_runtime: bool = False, limit: int = 32) -> List[Dict[str, object]]:
    notes: List[Dict[str, object]] = []
    for event in read_experience_events(limit=limit, prefer_runtime=prefer_runtime):
        event_id = normalize_text_value(event.get("id"), fallback="", limit=80) or sha256_text(
            json.dumps(event, sort_keys=True, ensure_ascii=True)
        )[:12]
        event_type = normalize_text_value(event.get("event_type"), fallback="experience", limit=60)
        summary = normalize_text_value(event.get("summary"), fallback="Experience event", limit=100)
        event_source = normalize_text_value(event.get("source"), fallback="", limit=120).lower()
        actor = normalize_text_value(event.get("actor"), fallback="unknown", limit=40).lower()
        result = normalize_text_value(event.get("result"), fallback="", limit=220)
        self_output_without_consequence = bool(
            actor == "eve"
            and event_source.startswith("message:")
            and not result
        )
        authority = (
            "Self-authored message event without an observed consequence; preserve it as output history, not lived evidence."
            if self_output_without_consequence
            else "Experience record; use its recorded result and verification boundary when drawing conclusions."
        )
        note = build_memory_note(
            f"experience:{event_id}",
            "experience",
            summary,
            textwrap.dedent(
                f"""
                Created: {event.get('created_at') or event.get('timestamp') or 'unknown'}
                Type: {event_type}
                Actor: {event.get('actor') or 'unknown'}
                Authority: {authority}
                Subject: {event.get('subject') or 'not recorded'}
                Prediction: {event.get('prediction') or 'not recorded'}
                Result: {event.get('result') or 'not recorded'}
                Learning: {event.get('learning') or 'not recorded'}
                Summary: {event.get('summary') or 'not recorded'}
                """
            ).strip(),
            tags=[
                "experience",
                event_type,
                "self_output" if self_output_without_consequence else "lived_evidence",
            ],
        )
        if note:
            notes.append(note)
    return notes


