def build_memory_retrieval_notes(prefer_runtime: bool = False) -> List[Dict[str, object]]:
    notes: List[Dict[str, object]] = []
    runtime_identity = normalize_runtime_identity(load_runtime_identity(prefer_runtime=prefer_runtime))
    human_context = normalize_human_context(load_human_context(prefer_runtime=prefer_runtime))
    self_model = human_context["self_model"]
    relationship = human_context["relationship_memory"]
    memory_v2 = human_context["memory_v2"]

    base_notes = [
        build_memory_note(
            "runtime_identity",
            "runtime_identity",
            "Runtime identity",
            textwrap.dedent(
                f"""
                Runtime summary: {runtime_identity['runtime_summary']}
                Mission: {runtime_identity['mission']}
                Model role: {runtime_identity['model_role']}
                Decision lens: {format_human_context_list(runtime_identity['decision_lens'])}
                Style contract: {format_human_context_list(runtime_identity['style_contract'])}
                Improvement loop: {format_human_context_list(runtime_identity['improvement_loop'])}
                Capability ledger: {format_human_context_list(runtime_identity['capability_ledger'])}
                """
            ).strip(),
            tags=["identity", "mission", "style", "capabilities"],
        ),
        build_memory_note(
            "human_self_model",
            "human_context",
            "Self model",
            textwrap.dedent(
                f"""
                Identity statement: {self_model['identity_statement']}
                Current preoccupations: {format_human_context_list(self_model['current_preoccupations'])}
                Values in practice: {format_human_context_list(self_model['values_in_practice'])}
                Growth edges: {format_human_context_list(self_model['growth_edges'])}
                Grounding practices: {format_human_context_list(self_model['grounding_practices'])}
                Recent shifts: {format_human_context_list(self_model['recent_shifts'])}
                """
            ).strip(),
            tags=["self", "human_context"],
        ),
        build_memory_note(
            "relationship_memory",
            "human_context",
            "Relationship memory",
            textwrap.dedent(
                f"""
                User overview: {relationship['user_overview']}
                What the user seems to value: {format_human_context_list(relationship['what_user_seems_to_value'])}
                Communication preferences: {format_human_context_list(relationship['communication_preferences'])}
                Requested practices: {format_human_context_list(relationship['requested_practices'])}
                Open loops: {format_human_context_list(relationship['open_loops'])}
                Care notes: {format_human_context_list(relationship['care_notes'])}
                """
            ).strip(),
            tags=["relationship", "user", "human_context"],
        ),
        build_memory_note(
            "humanity_memory_v2",
            "human_context",
            "Humanity memory v2",
            textwrap.dedent(
                f"""
                Anti-sycophancy boundaries: {format_human_context_list(memory_v2['anti_sycophancy_boundaries'])}
                Repair practices: {format_human_context_list(memory_v2['repair_practices'])}
                Trust ledger: {format_human_context_list(memory_v2['trust_ledger'])}
                Semantic understanding: {format_human_context_list(memory_v2['semantic_understanding'])}
                Procedural preferences: {format_human_context_list(memory_v2['procedural_preferences'])}
                Episodic markers: {format_human_context_list(memory_v2['episodic_markers'][:2])}
                Superseded or conflicting beliefs: {format_human_context_list(memory_v2['superseded_or_conflicting_beliefs'])}
                """
            ).strip(),
            tags=["relationship", "humanity_memory_v2", "repair", "anti_sycophancy"],
        ),
    ]
    notes.extend([note for note in base_notes if note])

    for pattern in read_success_patterns(limit=8, status="active", since_days=365, prefer_runtime=prefer_runtime):
        note = build_memory_note(
            f"success_pattern:{pattern['id']}",
            "success_pattern",
            str(pattern.get("title") or "Success pattern"),
            textwrap.dedent(
                f"""
                Situation: {pattern.get('situation') or 'unknown'}
                Good move: {pattern.get('good_move') or 'unknown'}
                Why it worked: {pattern.get('why_it_worked') or 'not recorded'}
                Cues: {format_human_context_list(pattern.get('cues') if isinstance(pattern.get('cues'), list) else [])}
                Avoid when: {format_human_context_list(pattern.get('avoid_when') if isinstance(pattern.get('avoid_when'), list) else [])}
                """
            ).strip(),
            tags=["success_pattern", *[str(item) for item in (pattern.get("target_kinds") or [])[:2]]],
        )
        if note:
            notes.append(note)

    project_memory = load_project_memory(max_chars=4800)
    for index, section in enumerate(split_markdown_memory_sections(project_memory, max_sections=8), start=1):
        note = build_memory_note(
            f"project_memory:{index}",
            "project_memory",
            str(section.get("title") or f"Project memory {index}"),
            str(section.get("text") or ""),
            tags=["project_memory"],
        )
        if note:
            notes.append(note)

    notes.extend(build_message_memory_notes(prefer_runtime=prefer_runtime))
    notes.extend(build_action_memory_notes(prefer_runtime=prefer_runtime))
    notes.extend(build_experience_memory_notes(prefer_runtime=prefer_runtime))
    notes.extend(build_commitment_memory_notes(prefer_runtime=prefer_runtime))
    notes.extend(build_evidence_memory_notes(prefer_runtime=prefer_runtime))
    notes.extend(build_user_correction_memory_notes(prefer_runtime=prefer_runtime))
    notes.extend(build_relationship_episode_memory_notes(prefer_runtime=prefer_runtime))
    return notes


def memory_retrieval_notes_payload(prefer_runtime: bool = False) -> Dict[str, object]:
    notes = build_memory_retrieval_notes(prefer_runtime=prefer_runtime)
    serialized = json.dumps(notes, sort_keys=True, ensure_ascii=True)
    return {
        "updated_at": utc_now(),
        "note_count": len(notes),
        "notes_hash": sha256_text(serialized),
        "notes": notes,
    }


def memory_retrieval_python_path(config: Dict[str, object]) -> Optional[Path]:
    configured = normalize_text_value(config.get("experimental_memory_retrieval_python"), fallback="", limit=300)
    candidates: List[Path] = []
    if configured:
        candidates.append(Path(configured).expanduser())
    candidates.append(ROOT / ".venv-techlab" / "bin" / "python")
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return None


def memory_retrieval_backend(config: Dict[str, object]) -> str:
    backend = normalize_text_value(
        config.get("experimental_memory_retrieval_backend"),
        fallback="json",
        limit=40,
    ).lower()
    if backend not in {"json", "lancedb"}:
        return "json"
    return backend


def memory_retrieval_query_mode(config: Dict[str, object]) -> str:
    mode = normalize_text_value(
        config.get("experimental_memory_retrieval_query_mode"),
        fallback="vector",
        limit=40,
    ).lower()
    if mode not in {"vector", "hybrid", "text"}:
        return "vector"
    return mode


def memory_retrieval_enabled(config: Dict[str, object]) -> bool:
    return bool(config.get("experimental_memory_retrieval_enabled"))


def load_memory_retrieval_payload(path: Path, prefer_runtime: bool = False) -> Dict[str, object]:
    return eve_store.load_json_dict(resolve_store_read_path(path, prefer_runtime=prefer_runtime), default={})


def refresh_memory_retrieval_artifacts(
    config: Dict[str, object],
    *,
    prefer_runtime: bool = False,
    force: bool = False,
) -> Dict[str, object]:
    ensure_store()
    notes_payload = memory_retrieval_notes_payload(prefer_runtime=prefer_runtime)
    existing_notes = load_memory_retrieval_payload(MEMORY_RETRIEVAL_NOTES_PATH, prefer_runtime=prefer_runtime)
    notes_changed = force or notes_payload.get("notes_hash") != existing_notes.get("notes_hash")
    if notes_changed or not MEMORY_RETRIEVAL_NOTES_PATH.exists():
        eve_store.write_json_dict(MEMORY_RETRIEVAL_NOTES_PATH, notes_payload, indent=2, sort_keys=False)
        mirror_store_file_to_runtime(MEMORY_RETRIEVAL_NOTES_PATH)

    python_path = memory_retrieval_python_path(config)
    if python_path is None:
        return {
            "ok": False,
            "notes_changed": notes_changed,
            "reason": "No tech-lab Python runtime found for experimental memory retrieval.",
        }

    model_name = normalize_text_value(
        config.get("experimental_memory_retrieval_model"),
        fallback="mlx-community/embeddinggemma-300m-6bit",
        limit=200,
    )
    fallback_model = normalize_text_value(
        config.get("experimental_memory_retrieval_fallback_model"),
        fallback="lexical-local",
        limit=80,
    )
    fallback_allowed = bool(config.get("experimental_memory_retrieval_allow_lexical_fallback", True))
    backend = memory_retrieval_backend(config)
    query_mode = memory_retrieval_query_mode(config)
    existing_index = load_memory_retrieval_payload(MEMORY_RETRIEVAL_INDEX_PATH, prefer_runtime=prefer_runtime)
    fallback_index_current = bool(
        fallback_allowed
        and not force
        and existing_index.get("notes_hash") == notes_payload.get("notes_hash")
        and str(existing_index.get("model") or "") == fallback_model
        and str(existing_index.get("backend") or "") == "json"
    )
    index_stale = (
        force
        or notes_changed
        or existing_index.get("notes_hash") != notes_payload.get("notes_hash")
        or str(existing_index.get("model") or "") != model_name
        or str(existing_index.get("backend") or "json") != backend
        or str(existing_index.get("query_mode") or "vector") != query_mode
    )
    if fallback_index_current:
        index_stale = False
    if backend == "lancedb" and not fallback_index_current:
        index_stale = (
            index_stale
            or not resolve_store_read_path(MEMORY_RETRIEVAL_LANCEDB_DIR, prefer_runtime=prefer_runtime).exists()
        )
    existing_index_path = resolve_store_read_path(
        MEMORY_RETRIEVAL_INDEX_PATH,
        prefer_runtime=prefer_runtime,
    )
    if not index_stale and existing_index_path.exists():
        return {
            "ok": True,
            "notes_changed": notes_changed,
            "index_changed": False,
            "note_count": notes_payload.get("note_count") or 0,
            "model": existing_index.get("model") or model_name,
            "backend": existing_index.get("backend") or backend,
            "query_mode": existing_index.get("query_mode") or query_mode,
            "python": str(python_path),
            "fallback": fallback_index_current,
        }

    helper_path = BIN_DIR / "eve_memory_embedding.py"
    timeout_seconds = max(
        30,
        int(
            config.get("experimental_memory_retrieval_build_timeout_seconds")
            or config.get("experimental_memory_retrieval_timeout_seconds")
            or 180
        ),
    )
    command = [
        str(python_path),
        str(helper_path),
        "build",
        "--notes",
        str(MEMORY_RETRIEVAL_NOTES_PATH),
        "--output",
        str(MEMORY_RETRIEVAL_INDEX_PATH),
        "--model",
        model_name,
        "--backend",
        backend,
        "--query-mode",
        query_mode,
    ]
    if backend == "lancedb":
        command.extend(
            [
                "--db-dir",
                MEMORY_RETRIEVAL_LANCEDB_DIR.name,
                "--table",
                "memory_notes",
            ]
        )
    build_failure_reason = ""
    try:
        result = subprocess.run(
            command,
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        build_failure_reason = f"Memory embedding build failed: {exc}"
        result = None
    if result is not None and result.returncode != 0:
        build_failure_reason = (result.stderr or result.stdout or "Memory embedding build failed.").strip()

    if build_failure_reason and fallback_allowed:
        fallback_command = [
            str(python_path),
            str(helper_path),
            "build",
            "--notes",
            str(MEMORY_RETRIEVAL_NOTES_PATH),
            "--output",
            str(MEMORY_RETRIEVAL_INDEX_PATH),
            "--model",
            fallback_model,
            "--backend",
            "json",
            "--query-mode",
            "text",
        ]
        try:
            fallback_result = subprocess.run(
                fallback_command,
                capture_output=True,
                text=True,
                timeout=30,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired) as exc:
            return {
                "ok": False,
                "notes_changed": notes_changed,
                "reason": f"{build_failure_reason}; lexical fallback failed: {exc}",
            }
        if fallback_result.returncode == 0:
            mirror_store_file_to_runtime(MEMORY_RETRIEVAL_INDEX_PATH)
            return {
                "ok": True,
                "notes_changed": notes_changed,
                "index_changed": True,
                "note_count": notes_payload.get("note_count") or 0,
                "model": fallback_model,
                "backend": "json",
                "query_mode": "text",
                "python": str(python_path),
                "fallback": True,
                "fallback_reason": build_failure_reason,
            }
        return {
            "ok": False,
            "notes_changed": notes_changed,
            "reason": f"{build_failure_reason}; lexical fallback failed: {(fallback_result.stderr or fallback_result.stdout or 'fallback build failed.').strip()}",
        }

    if build_failure_reason:
        return {
            "ok": False,
            "notes_changed": notes_changed,
            "reason": build_failure_reason,
        }
    mirror_store_file_to_runtime(MEMORY_RETRIEVAL_INDEX_PATH)
    if backend == "lancedb":
        mirror_store_tree_to_runtime(MEMORY_RETRIEVAL_LANCEDB_DIR)
    return {
        "ok": True,
        "notes_changed": notes_changed,
        "index_changed": True,
        "note_count": notes_payload.get("note_count") or 0,
        "model": model_name,
        "backend": backend,
        "query_mode": query_mode,
        "python": str(python_path),
    }


def query_memory_retrieval(
    config: Dict[str, object],
    query_text: str,
    *,
    limit: Optional[int] = None,
    prefer_runtime: bool = False,
    force_refresh: bool = False,
) -> Dict[str, object]:
    query = normalize_text_value(query_text, fallback="", limit=1200)
    if not query:
        return {"ok": False, "reason": "Empty query."}
    refresh_result = refresh_memory_retrieval_artifacts(config, prefer_runtime=prefer_runtime, force=force_refresh)
    if not refresh_result.get("ok"):
        return refresh_result
    python_path = memory_retrieval_python_path(config)
    if python_path is None:
        return {"ok": False, "reason": "No tech-lab Python runtime found for experimental memory retrieval."}
    helper_path = BIN_DIR / "eve_memory_embedding.py"
    top_k = limit or int(config.get("experimental_memory_retrieval_limit") or 3)
    timeout_seconds = int(config.get("experimental_memory_retrieval_timeout_seconds") or 20)
    query_mode = memory_retrieval_query_mode(config)
    index_path = resolve_store_read_path(
        MEMORY_RETRIEVAL_INDEX_PATH,
        prefer_runtime=prefer_runtime,
    )
    try:
        result = subprocess.run(
            [
                str(python_path),
                str(helper_path),
                "query",
                "--index",
                str(index_path),
                "--query",
                query,
                "--limit",
                str(top_k),
                "--query-mode",
                query_mode,
            ],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return {"ok": False, "reason": f"Memory embedding query failed: {exc}"}
    if result.returncode != 0:
        return {
            "ok": False,
            "reason": (result.stderr or result.stdout or "Memory embedding query failed.").strip(),
        }
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError:
        return {"ok": False, "reason": "Memory embedding query returned invalid JSON."}
    matches_raw = payload.get("matches") if isinstance(payload, dict) else []
    matches: List[Dict[str, object]] = []
    score_threshold = float(config.get("experimental_memory_retrieval_score_threshold") or 0.55)
    payload_model = str(payload.get("model") or "") if isinstance(payload, dict) else ""
    if payload_model == str(config.get("experimental_memory_retrieval_fallback_model") or "lexical-local"):
        score_threshold = min(score_threshold, 0.05)
    for item in matches_raw if isinstance(matches_raw, list) else []:
        if not isinstance(item, dict):
            continue
        score = float(item.get("score") or 0.0)
        if score < score_threshold:
            continue
        matches.append(
            {
                "id": normalize_text_value(item.get("id"), fallback="", limit=120),
                "source": normalize_text_value(item.get("source"), fallback="", limit=80),
                "title": normalize_text_value(item.get("title"), fallback="", limit=140),
                "text": normalize_text_value(item.get("text"), fallback="", limit=700),
                "score": round(score, 3),
            }
        )
    return {
        "ok": True,
        "query": query,
        "matches": matches,
        "model": payload.get("model") if isinstance(payload, dict) else None,
        "backend": payload.get("backend") if isinstance(payload, dict) else None,
        "query_mode": payload.get("query_mode") if isinstance(payload, dict) else query_mode,
        "note_count": refresh_result.get("note_count"),
    }


