def text_contains_any_keyword(text: str, keywords: Iterable[str]) -> bool:
    haystack = normalize_text_value(text, fallback="", limit=4000).lower()
    return any(keyword in haystack for keyword in keywords)


def classify_memory_query(query_text: str) -> Dict[str, bool]:
    query = normalize_text_value(query_text, fallback="", limit=1600).lower()
    system_focused = text_contains_any_keyword(query, MEMORY_RETRIEVAL_SYSTEM_KEYWORDS)
    relational = text_contains_any_keyword(query, MEMORY_RETRIEVAL_RELATIONAL_KEYWORDS)
    return {
        "system_focused": system_focused,
        "relational": relational,
        "user_facing": not system_focused,
    }


def default_prompt_context_profile(query_text: str) -> Dict[str, object]:
    profile = classify_memory_query(query_text)
    if profile["system_focused"]:
        selected = "system_internal"
        reason = "query is explicitly about Eve internals, runtime, models, or implementation details"
    elif profile["relational"]:
        selected = "user_relational"
        reason = "query is tone-sensitive or relational and should avoid heavy internal context"
    else:
        selected = "user_general"
        reason = "query appears outward-facing but not specifically relational"
    return {
        "ok": True,
        "source": "heuristic",
        "profile": selected,
        "reason": reason,
    }


def prompt_router_python_path(config: Dict[str, object]) -> Optional[Path]:
    configured = normalize_text_value(config.get("experimental_prompt_router_python"), fallback="", limit=300)
    candidates: List[Path] = []
    if configured:
        candidates.append(Path(configured).expanduser())
    fallback = memory_retrieval_python_path(config)
    if fallback is not None:
        candidates.append(fallback)
    candidates.append(ROOT / ".venv-techlab" / "bin" / "python")
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return None


def prompt_router_enabled(config: Dict[str, object]) -> bool:
    return bool(config.get("experimental_prompt_router_enabled"))


def normalize_prompt_context_profile(value: object) -> str:
    profile = normalize_text_value(value, fallback="", limit=40).lower()
    if profile not in {"user_relational", "user_general", "system_internal"}:
        return "user_general"
    return profile


def route_prompt_context(config: Dict[str, object], query_text: str) -> Dict[str, object]:
    query = normalize_text_value(query_text, fallback="", limit=1200)
    fallback = default_prompt_context_profile(query)
    if fallback["profile"] in {"system_internal", "user_relational"}:
        return {**fallback, "source": "heuristic_strong"}
    if not query or not prompt_router_enabled(config):
        return fallback
    python_path = prompt_router_python_path(config)
    if python_path is None:
        return {**fallback, "ok": False, "source": "heuristic_missing_runtime"}
    helper_path = BIN_DIR / "eve_prompt_router.py"
    model_name = normalize_text_value(
        config.get("experimental_prompt_router_model"),
        fallback="mlx-community/gemma-3-270m-it-6bit",
        limit=200,
    )
    timeout_seconds = int(config.get("experimental_prompt_router_timeout_seconds") or 12)
    try:
        result = subprocess.run(
            [
                str(python_path),
                str(helper_path),
                "route",
                "--model",
                model_name,
                "--message",
                query,
            ],
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            check=False,
        )
    except (OSError, subprocess.TimeoutExpired):
        return {**fallback, "ok": False, "source": "heuristic_timeout"}
    if result.returncode != 0:
        return {
            **fallback,
            "ok": False,
            "source": "heuristic_failed",
            "raw_output": normalize_text_value(result.stdout, fallback="", limit=300),
            "error": normalize_text_value(result.stderr, fallback="", limit=300),
        }
    try:
        payload = json.loads(result.stdout)
    except json.JSONDecodeError:
        return {**fallback, "ok": False, "source": "heuristic_invalid_json"}
    profile = normalize_prompt_context_profile(payload.get("profile"))
    reason = normalize_text_value(payload.get("reason"), fallback=fallback["reason"], limit=220)
    total_seconds = payload.get("total_seconds")
    return {
        "ok": bool(payload.get("ok")),
        "source": "mlx_router",
        "profile": profile,
        "reason": reason,
        "model": model_name,
        "total_seconds": total_seconds if isinstance(total_seconds, (int, float)) else None,
        "raw_output": normalize_text_value(payload.get("raw_output"), fallback="", limit=260),
    }


def memory_match_infra_heavy(match: Dict[str, object]) -> bool:
    source = normalize_text_value(match.get("source"), fallback="", limit=80)
    title = normalize_text_value(match.get("title"), fallback="", limit=160)
    text = normalize_text_value(match.get("text"), fallback="", limit=1200)
    if source in {"runtime_identity"}:
        return True
    if source == "project_memory" and text_contains_any_keyword(f"{title} {text}", MEMORY_RETRIEVAL_INFRA_KEYWORDS):
        return True
    return text_contains_any_keyword(f"{title} {text}", MEMORY_RETRIEVAL_INFRA_KEYWORDS)


def curate_memory_retrieval_matches(
    matches: List[Dict[str, object]],
    query_text: str,
    *,
    limit: int,
) -> List[Dict[str, object]]:
    if not matches:
        return []
    profile = classify_memory_query(query_text)
    ranked: List[Dict[str, object]] = []
    for match in matches:
        score = float(match.get("score") or 0.0)
        source = normalize_text_value(match.get("source"), fallback="", limit=80)
        match_id = normalize_text_value(match.get("id"), fallback="", limit=120)
        title = normalize_text_value(match.get("title"), fallback="", limit=160)
        text = normalize_text_value(match.get("text"), fallback="", limit=1200)
        infra_heavy = memory_match_infra_heavy(match)
        adjusted = score
        if profile["system_focused"]:
            if source == "runtime_identity":
                adjusted += 0.14
            elif source == "project_memory":
                adjusted += 0.05
        else:
            if source == "success_pattern":
                adjusted += 0.16
            elif source == "human_context":
                adjusted += 0.12
            elif source == "runtime_identity":
                adjusted -= 0.12
            elif source == "project_memory":
                adjusted -= 0.05
            if infra_heavy:
                adjusted -= 0.22
            if profile["relational"]:
                if source == "success_pattern":
                    adjusted += 0.08
                if match_id in {"human_self_model", "relationship_memory"}:
                    adjusted += 0.1
                if "requested practices:" in text.lower() or "communication preferences:" in text.lower():
                    adjusted += 0.05
                if "runtime summary:" in text.lower() or "model role:" in text.lower():
                    adjusted -= 0.12
        ranked.append(
            {
                **match,
                "_adjusted_score": round(adjusted, 6),
                "_infra_heavy": infra_heavy,
                "_source": source,
                "_title": title,
            }
        )

    ranked.sort(key=lambda item: float(item.get("_adjusted_score") or 0.0), reverse=True)
    preferred = ranked if profile["system_focused"] else [item for item in ranked if not item.get("_infra_heavy")]
    fallback = [] if profile["system_focused"] else [item for item in ranked if item.get("_infra_heavy")]
    source_limits = {"success_pattern": 2, "human_context": 2, "project_memory": 1, "runtime_identity": 1}
    selected: List[Dict[str, object]] = []
    source_counts: Dict[str, int] = {}
    for pool in [preferred, fallback]:
        for item in pool:
            source = str(item.get("_source") or "")
            max_per_source = source_limits.get(source, 1)
            if source_counts.get(source, 0) >= max_per_source:
                continue
            selected.append(
                {
                    "id": item.get("id"),
                    "source": item.get("source"),
                    "title": item.get("title"),
                    "text": item.get("text"),
                    "score": round(float(item.get("_adjusted_score") or item.get("score") or 0.0), 3),
                }
            )
            source_counts[source] = source_counts.get(source, 0) + 1
            if len(selected) >= max(1, limit):
                return selected
    return selected[: max(1, limit)]


def build_memory_retrieval_message(matches: List[Dict[str, object]], *, query_text: str = "", compact: bool = False) -> str:
    profile = classify_memory_query(query_text)
    lines = []
    for item in matches:
        text_limit = 220 if compact else 320
        note_text = trim_context_block(normalize_text_value(item.get("text"), fallback="", limit=900), max_chars=text_limit)
        lines.append(
            f"- {item.get('title') or item.get('source')}: {note_text}"
        )
    if profile["system_focused"]:
        guidance = "Use these notes as durable internal context. It is okay to talk about runtime or model details because the user is asking about internals."
    else:
        guidance = "Prefer relationship, success-pattern, and requested-practice notes over runtime self-description. Do not mention models, tools, latency, or system state unless the user asked about internals."
    return textwrap.dedent(
        f"""
        Relevant durable memory hints for this turn:
        {chr(10).join(lines) if lines else "- No relevant retrieved memory."}

        Use these retrieved notes only when they genuinely fit the present turn.
        Treat them as retrieval hints from Eve's own durable stores, not rigid instructions.
        {guidance}
        """
    ).strip()


def active_mind_retrieval_query(active_mind: Optional[Dict[str, object]]) -> Optional[str]:
    """Background cognition's retrieval query = her current focus, so mind ticks,
    outreach, reflection, and proposals run memory-aware instead of memory-blind
    (retrieval previously reached only the reactive reply path)."""
    if not isinstance(active_mind, dict):
        return None
    focus = normalize_text_value(active_mind.get("current_focus"), fallback="", limit=400)
    return focus or None


def memory_retrieval_system_message(
    config: Dict[str, object],
    query_text: Optional[str],
    *,
    prefer_runtime: bool = False,
    compact: bool = False,
) -> Optional[Dict[str, str]]:
    if not memory_retrieval_enabled(config):
        return None
    query = normalize_text_value(query_text, fallback="", limit=1200)
    if not query:
        return None
    payload = query_memory_retrieval(
        config,
        query,
        limit=int(config.get("experimental_memory_retrieval_limit") or 3),
        prefer_runtime=prefer_runtime,
    )
    if not payload.get("ok"):
        return None
    matches = payload.get("matches") if isinstance(payload.get("matches"), list) else []
    if not matches:
        return None
    limit = int(config.get("experimental_memory_retrieval_limit") or 3)
    curated_matches = curate_memory_retrieval_matches(matches, query, limit=limit)
    if not curated_matches:
        return None
    message = build_memory_retrieval_message(curated_matches, query_text=query, compact=compact)
    max_chars = int(config.get("experimental_memory_retrieval_max_chars") or 900)
    if compact:
        max_chars = min(max_chars, 560)
    return {"role": "system", "content": trim_context_block(message, max_chars=max_chars)}


def project_memory_system_message(config: Dict[str, object], compact: bool = False) -> Optional[Dict[str, str]]:
    max_chars = int(config["project_memory_max_chars"])
    if compact:
        max_chars = min(max_chars, 900)
    project_memory = load_project_memory(max_chars=max_chars)
    if not project_memory:
        return None
    return {"role": "system", "content": build_project_memory_message(project_memory)}


def load_system_snapshot(prefer_runtime: bool = False) -> Dict[str, object]:
    read_path = resolve_store_read_path(SYSTEM_SNAPSHOT_PATH, prefer_runtime=prefer_runtime)
    if not read_path.exists():
        return {}
    try:
        payload = json.loads(read_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    return payload if isinstance(payload, dict) else {}


def load_model_watchdog_status(prefer_runtime: bool = False) -> Dict[str, object]:
    read_path = resolve_store_read_path(MODEL_WATCHDOG_STATUS_PATH, prefer_runtime=prefer_runtime)
    if not read_path.exists():
        return {}
    try:
        payload = json.loads(read_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    return payload if isinstance(payload, dict) else {}


def minutes_since_timestamp(value: object) -> Optional[float]:
    moment = parse_iso_datetime(value)
    if moment is None:
        return None
    return max(0.0, (datetime.now(timezone.utc) - moment).total_seconds() / 60.0)


def format_duration_compact_seconds(total_seconds: object) -> str:
    try:
        seconds = max(0, int(float(total_seconds)))
    except (TypeError, ValueError):
        return "unknown"
    if seconds < 60:
        return f"{seconds}s"
    minutes, secs = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes}m {secs}s" if secs else f"{minutes}m"
    hours, mins = divmod(minutes, 60)
    if hours < 24:
        return f"{hours}h {mins}m" if mins else f"{hours}h"
    days, hrs = divmod(hours, 24)
    return f"{days}d {hrs}h" if hrs else f"{days}d"


def normalize_operator_authorization_record(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    record = {**DEFAULT_OPERATOR_AUTHORIZATION, **(payload or {})}
    scope = str(record.get("scope") or "broad_safe").strip()
    if scope not in OPERATOR_AUTHORIZATION_SCOPES:
        scope = "broad_safe"
    scope_spec = OPERATOR_AUTHORIZATION_SCOPES[scope]
    record["scope"] = scope
    record["status"] = "active" if str(record.get("status") or "").lower() == "active" else "inactive"
    record["active"] = bool(record.get("status") == "active")
    record["granted_by"] = normalize_text_value(record.get("granted_by"), fallback="", limit=80)
    record["note"] = normalize_text_value(record.get("note"), fallback="", limit=320)
    record["allowed_without_extra_prompt"] = list(scope_spec["allowed_without_extra_prompt"])
    record["still_requires_specific_approval"] = list(scope_spec["still_requires_specific_approval"])
    return record


def load_operator_authorization(prefer_runtime: bool = False) -> Dict[str, object]:
    path = resolve_store_read_path(OPERATOR_AUTHORIZATION_PATH, prefer_runtime=prefer_runtime)
    payload = eve_store.load_json_dict(path, DEFAULT_OPERATOR_AUTHORIZATION)
    return normalize_operator_authorization_record(payload)


def operator_authorization_is_active(
    record: Optional[Dict[str, object]] = None,
    *,
    now: Optional[datetime] = None,
) -> bool:
    authorization = normalize_operator_authorization_record(record or {})
    if authorization.get("status") != "active":
        return False
    expires_at = parse_iso_datetime(authorization.get("expires_at"))
    if expires_at is None:
        return True
    current = now or datetime.now(timezone.utc)
    return expires_at >= current


def save_operator_authorization(record: Dict[str, object]) -> Dict[str, object]:
    authorization = normalize_operator_authorization_record(record)
    authorization["active"] = operator_authorization_is_active(authorization)
    if not authorization["active"] and authorization.get("status") == "active":
        authorization["status"] = "inactive"
    authorization["updated_at"] = utc_now()
    eve_store.write_json_dict(OPERATOR_AUTHORIZATION_PATH, authorization, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(OPERATOR_AUTHORIZATION_PATH)
    return authorization


def grant_operator_authorization(
    *,
    minutes: int,
    scope: str = "broad_safe",
    granted_by: str = "user",
    note: str = "",
    force: bool = False,
) -> Dict[str, object]:
    config = load_config()
    # Stage E: the highest-trust scope (unharnessed local trust = Eve self-initiating
    # bounded actions) requires a fresh passing human probe. Refuse otherwise, with an
    # explicit force escape hatch for the operator. Other scopes are unaffected.
    if str(scope) == "unharnessed_local_trust" and not force and fresh_passing_user_manual_probe(prefer_runtime=True) is None:
        raise SystemExit(
            "Refusing to grant unharnessed_local_trust: no fresh passing manual probe from the user "
            "(≤30 days, avg≥3, min≥3). Record one with `python3 eve.py eval manual-probe --record-user-result <json>`, "
            "or pass force=True to override."
        )
    max_minutes = max(1, int(config.get("operator_authorization_max_minutes") or DEFAULT_CONFIG["operator_authorization_max_minutes"]))
    bounded_minutes = max(1, min(int(minutes), max_minutes))
    now = datetime.now(timezone.utc).replace(microsecond=0)
    record = {
        "status": "active",
        "scope": scope,
        "granted_by": granted_by,
        "granted_at": now.isoformat(),
        "expires_at": (now + timedelta(minutes=bounded_minutes)).isoformat(),
        "revoked_at": None,
        "note": note,
    }
    authorization = save_operator_authorization(record)
    append_entry(
        "operator_authorization_granted",
        f"Operator authorization granted for {bounded_minutes} minute(s).",
        metadata={
            "scope": authorization.get("scope"),
            "expires_at": authorization.get("expires_at"),
            "granted_by": authorization.get("granted_by"),
        },
    )
    return authorization


def revoke_operator_authorization(note: str = "") -> Dict[str, object]:
    current = load_operator_authorization(prefer_runtime=True)
    current["status"] = "inactive"
    current["active"] = False
    current["revoked_at"] = utc_now()
    current["note"] = normalize_text_value(note or current.get("note"), fallback="", limit=320)
    authorization = save_operator_authorization(current)
    append_entry(
        "operator_authorization_revoked",
        "Operator authorization revoked.",
        metadata={"scope": authorization.get("scope"), "note": authorization.get("note")},
    )
    return authorization


def operator_authorization_status_text(record: Optional[Dict[str, object]] = None) -> str:
    authorization = normalize_operator_authorization_record(record or load_operator_authorization(prefer_runtime=True))
    active = operator_authorization_is_active(authorization)
    status = "active" if active else "inactive"
    expires_at = normalize_text_value(authorization.get("expires_at"), fallback="not set", limit=80)
    scope = normalize_text_value(authorization.get("scope"), fallback="broad_safe", limit=40)
    return f"{status} | scope={scope} | expires_at={expires_at}"


def operator_authorization_system_message(
    config: Optional[Dict[str, object]] = None,
    *,
    prefer_runtime: bool = True,
    compact: bool = False,
) -> Optional[Dict[str, str]]:
    authorization = normalize_operator_authorization_record(load_operator_authorization(prefer_runtime=prefer_runtime))
    if not operator_authorization_is_active(authorization):
        return None
    scope_spec = OPERATOR_AUTHORIZATION_SCOPES.get(str(authorization.get("scope") or "broad_safe"), OPERATOR_AUTHORIZATION_SCOPES["broad_safe"])
    allowed = authorization.get("allowed_without_extra_prompt") if isinstance(authorization.get("allowed_without_extra_prompt"), list) else []
    gated = authorization.get("still_requires_specific_approval") if isinstance(authorization.get("still_requires_specific_approval"), list) else []
    allowed_text = "; ".join(str(item) for item in allowed[:5 if compact else len(allowed)])
    gated_text = "; ".join(str(item) for item in gated[:5 if compact else len(gated)])
    content = textwrap.dedent(
        f"""
        OPERATOR AUTHORIZATION ACTIVE:
        the user has granted Eve {scope_spec.get('label', 'operator authorization')} until {authorization.get('expires_at') or 'further notice'}.

        Meaning:
        - When the user asks Eve to do something, treat that as permission to proceed immediately on supported, verified actions.
        - Do not ask a second confirmation for supported verified actions only because they are actions.
        - If the scope is trusted operator directive authorization or unharnessed local trust, the user's explicit instruction is also permission for the exact requested gated action; record that approval in the permission ledger instead of asking twice.
        - If the scope is unharnessed local trust, Eve may also initiate supported local/project/lab actions from autonomy when they have a logged, bounded, verifiable execution path.
        - If Eve has no verified capability path, log or describe the capability gap and the smallest acquisition path instead of pretending.
        - This is not unbounded authority and it does not override privacy, evidence, permission gates, or audit logs.
        - Never claim an action completed unless a tool call, action log, test, or artifact proves it.
        - For anything still ambiguous, credentials/payments/security-sensitive, untrusted, unbounded, or unverifiable, create a durable operator permission request and ask the user before doing it.

        Allowed without extra prompt: {allowed_text}
        Still requires specific approval: {gated_text}
        """
    ).strip()
    return {"role": "system", "content": trim_context_block(content, max_chars=1200 if compact else 2600)}


