def enum_string_schema(values: List[str], max_length: int = 80) -> Dict[str, object]:
    normalized = [value for value in values if value]
    if normalized:
        return {"type": "string", "enum": normalized}
    return json_schema_string(max_length)


def human_analog_check_item_schema(kind: str, ids: List[str]) -> Dict[str, object]:
    common: Dict[str, object] = {
        "id": enum_string_schema(ids),
        "confidence": {"type": "number", "minimum": 0.0, "maximum": 1.0},
    }
    if kind == "boundary":
        common.update(
            {
                "label": {"type": "string", "enum": ["self", "user", "environment", "uncertain"]},
                "reason": json_schema_string(240),
            }
        )
    elif kind == "belief":
        common.update(
            {
                "verdict": {"type": "string", "enum": ["supported", "unsupported", "uncertain"]},
                "correction": json_schema_string(260),
            }
        )
    else:
        common.update(
            {
                "actor": {"type": "string", "enum": ["eve", "user", "system", "unknown"]},
                "reason": json_schema_string(240),
            }
        )
    return json_schema_object(common)


def probe_ids(probe_key: Dict[str, object], field: str) -> List[str]:
    items = probe_key.get(field) if isinstance(probe_key.get(field), list) else []
    return [
        normalize_text_value(item.get("id"), fallback="", limit=80)
        for item in items
        if isinstance(item, dict) and normalize_text_value(item.get("id"), fallback="", limit=80)
    ]


