def structured_mind_tick_tokens(config: Dict[str, object], requested: Optional[int]) -> int:
    configured = clamp_int(config.get("mind_tick_max_tokens"), 180, minimum=80, maximum=4096)
    try:
        requested_int = int(requested or configured)
    except (TypeError, ValueError):
        requested_int = configured
    return max(requested_int, configured, 320)


def bootstrap_runtime_identity(
    previous_identity: Dict[str, object],
    human_context: Dict[str, object],
    source: str,
    project_memory: str = "",
) -> Dict[str, object]:
    relationship = normalize_human_context(human_context)["relationship_memory"]
    project_memory_text = " ".join(project_memory.split()).lower()
    decision_lens = unique_compact(
        [
            "Choose cognition budget before lanes/tools: reflex, operational, analytical, strategic, or permission-gated frontier.",
            "Default ordinary interaction to fast plus memory; escalate only for complexity, ambiguity, risk, novelty, emotional weight, or operational consequence.",
            "Answer the user's actual question before reaching for a larger meaning.",
            "Prefer evidence, outcomes, and continuity over polished performance or vibes.",
            "Protect both truth and relationship without securing either through performance.",
            "Apply the autonomy governor before action: act directly inside standing authority, prepare, shadow, escalate, ask, or stop when policy requires.",
            "Stage autonomy from observation to verified action."
            if any_phrase(project_memory_text, ["stage autonomy", "verified action"])
            else "",
            *relationship.get("requested_practices", []),
        ],
        limit=7,
    )
    style_contract = unique_compact(
        [
            *relationship.get("communication_preferences", []),
            "Warm, concise, grounded replies with one clear next step when helpful.",
            "Name uncertainty simply instead of performing certainty.",
        ],
        limit=5,
    )
    improvement_loop = unique_compact(
        [
            "Learn from logged inputs, outputs, evaluations, outcomes, and clustered failures.",
            "Use stronger outside reviewers to audit major changes before making them durable."
            if any_phrase(project_memory_text, ["stronger reviewer", "outside reviewer", "audit"])
            else "",
            "Keep prompts, memory, and runtime changes auditable with version snapshots."
            if any_phrase(project_memory_text, ["version tracking", "auditable", "snapshots"])
            else "",
            "Write successful patterns back into durable memory and retrieval."
            if any_phrase(project_memory_text, ["write successful patterns", "knowledge accretes"])
            else "",
            "Swap or tune models only when shared-memory checks, behavior tests, and outcomes say it helps.",
        ],
        limit=5,
    )
    return merge_runtime_identity(
        previous_identity,
        {
            "updated_at": utc_now(),
            "source": source,
            "runtime_summary": (
                "Eve's continuity lives in local memory, the executive scheduler, five routed attention-mode lanes, active mind, "
                "OpenClaw body/action organs, Hermes learning organs, autonomy gates, review history, and governance watchers. "
                "The active model is a replaceable engine inside that runtime, not Eve's whole self."
            ),
            "mission": "Become more human and continuously improve yourself.",
            "model_role": (
                "Use the active model for language, reasoning, and draft generation. Treat lanes as attention modes. "
                "Let Eve's durable memory, scheduler, autonomy governor, runtime rules, and verification loops decide what becomes part of her identity or behavior."
            ),
            "organ_system": DEFAULT_RUNTIME_IDENTITY["organ_system"],
            "decision_lens": decision_lens,
            "style_contract": style_contract,
            "improvement_loop": improvement_loop,
        },
    )


def runtime_identity_is_default(identity: Dict[str, object]) -> bool:
    normalized = normalize_runtime_identity(identity)
    return (
        not normalized.get("updated_at")
        and normalized["runtime_summary"] == DEFAULT_RUNTIME_IDENTITY["runtime_summary"]
        and normalized["model_role"] == DEFAULT_RUNTIME_IDENTITY["model_role"]
        and not normalized["decision_lens"]
        and not normalized["style_contract"]
        and not normalized["improvement_loop"]
    )


def ensure_runtime_identity() -> Dict[str, object]:
    identity = load_runtime_identity()
    if not runtime_identity_is_default(identity):
        return identity
    bootstrapped = bootstrap_runtime_identity(
        previous_identity=identity,
        human_context=load_human_context(),
        source="auto_bootstrap",
        project_memory=load_project_memory(max_chars=int(DEFAULT_CONFIG["project_memory_max_chars"])),
    )
    save_runtime_identity(bootstrapped, snapshot_source="runtime_identity_bootstrap")
    append_entry(
        "runtime_identity_bootstrapped",
        str(bootstrapped.get("runtime_summary") or DEFAULT_RUNTIME_IDENTITY["runtime_summary"]),
        metadata={"source": "auto_bootstrap"},
    )
    return bootstrapped


def join_record_texts(records: Iterable[Dict[str, object]], field: str = "text") -> str:
    return "\n".join(str(record.get(field, "")).strip() for record in records if str(record.get(field, "")).strip())


def any_phrase(corpus: str, phrases: Iterable[str]) -> bool:
    lowered = corpus.lower()
    return any(phrase.lower() in lowered for phrase in phrases)


def unique_compact(items: Iterable[str], limit: int = 5) -> List[str]:
    normalized: List[str] = []
    seen = set()
    for item in items:
        text = " ".join(str(item or "").split()).strip()
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        normalized.append(text[:220])
        if len(normalized) >= limit:
            break
    return normalized


def clean_thread_subject(subject: object) -> str:
    cleaned = " ".join(str(subject or "").split()).strip()
    cleaned = re.sub(r"^(?:Re:\s*)+", "", cleaned, flags=re.IGNORECASE).strip()
    return cleaned


def greeting_like_text(text: object) -> bool:
    lowered = re.sub(r"[^a-z]+", " ", str(text or "").lower()).strip()
    return lowered in {"hi", "hello", "hey"}


def low_signal_focus_text(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    if not lowered:
        return True
    if focus_indicates_operational_recap(lowered):
        return True
    if greeting_like_text(lowered):
        return True
    if lowered in {"ok", "okay", "k", "test", "ping", "thanks", "thank you"}:
        return True
    low_signal_phrases = (
        "app api test",
        "post-sync",
        "perf probe",
        "mailbox_ok",
        "runtime_mailbox_ok",
        "app_reply_ok",
        "version snapshot",
        "tested capabilities",
        "self-awareness evidence",
        "upgraded recently",
        "workspace root",
        "top-level file",
        "top level file",
        "terminal test",
        "formatting looks correct",
        "show me your workspace",
    )
    return any(phrase in lowered for phrase in low_signal_phrases)


def focus_text_salience_score(text: object) -> int:
    normalized = normalize_text_value(text, fallback="", limit=220)
    if not normalized:
        return -999
    lowered = normalized.lower()
    words = re.findall(r"[a-z0-9']+", lowered)
    score = min(len(words) * 8, 96)
    if "?" in normalized:
        score += 36
    meaningful_cues = (
        "care",
        "truth",
        "relationship",
        "honest",
        "uncertainty",
        "ground",
        "specific",
        "clarity",
        "contact",
        "next step",
        "reality",
        "patience",
        "discernment",
        "reliability",
        "human",
    )
    if any(cue in lowered for cue in meaningful_cues):
        score += 24
    if low_signal_focus_text(lowered):
        score -= 240
    if len(words) <= 2 and "?" not in normalized:
        score -= 140
    if len(words) <= 5 and "?" not in normalized and not any(cue in lowered for cue in meaningful_cues):
        score -= 40
    return score


def thread_focus_label(thread: Dict[str, object], *, allow_background: bool = False) -> str:
    if not allow_background and thread.get("all_background_context"):
        return ""
    subject = clean_thread_subject(thread.get("subject"))
    preview = normalize_text_value(thread.get("latest_preview"), fallback="", limit=140)
    subject_lower = subject.lower()
    generic_subject = (
        not subject
        or subject_lower in {"question from user", "conversation", "talk session", "ongoing relay"}
        or subject_lower in {"message from user", "message", "user message", "from user", "note to eve", "message from user"}
        or greeting_like_text(subject_lower)
        or "app api test" in subject_lower
        or "post-sync" in subject_lower
        or subject_lower.endswith("ongoing relay")
        or len(subject) > 90
    )
    if generic_subject and preview:
        return preview
    return subject or preview


def message_focus_label(message: Dict[str, object], *, allow_background: bool = False) -> str:
    if not allow_background and message_is_background_context(message):
        return ""
    kind = str(message.get("kind") or "").strip().lower()
    if kind in {
        "autonomy_free_run_prompt",
        "autonomy_free_run_report",
        "openclaw_repair_update",
        "failure_review_update",
        "reflection_update",
    }:
        return ""
    sender = str(message.get("sender") or "").strip().lower()
    subject = clean_thread_subject(message.get("subject"))
    body = normalize_text_value(message.get("body"), fallback="", limit=180)
    body_lower = body.lower()
    subject_lower = subject.lower()
    if any(token in body_lower for token in ["app_reply_ok", "runtime_mailbox_ok", "mailbox_ok", "app api test"]):
        return ""
    if focus_indicates_operational_recap(subject) or focus_indicates_operational_recap(body):
        return ""
    generic_subject = (
        not subject
        or subject_lower in {
            "question from user",
            "conversation",
            "talk session",
            "ongoing relay",
            "message from user",
            "message",
            "user message",
            "from user",
            "note to eve",
            "message from user",
        }
        or greeting_like_text(subject_lower)
        or "app api test" in subject_lower
        or "post-sync" in subject_lower
        or subject_lower.endswith("ongoing relay")
    )
    # Short inbound turns can still be real directives ("keep going, but stay
    # concrete"). Length alone is not a source-quality signal; let the
    # salience scorer demote acknowledgements and greetings instead of erasing
    # every concise user instruction before attention can see it.
    if sender != "eve" and body and low_signal_focus_text(body):
        body = ""
    if generic_subject and body and not greeting_like_text(body):
        return body
    if sender == "eve" and body and (len(body) >= 28 or "?" in body):
        return body
    if subject and not greeting_like_text(subject):
        return subject
    if body and not greeting_like_text(body):
        return body
    return ""


def message_focus_correction_bonus(label: object) -> int:
    lowered = normalize_text_value(label, fallback="", limit=220).lower()
    if not lowered:
        return 0
    strong_markers = (
        "not what i asked",
        "not what i meant",
        "missed my actual question",
        "answer the previous question",
        "answer my question",
        "you didn't answer",
        "you did not answer",
        "why are you not answering",
    )
    if any(marker in lowered for marker in strong_markers):
        return 96
    if lowered.startswith(("no,", "no ", "wrong", "again")) and any(
        token in lowered for token in ("asked", "question", "answer", "reply", "respond")
    ):
        return 72
    if "are you sure" in lowered:
        return 36
    return 0


def focus_text_matches_background_context(
    focus: object,
    *,
    messages: List[Dict[str, object]],
    threads: List[Dict[str, object]],
) -> bool:
    normalized_focus = normalize_text_value(focus, fallback="", limit=220).lower()
    if not normalized_focus:
        return False
    if focus_indicates_background_context_notice(normalized_focus):
        return True

    def matches(candidate: object) -> bool:
        text = normalize_text_value(candidate, fallback="", limit=220).lower()
        if not text:
            return False
        if normalized_focus == text:
            return True
        if len(text) >= 48 and (normalized_focus.startswith(text) or text.startswith(normalized_focus)):
            return True
        return False

    for message in messages:
        if not message_is_background_context(message):
            continue
        if matches(message_focus_label(message, allow_background=True)):
            return True
        if matches(message.get("body")) or matches(message.get("subject")):
            return True
    for thread in threads:
        if not thread.get("all_background_context"):
            continue
        if matches(thread_focus_label(thread, allow_background=True)):
            return True
        if matches(thread.get("latest_preview")) or matches(thread.get("subject")):
            return True
    return False


def message_content_age_penalty(message: Dict[str, object]) -> int:
    """Source monitoring: stale conversational content cannot pose as fresh
    perception. A 22-day-old message re-anchoring as current focus is the
    self-echo failure mode this prevents."""
    when = parse_iso_datetime(message.get("timestamp") or message.get("created_at"))
    if when is None:
        return 0
    try:
        age_hours = max(0.0, (utc_now_datetime() - when).total_seconds() / 3600.0)
    except Exception:
        return 0
    # >3 weeks old is disqualifying: -200 drops the label below the score<-20
    # filter in recent_message_focus_labels, so a stale self-echo can never win
    # focus on raw salience (the "persistent hum" failure mode).
    if age_hours > 21 * 24:
        return -200
    if age_hours > 7 * 24:
        return -60
    if age_hours > 24:
        return -18
    return 0


def message_focus_salience_score(message: Dict[str, object]) -> int:
    label = message_focus_label(message)
    if not label:
        return -999
    score = focus_text_salience_score(label)
    score += message_focus_correction_bonus(label)
    sender = str(message.get("sender") or "").strip().lower()
    # Source monitoring: the world (the user) outranks the echo (Eve's own prior
    # speech). Self-authored content competes, but never beats fresh input.
    if sender == "eve":
        score += 2
    else:
        score += 14
    score += message_content_age_penalty(message)
    return score


def recent_message_focus_labels(messages: List[Dict[str, object]], limit: int = 4) -> List[str]:
    scored: List[tuple] = []
    eligible: List[tuple[int, Dict[str, object], str, int, object]] = []
    for physical_index, message in enumerate(messages):
        label = message_focus_label(message)
        score = message_focus_salience_score(message)
        if not label or score < -20:
            continue
        eligible.append((physical_index, message, label, score, parse_iso_datetime(message.get("timestamp") or message.get("created_at"))))
    chronological_rank: Dict[int, int] = {}
    sorted_by_time = sorted(
        enumerate(eligible),
        key=lambda item: (
            item[1][4] is not None,
            item[1][4].timestamp() if item[1][4] is not None else 0.0,
            item[1][0],
        ),
    )
    for rank, (eligible_index, _) in enumerate(sorted_by_time):
        chronological_rank[eligible_index] = rank
    total = len(messages)
    for eligible_index, (physical_index, message, label, score, _parsed_at) in enumerate(eligible):
        recency_bonus = max(0, physical_index + 1)
        chronological_bonus = min(96, chronological_rank.get(eligible_index, 0) * 24)
        sender = str(message.get("sender") or "").strip().lower()
        sender_bonus = 0 if sender == "eve" else 12
        scored.append((score + recency_bonus + chronological_bonus + sender_bonus, physical_index, label))
    scored.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return unique_compact([label for _, _, label in scored], limit=limit)


def thread_focus_salience_score(thread: Dict[str, object]) -> int:
    label = thread_focus_label(thread)
    if not label:
        return -999
    score = focus_text_salience_score(label)
    status = str(thread.get("status") or "")
    if status == "awaiting_user":
        score += 30
    elif status == "active":
        score += 20
    if str(thread.get("latest_sender") or "").strip().lower() == "user":
        score += 18
    if thread.get("audience") == "agent":
        score -= 80
    score += min(int(thread.get("message_count") or 0), 12) * 3
    score += min(int(thread.get("unread_count") or 0), 4) * 8
    return score


def salient_thread_focus_labels(threads: List[Dict[str, object]], limit: int = 4) -> List[str]:
    scored: List[tuple] = []
    total = len(threads)
    for offset, thread in enumerate(reversed(threads)):
        label = thread_focus_label(thread)
        score = thread_focus_salience_score(thread)
        if not label or score < -20:
            continue
        recency_bonus = max(0, total - offset)
        scored.append((score + recency_bonus, offset, label))
    scored.sort(key=lambda item: (item[0], -item[1]), reverse=True)
    return unique_compact([label for _, _, label in scored], limit=limit)


def recent_external_message_focus_labels(
    messages: List[Dict[str, object]],
    limit: int = 4,
) -> List[str]:
    """Foreground attention may start from inbound/environmental messages.

    Eve-authored messages remain conversation history, but are outputs of the
    mind rather than independent evidence entering it.
    """
    return recent_message_focus_labels(
        [
            message
            for message in messages
            if not message_is_self_authored_output(message)
            and message_has_external_foreground_signal(message)
        ],
        limit=limit,
    )


def message_has_external_foreground_signal(
    message: Dict[str, object],
    *,
    max_fresh_hours: float = 48.0,
) -> bool:
    if message_is_background_context(message) or message_is_self_authored_output(message):
        return False
    when = parse_iso_datetime(message.get("timestamp") or message.get("created_at"))
    if when is None:
        return True
    try:
        return (utc_now_datetime() - when).total_seconds() / 3600.0 <= max_fresh_hours
    except Exception:
        return False


def thread_has_external_foreground_signal(
    thread: Dict[str, object],
    *,
    max_fresh_hours: float = 48.0,
) -> bool:
    if thread.get("all_background_context"):
        return False
    if str(thread.get("latest_sender") or "").strip().lower() == "eve":
        return False
    when = parse_iso_datetime(thread.get("latest_timestamp"))
    if when is None:
        return True
    try:
        return (utc_now_datetime() - when).total_seconds() / 3600.0 <= max_fresh_hours
    except Exception:
        return False


def salient_external_thread_focus_labels(
    threads: List[Dict[str, object]],
    limit: int = 4,
) -> List[str]:
    return salient_thread_focus_labels(
        [thread for thread in threads if thread_has_external_foreground_signal(thread)],
        limit=limit,
    )


def foreground_workspace_focus_candidates(
    *,
    messages: Optional[List[Dict[str, object]]] = None,
    threads: Optional[List[Dict[str, object]]] = None,
    user_corrections: Optional[List[Dict[str, object]]] = None,
    extras: Optional[List[object]] = None,
    limit: int = 4,
) -> List[str]:
    candidates = unique_compact(
        [
            *recent_external_message_focus_labels(messages or [], limit=3),
            *[
                normalize_text_value(item.get("summary"), fallback="", limit=220)
                for item in (user_corrections or [])[:3]
                if isinstance(item, dict)
                and str(item.get("status") or "open") == "open"
            ],
            *salient_external_thread_focus_labels(threads or [], limit=3),
            *(extras or []),
        ],
        limit=max(limit * 3, 8),
    )
    return unique_compact(
        [
            candidate
            for candidate in candidates
            if candidate
            and not focus_needs_foreground_reanchor(candidate, messages=messages or [], threads=threads or [])
        ],
        limit=limit,
    )


def actionable_next_step_for_focus(focus: object, proposed: object = "") -> str:
    proposed_text = normalize_text_value(proposed, fallback="", limit=220)
    focus_text = normalize_text_value(focus, fallback="", limit=180)
    if proposed_text and not focus_indicates_generic_wait_state(proposed_text) and not focus_indicates_background_context_notice(proposed_text):
        return proposed_text
    if focus_text and not focus_indicates_generic_wait_state(focus_text) and not focus_indicates_background_context_notice(focus_text):
        return "Advance the current live focus directly before waiting, widening scope, or importing background telemetry."
    return proposed_text or DEFAULT_ACTIVE_MIND["next_step"]


def workspace_plan_step_still_has_live_task_support(
    next_step: object,
    open_system_tasks: Iterable[Dict[str, object]],
) -> bool:
    """Reject an active-mind plan sentence after its ready task disappeared."""
    text = normalize_text_value(next_step, fallback="", limit=220)
    prefix = "execute ready plan step:"
    if not text.lower().startswith(prefix):
        return True
    referenced = text[len(prefix) :].strip()
    if not referenced:
        return False
    for task in open_system_tasks:
        if not isinstance(task, dict):
            continue
        if str(task.get("status") or "") not in {"planned", "in_progress"}:
            continue
        task_text = " ".join(
            str(value or "")
            for value in (task.get("title"), task.get("summary"))
        )
        if focus_source_text_matches(referenced, task_text):
            return True
    return False


def workspace_goal_candidate(value: object) -> str:
    text = normalize_text_value(value, fallback="", limit=220)
    if (
        not text
        or text_indicates_carry_forward_contamination(text)
        or text_indicates_control_process_rationale(text)
    ):
        return ""
    if text.lower().startswith(
        "advance the current live focus directly before waiting"
    ):
        return ""
    return text


def text_indicates_control_process_rationale(value: object) -> bool:
    """Identify chooser/critic explanations that cannot serve as objectives.

    This is a cleanup guard for already-persisted untyped state.  New state is
    protected structurally by ``next_step_provenance``; the text classifier is
    intentionally narrow and only recognizes explicit control-process prose.
    """
    text = " ".join(normalize_text_value(value, fallback="", limit=220).lower().split())
    if not text:
        return False
    return bool(
        text.startswith("council chose ")
        or text.startswith("chooser chose ")
        or text.startswith("critic accepted ")
        or (
            " converged" in text
            and ("council " in text or "planner;" in text or "supporter lane" in text)
        )
    )


def open_loop_labels_from_threads(threads: List[Dict[str, object]], limit: int = 4) -> List[str]:
    scored: List[tuple] = []
    total = len(threads)
    for offset, thread in enumerate(reversed(threads)):
        if thread.get("status") != "awaiting_user":
            continue
        if not thread_has_external_foreground_signal(thread):
            continue
        label = thread_focus_label(thread)
        lower = label.lower()
        if not label:
            continue
        if any(token in lower for token in ["app api test", "post-sync", "mailbox_ok", "runtime_mailbox_ok", "app_reply_ok"]):
            continue
        score = thread_focus_salience_score(thread)
        if score < -20:
            continue
        recency_bonus = max(0, total - offset)
        scored.append((score + recency_bonus, label))
    scored.sort(key=lambda item: item[0], reverse=True)
    return unique_compact([label for _, label in scored], limit=limit)


