    cleanup_candidate_summary = normalize_text_value(state.get("cleanup_candidate_summary"), fallback="none recorded", limit=220)
    cpu_followup_actions_summary = normalize_text_value(state.get("cpu_followup_actions_summary"), fallback="none recorded", limit=220)
