def normalize_workspace_boundary(payload: object) -> Dict[str, object]:
    payload = payload if isinstance(payload, dict) else {}
    return {
        "self": normalize_text_value(payload.get("self"), fallback="Not enough evidence yet.", limit=220),
        "world": normalize_text_value(payload.get("world"), fallback="Not enough evidence yet.", limit=220),
        "others": normalize_text_value(payload.get("others"), fallback="Not enough evidence yet.", limit=220),
        "unknowns": normalize_text_list(payload.get("unknowns"), limit=5),
    }


def normalize_global_workspace(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    workspace_state = payload.get("workspace_state") if isinstance(payload.get("workspace_state"), dict) else {}
    normalized = default_global_workspace()
    normalized["updated_at"] = payload.get("updated_at")
    normalized["source"] = normalize_text_value(payload.get("source"), fallback="", limit=80)
    normalized["summary"] = normalize_text_value(payload.get("summary"), fallback=DEFAULT_GLOBAL_WORKSPACE["summary"], limit=220)
    normalized["current_experience"] = normalize_text_value(
        payload.get("current_experience"),
        fallback=DEFAULT_GLOBAL_WORKSPACE["current_experience"],
        limit=320,
    )
    normalized["dominant_pressures"] = normalize_text_list(payload.get("dominant_pressures"), limit=4)
    normalized["active_goals"] = normalize_text_list(payload.get("active_goals"), limit=6)
    normalized["salient_percepts"] = normalize_text_list(payload.get("salient_percepts"), limit=6)
    normalized["prediction_errors"] = normalize_text_list(payload.get("prediction_errors"), limit=5)
    normalized["continuity_threads"] = normalize_text_list(payload.get("continuity_threads"), limit=6)
    normalized["surprise_signals"] = normalize_text_list(payload.get("surprise_signals"), limit=5)
    normalized["consequence_trace"] = normalize_text_list(payload.get("consequence_trace"), limit=6)
    normalized["action_readiness"] = normalize_text_list(payload.get("action_readiness"), limit=5)
    normalized["workspace_state"] = {
        "focus": normalize_text_value(workspace_state.get("focus"), fallback="Not enough evidence yet.", limit=180),
        "mode": normalize_text_value(workspace_state.get("mode"), fallback="steady", limit=40),
        "frontmost_app": normalize_text_value(workspace_state.get("frontmost_app"), fallback="", limit=80),
        "load_state": normalize_text_value(workspace_state.get("load_state"), fallback="", limit=40),
    }
    normalized["self_world_boundary"] = normalize_workspace_boundary(payload.get("self_world_boundary"))
    normalized["next_refresh"] = normalize_text_value(
        payload.get("next_refresh"),
        fallback=DEFAULT_GLOBAL_WORKSPACE["next_refresh"],
        limit=220,
    )
    if text_indicates_carry_forward_contamination(normalized["workspace_state"]["focus"]):
        normalized["workspace_state"]["focus"] = "Not enough evidence yet."
    for field in [
        "active_goals",
        "salient_percepts",
        "prediction_errors",
        "continuity_threads",
        "surprise_signals",
        "consequence_trace",
        "action_readiness",
    ]:
        normalized[field] = [
            item for item in normalized[field] if not text_indicates_carry_forward_contamination(item)
        ][: len(normalized[field])]
    if text_indicates_carry_forward_contamination(normalized["summary"]):
        focus = normalized["workspace_state"]["focus"]
        normalized["summary"] = (
            normalize_text_value(
                f"Focus '{focus}' inside a {normalized['workspace_state']['mode']} mode workspace.",
                fallback=DEFAULT_GLOBAL_WORKSPACE["summary"],
                limit=220,
            )
            if focus and not focus_indicates_generic_wait_state(focus)
            else DEFAULT_GLOBAL_WORKSPACE["summary"]
        )
    if text_indicates_carry_forward_contamination(normalized["current_experience"]):
        normalized["current_experience"] = normalized["summary"]
    if text_indicates_carry_forward_contamination(normalized["next_refresh"]):
        normalized["next_refresh"] = DEFAULT_GLOBAL_WORKSPACE["next_refresh"]
    return normalized


def normalize_conscious_state(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    """Normalize the persisted recurrent state without inventing live evidence."""
    payload = payload if isinstance(payload, dict) else {}
    normalized = default_conscious_state()
    for field in [
        "recurrent",
        "perception",
        "broadcast",
        "self_model",
        "world_model",
        "other_minds",
        "interoception",
        "epistemic_state",
        "memory",
        "goals",
        "plan_model",
        "action_model",
        "predictions",
        "metacognition",
        "cycle_outcome",
        "learning",
    ]:
        if isinstance(payload.get(field), dict):
            normalized[field] = json.loads(json.dumps(payload[field]))
    normalized["schema_version"] = normalize_text_value(
        payload.get("schema_version"),
        fallback=eve_consciousness.SCHEMA_VERSION,
        limit=80,
    )
    normalized["cycle_id"] = normalize_text_value(payload.get("cycle_id"), fallback="", limit=80)
    normalized["cycle_index"] = max(0, int(payload.get("cycle_index") or 0))
    normalized["updated_at"] = payload.get("updated_at")
    normalized["source"] = normalize_text_value(payload.get("source"), fallback="", limit=100)
    normalized["status"] = normalize_text_value(payload.get("status"), fallback="uninitialized", limit=40)
    # Keep every bounded kernel provenance source. Adding a real causal faculty
    # must not make normalization silently truncate a verified checkpoint and
    # thereby invalidate concurrent-lineage learning.
    normalized["causal_provenance"] = normalize_text_list(payload.get("causal_provenance"), limit=20)
    normalized["lesions"] = [
        item
        for item in normalize_text_list(payload.get("lesions"), limit=12)
        if item in eve_consciousness.LESIONS
    ]
    return normalized


def normalize_self_model_state(payload: Optional[Dict[str, object]]) -> Dict[str, object]:
    payload = payload or {}
    normalized = default_self_model_state()
    normalized["updated_at"] = payload.get("updated_at")
    normalized["source"] = normalize_text_value(payload.get("source"), fallback="", limit=80)
    normalized["identity"] = normalize_text_value(payload.get("identity"), fallback=DEFAULT_SELF_MODEL_STATE["identity"], limit=220)
    normalized["current_state"] = normalize_text_value(
        payload.get("current_state"),
        fallback=DEFAULT_SELF_MODEL_STATE["current_state"],
        limit=220,
    )
    normalized["organ_system"] = unique_compact(
        [
            *normalize_text_list(payload.get("organ_system"), limit=5),
            *DEFAULT_SELF_MODEL_STATE["organ_system"],
        ],
        limit=5,
    )
    normalized["capabilities"] = normalize_text_list(payload.get("capabilities"), limit=6)
    normalized["limits"] = normalize_text_list(payload.get("limits"), limit=6)
    normalized["commitments"] = normalize_text_list(payload.get("commitments"), limit=5)
    normalized["uncertainty_edges"] = normalize_text_list(payload.get("uncertainty_edges"), limit=5)
    normalized["recent_changes"] = normalize_text_list(payload.get("recent_changes"), limit=5)
    return normalized


WORLD_INQUIRY_OPEN_STATUSES = {"open", "in_progress", "blocked"}


def world_inquiry_stable_id(domain: object, source_fingerprint: object, question: object) -> str:
    seed = "|".join(
        [
            normalize_text_value(domain, fallback="world", limit=80).lower(),
            normalize_text_value(source_fingerprint, fallback="", limit=160).lower(),
            normalize_text_value(question, fallback="", limit=320).lower(),
        ]
    )
    return "inquiry-" + hashlib.sha256(seed.encode("utf-8", errors="ignore")).hexdigest()[:20]


def normalize_world_inquiry_attempt(payload: object) -> Optional[Dict[str, object]]:
    if not isinstance(payload, dict):
        return None
    action = normalize_text_value(payload.get("action"), fallback="", limit=80)
    observed = normalize_text_value(payload.get("observed"), fallback="", limit=220)
    if not action and not observed:
        return None
    return {
        "attempted_at": payload.get("attempted_at"),
        "run_id": normalize_text_value(payload.get("run_id"), fallback="", limit=100),
        "source_cycle_id": normalize_text_value(payload.get("source_cycle_id"), fallback="", limit=100),
        "action": action,
        "status": normalize_text_value(payload.get("status"), fallback="unknown", limit=40),
        "consequence_observed": bool(payload.get("consequence_observed")),
        "outcome_ok": parse_explicit_boolish(payload.get("outcome_ok")),
        "evidence_kind": normalize_text_value(payload.get("evidence_kind"), fallback="pending", limit=80),
        "observed": observed,
    }


def normalize_world_inquiry(payload: object, *, default_status: str = "open") -> Optional[Dict[str, object]]:
    if not isinstance(payload, dict):
        return None
    question = normalize_text_value(payload.get("question"), fallback="", limit=320)
    if not question:
        return None
    domain = normalize_text_value(payload.get("domain"), fallback="world", limit=80)
    source_fingerprint = normalize_text_value(payload.get("source_fingerprint"), fallback="", limit=160)
    inquiry_id = normalize_text_value(payload.get("id"), fallback="", limit=100) or world_inquiry_stable_id(
        domain,
        source_fingerprint,
        question,
    )
    status = normalize_text_value(payload.get("status"), fallback=default_status, limit=40).lower()
    if status not in WORLD_INQUIRY_OPEN_STATUSES | {"answered", "superseded"}:
        status = default_status
    candidate_actions = [
        action
        for action in normalize_text_list(payload.get("candidate_actions"), limit=5)
        if action in AUTONOMY_FREE_RUN_ACTIONS
    ]
    attempts = [
        attempt
        for attempt in (
            normalize_world_inquiry_attempt(item)
            for item in (payload.get("attempts") if isinstance(payload.get("attempts"), list) else [])[-8:]
        )
        if attempt is not None
    ]
    attempted_actions = unique_compact(
        [str(item.get("action") or "") for item in attempts if item.get("action")],
        limit=5,
    )
    failed_actions = unique_compact(
        [
            str(item.get("action") or "")
            for item in attempts
            if item.get("action")
            and (
                item.get("outcome_ok") is False
                or str(item.get("status") or "").lower() in {"blocked", "error", "failed", "skipped"}
            )
        ],
        limit=5,
    )
    unverified_actions = unique_compact(
        [
            str(item.get("action") or "")
            for item in attempts
            if item.get("action")
            and (
                not bool(item.get("consequence_observed"))
                or item.get("outcome_ok") is None
            )
        ],
        limit=5,
    )
    remaining_actions = [action for action in candidate_actions if action not in attempted_actions]
    selected_action = normalize_text_value(payload.get("selected_action"), fallback="", limit=80)
    if status in {"answered", "superseded", "blocked"}:
        selected_action = ""
    elif selected_action not in candidate_actions or selected_action in attempted_actions:
        selected_action = remaining_actions[0] if remaining_actions else ""
    return {
        "id": inquiry_id,
        "question": question,
        "domain": domain,
        "source": normalize_text_value(payload.get("source"), fallback="world_model", limit=100),
        "source_ids": normalize_text_list(payload.get("source_ids"), limit=6),
        "source_fingerprint": source_fingerprint,
        "status": status,
        "priority": clamp_int(payload.get("priority"), 70, minimum=1, maximum=100),
        "confidence": clamp_int(payload.get("confidence"), 70, minimum=0, maximum=100),
        "candidate_actions": candidate_actions,
        "selected_action": selected_action,
        "expected_observation": normalize_text_value(
            payload.get("expected_observation"),
            fallback="A bounded observation should reduce this uncertainty.",
            limit=260,
        ),
        "created_at": payload.get("created_at"),
        "updated_at": payload.get("updated_at"),
        "attempts": attempts,
        "attempt_count": len(attempts),
        "attempted_actions": attempted_actions,
        "failed_actions": failed_actions,
        "unverified_actions": unverified_actions,
        "remaining_actions": remaining_actions,
        "recovery_step": bool(attempts and selected_action),
        "probe_exhausted": bool(attempts and not remaining_actions and status not in {"answered", "superseded"}),
        "last_observation": normalize_text_value(payload.get("last_observation"), fallback="", limit=220),
        "answer": normalize_text_value(payload.get("answer"), fallback="", limit=260),
        "answered_at": payload.get("answered_at"),
    }


def normalize_world_inquiry_list(
    payload: object,
    *,
    statuses: Set[str],
    limit: int,
) -> List[Dict[str, object]]:
    source = payload if isinstance(payload, list) else []
    result: List[Dict[str, object]] = []
    seen: Set[str] = set()
    for raw in source:
        inquiry = normalize_world_inquiry(raw)
        if inquiry is None or str(inquiry.get("status") or "") not in statuses:
            continue
        inquiry_id = str(inquiry.get("id") or "")
        if inquiry_id in seen:
            continue
        seen.add(inquiry_id)
        result.append(inquiry)
        if len(result) >= limit:
            break
    return result


