def homeostasis_pressure_level(homeostasis: Dict[str, object], pressure_id: str) -> int:
    pressures = homeostasis.get("pressures") if isinstance(homeostasis, dict) else None
    if not isinstance(pressures, list):
        return 0
    for item in pressures:
        if isinstance(item, dict) and str(item.get("id") or "") == pressure_id:
            return int(item.get("level") or 0)
    return 0


def homeostasis_autonomy_interval_factor(homeostasis: Optional[Dict[str, object]] = None) -> float:
    """Valence->policy coupling: regulation mode modulates autonomy cadence.

    'stabilize' (resource pressure) defers autonomous work; 'respond'
    (social/commitment pressure) engages sooner. Bounded 0.75-2.0 so the
    homeostat can lean on the schedule but never seize it."""
    state = homeostasis if homeostasis is not None else load_homeostasis(prefer_runtime=True)
    mode = str(state.get("regulation_mode") or "steady") if isinstance(state, dict) else "steady"
    if mode == "stabilize":
        return 2.0
    if mode == "respond":
        return 0.75
    return 1.0


def homeostasis_outreach_interval_factor(homeostasis: Optional[Dict[str, object]] = None) -> float:
    """Valence->policy coupling: social-continuity pressure modulates how soon
    Eve reaches out, replacing the pure timer with a felt schedule."""
    state = homeostasis if homeostasis is not None else load_homeostasis(prefer_runtime=True)
    social = homeostasis_pressure_level(state, "social_continuity")
    if social >= 60:
        return 0.5
    if social >= 40:
        return 0.75
    if social < 20:
        return 1.5
    return 1.0


