def previous_pressure_level(previous_homeostasis: Dict[str, object], pressure_id: str) -> Optional[int]:
    pressures = previous_homeostasis.get("pressures") if isinstance(previous_homeostasis.get("pressures"), list) else []
    for item in pressures:
        if isinstance(item, dict) and str(item.get("id") or "") == pressure_id:
            try:
                return int(item.get("level") or 0)
            except (TypeError, ValueError):
                return 0
    return None


def pressure_trend(previous_level: Optional[int], current_level: int) -> str:
    if previous_level is None:
        return "new"
    if current_level - previous_level >= 8:
        return "rising"
    if previous_level - current_level >= 8:
        return "falling"
    return "steady"


def diminishing_count_pressure(
    count: int,
    *,
    unit: int,
    cap: int,
    linear_until: int = 2,
    tail_weight: float = 0.6,
) -> int:
    normalized_count = max(0, int(count or 0))
    if normalized_count <= 0:
        return 0
    linear_count = min(normalized_count, max(0, int(linear_until)))
    tail_count = max(0, normalized_count - linear_count)
    raw_level = (linear_count * unit) + (math.sqrt(tail_count) * unit * max(0.0, float(tail_weight)))
    return min(max(0, int(round(raw_level))), max(0, int(cap)))


def build_homeostasis_pressure(
    pressure_id: str,
    label: str,
    level: int,
    reason: str,
    *,
    previous_level: Optional[int] = None,
    signal_count: int = 0,
) -> Dict[str, object]:
    normalized_level = clamp_thread_weight(level, default=0)
    return {
        "id": pressure_id,
        "label": normalize_text_value(label, fallback=pressure_id.replace("_", " "), limit=60),
        "level": normalized_level,
        "trend": pressure_trend(previous_level, normalized_level),
        "reason": normalize_text_value(reason, fallback="", limit=220),
        "signal_count": max(0, int(signal_count)),
    }


def age_minutes_label(value: Optional[float]) -> str:
    if value is None:
        return "never"
    if value < 1:
        return "<1m ago"
    return f"{int(value)}m ago"


def bool_state_label(value: object, yes: str, no: str, unknown: str = "unknown") -> str:
    if value is True:
        return yes
    if value is False:
        return no
    return unknown


def action_execution_consequence_line(record: Dict[str, object]) -> str:
    action = normalize_text_value(record.get("action"), fallback="action", limit=60)
    verification = bool_state_label(record.get("verification_ok"), "verified", "verification failed", "verification unknown")
    typed_contract = bool_state_label(record.get("typed_contract_ok"), "contract ok", "contract failed", "contract unknown")
    result = bool_state_label(record.get("result_ok"), "result ok", "result failed", "result unknown")
    summary = normalize_text_value(record.get("summary"), fallback="", limit=120)
    return normalize_text_value(
        f"{action}: {verification}, {typed_contract}, {result}. {summary}",
        fallback=f"{action}: {verification}, {typed_contract}, {result}.",
        limit=220,
    )


def action_execution_failed(record: Dict[str, object]) -> bool:
    return (
        record.get("verification_ok") is False
        or record.get("typed_contract_ok") is False
        or record.get("result_ok") is False
    )


def action_execution_succeeded(record: Dict[str, object]) -> bool:
    return (
        record.get("verification_ok") is True
        and record.get("typed_contract_ok") is True
        and record.get("result_ok") is True
    )


def action_execution_timestamp(record: Dict[str, object]) -> Optional[datetime]:
    return parse_iso_datetime(record.get("created_at") or record.get("timestamp") or record.get("updated_at"))


def openclaw_sync_recovered_after(timestamp: Optional[datetime]) -> bool:
    if timestamp is None:
        return False
    try:
        status = eve_openclaw.load_openclaw_status(prefer_runtime=bool(running_from_runtime_bundle() or daemon_runtime_running()))
    except Exception:
        return False
    if status.get("last_sync_ok") is not True:
        return False
    recovered_at = parse_iso_datetime(status.get("last_sync_at"))
    return recovered_at is not None and recovered_at > timestamp


def action_execution_superseded_by_recovery(record: Dict[str, object], records: List[Dict[str, object]]) -> bool:
    if not action_execution_failed(record):
        return False
    action = normalize_text_value(record.get("action"), fallback="", limit=80)
    timestamp = action_execution_timestamp(record)
    for other in records:
        if other is record:
            continue
        if normalize_text_value(other.get("action"), fallback="", limit=80) != action:
            continue
        other_timestamp = action_execution_timestamp(other)
        if other_timestamp is not None and timestamp is not None and other_timestamp <= timestamp:
            continue
        if action_execution_succeeded(other):
            return True
    if action == "openclaw_sync_check":
        return openclaw_sync_recovered_after(timestamp)
    return False


def outcome_consequence_line(record: Dict[str, object]) -> str:
    direction = normalize_text_value(record.get("direction"), fallback="unknown", limit=20)
    outcome = normalize_text_value(record.get("outcome"), fallback="outcome", limit=40)
    summary = normalize_text_value(record.get("summary"), fallback="", limit=140)
    return normalize_text_value(
        f"{direction}/{outcome}: {summary}",
        fallback=f"{direction}/{outcome}",
        limit=220,
    )


def system_task_resource_deferred(task: Dict[str, object]) -> bool:
    if str(task.get("status") or "").strip().lower() != "blocked":
        return False
    blocked_reason = normalize_text_value(task.get("blocked_reason"), fallback="", limit=220).lower()
    if not blocked_reason:
        return False
    return (
        "system load is hot" in blocked_reason
        or "defer gpu" in blocked_reason
        or "machine cools down" in blocked_reason
    )


def build_homeostasis_state(
    *,
    source: str,
    human_context: Dict[str, object],
    active_mind: Dict[str, object],
    state: Dict[str, object],
    system_snapshot: Dict[str, object],
    threads: List[Dict[str, object]],
    uncertainty_records: List[Dict[str, object]],
    judgment_records: List[Dict[str, object]],
    outcomes: List[Dict[str, object]],
    action_executions: List[Dict[str, object]],
    open_system_tasks: List[Dict[str, object]],
    previous_homeostasis: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    previous = normalize_homeostasis_state(previous_homeostasis)
    relationship = normalize_human_context(human_context)["relationship_memory"]
    live_threads = active_mind.get("live_threads") if isinstance(active_mind.get("live_threads"), list) else []
    response_due_threads = [thread for thread in threads if thread_summary_response_due_count(thread) > 0]
    inbound_user_signal_count = sum(thread_summary_response_due_count(thread) for thread in response_due_threads)
    outbound_unseen_threads = [thread for thread in threads if thread_summary_outbound_unread_count(thread) > 0]
    outbound_unseen_count = sum(thread_summary_outbound_unread_count(thread) for thread in outbound_unseen_threads)
    synthetic_continuity_count = sum(thread_summary_synthetic_continuity_count(thread) for thread in threads)
    raw_pending_uncertainty = [
        item for item in uncertainty_records if str(item.get("status") or "") == "pending"
    ]
    raw_pending_judgment = [
        item for item in judgment_records if str(item.get("status") or "") == "pending"
    ]
    pending_uncertainty = active_pending_uncertainty_records(uncertainty_records)
    pending_judgment = active_pending_judgment_calls(judgment_records)
    discounted_uncertainty_count = max(
        0, len(raw_pending_uncertainty) - len(pending_uncertainty)
    )
    discounted_judgment_count = max(
        0, len(raw_pending_judgment) - len(pending_judgment)
    )
    resource_alerts = system_resource_alerts(system_snapshot)
    load_state = normalize_text_value(system_snapshot.get("load_state"), fallback="unknown", limit=20).lower()
    negative_outcomes = [item for item in outcomes if str(item.get("direction") or "") == "negative"]
    mixed_outcomes = [item for item in outcomes if str(item.get("direction") or "") == "mixed"]
    recent_action_executions = action_executions[:6]
    superseded_action_failures = [
        item for item in recent_action_executions if action_execution_superseded_by_recovery(item, action_executions)
    ]
    resolved_action_traces = [
        item
        for item in recent_action_executions
        if action_execution_succeeded(item)
    ]
    unresolved_action_traces = [
        item for item in recent_action_executions if item not in resolved_action_traces and item not in superseded_action_failures
    ]
    failing_actions = [
        item
        for item in recent_action_executions
        if action_execution_failed(item) and item not in superseded_action_failures
    ]
    recent_outcomes = outcomes[-6:]
    destabilizing_recent_outcomes = [
        item for item in recent_outcomes if str(item.get("direction") or "") in {"negative", "mixed"}
    ]
    stabilizing_recent_outcomes = [
        item for item in recent_outcomes if str(item.get("direction") or "") == "positive"
    ]
    open_loops = relationship.get("open_loops") if isinstance(relationship.get("open_loops"), list) else []
    live_concern_count = len(active_mind.get("live_concerns") or [])
    self_check_text = normalize_text_value(active_mind.get("lanes", {}).get("self_check"), fallback="", limit=180)
    current_focus = normalize_text_value(active_mind.get("current_focus"), fallback="", limit=160)
    if focus_indicates_background_context_notice(current_focus):
        current_focus = ""
    last_thought_age_minutes = minutes_since_timestamp(state.get("last_thought_at"))
    last_mind_tick_age_minutes = minutes_since_timestamp(state.get("last_mind_tick_at"))
    resource_deferred_system_tasks = [task for task in open_system_tasks if system_task_resource_deferred(task)]
    actionable_open_system_tasks = [
        task for task in open_system_tasks if not system_task_resource_deferred(task)
    ]
    discounted_signals: List[Dict[str, object]] = []
    if resource_deferred_system_tasks:
        discounted_signals.append(
            {
                "id": "resource_deferred_system_tasks",
                "label": "resource-deferred system tasks",
                "count": len(resource_deferred_system_tasks),
                "pressure_id": "resource_safety",
                "disposition": "deferred by resource safety",
                "reason": "Blocked tasks remain visible but are not counted as unfinished commitments while load is hot.",
            }
        )
    if synthetic_continuity_count:
        discounted_signals.append(
            {
                "id": "synthetic_continuity_messages",
                "label": "synthetic continuity messages",
                "count": synthetic_continuity_count,
                "pressure_id": "social_continuity",
                "disposition": "discounted as synthetic",
                "reason": "Synthetic relay/backlog messages remain visible but do not count as human response-due work.",
            }
        )
    if superseded_action_failures:
        discounted_signals.append(
            {
                "id": "superseded_action_failures",
                "label": "superseded action failures",
                "count": len(superseded_action_failures),
                "pressure_id": "surprise_load",
                "disposition": "resolved by later evidence",
                "reason": "Earlier failed action traces remain visible but are not counted as current surprise after later verified recovery.",
            }
        )
    if discounted_uncertainty_count:
        discounted_signals.append(
            {
                "id": "routine_or_duplicate_uncertainty",
                "label": "routine, duplicate, or stale uncertainty records",
                "count": discounted_uncertainty_count,
                "pressure_id": "uncertainty_debt",
                "disposition": "kept as audit history, excluded from control pressure",
                "reason": (
                    "Routine ambiguity plus duplicate or attention-expired unresolved records "
                    "remain auditable without occupying Eve's bounded working state."
                ),
            }
        )
    if discounted_judgment_count:
        discounted_signals.append(
            {
                "id": "routine_or_duplicate_judgments",
                "label": "routine, duplicate, or stale judgment records",
                "count": discounted_judgment_count,
                "pressure_id": "coherence",
                "disposition": "kept as audit history, excluded from control pressure",
                "reason": (
                    "Generic response shaping and attention-expired choices remain audit "
                    "traces, not unresolved judgments that should keep Eve's attention."
                ),
            }
        )

    live_concern_pressure = diminishing_count_pressure(live_concern_count, unit=14, cap=48)
    pending_judgment_pressure = diminishing_count_pressure(len(pending_judgment), unit=12, cap=64)
    pending_uncertainty_pressure = diminishing_count_pressure(len(pending_uncertainty), unit=20, cap=72)
    open_system_task_pressure = diminishing_count_pressure(len(actionable_open_system_tasks), unit=18, cap=82)
    commitment_response_due_pressure = diminishing_count_pressure(len(response_due_threads), unit=10, cap=48)
    social_response_due_pressure = diminishing_count_pressure(len(response_due_threads), unit=18, cap=70)
    open_loop_pressure = diminishing_count_pressure(len(open_loops), unit=12, cap=54)
    negative_outcome_pressure = diminishing_count_pressure(len(negative_outcomes), unit=28, cap=76)
    mixed_outcome_pressure = diminishing_count_pressure(len(mixed_outcomes), unit=14, cap=42)

    coherence_level = (
        max(live_concern_pressure, pending_judgment_pressure)
        + (12 if self_check_text else 0)
        + (10 if not current_focus else 0)
    )
    commitment_level = open_system_task_pressure + commitment_response_due_pressure + min(inbound_user_signal_count, 5) * 6
    uncertainty_level = (
        max(pending_uncertainty_pressure, pending_judgment_pressure)
        + (12 if self_check_text else 0)
    )
    resource_level = len(resource_alerts) * 22 + {"calm": 8, "busy": 26, "hot": 56}.get(load_state, 16)
    # Open loops and response-due threads usually describe the same relational
    # pressure from different angles. Let the stronger of those two families set
    # the base, then add small freshness/unseen-message bonuses, instead of
    # summing both into a saturated 100 whenever a few live conversations also
    # have unresolved relationship loops.
    social_level = (
        max(social_response_due_pressure, open_loop_pressure)
        + min(inbound_user_signal_count, 5) * 7
        + min(len(outbound_unseen_threads), 3) * 3
    )
    trust_level = negative_outcome_pressure + mixed_outcome_pressure + (8 if open_loops and response_due_threads else 0)
    continuity_level = (
        diminishing_count_pressure(len(unresolved_action_traces), unit=10, cap=42)
        + len(destabilizing_recent_outcomes) * 14
        + (14 if last_thought_age_minutes is None or last_thought_age_minutes > 120 else 0)
        + (10 if last_mind_tick_age_minutes is None or last_mind_tick_age_minutes > 60 else 0)
        + (8 if current_focus and not live_threads else 0)
    )
    surprise_level = len(failing_actions) * 24 + len(negative_outcomes) * 16 + len(mixed_outcomes) * 12 + len(resource_alerts) * 8
    # Genuine prediction error: graded expectation-vs-outcome mismatches from
    # the autonomy loop now contribute to felt surprise.
    try:
        unfulfilled_predictions = [
            record
            for record in read_recent_prediction_checks(hours=24.0)
            if not record.get("fulfilled") and int(record.get("error_magnitude") or 0) > 0
        ]
        surprise_level += min(40, sum(int(record.get("error_magnitude") or 0) for record in unfulfilled_predictions) // 4)
    except Exception:
        unfulfilled_predictions = []

    pressures = [
        build_homeostasis_pressure(
            "coherence",
            "coherence",
            coherence_level,
            (
                f"{live_concern_count} live concern(s), {len(pending_judgment)} active pending judgment review(s), "
                f"{discounted_judgment_count} routine/duplicate/stale record(s) discounted, "
                f"self-check {'active' if self_check_text else 'quiet'}."
            ),
            previous_level=previous_pressure_level(previous, "coherence"),
            signal_count=live_concern_count + len(pending_judgment) + (1 if self_check_text else 0),
        ),
        build_homeostasis_pressure(
            "unfinished_commitments",
            "unfinished commitments",
            commitment_level,
            (
                f"{len(actionable_open_system_tasks)} actionable open system task(s), "
                f"{len(resource_deferred_system_tasks)} resource-deferred task(s), "
                f"{len(response_due_threads)} response-due thread(s), "
                f"{inbound_user_signal_count} inbound signal(s), {outbound_unseen_count} outbound unseen message(s)"
                + (f", {synthetic_continuity_count} synthetic continuity message(s) discounted." if synthetic_continuity_count else ".")
            ),
            previous_level=previous_pressure_level(previous, "unfinished_commitments"),
            signal_count=len(actionable_open_system_tasks) + len(response_due_threads) + inbound_user_signal_count,
        ),
        build_homeostasis_pressure(
            "uncertainty_debt",
            "uncertainty debt",
            uncertainty_level,
            (
                f"{len(pending_uncertainty)} active pending uncertainty record(s), "
                f"{len(pending_judgment)} active pending judgment call(s); "
                f"{discounted_uncertainty_count + discounted_judgment_count} "
                "routine/duplicate/stale record(s) discounted."
            ),
            previous_level=previous_pressure_level(previous, "uncertainty_debt"),
            signal_count=len(pending_uncertainty) + len(pending_judgment),
        ),
        build_homeostasis_pressure(
            "resource_safety",
            "resource safety",
            resource_level,
            (
                f"Load is {load_state or 'unknown'} with {len(resource_alerts)} resource alert(s)"
                + (
                    f"; {len(resource_deferred_system_tasks)} resource-deferred task(s)."
                    if resource_deferred_system_tasks
                    else "."
                )
            ),
            previous_level=previous_pressure_level(previous, "resource_safety"),
            signal_count=len(resource_alerts) + (1 if load_state in {'busy', 'hot'} else 0),
        ),
        build_homeostasis_pressure(
            "social_continuity",
            "social continuity",
            social_level,
            (
                f"{len(response_due_threads)} response-due thread(s), {len(open_loops)} open loop(s), "
                f"{inbound_user_signal_count} inbound signal(s), {outbound_unseen_count} outbound unseen message(s)"
                + (f", {synthetic_continuity_count} synthetic continuity message(s) discounted." if synthetic_continuity_count else ".")
            ),
            previous_level=previous_pressure_level(previous, "social_continuity"),
            signal_count=len(response_due_threads) + len(open_loops) + inbound_user_signal_count,
        ),
        build_homeostasis_pressure(
            "trust_repair",
            "trust repair",
            trust_level,
            f"{len(negative_outcomes)} negative and {len(mixed_outcomes)} mixed outcome(s) remain in recent memory.",
            previous_level=previous_pressure_level(previous, "trust_repair"),
            signal_count=len(negative_outcomes) + len(mixed_outcomes),
        ),
        build_homeostasis_pressure(
            "continuity_drift",
            "continuity drift",
            continuity_level,
            (
                f"{len(unresolved_action_traces)} unresolved action trace(s), "
                f"{len(destabilizing_recent_outcomes)} destabilizing outcome trace(s), "
                f"{len(resolved_action_traces)} verified action trace(s), "
                f"{len(stabilizing_recent_outcomes)} stabilizing outcome trace(s), "
                f"last thought {age_minutes_label(last_thought_age_minutes)}, last mind tick {age_minutes_label(last_mind_tick_age_minutes)}."
            ),
            previous_level=previous_pressure_level(previous, "continuity_drift"),
            signal_count=(
                len(unresolved_action_traces)
                + len(destabilizing_recent_outcomes)
                + (1 if last_thought_age_minutes is None or last_thought_age_minutes > 120 else 0)
                + (1 if last_mind_tick_age_minutes is None or last_mind_tick_age_minutes > 60 else 0)
                + (1 if current_focus and not live_threads else 0)
            ),
        ),
        build_homeostasis_pressure(
            "surprise_load",
            "surprise load",
            surprise_level,
            (
                f"{len(failing_actions)} failed or unverified action(s), {len(negative_outcomes)} negative outcome(s), "
                f"{len(mixed_outcomes)} mixed outcome(s), {len(resource_alerts)} resource alert(s)."
            ),
            previous_level=previous_pressure_level(previous, "surprise_load"),
            signal_count=len(failing_actions) + len(negative_outcomes) + len(mixed_outcomes) + len(resource_alerts),
        ),
    ]
    pressures.sort(key=lambda item: int(item.get("level") or 0), reverse=True)
    dominant = [item for item in pressures if int(item.get("level") or 0) >= 25][:3] or pressures[:2]
    dominant_text = [format_pressure_brief(item) for item in dominant if int(item.get("level") or 0) > 0]

    regulation_mode = "steady"
    top_pressure = dominant[0] if dominant else {}
    top_id = str(top_pressure.get("id") or "")
    top_level = int(top_pressure.get("level") or 0)
    if top_id == "resource_safety" and top_level >= 60:
        regulation_mode = "stabilize"
    elif top_id == "trust_repair" and top_level >= 50:
        regulation_mode = "repair"
    elif top_id in {"unfinished_commitments", "social_continuity"} and top_level >= 50:
        regulation_mode = "respond"
    elif top_id == "continuity_drift" and top_level >= 45:
        regulation_mode = "integrate"
    elif top_id in {"uncertainty_debt", "coherence"} and top_level >= 45:
        regulation_mode = "orient"
    elif top_id == "surprise_load" and top_level >= 40:
        regulation_mode = "orient"

    target_map = {
        "coherence": "Re-anchor the current self/world summary before escalating language.",
        "unfinished_commitments": "Finish, defer, or explicitly re-queue outstanding commitments instead of letting them hover.",
        "uncertainty_debt": "Reduce uncertainty debt by checking sources or recording a bounded unknown.",
        "resource_safety": "Reduce load, avoid heavier work, and keep the machine stable before deepening effort.",
        "social_continuity": "Keep waiting threads and open loops in contact so continuity does not drift.",
        "trust_repair": "Ground the next relational move in evidence and close any repair loop explicitly.",
        "continuity_drift": "Integrate what just changed so identity carries forward instead of resetting between loops.",
        "surprise_load": "Name what violated expectation and either verify it, accept it, or bound it as an open unknown.",
    }
    recovery_targets = [
        target_map.get(str(item.get("id") or ""), "")
        for item in dominant
        if int(item.get("level") or 0) >= 35 and target_map.get(str(item.get("id") or ""))
    ]
    recovery_targets = unique_compact(recovery_targets, limit=4)
    # Relief signals: the appetitive counterpart to pressure — pressures that
    # fell meaningfully since the previous cycle register as felt easing.
    relief_signals = unique_compact(
        [
            f"{item.get('label')} easing ({previous_pressure_level(previous, str(item.get('id') or ''))}→{int(item.get('level') or 0)})"
            for item in pressures
            if str(item.get("trend") or "") == "falling"
            and (previous_pressure_level(previous, str(item.get("id") or "")) or 0) - int(item.get("level") or 0) >= 15
        ],
        limit=3,
    )
    summary = (
        f"Mode {regulation_mode}. Dominant pressures: {', '.join(dominant_text) if dominant_text else 'none beyond baseline'}."
    )
    if relief_signals:
        summary += f" Relief: {', '.join(relief_signals)}."
    next_regulation_step = (
        recovery_targets[0]
        if recovery_targets
        else "Hold steady and wait for a stronger signal before manufacturing regulation work."
    )
    return normalize_homeostasis_state(
        {
            "updated_at": utc_now(),
            "source": source,
            "summary": summary,
            "regulation_mode": regulation_mode,
            "pressures": pressures,
            "discounted_signals": discounted_signals,
            "dominant_pressures": dominant_text,
            "relief_signals": relief_signals,
            "recovery_targets": recovery_targets,
            "next_regulation_step": next_regulation_step,
        }
    )


def build_self_model_state(
    *,
    source: str,
    runtime_identity: Dict[str, object],
    human_context: Dict[str, object],
    active_mind: Dict[str, object],
    state: Dict[str, object],
    homeostasis: Dict[str, object],
    threads: Optional[List[Dict[str, object]]] = None,
    messages: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    threads = threads or []
    messages = messages or []
    human_self = normalize_human_context(human_context)["self_model"]
    model_role = normalize_text_value(runtime_identity.get("model_role"), fallback="", limit=220)
    organ_system = unique_compact(
        runtime_identity.get("organ_system") or DEFAULT_RUNTIME_IDENTITY["organ_system"],
        limit=5,
    )
    capabilities = unique_compact(runtime_identity.get("capability_ledger") or [], limit=6)
    commitments = unique_compact(
        [
            active_mind.get("next_step"),
            *[
                thread.get("next_step")
                for thread in active_mind.get("live_threads", [])
                if isinstance(thread, dict)
                and str(thread.get("kind") or "") in {"focus", "next_step"}
                and thread.get("next_step")
            ],
        ],
        limit=5,
    )
    uncertainty_edges = unique_compact(
        [
            active_mind.get("lanes", {}).get("self_check"),
            state.get("uncertainty_review_summary"),
            *human_self.get("current_preoccupations", []),
        ],
        limit=5,
    )
    limits = unique_compact(
        [
            model_role,
            *human_self.get("growth_edges", []),
            "Claims should stay grounded in evidence and supported actions.",
        ],
        limit=6,
    )
    # `recent_shifts` is a semantic, model-authored consolidation. It can guide
    # long-horizon identity, but it is not causal evidence that Eve actually
    # changed. Keep the recurrent self-model's recent-change field limited to
    # externally checkable state until an outcome/trace-backed change exists.
    recent_changes = unique_compact(
        [state.get("component_update_summary")],
        limit=5,
    )
    identity = human_self.get("identity_statement") or runtime_identity.get("runtime_summary") or DEFAULT_SELF_MODEL_STATE["identity"]
    active_focus = normalize_text_value(active_mind.get("current_focus"), fallback="", limit=160)
    if focus_needs_foreground_reanchor(
        active_focus,
        messages=messages,
        threads=threads,
        focus_since=active_mind.get("current_focus_since"),
    ):
        active_focus = next(
            iter(
                foreground_workspace_focus_candidates(
                    messages=messages,
                    threads=threads,
                    extras=[
                        active_mind.get("next_step"),
                        homeostasis.get("next_regulation_step"),
                    ],
                    limit=1,
                )
            ),
            "",
        )
    current_state = normalize_text_value(
        (
            f"Focus: {active_focus or 'none recorded'}. "
            f"Regulation mode: {homeostasis.get('regulation_mode') or 'steady'}. "
            f"{homeostasis.get('summary') or active_mind.get('summary') or ''}"
        ),
        fallback=DEFAULT_SELF_MODEL_STATE["current_state"],
        limit=220,
    )
    return normalize_self_model_state(
        {
            "updated_at": utc_now(),
            "source": source,
            "identity": identity,
            "current_state": current_state,
            "organ_system": organ_system,
            "capabilities": capabilities,
            "limits": limits,
            "commitments": commitments,
            "uncertainty_edges": uncertainty_edges,
            "recent_changes": recent_changes,
        }
    )


def world_inquiry_source_fingerprint(domain: object, payload: object) -> str:
    canonical = json.dumps(
        {
            "domain": normalize_text_value(domain, fallback="world", limit=80),
            "signal": payload,
        },
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        default=str,
    )
    return hashlib.sha256(canonical.encode("utf-8", errors="ignore")).hexdigest()[:24]


def make_world_inquiry(
    *,
    question: str,
    domain: str,
    source: str,
    source_ids: Iterable[object],
    source_signal: object,
    priority: int,
    confidence: int,
    candidate_actions: Iterable[str],
    expected_observation: str,
    now: str,
) -> Dict[str, object]:
    actions = [str(action) for action in candidate_actions]
    source_fingerprint = world_inquiry_source_fingerprint(domain, source_signal)
    return normalize_world_inquiry(
        {
            "id": world_inquiry_stable_id(domain, source_fingerprint, question),
            "question": question,
            "domain": domain,
            "source": source,
            "source_ids": list(source_ids),
            "source_fingerprint": source_fingerprint,
            "status": "open",
            "priority": priority,
            "confidence": confidence,
            "candidate_actions": actions,
            "selected_action": actions[0] if actions else "",
            "expected_observation": expected_observation,
            "created_at": now,
            "updated_at": now,
            "attempts": [],
        }
    ) or {}


def world_inquiry_semantic_key(payload: object) -> Tuple[str, str]:
    """Identify one question independently of a volatile evidence revision."""
    record = payload if isinstance(payload, dict) else {}
    return (
        normalize_text_value(record.get("domain"), fallback="world", limit=80)
        .strip()
        .lower(),
        normalize_text_value(record.get("question"), fallback="", limit=320)
        .strip()
        .lower(),
    )


def merge_world_inquiries(
    previous_world_model: Dict[str, object],
    candidates: Iterable[Dict[str, object]],
    *,
    now: str,
) -> Tuple[List[Dict[str, object]], List[Dict[str, object]]]:
    previous = normalize_world_model_state(previous_world_model)
    answered = list(previous.get("answered_questions") or [])
    answered_fingerprints = {
        (str(item.get("domain") or ""), str(item.get("source_fingerprint") or ""))
        for item in answered
        if isinstance(item, dict) and item.get("source_fingerprint")
    }
    latest_answered_at_by_semantic_key: Dict[Tuple[str, str], datetime] = {}
    for item in answered:
        if not isinstance(item, dict):
            continue
        key = world_inquiry_semantic_key(item)
        if not key[1]:
            continue
        answered_at = parse_iso_datetime(
            item.get("answered_at") or item.get("updated_at")
        )
        if answered_at is None:
            continue
        previous_answered_at = latest_answered_at_by_semantic_key.get(key)
        if previous_answered_at is None or answered_at > previous_answered_at:
            latest_answered_at_by_semantic_key[key] = answered_at
    previous_open = {
        str(item.get("id") or ""): item
        for item in previous.get("open_questions") or []
        if isinstance(item, dict) and item.get("id")
    }
    merged: Dict[str, Dict[str, object]] = {}
    current_semantic_keys: Set[Tuple[str, str]] = set()
    resolved_current_semantic_keys: Set[Tuple[str, str]] = set()
    for raw in candidates:
        candidate = normalize_world_inquiry(raw)
        if candidate is None:
            continue
        semantic_key = world_inquiry_semantic_key(candidate)
        current_semantic_keys.add(semantic_key)
        fingerprint_key = (
            str(candidate.get("domain") or ""),
            str(candidate.get("source_fingerprint") or ""),
        )
        if fingerprint_key in answered_fingerprints:
            resolved_current_semantic_keys.add(semantic_key)
            continue
        inquiry_id = str(candidate.get("id") or "")
        prior = previous_open.get(inquiry_id)
        if prior:
            candidate["created_at"] = prior.get("created_at") or candidate.get("created_at") or now
            candidate["attempts"] = list(prior.get("attempts") or [])[-8:]
            candidate["last_observation"] = prior.get("last_observation") or ""
            candidate["status"] = prior.get("status") or "open"
            if prior.get("selected_action") in candidate.get("candidate_actions", []):
                candidate["selected_action"] = prior.get("selected_action")
        candidate["updated_at"] = now
        merged[inquiry_id] = candidate

    answered_ids = {
        str(item.get("id") or "")
        for item in answered
        if isinstance(item, dict) and item.get("id")
    }

    def supersede_stale_open(prior: Dict[str, object], reason: str) -> None:
        prior_id = str(prior.get("id") or "")
        if prior_id and prior_id in answered_ids:
            return
        superseded = dict(prior)
        superseded.update(
            {
                "status": "superseded",
                "selected_action": "",
                "updated_at": now,
                "answered_at": now,
                "answer": normalize_text_value(reason, fallback="Superseded.", limit=260),
            }
        )
        normalized = normalize_world_inquiry(
            superseded,
            default_status="superseded",
        )
        if normalized is not None:
            answered.append(normalized)
            if prior_id:
                answered_ids.add(prior_id)

    # A source-owned unknown is durable until an observation answers it.  It
    # must not, however, survive beside a newer revision of the *same semantic
    # question*, or outlive a verified answer recorded after that stale copy.
    # Source fingerprints version evidence; they do not create parallel minds.
    for inquiry_id, prior in previous_open.items():
        if inquiry_id in merged:
            continue
        semantic_key = world_inquiry_semantic_key(prior)
        prior_updated_at = parse_iso_datetime(
            prior.get("updated_at") or prior.get("created_at")
        )
        latest_answered_at = latest_answered_at_by_semantic_key.get(semantic_key)
        answered_after_prior = bool(
            latest_answered_at
            and (
                prior_updated_at is None
                or latest_answered_at >= prior_updated_at
            )
        )
        if semantic_key in resolved_current_semantic_keys or answered_after_prior:
            supersede_stale_open(
                prior,
                "Superseded by a newer verified answer to the same world-model question.",
            )
            continue
        if semantic_key in current_semantic_keys:
            supersede_stale_open(
                prior,
                "Superseded by the current evidence revision of the same world-model question.",
            )
            continue
        merged[inquiry_id] = dict(prior)
    open_questions = sorted(
        merged.values(),
        key=lambda item: (
            int(item.get("priority") or 0),
            str(item.get("updated_at") or item.get("created_at") or ""),
        ),
        reverse=True,
    )[:8]
    answered = sorted(
        answered,
        key=lambda item: str(item.get("answered_at") or item.get("updated_at") or ""),
        reverse=True,
    )[:16]
    return open_questions, answered


def active_world_inquiry(world_model: object) -> Dict[str, object]:
    normalized = normalize_world_model_state(world_model if isinstance(world_model, dict) else {})
    candidates = [
        item
        for item in normalized.get("open_questions") or []
        if isinstance(item, dict)
        and str(item.get("status") or "") in {"open", "in_progress"}
        and str(item.get("selected_action") or "") in AUTONOMY_FREE_RUN_ACTIONS
    ]
    if not candidates:
        return {}
    candidates.sort(
        key=lambda item: (
            int(item.get("priority") or 0),
            int(item.get("confidence") or 0),
            str(item.get("updated_at") or item.get("created_at") or ""),
        ),
        reverse=True,
    )
    return dict(candidates[0])


def build_world_model_state(
    *,
    source: str,
    system_snapshot: Dict[str, object],
    state: Dict[str, object],
    openclaw_status: Optional[Dict[str, object]] = None,
    previous_world_model: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    now = utc_now()
    workspace = system_snapshot.get("workspace") if isinstance(system_snapshot.get("workspace"), dict) else {}
    external_pressures = unique_compact(
        [
            *system_resource_alerts(system_snapshot),
            state.get("service_health_summary"),
            state.get("component_update_summary"),
        ],
        limit=6,
    )
    recent_changes = unique_compact(
        [
            workspace.get("recent_changes_summary"),
            *[
                item.get("path")
                for item in workspace.get("recent_changes", [])
                if isinstance(item, dict) and item.get("path")
            ],
        ],
        limit=5,
    )
    inquiry_candidates: List[Dict[str, object]] = []
    service_health_summary = normalize_text_value(state.get("service_health_summary"), fallback="", limit=220)
    service_health_lower = service_health_summary.lower()
    if not service_health_summary or any(
        marker in service_health_lower
        for marker in ("unknown", "degraded", "unhealthy", "failed", "failure", "error", "unavailable", "stale")
    ):
        inquiry_candidates.append(
            make_world_inquiry(
                question="What is the current verified service-health state?",
                domain="service_health",
                source="state.service_health_summary",
                source_ids=["service_health_summary"],
                source_signal={"summary": service_health_summary or "missing"},
                priority=82 if service_health_summary else 72,
                confidence=85 if service_health_summary else 60,
                candidate_actions=["service_health_check"],
                expected_observation="A fresh service-health check should identify which services are currently healthy, degraded, or unavailable.",
                now=now,
            )
        )
    current_openclaw = openclaw_status if isinstance(openclaw_status, dict) else {}
    if current_openclaw and openclaw_attention_needs_action(current_openclaw):
        openclaw_signal = {
            key: current_openclaw.get(key)
            for key in (
                "summary",
                "sync_health_summary",
                "last_sync_at",
                "last_sync_ok",
                "gateway_reachable",
                "memory_status_summary",
                "memory_status_ok",
            )
        }
        inquiry_candidates.append(
            make_world_inquiry(
                question="Does OpenClaw currently show a live fault, or only recovered historical failure evidence?",
                domain="openclaw_runtime",
                source="openclaw_status",
                source_ids=[
                    value
                    for value in (current_openclaw.get("last_sync_at"), current_openclaw.get("last_repair_at"))
                    if value
                ],
                source_signal=openclaw_signal,
                priority=88,
                confidence=82,
                candidate_actions=["openclaw_log_check", "openclaw_sync_check"],
                expected_observation=(
                    "Fresh OpenClaw logs should distinguish a current runtime fault from recovered historical failures; "
                    "if that evidence path fails, a bounded sync/status verification should provide an independent observation."
                ),
                now=now,
            )
        )
    open_questions, answered_questions = merge_world_inquiries(
        previous_world_model or {},
        inquiry_candidates,
        now=now,
    )
    live_unknowns = unique_compact(
        [
            "No fresh system snapshot is recorded." if not system_snapshot else "",
            "Service health is still unknown." if not state.get("service_health_summary") else "",
            "The workspace working set is still sparse." if not workspace.get("focus_files") else "",
            *[item.get("question") for item in open_questions if isinstance(item, dict)],
        ],
        limit=5,
    )
    return normalize_world_model_state(
        {
            "updated_at": now,
            "source": source,
            "environment_summary": system_snapshot.get("summary") or state.get("system_summary") or DEFAULT_WORLD_MODEL_STATE["environment_summary"],
            "system_state": unique_compact(
                [
                    f"frontmost_app: {system_snapshot.get('frontmost_app') or 'unknown'}",
                    f"load_state: {system_snapshot.get('load_state') or 'unknown'}",
                    f"idle_seconds: {system_snapshot.get('idle_seconds') if system_snapshot.get('idle_seconds') is not None else 'unknown'}",
                    state.get("service_health_summary"),
                ],
                limit=5,
            ),
            "workspace_state": unique_compact(
                [
                    f"focus_areas: {compact_mapping_items(workspace.get('focus_areas'), limit=4)}",
                    f"working_set: {format_workspace_focus_files(workspace.get('focus_files'), limit=3)}",
                    workspace.get("recent_changes_summary"),
                ],
                limit=5,
            ),
            "external_pressures": external_pressures,
            "recent_changes": recent_changes,
            "live_unknowns": live_unknowns,
            "open_questions": open_questions,
            "answered_questions": answered_questions,
        }
    )


def build_relationship_model_state(
    *,
    source: str,
    human_context: Dict[str, object],
    active_mind: Dict[str, object],
    threads: List[Dict[str, object]],
    messages: List[Dict[str, object]],
    outcomes: List[Dict[str, object]],
) -> Dict[str, object]:
    relationship = normalize_human_context(human_context)["relationship_memory"]
    waiting_threads = [thread for thread in threads if thread_status_label(thread) == "waiting"]
    externally_grounded_waiting_threads = [
        thread for thread in waiting_threads if thread_has_external_foreground_signal(thread)
    ]
    externally_grounded_open_loops = unique_compact(
        [workspace_thread_label(thread) for thread in externally_grounded_waiting_threads],
        limit=6,
    )
    user_messages = [
        message
        for message in reversed(messages)
        if str(message.get("sender") or "").strip().lower() == "user"
    ]
    positive = sum(1 for item in outcomes if str(item.get("direction") or "") == "positive")
    mixed = sum(1 for item in outcomes if str(item.get("direction") or "") == "mixed")
    negative = sum(1 for item in outcomes if str(item.get("direction") or "") == "negative")
    relationship_state = normalize_text_value(
        (
            f"{len(externally_grounded_waiting_threads)} waiting conversation(s), "
            f"{len(externally_grounded_open_loops)} open loop(s), "
            f"and relationship pull '{normalize_text_value(active_mind.get('relationship_pull', [''])[0] if active_mind.get('relationship_pull') else '', fallback='none', limit=120)}'."
        ),
        fallback=DEFAULT_RELATIONSHIP_MODEL_STATE["relationship_state"],
        limit=220,
    )
    next_relational_move = (
        active_mind.get("relationship_pull", [])[0]
        if isinstance(active_mind.get("relationship_pull"), list) and active_mind.get("relationship_pull")
        else "Stay attentive to the next real user signal."
    )
    return normalize_relationship_model_state(
        {
            "updated_at": utc_now(),
            "source": source,
            "counterpart": "user",
            "relationship_state": relationship_state,
            "user_priorities": relationship.get("what_user_seems_to_value"),
            "communication_contract": unique_compact(
                [
                    *relationship.get("communication_preferences", []),
                    *relationship.get("requested_practices", []),
                ],
                limit=6,
            ),
            # Human-context open_loops are model-authored semantic memory. They
            # stay available in relationship memory, but only a current inbound
            # thread can become a live relational obligation here.
            "open_loops": externally_grounded_open_loops,
            "trust_signals": unique_compact(
                [
                    f"positive_outcomes: {positive}",
                    f"mixed_outcomes: {mixed}",
                    f"negative_outcomes: {negative}",
                ],
                limit=4,
            ),
            "recent_signals": unique_compact(
                [
                    *[
                        normalize_text_value(message.get("body"), fallback="", limit=160)
                        for message in user_messages[:3]
                    ],
                ],
                limit=4,
            ),
            "next_relational_move": next_relational_move,
        }
    )


def build_other_minds_model_state(
    *,
    source: str,
    human_context: Dict[str, object],
    relationship_model: Dict[str, object],
    active_mind: Dict[str, object],
    system_snapshot: Dict[str, object],
    messages: List[Dict[str, object]],
    action_executions: List[Dict[str, object]],
) -> Dict[str, object]:
    relationship = normalize_human_context(human_context)["relationship_memory"]
    normalized_relationship = normalize_relationship_model_state(relationship_model)
    normalized_mind = normalize_active_mind(active_mind)
    latest_user = most_recent_message(messages, "user")
    latest_action = action_executions[0] if action_executions else {}
    load_state_text = normalize_text_value(system_snapshot.get("load_state"), fallback="unknown", limit=40)
    latest_user_signal = human_analog_message_label(latest_user)
    observed = [
        {
            "id": "user",
            "label": "user",
            "state": normalized_relationship.get("relationship_state"),
            "goals": normalized_relationship.get("user_priorities"),
            "constraints": normalized_relationship.get("communication_contract"),
            "signals": unique_compact(
                [
                    latest_user_signal,
                    *(normalized_relationship.get("recent_signals") or [])[:2],
                ],
                limit=4,
            ),
            "unknowns": unique_compact(
                [
                    "The user's emotional state is only partially known from the visible thread.",
                ],
                limit=3,
            ),
        },
        {
            "id": "system",
            "label": "runtime/system",
            "state": normalize_text_value(
                f"System load is {load_state_text}; frontmost app is {system_snapshot.get('frontmost_app') or 'unknown'}.",
                fallback="Not enough evidence yet.",
                limit=220,
            ),
            "goals": unique_compact(
                [
                    "Keep services stable.",
                    "Keep the machine responsive enough for bounded work.",
                ],
                limit=3,
            ),
            "constraints": unique_compact(system_resource_alerts(system_snapshot), limit=3),
            "signals": unique_compact(
                [
                    normalize_text_value(system_snapshot.get("summary"), fallback="", limit=180),
                ],
                limit=3,
            ),
            "unknowns": unique_compact(
                [
                    "The system does not expose a full causal model for why every service event happened.",
                ],
                limit=3,
            ),
        },
        {
            "id": "agents",
            "label": "other agents/sidecars",
            "state": normalize_text_value(
                latest_action.get("summary") or "No recent sidecar or execution-tree action was recorded.",
                fallback="Not enough evidence yet.",
                limit=220,
            ),
            "goals": unique_compact(
                [
                    "Complete bounded operational actions with evidence.",
                    "Provide verified results instead of implied follow-through.",
                ],
                limit=3,
            ),
            "constraints": unique_compact(
                [
                    "Bounded verified actions only.",
                    "Typed result contracts must validate before results become memory.",
                ],
                limit=3,
            ),
            "signals": unique_compact(
                [
                    normalize_text_value(latest_action.get("action"), fallback="", limit=120),
                ],
                limit=3,
            ),
            "unknowns": unique_compact(
                [
                    "Other agent intent is only known through their logged outputs and actions.",
                ],
                limit=3,
            ),
        },
    ]
    coordination_risks = unique_compact(
        [
            "User needs may be over-inferred from sparse recent signals." if not latest_user_signal else "",
            "System constraints can silently tighten when load or disk pressure rises." if load_state_text in {"busy", "hot", "unknown"} else "",
            "Sidecar outputs can look complete while still missing a typed contract or verification." if latest_action and not latest_action.get("typed_contract_ok", True) else "",
            "Relationship pull can dominate action selection if the user's practical ask is not kept explicit." if normalized_mind.get("relationship_pull") else "",
        ],
        limit=4,
    )
    uncertainty_edges = unique_compact(
        [
            "The user may want practical action, relational repair, or both.",
            "System events only reveal partial state, not full intent.",
            "Other agent processes only expose what they logged, not their hidden deliberation.",
        ],
        limit=4,
    )
    return normalize_other_minds_model_state(
        {
            "updated_at": utc_now(),
            "source": source,
            "summary": normalize_text_value(
                f"User, system, and sidecar/agent state are now tracked explicitly so Eve can separate self from other minds before acting.",
                fallback=DEFAULT_OTHER_MINDS_MODEL_STATE["summary"],
                limit=220,
            ),
            "observed_minds": observed,
            "coordination_risks": coordination_risks,
            "uncertainty_edges": uncertainty_edges,
            "next_check": "Before acting, re-check whether the pressure belongs to Eve, the user, the system, or another agent surface.",
        }
    )


def build_global_workspace_state(
    *,
    source: str,
    active_mind: Dict[str, object],
    system_snapshot: Dict[str, object],
    self_model: Dict[str, object],
    world_model: Dict[str, object],
    relationship_model: Dict[str, object],
    other_minds_model: Dict[str, object],
    homeostasis: Dict[str, object],
    open_system_tasks: List[Dict[str, object]],
    action_executions: List[Dict[str, object]],
    outcomes: List[Dict[str, object]],
    uncertainty_records: List[Dict[str, object]],
    judgment_records: List[Dict[str, object]],
    evidence_records: Optional[List[Dict[str, object]]] = None,
    experience_events: Optional[List[Dict[str, object]]] = None,
    commitments: Optional[List[Dict[str, object]]] = None,
    user_corrections: Optional[List[Dict[str, object]]] = None,
    relationship_episodes: Optional[List[Dict[str, object]]] = None,
    threads: Optional[List[Dict[str, object]]] = None,
    messages: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    evidence_records = evidence_records or []
    experience_events = experience_events or []
    threads = threads or []
    messages = messages or []
    visible_experience_events = [
        item for item in experience_events if isinstance(item, dict) and not experience_event_is_background_context(item)
    ]
    commitments = commitments or []
    user_corrections = user_corrections or []
    relationship_episodes = relationship_episodes or []
    active_uncertainty_records = active_pending_uncertainty_records(uncertainty_records)
    active_judgment_records = active_pending_judgment_calls(judgment_records)
    active_focus = normalize_text_value(active_mind.get("current_focus"), fallback="", limit=160)
    original_active_focus = active_focus
    active_focus_since = active_mind.get("current_focus_since")
    active_next_step = normalize_text_value(active_mind.get("next_step"), fallback="", limit=220)
    if focus_needs_foreground_reanchor(
        active_focus,
        messages=messages,
        threads=threads,
        focus_since=active_focus_since,
    ):
        active_focus = ""
    if not active_focus:
        active_focus = next(
            iter(
                foreground_workspace_focus_candidates(
                    messages=messages,
                    threads=threads,
                    user_corrections=user_corrections,
                    extras=[
                        active_next_step,
                        relationship_model.get("next_relational_move"),
                        homeostasis.get("next_regulation_step"),
                    ],
                    limit=1,
                )
            ),
            "",
        )
    active_focus_candidate_since = focus_since_for_candidate(
        active_focus,
        state_focus=original_active_focus,
        state_focus_since=active_focus_since,
        previous_mind=active_mind,
    )
    if focus_needs_foreground_reanchor(
        active_focus,
        messages=messages,
        threads=threads,
        focus_since=active_focus_candidate_since,
    ):
        active_focus = ""
    if not workspace_plan_step_still_has_live_task_support(
        active_next_step,
        open_system_tasks,
    ):
        active_next_step = ""
    active_next_step = actionable_next_step_for_focus(active_focus, active_next_step)
    # Prediction errors are expectation-vs-outcome mismatches and failed
    # verification traces.  Uncertainty and judgment records remain separate:
    # relabeling "I was unsure" as prediction error created false surprise.
    waiting_prediction_errors = []
    try:
        waiting_prediction_errors.extend(
            normalize_text_value(
                f"Expected '{record.get('expected_signal')}' from {record.get('action')}, observed: {record.get('observed')} (error {record.get('error_magnitude')})",
                fallback="",
                limit=180,
            )
            for record in read_recent_prediction_checks(hours=24.0)
            if not record.get("fulfilled") and int(record.get("error_magnitude") or 0) > 0
        )
    except Exception:
        pass
    waiting_prediction_errors.extend(
        normalize_text_value(item.get("summary"), fallback="", limit=180)
        for item in action_executions
        if (
            item.get("verification_ok") is False
            or item.get("typed_contract_ok") is False
            or item.get("result_ok") is False
        )
        and not action_execution_superseded_by_recovery(item, action_executions)
    )
    salient_percepts = unique_compact(
        [
            world_model.get("environment_summary"),
            *world_model.get("external_pressures", []),
            *relationship_model.get("recent_signals", []),
            *[
                item.get("summary")
                for item in user_corrections[:2]
                if isinstance(item, dict)
            ],
            *[
                item.get("summary") or item.get("claim")
                for item in evidence_records[:3]
                if isinstance(item, dict)
            ],
        ],
        limit=6,
    )
    active_goals = unique_compact(
        [
            # A focus is an attended observation, and model-authored planner
            # prose is only a proposal.  An active next step enters the durable
            # goal projection only when its exact text is bound to a typed,
            # source-owned objective/action contract.
            workspace_goal_candidate(active_next_step)
            if active_mind_next_step_is_goal_eligible(active_mind)
            else "",
            *[
                workspace_goal_candidate(thread.get("title"))
                for thread in active_mind.get("live_threads", [])
                if isinstance(thread, dict)
                and str(thread.get("kind") or "") == "next_step"
                and active_mind_thread_is_goal_eligible(thread)
                and workspace_plan_step_still_has_live_task_support(
                    thread.get("title"),
                    open_system_tasks,
                )
                and not text_indicates_carry_forward_contamination(thread.get("title"))
                and not text_indicates_carry_forward_contamination(thread.get("detail"))
            ],
        ],
        limit=6,
    )
    recent_action_executions = action_executions[:4]
    superseded_recent_action_failures = [
        item for item in recent_action_executions if action_execution_superseded_by_recovery(item, action_executions)
    ]
    recent_outcomes = list(reversed(outcomes[-3:]))
    continuity_threads = unique_compact(
        [
            active_focus,
            active_next_step,
            *[
                f"Unresolved uncertainty: {normalize_text_value(item.get('summary'), fallback='', limit=160)}"
                for item in active_uncertainty_records[:2]
            ],
            *[
                f"Pending judgment: {normalize_text_value(item.get('summary'), fallback='', limit=160)}"
                for item in active_judgment_records[:2]
            ],
            relationship_model.get("next_relational_move"),
            homeostasis.get("next_regulation_step"),
            *[
                item.get("summary")
                for item in visible_experience_events[:2]
                if isinstance(item, dict)
            ],
            *[
                item.get("what_happened")
                for item in relationship_episodes[:2]
                if isinstance(item, dict)
            ],
            *[
                task.get("summary") or task.get("title")
                for task in open_system_tasks[:2]
                if isinstance(task, dict)
            ],
        ],
        limit=6,
    )
    surprise_signals = unique_compact(
        [
            *[
                pressure.get("reason")
                for pressure in homeostasis.get("pressures", [])
                if isinstance(pressure, dict)
                and str(pressure.get("id") or "") == "surprise_load"
                and int(pressure.get("level") or 0) >= 25
            ],
            *[
                pressure.get("reason")
                for pressure in homeostasis.get("pressures", [])
                if isinstance(pressure, dict)
                and str(pressure.get("trend") or "") in {"rising", "new"}
                and int(pressure.get("level") or 0) >= 35
            ],
            *[
                action_execution_consequence_line(item)
                for item in recent_action_executions
                if action_execution_failed(item) and item not in superseded_recent_action_failures
            ],
            *[
                outcome_consequence_line(item)
                for item in recent_outcomes
                if str(item.get("direction") or "") in {"negative", "mixed"}
            ],
            *[
                f"User correction still open: {normalize_text_value(item.get('summary'), fallback='', limit=160)}"
                for item in user_corrections[:2]
                if isinstance(item, dict) and str(item.get("status") or "") == "open"
            ],
        ],
        limit=5,
    )
    consequence_trace = unique_compact(
        [
            *[action_execution_consequence_line(item) for item in recent_action_executions],
            *[outcome_consequence_line(item) for item in recent_outcomes],
            *[
                normalize_text_value(item.get("summary"), fallback="", limit=180)
                for item in visible_experience_events[:2]
                if isinstance(item, dict)
            ],
            *[
                normalize_text_value(item.get("what_changed_afterward") or item.get("what_happened"), fallback="", limit=180)
                for item in relationship_episodes[:2]
                if isinstance(item, dict)
            ],
        ],
        limit=6,
    )
    action_readiness = unique_compact(
        [
            active_next_step,
            *[
                item.get("text")
                for item in commitments[:2]
                if isinstance(item, dict) and str(item.get("status") or "") in {"proposed", "blocked", "capability_gap"}
            ],
            *[
                task.get("summary") or task.get("title")
                for task in open_system_tasks[:3]
                if isinstance(task, dict)
            ],
            homeostasis.get("next_regulation_step"),
        ],
        limit=5,
    )
    dominant_pressures = normalize_text_list(homeostasis.get("dominant_pressures"), limit=4)
    summary = normalize_text_value(
        (
            f"Focus '{active_focus or 'none recorded'}' inside a {homeostasis.get('regulation_mode') or 'steady'} mode workspace. "
            f"Dominant pressures: {', '.join(dominant_pressures) if dominant_pressures else 'none beyond baseline'}."
        ),
        fallback=DEFAULT_GLOBAL_WORKSPACE["summary"],
        limit=220,
    )
    current_experience = normalize_text_value(
        (
            f"{self_model.get('current_state') or 'Not enough integrated evidence yet.'} "
            f"World state: {world_model.get('environment_summary') or 'unknown'}. "
            f"Relationship state: {relationship_model.get('relationship_state') or 'unknown'}. "
            f"Latest lived event: {(visible_experience_events[0].get('summary') if visible_experience_events and isinstance(visible_experience_events[0], dict) else 'none recorded')}. "
            f"Surprise: {(surprise_signals or ['none beyond baseline'])[0]}."
        ),
        fallback=DEFAULT_GLOBAL_WORKSPACE["current_experience"],
        limit=320,
    )
    return normalize_global_workspace(
        {
            "updated_at": utc_now(),
            "source": source,
            "summary": summary,
            "current_experience": current_experience,
            "dominant_pressures": dominant_pressures,
            "active_goals": active_goals,
            "salient_percepts": salient_percepts,
            "prediction_errors": unique_compact(waiting_prediction_errors, limit=5),
            "continuity_threads": continuity_threads,
            "surprise_signals": surprise_signals,
            "consequence_trace": consequence_trace,
            "action_readiness": action_readiness,
            "workspace_state": {
                "focus": active_focus or "Not enough evidence yet.",
                "mode": homeostasis.get("regulation_mode") or "steady",
                "frontmost_app": system_snapshot.get("frontmost_app") or "",
                "load_state": system_snapshot.get("load_state") or "",
            },
            "self_world_boundary": {
                "self": self_model.get("current_state"),
                "world": world_model.get("environment_summary"),
                "others": other_minds_model.get("summary") or relationship_model.get("relationship_state"),
                "unknowns": unique_compact(
                    [
                        *self_model.get("uncertainty_edges", []),
                        *world_model.get("live_unknowns", []),
                        *other_minds_model.get("uncertainty_edges", []),
                    ],
                    limit=5,
                ),
            },
            "next_refresh": homeostasis.get("next_regulation_step") or DEFAULT_GLOBAL_WORKSPACE["next_refresh"],
        }
    )


def project_active_mind_from_workspace(
    *,
    previous_mind: Dict[str, object],
    workspace: Dict[str, object],
    self_model: Dict[str, object],
    world_model: Dict[str, object],
    relationship_model: Dict[str, object],
    homeostasis: Dict[str, object],
    threads: List[Dict[str, object]],
    messages: List[Dict[str, object]],
    source: str,
    conscious_state: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    previous = normalize_active_mind(previous_mind)
    normalized_workspace = normalize_global_workspace(workspace)
    normalized_self_model = normalize_self_model_state(self_model)
    normalized_world_model = normalize_world_model_state(world_model)
    normalized_relationship_model = normalize_relationship_model_state(relationship_model)
    normalized_homeostasis = normalize_homeostasis_state(homeostasis)

    current_focus = normalize_text_value(
        normalized_workspace.get("workspace_state", {}).get("focus"),
        fallback=previous.get("current_focus") or DEFAULT_ACTIVE_MIND["current_focus"],
        limit=160,
    )
    normalized_conscious = normalize_conscious_state(conscious_state)
    conscious_broadcast = (
        normalized_conscious.get("broadcast")
        if isinstance(normalized_conscious.get("broadcast"), dict)
        else {}
    )
    conscious_winner = (
        (normalized_conscious.get("perception") or {}).get("winning_coalition")
        if isinstance(normalized_conscious.get("perception"), dict)
        else {}
    )
    broadcast_content = normalize_text_value(conscious_broadcast.get("content"), fallback="", limit=160)
    broadcast_kind = normalize_text_value((conscious_winner or {}).get("kind"), fallback="", limit=40)
    if (
        broadcast_content
        and broadcast_content != "Not enough integrated evidence yet."
        and float(conscious_broadcast.get("ignition_score") or 0.0) >= 45
        and broadcast_kind not in {"memory", "prior_broadcast"}
        and not text_indicates_carry_forward_contamination(broadcast_content)
    ):
        current_focus = broadcast_content
    workspace_focus = current_focus
    current_focus_since = focus_since_for_candidate(
        current_focus,
        state_focus=previous.get("current_focus"),
        state_focus_since=previous.get("current_focus_since"),
        previous_mind=previous,
    )
    focus_reanchored = False
    if focus_needs_foreground_reanchor(
        current_focus,
        messages=messages,
        threads=threads,
        focus_since=current_focus_since,
    ):
        live_focuses = foreground_workspace_focus_candidates(
            messages=messages,
            threads=threads,
            extras=[
                previous.get("current_focus"),
                normalized_workspace.get("action_readiness", [""])[0]
                if isinstance(normalized_workspace.get("action_readiness"), list)
                and normalized_workspace.get("action_readiness")
                else "",
            ],
            limit=3,
        )
        replacement_focus = ""
        for candidate in live_focuses:
            candidate_since = focus_since_for_candidate(
                candidate,
                state_focus=previous.get("current_focus"),
                state_focus_since=previous.get("current_focus_since"),
                previous_mind=previous,
            )
            if candidate and not focus_needs_foreground_reanchor(
                candidate,
                messages=messages,
                threads=threads,
                focus_since=candidate_since,
            ):
                replacement_focus = candidate
                current_focus_since = candidate_since
                break
        current_focus = normalize_text_value(
            replacement_focus,
            fallback="Re-anchor on the current user or work signal instead of daemon background notices.",
            limit=160,
        )
        focus_reanchored = bool(replacement_focus)
        if current_focus != workspace_focus:
            current_focus_since = focus_since_for_candidate(
                current_focus,
                state_focus=previous.get("current_focus"),
                state_focus_since=previous.get("current_focus_since"),
                previous_mind=previous,
            )

    def foreground_current_candidate(candidate: object, *, limit: int = 220) -> str:
        normalized_candidate = normalize_text_value(candidate, fallback="", limit=limit)
        if not normalized_candidate:
            return ""
        candidate_since = focus_since_for_candidate(
            normalized_candidate,
            state_focus=previous.get("current_focus"),
            state_focus_since=previous.get("current_focus_since"),
            previous_mind=previous,
        )
        if focus_needs_foreground_reanchor(
            normalized_candidate,
            messages=messages,
            threads=threads,
            focus_since=candidate_since,
        ):
            return ""
        return normalized_candidate

    live_concerns = unique_compact(
        [
            *normalized_workspace.get("prediction_errors", []),
            *normalized_relationship_model.get("open_loops", []),
        ],
        limit=4,
    )
    active_threads = unique_compact(
        [
            *[foreground_current_candidate(item) for item in normalized_workspace.get("active_goals", [])],
            *[foreground_current_candidate(item) for item in normalized_relationship_model.get("open_loops", [])],
        ],
        limit=4,
    )
    relationship_pull = unique_compact(
        [
            normalized_relationship_model.get("next_relational_move"),
            *normalized_relationship_model.get("communication_contract", []),
            *normalized_relationship_model.get("open_loops", []),
        ],
        limit=4,
    )
    grounding_notes = unique_compact(
        [
            (
                f"Current broadcast won attention with score {conscious_broadcast.get('ignition_score')}: {broadcast_content}"
                if broadcast_content and conscious_broadcast.get("access_scope")
                else ""
            ),
            normalized_homeostasis.get("next_regulation_step"),
            *normalized_self_model.get("limits", []),
            *normalized_world_model.get("external_pressures", []),
        ],
        limit=4,
    )
    selected_intention = (
        (normalized_conscious.get("action_model") or {}).get("selected_intention")
        if isinstance(normalized_conscious.get("action_model"), dict)
        else {}
    )
    conscious_next_step = normalize_text_value(
        (selected_intention or {}).get("description"),
        fallback="",
        limit=220,
    )
    next_step = actionable_next_step_for_focus(
        current_focus,
        conscious_next_step or (normalized_workspace.get("action_readiness") or [""])[0],
    )
    next_step_provenance = normalize_active_mind_next_step_provenance({})
    selected_goal_id = normalize_text_value(
        (selected_intention or {}).get("goal_id"),
        fallback="",
        limit=160,
    )
    if conscious_next_step and selected_goal_id:
        next_step_provenance = active_mind_next_step_provenance(
            next_step,
            source_kind="current_goal",
            source_id=selected_goal_id,
            evidence=(selected_intention or {}).get("goal_text"),
        )
    elif conscious_next_step and normalize_text_value(
        (selected_intention or {}).get("id"), fallback="", limit=80
    ) == "respond_to_user":
        latest_user_message = next(
            (
                item
                for item in reversed(messages)
                if isinstance(item, dict)
                and str(item.get("sender") or "").strip().lower() == "user"
                and message_has_external_foreground_signal(item)
            ),
            {},
        )
        source_id = normalize_text_value(
            latest_user_message.get("id")
            or latest_user_message.get("message_id")
            or latest_user_message.get("timestamp"),
            fallback="",
            limit=160,
        )
        if source_id:
            next_step_provenance = active_mind_next_step_provenance(
                next_step,
                source_kind="user_request",
                source_id=source_id,
                evidence=current_focus,
            )
    if focus_reanchored and focus_indicates_generic_wait_state(next_step):
        next_step = actionable_next_step_for_focus(current_focus, "")
        next_step_provenance = normalize_active_mind_next_step_provenance({})
    lanes = normalize_active_mind_lanes(
        {
            "observer": normalized_workspace.get("current_experience") or normalized_workspace.get("summary"),
            "planner": next_step,
            "relationship": normalized_relationship_model.get("next_relational_move")
            or normalized_relationship_model.get("relationship_state"),
            "grounding": grounding_notes[0] if grounding_notes else normalized_homeostasis.get("summary"),
            "self_check": (normalized_workspace.get("prediction_errors") or normalized_self_model.get("uncertainty_edges") or [""])[0],
        }
    )
    projected = merge_active_mind(
        previous,
        {
            "updated_at": utc_now(),
            "source": source,
            "model": "workspace-view",
            "summary": normalize_text_value(
                f"{normalized_workspace.get('summary') or DEFAULT_ACTIVE_MIND['summary']} Next check: {next_step}",
                fallback=DEFAULT_ACTIVE_MIND["summary"],
                limit=220,
            ),
            "current_focus": current_focus,
            "current_focus_since": current_focus_since,
            "live_concerns": live_concerns,
            "active_threads": active_threads,
            "relationship_pull": relationship_pull,
            "grounding_notes": grounding_notes,
            "lanes": lanes,
            "next_step": next_step,
            "next_step_provenance": next_step_provenance,
        },
    )
    projected["live_concerns"] = live_concerns
    projected["active_threads"] = active_threads
    projected["relationship_pull"] = relationship_pull
    projected["grounding_notes"] = grounding_notes
    return ensure_active_mind_live_threads(projected, threads=threads, messages=messages)


def global_workspace_change_notes(previous: Dict[str, object], current: Dict[str, object]) -> List[str]:
    previous_normalized = normalize_global_workspace(previous)
    current_normalized = normalize_global_workspace(current)
    notes: List[str] = []
    if previous_normalized.get("summary") != current_normalized.get("summary"):
        notes.append("summary shifted")
    if previous_normalized.get("current_experience") != current_normalized.get("current_experience"):
        notes.append("current experience shifted")
    if previous_normalized.get("dominant_pressures") != current_normalized.get("dominant_pressures"):
        notes.append("dominant pressures changed")
    if previous_normalized.get("action_readiness") != current_normalized.get("action_readiness"):
        notes.append("action readiness changed")
    return notes


def append_global_workspace_audit_event(
    previous_workspace: Dict[str, object],
    current_workspace: Dict[str, object],
    *,
    source: str,
) -> Optional[Dict[str, object]]:
    change_notes = global_workspace_change_notes(previous_workspace, current_workspace)
    if not change_notes:
        return None
    record = {
        "id": str(uuid.uuid4()),
        "timestamp": normalize_text_value(current_workspace.get("updated_at"), fallback=utc_now(), limit=40),
        "source": normalize_text_value(source, fallback="unknown", limit=80),
        "summary": normalize_text_value(current_workspace.get("summary"), fallback="", limit=220),
        "dominant_pressures": normalize_text_list(current_workspace.get("dominant_pressures"), limit=4),
        "action_readiness": normalize_text_list(current_workspace.get("action_readiness"), limit=4),
        "changes": change_notes,
    }
    append_jsonl_record(GLOBAL_WORKSPACE_AUDIT_LOG_PATH, record)
    mirror_store_file_to_runtime(GLOBAL_WORKSPACE_AUDIT_LOG_PATH)
    return record


def select_conscious_memory_items(query: object, *, prefer_runtime: bool = True, limit: int = 6) -> List[Dict[str, object]]:
    """Select compact durable memory anchors for the recurrent state.

    This deliberately reads the existing retrieval-note corpus rather than
    invoking the embedding service on every daemon/reply cycle.  It makes
    memory causally available at the hot path while leaving the heavier
    retrieval service free to refresh the corpus asynchronously.
    """
    payload = load_memory_retrieval_payload(MEMORY_RETRIEVAL_NOTES_PATH, prefer_runtime=prefer_runtime)
    notes = payload.get("notes") if isinstance(payload.get("notes"), list) else []
    query_tokens = {
        token
        for token in re.findall(r"[a-z0-9]+", normalize_text_value(query, fallback="", limit=1000).lower())
        if len(token) > 2
    }
    ranked: List[Tuple[float, int, Dict[str, object]]] = []
    source_bonus = {
        "human_context": 3.0,
        "success_pattern": 2.5,
        "relationship_episode": 2.5,
        "experience_event": 2.0,
        "commitment": 2.0,
        "runtime_identity": 1.5,
        "project_memory": 1.0,
    }
    for index, raw in enumerate(notes):
        if not isinstance(raw, dict):
            continue
        tags = {
            normalize_text_value(item, fallback="", limit=40).lower()
            for item in (raw.get("tags") if isinstance(raw.get("tags"), list) else [])
        }
        # Eve's own language is autobiographical output history, not a new
        # perception. Keep it available to explicit conversation-history
        # retrieval, but do not let it re-enter the hot recurrent workspace as
        # evidence and then become a goal, pressure, or fresh observation.
        if "self_output" in tags:
            continue
        text = normalize_text_value(raw.get("text") or raw.get("content") or raw.get("title"), fallback="", limit=2400)
        if not text:
            continue
        note_tokens = {token for token in re.findall(r"[a-z0-9]+", text.lower()) if len(token) > 2}
        overlap = len(query_tokens & note_tokens)
        density = overlap / max(1, len(query_tokens)) if query_tokens else 0.0
        source = normalize_text_value(raw.get("source"), fallback="memory", limit=80)
        score = overlap * 2.0 + density * 5.0 + source_bonus.get(source, 0.0)
        ranked.append(
            (
                score,
                -index,
                {
                    "id": normalize_text_value(raw.get("id"), fallback=f"memory-{index}", limit=100),
                    "source": source,
                    "title": normalize_text_value(raw.get("title"), fallback=source, limit=140),
                    "text": text[:600],
                    "confidence": 75 if overlap else 60,
                    "relevance_score": round(score, 3),
                },
            )
        )
    ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
    return [item[2] for item in ranked[: max(1, int(limit))]]


def append_conscious_state_audit_event(
    state: Dict[str, object],
    *,
    event: str,
    source: str,
) -> Dict[str, object]:
    broadcast = state.get("broadcast") if isinstance(state.get("broadcast"), dict) else {}
    recurrent = state.get("recurrent") if isinstance(state.get("recurrent"), dict) else {}
    goals = state.get("goals") if isinstance(state.get("goals"), dict) else {}
    action_model = state.get("action_model") if isinstance(state.get("action_model"), dict) else {}
    metacognition = state.get("metacognition") if isinstance(state.get("metacognition"), dict) else {}
    record = {
        "id": str(uuid.uuid4()),
        "timestamp": state.get("updated_at") or utc_now(),
        "event": normalize_text_value(event, fallback="cycle", limit=60),
        "source": normalize_text_value(source, fallback="unknown", limit=100),
        "cycle_id": normalize_text_value(state.get("cycle_id"), fallback="", limit=80),
        "cycle_index": int(state.get("cycle_index") or 0),
        "status": normalize_text_value(state.get("status"), fallback="unknown", limit=40),
        "broadcast": normalize_text_value(broadcast.get("content"), fallback="", limit=260),
        "ignition_score": float(broadcast.get("ignition_score") or 0.0),
        "access_scope": normalize_text_list(broadcast.get("access_scope"), limit=8),
        "continuity_strength": int(recurrent.get("continuity_strength") or 0),
        "selected_goal": normalize_text_value(goals.get("selected_goal"), fallback="", limit=220),
        "selected_intention": normalize_text_value(
            (action_model.get("selected_intention") or {}).get("description"),
            fallback="",
            limit=220,
        ),
        "metacognitive_confidence": int(metacognition.get("confidence") or 0),
        "causal_provenance": normalize_text_list(state.get("causal_provenance"), limit=12),
        "lesions": normalize_text_list(state.get("lesions"), limit=8),
    }
    append_jsonl_record(CONSCIOUS_STATE_AUDIT_LOG_PATH, record)
    mirror_store_file_to_runtime(CONSCIOUS_STATE_AUDIT_LOG_PATH)
    return record


def conscious_epistemic_conflict_items(
    *,
    workspace: Dict[str, object],
    human_context: Dict[str, object],
) -> List[Dict[str, object]]:
    """Select live contradictions without reviving resolved belief history.

    ``superseded_or_conflicting_beliefs`` is an archive, not an unresolved-
    conflict queue. Only explicitly unresolved archive entries are admitted.
    Current workspace surprise/prediction-error records are admitted when their
    wording actually describes incompatible evidence.
    """

    def conflict_parts(value: object) -> Tuple[str, str]:
        text = normalize_text_value(value, fallback="", limit=420)
        lowered = text.lower()
        for marker in (" versus ", " vs. ", " while ", " but ", " contradicts ", " conflicts with "):
            position = lowered.find(marker)
            if position > 0:
                return text[:position].strip(" :;-"), text[position + len(marker) :].strip(" :;-")
        return text, ""

    records: List[Dict[str, object]] = []
    seen: set[str] = set()

    def admit(value: object, *, source: str, confidence: int) -> None:
        claim, counterclaim = conflict_parts(value)
        if not claim:
            return
        key = f"{claim}|{counterclaim}".lower()
        if key in seen:
            return
        seen.add(key)
        records.append(
            {
                "claim": claim,
                "contradicts": counterclaim,
                "source": source,
                "status": "unresolved",
                "confidence": confidence,
                "evidence": normalize_text_value(value, fallback="", limit=420),
            }
        )

    conflict_cues = (
        "contradict",
        "conflict",
        "inconsistent",
        "mismatch",
        "disagree",
        " versus ",
        " vs. ",
    )
    for field in ("prediction_errors", "surprise_signals"):
        for item in normalize_text_list(workspace.get(field), limit=6):
            lowered = item.lower()
            before_while, separator, after_while = lowered.partition(" while ")
            structured_while_conflict = bool(
                separator
                and "=" in before_while
                and (
                    "=" in after_while
                    or any(token in after_while for token in ("claimed success", "claimed failure", "reported success", "reported failure"))
                )
            )
            if any(cue in lowered for cue in conflict_cues) or structured_while_conflict:
                admit(item, source=f"global_workspace:{field}", confidence=85)

    memory_v2 = human_context.get("memory_v2") if isinstance(human_context.get("memory_v2"), dict) else {}
    for item in normalize_text_list(memory_v2.get("superseded_or_conflicting_beliefs"), limit=8):
        lowered = item.lower().lstrip()
        if lowered.startswith(("unresolved:", "unresolved conflict:", "(unresolved)", "contradiction:")):
            admit(item, source="human_context:unresolved_conflict", confidence=65)
    return records[: eve_consciousness.MAX_EPISTEMIC_CONFLICTS]


def _sensory_age_seconds(value: object, *, now: datetime) -> Optional[float]:
    observed = parse_iso_datetime(value)
    if observed is None:
        return None
    return max(0.0, (now - observed).total_seconds())


def collect_runtime_sensory_events(
    config: Dict[str, object],
    *,
    prefer_runtime: bool,
    now: Optional[datetime] = None,
    system_snapshot: Optional[Dict[str, object]] = None,
) -> List[Dict[str, object]]:
    """Collect concurrent typed features from Eve's admitted local senses.

    This deliberately does not start a camera, microphone, screen recorder, or
    unadmitted OpenClaw device stream. Those are separate permission-gated
    adapters. The always-on baseline sees recent human input, machine state,
    homeostatic state, action consequences, organ state, and any typed external
    sensory events already admitted to the local event spine.
    """
    current = now or datetime.now(timezone.utc)
    timestamp = current.replace(microsecond=0).isoformat()
    window_seconds = clamp_int(
        config.get("sensory_attention_window_seconds"),
        180,
        minimum=30,
        maximum=3600,
    )
    events: List[Dict[str, object]] = []

    # Social/exteroceptive input: only a recent lived human turn. Old chat is
    # memory, not a stimulus that should keep reorienting the present.
    for message in reversed(read_lived_messages(limit=24, prefer_runtime=prefer_runtime)):
        sender = normalize_text_value(message.get("sender"), fallback="", limit=40).lower()
        if sender in {"eve", "assistant", "system", "daemon"}:
            continue
        observed_at = message.get("timestamp") or message.get("created_at")
        age = _sensory_age_seconds(observed_at, now=current)
        if age is None or age > window_seconds:
            continue
        summary = normalize_text_value(
            message.get("body") or message.get("content") or message.get("text"),
            fallback=normalize_text_value(message.get("subject"), fallback="Recent human input", limit=180),
            limit=320,
        )
        events.append(
            {
                "id": f"lived-message:{normalize_text_value(message.get('id'), fallback='recent', limit=120)}",
                "observed_at": observed_at or timestamp,
                "modality": "social",
                "source": "lived_human_message",
                "subject": normalize_text_value(sender, fallback="human", limit=80),
                "correlation_id": normalize_text_value(message.get("thread_id"), fallback="", limit=120),
                "summary": summary,
                "intensity": 70,
                "novelty": 90,
                "change": 80,
                "urgency": 85,
                "goal_relevance": 95,
                "self_relevance": 75,
                "social_relevance": 100,
                "precision": 100,
                "direct_human": True,
                "privacy": "local_private",
                "permission_granted": True,
            }
        )
        break

    snapshot = (
        system_snapshot
        if isinstance(system_snapshot, dict)
        else load_system_snapshot(prefer_runtime=prefer_runtime)
    )
    if snapshot:
        load_state_name = normalize_text_value(snapshot.get("load_state"), fallback="unknown", limit=40).lower()
        load_level = {
            "quiet": 20,
            "normal": 30,
            "steady": 35,
            "busy": 60,
            "high": 72,
            "hot": 88,
            "critical": 98,
        }.get(load_state_name, 45)
        disk = snapshot.get("disk") if isinstance(snapshot.get("disk"), dict) else {}
        model_summary = normalize_text_value(snapshot.get("model_summary"), fallback="model state unknown", limit=120)
        disk_used = disk.get("strict_used_percent") if disk.get("strict_used_percent") is not None else disk.get("used_percent")
        summary = (
            f"Machine load is {load_state_name}; {model_summary}; "
            f"strict disk use is {disk_used if disk_used is not None else 'unknown'}%."
        )
        events.append(
            {
                "id": f"system-snapshot:{normalize_text_value(snapshot.get('timestamp'), fallback=timestamp, limit=80)}",
                "observed_at": snapshot.get("timestamp") or timestamp,
                "modality": "system",
                "source": "system_snapshot",
                "subject": "eve-machine",
                "summary": summary,
                "intensity": load_level,
                "novelty": 45,
                "change": 25,
                "urgency": max(15, load_level - 18),
                "goal_relevance": 70,
                "self_relevance": 90,
                "precision": 95,
                "safety_critical": load_state_name == "critical",
                "privacy": "local_private",
                "permission_granted": True,
            }
        )

    homeostasis = load_homeostasis(prefer_runtime=prefer_runtime)
    pressures = homeostasis.get("pressures") if isinstance(homeostasis.get("pressures"), list) else []
    pressure_records = [item for item in pressures if isinstance(item, dict)]
    pressure_records.sort(key=lambda item: int(item.get("level") or 0), reverse=True)
    if pressure_records:
        pressure = pressure_records[0]
        level = clamp_int(pressure.get("level"), 0, minimum=0, maximum=100)
        label = normalize_text_value(pressure.get("label") or pressure.get("id"), fallback="internal pressure", limit=80)
        reason = normalize_text_value(pressure.get("reason"), fallback="", limit=200)
        events.append(
            {
                "id": f"homeostasis:{normalize_text_value(pressure.get('id'), fallback=label, limit=80)}:{homeostasis.get('updated_at') or timestamp}",
                "observed_at": homeostasis.get("updated_at") or timestamp,
                "modality": "interoceptive",
                "source": "homeostasis",
                "subject": "eve-regulation",
                "summary": f"Dominant internal pressure is {label} at {level}/100" + (f": {reason}" if reason else "."),
                "intensity": level,
                "novelty": 55 if pressure.get("trend") in {"new", "rising"} else 25,
                "change": 60 if pressure.get("trend") in {"new", "rising"} else 15,
                "urgency": level,
                "goal_relevance": 65,
                "self_relevance": 100,
                "precision": 90,
                "privacy": "local_private",
                "permission_granted": True,
            }
        )

    actions = read_action_executions(limit=1, prefer_runtime=prefer_runtime)
    if actions:
        action = actions[0]
        age = _sensory_age_seconds(action.get("created_at") or action.get("updated_at"), now=current)
        if age is not None and age <= window_seconds:
            verified = bool(action.get("verification_ok") or action.get("result_ok"))
            action_id = normalize_text_value(action.get("action"), fallback="bounded_action", limit=80)
            summary = normalize_text_value(action.get("summary"), fallback="Action result observed.", limit=260)
            events.append(
                {
                    "id": f"action-execution:{normalize_text_value(action.get('id'), fallback=timestamp, limit=120)}",
                    "observed_at": action.get("created_at") or action.get("updated_at") or timestamp,
                    "modality": "proprioceptive",
                    "source": "verified_action_execution",
                    "subject": action_id,
                    "summary": f"Action {action_id} {'verified' if verified else 'did not verify'}: {summary}",
                    "intensity": 65 if verified else 85,
                    "novelty": 80,
                    "change": 75,
                    "urgency": 35 if verified else 90,
                    "goal_relevance": 90,
                    "self_relevance": 100,
                    "precision": 100,
                    "privacy": normalize_text_value(action.get("privacy_tier"), fallback="local_private", limit=40),
                    "permission_granted": True,
                }
            )

    pulses = read_organ_pulses(limit=1, prefer_runtime=prefer_runtime)
    if pulses:
        pulse = pulses[0]
        observed_at = pulse.get("generated_at") or pulse.get("created_at")
        age = _sensory_age_seconds(observed_at, now=current)
        organs = pulse.get("organs") if isinstance(pulse.get("organs"), list) else []
        attention = [
            normalize_text_value(item.get("label") or item.get("id"), fallback="organ", limit=80)
            for item in organs
            if isinstance(item, dict)
            and normalize_text_value(item.get("operational_status"), fallback="", limit=40).lower()
            not in {"ready", "working", "lab_ready"}
        ][:3]
        if age is not None and age <= max(window_seconds, 900) and attention:
            events.append(
                {
                    "id": f"organ-pulse:{normalize_text_value(observed_at, fallback=timestamp, limit=80)}",
                    "observed_at": observed_at or timestamp,
                    "modality": "world",
                    "source": "organ_assimilation",
                    "subject": "eve-organ-system",
                    "summary": "Organ state asks for attention: " + ", ".join(attention),
                    "intensity": 55,
                    "novelty": 45,
                    "change": 35,
                    "urgency": 45,
                    "goal_relevance": 70,
                    "self_relevance": 85,
                    "precision": 85,
                    "privacy": "local_private",
                    "permission_granted": True,
                }
            )

    # Go, Swift, OpenClaw, and future device adapters may publish typed events
    # here after admission. The normalizer strips any raw device fields again.
    db_path = (
        RUNTIME_OPERATIONAL_DB_PATH
        if prefer_runtime and RUNTIME_OPERATIONAL_DB_PATH.exists()
        else OPERATIONAL_DB_PATH
    )
    try:
        external_events = eve_db.read_events(
            db_path,
            limit=24,
            stream="sensory",
            kind="sensory.observed",
        )
    except (OSError, sqlite3.Error):
        external_events = []
    for record in reversed(external_events):
        payload = record.get("payload") if isinstance(record.get("payload"), dict) else {}
        candidate = payload.get("event") if isinstance(payload.get("event"), dict) else payload
        observed_at = candidate.get("observed_at") or record.get("created_at")
        age = _sensory_age_seconds(observed_at, now=current)
        if age is None or age > window_seconds:
            continue
        candidate = dict(candidate)
        candidate.setdefault("id", record.get("id"))
        candidate.setdefault("observed_at", observed_at)
        candidate.setdefault("source", record.get("source") or "typed_sensory_adapter")
        events.append(candidate)

    return [eve_sensory.normalize_event(item, now=timestamp) for item in events]


def sensory_frame_digest(frame: Dict[str, object]) -> str:
    winner = frame.get("winner") if isinstance(frame.get("winner"), dict) else {}
    orientation = frame.get("orienting_request") if isinstance(frame.get("orienting_request"), dict) else {}
    semantic = {
        "observations": [
            [item.get("modality"), item.get("source"), item.get("subject"), item.get("fingerprint")]
            for item in (frame.get("observations") or [])
            if isinstance(item, dict)
        ],
        "working_set": [
            [item.get("fingerprint"), item.get("disposition")]
            for item in (frame.get("working_set") or [])
            if isinstance(item, dict)
        ],
        "winner": [winner.get("fingerprint"), winner.get("disposition")],
        "orient": [orientation.get("target_fingerprint"), orientation.get("recommended_action")],
    }
    return hashlib.sha256(
        json.dumps(semantic, ensure_ascii=True, sort_keys=True).encode("utf-8")
    ).hexdigest()


def run_sensory_attention_tick(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    source: str,
    prefer_runtime: bool,
    system_snapshot: Optional[Dict[str, object]] = None,
    persist_event: bool = True,
    now: Optional[datetime] = None,
) -> Dict[str, object]:
    current = now or datetime.now(timezone.utc)
    prior = state.get("sensory_frame") if isinstance(state.get("sensory_frame"), dict) else {}
    observations = collect_runtime_sensory_events(
        config,
        prefer_runtime=prefer_runtime,
        now=current,
        system_snapshot=system_snapshot,
    )
    frame = eve_sensory.build_frame(
        observations,
        prior_frame=prior,
        now=current,
        capacity=clamp_int(config.get("sensory_attention_capacity"), 4, minimum=1, maximum=8),
        binding_window_seconds=clamp_int(config.get("sensory_binding_window_seconds"), 3, minimum=0, maximum=30),
        recovery_seconds=clamp_int(config.get("sensory_habituation_recovery_seconds"), 300, minimum=30, maximum=86400),
        orient_threshold=clamp_int(config.get("sensory_orient_threshold"), 68, minimum=35, maximum=100),
    )
    frame = eve_sensory.public_frame(frame)
    frame["privacy"]["explicit_private_session_adapter_available"] = parse_boolish(
        config.get("sensory_private_session_adapter_available", True)
    )
    frame["privacy"]["unattended_private_audio_capture_enabled"] = parse_boolish(
        config.get("sensory_private_audio_enabled", False)
    )
    frame["privacy"]["unattended_private_visual_capture_enabled"] = parse_boolish(
        config.get("sensory_private_visual_enabled", False)
    )
    digest = sensory_frame_digest(frame)
    state["sensory_frame"] = frame
    state["last_sensory_attention_at"] = frame.get("generated_at")
    state["sensory_attention_summary"] = (
        f"Observed {frame.get('observed_count')} signal(s) across {frame.get('modality_count')} modality type(s); "
        f"admitted {frame.get('admitted_count')}, habituated {frame.get('habituated_count')}, "
        f"ignored {frame.get('ignored_count')}."
    )
    previous_digest = normalize_text_value(state.get("sensory_frame_digest"), fallback="", limit=80)
    last_event_age = _sensory_age_seconds(state.get("last_sensory_frame_event_at"), now=current)
    should_record = bool(
        persist_event
        and (digest != previous_digest or last_event_age is None or last_event_age >= 600)
    )
    state["sensory_frame_digest"] = digest
    if should_record:
        db_path = (
            RUNTIME_OPERATIONAL_DB_PATH
            if prefer_runtime and (RUNTIME_OPERATIONAL_DB_PATH.exists() or running_from_runtime_bundle())
            else OPERATIONAL_DB_PATH
        )
        eve_db.record_event(
            db_path,
            kind="sensory.frame",
            source=source,
            actor="eve",
            stream="sensory",
            subject="selective_attention",
            correlation_id=digest,
            payload={"frame": frame},
            metadata={
                "persistence": "features_only",
                "raw_device_capture": False,
                "authority": "attention_evidence_only",
            },
        )
        state["last_sensory_frame_event_at"] = frame.get("generated_at")
    return frame


def load_sensory_frame(*, prefer_runtime: bool = False) -> Dict[str, object]:
    state = load_state(prefer_runtime=prefer_runtime)
    frame = state.get("sensory_frame") if isinstance(state.get("sensory_frame"), dict) else {}
    if frame:
        return eve_sensory.public_frame(frame)
    return eve_sensory.build_frame([], now=state.get("last_loop_at") or utc_now())


def format_sensory_attention_report(frame: Dict[str, object], *, full: bool = False) -> str:
    winner = frame.get("winner") if isinstance(frame.get("winner"), dict) else {}
    orientation = frame.get("orienting_request") if isinstance(frame.get("orienting_request"), dict) else {}
    lines = [
        "Eve selective perception",
        f"status: {frame.get('status') or 'quiet'}",
        f"generated_at: {frame.get('generated_at') or 'not yet'}",
        (
            f"signals: observed={frame.get('observed_count') or 0} modalities={frame.get('modality_count') or 0} "
            f"admitted={frame.get('admitted_count') or 0}/{frame.get('capacity') or 0} "
            f"ignored={frame.get('ignored_count') or 0} habituated={frame.get('habituated_count') or 0} "
            f"dishabituated={frame.get('dishabituated_count') or 0} bound={frame.get('bound_episode_count') or 0}"
        ),
        (
            f"winner: {winner.get('modality') or 'none'} | score={winner.get('attention_score') or 0} | "
            f"{winner.get('summary') or 'No signal won admission.'}"
        ),
        (
            f"orienting: {orientation.get('recommended_action') or 'none'} | "
            f"authority={orientation.get('authority') or 'none'} | "
            f"permission={'required' if orientation.get('requires_permission') else 'not_required'}"
        ),
    ]
    if full:
        for item in frame.get("working_set") or []:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- {item.get('modality')} | score={item.get('attention_score')} | "
                f"repeat={item.get('repeat_count', 1)} | source={item.get('source')} | {item.get('summary')}"
            )
        privacy = frame.get("privacy") if isinstance(frame.get("privacy"), dict) else {}
        lines.append("privacy: " + json.dumps(privacy, ensure_ascii=True, sort_keys=True))
    lines.append(f"boundary: {frame.get('boundary') or eve_sensory.BOUNDARY}")
    return "\n".join(lines)


def conscious_runtime_epoch(runtime_state: Dict[str, object]) -> str:
    """Return the shared daemon epoch used by every Eve process.

    Reply workers and the daemon are separate processes, so a process-local UUID
    would manufacture false restarts. The daemon start marker is persisted in
    Eve state and therefore gives all cooperating processes the same epoch.
    """
    started_at = normalize_text_value(runtime_state.get("daemon_started_at"), fallback="", limit=80)
    daemon_pid = normalize_text_value(runtime_state.get("daemon_process_id"), fallback="", limit=32)
    if started_at:
        return f"daemon:{started_at}:pid:{daemon_pid or 'unknown'}"
    code_path = normalize_text_value(runtime_state.get("daemon_code_path"), fallback="", limit=180)
    return f"runtime-unobserved:{code_path or 'unknown'}"


def build_recurrent_conscious_state(
    *,
    source: str,
    workspace: Optional[Dict[str, object]] = None,
    self_model: Optional[Dict[str, object]] = None,
    world_model: Optional[Dict[str, object]] = None,
    relationship_model: Optional[Dict[str, object]] = None,
    other_minds_model: Optional[Dict[str, object]] = None,
    homeostasis: Optional[Dict[str, object]] = None,
    plan_model: Optional[Dict[str, object]] = None,
    inbound: object = "",
    latest_outcome: Optional[Dict[str, object]] = None,
    persist: bool = True,
    lesions: Optional[Iterable[str]] = None,
    learned_epistemic_enabled: bool = True,
    epistemic_frame_override: Optional[Dict[str, object]] = None,
    sensory_frame_override: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    prefer_runtime = source.startswith(("daemon", "reply", "presence", "chat")) or running_from_runtime_bundle()
    workspace = normalize_global_workspace(workspace if isinstance(workspace, dict) else load_global_workspace(prefer_runtime=prefer_runtime))
    self_model = normalize_self_model_state(self_model if isinstance(self_model, dict) else load_self_model_state(prefer_runtime=prefer_runtime))
    world_model = normalize_world_model_state(world_model if isinstance(world_model, dict) else load_world_model_state(prefer_runtime=prefer_runtime))
    relationship_model = normalize_relationship_model_state(
        relationship_model if isinstance(relationship_model, dict) else load_relationship_model_state(prefer_runtime=prefer_runtime)
    )
    other_minds_model = normalize_other_minds_model_state(
        other_minds_model if isinstance(other_minds_model, dict) else load_other_minds_model_state(prefer_runtime=prefer_runtime)
    )
    homeostasis = normalize_homeostasis_state(homeostasis if isinstance(homeostasis, dict) else load_homeostasis(prefer_runtime=prefer_runtime))
    conscious_plan_model = (
        dict(plan_model)
        if isinstance(plan_model, dict)
        else build_conscious_plan_model(prefer_runtime=prefer_runtime)
    )
    previous = load_conscious_state(prefer_runtime=prefer_runtime)
    autonomy_agenda = load_autonomy_agenda(prefer_runtime=prefer_runtime)
    human_context = load_human_context(prefer_runtime=prefer_runtime)
    memory_query = " ".join(
        unique_compact(
            [
                inbound,
                (workspace.get("workspace_state") or {}).get("focus") if isinstance(workspace.get("workspace_state"), dict) else "",
                *(workspace.get("active_goals") or [])[:3],
                *(workspace.get("continuity_threads") or [])[:2],
            ],
            limit=8,
        )
    )
    memory_items = select_conscious_memory_items(memory_query, prefer_runtime=prefer_runtime, limit=6)
    runtime_state = load_state(prefer_runtime=prefer_runtime)
    sensory_frame = (
        eve_sensory.public_frame(sensory_frame_override)
        if isinstance(sensory_frame_override, dict)
        else runtime_state.get("sensory_frame")
        if isinstance(runtime_state.get("sensory_frame"), dict)
        else eve_sensory.build_frame([], now=utc_now())
    )
    conflict_items = conscious_epistemic_conflict_items(
        workspace=workspace,
        human_context=human_context,
    )
    learned_epistemic_frame = (
        (
            epistemic_frame_override
            if isinstance(epistemic_frame_override, dict)
            else eve_epistemic.build_frame(inbound)
        )
        if learned_epistemic_enabled
        else eve_epistemic.lesioned_frame()
    )
    runtime_epoch = conscious_runtime_epoch(runtime_state)
    revision_rounds = int(runtime_state.get("last_mind_stream_revision_count") or 0)
    # Do not treat the newest runtime action as the consequence of this
    # recurrent state's prior prediction. The kernel admits feedback only when
    # an explicit source cycle and action match, or when the exact prior cycle
    # already contains its completed outcome.
    conscious_state = eve_consciousness.build_conscious_state(
        source=source,
        workspace=workspace,
        self_model=self_model,
        world_model=world_model,
        relationship_model=relationship_model,
        other_minds_model=other_minds_model,
        homeostasis=homeostasis,
        plan_model=conscious_plan_model,
        autonomy_agenda=autonomy_agenda,
        memory_items=memory_items,
        sensory_frame=sensory_frame,
        inbound=inbound,
        previous_state=previous,
        latest_outcome=latest_outcome,
        revision_rounds=revision_rounds,
        conflict_items=conflict_items,
        epistemic_frame=learned_epistemic_frame,
        runtime_epoch=runtime_epoch,
        lesions=lesions,
    )
    conscious_state = normalize_conscious_state(conscious_state)
    if persist and not conscious_state.get("lesions"):
        expected_previous_cycle_id = normalize_text_value(
            (conscious_state.get("recurrent") or {}).get("previous_cycle_id")
            if isinstance(conscious_state.get("recurrent"), dict)
            else "",
            fallback="",
            limit=80,
        )

        def persist_opened_cycle(payload: Dict[str, object]) -> Dict[str, object]:
            latest = normalize_conscious_state(payload)
            latest_cycle_id = normalize_text_value(latest.get("cycle_id"), fallback="", limit=80)
            opened_cycle_id = normalize_text_value(conscious_state.get("cycle_id"), fallback="", limit=80)
            concurrent = bool(
                latest_cycle_id
                and latest_cycle_id != opened_cycle_id
                and latest_cycle_id != expected_previous_cycle_id
            )
            persisted = (
                normalize_conscious_state(
                    eve_consciousness.merge_concurrent_lineage_into_opened_state(conscious_state, latest)
                )
                if concurrent
                else conscious_state
            )
            payload.clear()
            payload.update(json.loads(json.dumps(persisted)))
            return {"state": persisted, "concurrent": concurrent, "latest_cycle_id": latest_cycle_id}

        persistence = CONSCIOUS_STATE_REPOSITORY.update(persist_opened_cycle)
        if isinstance(persistence, dict) and isinstance(persistence.get("state"), dict):
            conscious_state = normalize_conscious_state(persistence["state"])
        append_conscious_state_audit_event(conscious_state, event="cycle_opened", source=source)
        if isinstance(persistence, dict) and persistence.get("concurrent"):
            append_conscious_state_audit_event(
                conscious_state,
                event="cycle_opened_concurrent_lineage_merged",
                source=source,
            )
    return conscious_state


def complete_recurrent_conscious_cycle(
    *,
    actual_process: Dict[str, object],
    outcome: Dict[str, object],
    source: str,
    opened_state: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Complete the exact cycle that made the prediction, then join its learning.

    More than one reply/autonomy/daemon cycle may be open at once. Loading the
    latest state here used to assign a delayed outcome to whichever cycle had
    most recently won attention. ``opened_state`` preserves causal attribution;
    the repository mutation then joins only learned consequences when a newer
    broadcast already exists.
    """
    current = (
        normalize_conscious_state(opened_state)
        if isinstance(opened_state, dict) and opened_state.get("cycle_id")
        else load_conscious_state(prefer_runtime=source.startswith("reply") or running_from_runtime_bundle())
    )
    completed = eve_consciousness.complete_cycle(
        current,
        actual_process=actual_process,
        outcome=outcome,
    )
    completed = normalize_conscious_state(completed)

    def persist_completion(payload: Dict[str, object]) -> Dict[str, object]:
        latest = normalize_conscious_state(payload)
        latest_cycle_id = normalize_text_value(latest.get("cycle_id"), fallback="", limit=80)
        completed_cycle_id = normalize_text_value(completed.get("cycle_id"), fallback="", limit=80)
        joined = bool(latest_cycle_id and completed_cycle_id and latest_cycle_id != completed_cycle_id)
        persisted = (
            normalize_conscious_state(eve_consciousness.merge_completed_cycle_into_current(latest, completed))
            if joined
            else completed
        )
        payload.clear()
        payload.update(json.loads(json.dumps(persisted)))
        return {
            "joined": joined,
            "persisted_cycle_id": normalize_text_value(persisted.get("cycle_id"), fallback="", limit=80),
            "completed_cycle_id": completed_cycle_id,
            "state": persisted,
        }

    persistence = CONSCIOUS_STATE_REPOSITORY.update(persist_completion)
    append_conscious_state_audit_event(completed, event="cycle_completed", source=source)
    persistence = persistence if isinstance(persistence, dict) else {}
    if persistence.get("joined") and isinstance(persistence.get("state"), dict):
        append_conscious_state_audit_event(
            persistence["state"],
            event="cycle_completion_joined",
            source=source,
        )
    result = json.loads(json.dumps(completed))
    result["completion_persistence"] = {
        "joined": bool(persistence.get("joined")),
        "persisted_cycle_id": normalize_text_value(persistence.get("persisted_cycle_id"), fallback="", limit=80),
        "completed_cycle_id": normalize_text_value(persistence.get("completed_cycle_id"), fallback="", limit=80),
    }
    return result


def build_quiet_consolidation_text(
    *,
    workspace: Dict[str, object],
    homeostasis: Dict[str, object],
    relationship_model: Dict[str, object],
    other_minds_model: Dict[str, object],
    recent_entries: List[Dict[str, object]],
    recent_messages: List[Dict[str, object]],
    open_system_tasks: List[Dict[str, object]],
) -> str:
    normalized_workspace = normalize_global_workspace(workspace)
    normalized_homeostasis = normalize_homeostasis_state(homeostasis)
    normalized_relationship = normalize_relationship_model_state(relationship_model)
    normalized_other_minds = normalize_other_minds_model_state(other_minds_model)
    entry_labels = [
        normalize_text_value(item.get("text"), fallback="", limit=140)
        for item in recent_entries[:3]
        if isinstance(item, dict)
    ]
    message_labels = [
        human_analog_message_label(item)
        for item in recent_messages[:3]
        if isinstance(item, dict)
    ]
    task_labels = [
        normalize_text_value(item.get("summary") or item.get("title"), fallback="", limit=140)
        for item in open_system_tasks[:3]
        if isinstance(item, dict)
    ]
    carry_forward = unique_compact(
        [
            *(normalized_workspace.get("continuity_threads") or [])[:3],
            *(normalized_workspace.get("action_readiness") or [])[:2],
            normalized_homeostasis.get("next_regulation_step"),
            normalized_relationship.get("next_relational_move"),
        ],
        limit=10,
    )
    carry_forward = foreground_safe_text_list(carry_forward, limit=5)
    sections = [
        "Quiet-period consolidation.",
        f"Workspace: {normalized_workspace.get('summary') or 'none recorded'}",
        f"Current experience: {normalized_workspace.get('current_experience') or 'none recorded'}",
        f"Dominant pressures: {format_human_context_list(normalized_homeostasis.get('dominant_pressures') or [])}",
        f"Continuity threads: {format_human_context_list(normalized_workspace.get('continuity_threads') or [])}",
        f"Surprise signals: {format_human_context_list(normalized_workspace.get('surprise_signals') or [])}",
        f"Consequence trace: {format_human_context_list(normalized_workspace.get('consequence_trace') or [])}",
        f"Carry forward: {format_human_context_list(carry_forward)}",
        f"Relationship: {normalized_relationship.get('relationship_state') or 'none recorded'}",
        f"Other minds: {normalized_other_minds.get('summary') or 'none recorded'}",
        f"Recent journal: {format_human_context_list(entry_labels)}",
        f"Recent messages: {format_human_context_list(message_labels)}",
        f"Open system tasks: {format_human_context_list(task_labels)}",
    ]
    return "\n".join(sections)


def run_quiet_period_consolidation(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    source: str,
    workspace_bundle: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    bundle = workspace_bundle or {
        "workspace": load_global_workspace(prefer_runtime=source.startswith("daemon")),
        "self_model": load_self_model_state(prefer_runtime=source.startswith("daemon")),
        "world_model": load_world_model_state(prefer_runtime=source.startswith("daemon")),
        "relationship_model": load_relationship_model_state(prefer_runtime=source.startswith("daemon")),
        "other_minds_model": load_other_minds_model_state(prefer_runtime=source.startswith("daemon")),
        "homeostasis": load_homeostasis(prefer_runtime=source.startswith("daemon")),
    }
    workspace = normalize_global_workspace(bundle.get("workspace") if isinstance(bundle.get("workspace"), dict) else {})
    homeostasis = normalize_homeostasis_state(bundle.get("homeostasis") if isinstance(bundle.get("homeostasis"), dict) else {})
    relationship_model = normalize_relationship_model_state(
        bundle.get("relationship_model") if isinstance(bundle.get("relationship_model"), dict) else {}
    )
    other_minds_model = normalize_other_minds_model_state(
        bundle.get("other_minds_model") if isinstance(bundle.get("other_minds_model"), dict) else {}
    )
    recent_entries = read_salient_entries(limit=6, since_days=7)
    recent_messages = read_lived_messages(limit=6)
    open_system_tasks = read_system_tasks(limit=10, status=["planned", "in_progress", "blocked"])
    carry_forward = unique_compact(
        [
            *(workspace.get("continuity_threads") or [])[:3],
            *(workspace.get("action_readiness") or [])[:2],
            homeostasis.get("next_regulation_step"),
            relationship_model.get("next_relational_move"),
            *[
                normalize_text_value(task.get("summary") or task.get("title"), fallback="", limit=140)
                for task in open_system_tasks[:2]
                if isinstance(task, dict)
            ],
        ],
        limit=12,
    )
    carry_forward = foreground_safe_text_list(carry_forward, limit=6)
    summary = normalize_text_value(
        (
            f"Quiet consolidation held {len(workspace.get('continuity_threads') or [])} continuity thread(s), "
            f"{len(workspace.get('surprise_signals') or [])} surprise signal(s), and "
            f"{len(open_system_tasks)} open system task(s) in a {homeostasis.get('regulation_mode') or 'steady'} mode."
        ),
        fallback="Quiet consolidation completed.",
        limit=220,
    )
    record = {
        "updated_at": utc_now(),
        "source": source,
        "summary": summary,
        "carry_forward": carry_forward,
        "dominant_pressures": normalize_text_list(homeostasis.get("dominant_pressures"), limit=4),
        "continuity_threads": normalize_text_list(workspace.get("continuity_threads"), limit=6),
        "surprise_signals": normalize_text_list(workspace.get("surprise_signals"), limit=5),
        "consequence_trace": normalize_text_list(workspace.get("consequence_trace"), limit=6),
        "regulation_mode": normalize_text_value(homeostasis.get("regulation_mode"), fallback="steady", limit=40),
        "next_regulation_step": normalize_text_value(homeostasis.get("next_regulation_step"), fallback="", limit=220),
    }
    prefer_runtime = source.startswith("daemon") or running_from_runtime_bundle()
    presence_cycle_episodes = extract_presence_cycle_episodes(
        config,
        source=f"{source}_presence_cycle_episode_extraction",
        prefer_runtime=prefer_runtime,
    )
    distilled_presence_context = distill_presence_cycle_episodes_to_human_context(
        presence_cycle_episodes,
        source=f"{source}_presence_cycle_distillation",
        prefer_runtime=prefer_runtime,
    )
    if presence_cycle_episodes:
        record["presence_cycle_episodes_created"] = len(presence_cycle_episodes)
        record["presence_cycle_episode_ids"] = [
            normalize_text_value(item.get("id"), fallback="", limit=80)
            for item in presence_cycle_episodes
            if isinstance(item, dict)
        ]
        record["semantic_distillation"] = {
            "updated": bool(distilled_presence_context),
            "semantic_understanding": (
                (distilled_presence_context.get("memory_v2") or {}).get("semantic_understanding")
                if isinstance(distilled_presence_context.get("memory_v2"), dict)
                else []
            )[:3],
            "episodic_markers": (
                (distilled_presence_context.get("memory_v2") or {}).get("episodic_markers")
                if isinstance(distilled_presence_context.get("memory_v2"), dict)
                else []
            )[:3],
        }
    append_entry(
        "quiet_consolidation",
        build_quiet_consolidation_text(
            workspace=workspace,
            homeostasis=homeostasis,
            relationship_model=relationship_model,
            other_minds_model=other_minds_model,
            recent_entries=recent_entries,
            recent_messages=recent_messages,
            open_system_tasks=open_system_tasks,
        ),
        metadata={
            "source": source,
            "summary": summary,
            "carry_forward": carry_forward,
            "dominant_pressures": record["dominant_pressures"],
            "regulation_mode": record["regulation_mode"],
            "presence_cycle_episodes_created": record.get("presence_cycle_episodes_created", 0),
        },
    )
    state["last_quiet_consolidation_at"] = record["updated_at"]
    state["last_quiet_consolidation_attempt_at"] = record["updated_at"]
    state["quiet_consolidation_summary"] = summary
    state["quiet_consolidation_carry_forward"] = carry_forward
    if presence_cycle_episodes:
        state["last_presence_cycle_episode_extraction_at"] = record["updated_at"]
        state["last_presence_cycle_episode_ids"] = record["presence_cycle_episode_ids"]
    return record


def scrub_background_carry_forward_state(state: Dict[str, object], *, workspace: Optional[Dict[str, object]] = None) -> Dict[str, object]:
    workspace = normalize_global_workspace(workspace or {})
    state["quiet_consolidation_carry_forward"] = foreground_safe_text_list(
        state.get("quiet_consolidation_carry_forward"),
        limit=6,
    )
    if text_indicates_carry_forward_contamination(state.get("quiet_consolidation_summary")):
        state["quiet_consolidation_summary"] = normalize_text_value(
            "Quiet consolidation has no safe foreground carry-forward yet.",
            fallback="Quiet consolidation completed.",
            limit=220,
        )
    if text_indicates_carry_forward_contamination(state.get("last_autonomy_run_summary")):
        safe_summary = normalize_text_value(
            workspace.get("summary"),
            fallback="Previous autonomy run has no safe foreground carry-forward.",
            limit=220,
        )
        if text_indicates_carry_forward_contamination(safe_summary):
            safe_summary = "Previous autonomy run has no safe foreground carry-forward."
        state["last_autonomy_run_summary"] = safe_summary
    return state


def refresh_global_workspace(source: str = "manual", *, persist: bool = True) -> Dict[str, object]:
    config = load_config()
    previous_workspace = load_global_workspace()
    previous_homeostasis = load_homeostasis()
    previous_world_model = load_world_model_state(prefer_runtime=True)
    runtime_identity = ensure_runtime_identity()
    human_context = load_human_context()
    active_mind = load_active_mind()
    state = recompute_humanity_learning_summaries(load_state())
    system_snapshot = load_system_snapshot(prefer_runtime=True)
    openclaw_status = eve_openclaw.collect_openclaw_status(config, prefer_runtime=True, include_gateway_probe=False)
    if focus_needs_live_reanchor(
        active_mind.get("current_focus"),
        system_snapshot=system_snapshot,
        openclaw_status=openclaw_status,
    ):
        objective_reanchor = objective_reanchor_from_agenda(
            config,
            system_snapshot,
            openclaw_status=openclaw_status,
        )
        replacement_focus = normalize_text_value(objective_reanchor.get("focus"), fallback="", limit=160)
        if replacement_focus:
            active_mind = merge_active_mind(
                active_mind,
                {
                    "updated_at": utc_now(),
                    "source": f"{source}_objective_reanchor",
                    "model": "deterministic",
                    "summary": normalize_text_value(
                        f"{replacement_focus} Next check: {objective_reanchor.get('next_step') or 'advance one grounded action.'}",
                        fallback=DEFAULT_ACTIVE_MIND["summary"],
                        limit=220,
                    ),
                    "current_focus": replacement_focus,
                    "next_step": normalize_text_value(
                        objective_reanchor.get("next_step"),
                        fallback="Advance one grounded action from the carry-forward objective.",
                        limit=220,
                    ),
                    "next_step_provenance": active_mind_next_step_provenance(
                        objective_reanchor.get("next_step"),
                        source_kind=(
                            "autonomy_agenda"
                            if objective_reanchor.get("source_id")
                            else "operational_reanchor"
                        ),
                        source_id=objective_reanchor.get("source_id")
                        or objective_reanchor.get("preferred_action")
                        or replacement_focus,
                        evidence=objective_reanchor.get("why")
                        or objective_reanchor.get("evidence"),
                    ),
                },
            )
    threads = read_thread_summaries(limit=12)
    messages = read_lived_messages(limit=12, prefer_runtime=source.startswith("daemon"))
    open_system_tasks = read_system_tasks(limit=16, status=["planned", "in_progress", "blocked"])
    uncertainty_records = read_uncertainty_records(limit=40, since_days=30)
    judgment_records = read_judgment_calls(limit=40, since_days=30)
    outcomes = read_outcomes(limit=40, since_days=30)
    action_executions = read_action_executions(limit=24, since_days=14)
    evidence_records = read_evidence_ledger(limit=16, active_only=True, prefer_runtime=True)
    experience_events = read_experience_events(limit=16, prefer_runtime=True)
    commitments = read_commitments(limit=12, prefer_runtime=True)
    user_corrections = read_user_corrections(limit=8, status="open", prefer_runtime=True)
    relationship_episodes = read_relationship_episodes(limit=8, prefer_runtime=True)

    homeostasis = build_homeostasis_state(
        source=source,
        human_context=human_context,
        active_mind=active_mind,
        state=state,
        system_snapshot=system_snapshot,
        threads=threads,
        uncertainty_records=uncertainty_records,
        judgment_records=judgment_records,
        outcomes=outcomes,
        action_executions=action_executions,
        open_system_tasks=open_system_tasks,
        previous_homeostasis=previous_homeostasis,
    )
    self_model = build_self_model_state(
        source=source,
        runtime_identity=runtime_identity,
        human_context=human_context,
        active_mind=active_mind,
        state=state,
        homeostasis=homeostasis,
        threads=threads,
        messages=messages,
    )
    world_model = build_world_model_state(
        source=source,
        system_snapshot=system_snapshot,
        state=state,
        openclaw_status=openclaw_status,
        previous_world_model=previous_world_model,
    )
    relationship_model = build_relationship_model_state(
        source=source,
        human_context=human_context,
        active_mind=active_mind,
        threads=threads,
        messages=messages,
        outcomes=outcomes,
    )
    other_minds_model = build_other_minds_model_state(
        source=source,
        human_context=human_context,
        relationship_model=relationship_model,
        active_mind=active_mind,
        system_snapshot=system_snapshot,
        messages=messages,
        action_executions=action_executions,
    )
    workspace = build_global_workspace_state(
        source=source,
        active_mind=active_mind,
        system_snapshot=system_snapshot,
        self_model=self_model,
        world_model=world_model,
        relationship_model=relationship_model,
        other_minds_model=other_minds_model,
        homeostasis=homeostasis,
        open_system_tasks=open_system_tasks,
        action_executions=action_executions,
        outcomes=outcomes,
        uncertainty_records=uncertainty_records,
        judgment_records=judgment_records,
        evidence_records=evidence_records,
        experience_events=experience_events,
        commitments=commitments,
        user_corrections=user_corrections,
        relationship_episodes=relationship_episodes,
        threads=threads,
        messages=messages,
    )

    if persist:
        save_self_model_state(self_model)
        save_world_model_state(world_model)
        save_relationship_model_state(relationship_model)
        save_other_minds_model_state(other_minds_model)
        save_homeostasis(homeostasis)
        save_global_workspace(workspace)
        audit_event = append_global_workspace_audit_event(previous_workspace, workspace, source=source)
    else:
        audit_event = None
    conscious_state = build_recurrent_conscious_state(
        source=f"{source}_conscious_cycle",
        workspace=workspace,
        self_model=self_model,
        world_model=world_model,
        relationship_model=relationship_model,
        other_minds_model=other_minds_model,
        homeostasis=homeostasis,
        persist=persist,
    )
    projected_active_mind = project_active_mind_from_workspace(
        previous_mind=active_mind,
        workspace=workspace,
        self_model=self_model,
        world_model=world_model,
        relationship_model=relationship_model,
        homeostasis=homeostasis,
        threads=threads,
        messages=messages,
        source=f"{source}_workspace_view",
        conscious_state=conscious_state,
    )
    if persist and normalize_active_mind(projected_active_mind) != normalize_active_mind(active_mind):
        save_active_mind(projected_active_mind)

    if persist:
        tick_at = workspace.get("updated_at") or utc_now()
        state["last_workspace_tick_at"] = tick_at
        state["global_workspace_summary"] = normalize_text_value(workspace.get("summary"), fallback="", limit=220)
        state["homeostasis_summary"] = normalize_text_value(homeostasis.get("summary"), fallback="", limit=220)
        state["homeostasis_mode"] = normalize_text_value(homeostasis.get("regulation_mode"), fallback="steady", limit=40)
        state["dominant_pressures"] = normalize_text_list(homeostasis.get("dominant_pressures"), limit=4)
        state["self_model_summary"] = normalize_text_value(self_model.get("current_state"), fallback="", limit=220)
        state["world_model_summary"] = normalize_text_value(world_model.get("environment_summary"), fallback="", limit=220)
        state["relationship_state_summary"] = normalize_text_value(relationship_model.get("relationship_state"), fallback="", limit=220)
        state["other_minds_summary"] = normalize_text_value(other_minds_model.get("summary"), fallback="", limit=220)
        state["last_conscious_cycle_at"] = conscious_state.get("updated_at")
        state["last_conscious_cycle_id"] = normalize_text_value(conscious_state.get("cycle_id"), fallback="", limit=80)
        state["conscious_cycle_status"] = normalize_text_value(conscious_state.get("status"), fallback="unknown", limit=40)
        state["conscious_broadcast"] = normalize_text_value(
            (conscious_state.get("broadcast") or {}).get("content")
            if isinstance(conscious_state.get("broadcast"), dict)
            else "",
            fallback="",
            limit=220,
        )
        state["current_focus"] = normalize_text_value(projected_active_mind.get("current_focus"), fallback="", limit=160)
        state["last_active_mind_refresh_at"] = projected_active_mind.get("updated_at") or state.get("last_active_mind_refresh_at")
        state["last_active_mind_refresh_source"] = normalize_text_value(
            projected_active_mind.get("source"),
            fallback=state.get("last_active_mind_refresh_source") or source,
            limit=120,
        )
        state = scrub_background_carry_forward_state(state, workspace=workspace)
        save_state(state)

    if persist and source.startswith("manual"):
        append_entry(
            "workspace_tick",
            str(workspace.get("summary") or DEFAULT_GLOBAL_WORKSPACE["summary"]),
            metadata={
                "source": source,
                "regulation_mode": homeostasis.get("regulation_mode"),
                "dominant_pressures": homeostasis.get("dominant_pressures", []),
                "audit_logged": bool(audit_event),
            },
        )
    return {
        "workspace": workspace,
        "self_model": self_model,
        "world_model": world_model,
        "relationship_model": relationship_model,
        "other_minds_model": other_minds_model,
        "homeostasis": homeostasis,
        "conscious_state": conscious_state,
        "active_mind": projected_active_mind,
        "audit_event": audit_event,
        "persisted": bool(persist),
    }


def format_global_workspace_report(workspace: Dict[str, object], full: bool = False) -> str:
    normalized = normalize_global_workspace(workspace)
    lines = [
        f"updated_at: {normalized.get('updated_at') or 'never'}",
        f"source: {normalized.get('source') or 'unknown'}",
        f"summary: {normalized['summary']}",
        f"current_experience: {normalized['current_experience']}",
        f"dominant_pressures: {format_human_context_list(normalized['dominant_pressures'])}",
        f"active_goals: {format_human_context_list(normalized['active_goals'])}",
        f"action_readiness: {format_human_context_list(normalized['action_readiness'])}",
    ]
    if full:
        workspace_state = normalized["workspace_state"]
        boundary = normalized["self_world_boundary"]
        lines.extend(
            [
                f"salient_percepts: {format_human_context_list(normalized['salient_percepts'])}",
                f"prediction_errors: {format_human_context_list(normalized['prediction_errors'])}",
                f"continuity_threads: {format_human_context_list(normalized['continuity_threads'])}",
                f"surprise_signals: {format_human_context_list(normalized['surprise_signals'])}",
                f"consequence_trace: {format_human_context_list(normalized['consequence_trace'])}",
                f"workspace_state: focus={workspace_state['focus']} | mode={workspace_state['mode']} | frontmost_app={workspace_state['frontmost_app'] or 'unknown'} | load={workspace_state['load_state'] or 'unknown'}",
                f"self_boundary: {boundary['self']}",
                f"world_boundary: {boundary['world']}",
                f"others_boundary: {boundary['others']}",
                f"unknowns: {format_human_context_list(boundary['unknowns'])}",
                f"next_refresh: {normalized['next_refresh']}",
            ]
        )
    return "\n".join(lines)


def format_conscious_state_report(state: Dict[str, object], full: bool = False) -> str:
    normalized = normalize_conscious_state(state)
    recurrent = normalized.get("recurrent") if isinstance(normalized.get("recurrent"), dict) else {}
    broadcast = normalized.get("broadcast") if isinstance(normalized.get("broadcast"), dict) else {}
    goals = normalized.get("goals") if isinstance(normalized.get("goals"), dict) else {}
    action_model = normalized.get("action_model") if isinstance(normalized.get("action_model"), dict) else {}
    intention = action_model.get("selected_intention") if isinstance(action_model.get("selected_intention"), dict) else {}
    predictions = normalized.get("predictions") if isinstance(normalized.get("predictions"), dict) else {}
    process = predictions.get("process") if isinstance(predictions.get("process"), dict) else {}
    metacognition = normalized.get("metacognition") if isinstance(normalized.get("metacognition"), dict) else {}
    interoception = normalized.get("interoception") if isinstance(normalized.get("interoception"), dict) else {}
    interoceptive_error = interoception.get("prediction_error") if isinstance(interoception.get("prediction_error"), dict) else {}
    epistemic = normalized.get("epistemic_state") if isinstance(normalized.get("epistemic_state"), dict) else {}
    memory = normalized.get("memory") if isinstance(normalized.get("memory"), dict) else {}
    perception = normalized.get("perception") if isinstance(normalized.get("perception"), dict) else {}
    sensory_frame = perception.get("sensory_frame") if isinstance(perception.get("sensory_frame"), dict) else {}
    sensory_winner = sensory_frame.get("winner") if isinstance(sensory_frame.get("winner"), dict) else {}
    lines = [
        f"schema: {normalized.get('schema_version')}",
        f"cycle: {normalized.get('cycle_id') or 'never'} | index={normalized.get('cycle_index') or 0} | status={normalized.get('status') or 'unknown'}",
        f"updated_at: {normalized.get('updated_at') or 'never'}",
        f"source: {normalized.get('source') or 'unknown'}",
        f"broadcast: {broadcast.get('content') or 'none'}",
        f"ignition: {broadcast.get('ignition_score') or 0} | access={format_human_context_list(broadcast.get('access_scope') or [])}",
        f"continuity: {recurrent.get('continuity_strength') or 0}/100 | mode={recurrent.get('continuity_mode') or 'unknown'} | previous={recurrent.get('previous_cycle_id') or 'none'} | elapsed={recurrent.get('elapsed_since_previous_seconds') if recurrent.get('elapsed_since_previous_seconds') is not None else 'unknown'}s | restart={'yes' if recurrent.get('runtime_epoch_changed') else 'no'} | checkpoint={recurrent.get('previous_checkpoint_integrity') or 'unknown'} | joined={recurrent.get('branch_join_count') or 0}",
        f"goal: {goals.get('selected_goal') or 'none'}",
        f"intention: {intention.get('description') or 'none'} | value={intention.get('value') if intention else 'n/a'}",
        f"process_prediction: budget={process.get('budget') or 'unknown'} lanes={format_human_context_list(process.get('lanes') or [])} tools={'yes' if process.get('needs_tools') else 'no'} memory={'yes' if process.get('needs_memory') else 'no'} revision={'yes' if process.get('needs_revision') else 'no'}",
        f"metacognition: confidence={metacognition.get('confidence') or 0}/100 uncertainty_targets={metacognition.get('uncertainty_count') or 0}",
        f"interoception: mode={interoception.get('regulation_mode') or 'steady'} valence={interoception.get('valence') or 0} arousal={interoception.get('arousal') or 0} prediction_error={interoceptive_error.get('error_magnitude') or 0}",
        f"epistemic_conflicts: unresolved={epistemic.get('unresolved_count') or 0}",
        f"memory: available={'yes' if memory.get('available') else 'no'} anchors={len(memory.get('continuity_anchors') or [])}",
        (
            f"sensory_attention: observed={sensory_frame.get('observed_count') or 0} "
            f"modalities={sensory_frame.get('modality_count') or 0} admitted={sensory_frame.get('admitted_count') or 0} "
            f"winner={sensory_winner.get('modality') or 'none'}"
        ),
    ]
    if full:
        lines.extend(
            [
                f"why_selected: {broadcast.get('why_selected') or 'unknown'}",
                f"source_kinds: {format_human_context_list(broadcast.get('source_kinds') or [])}",
                f"alternatives: {format_human_context_list([item.get('content') for item in perception.get('alternatives') or [] if isinstance(item, dict)])}",
                f"goal_stack: {format_human_context_list([item.get('text') for item in goals.get('stack') or [] if isinstance(item, dict)])}",
                f"affordances: {format_human_context_list([str(item.get('id')) + '=' + str(item.get('value')) for item in action_model.get('affordances') or [] if isinstance(item, dict)])}",
                f"process_forecast: lanes={format_human_context_list(process.get('forecast_lanes') or process.get('lanes') or [])} required_lanes={format_human_context_list(process.get('required_lanes') or [])} effective_lanes={format_human_context_list(process.get('lanes') or [])}",
                f"calibration_targets: {format_human_context_list(metacognition.get('calibration_targets') or [])}",
                f"provenance: {format_human_context_list(normalized.get('causal_provenance') or [])}",
                f"sensory_frame: {json.dumps(sensory_frame, ensure_ascii=True, sort_keys=True)}",
                f"cycle_outcome: {json.dumps(normalized.get('cycle_outcome') or {}, ensure_ascii=True, sort_keys=True)}",
                f"learning: {json.dumps(normalized.get('learning') or {}, ensure_ascii=True, sort_keys=True)}",
            ]
        )
    return "\n".join(lines)


def run_conscious_state_ablation(*, prefer_runtime: bool = True) -> Dict[str, object]:
    workspace = load_global_workspace(prefer_runtime=prefer_runtime)
    self_model = load_self_model_state(prefer_runtime=prefer_runtime)
    world_model = load_world_model_state(prefer_runtime=prefer_runtime)
    relationship_model = load_relationship_model_state(prefer_runtime=prefer_runtime)
    other_minds_model = load_other_minds_model_state(prefer_runtime=prefer_runtime)
    homeostasis = load_homeostasis(prefer_runtime=prefer_runtime)
    previous = load_conscious_state(prefer_runtime=prefer_runtime)
    agenda = load_autonomy_agenda(prefer_runtime=prefer_runtime)
    query = " ".join(
        unique_compact(
            [
                (workspace.get("workspace_state") or {}).get("focus") if isinstance(workspace.get("workspace_state"), dict) else "",
                *(workspace.get("active_goals") or [])[:3],
                *(workspace.get("continuity_threads") or [])[:3],
            ],
            limit=8,
        )
    )
    memory_items = select_conscious_memory_items(query, prefer_runtime=prefer_runtime, limit=6)
    return eve_consciousness.run_causal_ablation_suite(
        {
            "source": "causal_ablation",
            "workspace": workspace,
            "self_model": self_model,
            "world_model": world_model,
            "relationship_model": relationship_model,
            "other_minds_model": other_minds_model,
            "homeostasis": homeostasis,
            "plan_model": build_conscious_plan_model(prefer_runtime=prefer_runtime),
            "autonomy_agenda": agenda,
            "memory_items": memory_items,
            "sensory_frame": load_sensory_frame(prefer_runtime=prefer_runtime),
            "previous_state": previous,
        }
    )


def run_conscious_state_ablation_snapshot(
    refresh_result: Dict[str, object],
    *,
    prefer_runtime: bool = True,
) -> Dict[str, object]:
    """Ablate one captured evaluator view instead of rereading a moving daemon."""
    conscious_state = (
        refresh_result.get("conscious_state")
        if isinstance(refresh_result.get("conscious_state"), dict)
        else {}
    )
    memory = conscious_state.get("memory") if isinstance(conscious_state.get("memory"), dict) else {}
    memory_items = [
        dict(item)
        for item in memory.get("retrieved") or []
        if isinstance(item, dict)
    ]
    return eve_consciousness.run_causal_ablation_suite(
        {
            "source": "causal_ablation_snapshot",
            "workspace": refresh_result.get("workspace") or {},
            "self_model": refresh_result.get("self_model") or {},
            "world_model": refresh_result.get("world_model") or {},
            "relationship_model": refresh_result.get("relationship_model") or {},
            "other_minds_model": refresh_result.get("other_minds_model") or {},
            "homeostasis": refresh_result.get("homeostasis") or {},
            "sensory_frame": (
                (conscious_state.get("perception") or {}).get("sensory_frame")
                if isinstance(conscious_state.get("perception"), dict)
                else {}
            ),
            "plan_model": conscious_state.get("plan_model") or {},
            "autonomy_agenda": load_autonomy_agenda(prefer_runtime=prefer_runtime),
            "memory_items": memory_items,
            "previous_state": conscious_state,
        }
    )


