def run_conscious_state_durability(*, prefer_runtime: bool = True) -> Dict[str, object]:
    """Run evaluator-owned durability probes, including a real child process."""
    workspace = load_global_workspace(prefer_runtime=prefer_runtime)
    query = " ".join(
        unique_compact(
            [
                (workspace.get("workspace_state") or {}).get("focus") if isinstance(workspace.get("workspace_state"), dict) else "",
                *(workspace.get("active_goals") or [])[:3],
                *(workspace.get("continuity_threads") or [])[:3],
            ],
            limit=8,
        )
    )
    build_inputs: Dict[str, object] = {
        "source": "durable_continuity",
        "workspace": workspace,
        "self_model": load_self_model_state(prefer_runtime=prefer_runtime),
        "world_model": load_world_model_state(prefer_runtime=prefer_runtime),
        "relationship_model": load_relationship_model_state(prefer_runtime=prefer_runtime),
        "other_minds_model": load_other_minds_model_state(prefer_runtime=prefer_runtime),
        "homeostasis": load_homeostasis(prefer_runtime=prefer_runtime),
        "autonomy_agenda": load_autonomy_agenda(prefer_runtime=prefer_runtime),
        "memory_items": select_conscious_memory_items(query, prefer_runtime=prefer_runtime, limit=6),
        "previous_state": load_conscious_state(prefer_runtime=prefer_runtime),
    }
    report = eve_consciousness.run_durable_continuity_suite(build_inputs)

    seed_inputs = json.loads(json.dumps(build_inputs))
    seed_inputs.update(
        {
            "source": "independent_process_seed",
            "previous_state": {},
            "conflict_items": [],
            "runtime_epoch": "independent-parent-epoch",
            "now": "2026-07-12T19:00:00+00:00",
        }
    )
    seed = eve_consciousness.build_conscious_state(**seed_inputs)
    predicted = (seed.get("predictions") or {}).get("process") if isinstance(seed.get("predictions"), dict) else {}
    predicted = predicted if isinstance(predicted, dict) else {}
    completed = eve_consciousness.complete_cycle(
        seed,
        actual_process={
            "lanes": list(predicted.get("lanes") or []),
            "tools_used": ["independent_parent_probe"] if predicted.get("needs_tools") else [],
            "revision_used": bool(predicted.get("needs_revision")),
        },
        outcome={"ok": True, "summary": "Parent process wrote a verified checkpoint."},
        now="2026-07-12T19:00:30+00:00",
    )
    child_inputs = json.loads(json.dumps(build_inputs))
    child_inputs.update(
        {
            "source": "independent_process_resume",
            "previous_state": completed,
            "conflict_items": [],
            "runtime_epoch": "independent-child-epoch",
            "now": "2026-07-12T19:01:00+00:00",
        }
    )
    child_script = textwrap.dedent(
        """
        import json
        import os
        import sys
        import eve_consciousness

        payload = json.load(sys.stdin)
        state = eve_consciousness.build_conscious_state(**payload)
        print(json.dumps({"pid": os.getpid(), "state": state}, ensure_ascii=True))
        """
    )
    child_evidence: Dict[str, object] = {}
    child_passed = False
    try:
        child = subprocess.run(
            [sys.executable, "-c", child_script],
            input=json.dumps(child_inputs, ensure_ascii=True),
            text=True,
            capture_output=True,
            cwd=str(ROOT),
            timeout=20,
            check=False,
        )
        child_payload = json.loads(child.stdout) if child.returncode == 0 and child.stdout.strip() else {}
        child_state = child_payload.get("state") if isinstance(child_payload.get("state"), dict) else {}
        child_recurrent = child_state.get("recurrent") if isinstance(child_state.get("recurrent"), dict) else {}
        child_passed = bool(
            child.returncode == 0
            and int(child_payload.get("pid") or 0) != os.getpid()
            and child_recurrent.get("previous_cycle_id") == completed.get("cycle_id")
            and child_recurrent.get("previous_checkpoint_integrity") == "verified"
            and child_recurrent.get("runtime_epoch_changed") is True
            and int(child_recurrent.get("continuity_strength") or 0) > 0
            and bool((child_state.get("learning") or {}).get("process_models"))
        )
        child_evidence = {
            "returncode": child.returncode,
            "parent_pid": os.getpid(),
            "child_pid": child_payload.get("pid"),
            "previous_cycle_id": child_recurrent.get("previous_cycle_id"),
            "checkpoint": child_recurrent.get("previous_checkpoint_integrity"),
            "continuity_mode": child_recurrent.get("continuity_mode"),
            "continuity_strength": child_recurrent.get("continuity_strength"),
            "stderr": normalize_text_value(child.stderr, fallback="", limit=220),
        }
    except Exception as exc:
        child_evidence = {"error": normalize_text_value(exc, fallback="independent process probe failed", limit=220)}

    checks = report.get("checks") if isinstance(report.get("checks"), dict) else {}
    checks["independent_process_resume"] = {"passed": child_passed, **child_evidence}
    report["checks"] = checks
    report["passed_count"] = sum(1 for item in checks.values() if isinstance(item, dict) and item.get("passed"))
    report["total"] = len(checks)
    report["passed"] = bool(checks) and int(report["passed_count"]) == int(report["total"])
    report["design"] = (
        str(report.get("design") or "")
        + "; independent Python-process deserialize-and-resume intervention"
    ).strip("; ")
    return report


