def format_other_minds_model_state_report(model_state: Dict[str, object]) -> str:
    normalized = normalize_other_minds_model_state(model_state)
    lines = [
        f"updated_at: {normalized.get('updated_at') or 'never'}",
        f"source: {normalized.get('source') or 'unknown'}",
        f"summary: {normalized['summary']}",
        f"coordination_risks: {format_human_context_list(normalized['coordination_risks'])}",
        f"uncertainty_edges: {format_human_context_list(normalized['uncertainty_edges'])}",
        f"next_check: {normalized['next_check']}",
    ]
    if normalized.get("observed_minds"):
        lines.append("observed_minds:")
        for item in normalized["observed_minds"]:
            lines.append(
                f"- {item.get('id')}: {item.get('state') or 'none recorded'} | goals {format_human_context_list(item.get('goals') or [])} | constraints {format_human_context_list(item.get('constraints') or [])}"
            )
            lines.append(
                f"  signals: {format_human_context_list(item.get('signals') or [])} | unknowns: {format_human_context_list(item.get('unknowns') or [])}"
            )
    return "\n".join(lines)


def format_homeostasis_report(homeostasis: Dict[str, object], full: bool = False) -> str:
    normalized = normalize_homeostasis_state(homeostasis)
    lines = [
        f"updated_at: {normalized.get('updated_at') or 'never'}",
        f"source: {normalized.get('source') or 'unknown'}",
        f"summary: {normalized['summary']}",
        f"regulation_mode: {normalized['regulation_mode']}",
        f"dominant_pressures: {format_human_context_list(normalized['dominant_pressures'])}",
        f"next_regulation_step: {normalized['next_regulation_step']}",
    ]
    if full:
        lines.append("pressures:")
        for pressure in normalized.get("pressures", []):
            lines.append(
                f"- {pressure.get('label')}: {int(pressure.get('level') or 0)} | {pressure.get('trend') or 'steady'} | {pressure.get('reason') or 'none recorded'}"
            )
        discounted_signals = normalized.get("discounted_signals") if isinstance(normalized.get("discounted_signals"), list) else []
        if discounted_signals:
            lines.append("discounted_signals:")
            for signal in discounted_signals:
                lines.append(
                    f"- {signal.get('label')}: {int(signal.get('count') or 0)} | {signal.get('disposition') or 'discounted'} | {signal.get('reason') or 'none recorded'}"
                )
        else:
            lines.append("discounted_signals: none")
        lines.append(f"recovery_targets: {format_human_context_list(normalized['recovery_targets'])}")
    return "\n".join(lines)


def format_meta_check_report(bundle: Dict[str, object], full: bool = False) -> str:
    workspace = bundle.get("workspace") if isinstance(bundle.get("workspace"), dict) else load_global_workspace()
    conscious_state = bundle.get("conscious_state") if isinstance(bundle.get("conscious_state"), dict) else load_conscious_state()
    self_model = bundle.get("self_model") if isinstance(bundle.get("self_model"), dict) else load_self_model_state()
    world_model = bundle.get("world_model") if isinstance(bundle.get("world_model"), dict) else load_world_model_state()
    relationship_model = (
        bundle.get("relationship_model") if isinstance(bundle.get("relationship_model"), dict) else load_relationship_model_state()
    )
    other_minds_model = (
        bundle.get("other_minds_model") if isinstance(bundle.get("other_minds_model"), dict) else load_other_minds_model_state()
    )
    homeostasis = bundle.get("homeostasis") if isinstance(bundle.get("homeostasis"), dict) else load_homeostasis()
    parts = [
        "Global workspace",
        format_global_workspace_report(workspace, full=full),
        "",
        "Recurrent conscious state",
        format_conscious_state_report(conscious_state, full=full),
        "",
        "Self model",
        format_self_model_state_report(self_model),
        "",
        "World model",
        format_world_model_state_report(world_model),
        "",
        "Relationship model",
        format_relationship_model_state_report(relationship_model),
        "",
        "Other minds model",
        format_other_minds_model_state_report(other_minds_model),
        "",
        "Homeostasis",
        format_homeostasis_report(homeostasis, full=full),
    ]
    return "\n".join(parts)


