MODEL_BAKEOFF_SUITES = {
    "fast": FAST_MODEL_BAKEOFF_PROMPTS,
    "generic": MODEL_BAKEOFF_PROMPTS,
    "deep": DEEP_MODEL_BAKEOFF_PROMPTS,
    "observer": OBSERVER_MODEL_BAKEOFF_PROMPTS,
    "planner": PLANNER_MODEL_BAKEOFF_PROMPTS,
    "relationship": RELATIONSHIP_MODEL_BAKEOFF_PROMPTS,
}

MODEL_BAKEOFF_DEFAULT_BUDGETS = {
    "generic": {"max_tokens": 220, "timeout_seconds": 45},
    "fast": {"max_tokens": 800, "timeout_seconds": 120},
    "deep": {"max_tokens": 640, "timeout_seconds": 180},
    "observer": {"max_tokens": 360, "timeout_seconds": 90},
    "planner": {"max_tokens": 260, "timeout_seconds": 120},
    "relationship": {"max_tokens": 420, "timeout_seconds": 120},
}


def model_bakeoff_prompts_for_suite(suite: object) -> List[Dict[str, object]]:
    normalized = " ".join(str(suite or "generic").lower().split()) or "generic"
    if normalized not in MODEL_BAKEOFF_SUITES:
        raise SystemExit(
            "Unknown model bakeoff suite. Use one of: "
            + ", ".join(sorted(MODEL_BAKEOFF_SUITES.keys()))
        )
    return MODEL_BAKEOFF_SUITES[normalized]


def model_bakeoff_default_budget(suite: object) -> Dict[str, int]:
    normalized = " ".join(str(suite or "generic").lower().split()) or "generic"
    budget = MODEL_BAKEOFF_DEFAULT_BUDGETS.get(normalized) or MODEL_BAKEOFF_DEFAULT_BUDGETS["generic"]
    return {
        "max_tokens": int(budget["max_tokens"]),
        "timeout_seconds": int(budget["timeout_seconds"]),
    }


def bytes_to_gib(value: object) -> float:
    try:
        raw = float(value)
    except (TypeError, ValueError):
        return 0.0
    return raw / (1024 ** 3)


def system_memory_bytes() -> int:
    try:
        return int(os.sysconf("SC_PAGE_SIZE")) * int(os.sysconf("SC_PHYS_PAGES"))
    except (AttributeError, OSError, ValueError):
        return 0


# NOTE: parse_iso_datetime is defined once, earlier in this file (the tz-aware,
# robust version). A second, naive-returning definition used to shadow it here and
# caused aware/naive datetime mismatches — removed so there is a single source of
# truth that always returns timezone-aware UTC datetimes.


def model_scout_parameter_billion(model_id: object) -> Optional[float]:
    text = normalize_text_value(model_id, fallback="", limit=300)
    matches = re.findall(r"(?<![A-Za-z])(\d+(?:\.\d+)?)\s*[bB](?![A-Za-z])", text)
    if not matches:
        return None
    try:
        return max(float(item) for item in matches)
    except ValueError:
        return None


def model_scout_estimated_weight_gib(model_id: object) -> Optional[float]:
    params_b = model_scout_parameter_billion(model_id)
    if params_b is None:
        return None
    lowered = normalize_text_value(model_id, fallback="", limit=300).lower()
    if any(marker in lowered for marker in ["q2", "2bit", "2-bit"]):
        multiplier = 0.32
    elif any(marker in lowered for marker in ["q3", "3bit", "3-bit"]):
        multiplier = 0.42
    elif any(marker in lowered for marker in ["q5", "5bit", "5-bit"]):
        multiplier = 0.68
    elif any(marker in lowered for marker in ["q6", "6bit", "6-bit"]):
        multiplier = 0.82
    elif any(marker in lowered for marker in ["q8", "8bit", "8-bit"]):
        multiplier = 1.05
    elif any(marker in lowered for marker in ["q4", "4bit", "4-bit", "mlx"]):
        multiplier = 0.58
    else:
        multiplier = 0.58
    return round(params_b * multiplier, 2)


def model_scout_candidate_lane_fit(candidate: Dict[str, object]) -> List[str]:
    estimated_weight = candidate.get("estimated_weight_gib")
    params_b = candidate.get("params_b")
    fits: List[str] = []
    for lane in MODEL_LANE_ORDER:
        budget = MODEL_LANE_RESOURCE_BUDGET.get(lane, {})
        soft_weight = float(budget.get("soft_weight_gib") or 0.0)
        if isinstance(estimated_weight, (int, float)) and estimated_weight > 0:
            weight = float(estimated_weight)
            if lane == "observer" and weight <= soft_weight * 1.10:
                fits.append(lane)
            elif lane == "planner" and 0.8 <= weight <= soft_weight * 1.10:
                fits.append(lane)
            elif lane == "fast" and 1.5 <= weight <= soft_weight * 1.10:
                fits.append(lane)
            elif lane == "relationship" and 2.0 <= weight <= soft_weight * 1.10:
                fits.append(lane)
            elif lane == "deep" and 7.0 <= weight <= soft_weight * 1.10:
                fits.append(lane)
            continue
        if isinstance(params_b, (int, float)):
            if lane == "observer" and params_b <= 2.5:
                fits.append(lane)
            elif lane == "planner" and 1.0 <= params_b <= 7:
                fits.append(lane)
            elif lane == "fast" and 2.0 <= params_b <= 9:
                fits.append(lane)
            elif lane == "relationship" and 3.0 <= params_b <= 9:
                fits.append(lane)
            elif lane == "deep" and 12 <= params_b <= 40:
                fits.append(lane)
    return fits


def model_scout_candidate_score(candidate: Dict[str, object]) -> int:
    lowered = " ".join(
        [
            normalize_text_value(candidate.get("id"), fallback="", limit=300),
            " ".join(str(item) for item in candidate.get("tags") or []),
        ]
    ).lower()
    score = 0
    if any(term in lowered for term in ["gguf", "mlx", "4bit", "q4", "q3"]):
        score += 4
    if any(term in lowered for term in ["qwen", "gemma", "deepseek", "kimi", "mistral", "llama", "phi"]):
        score += 2
    if candidate.get("lane_fit"):
        score += min(4, len(candidate.get("lane_fit") or []))
    try:
        downloads = int(candidate.get("downloads") or 0)
    except (TypeError, ValueError):
        downloads = 0
    try:
        likes = int(candidate.get("likes") or 0)
    except (TypeError, ValueError):
        likes = 0
    if downloads >= 1000:
        score += 1
    if likes >= 25:
        score += 1
    last_modified = parse_iso_datetime(candidate.get("last_modified"))
    if last_modified:
        age_days = (datetime.now(timezone.utc) - last_modified.astimezone(timezone.utc)).days
        if age_days <= 14:
            score += 3
        elif age_days <= 45:
            score += 1
    estimated_weight = candidate.get("estimated_weight_gib")
    if isinstance(estimated_weight, (int, float)) and estimated_weight > MODEL_TOTAL_HARD_WEIGHT_GIB:
        score -= 5
    flags = set(candidate.get("flags") or [])
    if "not_chat_lane" in flags:
        score -= 8
    if "safety_review_required" in flags:
        score -= 4
    if "runtime_artifact_unclear" in flags:
        score -= 2
    return score


def model_scout_candidate_flags(candidate: Dict[str, object]) -> List[str]:
    lowered = " ".join(
        [
            normalize_text_value(candidate.get("id"), fallback="", limit=300),
            normalize_text_value(candidate.get("pipeline_tag"), fallback="", limit=80),
            " ".join(str(item) for item in candidate.get("tags") or []),
        ]
    ).lower()
    flags: List[str] = []
    if any(term in lowered for term in ["embedding", "rerank", "reranker", "sentence-transformers"]):
        flags.append("not_chat_lane")
    if any(term in lowered for term in ["abliterated", "obliterated", "uncensored", "nsfw"]):
        flags.append("safety_review_required")
    if not any(term in lowered for term in ["gguf", "mlx", "q4", "q3", "4bit", "3bit"]):
        flags.append("runtime_artifact_unclear")
    return flags


def normalize_huggingface_model_candidate(raw: Dict[str, object], *, source: str) -> Dict[str, object]:
    model_id = normalize_text_value(raw.get("id") or raw.get("modelId"), fallback="", limit=300)
    tags = raw.get("tags") if isinstance(raw.get("tags"), list) else []
    params_b = model_scout_parameter_billion(model_id)
    estimated_weight = model_scout_estimated_weight_gib(model_id)
    candidate: Dict[str, object] = {
        "id": model_id,
        "source": source,
        "url": f"https://huggingface.co/{model_id}" if model_id else "",
        "pipeline_tag": normalize_text_value(raw.get("pipeline_tag"), fallback="", limit=80),
        "tags": [normalize_text_value(item, fallback="", limit=80) for item in tags if normalize_text_value(item, fallback="", limit=80)],
        "downloads": raw.get("downloads") or 0,
        "likes": raw.get("likes") or 0,
        "last_modified": normalize_text_value(raw.get("lastModified") or raw.get("last_modified"), fallback="", limit=80),
        "params_b": params_b,
        "estimated_weight_gib": estimated_weight,
    }
    candidate["flags"] = model_scout_candidate_flags(candidate)
    candidate["lane_fit"] = [] if "not_chat_lane" in candidate["flags"] else model_scout_candidate_lane_fit(candidate)
    candidate["score"] = model_scout_candidate_score(candidate)
    return candidate


def model_scout_mtp_drafter_candidates() -> List[Dict[str, object]]:
    candidates: List[Dict[str, object]] = []
    for item in GEMMA4_MTP_DRAFTER_CANDIDATES:
        target_repo = normalize_huggingface_model_repo(item.get("target_repo"))
        assistant_repo = normalize_huggingface_model_repo(item.get("assistant_repo"))
        target_weight = model_scout_estimated_weight_gib(target_repo)
        candidate_lanes = [str(lane) for lane in item.get("candidate_lanes") or [] if str(lane).strip()]
        candidates.append(
            {
                "id": str(item.get("id") or ""),
                "kind": "target_plus_drafter",
                "source": "google_gemma4_mtp_official",
                "target_repo": target_repo,
                "target_url": f"https://huggingface.co/{target_repo}" if target_repo else "",
                "assistant_repo": assistant_repo,
                "assistant_url": f"https://huggingface.co/{assistant_repo}" if assistant_repo else "",
                "assistant_size": str(item.get("assistant_size") or ""),
                "target_estimated_weight_gib": target_weight,
                "lane_fit": candidate_lanes,
                "flags": ["target_plus_drafter_only", "lab_candidate", "not_standalone_lane"],
                "score": 0,
                "adoption": (
                    "Test only as a matching target-plus-drafter temporary alias for one existing lane; "
                    "the drafter alone is not a lane candidate."
                ),
                "notes": str(item.get("notes") or ""),
            }
        )
    return candidates


