def external_faculty_causal_evidence_input_path(value: object) -> Path:
    """Require evaluator packets to originate outside Eve-readable storage."""
    path = Path(str(value or "")).expanduser().resolve()
    if not path.is_file():
        raise SystemExit(f"Faculty causal evidence file not found: {path}")
    forbidden_roots = [
        ROOT.resolve(),
        (Path.home() / ".eve_runtime").resolve(),
        (Path.home() / ".openclaw-eve-repair").resolve(),
    ]
    for root in forbidden_roots:
        try:
            path.relative_to(root)
        except ValueError:
            continue
        raise SystemExit(
            "Faculty causal evidence must remain evaluator-private until its text-free packet is ingested; "
            f"refused Eve-readable path under {root}."
        )
    return path


def cmd_reply_learning_ingest_causal(args: argparse.Namespace) -> int:
    """Ingest only a text-free external matched-ablation result packet."""
    path = external_faculty_causal_evidence_input_path(args.file)
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise SystemExit(f"Invalid faculty causal evidence JSON: {exc}") from exc
    packet = normalize_external_faculty_causal_evidence(raw)
    evidence_id = str(packet.get("evidence_id") or "")
    before = load_reply_lane_learning(prefer_runtime=False)
    before_ids = set(
        normalize_text_list(before.get("applied_causal_evidence_ids"), limit=128)
    )
    conscious_result = join_external_faculty_causal_evidence(packet)
    learning = record_reply_lane_learning_from_causal_evidence(packet)
    after_ids = set(
        normalize_text_list(learning.get("applied_causal_evidence_ids"), limit=128)
    )
    result = {
        "schema_version": EXTERNAL_FACULTY_CAUSAL_EVIDENCE_SCHEMA,
        "evidence_id": evidence_id,
        "private_run_digest": packet.get("private_run_digest"),
        "evaluated_behavior_fingerprint": packet.get(
            "evaluated_behavior_fingerprint"
        ),
        "learning_applied": evidence_id not in before_ids and evidence_id in after_ids,
        "conscious_state_applied": bool(conscious_result.get("applied")),
        "systemic_failure": packet.get("systemic_failure"),
        "lane_count": len(packet.get("lanes") or []),
        "private_text_withheld": True,
    }
    append_entry(
        "external_faculty_causal_evidence_ingested",
        "Ingested text-free external matched faculty-ablation evidence.",
        metadata=result,
    )
    if args.json:
        print(json.dumps(result, ensure_ascii=True, indent=2))
    else:
        print(
            "external faculty causal evidence: "
            + ("applied" if result["learning_applied"] or result["conscious_state_applied"] else "already applied")
        )
        print(f"evidence_id: {evidence_id}")
        print(f"lanes: {result['lane_count']}")
        print(
            "systemic_failure: "
            + ("yes" if bool((packet.get("systemic_failure") or {}).get("present")) else "no")
        )
        print("private_prompt_response_rubric_text: withheld")
    return 0


def format_reply_council_turns(records: List[Dict[str, object]], *, full: bool = False) -> str:
    lines = [f"reply_council_turns: {len(records)}"]
    if not records:
        return "\n".join(lines + ["No reply council turn records found."])
    for record in records:
        active = ", ".join(str(item) for item in record.get("active_lanes") or []) or "none"
        stream_lanes = ", ".join(str(item) for item in record.get("selected_stream_lanes") or []) or "none"
        lines.append(
            f"- {record.get('created_at') or 'unknown'} | thread={record.get('thread_id') or '-'} "
            f"intent={record.get('intent') or '-'} topic={record.get('current_topic') or '-'} "
            f"active={active} streams={stream_lanes} repair={'yes' if record.get('needed_repair') else 'no'}"
        )
        if full:
            lines.append(f"  inbound: {normalize_text_value(record.get('inbound_preview'), fallback='', limit=180)}")
            lines.append(f"  reply: {normalize_text_value(record.get('reply_preview'), fallback='', limit=180)}")
            lines.append(f"  synthesis_model: {record.get('synthesis_model') or record.get('used_model') or '-'}")
            contributors = [
                item for item in record.get("faculty_contributors") or [] if isinstance(item, dict)
            ]
            if contributors:
                lines.append(
                    "  contributors: "
                    + ", ".join(
                        f"{item.get('lane')}:{float(item.get('credit_weight') or 0.0):.3f}"
                        f"[{'+'.join(str(role) for role in item.get('roles') or [])}]"
                        for item in contributors
                    )
                )
            for lane in record.get("lanes") or []:
                if not isinstance(lane, dict):
                    continue
                reasons = ", ".join(str(item) for item in lane.get("reasons") or []) or "-"
                lines.append(
                    f"  lane {lane.get('lane')}: {lane.get('stance') or '-'} "
                    f"pressure={lane.get('pressure')} model={lane.get('model') or '-'} reasons={reasons}"
                )
    return "\n".join(lines)


def cmd_reply_council_turns(args: argparse.Namespace) -> int:
    records = read_reply_council_turns(
        limit=max(1, int(args.limit or 20)),
        thread_id=args.thread_id,
        reply_message_id=args.reply_message_id,
        prefer_runtime=bool(args.runtime),
    )
    if args.json:
        print(json.dumps(records, ensure_ascii=True, indent=2))
    else:
        print(format_reply_council_turns(records, full=bool(args.full)))
    return 0


def latest_outbound_message() -> Optional[Dict[str, object]]:
    messages = read_messages(sender="eve", recipient="user")
    lived = [item for item in messages if not conversation_message_is_synthetic(item)]
    return lived[-1] if lived else None


def outreach_pacing_reason(
    config: Dict[str, object],
    threads: List[Dict[str, object]],
    *,
    ignore_waiting_threads: bool = False,
) -> Optional[str]:
    waiting_threads = [item for item in threads if item.get("status") == "awaiting_user"]
    max_waiting = int(config["max_waiting_threads_before_outreach"])
    if not ignore_waiting_threads and max_waiting > 0 and len(waiting_threads) >= max_waiting:
        return f"Holding outreach because {len(waiting_threads)} threads are already waiting on the user."

    minimum_gap = int(config["minimum_outreach_gap_minutes"])
    last_outbound = latest_outbound_message()
    if last_outbound and minimum_gap > 0 and not interval_due(last_outbound.get("timestamp"), minimum_gap):
        return (
            "Holding outreach because Eve already messaged the user recently "
            f"at {last_outbound.get('timestamp')}."
        )
    return None


PERSONAL_CONVERSATION_SOURCES = {"daemon", "web_wake", "monitor_personal", "manual"}


def message_is_personal_conversation(message: Dict[str, object]) -> bool:
    if message.get("sender") != "eve" or message.get("recipient") != "user":
        return False
    if message.get("reply_to"):
        return False
    kind = str(message.get("kind") or "").lower()
    metadata = message.get("metadata") if isinstance(message.get("metadata"), dict) else {}
    return (
        kind in {"proactive_outreach", "personal_conversation"}
        or str(metadata.get("surface") or "") == "personal_conversation"
        or str(metadata.get("conversation_kind") or "") == "eve_initiated_personal"
        or bool(metadata.get("local_only"))
    )


def latest_personal_conversation_message() -> Optional[Dict[str, object]]:
    messages = read_messages(sender="eve", recipient="user")
    for message in reversed(messages):
        if not conversation_message_is_synthetic(message) and message_is_personal_conversation(message):
            return message
    return None


def personal_conversation_pacing_reason(config: Dict[str, object]) -> Optional[str]:
    minimum_gap = int(
        config.get("personal_conversation_minimum_gap_minutes")
        or config.get("minimum_outreach_gap_minutes")
        or 0
    )
    if minimum_gap <= 0:
        return None
    last_personal = latest_personal_conversation_message()
    if last_personal and not interval_due(last_personal.get("timestamp") or last_personal.get("created_at"), minimum_gap):
        return (
            "Holding personal conversation because Eve opened a personal thread recently "
            f"at {message_record_timestamp(last_personal)}."
        )
    return None


def record_personal_conversation_check(
    *,
    source: str,
    status: str,
    reason: str,
    record: Optional[Dict[str, object]] = None,
    state: Optional[Dict[str, object]] = None,
) -> None:
    now = utc_now()
    target_state = state if state is not None else load_state()
    target_state["last_personal_conversation_check_at"] = now
    target_state["last_personal_conversation_status"] = normalize_text_value(status, fallback="checked", limit=40)
    target_state["last_personal_conversation_reason"] = normalize_text_value(reason, fallback="", limit=280)
    target_state["last_personal_conversation_source"] = normalize_text_value(source, fallback="", limit=80)
    if record is not None:
        target_state["last_personal_conversation_at"] = now
        target_state["last_personal_conversation_message_id"] = str(record.get("id") or "")
        target_state["last_personal_conversation_thread_id"] = str(record.get("thread_id") or "")
        target_state["last_personal_conversation_subject"] = normalize_text_value(record.get("subject"), fallback="", limit=160)
    if state is None:
        save_state(target_state)


def add_interval_iso(
    timestamp: Optional[object],
    *,
    minutes: Optional[int] = None,
    seconds: Optional[int] = None,
) -> Optional[str]:
    parsed = parse_iso_datetime(timestamp)
    if parsed is None:
        return None
    if seconds is not None:
        return (parsed + timedelta(seconds=max(0, int(seconds)))).isoformat()
    if minutes is not None:
        return (parsed + timedelta(minutes=max(0, int(minutes)))).isoformat()
    return None


def personal_conversation_status_payload(
    config: Optional[Dict[str, object]] = None,
    state: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    effective_config = config or load_config()
    runtime_state = state or load_state(prefer_runtime=daemon_runtime_running())
    latest_personal = latest_personal_conversation_message()
    status = str(runtime_state.get("last_personal_conversation_status") or "").strip()
    if not status:
        status = "open" if latest_personal else "waiting"
    reason = str(runtime_state.get("last_personal_conversation_reason") or "").strip()
    if not reason:
        if latest_personal:
            reason = "Eve has an open personal thread."
        else:
            reason = "Eve has not opened a personal thread yet."

    interval_seconds = effective_config.get("personal_conversation_interval_seconds")
    if interval_seconds is None:
        next_check_at = add_interval_iso(
            runtime_state.get("last_personal_conversation_check_at") or runtime_state.get("last_outreach_check_at"),
            minutes=int(effective_config.get("personal_conversation_interval_minutes") or effective_config.get("outreach_interval_minutes") or 0),
        )
    else:
        next_check_at = add_interval_iso(
            runtime_state.get("last_personal_conversation_check_at") or runtime_state.get("last_outreach_check_at"),
            seconds=int(interval_seconds),
        )

    latest_message_id = str(latest_personal.get("id") or "") if latest_personal else ""
    latest_thread_id = str(latest_personal.get("thread_id") or "") if latest_personal else ""
    latest_subject = str(latest_personal.get("subject") or "") if latest_personal else ""
    latest_at = str(latest_personal.get("timestamp") or latest_personal.get("created_at") or "") if latest_personal else ""

    return {
        "status": status,
        "reason": reason,
        "last_check_at": runtime_state.get("last_personal_conversation_check_at") or runtime_state.get("last_outreach_check_at"),
        "last_sent_at": runtime_state.get("last_personal_conversation_at") or latest_at,
        "next_check_at": next_check_at,
        "source": runtime_state.get("last_personal_conversation_source") or "",
        "message_id": runtime_state.get("last_personal_conversation_message_id") or latest_message_id,
        "thread_id": runtime_state.get("last_personal_conversation_thread_id") or latest_thread_id,
        "subject": runtime_state.get("last_personal_conversation_subject") or latest_subject,
        "minimum_gap_minutes": int(effective_config.get("personal_conversation_minimum_gap_minutes") or 0),
    }


def final_answer_retry_instruction(operation: str) -> str:
    normalized = " ".join(str(operation or "general").lower().split()) or "general"
    if normalized in {"mind_tick", "self_awareness", "human_context"}:
        return "Return only the final answer as compact JSON. No markdown fences, commentary, or hidden reasoning."
    return "Return only the final answer now. No hidden reasoning, no commentary, and no preamble."


def final_answer_retry_max_tokens(max_tokens: int) -> int:
    return max(max_tokens, min(900, max(max_tokens + 120, int(max_tokens * 1.5))))


def recoverable_reply_model_failure(error_text: object) -> bool:
    normalized = " ".join(str(error_text or "").lower().split())
    if not normalized:
        return False
    recoverable_markers = (
        "thinking_only",
        "only hidden reasoning",
        "no final answer",
        "empty response",
        "timed out",
        "timeout",
        "remote end closed connection",
    )
    return any(marker in normalized for marker in recoverable_markers)


def ollama_message_content(body: Dict[str, object]) -> tuple[str, str, str]:
    message = body.get("message", {}) if isinstance(body.get("message"), dict) else {}
    content = str(message.get("content", "")).strip()
    thinking = str(message.get("thinking", "")).strip()
    failure_kind = ""
    if not content and thinking:
        failure_kind = "thinking_only"
    elif not content:
        failure_kind = "empty_response"
    return content, thinking, failure_kind


def llama_cpp_message_content(body: Dict[str, object]) -> tuple[str, str, str]:
    choices = body.get("choices") if isinstance(body.get("choices"), list) else []
    first_choice = choices[0] if choices and isinstance(choices[0], dict) else {}
    message = first_choice.get("message") if isinstance(first_choice.get("message"), dict) else {}
    content_value = message.get("content")
    if isinstance(content_value, list):
        content = "\n".join(
            normalize_text_value(item.get("text"), fallback="", limit=4000)
            for item in content_value
            if isinstance(item, dict) and normalize_text_value(item.get("text"), fallback="", limit=4000)
        ).strip()
    else:
        content = normalize_text_value(content_value or first_choice.get("text"), fallback="", limit=12000)
    failure_kind = "" if content else "empty_response"
    return content, "", failure_kind


def llama_cpp_request_headers(config: Dict[str, object]) -> Dict[str, str]:
    headers: Dict[str, str] = {}
    api_key = normalize_text_value(config.get("llama_cpp_api_key"), fallback="", limit=400)
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    return headers


def llama_cpp_compatible_messages(messages: List[Dict[str, str]]) -> List[Dict[str, str]]:
    # Gemma's llama.cpp template accepts one optional leading system turn and
    # then requires strict user/assistant alternation. Preserve that leading
    # system role instead of demoting the complete identity and the actual user
    # request into one oversized user message. Later system records (for
    # example, a tool result after an assistant tool call) become the next user
    # turn because they are environment evidence inside an active exchange.
    normalized_messages: List[Dict[str, str]] = []
    leading_system_parts: List[str] = []
    conversation_started = False

    def append_message(role: str, content: str) -> None:
        if normalized_messages and normalized_messages[-1]["role"] == role:
            normalized_messages[-1]["content"] = (
                normalized_messages[-1]["content"].rstrip() + "\n\n" + content
            ).strip()
        else:
            normalized_messages.append({"role": role, "content": content})

    for message in messages:
        if not isinstance(message, dict):
            continue
        raw_role = " ".join(str(message.get("role") or "user").lower().split()) or "user"
        content = str(message.get("content") or "").strip()
        if not content:
            continue

        if raw_role == "system" and not conversation_started:
            leading_system_parts.append(content)
            continue

        if not conversation_started:
            conversation_started = True
            if leading_system_parts:
                normalized_messages.append(
                    {"role": "system", "content": "\n\n".join(leading_system_parts).strip()}
                )

        if raw_role == "assistant":
            append_message("assistant", content)
        elif raw_role == "system":
            append_message("user", f"System guidance:\n{content}")
        else:
            append_message("user", content)

    if not conversation_started and leading_system_parts:
        normalized_messages.append(
            {"role": "system", "content": "\n\n".join(leading_system_parts).strip()}
        )
    return normalized_messages


def model_input_provenance(
    config: Dict[str, object],
    model: str,
    messages: List[Dict[str, str]],
    *,
    operation: str,
) -> Dict[str, object]:
    """Describe model input structure without retaining private message text."""
    backend = configured_model_backend(config, model, operation)
    prepared = llama_cpp_compatible_messages(messages) if backend == "llama_cpp" else [
        {"role": str(item.get("role") or ""), "content": str(item.get("content") or "")}
        for item in messages
        if isinstance(item, dict) and str(item.get("content") or "").strip()
    ]
    final_user = next(
        (str(item.get("content") or "") for item in reversed(prepared) if item.get("role") == "user"),
        "",
    )
    return {
        "schema_id": "eve.model_input_provenance.v1",
        "backend": backend,
        "operation": operation,
        "raw_roles": [str(item.get("role") or "") for item in messages if isinstance(item, dict)],
        "prepared_roles": [str(item.get("role") or "") for item in prepared],
        "raw_message_count": len(messages),
        "prepared_message_count": len(prepared),
        "raw_chars": sum(len(str(item.get("content") or "")) for item in messages if isinstance(item, dict)),
        "prepared_chars": sum(len(str(item.get("content") or "")) for item in prepared),
        "final_user_present": bool(final_user),
        "final_user_is_terminal": bool(prepared and prepared[-1].get("role") == "user"),
        "final_user_sha256": hashlib.sha256(final_user.encode("utf-8")).hexdigest() if final_user else "",
    }


def ollama_chat(
    host: str,
    model: str,
    messages: List[Dict[str, str]],
    max_tokens: int,
    think_level: str,
    operation: str = "general",
    timeout_seconds: int = 1800,
) -> str:
    url = host.rstrip("/") + "/api/chat"
    think_enabled = parse_boolish(think_level)
    deadline = time.perf_counter() + timeout_seconds

    def perform_request(
        request_messages: List[Dict[str, str]],
        request_max_tokens: int,
        request_think: bool,
        attempt: str,
        recovered_from: str = "",
    ) -> tuple[Dict[str, object], float]:
        payload = {
            "model": model,
            "messages": request_messages,
            "stream": False,
            "think": request_think,
            "options": {
                "num_predict": request_max_tokens,
            },
        }
        data = json.dumps(payload).encode("utf-8")
        req = request.Request(
            url,
            data=data,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        request_timeout = max(1, deadline - time.perf_counter())
        started = time.perf_counter()
        try:
            with request.urlopen(req, timeout=request_timeout) as resp:
                body = json.loads(resp.read().decode("utf-8"))
        except (error.URLError, http.client.RemoteDisconnected, TimeoutError, socket.timeout) as exc:
            append_perf_event(
                "model_call",
                operation,
                (time.perf_counter() - started) * 1000,
                ok=False,
                metadata={
                    "operation": operation,
                    "model": model,
                    "host": host,
                    "message_count": len(request_messages),
                    "max_tokens": request_max_tokens,
                    "think": request_think,
                    "attempt": attempt,
                    "recovered_from": recovered_from,
                    "request_timeout_seconds": round(request_timeout, 3),
                    "error": str(exc),
                },
            )
            raise SystemExit(
                "Could not reach Ollama cleanly at "
                f"{url}. Make sure the local Ollama service is running. Details: {exc}"
            )
        except json.JSONDecodeError as exc:
            append_perf_event(
                "model_call",
                operation,
                (time.perf_counter() - started) * 1000,
                ok=False,
                metadata={
                    "operation": operation,
                    "model": model,
                    "host": host,
                    "message_count": len(request_messages),
                    "max_tokens": request_max_tokens,
                    "think": request_think,
                    "attempt": attempt,
                    "recovered_from": recovered_from,
                    "request_timeout_seconds": round(request_timeout, 3),
                    "error": f"invalid_json: {exc}",
                },
            )
            raise SystemExit(f"Ollama returned invalid JSON: {exc}")
        duration_ms = (time.perf_counter() - started) * 1000
        if "error" in body:
            append_perf_event(
                "model_call",
                operation,
                duration_ms,
                ok=False,
                metadata={
                    "operation": operation,
                    "model": model,
                    "host": host,
                    "message_count": len(request_messages),
                    "max_tokens": request_max_tokens,
                    "think": request_think,
                    "attempt": attempt,
                    "recovered_from": recovered_from,
                    "request_timeout_seconds": round(request_timeout, 3),
                    "error": str(body["error"]),
                },
            )
            raise SystemExit(f"Ollama failed: {body['error']}")
        return body, duration_ms

    primary_body, primary_duration_ms = perform_request(messages, max_tokens, think_enabled, attempt="primary")
    content, thinking, failure_kind = ollama_message_content(primary_body)
    if content:
        append_perf_event(
            "model_call",
            operation,
            primary_duration_ms,
            ok=True,
            metadata={
                "operation": operation,
                "model": model,
                "host": host,
                "message_count": len(messages),
                "max_tokens": max_tokens,
                "think": think_enabled,
                "attempt": "primary",
                "response_chars": len(content),
            },
        )
        return content

    append_perf_event(
        "model_call",
        operation,
        primary_duration_ms,
        ok=False,
        metadata={
            "operation": operation,
            "model": model,
            "host": host,
            "message_count": len(messages),
            "max_tokens": max_tokens,
            "think": think_enabled,
            "attempt": "primary",
            "error": failure_kind or "empty_response",
            "thinking_chars": len(thinking),
        },
    )

    retry_messages = [
        *messages,
        {"role": "user", "content": final_answer_retry_instruction(operation)},
    ]
    retry_max_tokens = final_answer_retry_max_tokens(max_tokens)
    try:
        retry_body, retry_duration_ms = perform_request(
            retry_messages,
            retry_max_tokens,
            False,
            attempt="final_only_retry",
            recovered_from=failure_kind or "empty_response",
        )
    except SystemExit as exc:
        if failure_kind == "thinking_only":
            raise SystemExit(
                "Ollama returned only hidden reasoning and no final answer. "
                f"Eve asked for a final-answer-only retry, but it failed: {exc}"
            )
        raise SystemExit(f"Ollama returned an empty response. Final-answer retry failed: {exc}")

    retry_content, retry_thinking, retry_failure_kind = ollama_message_content(retry_body)
    if retry_content:
        append_perf_event(
            "model_call",
            operation,
            retry_duration_ms,
            ok=True,
            metadata={
                "operation": operation,
                "model": model,
                "host": host,
                "message_count": len(retry_messages),
                "max_tokens": retry_max_tokens,
                "think": False,
                "attempt": "final_only_retry",
                "recovered_from": failure_kind or "empty_response",
                "response_chars": len(retry_content),
            },
        )
        return retry_content

    append_perf_event(
        "model_call",
        operation,
        retry_duration_ms,
        ok=False,
        metadata={
            "operation": operation,
            "model": model,
            "host": host,
            "message_count": len(retry_messages),
            "max_tokens": retry_max_tokens,
            "think": False,
            "attempt": "final_only_retry",
            "recovered_from": failure_kind or "empty_response",
            "error": retry_failure_kind or "empty_response",
            "thinking_chars": len(retry_thinking),
        },
    )
    if failure_kind == "thinking_only":
        raise SystemExit(
            "Ollama returned only hidden reasoning and no final answer. "
            "Eve asked for a final-answer-only retry, but Ollama still returned no usable answer."
        )
    raise SystemExit("Ollama returned an empty response, even after a final-answer-only retry.")


def llama_cpp_chat(
    config: Dict[str, object],
    host: str,
    model: str,
    messages: List[Dict[str, str]],
    max_tokens: int,
    operation: str = "general",
    timeout_seconds: int = 1800,
    response_schema: Optional[Dict[str, object]] = None,
) -> str:
    url = host.rstrip("/") + "/v1/chat/completions"
    deadline = time.perf_counter() + timeout_seconds
    headers = llama_cpp_request_headers(config)

    def prefers_json_response(op: str) -> bool:
        normalized = " ".join(str(op or "").lower().split())
        return (
            normalized == "human_context_refresh"
            or normalized == "mind_tick"
            or normalized.endswith("_strict_json")
            or normalized.startswith("self_awareness")
            or normalized.startswith("mind_stream_")
            or normalized.startswith("reply_stream_")
        )

    def perform_request(
        request_messages: List[Dict[str, str]],
        request_max_tokens: int,
        attempt: str,
        recovered_from: str = "",
    ) -> tuple[Dict[str, object], float]:
        prepared_messages = llama_cpp_compatible_messages(request_messages)
        payload = {
            "model": model,
            "messages": prepared_messages,
            "stream": False,
            "max_tokens": request_max_tokens,
            "cache_prompt": parse_boolish(
                llama_cpp_profile_config_value(config, model, "cache_prompt", True)
            ),
        }
        chat_template_kwargs = llama_cpp_chat_template_kwargs(config, model)
        if chat_template_kwargs:
            payload["chat_template_kwargs"] = chat_template_kwargs
        if response_schema:
            payload["response_format"] = {
                "type": "json_schema",
                "json_schema": {
                    "name": reviewer_token(operation, fallback="eve_json"),
                    "strict": True,
                    "schema": response_schema,
                },
            }
        elif prefers_json_response(operation):
            payload["response_format"] = {"type": "json_object"}
        request_timeout = max(1, deadline - time.perf_counter())
        started = time.perf_counter()
        try:
            body = post_json_url(url, payload, timeout=request_timeout, headers=headers or None)
        except (error.URLError, http.client.RemoteDisconnected, TimeoutError, socket.timeout) as exc:
            append_perf_event(
                "model_call",
                operation,
                (time.perf_counter() - started) * 1000,
                ok=False,
                metadata={
                    "operation": operation,
                    "backend": "llama_cpp",
                    "model": model,
                    "host": host,
                    "message_count": len(prepared_messages),
                    "max_tokens": request_max_tokens,
                    "attempt": attempt,
                    "recovered_from": recovered_from,
                    "request_timeout_seconds": round(request_timeout, 3),
                    "error": str(exc),
                },
            )
            raise SystemExit(
                "Could not reach llama.cpp cleanly at "
                f"{url}. Make sure the local llama-server is running. Details: {exc}"
            )
        except json.JSONDecodeError as exc:
            append_perf_event(
                "model_call",
                operation,
                (time.perf_counter() - started) * 1000,
                ok=False,
                metadata={
                    "operation": operation,
                    "backend": "llama_cpp",
                    "model": model,
                    "host": host,
                    "message_count": len(prepared_messages),
                    "max_tokens": request_max_tokens,
                    "attempt": attempt,
                    "recovered_from": recovered_from,
                    "request_timeout_seconds": round(request_timeout, 3),
                    "error": f"invalid_json: {exc}",
                },
            )
            raise SystemExit(f"llama.cpp returned invalid JSON: {exc}")
        duration_ms = (time.perf_counter() - started) * 1000
        if "error" in body:
            append_perf_event(
                "model_call",
                operation,
                duration_ms,
                ok=False,
                metadata={
                    "operation": operation,
                    "backend": "llama_cpp",
                    "model": model,
                    "host": host,
                    "message_count": len(prepared_messages),
                    "max_tokens": request_max_tokens,
                    "attempt": attempt,
                    "recovered_from": recovered_from,
                    "request_timeout_seconds": round(request_timeout, 3),
                    "error": normalize_text_value(
                        body.get("error"),
                        fallback=normalize_text_value(
                            body.get("error", {}).get("message")
                            if isinstance(body.get("error"), dict)
                            else "",
                            fallback="unknown llama.cpp error",
                            limit=220,
                        ),
                        limit=220,
                    ),
                },
            )
            raise SystemExit(f"llama.cpp failed: {body['error']}")
        return body, duration_ms

    primary_body, primary_duration_ms = perform_request(messages, max_tokens, attempt="primary")
    content, _, failure_kind = llama_cpp_message_content(primary_body)
    if content:
        append_perf_event(
            "model_call",
            operation,
            primary_duration_ms,
            ok=True,
            metadata={
                "operation": operation,
                "backend": "llama_cpp",
                "model": model,
                "host": host,
                "message_count": len(messages),
                "max_tokens": max_tokens,
                "attempt": "primary",
                "response_chars": len(content),
            },
        )
        return content

    append_perf_event(
        "model_call",
        operation,
        primary_duration_ms,
        ok=False,
        metadata={
            "operation": operation,
            "backend": "llama_cpp",
            "model": model,
            "host": host,
            "message_count": len(messages),
            "max_tokens": max_tokens,
            "attempt": "primary",
            "error": failure_kind or "empty_response",
        },
    )

    retry_messages = [
        *messages,
        {"role": "user", "content": final_answer_retry_instruction(operation)},
    ]
    retry_max_tokens = final_answer_retry_max_tokens(max_tokens)
    try:
        retry_body, retry_duration_ms = perform_request(
            retry_messages,
            retry_max_tokens,
            attempt="final_only_retry",
            recovered_from=failure_kind or "empty_response",
        )
    except SystemExit as exc:
        raise SystemExit(f"llama.cpp returned an empty response. Final-answer retry failed: {exc}")

    retry_content, _, retry_failure_kind = llama_cpp_message_content(retry_body)
    if retry_content:
        append_perf_event(
            "model_call",
            operation,
            retry_duration_ms,
            ok=True,
            metadata={
                "operation": operation,
                "backend": "llama_cpp",
                "model": model,
                "host": host,
                "message_count": len(retry_messages),
                "max_tokens": retry_max_tokens,
                "attempt": "final_only_retry",
                "recovered_from": failure_kind or "empty_response",
                "response_chars": len(retry_content),
            },
        )
        return retry_content

    append_perf_event(
        "model_call",
        operation,
        retry_duration_ms,
        ok=False,
        metadata={
            "operation": operation,
            "backend": "llama_cpp",
            "model": model,
            "host": host,
            "message_count": len(retry_messages),
            "max_tokens": retry_max_tokens,
            "attempt": "final_only_retry",
            "recovered_from": failure_kind or "empty_response",
            "error": retry_failure_kind or "empty_response",
        },
    )
    raise SystemExit("llama.cpp returned an empty response, even after a final-answer-only retry.")


def evaluate_model_governor(
    config: Dict[str, object],
    *,
    model: str,
    operation: str,
    host: str,
) -> Dict[str, object]:
    try:
        recent_events = read_perf_events(
            limit=250,
            since_minutes=int(config.get("model_governor_failure_window_minutes") or 20),
            category="model_call",
        )
        decision = eve_model_governor.decide(
            config,
            recent_events,
            model=model,
            operation=operation,
            host=host,
        )
        if private_evaluator_persistence_active():
            decision["evaluator_private"] = True
            decision["persisted"] = False
        else:
            eve_db.record_model_governor_decision(OPERATIONAL_DB_PATH, decision)
        return decision
    except Exception as exc:
        return {
            "id": str(uuid.uuid4()),
            "created_at": utc_now(),
            "model": model,
            "operation": operation,
            "host": host,
            "action": "allow",
            "reason": f"governor self-error; allowing call: {exc}",
            "failure_count": 0,
        }


def model_chat(
    config: Dict[str, object],
    model: str,
    messages: List[Dict[str, str]],
    max_tokens: int,
    think_level: str,
    operation: str = "general",
    timeout_seconds: int = 1800,
    response_schema: Optional[Dict[str, object]] = None,
) -> str:
    backend = configured_model_backend(config, model, operation)
    host = configured_model_host(config, model, operation)
    active_call = start_active_model_call(
        operation=operation,
        backend=backend,
        model=model,
        host=host,
        message_count=len(messages),
        max_tokens=max_tokens,
    )
    active_call_id = str(active_call.get("id") or "")
    try:
        governor_decision = evaluate_model_governor(config, model=model, operation=operation, host=host)
        if governor_decision.get("action") == "skip":
            append_perf_event(
                "model_governor",
                operation,
                0,
                ok=False,
                metadata={
                    "model": model,
                    "host": host,
                    "action": "skip",
                    "reason": governor_decision.get("reason") or "model governor skipped call",
                    "failure_count": governor_decision.get("failure_count"),
                },
            )
            raise SystemExit(str(governor_decision.get("reason") or "Model governor skipped this call."))
        if backend == "llama_cpp":
            result = llama_cpp_chat(
                config,
                host,
                model,
                messages,
                max_tokens=max_tokens,
                operation=operation,
                timeout_seconds=timeout_seconds,
                response_schema=response_schema,
            )
        else:
            result = ollama_chat(
                host,
                model,
                messages,
                max_tokens=max_tokens,
                think_level=think_level,
                operation=operation,
                timeout_seconds=timeout_seconds,
            )
    except (Exception, SystemExit) as exc:
        finish_active_model_call(active_call_id, ok=False, error_text=str(exc))
        raise
    finish_active_model_call(active_call_id, ok=True)
    return result


def render_output(text: str) -> None:
    print(text.strip())


def run_local_command(cmd: List[str], timeout: int = 60) -> subprocess.CompletedProcess:
    try:
        return subprocess.run(
            cmd,
            check=False,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except FileNotFoundError as exc:
        return subprocess.CompletedProcess(cmd, 127, stdout="", stderr=str(exc))
    except PermissionError as exc:
        return subprocess.CompletedProcess(cmd, 1, stdout="", stderr=str(exc))
    except subprocess.TimeoutExpired:
        raise SystemExit(f"Command timed out: {' '.join(cmd)}")


def clamp_int(value: object, default: int, minimum: int = 1, maximum: Optional[int] = None) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    if parsed < minimum:
        parsed = minimum
    if maximum is not None and parsed > maximum:
        parsed = maximum
    return parsed


def safe_float(value: object, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def truncate_text(value: object, limit: int) -> str:
    text = str(value or "")
    if limit <= 0 or len(text) <= limit:
        return text
    trimmed = text[: max(0, limit - 18)].rstrip()
    return trimmed + "\n...[truncated]"


def capability_specs() -> List[Dict[str, str]]:
    return [
        {
            "name": "shell",
            "description": "Run a local shell command in Eve's workspace root.",
            "args": '{"command": "pwd", "timeout_seconds": 30}',
        },
        {
            "name": "list_dir",
            "description": "List files or folders at a path.",
            "args": '{"path": ".", "limit": 40}',
        },
        {
            "name": "read_file",
            "description": "Read a text file, optionally with line bounds.",
            "args": '{"path": "README.md", "start_line": 1, "end_line": 80}',
        },
        {
            "name": "write_file",
            "description": "Write or overwrite a text file.",
            "args": '{"path": ".eve/note.txt", "content": "hello"}',
        },
        {
            "name": "search_text",
            "description": "Search the workspace with ripgrep.",
            "args": '{"pattern": "def cmd_chat", "path": "eve.py"}',
        },
        {
            "name": "fetch_url",
            "description": "Fetch a web page and summarize the result.",
            "args": '{"url": "https://example.com"}',
        },
        {
            "name": "web_search",
            "description": "Search the public web for candidate pages when Eve needs to discover a tool, documentation, or capability path.",
            "args": '{"query": "python package disk cleanup macos", "limit": 5}',
        },
    ]


def format_capability_specs() -> str:
    lines: List[str] = []
    for spec in capability_specs():
        lines.append(
            f"- {spec['name']}: {spec['description']} Example args: {spec['args']}"
        )
    return "\n".join(lines)


def insert_system_message(messages: List[Dict[str, str]], content: str) -> List[Dict[str, str]]:
    updated: List[Dict[str, str]] = []
    inserted = False
    for message in messages:
        if not inserted and str(message.get("role")) != "system":
            updated.append({"role": "system", "content": content})
            inserted = True
        updated.append(message)
    if not inserted:
        updated.append({"role": "system", "content": content})
    return updated


def build_tool_capability_message() -> str:
    return textwrap.dedent(
        f"""
        Eve's current tool capabilities are available inside the workspace rooted at:
        {ROOT}

        Prefer relative paths inside that workspace when possible.

        Available tools:
        {format_capability_specs()}
        """
    ).strip()


def configured_tool_workspace_root(config: Optional[Dict[str, object]] = None) -> Path:
    effective_config = config or {}
    raw_root = normalize_text_value(effective_config.get("_tool_workspace_root"), fallback="", limit=1000)
    if raw_root:
        candidate = Path(raw_root).expanduser()
        if candidate.exists() and candidate.is_dir():
            return candidate.resolve()
    return ROOT.resolve()


def resolve_tool_path(raw_path: object, config: Optional[Dict[str, object]] = None) -> Path:
    text = str(raw_path or ".").strip() or "."
    path = Path(text).expanduser()
    if not path.is_absolute():
        path = configured_tool_workspace_root(config) / path
    return path.resolve()


def resolve_executable_path(command_name: str) -> str:
    resolved = shutil.which(command_name)
    if resolved:
        return resolved
    for parent in ["/opt/homebrew/bin", "/usr/local/bin", "/Applications/Codex.app/Contents/Resources"]:
        candidate = Path(parent) / command_name
        if candidate.exists() and os.access(candidate, os.X_OK):
            return str(candidate)
    return command_name


def execute_shell_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    command = str(args.get("command") or "").strip()
    if not command:
        raise SystemExit("The shell tool requires a non-empty `command`.")
    timeout_seconds = clamp_int(
        args.get("timeout_seconds"),
        int(config["tool_shell_timeout_seconds"]),
        minimum=1,
        maximum=300,
    )
    output_limit = int(config["tool_output_max_chars"])
    try:
        result = subprocess.run(
            ["/bin/zsh", "-lc", command],
            check=False,
            capture_output=True,
            text=True,
            timeout=timeout_seconds,
            cwd=ROOT,
        )
    except subprocess.TimeoutExpired:
        return {
            "ok": False,
            "command": command,
            "cwd": str(ROOT),
            "timeout_seconds": timeout_seconds,
            "error": "Command timed out.",
        }
    return {
        "ok": result.returncode == 0,
        "command": command,
        "cwd": str(ROOT),
        "timeout_seconds": timeout_seconds,
        "exit_code": result.returncode,
        "stdout": truncate_text(result.stdout, output_limit),
        "stderr": truncate_text(result.stderr, output_limit),
    }


def execute_list_dir_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    path = resolve_tool_path(args.get("path") or ".", config)
    if not path.exists():
        raise SystemExit(f"Path does not exist: {path}")
    if not path.is_dir():
        raise SystemExit(f"Path is not a directory: {path}")
    limit = clamp_int(args.get("limit"), 60, minimum=1, maximum=200)
    children = sorted(path.iterdir(), key=lambda item: (not item.is_dir(), item.name.lower()))
    items: List[Dict[str, object]] = []
    for child in children[:limit]:
        item: Dict[str, object] = {
            "name": child.name,
            "path": str(child),
            "kind": "dir" if child.is_dir() else "file",
        }
        if child.exists() and child.is_file():
            item["size_bytes"] = child.stat().st_size
        items.append(item)
    return {
        "ok": True,
        "path": str(path),
        "item_count": len(children),
        "truncated": len(children) > limit,
        "items": items,
    }


def execute_read_file_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    path = resolve_tool_path(args.get("path"), config)
    if not path.exists():
        raise SystemExit(f"File does not exist: {path}")
    if not path.is_file():
        raise SystemExit(f"Path is not a file: {path}")
    max_lines = clamp_int(args.get("max_lines"), int(config["tool_read_max_lines"]), minimum=1, maximum=400)
    text = path.read_text(encoding="utf-8", errors="replace")
    lines = text.splitlines()
    total_lines = len(lines)
    if total_lines == 0:
        return {
            "ok": True,
            "path": str(path),
            "total_lines": 0,
            "start_line": 0,
            "end_line": 0,
            "content": "",
        }
    start_line = clamp_int(args.get("start_line"), 1, minimum=1, maximum=total_lines)
    end_default = min(total_lines, start_line + max_lines - 1)
    end_line = clamp_int(args.get("end_line"), end_default, minimum=start_line, maximum=total_lines)
    excerpt = "\n".join(lines[start_line - 1 : end_line])
    if text.endswith("\n") and end_line == total_lines:
        excerpt += "\n"
    return {
        "ok": True,
        "path": str(path),
        "total_lines": total_lines,
        "start_line": start_line,
        "end_line": end_line,
        "truncated": start_line > 1 or end_line < total_lines,
        "content": truncate_text(excerpt, int(config["tool_output_max_chars"])),
    }


def execute_write_file_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    path = resolve_tool_path(args.get("path"), config)
    content = str(args.get("content") or "")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return {
        "ok": True,
        "path": str(path),
        "bytes": len(content.encode("utf-8")),
        "lines": len(content.splitlines()) if content else 0,
    }


def execute_search_text_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    pattern = str(args.get("pattern") or "").strip()
    if not pattern:
        raise SystemExit("The search_text tool requires a non-empty `pattern`.")
    path = resolve_tool_path(args.get("path") or ".", config)
    if not path.exists():
        raise SystemExit(f"Search path does not exist: {path}")
    limit = clamp_int(args.get("limit"), int(config["tool_search_max_matches"]), minimum=1, maximum=200)
    timeout_seconds = clamp_int(args.get("timeout_seconds"), 30, minimum=1, maximum=300)
    cmd = [resolve_executable_path("rg"), "-n", "--hidden", "--no-heading", "--color", "never"]
    glob = str(args.get("glob") or "").strip()
    if glob:
        cmd.extend(["--glob", glob])
    cmd.extend([pattern, str(path)])
    result = run_local_command(cmd, timeout=timeout_seconds)
    matches = result.stdout.splitlines()
    ok = result.returncode in {0, 1}
    return {
        "ok": ok,
        "pattern": pattern,
        "path": str(path),
        "match_count": len(matches),
        "matches": matches[:limit],
        "truncated": len(matches) > limit,
        "stderr": truncate_text(result.stderr, int(config["tool_output_max_chars"])),
        "exit_code": result.returncode,
    }


class _ReadableHTMLParser(HTMLParser):
    """Extract readable text without treating regexes as an HTML parser."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self._ignored_depth = 0
        self._title_depth = 0
        self.text_parts: List[str] = []
        self.title_parts: List[str] = []

    def handle_starttag(self, tag: str, attrs: List[Tuple[str, Optional[str]]]) -> None:
        del attrs
        if tag in {"script", "style"}:
            self._ignored_depth += 1
        elif tag == "title" and self._ignored_depth == 0:
            self._title_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag in {"script", "style"}:
            self._ignored_depth = max(0, self._ignored_depth - 1)
        elif tag == "title" and self._ignored_depth == 0:
            self._title_depth = max(0, self._title_depth - 1)

    def handle_data(self, data: str) -> None:
        if self._ignored_depth:
            return
        self.text_parts.append(data)
        if self._title_depth:
            self.title_parts.append(data)


def parse_readable_html(html: str) -> _ReadableHTMLParser:
    parser = _ReadableHTMLParser()
    parser.feed(html)
    parser.close()
    return parser


def html_to_text(html: str) -> str:
    return " ".join(" ".join(parse_readable_html(html).text_parts).split())


def extract_html_title(html: str) -> str:
    return " ".join(" ".join(parse_readable_html(html).title_parts).split())


def execute_fetch_url_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    url = str(args.get("url") or "").strip()
    if not url:
        raise SystemExit("The fetch_url tool requires a non-empty `url`.")
    preview_limit = int(config["web_fetch_max_chars"])
    timeout_seconds = clamp_int(args.get("timeout_seconds"), 30, minimum=1, maximum=300)
    req = request.Request(
        url,
        headers={"User-Agent": "Eve/1.0 (+local workspace tool)"},
        method="GET",
    )
    with request.urlopen(req, timeout=timeout_seconds) as resp:
        status = getattr(resp, "status", resp.getcode())
        content_type = resp.headers.get("Content-Type", "")
        charset = resp.headers.get_content_charset() or "utf-8"
        raw = resp.read(max(preview_limit * 4, 16000))
        final_url = resp.geturl()
    body = raw.decode(charset, errors="replace")
    title = extract_html_title(body)
    preview_source = html_to_text(body) if "<html" in body.lower() or "text/html" in content_type.lower() else " ".join(body.split())
    return {
        "ok": True,
        "url": url,
        "final_url": final_url,
        "status": int(status),
        "content_type": content_type,
        "title": title,
        "preview": truncate_text(preview_source, preview_limit),
    }


def execute_web_search_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    query = str(args.get("query") or "").strip()
    if not query:
        raise SystemExit("The web_search tool requires a non-empty `query`.")
    limit = clamp_int(args.get("limit"), 5, minimum=1, maximum=10)
    timeout_seconds = clamp_int(args.get("timeout_seconds"), 20, minimum=1, maximum=60)
    url = f"https://duckduckgo.com/html/?q={quote(query)}"
    preview_limit = int(config["web_fetch_max_chars"])
    req = request.Request(
        url,
        headers={"User-Agent": "Eve/1.0 (+local workspace web search)"},
        method="GET",
    )
    with request.urlopen(req, timeout=timeout_seconds) as resp:
        status = getattr(resp, "status", resp.getcode())
        raw = resp.read(max(preview_limit * 6, 24000))
        final_url = resp.geturl()
    html = raw.decode("utf-8", errors="replace")
    results: List[Dict[str, str]] = []
    for match in re.finditer(
        r'<a[^>]+class="result__a"[^>]+href="([^"]+)"[^>]*>(.*?)</a>',
        html,
        flags=re.IGNORECASE | re.DOTALL,
    ):
        href = unescape(match.group(1))
        parsed_href = urlparse(href)
        query_params = parse_qs(parsed_href.query)
        if "uddg" in query_params and query_params["uddg"]:
            href = unquote(str(query_params["uddg"][0]))
        title = html_to_text(match.group(2))
        if not title or not href:
            continue
        results.append({"title": title, "url": href})
        if len(results) >= limit:
            break
    if not results:
        # Search markup changes sometimes; keep the raw text preview as evidence instead of pretending there were no results.
        preview = truncate_text(html_to_text(html), preview_limit)
    else:
        preview = "\n".join(f"- {item['title']} | {item['url']}" for item in results)
    return {
        "ok": bool(results),
        "query": query,
        "url": url,
        "final_url": final_url,
        "status": int(status),
        "results": results,
        "preview": truncate_text(preview, preview_limit),
    }


def execute_capability_tool(tool_name: str, args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    dispatch = {
        "shell": execute_shell_tool,
        "list_dir": execute_list_dir_tool,
        "read_file": execute_read_file_tool,
        "write_file": execute_write_file_tool,
        "search_text": execute_search_text_tool,
        "fetch_url": execute_fetch_url_tool,
        "web_search": execute_web_search_tool,
    }
    tool = dispatch.get(tool_name)
    if tool is None:
        return {"ok": False, "error": f"Unknown tool `{tool_name}`."}
    try:
        return tool(args, config)
    except SystemExit as exc:
        return {"ok": False, "error": str(exc)}
    except Exception as exc:  # pragma: no cover - defensive boundary for tool runs
        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


def parse_agent_response(text: str) -> Optional[Dict[str, object]]:
    try:
        payload = extract_json_object(text, label="agent response")
    except SystemExit:
        return None
    response_type = str(payload.get("type") or payload.get("action") or "").strip().lower()
    if not response_type:
        if payload.get("tool") or payload.get("name"):
            response_type = "tool_call"
        elif payload.get("message") or payload.get("content") or payload.get("response"):
            response_type = "final"
    if response_type == "tool_call":
        tool_name = str(payload.get("tool") or payload.get("name") or "").strip()
        args = payload.get("args") if isinstance(payload.get("args"), dict) else {}
        if not tool_name:
            return None
        return {"type": "tool_call", "tool": tool_name, "args": args}
    if response_type == "final":
        message = str(payload.get("message") or payload.get("content") or payload.get("response") or "").strip()
        if not message:
            message = text.strip()
        return {"type": "final", "message": message}
    return None


def build_tool_result_message(tool_name: str, result: Dict[str, object]) -> str:
    return textwrap.dedent(
        f"""
        Tool result for `{tool_name}`:
        {json.dumps(result, ensure_ascii=True, indent=2)}

        Continue from this evidence. Return JSON only.
        If you need another tool, return {{"type":"tool_call","tool":"<name>","args":{{...}}}}.
        If you are done, return {{"type":"final","message":"<answer>"}}.
        """
    ).strip()


def build_tool_protocol_recovery_response(tool_calls: List[Dict[str, object]]) -> str:
    if not tool_calls:
        return (
            "I could not complete the tool protocol cleanly, and no tool result is available. "
            "I should not claim the action completed."
        )
    latest = tool_calls[-1]
    tool_name = normalize_text_value(latest.get("tool"), fallback="unknown_tool", limit=80)
    result = latest.get("result") if isinstance(latest.get("result"), dict) else {}
    ok = bool(result.get("ok"))
    execution_id = normalize_text_value(result.get("execution_id") or result.get("id"), fallback="", limit=80)
    tree_status = normalize_text_value(
        result.get("execution_tree_status") or result.get("tree_status") or result.get("status"),
        fallback="unknown",
        limit=80,
    )
    summary = normalize_text_value(
        result.get("execution_summary")
        or result.get("summary")
        or result.get("response")
        or result.get("error")
        or result.get("preview"),
        fallback="Tool returned no compact summary.",
        limit=520,
    )
    verification = result.get("execution_verification_ok")
    verification_text = (
        "unknown"
        if verification is None
        else "yes"
        if bool(verification)
        else "no"
    )
    record = (
        f"execution_id={execution_id}, tree_status={tree_status}, verification_ok={verification_text}"
        if execution_id
        else f"tool={tool_name}, ok={'yes' if ok else 'no'}, status={tree_status}, verification_ok={verification_text}"
    )
    return "\n".join(
        [
            "TOOL_PROTOCOL_RECOVERY: Eve's model did not return a valid final JSON envelope after tool use, so the runtime is reporting only the verified tool evidence.",
            f"ACTION_ATTEMPTED: {tool_name}",
            f"VERIFICATION_RECORD: {record}",
            f"RESULT: {summary}",
            "NOT_CLAIMING: I am not treating the malformed final model message as successful reasoning or as evidence of completion beyond the tool record above.",
        ]
    )


def run_eve_agent(
    config: Dict[str, object],
    messages: List[Dict[str, str]],
    max_tokens: int,
    allow_tools: bool = True,
    require_tool_use: bool = False,
    model_role: str = "chat",
    model_override: Optional[str] = None,
    timeout_seconds: Optional[int] = None,
) -> Dict[str, object]:
    model = resolve_model(config, model_role, explicit_model=model_override)
    think_level = str(config["think_level"])
    host = str(config["ollama_host"])
    request_timeout = int(timeout_seconds or 1800)
    if not allow_tools:
        operation = f"agent_{model_role}_direct"
        input_provenance = model_input_provenance(
            config,
            model,
            messages,
            operation=operation,
        )
        response = model_chat(
            config,
            model,
            messages,
            max_tokens=max_tokens,
            think_level=think_level,
            operation=operation,
            timeout_seconds=request_timeout,
        )
        return {
            "response": response,
            "model": model,
            "tool_calls": [],
            "input_provenance": input_provenance,
        }

    tool_messages = insert_system_message(messages, build_tool_capability_message())
    tool_messages = insert_system_message(tool_messages, load_prompt("tool_use.md"))
    tool_calls: List[Dict[str, object]] = []
    correction_count = 0
    max_steps = int(config["tool_max_steps"])

    for _ in range(max_steps):
        raw = model_chat(
            config,
            model,
            tool_messages,
            max_tokens=max_tokens,
            think_level=think_level,
            operation=f"agent_{model_role}_tool_loop",
            timeout_seconds=request_timeout,
        )
        parsed = parse_agent_response(raw)
        if parsed is None:
            if not require_tool_use and not tool_calls:
                return {"response": raw, "model": model, "tool_calls": tool_calls}
            correction_count += 1
            if correction_count > 2:
                if not require_tool_use and tool_calls:
                    return {
                        "response": build_tool_protocol_recovery_response(tool_calls),
                        "model": model,
                        "tool_calls": tool_calls,
                        "tool_protocol_recovery": True,
                    }
                raise SystemExit("Eve did not follow the JSON tool protocol.")
            tool_messages.append({"role": "assistant", "content": raw})
            tool_messages.append(
                {
                    "role": "system",
                    "content": (
                        "Return JSON only. Use "
                        '{"type":"tool_call","tool":"<name>","args":{...}} '
                        'for tool use or {"type":"final","message":"<answer>"} when finished.'
                    ),
                }
            )
            continue

        correction_count = 0
        if parsed["type"] == "final":
            final_message = str(parsed.get("message") or "").strip()
            if require_tool_use and not tool_calls:
                raise SystemExit("Eve finished without using any tools.")
            return {"response": final_message, "model": model, "tool_calls": tool_calls}

        tool_name = str(parsed.get("tool") or "").strip()
        args = parsed.get("args") if isinstance(parsed.get("args"), dict) else {}
        result = execute_capability_tool(tool_name, args, config)
        tool_calls.append({"tool": tool_name, "args": args, "result": result})
        tool_messages.append({"role": "assistant", "content": raw})
        tool_messages.append({"role": "system", "content": build_tool_result_message(tool_name, result)})

    raise SystemExit("Eve hit the tool-use step limit before finishing.")


