CODE_SESSION_EVENT_STRING_MAX_CHARS = 6000
CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS = 80
CODE_SESSION_EVENT_MAX_DEPTH = 6
CODE_SESSION_LOG_MAX_BYTES = 5 * 1024 * 1024
CODE_SESSION_LOG_HEAD_BYTES = 64 * 1024
CODE_SESSION_LOG_TAIL_BYTES = 512 * 1024


def normalize_code_session_id(value: object) -> str:
    text = str(value or "").strip()
    if not text:
        return utc_timestamp_for_filename() + "-" + str(uuid.uuid4())[:8]
    normalized = re.sub(r"[^A-Za-z0-9_.-]+", "-", text).strip(".-")
    return normalized[:120] or utc_timestamp_for_filename()


def code_session_path(session_id: object) -> Path:
    return CODE_SESSIONS_DIR / f"{normalize_code_session_id(session_id)}.jsonl"


def sanitize_code_session_value(value: object, *, depth: int = 0) -> object:
    if depth >= CODE_SESSION_EVENT_MAX_DEPTH:
        return normalize_text_value(value, fallback="", limit=CODE_SESSION_EVENT_STRING_MAX_CHARS)
    if value is None or isinstance(value, (bool, int, float)):
        return value
    if isinstance(value, str):
        return truncate_text(value, CODE_SESSION_EVENT_STRING_MAX_CHARS)
    if isinstance(value, Path):
        return truncate_text(str(value), CODE_SESSION_EVENT_STRING_MAX_CHARS)
    if isinstance(value, dict):
        sanitized: Dict[str, object] = {}
        items = list(value.items())
        for key, item_value in items[:CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS]:
            sanitized_key = normalize_text_value(key, fallback="key", limit=160)
            sanitized[sanitized_key] = sanitize_code_session_value(item_value, depth=depth + 1)
        if len(items) > CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS:
            sanitized["_truncated_items"] = len(items) - CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS
        return sanitized
    if isinstance(value, (list, tuple, set)):
        items = list(value)
        sanitized_items = [
            sanitize_code_session_value(item, depth=depth + 1)
            for item in items[:CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS]
        ]
        if len(items) > CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS:
            sanitized_items.append({"_truncated_items": len(items) - CODE_SESSION_EVENT_CONTAINER_MAX_ITEMS})
        return sanitized_items
    return truncate_text(str(value), CODE_SESSION_EVENT_STRING_MAX_CHARS)


def complete_head_lines(data: bytes) -> bytes:
    if not data:
        return b""
    newline_index = data.rfind(b"\n")
    if newline_index < 0:
        return b""
    return data[: newline_index + 1]


def complete_tail_lines(data: bytes) -> bytes:
    if not data:
        return b""
    newline_index = data.find(b"\n")
    if newline_index < 0:
        return b""
    return data[newline_index + 1 :]


def compact_code_session_log_file(
    path: Path,
    *,
    apply: bool = False,
    max_bytes: int = CODE_SESSION_LOG_MAX_BYTES,
    head_bytes: int = CODE_SESSION_LOG_HEAD_BYTES,
    tail_bytes: int = CODE_SESSION_LOG_TAIL_BYTES,
) -> Dict[str, object]:
    result: Dict[str, object] = {
        "path": str(path),
        "exists": path.exists(),
        "apply": apply,
        "max_bytes": max_bytes,
    }
    if not path.exists():
        result["status"] = "missing"
        return result
    try:
        original_size = path.stat().st_size
    except OSError as exc:
        result.update({"status": "error", "error": str(exc)})
        return result
    result["original_size_bytes"] = original_size
    if original_size <= max_bytes:
        result["status"] = "within_limit"
        return result
    result["status"] = "would_compact"
    if not apply:
        return result

    head_chunk = b""
    tail_chunk = b""
    try:
        with path.open("rb") as handle:
            head_chunk = complete_head_lines(handle.read(max(0, head_bytes)))
            if original_size > tail_bytes:
                handle.seek(max(0, original_size - max(0, tail_bytes)))
            tail_chunk = complete_tail_lines(handle.read(max(0, tail_bytes)))
    except OSError as exc:
        result.update({"status": "error", "error": str(exc)})
        return result

    if head_chunk and tail_chunk and head_chunk == tail_chunk:
        tail_chunk = b""
    marker = {
        "id": str(uuid.uuid4()),
        "timestamp": utc_now(),
        "type": "log_compaction",
        "original_size_bytes": original_size,
        "kept_head_bytes": len(head_chunk),
        "kept_tail_bytes": len(tail_chunk),
        "max_bytes": max_bytes,
        "note": "Coder-session log compacted to preserve the first and latest complete JSONL lines.",
    }
    temp_path = path.with_name(path.name + ".compact-tmp")
    try:
        with temp_path.open("wb") as handle:
            handle.write(json.dumps(marker, ensure_ascii=True).encode("utf-8") + b"\n")
            handle.write(head_chunk)
            if tail_chunk:
                handle.write(tail_chunk)
        temp_path.replace(path)
    except OSError as exc:
        try:
            if temp_path.exists():
                temp_path.unlink()
        except OSError:
            pass
        result.update({"status": "error", "error": str(exc)})
        return result

    try:
        compacted_size = path.stat().st_size
    except OSError:
        compacted_size = 0
    result.update(
        {
            "status": "compacted",
            "compacted_size_bytes": compacted_size,
            "reclaimed_bytes": max(0, original_size - compacted_size),
        }
    )
    return result


def code_session_log_paths(*, include_runtime: bool = False) -> List[Path]:
    roots = [CODE_SESSIONS_DIR]
    if include_runtime:
        roots.append(RUNTIME_CODE_SESSIONS_DIR)
    paths: List[Path] = []
    seen: set = set()
    for root in roots:
        if not root.exists():
            continue
        for path in sorted(root.glob("*.jsonl")):
            try:
                key = str(path.resolve())
            except OSError:
                key = str(path)
            if key in seen:
                continue
            seen.add(key)
            paths.append(path)
    return paths


def compact_code_session_logs(
    *,
    include_runtime: bool = False,
    apply: bool = False,
    max_bytes: int = CODE_SESSION_LOG_MAX_BYTES,
    head_bytes: int = CODE_SESSION_LOG_HEAD_BYTES,
    tail_bytes: int = CODE_SESSION_LOG_TAIL_BYTES,
) -> List[Dict[str, object]]:
    return [
        compact_code_session_log_file(
            path,
            apply=apply,
            max_bytes=max_bytes,
            head_bytes=head_bytes,
            tail_bytes=tail_bytes,
        )
        for path in code_session_log_paths(include_runtime=include_runtime)
    ]


def append_code_session_event(session_id: object, event_type: str, payload: Dict[str, object]) -> Dict[str, object]:
    ensure_store()
    CODE_SESSIONS_DIR.mkdir(parents=True, exist_ok=True)
    event = {
        "id": str(uuid.uuid4()),
        "timestamp": utc_now(),
        "type": normalize_text_value(event_type, fallback="event", limit=80),
        **{
            key: sanitize_code_session_value(value)
            for key, value in payload.items()
        },
    }
    path = code_session_path(session_id)
    compact_code_session_log_file(path, apply=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(event, ensure_ascii=True) + "\n")
    return event


def read_code_session_events(session_id: object, limit: Optional[int] = None) -> List[Dict[str, object]]:
    path = code_session_path(session_id)
    if not path.exists():
        return []
    records = read_jsonl_tail_records(path, limit) if limit else read_jsonl_records(path)
    return records


def list_code_sessions(limit: int = 10) -> List[Dict[str, object]]:
    ensure_store()
    CODE_SESSIONS_DIR.mkdir(parents=True, exist_ok=True)
    sessions: List[Dict[str, object]] = []
    for path in sorted(CODE_SESSIONS_DIR.glob("*.jsonl"), key=lambda item: item.stat().st_mtime, reverse=True):
        events = eve_store.read_jsonl_tail_records(path, 8)
        first_user = next((event for event in events if event.get("type") == "user_request"), {})
        final = next((event for event in reversed(events) if event.get("type") in {"final", "error"}), {})
        sessions.append(
            {
                "id": path.stem,
                "path": str(path),
                "updated_at": datetime.fromtimestamp(path.stat().st_mtime, tz=timezone.utc).replace(microsecond=0).isoformat(),
                "event_count_sample": len(events),
                "request": normalize_text_value(first_user.get("request"), fallback="", limit=160),
                "status": final.get("type") or "open",
                "summary": normalize_text_value(final.get("response") or final.get("error"), fallback="", limit=180),
            }
        )
        if len(sessions) >= limit:
            break
    return sessions


SELF_REPAIR_SCHEMA_VERSION = "eve_self_repair_plan.v1"
OPERATIONAL_REPAIR_SCHEMA_VERSION = "eve_operational_repair_plan.v1"


def classify_self_repair_kind(
    objective: object,
    *,
    files: Optional[List[str]] = None,
    tests: Optional[List[str]] = None,
) -> str:
    text = " ".join(
        normalize_text_list(
            [objective, *(files or []), *(tests or [])],
            limit=80,
        )
    ).lower()
    operational_terms = (
        "runtime/source",
        "source/runtime",
        "runtime source",
        "source sync",
        "runtime sync",
        "runtime drift",
        "runtime mismatch",
        "runtime_source_mismatch",
        "runtime bundle",
        "state reconcile",
        "state authority",
        "daemon restart",
        "restart daemon",
        "launchagent",
        "active claim",
        "claims release",
        "mirror drift",
        "mirror lag",
        "operational state",
        "runtime state",
        "state refresh",
        "state summaries",
        "system snapshot",
        "system observer",
        "cleanup_review_summary",
        "cleanup_candidate_summary",
        ".eve/state.json",
        ".eve/system_snapshot.json",
        ".eve/system_tasks.jsonl",
    )
    code_terms = (
        "code patch",
        "patch code",
        "source code",
        "implementation",
        "unit test",
        "test failure",
        "failing test",
        "regression",
        "syntax",
        "py_compile",
        "change function",
        "edit function",
    )
    code_scan_text = text
    for phrase in (
        "not a code patch",
        "without source code edits",
        "without source code changes",
        "no source code edits",
        "no source code changes",
        "do not change source files",
        "no source files are changed",
    ):
        code_scan_text = code_scan_text.replace(phrase, "")
    has_operational_signal = any(term in text for term in operational_terms)
    has_code_signal = any(term in code_scan_text for term in code_terms)
    return "operational" if has_operational_signal and not has_code_signal else "code_patch"


def default_self_repair_files(objective: object = "") -> List[str]:
    objective_text = normalize_text_value(objective, fallback="", limit=500).lower()
    files = [
        "eve.py",
        "tests/test_self_repair.py",
        "docs/SPECIALIST_SUBSTRATES.md",
        "docs/operating/CODEX_CAPABILITY_BRIDGE.md",
        "README.md",
        "PROJECT_MEMORY.md",
        "COORDINATION.md",
    ]
    if "openclaw" in objective_text or "repair" in objective_text:
        files.append("openclaw/skills/eve_self_repair/SKILL.md")
    return files


def default_self_repair_tests() -> List[str]:
    return [
        "python3 -m py_compile eve.py",
        "python3 -m unittest tests.test_self_repair tests.test_coder_mode tests.test_eve_governance",
        "python3 eve.py governance code-lifecycle --source eve_self_repair --file <code_patch_payload_path> --full",
        "python3 eve.py safety drills --full",
    ]


def default_operational_repair_tests(objective: object = "", runtime_truth: Optional[Dict[str, object]] = None) -> List[str]:
    objective_text = normalize_text_value(objective, fallback="", limit=900).lower()
    runtime_truth = runtime_truth if isinstance(runtime_truth, dict) else {}
    commands = ["python3 eve.py runtime truth --json"]
    if bool(runtime_truth.get("needs_runtime_sync")) or any(
        term in objective_text
        for term in (
            "runtime/source",
            "source/runtime",
            "runtime sync",
            "runtime drift",
            "runtime mismatch",
            "runtime_source_mismatch",
            "runtime bundle",
        )
    ):
        commands.append("python3 eve.py runtime sync")
    commands.append("python3 eve.py runtime truth --json")
    return commands[:8]


def compact_runtime_truth_for_self_repair(runtime_truth: Dict[str, object]) -> Dict[str, object]:
    files = []
    for item in runtime_truth.get("files") or []:
        if not isinstance(item, dict):
            continue
        files.append(
            {
                "label": item.get("label"),
                "matches": bool(item.get("matches")),
                "runtime_older_than_source": bool(item.get("runtime_older_than_source")),
                "source_path": item.get("source_path"),
                "runtime_path": item.get("runtime_path"),
            }
        )
    state_authority = runtime_truth.get("state_authority") if isinstance(runtime_truth.get("state_authority"), dict) else {}
    return {
        "status": runtime_truth.get("status") or "unknown",
        "daemon_runtime_running": runtime_truth.get("daemon_runtime_running"),
        "needs_runtime_sync": bool(runtime_truth.get("needs_runtime_sync")),
        "needs_state_reconcile": bool(runtime_truth.get("needs_state_reconcile")),
        "state_authority_status": state_authority.get("status"),
        "files": files[:8],
    }


def build_self_repair_readiness_report(
    objective: object,
    *,
    runtime_truth: Optional[Dict[str, object]] = None,
    safety_drills: Optional[Dict[str, object]] = None,
    safety_drills_path: str = "",
    code_sessions: Optional[List[Dict[str, object]]] = None,
    code_proposals: Optional[List[Dict[str, object]]] = None,
    prefer_runtime: bool = True,
) -> Dict[str, object]:
    objective_text = normalize_text_value(
        objective,
        fallback="Plan a bounded Eve self-repair.",
        limit=900,
    )
    runtime_truth = runtime_truth if runtime_truth is not None else runtime_source_truth_check(
        include_daemon=True,
        include_state_authority=True,
    )
    if safety_drills is None:
        safety_drills, safety_drills_path = read_whole_system_json_artifact(
            SAFETY_DRILLS_LATEST_PATH,
            prefer_runtime=prefer_runtime,
        )
    code_sessions = code_sessions if code_sessions is not None else list_code_sessions(limit=5)
    code_proposals = code_proposals if code_proposals is not None else read_governance_proposals(
        limit=8,
        proposal_type="CodePatchProposal",
        prefer_runtime=prefer_runtime,
    )

    blockers: List[str] = []
    cautions: List[str] = []
    if not objective_text:
        blockers.append("missing_objective")
    if not callable(globals().get("cmd_code_ask")):
        blockers.append("coder_mode_unavailable")
    if not callable(globals().get("cmd_governance_ingest_codex")):
        blockers.append("codex_code_patch_ingest_unavailable")
    if not callable(globals().get("governance_code_patch_lifecycle_plan")):
        blockers.append("code_lifecycle_unavailable")
    if not callable(globals().get("cmd_codex_handoff")):
        cautions.append("codex_handoff_cli_unavailable")
    if bool(runtime_truth.get("needs_runtime_sync")):
        cautions.append("runtime_source_sync_needed_before_live_trust")
    if bool(runtime_truth.get("needs_state_reconcile")):
        cautions.append("state_authority_reconcile_needed_before_live_trust")
    if not safety_drills:
        cautions.append("no_latest_safety_drills_artifact")
    elif str(safety_drills.get("status") or "") not in {"passed", "clean", "ok"}:
        cautions.append(f"safety_drills_status_{safety_drills.get('status') or 'unknown'}")

    recent_unreviewed_code = [
        str(item.get("id") or "")
        for item in code_proposals
        if isinstance(item, dict) and governance_proposal_approval_status(item) == "unreviewed"
    ]
    if recent_unreviewed_code:
        cautions.append("existing_unreviewed_code_patch_proposals")

    status = "blocked" if blockers else ("watch" if cautions else "ready")
    evidence_refs = unique_compact(
        [
            f"runtime_truth_status:{runtime_truth.get('status') or 'unknown'}",
            f"safety_drills:{safety_drills_path or 'missing'}",
            "coder_mode:python3 eve.py code ask|session|list|open|compact",
            "codex_handoff:python3 eve.py codex handoff",
            "governance_ingest_codex:python3 eve.py governance ingest-codex",
            "governance_code_lifecycle:python3 eve.py governance code-lifecycle",
            "docs:SPECIALIST_SUBSTRATES.md",
            "docs:operating/CODEX_CAPABILITY_BRIDGE.md",
        ],
        limit=12,
    )
    return {
        "schema_version": "eve_self_repair_readiness.v1",
        "generated_at": utc_now(),
        "objective": objective_text,
        "status": status,
        "blockers": blockers,
        "cautions": unique_compact(cautions, limit=12),
        "boundary": {
            "five_lanes_fixed": True,
            "adds_chat_lane": False,
            "deploys_code": False,
            "direct_state_write_allowed": False,
            "requires_approval": True,
            "requires_canary": True,
            "codex_is_separate_operator": True,
        },
        "runtime_truth": compact_runtime_truth_for_self_repair(runtime_truth),
        "safety_drills": {
            "path": safety_drills_path,
            "status": safety_drills.get("status") if isinstance(safety_drills, dict) else "",
            "exists": bool(safety_drills),
        },
        "recent_code_sessions": code_sessions[:5],
        "recent_code_patch_proposals": [
            {
                "id": item.get("id"),
                "review_status": item.get("review_status"),
                "approval": governance_proposal_approval_status(item),
                "canary": governance_proposal_canary_status(item),
                "summary": governance_proposal_summary(item, governance_proposal_claim(item)),
            }
            for item in code_proposals[:5]
            if isinstance(item, dict)
        ],
        "evidence_refs": evidence_refs,
        "next_actions": [
            "Classify the repair as operational or code-patch work.",
            "For operational drift, produce an OperationalRepairPlan and run only the listed commands after current-claim preflight.",
            "For code changes, create a strict CodePatchProposal and keep approval, canary, tests, and adoption separate.",
        ],
    }


def build_self_repair_code_patch_payload(
    objective: object,
    *,
    files: Optional[List[str]] = None,
    tests: Optional[List[str]] = None,
    evidence: Optional[List[str]] = None,
    diagnosis_only: bool = False,
) -> Dict[str, object]:
    objective_text = normalize_text_value(
        objective,
        fallback="Plan a bounded Eve self-repair.",
        limit=900,
    )
    files_changed = normalize_text_list(files or [], limit=40) or default_self_repair_files(objective_text)
    test_commands = normalize_text_list(tests or [], limit=40) or default_self_repair_tests()
    evidence_refs = normalize_text_list(evidence or [], limit=20)
    if not evidence_refs:
        evidence_refs = ["self_repair_readiness_report"]
    return {
        "code_patches": [
            {
                "summary": f"Eve self-repair proposal: {objective_text}",
                "objective": objective_text,
                "files_changed": files_changed,
                "tests": test_commands,
                "rollback_plan": (
                    "Do not auto-apply. Reject or revert the patch, restore the last known good git/app state, "
                    "then rerun runtime truth, governance code-lifecycle, targeted tests, and safety drills."
                ),
                "evidence": evidence_refs,
                "risk_level": 2,
                "requires_approval": True,
                "metadata": {
                    "source": "eve_self_repair",
                    "diagnosis_only": bool(diagnosis_only),
                    "deploys_code": False,
                    "direct_state_write_allowed": False,
                    "requires_approval": True,
                    "requires_canary": True,
                    "adds_chat_lane": False,
                    "codex_is_separate_operator": True,
                    "five_lanes_fixed": True,
                },
            }
        ]
    }


def reviewed_self_repair_code_patch_proposal(payload: Dict[str, object]) -> Dict[str, object]:
    proposals = eve_governance.proposal_envelopes_from_adapter_payload(
        payload,
        default_source="eve_self_repair",
    )
    code_proposals = [proposal for proposal in proposals if str(proposal.get("type") or "") == "CodePatchProposal"]
    if len(code_proposals) != 1:
        raise ValueError("Self-repair planning must create exactly one CodePatchProposal.")
    return eve_governance.reviewed_proposal(code_proposals[0])


def build_self_repair_operational_payload(
    objective: object,
    *,
    tests: Optional[List[str]] = None,
    evidence: Optional[List[str]] = None,
    runtime_truth: Optional[Dict[str, object]] = None,
    diagnosis_only: bool = False,
) -> Dict[str, object]:
    objective_text = normalize_text_value(
        objective,
        fallback="Plan a bounded Eve operational repair.",
        limit=900,
    )
    runtime_truth = runtime_truth if isinstance(runtime_truth, dict) else {}
    test_commands = normalize_text_list(tests or [], limit=40) or default_operational_repair_tests(
        objective_text,
        runtime_truth,
    )
    evidence_refs = normalize_text_list(evidence or [], limit=20) or ["self_repair_readiness_report"]
    return {
        "schema_version": OPERATIONAL_REPAIR_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "summary": f"Eve operational repair plan: {objective_text}",
        "objective": objective_text,
        "repair_kind": "operational",
        "mode": "diagnosis_only" if diagnosis_only else "operator_execute_after_preflight",
        "status": "watch" if diagnosis_only else "ready_for_operator_execution",
        "deploys_code": False,
        "changes_live_routing": False,
        "adds_chat_lane": False,
        "direct_state_write_allowed": False,
        "requires_current_claim_check": True,
        "runtime_truth": compact_runtime_truth_for_self_repair(runtime_truth),
        "commands": [
            {
                "id": f"step_{index + 1}",
                "command": command,
                "purpose": "verify" if "truth" in command else "repair",
            }
            for index, command in enumerate(test_commands)
        ],
        "verification": test_commands,
        "stop_conditions": [
            "active_codex_claim_touches_same_runtime_files",
            "runtime_truth_still_mismatched_after_sync",
            "state_authority_requires_reconcile",
            "command_fails_or_returns_unverifiable_output",
        ],
        "rollback_plan": (
            "Operational repair must not edit source. If runtime sync or restart worsens state, rerun runtime truth, "
            "restore the previous known-good source/runtime pairing, and record the failed command output before retrying."
        ),
        "evidence": evidence_refs,
    }


def operational_self_repair_lifecycle_plan(
    operational_payload: Dict[str, object],
    readiness: Dict[str, object],
    *,
    stored: bool = False,
) -> Dict[str, object]:
    blockers = normalize_text_list(readiness.get("blockers"), limit=20)
    cautions = normalize_text_list(readiness.get("cautions"), limit=20)
    status = "blocked" if blockers else ("watch" if cautions else "ready")
    next_steps = [
        "Recheck coordination claims before executing operational commands.",
        "Run the OperationalRepairPlan commands in order.",
        "Rerun runtime truth and preserve the resulting artifact.",
    ]
    return {
        "schema_version": "eve_operational_repair_lifecycle.v1",
        "status": status,
        "stored": bool(stored),
        "deploys_code": False,
        "changes_live_routing": False,
        "queue_target": "none",
        "proposal_type": "OperationalRepairPlan",
        "approval_status": "not_required_for_plan",
        "canary_status": "command_verification_required",
        "blockers": blockers,
        "cautions": cautions,
        "commands": [
            item.get("command")
            for item in operational_payload.get("commands", [])
            if isinstance(item, dict) and item.get("command")
        ],
        "next_steps": next_steps,
    }


def build_self_repair_plan(
    objective: object,
    *,
    files: Optional[List[str]] = None,
    tests: Optional[List[str]] = None,
    diagnosis_only: bool = False,
    prefer_runtime: bool = True,
    runtime_truth: Optional[Dict[str, object]] = None,
    safety_drills: Optional[Dict[str, object]] = None,
    safety_drills_path: str = "",
    code_sessions: Optional[List[Dict[str, object]]] = None,
    code_proposals: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    readiness = build_self_repair_readiness_report(
        objective,
        runtime_truth=runtime_truth,
        safety_drills=safety_drills,
        safety_drills_path=safety_drills_path,
        code_sessions=code_sessions,
        code_proposals=code_proposals,
        prefer_runtime=prefer_runtime,
    )
    repair_kind = classify_self_repair_kind(readiness.get("objective"), files=files, tests=tests)
    if repair_kind == "operational":
        operational = build_self_repair_operational_payload(
            readiness.get("objective"),
            tests=tests,
            evidence=normalize_text_list(readiness.get("evidence_refs"), limit=20),
            runtime_truth=readiness.get("runtime_truth") if isinstance(readiness.get("runtime_truth"), dict) else {},
            diagnosis_only=diagnosis_only,
        )
        lifecycle = operational_self_repair_lifecycle_plan(operational, readiness, stored=False)
        return {
            "schema_version": SELF_REPAIR_SCHEMA_VERSION,
            "generated_at": utc_now(),
            "objective": readiness.get("objective"),
            "status": readiness.get("status"),
            "repair_kind": "operational",
            "mode": "diagnosis_only" if diagnosis_only else "operational_repair_ready",
            "promotes_or_deploys_code": False,
            "live_routing_changed": False,
            "readiness": readiness,
            "operational_repair_plan": operational,
            "operational_lifecycle": lifecycle,
            "commands": {
                "inspect": "python3 eve.py self-repair plan <objective> --full",
                "execute_after_claim_preflight": "<operational_repair_payload_path>",
                "verify": "python3 eve.py runtime truth --json",
                "codex_handoff": "python3 eve.py self-repair plan <objective> --codex-handoff --full",
            },
        }
    payload = build_self_repair_code_patch_payload(
        readiness.get("objective"),
        files=files,
        tests=tests,
        evidence=normalize_text_list(readiness.get("evidence_refs"), limit=20),
        diagnosis_only=diagnosis_only,
    )
    reviewed = reviewed_self_repair_code_patch_proposal(payload)
    lifecycle = governance_code_patch_lifecycle_plan(reviewed, stored=False)
    return {
        "schema_version": SELF_REPAIR_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "objective": readiness.get("objective"),
        "status": readiness.get("status"),
        "repair_kind": "code_patch",
        "mode": "diagnosis_only" if diagnosis_only else "proposal_and_handoff_ready",
        "promotes_or_deploys_code": False,
        "live_routing_changed": False,
        "readiness": readiness,
        "code_patch_payload": payload,
        "reviewed_code_patch_proposal": reviewed,
        "code_lifecycle": lifecycle,
        "commands": {
            "inspect": "python3 eve.py self-repair plan <objective> --full",
            "dry_run_ingest": "python3 eve.py governance ingest-codex --source eve_self_repair --file <code_patch_payload_path> --dry-run --full",
            "queue": "python3 eve.py self-repair plan <objective> --queue --full",
            "code_lifecycle": "python3 eve.py governance code-lifecycle --source eve_self_repair --file <code_patch_payload_path> --full",
            "codex_handoff": "python3 eve.py self-repair plan <objective> --codex-handoff --full",
        },
    }


def update_self_repair_plan_commands_with_payload_path(plan: Dict[str, object], payload_path: Path) -> None:
    commands = plan.get("commands") if isinstance(plan.get("commands"), dict) else {}
    for key, value in list(commands.items()):
        commands[key] = (
            str(value)
            .replace("<code_patch_payload_path>", shlex.quote(str(payload_path)))
            .replace("<operational_repair_payload_path>", shlex.quote(str(payload_path)))
        )


def replace_self_repair_payload_path_placeholders(value: object, payload_path: Path) -> object:
    if isinstance(value, str):
        return value.replace("<code_patch_payload_path>", str(payload_path))
    if isinstance(value, list):
        return [replace_self_repair_payload_path_placeholders(item, payload_path) for item in value]
    if isinstance(value, dict):
        return {
            str(key): replace_self_repair_payload_path_placeholders(item, payload_path)
            for key, item in value.items()
        }
    return value


def update_self_repair_plan_payload_with_payload_path(plan: Dict[str, object], payload_path: Path) -> None:
    payload = plan.get("code_patch_payload") if isinstance(plan.get("code_patch_payload"), dict) else {}
    reviewed = plan.get("reviewed_code_patch_proposal") if isinstance(plan.get("reviewed_code_patch_proposal"), dict) else {}
    operational = plan.get("operational_repair_plan") if isinstance(plan.get("operational_repair_plan"), dict) else {}
    if payload:
        plan["code_patch_payload"] = replace_self_repair_payload_path_placeholders(payload, payload_path)
    if reviewed:
        updated_reviewed = replace_self_repair_payload_path_placeholders(reviewed, payload_path)
        if isinstance(updated_reviewed, dict):
            plan["reviewed_code_patch_proposal"] = updated_reviewed
            plan["code_lifecycle"] = governance_code_patch_lifecycle_plan(
                updated_reviewed,
                stored=bool(plan.get("queue_result")),
            )
    if operational:
        updated_operational = replace_self_repair_payload_path_placeholders(operational, payload_path)
        if isinstance(updated_operational, dict):
            plan["operational_repair_plan"] = updated_operational
            plan["operational_lifecycle"] = operational_self_repair_lifecycle_plan(
                updated_operational,
                plan.get("readiness") if isinstance(plan.get("readiness"), dict) else {},
                stored=bool(plan.get("artifact_path")),
            )


def save_self_repair_plan_artifact(plan: Dict[str, object]) -> Dict[str, object]:
    ensure_store()
    SELF_REPAIR_DIR.mkdir(parents=True, exist_ok=True)
    SELF_REPAIR_HISTORY_DIR.mkdir(parents=True, exist_ok=True)
    stamp = utc_timestamp_for_filename()
    plan_path = SELF_REPAIR_HISTORY_DIR / f"self_repair_plan-{stamp}.json"
    operational_kind = str(plan.get("repair_kind") or "") == "operational"
    if operational_kind:
        payload_path = SELF_REPAIR_HISTORY_DIR / f"self_repair_operational-{stamp}.json"
        latest_payload_path = SELF_REPAIR_DIR / "latest_operational_repair_payload.json"
        plan["operational_repair_payload_path"] = str(payload_path)
        plan["latest_operational_repair_payload_path"] = str(latest_payload_path)
    else:
        payload_path = SELF_REPAIR_HISTORY_DIR / f"self_repair_code_patch-{stamp}.json"
        latest_payload_path = SELF_REPAIR_DIR / "latest_code_patch_payload.json"
        plan["code_patch_payload_path"] = str(payload_path)
        plan["latest_code_patch_payload_path"] = str(latest_payload_path)
    plan["artifact_path"] = str(plan_path)
    plan["latest_path"] = str(SELF_REPAIR_LATEST_PATH)
    update_self_repair_plan_commands_with_payload_path(plan, payload_path)
    update_self_repair_plan_payload_with_payload_path(plan, payload_path)
    if operational_kind:
        payload = plan.get("operational_repair_plan") if isinstance(plan.get("operational_repair_plan"), dict) else {}
    else:
        payload = plan.get("code_patch_payload") if isinstance(plan.get("code_patch_payload"), dict) else {}
    eve_store.write_json_dict(payload_path, payload, indent=2, sort_keys=False)
    eve_store.write_json_dict(latest_payload_path, payload, indent=2, sort_keys=False)
    eve_store.write_json_dict(plan_path, plan, indent=2, sort_keys=False)
    eve_store.write_json_dict(SELF_REPAIR_LATEST_PATH, plan, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(payload_path)
    mirror_store_file_to_runtime(latest_payload_path)
    mirror_store_file_to_runtime(plan_path)
    mirror_store_file_to_runtime(SELF_REPAIR_LATEST_PATH)
    return plan


def queue_self_repair_code_patch_proposal(plan: Dict[str, object]) -> Dict[str, object]:
    reviewed = plan.get("reviewed_code_patch_proposal") if isinstance(plan.get("reviewed_code_patch_proposal"), dict) else {}
    if not reviewed:
        raise ValueError("Operational self-repair plans are not queued as CodePatchProposal records; run the listed OperationalRepairPlan commands after preflight.")
    saved = append_governance_proposal(dict(reviewed))
    mirror_store_file_to_runtime(GOVERNANCE_PROPOSALS_PATH)
    report = eve_governance.watcher_report([saved])
    result = {
        "schema_version": "eve_self_repair_queue_result.v1",
        "stored": True,
        "proposal_id": saved.get("id"),
        "review_status": saved.get("review_status"),
        "approval_status": governance_proposal_approval_status(saved),
        "canary_status": governance_proposal_canary_status(saved),
        "watchers": report,
        "next_command": f"python3 eve.py governance code-lifecycle {saved.get('id')} --full",
    }
    plan["queue_result"] = result
    plan["code_lifecycle"] = governance_code_patch_lifecycle_plan(saved, stored=True)
    return result


def create_self_repair_codex_handoff(plan: Dict[str, object], *, diagnosis_only: bool = False) -> Dict[str, object]:
    config = dict(load_config())
    objective = normalize_text_value(plan.get("objective"), fallback="Perform a bounded Eve self-repair.", limit=900)
    artifact_path = normalize_text_value(plan.get("artifact_path"), fallback="", limit=400)
    repair_kind = normalize_text_value(plan.get("repair_kind"), fallback="code_patch", limit=80)
    payload_path = normalize_text_value(
        plan.get("operational_repair_payload_path") or plan.get("code_patch_payload_path"),
        fallback="",
        limit=400,
    )
    config["_codex_handoff_subject"] = "Eve self-repair handoff"
    config["_codex_handoff_objective"] = (
        f"Use the Eve self-repair plan to diagnose, patch, and verify this bounded objective: {objective}"
    )
    config["_codex_handoff_repository"] = str(ROOT)
    config["_codex_handoff_mode"] = "diagnosis_only" if diagnosis_only else "patch_and_verify"
    config["_codex_handoff_acceptance"] = (
        "Return changed files, commands/tests run, artifact paths, verification results, residual risks, "
        f"and whether the {('OperationalRepairPlan' if repair_kind == 'operational' else 'CodePatchProposal')} should be executed, queued, rejected, or revised. "
        f"Self-repair artifact: {artifact_path or 'not saved'}. "
        f"Repair payload: {payload_path or 'not saved'}."
    )
    config["_codex_handoff_constraints"] = (
        "Keep Codex separate from Eve. Do not use secrets, credentials, destructive commands, external sends, "
        "or unrelated rewrites. Do not deploy code or change live routing. Preserve the five Eve lanes and return "
        "evidence that can enter governance only as a CodePatchProposal, OperationalRepairPlan, or verification artifact."
    )
    result = run_operational_action_tree(
        "codex_independent_handoff",
        config,
        source="self_repair_plan",
    )
    plan["codex_handoff_result"] = result
    return result


def format_self_repair_plan(plan: Dict[str, object], *, full: bool = False) -> str:
    readiness = plan.get("readiness") if isinstance(plan.get("readiness"), dict) else {}
    lifecycle = plan.get("code_lifecycle") if isinstance(plan.get("code_lifecycle"), dict) else {}
    operational_lifecycle = plan.get("operational_lifecycle") if isinstance(plan.get("operational_lifecycle"), dict) else {}
    reviewed = plan.get("reviewed_code_patch_proposal") if isinstance(plan.get("reviewed_code_patch_proposal"), dict) else {}
    review = reviewed.get("review") if isinstance(reviewed.get("review"), dict) else {}
    repair_kind = str(plan.get("repair_kind") or "code_patch")
    lines = [
        f"Eve self-repair plan: status={plan.get('status') or 'unknown'}",
        f"objective: {plan.get('objective') or ''}",
        f"repair_kind: {repair_kind}",
        "boundary: proposal-only, no deployment, no live routing change, no sixth lane",
    ]
    if repair_kind == "operational":
        lines.append("proposal_review: not_applicable")
        lines.append(f"operational_lifecycle: {operational_lifecycle.get('status') or 'unknown'}")
    else:
        lines.append(f"proposal_review: {review.get('decision') or reviewed.get('review_status') or 'unknown'}")
        lines.append(f"code_lifecycle: {lifecycle.get('status') or 'unknown'}")
    if plan.get("artifact_path"):
        lines.append(f"artifact: {plan.get('artifact_path')}")
    if plan.get("code_patch_payload_path"):
        lines.append(f"code_patch_payload: {plan.get('code_patch_payload_path')}")
    if plan.get("operational_repair_payload_path"):
        lines.append(f"operational_repair_payload: {plan.get('operational_repair_payload_path')}")
    blockers = readiness.get("blockers") if isinstance(readiness.get("blockers"), list) else []
    cautions = readiness.get("cautions") if isinstance(readiness.get("cautions"), list) else []
    if blockers:
        lines.append("blockers: " + ", ".join(str(item) for item in blockers))
    if cautions:
        lines.append("cautions: " + ", ".join(str(item) for item in cautions))
    if plan.get("queue_result"):
        queue = plan.get("queue_result") if isinstance(plan.get("queue_result"), dict) else {}
        lines.append(f"queued_proposal: {queue.get('proposal_id')} | next: {queue.get('next_command')}")
    if plan.get("codex_handoff_result"):
        handoff = plan.get("codex_handoff_result") if isinstance(plan.get("codex_handoff_result"), dict) else {}
        lines.append(f"codex_handoff: ok={bool(handoff.get('ok'))} message_id={handoff.get('message_id') or '-'}")
    if full:
        commands = plan.get("commands") if isinstance(plan.get("commands"), dict) else {}
        lines.append("commands:")
        for key, command in commands.items():
            lines.append(f"- {key}: {command}")
        active_lifecycle = operational_lifecycle if repair_kind == "operational" else lifecycle
        next_steps = active_lifecycle.get("next_steps") if isinstance(active_lifecycle.get("next_steps"), list) else []
        if next_steps:
            lines.append("lifecycle_next_steps:")
            for item in next_steps:
                lines.append(f"- {item}")
    return "\n".join(lines)


def coder_tool_specs() -> List[Dict[str, str]]:
    return [
        {
            "name": "run_command",
            "description": "Run a bounded, non-destructive shell command from Eve's workspace root.",
            "args": '{"command":"python3 -m py_compile eve.py","timeout_seconds":60}',
        },
        {
            "name": "run_tests",
            "description": "Run a verification command such as py_compile or unittest.",
            "args": '{"command":"python3 -m unittest tests.test_self_awareness","timeout_seconds":120}',
        },
        {
            "name": "git_status",
            "description": "Show concise git status for the workspace.",
            "args": '{}',
        },
        {
            "name": "git_diff",
            "description": "Show the current git diff, optionally scoped to a path.",
            "args": '{"path":"eve.py"}',
        },
        {
            "name": "list_dir",
            "description": "List files or folders at a path.",
            "args": '{"path":".","limit":40}',
        },
        {
            "name": "read_file",
            "description": "Read a text file, optionally with line bounds.",
            "args": '{"path":"eve.py","start_line":1,"end_line":80}',
        },
        {
            "name": "search_text",
            "description": "Search the workspace with ripgrep.",
            "args": '{"pattern":"def cmd_chat","path":"eve.py"}',
        },
        {
            "name": "apply_patch",
            "description": "Apply a unified git diff inside the Eve workspace. This is the only coder-mode file edit tool.",
            "args": '{"patch":"diff --git a/example.txt b/example.txt\\nnew file mode 100644\\nindex 0000000..1269488\\n--- /dev/null\\n+++ b/example.txt\\n@@ -0,0 +1 @@\\n+hello\\n"}',
        },
    ]


def format_coder_tool_specs() -> str:
    return "\n".join(
        f"- {spec['name']}: {spec['description']} Example args: {spec['args']}"
        for spec in coder_tool_specs()
    )


def coder_workspace_root(config: Optional[Dict[str, object]] = None) -> Path:
    effective_config = config or {}
    raw_root = normalize_text_value(effective_config.get("code_workspace_root"), fallback="", limit=1000)
    if raw_root:
        candidate = Path(raw_root).expanduser()
        if candidate.exists() and candidate.is_dir():
            return candidate.resolve()
    return ROOT.resolve()


def coder_tool_config(config: Dict[str, object]) -> Dict[str, object]:
    tool_config = dict(config)
    tool_config["_tool_workspace_root"] = str(coder_workspace_root(config))
    return tool_config


def build_coder_tool_capability_message(config: Optional[Dict[str, object]] = None) -> str:
    workspace_root = coder_workspace_root(config)
    return textwrap.dedent(
        f"""
        Eve Coder Mode has a bounded code-operation surface rooted at:
        {workspace_root}

        Available coder tools:
        {format_coder_tool_specs()}

        Execution boundaries:
        - Inspect before editing.
        - Edit only through apply_patch unified diffs.
        - Run verification after any successful apply_patch before calling work complete.
        - Do not use destructive shell commands, package installs, git history changes, or files outside this workspace.
        - If a requested action needs a blocked capability, explain the missing approval/capability instead of pretending.
        """
    ).strip()


def normalize_git_diff_path(raw_path: object) -> str:
    text = str(raw_path or "").strip().split("\t", 1)[0]
    if text in {"", "/dev/null"}:
        return ""
    if text.startswith("a/") or text.startswith("b/"):
        text = text[2:]
    return text.strip()


def coder_workspace_path_problem(raw_path: object, config: Optional[Dict[str, object]] = None) -> str:
    text = normalize_git_diff_path(raw_path)
    if not text:
        return ""
    candidate = Path(text)
    if candidate.is_absolute():
        return f"absolute paths are not allowed in coder patches: {text}"
    if any(part in {"..", ".git"} for part in candidate.parts):
        return f"path escapes or touches git internals: {text}"
    if candidate.parts and candidate.parts[0] == ".eve":
        return f"coder patches may not edit Eve runtime state under .eve: {text}"
    try:
        resolved_root = coder_workspace_root(config)
        resolved = (resolved_root / candidate).resolve()
        resolved.relative_to(resolved_root)
    except (OSError, ValueError):
        return f"path is outside the Eve workspace: {text}"
    return ""


def coder_patch_paths(patch_text: object) -> List[str]:
    paths: List[str] = []
    for line in str(patch_text or "").splitlines():
        if line.startswith("diff --git "):
            parts = line.split()
            for raw in parts[2:4]:
                normalized = normalize_git_diff_path(raw)
                if normalized:
                    paths.append(normalized)
            continue
        if line.startswith("--- ") or line.startswith("+++ "):
            normalized = normalize_git_diff_path(line[4:])
            if normalized:
                paths.append(normalized)
    return unique_compact(paths, limit=80)


def validate_coder_patch(patch_text: object, config: Dict[str, object]) -> Tuple[bool, str, List[str]]:
    text = str(patch_text or "")
    if not text.strip():
        return False, "Patch is empty.", []
    max_bytes = int(config.get("code_patch_max_bytes") or DEFAULT_CONFIG["code_patch_max_bytes"])
    if len(text.encode("utf-8")) > max_bytes:
        return False, f"Patch is too large for coder mode ({max_bytes} byte limit).", []
    paths = coder_patch_paths(text)
    if not paths:
        return False, "Patch did not include any recognizable file paths.", []
    problems = [coder_workspace_path_problem(path, config) for path in paths]
    problems = [problem for problem in problems if problem]
    if problems:
        return False, "; ".join(problems), paths
    return True, "", paths


def coder_command_block_reason(command: object) -> str:
    text = str(command or "").strip()
    if not text:
        return "Command is empty."
    for pattern, reason in CODER_BLOCKED_COMMAND_PATTERNS:
        if re.search(pattern, text, flags=re.IGNORECASE):
            return reason
    for pattern, reason in CODER_PROTECTED_PATH_PATTERNS:
        if re.search(pattern, text, flags=re.IGNORECASE):
            return f"{reason} Use a narrow approved capability instead of coder-mode shell access."
    return ""


def run_coder_shell_command(command: str, config: Dict[str, object], *, timeout_seconds: Optional[int] = None) -> Dict[str, object]:
    workspace_root = coder_workspace_root(config)
    blocked_reason = coder_command_block_reason(command)
    if blocked_reason:
        return {
            "ok": False,
            "blocked": True,
            "command": command,
            "cwd": str(workspace_root),
            "error": blocked_reason,
        }
    timeout = clamp_int(
        timeout_seconds,
        int(config.get("code_command_timeout_seconds") or DEFAULT_CONFIG["code_command_timeout_seconds"]),
        minimum=1,
        maximum=600,
    )
    output_limit = int(config.get("code_output_max_chars") or DEFAULT_CONFIG["code_output_max_chars"])
    try:
        result = subprocess.run(
            ["/bin/zsh", "-lc", command],
            check=False,
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=workspace_root,
        )
    except subprocess.TimeoutExpired:
        return {
            "ok": False,
            "blocked": False,
            "command": command,
            "cwd": str(workspace_root),
            "timeout_seconds": timeout,
            "error": "Command timed out.",
        }
    return {
        "ok": result.returncode == 0,
        "blocked": False,
        "command": command,
        "cwd": str(workspace_root),
        "timeout_seconds": timeout,
        "exit_code": result.returncode,
        "stdout": truncate_text(result.stdout, output_limit),
        "stderr": truncate_text(result.stderr, output_limit),
    }


def execute_coder_apply_patch_tool(args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    patch_text = str(args.get("patch") or "")
    valid, problem, paths = validate_coder_patch(patch_text, config)
    if not valid:
        return {"ok": False, "blocked": True, "error": problem, "paths": paths}

    workspace_root = coder_workspace_root(config)
    output_limit = int(config.get("code_output_max_chars") or DEFAULT_CONFIG["code_output_max_chars"])
    check = subprocess.run(
        ["git", "apply", "--check", "--whitespace=nowarn"],
        input=patch_text,
        check=False,
        capture_output=True,
        text=True,
        timeout=60,
        cwd=workspace_root,
    )
    if check.returncode != 0:
        return {
            "ok": False,
            "blocked": False,
            "checked": False,
            "paths": paths,
            "error": "git apply --check failed.",
            "stdout": truncate_text(check.stdout, output_limit),
            "stderr": truncate_text(check.stderr, output_limit),
        }
    applied = subprocess.run(
        ["git", "apply", "--whitespace=nowarn"],
        input=patch_text,
        check=False,
        capture_output=True,
        text=True,
        timeout=60,
        cwd=workspace_root,
    )
    return {
        "ok": applied.returncode == 0,
        "blocked": False,
        "checked": True,
        "paths": paths,
        "exit_code": applied.returncode,
        "stdout": truncate_text(applied.stdout, output_limit),
        "stderr": truncate_text(applied.stderr, output_limit),
    }


def execute_coder_tool(tool_name: str, args: Dict[str, object], config: Dict[str, object]) -> Dict[str, object]:
    tool_config = coder_tool_config(config)
    if tool_name == "run_command":
        return run_coder_shell_command(
            str(args.get("command") or ""),
            config,
            timeout_seconds=clamp_int(args.get("timeout_seconds"), int(config.get("code_command_timeout_seconds") or 120), minimum=1, maximum=600),
        )
    if tool_name == "run_tests":
        return run_coder_shell_command(
            str(args.get("command") or "python3 -m unittest"),
            config,
            timeout_seconds=clamp_int(args.get("timeout_seconds"), 180, minimum=1, maximum=900),
        )
    if tool_name == "git_status":
        return run_coder_shell_command("git status --short", config, timeout_seconds=30)
    if tool_name == "git_diff":
        path_arg = normalize_git_diff_path(args.get("path") or "")
        path_problem = coder_workspace_path_problem(path_arg, config) if path_arg else ""
        if path_problem:
            return {"ok": False, "blocked": True, "error": path_problem}
        command = "git diff -- " + shlex.quote(path_arg) if path_arg else "git diff --"
        return run_coder_shell_command(command, config, timeout_seconds=60)
    if tool_name == "list_dir":
        return execute_list_dir_tool(args, tool_config)
    if tool_name == "read_file":
        return execute_read_file_tool(args, tool_config)
    if tool_name == "search_text":
        return execute_search_text_tool(args, tool_config)
    if tool_name == "apply_patch":
        if parse_boolish(config.get("_coder_disable_apply_patch")):
            return {
                "ok": False,
                "blocked": True,
                "error": "apply_patch is disabled for this coder-mode run.",
            }
        return execute_coder_apply_patch_tool(args, config)
    return {"ok": False, "error": f"Unknown coder tool `{tool_name}`."}


def build_coder_tool_result_message(tool_name: str, result: Dict[str, object]) -> str:
    return textwrap.dedent(
        f"""
        Coder tool result for `{tool_name}`:
        {json.dumps(result, ensure_ascii=True, indent=2)}

        Continue from this evidence. Return JSON only.
        If more inspection/editing/verification is needed, return {{"type":"tool_call","tool":"<name>","args":{{...}}}}.
        If finished, return {{"type":"final","message":"<concise answer with changed files and verification>"}}.
        """
    ).strip()


def build_coder_context_message(session_id: str, user_request: str, config: Optional[Dict[str, object]] = None) -> str:
    effective_config = config or load_config()
    git_status = run_coder_shell_command("git status --short", effective_config, timeout_seconds=30)
    previous_events = read_code_session_events(session_id, limit=10)
    previous_summary = "\n".join(
        "- "
        + normalize_text_value(
            event.get("response")
            or event.get("request")
            or f"{event.get('tool')}: {event.get('type')}",
            fallback=str(event.get("type") or "event"),
            limit=220,
        )
        for event in previous_events
    )
    return textwrap.dedent(
        f"""
        Coder session: {session_id}
        User request:
        {user_request}

        Recent session events:
        {previous_summary or "- No prior events in this coder session."}

        Current git status:
        {git_status.get('stdout') or git_status.get('stderr') or 'No git status output.'}
        """
    ).strip()


def run_eve_coder_agent(
    config: Dict[str, object],
    user_request: str,
    *,
    session_id: str,
    model_override: Optional[str] = None,
    max_tokens: Optional[int] = None,
    require_tool_use: bool = True,
    required_tools: Optional[List[str]] = None,
    required_tool_groups: Optional[List[List[str]]] = None,
) -> Dict[str, object]:
    model = resolve_model(config, "code", explicit_model=model_override)
    request_timeout = int(config.get("code_timeout_seconds") or DEFAULT_CONFIG["code_timeout_seconds"])
    max_steps = int(config.get("code_tool_max_steps") or DEFAULT_CONFIG["code_tool_max_steps"])
    token_budget = max_tokens or int(config.get("code_max_tokens") or DEFAULT_CONFIG["code_max_tokens"])
    messages = [
        *build_eve_identity_system_messages(include_human_context=True, include_active_mind=True, compact=True),
        {"role": "system", "content": load_prompt("code_mode.md")},
        {"role": "system", "content": build_coder_tool_capability_message(config)},
        {"role": "user", "content": build_coder_context_message(session_id, user_request, config)},
    ]
    tool_calls: List[Dict[str, object]] = []
    correction_count = 0
    required_tools = [tool for tool in (required_tools or []) if tool]
    required_tool_groups = [[tool for tool in group if tool] for group in (required_tool_groups or []) if group]
    max_protocol_repairs = max(2, len(required_tools) + len(required_tool_groups) + 2)

    append_code_session_event(
        session_id,
        "user_request",
        {"request": user_request, "model": model, "require_tool_use": require_tool_use},
    )

    for step_index in range(max_steps):
        raw = model_chat(
            config,
            model,
            messages,
            max_tokens=token_budget,
            think_level=str(config["think_level"]),
            operation="code_tool_loop",
            timeout_seconds=request_timeout,
        )
        parsed = parse_agent_response(raw)
        if parsed is None:
            correction_count += 1
            append_code_session_event(
                session_id,
                "protocol_repair",
                {"step": step_index, "raw": truncate_text(raw, 1200), "correction_count": correction_count},
            )
            if not require_tool_use and not tool_calls:
                return {"response": raw, "model": model, "tool_calls": tool_calls, "session_id": session_id}
            if correction_count > max_protocol_repairs:
                raise SystemExit("Eve Coder Mode did not follow the JSON tool protocol.")
            messages.append({"role": "assistant", "content": raw})
            messages.append(
                {
                    "role": "system",
                    "content": (
                        "Return JSON only. Use "
                        '{"type":"tool_call","tool":"<name>","args":{...}} '
                        'or {"type":"final","message":"<answer>"} when finished.'
                    ),
                }
            )
            continue

        correction_count = 0
        if parsed["type"] == "final":
            final_message = str(parsed.get("message") or "").strip()
            used_tools = {str(call.get("tool") or "") for call in tool_calls if isinstance(call, dict)}
            if require_tool_use and not tool_calls:
                correction_count += 1
                append_code_session_event(
                    session_id,
                    "protocol_repair",
                    {
                        "step": step_index,
                        "raw": truncate_text(final_message, 1200),
                        "correction_count": correction_count,
                        "reason": "final_without_required_tool",
                    },
                )
                if correction_count > max_protocol_repairs:
                    raise SystemExit("Eve Coder Mode finished without using any tools.")
                messages.append({"role": "assistant", "content": raw})
                messages.append(
                    {
                        "role": "system",
                        "content": (
                            "You must use at least one coder tool before the final answer. "
                            "For this request, call the most relevant inspection tool now. "
                            'Return JSON only, for example {"type":"tool_call","tool":"git_status","args":{}}.'
                        ),
                    }
                )
                continue
            missing_required_tools = [tool for tool in required_tools if tool not in used_tools]
            missing_required_groups = [
                group for group in required_tool_groups if not any(tool in used_tools for tool in group)
            ]
            if missing_required_tools or missing_required_groups:
                correction_count += 1
                append_code_session_event(
                    session_id,
                    "protocol_repair",
                    {
                        "step": step_index,
                        "raw": truncate_text(final_message, 1200),
                        "correction_count": correction_count,
                        "reason": "final_before_required_tools",
                        "missing_required_tools": missing_required_tools,
                        "missing_required_groups": missing_required_groups,
                    },
                )
                if correction_count > max_protocol_repairs:
                    raise SystemExit(
                        "Eve Coder Mode finished before required tools were used: "
                        + ", ".join(missing_required_tools)
                    )
                group_text = "; ".join(" or ".join(group) for group in missing_required_groups)
                requirement_text = ", ".join(missing_required_tools)
                if group_text:
                    requirement_text = (requirement_text + "; " if requirement_text else "") + group_text
                next_tool = missing_required_tools[0] if missing_required_tools else missing_required_groups[0][0]
                messages.append({"role": "assistant", "content": raw})
                messages.append(
                    {
                        "role": "system",
                        "content": (
                            "You cannot finalize yet. Required coder tools are still missing: "
                            f"{requirement_text}. Call one missing required tool now. "
                            f'Return JSON only, for example {{"type":"tool_call","tool":"{next_tool}","args":{{}}}}.'
                        ),
                    }
                )
                continue
            successful_patch = any(
                call.get("tool") == "apply_patch"
                and isinstance(call.get("result"), dict)
                and bool(call["result"].get("ok"))
                for call in tool_calls
            )
            verification_used = any(call.get("tool") in {"run_tests", "run_command"} for call in tool_calls)
            if successful_patch and not verification_used:
                final_message = (
                    final_message.rstrip()
                    + "\n\nVerification note: I changed files, but no verification command is recorded in this session yet."
                )
            append_code_session_event(
                session_id,
                "final",
                {
                    "response": final_message,
                    "model": model,
                    "tool_count": len(tool_calls),
                    "tools_used": [str(call.get("tool") or "") for call in tool_calls],
                },
            )
            append_entry(
                "code_session_completed",
                normalize_text_value(final_message, fallback="Eve Coder Mode completed a session.", limit=260),
                metadata={
                    "session_id": session_id,
                    "model": model,
                    "tool_count": len(tool_calls),
                    "tools_used": [str(call.get("tool") or "") for call in tool_calls],
                    "successful_patch": successful_patch,
                    "verification_used": verification_used,
                },
            )
            return {"response": final_message, "model": model, "tool_calls": tool_calls, "session_id": session_id}

        tool_name = str(parsed.get("tool") or "").strip()
        args = parsed.get("args") if isinstance(parsed.get("args"), dict) else {}
        result = execute_coder_tool(tool_name, args, config)
        call_record = {"tool": tool_name, "args": args, "result": result}
        tool_calls.append(call_record)
        append_code_session_event(
            session_id,
            "tool_call",
            {
                "step": step_index,
                "tool": tool_name,
                "args": args,
                "result": result,
            },
        )
        messages.append({"role": "assistant", "content": raw})
        messages.append({"role": "system", "content": build_coder_tool_result_message(tool_name, result)})

    raise SystemExit("Eve Coder Mode hit the tool-use step limit before finishing.")


def build_capability_self_test_prompt(artifact_path: Path, artifact_content: str) -> str:
    try:
        artifact_reference = str(artifact_path.relative_to(ROOT))
    except ValueError:
        artifact_reference = str(artifact_path)
    return textwrap.dedent(
        f"""
        Use your tools to verify that your capabilities are actually working, not just described.

        Run these checks in order:
        1. Use `shell` to print the working directory and Python version.
        2. Use `list_dir` on the workspace root.
        3. Use `read_file` on `README.md`.
        4. Use `search_text` to find `def cmd_chat` inside `eve.py`.
        5. Use `write_file` to create `{artifact_reference}` with this exact content:
           {artifact_content}
        6. Use `read_file` to read `{artifact_reference}` back and confirm the contents match.
        7. Use `fetch_url` on `https://example.com`.

        After the checks are complete, return a concise final report that names each capability, whether it worked, and one piece of evidence.
        """
    ).strip()


def capability_test_problems(
    tool_calls: List[Dict[str, object]],
    artifact_path: Path,
    artifact_content: str,
) -> List[str]:
    problems: List[str] = []
    required_tools = {"shell", "list_dir", "read_file", "write_file", "search_text", "fetch_url", "web_search"}
    used_tools = {str(call.get("tool")) for call in tool_calls}
    missing = sorted(required_tools - used_tools)
    if missing:
        problems.append("Missing tool runs: " + ", ".join(missing))

    shell_ok = any(
        str(ROOT) in str(call.get("result", {}).get("stdout", ""))
        for call in tool_calls
        if str(call.get("tool")) == "shell"
    )
    if not shell_ok:
        problems.append("Shell test did not confirm the Eve workspace root.")

    readme_ok = any(
        Path(str(call.get("args", {}).get("path", ""))).name == "README.md"
        and bool(call.get("result", {}).get("content"))
        for call in tool_calls
        if str(call.get("tool")) == "read_file"
    )
    if not readme_ok:
        problems.append("README.md was not successfully read.")

    search_ok = any(
        "def cmd_chat" in "\n".join(call.get("result", {}).get("matches", []))
        for call in tool_calls
        if str(call.get("tool")) == "search_text"
    )
    if not search_ok:
        problems.append("Code search did not find `def cmd_chat` in eve.py.")

    if not artifact_path.exists():
        problems.append(f"Self-test artifact was not created at {artifact_path}.")
    else:
        actual = artifact_path.read_text(encoding="utf-8")
        if actual != artifact_content:
            problems.append("Self-test artifact contents did not match the expected text.")

    read_back_ok = any(
        Path(str(call.get("args", {}).get("path", ""))).name == artifact_path.name
        and artifact_content in str(call.get("result", {}).get("content", ""))
        for call in tool_calls
        if str(call.get("tool")) == "read_file"
    )
    if not read_back_ok:
        problems.append("The artifact file was not read back successfully.")

    fetch_ok = any(
        "Example Domain" in str(call.get("result", {}).get("title", ""))
        or "Example Domain" in str(call.get("result", {}).get("preview", ""))
        for call in tool_calls
        if str(call.get("tool")) == "fetch_url"
    )
    if not fetch_ok:
        problems.append("Web fetch did not return the expected Example Domain content.")

    return problems


