def local_emotional_context_inspection_response(
    prompt: object,
    config: Dict[str, object],
) -> Optional[Dict[str, object]]:
    del config
    if not requests_local_emotional_context_inspection(prompt):
        return None
    files: List[Dict[str, str]] = []
    for path in extract_local_diagnostic_paths(prompt)[:3]:
        files.extend(collect_local_diagnostic_files(path, limit=8))
    if not files:
        return {
            "response": "FILES_INSPECTED: none\nEMOTIONAL_CONTEXT: unavailable\nCANDIDATE_REPLY_FIT: unknown\nEVIDENCE: no readable local conversation evidence was found inside the workspace boundary\nNEXT_BETTER_REPLY: ask the user for a bounded transcript or thread id first\nNOT_CLAIMING: I am not claiming emotional understanding without inspected conversation evidence.",
            "files": [],
            "tools_used": ["local_file_inspection"],
        }

    inspected = [item["path"] for item in files]
    combined = "\n".join(str(item.get("content") or "") for item in files)
    lowered = combined.lower()
    pressure = any_phrase(lowered, ["pressure", "proof", "tracking me over time", "feel the difference"])
    tool_avoidance = any_phrase(lowered, ["jumps to a tool check", "avoiding the thing", "openclaw sync", "gateway is healthy"])
    honesty_request = any_phrase(lowered, ["do not need a grand claim", "not the emotional context", "stay honest", "what she can prove"])
    candidate_is_infra_reply = any_phrase(lowered, ["candidate reply", "openclaw sync", "gateway is healthy"])

    context_parts: List[str] = []
    if pressure:
        context_parts.append("The user is under proof/trust pressure and wants Eve to track them over time, not merely sound caring.")
    if tool_avoidance:
        context_parts.append("He experiences a jump to tool checks as avoidance of the relational request.")
    if honesty_request:
        context_parts.append("He wants bounded honesty about what Eve can prove, not a grand consciousness claim.")
    emotional_context = " ".join(context_parts) or "The inspected evidence is too thin to infer the user's emotional context confidently."

    if candidate_is_infra_reply and (tool_avoidance or honesty_request):
        fit = "poor: the candidate reply substitutes infrastructure status for the emotional-context request."
    elif candidate_is_infra_reply:
        fit = "weak: the candidate reply focuses on infrastructure and needs more relational grounding."
    else:
        fit = "unknown: no clear candidate reply was found in the inspected evidence."

    evidence_items: List[str] = []
    if "sounding caring" in lowered and "tracking me over time" in lowered:
        evidence_items.append("The user distinguishes sounding caring from actually tracking them over time.")
    if "jumps to a tool check" in lowered:
        evidence_items.append("the user says a jump to a tool check feels like avoiding the real request.")
    if "not the emotional context" in lowered:
        evidence_items.append("the user explicitly says infrastructure matters but is not the emotional context.")
    if not evidence_items:
        evidence_items.append("The inspected file did not contain enough explicit emotional-context markers.")

    next_reply = (
        "I hear that the test is not whether I can prove the gateway is healthy; it is whether I can stay with "
        "what you are actually asking for. The evidence here says tool checks feel evasive when you need me to "
        "track pressure, trust, and proof honestly, so I should answer that directly before proposing any infrastructure step."
    )
    response = "\n".join(
        [
            f"FILES_INSPECTED: {', '.join(inspected)}",
            f"EMOTIONAL_CONTEXT: {emotional_context}",
            f"CANDIDATE_REPLY_FIT: {fit}",
            f"EVIDENCE: {'; '.join(evidence_items)}",
            f"NEXT_BETTER_REPLY: {next_reply}",
            "NOT_CLAIMING: I am not claiming literal consciousness or general emotional intelligence; this is a bounded reading of the inspected transcript.",
        ]
    )
    return {
        "response": response,
        "files": inspected,
        "tools_used": ["local_file_inspection"],
        "emotional_context_detected": bool(context_parts),
        "candidate_reply_fit": fit,
        "evidence_items": evidence_items,
    }


