BOUNDED_EMOTIONAL_CONTEXT_LESSON = (
    "The user's proof/tool-check emotional-context lesson: tool checks can feel evasive when they are asking Eve for "
    "relational tracking; substituting infrastructure or gateway proof for an emotional-context request misses the "
    "point; use proof through sustained tracking over time."
)

BOUNDED_EMOTIONAL_CONTEXT_PRACTICE = (
    "When the user asks whether Eve is tracking them, answer the relational pressure first; use tool checks only when "
    "they are the relevant proof surface."
)


def durable_emotional_context_text(human_context: Dict[str, object]) -> str:
    normalized = normalize_human_context(human_context)
    relationship = normalized["relationship_memory"]
    self_model = normalized["self_model"]
    return " ".join(
        str(item or "")
        for item in [
            relationship.get("user_overview"),
            *relationship.get("what_user_seems_to_value", []),
            *relationship.get("communication_preferences", []),
            *relationship.get("requested_practices", []),
            *relationship.get("care_notes", []),
            *self_model.get("current_preoccupations", []),
            *self_model.get("growth_edges", []),
        ]
    ).lower()


def human_context_contains_bounded_emotional_lesson(human_context: Dict[str, object]) -> bool:
    text = durable_emotional_context_text(human_context)
    return any_phrase(
        text,
        [
            "tool checks can feel evasive",
            "tool checks as avoidance",
            "substituting infrastructure",
            "proof through sustained tracking",
            "proof/trust pressure",
            "not caring-sounding language",
            "emotional-context request",
        ],
    )


def load_human_context_candidates(prefer_runtime: bool) -> List[Tuple[str, Dict[str, object]]]:
    primary_label = "human_context(runtime-preferred)" if prefer_runtime else "human_context"
    primary = load_human_context(prefer_runtime=prefer_runtime)
    candidates: List[Tuple[str, Dict[str, object]]] = [(primary_label, primary)]
    if prefer_runtime:
        source = load_human_context(prefer_runtime=False)
        if normalize_human_context(source) != normalize_human_context(primary):
            candidates.append(("human_context(source)", source))
    return candidates


