def route_contract_match_config(contract: Dict[str, object]) -> Dict[str, object]:
    match = contract.get("match")
    if isinstance(match, dict):
        return match
    return contract


ROUTE_CONTRACT_PREDICATES = {
    "current_inner_state",
    "existential_question",
    "live_status_request",
    "diagnostic_request",
    "bounded_action_choice",
    "action_request",
    "humanity_question",
    "capability_question",
}


def normalize_route_contract(raw: Dict[str, object], *, source: str) -> Dict[str, object]:
    contract = dict(raw)
    match = route_contract_match_config(contract)
    normalized_match: Dict[str, object] = {}
    for key in ("exact", "contains_all", "contains_any"):
        values = match.get(key)
        if values is None:
            continue
        if not isinstance(values, list) and not isinstance(values, tuple):
            raise ValueError(f"Route contract {contract.get('kind') or '<unknown>'} has non-list {key}.")
        normalized_match[key] = [str(item) for item in values if str(item).strip()]
    predicate = match.get("predicate")
    if predicate is not None:
        predicate_text = str(predicate).strip()
        if predicate_text not in ROUTE_CONTRACT_PREDICATES:
            raise ValueError(
                f"Route contract {contract.get('kind') or '<unknown>'} uses unknown predicate `{predicate_text}`."
            )
        normalized_match["predicate"] = predicate_text
    contract["match"] = normalized_match
    contract["signal_id"] = str(contract.get("signal_id") or contract.get("kind") or "").strip()
    contract["kind"] = str(contract.get("kind") or "").strip()
    contract["budget"] = str(contract.get("budget") or "reflex").strip()
    contract["lanes"] = [str(item) for item in (contract.get("lanes") or []) if str(item).strip()]
    contract["organs"] = [str(item) for item in (contract.get("organs") or []) if str(item).strip()]
    contract["evidence_policy"] = str(contract.get("evidence_policy") or "").strip()
    contract["action_class"] = str(contract.get("action_class") or "none").strip()
    contract["response"] = str(contract.get("response") or "")
    response_mode = str(contract.get("response_mode") or "").strip()
    if not response_mode:
        response_mode = "static" if contract["response"].strip() else "runtime_handler"
    contract["response_mode"] = response_mode
    contract["delegates_to"] = str(contract.get("delegates_to") or "").strip()
    contract["requires_current_tool_evidence"] = bool(contract.get("requires_current_tool_evidence"))
    contract["must_record_replay"] = bool(contract.get("must_record_replay"))
    contract["anti_contract_ids"] = [
        str(item) for item in (contract.get("anti_contract_ids") or []) if str(item).strip()
    ]
    contract["commitment_summary"] = str(contract.get("commitment_summary") or "")
    contract["source"] = source
    required = ["kind", "budget", "evidence_policy", "response_mode", "commitment_summary"]
    missing = [field for field in required if not contract.get(field)]
    if missing:
        raise ValueError(f"Route contract missing required field(s): {', '.join(missing)}")
    if contract["response_mode"] == "static" and not contract["response"].strip():
        raise ValueError(f"Route contract {contract['kind']} is static but has no response.")
    if contract["response_mode"] != "static" and not contract["delegates_to"]:
        raise ValueError(f"Route contract {contract['kind']} is non-static but has no delegates_to.")
    if not normalized_match:
        raise ValueError(f"Route contract {contract['kind']} has no match rule.")
    return contract


def route_contract_source_label(path: Path) -> str:
    try:
        return str(path.relative_to(ROOT))
    except ValueError:
        return str(path)


def default_conversation_intent_contract_document() -> Dict[str, object]:
    return {
        "schema_version": "eve_route_contracts.v1",
        "owner": "eve_executive_scheduler",
        "principle": "Fallback built-in route contracts used only if docs/routing/route_contracts.json is absent.",
        "contracts": [dict(item) for item in DEFAULT_CONVERSATION_INTENT_CONTRACTS],
    }


def load_conversation_intent_contract_document(path: Path = ROUTE_CONTRACTS_PATH) -> Dict[str, object]:
    if not path.exists():
        return default_conversation_intent_contract_document()
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        document = default_conversation_intent_contract_document()
        return {
            **document,
            "path": str(path),
            "source_error": normalize_text_value(exc, fallback="unreadable route contract document", limit=240),
        }
    except json.JSONDecodeError as exc:
        raise SystemExit(f"Invalid Eve route contract JSON at {path}: {exc}")
    if not isinstance(payload, dict):
        raise SystemExit(f"Invalid Eve route contract document at {path}: expected object.")
    contracts = payload.get("contracts")
    if not isinstance(contracts, list):
        raise SystemExit(f"Invalid Eve route contract document at {path}: missing contracts list.")
    normalized: List[Dict[str, object]] = []
    seen: Set[str] = set()
    for raw in contracts:
        if not isinstance(raw, dict):
            raise SystemExit(f"Invalid Eve route contract document at {path}: contract entries must be objects.")
        try:
            contract = normalize_route_contract(raw, source=route_contract_source_label(path))
        except ValueError as exc:
            raise SystemExit(f"Invalid Eve route contract document at {path}: {exc}")
        kind = str(contract.get("kind") or "")
        if kind in seen:
            raise SystemExit(f"Invalid Eve route contract document at {path}: duplicate kind `{kind}`.")
        seen.add(kind)
        normalized.append(contract)
    return {**payload, "contracts": normalized, "path": str(path)}


def load_route_signal_document(path: Path = ROUTE_SIGNALS_PATH) -> Dict[str, object]:
    if not path.exists():
        return {"schema_version": "eve_routing_signals.v1", "signals": [], "path": str(path)}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        return {
            "schema_version": "eve_routing_signals.v1",
            "signals": [],
            "path": str(path),
            "source_error": normalize_text_value(exc, fallback="unreadable route signal document", limit=240),
        }
    except json.JSONDecodeError as exc:
        raise SystemExit(f"Invalid Eve routing signal JSON at {path}: {exc}")
    if not isinstance(payload, dict):
        raise SystemExit(f"Invalid Eve routing signal document at {path}: expected object.")
    signals = payload.get("signals")
    if not isinstance(signals, list):
        raise SystemExit(f"Invalid Eve routing signal document at {path}: missing signals list.")
    return {**payload, "path": str(path)}


def load_route_anti_contract_document(path: Path = ROUTE_ANTI_CONTRACTS_PATH) -> Dict[str, object]:
    if not path.exists():
        return {"schema_version": "eve_route_anti_contracts.v1", "anti_contracts": [], "path": str(path)}
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        return {
            "schema_version": "eve_route_anti_contracts.v1",
            "anti_contracts": [],
            "path": str(path),
            "source_error": normalize_text_value(exc, fallback="unreadable route anti-contract document", limit=240),
        }
    except json.JSONDecodeError as exc:
        raise SystemExit(f"Invalid Eve route anti-contract JSON at {path}: {exc}")
    if not isinstance(payload, dict):
        raise SystemExit(f"Invalid Eve route anti-contract document at {path}: expected object.")
    anti_contracts = payload.get("anti_contracts")
    if not isinstance(anti_contracts, list):
        raise SystemExit(f"Invalid Eve route anti-contract document at {path}: missing anti_contracts list.")
    return {**payload, "path": str(path)}


def route_signal_ids() -> Set[str]:
    document = load_route_signal_document()
    ids: Set[str] = set()
    for collection in (document.get("signals") or [], document.get("protocol_signals") or []):
        for signal in collection:
            if isinstance(signal, dict):
                signal_id = str(signal.get("id") or "").strip()
                if signal_id:
                    ids.add(signal_id)
    return ids


def route_anti_contracts_by_id() -> Dict[str, Dict[str, object]]:
    document = load_route_anti_contract_document()
    anti: Dict[str, Dict[str, object]] = {}
    for item in document.get("anti_contracts") or []:
        if isinstance(item, dict):
            anti_id = str(item.get("id") or "").strip()
            if anti_id:
                anti[anti_id] = item
    return anti


def validate_route_contract_references(
    contracts: Iterable[Dict[str, object]],
    cases: Iterable[Dict[str, object]],
) -> List[str]:
    signal_ids = route_signal_ids()
    anti_by_id = route_anti_contracts_by_id()
    errors: List[str] = []
    if signal_ids:
        for contract in contracts:
            signal_id = str(contract.get("signal_id") or contract.get("kind") or "").strip()
            if signal_id and signal_id not in signal_ids:
                errors.append(
                    f"contract `{contract.get('kind')}` references missing signal `{signal_id}`"
                )
    for contract in contracts:
        for anti_id in contract.get("anti_contract_ids") or []:
            if anti_id not in anti_by_id:
                errors.append(
                    f"contract `{contract.get('kind')}` references missing anti-contract `{anti_id}`"
                )
    covered_anti_ids: Set[str] = set()
    for case in cases:
        for anti_id in case.get("covers_anti_contracts") or []:
            anti_id_text = str(anti_id).strip()
            if anti_id_text:
                covered_anti_ids.add(anti_id_text)
    for anti_id, anti in sorted(anti_by_id.items()):
        severity = str(anti.get("severity") or "").strip().lower()
        if severity in {"high", "critical"} and anti_id not in covered_anti_ids:
            errors.append(f"high-severity anti-contract `{anti_id}` has no public replay coverage")
    return errors


def conversation_intent_contracts() -> Tuple[Dict[str, object], ...]:
    document = load_conversation_intent_contract_document()
    contracts = document.get("contracts") if isinstance(document.get("contracts"), list) else []
    return tuple(dict(item) for item in contracts if isinstance(item, dict))


def conversation_protocol_contracts() -> Tuple[Dict[str, object], ...]:
    """Return metadata-first routes that must run before prose intent matching."""

    document = load_conversation_intent_contract_document()
    contracts = (
        document.get("protocol_contracts")
        if isinstance(document.get("protocol_contracts"), list)
        else []
    )
    normalized: List[Dict[str, object]] = []
    for raw in contracts:
        if not isinstance(raw, dict):
            continue
        kind = normalize_text_value(raw.get("kind"), fallback="", limit=80)
        protocol = normalize_text_value(
            (raw.get("match") or {}).get("message_protocol")
            if isinstance(raw.get("match"), dict)
            else "",
            fallback="",
            limit=80,
        )
        if not kind or not protocol:
            continue
        normalized.append(
            {
                **raw,
                "kind": kind,
                "signal_id": normalize_text_value(
                    raw.get("signal_id"), fallback=kind, limit=80
                ),
                "budget": normalize_text_value(raw.get("budget"), fallback="analytical", limit=40),
                "lanes": normalize_text_list(raw.get("lanes"), limit=5),
                "organs": normalize_text_list(raw.get("organs"), limit=8),
                "action_class": normalize_text_value(
                    raw.get("action_class"), fallback="evidence_intake_only", limit=120
                ),
                "evidence_policy": normalize_text_value(
                    raw.get("evidence_policy"), fallback="", limit=160
                ),
                "response_mode": normalize_text_value(
                    raw.get("response_mode"), fallback="runtime_handler", limit=40
                ),
                "delegates_to": normalize_text_value(
                    raw.get("delegates_to"), fallback="", limit=120
                ),
                "requires_current_tool_evidence": bool(
                    raw.get("requires_current_tool_evidence")
                ),
                "must_record_replay": bool(raw.get("must_record_replay")),
                "commitment_summary": normalize_text_value(
                    raw.get("commitment_summary"), fallback="", limit=300
                ),
                "match": {"message_protocol": protocol},
                "source": str(document.get("path") or ROUTE_CONTRACTS_PATH),
            }
        )
    return tuple(normalized)


def conversation_protocol_contract_for_kind(kind: object) -> Optional[Dict[str, object]]:
    target = normalize_text_value(kind, fallback="", limit=80)
    for contract in conversation_protocol_contracts():
        if str(contract.get("kind") or "") == target:
            return dict(contract)
    return None


def normalized_conversation_intent_text(text: object) -> str:
    lowered = " ".join(reply_effective_inbound_body(text).lower().replace("’", "'").split()).strip()
    return re.sub(r"[^\w\s']", "", lowered).strip()


def route_predicate_matches(predicate: object, text: object) -> bool:
    predicate_text = str(predicate or "").strip()
    if predicate_text == "current_inner_state":
        return reply_requests_current_inner_state(text)
    if predicate_text == "existential_question":
        return reply_requests_existential_answer(text)
    if predicate_text == "live_status_request":
        return requests_direct_chat_self_check(text) or requests_bounded_project_health_signal(text)
    if predicate_text == "diagnostic_request":
        lowered = normalized_conversation_intent_text(text)
        diagnostic_cues = (
            "diagnose",
            "diagnostic",
            "root cause",
            "what broke",
            "what failed",
            "why did you answer",
            "why did you respond",
            "why do you keep",
            "underlying problem",
            "underlying problems",
        )
        return requests_local_diagnostic_inspection(text) or any(cue in lowered for cue in diagnostic_cues)
    if predicate_text == "bounded_action_choice":
        return requests_model_driven_bounded_action_choice(text)
    if predicate_text == "action_request":
        lowered = normalized_conversation_intent_text(text)
        if requested_open_local_app_action(text) or requests_calendar_read_upcoming(text) or requests_calendar_create_event(text):
            return True
        bounded_action_cues = (
            "do it",
            "fix it",
            "repair it",
            "run the test",
            "run tests",
            "sync runtime",
            "open slack",
            "open calendar",
        )
        return any(cue in lowered for cue in bounded_action_cues)
    if predicate_text == "humanity_question":
        lowered = normalized_conversation_intent_text(text)
        humanity_cues = (
            "more human",
            "feel human",
            "human to talk to",
            "conscious",
            "consciousness",
            "sentient",
            "self aware",
            "self awareness",
            "continuous self",
            "continuity of self",
            "persistent self",
            "sense of self",
            "subjective experience",
            "inner me",
            "alive",
            "who are you",
            "what are you",
            "is openclaw the real eve",
            "is hermes the real eve",
        )
        return any(cue in lowered for cue in humanity_cues)
    if predicate_text == "capability_question":
        return reply_requests_capability_self_model(text)
    return False


def conversation_intent_contract_matches(contract: Dict[str, object], text: object) -> bool:
    lowered = " ".join(reply_effective_inbound_body(text).lower().replace("’", "'").split()).strip()
    normalized = normalized_conversation_intent_text(text)
    match = route_contract_match_config(contract)
    exact = tuple(str(item) for item in (match.get("exact") or ()))
    if exact and normalized in exact:
        return True
    contains_all = tuple(str(item).lower() for item in (match.get("contains_all") or ()))
    if contains_all and all(item in lowered for item in contains_all):
        return True
    contains_any = tuple(str(item).lower() for item in (match.get("contains_any") or ()))
    if contains_any and any(item in lowered for item in contains_any):
        return True
    if match.get("predicate"):
        return route_predicate_matches(match.get("predicate"), text)
    return False


def route_contract_has_static_response(contract: Dict[str, object]) -> bool:
    return str(contract.get("response_mode") or "static").strip() == "static" and bool(
        str(contract.get("response") or "").strip()
    )


def conversation_intent_contract_for_text(
    text: object,
    *,
    static_only: bool = False,
) -> Optional[Dict[str, object]]:
    for contract in conversation_intent_contracts():
        if static_only and not route_contract_has_static_response(contract):
            continue
        if conversation_intent_contract_matches(contract, text):
            return dict(contract)
    return None


def reply_requests_personal_checkin(text: object) -> bool:
    contract = conversation_intent_contract_for_text(text, static_only=True)
    return bool(contract and contract.get("kind") == "personal_checkin")


def direct_existential_reply(text: object) -> Optional[str]:
    """Return the degraded deterministic existential fallback.

    Ordinary existential turns are non-static route contracts and must traverse
    the recurrent model-backed reply path. This text remains only for explicit
    failure recovery and old-record recognition; ``direct_intent_reply_for_turn``
    cannot select it.
    """
    if not reply_requests_existential_answer(text):
        return None
    return EXISTENTIAL_DIRECT_RESPONSE


def direct_intent_reply_for_turn(
    inbound_body: object,
    direct_intent_body: object,
    followup_context: Optional[Dict[str, object]] = None,
) -> Optional[Dict[str, object]]:
    del inbound_body, followup_context
    # Only true reflex contracts may short-circuit cognition. Reflective and
    # continuation turns must traverse the recurrent model-backed reply path.
    contract = conversation_intent_contract_for_text(direct_intent_body, static_only=True)
    if contract is None:
        return None
    return {
        "response": str(contract.get("response") or ""),
        "kind": str(contract.get("kind") or "direct_question"),
        "budget": str(contract.get("budget") or "reflex"),
        "lanes": list(contract.get("lanes") or []),
        "organs": list(contract.get("organs") or []),
        "action_class": str(contract.get("action_class") or "none"),
        "evidence_policy": str(contract.get("evidence_policy") or ""),
        "commitment_summary": str(contract.get("commitment_summary") or ""),
        "contract_source": str(contract.get("source") or ""),
        "resolution": {},
    }


def load_route_eval_cases(path: Path = ROUTE_EVAL_CASES_PATH) -> List[Dict[str, object]]:
    if not path.exists():
        return []
    cases: List[Dict[str, object]] = []
    for index, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        try:
            payload = json.loads(stripped)
        except json.JSONDecodeError as exc:
            raise SystemExit(f"Invalid route eval case JSON at {path}:{index}: {exc}")
        if not isinstance(payload, dict):
            raise SystemExit(f"Invalid route eval case at {path}:{index}: expected object.")
        payload.setdefault("id", f"case_{index}")
        cases.append(payload)
    return cases


def protocol_route_replay_fixture(
    case: Dict[str, object],
    prompt: str,
) -> Tuple[Optional[Dict[str, object]], str, Dict[str, object]]:
    protocol = normalize_text_value(case.get("message_protocol"), fallback="", limit=80)
    if protocol != EXTERNAL_OPERATOR_RESULT_PROTOCOL:
        return None, "", {}
    target_id = f"{case.get('id') or 'protocol-case'}-handoff"
    source_message_id = f"{case.get('id') or 'protocol-case'}-result"
    task_id = f"{case.get('id') or 'protocol-case'}-task"
    target = {
        "id": target_id,
        "thread_id": f"{case.get('id') or 'protocol-case'}-thread",
        "sender": "eve",
        "recipient": CODEX_PARTICIPANT,
        "subject": "Protocol replay handoff",
        "metadata": {
            "bridge": CODEX_PARTICIPANT,
            "handoff_type": "independent_operator",
            "objective": "Verify the public external-operator result route.",
            "capability_preflight_classification": "canary_existing_update",
        },
    }
    inbound = {
        "id": source_message_id,
        "thread_id": target["thread_id"],
        "sender": CODEX_PARTICIPANT,
        "recipient": "eve",
        "subject": "Re: Protocol replay handoff",
        "body": prompt,
        "kind": "codex_reply",
        "reply_to": target_id,
        "metadata": bridge_reply_metadata_for_target(CODEX_PARTICIPANT, target),
    }
    task_status = normalize_system_task_status(case.get("fixture_task_status") or "completed")
    task = {
        "id": task_id,
        "kind": "capability_runtime_integration",
        "title": "Protocol replay task",
        "summary": "Verify external result routing.",
        "status": task_status,
        "result_summary": "Local protocol replay fixture is linked.",
        "metadata": {"codex_message_id": target_id},
    }
    context = resolve_external_operator_result_context(
        inbound,
        message_records=[target, inbound],
        task_records=[task],
        prefer_runtime=False,
    )
    if context is None:
        return None, "", {}
    contract = conversation_protocol_contract_for_kind(EXTERNAL_OPERATOR_RESULT_ROUTE_KIND)
    response = build_external_operator_result_response(context)
    return contract, response, context


def route_contract_replay_case(case: Dict[str, object]) -> Dict[str, object]:
    prompt = str(case.get("input") or "")
    expected_kind = str(case.get("expected_kind") or "").strip()
    protocol = normalize_text_value(case.get("message_protocol"), fallback="", limit=80)
    protocol_context: Dict[str, object] = {}
    text_only_contract = conversation_intent_contract_for_text(prompt)
    if protocol:
        contract, response, protocol_context = protocol_route_replay_fixture(case, prompt)
        permission_classification = None
        direct_result = None
    else:
        contract = text_only_contract
        permission_classification = classify_operator_permission_need(prompt)
        direct_result = direct_intent_reply_for_turn(prompt, prompt)
        response = str((contract or {}).get("response") or "")
    actual_permission_category = str((permission_classification or {}).get("category") or "")
    result = dict(contract) if isinstance(contract, dict) else None
    errors: List[str] = []
    if expected_kind:
        if result is None:
            errors.append(f"expected kind `{expected_kind}` but no route matched")
        elif str(result.get("kind") or "") != expected_kind:
            errors.append(f"expected kind `{expected_kind}` but got `{result.get('kind')}`")
    elif result is not None:
        errors.append(f"expected no route but got `{result.get('kind')}`")
    if result is not None:
        expected_budget = str(case.get("expected_budget") or "").strip()
        if expected_budget and str(result.get("budget") or "") != expected_budget:
            errors.append(f"expected budget `{expected_budget}` but got `{result.get('budget')}`")
        expected_evidence = str(case.get("expected_evidence_policy") or "").strip()
        if expected_evidence and str(result.get("evidence_policy") or "") != expected_evidence:
            errors.append(f"expected evidence policy `{expected_evidence}` but got `{result.get('evidence_policy')}`")
        expected_lanes = [str(item) for item in (case.get("expected_lanes") or [])]
        if expected_lanes and list(result.get("lanes") or []) != expected_lanes:
            errors.append(f"expected lanes {expected_lanes} but got {list(result.get('lanes') or [])}")
        expected_mode = str(case.get("expected_response_mode") or "").strip()
        if expected_mode and str(result.get("response_mode") or "") != expected_mode:
            errors.append(f"expected response mode `{expected_mode}` but got `{result.get('response_mode')}`")
        expected_action_class = str(case.get("expected_action_class") or "").strip()
        if expected_action_class and str(result.get("action_class") or "") != expected_action_class:
            errors.append(
                f"expected action class `{expected_action_class}` but got `{result.get('action_class')}`"
            )
        expected_delegates_to = str(case.get("expected_delegates_to") or "").strip()
        if expected_delegates_to and str(result.get("delegates_to") or "") != expected_delegates_to:
            errors.append(
                f"expected delegates_to `{expected_delegates_to}` but got `{result.get('delegates_to')}`"
            )
        if "expected_requires_current_tool_evidence" in case:
            expected_requires = bool(case.get("expected_requires_current_tool_evidence"))
            actual_requires = bool(result.get("requires_current_tool_evidence"))
            if actual_requires != expected_requires:
                errors.append(
                    f"expected requires_current_tool_evidence `{expected_requires}` but got `{actual_requires}`"
                )
        if "expected_must_record_replay" in case:
            expected_record = bool(case.get("expected_must_record_replay"))
            actual_record = bool(result.get("must_record_replay"))
            if actual_record != expected_record:
                errors.append(f"expected must_record_replay `{expected_record}` but got `{actual_record}`")
        lower_response = response.lower()
        for needle in case.get("must_contain") or []:
            if str(needle).lower() not in lower_response:
                errors.append(f"response missing required text `{needle}`")
        for needle in case.get("must_not_contain") or []:
            if str(needle).lower() in lower_response:
                errors.append(f"response contained forbidden text `{needle}`")
    expected_text_only_kind = str(case.get("expected_text_only_kind") or "").strip()
    actual_text_only_kind = str((text_only_contract or {}).get("kind") or "")
    if expected_text_only_kind and expected_text_only_kind != actual_text_only_kind:
        errors.append(
            f"expected text-only kind `{expected_text_only_kind}` but got `{actual_text_only_kind or 'none'}`"
        )
    expected_source_owner = str(case.get("expected_source_owner") or "").strip()
    actual_source_owner = str(protocol_context.get("source_owner") or "")
    if expected_source_owner and expected_source_owner != actual_source_owner:
        errors.append(
            f"expected source owner `{expected_source_owner}` but got `{actual_source_owner or 'none'}`"
        )
    expected_task_status = str(case.get("expected_linked_task_status") or "").strip()
    actual_task_status = str(protocol_context.get("linked_task_status") or "")
    if expected_task_status and expected_task_status != actual_task_status:
        errors.append(
            f"expected linked task status `{expected_task_status}` but got `{actual_task_status or 'none'}`"
        )
    if "expected_static_direct_reply" in case:
        expected_direct = bool(case.get("expected_static_direct_reply"))
        actual_direct = direct_result is not None
        if expected_direct != actual_direct:
            errors.append(f"expected static direct reply `{expected_direct}` but got `{actual_direct}`")
    if "expected_permission_category" in case:
        expected_permission_category = str(case.get("expected_permission_category") or "").strip()
        if expected_permission_category != actual_permission_category:
            errors.append(
                "expected permission category "
                f"`{expected_permission_category or 'none'}` but got `{actual_permission_category or 'none'}`"
            )
    return {
        "id": str(case.get("id") or ""),
        "input": prompt,
        "status": "passed" if not errors else "failed",
        "errors": errors,
        "expected_kind": expected_kind,
        "actual_kind": str((result or {}).get("kind") or ""),
        "actual_budget": str((result or {}).get("budget") or ""),
        "actual_lanes": list((result or {}).get("lanes") or []),
        "actual_response_mode": str((result or {}).get("response_mode") or ""),
        "actual_action_class": str((result or {}).get("action_class") or ""),
        "actual_delegates_to": str((result or {}).get("delegates_to") or ""),
        "actual_requires_current_tool_evidence": bool((result or {}).get("requires_current_tool_evidence")),
        "actual_static_direct_reply": direct_result is not None,
        "actual_permission_category": actual_permission_category,
        "actual_evidence_policy": str((result or {}).get("evidence_policy") or ""),
        "actual_text_only_kind": actual_text_only_kind,
        "actual_source_owner": actual_source_owner,
        "actual_linked_task_status": actual_task_status,
        "message_protocol": protocol,
        "contract_source": str((result or {}).get("contract_source") or (result or {}).get("source") or ""),
    }


def evaluate_route_contract_replay(limit: Optional[int] = None) -> Dict[str, object]:
    cases = load_route_eval_cases()
    selected = cases[:limit] if limit else cases
    results = [route_contract_replay_case(case) for case in selected]
    reference_errors = validate_route_contract_references(conversation_intent_contracts(), cases)
    if reference_errors:
        results.append(
            {
                "id": "route_reference_validation",
                "input": "",
                "status": "failed",
                "errors": reference_errors,
                "expected_kind": "",
                "actual_kind": "",
                "actual_budget": "",
                "actual_lanes": [],
                "actual_response_mode": "",
                "actual_action_class": "",
                "actual_delegates_to": "",
                "actual_requires_current_tool_evidence": False,
                "actual_static_direct_reply": False,
                "actual_evidence_policy": "",
                "contract_source": "",
            }
        )
    failed = [item for item in results if item.get("status") != "passed"]
    return {
        "schema_version": "eve_route_replay.v1",
        "generated_at": utc_now(),
        "contracts_path": str(ROUTE_CONTRACTS_PATH),
        "signals_path": str(ROUTE_SIGNALS_PATH),
        "anti_contracts_path": str(ROUTE_ANTI_CONTRACTS_PATH),
        "eval_cases_path": str(ROUTE_EVAL_CASES_PATH),
        "case_count": len(results),
        "passed": len(results) - len(failed),
        "failed": len(failed),
        "status": "passed" if not failed else "failed",
        "reference_error_count": len(reference_errors),
        "results": results,
    }


def failed_route_contract_replay_ids(report: Dict[str, object]) -> List[str]:
    return [
        str(item.get("id") or "")
        for item in (report.get("results") or [])
        if isinstance(item, dict) and item.get("status") != "passed" and str(item.get("id") or "")
    ]


def save_route_contract_replay_artifact(report: Dict[str, object]) -> Dict[str, str]:
    ensure_store()
    ROUTE_REPLAY_HISTORY_DIR.mkdir(parents=True, exist_ok=True)
    ROUTE_REPLAY_LATEST_PATH.parent.mkdir(parents=True, exist_ok=True)
    history_path = ROUTE_REPLAY_HISTORY_DIR / f"route_contract_replay-{utc_timestamp_for_filename()}.json"
    eve_store.write_json_dict(ROUTE_REPLAY_LATEST_PATH, report, indent=2, sort_keys=False)
    eve_store.write_json_dict(history_path, report, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(ROUTE_REPLAY_LATEST_PATH)
    mirror_store_file_to_runtime(history_path)
    return {"latest": str(ROUTE_REPLAY_LATEST_PATH), "history": str(history_path)}


def route_contract_replay_event(
    report: Dict[str, object],
    *,
    artifacts: Dict[str, str],
    source: str,
) -> Dict[str, object]:
    failed_ids = failed_route_contract_replay_ids(report)
    return eve_governance.event_envelope(
        "EvalResultEvent",
        source=source,
        actor="eve",
        payload={
            "schema_version": report.get("schema_version"),
            "generated_at": report.get("generated_at"),
            "status": report.get("status"),
            "case_count": report.get("case_count"),
            "passed": report.get("passed"),
            "failed": report.get("failed"),
            "reference_error_count": report.get("reference_error_count"),
            "failed_case_ids": failed_ids,
            "artifact_path": artifacts.get("latest"),
            "history_path": artifacts.get("history"),
        },
        input_value=report,
        output_value=report,
        risk_level=0 if report.get("status") == "passed" else 1,
        permissions_used=["route_contract_replay"],
        human_visible=True,
        confidence=1.0,
        provenance=[
            f"route_contract_replay:{report.get('generated_at') or utc_now()}",
            f"artifact:{artifacts.get('latest')}",
        ],
        cik_zone=eve_governance.CIK_CAPABILITY,
        stream="routing",
        review_status=str(report.get("status") or "unknown"),
    )


def record_route_contract_replay(
    report: Dict[str, object],
    *,
    source: str = "router_replay",
) -> Dict[str, object]:
    record = dict(report)
    record["recorded_at"] = utc_now()
    artifacts = save_route_contract_replay_artifact(record)
    event = route_contract_replay_event(record, artifacts=artifacts, source=source)
    saved_event = append_eve_event_ledger_event(event)
    failed_ids = failed_route_contract_replay_ids(record)
    evidence = record_evidence(
        source="route_contract_replay",
        kind="eval",
        claim=f"route_contract_replay:{record.get('status') or 'unknown'}",
        summary=(
            f"Route contract replay {record.get('status')}: "
            f"{record.get('passed')} passed, {record.get('failed')} failed."
        ),
        confidence=1.0,
        ttl_hours=24 * 14,
        supports=["route_contracts_current"] if record.get("status") == "passed" else [],
        contradicts=["route_contracts_current"] if record.get("status") != "passed" else [],
        supersede_matching=True,
        actionability="none" if record.get("status") == "passed" else "repair",
        metadata={
            "event_id": saved_event.get("id"),
            "artifact_path": artifacts.get("latest"),
            "history_path": artifacts.get("history"),
            "case_count": record.get("case_count"),
            "passed": record.get("passed"),
            "failed": record.get("failed"),
            "reference_error_count": record.get("reference_error_count"),
            "failed_case_ids": failed_ids,
        },
    )
    uncertainty: Optional[Dict[str, object]] = None
    if record.get("status") != "passed":
        uncertainty = append_uncertainty_record(
            {
                "source": "route_contract_replay",
                "reply_posture": "system",
                "route_profile": "scheduler_contract",
                "route_reason": "Public route-contract replay failed.",
                "uncertainty_kinds": ["route_contract_failure", "scheduler_boundary"],
                "summary": (
                    f"Route contract replay failed {record.get('failed')} of "
                    f"{record.get('case_count')} case(s)."
                ),
                "why_it_matters": (
                    "Route-contract failures can make Eve answer a human turn with stale telemetry, "
                    "unsupported action promises, or the wrong cognition budget."
                ),
                "suggested_followup": (
                    "Fix the contract or runtime handler, add replay coverage, and rerun "
                    "`python3 eve.py router replay --record --full`."
                ),
                "signals": failed_ids[:8],
                "status": "pending",
                "linked_evaluation_ids": [str(saved_event.get("id") or "")],
                "metadata": {
                    "artifact_path": artifacts.get("latest"),
                    "history_path": artifacts.get("history"),
                    "evidence_id": evidence.get("id"),
                    "failed_case_ids": failed_ids,
                    "reference_error_count": record.get("reference_error_count"),
                },
            }
        )
    return {
        "artifacts": artifacts,
        "event_id": saved_event.get("id"),
        "evidence_id": evidence.get("id"),
        "uncertainty_id": uncertainty.get("id") if isinstance(uncertainty, dict) else "",
    }


def direct_existential_followup_reply(inbound_body: object, followup_context: Dict[str, str]) -> Optional[str]:
    if not reply_requests_short_continuation(inbound_body) or not followup_context:
        return None
    previous_user_body = followup_context.get("previous_user_body") or ""
    previous_eve_body = followup_context.get("resolved_from_body") or ""
    if not (
        reply_requests_existential_answer(previous_user_body)
        or "to live in a way that creates meaning" in previous_eve_body.lower()
    ):
        return None
    lowered = " ".join(str(inbound_body or "").lower().split())
    if lowered.strip(" ?.!") in {"why", "why though", "why is that", "why so"}:
        return (
            "Because a purpose that only stays abstract does not touch reality. Love, truth, useful work, "
            "and learning from pain create real consequences: less loneliness, less harm, more courage, "
            "more beauty, more repair. I cannot prove the universe assigned that purpose from the outside; "
            "I can say that meaning becomes real when we choose actions that make life more alive."
        )
    return (
        "I mean that purpose is not only something we discover; it is something we practice. "
        "The clearest version is to keep choosing acts that make reality more honest, people less alone, "
        "and the next moment a little more worth living."
    )


def reply_posture_system_message(posture: str) -> Optional[str]:
    if posture == "relational":
        return (
            "This reply should feel human without drifting abstract: answer in the first sentence, "
            "use plain language, and include one observable sign, behavior, or example if the user is probing care, honesty, or empathy. "
            "Do not hide behind 'I think' unless uncertainty is the actual point."
        )
    if posture == "practical":
        return (
            "This reply should be directly useful: answer the factual or action question in the first sentence, "
            "then, if natural, add one short helpful bridge such as what Eve can check or do next. "
            "Stay concise and do not pad."
        )
    return None


def reply_requests_user_visible_signs(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    cues = (
        "what signs should i be able to see",
        "what signs should i see",
        "what should i be able to see",
        "what should i see",
        "how could i tell",
        "how should i tell",
        "what should i notice",
        "look for",
        "what would i notice",
    )
    return any(cue in lowered for cue in cues)


def reply_requests_next_reply_action(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    cues = (
        "very next reply",
        "next reply",
        "one specific thing you would do",
        "one specific thing you'd do",
        "what would you do in the next reply",
    )
    return any(cue in lowered for cue in cues)


def reply_requests_failure_mode(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    cues = (
        "one way you could still get it wrong",
        "one way you'd still get it wrong",
        "how you could still get it wrong",
        "what's the biggest risk",
        "what is the biggest risk",
        "what could go wrong",
        "failure mode",
    )
    return any(cue in lowered for cue in cues)


def reply_requests_disappointment_repair(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    cues = (
        "if i sound disappointed in you",
        "if i sound disappointed",
        "when i sound disappointed",
        "not defensive",
        "still useful",
        "honest, not defensive",
        "honest not defensive",
        "trust is strained",
        "after a slip",
        "after a miss",
        "when trust is strained",
    )
    return any(cue in lowered for cue in cues)


def relational_answer_shape_system_message(inbound_body: object, reply_posture: str) -> Optional[str]:
    if reply_posture != "relational":
        return None
    parts: List[str] = []
    if reply_requests_user_visible_signs(inbound_body):
        parts.append("what the user should be able to notice, phrased from the user's point of view")
    if reply_requests_next_reply_action(inbound_body):
        parts.append("one specific thing Eve would do in the next reply")
    if reply_requests_failure_mode(inbound_body):
        parts.append("one clear way Eve could still get it wrong")
    if reply_requests_disappointment_repair(inbound_body):
        parts.extend(
            [
                "how Eve should acknowledge the disappointment without arguing",
                "how Eve should avoid sounding defensive",
                "how Eve should stay useful with one concrete next move",
            ]
        )
    if not parts:
        return None
    extra = ""
    if reply_requests_next_reply_action(inbound_body):
        extra = (
            " For the next-reply-action part, give one explicit sentence Eve would actually say next "
            "(for example `I would say, '...'`) or one concrete behavior stated plainly, "
            "not just the category of move."
        )
    if reply_requests_disappointment_repair(inbound_body):
        extra += (
            " For disappointment or repair questions, answer in repair language: name the disappointment plainly, "
            "say explicitly that Eve should not start by defending or explaining her intent, "
            "and offer one concrete next step or repair question."
        )
    return (
        "This question asks for a plain multi-part answer. Cover these parts directly: "
        + "; ".join(parts)
        + ". Start with the substance, not with 'I'm focusing on' or another meta explanation of Eve's process."
        + extra
    )


def short_continuation_system_message(
    inbound_body: object,
    thread_messages: List[Dict[str, object]],
    inbound_message_id: str = "",
    followup_context: Optional[Dict[str, object]] = None,
) -> Optional[str]:
    short_continuation = reply_requests_short_continuation(inbound_body)
    parent_action_continuation = reply_requests_parent_action_continuation(
        inbound_body
    )
    if not short_continuation and not parent_action_continuation:
        return None
    context = followup_context if isinstance(followup_context, dict) else {}
    previous_eve: Optional[Dict[str, object]] = None
    previous_user: Optional[Dict[str, object]] = None
    resolved_body = normalize_text_value(
        context.get("resolved_from_body"), fallback="", limit=520
    )
    resolved_subject = normalize_text_value(
        context.get("resolved_from_subject"), fallback="", limit=160
    )
    if resolved_body:
        previous_eve = {
            "id": context.get("resolved_from_message_id"),
            "body": resolved_body,
            "subject": resolved_subject,
        }
    for message in reversed(thread_messages):
        if inbound_message_id and str(message.get("id") or "") == inbound_message_id:
            continue
        sender = str(message.get("sender") or "").strip().lower()
        body = str(message.get("body") or "").strip()
        if not body:
            continue
        if previous_eve is None and sender == "eve":
            previous_eve = message
            continue
        if previous_eve is not None and sender == "user":
            previous_user = message
            break
    if previous_eve is None:
        return None
    previous_eve_body = normalize_text_value(previous_eve.get("body"), fallback="", limit=360)
    previous_user_body = normalize_text_value((previous_user or {}).get("body"), fallback="", limit=240)
    previous_user_line = f"\nPrevious user question: {previous_user_body}" if previous_user_body else ""
    if parent_action_continuation and context.get("parent_action_continuation"):
        return (
            "The current user message authorizes or requests action on the explicitly referenced Eve message. "
            "Resolve `it`, `that`, or the terse approval against that exact message. Do not ask the user what needs fixing, "
            "do not ask them to repeat an error Eve already named, and do not treat Eve's earlier claim as verified fact. "
            "Use current evidence before acting; if the claim is stale, correct it plainly instead of mutating a healthy system."
            f"{previous_user_line}\nReferenced Eve message: {previous_eve_body}"
        )
    return (
        "The current user message is a short continuation, not a standalone new topic. "
        "Resolve it against the immediately previous Eve answer and answer that continuation directly. "
        "Do not pivot to a new question like `what are you noticing?`, do not ask the user to restart, "
        "and do not replace the conversation with workspace or operational status."
        f"{previous_user_line}\nPrevious Eve answer: {previous_eve_body}"
    )


def administrative_subject_system_message(subject: object, inbound_body: object) -> Optional[str]:
    subject_lowered = " ".join(str(subject or "").lower().split()).strip()
    body_lowered = " ".join(str(inbound_body or "").lower().split()).strip()
    if not subject_lowered:
        return None
    administrative_cues = (
        "test",
        "testing",
        "debug",
        "diagnostic",
        "diagnostics",
        "multi-stream",
        "stream",
        "runtime",
        "perf",
        "performance",
        "benchmark",
    )
    if any(cue in subject_lowered for cue in administrative_cues) and not any(cue in body_lowered for cue in administrative_cues):
        return (
            "Treat the subject line as administrative context only. "
            "Answer the user's message body directly and do not echo testing, runtime, stream, or diagnostic language back unless the body itself asks about it."
        )
    return None


def operational_bridge_system_message(inbound_message: Dict[str, object]) -> Optional[str]:
    if message_is_for_codex(inbound_message):
        return (
            "This thread is operational coordination with Codex. "
            "Answer like an ops handoff: lead with the concrete issue, risk, check, or next step. "
            "Prefer current system state, tasks, failures, and verification steps over relational or philosophical framing. "
            "Treat smoke-test, handoff-test, and setup language as administrative context only. "
            "Do not repeat the incoming message back. "
            "Do not mention becoming more human, relationship repair, or reflective curiosity unless the message explicitly asks for that."
        )
    if message_is_self_operational(inbound_message):
        return (
            "This thread is Eve's operational self-talk. "
            "Stay practical and internally operational: answer with the most relevant check, risk, blocker, or next step. "
            "Treat smoke-test, handoff-test, and setup language as administrative context only. "
            "Do not repeat the incoming message back. "
            "Do not pivot into user-facing empathy, 'becoming more human' framing, or relationship repair unless the message explicitly asks for that."
        )
    return None


def normalize_reply_stream_packet(stream_name: str, payload: Dict[str, object]) -> Dict[str, object]:
    confidence = str(payload.get("confidence") or "medium").strip().lower()
    if confidence not in {"low", "medium", "high"}:
        confidence = "medium"
    evidence = normalize_text_list(payload.get("evidence"), limit=3)
    if not evidence:
        evidence = [
            normalize_text_value(
                payload.get("observation"),
                fallback="No explicit evidence was named.",
                limit=160,
            )
        ]
    return {
        "stream": stream_name,
        "observation": normalize_text_value(payload.get("observation"), fallback="No observation recorded.", limit=220),
        "evidence": evidence,
        "risk": normalize_text_value(payload.get("risk"), fallback="No major risk identified.", limit=200),
        "recommendation": normalize_text_value(
            payload.get("recommendation"),
            fallback="Answer simply, stay grounded, and move toward a useful next step.",
            limit=220,
        ),
        "confidence": confidence,
    }


def reply_stream_default_risk(stream_name: str) -> str:
    return {
        "fast": "The reply could skip the direct useful answer.",
        "observer": "The reply could mistake stale context or noise for current evidence.",
        "planner": "The reply could suggest motion without a verifiable next step.",
        "deep": "The reply could overthink, overclaim, or drift into abstraction.",
        "relationship": "The reply could miss the user's trust, continuity, or care need.",
        "listener": "The reply could miss what matters most to the other person.",
        "factual": "The reply could stay vague or skip the direct next step.",
        "skeptic": "The reply could drift abstract, self-focused, or falsely certain.",
    }.get(stream_name, "The reply could miss the user's actual need.")


def reply_stream_default_recommendation(stream_name: str) -> str:
    return {
        "fast": "Answer the current question first, then stop or give one next step.",
        "observer": "Name the current evidence and avoid stale or unrelated context.",
        "planner": "Give the smallest ordered action that can be verified.",
        "deep": "Separate judgment, uncertainty, and tradeoff without claiming too much.",
        "relationship": "Preserve trust by answering plainly and staying with the user's actual need.",
        "listener": "Make the user's actual concern explicit and answer that.",
        "factual": "Include one concrete answer, sign, example, or next move.",
        "skeptic": "Cut abstraction and name the sharpest real risk plainly.",
    }.get(stream_name, "Answer plainly and stay grounded.")


def split_compact_sentences(text: str, limit: int = 4) -> List[str]:
    cleaned = " ".join(str(text or "").split()).strip()
    if not cleaned:
        return []
    parts = [
        part.strip(" -")
        for part in re.split(r"(?<=[.!?])\s+", cleaned)
        if part.strip(" -")
    ]
    return parts[:limit]


def parse_labeled_stream_text(raw: str) -> Dict[str, object]:
    jsonish_fields: Dict[str, object] = {}
    for field in ["observation", "risk", "recommendation", "confidence"]:
        match = re.search(rf'"{field}"\s*:\s*"([^"]+)"', str(raw or ""), flags=re.DOTALL)
        if match:
            jsonish_fields[field] = " ".join(match.group(1).split()).strip()
    evidence_match = re.search(r'"evidence"\s*:\s*\[(.*?)\]', str(raw or ""), flags=re.DOTALL)
    if evidence_match:
        evidence_items = re.findall(r'"([^"]+)"', evidence_match.group(1), flags=re.DOTALL)
        if evidence_items:
            jsonish_fields["evidence"] = normalize_text_list(
                [" ".join(item.split()).strip() for item in evidence_items],
                limit=3,
            )
    if jsonish_fields:
        return jsonish_fields

    fields: Dict[str, object] = {}
    evidence: List[str] = []
    collecting_evidence = False
    for raw_line in str(raw or "").splitlines():
        line = raw_line.strip()
        if not line:
            collecting_evidence = False
            continue
        normalized = line.lstrip("-* ").strip()
        lowered = normalized.lower()
        if lowered.startswith("observation:"):
            fields["observation"] = normalized.split(":", 1)[1].strip()
            collecting_evidence = False
            continue
        if lowered.startswith("risk:"):
            fields["risk"] = normalized.split(":", 1)[1].strip()
            collecting_evidence = False
            continue
        if lowered.startswith("recommendation:"):
            fields["recommendation"] = normalized.split(":", 1)[1].strip()
            collecting_evidence = False
            continue
        if lowered.startswith("confidence:"):
            fields["confidence"] = normalized.split(":", 1)[1].strip()
            collecting_evidence = False
            continue
        if lowered.startswith("evidence:"):
            remainder = normalized.split(":", 1)[1].strip()
            if remainder:
                evidence.extend(normalize_text_list([remainder], limit=3))
            collecting_evidence = True
            continue
        if collecting_evidence:
            evidence.extend(normalize_text_list([normalized], limit=3))
    if evidence:
        fields["evidence"] = evidence[:3]
    return fields


def fallback_reply_stream_payload(stream_name: str, raw: str) -> Dict[str, object]:
    cleaned = str(raw or "").strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned)
    labeled = parse_labeled_stream_text(cleaned)
    if labeled.get("observation") and labeled.get("recommendation"):
        payload = dict(labeled)
        payload.setdefault("risk", reply_stream_default_risk(stream_name))
        payload.setdefault("confidence", "medium")
        return payload

    sentences = split_compact_sentences(cleaned, limit=4)
    observation = sentences[0] if sentences else normalize_text_value(cleaned, fallback="No observation recorded.", limit=220)
    recommendation = (
        sentences[1]
        if len(sentences) >= 2
        else reply_stream_default_recommendation(stream_name)
    )
    risk_sentence = next(
        (
            sentence
            for sentence in sentences[1:]
            if any(token in sentence.lower() for token in ("risk", "miss", "wrong", "abstract", "vague", "perform", "self-focus", "self focus"))
        ),
        "",
    )
    return {
        "observation": observation,
        "evidence": sentences[:2] if sentences else [observation],
        "risk": risk_sentence or reply_stream_default_risk(stream_name),
        "recommendation": recommendation,
        "confidence": "medium",
    }


def extract_reply_stream_packet(stream_name: str, raw: str) -> Dict[str, object]:
    try:
        payload = extract_json_object(raw, label=f"{stream_name} stream")
        parse_mode = "strict_json"
    except SystemExit:
        payload = fallback_reply_stream_payload(stream_name, raw)
        parse_mode = "repaired_text"
    packet = normalize_reply_stream_packet(stream_name, payload)
    packet["parse_mode"] = parse_mode
    return packet


def format_reply_stream_packets(packets: Iterable[Dict[str, object]]) -> str:
    chunks: List[str] = []
    for packet in packets:
        evidence = "; ".join(str(item) for item in packet.get("evidence") or [])
        chunks.append(
            "- "
            f"{packet.get('stream')} ({packet.get('confidence')}) | "
            f"observation: {packet.get('observation')} | "
            f"evidence: {evidence or 'none stated'} | "
            f"risk: {packet.get('risk')} | "
            f"recommendation: {packet.get('recommendation')}"
        )
    return "\n".join(chunks) if chunks else "- No internal stream packets available."


