def reply_is_overcentered_on_eve(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    first_person_count = len(re.findall(r"\b(i|i'm|i've|i'd|i'll|me|my|myself)\b", lowered))
    other_person_count = len(re.findall(r"\b(you|your|yours|we|us|our|ours)\b", lowered))
    return first_person_count >= other_person_count + 3


def reply_opens_with_needless_uncertainty(inbound_body: str, response: str, reply_posture: str) -> bool:
    lowered_response = " ".join(str(response or "").lower().split()).strip()
    lowered_inbound = " ".join(str(inbound_body or "").lower().split()).strip()
    if not lowered_response.startswith("i think "):
        return False
    if reply_posture != "relational":
        return False
    uncertainty_cues = ("uncertain", "not sure", "guess", "maybe", "wonder", "do you think")
    if any(cue in lowered_inbound for cue in uncertainty_cues):
        return False
    return True


def reply_has_humanity_first_filler_opening(text: object) -> bool:
    cleaned = " ".join(str(text or "").split()).strip().lower()
    if not cleaned:
        return False
    if len(cleaned.split()) <= 8:
        return False
    filler_openers = (
        "okay.",
        "okay,",
        "sure.",
        "sure,",
        "absolutely.",
        "absolutely,",
        "great question",
        "good question",
        "let's focus",
        "let me answer",
        "i'll answer",
        "i will answer",
        "happy to",
    )
    return any(cleaned.startswith(opener) for opener in filler_openers)


def reply_needs_humanity_first_shape(inbound_body: str, response: str, reply_posture: str) -> bool:
    cleaned_response = " ".join(str(response or "").split()).strip()
    if not cleaned_response:
        return False
    # A user-defined labeled evidence contract is already the requested answer
    # shape.  Do not force a conversational landing or follow-up into it; that
    # can violate both exact-line constraints and explicit no-action bounds.
    requested_labels = reply_requested_labeled_lines(inbound_body)
    if requested_labels and reply_preserves_requested_labeled_lines(inbound_body, response):
        return False
    lowered_response = cleaned_response.lower()
    if lowered_response.startswith(("action_attempted:", "action attempted:", "action:", "status:")):
        return False
    lowered_inbound = " ".join(str(inbound_body or "").lower().split()).strip()
    humanity_cues = (
        "more human",
        "humanity",
        "feel human",
        "emotionally thin",
        "less performative",
        "more real",
        "more alive",
    )
    if any(cue in lowered_inbound for cue in humanity_cues):
        return True
    if reply_requests_concrete_support(inbound_body) or reply_requests_relational_grounding(inbound_body):
        return True
    if reply_has_humanity_first_filler_opening(cleaned_response):
        return True
    if reply_posture == "relational" and len(cleaned_response.split()) >= 32:
        return True
    return len(cleaned_response.split()) >= 32


