def reply_has_workbench_process_leakage(inbound_body: object, response: object) -> bool:
    inbound_lowered = " ".join(str(inbound_body or "").lower().split()).strip()
    raw_response = str(response or "")
    response_lowered = " ".join(raw_response.lower().split()).strip()
    if not response_lowered:
        return False
    if any(
        cue in inbound_lowered
        for cue in (
            "show your workbench",
            "show the workbench",
            "show your tool",
            "show your tools",
            "show your trace",
            "internal process",
            "raw search notes",
            "debug",
            "trace",
        )
    ):
        return False
    visible_status_pattern = re.compile(
        r"(^|\n)\s*(searching|opening|reading|fetching|clicking)\s+"
        r"(?:https?://)?(?:www\.)?[a-z0-9][a-z0-9.-]*\.[a-z]{2,}",
        flags=re.IGNORECASE,
    )
    if visible_status_pattern.search(raw_response):
        return True
    direct_cues = (
        "the system requires",
        "system requires screenshots",
        "use screenshots when analyzing pdf",
        "screenshots to be used for pdf analysis",
        "even though i could parse",
        "even though i can parse",
        "i need to cite the official",
        "i need to take screenshots",
        "i'll locate the relevant lines",
        "i’ll locate the relevant lines",
        "locate the relevant lines and official documents to proceed",
    )
    if any(cue in response_lowered for cue in direct_cues):
        return True
    need_to_tool_cues = (
        "i need to find",
        "i need to locate",
        "i need to search",
        "i need to use screenshots",
        "i need to cite",
        "i need to take",
    )
    tool_context_cues = (
        "official pdf",
        "official document",
        "screenshots",
        "pdf analysis",
        "when analyzing pdf",
        "to proceed",
        "relevant lines",
        "search results",
    )
    return any(cue in response_lowered for cue in need_to_tool_cues) and any(
        cue in response_lowered for cue in tool_context_cues
    )


