def reply_current_turn_supports_action(action: object, inbound_body: object) -> bool:
    action_name = str(action or "").strip()
    lowered = " ".join(str(inbound_body or "").lower().split())
    if not action_name or not lowered:
        return False
    if action_name in LOCAL_APP_OPEN_ACTIONS:
        return requested_open_local_app_action(lowered) == action_name or confirms_prior_open_local_app_request(lowered)
    if action_name == CALENDAR_CREATE_EVENT_ACTION:
        return requests_calendar_create_event(lowered)
    if action_name == CALENDAR_READ_UPCOMING_ACTION:
        return requests_calendar_read_upcoming(lowered)
    if action_name == "openclaw_self_test":
        return requests_bounded_openclaw_self_test(lowered) or (
            ("openclaw" in lowered or "open claw" in lowered)
            and "self" in lowered
            and "test" in lowered
        )
    if action_name == "openclaw_log_check":
        return requests_bounded_openclaw_log_check(lowered) or (
            ("openclaw" in lowered or "open claw" in lowered)
            and ("log" in lowered or "logs" in lowered)
            and any(cue in lowered for cue in ("check", "inspect", "read", "look", "review"))
        )
    if action_name == "openclaw_sync_check":
        return (
            ("openclaw" in lowered or "open claw" in lowered)
            and any(cue in lowered for cue in ("sync", "status", "gateway", "check", "verify"))
        )
    if action_name == "service_health_check":
        return any(
            cue in lowered
            for cue in (
                "service health",
                "live health",
                "system health",
                "daemon status",
                "runtime status",
                "model watchdog",
                "watchdog",
                "health check",
                "observe the systems themselves",
                "observing the systems themselves",
                "quick scan of the core components",
                "scan of the core components",
                "scan the core components",
                "system check",
                "diagnostic sweep",
                "scan the five lanes",
                "check the five lanes",
            )
        )
    if action_name == "cleanup_candidate_check":
        return any(cue in lowered for cue in ("cleanup", "clean up", "disk pressure", "free space", "storage pressure"))
    if action_name == "updates_status":
        return any(cue in lowered for cue in ("component update", "update status", "upstream update", "updates check", "check updates"))
    if action_name == "web_search":
        return any(
            cue in lowered
            for cue in (
                "search the web",
                "search online",
                "look online",
                "look it up",
                "research online",
                "search the internet",
                "find it on the internet",
                "check the internet",
            )
        )
    if action_name == "code_change":
        return any(
            cue in lowered
            for cue in (
                "write code",
                "add code",
                "fix code",
                "change code",
                "modify the code",
                "edit the code",
                "patch the code",
                "apply a patch",
                "implement",
                "update the code",
            )
        )
    if action_name == "agent_capability_scout":
        return any(
            cue in lowered
            for cue in (
                "capability scout",
                "agent capability",
                "openclaw capabilities",
                "scan capabilities",
                "check capabilities",
            )
        )
    if action_name == "agent_capability_integration":
        return any(
            cue in lowered
            for cue in (
                "integrate agent",
                "integrate capabilities",
                "agent integration",
                "integrate all this",
                "integrate these capabilities",
            )
        )
    if action_name == "codex_independent_handoff":
        return any(
            cue in lowered
            for cue in (
                "ask codex",
                "have codex",
                "codex handoff",
                "codex review",
                "codex audit",
                "codex independent",
                "send this to codex",
                "bring codex in",
                "involve codex",
            )
        )
    return False


def reply_commitment_mismatches_user_intent(inbound_body: object, response: object) -> bool:
    action = classify_supported_reply_commitment(str(response or ""))
    if action and not reply_current_turn_supports_action(action, inbound_body):
        return True
    return reply_contains_unrequested_organ_status(inbound_body, response)


def reply_contains_unsupported_future_commitment(response: str) -> bool:
    return reply_contains_future_commitment(response) and not classify_supported_reply_commitment(response)


