    lowered = normalized_turn_text(response)
    logical = any(
        cue in lowered
        for cue in ("logical facult", "cognitive function", "attention function", "attention mode")
    )
    physical = any(
        cue in lowered
        for cue in (
            "physical server",
            "separate server",
            "model server",
            "model process",
            "separate process",
            "model weight",
            "model alias",
            "physical topology",
        )
    )
    return logical and physical


