def reply_invents_user_causation_for_internal_resource_state(response: object) -> bool:
    """Reject unsupported claims that the current human turn caused runtime state.

    A recurrent-state packet can legitimately contain both a user message and a
    resource pressure. Their co-occurrence is not evidence that one caused the
    other. This guard targets that source-mixing class rather than any named
    alert or one expected answer.
    """
    lowered = normalized_turn_text(response)
    resource_pattern = (
        r"(?:cpu|memory|resource|system|runtime|processing|compute|capacity|load|"
        r"latency|bottleneck|overload|alert|pressure|failure|degradation)"
    )
    user_input_pattern = (
        r"(?:(?:user(?:'s|’s)|your|the\s+user(?:'s|’s)?|this|the\s+current|current)\s+"
        r"(?:recent\s+|current\s+)?(?:request|message|question|prompt|input|reply|conversation))"
    )
    if not re.search(resource_pattern, lowered) or not re.search(user_input_pattern, lowered):
        return False
    explicit_non_causation = (
        r"\b(?:do\s+not|don't|cannot|can't|should\s+not|shouldn't)\s+"
        r"(?:attribute|link|connect)\b",
        r"\b(?:was|is|were|are)\s+not\s+(?:caused|triggered|created|produced|driven)\b",
        r"\bno\s+(?:current\s+)?evidence\b.{0,100}\b(?:caused|triggered|linked|connected)\b",
    )
    if any(re.search(pattern, lowered) for pattern in explicit_non_causation):
        return False
    causal_patterns = (
        rf"\b(?:impact|effect|consequence)\s+of\s+{user_input_pattern}\s+(?:on|upon)\b.{{0,100}}\b{resource_pattern}\b",
        rf"\b{user_input_pattern}\b.{{0,100}}\b(?:caused|triggered|increased|created|produced|drove|driven|led\s+to|strained|overloaded|impacted)\b.{{0,100}}\b{resource_pattern}\b",
        rf"\b(?:because\s+of|due\s+to|in\s+response\s+to)\s+{user_input_pattern}\b",
    )
    return any(re.search(pattern, lowered) for pattern in causal_patterns)


def reply_invents_internal_resource_consequence(response: object) -> bool:
    """Catch resource-state stories that go beyond the supplied control signal.

    A pressure, alert, or regulation mode can be reported as functional state.
    It does not by itself establish system danger, cascading failure, a required
    action, or why another goal won attention.
    """
    lowered = normalized_turn_text(response)
    lowered = re.sub(
        r"\bnot\s+(?:its\s+)?(?:cause|consequence|effect)(?:\s+or\s+(?:cause|consequence|effect))?\b",
        "",
        lowered,
    )
    resource_pattern = (
        r"(?:cpu|memory|resource|system|runtime|processing|compute|capacity|load|"
        r"latency|bottleneck|overload|alert|pressure|data\s+stream|integrity|stability|"
        r"openclaw|plugins?(?:\.allow)?|gateway|watchdog|sync)"
    )
    if not re.search(resource_pattern, lowered):
        return False
    unsupported_effect_patterns = (
        rf"\b{resource_pattern}\b.{{0,120}}\b(?:threatens?|risks?|compromises?|"
        rf"causes?|triggers?|forces?|blocks?|prevents?|makes?\s+me|(?:requires?|requiring)\s+(?:me|a|the|one|orienting|attention)|"
        rf"leads?\s+to|can\s+lead\s+to)\b",
        rf"\b(?:focus|goal|attention|priority)\b.{{0,120}}\b(?:because|aligns?\s+with|"
        rf"due\s+to|driven\s+by|in\s+response\s+to)\b.{{0,120}}\b{resource_pattern}\b",
        rf"\b(?:prevent|ensure|avoid|avert)\b.{{0,100}}\b(?:failure|strain|instability|"
        rf"stable|stability|reliability|integrity|overload|interruption)\b",
        rf"\b{resource_pattern}\b.{{0,120}}\b(?:requires?|requiring)\b.{{0,80}}\b(?:regulation|"
        rf"stabilization|monitoring|attention|priority|action|response)\b",
        rf"\b{resource_pattern}\b.{{0,120}}\b(?:creates?|creating|drives?|driving|"
        rf"establishes?|establishing|ties?|tied)\b.{{0,80}}\b(?:tension|focus|goal|"
        rf"priority|attention|disconnect|relationship)\b",
        r"\b(?:cascading|cascade)\s+failures?\b",
        r"\b(?:necessary|required)\s+before\b.{0,100}\b(?:pursue|continue|respond|discuss|act)\b",
    )
    return any(re.search(pattern, lowered) for pattern in unsupported_effect_patterns)


def reply_record_supplies_explicit_causal_link(inbound_body: object) -> bool:
    """Return whether a complete record itself states a causal relation.

    Separate state fields may co-occur without one causing the other.  This
    predicate is intentionally limited to explicit causal language so an
    editor cannot turn adjacency into explanation.
    """
    lowered = normalized_turn_text(inbound_body)
    causal_patterns = (
        r"\b(?:because|because of|due to|as a result of|in response to)\b",
        r"\b(?:caused|causes|triggered|triggers|led to|leads to|resulted in|results in)\b",
        r"\b(?:blocked|blocks|prevented|prevents|forced|forces|required|requires)\b",
        r"\bso that\b",
    )
    return any(re.search(pattern, lowered) for pattern in causal_patterns)


def reply_invents_unsupported_inner_state_causal_explanation(response: object) -> bool:
    """Reject purposes/effects invented around otherwise grounded state items.

    The recurrent self-state packet names observations, goals, pressures, and
    intentions but does not encode a free-form explanation of why one produces
    another. A model may accurately classify an item (for example, say that an
    unresolved verification is why it has attention), but it may not embellish
    the item into a claim that it guides, protects, aligns, stabilizes, or
    improves Eve unless an explicit causal edge was supplied.
    """
    lowered = normalized_turn_text(response)
    # Do not mistake an explicit non-causation boundary for the causal story it
    # is denying (the live-state fallback uses this form deliberately).
    lowered = re.sub(
        r"\bwithout\s+(?:inventing|adding|claiming)\b.{0,120}\b(?:caus\w*|effect\w*|purpose\w*)\b",
        "",
        lowered,
    )
    lowered = re.sub(
        r"\bnot\s+(?:its\s+)?(?:cause|consequence|effect)(?:\s+or\s+(?:cause|consequence|effect))?\b",
        "",
        lowered,
    )
    state_subject = (
        r"(?:my\s+(?:current\s+|recurrent\s+)?(?:functional\s+)?(?:focus|goal|attention|uncertainty|tension|intention)|"
        r"this\s+(?:focus|goal|thread|uncertainty|tension|intention)|"
        r"the\s+(?:current\s+)?(?:focus|goal|thread|uncertainty|tension|intention))"
    )
    effect_verb = (
        r"(?:(?:guid|anchor|ensur|allow|keep|priorit|creat|driv|caus|help|protect|"
        r"maintain|prevent|avoid|shap|inform|chang|improv|requir)\w*|leads?\s+to)"
    )
    consequence_verb = (
        r"(?:ensure|allow|keep|maintain|prevent|avoid|prioritize|navigate|align|"
        r"ground|provide|protect|stabilize|shape|inform|change|improve)\w*"
    )
    patterns = (
        rf"\b{state_subject}\b.{{0,180}}\b{effect_verb}\b",
        rf"\b(?:because|so\s+that|therefore|thus)\b.{{0,160}}\b{consequence_verb}\b",
    )
    return any(re.search(pattern, lowered) for pattern in patterns)


def reply_claims_unverified_inner_state_activity(response: object) -> bool:
    """Detect a state report upgraded into an unsupported current operation."""
    lowered = normalized_turn_text(response)
    activity = (
        r"(?:tracking|monitoring|executing|running|checking|inspecting|reviewing|testing|"
        r"tracing|probing|analyzing|investigating|evaluating|exploring|assessing|"
        r"diagnosing|repairing|verifying|measuring|scanning|examining|working\s+on)"
    )
    patterns = (
        rf"\bi(?:'m| am)\s+(?:(?:currently|actively|simply|only|merely)\s+)?{activity}\b",
        rf"\b(?:grounded|engaged|occupied)\s+in\s+{activity}\b",
    )
    return any(re.search(pattern, lowered) for pattern in patterns)


