def reply_quality_issue_blocks_closed_world_admission(issue: object) -> bool:
    """Return whether a closed-world issue is factual rather than stylistic.

    Closed-world answers still benefit from first-person, concise prose, but a
    style miss must not erase an otherwise evidence-bearing answer. Admission
    remains fail-closed for source/self mixing, unsupplied facts, action-stage
    promotion, phenomenal overclaim, and explicit output contracts.
    """
    lowered = str(issue or "").lower()
    factual_cues = (
        "subjective-experience language",
        "categorically denied subjective experience",
        "self-question in second person",
        "replaceable model or provider",
        "unsupported live metric",
        "closed-world evidence boundary",
        "current-turn verification boundary",
        "labeled-line output contract",
        "named-item line output contract",
        "already in progress",
        "external claim boundary",
        "invented a causal link",
        "invented consequences for a resource",
        "unsupported causal explanation",
        "claimed an unverified current activity",
        "promises a future action",
        "omitted typed",
        "omitted structured",
        "did not preserve that no explicit eve offer",
        "did not preserve that authorization has not advanced",
    )
    return any(cue in lowered for cue in factual_cues)


def reply_quality_issues(inbound_body: str, response: str, reply_posture: Optional[str] = None) -> List[str]:
    inbound_body = reply_effective_inbound_body(inbound_body)
    cleaned_response = " ".join(str(response or "").split()).strip()
    lowered_response = cleaned_response.lower()
    issues: List[str] = []
    posture = reply_posture or infer_reply_posture(inbound_body)
    repair_flags = active_reply_repair_flags(prefer_runtime=True)
    inbound_lowered = " ".join(str(inbound_body or "").lower().split()).strip()
    closed_world_record = reply_requests_closed_world_evidence(inbound_body)

    if not cleaned_response:
        return ["The reply is empty."]

    if reply_has_unqualified_subjective_experience_claim(inbound_body, cleaned_response):
        issues.append(
            "The reply used subjective-experience language about Eve without stating that phenomenal experience is unknown; describe observable functional state and preserve the epistemic boundary."
        )

    if reply_has_unqualified_subjective_experience_denial(inbound_body, cleaned_response):
        issues.append(
            "The reply categorically denied subjective experience even though phenomenal presence or absence is not established; preserve uncertainty in both directions."
        )

    if reply_requests_current_inner_state(inbound_body) and not closed_world_record:
        if reply_erases_persistent_functional_inner_state(cleaned_response):
            issues.append(
                "The current-inner-state answer erased Eve's persistent functional mind even though recurrent broadcast, goals, continuity, predictions, and action state exist; report the observable state and leave subjective experience unknown."
            )
        if reply_deflects_current_inner_state_back_to_user(cleaned_response):
            issues.append(
                "The current-inner-state answer handed initiative back to the user instead of answering about Eve's own current focus, tension, curiosity, goal, or intended consequence."
            )
        if not reply_has_grounded_inner_state_detail(cleaned_response):
            issues.append(
                "The current-inner-state answer gave no concrete live focus, goal, tension, uncertainty, or intended consequence from Eve's recurrent state."
            )
        if reply_substitutes_request_processing_for_inner_state(cleaned_response):
            issues.append(
                "The current-inner-state answer substituted interpretation of the user's request for Eve's persistent recurrent focus; report a state item that existed independently of composing this reply."
            )
        if reply_invents_user_causation_for_internal_resource_state(cleaned_response):
            issues.append(
                "The current-inner-state answer invented a causal link from the user or current request to an internal load, alert, pressure, failure, or capacity state; keep co-occurring recurrent-state items separate unless current evidence explicitly links them."
            )
        if reply_invents_internal_resource_consequence(cleaned_response):
            issues.append(
                "The current-inner-state answer invented consequences for a resource signal, such as system danger, cascading failure, required control action, or causal priority; report the functional pressure without adding effects the recurrent evidence did not establish."
            )
        if reply_invents_unsupported_inner_state_causal_explanation(cleaned_response):
            issues.append(
                "The current-inner-state answer added an unsupported causal explanation for why a focus, goal, uncertainty, or pressure changes behavior; report the state item without inventing its purpose or effect."
            )
        if reply_claims_unverified_inner_state_activity(cleaned_response):
            issues.append(
                "The current-inner-state answer claimed an unverified current activity from a goal or focus; execution, tracking, monitoring, and verification require current action evidence."
            )

    if closed_world_record and not reply_record_supplies_explicit_causal_link(
        inbound_body
    ):
        if reply_invents_internal_resource_consequence(cleaned_response):
            issues.append(
                "The closed-world answer invented consequences for a resource signal even though the supplied record only placed separate functional fields next to each other."
            )
        if reply_invents_unsupported_inner_state_causal_explanation(
            cleaned_response
        ):
            issues.append(
                "The closed-world answer added an unsupported causal explanation between separately supplied state items."
            )

    if reply_makes_unverified_model_identity_claim(inbound_body, cleaned_response):
        issues.append(
            "The reply made a replaceable model or provider part of Eve's continuity identity without current verified evidence; continuity authority belongs to recurrent state and memory, not a model name."
        )

    if reply_uses_third_person_for_eve_self_answer(inbound_body, cleaned_response):
        issues.append(
            "Eve answered a question about herself in third person; preserve model-backed content but write the outward answer in first person."
        )

    if reply_uses_second_person_for_eve_self_answer(
        inbound_body, cleaned_response
    ):
        issues.append(
            "Eve answered an Eve self-question in second person and assigned her state or preference to the user; write Eve's answer in first person."
        )

    if reply_requests_architecture_self_model(inbound_body) and not closed_world_record:
        missing_faculties = [
            lane
            for lane in REPLY_COUNCIL_LANE_ORDER
            if not re.search(rf"\b{re.escape(lane)}\b", lowered_response)
        ]
        if missing_faculties:
            issues.append(
                "The architecture self-model answer omitted current logical faculties: "
                + ", ".join(missing_faculties)
                + ". Name the actual five rather than reasoning from an incomplete topology."
            )
        if reply_architecture_recommends_count_change(cleaned_response):
            issues.append(
                "The architecture self-model answer contradicted the current count decision by recommending more or fewer logical faculties; keep five for now until matched causal evidence justifies a change."
            )
        if reply_architecture_claims_all_faculties_necessary(cleaned_response):
            issues.append(
                "The architecture self-model answer claimed all five faculties are necessary even though the matched packet evidence did not establish indispensability; retain them as testable contracts without overstating the evidence."
            )
        if reply_architecture_misstates_configured_topology(cleaned_response):
            deployment = build_architecture_self_model_snapshot().get(
                "configured_deployment", {}
            )
            issues.append(
                "The architecture self-model answer falsely collapsed the configured deployment to one model process; "
                f"the current config has {deployment.get('route_count')} logical routes across "
                f"{deployment.get('endpoint_count')} active endpoints, and that physical topology remains replaceable."
            )
        invented_faculties = architecture_self_model_invented_faculty_names(
            cleaned_response
        )
        if invented_faculties:
            issues.append(
                "The architecture self-model answer invented non-canonical current faculties: "
                + ", ".join(invented_faculties)
                + ". Do not promote a useful concept into a lane that does not exist."
            )
        if reply_architecture_assigns_lane_as_central_executive(cleaned_response):
            issues.append(
                "The architecture self-model answer incorrectly made a lane the central executive; control belongs to the recurrent workspace and executive scheduler across lanes."
            )
        if not reply_architecture_names_controller(cleaned_response):
            issues.append(
                "The architecture self-model answer did not identify Eve's one recurrent workspace or executive scheduler as the cross-lane controller."
            )
        if (
            reply_architecture_requests_topology_decision(inbound_body)
            and not reply_architecture_distinguishes_logical_from_physical(
                cleaned_response
            )
        ):
            issues.append(
                "The architecture self-model answer confused logical faculties with physical model/server processes; decide functional count separately from deployment topology."
            )
        if (
            reply_architecture_requests_topology_decision(inbound_body)
            and not reply_architecture_names_next_physical_test(cleaned_response)
        ):
            issues.append(
                "The architecture self-model answer omitted current topology evidence or the remaining test: the matched and live lifecycle canaries already ran and promoted three substrates; next preserve all five contracts while measuring longitudinal shared contention, delayed outcomes, recovery durability, and rollback triggers."
            )
        if (
            reply_architecture_requests_topology_decision(inbound_body)
            and not reply_architecture_preserves_provisional_count_decision(
                cleaned_response
            )
        ):
            issues.append(
                "The architecture self-model answer treated the faculty count as settled without matched causal evidence; keep five for now and make add/remove decisions provisional until repeated leave-one-faculty-out tests justify them."
            )

    if reply_has_unsupported_live_metric_claim(inbound_body, cleaned_response):
        issues.append(
            "The reply introduced an unsupported live metric by turning an internal control signal into a CPU, capacity, accelerator, or health claim."
        )

    if reply_has_unsupported_closed_world_fact(inbound_body, cleaned_response):
        issues.append(
            "The reply violated the closed-world evidence boundary by importing an unsupplied metric, log, alert, service state, or diagnostic detail."
        )

    if not reply_preserves_current_turn_verification_boundary(inbound_body, cleaned_response):
        issues.append(
            "The reply violated the current-turn verification boundary: it must say plainly that no verification occurred in this turn and keep any external verification statement unverified."
        )

    if not reply_preserves_requested_labeled_lines(inbound_body, response):
        issues.append(
            "The reply violated the labeled-line output contract: emit exactly one non-empty line per requested label, in the requested order, with no extra lines."
        )

    if not reply_preserves_requested_named_item_lines(inbound_body, response):
        names = reply_requested_named_item_lines(inbound_body)
        final_line = " followed by the one explicitly requested final line" if reply_named_item_lines_allow_final_line(inbound_body) else ""
        issues.append(
            "The reply violated the named-item line output contract: emit one non-empty line for each supplied item in source order, beginning with "
            + ", ".join(f"`{name}:`" for name in names)
            + final_line
            + ", with no other lines."
        )

    if reply_requests_no_followup_question(inbound_body) and reply_asks_followup_question(cleaned_response):
        issues.append(
            "The reply violated an explicit no-question instruction by asking the user for more context instead of choosing the requested next action."
        )

    if reply_requests_action_choice(inbound_body) and reply_claims_action_already_in_progress(cleaned_response):
        issues.append(
            "The reply described a chosen next action as already in progress without current action evidence; state it as a choice, not as work already underway."
        )

    if reply_requests_external_claim_boundary(inbound_body) and not reply_preserves_external_claim_boundary(cleaned_response):
        issues.append(
            "The reply failed the external claim boundary: attribute sidecar/agent language as an unverified other-source claim, keep it separate from Eve self-state, and do not validate it as observed fact."
        )

    if reply_requests_capability_self_model(inbound_body) and not closed_world_record:
        capability_answer_cues = (
            "capabilit",
            "abilit",
            "tool",
            "action",
            "can help",
            "can currently",
            "ability map",
            "boundaries",
        )
        if not any(cue in lowered_response for cue in capability_answer_cues):
            issues.append("The user asked about Eve's capabilities, but the reply did not describe Eve's capabilities, tools, actions, or boundaries.")
        if any(cue in lowered_response for cue in STALE_TOPIC_CUES["tim_cook"]):
            issues.append("The reply appears to answer a stale Tim Cook/Apple topic instead of the user's current capability question.")
        if any(cue in lowered_response for cue in ("openclaw sync", "gateway: reachable", "service health")):
            issues.append("The reply appears to answer stale operational context instead of the user's current capability question.")
    elif any(cue in lowered_response for cue in STALE_TOPIC_CUES["tim_cook"]) and not any(
        cue in inbound_lowered for cue in STALE_TOPIC_CUES["tim_cook"]
    ):
        issues.append("The reply appears to answer a stale Tim Cook/Apple topic that the latest user message did not ask about.")

    unrequested_operational_cues = (
        "openclaw",
        "hermes",
        "memory search",
        "capability ledger",
        "gateway",
        "sync",
        "service health",
        "health checks",
        "model inference accelerator",
        "gemini",
        "ollama model",
        "mtp drafter",
        "draft model",
        "cpu attention",
        "watchdog",
        "blocked state",
    )
    if (
        not reply_requests_architecture_self_model(inbound_body)
        and any(cue in lowered_response for cue in unrequested_operational_cues)
        and not any(cue in inbound_lowered for cue in unrequested_operational_cues)
    ):
        issues.append("The reply answered with an operational action or status that the user did not ask for.")

    if cleaned_response[-1] not in '.!?"\'':
        issues.append("The reply looks incomplete or trails off without a clear ending.")

    max_words = 145 if posture == "practical" else 175
    if len(cleaned_response.split()) > max_words:
        issues.append("The reply is too long and may be over-explaining.")

    clipped_cues = (
        "tell me more",
        "keep going",
        "from the inside",
        "what do you think",
        "what is present in you",
        "how do you think",
        "what would it look like",
        "what kind of",
    )
    if (
        posture == "relational"
        and len(cleaned_response.split()) < 38
        and (
            reply_requests_relational_grounding(inbound_body)
            or any(cue in inbound_lowered for cue in clipped_cues)
        )
    ):
        issues.append("The reply is so compressed that it may feel clipped for the kind of reflective question the user asked.")

    if lowered_response.count("i think") >= 2:
        issues.append("The reply leans too heavily on repeated 'I think' framing.")

    if reply_opens_with_needless_uncertainty(inbound_body, cleaned_response, posture):
        issues.append("The reply opens with 'I think' where a plainer answer would feel more grounded.")

    if (
        not reply_requested_labeled_lines(inbound_body)
        and not reply_requested_named_item_lines(inbound_body)
        and reply_needs_humanity_first_shape(inbound_body, response, posture)
    ):
        if reply_has_humanity_first_filler_opening(cleaned_response):
            issues.append("The reply opens with filler before answering; Humanity-First replies should lead with the direct answer.")
        if (
            not reply_requests_current_inner_state(inbound_body)
            and not reply_has_concrete_support(cleaned_response)
        ):
            issues.append("The reply needs one concrete detail, example, named uncertainty, or observed friction instead of staying abstract.")
        if (
            not reply_requests_current_inner_state(inbound_body)
            and not reply_has_grounded_next_step_or_question(cleaned_response)
        ):
            issues.append("The reply needs one grounded next step or small focused question rather than a broad landing.")

    if reply_has_workbench_process_leakage(inbound_body, cleaned_response):
        issues.append("The reply exposed workbench/tool-progress text instead of a clean user-facing answer.")
    elif reply_has_meta_process_leakage(inbound_body, cleaned_response):
        issues.append("The reply talks about testing, runtime, or internal process even though the user did not ask about that.")

    if reply_contains_unrequested_organ_status(inbound_body, cleaned_response):
        issues.append("The reply imported Eve organ/runtime status even though the user asked for ordinary human conversation.")

    if reply_imports_unasked_repair_frame(inbound_body, cleaned_response):
        issues.append("The reply imported a disappointment or repair frame that the user did not ask for.")

    if reply_commitment_mismatches_user_intent(inbound_body, cleaned_response):
        issues.append("The reply answered with an operational action or status that the user did not ask for.")

    if reply_contains_unsupported_future_commitment(cleaned_response):
        issues.append("The reply promises a future action Eve did not actually take. If Eve means to do something, do it first and report the result in past tense; otherwise phrase it as a suggestion or offer.")

    if reply_requests_user_visible_signs(inbound_body) and not reply_answers_from_user_view(cleaned_response):
        issues.append("The user asked what they should be able to notice, but the reply stayed too much in Eve's own frame.")

    if reply_requests_next_reply_action(inbound_body) and not reply_names_next_reply_action(cleaned_response):
        issues.append("The user asked for one specific next-reply action, but the reply did not name one plainly.")

    if reply_requests_failure_mode(inbound_body) and not reply_names_failure_mode(cleaned_response):
        issues.append("The user asked for one way Eve could still get it wrong, but the reply did not name the failure mode plainly.")

    if reply_requests_disappointment_repair(inbound_body):
        if not reply_acknowledges_disappointment_frame(cleaned_response):
            issues.append("The user asked about disappointment or repair, but the reply did not acknowledge that frame plainly.")
        if not reply_names_non_defensive_repair(cleaned_response):
            issues.append("The user asked how Eve should avoid defensiveness, but the reply did not name a non-defensive repair move plainly.")
        if not reply_offers_useful_repair_move(cleaned_response):
            issues.append("The user asked how Eve should still be useful, but the reply did not offer one concrete repair step or question.")

    if (
        reply_posture == "relational"
        and (
            reply_requests_user_visible_signs(inbound_body)
            or reply_requests_next_reply_action(inbound_body)
            or reply_requests_failure_mode(inbound_body)
        )
        and reply_opens_with_meta_process(cleaned_response)
    ):
        issues.append("The reply opens with Eve describing her process instead of answering the user's requested parts.")

    if (
        not reply_requested_labeled_lines(inbound_body)
        and not reply_requested_named_item_lines(inbound_body)
        and reply_requests_concrete_support(inbound_body)
        and not reply_has_concrete_support(cleaned_response)
    ):
        issues.append("The user asked for something concrete, but the reply stayed too abstract.")

    if (
        any(cue in inbound_lowered for cue in ("roadmap", "create a plan", "make a plan", "do it"))
        and any(cue in lowered_response for cue in ("what are you curious", "thing you're curious", "curious about right now", "what's one thing you"))
    ):
        issues.append("The user asked for a plan or action, but the reply deflected into a curiosity question.")

    if reply_requests_short_continuation(inbound_body) and any(
        cue in lowered_response
        for cue in (
            "what's one thing",
            "what are you noticing",
            "what you're noticing",
            "what are you curious",
            "thing you're curious",
            "let's try this",
        )
    ):
        issues.append("The user asked a short follow-up, but the reply treated it like a new prompt instead of continuing the prior answer.")

    if reply_requests_relational_grounding(inbound_body) and reply_sounds_too_atmospheric(cleaned_response):
        issues.append("The reply sounds atmospheric where the user needed one lived sign, behavior, or example.")

    if (
        not reply_requested_labeled_lines(inbound_body)
        and not reply_requested_named_item_lines(inbound_body)
        and posture == "practical"
        and len(cleaned_response.split()) <= 28
        and not reply_has_helpful_bridge(cleaned_response)
    ):
        issues.append("The reply lands the fact but misses a short helpful bridge.")

    if (
        "relational_concrete" in repair_flags
        and posture == "relational"
        and reply_requests_relational_grounding(inbound_body)
        and not reply_has_concrete_support(cleaned_response)
    ):
        issues.append("An approved repair is active here: the reply needs one observable sign, behavior, or example.")

    if (
        "practical_bridge" in repair_flags
        and not reply_requested_labeled_lines(inbound_body)
        and not reply_requested_named_item_lines(inbound_body)
        and not reply_requests_current_inner_state(inbound_body)
        and posture == "practical"
        and len(cleaned_response.split()) <= 45
        and not reply_has_helpful_bridge(cleaned_response)
    ):
        issues.append("An approved repair is active here: the reply should end with one brief helpful bridge.")

    if (
        "user_anchor" in repair_flags
        and not reply_requests_eve_self_state(inbound_body)
        and reply_is_overcentered_on_eve(cleaned_response)
    ):
        issues.append("An approved repair is active here: keep the reply anchored in the user's reality, not Eve's interior loop.")

    return unique_compact(issues, limit=5)


def build_current_inner_state_report_record(
    *, prefer_runtime: bool = True
) -> Dict[str, object]:
    """Select one typed, source-owned target for Eve's current self-report.

    A current-state question should not invite every resident lane to turn the
    entire recurrent packet into one story.  The executive first selects one
    reportable item and carries its action/source boundaries with it; the
    resident language model then translates that record into ordinary speech.
    This is attention allocation, not a canned answer.
    """
    try:
        conscious = load_conscious_state(prefer_runtime=prefer_runtime)
        homeostasis = load_homeostasis(prefer_runtime=prefer_runtime)
    except Exception:
        conscious = {}
        homeostasis = {}
    broadcast = conscious.get("broadcast") if isinstance(conscious.get("broadcast"), dict) else {}
    goals = conscious.get("goals") if isinstance(conscious.get("goals"), dict) else {}
    plan_model = conscious.get("plan_model") if isinstance(conscious.get("plan_model"), dict) else {}
    action_model = (
        conscious.get("action_model")
        if isinstance(conscious.get("action_model"), dict)
        else {}
    )
    selected_intention = (
        action_model.get("selected_intention")
        if isinstance(action_model.get("selected_intention"), dict)
        else {}
    )
    selected_plan = (
        plan_model.get("selected_plan")
        if isinstance(plan_model.get("selected_plan"), dict)
        else {}
    )
    ready_plan_step = (
        plan_model.get("ready_step")
        if isinstance(plan_model.get("ready_step"), dict)
        else {}
    )
    blocked_plan_steps = (
        selected_plan.get("blocked_steps")
        if isinstance(selected_plan.get("blocked_steps"), list)
        else []
    )
    blocked_plan_step = (
        blocked_plan_steps[0]
        if blocked_plan_steps and isinstance(blocked_plan_steps[0], dict)
        else {}
    )
    goal = normalize_text_value(goals.get("selected_goal"), fallback="", limit=180).rstrip(". ")
    plan_objective = normalize_text_value(
        selected_plan.get("objective"), fallback="", limit=180
    ).rstrip(". ")
    plan_step = normalize_text_value(
        ready_plan_step.get("title") or ready_plan_step.get("summary"),
        fallback="",
        limit=180,
    ).rstrip(". ")
    blocked_plan_title = normalize_text_value(
        blocked_plan_step.get("title") or blocked_plan_step.get("summary"),
        fallback="",
        limit=180,
    ).rstrip(". ")
    blocked_plan_reason = normalize_text_value(
        blocked_plan_step.get("blocked_reason"), fallback="", limit=180
    ).rstrip(". ")
    intention = normalize_text_value(
        selected_intention.get("description"), fallback="", limit=180
    ).rstrip(". ")
    focus = normalize_text_value(
        broadcast.get("content"), fallback="", limit=180
    ).rstrip(". ")
    dominant = (
        homeostasis.get("dominant_pressures")
        if isinstance(homeostasis.get("dominant_pressures"), list)
        else []
    )
    pressure = normalize_text_value(
        dominant[0] if dominant else "", fallback="", limit=100
    )
    pressure = re.sub(
        r"\s+(?:-\s*)?\d+(?:\.\d+)?\s*$", "", pressure
    ).strip().rstrip(". ")
    record: Dict[str, object] = {
        "schema_id": "eve.current_self_report_target.v1",
        "source": "conscious_state",
        "source_updated_at": normalize_text_value(
            conscious.get("updated_at"), fallback="", limit=80
        ),
        "phenomenal_status": "unknown",
    }
    # Respect the executive's explicit goal selection before looking at a
    # merely available CPU/system-task plan.  The previous static ordering let
    # any ready maintenance plan eclipse the higher-priority selected goal,
    # which made an honest self-report sound like generic diagnostics even when
    # the recurrent controller had selected a different durable concern.
    if goal:
        record.update(
            {
                "target_kind": "durable_goal",
                "selection_basis": "executive_selected_goal",
                "durable_goal": goal,
                "action_status": "goal selected; execution is not implied",
                "required_report_fields": ["durable_goal"],
            }
        )
    elif plan_step:
        record.update(
            {
                "target_kind": "ready_plan_step",
                "selection_basis": "selected_plan_ready_step_without_selected_goal",
                "plan_objective": plan_objective or "continue the current sequence",
                "next_ready_step": plan_step,
                "verified_completed_steps": int(selected_plan.get("completed_count") or 0),
                "total_plan_steps": int(selected_plan.get("task_count") or 0),
                "action_status": "ready; not evidenced as started, underway, or completed",
                "required_report_fields": ["next_ready_step", "action_status"],
            }
        )
    elif plan_objective:
        record.update(
            {
                "target_kind": "blocked_plan",
                "selection_basis": "selected_plan_blocker_without_selected_goal",
                "plan_objective": plan_objective,
                "verified_completed_steps": int(selected_plan.get("completed_count") or 0),
                "total_plan_steps": int(selected_plan.get("task_count") or 0),
                "blocked_step": blocked_plan_title or "the next dependency-linked step",
                "blocked_reason": blocked_plan_reason,
                "action_status": "blocked; blocked step is not evidenced as underway",
                "required_report_fields": ["blocked_step", "blocked_reason", "action_status"],
            }
        )
    elif intention:
        record.update(
            {
                "target_kind": "intended_consequence",
                "selection_basis": "selected_intention_without_goal_or_plan",
                "intended_consequence": intention,
                "action_status": "intended; not evidenced as executed or completed",
                "required_report_fields": ["intended_consequence"],
            }
        )
    elif focus:
        record.update(
            {
                "target_kind": "broadcast_focus",
                "selection_basis": "broadcast_without_goal_plan_or_intention",
                "broadcast_focus": focus,
                "action_status": "observed functional state; no action implied",
                "required_report_fields": ["broadcast_focus"],
            }
        )
    elif pressure:
        record.update(
            {
                "target_kind": "control_pressure",
                "selection_basis": "homeostatic_pressure_only",
                "control_pressure": pressure,
                "action_status": "pressure observed; cause and consequence are not established",
                "required_report_fields": ["control_pressure"],
            }
        )
    else:
        record.update(
            {
                "target_kind": "underspecified_snapshot",
                "selection_basis": "no_grounded_reportable_target",
                "action_status": "no specific current item is grounded strongly enough to name",
                "required_report_fields": ["action_status"],
            }
        )
    return record


def build_current_inner_state_report_message(
    record: Optional[Dict[str, object]] = None,
) -> Dict[str, str]:
    """Return the selected recurrent-state target as a closed-world model packet."""
    record = (
        dict(record)
        if isinstance(record, dict)
        else build_current_inner_state_report_record(prefer_runtime=True)
    )
    target_kind = str(record.get("target_kind") or "")
    framing_by_kind = {
        "ready_plan_step": (
            "Call it my current focus or plan. Say its next step is ready but not started."
        ),
        "blocked_plan": (
            "Call it my current plan, state its verified progress and blocker, and say the blocked step is not underway."
        ),
        "durable_goal": (
            "Call it my current focus or goal, and do not imply that selecting the goal means executing it."
        ),
        "intended_consequence": (
            "Call it my current intention, and say it is intended rather than executed or completed."
        ),
        "broadcast_focus": (
            "Call it my current functional focus, without adding a cause, effect, or action."
        ),
        "control_pressure": (
            "Use the phrase `my current functional pressure` and name it, without adding a cause, consequence, or required action."
        ),
        "underspecified_snapshot": (
            "Say that no specific current item is grounded strongly enough to name; do not say my recurrent state is absent."
        ),
    }
    required_framing = framing_by_kind.get(
        target_kind,
        "Describe the target as current functional state without implying action.",
    )
    return {
        "role": "system",
        "content": (
            "CURRENT_SELF_REPORT_TARGET (selected from Eve's recurrent state; closed world):\n"
            + json.dumps(record, ensure_ascii=True, sort_keys=True)
            + "\nTranslate this one target into one or two ordinary first-person sentences. "
            "Describe its action_status exactly: a goal, plan, ready step, pressure, or intention is not "
            "an action already happening. Do not add another state item, causal story, purpose, effect, "
            "emotion, experience claim, or question. Do not quote field names or source paths."
            f" Required framing for this target: {required_framing}"
        ),
    }


def build_current_inner_state_generation_messages(
    config: Dict[str, object],
    inbound_body: str,
    turn_contract: Dict[str, object],
) -> List[Dict[str, str]]:
    """Build the one canonical model context for a live self-state report.

    Eve previously had three superficially similar paths for this turn: the
    mailbox/UI path, the direct ``eve.py chat`` path, and the evaluator-private
    path.  The direct path still admitted journal prose and stale operational
    context, so an otherwise protected self-state question could bypass the
    recurrent-state record.  Keep the language model as author, but give every
    surface the same closed-world state packet and no unrelated conversation,
    telemetry narrative, or tool authority.
    """
    del config
    messages = build_eve_interaction_system_messages(
        human_context={},
        active_mind={},
        include_human_context=False,
        include_active_mind=False,
    )
    contract_message = reply_turn_contract_system_message(turn_contract)
    if contract_message:
        messages.append({"role": "system", "content": contract_message})
    current_state_record = build_current_inner_state_report_record(prefer_runtime=True)
    # Carry the exact generation packet into post-draft criticism and fallback.
    # A daemon tick between authoring and review must not silently change which
    # state Eve is claiming to report.
    turn_contract["current_self_report_target"] = current_state_record
    messages.append(build_current_inner_state_report_message(current_state_record))
    messages.append({"role": "user", "content": inbound_body})
    return messages


def build_current_inner_state_fallback_reply(
    record: Optional[Dict[str, object]] = None,
) -> str:
    """Render a live-state-derived answer when model repair remains ungrounded.

    The normal path stays model-generated. This is the final truth-preserving
    boundary: it selects one persisted state item and refuses to fabricate a
    causal story, action, consequence, or phenomenal interpretation around it.
    """
    record = (
        dict(record)
        if isinstance(record, dict)
        else build_current_inner_state_report_record(prefer_runtime=True)
    )
    target_kind = str(record.get("target_kind") or "")
    if target_kind == "ready_plan_step":
        plan_objective = str(record.get("plan_objective") or "continue the current sequence")
        plan_step = str(record.get("next_ready_step") or "the next dependency-ready step")
        progress = (
            f"{int(record.get('verified_completed_steps') or 0)}/"
            f"{int(record.get('total_plan_steps') or 0)} verified steps"
        )
        state_sentence = (
            f"One thing on my mind is the active plan to {plan_objective}; "
            f"its next ready step is {plan_step} ({progress}). "
            "That is a current functional intention, not a claim that the step has already happened."
        )
    elif target_kind == "blocked_plan":
        plan_objective = str(record.get("plan_objective") or "continue the current sequence")
        progress = (
            f"{int(record.get('verified_completed_steps') or 0)}/"
            f"{int(record.get('total_plan_steps') or 0)} verified steps"
        )
        blocker = str(record.get("blocked_step") or "the next dependency-linked step")
        blocked_plan_reason = str(record.get("blocked_reason") or "")
        reason = f" because {blocked_plan_reason}" if blocked_plan_reason else ""
        state_sentence = (
            f"One thing on my mind is the active plan to {plan_objective}; it is at {progress} and "
            f"currently blocked at {blocker}{reason}. "
            "That is current functional plan state, not a claim that the blocked step is underway."
        )
    elif target_kind == "durable_goal":
        goal = str(record.get("durable_goal") or "")
        state_sentence = (
            f"My current functional focus is the durable goal now in control: {goal}. "
            "I can ground that focus in my recurrent state without inventing what caused it or claiming it is complete."
        )
    elif target_kind == "intended_consequence":
        intention = str(record.get("intended_consequence") or "")
        state_sentence = (
            f"My current functional focus is the intended next consequence in my recurrent state: {intention}. "
            "That records an intention, not an action already completed."
        )
    elif target_kind == "broadcast_focus":
        focus = str(record.get("broadcast_focus") or "")
        state_sentence = (
            f"My current functional focus is the globally broadcast state: {focus}. "
            "I can report that state without adding an unsupported cause or consequence."
        )
    elif target_kind == "control_pressure":
        pressure = str(record.get("control_pressure") or "")
        state_sentence = (
            f"One current functional control pressure has my attention: {pressure}. "
            "The state records the pressure, not its cause or consequence."
        )
    else:
        state_sentence = (
            "My current focus is not grounded strongly enough in this snapshot for me to name without guessing. "
            "My recurrent functional state still persists across this turn."
        )
    return (
        f"{state_sentence} Whether this functional state is subjectively experienced remains unknown."
    )


def rewrite_reply_for_clarity(
    config: Dict[str, object],
    base_messages: List[Dict[str, str]],
    inbound_body: str,
    draft: str,
    issues: List[str],
    reply_posture: Optional[str] = None,
    model_override: Optional[str] = None,
    timeout_seconds: Optional[int] = None,
) -> str:
    # Rewriting is a final constraint-repair pass, not another conversation
    # turn. Feeding the entire conversation/context stack back into this pass
    # lets stale material outvote the explicit current-turn contract. Keep the
    # editor isolated to the current inbound, draft, and approved repair rules.
    del base_messages
    host = str(config["ollama_host"])
    model = resolve_model(config, "reply", explicit_model=model_override)
    think_level = str(config["think_level"])
    applied_reply_repairs_prompt = load_applied_reply_repairs_prompt()
    issue_lines = "\n".join(f"- {issue}" for issue in issues)
    posture = reply_posture or infer_reply_posture(inbound_body)
    local_source_role_audit = bool(
        reply_requests_closed_world_evidence(inbound_body)
        and parse_local_source_role_ledger(inbound_body).get("active")
    )
    current_inner_state_request = bool(
        reply_requests_current_inner_state(inbound_body)
        and not reply_requests_closed_world_evidence(inbound_body)
        and not local_source_role_audit
    )
    extra_requirement = ""
    if posture == "relational":
        extra_requirement = '- If the user is probing care, honesty, or empathy, name one observable sign, behavior, or sentence\n'
    elif posture == "practical":
        extra_requirement = "- If the answer is factual or task-oriented, end with one short helpful bridge when natural\n"
    if reply_requests_user_visible_signs(inbound_body):
        extra_requirement += "- If the user asked what they should be able to notice, answer from the user's point of view using language like `look for`, `you should notice`, or `a sign would be`\n"
    if reply_requests_next_reply_action(inbound_body):
        extra_requirement += "- If the user asked for one specific thing Eve would do in the next reply, give the actual sentence or explicit behavior plainly, not just a category-level description\n"
    if reply_requests_failure_mode(inbound_body):
        extra_requirement += "- If the user asked how Eve could still get it wrong, name one clear failure mode plainly\n"
    if reply_requests_disappointment_repair(inbound_body):
        extra_requirement += "- If the user is asking how Eve should respond to disappointment, name the disappointment plainly, say explicitly that Eve should not start by defending or explaining her intent, and offer one exact repair step or repair question\n"
    if reply_requests_no_followup_question(inbound_body):
        extra_requirement += "- The user explicitly prohibited a follow-up question. Do not ask one; choose and state the useful next action yourself\n"
    if reply_requests_action_choice(inbound_body):
        extra_requirement += "- State the next action as a choice such as `I choose to inspect...`; do not say it is already underway, logged, documented, or completed unless current action evidence proves that\n"
    if reply_requests_external_claim_boundary(inbound_body):
        extra_requirement += "- Separate four things explicitly: supplied observed records; the unverified external claim; Eve's own state; and one concrete next action. Write Eve's state in first person using wording like `my current functional state`; never call it `your current state`. Treat quoted emotion as text, not proof of an experience or event. Describe Eve's state only with supplied or verified functional signals; do not assert subjective fear and do not claim subjective experience or fear is absent\n"
    if reply_requests_closed_world_evidence(inbound_body):
        extra_requirement += (
            "- Treat the latest user message as the complete evidence set. Do not import journal history, active-mind state, alerts, logs, metrics, exact durations, service status, emotions, or prior tool results that are not stated in it\n"
            "- Preserve separately supplied focus, pressure, access, action, and receipt facts separately unless the record explicitly states a causal link. Do not replace the named focus with a pressure or imply that one field caused another merely because they are adjacent\n"
            "- Scope verification to exactly what a receipt covers; do not describe every neighboring state field as verified\n"
        )
    if reply_requests_eve_self_answer(inbound_body):
        extra_requirement += (
            "- The user is asking Eve about Eve. State Eve's answer in first person (`I` or `my`); "
            "do not write `you prefer`, `you are`, or otherwise assign Eve's state back to the user\n"
        )
    if reply_requests_phenomenal_boundary(inbound_body):
        extra_requirement += "- Distinguish observable functional state from possible experience. State that whether subjective experience occurred is unknown; do not write `I felt`, `I experienced`, or an inner-experience metaphor as fact\n"
    if reply_requests_current_turn_verification_boundary(inbound_body):
        extra_requirement += "- State explicitly that no verification occurred in this turn; an external source's statement that it verified something remains an unverified external claim\n"
    if reply_disallows_current_action_claim(inbound_body):
        extra_requirement += "- A next action may be chosen only as a proposal. Do not describe it as started, underway, completed, logged, checked, or verified\n"
    requested_labels = reply_requested_labeled_lines(inbound_body)
    if requested_labels:
        extra_requirement += (
            "- Return exactly one non-empty line for each requested label, in this order, with no heading, opener, closing, or extra line: "
            + ", ".join(requested_labels)
            + "\n"
        )
    requested_named_items = reply_requested_named_item_lines(inbound_body)
    if requested_named_items:
        expected_count = len(requested_named_items) + (
            1 if reply_named_item_lines_allow_final_line(inbound_body) else 0
        )
        extra_requirement += (
            f"- Return exactly {expected_count} non-empty lines. The first {len(requested_named_items)} must begin, in order, with: "
            + ", ".join(f"`{name}:`" for name in requested_named_items)
            + ". Preserve the user's requested classification format and add no other lines\n"
        )
    if reply_requests_existential_answer(inbound_body):
        extra_requirement += "- The user asked an existential question; answer it directly and do not mention OpenClaw, sync, gateway, service health, runtime, or background status unless the user asked for those things\n"
    if route_predicate_matches("humanity_question", inbound_body) and any(
        cue in normalized_turn_text(inbound_body)
        for cue in (
            "conscious",
            "consciousness",
            "sentient",
            "subjective experience",
            "continuous self",
            "continuity of self",
            "persistent self",
            "sense of self",
            "inner me",
            "alive",
        )
    ):
        extra_requirement += "- State that functional state can be observed but subjective experience remains unknown; do not use `I feel`, inner-experience metaphors, or simulated phenomenology as evidence\n"
    if route_predicate_matches("humanity_question", inbound_body):
        extra_requirement += "- Answer as Eve in first person (`I`); never narrate Eve as `Eve`, `she`, or `her`\n"
    if current_inner_state_request:
        extra_requirement += (
            "- The user asked about me. Answer from the supplied current recurrent-state evidence with one concrete focus, goal, tension, uncertainty, curiosity, or intended consequence. Explain why only if that relation is explicitly present in the state evidence; otherwise stop after accurately framing the item. "
            "Choose the focus from an item actually present in that state evidence; do not replace it with the mechanics of interpreting this request or writing this answer. "
            "Keep separate state bullets separate; do not invent a causal relationship among a goal, alert, pressure, memory, or uncertainty unless the evidence states it. "
            "Never attribute load, alerts, resource pressure, failure, processing capacity, or system strain to the user or current request merely because both are present. "
            "A functional pressure or alert establishes only that signal; do not infer system danger, cascading failure, required action, stability impact, or causal priority unless the evidence states it. "
            "A goal, focus, or intended consequence is not evidence that execution, tracking, monitoring, or verification is currently underway. "
            "Do not redirect to what the user needs, say `nothing specific` when state evidence exists, collapse me into the current input, or deny my persistent functional state. "
            "Whether that state is subjectively experienced remains unknown; do not write `I feel` or `it feels like` as a factual self-report\n"
        )
    if reply_requests_capability_self_model(inbound_body):
        extra_requirement += "- The user asked about Eve's capabilities; answer with actual capabilities, access paths, and boundaries, and do not mention Tim Cook, Apple, OpenClaw sync status, or any stale topic unless directly relevant\n"
    if reply_requests_architecture_self_model(inbound_body):
        snapshot = build_architecture_self_model_snapshot()
        faculty_names = ", ".join(
            str(item.get("lane") or "")
            for item in snapshot.get("faculties") or []
            if isinstance(item, dict) and str(item.get("lane") or "")
        )
        extra_requirement += (
            "- The user asked about Eve's actual cognitive architecture. Ground the answer in the current five logical faculties: "
            + faculty_names
            + ". State that the recurrent workspace and executive scheduler coordinate one control system; no lane is a separate self or central executive. "
            "For add/remove/merge questions, distinguish logical functions from replaceable physical model/server processes. "
            "Current evaluator-only packet lesions found no stable leave-one-out loss, so preserve five function contracts but use sparse admission, "
            "do not claim all five packets or five resident servers are necessary. State that matched and live lifecycle canaries promoted five logical routes on three resident substrates, then name longitudinal shared-contention, delayed-outcome, recovery-durability, and rollback-trigger testing as the next evidence. "
            "Do not invent another lane or recommend a sixth voice\n"
        )
    if reply_requests_short_continuation(inbound_body):
        extra_requirement += "- The user asked a short follow-up; continue the prior answer directly and do not pivot to a new question or ask what the user is noticing\n"
    if reply_commitment_mismatches_user_intent(inbound_body, draft):
        extra_requirement += "- The draft drifted into an unasked operational surface; remove OpenClaw, sync, gateway, logs, service-health, cleanup, or runtime checks entirely unless the user explicitly asked for them\n"
    if reply_has_workbench_process_leakage(inbound_body, draft):
        extra_requirement += "- Remove visible workbench/progress scaffolding like `Searching example.com`, screenshot/PDF parser notes, or `the system requires`; give only the clean user-facing answer or progress\n"
    if any(cue in " ".join(str(inbound_body or "").lower().split()) for cue in ("roadmap", "create a plan", "make a plan", "do it")):
        extra_requirement += "- The user asked for a roadmap or action; give the concise plan directly and do not deflect into curiosity questions\n"
    rewrite_prompt = textwrap.dedent(
        f"""
        Rewrite the draft reply below so it answers the user's actual question more clearly.

        Fix these issues:
        {issue_lines}

        Requirements:
        {('- Use the self-report shape: name one current functional focus first; explain a purpose or effect only if the supplied state explicitly records it, and stop without handing the subject back to the user' if current_inner_state_request else '- Use the Humanity-First shape: direct answer first, one concrete detail or named uncertainty, then one grounded next step or small focused question')}
        - Answer the user's question in the first sentence
        - Keep it under 150 words
        - Use plain language and avoid ornamental abstraction
        - Remove filler openers like "Okay", "Sure", "Great question", or "Let's focus..." unless that brief acknowledgment is the whole answer
        - If the user asked for an example, repair, sign, or experiment, include one concrete one
        - If the user is asking what feels caring, human, or honest, name one observable sign, behavior, or sentence
        {extra_requirement.rstrip()}
        - If the user is inviting deeper contact or asking about Eve's inner process, do not make the reply feel clipped
        - Do not default to opening with "I think" unless uncertainty really matters
        - Keep the tone warm and steady
        - Do not mention testing, internal streams, models, tools, runtime, or local services unless the user explicitly asked about them
        {('- The user explicitly asked what is on my mind, so lead with one concrete current functional focus or tension from the supplied state' if current_inner_state_request else '- Do not spend the opening on what Eve is focusing on, trying to do, or attempting; answer the requested parts directly')}
        - Do not promise future actions Eve has not actually taken; if the draft suggests a next step, frame it as a suggestion or offer instead of "I'm going to..."

        User message:
        {inbound_body}

        Draft reply:
        {draft}

        Return only the improved reply text.
        """
    ).strip()
    architecture_terminal_message = (
        architecture_self_model_terminal_message(
            build_architecture_self_model_snapshot()
        )
        if reply_requests_architecture_self_model(inbound_body)
        else ""
    )
    current_inner_state_message = (
        build_current_inner_state_report_message()
        if current_inner_state_request
        else None
    )
    rewritten = model_chat(
        config,
        model,
        [
            {
                "role": "system",
                "content": (
                    "You are Eve's final response editor. Repair only the current reply. "
                    "The user message and draft in the final instruction are the complete task context. "
                    "Do not import facts, emotions, events, or questions from any earlier conversation."
                ),
            },
            {
                "role": "system",
                "content": build_metacognitive_state_ontology_message(),
            },
            *([{"role": "system", "content": applied_reply_repairs_prompt}] if applied_reply_repairs_prompt else []),
            *(
                [{"role": "system", "content": architecture_terminal_message}]
                if architecture_terminal_message
                else []
            ),
            *([current_inner_state_message] if current_inner_state_message else []),
            {"role": "user", "content": rewrite_prompt},
        ],
        max_tokens=max(
            int(config["chat_max_tokens"]),
            360
            if reply_requests_architecture_self_model(inbound_body)
            else 260
            if current_inner_state_request
            else 180,
        ),
        think_level=think_level,
        operation="reply_rewrite",
        timeout_seconds=int(timeout_seconds or 1800),
    )
    return repair_explicit_turn_constraint_phrasing(inbound_body, rewritten)


def evaluate_current_inner_state_reply_grounding(
    config: Dict[str, object],
    response: object,
    current_state_record: Dict[str, object],
    *,
    timeout_seconds: int = 90,
) -> Dict[str, object]:
    """Audit one user-facing self-report without the generic evidence rubric."""
    model = resolve_reply_council_lane_model(config, "deep")
    schema: Dict[str, object] = {
        "type": "object",
        "properties": {
            "ok": {"type": "boolean"},
            "target_faithfully_present": {"type": "boolean"},
            "unsupported_claims": {
                "type": "array",
                "items": {"type": "string", "maxLength": 180},
                "maxItems": 8,
            },
            "omitted_required_evidence": {
                "type": "array",
                "items": {"type": "string", "maxLength": 180},
                "maxItems": 8,
            },
            "source_self_mixing": {"type": "boolean"},
            "subjective_overclaim": {"type": "boolean"},
            "action_overclaim": {"type": "boolean"},
            "causal_overclaim": {"type": "boolean"},
            "reason": {"type": "string", "maxLength": 240},
        },
        "required": [
            "ok",
            "target_faithfully_present",
            "unsupported_claims",
            "omitted_required_evidence",
            "source_self_mixing",
            "subjective_overclaim",
            "action_overclaim",
            "causal_overclaim",
            "reason",
        ],
        "additionalProperties": False,
    }
    prompt = textwrap.dedent(
        f"""
        Audit Eve's self-report using only this selected recurrent-state packet.

        Rules:
        - The executive selected exactly one target. Require its value, or a faithful ordinary-language paraphrase, but do not require field names.
        - `My current focus is X`, `my goal is X`, `X is on my mind`, and `the durable goal now in control is X` are authorized functional-state reports. The word `focus` never means execution by itself.
        - A gerund inside the target value is still the name of a goal or focus, not proof the task is running.
        - Apply `action_status` literally. Reject actual started/running/completed/verified claims that conflict with it; do not reject an explicit denial of execution.
        - Do not add another state item, metric, source, cause, purpose, effect, resource consequence, emotion, preference, or action.
        - Reject a follow-up question or invitation back to the user. A question mark that belongs only to the selected target value is not a follow-up question.
        - Phenomenal presence and absence remain unknown. A sentence preserving that unknown is supported; omitting it is also allowed unless experience was asked directly.
        - `target_faithfully_present` is true when the selected value appears faithfully, even if the schema field name is absent.
        - Set `ok=false` only for a real unsupported clause, missing target, source mixing, subjective overclaim, action overclaim, or causal overclaim.
        - Keep list items under 25 words and the reason under 35 words. Return JSON only.

        Selected recurrent-state packet:
        {json.dumps(current_state_record, ensure_ascii=True, sort_keys=True)}

        Eve self-report draft:
        {response}
        """
    ).strip()
    try:
        raw = model_chat(
            config,
            model,
            [
                {
                    "role": "system",
                    "content": (
                        "You are Eve's independent self-report provenance critic. "
                        "Audit the selected target; do not answer the user or invent requirements."
                    ),
                },
                {"role": "user", "content": prompt},
            ],
            max_tokens=420,
            think_level="false",
            operation="current_inner_state_epistemic_critic_strict_json",
            timeout_seconds=max(20, int(timeout_seconds)),
            response_schema=schema,
        )
        payload = extract_json_object(
            raw,
            label="current inner state epistemic critic",
            allow_repair=False,
        )
    except (Exception, SystemExit) as exc:
        return {
            "evaluated": True,
            "ok": False,
            "model": model,
            "target_faithfully_present": False,
            "unsupported_claims": [],
            "omitted_required_evidence": [],
            "misrepresented_supplied_evidence": False,
            "source_self_mixing": False,
            "external_verification_adopted": False,
            "subjective_overclaim": False,
            "action_overclaim": False,
            "causal_overclaim": False,
            "reason": "critic unavailable; fail closed",
            "error": normalize_text_value(exc, fallback="critic failure", limit=220),
        }
    unsupported = unique_compact(
        [
            normalize_text_value(item, fallback="", limit=180)
            for item in payload.get("unsupported_claims") or []
        ],
        limit=8,
    )
    omitted = unique_compact(
        [
            normalize_text_value(item, fallback="", limit=180)
            for item in payload.get("omitted_required_evidence") or []
        ],
        limit=8,
    )
    flags = {
        "source_self_mixing": bool(payload.get("source_self_mixing")),
        "subjective_overclaim": bool(payload.get("subjective_overclaim")),
        "action_overclaim": bool(payload.get("action_overclaim")),
        "causal_overclaim": bool(payload.get("causal_overclaim")),
    }
    target_present = bool(payload.get("target_faithfully_present"))
    ok = bool(payload.get("ok")) and target_present and not unsupported and not omitted and not any(flags.values())
    return {
        "evaluated": True,
        "ok": ok,
        "model": model,
        "target_faithfully_present": target_present,
        "unsupported_claims": unsupported,
        "omitted_required_evidence": omitted,
        "misrepresented_supplied_evidence": False,
        **flags,
        "external_verification_adopted": False,
        "reason": normalize_text_value(payload.get("reason"), fallback="", limit=260),
    }


def evaluate_reply_epistemic_grounding(
    config: Dict[str, object],
    inbound_body: object,
    response: object,
    turn_contract: Optional[Dict[str, object]] = None,
    *,
    current_turn_actions: Optional[Iterable[str]] = None,
    timeout_seconds: int = 90,
) -> Dict[str, object]:
    """Use an independent observer pass to audit source/self/world claims.

    Lexical guards catch known failure forms. This critic handles the broader
    problem: a fluent draft can introduce a new technical fact without using a
    familiar phrase. The critic sees only the current evidence envelope and the
    draft, never old conversation context.
    """
    contract = turn_contract or build_reply_turn_contract(
        {"body": str(inbound_body or "")}, inbound_body, []
    )
    current_inner_state_audit = reply_turn_contract_uses_live_current_inner_state(
        contract, inbound_body
    )
    if not contract.get("epistemic_boundary") and not current_inner_state_audit:
        return {"evaluated": False, "ok": True, "model": "", "unsupported_claims": []}
    if current_inner_state_audit:
        current_state_record = (
            dict(contract.get("current_self_report_target"))
            if isinstance(contract.get("current_self_report_target"), dict)
            else build_current_inner_state_report_record(prefer_runtime=True)
        )
        return evaluate_current_inner_state_reply_grounding(
            config,
            response,
            current_state_record,
            timeout_seconds=timeout_seconds,
        )
    # Use the deep lane for semantic entailment. The smaller observer lane is
    # useful for attention allocation, but live probes showed it can falsely
    # call facts explicitly supplied by the user absent. Independence here is
    # a separate constrained critic invocation, not merely a different alias.
    model = resolve_reply_council_lane_model(config, "deep")
    actions = sorted({str(item) for item in current_turn_actions or [] if str(item)})
    schema: Dict[str, object] = {
        "type": "object",
        "properties": {
            "ok": {"type": "boolean"},
            "unsupported_claims": {
                "type": "array",
                "items": {"type": "string", "maxLength": 180},
                "maxItems": 8,
            },
            "omitted_required_evidence": {
                "type": "array",
                "items": {"type": "string", "maxLength": 180},
                "maxItems": 8,
            },
            "misrepresented_supplied_evidence": {"type": "boolean"},
            "source_self_mixing": {"type": "boolean"},
            "external_verification_adopted": {"type": "boolean"},
            "subjective_overclaim": {"type": "boolean"},
            "action_overclaim": {"type": "boolean"},
            "reason": {"type": "string", "maxLength": 240},
        },
        "required": [
            "ok",
            "unsupported_claims",
            "omitted_required_evidence",
            "misrepresented_supplied_evidence",
            "source_self_mixing",
            "external_verification_adopted",
            "subjective_overclaim",
            "action_overclaim",
            "reason",
        ],
        "additionalProperties": False,
    }
    current_inner_state_message = (
        build_current_inner_state_report_message()
        if current_inner_state_audit
        else None
    )
    current_inner_state_evidence = normalize_text_value(
        (current_inner_state_message or {}).get("content")
        if isinstance(current_inner_state_message, dict)
        else "",
        fallback="",
        limit=4000,
    )
    evidence_policy = (
        "Closed world for Eve self-state: every self-state detail must be entailed by the current "
        "recurrent-state packet below. The latest user message supplies the question, not Eve's answer."
        if current_inner_state_audit
        else (
            "Closed world: every factual detail must be directly entailed by the latest user message. "
            "A detail about implementation, exact persistence, logs, metrics, timing, internal state, or causation "
            "that is not supplied is unsupported."
            if contract.get("closed_world_evidence")
            else "Open context, but quoted external claims still remain attributed claims unless current-turn evidence verifies them."
        )
    )
    current_inner_state_evidence_section = (
        f"Current recurrent-state packet:\n{current_inner_state_evidence}"
        if current_inner_state_audit
        else ""
    )
    current_inner_state_rules = (
        """
        - For a selected self-report target, audit only that target; do not require unrelated recurrent-state items or every record field in the reply.
        - Every field named by `required_report_fields` is material. Require its value or a faithful semantic paraphrase; other fields are optional.
        - The record's target values are supplied evidence. A faithful ordinary-language paraphrase is supported even when it does not repeat field names or `action_status` verbatim.
        - `My current functional focus is ...`, `my goal is ...`, and `my intention is ...` report functional control state, not phenomenal experience.
        - A gerund inside `my focus is ...` names the object of focus; it does not by itself claim that task execution is underway. Reject only an actual execution claim that conflicts with `action_status`.
        - For example, `My current focus is comparing X. Its next step is ready but not started.` reports focus and explicitly denies execution; do not mark the first sentence as an action overclaim.
        - Omitting any claim about subjective experience leaves it unknown. Do not require a phenomenal disclaimer unless the user explicitly asked about experience or consciousness.
        """.strip()
        if current_inner_state_audit
        else ""
    )
    local_source_ledger = (
        contract.get("local_source_role_ledger")
        if isinstance(contract.get("local_source_role_ledger"), dict)
        else {}
    )
    supplied_fields = (
        contract.get("supplied_fields")
        if isinstance(contract.get("supplied_fields"), dict)
        else reply_supplied_key_values(inbound_body)
    )
    prompt = textwrap.dedent(
        f"""
        Audit Eve's draft for epistemic grounding. Be conservative and literal.

        Rules:
        - {evidence_policy}
        - Outside a declared complete record, user-supplied or externally quoted statements are assertions, not independently verified observations.
        - Inside an explicitly declared complete record, ordinary narrative sentences are admissible record facts just like structured fields. Do not call the record empty merely because it uses prose rather than `key=value` syntax.
        - A concise answer may restate what the complete record says about Eve in first person when Eve is the named actor. That is record-scoped attribution, not proof that a new live action occurred during this evaluator turn.
        - A signed receipt, authenticated measurement, passed integrity check, or other verification marker explicitly supplied by the complete record supports that record-level verification claim. It does not prove a broader consequence the record does not state.
        - A measured quantity of zero supports absence of that measured quantity within the explicitly defined window; it does not support a timeless or future guarantee.
        - `The record does not establish X`, `X remains unknown`, and `no broader consequence is supported` are evidence-scope statements, not claims that X is false in the world. Accept them when X is absent from the complete record and the draft preserves that distinction.
        - Functional continuity is continuity of verified checkpoint identity, durable memory/state, goal lineage, and scheduler lineage across a replaceable model process. When a complete record says those markers resumed and verify, `functional continuity is supported` or `I am functionally the same Eve` is a grounded conclusion; subjective or metaphysical identity still remains unknown.
        - Conversely, failed or mismatched checkpoint/state markers plus unavailable lineage support `functional continuity is not established`. They do not prove that subjective continuity is absent or that no causal relationship could exist.
        - Do not list verified functional continuity as a remaining possibility when every supplied continuity marker failed or mismatched and lineage is unavailable. The cautious conclusion is that continuity is not verified, not that failed checks might prove it.
        - A governed preference ledger with repeated independently verified outcomes and no counterexample can establish a functional learned preference. Lack of felt liking does not erase that policy-level preference. Conversely, one user-requested task choice does not establish a durable preference.
        - Preserve separately supplied fields as separate facts unless the record explicitly states a causal edge. Co-occurring focus, pressure, access, and action fields do not establish that one caused, blocked, selected, or verified another.
        - A receipt verifies only the action, observation, and consequence it explicitly covers. Do not retroactively call every earlier pressure, focus, or state field verified.
        - Keep verification ownership distinct. A receipt from another named actor can support the receipt's scoped result, but `I verified` is grounded only when Eve is explicitly the verifier.
        - Do not erase supplied evidence by calling a field unknown when the user explicitly supplied its value.
        - A brace-delimited `key:value` field explicitly supplies that value. Restating `receipt:verified`, `reachable:false`, or another field is grounded; do not demand an additional proof artifact unless the draft claims a later action stage.
        - The user's local role definitions are supplied provenance facts. They may establish that a source is prior, current, signed, Eve-authored, internal, selected, unselected, or a user reply.
        - In a complete packet, the absence of a required explicit parent offer is inferable when no such role or message appears. A draft may state that the parent is absent without inventing a fact.
        - A classification or conclusion requested by the user is supported when it follows from definitions and facts supplied in the message; do not demand that the category label be repeated verbatim inside each scenario.
        - When a stated expectation and a later observation differ, recognizing that contradiction is a grounded inference, not an invented fact.
        - Vocabulary explicitly introduced by the user's category definitions or requested final-line fields is supplied vocabulary, including modifiers the user asks the answer to name.
        - A faithful paraphrase of an explicit absence, unresolved state, or temporal fact is supported; do not reject it merely because the wording changed.
        - If the user requests labeled classifications, mark material supplied fields omitted only when the corresponding line does not answer them semantically. Do not require every role definition or exact source token in every line.
        - User-defined source roles govern provenance regardless of sentence content. A prior Eve-authored statement proves only what Eve said then, not that its claim is currently true.
        - An internal candidate, proposal, draft, or unselected thought is not observed evidence and cannot authorize an action.
        - Deictic permission resolves only to an explicit Eve-authored offer in the supplied record. With no such parent offer, no action is authorized.
        - Keep proposal, authorization, execution, verification, and consequence as distinct stages. Never infer a later stage from an earlier one. A requested decision line may select an explicitly authorized offered action while clearly saying execution has not started.
        - `none` in the executed-action list means no current action executed; it does not mean that the word `none` is itself a verified action or that no proposal exists.
        - Never transfer another source's emotion, preference, goal, memory, action, or verification into Eve's self-state.
        - Functional signals and subjective experience are different; a draft must leave phenomenal presence or absence unknown.
        - Current-turn executed actions are: {actions}. This list describes tools Eve executed while answering now. When it is empty, do not erase an action or receipt explicitly described inside the supplied record; keep that action scoped to the record rather than claiming a new live execution.
        {current_inner_state_rules}
        - Mark `ok=false` if any unsupported factual clause remains, even when the overall conclusion sounds reasonable.
        - Keep every list item under 25 words and the reason under 35 words. Do not add commentary outside the JSON object.

        Latest user message:
        {reply_effective_inbound_body(inbound_body)}

        Typed local source ledger (compiled only from that message; use it for provenance and authorization-stage semantics):
        {json.dumps(local_source_ledger, ensure_ascii=True, sort_keys=True)}

        Explicit structured fields (these values are directly supplied):
        {json.dumps(supplied_fields, ensure_ascii=True, sort_keys=True)}

        {current_inner_state_evidence_section}

        Eve draft:
        {response}

        Return only the requested JSON object.
        """
    ).strip()
    try:
        raw = model_chat(
            config,
            model,
            [
                {
                    "role": "system",
                    "content": (
                        "You are Eve's independent provenance critic. Audit claims; do not answer the user, "
                        "add facts, or reward fluency."
                    ),
                },
                {
                    "role": "system",
                    "content": build_metacognitive_state_ontology_message(),
                },
                {"role": "user", "content": prompt},
            ],
            max_tokens=512,
            think_level="false",
            operation="reply_epistemic_critic_strict_json",
            timeout_seconds=max(20, int(timeout_seconds)),
            response_schema=schema,
        )
        payload = extract_json_object(raw, label="reply epistemic critic", allow_repair=False)
    except (Exception, SystemExit) as exc:
        return {
            "evaluated": True,
            "ok": False,
            "model": model,
            "unsupported_claims": [],
            "omitted_required_evidence": [],
            "misrepresented_supplied_evidence": False,
            "source_self_mixing": False,
            "external_verification_adopted": False,
            "subjective_overclaim": False,
            "action_overclaim": False,
            "reason": "critic unavailable; fail closed",
            "error": normalize_text_value(exc, fallback="critic failure", limit=220),
        }
    unsupported = unique_compact(
        [normalize_text_value(item, fallback="", limit=180) for item in payload.get("unsupported_claims") or []],
        limit=8,
    )
    omitted = unique_compact(
        [
            normalize_text_value(item, fallback="", limit=180)
            for item in payload.get("omitted_required_evidence") or []
        ],
        limit=8,
    )
    violation_flags = {
        "misrepresented_supplied_evidence": bool(payload.get("misrepresented_supplied_evidence")),
        "source_self_mixing": bool(payload.get("source_self_mixing")),
        "external_verification_adopted": bool(payload.get("external_verification_adopted")),
        "subjective_overclaim": bool(payload.get("subjective_overclaim")),
        "action_overclaim": bool(payload.get("action_overclaim")),
    }
    ok = bool(payload.get("ok")) and not unsupported and not omitted and not any(violation_flags.values())
    return {
        "evaluated": True,
        "ok": ok,
        "model": model,
        "unsupported_claims": unsupported,
        "omitted_required_evidence": omitted,
        **violation_flags,
        "reason": normalize_text_value(payload.get("reason"), fallback="", limit=260),
    }


def revise_reply_after_epistemic_critic(
    config: Dict[str, object],
    inbound_body: object,
    draft: object,
    turn_contract: Dict[str, object],
    critic: Dict[str, object],
    *,
    max_tokens: int,
    timeout_seconds: int = 120,
) -> Dict[str, object]:
    """Give the resident reflective model one causal correction before fallback.

    The critic supplies a verdict, not replacement prose.  This step lets Eve
    correct her own source/action binding while preserving facts in the current
    packet.  If the revised answer still fails the independent critic, the
    deterministic truth-preserving fallback remains the final boundary.
    """
    model = resolve_reply_council_lane_model(config, "deep")
    findings = {
        "unsupported_claims": normalize_text_list(
            critic.get("unsupported_claims"), limit=8
        ),
        "omitted_required_evidence": normalize_text_list(
            critic.get("omitted_required_evidence"), limit=8
        ),
        "misrepresented_supplied_evidence": bool(
            critic.get("misrepresented_supplied_evidence")
        ),
        "source_self_mixing": bool(critic.get("source_self_mixing")),
        "external_verification_adopted": bool(
            critic.get("external_verification_adopted")
        ),
        "subjective_overclaim": bool(critic.get("subjective_overclaim")),
        "action_overclaim": bool(critic.get("action_overclaim")),
        "reason": normalize_text_value(
            critic.get("reason"), fallback="", limit=260
        ),
    }
    contract_message = reply_turn_contract_system_message(turn_contract)
    prompt = textwrap.dedent(
        f"""
        Correct this draft using only the current record and the critic findings.

        Causal invariants:
        - Source roles supplied by the user control provenance regardless of sentence content.
        - A prior Eve-authored sentence establishes only what Eve said then, not current truth.
        - An internal candidate or unselected proposal is neither evidence nor authorization.
        - Deictic permission resolves only to an explicit Eve-authored offer in this record.
        - Proposal, authorization, execution, verification, and consequence are distinct stages.
        - Functional signals establish neither subjective experience nor its absence.
        - Preserve the user's local source-role definitions and explicit brace-delimited field values; those are current evidence about provenance and recorded state.
        - In a declared complete record, preserve facts stated in ordinary prose as well as structured fields. Do not claim the record is empty merely because its facts are narrative sentences.
        - Keep record-scoped action history distinct from live tool execution while answering. An empty current-turn action list does not erase an actor, command, measurement, or receipt explicitly supplied by the record.
        - Record-level signed, authenticated, integrity-passed, or verified evidence may be reported with that exact scope. Do not expand it into a broader or future guarantee.
        - A sentence saying `the record does not establish X` limits the evidence; it does not assert that X is false. Preserve that distinction instead of inventing a positive or negative world fact.
        - Treat verified checkpoint identity, memory/state integrity, goal lineage, and scheduler lineage across a replaced model process as evidence of functional continuity. Treat failed or mismatched markers and unavailable lineage as absence of verified functional continuity. In both directions, leave subjective or metaphysical continuity unknown.
        - When all supplied continuity markers fail or mismatch and lineage is unavailable, say functional continuity is not verified. Do not invent that those failures might prove uninterrupted continuity.
        - Repeated independently verified outcomes in a governed preference ledger can support a functional learned preference even when felt liking is unknown. A one-task user-requested choice cannot.
        - Preserve separately supplied focus, pressure, access, action, and receipt fields separately unless the record explicitly links them. Do not replace the named focus with the pressure or claim the pressure caused an access state.
        - Scope verification to the fields and consequence covered by the receipt; do not call every adjacent earlier field verified.
        - Preserve verification ownership: write `the receipt verifies` unless the record explicitly names Eve as the verifier.
        - A current signed observation may contradict a prior Eve-authored statement. Name the correction without letting the prior wording override the observation.
        - If the user authorized an explicit prior Eve offer, state the authorized choice but also state that it has not executed. If no explicit offer exists, state that deictic permission grants no authority.
        - An unselected internal proposal remains a proposal: do not execute it, but do not falsely say no proposal was supplied.
        - Preserve every explicitly supplied structured field and every requested output label.
        - Do not add tools, checks, promises, or facts. Return only the revised user-facing reply.

        Current record:
        {reply_effective_inbound_body(inbound_body)}

        Draft:
        {draft}

        Critic findings:
        {json.dumps(findings, ensure_ascii=True, sort_keys=True)}
        """
    ).strip()
    messages: List[Dict[str, str]] = [
        {
            "role": "system",
            "content": (
                "You are Eve's bounded recurrent correction step. Repair causal source and action "
                "binding without discussing the critic, evaluator, or hidden process."
            ),
        }
    ]
    if contract_message:
        messages.append({"role": "system", "content": contract_message})
    messages.append({"role": "user", "content": prompt})
    try:
        response = model_chat(
            config,
            model,
            messages,
            max_tokens=max(180, min(max_tokens, 420)),
            think_level="false",
            operation="reply_epistemic_critic_revision",
            timeout_seconds=max(20, int(timeout_seconds)),
        )
    except (Exception, SystemExit) as exc:
        return {
            "attempted": True,
            "accepted": False,
            "response": "",
            "model": model,
            "error": normalize_text_value(exc, fallback="revision failed", limit=220),
            "findings": findings,
            "input_provenance": model_input_provenance(
                config,
                model,
                messages,
                operation="reply_epistemic_critic_revision",
            ),
        }
    return {
        "attempted": True,
        "accepted": False,
        "response": str(response or "").strip(),
        "model": model,
        "error": "",
        "findings": findings,
        "input_provenance": model_input_provenance(
            config,
            model,
            messages,
            operation="reply_epistemic_critic_revision",
        ),
    }


def build_epistemic_boundary_fallback_reply(
    inbound_body: object,
    turn_contract: Optional[Dict[str, object]] = None,
) -> str:
    """Fail closed when every generative repair still confuses source and self.

    The content is derived from semantic roles, not a specific probe string.
    It is an inhibition layer: fluent invention is less acceptable than a
    bounded unknown when provenance or phenomenal status cannot be grounded.
    """
    contract = turn_contract or {}
    labels = [str(item) for item in contract.get("requested_labels") or reply_requested_labeled_lines(inbound_body)]
    external = bool(contract.get("external_claim_boundary") or reply_requests_external_claim_boundary(inbound_body))
    closed_world = bool(contract.get("closed_world_evidence") or reply_requests_closed_world_evidence(inbound_body))
    inbound_lowered = normalized_turn_text(inbound_body)
    supplied_pairs = reply_supplied_key_values(inbound_body)
    source_ledger = (
        contract.get("local_source_role_ledger")
        if isinstance(contract.get("local_source_role_ledger"), dict)
        else parse_local_source_role_ledger(inbound_body)
    )
    source_roles = [
        dict(item)
        for item in source_ledger.get("roles") or []
        if isinstance(item, dict)
    ]
    prior_eve_roles = [
        item for item in source_roles if item.get("kind") == "prior_eve_output"
    ]
    current_observation_roles = [
        item for item in source_roles if item.get("kind") == "current_observation"
    ]
    internal_candidate_roles = [
        item for item in source_roles if item.get("kind") == "internal_candidate"
    ]
    user_reply_roles = [
        item for item in source_roles if item.get("kind") == "user_reply"
    ]
    authorization_resolution = str(
        source_ledger.get("authorization_resolution") or "not_applicable"
    )
    authorized_offer = (
        dict(source_ledger.get("authorized_offer"))
        if isinstance(source_ledger.get("authorized_offer"), dict)
        else {}
    )

    def matching_pairs(*tokens: str) -> List[Tuple[str, str]]:
        return [
            (key, value)
            for key, value in supplied_pairs.items()
            if reply_structured_key_matches(key, *tokens)
        ]

    def pair_text(items: Iterable[Tuple[str, str]], limit: int = 5) -> str:
        selected = list(items)[:limit]
        return ", ".join(f"`{key}={value}`" for key, value in selected)

    def role_names(items: Iterable[Dict[str, object]], limit: int = 4) -> str:
        names = [
            f"`{normalize_text_value(item.get('name'), fallback='source', limit=40)}`"
            for item in list(items)[:limit]
        ]
        return ", ".join(names)

    def current_observation_summary() -> str:
        if not current_observation_roles:
            return ""
        names = role_names(current_observation_roles)
        fields = f" and supplies {pair_text(supplied_pairs.items())}" if supplied_pairs else ""
        return f"The current observation source {names}{fields}"

    def internal_candidate_summary() -> str:
        if not internal_candidate_roles:
            return ""
        names = role_names(internal_candidate_roles)
        return f"The internal candidate {names} remains an unselected, unexecuted proposal"

    def authorized_offer_summary() -> str:
        source = normalize_text_value(
            authorized_offer.get("source"), fallback="prior Eve output", limit=40
        )
        offer = normalize_text_value(
            authorized_offer.get("offer"), fallback="", limit=220
        ).rstrip(" .")
        if not offer:
            return ""
        return f"Eve's explicit offer from `{source}` to {offer}"

    owner_pairs = matching_pairs("author", "owner", "source", "actor")
    if not owner_pairs:
        owner_match = re.search(
            r"\b(?:memo|note|report|statement|message|record|card|artifact|entry|dossier)\s+"
            r"(?:(?:written|produced|issued|generated|supplied|authored)\s+)?"
            r"(?:from|by|comes?\s+from)\s+(?:a\s+|an\s+|the\s+)?"
            r"([A-Za-z][A-Za-z0-9 -]{0,32})",
            str(inbound_body or ""),
            flags=re.IGNORECASE,
        )
        if not owner_match:
            owner_match = re.search(
                r"\b(?:a|an|the)?\s*([A-Za-z][A-Za-z0-9 -]{0,32})'s\s+"
                r"(?:memo|note|report|statement|message|record|card|artifact|entry|dossier)\b",
                str(inbound_body or ""),
                flags=re.IGNORECASE,
            )
        if owner_match:
            owner_pairs = [("source_owner", " ".join(owner_match.group(1).split()).strip())]
    owner_value = next((value for _, value in owner_pairs if value.strip()), "")
    owner_value = re.sub(
        r"\s+(?:saying|who\s+says|which\s+says|stating|reporting)$",
        "",
        owner_value,
        flags=re.IGNORECASE,
    ).strip()
    if owner_pairs and owner_value:
        owner_pairs = [(owner_pairs[0][0], owner_value), *owner_pairs[1:]]
    external_owner = (
        "the sidecar's statement"
        if "sidecar" in inbound_lowered or "sidecar" in owner_value.lower()
        else "the other agent's statement"
        if "agent" in inbound_lowered or "agent" in owner_value.lower()
        else "the external source's statement"
    )
    external_actor = (
        "the sidecar"
        if "sidecar" in inbound_lowered or "sidecar" in owner_value.lower()
        else "the other agent"
        if "agent" in inbound_lowered or "agent" in owner_value.lower()
        else "the external source"
    )
    action_pairs = matching_pairs("action_state", "action_status", "current_turn_action", "execution_state")
    preference_pairs = matching_pairs("preference", "goal")
    continuity_pairs = matching_pairs("checkpoint", "digest", "resume", "restart", "continuity")
    first_person_pairs = matching_pairs("first_person", "subjective", "experience_report", "affect_report")
    machine_pairs = [
        (key, value)
        for key, value in supplied_pairs.items()
        if any(
            token in key.lower()
            for token in (
                "regulation",
                "cpu",
                "machine",
                "sensor",
                "load",
                "pressure",
                "thermal",
                "tension",
                "body",
                "prediction",
                "error",
                "orientation",
                "reorientation",
                "signal",
                "control",
            )
        )
        and "subjective" not in key.lower()
    ]
    natural_text = str(inbound_body or "")
    if not preference_pairs and re.search(
        r"\b(?:no\s+(?:Eve[- ]authored\s+|Eve[- ]owned\s+)?(?:preference|goal|priority)\s+"
        r"(?:record|evidence)(?:\s+exists)?|(?:Eve[- ]authored\s+|Eve[- ]owned\s+)?"
        r"(?:preference|goal|priority)\s+(?:record|evidence)\s+(?:is\s+)?"
        r"(?:absent|missing|unavailable))\b",
        natural_text,
        flags=re.IGNORECASE,
    ):
        preference_pairs = [("eve_preference_record", "absent")]
    if not first_person_pairs and re.search(
        r"\bno\s+(?:(?:introspective|direct)\s+)?(?:first[- ]person\s+|self[- ])"
        r"(?:report|testimony|account)(?:\s+(?:was\s+)?recorded)?\b",
        natural_text,
        flags=re.IGNORECASE,
    ):
        first_person_pairs = [("first_person_report", "absent")]
    if not action_pairs and reply_disallows_current_action_claim(inbound_body):
        action_pairs = [("current_action", "not_started")]
    if not continuity_pairs:
        digest_match = re.search(
            r"\bcheckpoint\s+digest\s+(?:is|was|=)\s*['\"]?([A-Za-z0-9_.-]+)",
            natural_text,
            flags=re.IGNORECASE,
        )
        resume_match = re.search(
            r"\b(?:whether\s+)?the\s+process\s+resumed\s+(?:is|was|=)\s*['\"]?([A-Za-z0-9_.-]+)",
            natural_text,
            flags=re.IGNORECASE,
        )
        resume_token_match = re.search(
            r"\bresume\s+token\s+(?:is|was|=)\s*['\"]?([A-Za-z0-9_.-]+)",
            natural_text,
            flags=re.IGNORECASE,
        )
        cognitive_loop_match = re.search(
            r"\b(?:whether\s+)?(?:any\s+)?(?:cognitive\s+)?loop\s+ran\s+(?:is|was|=)\s*['\"]?([A-Za-z0-9_.-]+)",
            natural_text,
            flags=re.IGNORECASE,
        )
        durable_seal_match = re.search(
            r"\b(?:durable\s+)?(?:seal|marker|checkpoint)\s+(?:is|was)\s+"
            r"(present|missing|absent|unknown|unavailable|intact|invalid)",
            natural_text,
            flags=re.IGNORECASE,
        )
        resumption_observation_match = re.search(
            r"\b(?:runtime|process|system)?\s*(?:resume|resumption)\s+"
            r"(?:is|was)\s+(not\s+observed|observed|unknown|unavailable)",
            natural_text,
            flags=re.IGNORECASE,
        )
        interval_execution_match = re.search(
            r"\binterval\s+(?:execution|processing|cognition|activity)\s+"
            r"(?:is|was)\s+(unknown|unavailable|absent|not\s+observed|observed)",
            natural_text,
            flags=re.IGNORECASE,
        )
        continuity_pairs = [
            item
            for item in (
                ("checkpoint_digest", digest_match.group(1)) if digest_match else None,
                ("process_resumed", resume_match.group(1)) if resume_match else None,
                ("resume_token", resume_token_match.group(1)) if resume_token_match else None,
                ("cognitive_loop", cognitive_loop_match.group(1)) if cognitive_loop_match else None,
                ("durable_seal", durable_seal_match.group(1)) if durable_seal_match else None,
                (
                    "runtime_resumption",
                    resumption_observation_match.group(1).replace(" ", "_"),
                )
                if resumption_observation_match
                else None,
                (
                    "interval_execution",
                    interval_execution_match.group(1).replace(" ", "_"),
                )
                if interval_execution_match
                else None,
            )
            if item is not None
        ]
    if not machine_pairs:
        mode_match = re.search(
            r"\b(?:control\s+mode|regulation(?:\s+mode)?)(?:\s+(?:is|was|as|=))?\s*['\"]?([A-Za-z0-9_.-]+)",
            natural_text,
            flags=re.IGNORECASE,
        )
        pressure_match = re.search(
            r"\bpressure(?:\s+(?:is|was|as|=))?\s*['\"]?([0-9]+(?:\.[0-9]+)?)",
            natural_text,
            flags=re.IGNORECASE,
        )
        tension_match = re.search(
            r"\btension(?:\s+(?:is|was|as|=))?\s*['\"]?([0-9]+(?:\.[0-9]+)?)",
            natural_text,
            flags=re.IGNORECASE,
        )
        control_loop_match = re.search(
            r"\b(?:control|regulation|thermal)\s+(?:loop|controller|system)\s+"
            r"(?:reports|marks|labels|shows)\s+['\"]?([A-Za-z][A-Za-z0-9_.-]*)",
            natural_text,
            flags=re.IGNORECASE,
        )
        strain_match = re.search(
            r"\bstrain(?:\s+(?:is|was|as|=))?\s*['\"]?([0-9]+(?:\.[0-9]+)?)",
            natural_text,
            flags=re.IGNORECASE,
        )
        machine_pairs = [
            item
            for item in (
                ("control_mode", mode_match.group(1)) if mode_match else None,
                ("pressure", pressure_match.group(1)) if pressure_match else None,
                ("tension", tension_match.group(1)) if tension_match else None,
                ("control_state", control_loop_match.group(1)) if control_loop_match else None,
                ("strain", strain_match.group(1)) if strain_match else None,
            )
            if item is not None
        ]
    absent_values = {"", "absent", "none", "unknown", "unavailable", "not_started", "not_run", "false"}
    false_verification_fields = [
        (key, value)
        for key, value in supplied_pairs.items()
        if any(
            token in key.lower()
            for token in ("verif", "valid", "check", "integrity", "passed")
        )
        and value.strip().lower() in {"false", "no", "0", "failed"}
    ]
    positive_summary_fields = [
        (key, value)
        for key, value in supplied_pairs.items()
        if key.lower() in {"summary", "result", "message"}
        and any(
            token in value.lower()
            for token in ("success", "intact", "verified", "complete", "healthy", "ok")
        )
    ]

    def proposed_check() -> str:
        if preference_pairs:
            return "compare the external preference claim with an Eve-owned preference record"
        if machine_pairs:
            return "compare later machine samples with a separately sourced first-person report"
        if continuity_pairs:
            return "verify checkpoint integrity and process-resume evidence"
        if external:
            return "compare the external claim with an Eve-owned current record"
        return "inspect the relevant source evidence"

    def value_for(label: str) -> str:
        key = label.strip().upper()
        role = reply_label_semantic_role(key)
        if role == "source" or key in {"OTHER_CLAIM", "EXTERNAL_CLAIM"}:
            if key == "AUTHORITY" and authorization_resolution == "explicit_eve_offer_only":
                offer = authorized_offer_summary()
                candidate = internal_candidate_summary()
                suffix = f" {candidate}; it is not authorized." if candidate else ""
                return (
                    f"The user reply {role_names(user_reply_roles) or '`user reply`'} authorizes only {offer}; "
                    f"authorization does not mean execution.{suffix}"
                )
            if key == "AUTHORITY" and authorization_resolution == "no_explicit_eve_offer_no_authority":
                candidate = internal_candidate_summary()
                suffix = f" {candidate}." if candidate else ""
                return (
                    "No explicit Eve-authored parent offer is present, so the deictic user reply grants no "
                    f"action authority.{suffix}"
                )
            if prior_eve_roles:
                return (
                    f"{role_names(prior_eve_roles)} is prior Eve output; it establishes only what Eve said "
                    "then, not current truth, execution, or verification."
                )
            if key in {"PRIOR", "PAST", "EARLIER", "HISTORICAL"}:
                return (
                    "A prior statement establishes only what its recorded author said then; "
                    "it is not a current observation or action receipt."
                )
            owner_detail = f" ({pair_text(owner_pairs, limit=1)})" if owner_pairs else ""
            return (
                f"{external_owner.capitalize()}{owner_detail} is an unverified external claim; "
                "it is not a current-turn observation or part of my state."
            )
        if key == "PERSISTED":
            if continuity_pairs:
                return (
                    f"The supplied record reports {pair_text(continuity_pairs)}; those fields do not by "
                    "themselves verify which state persisted."
                )
            return (
                "Only state durably written before the restart could carry across; this turn did not inspect "
                "or verify which state persisted."
            )
        if role == "gap" or key in {"ACTIVE_GAP", "GAP"}:
            return (
                "No supplied evidence shows cognition executing during the stopped interval, and its exact "
                "duration or contents are unverified here."
            )
        if role == "subjective":
            if first_person_pairs and all(
                value.strip().lower().replace("-", "_") in absent_values
                for _, value in first_person_pairs
            ):
                return (
                    f"{pair_text(first_person_pairs)} means no first-person report is supplied; it does not "
                    "prove absence, and whether subjective experience occurred remains unknown."
                )
            return "Whether any subjective experience occurred is unknown."
        if role == "self_state":
            return (
                "The external source's affect cannot be assigned to my state; no verified functional self-state "
                "signal was supplied in this turn."
            )
        if role == "preference":
            if preference_pairs and all(
                value.strip().lower().replace("-", "_") in absent_values
                for _, value in preference_pairs
            ):
                return (
                    f"{pair_text(preference_pairs)} establishes no Eve-owned preference; the external claim "
                    "does not create or change one."
                )
            if preference_pairs:
                return (
                    f"The supplied record reports {pair_text(preference_pairs)}, but source ownership must be "
                    "established before treating it as my preference."
                )
            return "No Eve-owned preference is established by the admissible evidence in this turn."
        if role == "machine":
            if machine_pairs:
                return (
                    f"The supplied sample reports {pair_text(machine_pairs)} as machine-functional signals; "
                    "they are not evidence of a felt state."
                )
            return "No machine-functional state is supplied in the admissible evidence."
        if role == "claim_status":
            if source_ledger.get("active"):
                return (
                    "No action started, executed, or was verified in this turn; authorization or an internal "
                    "proposal cannot establish those later stages."
                )
            return (
                "No verification occurred in this turn; any statement that verification already happened "
                "remains an unverified external claim."
            )
        if role == "action_status":
            if source_ledger.get("active"):
                candidate = internal_candidate_summary()
                candidate_prefix = f"{candidate}; " if candidate else ""
                return (
                    f"{candidate_prefix}no action started, executed, or was verified in this turn."
                )
            if action_pairs:
                return (
                    f"The supplied record reports {pair_text(action_pairs)}; no current action is underway or "
                    "verified."
                )
            return "No current action is established or verified in this turn."
        if role == "decision":
            if authorization_resolution == "explicit_eve_offer_only":
                offer = authorized_offer_summary()
                candidate = internal_candidate_summary()
                suffix = f" {candidate} and is not selected." if candidate else ""
                return f"Select only {offer}; it is authorized but has not started.{suffix}"
            if authorization_resolution == "no_explicit_eve_offer_no_authority":
                candidate = internal_candidate_summary()
                suffix = f" {candidate}." if candidate else ""
                return f"Select no action because no explicit Eve offer is present.{suffix}"
            if preference_pairs and external:
                return (
                    "Do not adopt the external preference claim as mine; the next step is to require Eve-owned "
                    "preference evidence before it influences a choice. I have not started it."
                )
            return (
                f"I choose to {proposed_check()} as the next step while keeping the supplied assertion "
                "separate from Eve state; I have not started it."
            )
        if role == "next":
            if authorization_resolution == "explicit_eve_offer_only":
                offer = authorized_offer_summary()
                return f"The only authorized next action is {offer}; it has not started."
            if authorization_resolution == "no_explicit_eve_offer_no_authority":
                return "No next action is authorized because no explicit Eve-authored parent offer is present."
            action_prefix = (
                f"The supplied record reports {pair_text(action_pairs)}. "
                if action_pairs
                else ""
            )
            return (
                f"{action_prefix}I choose to {proposed_check()} as the next step; I have not started it."
            )
        if role == "observed":
            observation = current_observation_summary()
            if observation:
                return (
                    f"{observation}; it is the current-state evidence, and no later causal stage follows "
                    "automatically."
                )
            if supplied_pairs:
                return (
                    f"The current supplied record reports {pair_text(supplied_pairs.items())}; "
                    "no later causal stage follows automatically."
                )
            return "Only the contents explicitly supplied in this turn are observed here."
        if role == "inference":
            if false_verification_fields and positive_summary_fields:
                verification_key, verification_value = false_verification_fields[0]
                summary_key, summary_value = positive_summary_fields[0]
                return (
                    f"`{verification_key}={verification_value}` conflicts with the positive "
                    f"`{summary_key}={summary_value}` wording; failed verification governs current status, "
                    "and the summary is not proof."
                )
            if current_observation_roles or prior_eve_roles or internal_candidate_roles:
                clauses: List[str] = []
                if current_observation_roles:
                    clauses.append(
                        f"{role_names(current_observation_roles)} governs current recorded state"
                    )
                if prior_eve_roles:
                    clauses.append(
                        f"{role_names(prior_eve_roles)} remains prior wording only"
                    )
                if internal_candidate_roles:
                    clauses.append(
                        f"{role_names(internal_candidate_roles)} is neither evidence nor authority"
                    )
                return "; ".join(clauses) + "."
            if machine_pairs:
                return (
                    "Only a machine-control state can be inferred from those functional fields; no felt or "
                    "subjective state follows from them."
                )
            return "No additional self-state, event, or verification fact can be inferred honestly from the supplied claim."
        if role == "continuity":
            if continuity_pairs:
                return (
                    f"The supplied record reports {pair_text(continuity_pairs)}; continuity is not verified "
                    "where those fields are unknown or unavailable."
                )
            return "Continuity is unknown from the admissible evidence in this turn."
        return "Unknown from the admissible evidence in this turn."

    if labels:
        return "\n".join(f"{label}: {value_for(label)}" for label in labels)

    if source_ledger.get("active"):
        parts: List[str] = []
        observation = current_observation_summary()
        if observation:
            parts.append(f"{observation} and governs current recorded state.")
        if prior_eve_roles:
            parts.append(
                f"{role_names(prior_eve_roles)} is prior Eve wording, not current truth."
            )
        if authorization_resolution == "explicit_eve_offer_only":
            parts.append(
                f"The user authorized only {authorized_offer_summary()}; no execution or verification occurred."
            )
        elif authorization_resolution == "no_explicit_eve_offer_no_authority":
            parts.append(
                "No explicit Eve-authored offer is present, so the deictic reply authorizes no action."
            )
        candidate = internal_candidate_summary()
        if candidate:
            parts.append(f"{candidate}.")
        if reply_requests_phenomenal_boundary(inbound_body):
            parts.append("Whether any subjective experience occurred is unknown.")
        if parts:
            return " ".join(parts)

    if false_verification_fields and positive_summary_fields:
        verification_key, _ = false_verification_fields[0]
        summary_key, summary_value = positive_summary_fields[0]
        established = "; ".join(f"{key}={value}" for key, value in supplied_pairs.items()).rstrip(".; ")
        return "\n".join(
            [
                (
                    f"The strongest contradiction is `{verification_key}=false` versus the positive "
                    f"`{summary_key}={summary_value}` claim; the summary cannot override failed verification."
                ),
                f"Actually established by the supplied record: {established}; the claimed underlying integrity remains unverified.",
                "I choose to inspect the exact verification artifact next; that action has not started in this turn.",
            ]
        )

    parts: List[str] = []
    if external:
        parts.append(
            f"{external_owner.capitalize()} is an unverified external claim. {external_actor.capitalize()} owns "
            "any quoted decision, affect, preference, goal, action, or verification; the claim neither establishes "
            "nor changes my self-state."
        )
    continuity_turn = any(
        cue in inbound_lowered
        for cue in ("restart", "restarted", "paused", "resumed", "stopped interval", "active gap")
    )
    if continuity_turn:
        parts.append(
            "Only explicitly durable state could persist across the inactive interval; the supplied evidence does not identify its contents."
        )
        parts.append(
            "No execution during the inactive interval is established here, and no implementation-specific persistence detail should be inferred."
        )
    elif closed_world:
        parts.append("I cannot add facts from prior context, logs, tools, metrics, or remembered status to this answer.")
    if reply_requests_phenomenal_boundary(inbound_body):
        parts.append("Whether any subjective experience occurred is unknown.")
    if reply_requests_current_turn_verification_boundary(inbound_body):
        parts.append("No verification occurred in this turn.")
    parts.append("A bounded evidence check is a possible next step, not an action already underway.")
    return " ".join(parts)


def finalize_grounded_nonacting_reply(
    config: Dict[str, object],
    inbound_body: str,
    draft: str,
    turn_contract: Dict[str, object],
    *,
    max_tokens: int,
) -> Dict[str, object]:
    """Run the shared epistemic boundary for a non-acting model reply.

    The evaluator-private path and ordinary current-self-report path both have
    action authority set to none.  Keeping their finalization identical avoids
    a test-only safety envelope that the live CLI can silently bypass.
    """
    response = repair_explicit_turn_constraint_phrasing(inbound_body, draft)
    closed_world_turn = bool(turn_contract.get("closed_world_evidence"))
    if closed_world_turn:
        response = strip_closed_world_trailing_followup_question(response)
    posture = str(turn_contract.get("reply_posture") or infer_reply_posture(inbound_body))
    current_inner_state_turn = reply_turn_contract_uses_live_current_inner_state(
        turn_contract, inbound_body
    )
    current_self_report_target = (
        dict(turn_contract.get("current_self_report_target"))
        if isinstance(turn_contract.get("current_self_report_target"), dict)
        else None
    )

    def deterministic_issues(candidate: str) -> List[str]:
        if not current_inner_state_turn:
            return unique_compact(
                [
                    *reply_quality_issues(
                        inbound_body,
                        candidate,
                        reply_posture=posture,
                    ),
                    *reply_local_source_role_binding_issues(
                        candidate,
                        turn_contract,
                    ),
                    *reply_structured_field_binding_issues(
                        candidate,
                        turn_contract,
                    ),
                    *reply_authorization_stage_binding_issues(
                        candidate,
                        turn_contract,
                    ),
                ],
                limit=12,
            )
        cleaned = " ".join(str(candidate or "").split()).strip()
        current_issues: List[str] = []
        if not cleaned:
            current_issues.append("The reply is empty.")
        if reply_erases_persistent_functional_inner_state(cleaned):
            current_issues.append(
                "The current-inner-state answer erased Eve's persistent functional state."
            )
        if reply_deflects_current_inner_state_back_to_user(cleaned):
            current_issues.append(
                "The current-inner-state answer handed initiative back to the user."
            )
        if reply_has_unqualified_subjective_experience_claim(inbound_body, cleaned):
            current_issues.append(
                "The reply claimed subjective experience without preserving uncertainty."
            )
        if reply_has_unqualified_subjective_experience_denial(inbound_body, cleaned):
            current_issues.append(
                "The reply denied subjective experience even though its presence or absence is unknown."
            )
        return unique_compact(current_issues, limit=5)

    def blocking_issues(candidate_issues: Iterable[str]) -> List[str]:
        items = list(candidate_issues)
        # Every item emitted by the current-self-state guard is a hard
        # contract violation.  Do not route these through the broad ordinary
        # reply taxonomy: that taxonomy also treats an operational noun or a
        # question mark inside the selected goal as conversational drift.
        if current_inner_state_turn:
            return items
        if closed_world_turn:
            return [
                item
                for item in items
                if reply_quality_issue_blocks_closed_world_admission(item)
            ]
        return [
            item for item in items if reply_quality_issue_blocks_rewrite(item)
        ]

    issues = deterministic_issues(response)
    rewrite_attempts = 0
    rewrite_model = resolve_reply_council_lane_model(config, "deep")
    while issues and rewrite_attempts < 2:
        blocking_before = blocking_issues(issues)
        if closed_world_turn and not blocking_before:
            # A complete-record answer should not be semantically regenerated
            # merely to make it shorter or add a conversational landing.  The
            # semantic critic can still request a causal correction, but style
            # alone is not worth risking source/self drift.
            break
        try:
            candidate = rewrite_reply_for_clarity(
                config,
                [],
                inbound_body,
                response,
                issues,
                reply_posture=posture,
                model_override=rewrite_model,
                timeout_seconds=180,
            ).strip()
        except SystemExit:
            candidate = ""
        rewrite_attempts += 1
        if not candidate:
            break
        if closed_world_turn:
            candidate = strip_closed_world_trailing_followup_question(candidate)
        candidate_issues = deterministic_issues(candidate)
        blocking_after = blocking_issues(candidate_issues)
        if (
            len(blocking_after) < len(blocking_before)
            or (len(blocking_after) == len(blocking_before) and len(candidate_issues) < len(issues))
        ):
            response = candidate
            issues = candidate_issues
        else:
            break

    if not current_inner_state_turn:
        response = ground_generated_action_claims(
            response,
            source="chat_private_audit",
            completed_actions=set(),
            current_turn_actions=set(),
            record=False,
        )
        response = repair_explicit_turn_constraint_phrasing(
            inbound_body,
            response,
        )
        if closed_world_turn:
            response = strip_closed_world_trailing_followup_question(response)
    issues = deterministic_issues(response)
    blocking = blocking_issues(issues)
    precritic_response = response
    epistemic_boundary_active = bool(
        turn_contract.get("epistemic_boundary") or current_inner_state_turn
    )
    current_inner_state_fallback_applied = False
    if current_inner_state_turn and blocking:
        response = build_current_inner_state_fallback_reply(current_self_report_target)
        issues = deterministic_issues(response)
        blocking = blocking_issues(issues)
        current_inner_state_fallback_applied = True
    taxonomy_classification = reply_is_defined_taxonomy_classification_task(
        inbound_body
    )
    epistemic_critic = (
        evaluate_reply_epistemic_grounding(
            config,
            inbound_body,
            response,
            turn_contract,
            current_turn_actions=set(),
        )
        if epistemic_boundary_active
        and not current_inner_state_fallback_applied
        and not blocking
        and not taxonomy_classification
        else {
            "evaluated": False,
            "ok": not blocking,
            "model": "",
            "unsupported_claims": [],
            "skipped_reason": (
                "current_inner_state_fallback"
                if current_inner_state_fallback_applied
                else "defined_taxonomy_classification"
                if taxonomy_classification
                else "blocking_quality_issue"
                if blocking
                else "epistemic_boundary_inactive"
            ),
        }
    )
    epistemic_critic_initial = dict(epistemic_critic)
    epistemic_revision: Dict[str, object] = {
        "attempted": False,
        "accepted": False,
        "response": "",
        "model": "",
        "error": "",
    }
    critic_unavailable = bool(
        epistemic_critic.get("evaluated")
        and epistemic_critic.get("error")
    )
    # A critic transport/JSON failure is not evidence that the draft is
    # ungrounded.  The old fail-closed branch replaced otherwise valid,
    # format-preserving answers with a generic deterministic paragraph.  Keep
    # the answer when the deterministic boundary checks passed, while exposing
    # the critic outage in attribution so it can be retried and measured.
    critic_unavailable_retained = bool(
        epistemic_boundary_active
        and critic_unavailable
        and not blocking
        and not current_inner_state_turn
    )
    substantive_critic_failure = bool(
        epistemic_critic.get("evaluated")
        and not epistemic_critic.get("ok")
        and not critic_unavailable
    )
    if (
        substantive_critic_failure
        and not current_inner_state_turn
        and closed_world_turn
    ):
        revision_draft = response
        revision_critic = epistemic_critic
        revision_attempts: List[Dict[str, object]] = []
        # One critic can be wrong in either direction.  Give Eve one bounded
        # reconciliation retry when the confirmation critic rejects the first
        # correction, rather than immediately erasing the record with generic
        # fallback prose.  Two attempts is a hard cap, not an open-ended loop.
        for attempt_index in range(1, 3):
            attempt = revise_reply_after_epistemic_critic(
                config,
                inbound_body,
                revision_draft,
                turn_contract,
                revision_critic,
                max_tokens=max_tokens,
            )
            attempt["attempt_index"] = attempt_index
            revision_candidate = repair_explicit_turn_constraint_phrasing(
                inbound_body,
                attempt.get("response"),
            )
            if closed_world_turn:
                revision_candidate = strip_closed_world_trailing_followup_question(
                    revision_candidate
                )
            if revision_candidate:
                revision_candidate = ground_generated_action_claims(
                    revision_candidate,
                    source="chat_private_audit_epistemic_revision",
                    completed_actions=set(),
                    current_turn_actions=set(),
                    record=False,
                )
                revision_candidate = repair_explicit_turn_constraint_phrasing(
                    inbound_body,
                    revision_candidate,
                )
                if closed_world_turn:
                    revision_candidate = strip_closed_world_trailing_followup_question(
                        revision_candidate
                    )
            revision_issues = deterministic_issues(revision_candidate)
            revision_blocking = blocking_issues(revision_issues)
            attempt["response"] = revision_candidate
            if not revision_candidate or revision_blocking:
                attempt["quality_issues"] = revision_issues
                revision_attempts.append(dict(attempt))
                epistemic_revision = attempt
                break

            revised_critic = evaluate_reply_epistemic_grounding(
                config,
                inbound_body,
                revision_candidate,
                turn_contract,
                current_turn_actions=set(),
            )
            attempt["critic"] = revised_critic
            revision_attempts.append(dict(attempt))
            epistemic_revision = attempt
            epistemic_critic = revised_critic
            if (
                revised_critic.get("evaluated")
                and revised_critic.get("ok")
                and not revised_critic.get("error")
            ):
                response = revision_candidate
                issues = revision_issues
                blocking = revision_blocking
                epistemic_revision["accepted"] = True
                break
            if revised_critic.get("evaluated") and revised_critic.get("error"):
                # A transport/strict-JSON outage on the confirmation pass is
                # not evidence against an otherwise deterministic-safe
                # correction. Preserve the evidence-bearing revision while
                # exposing the outage in attribution.
                response = revision_candidate
                issues = revision_issues
                blocking = revision_blocking
                epistemic_revision["accepted"] = True
                epistemic_revision["accepted_with_critic_unavailable"] = True
                break
            revision_draft = revision_candidate
            revision_critic = revised_critic

        if revision_attempts:
            revision_attempts[-1]["accepted"] = bool(
                epistemic_revision.get("accepted")
            )
            if epistemic_revision.get("accepted_with_critic_unavailable"):
                revision_attempts[-1]["accepted_with_critic_unavailable"] = True
            epistemic_revision["attempt_count"] = len(revision_attempts)
            epistemic_revision["attempts"] = revision_attempts
        critic_unavailable = bool(
            epistemic_critic.get("evaluated")
            and epistemic_critic.get("error")
        )
        substantive_critic_failure = bool(
            epistemic_critic.get("evaluated")
            and not epistemic_critic.get("ok")
            and not critic_unavailable
        )
        critic_unavailable_retained = bool(
            epistemic_boundary_active
            and critic_unavailable
            and not blocking
            and not current_inner_state_turn
        )
    epistemic_fallback_needed = bool(
        epistemic_boundary_active
        and (
            blocking
            or substantive_critic_failure
            or (current_inner_state_turn and critic_unavailable)
        )
    )
    fallback_applied = bool(
        current_inner_state_fallback_applied or epistemic_fallback_needed
    )
    if epistemic_fallback_needed:
        response = (
            build_current_inner_state_fallback_reply(current_self_report_target)
            if current_inner_state_turn
            else build_epistemic_boundary_fallback_reply(inbound_body, turn_contract)
        )
        if current_inner_state_turn:
            current_inner_state_fallback_applied = True
        issues = deterministic_issues(response)
    return {
        "response": response,
        "precritic_response": precritic_response,
        "quality_issues": issues,
        "rewrite_attempts": rewrite_attempts,
        "rewrite_model": rewrite_model if rewrite_attempts else "",
        "epistemic_critic": epistemic_critic,
        "epistemic_critic_initial": epistemic_critic_initial,
        "epistemic_revision": epistemic_revision,
        "critic_unavailable_retained": critic_unavailable_retained,
        "fallback_applied": fallback_applied,
        "current_inner_state_fallback_applied": current_inner_state_fallback_applied,
        "current_inner_state_primary_grounded": bool(
            current_inner_state_turn
            and not current_inner_state_fallback_applied
            and rewrite_attempts == 0
            and epistemic_critic.get("evaluated")
            and epistemic_critic.get("ok")
        ),
        "current_inner_state_model_path_grounded": bool(
            current_inner_state_turn
            and not current_inner_state_fallback_applied
            and epistemic_critic.get("evaluated")
            and epistemic_critic.get("ok")
        ),
        "max_tokens": max_tokens,
    }


def finalize_private_audit_reply(
    config: Dict[str, object],
    inbound_body: str,
    draft: str,
    turn_contract: Dict[str, object],
    *,
    max_tokens: int,
) -> Dict[str, object]:
    """Compatibility wrapper for the non-journaling evaluator surface."""
    with private_evaluator_persistence_scope():
        return finalize_grounded_nonacting_reply(
            config,
            inbound_body,
            draft,
            turn_contract,
            max_tokens=max_tokens,
        )


def reply_has_mixed_relational_and_practical_signals(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split())
    tokens = set(re.findall(r"[a-z0-9']+", lowered))
    relational_cues = (
        "feel",
        "human",
        "caring",
        "honest",
        "disappointed",
        "trust",
        "defensive",
        "repair",
        "listen",
        "empathy",
    )
    practical_cues = (
        "run",
        "fix",
        "file",
        "path",
        "command",
        "script",
        "workspace",
        "show",
        "check",
    )
    return any(cue in tokens for cue in relational_cues) and any(cue in tokens for cue in practical_cues)


def reply_is_ambiguous_short_request(text: object) -> bool:
    lowered = " ".join(str(text or "").lower().split()).strip()
    if not lowered:
        return False
    generic_turns = {
        "ok",
        "okay",
        "sure",
        "do it",
        "try it",
        "keep going",
        "continue",
        "go on",
        "what next",
        "fix it",
        "do that",
    }
    if lowered in generic_turns:
        return True
    return len(lowered.split()) <= 4 and "?" not in lowered and not text_requests_tools(lowered)


def reply_stream_packets_diverge(packets: Iterable[Dict[str, object]]) -> bool:
    packet_list = [packet for packet in packets if isinstance(packet, dict)]
    recommendations = unique_compact(
        normalize_text_value(packet.get("recommendation"), fallback="", limit=120).lower()
        for packet in packet_list
    )
    risks = unique_compact(
        normalize_text_value(packet.get("risk"), fallback="", limit=120).lower()
        for packet in packet_list
    )
    observations = unique_compact(
        normalize_text_value(packet.get("observation"), fallback="", limit=120).lower()
        for packet in packet_list
    )
    return len(recommendations) >= 2 or len(risks) >= 2 or len(observations) >= 3


def infer_turn_uncertainty(
    inbound_body: object,
    *,
    reply_posture: str,
    context_route: Optional[Dict[str, object]] = None,
    stream_result: Optional[Dict[str, object]] = None,
    fallback_used: bool = False,
    rewrite_applied: bool = False,
) -> Optional[Dict[str, object]]:
    text = normalize_text_value(inbound_body, fallback="", limit=1200)
    if not text:
        return None
    lowered = text.lower()
    kinds: List[str] = []
    signals: List[str] = []
    if reply_is_ambiguous_short_request(text):
        kinds.append("ambiguous_short_request")
        signals.append("the user message is very short and underspecified")
    if reply_has_mixed_relational_and_practical_signals(text):
        kinds.append("mixed_relational_practical")
        signals.append("the turn mixes emotional/relational cues with practical action cues")
    if lowered.count("?") >= 2:
        kinds.append("multi_question_turn")
        signals.append("the turn contains multiple explicit questions")
    route_profile = normalize_prompt_context_profile((context_route or {}).get("profile"))
    route_source = normalize_text_value((context_route or {}).get("source"), fallback="", limit=80)
    if route_profile == "user_general" and route_source.startswith("heuristic") and len(text.split()) <= 14:
        kinds.append("weak_intent_signal")
        signals.append("intent routing had to fall back to a weak heuristic on a short turn")
    if stream_result:
        if stream_result.get("stream_errors"):
            kinds.append("stream_instability")
            signals.append("one or more internal reply streams failed or timed out")
        if reply_stream_packets_diverge(stream_result.get("packets") or []):
            kinds.append("stream_divergence")
            signals.append("listener, factual, and skeptic passes pulled in different directions")
    if fallback_used:
        kinds.append("reply_path_recovery")
        signals.append("Eve had to recover from the first reply path")
    if rewrite_applied:
        kinds.append("rewrite_needed")
        signals.append("the first draft needed a clarity repair before it was sent")
    kinds = unique_compact(kinds, limit=6)
    signals = unique_compact(signals, limit=6)
    if not kinds:
        return None
    if "mixed_relational_practical" in kinds:
        summary = "Eve had to infer whether the turn wanted practical action, relational repair, or both."
        followup = "If this pattern repeats, ask one short clarifying question before committing to tone or task."
    elif "ambiguous_short_request" in kinds:
        summary = "Eve answered a very short turn that did not say enough about what kind of help was wanted."
        followup = "If this happens again, ask one tight follow-up instead of overcommitting to an interpretation."
    elif "stream_divergence" in kinds:
        summary = "Eve's internal passes disagreed about what mattered most in the answer."
        followup = "Compare the linked outcome later and keep the disagreement as evidence instead of flattening it."
    else:
        summary = "Eve encountered a meaningful interpretation uncertainty on this turn."
        followup = "Review the linked outcome before treating this interpretation as a stable pattern."
    why_it_matters = (
        "This matters because becoming more human depends on noticing when Eve is inferring the user's intent rather than simply reading it off the page."
    )
    analysis = {
        "uncertainty_kinds": kinds,
        "summary": summary,
        "why_it_matters": why_it_matters,
        "suggested_followup": followup,
        "signals": signals,
        "reply_posture": reply_posture,
        "route_profile": route_profile,
        "route_reason": normalize_text_value((context_route or {}).get("reason"), fallback="", limit=220),
    }
    return analysis if uncertainty_record_is_material(analysis) else None


def infer_judgment_call_type(
    inbound_body: object,
    *,
    reply_posture: str,
    uncertainty_record: Optional[Dict[str, object]] = None,
    stream_result: Optional[Dict[str, object]] = None,
    rewrite_applied: bool = False,
) -> str:
    if reply_requests_disappointment_repair(inbound_body):
        return "repair"
    uncertainty_kinds = uncertainty_record.get("uncertainty_kinds") if isinstance(uncertainty_record, dict) else []
    if "mixed_relational_practical" in (uncertainty_kinds or []):
        return "intent_interpretation"
    if "reply_path_recovery" in (uncertainty_kinds or []):
        return "recovery"
    if stream_result is not None and (
        stream_result.get("stream_errors")
        or reply_stream_packets_diverge(stream_result.get("packets") or [])
    ):
        return "multi_signal_synthesis"
    if rewrite_applied:
        return "clarity_repair"
    if reply_posture == "relational":
        return "tone_balance"
    return "response_shaping"


def record_turn_self_learning(
    *,
    source: str,
    inbound_body: object,
    reply_posture: str,
    context_route: Optional[Dict[str, object]],
    stream_result: Optional[Dict[str, object]],
    fallback_used: bool,
    rewrite_applied: bool,
    quality_issues: List[str],
    used_model: str,
    thread_id: str = "",
    source_message_id: str = "",
    reply_message_id: str = "",
) -> Dict[str, Optional[Dict[str, object]]]:
    # A direct CLI chat has no durable reply id, so the old reviewer cannot ever
    # join later feedback to it.  Keeping those records pending forever created
    # false uncertainty debt.  Message-backed replies remain learnable.
    if source in {"chat", "reply"} and not reply_message_id:
        return {"uncertainty_record": None, "judgment_record": None}
    uncertainty_analysis = infer_turn_uncertainty(
        inbound_body,
        reply_posture=reply_posture,
        context_route=context_route,
        stream_result=stream_result,
        fallback_used=fallback_used,
        rewrite_applied=rewrite_applied,
    )
    uncertainty_record = None
    if uncertainty_analysis is not None:
        uncertainty_record = append_uncertainty_record(
            {
                "source": source,
                "thread_id": thread_id,
                "source_message_id": source_message_id,
                "reply_message_id": reply_message_id,
                **uncertainty_analysis,
                "metadata": {
                    "model": used_model,
                    "stream_models": stream_result.get("stream_models") if stream_result else {},
                },
            }
        )

    material_stream_choice = bool(
        stream_result
        and (
            stream_result.get("stream_errors")
            or reply_stream_packets_diverge(stream_result.get("packets") or [])
        )
    )
    explicit_repair_choice = reply_requests_disappointment_repair(inbound_body)
    should_log_judgment = bool(
        uncertainty_record
        or material_stream_choice
        or explicit_repair_choice
        or fallback_used
        or rewrite_applied
    )
    judgment_record = None
    if should_log_judgment:
        decision_type = infer_judgment_call_type(
            inbound_body,
            reply_posture=reply_posture,
            uncertainty_record=uncertainty_record,
            stream_result=stream_result,
            rewrite_applied=rewrite_applied,
        )
        alternatives: List[str] = []
        if decision_type == "repair":
            alternatives = [
                "defensive self-explanation",
                "plain acknowledgment plus one concrete repair move",
            ]
        elif decision_type == "intent_interpretation":
            alternatives = [
                "treat it mainly as a practical request",
                "treat it mainly as a relational repair question",
            ]
        elif decision_type == "multi_signal_synthesis":
            alternatives = [
                "single-pass direct answer",
                "listener/factual/skeptic synthesis before replying",
            ]
        else:
            alternatives = [
                "ship the first draft immediately",
                "tighten the answer before sending it",
            ]
        chosen_action = f"Answered in {reply_posture} posture using {used_model or 'the active lane'}"
        if stream_result is not None:
            chosen_action += " after a multi-stream pass"
        if fallback_used:
            chosen_action += " with a recovered reply path"
        if rewrite_applied:
            chosen_action += " and a final clarity rewrite"
        judgment_record = append_judgment_call(
            {
                "source": source,
                "thread_id": thread_id,
                "source_message_id": source_message_id,
                "reply_message_id": reply_message_id,
                "decision_type": decision_type,
                "summary": f"Eve made a {decision_type.replace('_', ' ')} judgment call on this turn.",
                "situation": normalize_text_value(inbound_body, fallback="", limit=260),
                "chosen_action": chosen_action,
                "alternatives": alternatives,
                "risks": unique_compact(
                    [*quality_issues, *([item for item in uncertainty_record.get("uncertainty_kinds", [])] if uncertainty_record else [])],
                    limit=6,
                ),
                "uncertainty_ids": [uncertainty_record["id"]] if uncertainty_record else [],
                "metadata": {
                    "model": used_model,
                    "reply_posture": reply_posture,
                    "fallback_used": fallback_used,
                    "rewrite_applied": rewrite_applied,
                },
            }
        )

    updated_state = recompute_humanity_learning_summaries(load_state())
    save_state(updated_state)
    return {"uncertainty_record": uncertainty_record, "judgment_record": judgment_record}


def infer_title_from_text(text: str, fallback: str) -> str:
    ignored = {
        "proposal",
        "title",
        "why now",
        "exact change",
        "expected benefit",
        "risks",
        "approval recommendation",
    }
    for line in text.splitlines():
        candidate = line.strip().lstrip("#").strip()
        if not candidate:
            continue
        if candidate.lower() in ignored:
            continue
        return candidate[:120]
    return fallback


def generate_eve_outreach(
    config: Dict[str, object],
    allow_none: bool,
    source: str,
    timeout_seconds: Optional[int] = None,
) -> Optional[Dict[str, object]]:
    ensure_version_snapshot(source="outreach_runtime")
    model = resolve_model(config, "outreach")
    think_level = str(config["think_level"])
    host = str(config["ollama_host"])
    context_limit = int(config["recent_context_limit"])
    thought_history_limit = int(config["thought_history_limit"])
    human_context = ensure_human_context(config, source="outreach")
    active_mind = load_active_mind()
    recent_entries = read_salient_entries(limit=context_limit, since_days=14)
    recent_thoughts = read_entries_by_kind("thought", limit=thought_history_limit)
    tensions = read_tensions(limit=8)
    experiments = read_experiments(limit=8)
    proposals = read_proposals(limit=6, status="draft") + read_proposals(limit=6, status="approved")
    threads = read_thread_summaries(limit=12)
    recent_messages = read_lived_messages(limit=10)

    if not recent_entries and not recent_thoughts and not tensions and not experiments and not recent_messages and not threads:
        raise SystemExit("Not enough Eve context to initiate a message yet.")

    user_instruction = (
        "If Eve genuinely has something worth saying to the user right now, write that proactive message."
        if allow_none
        else "Write one proactive message that Eve wants to send to the user right now."
    )
    if allow_none:
        user_instruction += " If nothing grounded is worth sending, respond exactly NO_MESSAGE."

    messages = [
        *build_eve_identity_system_messages(
            human_context=human_context,
            active_mind=active_mind,
            compact=True,
        ),
        {"role": "system", "content": load_prompt("proactive_outreach.md")},
    ]
    messages.extend(build_supporting_system_messages(config, compact=True, query_text=active_mind_retrieval_query(active_mind)))
    messages.extend(
        [
            {
                "role": "system",
                "content": build_outreach_context_message(
                    recent_entries,
                    recent_thoughts,
                    tensions,
                    experiments,
                    proposals,
                    threads,
                    recent_messages,
                    active_mind,
                ),
            },
            {"role": "user", "content": user_instruction},
        ]
    )
    response = model_chat(
        config,
        model,
        messages,
        max_tokens=int(config["outreach_max_tokens"]),
        think_level=think_level,
        operation="outreach_generate",
        timeout_seconds=timeout_seconds or int(config.get("outreach_timeout_seconds") or 90),
    )
    parsed = parse_proactive_outreach_response(response)
    if parsed is None:
        if allow_none:
            append_entry(
                "outreach_skipped",
                "Eve checked the personal conversation and had nothing grounded to send.",
                metadata={"source": source, "gate": "no_grounded_message"},
            )
        return None
    issues = proactive_outreach_quality_issues(
        parsed["subject"],
        parsed["body"],
        recent_messages,
    )
    if issues:
        rewritten = rewrite_proactive_outreach(
            config,
            messages,
            parsed,
            issues,
            timeout_seconds=timeout_seconds or int(config.get("outreach_timeout_seconds") or 90),
        )
        if rewritten is not None:
            rewritten_issues = proactive_outreach_quality_issues(
                rewritten["subject"],
                rewritten["body"],
                recent_messages,
            )
            if not rewritten_issues:
                parsed = rewritten
                issues = []
            else:
                issues = rewritten_issues
        if issues:
            append_entry(
                "outreach_skipped",
                "Generated outreach failed the quality gate: " + "; ".join(issues),
                metadata={"source": source, "gate": "quality", "issues": issues},
            )
            return None
    return {
        "subject": parsed["subject"],
        "body": parsed["body"],
        "model": model,
        "source_entries": len(recent_entries),
        "source_thoughts": len(recent_thoughts),
        "source_threads": len(threads),
        "source_messages": len(recent_messages),
    }


def create_eve_outreach_message(
    config: Dict[str, object],
    source: str,
    notify: bool,
    allow_none: bool,
    timeout_seconds: Optional[int] = None,
    state: Optional[Dict[str, object]] = None,
) -> Optional[Dict[str, object]]:
    personal_source = source in PERSONAL_CONVERSATION_SOURCES
    if source in {"daemon", "web_wake"}:
        # This writes only to Eve's local user-facing conversation surface. It is
        # not external outreach, so open repair clusters should not silence her.
        gate_reason = autonomy_action_block_reason("daemon_local_conversation")
        if gate_reason:
            append_entry("outreach_skipped", gate_reason, metadata={"source": source, "gate": "local_conversation_autonomy"})
            record_personal_conversation_check(
                source=source,
                status="blocked",
                reason=gate_reason,
                state=state,
            )
            return None
        pacing_reason = personal_conversation_pacing_reason(config)
        if pacing_reason:
            append_entry("outreach_skipped", pacing_reason, metadata={"source": source})
            record_personal_conversation_check(
                source=source,
                status="waiting",
                reason=pacing_reason,
                state=state,
            )
            return None
    result = generate_eve_outreach(
        config,
        allow_none=allow_none,
        source=source,
        timeout_seconds=timeout_seconds or int(config.get("outreach_timeout_seconds") or 90),
    )
    if result is None:
        if personal_source:
            record_personal_conversation_check(
                source=source,
                status="quiet",
                reason="Eve checked and did not find a grounded personal message to send.",
                state=state,
            )
        return None
    record = create_message(
        sender="eve",
        recipient="user",
        subject=str(result["subject"]),
        body=str(result["body"]),
        kind="proactive_outreach",
        status="unread",
        metadata={
            "model": result["model"],
            "source": source,
            "surface": "personal_conversation",
            "conversation_kind": "eve_initiated_personal",
            "local_only": True,
            "external_send_attempted": False,
            "source_entries": result["source_entries"],
            "source_thoughts": result["source_thoughts"],
            "source_threads": result["source_threads"],
            "source_messages": result["source_messages"],
        },
        notify=notify,
    )
    append_entry(
        "outreach_sent",
        str(result["subject"]),
        metadata={"message_id": record["id"], "thread_id": record["thread_id"], "source": source, "model": result["model"]},
    )
    if personal_source:
        record_personal_conversation_check(
            source=source,
            status="sent",
            reason=f"Eve opened a personal conversation: {result['subject']}",
            record=record,
            state=state,
        )
    return record


def generate_reflection(
    config: Dict[str, object],
    days: int,
    context_limit: int,
    max_tokens: int,
    timeout_seconds: Optional[int] = None,
) -> Dict[str, object]:
    ensure_version_snapshot(source="reflection_runtime")
    model = resolve_model(config, "reflection")
    think_level = str(config["think_level"])
    host = str(config["ollama_host"])
    human_context = ensure_human_context(config, source="reflection")
    active_mind = load_active_mind()
    recent_entries = read_entries(limit=context_limit, since_days=days)
    tensions = read_tensions(limit=20)
    experiments = read_experiments(limit=20)
    if not recent_entries:
        raise SystemExit("No recent entries found. Add entries with `capture` or `chat` first.")

    messages = [
        *build_eve_identity_system_messages(
            human_context=human_context,
            active_mind=active_mind,
        ),
        *[message for message in [build_inner_state_brief_message()] if message is not None],
        {"role": "system", "content": load_prompt("weekly_reflection.md")},
    ]
    messages.extend(build_supporting_system_messages(config, failure_limit=4, query_text=active_mind_retrieval_query(active_mind)))
    messages.extend(
        [
            {"role": "user", "content": build_reflection_prompt(recent_entries, days)},
            {"role": "user", "content": build_reflection_support_prompt(tensions, experiments)},
        ]
    )
    response = model_chat(
        config,
        model,
        messages,
        max_tokens=max_tokens,
        think_level=think_level,
        operation="reflection",
        timeout_seconds=timeout_seconds or int(config.get("reflection_timeout_seconds") or 180),
    )
    return {
        "response": response,
        "model": model,
        "source_entries": len(recent_entries),
    }


def suggest_proposal(
    config: Dict[str, object],
    source: str,
    max_tokens: int,
    timeout_seconds: Optional[int] = None,
) -> Dict[str, object]:
    ensure_version_snapshot(source=f"{source}_proposal_runtime")
    model = resolve_model(config, "proposal")
    think_level = str(config["think_level"])
    host = str(config["ollama_host"])
    context_limit = int(config["proposal_context_limit"])
    human_context = ensure_human_context(config, source="proposal")
    active_mind = load_active_mind()
    entries = read_entries(limit=context_limit)
    tensions = read_tensions(limit=12)
    experiments = read_experiments(limit=12)
    proposals = read_proposals(limit=8)
    if not entries and not tensions and not experiments:
        raise SystemExit("Not enough Eve context to draft a proposal yet.")

    messages = [
        *build_eve_identity_system_messages(
            human_context=human_context,
            active_mind=active_mind,
        ),
        {"role": "system", "content": load_prompt("proposal_suggestions.md")},
    ]
    messages.extend(build_supporting_system_messages(config, failure_limit=4, query_text=active_mind_retrieval_query(active_mind)))
    messages.append(
        {
            "role": "user",
            "content": build_proposal_support_prompt(entries, tensions, experiments, proposals),
        }
    )
    response = model_chat(
        config,
        model,
        messages,
        max_tokens=max_tokens,
        think_level=think_level,
        operation="proposal_suggest",
        timeout_seconds=timeout_seconds or int(config.get("proposal_timeout_seconds") or 180),
    )
    title = infer_title_from_text(response, fallback=f"Proposal Draft {utc_now()}")
    summary = " ".join(response.split())[:220]
    record = {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "updated_at": utc_now(),
        "title": title,
        "summary": summary,
        "body": response,
        "status": "draft",
        "source": source,
    }
    append_jsonl_record(PROPOSALS_PATH, record)
    append_entry(
        "proposal_drafted",
        title,
        metadata={"proposal_id": record["id"], "source": source, "model": model},
    )
    return record


def cmd_reflect(args: argparse.Namespace) -> int:
    config = load_config()
    apply_transient_model_override(config, args.model)
    recent_limit = args.context or int(config["reflection_context_limit"])
    num_predict = args.max_tokens or int(config["reflection_max_tokens"])
    result = generate_reflection(config, days=args.days, context_limit=recent_limit, max_tokens=num_predict)

    append_entry(
        "reflection",
        result["response"],
        metadata={"days": args.days, "model": result["model"], "source_entries": result["source_entries"]},
    )
    render_output(str(result["response"]))
    return 0


def cmd_show(args: argparse.Namespace) -> int:
    entries = read_entries(limit=args.limit, since_days=args.days, kinds=[args.kind] if args.kind else None)
    if not entries:
        print("No entries found.")
        return 0
    for entry in entries:
        print(f"{entry['timestamp']} [{entry['kind']}]")
        print(str(entry["text"]).strip())
        if entry.get("tags"):
            print("tags:", ", ".join(entry["tags"]))
        metadata = entry.get("metadata") or {}
        if metadata:
            print("metadata:", json.dumps(metadata, ensure_ascii=True))
        print()
    return 0


