def cmd_bootstrap_export(args: argparse.Namespace) -> int:
    payload = bootstrap_bundle_payload(
        primary_host=args.host or "",
        api_port=args.api_port,
        ollama_port=args.ollama_port,
    )
    output_path = Path(args.output).expanduser() if args.output else APP_DIR / "bootstrap_bundle.json"
    output_path.parent.mkdir(parents=True, exist_ok=True)
    output_path.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
    print(f"Wrote Eve bootstrap bundle to {output_path}")
    if payload.get("primary_eve_url"):
        print(f"primary_eve_url: {payload['primary_eve_url']}")
    if payload.get("primary_ollama_url"):
        print(f"primary_ollama_url: {payload['primary_ollama_url']}")
    print(f"models: {', '.join(payload.get('models') or []) or 'none configured'}")
    return 0


def cmd_bootstrap_import(args: argparse.Namespace) -> int:
    bundle_path = Path(args.bundle).expanduser()
    if not bundle_path.exists():
        raise SystemExit(f"Missing bootstrap bundle: {bundle_path}")
    try:
        payload = json.loads(bundle_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise SystemExit(f"Invalid bootstrap bundle at {bundle_path}: {exc}") from exc
    if not isinstance(payload, dict):
        raise SystemExit("Bootstrap bundle must be a JSON object.")
    result = apply_bootstrap_bundle(
        payload,
        use_primary_ollama=args.use_primary_ollama,
        pull_models=args.pull_models,
        ollama_pull_timeout_seconds=args.ollama_pull_timeout_seconds,
    )
    print("Imported Eve bootstrap bundle.")
    print(f"ollama_host: {result['ollama_host']}")
    print(f"models: {', '.join(result['models']) or 'none configured'}")
    if result["pulled_models"]:
        print(f"pulled_models: {', '.join(result['pulled_models'])}")
    if result["primary_eve_url"]:
        print(f"primary_eve_url: {result['primary_eve_url']}")
    return 0


def cmd_bootstrap_pull(args: argparse.Namespace) -> int:
    code_result = None
    if args.include_code:
        archive_bytes = fetch_code_bundle(
            host=args.host,
            api_port=args.api_port,
            timeout=args.code_timeout,
        )
        code_result = apply_code_bundle_archive(archive_bytes)
    payload = fetch_bootstrap_bundle(
        host=args.host,
        api_port=args.api_port,
        ollama_port=args.ollama_port,
        timeout=args.timeout,
    )
    result = apply_bootstrap_bundle(
        payload,
        use_primary_ollama=args.use_primary_ollama,
        pull_models=args.pull_models,
        ollama_pull_timeout_seconds=args.ollama_pull_timeout_seconds,
    )
    print("Pulled Eve bootstrap update from the primary host.")
    print(f"ollama_host: {result['ollama_host']}")
    print(f"models: {', '.join(result['models']) or 'none configured'}")
    if result["pulled_models"]:
        print(f"pulled_models: {', '.join(result['pulled_models'])}")
    if result["primary_eve_url"]:
        print(f"primary_eve_url: {result['primary_eve_url']}")
    if code_result is not None:
        print(f"code_updated_files: {len(code_result['updated_files'])}")
        if code_result["backup_root"]:
            print(f"code_backup_root: {code_result['backup_root']}")
    return 0


