def cmd_human_bootstrap(_: argparse.Namespace) -> int:
    config = load_config()
    entries = read_salient_entries(limit=18, since_days=30)
    thoughts = read_entries_by_kind("thought", limit=8)
    reflections = read_entries_by_kind("reflection", limit=4)
    threads = read_thread_summaries(limit=12)
    messages = read_lived_messages(limit=24)
    context = bootstrap_human_context(
        entries=entries,
        thoughts=thoughts,
        reflections=reflections,
        threads=threads,
        messages=messages,
        previous_context=load_human_context(),
        source="manual_bootstrap",
        project_memory=load_project_memory(max_chars=int(config["project_memory_max_chars"])),
    )
    save_human_context(context, snapshot_source="manual_bootstrap_human_context")
    state = load_state()
    state["last_human_context_at"] = context.get("updated_at")
    state["last_human_context_attempt_at"] = context.get("updated_at")
    save_state(state)
    append_entry(
        "human_context_refreshed",
        str(context["self_model"]["identity_statement"]),
        metadata={"source": "manual_bootstrap", "model": "deterministic"},
    )
    print("Bootstrapped human context from existing evidence.")
    print()
    return cmd_human_show(_)


