def cmd_mind_tick(args: argparse.Namespace) -> int:
    config = load_config()
    apply_transient_model_override(config, args.model)
    configured_timeout = int(config.get("mind_tick_timeout_seconds") or DEFAULT_CONFIG["mind_tick_timeout_seconds"])
    delegate_timeout = max(
        configured_timeout * 3,
        configured_timeout + 45,
        90,
    )
    delegated = delegate_cli_to_runtime(
        [
            "mind",
            "tick",
            *(["--model", args.model] if args.model else []),
            *(["--max-tokens", str(args.max_tokens)] if args.max_tokens else []),
        ],
        timeout_seconds=delegate_timeout,
    )
    if delegated is not None:
        return delegated
    max_tokens = args.max_tokens or int(config["mind_tick_max_tokens"])
    record = run_mind_tick(config, source="manual", max_tokens=max_tokens)
    report = format_active_mind_report(record["mind"])
    if record.get("used_fallback"):
        report += "\n\nfallback_reason: " + str(record.get("fallback_reason") or "unknown")
    print(report)
    return 0


