def cmd_sensory_tick(args: argparse.Namespace) -> int:
    delegated = delegate_cli_to_runtime(
        [
            "sensory",
            "tick",
            *(["--full"] if args.full else []),
            *(["--json"] if args.json else []),
            *(["--no-event"] if args.no_event else []),
        ],
        timeout_seconds=45,
    )
    if delegated is not None:
        return delegated
    config = load_config()
    prefer_runtime = running_from_runtime_bundle()
    state = load_state(prefer_runtime=prefer_runtime)
    frame = run_sensory_attention_tick(
        config,
        state,
        source="manual_sensory_tick",
        prefer_runtime=prefer_runtime,
        persist_event=not args.no_event,
    )
    save_state(state)
    # Make the selected frame causally available to the recurrent workspace in
    # the same bounded tick; no model or body action is invoked here.
    build_recurrent_conscious_state(
        source="manual_sensory_tick",
        persist=True,
        sensory_frame_override=frame,
    )
    if args.json:
        print(json.dumps(frame, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_sensory_attention_report(frame, full=args.full))
    return 0


