def cmd_conscious_state_ablate(args: argparse.Namespace) -> int:
    prefer_runtime = bool(args.runtime or daemon_runtime_running())
    report = run_conscious_state_ablation(prefer_runtime=prefer_runtime)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True))
    else:
        print(
            f"Causal conscious-state ablation: {report.get('passed_count') or 0}/{report.get('total') or 0} exercised contributions verified"
        )
        for lesion, result in (report.get("lesions") or {}).items():
            status = result.get("status") or ("passed" if result.get("passed") else "failed")
            print(
                f"- {lesion}: {status} | "
                f"{result.get('metric')} {result.get('baseline')} -> {result.get('lesioned')} "
                f"(delta {result.get('delta')})"
            )
            if args.full and result.get("first_order_action_preserved") is not None:
                print(
                    f"  first_order_action_preserved: {'yes' if result.get('first_order_action_preserved') else 'no'}"
                )
        if report.get("not_exercised"):
            print(
                "not_exercised: "
                + ", ".join(str(item) for item in report.get("not_exercised") or [])
            )
        print("boundary: causal contribution is evidence for an integrated candidate architecture, not proof of subjective experience")
    return 0 if report.get("passed") else 1


