    next_experiments = autonomy_agenda.get("next_experiments") if isinstance(autonomy_agenda.get("next_experiments"), list) else []
    last_supervisor = autonomy_agenda.get("last_supervisor") if isinstance(autonomy_agenda.get("last_supervisor"), dict) else {}
