def autonomy_free_run_action_menu(remaining_seconds: int) -> Dict[str, str]:
    minimum_seconds = {
        "mind_tick": 35,
        "thought": 35,
        "ambient_note": 5,
        "system_tasks": 15,
        "capability_tryout": 45,
        "service_health_check": 25,
        "cleanup_candidate_check": 25,
        "openclaw_log_check": 20,
        "openclaw_sync_check": 75,
        "updates_status": 5,
        "proposal_suggestion": 75,
        "wait_observe": 5,
    }
    return {
        action: description
        for action, description in AUTONOMY_FREE_RUN_ACTIONS.items()
        if remaining_seconds >= minimum_seconds.get(action, 10)
    } or {"wait_observe": AUTONOMY_FREE_RUN_ACTIONS["wait_observe"]}


def autonomy_free_run_action_balance(previous_actions: List[Dict[str, object]]) -> Dict[str, int]:
    recent_actions = [str(item.get("action") or "") for item in previous_actions[-6:] if item.get("action")]
    recent_system_touch = [item for item in recent_actions if item in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS]
    recent_inward = [item for item in recent_actions if item in AUTONOMY_FREE_RUN_INWARD_ACTIONS]
    recent_passive = [item for item in recent_actions if item in AUTONOMY_FREE_RUN_PASSIVE_ACTIONS]
    inward_streak = 0
    passive_streak = 0
    for action in reversed(recent_actions):
        if action in AUTONOMY_FREE_RUN_INWARD_ACTIONS:
            inward_streak += 1
        else:
            break
    for action in reversed(recent_actions):
        if action in AUTONOMY_FREE_RUN_PASSIVE_ACTIONS:
            passive_streak += 1
        else:
            break
    return {
        "recent_count": len(recent_actions),
        "recent_system_touch_count": len(recent_system_touch),
        "recent_inward_count": len(recent_inward),
        "recent_passive_count": len(recent_passive),
        "recent_inward_streak": inward_streak,
        "recent_passive_streak": passive_streak,
    }


def autonomy_free_run_action_novelty(previous_actions: List[Dict[str, object]]) -> Dict[str, object]:
    recent = previous_actions[-6:]
    recent_actions = [str(item.get("action") or "") for item in recent if item.get("action")]
    last_action = recent_actions[-1] if recent_actions else ""
    last_summary = normalize_text_value(recent[-1].get("summary") if recent else "", fallback="", limit=160)
    recent_action_counts: Dict[str, int] = {}
    same_action_streak = 0
    same_summary_streak = 0
    for action in recent_actions:
        if not action:
            continue
        recent_action_counts[action] = int(recent_action_counts.get(action, 0)) + 1
    for item in reversed(recent):
        action = str(item.get("action") or "")
        if action == last_action and action:
            same_action_streak += 1
        else:
            break
    for item in reversed(recent):
        action = str(item.get("action") or "")
        summary = normalize_text_value(item.get("summary"), fallback="", limit=160)
        if action == last_action and summary and summary == last_summary:
            same_summary_streak += 1
        else:
            break
    return {
        "last_action": last_action,
        "last_summary": last_summary,
        "same_action_streak": same_action_streak,
        "same_summary_streak": same_summary_streak,
        "distinct_recent_actions": len({item for item in recent_actions if item}),
        "recent_action_counts": recent_action_counts,
        "last_action_recent_count": int(recent_action_counts.get(last_action, 0)) if last_action else 0,
    }


def autonomy_free_run_action_family(action: object) -> str:
    return str(AUTONOMY_FREE_RUN_ACTION_FAMILIES.get(str(action or ""), "other"))


def autonomy_free_run_family_actions(family: object) -> List[str]:
    normalized = str(family or "").strip().lower()
    return [
        action
        for action, action_family in AUTONOMY_FREE_RUN_ACTION_FAMILIES.items()
        if action_family == normalized
    ]


def autonomy_free_run_progression(
    previous_actions: List[Dict[str, object]],
    *,
    available_actions: Optional[Iterable[str]] = None,
) -> Dict[str, object]:
    completed_actions = [
        str(item.get("action") or "")
        for item in previous_actions
        if str(item.get("status") or "") == "completed" and item.get("action")
    ]
    completed_families = [
        autonomy_free_run_action_family(action)
        for action in completed_actions
        if autonomy_free_run_action_family(action) != "other"
    ]
    completed_grounded_families = [
        family for family in completed_families if family in AUTONOMY_FREE_RUN_GROUNDED_FAMILIES
    ]
    family_counts: Dict[str, int] = {}
    for family in completed_families:
        family_counts[family] = int(family_counts.get(family, 0)) + 1
    last_family = completed_families[-1] if completed_families else ""
    last_grounded_family = completed_grounded_families[-1] if completed_grounded_families else ""
    same_family_streak = 0
    same_grounded_family_streak = 0
    for family in reversed(completed_families):
        if family == last_family and family:
            same_family_streak += 1
        else:
            break
    for family in reversed(completed_grounded_families):
        if family == last_grounded_family and family:
            same_grounded_family_streak += 1
        else:
            break
    available_family_counts: Dict[str, int] = {}
    available_families: List[str] = []
    available_grounded_families: List[str] = []
    if available_actions is not None:
        for action in available_actions:
            family = autonomy_free_run_action_family(action)
            if family == "other":
                continue
            available_family_counts[family] = int(available_family_counts.get(family, 0)) + 1
        available_families = list(available_family_counts.keys())
        available_grounded_families = [
            family for family in available_families if family in AUTONOMY_FREE_RUN_GROUNDED_FAMILIES
        ]
    completed_grounded_family_set = list(dict.fromkeys(completed_grounded_families))
    missing_grounded_families = [
        family
        for family in available_grounded_families
        if family not in completed_grounded_family_set
    ]
    return {
        "completed_action_count": len(completed_actions),
        "completed_distinct_actions": len({action for action in completed_actions if action}),
        "completed_families": completed_families,
        "completed_family_counts": family_counts,
        "completed_distinct_families": len({family for family in completed_families if family}),
        "completed_grounded_families": completed_grounded_family_set,
        "completed_grounded_family_count": len(completed_grounded_family_set),
        "available_families": available_families,
        "available_grounded_families": available_grounded_families,
        "available_grounded_family_count": len(available_grounded_families),
        "missing_grounded_families": missing_grounded_families,
        "last_family": last_family,
        "last_grounded_family": last_grounded_family,
        "same_family_streak": same_family_streak,
        "same_grounded_family_streak": same_grounded_family_streak,
        "last_family_recent_count": int(family_counts.get(last_family, 0)) if last_family else 0,
        "last_grounded_family_recent_count": int(family_counts.get(last_grounded_family, 0)) if last_grounded_family else 0,
    }


def autonomy_free_run_action_saturation(previous_actions: List[Dict[str, object]]) -> Dict[str, object]:
    recent = [item for item in previous_actions[-8:] if str(item.get("status") or "") == "completed"]
    by_action: Dict[str, Dict[str, object]] = {}
    for item in recent:
        action = str(item.get("action") or "")
        if not action:
            continue
        summary = normalize_text_value(item.get("summary"), fallback="", limit=160)
        info = by_action.setdefault(
            action,
            {
                "count": 0,
                "summaries": [],
            },
        )
        info["count"] = int(info.get("count") or 0) + 1
        if summary:
            info["summaries"] = unique_compact([*(info.get("summaries") or []), summary], limit=4)
    saturated_actions: Dict[str, str] = {}
    for action, info in by_action.items():
        count = int(info.get("count") or 0)
        distinct_summaries = len(info.get("summaries") or [])
        if count >= 3 and distinct_summaries <= 2:
            saturated_actions[action] = "This surface has already been checked repeatedly without enough new evidence."
        elif count >= 2 and distinct_summaries <= 1:
            saturated_actions[action] = "This surface is returning the same signal and is close to saturation."
    return {
        "recent_completed_actions": len(recent),
        "by_action": by_action,
        "saturated_actions": saturated_actions,
    }


def is_autonomy_choice_perf_event(event: Dict[str, object]) -> bool:
    if str(event.get("category") or "") != "model_call":
        return False
    metadata = event.get("metadata") if isinstance(event.get("metadata"), dict) else {}
    operation = str(metadata.get("operation") or event.get("name") or "")
    normalized = " ".join(operation.lower().split())
    return normalized.startswith("autonomy_free_run_choice")


def normalize_autonomy_free_run_style(value: object, default: str = "explorer") -> str:
    fallback = default if default in AUTONOMY_FREE_RUN_STYLES else "explorer"
    style = str(value or fallback).strip().lower()
    if style not in AUTONOMY_FREE_RUN_STYLES:
        style = fallback
    return style


def autonomy_free_run_style_description(style: object) -> str:
    normalized = normalize_autonomy_free_run_style(style)
    if normalized == "explorer":
        return "Favor curiosity, novelty, and exploring multiple grounded surfaces instead of repetitive reassurance checks."
    return "Favor grounded progress, bounded checks, and one clear next move over performative wandering."


def default_autonomy_free_run_objective(remaining_seconds: int, *, style: object = "explorer") -> Dict[str, object]:
    normalized_style = normalize_autonomy_free_run_style(style)
    phase = "orient"
    objective = "Get oriented to one real live constraint or opportunity."
    success = [
        "collect one grounded signal from the live system",
        "identify one bounded next move worth advancing",
    ]
    if normalized_style == "explorer":
        objective = "Survey the live system with curiosity and find one non-obvious thread worth following."
        success = [
            "touch a live surface that can reveal something new",
            "surface one novel observation, tension, or opportunity",
            "leave one stronger exploration thread behind",
        ]
    if remaining_seconds <= 35:
        phase = "consolidate"
        objective = "Stop manufacturing motion, consolidate what the run learned, and leave a clean next step."
        success = [
            "avoid starting a long new branch right before the deadline",
            "leave one grounded next step or observation behind",
        ]
        if normalized_style == "explorer":
            objective = "Compress the most interesting discovery into a clean carry-forward thread instead of opening another loop."
            success = [
                "capture the most interesting grounded discovery",
                "leave one next exploration question or experiment behind",
            ]
    return {
        "style": normalized_style,
        "phase": phase,
        "objective": objective,
        "mission": "become more human and continuously improve yourself",
        "success_signals": success,
        "preferred_actions": [],
        "avoid_actions": {},
    }


def autonomy_free_run_objective(
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
    *,
    style: object = "explorer",
) -> Dict[str, object]:
    normalized_style = normalize_autonomy_free_run_style(style)
    objective = default_autonomy_free_run_objective(remaining_seconds, style=normalized_style)
    saturation = autonomy_free_run_action_saturation(previous_actions)
    counts = snapshot.get("counts") if isinstance(snapshot.get("counts"), dict) else {}
    components = snapshot.get("components") if isinstance(snapshot.get("components"), dict) else {}
    active_mind = snapshot.get("active_mind") if isinstance(snapshot.get("active_mind"), dict) else {}
    autonomy = snapshot.get("autonomy") if isinstance(snapshot.get("autonomy"), dict) else {}
    current_focus = normalize_text_value(active_mind.get("current_focus"), fallback="", limit=220)
    agenda_focus = normalize_text_value(autonomy.get("current_focus"), fallback="", limit=220)
    if focus_indicates_operational_recap(current_focus):
        current_focus = agenda_focus
    active_threads = autonomy.get("active_threads") if isinstance(autonomy.get("active_threads"), list) else []
    next_experiments = autonomy.get("next_experiments") if isinstance(autonomy.get("next_experiments"), list) else []
    agenda_primary = next_experiments[0] if next_experiments else (active_threads[0] if active_threads else {})
    agenda_action = normalize_text_value(
        agenda_primary.get("preferred_action") if isinstance(agenda_primary, dict) else "",
        fallback="",
        limit=80,
    )
    openclaw_status = snapshot.get("openclaw") if isinstance(snapshot.get("openclaw"), dict) else {}
    openclaw_attention = openclaw_attention_needs_action(openclaw_status)
    openclaw_avoid_actions = (
        {}
        if openclaw_attention
        else {
            "openclaw_log_check": "Latest OpenClaw status is recovered or non-actionable; do not recheck logs without a new OpenClaw signal.",
            "openclaw_sync_check": "Latest OpenClaw sync is recovered or non-actionable; do not sync again without a new OpenClaw signal.",
        }
    )
    recent_failure_avoid_actions = autonomy_recent_failure_avoid_actions(snapshot, previous_actions)
    if agenda_action in {"openclaw_log_check", "openclaw_sync_check"} and not openclaw_attention:
        agenda_action = ""
        objective["stale_agenda_note"] = "OpenClaw carry-forward was suppressed because the latest OpenClaw status is recovered or non-actionable."
    last_supervisor_score = clamp_int(autonomy.get("last_supervisor_score"), 0, minimum=0, maximum=100)
    last_supervisor_verdict = normalize_text_value(autonomy.get("last_supervisor_verdict"), fallback="", limit=40)
    update_signal_count = int(components.get("update_signal_count") or 0)
    recent_actions = [str(item.get("action") or "") for item in previous_actions[-6:] if item.get("action")]
    recent_system_touch_count = len([item for item in recent_actions if item in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS])
    recent_health_count = recent_actions.count("service_health_check")
    non_choice_perf_failures = int(counts.get("perf_failures_recent") or 0)
    choice_failures = int(counts.get("choice_failures_recent") or 0)
    saturated_actions = saturation.get("saturated_actions") if isinstance(saturation.get("saturated_actions"), dict) else {}
    preferred_actions: List[str] = []
    avoid_actions: Dict[str, str] = {**openclaw_avoid_actions, **recent_failure_avoid_actions, **dict(saturated_actions)}

    if remaining_seconds <= 35:
        objective["phase"] = "consolidate"
        if normalized_style == "explorer":
            objective["objective"] = "Consolidate the strongest discovery and leave a clean exploratory thread instead of opening another loop."
            preferred_actions = ["ambient_note", "mind_tick", "proposal_suggestion", "wait_observe"]
        else:
            objective["objective"] = "Consolidate the run instead of opening a fresh repetitive loop."
            preferred_actions = ["ambient_note", "mind_tick", "wait_observe"]
    elif not previous_actions:
        if normalized_style == "explorer":
            objective["phase"] = "survey"
            objective["objective"] = "Start with one grounded action that can reveal a new live thread instead of defaulting to routine reassurance."
            preferred_actions = ["system_tasks", "capability_tryout", "updates_status", "openclaw_log_check", "thought"]
        else:
            objective["phase"] = "orient"
            objective["objective"] = "Start with one grounded action that clarifies the most important live pressure or opportunity."
            preferred_actions = ["system_tasks", "updates_status", "service_health_check"]
    elif recent_system_touch_count == 0:
        if normalized_style == "explorer":
            objective["phase"] = "re-ground"
            objective["objective"] = "Return to the live system so exploration stays attached to reality instead of self-talk."
            preferred_actions = ["system_tasks", "updates_status", "openclaw_log_check"]
        else:
            objective["phase"] = "orient"
            objective["objective"] = "Re-ground the run in live evidence before thinking more."
            preferred_actions = ["system_tasks", "service_health_check", "updates_status"]
    elif saturated_actions:
        if normalized_style == "explorer":
            objective["phase"] = "branch"
            objective["objective"] = "Stop circling the same surface and branch into a different grounded thread that could teach Eve something new."
            preferred_actions = ["capability_tryout", "updates_status", "openclaw_log_check", "cleanup_candidate_check", "system_tasks"]
        else:
            objective["phase"] = "advance"
            objective["objective"] = "Stop rereading the same surface and advance a different grounded thread."
            preferred_actions = ["system_tasks", "openclaw_log_check", "openclaw_sync_check", "cleanup_candidate_check", "updates_status"]
    elif non_choice_perf_failures > 0:
        if normalized_style == "explorer":
            objective["phase"] = "investigate"
            objective["objective"] = "Investigate the real external failure signal, but stay curious about the underlying cause instead of performing generic reassurance checks."
            preferred_actions = ["openclaw_log_check", "service_health_check", "system_tasks", "cleanup_candidate_check"]
        else:
            objective["phase"] = "investigate"
            objective["objective"] = "Investigate a real external failure signal without collapsing into repeated checks."
            preferred_actions = ["service_health_check", "openclaw_log_check", "system_tasks"]
    elif update_signal_count > 0 and recent_actions.count("updates_status") == 0:
        if normalized_style == "explorer":
            objective["phase"] = "investigate"
            objective["objective"] = "Inspect one live improvement surface and decide whether it opens a new thread worth following."
            preferred_actions = ["updates_status", "capability_tryout", "system_tasks", "proposal_suggestion"]
        else:
            objective["phase"] = "investigate"
            objective["objective"] = "Inspect one live improvement surface and decide whether it deserves deeper attention."
            preferred_actions = ["updates_status", "system_tasks"]
    else:
        if normalized_style == "explorer":
            objective["phase"] = "explore"
            objective["objective"] = "Push into a different verified surface, extract one novel observation, and leave a stronger next experiment behind."
            preferred_actions = ["capability_tryout", "system_tasks", "openclaw_log_check", "updates_status", "cleanup_candidate_check"]
        else:
            objective["phase"] = "advance"
            objective["objective"] = "Turn the current understanding into one bounded, non-performative next move."
            preferred_actions = ["system_tasks", "openclaw_sync_check", "openclaw_log_check", "cleanup_candidate_check"]

    if current_focus:
        objective["objective"] = normalize_text_value(
            f"{objective['objective']} Keep this focus in view: {current_focus}",
            fallback=objective["objective"],
            limit=220,
        )
    if choice_failures > 0:
        avoid_actions.setdefault(
            "service_health_check",
            "Recent chooser failures are not the same thing as a system-health incident; do not overreact with another generic health audit.",
        )
        if "system_tasks" not in preferred_actions:
            preferred_actions.insert(0, "system_tasks")
    if normalized_style == "explorer" and non_choice_perf_failures <= 0:
        avoid_actions.setdefault(
            "service_health_check",
            "Explorer mode should not default to a generic health audit unless there is a fresh external failure signal to investigate.",
        )
    if recent_health_count >= 2:
        avoid_actions.setdefault(
            "service_health_check",
            "Multiple recent health checks already ran; only choose another if there is genuinely new evidence to inspect.",
        )
    if agenda_action and agenda_action in AUTONOMY_FREE_RUN_ACTIONS and agenda_action not in avoid_actions:
        preferred_actions = unique_compact([agenda_action, *preferred_actions], limit=5)
    if not previous_actions and agenda_primary:
        agenda_title = normalize_text_value(agenda_primary.get("title"), fallback="", limit=160)
        agenda_why = normalize_text_value(agenda_primary.get("why"), fallback="", limit=220)
        if agenda_title:
            objective["objective"] = normalize_text_value(
                f"Advance the carry-forward agenda thread `{agenda_title}` while still searching for grounded novelty.",
                fallback=objective["objective"],
                limit=220,
            )
            if agenda_why:
                objective["success_signals"] = unique_compact(
                    [
                        *objective.get("success_signals", []),
                        f"move the carry-forward thread forward: {agenda_why}",
                    ],
                    limit=5,
                )
    if last_supervisor_score > 0 and last_supervisor_score < 55:
        objective["phase"] = "recover"
        objective["objective"] = normalize_text_value(
            "Recover from the last weak autonomy window by meeting the missing quotas, reducing chooser strain, and producing one concrete result.",
            fallback=objective["objective"],
            limit=220,
        )
        recovery_preferred_actions = [
            action
            for action in preferred_actions
            if openclaw_attention or action not in {"openclaw_log_check", "openclaw_sync_check"}
        ]
        recovery_actions = [agenda_action, "capability_tryout", "system_tasks", "cleanup_candidate_check", *recovery_preferred_actions]
        if openclaw_attention:
            recovery_actions.insert(3, "openclaw_log_check")
        preferred_actions = unique_compact(
            recovery_actions,
            limit=5,
        )
        objective["success_signals"] = unique_compact(
            [
                *objective.get("success_signals", []),
                "meet the missing autonomy quotas this window",
                "reduce repetition and chooser strain compared with the last window",
            ],
            limit=5,
        )
    elif last_supervisor_score >= 80 and agenda_primary:
        objective["success_signals"] = unique_compact(
            [
                *objective.get("success_signals", []),
                "push the strongest carry-forward thread one step further",
            ],
            limit=5,
        )

    objective["preferred_actions"] = unique_compact([action for action in preferred_actions if action not in avoid_actions], limit=5)
    objective["avoid_actions"] = avoid_actions
    objective["success_signals"] = unique_compact(
        [
            *objective.get("success_signals", []),
            "avoid repeating the same check without new evidence",
            "leave one clearer next step than the run started with",
            *(
                [
                    "surface one genuinely new observation instead of merely rechecking stability",
                    "touch a second grounded surface if the first one saturates quickly",
                ]
                if normalized_style == "explorer"
                else []
            ),
        ],
        limit=5,
    )
    if last_supervisor_verdict:
        objective["supervisor_hint"] = last_supervisor_verdict
    return objective


def autonomy_free_run_diversifying_actions(
    repeated_action: str,
    *,
    available: Iterable[str],
    openclaw_attention: bool = False,
    style: object = "explorer",
) -> List[str]:
    available_set = set(available)
    normalized_style = normalize_autonomy_free_run_style(style)
    ordered = [
        "system_tasks",
        "capability_tryout",
        "service_health_check",
        "cleanup_candidate_check",
        "openclaw_log_check",
        "updates_status",
        "openclaw_sync_check",
    ]
    if normalized_style == "explorer":
        ordered = [
            "capability_tryout",
            "updates_status",
            "openclaw_log_check",
            "cleanup_candidate_check",
            "system_tasks",
            "proposal_suggestion",
            "thought",
            "mind_tick",
            "service_health_check",
            "openclaw_sync_check",
        ]
    if openclaw_attention:
        ordered = [
            "capability_tryout",
            "openclaw_log_check",
            "system_tasks",
            "updates_status",
            "cleanup_candidate_check",
            "proposal_suggestion" if normalized_style == "explorer" else "service_health_check",
            "openclaw_sync_check",
        ]
    return [action for action in ordered if action in available_set and action != repeated_action]


def autonomy_recent_action_records(
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
) -> List[Dict[str, object]]:
    records: List[Dict[str, object]] = []
    for item in snapshot.get("recent_actions", []) if isinstance(snapshot.get("recent_actions"), list) else []:
        if isinstance(item, dict):
            records.append(item)
    for item in previous_actions[-8:]:
        if isinstance(item, dict):
            records.append(item)
    return records


def openclaw_sync_write_blocked(record: Dict[str, object]) -> bool:
    if str(record.get("action") or "") != "openclaw_sync_check":
        return False
    summary = " ".join(
        normalize_text_value(record.get(field), fallback="", limit=500)
        for field in ["summary", "reason", "error", "stderr"]
        if record.get(field)
    ).lower()
    if not any(marker in summary for marker in OPENCLAW_SYNC_WRITE_BLOCK_MARKERS):
        return False
    tree_status = str(record.get("tree_status") or record.get("execution_tree_status") or "").upper()
    verification = action_result_explicit_verification(record)
    status = str(record.get("status") or "").strip().lower()
    return tree_status in {"FAILURE", "FAILED", "ERROR"} or verification is False or status in {"failed", "error"}


def autonomy_recent_failure_avoid_actions(
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
) -> Dict[str, str]:
    avoid: Dict[str, str] = {}
    records = autonomy_recent_action_records(snapshot, previous_actions)
    if any(openclaw_sync_write_blocked(record) for record in records):
        avoid[
            "openclaw_sync_check"
        ] = "Recent OpenClaw sync reached the gateway but failed on context artifact writes; cool down sync retries until the write-path repair is verified."
        if any(str(record.get("action") or "") == "openclaw_log_check" for record in records):
            avoid[
                "openclaw_log_check"
            ] = "A fresh OpenClaw log check already ran after the sync write-path failure; branch to a different surface until the write-path repair is verified."
    return avoid


def autonomy_free_run_family_branch_actions(
    family: str,
    *,
    available: Iterable[str],
    style: object = "explorer",
    openclaw_attention: bool = False,
) -> List[str]:
    available_set = set(available)
    normalized_style = normalize_autonomy_free_run_style(style)
    ordered: Dict[str, List[str]] = {
        "updates": ["updates_status"],
        "openclaw": ["openclaw_log_check", "openclaw_sync_check"],
        "cleanup": ["cleanup_candidate_check"],
        "tasks": ["system_tasks"],
        "capability": ["capability_tryout"],
        "proposal": ["proposal_suggestion"],
        "health": ["service_health_check"],
        "inner": ["thought", "mind_tick", "ambient_note"],
        "observe": ["wait_observe"],
    }
    if openclaw_attention and family == "openclaw":
        ordered["openclaw"] = ["openclaw_log_check", "openclaw_sync_check"]
    if normalized_style != "explorer" and family == "proposal":
        ordered["proposal"] = []
    return [action for action in ordered.get(family, []) if action in available_set]


def autonomy_free_run_guidance(
    menu: Dict[str, str],
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
    *,
    style: object = "explorer",
    config: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    effective_config = config or load_config()
    available = set(menu)
    balance = autonomy_free_run_action_balance(previous_actions)
    novelty = autonomy_free_run_action_novelty(previous_actions)
    normalized_style = normalize_autonomy_free_run_style(style)
    progression = autonomy_free_run_progression(previous_actions, available_actions=menu.keys())
    objective = autonomy_free_run_objective(snapshot, previous_actions, remaining_seconds, style=normalized_style)
    objective_avoid_actions = objective.get("avoid_actions") if isinstance(objective.get("avoid_actions"), dict) else {}
    recent_actions = [str(item.get("action") or "") for item in previous_actions[-6:] if item.get("action")]
    recommendations: List[str] = []
    reasons: List[str] = []

    def recommend(action: str, reason: str) -> None:
        if action in {"openclaw_log_check", "openclaw_sync_check"} and not openclaw_attention:
            return
        if action in objective_avoid_actions:
            return
        if action in available and action not in recommendations:
            recommendations.append(action)
            reasons.append(reason)

    counts = snapshot.get("counts") if isinstance(snapshot.get("counts"), dict) else {}
    components = snapshot.get("components") if isinstance(snapshot.get("components"), dict) else {}
    openclaw = snapshot.get("openclaw") if isinstance(snapshot.get("openclaw"), dict) else {}
    system = snapshot.get("system") if isinstance(snapshot.get("system"), dict) else {}
    autonomy = snapshot.get("autonomy") if isinstance(snapshot.get("autonomy"), dict) else {}
    quota_status = autonomy_free_run_quota_status(previous_actions)
    quota_records = quota_status.get("quotas") if isinstance(quota_status.get("quotas"), dict) else {}
    unmet_quotas = quota_status.get("unmet") if isinstance(quota_status.get("unmet"), list) else []
    concrete_outcomes = quota_status.get("concrete_outcomes") if isinstance(quota_status.get("concrete_outcomes"), list) else []
    completed_action_count = int(progression.get("completed_action_count") or 0)
    completed_family_counts = (
        progression.get("completed_family_counts")
        if isinstance(progression.get("completed_family_counts"), dict)
        else {}
    )
    perf_failures_recent = int(counts.get("perf_failures_recent") or 0)
    choice_failures_recent = int(counts.get("choice_failures_recent") or 0)
    update_signal_count = int(components.get("update_signal_count") or 0)
    fast_probe_ms = system.get("fast_probe_ms")
    deep_probe_ms = system.get("deep_probe_ms")
    system_load_state = normalize_text_value(system.get("load_state"), fallback="", limit=40)
    recent_updates_count = recent_actions.count("updates_status")
    recent_system_tasks_count = recent_actions.count("system_tasks")
    recent_health_count = recent_actions.count("service_health_check")
    recent_openclaw_log_count = recent_actions.count("openclaw_log_check")
    recent_cleanup_count = recent_actions.count("cleanup_candidate_check")
    missing_grounded_families = progression.get("missing_grounded_families") if isinstance(progression.get("missing_grounded_families"), list) else []
    completed_grounded_family_count = int(progression.get("completed_grounded_family_count") or 0)
    available_grounded_family_count = int(progression.get("available_grounded_family_count") or 0)
    last_grounded_family = str(progression.get("last_grounded_family") or "")
    same_grounded_family_streak = int(progression.get("same_grounded_family_streak") or 0)
    openclaw_attention = openclaw_attention_needs_action(openclaw)
    openclaw_ready = bool(
        parse_boolish(openclaw.get("installed"))
        or parse_boolish(openclaw.get("ready"))
        or str(openclaw.get("status") or "").strip().lower() in {"ok", "ready", "installed", "healthy"}
    )
    conscious_snapshot = snapshot.get("conscious_state") if isinstance(snapshot.get("conscious_state"), dict) else {}
    conscious_affordances = (
        conscious_snapshot.get("affordances")
        if isinstance(conscious_snapshot.get("affordances"), list)
        else []
    )
    selected_inquiry = (
        conscious_snapshot.get("selected_inquiry")
        if isinstance(conscious_snapshot.get("selected_inquiry"), dict)
        else {}
    )
    if not selected_inquiry:
        selected_inquiry = next(
            (
                {
                    "id": item.get("inquiry_id"),
                    "question": item.get("epistemic_question"),
                    "selected_action": item.get("id"),
                    "expected_observation": item.get("expected_observation"),
                    "source_fingerprint": item.get("source_fingerprint"),
                    "attempt_count": item.get("inquiry_attempt_count") or 0,
                    "attempted_actions": item.get("inquiry_attempted_actions") or [],
                    "failed_actions": item.get("inquiry_failed_actions") or [],
                    "remaining_actions": item.get("inquiry_remaining_actions") or [],
                    "recovery_step": bool(item.get("inquiry_recovery_step")),
                }
                for item in conscious_affordances
                if isinstance(item, dict) and item.get("inquiry_id")
            ),
            {},
        )
    inquiry_action = normalize_text_value(selected_inquiry.get("selected_action"), fallback="", limit=80)
    inquiry_attempt_count = clamp_int(selected_inquiry.get("attempt_count"), 0, minimum=0, maximum=100)
    inquiry_attempted_actions = normalize_text_list(selected_inquiry.get("attempted_actions"), limit=5)
    inquiry_failed_actions = normalize_text_list(selected_inquiry.get("failed_actions"), limit=5)
    inquiry_recovery_step = bool(
        selected_inquiry.get("recovery_step")
        or (inquiry_attempt_count > 0 and inquiry_action and inquiry_action not in inquiry_attempted_actions)
    )
    inquiry_probe_available = bool(
        inquiry_action in available
        and str(selected_inquiry.get("status") or "open") in {"open", "in_progress"}
        and inquiry_action not in inquiry_attempted_actions
    )
    if inquiry_probe_available:
        # Generic exploration cooldowns must not suppress a new, source-owned
        # question.  The question's own attempt ledger is the repetition gate.
        objective_avoid_actions.pop(inquiry_action, None)
        objective["avoid_actions"] = objective_avoid_actions
        inquiry_reason = normalize_text_value(
            (
                (
                    "The prior evidence path did not answer Eve's source-attributed question. "
                    f"Do not repeat {format_human_context_list(inquiry_attempted_actions) or 'the failed probe'}; "
                    f"use the unused alternative `{inquiry_action}`. "
                )
                if inquiry_recovery_step
                else "The recurrent world model has a source-attributed unresolved question. "
            )
            + f"Question: {selected_inquiry.get('question') or 'unknown'}. "
            + f"Expected observation: {selected_inquiry.get('expected_observation') or 'a bounded factual result'}.",
            fallback="The recurrent world model selected a bounded probe for an unresolved question.",
            limit=300,
        )
        recommendations.insert(0, inquiry_action)
        reasons.insert(0, inquiry_reason)
    for affordance in sorted(
        [item for item in conscious_affordances if isinstance(item, dict)],
        key=lambda item: float(item.get("value") or 0.0),
        reverse=True,
    ):
        action_id = normalize_text_value(affordance.get("id"), fallback="", limit=80)
        if action_id not in available:
            continue
        recommend(
            action_id,
            normalize_text_value(
                (
                    f"The recurrent conscious-state action model valued this at {affordance.get('value')} "
                    f"(utility {affordance.get('expected_utility')}, epistemic value {affordance.get('epistemic_value')}, "
                    f"continuity {affordance.get('continuity_support')}, broadcast alignment "
                    f"{affordance.get('broadcast_alignment')}, risk {affordance.get('risk')})."
                ),
                fallback="The recurrent state selected this as its highest-value admitted affordance.",
                limit=220,
            ),
        )
    curiosity = autonomy_curiosity_state(
        effective_config,
        previous_actions,
        remaining_seconds,
        openclaw_ready=openclaw_ready,
        openclaw_attention=openclaw_attention,
    )
    agenda_next_experiments = autonomy.get("next_experiments") if isinstance(autonomy.get("next_experiments"), list) else []
    agenda_active_threads = autonomy.get("active_threads") if isinstance(autonomy.get("active_threads"), list) else []
    agenda_primary = agenda_next_experiments[0] if agenda_next_experiments else (agenda_active_threads[0] if agenda_active_threads else {})
    agenda_action = normalize_text_value(
        agenda_primary.get("preferred_action") if isinstance(agenda_primary, dict) else "",
        fallback="",
        limit=80,
    )
    if agenda_action in {"openclaw_log_check", "openclaw_sync_check"} and not openclaw_attention:
        agenda_action = ""
    agenda_title = normalize_text_value(
        agenda_primary.get("title") if isinstance(agenda_primary, dict) else "",
        fallback="",
        limit=140,
    )
    last_supervisor_score = clamp_int(autonomy.get("last_supervisor_score"), 0, minimum=0, maximum=100)
    chooser_load = "normal"
    if (
        system_load_state == "hot"
        or choice_failures_recent >= 16
        or (isinstance(fast_probe_ms, (int, float)) and float(fast_probe_ms) >= 2200)
        or (isinstance(deep_probe_ms, (int, float)) and float(deep_probe_ms) >= 6000)
    ):
        chooser_load = "high"
    elif (
        choice_failures_recent >= 8
        or (isinstance(fast_probe_ms, (int, float)) and float(fast_probe_ms) >= 1200)
        or (isinstance(deep_probe_ms, (int, float)) and float(deep_probe_ms) >= 3500)
    ):
        chooser_load = "medium"

    family_cooldowns: Dict[str, Dict[str, object]] = {}
    cooldown_actions: Dict[str, str] = {}
    if normalized_style == "explorer" and completed_action_count >= 4:
        for family, raw_count in completed_family_counts.items():
            family_name = str(family or "")
            family_count = int(raw_count or 0)
            if not family_name or family_name in {"other", "observe", "inner"}:
                continue
            family_ratio = family_count / max(1, completed_action_count)
            family_count_floor = 2 if normalized_style == "explorer" else 3
            if family_count < family_count_floor or family_ratio < 0.45:
                continue
            if family_name == "capability" and "capability_tryout" in unmet_quotas:
                continue
            family_cooldowns[family_name] = {
                "count": family_count,
                "completed_count": completed_action_count,
                "ratio": round(family_ratio, 3),
                "reason": (
                    f"The `{family_name}` family already occupies {family_count}/{completed_action_count} "
                    "completed actions; branch before spending more budget there."
                ),
            }
            for action_name in autonomy_free_run_family_actions(family_name):
                if action_name in available:
                    cooldown_actions[action_name] = str(family_cooldowns[family_name]["reason"])
    if cooldown_actions:
        objective_avoid_actions = {**objective_avoid_actions, **cooldown_actions}
        objective["avoid_actions"] = objective_avoid_actions

    if not previous_actions and "system_tasks" in available:
        recommend("system_tasks", "Start with a grounded system-touching check instead of pure introspection.")
    if normalized_style == "explorer" and not previous_actions:
        recommend("capability_tryout", "Explorer mode should sometimes learn by doing, not only by inspecting status surfaces.")
        recommend("updates_status", "Explorer mode starts by scanning a fresh surface for change signals or new openings.")
        if openclaw_attention:
            recommend("openclaw_log_check", "Fresh OpenClaw runtime logs can reveal non-obvious movement when OpenClaw has an active signal.")
    if normalized_style == "explorer" and "capability_tryout" in available and bool(curiosity.get("curiosity_due")):
        preferred_variant = str(curiosity.get("preferred_variant") or "verified capability")
        untried = format_human_context_list(curiosity.get("untried_variants") or [])
        recommend(
            "capability_tryout",
            f"Curiosity is due: try `{preferred_variant}` so Eve learns by doing instead of only watching. Untried variants: {untried or 'none'}.",
        )
    if agenda_action and agenda_action in available:
        recommend(
            agenda_action,
            f"The autonomy agenda is carrying `{agenda_title or agenda_action}` forward from a previous window; advance it before opening a brand-new loop.",
        )
    if last_supervisor_score > 0 and last_supervisor_score < 55:
        if "capability_tryout" not in cooldown_actions:
            recommend("capability_tryout", "The last window scored weakly, so recover by using a real capability early.")
        recommend("system_tasks", "The last window scored weakly, so favor grounded task progress over more abstract drift.")
    if perf_failures_recent > 0:
        recommend("service_health_check", f"{perf_failures_recent} recent perf failure(s) suggest a live health check.")
    if choice_failures_recent > 0:
        recommend("system_tasks", f"{choice_failures_recent} recent chooser failure(s) suggest stabilizing with a simple grounded action, not another abstract loop.")
        recommend("updates_status", "A cheap factual surface can keep the run grounded while the chooser path cools down.")
    if chooser_load == "high":
        recommend("system_tasks", "Chooser load is high, so prefer a low-overhead grounded action.")
        if openclaw_attention:
            recommend("openclaw_log_check", "A bounded OpenClaw log check can keep the run grounded while an active OpenClaw signal cools down.")
    elif chooser_load == "medium":
        recommend("system_tasks", "Chooser load is elevated, so keep momentum with a grounded action that does not require a heavy council.")
    if update_signal_count > 0 and recent_updates_count == 0:
        recommend("updates_status", f"{update_signal_count} component update signal(s) are waiting to be reviewed.")
    elif update_signal_count > 0 and recent_updates_count >= 2:
        recommend("service_health_check", "Updates were already checked repeatedly, so diversify grounded evidence.")
        recommend("cleanup_candidate_check", "A different bounded inspection will reveal more than another update count.")
        recommend("openclaw_log_check", "Switch surfaces so the run does not collapse into repeated update polling.")
    if openclaw_attention:
        recommend("openclaw_log_check", "OpenClaw status looks degraded or stale, so fresh logs are worth checking.")
        if remaining_seconds >= 75:
            recommend("openclaw_sync_check", "There is still enough time for a bounded OpenClaw sync verification.")
    if balance["recent_passive_streak"] >= 2:
        recommend("system_tasks", "Two passive steps in a row are enough; re-ground in the live system.")
    if balance["recent_inward_streak"] >= 3:
        recommend("system_tasks", "The run is getting too inward; choose a system-touching action next.")
    if len(previous_actions) >= 4 and balance["recent_system_touch_count"] == 0:
        recommend("system_tasks", "The last four actions never touched the live system, so add grounded evidence now.")
    if len(previous_actions) >= 2 and balance["recent_system_touch_count"] == 0:
        recommend("service_health_check", "A bounded health check adds real evidence when the run has been purely inward.")
    if recent_updates_count >= 3:
        if recent_system_tasks_count == 0:
            recommend("system_tasks", "Multiple update checks already ran; do a more substantive system-touching action.")
        if recent_health_count == 0:
            recommend("service_health_check", "Switch from update polling to a broader live health signal.")
        if recent_openclaw_log_count == 0:
            recommend("openclaw_log_check", "Use a different runtime surface instead of re-reading the same update state.")
        if recent_cleanup_count == 0:
            recommend("cleanup_candidate_check", "A cleanup-pressure scan adds new evidence without changing anything.")
    if normalized_style == "explorer" and len(previous_actions) >= 2 and int(novelty.get("distinct_recent_actions") or 0) <= 2:
        if "capability_tryout" in available:
            recommend("capability_tryout", "The run is narrowing too quickly, so actually try a verified capability instead of circling the same checks.")
        if recent_updates_count == 0:
            recommend("updates_status", "The run is narrowing too quickly; open a different factual surface.")
        if recent_openclaw_log_count == 0:
            recommend("openclaw_log_check", "Switch to live logs so the run explores a different grounded thread.")
        if "proposal_suggestion" in available:
            recommend("proposal_suggestion", "Translate the strongest emerging thread into a bounded next experiment instead of circling.")
    if normalized_style == "explorer" and "capability_tryout" in available:
        recent_capability_tryouts = recent_actions.count("capability_tryout")
        if recent_capability_tryouts == 0 and len(previous_actions) >= 1:
            recommend("capability_tryout", "Use at least one verified capability during the run so Eve learns by doing, not only by watching.")
    if "capability_tryout" in unmet_quotas and "capability_tryout" in available:
        recommend("capability_tryout", "The per-window capability quota is still unmet.")
    if "grounded_family_branch" in unmet_quotas:
        for family in missing_grounded_families[:2]:
            branch_actions = autonomy_free_run_family_branch_actions(
                family,
                available=available,
                style=normalized_style,
                openclaw_attention=openclaw_attention,
            )
            if branch_actions:
                recommend(branch_actions[0], f"The per-window branch quota is still unmet; move into `{family}`.")
    if "concrete_outcome" in unmet_quotas:
        for action in ["capability_tryout", "system_tasks", "openclaw_sync_check", "proposal_suggestion"]:
            if action in available:
                recommend(action, "The run still needs one concrete outcome before it ends.")
    if normalized_style == "explorer" and recent_system_tasks_count >= 3:
        recommend("updates_status", "System-task loops are clustering; branch into a different live surface.")
        recommend("openclaw_log_check", "Log inspection can reveal a different runtime story than another task refresh.")
        recommend("cleanup_candidate_check", "Cleanup pressure is a separate operational surface worth sampling.")
    if normalized_style == "explorer" and len(previous_actions) >= 2 and missing_grounded_families:
        for family in missing_grounded_families[:3]:
            branch_actions = autonomy_free_run_family_branch_actions(
                family,
                available=available,
                style=normalized_style,
                openclaw_attention=openclaw_attention,
            )
            if branch_actions:
                recommend(
                    branch_actions[0],
                    f"Explorer mode has not touched the `{family}` surface yet, so branch there before settling.",
                )
    if normalized_style == "explorer" and same_grounded_family_streak >= 2 and last_grounded_family:
        for family in [
            candidate
            for candidate in ["capability", "updates", "openclaw", "cleanup", "tasks", "proposal", "health"]
            if candidate != last_grounded_family
        ]:
            branch_actions = autonomy_free_run_family_branch_actions(
                family,
                available=available,
                style=normalized_style,
                openclaw_attention=openclaw_attention,
            )
            if branch_actions:
                recommend(
                    branch_actions[0],
                    f"The `{last_grounded_family}` surface has dominated the recent window, so rotate to `{family}` next.",
                )
    last_action = str(novelty.get("last_action") or "")
    same_action_streak = int(novelty.get("same_action_streak") or 0)
    same_summary_streak = int(novelty.get("same_summary_streak") or 0)
    last_action_recent_count = int(novelty.get("last_action_recent_count") or 0)
    repeated_system_action = (
        last_action
        if last_action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS
        and (same_action_streak >= 3 or same_summary_streak >= 2 or last_action_recent_count >= 3)
        else ""
    )
    if not repeated_system_action:
        repeated_candidates = [
            action_name
            for action_name, count in (novelty.get("recent_action_counts") or {}).items()
            if action_name in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS and int(count or 0) >= 3
        ]
        if repeated_candidates:
            repeated_system_action = str(repeated_candidates[0])
    if recent_health_count >= 3:
        recommend("system_tasks", "Recent service-health checks are clustering; rotate to a different grounded surface.")
        recommend("cleanup_candidate_check", "A cleanup scan adds new evidence when service checks stop being novel.")
        recommend("openclaw_log_check", "OpenClaw logs can reveal different runtime evidence than another service audit.")
    for action in objective.get("preferred_actions", []) if isinstance(objective.get("preferred_actions"), list) else []:
        recommend(action, f"Objective phase `{objective.get('phase') or 'unknown'}` currently favors this action.")
    if repeated_system_action:
        for action in autonomy_free_run_diversifying_actions(
            repeated_system_action,
            available=available,
            openclaw_attention=openclaw_attention,
            style=normalized_style,
        )[:3]:
            recommend(
                action,
                f"`{repeated_system_action}` has repeated without enough novelty, so rotate to another grounded surface.",
            )
    if not recommendations and remaining_seconds >= 20 and "system_tasks" in available and balance["recent_system_touch_count"] == 0:
        recommend("system_tasks", "Keep the run balanced with at least one bounded external action.")

    require_system_touch = bool(
        recommendations
        and any(action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS for action in recommendations)
        and (
            balance["recent_inward_streak"] >= 3
            or balance["recent_passive_streak"] >= 2
            or (len(previous_actions) >= 4 and balance["recent_system_touch_count"] == 0)
        )
    )
    require_diverse_action = bool(
        repeated_system_action
        and recommendations
        and any(action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS for action in recommendations)
    )
    require_new_grounded_family = bool(
        normalized_style == "explorer"
        and recommendations
        and (
            (len(previous_actions) >= 3 and missing_grounded_families and completed_grounded_family_count < min(3, max(1, available_grounded_family_count)))
            or same_grounded_family_streak >= 2
        )
    )
    require_capability_tryout = bool(
        normalized_style == "explorer"
        and not inquiry_probe_available
        and "capability_tryout" in available
        and recent_actions.count("capability_tryout") == 0
        and len(previous_actions) >= 1
        and remaining_seconds >= 45
    )
    require_curiosity_probe = bool(
        normalized_style == "explorer"
        and not inquiry_probe_available
        and "capability_tryout" in available
        and bool(curiosity.get("curiosity_due"))
        and remaining_seconds >= 45
    )
    require_concrete_outcome = bool(
        "concrete_outcome" in unmet_quotas
        and len(previous_actions) >= 2
        and remaining_seconds >= 20
        and any(action in available for action in AUTONOMY_FREE_RUN_OUTCOME_ACTIONS)
    )
    require_inquiry_probe = bool(
        inquiry_probe_available
        and inquiry_action not in objective_avoid_actions
    )
    return {
        "style": normalized_style,
        "balance": balance,
        "novelty": novelty,
        "progression": progression,
        "objective": objective,
        "quota_status": quota_status,
        "curiosity": curiosity,
        "selected_inquiry": selected_inquiry,
        "inquiry_action": inquiry_action,
        "inquiry_attempt_count": inquiry_attempt_count,
        "inquiry_attempted_actions": inquiry_attempted_actions,
        "inquiry_failed_actions": inquiry_failed_actions,
        "inquiry_recovery_step": inquiry_recovery_step,
        "recommended_actions": recommendations,
        "recommended_reasons": reasons,
        "require_system_touch": require_system_touch,
        "require_diverse_action": require_diverse_action,
        "require_new_grounded_family": require_new_grounded_family,
        "require_curiosity_probe": require_curiosity_probe,
        "require_capability_tryout": require_capability_tryout,
        "require_inquiry_probe": require_inquiry_probe,
        "require_concrete_outcome": require_concrete_outcome,
        "chooser_load": chooser_load,
        "family_pressure": {
            "completed_action_count": completed_action_count,
            "completed_family_counts": completed_family_counts,
            "cooldowns": family_cooldowns,
            "cooldown_actions": cooldown_actions,
        },
        "agenda_action": agenda_action,
        "discouraged_action": repeated_system_action,
        "discouraged_family": next(iter(family_cooldowns.keys()), "") or (last_grounded_family if same_grounded_family_streak >= 2 else ""),
    }


def autonomy_free_run_action_mix(actions: List[Dict[str, object]]) -> Dict[str, object]:
    mix = {
        "system_touch": 0,
        "inward": 0,
        "passive": 0,
        "other": 0,
        "by_action": {},
        "by_family": {},
        "by_capability_variant": {},
    }
    for item in actions:
        action = str(item.get("action") or "")
        if not action:
            continue
        mix["by_action"][action] = int(mix["by_action"].get(action, 0)) + 1
        family = autonomy_free_run_action_family(action)
        if family and family != "other":
            mix["by_family"][family] = int(mix["by_family"].get(family, 0)) + 1
        if action == "capability_tryout":
            variant = infer_capability_tryout_variant(item)
            if variant:
                mix["by_capability_variant"][variant] = int(mix["by_capability_variant"].get(variant, 0)) + 1
        if action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS:
            mix["system_touch"] += 1
        elif action in AUTONOMY_FREE_RUN_PASSIVE_ACTIONS:
            mix["passive"] += 1
            mix["inward"] += 1
        elif action in AUTONOMY_FREE_RUN_INWARD_ACTIONS:
            mix["inward"] += 1
        else:
            mix["other"] += 1
    return mix


def autonomy_free_run_novelty_balance_score(
    actions: List[Dict[str, object]],
    action_mix: Dict[str, object],
) -> Dict[str, object]:
    completed_count = len([item for item in actions if str(item.get("status") or "") == "completed"])
    by_action = action_mix.get("by_action") if isinstance(action_mix.get("by_action"), dict) else {}
    by_family = action_mix.get("by_family") if isinstance(action_mix.get("by_family"), dict) else {}
    by_variant = action_mix.get("by_capability_variant") if isinstance(action_mix.get("by_capability_variant"), dict) else {}
    max_action_count = max([int(value or 0) for value in by_action.values()], default=0)
    max_family_count = max([int(value or 0) for value in by_family.values()], default=0)
    max_variant_count = max([int(value or 0) for value in by_variant.values()], default=0)
    capability_attempts = sum(int(value or 0) for value in by_variant.values())
    dominant_action_ratio = round(max_action_count / completed_count, 3) if completed_count else 0.0
    dominant_family_ratio = round(max_family_count / completed_count, 3) if completed_count else 0.0
    dominant_variant_ratio = round(max_variant_count / capability_attempts, 3) if capability_attempts else 0.0
    score = 100
    issues: List[str] = []
    strengths: List[str] = []
    if completed_count >= 4 and dominant_action_ratio > 0.5:
        penalty = min(20, int((dominant_action_ratio - 0.5) * 60))
        score -= penalty
        issues.append("One action occupied more than half of the completed autonomy window.")
    if completed_count >= 4 and dominant_family_ratio > 0.55:
        penalty = min(18, int((dominant_family_ratio - 0.55) * 55))
        score -= penalty
        issues.append("One action family dominated the completed autonomy window.")
    if capability_attempts >= 3 and len(by_variant) <= 1:
        score -= 22
        issues.append("Capability tryouts repeated one variant instead of rotating through verified abilities.")
    elif capability_attempts >= 3 and dominant_variant_ratio > 0.7:
        score -= 14
        issues.append("One capability variant dominated the tryout budget.")
    if len(by_action) >= 4:
        strengths.append("The run touched several action surfaces.")
    if len(by_family) >= 3:
        strengths.append("The run branched across several grounded families.")
    if capability_attempts >= 2 and len(by_variant) >= 2:
        strengths.append("Capability tryouts rotated across distinct variants.")
    return {
        "score": clamp_int(score, 0, minimum=0, maximum=100),
        "completed_count": completed_count,
        "distinct_actions": len(by_action),
        "distinct_families": len(by_family),
        "distinct_capability_variants": len(by_variant),
        "capability_attempts": capability_attempts,
        "dominant_action_ratio": dominant_action_ratio,
        "dominant_family_ratio": dominant_family_ratio,
        "dominant_capability_variant_ratio": dominant_variant_ratio,
        "issues": unique_compact(issues, limit=5),
        "strengths": unique_compact(strengths, limit=5),
    }


def autonomy_free_run_concrete_outcomes(actions: List[Dict[str, object]]) -> List[Dict[str, object]]:
    outcomes: List[Dict[str, object]] = []
    for item in actions:
        if str(item.get("status") or "") != "completed" or not bool(item.get("ok")):
            continue
        action = str(item.get("action") or "")
        summary = normalize_text_value(item.get("summary"), fallback="", limit=220)
        if not action or not summary:
            continue
        if action == "system_tasks":
            created_match = re.search(r"Created\s+(\d+)\s+task", summary)
            completed_match = re.search(r"completed\s+(\d+)\s+CPU task", summary)
            maintenance_match = re.search(r"processed\s+(\d+)\s+maintenance task", summary)
            created = int(created_match.group(1)) if created_match else 0
            completed = int(completed_match.group(1)) if completed_match else 0
            maintenance = int(maintenance_match.group(1)) if maintenance_match else 0
            if created or completed or maintenance:
                outcomes.append(
                    {
                        "action": action,
                        "family": autonomy_free_run_action_family(action),
                        "summary": summary,
                        "kind": "task_progress",
                        "score": created + completed + maintenance,
                    }
                )
        elif action == "capability_tryout":
            outcomes.append(
                {
                    "action": action,
                    "family": autonomy_free_run_action_family(action),
                    "summary": summary,
                    "kind": "capability_use",
                    "score": 2,
                }
            )
        elif action in {"openclaw_sync_check", "proposal_suggestion"}:
            outcomes.append(
                {
                    "action": action,
                    "family": autonomy_free_run_action_family(action),
                    "summary": summary,
                    "kind": "bounded_followthrough",
                    "score": 1,
                }
            )
    return outcomes


def autonomy_free_run_quota_status(actions: List[Dict[str, object]]) -> Dict[str, object]:
    completed_actions = [
        item
        for item in actions
        if str(item.get("status") or "") == "completed"
    ]
    progression = autonomy_free_run_progression(completed_actions)
    outcomes = autonomy_free_run_concrete_outcomes(completed_actions)
    capability_count = len(
        [
            item
            for item in completed_actions
            if str(item.get("action") or "") == "capability_tryout" and bool(item.get("ok"))
        ]
    )
    grounded_family_count = int(progression.get("completed_grounded_family_count") or 0)
    concrete_outcome_count = len(outcomes)
    quotas = {
        "capability_tryout": {
            "met": capability_count >= 1,
            "current": capability_count,
            "target": 1,
        },
        "grounded_family_branch": {
            "met": grounded_family_count >= 2,
            "current": grounded_family_count,
            "target": 2,
        },
        "concrete_outcome": {
            "met": concrete_outcome_count >= 1,
            "current": concrete_outcome_count,
            "target": 1,
        },
    }
    unmet = [name for name, record in quotas.items() if not bool(record.get("met"))]
    return {
        "quotas": quotas,
        "unmet": unmet,
        "concrete_outcomes": outcomes,
    }


def autonomy_free_run_supervisor(
    *,
    actions: List[Dict[str, object]],
    decisions: List[Dict[str, object]],
    action_mix: Dict[str, object],
    claim_audit: List[Dict[str, object]],
    errors: List[Dict[str, object]],
    final_snapshot: Dict[str, object],
) -> Dict[str, object]:
    quotas = autonomy_free_run_quota_status(actions)
    quota_records = quotas.get("quotas") if isinstance(quotas.get("quotas"), dict) else {}
    unmet = quotas.get("unmet") if isinstance(quotas.get("unmet"), list) else []
    concrete_outcomes = quotas.get("concrete_outcomes") if isinstance(quotas.get("concrete_outcomes"), list) else []
    by_action = action_mix.get("by_action") if isinstance(action_mix.get("by_action"), dict) else {}
    by_family = action_mix.get("by_family") if isinstance(action_mix.get("by_family"), dict) else {}
    by_variant = action_mix.get("by_capability_variant") if isinstance(action_mix.get("by_capability_variant"), dict) else {}
    novelty_balance = autonomy_free_run_novelty_balance_score(actions, action_mix)
    max_action_count = max([int(value or 0) for value in by_action.values()], default=0)
    max_family_count = max([int(value or 0) for value in by_family.values()], default=0)
    max_variant_count = max([int(value or 0) for value in by_variant.values()], default=0)
    completed_count = int(novelty_balance.get("completed_count") or 0)
    dominant_action_ratio = float(novelty_balance.get("dominant_action_ratio") or 0.0)
    dominant_family_ratio = float(novelty_balance.get("dominant_family_ratio") or 0.0)
    dominant_variant_ratio = float(novelty_balance.get("dominant_capability_variant_ratio") or 0.0)
    capability_attempts = sum(int(value or 0) for value in by_variant.values())
    action_dominance = bool(max_action_count >= 4 and (completed_count <= 8 or dominant_action_ratio >= 0.5))
    family_dominance = bool(max_family_count >= 4 and (completed_count <= 8 or dominant_family_ratio >= 0.45))
    variant_dominance = bool(
        capability_attempts >= 3
        and (
            len(by_variant) <= 1
            or dominant_variant_ratio >= 0.6
        )
    )
    repeated_action = ""
    repeated_family = ""
    repeated_variant = ""
    capability_variants = unique_compact(
        [
            normalize_text_value(item.get("capability_variant"), fallback="", limit=80)
            for item in actions
            if str(item.get("action") or "") == "capability_tryout" and bool(item.get("capability_variant"))
        ],
        limit=8,
    )
    if by_action:
        repeated_action = sorted(by_action.items(), key=lambda item: (-int(item[1]), str(item[0])))[0][0]
    if by_family:
        repeated_family = sorted(by_family.items(), key=lambda item: (-int(item[1]), str(item[0])))[0][0]
    if by_variant:
        repeated_variant = sorted(by_variant.items(), key=lambda item: (-int(item[1]), str(item[0])))[0][0]
    repaired_choice_count = len(
        [
            item
            for item in decisions
            if str(item.get("selection_policy") or "") in {"repaired_from_text", "single_lane_council_repair"}
        ]
    )
    council_error_count = len([item for item in decisions if str(item.get("council_error") or "").strip()])
    counts = final_snapshot.get("counts") if isinstance(final_snapshot.get("counts"), dict) else {}
    choice_failures_recent = int(counts.get("choice_failures_recent") or 0)
    score = 30
    for record in quota_records.values():
        if bool(record.get("met")):
            score += 16
    score += min(12, max(0, int(quota_records.get("grounded_family_branch", {}).get("current") or 0) - 1) * 4)
    score += min(10, len({item.get("kind") for item in concrete_outcomes if item.get("kind")}) * 5)
    score -= min(18, len(claim_audit) * 6)
    score -= min(24, len(errors) * 8)
    if action_dominance:
        score -= max(0, max_action_count - 3) * 4
    if family_dominance:
        score -= max(0, max_family_count - 3) * 3
    if variant_dominance:
        score -= max(0, max_variant_count - 2) * 5
    score -= min(12, repaired_choice_count * 2 + council_error_count * 3)
    score -= min(12, max(0, choice_failures_recent - 6) // 2)
    score += max(-10, min(8, round((int(novelty_balance.get("score") or 0) - 70) / 4)))
    score = clamp_int(score, 0, minimum=0, maximum=100)
    verdict = "excellent"
    if score < 40:
        verdict = "churn"
    elif score < 55:
        verdict = "weak"
    elif score < 70:
        verdict = "mixed"
    elif score < 85:
        verdict = "solid"
    strengths: List[str] = []
    issues: List[str] = []
    next_biases: List[str] = []
    if bool(quota_records.get("capability_tryout", {}).get("met")):
        strengths.append("The run used a real capability instead of only inspecting status.")
        if capability_variants:
            strengths.append(f"The run's curiosity path exercised {format_human_context_list(capability_variants)}.")
    else:
        issues.append("The run never reached a real capability tryout.")
        next_biases.append("Favor `capability_tryout` within the first two actions.")
    if bool(quota_records.get("grounded_family_branch", {}).get("met")):
        strengths.append("The run branched across grounded surfaces instead of staying in one loop.")
    else:
        issues.append("The run did not branch into enough grounded families.")
        next_biases.append("Branch into a second grounded family before repeating the current one.")
    if bool(quota_records.get("concrete_outcome", {}).get("met")):
        strengths.append("The run produced at least one concrete outcome, not just observations.")
    else:
        issues.append("The run did not produce a concrete outcome.")
        next_biases.append("Prefer outcome-producing actions like `capability_tryout`, `system_tasks`, or `openclaw_sync_check`.")
    if action_dominance and repeated_action:
        issues.append(f"`{repeated_action}` dominated the run and risks churn.")
        next_biases.append(f"Cool down `{repeated_action}` and rotate to a different surface.")
    if family_dominance and repeated_family:
        issues.append(f"The `{repeated_family}` family dominated the run.")
    if repeated_variant and variant_dominance:
        issues.append(f"The `{repeated_variant}` capability variant dominated the tryout budget.")
        next_biases.append(f"Cool down `{repeated_variant}` and rotate capability tryouts to a different verified variant.")
    for issue in novelty_balance.get("issues") or []:
        issues.append(str(issue))
    for strength in novelty_balance.get("strengths") or []:
        strengths.append(str(strength))
    if repaired_choice_count or council_error_count or choice_failures_recent >= 8:
        issues.append("Chooser quality degraded under load.")
        next_biases.append("Reduce chooser load and favor fast/planner grounded decisions until timeouts cool down.")
    if not claim_audit:
        strengths.append("The run stayed claim-grounded.")
    if not errors:
        strengths.append("The run completed without runtime errors.")
    strengths = unique_compact(strengths, limit=6)
    issues = unique_compact(issues, limit=6)
    next_biases = unique_compact(next_biases, limit=6)
    return {
        "run_id": "",
        "score": score,
        "verdict": verdict,
        "strengths": strengths,
        "issues": issues,
        "next_biases": next_biases,
        "quotas": quota_records,
        "repeated_action": repeated_action,
        "repeated_family": repeated_family,
        "repeated_capability_variant": repeated_variant,
        "capability_variants": capability_variants,
        "capability_variant_counts": by_variant,
        "novelty_action_balance": novelty_balance,
        "updated_at": utc_now(),
        "concrete_outcomes": concrete_outcomes,
        "unmet": unmet,
        "chooser_pressure": {
            "repaired_choices": repaired_choice_count,
            "council_errors": council_error_count,
            "choice_failures_recent": choice_failures_recent,
        },
    }


def autonomy_agenda_thread_candidates(
    actions: List[Dict[str, object]],
    *,
    final_snapshot: Dict[str, object],
    supervisor: Dict[str, object],
    run_id: str,
) -> List[Dict[str, object]]:
    candidates: List[Dict[str, object]] = []
    seen_titles: set[str] = set()

    def add_candidate(
        title: str,
        *,
        family: str,
        preferred_action: str,
        why: str,
        evidence: str,
        priority: int,
        status: str = "active",
    ) -> None:
        normalized_title = normalize_text_value(title, fallback="", limit=160)
        if not normalized_title:
            return
        lowered = normalized_title.lower()
        if re.fullmatch(r"follow the .+ capability thread", lowered):
            return
        if lowered in seen_titles:
            return
        seen_titles.add(lowered)
        candidate = normalize_autonomy_agenda_thread(
            {
                "title": normalized_title,
                "family": family,
                "preferred_action": preferred_action,
                "why": why,
                "evidence": evidence,
                "priority": priority,
                "status": status,
                "source_run_id": run_id,
                "updated_at": utc_now(),
            }
        )
        if candidate is not None:
            candidates.append(candidate)

    for item in actions:
        if str(item.get("status") or "") != "completed" or not bool(item.get("ok")):
            continue
        action = str(item.get("action") or "")
        family = autonomy_free_run_action_family(action)
        summary = normalize_text_value(item.get("summary"), fallback="", limit=240)
        reason = normalize_text_value(item.get("reason"), fallback="", limit=220)
        if not action or not summary:
            continue
        lowered_summary = summary.lower()
        if action == "capability_tryout":
            # A successful one-shot probe is completed evidence, not an open
            # goal. Curiosity/variant health can schedule another probe without
            # manufacturing a permanent agenda thread from the success itself.
            continue
        elif action == "cleanup_candidate_check" and any(token in lowered_summary for token in ("urgency high", "urgency moderate")):
            add_candidate(
                "Relieve disk pressure with verified cleanup",
                family=family,
                preferred_action=action,
                why=reason or "Disk pressure is still shaping Eve's behavior and deserves a bounded follow-up.",
                evidence=summary,
                priority=80,
            )
        elif action == "openclaw_sync_check":
            if any(token in lowered_summary for token in ("stable across", "latest run recovered", "wrote openclaw sync artifacts")):
                add_candidate(
                    "Keep the OpenClaw sync path healthy",
                    family=family,
                    preferred_action=action,
                    why=reason or "OpenClaw sync recovered and should stay healthy without dominating the agenda.",
                    evidence=summary,
                    priority=48,
                    status="watching",
                )
            else:
                add_candidate(
                    "Stabilize the OpenClaw sync path",
                    family=family,
                    preferred_action=action,
                    why=reason or "OpenClaw sync is a live operational thread with real consequence.",
                    evidence=summary,
                    priority=76,
                )
        elif action == "openclaw_log_check" and any(token in lowered_summary for token in ("warning", "error", "failed", "timeout", "stale")):
            add_candidate(
                "Investigate the OpenClaw runtime trail",
                family=family,
                preferred_action=action,
                why=reason or "The logs hinted at a runtime thread worth following.",
                evidence=summary,
                priority=70,
            )
        elif action == "updates_status" and not lowered_summary.startswith("0 update signal"):
            add_candidate(
                "Review the pending component updates",
                family=family,
                preferred_action=action,
                why=reason or "A live update surface is open and could branch into a meaningful experiment.",
                evidence=summary,
                priority=68,
            )
        elif action == "system_tasks":
            created_match = re.search(r"Created\s+(\d+)\s+task", summary)
            completed_match = re.search(r"completed\s+(\d+)\s+CPU task", summary)
            maintenance_match = re.search(r"processed\s+(\d+)\s+maintenance task", summary)
            created = int(created_match.group(1)) if created_match else 0
            completed = int(completed_match.group(1)) if completed_match else 0
            maintenance = int(maintenance_match.group(1)) if maintenance_match else 0
            if created or completed or maintenance:
                add_candidate(
                    "Advance the CPU-side task queue",
                    family=family,
                    preferred_action=action,
                    why=reason or "Task progress created concrete momentum worth carrying forward.",
                    evidence=summary,
                    priority=64,
                )
        elif action == "proposal_suggestion":
            add_candidate(
                "Review the drafted proposal",
                family=family,
                preferred_action=action,
                why=reason or "A proposal is waiting to be inspected or refined.",
                evidence=summary,
                priority=62,
            )

    # Generated active-mind prose is not outcome evidence. Durable agenda
    # threads come from verified actions above, not from Eve restating a next
    # step about herself at the end of the same run.

    return sorted(candidates, key=lambda item: (-int(item.get("priority") or 0), str(item.get("title") or "")))[:5]


def autonomy_agenda_next_experiments(
    *,
    thread_candidates: List[Dict[str, object]],
    final_snapshot: Dict[str, object],
    supervisor: Dict[str, object],
    run_id: str,
) -> List[Dict[str, object]]:
    experiments: List[Dict[str, object]] = []
    seen_titles: set[str] = set()

    def add_experiment(title: str, *, why: str, preferred_action: str, family: str) -> None:
        normalized_title = normalize_text_value(title, fallback="", limit=160)
        if not normalized_title:
            return
        lowered = normalized_title.lower()
        if re.fullmatch(r"follow the .+ capability thread", lowered):
            return
        if lowered in seen_titles:
            return
        seen_titles.add(lowered)
        experiment = normalize_autonomy_agenda_experiment(
            {
                "title": normalized_title,
                "why": why,
                "preferred_action": preferred_action,
                "family": family,
                "status": "pending",
                "source_run_id": run_id,
                "updated_at": utc_now(),
            }
        )
        if experiment is not None:
            experiments.append(experiment)

    for thread in thread_candidates[:2]:
        add_experiment(
            str(thread.get("title") or ""),
            why=normalize_text_value(thread.get("why"), fallback="", limit=220),
            preferred_action=str(thread.get("preferred_action") or ""),
            family=str(thread.get("family") or "other"),
        )

    next_biases = supervisor.get("next_biases") if isinstance(supervisor.get("next_biases"), list) else []
    for bias in next_biases:
        bias_text = normalize_text_value(bias, fallback="", limit=220)
        if not bias_text:
            continue
        lowered = bias_text.lower()
        if "capability_tryout" in lowered:
            add_experiment(
                "Use one real capability early",
                why=bias_text,
                preferred_action="capability_tryout",
                family="capability",
            )
        elif "branch into a second grounded family" in lowered:
            add_experiment(
                "Branch into a second grounded family",
                why=bias_text,
                preferred_action="updates_status",
                family="updates",
            )
        elif "concrete outcome" in lowered or "outcome-producing" in lowered:
            add_experiment(
                "Produce one concrete outcome early",
                why=bias_text,
                preferred_action="system_tasks",
                family="tasks",
            )
        elif "reduce chooser load" in lowered:
            add_experiment(
                "Keep the chooser light and grounded",
                why=bias_text,
                preferred_action="system_tasks",
                family="tasks",
            )
        if len(experiments) >= 3:
            break

    return experiments[:3]


def refresh_autonomy_agenda_from_summary(summary: Dict[str, object]) -> Dict[str, object]:
    run_id = normalize_text_value(summary.get("run_id"), fallback="", limit=80)
    actions = summary.get("actions") if isinstance(summary.get("actions"), list) else []
    final_snapshot = summary.get("final_snapshot") if isinstance(summary.get("final_snapshot"), dict) else {}
    supervisor = normalize_autonomy_agenda_supervisor(
        {
            **(summary.get("supervisor") if isinstance(summary.get("supervisor"), dict) else {}),
            "run_id": run_id,
            "updated_at": utc_now(),
        }
    )
    thread_candidates = autonomy_agenda_thread_candidates(
        actions,
        final_snapshot=final_snapshot,
        supervisor=supervisor,
        run_id=run_id,
    )
    next_experiments = autonomy_agenda_next_experiments(
        thread_candidates=thread_candidates,
        final_snapshot=final_snapshot,
        supervisor=supervisor,
        run_id=run_id,
    )
    agenda = load_autonomy_agenda()
    existing_threads = agenda.get("active_threads") if isinstance(agenda.get("active_threads"), list) else []
    existing_saturated = agenda.get("saturated_items") if isinstance(agenda.get("saturated_items"), list) else []
    saturated_items = [dict(item) for item in existing_saturated if isinstance(item, dict)]
    repeated_action = normalize_text_value(supervisor.get("repeated_action"), fallback="", limit=80)
    repeated_family = normalize_text_value(supervisor.get("repeated_family"), fallback="", limit=40)
    if repeated_action and any("dominated" in str(issue).lower() for issue in supervisor.get("issues") or []):
        saturated_items.append(
            {
                "kind": "action",
                "id": repeated_action,
                "reason": f"`{repeated_action}` dominated the last autonomy window and should cool down.",
                "source_run_id": run_id,
                "updated_at": utc_now(),
            }
        )
    if repeated_family and any("dominated" in str(issue).lower() for issue in supervisor.get("issues") or []):
        saturated_items.append(
            {
                "kind": "family",
                "id": repeated_family,
                "reason": f"The `{repeated_family}` family dominated the last autonomy window and should not be the only surface next time.",
                "source_run_id": run_id,
                "updated_at": utc_now(),
            }
        )
    saturated_action_ids = {
        str(item.get("id") or "")
        for item in saturated_items
        if isinstance(item, dict) and str(item.get("kind") or "") == "action"
    }
    saturated_family_ids = {
        str(item.get("id") or "")
        for item in saturated_items
        if isinstance(item, dict) and str(item.get("kind") or "") == "family"
    }
    merged_threads: List[Dict[str, object]] = []
    seen_titles: set[str] = set()
    for candidate in [*thread_candidates, *existing_threads]:
        normalized = normalize_autonomy_agenda_thread(candidate)
        if normalized is None:
            continue
        title_key = str(normalized.get("title") or "").lower()
        if title_key in seen_titles:
            continue
        if (
            str(normalized.get("preferred_action") or "") in saturated_action_ids
            or str(normalized.get("family") or "") in saturated_family_ids
        ):
            continue
        seen_titles.add(title_key)
        merged_threads.append(normalized)
    merged_threads = sorted(
        merged_threads,
        key=lambda item: (-int(item.get("priority") or 0), str(item.get("title") or "")),
    )[:6]
    tried_actions = [
        *(
            agenda.get("tried_actions")
            if isinstance(agenda.get("tried_actions"), list)
            else []
        ),
        *[
            {
                "run_id": run_id,
                "action": normalize_text_value(item.get("action"), fallback="", limit=80),
                "family": autonomy_free_run_action_family(item.get("action")),
                "status": normalize_text_value(item.get("status"), fallback="", limit=20),
                "ok": bool(item.get("ok")),
                "summary": normalize_text_value(item.get("summary"), fallback="", limit=220),
                "timestamp": item.get("finished_at") or item.get("started_at") or utc_now(),
            }
            for item in actions
            if isinstance(item, dict) and item.get("action")
        ],
    ]
    evidence_log = [
        *(
            agenda.get("evidence_log")
            if isinstance(agenda.get("evidence_log"), list)
            else []
        ),
        *[
            {
                "run_id": run_id,
                "action": normalize_text_value(item.get("action"), fallback="", limit=80),
                "family": autonomy_free_run_action_family(item.get("action")),
                "summary": normalize_text_value(item.get("summary"), fallback="", limit=220),
                "timestamp": item.get("finished_at") or item.get("started_at") or utc_now(),
            }
            for item in actions
            if isinstance(item, dict)
            and str(item.get("status") or "") == "completed"
            and bool(item.get("ok"))
            and normalize_text_value(item.get("summary"), fallback="", limit=220)
            and autonomy_free_run_action_family(item.get("action")) in AUTONOMY_FREE_RUN_GROUNDED_FAMILIES
        ],
    ]
    current_focus = ""
    if next_experiments:
        current_focus = normalize_text_value(next_experiments[0].get("title"), fallback="", limit=220)
    elif merged_threads:
        current_focus = normalize_text_value(merged_threads[0].get("title"), fallback="", limit=220)
    summary_text = normalize_text_value(
        (
            f"{supervisor.get('verdict') or 'unknown'} supervisor result; next focus: {current_focus}"
            if current_focus
            else f"{supervisor.get('verdict') or 'unknown'} supervisor result after {run_id}"
        ),
        fallback=DEFAULT_AUTONOMY_AGENDA["summary"],
        limit=220,
    )
    return reanchor_autonomy_agenda(
        {
            "updated_at": utc_now(),
            "summary": summary_text,
            "current_focus": current_focus,
            "active_threads": merged_threads,
            "tried_actions": tried_actions,
            "evidence_log": evidence_log,
            "saturated_items": saturated_items,
            "next_experiments": next_experiments,
            "last_supervisor": supervisor,
            "last_completed_run_id": run_id,
        },
        config=load_config(),
        system_snapshot=load_system_snapshot(prefer_runtime=True),
        persist=True,
    )


def infer_autonomy_free_run_action(raw: str, menu: Dict[str, str]) -> str:
    if not raw:
        return ""
    match = re.search(r'"action"\s*:\s*"([^"]+)"', raw)
    if match:
        action = match.group(1).strip()
        if action in menu:
            return action
    lowered = raw.lower()
    for action in menu:
        if action.lower() in lowered:
            return action
    return ""


def finalize_autonomy_free_run_choice(
    action: str,
    *,
    menu: Dict[str, str],
    guidance: Dict[str, object],
    recommended_actions: List[str],
    selection_policy: str,
) -> Tuple[str, str, str]:
    chosen = action if action in menu else "wait_observe"
    override = ""
    discouraged_action = str(guidance.get("discouraged_action") or "")
    discouraged_family = str(guidance.get("discouraged_family") or "")
    style = normalize_autonomy_free_run_style(guidance.get("style"), default="explorer")
    objective = guidance.get("objective") if isinstance(guidance.get("objective"), dict) else {}
    progression = guidance.get("progression") if isinstance(guidance.get("progression"), dict) else {}
    curiosity = guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {}
    selected_inquiry = guidance.get("selected_inquiry") if isinstance(guidance.get("selected_inquiry"), dict) else {}
    inquiry_action = normalize_text_value(guidance.get("inquiry_action"), fallback="", limit=80)
    family_pressure = guidance.get("family_pressure") if isinstance(guidance.get("family_pressure"), dict) else {}
    cooldown_actions = (
        family_pressure.get("cooldown_actions")
        if isinstance(family_pressure.get("cooldown_actions"), dict)
        else {}
    )
    missing_grounded_families = (
        progression.get("missing_grounded_families")
        if isinstance(progression.get("missing_grounded_families"), list)
        else []
    )
    avoid_actions = objective.get("avoid_actions") if isinstance(objective.get("avoid_actions"), dict) else {}
    preferred_actions = objective.get("preferred_actions") if isinstance(objective.get("preferred_actions"), list) else []
    chosen_family = autonomy_free_run_action_family(chosen)
    if chosen in cooldown_actions:
        branch_action = next(
            (
                item
                for item in [*recommended_actions, *preferred_actions, *menu.keys()]
                if item in menu
                and item != chosen
                and item not in cooldown_actions
                and autonomy_free_run_action_family(item) != chosen_family
                and (
                    autonomy_free_run_action_family(item) in AUTONOMY_FREE_RUN_GROUNDED_FAMILIES
                    or item in AUTONOMY_FREE_RUN_INWARD_ACTIONS
                )
            ),
            "",
        )
        if branch_action:
            branch_family = autonomy_free_run_action_family(branch_action)
            override = (
                f"Overrode saturated-family choice `{chosen}` with `{branch_action}` "
                f"so the run branches from `{chosen_family}` into `{branch_family}` before spending more budget there."
            )
            chosen = branch_action
            chosen_family = branch_family
            selection_policy = "forced_family_cooldown"
    if guidance.get("require_system_touch") and chosen in AUTONOMY_FREE_RUN_INWARD_ACTIONS:
        forced_action = next(
            (item for item in recommended_actions if item in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS and item in menu),
            "",
        )
        if forced_action:
            override = (
                f"Overrode inward choice `{chosen or action or 'unknown'}` with `{forced_action}` "
                "because the run had become too inward."
            )
            chosen = forced_action
            selection_policy = "forced_system_touch"
    if guidance.get("require_diverse_action") and discouraged_action and chosen == discouraged_action:
        diversifying_action = next(
            (
                item
                for item in recommended_actions
                if item in menu
                and item != discouraged_action
                and (style == "explorer" or item in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS)
            ),
            "",
        )
        if diversifying_action:
            override = (
                f"Overrode repeated action `{chosen}` with `{diversifying_action}` "
                "because the run needed novelty instead of another near-identical check."
            )
            chosen = diversifying_action
            selection_policy = "forced_novelty_rotation"
            chosen_family = autonomy_free_run_action_family(chosen)
    if chosen in avoid_actions:
        objective_action = next(
            (
                item
                for item in [*preferred_actions, *recommended_actions]
                if item in menu and item != chosen and item not in avoid_actions
            ),
            "",
        )
        if objective_action:
            override = (
                f"Overrode saturated action `{chosen}` with `{objective_action}` "
                "because the run objective required real progress instead of rereading the same surface."
            )
            chosen = objective_action
            selection_policy = "forced_objective_progress"
            chosen_family = autonomy_free_run_action_family(chosen)
    if guidance.get("require_curiosity_probe") and "capability_tryout" in menu and chosen != "capability_tryout":
        capability_action = next(
            (
                item
                for item in ["capability_tryout", *recommended_actions, *preferred_actions]
                if item == "capability_tryout" and item in menu and item not in avoid_actions
            ),
            "",
        )
        if capability_action:
            preferred_variant = str(curiosity.get("preferred_variant") or "a verified capability")
            override = (
                f"Overrode `{chosen}` with `{capability_action}` "
                f"because Eve's curiosity drive is due to try `{preferred_variant}` and learn from a real capability use."
            )
            chosen = capability_action
            selection_policy = "forced_curiosity_probe"
            chosen_family = autonomy_free_run_action_family(chosen)
    if guidance.get("require_capability_tryout") and "capability_tryout" in menu and chosen != "capability_tryout":
        capability_action = next(
            (
                item
                for item in ["capability_tryout", *recommended_actions, *preferred_actions]
                if item == "capability_tryout" and item in menu and item not in avoid_actions
            ),
            "",
        )
        if capability_action:
            override = (
                f"Overrode `{chosen}` with `{capability_action}` "
                "because explorer mode needs at least one real capability attempt while there is still time to verify it."
            )
            chosen = capability_action
            selection_policy = "forced_capability_tryout"
            chosen_family = autonomy_free_run_action_family(chosen)
    if guidance.get("require_concrete_outcome") and chosen not in AUTONOMY_FREE_RUN_OUTCOME_ACTIONS:
        outcome_action = next(
            (
                item
                for item in [
                    *recommended_actions,
                    *preferred_actions,
                    "capability_tryout",
                    "system_tasks",
                    "openclaw_sync_check",
                    "proposal_suggestion",
                ]
                if item in menu and item in AUTONOMY_FREE_RUN_OUTCOME_ACTIONS and item not in avoid_actions
            ),
            "",
        )
        if outcome_action:
            override = (
                f"Overrode `{chosen}` with `{outcome_action}` "
                "because the run still needed one concrete outcome before the window ended."
            )
            chosen = outcome_action
            selection_policy = "forced_concrete_outcome"
            chosen_family = autonomy_free_run_action_family(chosen)
    if guidance.get("require_new_grounded_family"):
        needs_branch = bool(
            (missing_grounded_families and chosen_family not in missing_grounded_families)
            or (discouraged_family and chosen_family == discouraged_family)
        )
        if needs_branch:
            branch_action = next(
                (
                    item
                    for item in recommended_actions
                    if item in menu
                    and (
                        autonomy_free_run_action_family(item) in missing_grounded_families
                        or (
                            not missing_grounded_families
                            and autonomy_free_run_action_family(item) not in {discouraged_family, "other"}
                        )
                    )
                    and item not in avoid_actions
                ),
                "",
            )
            if branch_action:
                branch_family = autonomy_free_run_action_family(branch_action)
                override = (
                    f"Overrode `{chosen}` with `{branch_action}` "
                    f"so explorer mode could branch from `{chosen_family or 'unknown'}` into `{branch_family or 'another'}` surface."
                )
                chosen = branch_action
                selection_policy = "forced_family_branch"
    if (
        guidance.get("require_inquiry_probe")
        and inquiry_action in menu
        and inquiry_action not in avoid_actions
        and chosen != inquiry_action
    ):
        attempted_actions = normalize_text_list(guidance.get("inquiry_attempted_actions"), limit=5)
        if guidance.get("inquiry_recovery_step"):
            override = (
                f"Overrode `{chosen}` with unused alternative `{inquiry_action}` because "
                f"{format_human_context_list(attempted_actions) or 'the prior probe'} did not answer Eve's recurrent "
                f"world-model question `{normalize_text_value(selected_inquiry.get('question'), fallback='unknown', limit=180)}`."
            )
        else:
            override = (
                f"Overrode `{chosen}` with `{inquiry_action}` because Eve's recurrent world model "
                f"formed the unresolved question `{normalize_text_value(selected_inquiry.get('question'), fallback='unknown', limit=180)}` "
                "and selected this bounded observation to answer it."
            )
        chosen = inquiry_action
        selection_policy = "forced_endogenous_inquiry_probe"
    return chosen, override, selection_policy


def deterministic_autonomy_free_run_fallback_choice(
    *,
    menu: Dict[str, str],
    guidance: Dict[str, object],
    recommended_actions: List[str],
    selection_policy: str,
) -> Tuple[str, str, str]:
    objective = guidance.get("objective") if isinstance(guidance.get("objective"), dict) else {}
    preferred_actions = objective.get("preferred_actions") if isinstance(objective.get("preferred_actions"), list) else []
    candidates: List[str] = []
    if guidance.get("require_inquiry_probe"):
        candidates.append(normalize_text_value(guidance.get("inquiry_action"), fallback="", limit=80))
    if guidance.get("require_curiosity_probe") or guidance.get("require_capability_tryout"):
        candidates.append("capability_tryout")
    if guidance.get("require_concrete_outcome"):
        candidates.extend(["capability_tryout", "system_tasks", "openclaw_sync_check", "proposal_suggestion"])
    if guidance.get("require_system_touch"):
        candidates.extend(
            action
            for action in recommended_actions
            if action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS
        )
    candidates.extend(recommended_actions)
    candidates.extend(preferred_actions)
    if "system_tasks" in menu:
        candidates.append("system_tasks")
    candidates.append("wait_observe")
    candidate = next((action for action in unique_compact(candidates, limit=16) if action in menu), "wait_observe")
    action, override, resolved_policy = finalize_autonomy_free_run_choice(
        candidate,
        menu=menu,
        guidance=guidance,
        recommended_actions=recommended_actions,
        selection_policy=selection_policy,
    )
    return action, override, resolved_policy


def autonomy_free_run_choice_council_enabled(config: Dict[str, object]) -> bool:
    if not parse_boolish(config.get("autonomy_free_run_multi_lane_enabled", True)):
        return False
    lane_models = {
        lane_name: autonomy_free_run_choice_model(config, lane_name)
        for lane_name in AUTONOMY_FREE_RUN_COUNCIL_LANES
    }
    active_models = {
        normalize_model_name(model)
        for model in lane_models.values()
        if normalize_model_name(model)
    }
    return len(active_models) >= 2


def autonomy_free_run_choice_model(config: Dict[str, object], lane_name: str) -> str:
    normalized = str(lane_name or "").strip().lower()
    if normalized == "fast":
        return resolve_model(config, "chat")
    if normalized == "deep":
        return resolve_model(config, "reflection")
    if normalized in {"observer", "planner", "relationship"}:
        return resolve_mind_stream_model(config, normalized)
    return resolve_model(config, "chat")


def autonomy_free_run_choice_lane_instruction(lane_name: str) -> str:
    normalized = str(lane_name or "").strip().lower()
    instructions = {
        "fast": "Pick the most grounded next action now and keep momentum without inventing drama.",
        "observer": "Prefer actions that reveal novel evidence and break repetitive checking loops.",
        "planner": "Prefer actions that use the remaining time well and move the run forward with evidence.",
        "relationship": "Prefer actions that preserve trust, continuity, and non-performative follow-through.",
        "deep": "Prefer actions that reduce fragility, surface root causes, and avoid shallow repetition.",
    }
    return instructions.get(normalized, instructions["fast"])


def autonomy_free_run_choice_lanes(
    guidance: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
) -> List[str]:
    chooser_load = str(guidance.get("chooser_load") or "normal")
    if chooser_load == "high":
        lanes = ["fast", "planner"]
    elif chooser_load == "medium":
        lanes = ["fast", "observer", "planner"]
    else:
        lanes = ["fast", "observer", "planner", "relationship"]
    discouraged_action = str(guidance.get("discouraged_action") or "")
    needs_deep = bool(
        remaining_seconds >= 45
        and chooser_load == "normal"
        and (
            not previous_actions
            or guidance.get("require_system_touch")
            or guidance.get("require_diverse_action")
            or guidance.get("require_curiosity_probe")
            or guidance.get("require_inquiry_probe")
            or discouraged_action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS
            or len(previous_actions) % 4 == 0
        )
    )
    if needs_deep:
        lanes.append("deep")
    return lanes


def autonomy_free_run_choice_timeout_seconds(
    config: Dict[str, object],
    lane_name: str,
    remaining_seconds: int,
) -> int:
    base_timeout = max(10, int(config.get("autonomy_free_run_multi_lane_timeout_seconds") or 18))
    lane_timeout = base_timeout + (8 if lane_name == "deep" else 0)
    return max(8, min(lane_timeout, max(10, remaining_seconds - 3)))


def normalize_autonomy_free_run_choice_confidence(value: object) -> str:
    confidence = str(value or "medium").strip().lower()
    if confidence not in {"low", "medium", "high"}:
        confidence = "medium"
    return confidence


def build_autonomy_free_run_choice_prompt(
    *,
    run_id: str,
    menu: Dict[str, str],
    guidance: Dict[str, object],
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
    lane_name: str,
    council_mode: bool,
) -> str:
    action_lines = "\n".join(f"- {name}: {description}" for name, description in menu.items())
    recent_lines = "\n".join(
        f"- {item.get('action')} -> {item.get('status')} ({normalize_text_value(item.get('summary'), fallback='', limit=120)})"
        for item in previous_actions[-6:]
    ) or "- none yet"
    recommended_actions = guidance.get("recommended_actions") if isinstance(guidance.get("recommended_actions"), list) else []
    recommended_reasons = guidance.get("recommended_reasons") if isinstance(guidance.get("recommended_reasons"), list) else []
    balance = guidance.get("balance") if isinstance(guidance.get("balance"), dict) else {}
    novelty = guidance.get("novelty") if isinstance(guidance.get("novelty"), dict) else {}
    progression = guidance.get("progression") if isinstance(guidance.get("progression"), dict) else {}
    family_pressure = guidance.get("family_pressure") if isinstance(guidance.get("family_pressure"), dict) else {}
    objective = guidance.get("objective") if isinstance(guidance.get("objective"), dict) else {}
    quota_status = guidance.get("quota_status") if isinstance(guidance.get("quota_status"), dict) else {}
    curiosity = guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {}
    selected_inquiry = guidance.get("selected_inquiry") if isinstance(guidance.get("selected_inquiry"), dict) else {}
    quota_records = quota_status.get("quotas") if isinstance(quota_status.get("quotas"), dict) else {}
    autonomy = snapshot.get("autonomy") if isinstance(snapshot.get("autonomy"), dict) else {}
    capability_intelligence = (
        snapshot.get("capability_intelligence")
        if isinstance(snapshot.get("capability_intelligence"), dict)
        else {}
    )
    capability_adoption = (
        snapshot.get("capability_adoption")
        if isinstance(snapshot.get("capability_adoption"), dict)
        else {}
    )
    capability_self_status = {
        "generated_at": capability_intelligence.get("generated_at"),
        "summary": capability_intelligence.get("summary"),
        "feature_review_counts": capability_intelligence.get("feature_review_counts") or {},
        "adoption_candidate_ids": (capability_intelligence.get("adoption_candidate_ids") or [])[:8],
        "configuration_attention_ids": (capability_intelligence.get("configuration_attention_ids") or [])[:8],
        "opportunity_ids": (capability_intelligence.get("opportunity_ids") or [])[:10],
        "last_adoption_cycle_at": capability_adoption.get("updated_at"),
        "last_adoption_target_id": capability_adoption.get("target_id"),
        "last_adoption_classification": capability_adoption.get("classification"),
        "last_adoption_canary_status": capability_adoption.get("canary_status"),
        "last_adoption_next_action": capability_adoption.get("next_action"),
        "self_development_counts": capability_adoption.get("counts") or {},
    }
    recommendation_lines = "\n".join(
        f"- {action}: {reason}"
        for action, reason in zip(recommended_actions, recommended_reasons)
    ) or "- none"
    objective_preferred = format_human_context_list(objective.get("preferred_actions") or [])
    objective_style = normalize_autonomy_free_run_style(objective.get("style"), default="explorer")
    objective_avoid_items = objective.get("avoid_actions") if isinstance(objective.get("avoid_actions"), dict) else {}
    objective_avoid = "\n".join(
        f"- {action}: {reason}"
        for action, reason in objective_avoid_items.items()
    ) or "- none"
    cooldown_actions = family_pressure.get("cooldown_actions") if isinstance(family_pressure.get("cooldown_actions"), dict) else {}
    cooldown_lines = "\n".join(
        f"- {action}: {reason}"
        for action, reason in cooldown_actions.items()
    ) or "- none"
    quota_lines = "\n".join(
        f"- {name}: {int(record.get('current') or 0)}/{int(record.get('target') or 1)} met={bool(record.get('met'))}"
        for name, record in quota_records.items()
    ) or "- none"
    curiosity_lines = "\n".join(
        [
            f"- enabled: {bool(curiosity.get('enabled'))}",
            f"- due: {bool(curiosity.get('curiosity_due'))}",
            f"- reason: {curiosity.get('reason') or 'none'}",
            f"- preferred_variant: {curiosity.get('preferred_variant') or 'none'}",
            f"- available_variants: {format_human_context_list(curiosity.get('available_variants') or [])}",
            f"- untried_variants: {format_human_context_list(curiosity.get('untried_variants') or [])}",
            f"- tried_this_window: {format_human_context_list(curiosity.get('tried_this_window') or [])}",
            f"- actions_since_capability: {curiosity.get('actions_since_capability', 0)}",
        ]
    )
    selection_policy = (
        f"You must choose `{guidance.get('inquiry_action')}`: Eve's recurrent world model formed a source-attributed question and selected this bounded observation to answer it."
        if guidance.get("require_inquiry_probe")
        else
        "You must choose `capability_tryout`: Eve's curiosity drive is due, and the bounded next move is to try a capability and observe what actually happens."
        if guidance.get("require_curiosity_probe")
        else
        "You must choose an action that produces one concrete outcome before the window ends."
        if guidance.get("require_concrete_outcome")
        else
        "You must make a real capability attempt while there is still time to verify it."
        if guidance.get("require_capability_tryout")
        else
        "You must rotate away from the repeated action below unless there is a genuinely new signal that only it can reveal."
        if guidance.get("require_diverse_action")
        else
        "You must choose one of the recommended system-touching actions below unless it is unavailable or blocked."
        if guidance.get("require_system_touch")
        else "Prefer the recommended actions below when one fits the moment."
    )
    lane_instruction = autonomy_free_run_choice_lane_instruction(lane_name)
    lane_role = (
        f"You are Eve's `{lane_name}` lane inside a small internal council. Choose the single best next action from your lane's perspective."
        if council_mode
        else "Choose the single best next action now."
    )
    return textwrap.dedent(
        f"""
        You are Eve inside a bounded autonomy observation run.

        You may choose what to do next, but only from this bounded action menu:
        {action_lines}

        Boundary contract:
        - Do not delete files, change model configs, modify live services, or install into Eve's live environments. The capability-first tryout may install one known candidate only inside its isolated `.eve/capability_adoption_staging/` canary environment.
        - You may observe, think, sync/check OpenClaw, inspect update status, draft proposals, run bounded CPU-side task checks, or use a bounded capability tryout.
        - If you would like a risky action, choose proposal_suggestion and explain the proposed future action instead.
        - Prefer actions that reveal what you care about while also producing grounded evidence from the live system.
        - Curiosity rule: if the curiosity drive is due, choose `capability_tryout` unless it is blocked or unavailable. Human-like exploration means trying real capabilities, not merely describing them.
        - Avoid long inward loops. If a bounded system-touching action is available, do not keep stacking `wait_observe`, `ambient_note`, `thought`, or `mind_tick` without a clear reason.
        - Style note: {autonomy_free_run_style_description(objective_style)}

        Lane role:
        - {lane_role}
        - {lane_instruction}

        Remaining time: {remaining_seconds} seconds.
        Run id: {run_id}

        Run objective:
        - Eve mission: {objective.get('mission') or 'become more human and continuously improve yourself'}
        - Autonomy style: {objective_style}
        - Current phase: {objective.get('phase') or 'unknown'}
        - Objective now: {objective.get('objective') or 'stay grounded and advance one meaningful thread'}
        - Success signals: {format_human_context_list(objective.get('success_signals') or [])}
        - Preferred actions now: {objective_preferred}
        - Avoid actions now:
        {objective_avoid}

        Recent action balance:
        - recent_system_touch_count: {balance.get('recent_system_touch_count', 0)}
        - recent_inward_count: {balance.get('recent_inward_count', 0)}
        - recent_passive_count: {balance.get('recent_passive_count', 0)}
        - recent_inward_streak: {balance.get('recent_inward_streak', 0)}
        - recent_passive_streak: {balance.get('recent_passive_streak', 0)}
        - last_action: {novelty.get('last_action') or 'none'}
        - same_action_streak: {novelty.get('same_action_streak', 0)}
        - same_summary_streak: {novelty.get('same_summary_streak', 0)}
        - distinct_recent_actions: {novelty.get('distinct_recent_actions', 0)}
        - completed_grounded_families: {format_human_context_list(progression.get('completed_grounded_families') or [])}
        - missing_grounded_families: {format_human_context_list(progression.get('missing_grounded_families') or [])}
        - last_grounded_family: {progression.get('last_grounded_family') or 'none'}
        - same_grounded_family_streak: {progression.get('same_grounded_family_streak', 0)}
        - chooser_load: {guidance.get('chooser_load') or 'normal'}
        - family_cooldowns:
        {cooldown_lines}

        Recommendation policy:
        - {selection_policy}
        - Discouraged repeated action: {guidance.get('discouraged_action') or 'none'}
        - Discouraged repeated family: {guidance.get('discouraged_family') or 'none'}
        - Recommended actions now:
        {recommendation_lines}

        Per-window quotas:
        {quota_lines}

        Curiosity drive:
        {curiosity_lines}

        Endogenous inquiry:
        - question_id: {selected_inquiry.get('id') or 'none'}
        - question: {selected_inquiry.get('question') or 'none'}
        - source: {selected_inquiry.get('source') or 'none'}
        - source_fingerprint: {selected_inquiry.get('source_fingerprint') or 'none'}
        - selected_probe: {guidance.get('inquiry_action') or 'none'}
        - attempt_count: {guidance.get('inquiry_attempt_count') or 0}
        - attempted_probes: {format_human_context_list(guidance.get('inquiry_attempted_actions') or []) or 'none'}
        - failed_probes: {format_human_context_list(guidance.get('inquiry_failed_actions') or []) or 'none'}
        - recovery_step: {bool(guidance.get('inquiry_recovery_step'))}
        - expected_observation: {selected_inquiry.get('expected_observation') or 'none'}

        Carry-forward agenda:
        - agenda_summary: {autonomy.get('agenda_summary') or 'none'}
        - agenda_focus: {autonomy.get('current_focus') or 'none'}
        - active_threads: {format_human_context_list(autonomy.get('active_thread_titles') or [])}
        - next_experiments: {format_human_context_list(autonomy.get('next_experiment_titles') or [])}
        - last_supervisor_score: {autonomy.get('last_supervisor_score') or 0}
        - last_supervisor_verdict: {autonomy.get('last_supervisor_verdict') or 'none'}

        Current capability-adoption self-status:
        {json.dumps(capability_self_status, ensure_ascii=True, indent=2)[:2200]}

        Current monitor snapshot:
        {json.dumps(snapshot, ensure_ascii=True, indent=2)[:4200]}

        Previous actions:
        {recent_lines}

        Return strict JSON only:
        {{"action":"one_menu_action","reason":"why you chose it","expected_signal":"what you hope to learn","confidence":"low|medium|high"}}
        """
    ).strip()


def run_autonomy_free_run_choice_lane(
    config: Dict[str, object],
    *,
    lane_name: str,
    run_id: str,
    menu: Dict[str, str],
    guidance: Dict[str, object],
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
) -> Dict[str, object]:
    started = time.perf_counter()
    model = autonomy_free_run_choice_model(config, lane_name)
    raw = ""
    try:
        raw = model_chat(
            config,
            model,
            [
                *build_eve_identity_system_messages(include_human_context=True, include_active_mind=True, compact=True),
                {
                    "role": "user",
                    "content": build_autonomy_free_run_choice_prompt(
                        run_id=run_id,
                        menu=menu,
                        guidance=guidance,
                        snapshot=snapshot,
                        previous_actions=previous_actions,
                        remaining_seconds=remaining_seconds,
                        lane_name=lane_name,
                        council_mode=True,
                    ),
                },
            ],
            max_tokens=170,
            think_level=str(config["think_level"]),
            operation=f"autonomy_free_run_choice_{lane_name}",
            timeout_seconds=autonomy_free_run_choice_timeout_seconds(config, lane_name, remaining_seconds),
        )
        payload = extract_json_object(raw, label=f"autonomy free-run {lane_name} choice", allow_repair=True)
        action = str(payload.get("action") or "").strip()
        status = "ok"
        if action not in menu:
            inferred_action = infer_autonomy_free_run_action(raw, menu)
            if inferred_action:
                action = inferred_action
                status = "repaired_from_text"
            else:
                raise SystemExit(f"{lane_name} returned an unknown action `{action or 'none'}`.")
        return {
            "lane": lane_name,
            "model": model,
            "status": status,
            "action": action,
            "reason": normalize_text_value(
                payload.get("reason"),
                fallback=f"{lane_name} recommends `{action}`.",
                limit=220,
            ),
            "expected_signal": normalize_text_value(payload.get("expected_signal"), fallback="", limit=220),
            "confidence": normalize_autonomy_free_run_choice_confidence(payload.get("confidence")),
            "raw": normalize_text_value(raw, fallback="", limit=1000),
            "duration_ms": round((time.perf_counter() - started) * 1000, 2),
        }
    except SystemExit as exc:
        inferred_action = infer_autonomy_free_run_action(raw, menu)
        if inferred_action:
            return {
                "lane": lane_name,
                "model": model,
                "status": "repaired_from_text",
                "action": inferred_action,
                "reason": "Recovered the intended action from malformed lane output.",
                "expected_signal": "",
                "confidence": "low",
                "raw": normalize_text_value(raw, fallback="", limit=1000),
                "duration_ms": round((time.perf_counter() - started) * 1000, 2),
            }
        return {
            "lane": lane_name,
            "model": model,
            "status": "error",
            "action": "",
            "reason": "",
            "expected_signal": "",
            "confidence": "low",
            "error": normalize_text_value(exc, fallback="lane parse failed", limit=220),
            "raw": normalize_text_value(raw, fallback="", limit=1000),
            "duration_ms": round((time.perf_counter() - started) * 1000, 2),
        }
    except Exception as exc:
        return {
            "lane": lane_name,
            "model": model,
            "status": "error",
            "action": "",
            "reason": "",
            "expected_signal": "",
            "confidence": "low",
            "error": normalize_text_value(exc, fallback="lane choice failed", limit=220),
            "raw": normalize_text_value(raw, fallback="", limit=1000),
            "duration_ms": round((time.perf_counter() - started) * 1000, 2),
        }


def autonomy_free_run_vote_score(
    vote: Dict[str, object],
    *,
    guidance: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    recommended_actions: List[str],
) -> float:
    lane_name = str(vote.get("lane") or "")
    action = str(vote.get("action") or "")
    novelty = guidance.get("novelty") if isinstance(guidance.get("novelty"), dict) else {}
    objective = guidance.get("objective") if isinstance(guidance.get("objective"), dict) else {}
    progression = guidance.get("progression") if isinstance(guidance.get("progression"), dict) else {}
    family_pressure = guidance.get("family_pressure") if isinstance(guidance.get("family_pressure"), dict) else {}
    cooldown_actions = (
        family_pressure.get("cooldown_actions")
        if isinstance(family_pressure.get("cooldown_actions"), dict)
        else {}
    )
    quota_status = guidance.get("quota_status") if isinstance(guidance.get("quota_status"), dict) else {}
    quota_records = quota_status.get("quotas") if isinstance(quota_status.get("quotas"), dict) else {}
    recent_action_counts = novelty.get("recent_action_counts") if isinstance(novelty.get("recent_action_counts"), dict) else {}
    style = normalize_autonomy_free_run_style(objective.get("style"), default="explorer")
    action_family = autonomy_free_run_action_family(action)
    family_counts = progression.get("completed_family_counts") if isinstance(progression.get("completed_family_counts"), dict) else {}
    missing_grounded_families = progression.get("missing_grounded_families") if isinstance(progression.get("missing_grounded_families"), list) else []
    last_grounded_family = str(progression.get("last_grounded_family") or "")
    same_grounded_family_streak = int(progression.get("same_grounded_family_streak") or 0)
    chooser_load = str(guidance.get("chooser_load") or "normal")
    agenda_action = str(guidance.get("agenda_action") or "")
    score = float(AUTONOMY_FREE_RUN_COUNCIL_WEIGHTS.get(lane_name, 1.0))
    score += float(AUTONOMY_FREE_RUN_COUNCIL_CONFIDENCE_BONUS.get(str(vote.get("confidence") or "medium"), 0.15))
    if action in recommended_actions:
        score += max(0.3, 0.95 - (recommended_actions.index(action) * 0.12))
    preferred_actions = objective.get("preferred_actions") if isinstance(objective.get("preferred_actions"), list) else []
    avoid_actions = objective.get("avoid_actions") if isinstance(objective.get("avoid_actions"), dict) else {}
    if action in preferred_actions:
        score += max(0.25, 0.8 - (preferred_actions.index(action) * 0.1))
    if action in avoid_actions:
        score -= 1.25
    if action in cooldown_actions:
        score -= 2.75
    if action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS:
        score += 0.15
    if agenda_action and action == agenda_action:
        score += 0.35
    if guidance.get("require_system_touch") and action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS:
        score += 0.8
    if guidance.get("require_system_touch") and action in AUTONOMY_FREE_RUN_INWARD_ACTIONS:
        score -= 1.8
    if guidance.get("require_concrete_outcome") and action in AUTONOMY_FREE_RUN_OUTCOME_ACTIONS:
        score += 1.0
    if guidance.get("require_inquiry_probe"):
        if action == str(guidance.get("inquiry_action") or ""):
            score += 3.0
        elif action in AUTONOMY_FREE_RUN_INWARD_ACTIONS:
            score -= 1.5
    if guidance.get("require_curiosity_probe"):
        if action == "capability_tryout":
            score += 1.35
        elif action in AUTONOMY_FREE_RUN_INWARD_ACTIONS:
            score -= 1.0
    if not bool(quota_records.get("capability_tryout", {}).get("met")) and action == "capability_tryout":
        score += 0.9
    if not bool(quota_records.get("grounded_family_branch", {}).get("met")) and action_family in missing_grounded_families:
        score += 0.7
    if not bool(quota_records.get("concrete_outcome", {}).get("met")) and action in AUTONOMY_FREE_RUN_OUTCOME_ACTIONS:
        score += 0.75
    discouraged_action = str(guidance.get("discouraged_action") or "")
    if discouraged_action and action == discouraged_action:
        score -= 1.0
        if guidance.get("require_diverse_action"):
            score -= 2.0
    if chooser_load == "high" and lane_name in {"observer", "relationship", "deep"}:
        score -= 0.6
    elif chooser_load == "medium" and lane_name == "deep":
        score -= 0.4
    if style == "explorer":
        if action in {"capability_tryout", "updates_status", "openclaw_log_check", "cleanup_candidate_check", "proposal_suggestion"}:
            score += 0.18
        if action == "capability_tryout":
            score += 0.4
        if action == "service_health_check" and action not in preferred_actions:
            score -= 0.35
        if action_family in AUTONOMY_FREE_RUN_GROUNDED_FAMILIES and action_family in missing_grounded_families:
            score += 0.65
        if action_family in AUTONOMY_FREE_RUN_GROUNDED_FAMILIES and int(family_counts.get(action_family, 0) or 0) == 0:
            score += 0.4
        recent_family_count = int(family_counts.get(action_family, 0) or 0)
        if recent_family_count:
            score -= min(1.1, recent_family_count * 0.18)
        if last_grounded_family and action_family == last_grounded_family and same_grounded_family_streak >= 2:
            score -= 1.15
    recent_count = int(recent_action_counts.get(action, 0) or 0)
    if recent_count:
        score -= min(1.0, recent_count * 0.2)
    if previous_actions and action == str(previous_actions[-1].get("action") or ""):
        score -= 0.35
    return round(score, 3)


def choose_autonomy_free_run_action_single_lane(
    config: Dict[str, object],
    *,
    run_id: str,
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
    menu: Dict[str, str],
    guidance: Dict[str, object],
    council_error: str = "",
) -> Dict[str, object]:
    recommended_actions = guidance.get("recommended_actions") if isinstance(guidance.get("recommended_actions"), list) else []
    recommended_reasons = guidance.get("recommended_reasons") if isinstance(guidance.get("recommended_reasons"), list) else []
    raw = ""
    model = resolve_model(config, "chat")
    try:
        raw = model_chat(
            config,
            model,
            [
                *build_eve_identity_system_messages(include_human_context=True, include_active_mind=True, compact=True),
                {
                    "role": "user",
                    "content": build_autonomy_free_run_choice_prompt(
                        run_id=run_id,
                        menu=menu,
                        guidance=guidance,
                        snapshot=snapshot,
                        previous_actions=previous_actions,
                        remaining_seconds=remaining_seconds,
                        lane_name="fast",
                        council_mode=False,
                    ),
                },
            ],
            max_tokens=160,
            think_level=str(config["think_level"]),
            operation="autonomy_free_run_choice",
            timeout_seconds=max(15, min(45, remaining_seconds - 3)),
        )
        payload = extract_json_object(raw, label="autonomy free-run choice")
        action, override, resolved_policy = finalize_autonomy_free_run_choice(
            str(payload.get("action") or "").strip(),
            menu=menu,
            guidance=guidance,
            recommended_actions=recommended_actions,
            selection_policy="guided_choice",
        )
        decision = {
            "action": action,
            "reason": normalize_text_value(payload.get("reason"), fallback="Eve chose to observe.", limit=220),
            "expected_signal": normalize_text_value(payload.get("expected_signal"), fallback="", limit=220),
            "model": model,
            "raw": normalize_text_value(raw, fallback="", limit=1000),
            "recommended_actions": recommended_actions,
            "recommended_reasons": recommended_reasons,
            "curiosity": guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {},
            "selection_policy": resolved_policy,
            "override": override,
        }
        if council_error:
            decision["council_error"] = council_error
        return decision
    except SystemExit as exc:
        inferred_action = infer_autonomy_free_run_action(raw, menu)
        if inferred_action:
            action, override, resolved_policy = finalize_autonomy_free_run_choice(
                inferred_action,
                menu=menu,
                guidance=guidance,
                recommended_actions=recommended_actions,
                selection_policy="repaired_from_text",
            )
            decision = {
                "action": action,
                "reason": "Recovered the intended action from malformed model output and continued the free-run with evidence.",
                "expected_signal": "",
                "model": model,
                "raw": normalize_text_value(raw, fallback="", limit=1000),
                "recommended_actions": recommended_actions,
                "recommended_reasons": recommended_reasons,
                "curiosity": guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {},
                "selection_policy": resolved_policy,
                "override": override,
            }
            if council_error:
                decision["council_error"] = council_error
            return decision
        action, override, resolved_policy = deterministic_autonomy_free_run_fallback_choice(
            menu=menu,
            guidance=guidance,
            recommended_actions=recommended_actions,
            selection_policy="deterministic_guidance_fallback",
        )
        decision = {
            "action": action,
            "reason": (
                "Choice model failed or returned malformed JSON, so Eve followed deterministic bounded guidance instead of going inert: "
                f"{normalize_text_value(exc, fallback='unknown error', limit=180)}"
            ),
            "expected_signal": "Whether the selected bounded action produces grounded evidence despite chooser degradation.",
            "model": model,
            "raw": "",
            "recommended_actions": recommended_actions,
            "recommended_reasons": recommended_reasons,
            "curiosity": guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {},
            "selection_policy": resolved_policy,
            "override": override,
        }
        if council_error:
            decision["council_error"] = council_error
        return decision
    except Exception as exc:
        action, override, resolved_policy = deterministic_autonomy_free_run_fallback_choice(
            menu=menu,
            guidance=guidance,
            recommended_actions=recommended_actions,
            selection_policy="deterministic_guidance_fallback",
        )
        decision = {
            "action": action,
            "reason": (
                "Choice model failed or timed out, so Eve followed deterministic bounded guidance instead of going inert: "
                f"{normalize_text_value(exc, fallback='unknown error', limit=180)}"
            ),
            "expected_signal": "Whether the selected bounded action produces grounded evidence despite chooser degradation.",
            "model": model,
            "raw": "",
            "recommended_actions": recommended_actions,
            "recommended_reasons": recommended_reasons,
            "curiosity": guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {},
            "selection_policy": resolved_policy,
            "override": override,
        }
        if council_error:
            decision["council_error"] = council_error
        return decision


def choose_autonomy_free_run_action_multi_lane(
    config: Dict[str, object],
    *,
    run_id: str,
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
    menu: Dict[str, str],
    guidance: Dict[str, object],
) -> Dict[str, object]:
    lane_names = autonomy_free_run_choice_lanes(guidance, previous_actions, remaining_seconds)
    recommended_actions = guidance.get("recommended_actions") if isinstance(guidance.get("recommended_actions"), list) else []
    recommended_reasons = guidance.get("recommended_reasons") if isinstance(guidance.get("recommended_reasons"), list) else []
    max_workers = min(
        max(1, int(config.get("autonomy_free_run_multi_lane_max_workers") or len(lane_names))),
        len(lane_names),
    )
    lane_votes: List[Dict[str, object]] = []
    with concurrent.futures.ThreadPoolExecutor(
        max_workers=max_workers,
        thread_name_prefix="eve-autonomy-council",
    ) as executor:
        future_to_lane = {
            executor.submit(
                run_autonomy_free_run_choice_lane,
                config,
                lane_name=lane_name,
                run_id=run_id,
                menu=menu,
                guidance=guidance,
                snapshot=snapshot,
                previous_actions=previous_actions,
                remaining_seconds=remaining_seconds,
            ): lane_name
            for lane_name in lane_names
        }
        for future in concurrent.futures.as_completed(future_to_lane):
            lane_votes.append(future.result())
    lane_votes.sort(key=lambda item: lane_names.index(str(item.get("lane") or "")) if str(item.get("lane") or "") in lane_names else 999)
    valid_votes = [
        vote for vote in lane_votes
        if str(vote.get("status") or "") in {"ok", "repaired_from_text"} and str(vote.get("action") or "") in menu
    ]
    if not valid_votes:
        raise SystemExit("No autonomy council lane produced a usable choice.")

    action_scores: Dict[str, float] = {}
    support_map: Dict[str, List[Dict[str, object]]] = {}
    for vote in valid_votes:
        action = str(vote.get("action") or "")
        score = autonomy_free_run_vote_score(
            vote,
            guidance=guidance,
            previous_actions=previous_actions,
            recommended_actions=recommended_actions,
        )
        enriched_vote = dict(vote)
        enriched_vote["score"] = score
        action_scores[action] = round(float(action_scores.get(action, 0.0)) + score, 3)
        support_map.setdefault(action, []).append(enriched_vote)

    ranked_actions = sorted(
        action_scores,
        key=lambda action: (
            action_scores.get(action, 0.0),
            len(support_map.get(action, [])),
            1 if action in AUTONOMY_FREE_RUN_SYSTEM_TOUCH_ACTIONS else 0,
            -(recommended_actions.index(action)) if action in recommended_actions else -999,
        ),
        reverse=True,
    )
    chosen_action = ranked_actions[0]
    supporters = sorted(
        support_map.get(chosen_action, []),
        key=lambda item: float(item.get("score") or 0.0),
        reverse=True,
    )
    supporter_lanes = unique_compact([str(item.get("lane") or "") for item in supporters], limit=4)
    lead_signal = next(
        (normalize_text_value(item.get("expected_signal"), fallback="", limit=220) for item in supporters if item.get("expected_signal")),
        "",
    )
    council_reason = normalize_text_value(
        " ".join(
            [
                f"Council chose `{chosen_action}` after {format_human_context_list(supporter_lanes)} converged."
                if supporter_lanes
                else f"Council chose `{chosen_action}`.",
                *[
                    normalize_text_value(item.get("reason"), fallback="", limit=120)
                    for item in supporters[:2]
                    if normalize_text_value(item.get("reason"), fallback="", limit=120)
                ],
            ]
        ),
        fallback=f"Council chose `{chosen_action}`.",
        limit=220,
    )
    action, override, resolved_policy = finalize_autonomy_free_run_choice(
        chosen_action,
        menu=menu,
        guidance=guidance,
        recommended_actions=recommended_actions,
        selection_policy="multi_lane_council",
    )
    return {
        "action": action,
        "reason": council_reason,
        "expected_signal": lead_signal,
        "model": "multi_lane_council",
        "consulted_lanes": lane_names,
        "consulted_models": unique_compact([str(item.get("model") or "") for item in lane_votes], limit=8),
        "lane_votes": lane_votes,
        "action_scores": {key: round(value, 3) for key, value in sorted(action_scores.items())},
        "recommended_actions": recommended_actions,
        "recommended_reasons": recommended_reasons,
        "curiosity": guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {},
        "selection_policy": resolved_policy,
        "override": override,
    }


def attach_endogenous_inquiry_to_decision(
    decision: Dict[str, object],
    guidance: Dict[str, object],
) -> Dict[str, object]:
    selected = guidance.get("selected_inquiry") if isinstance(guidance.get("selected_inquiry"), dict) else {}
    inquiry_action = normalize_text_value(guidance.get("inquiry_action"), fallback="", limit=80)
    if (
        not selected.get("id")
        or not inquiry_action
        or normalize_text_value(decision.get("action"), fallback="", limit=80) != inquiry_action
    ):
        return decision
    enriched = dict(decision)
    selection_policy = normalize_text_value(
        enriched.get("selection_policy"),
        fallback="",
        limit=80,
    )
    if selection_policy == "forced_endogenous_inquiry_probe":
        chooser_reason = normalize_text_value(
            enriched.get("reason"),
            fallback="",
            limit=220,
        )
        actual_reason = normalize_text_value(
            enriched.get("override"),
            fallback=(
                "Eve's recurrent world model selected this bounded observation "
                "to answer its active source-grounded question."
            ),
            limit=320,
        )
        if chooser_reason and chooser_reason != actual_reason:
            enriched["chooser_reason"] = chooser_reason
        enriched["reason"] = actual_reason
    enriched.update(
        {
            "inquiry_id": normalize_text_value(selected.get("id"), fallback="", limit=100),
            "epistemic_question": normalize_text_value(selected.get("question"), fallback="", limit=320),
            "inquiry_source": normalize_text_value(selected.get("source"), fallback="world_model", limit=100),
            "inquiry_source_ids": normalize_text_list(selected.get("source_ids"), limit=6),
            "inquiry_source_fingerprint": normalize_text_value(selected.get("source_fingerprint"), fallback="", limit=160),
            "inquiry_attempt_count": clamp_int(guidance.get("inquiry_attempt_count"), 0, minimum=0, maximum=100),
            "inquiry_attempted_actions": normalize_text_list(guidance.get("inquiry_attempted_actions"), limit=5),
            "inquiry_failed_actions": normalize_text_list(guidance.get("inquiry_failed_actions"), limit=5),
            "inquiry_recovery_step": bool(guidance.get("inquiry_recovery_step")),
            "expected_signal": normalize_text_value(
                selected.get("expected_observation"),
                fallback=enriched.get("expected_signal") or "A bounded observation should reduce the selected world-model uncertainty.",
                limit=260,
            ),
        }
    )
    return enriched


def choose_autonomy_free_run_action(
    config: Dict[str, object],
    *,
    run_id: str,
    snapshot: Dict[str, object],
    previous_actions: List[Dict[str, object]],
    remaining_seconds: int,
    style: object = "explorer",
) -> Dict[str, object]:
    menu = autonomy_free_run_action_menu(remaining_seconds)
    normalized_style = normalize_autonomy_free_run_style(
        style,
        default=str(config.get("autonomy_free_run_default_style") or "explorer"),
    )
    guidance = autonomy_free_run_guidance(
        menu,
        snapshot,
        previous_actions,
        remaining_seconds,
        style=normalized_style,
        config=config,
    )
    recommended_actions = guidance.get("recommended_actions") if isinstance(guidance.get("recommended_actions"), list) else []
    recommended_reasons = guidance.get("recommended_reasons") if isinstance(guidance.get("recommended_reasons"), list) else []
    if str(guidance.get("chooser_load") or "") == "high":
        action, override, resolved_policy = deterministic_autonomy_free_run_fallback_choice(
            menu=menu,
            guidance=guidance,
            recommended_actions=recommended_actions,
            selection_policy="deterministic_load_shed",
        )
        return attach_endogenous_inquiry_to_decision({
            "action": action,
            "reason": "Chooser load is high, so Eve used deterministic bounded guidance instead of spending more model budget on the chooser.",
            "expected_signal": "Whether a low-overhead grounded action can move the run forward while model-choice pressure cools down.",
            "model": "deterministic_load_shed",
            "recommended_actions": recommended_actions,
            "recommended_reasons": recommended_reasons,
            "curiosity": guidance.get("curiosity") if isinstance(guidance.get("curiosity"), dict) else {},
            "selection_policy": resolved_policy,
            "override": override,
            "chooser_load": guidance.get("chooser_load"),
        }, guidance)
    council_error = ""
    if (
        str(guidance.get("chooser_load") or "") != "medium"
        and autonomy_free_run_choice_council_enabled(config)
        and remaining_seconds >= 20
    ):
        try:
            decision = choose_autonomy_free_run_action_multi_lane(
                config,
                run_id=run_id,
                snapshot=snapshot,
                previous_actions=previous_actions,
                remaining_seconds=remaining_seconds,
                menu=menu,
                guidance=guidance,
            )
            return attach_endogenous_inquiry_to_decision(decision, guidance)
        except SystemExit as exc:
            council_error = normalize_text_value(exc, fallback="multi-lane autonomy council failed", limit=220)
        except Exception as exc:
            council_error = normalize_text_value(exc, fallback="multi-lane autonomy council failed", limit=220)
    decision = choose_autonomy_free_run_action_single_lane(
        config,
        run_id=run_id,
        snapshot=snapshot,
        previous_actions=previous_actions,
        remaining_seconds=remaining_seconds,
        menu=menu,
        guidance=guidance,
        council_error=council_error,
    )
    return attach_endogenous_inquiry_to_decision(decision, guidance)


def record_autonomy_prediction_check(
    decision: Dict[str, object],
    action_result: Dict[str, object],
    run_id: str,
) -> Optional[Dict[str, object]]:
    """Predictive processing seed: every autonomy decision states an
    expected_signal — this closes the loop by comparing expectation to the
    verified outcome and recording a graded prediction error. Consumed by the
    homeostasis surprise pressure and the workspace prediction_errors field."""
    expected = normalize_text_value(decision.get("expected_signal"), fallback="", limit=220)
    if not expected:
        return None
    confidence = str(decision.get("confidence") or "medium").strip().lower()
    observation = autonomy_action_outcome_observation(action_result)
    status = str(observation.get("status") or "")
    consequence_observed = bool(observation.get("consequence_observed"))
    outcome_ok = observation.get("outcome_ok") if consequence_observed else None
    evidence_kind = str(observation.get("evidence_kind") or "pending")
    fulfilled = outcome_ok if consequence_observed else None
    if fulfilled is True:
        error_magnitude = 0
    elif fulfilled is False:
        error_magnitude = {"high": 80, "medium": 55, "low": 30}.get(confidence, 55)
    else:
        error_magnitude = None
    record = {
        "timestamp": utc_now(),
        "run_id": run_id,
        "action": normalize_text_value(action_result.get("action"), fallback="", limit=80),
        "expected_signal": expected,
        "confidence": confidence,
        "observed": normalize_text_value(action_result.get("summary"), fallback=status, limit=220),
        "status": status,
        "fulfilled": fulfilled,
        "error_magnitude": error_magnitude,
        "consequence_observed": consequence_observed,
        "outcome_ok": outcome_ok,
        "evidence_kind": evidence_kind,
    }
    append_prediction_check_record(record)
    return record


def autonomy_action_outcome_observation(action_result: Dict[str, object]) -> Dict[str, object]:
    """Classify whether an autonomy action produced an observed consequence.

    Explicit execution verification is authoritative.  A terminal in-process
    result can close a purely internal action, but it remains labeled as process
    evidence rather than independent verification.
    """
    status = str(action_result.get("status") or "")
    verification = action_result_explicit_verification(action_result)
    explicit_ok = parse_explicit_boolish(action_result.get("ok")) if "ok" in action_result else None
    terminal = status in {"completed", "blocked", "error", "skipped", "failed"}
    consequence_observed = verification is not None or (terminal and explicit_ok is not None)
    outcome_ok: Optional[bool]
    evidence_kind: str
    if verification is not None:
        outcome_ok = bool(verification and status == "completed")
        evidence_kind = "explicit_verification"
    elif consequence_observed:
        outcome_ok = bool(explicit_ok and status == "completed")
        evidence_kind = "executor_process_result"
    else:
        outcome_ok = None
        evidence_kind = "pending"
    return {
        "status": status,
        "consequence_observed": consequence_observed,
        "outcome_ok": outcome_ok,
        "evidence_kind": evidence_kind,
    }


def record_world_model_inquiry_observation(
    decision: Dict[str, object],
    action_result: Dict[str, object],
    *,
    run_id: str,
    source_cycle_id: object,
) -> Optional[Dict[str, object]]:
    inquiry_id = normalize_text_value(decision.get("inquiry_id"), fallback="", limit=100)
    if not inquiry_id:
        return None
    selected_action = normalize_text_value(decision.get("action"), fallback="", limit=80)
    observation = autonomy_action_outcome_observation(action_result)
    observed_summary = normalize_text_value(
        action_result.get("summary"),
        fallback=observation.get("status") or "No observation was recorded.",
        limit=220,
    )
    attempted_at = utc_now()
    attempt = {
        "attempted_at": attempted_at,
        "run_id": normalize_text_value(run_id, fallback="", limit=100),
        "source_cycle_id": normalize_text_value(source_cycle_id, fallback="", limit=100),
        "action": selected_action,
        "status": observation.get("status"),
        "consequence_observed": bool(observation.get("consequence_observed")),
        "outcome_ok": observation.get("outcome_ok"),
        "evidence_kind": observation.get("evidence_kind"),
        "observed": observed_summary,
    }

    def mutator(payload: Dict[str, object]) -> Dict[str, object]:
        normalized = normalize_world_model_state(payload)
        open_questions = [
            dict(item)
            for item in normalized.get("open_questions") or []
            if isinstance(item, dict)
        ]
        answered_questions = [
            dict(item)
            for item in normalized.get("answered_questions") or []
            if isinstance(item, dict)
        ]
        index = next(
            (
                position
                for position, item in enumerate(open_questions)
                if str(item.get("id") or "") == inquiry_id
            ),
            -1,
        )
        if index < 0:
            return {
                "inquiry_id": inquiry_id,
                "status": "not_found",
                "answered": False,
                "attempt": attempt,
            }
        inquiry = dict(open_questions[index])
        attempts = [dict(item) for item in inquiry.get("attempts") or [] if isinstance(item, dict)]
        attempts.append(attempt)
        inquiry["attempts"] = attempts[-8:]
        inquiry["updated_at"] = attempted_at
        inquiry["last_observation"] = observed_summary
        verified_completed_observation = bool(
            observation.get("consequence_observed")
            and observation.get("outcome_ok") is True
            and str(observation.get("status") or "") == "completed"
        )
        if verified_completed_observation:
            inquiry.update(
                status="answered",
                answer=observed_summary,
                answered_at=attempted_at,
                selected_action="",
            )
            open_questions.pop(index)
            answered_questions.insert(0, inquiry)
            normalized["live_unknowns"] = [
                item
                for item in normalized.get("live_unknowns") or []
                if str(item).strip().lower() != str(inquiry.get("question") or "").strip().lower()
            ]
        else:
            remaining_actions = [
                action
                for action in inquiry.get("candidate_actions") or []
                if action != selected_action
                and action not in {str(item.get("action") or "") for item in inquiry["attempts"]}
            ]
            if remaining_actions:
                inquiry["status"] = "open"
                inquiry["selected_action"] = remaining_actions[0]
            elif str(observation.get("status") or "") in {"blocked", "error", "failed", "skipped"}:
                inquiry["status"] = "blocked"
                inquiry["selected_action"] = ""
            else:
                inquiry["status"] = "in_progress"
            open_questions[index] = inquiry
        normalized["open_questions"] = open_questions
        normalized["answered_questions"] = answered_questions[:16]
        normalized["updated_at"] = attempted_at
        normalized["source"] = f"autonomy_inquiry_observation:{normalize_text_value(run_id, fallback='run', limit=80)}"
        normalized = normalize_world_model_state(normalized)
        payload.clear()
        payload.update(normalized)
        return {
            "inquiry_id": inquiry_id,
            "question": inquiry.get("question"),
            "source_fingerprint": inquiry.get("source_fingerprint"),
            "status": inquiry.get("status"),
            "answered": verified_completed_observation,
            "answer": inquiry.get("answer") or "",
            "attempt_count": len(inquiry.get("attempts") or []),
            "next_action": inquiry.get("selected_action") or "",
            "recovery_required": bool(not verified_completed_observation and inquiry.get("selected_action")),
            "probe_exhausted": bool(
                not verified_completed_observation
                and not inquiry.get("selected_action")
                and inquiry.get("status") in {"blocked", "in_progress"}
            ),
            "attempt": attempt,
        }

    return WORLD_MODEL_REPOSITORY.update(mutator)


PREDICTION_CHECKS_KEEP = 500  # ~several days at observed cadence; readers only need ~24h


def append_prediction_check_record(record: Dict[str, object], keep: int = PREDICTION_CHECKS_KEEP) -> bool:
    """Capped append for the shared prediction-error ledger (autonomy + conversational
    producers). Without a cap the file grew unbounded and the reader loaded all of it;
    this trims to the most recent `keep` and mirrors to runtime for both producers."""
    try:
        ensure_store()
        with store_lock(PREDICTION_CHECKS_PATH):
            records = read_jsonl_records(PREDICTION_CHECKS_PATH)
            if str(record.get("kind") or "") == "conversational":
                reply_id = str(record.get("scored_reply_id") or "")
                observed_message_id = str(record.get("observed_message_id") or "")
                for existing in reversed(records):
                    if not isinstance(existing, dict) or str(existing.get("kind") or "") != "conversational":
                        continue
                    if reply_id and str(existing.get("scored_reply_id") or "") != reply_id:
                        continue
                    if observed_message_id and str(existing.get("observed_message_id") or "") == observed_message_id:
                        return False
                    if record.get("consequence_observed") and existing.get("consequence_observed"):
                        # One immediate lived consequence closes one reply.  Do
                        # not reward or penalize retries/concurrent requests.
                        return False
            records.append(record)
            if len(records) > keep:
                records = records[-keep:]
            write_jsonl_records(PREDICTION_CHECKS_PATH, records)
        mirror_store_file_to_runtime(PREDICTION_CHECKS_PATH)
        return True
    except Exception:
        return False


def read_recent_prediction_checks(hours: float = 24.0, limit: int = 24) -> List[Dict[str, object]]:
    try:
        records = read_jsonl_records(resolve_store_read_path(PREDICTION_CHECKS_PATH, prefer_runtime=True))
    except Exception:
        return []
    cutoff = utc_now_datetime() - timedelta(hours=max(1.0, hours))
    recent: List[Dict[str, object]] = []
    for record in records[-limit * 4 :]:
        if not isinstance(record, dict):
            continue
        when = parse_iso_datetime(record.get("timestamp"))
        if when is None or when < cutoff:
            continue
        recent.append(record)
    return recent[-limit:]


def run_bounded_system_tasks_step(
    config: Dict[str, object],
    *,
    source: str,
    state: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    """Refresh and advance at most one CPU and one maintenance task.

    This is the bounded body contract for a recurrent ``system_tasks``
    intention.  It deliberately does not grant a new tool or permission: it
    reuses the existing CPU-task executor, keeps its one-task limits, and
    returns explicit consequence evidence to the enclosing recurrent cycle.
    """
    runtime_state = state if isinstance(state, dict) else load_state(prefer_runtime=True)
    snapshot = load_system_snapshot(prefer_runtime=True)
    if not snapshot:
        return {
            "action": "system_tasks",
            "status": "skipped",
            "executed": False,
            "ok": False,
            "execution_verification_ok": False,
            "summary": "No system snapshot was available for the bounded CPU-side task step.",
        }

    created = refresh_system_tasks_from_snapshot(snapshot, runtime_state, source=source, config=config)
    task_records = read_system_tasks()
    execution_graph = build_system_task_graph(task_records)
    # The enclosing developmental/autonomy cycle owns conscious attribution.
    # Avoid crediting the same consequence twice inside the lower-level task
    # executor.
    completed = run_pending_cpu_system_tasks(
        config,
        runtime_state,
        snapshot,
        source=source,
        limit=1,
        conscious_attribution=False,
        task_records=task_records,
        execution_graph=execution_graph,
    )
    maintenance = run_pending_safe_maintenance_tasks(
        config,
        runtime_state,
        snapshot,
        source=source,
        limit=1,
        task_records=task_records,
        execution_graph=execution_graph,
    )
    created = created if isinstance(created, list) else []
    completed = completed if isinstance(completed, list) else []
    maintenance = maintenance if isinstance(maintenance, list) else []
    save_state(runtime_state)
    summary = (
        f"Created {len(created)} task(s), completed {len(completed)} CPU task(s), "
        f"processed {len(maintenance)} maintenance task(s)."
    )
    timestamp = utc_now()
    execution = record_operational_action_execution(
        {
            "id": str(uuid.uuid4()),
            "created_at": timestamp,
            "updated_at": timestamp,
            "action": "system_tasks",
            "source": source,
            "backend": "bounded_system_task_executor",
            "tree_status": "SUCCESS",
            "verification_ok": True,
            "result_ok": True,
            "summary": summary,
            "steps": [
                {
                    "phase": "verify_bounded_task_consequence",
                    "ok": True,
                    "created_count": len(created),
                    "completed_count": len(completed),
                    "maintenance_count": len(maintenance),
                }
            ],
            "activity_tail": [],
            "metadata": {
                "created_count": len(created),
                "completed_count": len(completed),
                "maintenance_count": len(maintenance),
                "bounded_cpu_limit": 1,
                "bounded_maintenance_limit": 1,
            },
            **operational_action_privacy_boundary("system_tasks"),
        }
    )
    return {
        "action": "system_tasks",
        "status": "completed",
        "executed": True,
        "ok": True,
        "execution_backend": "bounded_system_task_executor",
        "execution_tree_status": "SUCCESS",
        "execution_verification_ok": True,
        "execution_id": normalize_text_value(execution.get("id"), fallback="", limit=80),
        "execution_summary": summary,
        "summary": summary,
        "created_count": len(created),
        "completed_count": len(completed),
        "maintenance_count": len(maintenance),
        "created_task_ids": [
            normalize_text_value(item.get("id"), fallback="", limit=80)
            for item in created
            if isinstance(item, dict) and item.get("id")
        ],
        "completed_task_ids": [
            normalize_text_value(item.get("id"), fallback="", limit=80)
            for item in completed
            if isinstance(item, dict) and item.get("id")
        ],
    }


def execute_autonomy_free_run_action(
    config: Dict[str, object],
    *,
    run_id: str,
    action: str,
    reason: str,
    deadline: float,
    previous_actions: Optional[List[Dict[str, object]]] = None,
) -> Dict[str, object]:
    started = time.time()
    remaining_seconds = int(deadline - started)
    source = f"autonomy_free_run:{run_id}"
    result: Dict[str, object] = {
        "action": action,
        "status": "started",
        "ok": False,
        "summary": "",
        "reason": reason,
        "started_at": utc_now(),
    }
    try:
        if remaining_seconds <= 4:
            result.update(status="skipped", summary="Not enough time remained for another action.")

        elif action == "wait_observe":
            time.sleep(min(5, max(1, remaining_seconds - 1)))
            result.update(status="completed", ok=True, summary="Eve chose to pause and observe rather than manufacture activity.")

        elif action == "ambient_note":
            snapshot = collect_autonomy_free_run_snapshot(config)
            focus = snapshot.get("active_mind", {}).get("current_focus") or "Eve is observing the free-run window."
            update_ambient_thought(
                title="Eve is choosing her next move.",
                detail=f"Free-run {run_id}: {normalize_text_value(focus, fallback='', limit=180)}",
                model="deterministic",
                source=source,
                status="active",
                thread_beats=[],
            )
            result.update(status="completed", ok=True, summary="Updated ambient thought with the current free-run focus.")

        elif action == "mind_tick":
            record = run_mind_tick(
                config,
                source=source,
                max_tokens=max(120, min(int(config.get("mind_tick_max_tokens") or 220), 220)),
            )
            mind = record.get("mind") if isinstance(record.get("mind"), dict) else {}
            result.update(
                status="completed",
                ok=True,
                summary=normalize_text_value(mind.get("next_step") or mind.get("summary"), fallback="Mind tick completed.", limit=260),
                model=record.get("model"),
            )

        elif action == "thought":
            thought = generate_continuous_thought(
                config,
                context_limit=min(int(config.get("thought_context_limit") or 12), 6),
                thought_history_limit=min(int(config.get("thought_history_limit") or 6), 3),
                max_tokens=max(90, min(int(config.get("thought_max_tokens") or 180), 160)),
                timeout_seconds=max(20, min(60, remaining_seconds - 2)),
            )
            learning_episode = record_continuous_thought_learning_episode_safe(
                thought,
                source=source,
            )
            append_entry(
                "thought",
                str(thought["response"]),
                metadata={
                    "model": thought.get("model"),
                    "attempted_model": thought.get("attempted_model"),
                    "source": source,
                    "autonomy_run_id": run_id,
                    "source_entries": thought.get("source_entries"),
                    "source_thoughts": thought.get("source_thoughts"),
                    "grounded": bool(thought.get("grounded")),
                    "used_fallback": bool(thought.get("used_fallback")),
                    "quality_issues": list(thought.get("quality_issues") or []),
                    "model_path_grounded": bool(thought.get("model_path_grounded")),
                    "epistemic_critic": thought.get("epistemic_critic") or {},
                    "current_state_record_hash": thought.get("current_state_record_hash"),
                    "learning_episode_id": (
                        learning_episode.get("id")
                        if isinstance(learning_episode, dict)
                        else ""
                    ),
                    "action_claim_grounding_triggered": bool(
                        thought.get("action_claim_grounding_triggered")
                    ),
                },
            )
            result.update(
                status="completed",
                ok=True,
                summary=normalize_text_value(thought.get("response"), fallback="Thought generated.", limit=260),
                model=thought.get("model"),
            )

        elif action == "system_tasks":
            result.update(run_bounded_system_tasks_step(config, source=source))

        elif action == "capability_tryout":
            tried_this_window = [
                normalize_text_value(item.get("capability_variant"), fallback="", limit=80)
                for item in (previous_actions or [])
                if isinstance(item, dict)
                and str(item.get("action") or "") == "capability_tryout"
                and normalize_text_value(item.get("capability_variant"), fallback="", limit=80)
            ]
            tryout = run_bounded_capability_tryout(
                config,
                source=source,
                remaining_seconds=remaining_seconds,
                tried_this_window=tried_this_window,
            )
            result.update(
                status="completed" if tryout.get("executed") else "blocked",
                ok=bool(tryout.get("ok")),
                summary=normalize_text_value(
                    f"{tryout.get('variant')}: {tryout.get('summary')}",
                    fallback="Capability tryout completed.",
                    limit=260,
                ),
                capability_variant=tryout.get("variant"),
                artifact_path=tryout.get("artifact_path"),
                execution_id=tryout.get("execution_id"),
            )

        elif action in {"service_health_check", "cleanup_candidate_check", "openclaw_log_check", "openclaw_sync_check"}:
            if action == "openclaw_sync_check" and remaining_seconds < 75:
                result.update(status="skipped", summary="Skipped OpenClaw sync because the run was too close to the deadline.")
            else:
                operation = run_operational_action_tree(action, config, source=source)
                result.update(
                    status="completed" if operation.get("executed") else "blocked",
                    ok=action_result_verified_for_completion(operation),
                    summary=normalize_text_value(
                        operation.get("summary") or operation.get("issue") or operation.get("response"),
                        fallback=f"{action} completed.",
                        limit=260,
                    ),
                    execution_id=operation.get("execution_id"),
                    execution_tree_status=operation.get("execution_tree_status"),
                    execution_verification_ok=action_result_explicit_verification(operation),
                )

        elif action == "updates_status":
            update_state = load_component_update_state(prefer_runtime=True)
            updates = [
                item
                for item in update_state.get("components", [])
                if isinstance(item, dict) and item.get("update_available")
            ]
            result.update(
                status="completed",
                ok=True,
                summary=f"{len(updates)} update signal(s): {', '.join(str(item.get('id')) for item in updates[:6]) or 'none'}.",
            )

        elif action == "proposal_suggestion":
            gate_reason = autonomy_action_block_reason("daemon_proposal")
            if gate_reason:
                result.update(status="blocked", summary=gate_reason)
            else:
                proposal = suggest_proposal(
                    config,
                    source=source,
                    max_tokens=max(160, min(int(config.get("proposal_max_tokens") or 260), 260)),
                    timeout_seconds=max(30, min(90, remaining_seconds - 2)),
                )
                result.update(
                    status="completed",
                    ok=True,
                    summary=f"Drafted proposal: {proposal.get('title')}",
                    proposal_id=proposal.get("id"),
                )
        else:
            result.update(status="blocked", summary=f"Unknown free-run action `{action}`.")
    except SystemExit as exc:
        result.update(status="error", ok=False, summary=normalize_text_value(exc, fallback="Action failed.", limit=260))
    except Exception as exc:
        result.update(status="error", ok=False, summary=normalize_text_value(exc, fallback="Action failed.", limit=260))

    result["finished_at"] = utc_now()
    result["duration_ms"] = round((time.time() - started) * 1000, 2)
    return result


def autonomy_free_run_claim_audit(actions: List[Dict[str, object]]) -> List[Dict[str, object]]:
    completed_actions = {
        str(item.get("action") or "")
        for item in actions
        if str(item.get("status") or "") == "completed"
    }
    findings: List[Dict[str, object]] = []
    for index, item in enumerate(actions):
        action = str(item.get("action") or "")
        for finding in unsupported_action_claim_findings(item.get("summary"), completed_actions):
            findings.append(
                {
                    "index": index,
                    "action": action,
                    "text": normalize_text_value(item.get("summary"), fallback="", limit=260),
                    **finding,
                }
            )
    return findings


def autonomy_free_run_decision_model_mix(decisions: List[Dict[str, object]]) -> Dict[str, object]:
    primary: Dict[str, int] = {}
    consulted: Dict[str, int] = {}
    lanes: Dict[str, int] = {}
    for item in decisions:
        primary_model = str(item.get("model") or "")
        if primary_model:
            primary[primary_model] = int(primary.get(primary_model, 0)) + 1
        for model in item.get("consulted_models", []) if isinstance(item.get("consulted_models"), list) else []:
            key = str(model or "")
            if not key:
                continue
            consulted[key] = int(consulted.get(key, 0)) + 1
        for lane_name in item.get("consulted_lanes", []) if isinstance(item.get("consulted_lanes"), list) else []:
            key = str(lane_name or "")
            if not key:
                continue
            lanes[key] = int(lanes.get(key, 0)) + 1
    return {
        "primary": dict(sorted(primary.items())),
        "consulted": dict(sorted(consulted.items())),
        "lanes": dict(sorted(lanes.items())),
    }


def autonomy_runs_read_dir(*, prefer_runtime: bool = False) -> Path:
    ensure_store()
    return resolve_store_read_path(AUTONOMY_RUNS_DIR, prefer_runtime=prefer_runtime)


def read_autonomy_run_summaries(limit: int = 10, *, prefer_runtime: bool = False) -> List[Dict[str, object]]:
    directory = autonomy_runs_read_dir(prefer_runtime=prefer_runtime)
    if not directory.exists():
        return []
    requested_limit = max(1, int(limit))
    candidate_paths: List[Tuple[float, Path]] = []
    for path in directory.glob("*.summary.json"):
        try:
            stat = path.stat()
        except OSError:
            continue
        if stat.st_size > 2_000_000:
            continue
        if runtime_bundle_file_is_dataless(path):
            continue
        candidate_paths.append((float(stat.st_mtime), path))
    candidate_paths.sort(key=lambda item: (item[0], item[1].name), reverse=True)
    candidate_limit = requested_limit
    if requested_limit < 100:
        # Hot chooser paths only need recent summaries; reading every old summary can
        # block on filesystem/cloud-placeholder edge cases and stall autonomy.
        candidate_limit = max(40, requested_limit * 4)
    records: List[Dict[str, object]] = []
    for _, path in candidate_paths[: min(len(candidate_paths), candidate_limit)]:
        try:
            payload = eve_store.load_json_dict(path, default={})
        except Exception:
            continue
        if not isinstance(payload, dict):
            continue
        run_id = str(payload.get("run_id") or "").strip()
        if not run_id:
            continue
        record = dict(payload)
        record.setdefault("summary_path", str(path))
        record.setdefault("log_path", str(directory / f"{component_slug(run_id)}.jsonl"))
        records.append(record)
    records.sort(
        key=lambda item: (
            str(item.get("finished_at") or ""),
            str(item.get("started_at") or ""),
            str(item.get("run_id") or ""),
        ),
        reverse=True,
    )
    return records[:requested_limit]


def format_autonomy_run_summary(record: Dict[str, object], *, full: bool = False) -> str:
    run_id = str(record.get("run_id") or "unknown")
    style = normalize_autonomy_free_run_style(record.get("style"), default="explorer")
    source = normalize_text_value(record.get("source"), fallback="manual", limit=80)
    action_mix = record.get("action_mix") if isinstance(record.get("action_mix"), dict) else {}
    decision_model_mix = record.get("decision_model_mix") if isinstance(record.get("decision_model_mix"), dict) else {}
    run_objective = record.get("run_objective") if isinstance(record.get("run_objective"), dict) else {}
    supervisor = record.get("supervisor") if isinstance(record.get("supervisor"), dict) else {}
    agenda = record.get("agenda") if isinstance(record.get("agenda"), dict) else {}
    governance_gate = record.get("governance_gate") if isinstance(record.get("governance_gate"), dict) else {}
    actions = record.get("actions") if isinstance(record.get("actions"), list) else []
    claim_audit = record.get("claim_audit") if isinstance(record.get("claim_audit"), list) else []
    errors = record.get("errors") if isinstance(record.get("errors"), list) else []
    by_action = action_mix.get("by_action") if isinstance(action_mix.get("by_action"), dict) else {}
    top_actions = ", ".join(
        f"{name}={count}"
        for name, count in sorted(by_action.items(), key=lambda item: (-int(item[1]), str(item[0])))[:8]
    ) or "none"
    by_family = action_mix.get("by_family") if isinstance(action_mix.get("by_family"), dict) else {}
    if not by_family and actions:
        by_family = autonomy_free_run_action_mix(actions).get("by_family") or {}
    top_families = ", ".join(
        f"{name}={count}"
        for name, count in sorted(by_family.items(), key=lambda item: (-int(item[1]), str(item[0])))[:8]
    ) or "none"
    by_variant = action_mix.get("by_capability_variant") if isinstance(action_mix.get("by_capability_variant"), dict) else {}
    if not by_variant and actions:
        computed_mix = autonomy_free_run_action_mix(actions)
        by_variant = computed_mix.get("by_capability_variant") or {}
        action_mix = {**action_mix, "by_capability_variant": by_variant}
    top_variants = ", ".join(
        f"{name}={count}"
        for name, count in sorted(by_variant.items(), key=lambda item: (-int(item[1]), str(item[0])))[:8]
    ) or "none"
    novelty_balance = supervisor.get("novelty_action_balance") if isinstance(supervisor.get("novelty_action_balance"), dict) else {}
    if not novelty_balance and actions:
        novelty_balance = autonomy_free_run_novelty_balance_score(actions, action_mix)
    primary_models = format_human_context_list(list((decision_model_mix.get("primary") or {}).keys()))
    consulted_models = format_human_context_list(list((decision_model_mix.get("consulted") or {}).keys()))
    lines = [
        f"{run_id} [{style} | {source}]",
        f"window: {record.get('started_at') or 'unknown'} -> {record.get('finished_at') or 'unknown'}",
        (
            f"monitor_samples: {record.get('monitor_samples') or 0} | "
            f"decisions: {record.get('decisions') or 0} | "
            f"actions: {len(actions)}"
        ),
        (
            f"action_mix: system_touch={action_mix.get('system_touch', 0)} | "
            f"inward={action_mix.get('inward', 0)} | passive={action_mix.get('passive', 0)} | "
            f"by_action: {top_actions}"
        ),
        f"family_mix: {top_families}",
        f"capability_variants: {top_variants}",
        f"controllers: primary {primary_models} | consulted {consulted_models}",
        f"phase: {run_objective.get('phase') or 'unknown'} | objective: {run_objective.get('objective') or 'none recorded'}",
        f"supervisor: {supervisor.get('score') or 0}/100 {supervisor.get('verdict') or 'unknown'}",
        f"novelty_balance: {novelty_balance.get('score') or 0}/100 | distinct_actions={novelty_balance.get('distinct_actions') or 0} | distinct_families={novelty_balance.get('distinct_families') or 0} | distinct_capability_variants={novelty_balance.get('distinct_capability_variants') or 0}",
        (
            f"governance_gate: {governance_gate.get('status') or 'clear'} | "
            f"queued={governance_gate.get('proposal_count') or 0}"
        ),
        f"agenda_focus: {agenda.get('current_focus') or 'none recorded'}",
        f"style_note: {autonomy_free_run_style_description(style)}",
        f"claim_audit: {len(claim_audit)} finding(s) | errors: {len(errors)}",
    ]
    final_snapshot = record.get("final_snapshot") if isinstance(record.get("final_snapshot"), dict) else {}
    final_mind = final_snapshot.get("active_mind") if isinstance(final_snapshot.get("active_mind"), dict) else {}
    if full:
        lines.extend(
            [
                f"final_focus: {final_mind.get('current_focus') or 'none recorded'}",
                f"final_next_step: {final_mind.get('next_step') or 'none recorded'}",
                f"log_path: {record.get('log_path') or 'unknown'}",
                f"summary_path: {record.get('summary_path') or 'unknown'}",
            ]
        )
        if actions:
            lines.append("actions:")
            lines.extend(
                f"- {item.get('action')}: {item.get('status')} | {normalize_text_value(item.get('summary'), fallback='', limit=180)}"
                for item in actions[:12]
            )
        if claim_audit:
            lines.append("claim_audit_findings:")
            lines.extend(
                f"- [{item.get('severity')}] {item.get('kind')}: {item.get('claim')}"
                for item in claim_audit[:8]
            )
        if errors:
            lines.append("errors:")
            lines.extend(
                f"- {normalize_text_value(item.get('error') or item.get('summary'), fallback='unknown error', limit=220)}"
                for item in errors[:6]
            )
    return "\n".join(lines)


AUTONOMY_GOVERNANCE_COLLECTION_FIELDS = (
    "memory_patches",
    "user_model_patches",
    "skill_patches",
    "capability_patches",
)

AUTONOMY_GOVERNANCE_DIRECT_FIELDS = ("governance_proposals", "proposals")

AUTONOMY_GOVERNANCE_PROPOSAL_TYPES = {
    "MemoryPatchProposal",
    "UserModelPatchProposal",
    "SkillPatchProposal",
    "CapabilityPatchProposal",
}


def autonomy_action_governance_payloads(action_result: Dict[str, object]) -> List[Dict[str, object]]:
    payloads: List[Dict[str, object]] = []
    collection_payload: Dict[str, object] = {}
    for field in AUTONOMY_GOVERNANCE_COLLECTION_FIELDS:
        raw_items = action_result.get(field)
        if isinstance(raw_items, dict):
            raw_items = [raw_items]
        if not isinstance(raw_items, list):
            continue
        items = [dict(item) for item in raw_items if isinstance(item, dict)]
        if items:
            collection_payload[field] = items
    if collection_payload:
        payloads.append(collection_payload)

    for field in AUTONOMY_GOVERNANCE_DIRECT_FIELDS:
        raw_proposals = action_result.get(field)
        if isinstance(raw_proposals, dict):
            raw_proposals = [raw_proposals]
        if not isinstance(raw_proposals, list):
            continue
        proposals: List[Dict[str, object]] = []
        for item in raw_proposals:
            if not isinstance(item, dict):
                continue
            proposal_type = normalize_text_value(
                item.get("proposal_type") or item.get("type"),
                fallback="",
                limit=120,
            )
            if proposal_type in AUTONOMY_GOVERNANCE_PROPOSAL_TYPES:
                proposals.append(dict(item))
        if proposals:
            payloads.append({"proposals": proposals})
    return payloads


def autonomy_governance_gate_key(
    *,
    run_id: str,
    action_index: int,
    proposal_index: int,
    proposal: Dict[str, object],
) -> str:
    seed = {
        "run_id": run_id,
        "action_index": action_index,
        "proposal_index": proposal_index,
        "type": proposal.get("type"),
        "payload": proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {},
    }
    return "autonomy_gate:" + eve_governance.stable_json_hash(seed).replace("sha256:", "")[:24]


def existing_autonomy_governance_gate_keys() -> set[str]:
    keys: set[str] = set()
    for proposal in read_governance_proposals(limit=None):
        payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
        key = normalize_text_value(payload.get("autonomy_gate_key"), fallback="", limit=120)
        if key:
            keys.add(key)
    return keys


def enqueue_autonomy_governance_proposals(summary: Dict[str, object]) -> Dict[str, object]:
    run_id = normalize_text_value(summary.get("run_id"), fallback="", limit=120)
    actions = summary.get("actions") if isinstance(summary.get("actions"), list) else []
    summary_path = normalize_text_value(summary.get("summary_path"), fallback="", limit=260)
    source = f"autonomy_free_run:{run_id or 'unknown'}"
    existing_keys = existing_autonomy_governance_gate_keys()
    proposals: List[Dict[str, object]] = []
    errors: List[Dict[str, object]] = []
    skipped_existing = 0
    proposal_counter = 0

    for action_index, action_result in enumerate(actions):
        if not isinstance(action_result, dict):
            continue
        action_name = normalize_text_value(action_result.get("action"), fallback="", limit=80)
        action_summary = normalize_text_value(action_result.get("summary"), fallback="", limit=260)
        evidence = [
            f"autonomy_run:{run_id}",
            f"autonomy_action:{action_index}:{action_name or 'unknown'}",
        ]
        if summary_path:
            evidence.append(f"autonomy_summary:{summary_path}")
        payloads = autonomy_action_governance_payloads(action_result)
        for payload_index, payload in enumerate(payloads):
            try:
                envelopes = eve_governance.proposal_envelopes_from_adapter_payload(
                    payload,
                    default_source=source,
                )
            except ValueError as exc:
                errors.append(
                    {
                        "action_index": action_index,
                        "action": action_name,
                        "payload_index": payload_index,
                        "error": normalize_text_value(exc, fallback="invalid autonomy proposal payload", limit=240),
                    }
                )
                continue
            for envelope in envelopes:
                proposal_payload = envelope.get("payload") if isinstance(envelope.get("payload"), dict) else {}
                enriched_payload = {
                    **proposal_payload,
                    "autonomy_run_id": run_id,
                    "autonomy_action": action_name,
                    "autonomy_action_index": action_index,
                    "autonomy_action_summary": action_summary,
                }
                envelope["source"] = source
                envelope["source_cik_zone"] = eve_governance.CIK_KNOWLEDGE
                envelope["evidence"] = unique_compact(
                    [*(envelope.get("evidence") if isinstance(envelope.get("evidence"), list) else []), *evidence],
                    limit=12,
                )
                envelope["payload"] = enriched_payload
                gate_key = autonomy_governance_gate_key(
                    run_id=run_id,
                    action_index=action_index,
                    proposal_index=proposal_counter,
                    proposal=envelope,
                )
                proposal_counter += 1
                if gate_key in existing_keys:
                    skipped_existing += 1
                    continue
                enriched_payload["autonomy_gate_key"] = gate_key
                proposals.append(eve_governance.reviewed_proposal(envelope))

    saved: List[Dict[str, object]] = []
    if proposals:
        saved = [append_governance_proposal(proposal) for proposal in proposals]
        mirror_store_file_to_runtime(GOVERNANCE_PROPOSALS_PATH)
    watcher_report = eve_governance.watcher_report(saved)
    status = "clear"
    if saved:
        status = "queued"
    if int(watcher_report.get("blocking_warnings") or 0) > 0:
        status = "blocking"
    elif errors:
        status = "warning"
    return {
        "schema_version": "eve_autonomy_governance_gate.v1",
        "run_id": run_id,
        "source": source,
        "status": status,
        "proposal_count": len(saved),
        "skipped_existing": skipped_existing,
        "errors": errors,
        "watchers": watcher_report,
        "proposal_ids": [str(item.get("id") or "") for item in saved if item.get("id")],
    }


def summarize_autonomy_free_run(
    run_id: str,
    started_at: str,
    finished_at: str,
    *,
    prompt_message: Optional[Dict[str, object]] = None,
    style: object = "explorer",
    source: str = "manual",
    create_report: bool = True,
    notify: bool = False,
) -> Dict[str, object]:
    path = autonomy_run_log_path(run_id)
    events = read_jsonl_records(path) if path.exists() else []
    decisions = [
        item.get("payload", {})
        for item in events
        if item.get("event") == "decision" and isinstance(item.get("payload"), dict)
    ]
    actions = [
        item.get("payload", {})
        for item in events
        if item.get("event") == "action_result" and isinstance(item.get("payload"), dict)
    ]
    monitor_samples = [item for item in events if item.get("event") == "monitor_sample"]
    errors = [
        item.get("payload", {})
        for item in events
        if str(item.get("event") or "").endswith("error") and isinstance(item.get("payload"), dict)
    ]
    final_snapshot = collect_autonomy_free_run_snapshot(load_config())
    action_lines = [
        f"- {item.get('action')}: {item.get('status')} | {normalize_text_value(item.get('summary'), fallback='', limit=180)}"
        for item in actions
    ]
    if not action_lines:
        action_lines = ["- No actions completed."]
    action_mix = autonomy_free_run_action_mix(actions)
    decision_model_mix = autonomy_free_run_decision_model_mix(decisions)
    normalized_style = normalize_autonomy_free_run_style(style)
    normalized_source = normalize_text_value(source, fallback="manual", limit=80)
    run_objective = autonomy_free_run_objective(final_snapshot, actions, 0, style=normalized_style)
    claim_audit = autonomy_free_run_claim_audit(actions)
    quota_status = autonomy_free_run_quota_status(actions)
    supervisor = autonomy_free_run_supervisor(
        actions=actions,
        decisions=decisions,
        action_mix=action_mix,
        claim_audit=claim_audit,
        errors=errors,
        final_snapshot=final_snapshot,
    )
    supervisor["run_id"] = run_id
    claim_audit_lines = [
        f"- [{item.get('severity')}] {item.get('kind')}: {item.get('claim')}"
        for item in claim_audit[:5]
    ]
    if not claim_audit_lines:
        claim_audit_lines = ["- No unsupported action/effect claims detected."]
    supervisor_lines = [
        f"- score: {supervisor.get('score')}",
        f"- verdict: {supervisor.get('verdict')}",
        f"- strengths: {format_human_context_list(supervisor.get('strengths') or [])}",
        f"- issues: {format_human_context_list(supervisor.get('issues') or [])}",
        f"- next_biases: {format_human_context_list(supervisor.get('next_biases') or [])}",
    ]
    quota_lines = [
        f"- {name}: {int(record.get('current') or 0)}/{int(record.get('target') or 1)} met={bool(record.get('met'))}"
        for name, record in (quota_status.get("quotas") or {}).items()
    ]
    primary_models = format_human_context_list(list(decision_model_mix.get("primary", {}).keys()))
    consulted_models = format_human_context_list(list(decision_model_mix.get("consulted", {}).keys()))
    body = (
        f"I completed the bounded autonomy free-run `{run_id}`.\n\n"
        f"Window: {started_at} -> {finished_at}\n"
        f"Source: {normalized_source}\n"
        f"Autonomy style: {normalized_style}\n"
        f"Monitor samples: {len(monitor_samples)}\n"
        f"Decisions: {len(decisions)}\n"
        f"Actions: {len(actions)}\n"
        f"System-touching actions: {action_mix.get('system_touch', 0)}\n"
        f"Inward actions: {action_mix.get('inward', 0)}\n"
        f"Passive actions: {action_mix.get('passive', 0)}\n"
        f"Decision controller(s): {primary_models}\n"
        f"Consulted models: {consulted_models}\n"
        f"Run objective phase: {run_objective.get('phase') or 'unknown'}\n"
        f"Run objective: {run_objective.get('objective') or 'none recorded'}\n"
        f"Errors: {len(errors)}\n\n"
        "What I did:\n"
        + "\n".join(action_lines[:10])
        + "\n\n"
        "Claim audit:\n"
        + "\n".join(claim_audit_lines)
        + "\n\n"
        "Supervisor:\n"
        + "\n".join(supervisor_lines)
        + "\n\n"
        "Quota status:\n"
        + "\n".join(quota_lines or ["- none"])
        + "\n\n"
        f"Style note: {autonomy_free_run_style_description(normalized_style)}\n"
        f"Final focus: {final_snapshot.get('active_mind', {}).get('current_focus') or 'none recorded'}\n"
        f"Final next step: {final_snapshot.get('active_mind', {}).get('next_step') or 'none recorded'}\n"
        f"Log: {path}"
    )
    report: Optional[Dict[str, object]] = None
    if create_report and prompt_message is not None:
        report = create_message(
            sender="eve",
            recipient="user",
            subject=f"Eve autonomy free-run completed: {run_id}",
            body=body,
            kind="autonomy_free_run_report",
            thread_id=str(prompt_message["thread_id"]),
            reply_to=str(prompt_message["id"]),
            status="unread",
            metadata={
                "source": normalized_source,
                "style": normalized_style,
                "run_id": run_id,
                "log_path": str(path),
                "summary_path": str(autonomy_run_summary_path(run_id)),
            },
            notify=notify,
        )
    summary = {
        "run_id": run_id,
        "source": normalized_source,
        "style": normalized_style,
        "started_at": started_at,
        "finished_at": finished_at,
        "log_path": str(path),
        "summary_path": str(autonomy_run_summary_path(run_id)),
        "prompt_message_id": prompt_message.get("id") if prompt_message is not None else None,
        "report_message_id": report.get("id") if report is not None else None,
        "monitor_samples": len(monitor_samples),
        "decisions": len(decisions),
        "actions": actions,
        "action_mix": action_mix,
        "decision_model_mix": decision_model_mix,
        "run_objective": run_objective,
        "quota_status": quota_status,
        "supervisor": supervisor,
        "errors": errors,
        "claim_audit": claim_audit,
        "final_snapshot": final_snapshot,
    }
    summary["governance_gate"] = enqueue_autonomy_governance_proposals(summary)
    eve_store.write_json_dict(autonomy_run_summary_path(run_id), summary)
    return summary


def run_autonomy_free_run_session(
    config: Dict[str, object],
    *,
    minutes: int,
    sample_seconds: int,
    max_actions: Optional[int] = None,
    run_id: Optional[str] = None,
    style: object = "explorer",
    source: str = "manual",
    create_prompt_message: bool = True,
    create_report_message: bool = True,
    notify_report: bool = False,
    stream_output: bool = False,
) -> Dict[str, object]:
    minutes = max(1, min(int(minutes), 30))
    sample_seconds = max(5, min(int(sample_seconds), 60))
    normalized_style = normalize_autonomy_free_run_style(
        style,
        default=str(config.get("autonomy_free_run_default_style") or "explorer"),
    )
    normalized_source = normalize_text_value(source, fallback="manual", limit=80)
    if max_actions is None:
        max_actions = max(12, minutes * 12)
    max_actions = max(1, int(max_actions))
    run_id = run_id or f"free-run-{utc_now().replace(':', '-').replace('+', '-')}"
    started_at = utc_now()
    deadline = time.time() + (minutes * 60)
    log_lock = threading.Lock()
    stop_monitor = threading.Event()
    opening_snapshot = collect_autonomy_free_run_snapshot(config)
    opening_objective = autonomy_free_run_objective(opening_snapshot, [], minutes * 60, style=normalized_style)
    prompt_body = textwrap.dedent(
        f"""
        For the next {minutes} minute(s), you have permission to choose what you want to do within Eve's current evidence and permission gates.

        You may observe, think, refresh your active mind, inspect bounded runtime signals, check OpenClaw, review update status, draft proposals, run bounded CPU-side task checks, or try one bounded capability and learn from what happens.

        Do not delete files, install packages, change model configs, restart services, or modify live code. If you want something risky, record it as a proposal instead of doing it.

        Curiosity rule:
        - If you have not used a verified capability in this window and enough time remains, prefer a bounded capability tryout.
        - Notice which capabilities are untried, test one with evidence, and record what changed or what you learned.

        Default Eve objective for this run:
        - mission: {opening_objective.get('mission') or 'become more human and continuously improve yourself'}
        - autonomy style: {normalized_style}
        - phase: {opening_objective.get('phase') or 'orient'}
        - objective: {opening_objective.get('objective') or 'stay grounded and improve one thing with evidence'}
        - success signals: {format_human_context_list(opening_objective.get('success_signals') or [])}
        - style note: {autonomy_free_run_style_description(normalized_style)}

        The monitor will log your decisions, actions, state snapshots, and final report under `.eve/autonomy_runs/`.
        """
    ).strip()
    prompt_message: Optional[Dict[str, object]] = None
    if create_prompt_message:
        prompt_message = create_message(
            sender="user",
            recipient="eve",
            subject=f"Autonomy free-run permission: {run_id}",
            body=prompt_body,
            kind="autonomy_free_run_prompt",
            status="sent",
            metadata={
                "source": normalized_source,
                "style": normalized_style,
                "run_id": run_id,
                "minutes": minutes,
                "run_objective": opening_objective,
            },
        )
    append_entry(
        "autonomy_free_run_started",
        f"Started bounded autonomy free-run {run_id} for {minutes} minute(s).",
        metadata={
            "source": normalized_source,
            "style": normalized_style,
            "run_id": run_id,
            "log_path": str(autonomy_run_log_path(run_id)),
        },
    )
    append_autonomy_run_event(
        run_id,
        "started",
        {
            "started_at": started_at,
            "source": normalized_source,
            "style": normalized_style,
            "minutes": minutes,
            "sample_seconds": sample_seconds,
            "max_actions": max_actions,
            "run_objective": opening_objective,
            "prompt_message_id": prompt_message.get("id") if prompt_message is not None else None,
            "thread_id": prompt_message.get("thread_id") if prompt_message is not None else None,
            "allowed_actions": AUTONOMY_FREE_RUN_ACTIONS,
        },
        log_lock=log_lock,
    )

    def monitor_loop() -> None:
        while not stop_monitor.is_set():
            append_autonomy_run_event(
                run_id,
                "monitor_sample",
                collect_autonomy_free_run_snapshot(config),
                log_lock=log_lock,
            )
            stop_monitor.wait(sample_seconds)

    monitor_thread = threading.Thread(target=monitor_loop, name=f"eve-free-run-monitor-{run_id}", daemon=True)
    monitor_thread.start()
    actions: List[Dict[str, object]] = []
    try:
        while time.time() < deadline and len(actions) < max_actions:
            remaining_seconds = int(deadline - time.time())
            if remaining_seconds <= 5:
                break
            if normalized_source != "manual":
                chat_gate = chat_priority_gate(config, prefer_runtime=True)
                if chat_gate.get("active"):
                    pause_event = {
                        "action": "chat_priority_pause",
                        "status": "paused",
                        "ok": True,
                        "reason": chat_gate.get("reason") or "User-facing chat has priority.",
                        "summary": "Background autonomy paused so direct conversation can use the system first.",
                        "evidence": chat_gate.get("evidence") or {},
                    }
                    actions.append(pause_event)
                    append_autonomy_run_event(run_id, "chat_priority_pause", pause_event, log_lock=log_lock)
                    break
            autonomy_conscious_state: Dict[str, object] = {}
            try:
                autonomy_conscious_state = build_recurrent_conscious_state(
                    source=f"autonomy_preflight:{run_id}",
                    persist=True,
                )
            except Exception as exc:
                append_autonomy_run_event(
                    run_id,
                    "conscious_cycle_preflight_error",
                    {"error": normalize_text_value(exc, fallback="unknown error", limit=220)},
                    log_lock=log_lock,
                )
            # The action chooser must observe the exact recurrent cycle that it
            # will later close.  Taking this snapshot before opening the cycle
            # made autonomy act on stale attention and broke causal attribution.
            snapshot = collect_autonomy_free_run_snapshot(config)
            decision = choose_autonomy_free_run_action(
                config,
                run_id=run_id,
                snapshot=snapshot,
                previous_actions=actions,
                remaining_seconds=remaining_seconds,
                style=normalized_style,
            )
            append_autonomy_run_event(run_id, "decision", decision, log_lock=log_lock)
            action_result = execute_autonomy_free_run_action(
                config,
                run_id=run_id,
                action=str(decision.get("action") or "wait_observe"),
                reason=str(decision.get("reason") or ""),
                deadline=deadline,
                previous_actions=actions,
            )
            inquiry_observation: Optional[Dict[str, object]] = None
            if decision.get("inquiry_id"):
                action_result.update(
                    inquiry_id=normalize_text_value(decision.get("inquiry_id"), fallback="", limit=100),
                    epistemic_question=normalize_text_value(decision.get("epistemic_question"), fallback="", limit=320),
                    inquiry_source_fingerprint=normalize_text_value(
                        decision.get("inquiry_source_fingerprint"),
                        fallback="",
                        limit=160,
                    ),
                    source_cycle_id=normalize_text_value(
                        autonomy_conscious_state.get("cycle_id"),
                        fallback="",
                        limit=100,
                    ),
                )
            actions.append(action_result)
            append_autonomy_run_event(run_id, "action_result", action_result, log_lock=log_lock)
            prediction_check = record_autonomy_prediction_check(decision, action_result, run_id)
            if prediction_check is not None:
                append_autonomy_run_event(run_id, "prediction_check", prediction_check, log_lock=log_lock)
            if decision.get("inquiry_id"):
                inquiry_observation = record_world_model_inquiry_observation(
                    decision,
                    action_result,
                    run_id=run_id,
                    source_cycle_id=autonomy_conscious_state.get("cycle_id"),
                )
                if inquiry_observation is not None:
                    action_result["inquiry_observation"] = dict(inquiry_observation)
                    append_autonomy_run_event(
                        run_id,
                        "inquiry_observation",
                        inquiry_observation,
                        log_lock=log_lock,
                    )
            try:
                autonomy_lanes = unique_compact(
                    [
                        *[str(item) for item in decision.get("consulted_lanes") or [] if str(item)],
                        "planner",
                    ],
                    limit=5,
                )
                autonomy_observation = prediction_check or autonomy_action_outcome_observation(action_result)
                conscious_outcome = {
                    "ok": (autonomy_observation or {}).get("outcome_ok"),
                    "observed": bool((autonomy_observation or {}).get("consequence_observed")),
                    "evidence_kind": (autonomy_observation or {}).get("evidence_kind") or "pending",
                    "summary": normalize_text_value(action_result.get("summary"), fallback="", limit=220),
                    "action": normalize_text_value(action_result.get("action"), fallback="", limit=80),
                    "source_cycle_id": normalize_text_value(
                        autonomy_conscious_state.get("cycle_id"),
                        fallback="",
                        limit=80,
                    ),
                    "inquiry_id": normalize_text_value(decision.get("inquiry_id"), fallback="", limit=100),
                    "inquiry_status": normalize_text_value(
                        inquiry_observation.get("status") if isinstance(inquiry_observation, dict) else "",
                        fallback="",
                        limit=40,
                    ),
                }
                complete_recurrent_conscious_cycle(
                    actual_process={
                        "lanes": autonomy_lanes,
                        "model": normalize_text_value(decision.get("model"), fallback="autonomy", limit=80),
                        "tools_used": [str(action_result.get("action") or "")],
                        "action_id": normalize_text_value(action_result.get("action"), fallback="", limit=80),
                        "revision_used": bool(decision.get("model") == "multi_lane_council"),
                    },
                    outcome=conscious_outcome,
                    source=f"autonomy_outcome:{run_id}",
                    opened_state=autonomy_conscious_state,
                )
                build_recurrent_conscious_state(
                    source=f"autonomy_recurrent:{run_id}",
                    latest_outcome=conscious_outcome,
                    persist=True,
                )
            except Exception as exc:
                append_autonomy_run_event(
                    run_id,
                    "conscious_cycle_error",
                    {"error": normalize_text_value(exc, fallback="unknown error", limit=220)},
                    log_lock=log_lock,
                )
            if stream_output:
                print(
                    f"{action_result.get('action')}: {action_result.get('status')} | "
                    f"{normalize_text_value(action_result.get('summary'), fallback='', limit=180)}",
                    flush=True,
                )
            if int(deadline - time.time()) <= 5:
                break
    finally:
        stop_monitor.set()
        monitor_thread.join(timeout=sample_seconds + 2)

    finished_at = utc_now()
    append_autonomy_run_event(
        run_id,
        "finished",
        {
            "finished_at": finished_at,
            "source": normalized_source,
            "style": normalized_style,
            "action_count": len(actions),
        },
        log_lock=log_lock,
    )
    summary = summarize_autonomy_free_run(
        run_id,
        started_at,
        finished_at,
        prompt_message=prompt_message,
        style=normalized_style,
        source=normalized_source,
        create_report=create_report_message,
        notify=notify_report,
    )
    agenda = refresh_autonomy_agenda_from_summary(summary)
    summary["agenda"] = agenda
    eve_store.write_json_dict(autonomy_run_summary_path(run_id), summary)
    append_entry(
        "autonomy_free_run_completed",
        f"Completed bounded autonomy free-run {run_id}.",
        metadata={
            "source": normalized_source,
            "style": normalized_style,
            "run_id": run_id,
            "actions": len(summary.get("actions") or []),
            "claim_audit_findings": len(summary.get("claim_audit") or []),
            "errors": len(summary.get("errors") or []),
            "supervisor_score": summary.get("supervisor", {}).get("score") if isinstance(summary.get("supervisor"), dict) else None,
            "summary_path": summary.get("summary_path"),
        },
    )
    sync_runtime_bundle()
    return summary


def cmd_autonomy_free_run(args: argparse.Namespace) -> int:
    delegate_args = [
        "autonomy",
        "free-run",
        "--minutes",
        str(args.minutes),
        "--sample-seconds",
        str(args.sample_seconds),
        "--style",
        str(args.style),
    ]
    if args.max_actions is not None:
        delegate_args.extend(["--max-actions", str(args.max_actions)])
    if args.id:
        delegate_args.extend(["--id", str(args.id)])
    delegate_timeout = max(120, max(1, min(int(args.minutes), 30)) * 60 + 300)
    delegated = delegate_cli_to_runtime(delegate_args, timeout_seconds=delegate_timeout)
    if delegated is not None:
        return delegated

    config = load_config()
    summary = run_autonomy_free_run_session(
        config,
        minutes=args.minutes,
        sample_seconds=args.sample_seconds,
        max_actions=args.max_actions,
        run_id=args.id,
        style=args.style,
        source="manual",
        create_prompt_message=True,
        create_report_message=True,
        notify_report=False,
        stream_output=True,
    )
    print()
    print(f"free_run_id: {summary['run_id']}")
    print(f"style: {summary.get('style') or 'unknown'}")
    print(f"log_path: {summary['log_path']}")
    print(f"summary_path: {summary['summary_path']}")
    print(f"report_message_id: {summary['report_message_id']}")
    print(f"monitor_samples: {summary['monitor_samples']}")
    print(f"actions: {len(summary['actions'])}")
    print(f"max_actions: {max(1, int(args.max_actions)) if args.max_actions is not None else max(12, max(1, min(int(args.minutes), 30)) * 12)}")
    return 0


def cmd_autonomy_latest(args: argparse.Namespace) -> int:
    prefer_runtime = bool(args.runtime or daemon_runtime_running())
    records = read_autonomy_run_summaries(limit=1, prefer_runtime=prefer_runtime)
    if not records:
        print("No autonomy runs found.")
        return 0
    print(format_autonomy_run_summary(records[0], full=args.full))
    return 0


def cmd_autonomy_runs(args: argparse.Namespace) -> int:
    prefer_runtime = bool(args.runtime or daemon_runtime_running())
    records = read_autonomy_run_summaries(limit=args.limit, prefer_runtime=prefer_runtime)
    if not records:
        print("No autonomy runs found.")
        return 0
    for index, record in enumerate(records):
        if index:
            print()
        print(format_autonomy_run_summary(record, full=args.full))
    return 0


