def cmd_experiment_update(args: argparse.Namespace) -> int:
    experiments = read_jsonl_records(EXPERIMENTS_PATH)
    index = find_record_index(experiments, args.id)
    experiment = dict(experiments[index])
    if args.status:
        experiment["status"] = args.status
    if args.outcome is not None:
        experiment["outcome"] = args.outcome
    if args.notes is not None:
        experiment["notes"] = args.notes
    experiment["updated_at"] = utc_now()
    experiments[index] = experiment
    write_jsonl_records(EXPERIMENTS_PATH, experiments)
    append_entry(
        "experiment_updated",
        f"{experiment['name']} -> {experiment['status']}",
        metadata={"experiment_id": experiment["id"], "status": experiment["status"]},
    )
    if args.outcome is not None:
        direction = args.direction or (
            "positive"
            if experiment["status"] == "completed"
            else "negative"
            if experiment["status"] == "abandoned"
            else "neutral"
        )
        create_outcome(
            target_kind="experiment",
            target_id=str(experiment["id"]),
            direction=direction,
            outcome="experiment_update",
            summary=args.outcome or f"Experiment updated with status {experiment['status']}.",
            evidence=experiment.get("notes") or "",
            source="manual",
        )
    print(f"Updated experiment {experiment['id']}")
    return 0


