def research_lab_command(
    argv: List[str],
    *,
    purpose: str,
    ok_returncodes: Optional[List[int]] = None,
    timeout_seconds: Optional[int] = None,
) -> Dict[str, object]:
    return {
        "argv": argv,
        "purpose": purpose,
        "ok_returncodes": ok_returncodes or [0],
        "timeout_seconds": timeout_seconds,
    }


