def research_lab_safe_filename(value: object) -> str:
    safe = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(value or "").strip()).strip("-")
    return safe[:120] or str(uuid.uuid4())


def research_lab_run_artifact_path(run_id: object) -> Path:
    return RESEARCH_LAB_RUNS_DIR / f"{research_lab_safe_filename(run_id)}.json"


def research_lab_autonomy_smoke_command(budget_minutes: int) -> Dict[str, object]:
    minutes = clamp_int(budget_minutes, 3, minimum=1, maximum=10)
    max_actions = max(1, min(4, minutes))
    return research_lab_command(
        [
            "autonomy",
            "free-run",
            "--minutes",
            str(minutes),
            "--sample-seconds",
            "20",
            "--max-actions",
            str(max_actions),
            "--style",
            "explorer",
        ],
        purpose="Let Eve try bounded explorer actions inside the lab budget.",
        ok_returncodes=[0],
        timeout_seconds=max(90, minutes * 90),
    )


def research_lab_plan_for_kind(kind: str, *, budget_minutes: int) -> Dict[str, object]:
    specs = research_lab_kind_specs()
    if kind not in specs:
        raise SystemExit(f"Unknown lab kind: {kind}")
    spec = dict(specs[kind])
    baseline = [dict(item) for item in spec.get("baseline_commands", []) if isinstance(item, dict)]
    actions = [dict(item) for item in spec.get("action_commands", []) if isinstance(item, dict)]
    after = [dict(item) for item in spec.get("after_commands", []) if isinstance(item, dict)]
    if kind == "autonomy_smoke":
        actions = [research_lab_autonomy_smoke_command(budget_minutes)]
    spec["baseline_commands"] = baseline
    spec["action_commands"] = actions
    spec["after_commands"] = after
    return spec


def research_lab_load_json_metric(path: Path, *, prefer_runtime: bool = False) -> Tuple[Dict[str, object], str]:
    read_path = resolve_store_read_path(path, prefer_runtime=prefer_runtime)
    payload = eve_store.load_json_dict(read_path, {})
    return payload, str(read_path)


def research_lab_whole_system_metric(*, prefer_runtime: bool = False) -> Dict[str, object]:
    record, path = read_whole_system_json_artifact(WHOLE_SYSTEM_LATEST_EVAL_PATH, prefer_runtime=prefer_runtime)
    score = safe_float(record.get("average_score"), 0.0) if record else 0.0
    issues = clamp_int(record.get("failing_check_count"), 999, minimum=0) if record else 999
    return {
        "metric": "whole_system",
        "status": record.get("status") or "missing",
        "score": round(score, 3),
        "issue_count": issues,
        "artifact": path,
        "details": {
            "check_count": record.get("check_count") or 0,
            "missing_component_counts": record.get("missing_component_counts") if isinstance(record.get("missing_component_counts"), dict) else {},
        },
    }


def research_lab_roadmap_metric(*, prefer_runtime: bool = False) -> Dict[str, object]:
    report = build_roadmap_eval_report(prefer_runtime=prefer_runtime)
    warnings = report.get("warnings") if isinstance(report.get("warnings"), list) else []
    backlog = report.get("backlog") if isinstance(report.get("backlog"), dict) else {}
    issue_count = len(warnings)
    score = max(0.0, 5.0 - min(5.0, float(issue_count)))
    return {
        "metric": "roadmap",
        "status": report.get("status") or "unknown",
        "score": round(score, 3),
        "issue_count": issue_count,
        "artifact": str(ROOT / "docs" / "MASTER_ROADMAP.md"),
        "details": {
            "warnings": warnings[:8],
            "backlog": backlog,
            "first_priority": report.get("recommended_first_priority") if isinstance(report.get("recommended_first_priority"), dict) else {},
        },
    }


def research_lab_capability_metric(*, prefer_runtime: bool = False) -> Dict[str, object]:
    matrix, path = research_lab_load_json_metric(CAPABILITY_MATRIX_PATH, prefer_runtime=prefer_runtime)
    summary = matrix.get("summary") if isinstance(matrix.get("summary"), dict) else {}
    active_gaps = [
        item
        for item in read_capability_gaps(limit=None, prefer_runtime=prefer_runtime)
        if capability_gap_is_active(item)
    ]
    total = clamp_int(summary.get("total"), 0, minimum=0)
    verified = clamp_int(summary.get("verified"), 0, minimum=0)
    callable_count = clamp_int(summary.get("callable"), 0, minimum=0)
    open_gaps = clamp_int(summary.get("open_gaps"), len(active_gaps), minimum=0)
    unverified_callable = max(0, callable_count - verified)
    issue_count = open_gaps + unverified_callable
    score = 0.0 if total <= 0 else max(0.0, min(5.0, 5.0 * (verified / max(1, total))))
    return {
        "metric": "capability",
        "status": "passed" if issue_count == 0 and total > 0 else "degraded",
        "score": round(score, 3),
        "issue_count": issue_count,
        "artifact": path,
        "details": {
            "total": total,
            "callable": callable_count,
            "verified": verified,
            "open_gaps": open_gaps,
            "unverified_callable": unverified_callable,
            "active_gap_count": len(active_gaps),
        },
    }


def research_lab_autonomy_metric(*, prefer_runtime: bool = False) -> Dict[str, object]:
    records = read_autonomy_run_summaries(limit=1, prefer_runtime=prefer_runtime)
    latest = records[0] if records else {}
    actions = latest.get("actions") if isinstance(latest.get("actions"), list) else []
    errors = latest.get("errors") if isinstance(latest.get("errors"), list) else []
    status = latest.get("status") or ("missing" if not latest else "unknown")
    issue_count = len(errors) + (0 if status in {"completed", "passed"} else 1)
    score = 5.0 if latest and issue_count == 0 else max(0.0, 4.0 - float(issue_count))
    return {
        "metric": "autonomy",
        "status": status,
        "score": round(score, 3),
        "issue_count": issue_count,
        "artifact": str(AUTONOMY_RUNS_DIR),
        "details": {
            "run_id": latest.get("run_id"),
            "style": latest.get("style"),
            "action_count": len(actions),
            "error_count": len(errors),
            "finished_at": latest.get("finished_at"),
        },
    }


def research_lab_metric_snapshot(metric: str, *, prefer_runtime: bool = False) -> Dict[str, object]:
    if metric == "whole_system":
        return research_lab_whole_system_metric(prefer_runtime=prefer_runtime)
    if metric == "roadmap":
        return research_lab_roadmap_metric(prefer_runtime=prefer_runtime)
    if metric == "capability":
        return research_lab_capability_metric(prefer_runtime=prefer_runtime)
    if metric == "autonomy":
        return research_lab_autonomy_metric(prefer_runtime=prefer_runtime)
    return {
        "metric": metric,
        "status": "unknown",
        "score": 0.0,
        "issue_count": 999,
        "artifact": "",
        "details": {},
    }


def research_lab_command_timeout(command_spec: Dict[str, object], remaining_seconds: float) -> int:
    explicit = command_spec.get("timeout_seconds")
    default_timeout = 180
    timeout = clamp_int(explicit, default_timeout, minimum=5, maximum=900)
    if remaining_seconds <= 0:
        return 0
    return max(5, min(timeout, int(remaining_seconds)))


def run_research_lab_command(command_spec: Dict[str, object], *, timeout: int) -> Dict[str, object]:
    raw_argv = command_spec.get("argv") if isinstance(command_spec.get("argv"), list) else []
    argv = [str(item) for item in raw_argv if str(item)]
    command = [sys.executable, str(ROOT / "eve.py"), *argv]
    started_monotonic = time.monotonic()
    started_at = utc_now()
    try:
        completed = subprocess.run(
            command,
            check=False,
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=str(ROOT),
        )
        returncode: Optional[int] = completed.returncode
        stdout = completed.stdout or ""
        stderr = completed.stderr or ""
        timed_out = False
    except subprocess.TimeoutExpired as exc:
        returncode = None
        stdout = exc.stdout or ""
        stderr = exc.stderr or ""
        timed_out = True
    duration_ms = int((time.monotonic() - started_monotonic) * 1000)
    ok_returncodes = [
        int(item)
        for item in (command_spec.get("ok_returncodes") if isinstance(command_spec.get("ok_returncodes"), list) else [0])
        if isinstance(item, int)
    ]
    ok = (not timed_out) and returncode in ok_returncodes
    return {
        "argv": argv,
        "command": " ".join(shlex.quote(str(part)) for part in command),
        "purpose": command_spec.get("purpose") or "",
        "started_at": started_at,
        "finished_at": utc_now(),
        "duration_ms": duration_ms,
        "timeout_seconds": timeout,
        "returncode": returncode,
        "ok": ok,
        "timed_out": timed_out,
        "stdout_tail": truncate_text(stdout.strip(), 1200),
        "stderr_tail": truncate_text(stderr.strip(), 1200),
    }


def run_research_lab_command_group(
    commands: List[Dict[str, object]],
    *,
    label: str,
    deadline: float,
) -> List[Dict[str, object]]:
    results: List[Dict[str, object]] = []
    for command_spec in commands:
        remaining = deadline - time.monotonic()
        timeout = research_lab_command_timeout(command_spec, remaining)
        if timeout <= 0:
            results.append(
                {
                    "argv": command_spec.get("argv") or [],
                    "purpose": command_spec.get("purpose") or "",
                    "phase": label,
                    "ok": False,
                    "timed_out": False,
                    "skipped": True,
                    "reason": "budget_exhausted",
                    "started_at": utc_now(),
                    "finished_at": utc_now(),
                }
            )
            continue
        result = run_research_lab_command(command_spec, timeout=timeout)
        result["phase"] = label
        results.append(result)
    return results


def research_lab_command_failures(commands: List[Dict[str, object]]) -> List[Dict[str, object]]:
    return [item for item in commands if not item.get("ok")]


def decide_research_lab_result(
    before: Dict[str, object],
    after: Dict[str, object],
    *,
    command_failures: List[Dict[str, object]],
    action_count: int,
) -> Dict[str, object]:
    before_score = safe_float(before.get("score"), 0.0)
    after_score = safe_float(after.get("score"), 0.0)
    before_issues = clamp_int(before.get("issue_count"), 999, minimum=0)
    after_issues = clamp_int(after.get("issue_count"), 999, minimum=0)
    score_delta = round(after_score - before_score, 3)
    issue_delta = before_issues - after_issues
    after_status = str(after.get("status") or "unknown")
    before_status = str(before.get("status") or "unknown")
    if command_failures:
        return {
            "decision": "blocked",
            "reason": f"{len(command_failures)} command(s) failed or timed out; do not promote this result.",
            "score_delta": score_delta,
            "issue_delta": issue_delta,
        }
    if after_status == "failed" and before_status != "failed":
        return {
            "decision": "discard",
            "reason": "After-state failed where before-state did not.",
            "score_delta": score_delta,
            "issue_delta": issue_delta,
        }
    if score_delta < -0.05 or issue_delta < 0:
        return {
            "decision": "discard",
            "reason": "Score regressed or issue count increased.",
            "score_delta": score_delta,
            "issue_delta": issue_delta,
        }
    if action_count <= 0:
        return {
            "decision": "observe",
            "reason": "Measurement-only run completed; no action was promoted.",
            "score_delta": score_delta,
            "issue_delta": issue_delta,
        }
    if score_delta > 0.05 or issue_delta > 0:
        return {
            "decision": "keep",
            "reason": "After-state improved without a detected regression.",
            "score_delta": score_delta,
            "issue_delta": issue_delta,
        }
    return {
        "decision": "watch",
        "reason": "No regression detected, but no measurable improvement yet.",
        "score_delta": score_delta,
        "issue_delta": issue_delta,
    }


def save_research_lab_record(record: Dict[str, object]) -> Dict[str, str]:
    ensure_store()
    RESEARCH_LAB_DIR.mkdir(parents=True, exist_ok=True)
    RESEARCH_LAB_RUNS_DIR.mkdir(parents=True, exist_ok=True)
    history_path = research_lab_run_artifact_path(record.get("id"))
    artifacts = {
        "latest": str(RESEARCH_LAB_LATEST_PATH),
        "history": str(history_path),
        "jsonl": str(RESEARCH_LAB_RESULTS_JSONL_PATH),
        "tsv": str(RESEARCH_LAB_RESULTS_TSV_PATH),
    }
    record["artifacts"] = artifacts
    eve_store.write_json_dict(RESEARCH_LAB_LATEST_PATH, record, indent=2, sort_keys=False)
    eve_store.write_json_dict(history_path, record, indent=2, sort_keys=False)
    append_jsonl_record(RESEARCH_LAB_RESULTS_JSONL_PATH, record)
    if not RESEARCH_LAB_RESULTS_TSV_PATH.exists() or not RESEARCH_LAB_RESULTS_TSV_PATH.read_text(encoding="utf-8").strip():
        eve_store.atomic_write_text(
            RESEARCH_LAB_RESULTS_TSV_PATH,
            "id\tfinished_at\tkind\tdecision\tbefore_score\tafter_score\tbefore_issues\tafter_issues\thypothesis\n",
        )
    with RESEARCH_LAB_RESULTS_TSV_PATH.open("a", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, delimiter="\t")
        writer.writerow(
            [
                record.get("id") or "",
                record.get("finished_at") or "",
                record.get("kind") or "",
                record.get("decision") or "",
                record.get("before", {}).get("score") if isinstance(record.get("before"), dict) else "",
                record.get("after", {}).get("score") if isinstance(record.get("after"), dict) else "",
                record.get("before", {}).get("issue_count") if isinstance(record.get("before"), dict) else "",
                record.get("after", {}).get("issue_count") if isinstance(record.get("after"), dict) else "",
                record.get("hypothesis") or "",
            ]
        )
    mirror_store_file_to_runtime(RESEARCH_LAB_LATEST_PATH)
    mirror_store_file_to_runtime(history_path)
    mirror_store_file_to_runtime(RESEARCH_LAB_RESULTS_JSONL_PATH)
    mirror_store_file_to_runtime(RESEARCH_LAB_RESULTS_TSV_PATH)
    return artifacts


def append_research_lab_experiment_record(record: Dict[str, object]) -> None:
    spec = record.get("spec") if isinstance(record.get("spec"), dict) else {}
    experiment = {
        "id": f"lab:{record.get('id')}",
        "created_at": record.get("started_at") or utc_now(),
        "updated_at": record.get("finished_at") or utc_now(),
        "name": f"Research lab: {spec.get('title') or record.get('kind')}",
        "hypothesis": record.get("hypothesis") or "",
        "action": "; ".join(
            " ".join(str(arg) for arg in (command.get("argv") or []))
            for command in (record.get("commands") if isinstance(record.get("commands"), list) else [])
            if isinstance(command, dict) and command.get("phase") == "action"
        )
        or "measurement-only run",
        "success_criteria": spec.get("success_criteria") or "",
        "duration_days": 0,
        "status": "completed" if record.get("decision") in {"keep", "watch", "observe"} else "blocked",
        "outcome": f"{record.get('decision')}: {record.get('decision_reason')}",
        "notes": f"artifact: {record.get('artifacts', {}).get('history') if isinstance(record.get('artifacts'), dict) else ''}",
        "source": "research_lab",
        "research_lab_run_id": record.get("id"),
    }
    append_jsonl_record(EXPERIMENTS_PATH, experiment)
    mirror_store_file_to_runtime(EXPERIMENTS_PATH)


def run_research_lab_experiment(
    *,
    kind: str,
    hypothesis: str,
    budget_minutes: int = 5,
    run_id: Optional[str] = None,
    prefer_runtime: bool = False,
) -> Dict[str, object]:
    ensure_store()
    bounded_budget_minutes = clamp_int(budget_minutes, 5, minimum=1, maximum=120)
    run_id = run_id or timestamp_filename("research_lab", suffix="").replace("+00-00", "Z")
    spec = research_lab_plan_for_kind(kind, budget_minutes=bounded_budget_minutes)
    metric = str(spec.get("metric") or "whole_system")
    started_at = utc_now()
    deadline = time.monotonic() + (bounded_budget_minutes * 60)
    command_records: List[Dict[str, object]] = []
    command_records.extend(
        run_research_lab_command_group(
            [item for item in spec.get("baseline_commands", []) if isinstance(item, dict)],
            label="baseline",
            deadline=deadline,
        )
    )
    before = research_lab_metric_snapshot(metric, prefer_runtime=prefer_runtime)
    action_commands = [item for item in spec.get("action_commands", []) if isinstance(item, dict)]
    command_records.extend(run_research_lab_command_group(action_commands, label="action", deadline=deadline))
    command_records.extend(
        run_research_lab_command_group(
            [item for item in spec.get("after_commands", []) if isinstance(item, dict)],
            label="after",
            deadline=deadline,
        )
    )
    after = research_lab_metric_snapshot(metric, prefer_runtime=prefer_runtime)
    failures = research_lab_command_failures(command_records)
    decision = decide_research_lab_result(before, after, command_failures=failures, action_count=len(action_commands))
    finished_at = utc_now()
    record = {
        "id": run_id,
        "schema_version": RESEARCH_LAB_SCHEMA_VERSION,
        "kind": kind,
        "title": spec.get("title") or kind,
        "hypothesis": normalize_text_value(hypothesis, fallback="", limit=500),
        "started_at": started_at,
        "finished_at": finished_at,
        "budget_minutes": bounded_budget_minutes,
        "metric": metric,
        "before": before,
        "after": after,
        "decision": decision.get("decision"),
        "decision_reason": decision.get("reason"),
        "score_delta": decision.get("score_delta"),
        "issue_delta": decision.get("issue_delta"),
        "status": "completed" if decision.get("decision") in {"keep", "watch", "observe"} else decision.get("decision"),
        "spec": {
            "title": spec.get("title"),
            "allowed_surfaces": spec.get("allowed_surfaces") if isinstance(spec.get("allowed_surfaces"), list) else [],
            "mutable_surfaces": spec.get("mutable_surfaces") if isinstance(spec.get("mutable_surfaces"), list) else [],
            "success_criteria": spec.get("success_criteria") or "",
        },
        "commands": command_records,
        "failure_count": len(failures),
        "artifacts": {},
    }
    record["artifacts"] = save_research_lab_record(record)
    append_research_lab_experiment_record(record)
    evidence = record_evidence(
        source="research_lab",
        kind="experiment_result",
        claim=f"Research lab run {run_id} completed with decision {record.get('decision')}.",
        summary=record.get("decision_reason") or "",
        confidence=0.8 if record.get("decision") in {"keep", "observe", "watch"} else 0.6,
        actionability="watch" if record.get("decision") in {"observe", "watch"} else "act",
        metadata={
            "run_id": run_id,
            "kind": kind,
            "metric": metric,
            "score_delta": record.get("score_delta"),
            "issue_delta": record.get("issue_delta"),
            "artifacts": record.get("artifacts"),
        },
    )
    record_experience_event(
        event_type="experiment",
        source="research_lab",
        summary=f"{spec.get('title') or kind}: {record.get('decision')} ({record.get('decision_reason')})",
        subject=kind,
        prediction=record.get("hypothesis") or "",
        result=record.get("decision") or "",
        learning=record.get("decision_reason") or "",
        evidence_ids=[str(evidence.get("id") or "")],
        metadata={"run_id": run_id, "artifacts": record.get("artifacts")},
    )
    return record


def read_research_lab_runs(limit: Optional[int] = 10, *, prefer_runtime: bool = False) -> List[Dict[str, object]]:
    path = resolve_store_read_path(RESEARCH_LAB_RESULTS_JSONL_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_records(path)
    return maybe_limit(records, limit)


def latest_research_lab_run(*, prefer_runtime: bool = False) -> Dict[str, object]:
    path = resolve_store_read_path(RESEARCH_LAB_LATEST_PATH, prefer_runtime=prefer_runtime)
    payload = eve_store.load_json_dict(path, {})
    if payload:
        return payload
    runs = read_research_lab_runs(limit=1, prefer_runtime=prefer_runtime)
    return runs[0] if runs else {}


def format_research_lab_record(record: Dict[str, object], *, full: bool = False) -> str:
    if not record:
        return "No research lab runs found."
    before = record.get("before") if isinstance(record.get("before"), dict) else {}
    after = record.get("after") if isinstance(record.get("after"), dict) else {}
    artifacts = record.get("artifacts") if isinstance(record.get("artifacts"), dict) else {}
    lines = [
        "Eve Research Lab",
        f"id: {record.get('id') or 'unknown'}",
        f"kind: {record.get('kind') or 'unknown'}",
        f"decision: {record.get('decision') or 'unknown'}",
        f"reason: {record.get('decision_reason') or 'unknown'}",
        f"metric: {record.get('metric') or 'unknown'}",
        f"before: {before.get('status') or 'unknown'} score={before.get('score')} issues={before.get('issue_count')}",
        f"after: {after.get('status') or 'unknown'} score={after.get('score')} issues={after.get('issue_count')}",
        f"delta: score={record.get('score_delta')} issues={record.get('issue_delta')}",
        f"artifact: {artifacts.get('history') or artifacts.get('latest') or RESEARCH_LAB_LATEST_PATH}",
    ]
    if record.get("hypothesis"):
        lines.append(f"hypothesis: {record.get('hypothesis')}")
    if full:
        spec = record.get("spec") if isinstance(record.get("spec"), dict) else {}
        if spec.get("allowed_surfaces"):
            lines.append("allowed_surfaces: " + ", ".join(str(item) for item in spec.get("allowed_surfaces", [])))
        if spec.get("mutable_surfaces"):
            lines.append("mutable_surfaces: " + ", ".join(str(item) for item in spec.get("mutable_surfaces", [])))
        commands = record.get("commands") if isinstance(record.get("commands"), list) else []
        if commands:
            lines.append("commands:")
            for command in commands:
                if not isinstance(command, dict):
                    continue
                status = "ok" if command.get("ok") else "failed"
                if command.get("skipped"):
                    status = "skipped"
                lines.append(
                    f"- {command.get('phase') or 'run'} [{status}] {' '.join(str(arg) for arg in (command.get('argv') or []))}"
                )
                if command.get("stderr_tail"):
                    lines.append(f"  stderr: {truncate_text(command.get('stderr_tail'), 180)}")
    return "\n".join(lines)


def format_research_lab_program() -> str:
    lines = [
        "Eve Research Lab Program",
        "rule: Every run needs a hypothesis, fixed budget, allowlisted command plan, before/after metric, and keep/watch/discard decision.",
        "boundary: Lab results may inform Eve; they do not silently change live routing, install providers, or become a sixth always-on lane.",
        "kinds:",
    ]
    for kind, spec in research_lab_kind_specs().items():
        lines.append(f"- {kind}: {spec.get('title')} | metric={spec.get('metric')}")
    lines.extend(
        [
            "commands:",
            "python3 eve.py lab run --kind whole_system_baseline --hypothesis \"Refresh the baseline\" --budget-minutes 5 --full",
            "python3 eve.py lab latest --full",
            "python3 eve.py lab list --limit 10 --full",
        ]
    )
    return "\n".join(lines)


def cmd_lab_program(_: argparse.Namespace) -> int:
    print(format_research_lab_program())
    return 0


def cmd_lab_run(args: argparse.Namespace) -> int:
    record = run_research_lab_experiment(
        kind=args.kind,
        hypothesis=args.hypothesis,
        budget_minutes=args.budget_minutes,
        run_id=args.id,
        prefer_runtime=bool(args.runtime),
    )
    if args.json:
        print(json.dumps(record, indent=2, ensure_ascii=True))
        return 0
    print(format_research_lab_record(record, full=args.full))
    return 0 if record.get("decision") in {"keep", "watch", "observe"} else 1


def cmd_lab_latest(args: argparse.Namespace) -> int:
    record = latest_research_lab_run(prefer_runtime=bool(args.runtime))
    if args.json:
        print(json.dumps(record, indent=2, ensure_ascii=True))
        return 0
    print(format_research_lab_record(record, full=args.full))
    return 0


def cmd_lab_list(args: argparse.Namespace) -> int:
    records = read_research_lab_runs(limit=args.limit, prefer_runtime=bool(args.runtime))
    if args.json:
        print(json.dumps(records, indent=2, ensure_ascii=True))
        return 0
    if not records:
        print("No research lab runs found.")
        return 0
    for index, record in enumerate(records):
        if index:
            print()
        print(format_research_lab_record(record, full=args.full))
    return 0


