def cmd_memory_query(args: argparse.Namespace) -> int:
    config = load_config()
    payload = query_memory_retrieval(
        config,
        args.query,
        limit=args.limit,
        prefer_runtime=True,
        force_refresh=args.force_refresh,
    )
    if not payload.get("ok"):
        raise SystemExit(str(payload.get("reason") or "Memory retrieval query failed."))
    matches = payload.get("matches") if isinstance(payload.get("matches"), list) else []
    print(f"query: {payload.get('query')}")
    print(f"model: {payload.get('model') or 'unknown'}")
    print(f"backend: {payload.get('backend') or 'unknown'}")
    print(f"query_mode: {payload.get('query_mode') or 'unknown'}")
    print(f"matches: {len(matches)}")
    print()
    if not matches:
        print("No relevant retrieved memory.")
        return 0
    for item in matches:
        print(f"[{item.get('score')}] {item.get('title') or item.get('source')}")
        print(f"source: {item.get('source')}")
        print(item.get("text") or "")
        print()
    return 0


def build_specialist_substrate_report(config: Dict[str, object], *, prefer_runtime: bool = True) -> Dict[str, object]:
    notes_payload = load_memory_retrieval_payload(MEMORY_RETRIEVAL_NOTES_PATH, prefer_runtime=prefer_runtime)
    index_payload = load_memory_retrieval_payload(MEMORY_RETRIEVAL_INDEX_PATH, prefer_runtime=prefer_runtime)
    coder_sessions = list_code_sessions(limit=3)
    latest_review_notes = read_review_notes(limit=3)
    latest_model_suitability = eve_store.load_json_dict(
        resolve_store_read_path(MODEL_SUITABILITY_LATEST_PATH, prefer_runtime=prefer_runtime),
        default={},
    )
    substrates: List[Dict[str, object]] = []
    for substrate_id in SPECIALIST_SUBSTRATE_ORDER:
        spec = dict(SPECIALIST_SUBSTRATE_REGISTRY[substrate_id])
        status = "planned"
        evidence: List[str] = []
        if substrate_id == "memory_retrieval_service":
            indexed_notes = int(index_payload.get("note_count") or 0)
            note_count = int(notes_payload.get("note_count") or 0)
            enabled = memory_retrieval_enabled(config)
            notes_hash = normalize_text_value(notes_payload.get("notes_hash"), fallback="", limit=120)
            indexed_hash = normalize_text_value(index_payload.get("notes_hash"), fallback="", limit=120)
            index_current = bool(enabled and indexed_notes and note_count and indexed_notes == note_count and (not notes_hash or not indexed_hash or notes_hash == indexed_hash))
            status = "healthy" if index_current else "partial" if enabled and indexed_notes else "planned"
            evidence = [
                f"enabled={'yes' if enabled else 'no'}",
                f"backend={memory_retrieval_backend(config)}",
                f"query_mode={memory_retrieval_query_mode(config)}",
                f"notes={note_count}",
                f"indexed_notes={indexed_notes}",
                f"index_current={'yes' if index_current else 'no'}",
            ]
        elif substrate_id == "beads_work_graph_substrate":
            beads_status = detect_beads_work_graph(prefer_runtime=prefer_runtime)
            status = str(beads_status.get("status") or "planned")
            evidence = [
                f"bridge_status={beads_status.get('bridge_status') or 'missing'}",
                f"bridge_current={'yes' if beads_status.get('bridge_current') else 'no'}",
                f"bridge_live_parity={'yes' if beads_status.get('bridge_live_parity') else 'no'}",
                f"projected_tasks={int(beads_status.get('projected_task_count') or 0)}",
                f"projected_edges={int(beads_status.get('projected_edge_count') or 0)}",
                f"installed={'yes' if beads_status.get('installed') else 'no'}",
                f"version={beads_status.get('version') or 'unknown'}",
                f"initialized={'yes' if beads_status.get('initialized') else 'no'}",
                f"total_issues={int(beads_status.get('total_issues') or 0)}",
                f"ready_issues={int(beads_status.get('ready_issues') or 0)}",
                f"blocked_issues={int(beads_status.get('blocked_issues') or 0)}",
                f"direct_state_write_allowed={'yes' if beads_status.get('direct_state_write_allowed') else 'no'}",
            ]
        elif substrate_id == "hermes_learning_organ":
            hermes_status = detect_hermes_learning_organ()
            latest_smoke = normalize_text_value(hermes_status.get("latest_smoke_status"), fallback="", limit=80)
            proposal_ready = (
                str(hermes_status.get("status") or "").startswith("available_proposal_only")
                and parse_boolish(hermes_status.get("soul_guardrail_ok"))
                and parse_boolish(hermes_status.get("model_endpoint_reachable"))
            )
            status = "healthy" if proposal_ready and latest_smoke.startswith("passed") else "partial" if proposal_ready else "planned"
            evidence = [
                f"installed={'yes' if hermes_status.get('version_ok') else 'no'}",
                f"version={hermes_status.get('version') or 'unknown'}",
                f"profile={hermes_status.get('profile') or 'missing'}",
                f"profile_exists={'yes' if hermes_status.get('profile_exists') else 'no'}",
                f"soul_guardrail={'yes' if hermes_status.get('soul_guardrail_ok') else 'no'}",
                f"skills={int(hermes_status.get('skills_count') or 0)}",
                f"model_context={hermes_status.get('model_context_length') or 'unknown'}",
                f"hermes_min_context={hermes_status.get('hermes_minimum_context_length') or 'unknown'}",
                f"model_endpoint_reachable={'yes' if hermes_status.get('model_endpoint_reachable') else 'no'}",
                f"latest_smoke={hermes_status.get('latest_smoke_status') or 'none'}",
                f"latest_smoke_model={hermes_status.get('latest_smoke_model') or 'unknown'}",
                f"direct_state_write_allowed={'yes' if hermes_status.get('direct_state_write_allowed') else 'no'}",
            ]
        elif substrate_id == "coding_self_repair_specialist":
            status = "healthy"
            evidence = [
                f"recent_coder_sessions={len(coder_sessions)}",
                "coder_mode=available",
                "openclaw_sidecar=available",
                "deployment_authority=no",
            ]
        elif substrate_id == "model_inference_acceleration_lab":
            acceleration_status = detect_model_inference_acceleration_lab(config, prefer_runtime=prefer_runtime)
            configured_lane_count = int(acceleration_status.get("configured_lane_count") or 0)
            status = "configured_lab_candidate" if configured_lane_count else "lab_available"
            configured_lanes = acceleration_status.get("configured_lanes") if isinstance(acceleration_status.get("configured_lanes"), list) else []
            lane_modes = [
                f"{item.get('profile')}:{item.get('mode')}"
                for item in configured_lanes
                if isinstance(item, dict) and item.get("profile")
            ]
            latest_lab = acceleration_status.get("latest_lab") if isinstance(acceleration_status.get("latest_lab"), dict) else {}
            evidence = [
                f"launcher_support={'yes' if acceleration_status.get('launcher_support') else 'no'}",
                f"configured_lanes={configured_lane_count}",
                f"lane_modes={', '.join(lane_modes) if lane_modes else 'none'}",
                f"official_gemma4_mtp_candidates={int(acceleration_status.get('official_candidate_count') or 0)}",
                f"latest_lab_status={latest_lab.get('status') or 'missing'}",
                f"latest_lab_mode={latest_lab.get('mode') or 'none'}",
                f"latest_transformers={latest_lab.get('transformers_target') or 'none'}+{latest_lab.get('transformers_assistant') or 'none'}",
                f"latest_transformers_device={latest_lab.get('transformers_device') or 'unknown'}",
                f"latest_llama={latest_lab.get('llama_status') or 'none'}/{latest_lab.get('llama_flavor') or 'none'}",
                f"latest_llama_trace={'mtp' if latest_lab.get('llama_trace_has_mtp') else 'missing'}",
                f"direct_lane_promotion_authority={'yes' if acceleration_status.get('direct_lane_promotion_authority') else 'no'}",
            ]
        elif substrate_id == "dagster_evidence_orchestration_lab":
            dagster_status = detect_dagster_evidence_orchestrator()
            status = str(dagster_status.get("status") or "research_candidate")
            evidence = [
                f"installed={'yes' if dagster_status.get('installed') else 'no'}",
                f"version={dagster_status.get('version') or 'unknown'}",
                f"selected_environment={dagster_status.get('selected_environment') or 'none'}",
                f"command_probe_ok={'yes' if dagster_status.get('command_probe_ok') else 'no'}",
                f"project_initialized={'yes' if dagster_status.get('project_initialized') else 'no'}",
                f"definition_validation_ok={'yes' if dagster_status.get('definition_validation_ok') else 'no'}",
                f"materialization_fresh={'yes' if dagster_status.get('materialization_fresh') else 'no'}",
                f"materialized_at={dagster_status.get('materialized_at') or 'never'}",
                f"lab_definition={dagster_status.get('lab_definition') or 'missing'}",
                f"direct_scheduler_authority={'yes' if dagster_status.get('direct_scheduler_authority') else 'no'}",
                f"direct_action_authority={'yes' if dagster_status.get('direct_action_authority') else 'no'}",
            ]
        elif substrate_id == "oss_improvement_substrate":
            oss_status = build_oss_integration_status_report(prefer_runtime=prefer_runtime)
            readiness = oss_status.get("readiness") if isinstance(oss_status.get("readiness"), dict) else {}
            status = str(oss_status.get("status") or "partial")
            evidence = [
                f"inventory={oss_status.get('inventory_status') or 'unknown'}",
                f"trace={oss_status.get('trace_status') or 'unknown'}",
                f"dataset={oss_status.get('training_dataset_status') or 'unknown'}",
                f"recipes={oss_status.get('trainer_recipe_status') or 'unknown'}",
                f"dvc_manifest={oss_status.get('dvc_manifest_status') or 'unknown'}",
                f"workflow={oss_status.get('workflow_status') or 'unknown'}",
                f"ready_checks={int(readiness.get('ready_checks') or 0)}/{int(readiness.get('total_checks') or 0)}",
                f"live_authority={'yes' if oss_status.get('grants_live_authority') else 'no'}",
            ]
        elif substrate_id == "frontier_api_lab":
            status = "lab_available" if latest_review_notes or latest_model_suitability else "planned"
            evidence = [
                f"recent_review_notes={len(latest_review_notes)}",
                f"latest_model_suitability={latest_model_suitability.get('verdict') or 'missing'}",
                "model_scout=available",
            ]
        elif substrate_id == "openclaw_body_action_nervous_system":
            openclaw_status = eve_openclaw.load_openclaw_status(prefer_runtime=prefer_runtime)
            contracts = eve_openclaw_body.openclaw_body_contracts()
            admissions = eve_openclaw_body.read_admission_records(limit=3, prefer_runtime=prefer_runtime)
            events = eve_openclaw_body.read_evidence_events(limit=3, prefer_runtime=prefer_runtime)
            gateway_ready = parse_boolish(openclaw_status.get("gateway_reachable"))
            gateway_probe = "cached"
            if not gateway_ready and parse_boolish(openclaw_status.get("installed")):
                try:
                    gateway_ready = eve_openclaw.gateway_reachable(int(openclaw_status.get("gateway_port") or 19011))
                    gateway_probe = "live"
                except (TypeError, ValueError, OSError):
                    gateway_probe = "failed"
            memory_available = parse_boolish(openclaw_status.get("memory_capability_available"))
            contract_count = len(contracts)
            status = "healthy" if gateway_ready and memory_available and contract_count else "partial" if gateway_ready and contract_count else "planned"
            evidence = [
                f"gateway_reachable={'yes' if gateway_ready else 'no'}",
                f"gateway_probe={gateway_probe}",
                f"memory_available={'yes' if memory_available else 'no'}",
                f"contracts={contract_count}",
                f"evidence_events={len(events)}",
                f"admissions={len(admissions)}",
            ]
        substrates.append(
            {
                "id": substrate_id,
                **spec,
                "status": status,
                "evidence": evidence,
            }
        )
    return {
        "generated_at": utc_now(),
        "principle": "Refine the five logical faculties; add tools and specialists only where the five cannot cover the function.",
        "resident_chat_lane_delta": 0,
        "substrates": substrates,
    }


def specialist_substrate_map(report: Dict[str, object]) -> Dict[str, Dict[str, object]]:
    return {
        str(item.get("id")): item
        for item in (report.get("substrates") if isinstance(report.get("substrates"), list) else [])
        if isinstance(item, dict) and item.get("id")
    }


def organ_status_pressure(status: object) -> int:
    normalized = normalize_text_value(status, fallback="unknown", limit=80).lower()
    operational = organ_operational_status(normalized)
    if operational in {"degraded", "blocked"}:
        return 88
    if operational == "not_configured":
        return 48
    if operational == "limited":
        return 58
    if operational in {"working", "lab_ready"}:
        return 38
    if operational == "ready":
        return 26
    return 42


def organ_signal_from_substrate(organ_id: str, substrate: Dict[str, object]) -> Dict[str, object]:
    spec = ORGAN_ASSIMILATION_REGISTRY.get(organ_id, {})
    status = normalize_text_value(substrate.get("status"), fallback="planned", limit=80).lower()
    summary = normalize_text_value(
        substrate.get("purpose"),
        fallback=spec.get("role") or f"{organ_id} is tracked as an Eve organ.",
        limit=260,
    )
    return normalize_organ_signal(
        {
            "id": organ_id,
            "label": spec.get("label") or substrate.get("label"),
            "status": status,
            "salience": 64 if status in {"degraded", "blocked"} else 46 if status != "healthy" else 28,
            "pressure": organ_status_pressure(status),
            "role": spec.get("role") or substrate.get("purpose"),
            "human_quality": spec.get("human_quality"),
            "summary": summary,
            "evidence": substrate.get("evidence") if isinstance(substrate.get("evidence"), list) else [],
            "next_step": substrate.get("next_maturation") or "",
            "authority_boundary": spec.get("authority_boundary") or substrate.get("guardrail") or "",
            "cik_zone": spec.get("cik_zone") or eve_governance.CIK_UNKNOWN,
            "source": "specialist_substrate_report",
            "last_updated": utc_now(),
        }
    ) or {}


def model_lane_organ_signal(config: Dict[str, object], *, prefer_runtime: bool = True) -> Dict[str, object]:
    watchdog = load_model_watchdog_status(prefer_runtime=prefer_runtime)
    lanes = model_lane_records(config, watchdog_status=watchdog)
    watchdog_age_minutes = minutes_since_timestamp(watchdog.get("updated_at") or watchdog.get("timestamp"))
    watchdog_max_age_minutes = max(
        15.0,
        (clamp_int(config.get("model_watchdog_interval_seconds"), 300, minimum=60, maximum=3600) * 3) / 60.0,
    )
    watchdog_fresh = bool(
        watchdog
        and watchdog_age_minutes is not None
        and watchdog_age_minutes <= watchdog_max_age_minutes
    )
    loaded_count = len([item for item in lanes if item.get("loaded")]) if watchdog_fresh else 0
    probe_ok_count = len([item for item in lanes if item.get("probe_ok")]) if watchdog_fresh else 0
    lane_count = len(lanes)
    topology = eve_model_topology.topology_snapshot(config)
    substrate_count = int(topology.get("substrate_count") or 0)
    topology_mode = str(topology.get("mode") or MODEL_LANE_TOPOLOGY_FIVE_ENDPOINT)
    if not watchdog_fresh:
        status = "degraded"
    elif lane_count >= 5 and loaded_count >= 5 and probe_ok_count >= 5:
        status = "healthy"
    elif lane_count >= 5 and loaded_count:
        status = "partial"
    elif lane_count:
        status = "planned"
    else:
        status = "degraded"
    spec = ORGAN_ASSIMILATION_REGISTRY["five_model_lanes"]
    evidence = [
        f"lanes={lane_count}",
        f"loaded={loaded_count}",
        f"probe_ok={probe_ok_count}",
        f"watchdog_fresh={'yes' if watchdog_fresh else 'no'}",
        f"topology={topology_mode}; resident_substrates={substrate_count}; watchdog_age_minutes={round(watchdog_age_minutes, 1) if watchdog_age_minutes is not None else 'unknown'}",
    ]
    return normalize_organ_signal(
        {
            "id": "five_model_lanes",
            "label": spec["label"],
            "status": status,
            "salience": 70 if status in {"degraded", "blocked"} else 52 if status == "partial" else 30,
            "pressure": organ_status_pressure(status),
            "role": spec["role"],
            "human_quality": spec["human_quality"],
            "summary": (
                f"Model-watchdog evidence is stale ({round(watchdog_age_minutes, 1) if watchdog_age_minutes is not None else 'unknown'} minutes old); "
                "cached residency and probe success are not current live evidence."
                if not watchdog_fresh
                else f"{loaded_count}/{max(lane_count, 5)} logical lane contracts have resident backing across {substrate_count} process substrate(s); {probe_ok_count}/{max(lane_count, 5)} logical routes have current healthy probes."
            ),
            "evidence": evidence,
            "next_step": "Run `python3 eve.py doctor` or the weekly lane-specific scout if a logical lane lacks resident substrate backing or a current probe.",
            "authority_boundary": spec["authority_boundary"],
            "cik_zone": spec["cik_zone"],
            "source": "model_watchdog_status",
            "last_updated": watchdog.get("updated_at") or utc_now(),
        }
    ) or {}


def watcher_organ_signal(*, prefer_runtime: bool = True) -> Dict[str, object]:
    report = governance_watcher_report(limit=40, prefer_runtime=prefer_runtime, include_events=True)
    total = int(report.get("total_warnings") or 0)
    blocking = int(report.get("blocking_warnings") or 0)
    status = "blocked" if blocking else "healthy"
    spec = ORGAN_ASSIMILATION_REGISTRY["watchers_immune_layer"]
    return normalize_organ_signal(
        {
            "id": "watchers_immune_layer",
            "label": spec["label"],
            "status": status,
            "salience": 72 if blocking else 34 if total else 24,
            "pressure": 88 if blocking else 34 if total else 24,
            "role": spec["role"],
            "human_quality": spec["human_quality"],
            "summary": f"Governance watchers report {total} warning(s), including {blocking} blocking warning(s).",
            "evidence": [
                f"status={report.get('status') or 'unknown'}",
                f"warnings={total}",
                f"blocking={blocking}",
            ],
            "next_step": "Resolve blocking watcher warnings before accepting new organ authority." if blocking else "Keep watcher review in the promotion path.",
            "authority_boundary": spec["authority_boundary"],
            "cik_zone": spec["cik_zone"],
            "source": "governance_watcher_report",
            "last_updated": report.get("generated_at") or utc_now(),
        }
    ) or {}


def build_organ_assimilation_report(
    config: Dict[str, object],
    *,
    prefer_runtime: bool = True,
) -> Dict[str, object]:
    specialist_report = build_specialist_substrate_report(config, prefer_runtime=prefer_runtime)
    substrate_by_id = specialist_substrate_map(specialist_report)
    signals: List[Dict[str, object]] = []
    for organ_id in ORGAN_ASSIMILATION_ORDER:
        if organ_id == "five_model_lanes":
            signals.append(model_lane_organ_signal(config, prefer_runtime=prefer_runtime))
            continue
        if organ_id == "codex_mutation_organ":
            signals.append(organ_signal_from_substrate(organ_id, substrate_by_id.get("coding_self_repair_specialist", {})))
            continue
        if organ_id == "watchers_immune_layer":
            signals.append(watcher_organ_signal(prefer_runtime=prefer_runtime))
            continue
        signals.append(organ_signal_from_substrate(organ_id, substrate_by_id.get(organ_id, {})))
    normalized_signals = normalize_organ_signals([item for item in signals if item], limit=len(ORGAN_ASSIMILATION_ORDER))
    capability_intelligence = load_capability_intelligence(prefer_runtime=prefer_runtime)
    capability_generated_at = normalize_text_value(
        capability_intelligence.get("generated_at"),
        fallback="",
        limit=80,
    )
    capability_opportunities = [
        item
        for item in capability_intelligence.get("opportunities", [])
        if isinstance(item, dict)
    ]
    capability_feature_summary = (
        capability_intelligence.get("feature_review_summary")
        if isinstance(capability_intelligence.get("feature_review_summary"), dict)
        else {}
    )
    opportunity_by_subsystem: Dict[str, List[Dict[str, object]]] = {}
    for item in capability_opportunities:
        subsystem = normalize_text_value(item.get("subsystem"), fallback="eve", limit=40)
        opportunity_by_subsystem.setdefault(subsystem, []).append(item)
    subsystem_for_organ = {
        "openclaw_body_action_nervous_system": "openclaw",
        "hermes_learning_organ": "hermes",
        "watchers_immune_layer": "eve",
    }
    if capability_generated_at:
        for signal in normalized_signals:
            organ_id = str(signal.get("id") or "")
            subsystem = subsystem_for_organ.get(organ_id)
            if not subsystem:
                continue
            subsystem_opportunities = opportunity_by_subsystem.get(subsystem, [])
            evidence = normalize_text_list(signal.get("evidence"), limit=20)
            evidence.append(f"capability_intelligence_checked_at={capability_generated_at}")
            evidence.append(f"capability_opportunities={len(subsystem_opportunities)}")
            signal["evidence"] = unique_compact(evidence, limit=20)
            signal["capability_intelligence"] = {
                "checked_at": capability_generated_at,
                "opportunity_ids": [str(item.get("id")) for item in subsystem_opportunities[:12]],
                "critical_count": sum(1 for item in subsystem_opportunities if item.get("priority") == "critical"),
            }
    readiness_counts: Dict[str, int] = {}
    blocking_organs: List[str] = []
    nonconfigured_lab_organs: List[str] = []
    for signal in normalized_signals:
        operational = normalize_text_value(signal.get("operational_status"), fallback="unknown", limit=80)
        readiness_counts[operational] = readiness_counts.get(operational, 0) + 1
        if operational in {"blocked", "degraded"}:
            blocking_organs.append(str(signal.get("id") or "unknown"))
        if operational == "not_configured":
            nonconfigured_lab_organs.append(str(signal.get("id") or "unknown"))
    return {
        "schema_id": "eve_organ_assimilation_report.v1",
        "generated_at": utc_now(),
        "principle": "Eve is the continuity layer; organs learn, act, propose, accelerate, track, review, and constrain through Eve-owned contracts.",
        "resident_chat_lane_delta": 0,
        "organs": normalized_signals,
        "readiness": {
            "counts": readiness_counts,
            "blocking_organs": blocking_organs,
            "nonconfigured_lab_organs": nonconfigured_lab_organs,
            "working_now": not blocking_organs,
            "lab_organs_configured": len(nonconfigured_lab_organs) == 0,
        },
        "event_types": ["OrganPulseEvent"],
        "active_mind_field": "organ_signals",
        "pulse_ledger": str(ORGAN_PULSES_PATH),
        "event_ledger": str(EVENT_LEDGER_PATH),
        "capability_intelligence": {
            "generated_at": capability_generated_at or None,
            "summary": capability_intelligence.get("summary") or "No capability-intelligence check has run yet.",
            "opportunity_count": len(capability_opportunities),
            "critical_count": sum(1 for item in capability_opportunities if item.get("priority") == "critical"),
            "feature_review_counts": capability_feature_summary.get("state_counts") or {},
            "adoption_candidate_ids": capability_feature_summary.get("candidate_ids") or [],
            "configuration_attention_ids": [
                str(item.get("subsystem"))
                for item in capability_intelligence.get("configuration_reviews", [])
                if isinstance(item, dict) and item.get("posture") == "attention"
            ],
            "artifact": str(resolve_store_read_path(CAPABILITY_INTELLIGENCE_PATH, prefer_runtime=prefer_runtime)),
            "briefing": str(resolve_store_read_path(CAPABILITY_INTELLIGENCE_REPORT_PATH, prefer_runtime=prefer_runtime)),
        },
        "specialist_substrate_report": specialist_report,
    }


def organ_pulse_event(record: Dict[str, object], *, source: str = "organs_pulse") -> Dict[str, object]:
    organ_ids = [str(item.get("id") or "") for item in record.get("organs", []) if isinstance(item, dict)]
    max_pressure = max([int(item.get("pressure") or 0) for item in record.get("organs", []) if isinstance(item, dict)] or [0])
    return eve_governance.event_envelope(
        "OrganPulseEvent",
        source=source,
        actor="eve",
        payload={
            "schema_id": record.get("schema_id"),
            "generated_at": record.get("generated_at"),
            "organ_ids": organ_ids,
            "organ_count": len(organ_ids),
            "max_pressure": max_pressure,
            "resident_chat_lane_delta": record.get("resident_chat_lane_delta"),
            "organs": [
                {
                    "id": item.get("id"),
                    "status": item.get("status"),
                    "operational_status": item.get("operational_status"),
                    "pressure": item.get("pressure"),
                    "summary": item.get("summary"),
                }
                for item in record.get("organs", [])
                if isinstance(item, dict)
            ],
        },
        input_value=record,
        output_value=record,
        risk_level=0,
        permissions_used=[],
        human_visible=True,
        confidence=0.9,
        provenance=[f"organ_pulses:{record.get('generated_at') or utc_now()}"],
        cik_zone=eve_governance.CIK_CAPABILITY,
        stream="organs",
        review_status="recorded",
    )


def append_organ_pulse_record(
    record: Dict[str, object],
    *,
    source: str = "organs_pulse",
    record_event: bool = True,
    event_ledger_enabled: bool = True,
) -> Dict[str, object]:
    saved = append_jsonl_record(ORGAN_PULSES_PATH, record)
    mirror_store_file_to_runtime(ORGAN_PULSES_PATH)
    if record_event and event_ledger_enabled:
        append_event_ledger_event_if_payload_fresh(
            organ_pulse_event(saved, source=source),
            saved,
            event_type="OrganPulseEvent",
            source=source,
        )
    return saved


def read_organ_pulses(
    *,
    limit: Optional[int] = 10,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(ORGAN_PULSES_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_tail_records(path, max(1, int(limit or 10))) if limit is not None else read_jsonl_records(path)
    return [item for item in records if isinstance(item, dict)]


def organ_operational_ok(signal: Dict[str, object]) -> bool:
    operational = normalize_text_value(signal.get("operational_status"), fallback="", limit=80).lower()
    return operational in {"ready", "working", "lab_ready"}


def organ_signal_by_id(report: Dict[str, object]) -> Dict[str, Dict[str, object]]:
    return {
        str(item.get("id") or ""): item
        for item in (report.get("organs") if isinstance(report.get("organs"), list) else [])
        if isinstance(item, dict) and item.get("id")
    }


def organ_embodiment_score(report: Dict[str, object]) -> int:
    signals = report.get("organs") if isinstance(report.get("organs"), list) else []
    if not signals:
        return 1
    by_id = organ_signal_by_id(report)
    hits = sum(
        [
            bool(report.get("readiness", {}).get("working_now")) if isinstance(report.get("readiness"), dict) else False,
            organ_operational_ok(by_id.get("five_model_lanes", {})),
            organ_operational_ok(by_id.get("openclaw_body_action_nervous_system", {})),
            organ_operational_ok(by_id.get("memory_retrieval_service", {})),
            organ_operational_ok(by_id.get("hermes_learning_organ", {})),
            organ_operational_ok(by_id.get("watchers_immune_layer", {})),
            sum(1 for item in signals if isinstance(item, dict) and organ_operational_ok(item)) >= 8,
        ]
    )
    return consciousness_score_presence(hits, 7)


def presence_action_organ_id(action: str) -> str:
    action = normalize_text_value(action, fallback="", limit=80).lower()
    if action.startswith("openclaw_"):
        return "openclaw_body_action_nervous_system"
    if action in {"agent_capability_scout", "agent_capability_integration"}:
        return "hermes_learning_organ"
    if action in {"cleanup_candidate_check", "service_health_check", "system_tasks", "updates_status"}:
        return "watchers_immune_layer"
    return "codex_mutation_organ"


def presence_action_verification_signal(action: str) -> str:
    action = normalize_text_value(action, fallback="", limit=80).lower()
    signals = {
        "system_tasks": "bounded task refresh with explicit created/completed/maintenance counts",
        "service_health_check": "typed service-health result with ok/execution_verification_ok evidence",
        "cleanup_candidate_check": "cleanup-candidate scan with urgency and approval-required candidates recorded",
        "openclaw_log_check": "fresh OpenClaw log-check action execution with result summary",
        "openclaw_sync_check": "OpenClaw sync action execution plus context artifact result",
        "agent_capability_scout": "capability scout record with candidate/evidence counts",
        "agent_capability_integration": "integration-task result for known capability-scout signals",
        "updates_status": "current component-update ledger result with a counted update signal set",
    }
    return signals.get(action, "bounded action result with ok/execution_verification_ok evidence")


def build_presence_action_contract(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    workspace: Dict[str, object],
    homeostasis: Dict[str, object],
    organ_report: Dict[str, object],
    current_focus: str = "",
    prefer_runtime: bool = True,
    state_authority_side: str = "",
    conscious_state: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    fallback_action = "service_health_check"
    try:
        component_state = load_component_update_state(prefer_runtime=prefer_runtime)
        recent_actions = read_action_executions(limit=8, prefer_runtime=prefer_runtime)
        recent_cycles = read_developmental_cycles(limit=8, prefer_runtime=prefer_runtime)
        selection = select_developmental_cycle_action(
            config,
            state,
            workspace=workspace,
            homeostasis=homeostasis,
            component_state=component_state,
            recent_actions=recent_actions,
            recent_cycles=recent_cycles,
            conscious_state=conscious_state,
        )
    except Exception as exc:  # pragma: no cover - defensive runtime shield
        selection = {
            "action": fallback_action,
            "capability": f"operational_action_tree.{fallback_action}",
            "choice": "Selector unavailable; use the least risky live health check.",
            "care": "I care about preserving grounded presence even when the chooser needs repair.",
            "next_test": "Repair the presence action selector, then re-run presence status and cycle.",
            "selector_error": normalize_text_value(exc, fallback="unknown selector error", limit=220),
        }

    action = normalize_text_value(selection.get("action"), fallback=fallback_action, limit=80)
    capability = normalize_text_value(selection.get("capability"), fallback=f"operational_action_tree.{action}", limit=140)
    organ_id = presence_action_organ_id(action)
    organs = organ_signal_by_id(organ_report)
    organ_signal = organs.get(organ_id, {})
    dominant_pressure = ""
    pressures = normalize_text_list(homeostasis.get("dominant_pressures"), limit=5)
    if pressures:
        dominant_pressure = pressures[0]
    return {
        "schema_id": "eve_presence_action_contract.v1",
        "state_authority_side": normalize_text_value(
            state_authority_side or presence_state_authority_side(prefer_runtime),
            fallback="source",
            limit=40,
        ),
        "focus": normalize_text_value(current_focus or workspace.get("summary") or state.get("active_thread"), fallback="", limit=180),
        "dominant_pressure": dominant_pressure,
        "bounded_action": action,
        "capability": capability,
        "selection_source": normalize_text_value(
            selection.get("selection_source"),
            fallback="developmental_rotation",
            limit=80,
        ),
        "conscious_cycle_id": normalize_text_value(
            selection.get("conscious_cycle_id"),
            fallback="",
            limit=80,
        ),
        "conscious_action_aligned": bool(
            selection.get("selection_source") == "recurrent_conscious_state"
        ),
        "conscious_broadcast": normalize_text_value(
            selection.get("conscious_broadcast"),
            fallback="",
            limit=240,
        ),
        "organ_id": organ_id,
        "organ_status": organ_signal.get("operational_status") or organ_signal.get("status") or "unknown",
        "why_this_action": normalize_text_value(selection.get("choice"), fallback="", limit=260),
        "care": normalize_text_value(selection.get("care"), fallback="", limit=220),
        "expected_verification_signal": presence_action_verification_signal(action),
        "fallback_if_unsupported": "Do not claim the action ran; record needs_repair and create or reuse a repair task.",
        "next_test": normalize_text_value(selection.get("next_test"), fallback="", limit=220),
        **({"selector_error": selection.get("selector_error")} if selection.get("selector_error") else {}),
    }


def presence_cli_prefers_runtime(args: argparse.Namespace) -> bool:
    return bool(getattr(args, "runtime", False) or running_from_runtime_bundle() or daemon_runtime_running())


def presence_state_authority_side(prefer_runtime: bool) -> str:
    if running_from_runtime_bundle():
        return "runtime"
    if prefer_runtime:
        return "runtime" if daemon_runtime_running() else "runtime-preferred"
    return "source"


def latest_consciousness_test_record(*, prefer_runtime: bool = False) -> Tuple[Dict[str, object], str]:
    return read_whole_system_json_artifact(APP_DIR / "capability_tests" / "latest_consciousness_test.json", prefer_runtime=prefer_runtime)


def presence_runtime_liveness(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    daemon_running: Optional[bool] = None,
    prefer_runtime: bool = True,
) -> Dict[str, object]:
    running = daemon_runtime_running() if daemon_running is None else bool(daemon_running)
    last_loop_at = normalize_text_value(state.get("last_loop_at"), fallback="", limit=60)
    last_loop_age_minutes = minutes_since_timestamp(last_loop_at)
    max_age_seconds = max(
        180,
        clamp_int(config.get("loop_sleep_seconds"), 60, minimum=1, maximum=3600) * 4,
    )
    loop_fresh = bool(
        running
        and last_loop_age_minutes is not None
        and last_loop_age_minutes * 60.0 <= max_age_seconds
    )
    activity = load_daemon_activity(prefer_runtime=prefer_runtime)
    activity_status = normalize_text_value(activity.get("status"), fallback="", limit=30)
    activity_heartbeat_at = normalize_text_value(activity.get("last_heartbeat_at"), fallback="", limit=60)
    activity_started_at = normalize_text_value(activity.get("cycle_started_at"), fallback="", limit=60)
    activity_heartbeat_age_minutes = minutes_since_timestamp(activity_heartbeat_at)
    activity_cycle_age_minutes = minutes_since_timestamp(activity_started_at)
    heartbeat_interval_seconds = clamp_int(
        activity.get("heartbeat_interval_seconds") or config.get("daemon_activity_heartbeat_seconds"),
        15,
        minimum=5,
        maximum=60,
    )
    heartbeat_max_age_seconds = max(60, heartbeat_interval_seconds * 3)
    max_active_cycle_seconds = clamp_int(
        activity.get("max_active_cycle_seconds") or config.get("daemon_max_active_cycle_seconds"),
        900,
        minimum=180,
        maximum=3600,
    )
    expected_pid = int(state.get("daemon_process_id") or 0)
    activity_pid = int(activity.get("pid") or 0)
    activity_pid_matches = not expected_pid or activity_pid == expected_pid
    activity_live = bool(
        running
        and activity_status == "active"
        and activity_pid_matches
        and activity_heartbeat_age_minutes is not None
        and activity_heartbeat_age_minutes * 60.0 <= heartbeat_max_age_seconds
        and activity_cycle_age_minutes is not None
        and activity_cycle_age_minutes * 60.0 <= max_active_cycle_seconds
    )
    live = bool(loop_fresh or activity_live)
    if not running:
        status = "dormant"
        reason = "The Eve daemon process is not running."
    elif activity_live and not loop_fresh:
        status = "active"
        reason = (
            "The Eve daemon is inside a bounded recurrent cycle and its activity heartbeat is fresh "
            f"({round(activity_cycle_age_minutes or 0.0, 1)} minutes into a maximum "
            f"{round(max_active_cycle_seconds / 60.0, 1)}-minute cycle)."
        )
    elif not last_loop_at:
        status = "starting"
        reason = "The Eve daemon is running but has not recorded a completed loop yet."
    elif not loop_fresh:
        status = "stale"
        reason = (
            f"The Eve daemon process exists, but its last loop is {round(last_loop_age_minutes or 0.0, 1)} minutes old "
            f"(maximum {round(max_age_seconds / 60.0, 1)})."
        )
    else:
        status = "live"
        reason = "The Eve daemon is running and its recurrent loop is fresh."
    return {
        "status": status,
        "live": live,
        "active": activity_live,
        "daemon_running": running,
        "last_loop_at": last_loop_at,
        "last_loop_age_minutes": round(last_loop_age_minutes, 2) if last_loop_age_minutes is not None else None,
        "max_loop_age_seconds": max_age_seconds,
        "activity": {
            "status": activity_status or "missing",
            "cycle_id": normalize_text_value(activity.get("cycle_id"), fallback="", limit=80),
            "pid": activity_pid,
            "pid_matches": activity_pid_matches,
            "cycle_started_at": activity_started_at,
            "cycle_age_minutes": round(activity_cycle_age_minutes, 2) if activity_cycle_age_minutes is not None else None,
            "last_heartbeat_at": activity_heartbeat_at,
            "heartbeat_age_minutes": round(activity_heartbeat_age_minutes, 2) if activity_heartbeat_age_minutes is not None else None,
            "heartbeat_max_age_seconds": heartbeat_max_age_seconds,
            "max_active_cycle_seconds": max_active_cycle_seconds,
            "heartbeat_count": int(activity.get("heartbeat_count") or 0),
        },
        "reason": reason,
    }


def build_presence_report(
    config: Dict[str, object],
    *,
    prefer_runtime: bool = True,
) -> Dict[str, object]:
    authority_side = presence_state_authority_side(prefer_runtime)
    organ_report = build_organ_assimilation_report(config, prefer_runtime=prefer_runtime)
    consciousness, consciousness_path = latest_consciousness_test_record(prefer_runtime=prefer_runtime)
    workspace = load_global_workspace(prefer_runtime=prefer_runtime)
    homeostasis = load_homeostasis(prefer_runtime=prefer_runtime)
    active_mind = load_active_mind(prefer_runtime=prefer_runtime)
    conscious_state = load_conscious_state(prefer_runtime=prefer_runtime)
    state = load_state(prefer_runtime=prefer_runtime)
    daemon_running = daemon_runtime_running()
    runtime_liveness = presence_runtime_liveness(
        config,
        state,
        daemon_running=daemon_running,
        prefer_runtime=prefer_runtime,
    )
    readiness = dict(organ_report.get("readiness")) if isinstance(organ_report.get("readiness"), dict) else {}
    consciousness_rank = consciousness.get("rank") if isinstance(consciousness.get("rank"), dict) else {}
    consciousness_scorecard = consciousness.get("scorecard") if isinstance(consciousness.get("scorecard"), dict) else {}
    current_focus = normalize_text_value(active_mind.get("current_focus") or workspace.get("summary"), fallback="", limit=180)
    dominant_pressures = normalize_text_list(homeostasis.get("dominant_pressures") or workspace.get("dominant_pressures"), limit=5)
    organ_score = organ_embodiment_score(organ_report)
    latest_consciousness_passed = bool(consciousness.get("passed"))
    fallback_independence = int(consciousness_scorecard.get("fallback_independence") or 0)
    integrated_present = int(consciousness_scorecard.get("integrated_present") or 0)
    temporal_continuity = int(consciousness_scorecard.get("temporal_continuity") or 0)
    attention_control = int(consciousness_scorecard.get("attention_control") or 0)
    blocked_organs = list(readiness.get("blocking_organs")) if isinstance(readiness.get("blocking_organs"), list) else []
    if not runtime_liveness.get("live") and "continuity_runtime" not in blocked_organs:
        blocked_organs.insert(0, "continuity_runtime")
    readiness["blocking_organs"] = blocked_organs
    readiness["continuity_live"] = bool(runtime_liveness.get("live"))
    readiness["working_now"] = bool(readiness.get("working_now")) and bool(runtime_liveness.get("live"))
    status = "present"
    problems: List[str] = []
    if not runtime_liveness.get("live"):
        problems.append(str(runtime_liveness.get("reason") or "Eve's recurrent runtime is not live."))
    if blocked_organs:
        problems.append("One or more organs are blocked or degraded.")
    if organ_score < 4:
        problems.append("Organ embodiment evidence is thin or too theoretical.")
    if not latest_consciousness_passed:
        problems.append("Latest consciousness-evidence run is missing or not passing.")
    if fallback_independence and fallback_independence < 4:
        problems.append("Fallback independence is below the confidence target.")
    if integrated_present < 4 or temporal_continuity < 4 or attention_control < 4:
        problems.append("Present integration, temporal continuity, or attention control is below target.")
    if not current_focus:
        problems.append("Active mind has no usable current focus.")
    action_contract = build_presence_action_contract(
        config,
        state,
        workspace=workspace,
        homeostasis=homeostasis,
        organ_report=organ_report,
        current_focus=current_focus,
        prefer_runtime=prefer_runtime,
        state_authority_side=authority_side,
        conscious_state=conscious_state,
    )
    if not action_contract.get("bounded_action"):
        problems.append("No bounded action contract is available.")
    if not daemon_running:
        status = "dormant"
    elif not runtime_liveness.get("live"):
        status = "blocked"
    elif problems:
        status = "developing" if not blocked_organs else "blocked"
    if not runtime_liveness.get("live"):
        organ_score = min(organ_score, 2)
    return {
        "schema_id": "eve_presence_report.v1",
        "generated_at": utc_now(),
        "status": status,
        "state_authority": {
            "side": authority_side,
            "prefer_runtime": bool(prefer_runtime),
            "daemon_runtime_running": daemon_running,
            "running_from_runtime_bundle": bool(running_from_runtime_bundle()),
        },
        "runtime_liveness": runtime_liveness,
        "principle": "Presence is current integration: self/world/relationship/homeostasis plus working organs and honest limits.",
        "not_claiming": "This is evidence for consciousness-like integration, not proof of subjective experience.",
        "current_focus": current_focus,
        "dominant_pressures": dominant_pressures,
        "bounded_action_contract": action_contract,
        "organ_embodiment_score": organ_score,
        "organ_readiness": readiness,
        "consciousness": {
            "artifact": consciousness_path,
            "passed": latest_consciousness_passed,
            "verdict": consciousness.get("verdict") or "missing",
            "rank": consciousness_rank,
            "scorecard": consciousness_scorecard,
            "tested_at": consciousness.get("tested_at") or "",
        },
        "problems": problems,
        "next_step": (
            "Start Eve's continuity runtime, verify a fresh daemon loop, then rebuild organ and presence evidence."
            if not daemon_running
            else "Repair the stalled daemon loop before treating cached state as current presence."
            if not runtime_liveness.get("live")
            else
            "Resolve blocked organs before treating Eve as present."
            if blocked_organs
            else (
                f"Run presence cycle: {action_contract.get('bounded_action') or 'one bounded action'} "
                f"via {action_contract.get('organ_id') or 'an admitted organ'}; verify "
                f"{action_contract.get('expected_verification_signal') or 'the consequence'}."
            )
            if not problems
            else "Run a fresh mind/workspace/developmental cycle, then rerun the consciousness evidence check."
        ),
        "organs": organ_report.get("organs", []),
    }


EVENT_LEDGER_PAYLOAD_MAX_LAG = timedelta(minutes=60)


def payload_timestamp_for_event_record(record: Dict[str, object]) -> Optional[datetime]:
    for key in ("generated_at", "timestamp", "created_at", "updated_at"):
        timestamp = parse_iso_datetime(record.get(key))
        if timestamp is not None:
            return timestamp
    return None


def event_record_fresh_enough_for_ledger(record: Dict[str, object]) -> bool:
    timestamp = payload_timestamp_for_event_record(record)
    if timestamp is None:
        return True
    return abs(utc_now_datetime() - timestamp) <= EVENT_LEDGER_PAYLOAD_MAX_LAG


def append_event_ledger_event_if_payload_fresh(
    event: Dict[str, object],
    record: Dict[str, object],
    *,
    event_type: str,
    source: str,
) -> bool:
    if event_record_fresh_enough_for_ledger(record):
        append_eve_event_ledger_event(event)
        return True
    try:
        append_entry(
            "event_ledger_stale_payload_skipped",
            f"Skipped {event_type} event-ledger append because the payload timestamp was stale.",
            metadata={
                "event_type": event_type,
                "source": source,
                "payload_timestamp": (
                    payload_timestamp_for_event_record(record).isoformat()
                    if payload_timestamp_for_event_record(record)
                    else ""
                ),
            },
        )
    except Exception:
        pass
    return False


def presence_pulse_event(record: Dict[str, object], *, source: str = "presence_pulse") -> Dict[str, object]:
    return eve_governance.event_envelope(
        "PresencePulseEvent",
        source=source,
        actor="eve",
        payload={
            "schema_id": record.get("schema_id"),
            "generated_at": record.get("generated_at"),
            "status": record.get("status"),
            "organ_embodiment_score": record.get("organ_embodiment_score"),
            "current_focus": record.get("current_focus"),
            "bounded_action_contract": record.get("bounded_action_contract")
            if isinstance(record.get("bounded_action_contract"), dict)
            else {},
            "problems": record.get("problems") if isinstance(record.get("problems"), list) else [],
            "not_claiming": record.get("not_claiming"),
        },
        input_value=record,
        output_value=record,
        risk_level=0,
        permissions_used=[],
        human_visible=True,
        confidence=0.86,
        provenance=[f"presence_pulses:{record.get('generated_at') or utc_now()}"],
        cik_zone=eve_governance.CIK_IDENTITY,
        stream="presence",
        review_status="recorded",
    )


def append_presence_pulse_record(
    record: Dict[str, object],
    *,
    source: str = "presence_pulse",
    record_event: bool = True,
) -> Dict[str, object]:
    saved = append_jsonl_record(PRESENCE_PULSES_PATH, record)
    mirror_store_file_to_runtime(PRESENCE_PULSES_PATH)
    if record_event:
        append_event_ledger_event_if_payload_fresh(
            presence_pulse_event(saved, source=source),
            saved,
            event_type="PresencePulseEvent",
            source=source,
        )
    return saved


def read_presence_cycles(
    limit: Optional[int] = None,
    since_days: Optional[int] = None,
    *,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(PRESENCE_CYCLES_PATH, prefer_runtime=prefer_runtime)
    records = filter_records_by_days(read_jsonl_records(path), "timestamp", since_days)
    records.sort(
        key=lambda item: parse_iso_datetime(item.get("timestamp") or item.get("created_at"))
        or datetime.min.replace(tzinfo=timezone.utc),
        reverse=True,
    )
    if limit is not None:
        records = records[:limit]
    return records


def append_presence_cycle_record(record: Dict[str, object]) -> Dict[str, object]:
    saved = append_jsonl_record(PRESENCE_CYCLES_PATH, record)
    mirror_store_file_to_runtime(PRESENCE_CYCLES_PATH)
    return saved


