    consciousness = record.get("consciousness") if isinstance(record.get("consciousness"), dict) else {}
    readiness = record.get("organ_readiness") if isinstance(record.get("organ_readiness"), dict) else {}
    contract = record.get("bounded_action_contract") if isinstance(record.get("bounded_action_contract"), dict) else {}
