def cmd_presence_cycle(args: argparse.Namespace) -> int:
    config = load_config()
    delegate_args = [
        "presence",
        "cycle",
        *(["--force"] if args.force else []),
        *(["--max-tokens", str(args.max_tokens)] if args.max_tokens else []),
        *(["--no-mind"] if args.no_mind else []),
        *(["--no-workspace"] if args.no_workspace else []),
        *(["--no-action"] if args.no_action else []),
        *(["--no-pulse"] if args.no_pulse else []),
        *(["--full"] if args.full else []),
        *(["--json"] if args.json else []),
    ]
    delegated = delegate_cli_to_runtime(
        delegate_args,
        timeout_seconds=int(config.get("presence_cycle_timeout_seconds") or DEFAULT_CONFIG["presence_cycle_timeout_seconds"]),
    )
    if delegated is not None:
        return delegated

    state = load_state(prefer_runtime=daemon_runtime_running())
    record = run_presence_cycle(
        config,
        state,
        source="manual",
        force=bool(args.force),
        max_tokens=args.max_tokens,
        refresh_mind=not bool(args.no_mind),
        refresh_workspace=not bool(args.no_workspace),
        run_action=not bool(args.no_action),
        record_pulse=not bool(args.no_pulse),
    )
    if args.json:
        print(json.dumps(record, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_presence_cycle_record(record, full=bool(args.full)))
    return 0


