def format_organ_assimilation_report(record: Dict[str, object], *, full: bool = False) -> str:
    if not record:
        return "No organ assimilation report found."
    lines = [
        "Eve organ assimilation",
        f"generated_at: {record.get('generated_at') or 'unknown'}",
        f"principle: {record.get('principle') or 'unknown'}",
        f"resident_chat_lane_delta: {record.get('resident_chat_lane_delta')}",
        f"pulse_ledger: {record.get('pulse_ledger') or ORGAN_PULSES_PATH}",
    ]
    readiness = record.get("readiness") if isinstance(record.get("readiness"), dict) else {}
    if readiness:
        lines.append(f"working_now: {'yes' if readiness.get('working_now') else 'no'}")
        counts = readiness.get("counts") if isinstance(readiness.get("counts"), dict) else {}
        if counts:
            lines.append("readiness: " + ", ".join(f"{key}={value}" for key, value in sorted(counts.items())))
        if readiness.get("blocking_organs"):
            lines.append("blocking_organs: " + format_human_context_list(readiness.get("blocking_organs")))
        if readiness.get("nonconfigured_lab_organs"):
            lines.append("lab_not_configured: " + format_human_context_list(readiness.get("nonconfigured_lab_organs")))
    lines.append("organs:")
    for item in record.get("organs", []):
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- {item.get('id')}: {item.get('status')} | pressure={item.get('pressure')} | {item.get('label')}"
        )
        if item.get("operational_status") or item.get("maturity_status"):
            lines.append(
                f"  operational: {item.get('operational_status') or 'unknown'} | maturity: {item.get('maturity_status') or item.get('status') or 'unknown'}"
            )
        lines.append(f"  role: {normalize_text_value(item.get('role'), fallback='', limit=260)}")
        lines.append(f"  summary: {normalize_text_value(item.get('summary'), fallback='', limit=260)}")
        lines.append(f"  boundary: {normalize_text_value(item.get('authority_boundary'), fallback='', limit=260)}")
        if item.get("evidence"):
            lines.append(f"  evidence: {format_human_context_list(item.get('evidence') or [])}")
        if full:
            lines.append(f"  human_quality: {normalize_text_value(item.get('human_quality'), fallback='', limit=260)}")
            lines.append(f"  cik_zone: {item.get('cik_zone') or 'unknown'}")
            lines.append(f"  next: {normalize_text_value(item.get('next_step'), fallback='', limit=260)}")
    return "\n".join(lines)


