def format_specialist_substrate_report(record: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "Specialist substrate status",
        f"generated_at: {record.get('generated_at') or 'unknown'}",
        f"principle: {record.get('principle') or 'unknown'}",
        f"resident_chat_lane_delta: {record.get('resident_chat_lane_delta')}",
        "substrates:",
    ]
    for item in record.get("substrates", []):
        if not isinstance(item, dict):
            continue
        lines.append(
            f"- {item.get('id')}: {item.get('status')} | adds_chat_lane={'yes' if item.get('adds_chat_lane') else 'no'}"
        )
        lines.append(f"  purpose: {normalize_text_value(item.get('purpose'), fallback='', limit=220)}")
        lines.append(f"  guardrail: {normalize_text_value(item.get('guardrail'), fallback='', limit=220)}")
        if item.get("evidence"):
            lines.append(f"  evidence: {format_human_context_list(item.get('evidence') or [])}")
        if full:
            lines.append(f"  target: {item.get('target_state') or 'unknown'}")
            lines.append(f"  next: {normalize_text_value(item.get('next_maturation'), fallback='', limit=260)}")
            commands = item.get("commands") if isinstance(item.get("commands"), list) else []
            if commands:
                lines.append("  commands:")
                lines.extend(f"    - {command}" for command in commands)
    return "\n".join(lines)


