def cmd_hermes_feature_policy(args: argparse.Namespace) -> int:
    inventory = None
    if args.refresh_inventory:
        inventory = build_hermes_capability_inventory(timeout=int(args.timeout or 25), save=not bool(args.no_save))
    policy = build_hermes_feature_policy(inventory=inventory, save=not bool(args.no_save))
    if args.json:
        print(json.dumps(policy, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_hermes_feature_policy(policy, full=bool(args.full)))
    return 0 if policy.get("status") in {"clear", "watch"} else 1


def cmd_hermes_skill_admission(args: argparse.Namespace) -> int:
    report = evaluate_hermes_skill_admission_request(
        skill_name=str(args.skill or ""),
        purpose=str(args.purpose or ""),
        tests=[str(item) for item in (args.test or [])],
        evidence=[str(item) for item in (args.evidence or [])],
        permission_class=str(args.permission_class or "read_only"),
        source=str(args.source or "hermes"),
        skill_path=str(args.skill_path or ""),
        filesystem_boundary=str(args.filesystem_boundary or ""),
        network_boundary=str(args.network_boundary or ""),
        credential_boundary=str(args.credential_boundary or ""),
    )
    queued = False
    if args.enqueue:
        blockers = report.get("blockers") if isinstance(report.get("blockers"), list) else []
        if blockers:
            report["enqueue_status"] = "blocked"
        else:
            proposal = report.get("proposal") if isinstance(report.get("proposal"), dict) else {}
            saved = append_governance_proposal(dict(proposal))
            mirror_store_file_to_runtime(GOVERNANCE_PROPOSALS_PATH)
            report["proposal"] = saved
            report["enqueue_status"] = "queued"
            queued = True
    else:
        report["enqueue_status"] = "dry_run"
    if args.record or queued:
        append_jsonl_record(HERMES_SKILL_ADMISSION_AUDIT_LOG_PATH, dict(report))
        mirror_store_file_to_runtime(HERMES_SKILL_ADMISSION_AUDIT_LOG_PATH)
        report["audit_log"] = str(HERMES_SKILL_ADMISSION_AUDIT_LOG_PATH)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_hermes_skill_admission(report, full=bool(args.full)))
        print(f"enqueue_status: {report.get('enqueue_status')}")
        if report.get("audit_log"):
            print(f"audit_log: {report.get('audit_log')}")
    return 0 if str(report.get("status") or "").startswith(("ready", "needs_approval")) and report.get("enqueue_status") != "blocked" else 2


def cmd_hermes_doctor(args: argparse.Namespace) -> int:
    payload = detect_hermes_learning_organ(timeout=int(args.timeout or 10))
    command = str(payload.get("command") or hermes_command_path())
    launch_command = hermes_command_args("doctor")
    profile_home = str(payload.get("profile_home") or HERMES_EVE_PROFILE_HOME)
    env = os.environ.copy()
    env["HERMES_HOME"] = profile_home
    try:
        process = subprocess.run(
            launch_command,
            cwd=str(ROOT),
            env=env,
            text=True,
            capture_output=True,
            timeout=int(args.timeout or 45),
        )
    except (FileNotFoundError, subprocess.TimeoutExpired) as exc:
        print(f"Hermes doctor failed: {normalize_text_value(exc, fallback='command failed', limit=260)}")
        return 1
    if process.stdout:
        print(process.stdout.rstrip())
    if process.stderr:
        print(process.stderr.rstrip(), file=sys.stderr)
    return 0 if process.returncode == 0 else process.returncode


def cmd_hermes_smoke(args: argparse.Namespace) -> int:
    try:
        trace_payload = parse_hermes_trace_payload(
            trace_json=str(args.trace_json or ""),
            trace_file=str(args.trace_file or ""),
        )
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    if args.prompt_only:
        print(build_hermes_smoke_prompt(trace_payload))
        return 0
    record = run_hermes_smoke(
        trace_payload=trace_payload,
        timeout=int(args.timeout or 120),
        ingest=bool(args.ingest),
        allow_non_local=bool(args.allow_non_local),
        repair_json=bool(args.repair_json),
        allow_repaired_ingest=bool(args.allow_repaired_ingest),
        constrained_json=bool(args.constrained_json),
        local_64k_lab=bool(args.local_64k_lab),
        keep_local_lab=bool(args.keep_local_lab),
    )
    if args.json:
        print(json.dumps(record, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_hermes_smoke_result(record, full=bool(args.full)))
    status = str(record.get("status") or "")
    return 0 if status in {"passed", "passed_with_warnings", "passed_with_json_repair", "passed_with_json_repair_warnings"} else 2


