def format_route_contract_document(document: Dict[str, object], *, full: bool = False) -> str:
    contracts = document.get("contracts") if isinstance(document.get("contracts"), list) else []
    lines = [
        "Eve route contracts",
        f"schema: {document.get('schema_version') or 'unknown'}",
        f"owner: {document.get('owner') or 'unknown'}",
        f"path: {document.get('path') or ROUTE_CONTRACTS_PATH}",
        f"contracts: {len(contracts)}",
    ]
    for contract in contracts:
        if not isinstance(contract, dict):
            continue
        lines.append(
            f"- {contract.get('kind')}: budget={contract.get('budget')} "
            f"lanes={','.join(str(item) for item in (contract.get('lanes') or [])) or '-'} "
            f"mode={contract.get('response_mode') or 'static'} "
            f"evidence={contract.get('evidence_policy')}"
        )
        if full:
            lines.append(f"  description: {contract.get('description') or ''}")
            lines.append(f"  match: {json.dumps(contract.get('match') or {}, ensure_ascii=True, sort_keys=True)}")
            if contract.get("delegates_to"):
                lines.append(f"  delegates_to: {contract.get('delegates_to')}")
            if contract.get("anti_contract"):
                lines.append(f"  anti_contract: {len(contract.get('anti_contract') or [])} guard(s)")
    return "\n".join(lines)


