def format_route_contract_replay(report: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "Eve route contract replay",
        f"status: {report.get('status')}",
        f"cases: {report.get('case_count')} | passed: {report.get('passed')} | failed: {report.get('failed')}",
        f"contracts: {report.get('contracts_path')}",
        f"evals: {report.get('eval_cases_path')}",
    ]
    for item in report.get("results") or []:
        if not isinstance(item, dict):
            continue
        status = item.get("status")
        lines.append(
            f"- {item.get('id')}: {status} | kind={item.get('actual_kind') or '-'} "
            f"budget={item.get('actual_budget') or '-'}"
        )
        if full and item.get("errors"):
            for error_text in item.get("errors") or []:
                lines.append(f"  error: {error_text}")
    return "\n".join(lines)


