def execute_openclaw_action_plan(
    config: Dict[str, object],
    plan: Dict[str, object],
    *,
    timeout: int = 120,
    dry_run: bool = False,
) -> Dict[str, object]:
    action = normalize_text_value(plan.get("action"), fallback="", limit=80)
    if action not in eve_openclaw_body.openclaw_router_action_ids():
        raise SystemExit(f"Unsupported OpenClaw action router action: {action or 'unknown'}")
    base: Dict[str, object] = {
        "action": action,
        "ok": False,
        "executed": False,
        "summary": "",
        "plan": plan,
        "evidence_event_ids": [],
        "issues": [],
    }
    if dry_run:
        base.update(
            {
                "ok": True,
                "dry_run": True,
                "summary": f"Dry run selected OpenClaw action `{action}` for intent: {plan.get('intent')}",
            }
        )
        return base

    evidence_event_ids: List[str] = []
    status: Dict[str, object] = {}

    if action == "status_snapshot":
        status = eve_openclaw.collect_openclaw_status(
            config,
            prefer_runtime=True,
            include_gateway_probe=True,
            include_memory_probe=True,
        )
        eve_openclaw.save_openclaw_status(status)
        event = eve_openclaw_body.append_evidence_event(
            eve_openclaw_body.build_status_evidence_event(status, source="openclaw_action_router")
        )
        evidence_event_ids.append(str(event.get("id") or ""))
        base.update(
            {
                "ok": bool(status.get("gateway_reachable")),
                "executed": True,
                "summary": normalize_text_value(status.get("summary"), fallback="OpenClaw status snapshot recorded.", limit=260),
                "status": status,
            }
        )
    elif action == "sync_context":
        sync_result = eve_openclaw.sync_openclaw(
            config,
            append_memory=False,
            timeout=min(max(30, int(timeout)), int(config.get("openclaw_timeout_seconds") or 900)),
        )
        status = sync_result.get("status") if isinstance(sync_result.get("status"), dict) else {}
        if status:
            event = eve_openclaw_body.append_evidence_event(
                eve_openclaw_body.build_status_evidence_event(status, source="openclaw_action_router_sync")
            )
            evidence_event_ids.append(str(event.get("id") or ""))
        base.update(
            {
                "ok": bool(sync_result.get("ok")),
                "executed": True,
                "summary": normalize_text_value(
                    (status or {}).get("summary") or sync_result.get("stdout") or sync_result.get("stderr"),
                    fallback="OpenClaw context sync completed.",
                    limit=260,
                ),
                "sync": sync_result,
                "status": status,
            }
        )
    elif action == "activity_ingest":
        state_dir = Path(str(config.get("openclaw_state_dir") or eve_openclaw_body.DEFAULT_OPENCLAW_STATE_DIR)).expanduser()
        events = eve_openclaw_body.build_openclaw_activity_events(
            state_dir=state_dir,
            include_sessions=bool(plan.get("include_sessions")),
            limit=25,
            command_timeout=min(max(10, int(timeout)), 60),
        )
        ready_count = 0
        for event in events:
            saved = eve_openclaw_body.append_evidence_event(event)
            evidence_event_ids.append(str(saved.get("id") or ""))
            if str(saved.get("status") or "") == "ready":
                ready_count += 1
        base.update(
            {
                "ok": ready_count > 0,
                "executed": True,
                "summary": f"Ingested {len(events)} OpenClaw activity evidence event(s); ready={ready_count}.",
                "activity_event_count": len(events),
                "ready_event_count": ready_count,
            }
        )
    elif action == "memory_wiki_health":
        command_timeout = min(max(10, int(timeout)), 90)
        memory = eve_openclaw_body.run_openclaw_json_command(["memory", "status", "--deep", "--json"], timeout=command_timeout)
        wiki = eve_openclaw_body.run_openclaw_json_command(["wiki", "status", "--json"], timeout=command_timeout)
        created_at = eve_openclaw_body.utc_now()
        ready_count = sum(1 for item in [memory, wiki] if item.get("ok"))
        health_event = eve_openclaw_body.build_openclaw_activity_event(
            event_type="openclaw_memory_wiki_health",
            created_at=created_at,
            source="openclaw_action_router",
            status="ready" if memory.get("ok") and wiki.get("ok") else "degraded",
            summary=f"OpenClaw memory/wiki health checked; ready surfaces={ready_count}/2.",
            payload={
                "memory": memory,
                "wiki": wiki,
            },
        )
        saved = eve_openclaw_body.append_evidence_event(health_event)
        evidence_event_ids.append(str(saved.get("id") or ""))
        base.update(
            {
                "ok": bool(memory.get("ok") and wiki.get("ok")),
                "executed": True,
                "summary": f"OpenClaw memory/wiki health checked; ready surfaces={ready_count}/2.",
                "memory_ok": bool(memory.get("ok")),
                "wiki_ok": bool(wiki.get("ok")),
            }
        )
    elif action == "contracts_refresh":
        status = eve_openclaw.collect_openclaw_status(
            config,
            prefer_runtime=True,
            include_gateway_probe=True,
            include_memory_probe=True,
        )
        eve_openclaw.save_openclaw_status(status)
        report = eve_openclaw_body.write_contract_report(eve_openclaw_body.build_openclaw_body_contract_report(status))
        base.update(
            {
                "ok": True,
                "executed": True,
                "summary": f"Refreshed {len(report.get('contracts') or [])} OpenClaw body-bus contract(s).",
                "contract_count": len(report.get("contracts") or []),
                "status": status,
            }
        )
    elif action == "admission_audit":
        records = eve_openclaw_body.read_admission_records(limit=50, prefer_runtime=False)
        skills = eve_openclaw_body.run_openclaw_json_command(["skills", "list", "--json"], timeout=min(max(10, int(timeout)), 60))
        plugins = eve_openclaw_body.run_openclaw_json_command(["plugins", "list", "--json"], timeout=min(max(10, int(timeout)), 60))
        mcp = eve_openclaw_body.run_openclaw_json_command(["mcp", "list", "--json"], timeout=min(max(10, int(timeout)), 60))
        created_at = eve_openclaw_body.utc_now()
        audit_event = eve_openclaw_body.build_openclaw_activity_event(
            event_type="openclaw_admission_audit",
            created_at=created_at,
            source="openclaw_action_router",
            status="ready" if skills.get("ok") or plugins.get("ok") or mcp.get("ok") else "degraded",
            summary=f"OpenClaw admission audit saw {len(records)} Eve admission record(s).",
            payload={
                "admission_records": records,
                "skills": skills,
                "plugins": plugins,
                "mcp": mcp,
            },
        )
        saved = eve_openclaw_body.append_evidence_event(audit_event)
        evidence_event_ids.append(str(saved.get("id") or ""))
        base.update(
            {
                "ok": bool(skills.get("ok") or plugins.get("ok") or mcp.get("ok")),
                "executed": True,
                "summary": f"Audited OpenClaw admissions and runtime capability surfaces; records={len(records)}.",
                "admission_record_count": len(records),
                "skills_ok": bool(skills.get("ok")),
                "plugins_ok": bool(plugins.get("ok")),
                "mcp_ok": bool(mcp.get("ok")),
            }
        )
    elif action == "repair_diagnose":
        repair_result = eve_openclaw.repair_openclaw(
            config,
            message=openclaw_diagnose_only_prompt(),
            timeout=max(60, int(timeout)),
            skip_sync=False,
        )
        parsed_reply = repair_result.get("parsed_reply") if isinstance(repair_result.get("parsed_reply"), dict) else {}
        base.update(
            {
                "ok": bool(repair_result.get("ok")),
                "executed": True,
                "summary": normalize_text_value(
                    parsed_reply.get("issue") or parsed_reply.get("action") or repair_result.get("reply"),
                    fallback="OpenClaw diagnose-only repair completed.",
                    limit=260,
                ),
                "repair": repair_result,
            }
        )

    base["evidence_event_ids"] = [item for item in evidence_event_ids if item]
    router_event = eve_openclaw_body.append_openclaw_action_router_event(
        eve_openclaw_body.build_openclaw_action_router_event(plan, base)
    )
    base["router_event"] = router_event
    base["event_id"] = router_event.get("id")
    append_entry(
        "openclaw_action_router",
        normalize_text_value(base.get("summary"), fallback=f"OpenClaw action router ran {action}.", limit=260),
        metadata={
            "source": plan.get("source"),
            "action": action,
            "ok": bool(base.get("ok")),
            "event_id": router_event.get("id"),
            "contract_id": plan.get("contract_id"),
        },
    )
    return base


