def openclaw_routine_state_key(routine_id: object) -> str:
    token = re.sub(r"[^a-z0-9_]+", "_", str(routine_id or "routine").strip().lower()).strip("_")
    return f"last_openclaw_routine_{token}_at"


def openclaw_routine_due(spec: Dict[str, object], state: Dict[str, object], *, force: bool = False) -> bool:
    if force:
        return True
    interval_minutes = max(1, int(spec.get("interval_minutes") or 1440))
    return interval_due(state.get(openclaw_routine_state_key(spec.get("id"))), interval_minutes)


def build_openclaw_routine_event(
    spec: Dict[str, object],
    *,
    status: str,
    summary: str,
    source: str,
    plan: Optional[Dict[str, object]] = None,
    result: Optional[Dict[str, object]] = None,
    due: bool = False,
) -> Dict[str, object]:
    result = result if isinstance(result, dict) else {}
    return {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "event_type": "openclaw_routine",
        "source": normalize_text_value(source, fallback="manual", limit=120),
        "substrate_id": eve_openclaw_body.OPENCLAW_BODY_SUBSTRATE_ID,
        "canonical_memory_authority": False,
        "routine_id": normalize_text_value(spec.get("id"), fallback="openclaw_routine", limit=120),
        "router_action": normalize_text_value(spec.get("action"), fallback="", limit=80),
        "status": normalize_text_value(status, fallback="skipped", limit=80),
        "due": bool(due),
        "executed": bool(result.get("executed")),
        "ok": bool(result.get("ok")),
        "summary": normalize_text_value(summary, fallback="OpenClaw routine recorded.", limit=300),
        "payload": {
            "purpose": normalize_text_value(spec.get("purpose"), fallback="", limit=260),
            "interval_minutes": int(spec.get("interval_minutes") or 0),
            "plan_id": plan.get("id") if isinstance(plan, dict) else "",
            "router_event_id": result.get("event_id"),
            "evidence_event_ids": result.get("evidence_event_ids") if isinstance(result.get("evidence_event_ids"), list) else [],
        },
    }


def run_openclaw_routines(
    config: Dict[str, object],
    state: Dict[str, object],
    *,
    force: bool = False,
    dry_run: bool = False,
    record_skips: bool = False,
    limit: Optional[int] = None,
    timeout: int = 120,
    source: str = "manual",
) -> Dict[str, object]:
    if not eve_openclaw.openclaw_enabled(config):
        return {"ok": False, "summary": "OpenClaw is disabled.", "events": [], "executed": 0, "skipped": 0}
    if not force and not parse_boolish(config.get("openclaw_routines_enabled", True)):
        return {"ok": True, "summary": "OpenClaw routines are disabled.", "events": [], "executed": 0, "skipped": 0}

    specs = list(openclaw_routine_registry().values())
    if limit is not None:
        specs = specs[: max(0, int(limit))]
    events: List[Dict[str, object]] = []
    executed = 0
    skipped = 0
    ok_count = 0
    now = utc_now()
    for spec in specs:
        routine_id = normalize_text_value(spec.get("id"), fallback="openclaw_routine", limit=120)
        due = openclaw_routine_due(spec, state, force=force)
        if not due:
            skipped += 1
            if record_skips:
                event = eve_openclaw_body.append_openclaw_routine_event(
                    build_openclaw_routine_event(
                        spec,
                        status="skipped",
                        summary=f"{routine_id} not due yet.",
                        source=source,
                        due=False,
                    )
                )
                events.append(event)
            continue

        plan = eve_openclaw_body.build_openclaw_action_plan(
            intent=spec.get("intent") or routine_id,
            requested_action=spec.get("action") or "",
            source=f"{source}:openclaw_routine:{routine_id}",
            include_sessions=bool(spec.get("include_sessions")),
        )
        result = execute_openclaw_action_plan(
            config,
            plan,
            timeout=timeout,
            dry_run=dry_run,
        )
        executed += 1
        if result.get("ok"):
            ok_count += 1
        if not dry_run:
            state[openclaw_routine_state_key(routine_id)] = now
            state["last_openclaw_routine_at"] = now
        event_status = "dry_run" if dry_run else "ready" if result.get("ok") else "degraded"
        event = eve_openclaw_body.append_openclaw_routine_event(
            build_openclaw_routine_event(
                spec,
                status=event_status,
                summary=normalize_text_value(result.get("summary"), fallback=f"{routine_id} completed.", limit=300),
                source=source,
                plan=plan,
                result=result,
                due=True,
            )
        )
        events.append(event)

    summary = f"OpenClaw routines checked: executed={executed}, ok={ok_count}, skipped={skipped}."
    return {
        "ok": executed == 0 or ok_count == executed,
        "summary": summary,
        "events": events,
        "executed": executed,
        "ok_count": ok_count,
        "skipped": skipped,
        "dry_run": bool(dry_run),
    }


def format_openclaw_routine_result(result: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "OpenClaw routines",
        f"ok: {'yes' if result.get('ok') else 'no'}",
        f"summary: {result.get('summary') or 'none'}",
    ]
    events = result.get("events") if isinstance(result.get("events"), list) else []
    if events:
        lines.append("events:")
        for event in events:
            lines.append(
                f"- {event.get('routine_id')}: {event.get('status')} | "
                f"action={event.get('router_action')} | {event.get('summary')}"
            )
            if full:
                payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
                if payload.get("router_event_id"):
                    lines.append(f"  router_event_id: {payload.get('router_event_id')}")
                evidence_ids = payload.get("evidence_event_ids") if isinstance(payload.get("evidence_event_ids"), list) else []
                if evidence_ids:
                    lines.append(f"  evidence_event_ids: {', '.join(str(item) for item in evidence_ids)}")
    return "\n".join(lines)


def cmd_openclaw_routines(args: argparse.Namespace) -> int:
    config = load_config()
    state = load_state()
    result = run_openclaw_routines(
        config,
        state,
        force=bool(args.force),
        dry_run=bool(args.dry_run),
        record_skips=bool(args.record_skips),
        limit=args.limit,
        timeout=args.timeout or int(config.get("openclaw_timeout_seconds") or 900),
        source="cli",
    )
    if not args.dry_run:
        save_state(state)
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=True))
    else:
        print(format_openclaw_routine_result(result, full=args.full))
    return 0 if result.get("ok") else 1


