def build_openclaw_worker_plan(
    *,
    worker_kind: object,
    parent_intention: object,
    prompt: object,
    source: str = "manual",
    timeout: int = 120,
) -> Dict[str, object]:
    registry = openclaw_worker_registry()
    kind = normalize_text_value(worker_kind, fallback="", limit=80)
    if kind not in registry:
        raise ValueError(f"Unsupported OpenClaw worker kind: {kind or 'unknown'}")
    parent = normalize_text_value(parent_intention, fallback="", limit=320)
    task_prompt = normalize_text_value(prompt, fallback="", limit=1200)
    if not parent:
        raise ValueError("OpenClaw worker requires --parent-intention.")
    if not task_prompt:
        raise ValueError("OpenClaw worker requires --prompt.")
    spec = registry[kind]
    worker_id = f"eve-worker-{kind}-{uuid.uuid4().hex[:12]}"
    return {
        "id": worker_id,
        "created_at": utc_now(),
        "source": source,
        "worker_kind": kind,
        "parent_intention": parent,
        "prompt": task_prompt,
        "agent": "eve-repair",
        "session_id": worker_id,
        "permission_level": spec["permission_level"],
        "owning_lane": spec["owning_lane"],
        "description": spec["description"],
        "timeout": max(30, int(timeout)),
        "requires_specific_approval": spec["permission_level"] in {"approval_gated", "specific_approval_required"},
        "adds_chat_lane": False,
        "persistent_agent": False,
        "canonical_memory_authority": False,
    }


def build_openclaw_worker_message(plan: Dict[str, object]) -> str:
    return (
        "You are a short-lived OpenClaw worker for Eve, not a separate Eve identity.\n"
        "Use only the evidence needed for this one bounded task. Do not send messages, install plugins, change auth, "
        "change model providers, delete files, or perform approval-gated edits.\n"
        "Return exactly one strict JSON object and no prose, with keys: status, issue, action, verified, next_step.\n\n"
        f"Worker kind: {plan.get('worker_kind')}\n"
        f"Parent Eve intention: {plan.get('parent_intention')}\n"
        f"Task: {plan.get('prompt')}\n"
    )


OPENCLAW_WORKER_REQUIRED_KEYS = ("status", "issue", "action", "verified", "next_step")


def openclaw_worker_final_text(command_result: Dict[str, object]) -> str:
    payload = command_result.get("payload") if isinstance(command_result.get("payload"), dict) else {}
    meta = payload.get("meta") if isinstance(payload.get("meta"), dict) else {}
    for key in ("finalAssistantRawText", "finalAssistantVisibleText"):
        value = meta.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    payloads = payload.get("payloads") if isinstance(payload.get("payloads"), list) else []
    for item in reversed(payloads):
        if not isinstance(item, dict):
            continue
        text = item.get("text")
        if isinstance(text, str) and text.strip():
            return text.strip()
    return ""


def validate_openclaw_worker_strict_json(command_result: Dict[str, object]) -> Dict[str, object]:
    final_text = openclaw_worker_final_text(command_result)
    if not final_text:
        return {
            "ok": False,
            "error": "OpenClaw worker returned no final assistant text.",
            "required_keys": list(OPENCLAW_WORKER_REQUIRED_KEYS),
        }
    payload = strict_json_loads(final_text)
    if payload is None:
        return {
            "ok": False,
            "error": "OpenClaw worker final reply was not one strict JSON object.",
            "required_keys": list(OPENCLAW_WORKER_REQUIRED_KEYS),
            "final_text_excerpt": normalize_text_value(final_text, fallback="", limit=500),
        }
    missing = [key for key in OPENCLAW_WORKER_REQUIRED_KEYS if key not in payload]
    if missing:
        return {
            "ok": False,
            "error": f"OpenClaw worker strict JSON missing keys: {', '.join(missing)}.",
            "required_keys": list(OPENCLAW_WORKER_REQUIRED_KEYS),
            "missing_keys": missing,
            "payload_keys": sorted(payload.keys()),
        }
    return {
        "ok": True,
        "required_keys": list(OPENCLAW_WORKER_REQUIRED_KEYS),
        "payload": {key: payload.get(key) for key in OPENCLAW_WORKER_REQUIRED_KEYS},
        "payload_keys": sorted(payload.keys()),
    }


def build_openclaw_worker_event(
    plan: Dict[str, object],
    *,
    status: str,
    summary: str,
    command_result: Optional[Dict[str, object]] = None,
    dry_run: bool = False,
) -> Dict[str, object]:
    command_result = command_result if isinstance(command_result, dict) else {}
    payload = command_result.get("payload") if isinstance(command_result.get("payload"), dict) else {}
    return {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "event_type": "openclaw_worker",
        "source": normalize_text_value(plan.get("source"), fallback="manual", limit=120),
        "substrate_id": eve_openclaw_body.OPENCLAW_BODY_SUBSTRATE_ID,
        "canonical_memory_authority": False,
        "worker_id": plan.get("id"),
        "worker_kind": plan.get("worker_kind"),
        "parent_intention": plan.get("parent_intention"),
        "agent": plan.get("agent"),
        "session_id": plan.get("session_id"),
        "permission_level": plan.get("permission_level"),
        "owning_lane": plan.get("owning_lane"),
        "status": normalize_text_value(status, fallback="planned", limit=80),
        "ok": bool(command_result.get("ok")) if command_result else status in {"planned", "dry_run"},
        "dry_run": bool(dry_run),
        "summary": normalize_text_value(summary, fallback="OpenClaw worker event recorded.", limit=300),
        "task_evidence": {
            "session_id": plan.get("session_id"),
            "command": command_result.get("command") if command_result else [],
            "returncode": command_result.get("returncode"),
            "payload_keys": sorted(payload.keys()) if isinstance(payload, dict) else [],
        },
        "worker_strict_json": command_result.get("worker_strict_json") if command_result else {},
        "plan": {
            "description": plan.get("description"),
            "requires_specific_approval": plan.get("requires_specific_approval"),
            "adds_chat_lane": False,
            "persistent_agent": False,
            "canonical_memory_authority": False,
        },
        "payload": payload,
    }


def run_openclaw_worker_plan(
    plan: Dict[str, object],
    *,
    dry_run: bool = False,
) -> Dict[str, object]:
    if dry_run:
        event = eve_openclaw_body.append_openclaw_worker_event(
            build_openclaw_worker_event(
                plan,
                status="dry_run",
                summary=f"Dry run planned OpenClaw worker {plan.get('worker_kind')} for {plan.get('parent_intention')}.",
                dry_run=True,
            )
        )
        return {"ok": True, "event": event, "summary": event["summary"]}
    if plan.get("requires_specific_approval"):
        event = eve_openclaw_body.append_openclaw_worker_event(
            build_openclaw_worker_event(
                plan,
                status="blocked",
                summary="Worker kind requires explicit approval before execution.",
            )
        )
        return {"ok": False, "event": event, "summary": event["summary"]}
    timeout = max(30, int(plan.get("timeout") or 120))
    command_result = eve_openclaw_body.run_openclaw_json_command(
        [
            "agent",
            "--agent",
            str(plan.get("agent") or "eve-repair"),
            "--session-id",
            str(plan.get("session_id") or plan.get("id")),
            "--message",
            build_openclaw_worker_message(plan),
            "--json",
            "--timeout",
            str(timeout),
        ],
        timeout=timeout + 15,
    )
    validation = validate_openclaw_worker_strict_json(command_result) if command_result.get("ok") else {
        "ok": False,
        "error": "OpenClaw worker command failed.",
        "required_keys": list(OPENCLAW_WORKER_REQUIRED_KEYS),
    }
    command_result = dict(command_result)
    command_result["worker_strict_json"] = validation
    worker_ok = bool(command_result.get("ok") and validation.get("ok"))
    summary = "OpenClaw worker completed with strict JSON." if worker_ok else (
        validation.get("error")
        or command_result.get("stderr_excerpt")
        or command_result.get("stdout_excerpt")
        or "OpenClaw worker failed strict JSON validation."
    )
    event = eve_openclaw_body.append_openclaw_worker_event(
        build_openclaw_worker_event(
            plan,
            status="ready" if worker_ok else "degraded",
            summary=str(summary),
            command_result=command_result,
        )
    )
    return {"ok": worker_ok, "event": event, "summary": event["summary"], "command_result": command_result}


def format_openclaw_worker_events(events: List[Dict[str, object]], *, full: bool = False) -> str:
    if not events:
        return "No OpenClaw worker events found."
    lines = ["OpenClaw worker events"]
    for event in events:
        lines.append(
            f"- {event.get('worker_id') or event.get('id')}: {event.get('worker_kind')} | "
            f"{event.get('status')} | {event.get('summary')}"
        )
        if full:
            lines.append(f"  parent: {event.get('parent_intention')}")
            lines.append(f"  session: {event.get('session_id')}")
            lines.append(f"  permission: {event.get('permission_level')}")
    return "\n".join(lines)


def cmd_openclaw_worker_plan(args: argparse.Namespace) -> int:
    try:
        plan = build_openclaw_worker_plan(
            worker_kind=args.kind,
            parent_intention=args.parent_intention,
            prompt=args.prompt,
            source="cli",
            timeout=args.timeout,
        )
    except ValueError as exc:
        raise SystemExit(str(exc))
    event = eve_openclaw_body.append_openclaw_worker_event(
        build_openclaw_worker_event(plan, status="planned", summary=f"Planned OpenClaw worker {plan['worker_kind']}.")
    )
    print(json.dumps(event if args.json else plan, indent=2, ensure_ascii=True) if args.json else format_openclaw_worker_events([event], full=True))
    return 0


def cmd_openclaw_worker_run(args: argparse.Namespace) -> int:
    try:
        plan = build_openclaw_worker_plan(
            worker_kind=args.kind,
            parent_intention=args.parent_intention,
            prompt=args.prompt,
            source="cli",
            timeout=args.timeout,
        )
    except ValueError as exc:
        raise SystemExit(str(exc))
    result = run_openclaw_worker_plan(plan, dry_run=args.dry_run)
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=True))
    else:
        print(format_openclaw_worker_events([result["event"]], full=args.full))
    return 0 if result.get("ok") else 1


def cmd_openclaw_worker_list(args: argparse.Namespace) -> int:
    events = eve_openclaw_body.read_openclaw_worker_events(limit=args.limit, prefer_runtime=args.runtime)
    if args.json:
        print(json.dumps({"events": events}, indent=2, ensure_ascii=True))
    else:
        print(format_openclaw_worker_events(events, full=args.full))
    return 0


def cmd_openclaw_worker_audit(args: argparse.Namespace) -> int:
    events = eve_openclaw_body.read_openclaw_worker_events(limit=args.limit, prefer_runtime=args.runtime)
    tasks_audit = eve_openclaw_body.run_openclaw_json_command(["tasks", "audit", "--json"], timeout=args.timeout)
    degraded = [event for event in events if str(event.get("status") or "") in {"degraded", "failed", "lost", "blocked"}]
    payload = tasks_audit.get("payload") if isinstance(tasks_audit.get("payload"), dict) else {}
    findings = payload.get("findings") if isinstance(payload.get("findings"), list) else []
    audit_event = eve_openclaw_body.append_openclaw_worker_event(
        {
            "event_type": "openclaw_worker_audit",
            "source": "cli",
            "worker_kind": "audit",
            "status": "ready" if tasks_audit.get("ok") else "degraded",
            "ok": bool(tasks_audit.get("ok") and not degraded),
            "summary": f"Worker audit checked {len(events)} worker event(s), degraded={len(degraded)}, task_findings={len(findings)}.",
            "canonical_memory_authority": False,
            "payload": {
                "degraded_worker_events": degraded[: args.limit],
                "tasks_audit": tasks_audit,
            },
        }
    )
    if args.json:
        print(json.dumps({"audit_event": audit_event}, indent=2, ensure_ascii=True))
    else:
        print(format_openclaw_worker_events([audit_event], full=args.full))
    return 0 if audit_event.get("ok") else 1


OPENCLAW_MODEL_RUN_ERROR_MARKERS = (
    "message ordering conflict",
    "context overflow",
    "exceeds the available context size",
    "replayinvalid",
    "compaction timed out",
    "tooluse",
    "invalid_request_error",
    "model runtime error",
)


def collect_openclaw_model_output_texts(value: object, *, depth: int = 0) -> List[str]:
    if depth > 6:
        return []
    if isinstance(value, str):
        text = normalize_text_value(value, fallback="", limit=1200)
        return [text] if text else []
    if isinstance(value, list):
        texts: List[str] = []
        for item in value:
            texts.extend(collect_openclaw_model_output_texts(item, depth=depth + 1))
        return texts
    if isinstance(value, dict):
        texts = []
        for key in ("text", "content", "output", "message", "error", "raw"):
            if key in value:
                texts.extend(collect_openclaw_model_output_texts(value.get(key), depth=depth + 1))
        if not texts and "outputs" in value:
            texts.extend(collect_openclaw_model_output_texts(value.get("outputs"), depth=depth + 1))
        return texts
    return []


def unique_openclaw_texts(texts: Iterable[str], *, limit: int = 8) -> List[str]:
    unique: List[str] = []
    seen: set[str] = set()
    for text in texts:
        normalized = normalize_text_value(text, fallback="", limit=1200)
        if not normalized or normalized in seen:
            continue
        unique.append(normalized)
        seen.add(normalized)
        if len(unique) >= limit:
            break
    return unique


def collect_openai_responses_output_texts(payload: Dict[str, object]) -> List[str]:
    texts: List[str] = []
    outputs = payload.get("output") if isinstance(payload, dict) else []
    if not isinstance(outputs, list):
        return texts
    for item in outputs:
        if not isinstance(item, dict):
            continue
        content = item.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if not isinstance(part, dict) or part.get("type") != "output_text":
                continue
            text = normalize_text_value(part.get("text"), fallback="", limit=1200)
            if text:
                texts.append(text)
    return texts


def openclaw_model_smoke_failure_reasons(
    command_result: Dict[str, object],
    *,
    output_texts: List[str],
    expect_contains: str = "",
) -> List[str]:
    reasons: List[str] = []
    payload = command_result.get("payload") if isinstance(command_result.get("payload"), dict) else {}
    if not command_result.get("ok"):
        reasons.append("openclaw_command_failed")
    if isinstance(payload, dict) and payload.get("ok") is False:
        reasons.append("openclaw_payload_failed")
    joined = " ".join(
        [
            *(str(text) for text in output_texts),
            str(command_result.get("stdout_excerpt") or ""),
            str(command_result.get("stderr_excerpt") or ""),
            str(command_result.get("error") or ""),
        ]
    ).lower()
    for marker in OPENCLAW_MODEL_RUN_ERROR_MARKERS:
        if marker in joined:
            reasons.append(f"runtime_error:{marker}")
    expected = normalize_text_value(expect_contains, fallback="", limit=120)
    if expected and expected.lower() not in joined:
        reasons.append(f"missing_expected_text:{expected}")
    return list(dict.fromkeys(reasons))


def openclaw_configured_model_provider(model_ref: str) -> Dict[str, object]:
    provider_id, separator, model_id = model_ref.partition("/")
    if not separator or not provider_id.strip() or not model_id.strip():
        return {"ok": False, "error": "model reference must use <provider/model>."}
    config_path = eve_openclaw_body.DEFAULT_OPENCLAW_STATE_DIR / "openclaw.json"
    config_payload = eve_store.load_json_dict(config_path, default={})
    providers = config_payload.get("models", {}).get("providers") if isinstance(config_payload.get("models"), dict) else {}
    provider = providers.get(provider_id) if isinstance(providers, dict) else None
    if not isinstance(provider, dict):
        return {"ok": False, "error": f"OpenClaw provider not found: {provider_id}", "config_path": str(config_path)}
    return {
        "ok": True,
        "provider_id": provider_id,
        "model_id": model_id,
        "provider": provider,
        "config_path": str(config_path),
    }


def run_openclaw_configured_model_direct(
    *,
    model_ref: str,
    prompt: str,
    timeout: int,
) -> Dict[str, object]:
    provider_info = openclaw_configured_model_provider(model_ref)
    if not provider_info.get("ok"):
        return {"ok": False, "attempted": False, **provider_info}
    provider = provider_info.get("provider") if isinstance(provider_info.get("provider"), dict) else {}
    api = str(provider.get("api") or "")
    base_url = str(provider.get("baseUrl") or "").rstrip("/")
    if api != "openai-responses" or not base_url:
        return {
            "ok": False,
            "attempted": False,
            "error": f"OpenClaw provider {provider_info.get('provider_id')} is not a direct OpenAI Responses provider.",
            "provider": provider_info.get("provider_id"),
            "api": api,
        }
    endpoint = f"{base_url}/responses"
    headers: Dict[str, str] = {}
    api_key = str(provider.get("apiKey") or "")
    if api_key and str(provider.get("auth") or "") == "api-key":
        headers["Authorization"] = f"Bearer {api_key}"
    payload = {
        "model": str(provider_info.get("model_id") or ""),
        "input": prompt,
        "max_output_tokens": 128,
    }
    try:
        response = post_json_url(endpoint, payload, timeout=timeout, headers=headers)
    except BaseException as exc:
        return {
            "ok": False,
            "attempted": True,
            "transport": "configured_provider_direct",
            "provider": provider_info.get("provider_id"),
            "model": provider_info.get("model_id"),
            "endpoint": endpoint,
            "error": normalize_text_value(exc, fallback="configured provider request failed", limit=400),
            "payload": {},
        }
    return {
        "ok": str(response.get("status") or "completed") not in {"failed", "cancelled", "incomplete"},
        "attempted": True,
        "transport": "configured_provider_direct",
        "provider": provider_info.get("provider_id"),
        "model": provider_info.get("model_id"),
        "endpoint": endpoint,
        "payload": response,
    }


def run_openclaw_model_smoke(
    *,
    model: object,
    prompt: object = "Return exactly OK.",
    expect_contains: object = "OK",
    local: bool = True,
    gateway: bool = False,
    timeout: int = 90,
    source: str = "cli",
) -> Dict[str, object]:
    normalized_model = normalize_text_value(model, fallback="", limit=160)
    if not normalized_model:
        raise ValueError("OpenClaw model smoke requires --model.")
    normalized_prompt = normalize_text_value(prompt, fallback="", limit=2000)
    if not normalized_prompt:
        raise ValueError("OpenClaw model smoke requires --prompt.")
    normalized_expect = normalize_text_value(expect_contains, fallback="", limit=120)
    command = ["capability", "model", "run", "--model", normalized_model, "--prompt", normalized_prompt, "--json"]
    if gateway:
        command.append("--gateway")
    elif local:
        command.append("--local")
    direct_result = run_openclaw_configured_model_direct(
        model_ref=normalized_model,
        prompt=normalized_prompt,
        timeout=timeout,
    )
    command_result = (
        direct_result
        if direct_result.get("attempted")
        else eve_openclaw_body.run_openclaw_json_command(command, timeout=timeout)
    )
    payload = command_result.get("payload") if isinstance(command_result.get("payload"), dict) else {}
    if command_result.get("transport") == "configured_provider_direct":
        output_texts = unique_openclaw_texts(collect_openai_responses_output_texts(payload))
    else:
        output_texts = unique_openclaw_texts(collect_openclaw_model_output_texts(payload))
    failure_reasons = openclaw_model_smoke_failure_reasons(
        command_result,
        output_texts=output_texts,
        expect_contains=normalized_expect,
    )
    ok = not failure_reasons
    summary = (
        f"OpenClaw model smoke passed for {normalized_model}."
        if ok
        else f"OpenClaw model smoke failed for {normalized_model}: {', '.join(failure_reasons[:3])}."
    )
    event = eve_openclaw_body.append_evidence_event(
        {
            "id": str(uuid.uuid4()),
            "created_at": utc_now(),
            "event_type": "openclaw_capability_model_smoke",
            "source": normalize_text_value(source, fallback="cli", limit=80),
            "substrate_id": eve_openclaw_body.OPENCLAW_BODY_SUBSTRATE_ID,
            "canonical_memory_authority": False,
            "body_bus_layer": "typed_eve_action_contracts",
            "status": "ready" if ok else "degraded",
            "ok": ok,
            "summary": summary,
            "permission_level": "read_only",
            "external_send_attempted": False,
            "model": normalized_model,
            "payload": {
                "model": normalized_model,
                "mode": str(command_result.get("transport") or ("gateway" if gateway else "local" if local else "default")),
                "prompt_excerpt": normalize_text_value(normalized_prompt, fallback="", limit=240),
                "expect_contains": normalized_expect,
                "output_texts": output_texts,
                "failure_reasons": failure_reasons,
                "command_result": command_result,
            },
        }
    )
    return {
        "ok": ok,
        "event": event,
        "summary": event["summary"],
        "model": normalized_model,
        "output_texts": output_texts,
        "failure_reasons": failure_reasons,
    }


def format_openclaw_model_smoke_event(event: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "OpenClaw model smoke",
        f"- {event.get('model') or event.get('payload', {}).get('model')}: {event.get('status')} | {event.get('summary')}",
    ]
    if full:
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        if payload.get("failure_reasons"):
            lines.append("  failure_reasons: " + ", ".join(str(item) for item in payload.get("failure_reasons") or []))
        output_texts = payload.get("output_texts") if isinstance(payload.get("output_texts"), list) else []
        if output_texts:
            lines.append("  output: " + normalize_text_value(output_texts[0], fallback="", limit=300))
        lines.append(f"  external_send_attempted: {event.get('external_send_attempted')}")
    return "\n".join(lines)


def cmd_openclaw_model_smoke(args: argparse.Namespace) -> int:
    try:
        result = run_openclaw_model_smoke(
            model=args.model,
            prompt=args.prompt,
            expect_contains=args.expect_contains or "",
            local=not bool(args.gateway),
            gateway=bool(args.gateway),
            timeout=args.timeout,
            source="cli",
        )
    except ValueError as exc:
        raise SystemExit(str(exc))
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=True))
    else:
        print(format_openclaw_model_smoke_event(result["event"], full=args.full))
    return 0 if result.get("ok") else 1


OPENCLAW_CHANNEL_CHOICES = (
    "feishu",
    "googlechat",
    "nostr",
    "msteams",
    "mattermost",
    "nextcloud-talk",
    "matrix",
    "bluebubbles",
    "line",
    "zalo",
    "zalouser",
    "synology-chat",
    "tlon",
    "discord",
    "imessage",
    "irc",
    "qqbot",
    "signal",
    "slack",
    "telegram",
    "twitch",
    "whatsapp",
)

OPENCLAW_CHANNEL_CAPABILITY_TIMEOUT_SECONDS = 120


def openclaw_configured_channels(*payloads: Dict[str, object]) -> List[str]:
    channels: set[str] = set()
    for payload in payloads:
        if not isinstance(payload, dict):
            continue
        for key in ("chat", "channels", "channelAccounts", "channelDefaultAccountId"):
            value = payload.get(key)
            if isinstance(value, dict):
                channels.update(str(item) for item in value.keys() if str(item))
        order = payload.get("channelOrder")
        if isinstance(order, list):
            channels.update(str(item) for item in order if str(item))
        auth = payload.get("auth")
        if isinstance(auth, list):
            for item in auth:
                if isinstance(item, dict):
                    channel = item.get("channel") or item.get("provider") or item.get("name")
                    if channel:
                        channels.add(str(channel))
    return sorted(channel for channel in channels if channel in OPENCLAW_CHANNEL_CHOICES)


def openclaw_channel_health_issues(
    configured_channels: List[str],
    status_payload: Dict[str, object],
    capability_results: List[Dict[str, object]],
) -> List[Dict[str, object]]:
    issues: List[Dict[str, object]] = []
    status_channels = status_payload.get("channels") if isinstance(status_payload, dict) else {}
    status_accounts = status_payload.get("channelAccounts") if isinstance(status_payload, dict) else {}
    if not isinstance(status_channels, dict):
        status_channels = {}
    if not isinstance(status_accounts, dict):
        status_accounts = {}

    def status_reports_running(channel: str, account_id: str = "") -> bool:
        channel_status = status_channels.get(channel)
        if isinstance(channel_status, dict) and channel_status.get("configured"):
            if channel_status.get("running") is True and not channel_status.get("lastError"):
                return True
        account_items = status_accounts.get(channel)
        if isinstance(account_items, list):
            for account in account_items:
                if not isinstance(account, dict):
                    continue
                if account_id and str(account.get("accountId") or "") != account_id:
                    continue
                if (
                    account.get("configured")
                    and account.get("enabled", True)
                    and account.get("running") is True
                    and not account.get("lastError")
                ):
                    return True
        return False

    def status_reports_disabled(channel: str, account_id: str = "") -> bool:
        channel_status = status_channels.get(channel)
        if isinstance(channel_status, dict) and str(channel_status.get("lastError") or "").lower() == "disabled":
            return True
        account_items = status_accounts.get(channel)
        if isinstance(account_items, list):
            matched = False
            for account in account_items:
                if not isinstance(account, dict):
                    continue
                if account_id and str(account.get("accountId") or "") != account_id:
                    continue
                matched = True
                if account.get("enabled") is not False:
                    return False
            if matched:
                return True
        return False

    for channel in configured_channels:
        channel_status = status_channels.get(channel)
        if (
            isinstance(channel_status, dict)
            and channel_status.get("configured")
            and channel_status.get("running") is False
            and not status_reports_disabled(channel)
        ):
            issues.append(
                {
                    "channel": channel,
                    "kind": "channel_runtime",
                    "summary": str(channel_status.get("lastError") or "configured channel is not running"),
                }
            )
        account_items = status_accounts.get(channel)
        if isinstance(account_items, list):
            for account in account_items:
                if not isinstance(account, dict):
                    continue
                if (
                    account.get("configured")
                    and account.get("enabled", True)
                    and account.get("running") is False
                    and not status_reports_disabled(channel, str(account.get("accountId") or ""))
                ):
                    issues.append(
                        {
                            "channel": channel,
                            "account": str(account.get("accountId") or ""),
                            "kind": "account_runtime",
                            "summary": str(account.get("lastError") or "configured channel account is not running"),
                        }
                    )

    for item in capability_results:
        result = item.get("result") if isinstance(item, dict) else {}
        payload = result.get("payload") if isinstance(result, dict) and isinstance(result.get("payload"), dict) else {}
        channels = payload.get("channels") if isinstance(payload, dict) else []
        if not isinstance(channels, list):
            continue
        for channel_record in channels:
            if not isinstance(channel_record, dict):
                continue
            channel = str(channel_record.get("channel") or "")
            if channel not in configured_channels:
                continue
            probe = channel_record.get("probe")
            if isinstance(probe, dict) and probe.get("ok") is False:
                account_id = str(channel_record.get("accountId") or "")
                if status_reports_running(channel, account_id) or status_reports_disabled(channel, account_id):
                    continue
                issues.append(
                    {
                        "channel": channel,
                        "account": account_id,
                        "kind": "capability_probe",
                        "summary": str(probe.get("error") or "channel capability probe failed"),
                    }
                )
    return issues


def build_openclaw_channel_event(
    *,
    event_type: str,
    status: str,
    summary: str,
    ok: bool,
    source: str = "cli",
    channel: str = "",
    target: str = "",
    message: str = "",
    payload: Optional[Dict[str, object]] = None,
    permission_level: str = "read_only",
    external_send_attempted: bool = False,
) -> Dict[str, object]:
    return {
        "id": str(uuid.uuid4()),
        "created_at": utc_now(),
        "event_type": event_type,
        "source": normalize_text_value(source, fallback="cli", limit=80),
        "substrate_id": eve_openclaw_body.OPENCLAW_BODY_SUBSTRATE_ID,
        "canonical_memory_authority": False,
        "permission_level": permission_level,
        "privacy_tier": "external_communication",
        "channel": normalize_text_value(channel, fallback="", limit=80),
        "target": normalize_text_value(target, fallback="", limit=180),
        "message": normalize_text_value(message, fallback="", limit=4000),
        "status": normalize_text_value(status, fallback="blocked", limit=80),
        "ok": bool(ok),
        "summary": normalize_text_value(summary, fallback="OpenClaw channel event recorded.", limit=360),
        "external_send_attempted": bool(external_send_attempted),
        "payload": payload if isinstance(payload, dict) else {},
    }


def run_openclaw_channel_inventory(
    *,
    probe: bool = False,
    timeout: int = 30,
    source: str = "cli",
    record_event: bool = True,
) -> Dict[str, object]:
    list_result = eve_openclaw_body.run_openclaw_json_command(["channels", "list", "--json"], timeout=timeout)
    status_command = ["channels", "status", "--json"]
    if probe:
        status_command.append("--probe")
    status_result = eve_openclaw_body.run_openclaw_json_command(status_command, timeout=timeout)
    list_payload = list_result.get("payload") if isinstance(list_result.get("payload"), dict) else {}
    status_payload = status_result.get("payload") if isinstance(status_result.get("payload"), dict) else {}
    configured = openclaw_configured_channels(list_payload, status_payload)
    capability_results = []
    capability_timeout = max(timeout, OPENCLAW_CHANNEL_CAPABILITY_TIMEOUT_SECONDS)
    for channel in configured:
        capability_results.append(
            {
                "channel": channel,
                "result": eve_openclaw_body.run_openclaw_json_command(
                    ["channels", "capabilities", "--channel", channel, "--json"],
                    timeout=capability_timeout,
                ),
            }
        )
    channel_health_issues = openclaw_channel_health_issues(configured, status_payload, capability_results)
    ok = bool(
        list_result.get("ok")
        and status_result.get("ok")
        and all(item["result"].get("ok") for item in capability_results)
        and not channel_health_issues
    )
    summary = (
        f"OpenClaw channel inventory checked; configured_channels={len(configured)}. "
        f"channel_health_issues={len(channel_health_issues)}. No external send authority is implied."
    )
    payload = {
        "configured_channels": configured,
        "supported_channels": list(OPENCLAW_CHANNEL_CHOICES),
        "list": list_result,
        "status": status_result,
        "capabilities": capability_results,
        "channel_health_issues": channel_health_issues,
        "probe": bool(probe),
    }
    event = build_openclaw_channel_event(
        event_type="openclaw_channel_inventory",
        status="ready" if ok else "degraded",
        summary=summary,
        ok=ok,
        source=source,
        payload=payload,
        permission_level="read_only",
        external_send_attempted=False,
    )
    if record_event:
        event = eve_openclaw_body.append_openclaw_channel_event(event)
    return {
        "ok": ok,
        "event": event,
        "configured_channels": configured,
        "channel_health_issues": channel_health_issues,
        "summary": summary,
    }


def run_openclaw_channel_draft(
    *,
    channel: object,
    target: object,
    message: object,
    account: object = "",
    reply_to: object = "",
    timeout: int = 30,
    source: str = "cli",
) -> Dict[str, object]:
    normalized_channel = normalize_text_value(channel, fallback="", limit=80)
    normalized_target = normalize_text_value(target, fallback="", limit=180)
    normalized_message = normalize_text_value(message, fallback="", limit=4000)
    if normalized_channel not in OPENCLAW_CHANNEL_CHOICES:
        raise ValueError(f"Unsupported OpenClaw channel: {normalized_channel or 'unknown'}")
    if not normalized_target:
        raise ValueError("OpenClaw channel draft requires --target.")
    if not normalized_message:
        raise ValueError("OpenClaw channel draft requires --message.")
    inventory = run_openclaw_channel_inventory(timeout=timeout, source=source, record_event=False)
    configured = inventory.get("configured_channels") if isinstance(inventory.get("configured_channels"), list) else []
    channel_configured = normalized_channel in configured
    summary = (
        f"Draft recorded for {normalized_channel}; no external send attempted. "
        f"channel_configured={'yes' if channel_configured else 'no'}."
    )
    payload = {
        "account": normalize_text_value(account, fallback="", limit=120),
        "reply_to": normalize_text_value(reply_to, fallback="", limit=180),
        "configured_channels": configured,
        "channel_configured": channel_configured,
        "sendable_without_new_admission": False,
        "required_send_gate": "Exact current approval plus configured channel/account/target.",
    }
    event = eve_openclaw_body.append_openclaw_channel_event(
        build_openclaw_channel_event(
            event_type="openclaw_channel_draft",
            status="drafted",
            summary=summary,
            ok=True,
            source=source,
            channel=normalized_channel,
            target=normalized_target,
            message=normalized_message,
            payload=payload,
            permission_level="draft_only",
            external_send_attempted=False,
        )
    )
    return {"ok": True, "event": event, "summary": summary, "inventory": inventory}


def run_openclaw_channel_pairing_inventory(
    *,
    channel: object,
    account: object = "",
    timeout: int = 30,
    source: str = "cli",
) -> Dict[str, object]:
    normalized_channel = normalize_text_value(channel, fallback="", limit=80)
    if normalized_channel not in OPENCLAW_CHANNEL_CHOICES:
        raise ValueError(f"Unsupported OpenClaw channel: {normalized_channel or 'unknown'}")
    command = ["pairing", "list", "--channel", normalized_channel, "--json"]
    normalized_account = normalize_text_value(account, fallback="", limit=120)
    if normalized_account:
        command.extend(["--account", normalized_account])
    command_result = eve_openclaw_body.run_openclaw_json_command(command, timeout=timeout)
    payload = command_result.get("payload") if isinstance(command_result.get("payload"), dict) else {}
    requests = payload.get("requests") if isinstance(payload, dict) else []
    if not isinstance(requests, list):
        requests = []
    ok = bool(command_result.get("ok"))
    summary = (
        f"OpenClaw pairing inventory checked for `{normalized_channel}`; "
        f"pending_requests={len(requests)}. No pairing requests approved."
    )
    if not ok:
        summary = str(command_result.get("stderr_excerpt") or command_result.get("error") or summary)
    event = eve_openclaw_body.append_openclaw_channel_event(
        build_openclaw_channel_event(
            event_type="openclaw_channel_pairing_inventory",
            status="ready" if ok else "degraded",
            summary=summary,
            ok=ok,
            source=source,
            channel=normalized_channel,
            payload={"command_result": command_result, "pending_request_count": len(requests)},
            permission_level="read_only",
            external_send_attempted=False,
        )
    )
    return {"ok": ok, "event": event, "summary": event["summary"], "pending_request_count": len(requests)}


def openclaw_command_looks_interactive(command_result: Dict[str, object]) -> bool:
    joined = " ".join(
        str(command_result.get(key) or "")
        for key in ("stdout_excerpt", "stderr_excerpt", "error")
    ).lower()
    return any(
        marker in joined
        for marker in (
            "install imessage plugin",
            "install plugin",
            "proceed?",
            "continue?",
            "press enter",
            "select",
            "confirm",
        )
    )


def run_openclaw_channel_directory_self(
    *,
    channel: object,
    account: object = "",
    timeout: int = 30,
    source: str = "cli",
) -> Dict[str, object]:
    normalized_channel = normalize_text_value(channel, fallback="", limit=80)
    if normalized_channel not in OPENCLAW_CHANNEL_CHOICES:
        raise ValueError(f"Unsupported OpenClaw channel: {normalized_channel or 'unknown'}")
    inventory = run_openclaw_channel_inventory(timeout=timeout, source=source, record_event=False)
    configured = inventory.get("configured_channels") if isinstance(inventory.get("configured_channels"), list) else []
    if normalized_channel not in configured:
        summary = f"OpenClaw channel `{normalized_channel}` is not configured; directory probe skipped."
        event = eve_openclaw_body.append_openclaw_channel_event(
            build_openclaw_channel_event(
                event_type="openclaw_channel_directory_self",
                status="blocked",
                summary=summary,
                ok=False,
                source=source,
                channel=normalized_channel,
                payload={"inventory": inventory},
                permission_level="read_only",
                external_send_attempted=False,
            )
        )
        return {"ok": False, "event": event, "summary": summary}
    command = ["directory", "self", "--channel", normalized_channel, "--json"]
    normalized_account = normalize_text_value(account, fallback="", limit=120)
    if normalized_account:
        command.extend(["--account", normalized_account])
    command_result = eve_openclaw_body.run_openclaw_json_command(command, timeout=timeout)
    prompt_like = openclaw_command_looks_interactive(command_result)
    ok = bool(command_result.get("ok")) and not prompt_like
    if ok:
        summary = f"OpenClaw directory self probe checked `{normalized_channel}` without sending or approving anything."
    elif prompt_like:
        summary = f"OpenClaw directory self probe for `{normalized_channel}` is interactive/gated; no directory data accepted."
    else:
        summary = str(command_result.get("stderr_excerpt") or command_result.get("error") or "OpenClaw directory self probe failed.")
    event = eve_openclaw_body.append_openclaw_channel_event(
        build_openclaw_channel_event(
            event_type="openclaw_channel_directory_self",
            status="ready" if ok else "degraded",
            summary=summary,
            ok=ok,
            source=source,
            channel=normalized_channel,
            payload={"inventory": inventory, "command_result": command_result, "interactive_prompt_detected": prompt_like},
            permission_level="read_only",
            external_send_attempted=False,
        )
    )
    return {"ok": ok, "event": event, "summary": event["summary"]}


def openclaw_channel_send_approval_ok(*, permission_request_id: str = "", use_trusted_directive: bool = False) -> Dict[str, object]:
    if permission_request_id:
        matches = [
            item
            for item in read_operator_permission_requests(limit=200, prefer_runtime=True)
            if str(item.get("id") or "") == permission_request_id
        ]
        if not matches:
            return {"ok": False, "reason": f"Permission request `{permission_request_id}` was not found."}
        request = matches[0]
        if request.get("status") != "approved":
            return {"ok": False, "reason": f"Permission request `{short_id(permission_request_id)}` is not approved."}
        if request.get("category") != "external_communication":
            return {"ok": False, "reason": f"Permission request `{short_id(permission_request_id)}` is not for external communication."}
        return {"ok": True, "mode": "permission_request", "permission_request_id": permission_request_id}
    if use_trusted_directive and operator_authorization_allows_trusted_directives():
        return {"ok": True, "mode": "trusted_operator_directive"}
    return {
        "ok": False,
        "reason": "External sends require an approved external_communication request or active trusted_operator_directive with --use-trusted-directive.",
    }


def run_openclaw_channel_send(
    *,
    channel: object,
    target: object,
    message: object,
    account: object = "",
    reply_to: object = "",
    permission_request_id: str = "",
    use_trusted_directive: bool = False,
    confirm_approved_send: bool = False,
    dry_run: bool = False,
    timeout: int = 30,
    source: str = "cli",
) -> Dict[str, object]:
    normalized_channel = normalize_text_value(channel, fallback="", limit=80)
    normalized_target = normalize_text_value(target, fallback="", limit=180)
    normalized_message = normalize_text_value(message, fallback="", limit=4000)
    if normalized_channel not in OPENCLAW_CHANNEL_CHOICES:
        raise ValueError(f"Unsupported OpenClaw channel: {normalized_channel or 'unknown'}")
    if not normalized_target:
        raise ValueError("OpenClaw channel send requires --target.")
    if not normalized_message:
        raise ValueError("OpenClaw channel send requires --message.")
    approval = openclaw_channel_send_approval_ok(
        permission_request_id=permission_request_id,
        use_trusted_directive=use_trusted_directive,
    )
    if not confirm_approved_send or not approval.get("ok"):
        reason = "Missing --confirm-approved-send." if not confirm_approved_send else str(approval.get("reason") or "Send approval missing.")
        event = eve_openclaw_body.append_openclaw_channel_event(
            build_openclaw_channel_event(
                event_type="openclaw_channel_send",
                status="blocked",
                summary=reason,
                ok=False,
                source=source,
                channel=normalized_channel,
                target=normalized_target,
                message=normalized_message,
                payload={"approval": approval, "dry_run": bool(dry_run)},
                permission_level="specific_approval_required",
                external_send_attempted=False,
            )
        )
        return {"ok": False, "event": event, "summary": reason}
    inventory = run_openclaw_channel_inventory(timeout=timeout, source=source, record_event=False)
    configured = inventory.get("configured_channels") if isinstance(inventory.get("configured_channels"), list) else []
    if normalized_channel not in configured:
        summary = f"OpenClaw channel `{normalized_channel}` is not configured; no external send attempted."
        event = eve_openclaw_body.append_openclaw_channel_event(
            build_openclaw_channel_event(
                event_type="openclaw_channel_send",
                status="blocked",
                summary=summary,
                ok=False,
                source=source,
                channel=normalized_channel,
                target=normalized_target,
                message=normalized_message,
                payload={"approval": approval, "configured_channels": configured, "dry_run": bool(dry_run)},
                permission_level="specific_approval_required",
                external_send_attempted=False,
            )
        )
        return {"ok": False, "event": event, "summary": summary}
    command = ["message", "send", "--channel", normalized_channel, "--target", normalized_target, "--message", normalized_message, "--json"]
    normalized_account = normalize_text_value(account, fallback="", limit=120)
    normalized_reply_to = normalize_text_value(reply_to, fallback="", limit=180)
    if normalized_account:
        command.extend(["--account", normalized_account])
    if normalized_reply_to:
        command.extend(["--reply-to", normalized_reply_to])
    if dry_run:
        command.append("--dry-run")
    command_result = eve_openclaw_body.run_openclaw_json_command(command, timeout=timeout)
    ok = bool(command_result.get("ok"))
    summary = "OpenClaw channel dry-run completed." if dry_run and ok else (
        "OpenClaw channel message sent." if ok else (
            command_result.get("stderr_excerpt") or command_result.get("stdout_excerpt") or "OpenClaw channel send failed."
        )
    )
    event = eve_openclaw_body.append_openclaw_channel_event(
        build_openclaw_channel_event(
            event_type="openclaw_channel_send",
            status="ready" if ok else "degraded",
            summary=str(summary),
            ok=ok,
            source=source,
            channel=normalized_channel,
            target=normalized_target,
            message=normalized_message,
            payload={"approval": approval, "command_result": command_result, "dry_run": bool(dry_run)},
            permission_level="specific_approval_required",
            external_send_attempted=not dry_run,
        )
    )
    return {"ok": ok, "event": event, "summary": event["summary"], "command_result": command_result}


def format_openclaw_channel_events(events: List[Dict[str, object]], *, full: bool = False) -> str:
    if not events:
        return "No OpenClaw channel events found."
    lines = ["OpenClaw channel events"]
    for event in events:
        channel = event.get("channel") or "inventory"
        lines.append(f"- {event.get('event_type')}: {channel} | {event.get('status')} | {event.get('summary')}")
        if full:
            if event.get("target"):
                lines.append(f"  target: {event.get('target')}")
            lines.append(f"  permission: {event.get('permission_level')}")
            lines.append(f"  external_send_attempted: {event.get('external_send_attempted')}")
    return "\n".join(lines)


