def openclaw_bootstrap_budget_report(workspace: Path) -> Dict[str, object]:
    files = ["AGENTS.md", "SOUL.md", "TOOLS.md", "IDENTITY.md", "USER.md", "HEARTBEAT.md", "BOOTSTRAP.md", "MEMORY.md"]
    records: List[Dict[str, object]] = []
    total = 0
    per_file_limit = 4000
    total_limit = 12000
    for name in files:
        path = workspace / name
        exists = path.exists()
        size = path.stat().st_size if exists else 0
        total += size
        records.append(
            {
                "name": name,
                "path": str(path),
                "exists": exists,
                "bytes": size,
                "within_per_file_limit": size <= per_file_limit,
            }
        )
    return {
        "ok": all(item["within_per_file_limit"] for item in records) and total <= total_limit,
        "per_file_limit": per_file_limit,
        "total_limit": total_limit,
        "total_bytes": total,
        "files": records,
    }


def build_openclaw_full_audit(
    *,
    timeout: int = 30,
    prefer_runtime: bool = False,
    record_channel_inventory: bool = False,
) -> Dict[str, object]:
    config = load_config()
    workspace = eve_openclaw.openclaw_workspace(config)
    status = eve_openclaw.collect_openclaw_status(
        config,
        prefer_runtime=prefer_runtime,
        include_gateway_probe=True,
        include_memory_probe=True,
    )
    eve_openclaw.save_openclaw_status(status)
    contracts = eve_openclaw_body.build_openclaw_body_contract_report(status)
    worker_events = eve_openclaw_body.read_openclaw_worker_events(limit=20, prefer_runtime=prefer_runtime)
    routine_events = eve_openclaw_body.read_openclaw_routine_events(limit=20, prefer_runtime=prefer_runtime)
    channel_events = eve_openclaw_body.read_openclaw_channel_events(limit=20, prefer_runtime=prefer_runtime)
    channel_inventory = run_openclaw_channel_inventory(
        timeout=timeout,
        source="audit",
        record_event=record_channel_inventory,
    )
    skills_result = eve_openclaw_body.run_openclaw_json_command(["skills", "list", "--json"], timeout=timeout)
    skills_payload = skills_result.get("payload") if isinstance(skills_result.get("payload"), dict) else {}
    skill_names = sorted(
        str(item.get("name") or "")
        for item in skills_payload.get("skills", [])
        if isinstance(item, dict) and str(item.get("name") or "").startswith("eve_")
    )
    required_skills = {
        "eve_capability_use",
        "eve_codex_independent_operator",
        "eve_control_home",
        "eve_external_channel_drafting",
        "eve_memory_wiki_reflection",
        "eve_organ_assimilation",
        "eve_personal_conversation",
        "eve_self_repair",
        "eve_system_sensing",
        "eve_task_followthrough",
    }
    missing_skills = sorted(required_skills.difference(skill_names))
    bootstrap = openclaw_bootstrap_budget_report(workspace)
    degraded_workers = [event for event in worker_events if str(event.get("status") or "") in {"degraded", "failed", "lost", "blocked"}]
    latest_routine_by_id: Dict[str, Dict[str, object]] = {}
    for event in routine_events:
        routine_id = normalize_text_value(event.get("routine_id"), fallback=str(event.get("id") or "unknown"), limit=120)
        current = latest_routine_by_id.get(routine_id)
        if current is None or str(event.get("created_at") or "") > str(current.get("created_at") or ""):
            latest_routine_by_id[routine_id] = event
    degraded_routines = [
        event
        for event in latest_routine_by_id.values()
        if str(event.get("status") or "") in {"degraded", "failed", "lost"}
    ]
    channel_send_risks = [
        event
        for event in channel_events
        if event.get("external_send_attempted") and not event.get("ok")
    ]
    channel_health_issues = (
        channel_inventory.get("channel_health_issues")
        if isinstance(channel_inventory.get("channel_health_issues"), list)
        else []
    )
    checks = {
        "status_ready": bool(status.get("gateway_reachable") and status.get("memory_status_ok")),
        "contracts_ready": len(contracts.get("contracts") or []) >= len(eve_openclaw_body.OPENCLAW_BODY_CONTRACT_ORDER),
        "workers_ready": not degraded_workers,
        "routines_ready": not degraded_routines,
        "channels_ready": bool(channel_inventory.get("ok")) and not channel_send_risks,
        "skills_ready": bool(skills_result.get("ok")) and not missing_skills,
        "bootstrap_ready": bool(bootstrap.get("ok")),
    }
    ok = all(checks.values())
    report = {
        "generated_at": utc_now(),
        "ok": ok,
        "status": "ready" if ok else "degraded",
        "summary": (
            "OpenClaw full integration audit passed."
            if ok
            else "OpenClaw full integration audit found degraded checks."
        ),
        "checks": checks,
        "workspace": str(workspace),
        "status_summary": status.get("summary"),
        "contracts_count": len(contracts.get("contracts") or []),
        "worker_events_checked": len(worker_events),
        "routine_events_checked": len(routine_events),
        "channel_events_checked": len(channel_events),
        "configured_channels": channel_inventory.get("configured_channels"),
        "eve_skills": skill_names,
        "missing_eve_skills": missing_skills,
        "bootstrap": bootstrap,
        "degraded_workers": degraded_workers[:5],
        "degraded_routines": degraded_routines[:5],
        "channel_health_issues": channel_health_issues[:5],
        "channel_send_risks": channel_send_risks[:5],
        "artifacts": {},
    }
    audit_dir = APP_DIR / "openclaw_full_audits"
    history_dir = audit_dir / "history"
    history_dir.mkdir(parents=True, exist_ok=True)
    latest_path = audit_dir / "latest.json"
    history_stamp = str(report["generated_at"]).replace(":", "-").replace("+", "-")
    history_path = history_dir / f"openclaw_full_audit-{history_stamp}.json"
    report["artifacts"] = {"latest": str(latest_path), "history": str(history_path)}
    eve_store.write_json_dict(latest_path, report, indent=2, sort_keys=False)
    eve_store.write_json_dict(history_path, report, indent=2, sort_keys=False)
    evidence_event = eve_openclaw_body.append_evidence_event(
        {
            "event_type": "openclaw_full_integration_audit",
            "source": "cli",
            "status": report["status"],
            "ok": ok,
            "summary": report["summary"],
            "payload": {
                "checks": checks,
                "latest": str(latest_path),
                "history": str(history_path),
                "configured_channels": channel_inventory.get("configured_channels"),
                "channel_health_issues": channel_health_issues[:5],
                "missing_eve_skills": missing_skills,
                "bootstrap_total_bytes": bootstrap.get("total_bytes"),
            },
        }
    )
    report["evidence_event_id"] = evidence_event.get("id")
    eve_store.write_json_dict(latest_path, report, indent=2, sort_keys=False)
    eve_store.write_json_dict(history_path, report, indent=2, sort_keys=False)
    return report


def format_openclaw_full_audit(report: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "OpenClaw full integration audit",
        f"status: {report.get('status')}",
        f"summary: {report.get('summary')}",
    ]
    checks = report.get("checks") if isinstance(report.get("checks"), dict) else {}
    for key, value in checks.items():
        lines.append(f"- {key}: {'ok' if value else 'degraded'}")
    lines.append(f"configured_channels: {len(report.get('configured_channels') or [])}")
    lines.append(f"eve_skills: {len(report.get('eve_skills') or [])}")
    bootstrap = report.get("bootstrap") if isinstance(report.get("bootstrap"), dict) else {}
    lines.append(f"bootstrap_bytes: {bootstrap.get('total_bytes')}/{bootstrap.get('total_limit')}")
    artifacts = report.get("artifacts") if isinstance(report.get("artifacts"), dict) else {}
    lines.append(f"latest_artifact: {artifacts.get('latest')}")
    lines.append(f"history_artifact: {artifacts.get('history')}")
    if full:
        if report.get("missing_eve_skills"):
            lines.append(f"missing_eve_skills: {', '.join(str(item) for item in report.get('missing_eve_skills') or [])}")
        if report.get("degraded_workers"):
            lines.append(f"degraded_workers: {len(report.get('degraded_workers') or [])}")
        if report.get("degraded_routines"):
            lines.append(f"degraded_routines: {len(report.get('degraded_routines') or [])}")
        if report.get("channel_health_issues"):
            lines.append(f"channel_health_issues: {len(report.get('channel_health_issues') or [])}")
        if report.get("channel_send_risks"):
            lines.append(f"channel_send_risks: {len(report.get('channel_send_risks') or [])}")
        lines.append(f"evidence_event_id: {report.get('evidence_event_id')}")
    return "\n".join(lines)


def cmd_openclaw_full_audit(args: argparse.Namespace) -> int:
    report = build_openclaw_full_audit(
        timeout=args.timeout,
        prefer_runtime=args.runtime,
        record_channel_inventory=bool(args.record_channel_inventory),
    )
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True))
    else:
        print(format_openclaw_full_audit(report, full=args.full))
    return 0 if report.get("ok") else 1


def cmd_openclaw_action(args: argparse.Namespace) -> int:
    config = load_config()
    try:
        plan = eve_openclaw_body.build_openclaw_action_plan(
            intent=args.intent or args.action or "OpenClaw status",
            requested_action=args.action or "",
            source="cli",
            include_sessions=bool(args.include_sessions),
        )
    except ValueError as exc:
        raise SystemExit(str(exc))
    result = execute_openclaw_action_plan(
        config,
        plan,
        timeout=args.timeout or int(config.get("openclaw_timeout_seconds") or 900),
        dry_run=bool(args.dry_run),
    )
    if args.json:
        print(json.dumps(result, indent=2, ensure_ascii=True))
    else:
        print(eve_openclaw_body.format_openclaw_action_result(result, full=args.full))
    return 0


def cmd_openclaw_contracts(args: argparse.Namespace) -> int:
    config = load_config()
    status = eve_openclaw.load_openclaw_status(prefer_runtime=True)
    if args.refresh_status:
        status = eve_openclaw.collect_openclaw_status(
            config,
            prefer_runtime=True,
            include_gateway_probe=True,
            include_memory_probe=True,
        )
        eve_openclaw.save_openclaw_status(status)
    report = eve_openclaw_body.build_openclaw_body_contract_report(status)
    if args.save:
        eve_openclaw_body.write_contract_report(report)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True))
    else:
        print(eve_openclaw_body.format_contract_report(report, full=args.full))
    return 0


def cmd_openclaw_evidence(args: argparse.Namespace) -> int:
    config = load_config()
    status = eve_openclaw.load_openclaw_status(prefer_runtime=True)
    sanitize_report = None
    if args.record_status:
        status = eve_openclaw.collect_openclaw_status(
            config,
            prefer_runtime=True,
            include_gateway_probe=True,
            include_memory_probe=True,
        )
        eve_openclaw.save_openclaw_status(status)
        event = eve_openclaw_body.build_status_evidence_event(status, source="manual_openclaw_evidence")
        eve_openclaw_body.append_evidence_event(event)
    if args.record_hook_event:
        hook_event_path = Path(args.record_hook_event).expanduser()
        try:
            raw_hook_event = json.loads(hook_event_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as exc:
            raise SystemExit(f"Could not read OpenClaw hook event JSON from {hook_event_path}: {exc}")
        if not isinstance(raw_hook_event, dict):
            raise SystemExit(f"OpenClaw hook event file must contain one JSON object: {hook_event_path}")
        event = eve_openclaw_body.build_hook_callback_event(raw_hook_event)
        eve_openclaw_body.append_evidence_event(event)
    if args.sanitize_existing_hooks:
        sanitize_report = eve_openclaw_body.sanitize_existing_hook_evidence_events()
    if args.ingest_activity:
        state_dir = Path(str(config.get("openclaw_state_dir") or eve_openclaw_body.DEFAULT_OPENCLAW_STATE_DIR)).expanduser()
        events = eve_openclaw_body.build_openclaw_activity_events(
            state_dir=state_dir,
            include_sessions=args.include_sessions,
            limit=args.activity_limit,
            command_timeout=args.activity_timeout,
        )
        for event in events:
            eve_openclaw_body.append_evidence_event(event)
    report = eve_openclaw_body.build_evidence_bridge_report(
        status,
        latest_limit=args.limit,
        prefer_runtime=args.runtime,
    )
    if sanitize_report is not None:
        report["sanitization"] = sanitize_report
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True))
    else:
        if sanitize_report is not None:
            print(
                "Sanitized OpenClaw hook evidence: "
                f"changed={sanitize_report.get('changed_records')} "
                f"checked={sanitize_report.get('checked_records')}"
            )
        print(eve_openclaw_body.format_evidence_report(report, full=args.full))
    return 0


