def parse_mcp_admission_tool(value: object) -> Dict[str, object]:
    if isinstance(value, dict):
        name = normalize_text_value(value.get("name"), fallback="", limit=120)
        risk_class = normalize_text_value(value.get("risk_class") or value.get("risk"), fallback="", limit=40).lower()
        description = normalize_text_value(value.get("description"), fallback="", limit=220)
    else:
        raw = str(value or "").strip()
        name = raw
        risk_class = ""
        description = ""
        for separator in (":", "="):
            if separator in raw:
                name, risk_class = raw.split(separator, 1)
                break
        name = normalize_text_value(name, fallback="", limit=120)
        risk_class = normalize_text_value(risk_class, fallback="", limit=40).lower()
    valid = bool(name) and risk_class in MCP_ADMISSION_ALLOWED_TOOL_RISKS
    return {
        "name": name,
        "risk_class": risk_class or "unknown",
        "description": description,
        "valid": valid,
    }


def normalize_mcp_admission_request(payload: Dict[str, object]) -> Dict[str, object]:
    raw_tools = payload.get("tools")
    if raw_tools is None:
        raw_tools = payload.get("tool") or []
    if isinstance(raw_tools, (str, dict)):
        raw_tool_values = [raw_tools]
    elif isinstance(raw_tools, list):
        raw_tool_values = raw_tools
    else:
        raw_tool_values = []
    tools = [parse_mcp_admission_tool(item) for item in raw_tool_values]
    tools = [item for item in tools if item.get("name")]
    candidate_type = normalize_text_value(payload.get("candidate_type"), fallback="mcp", limit=40).lower()
    permission_level = normalize_text_value(payload.get("permission_level"), fallback="pending_review", limit=80).lower()
    noninteractive_policy = normalize_text_value(payload.get("noninteractive_policy"), fallback="fail", limit=40).lower()
    candidate_id = normalize_text_value(payload.get("candidate_id"), fallback="", limit=120)
    source = normalize_text_value(payload.get("source"), fallback="", limit=260)
    purpose = normalize_text_value(payload.get("purpose") or payload.get("capability"), fallback="", limit=420)
    verification_command = normalize_text_value(payload.get("verification_command"), fallback="", limit=360)
    rollback = normalize_text_value(payload.get("rollback"), fallback="", limit=360)
    data_boundary = normalize_text_value(payload.get("data_boundary"), fallback="", limit=360)
    suggested_command = build_openclaw_admission_command(
        candidate_id=candidate_id,
        candidate_type=candidate_type,
        source=source,
        capability=purpose,
        permission_level=permission_level,
        data_boundary=data_boundary,
        verification_command=verification_command,
        rollback=rollback,
    )
    return {
        "candidate_id": candidate_id,
        "name": normalize_text_value(payload.get("name"), fallback=candidate_id, limit=160),
        "candidate_type": candidate_type,
        "source": source,
        "purpose": purpose,
        "permission_level": permission_level,
        "data_boundary": data_boundary,
        "filesystem_scope": normalize_text_value(payload.get("filesystem_scope"), fallback="", limit=360),
        "network_scope": normalize_text_value(payload.get("network_scope"), fallback="", limit=360),
        "credential_scope": normalize_text_value(payload.get("credential_scope"), fallback="", limit=360),
        "tools": tools,
        "logging_evidence": normalize_text_value(
            payload.get("logging_evidence"),
            fallback="",
            limit=360,
        ),
        "verification_command": verification_command,
        "rollback": rollback,
        "admission_record": normalize_text_value(
            payload.get("admission_record") or suggested_command,
            fallback="",
            limit=1200,
        ),
        "noninteractive_policy": noninteractive_policy,
        "owner_review": normalize_text_value(payload.get("owner_review"), fallback="codex_preflight", limit=220),
    }


def build_openclaw_admission_command(
    *,
    candidate_id: str,
    candidate_type: str,
    source: str,
    capability: str,
    permission_level: str,
    data_boundary: str,
    verification_command: str,
    rollback: str,
) -> str:
    if not candidate_id or not source or not capability:
        return ""
    parts = [
        "python3",
        "eve.py",
        "openclaw",
        "admission",
        "create",
        "--candidate-id",
        candidate_id,
        "--candidate-type",
        candidate_type or "mcp",
        "--source",
        source,
        "--capability",
        capability,
        "--permission-level",
        permission_level or "pending_review",
        "--data-boundary",
        data_boundary or "unknown",
        "--decision",
        "pending_review",
    ]
    if verification_command:
        parts.extend(["--verification-command", verification_command])
    if rollback:
        parts.extend(["--rollback", rollback])
    return " ".join(shlex.quote(part) for part in parts)


def evaluate_mcp_admission_request(payload: Dict[str, object]) -> Dict[str, object]:
    request_payload = normalize_mcp_admission_request(payload)
    missing: List[Dict[str, object]] = []
    blockers: List[Dict[str, object]] = []
    warnings: List[Dict[str, object]] = []
    checks: List[Dict[str, object]] = []
    for check in MCP_ADMISSION_DEFAULT_CHECKS:
        field = str(check["field"])
        value = request_payload.get(field)
        passed = bool(value)
        if field == "tools":
            tools = request_payload.get("tools")
            passed = bool(tools) and all(bool(item.get("valid")) for item in tools if isinstance(item, dict))
        if field == "admission_record":
            passed = bool(value)
        check_record = {
            "id": check["id"],
            "field": field,
            "label": check["label"],
            "required": bool(check["required"]),
            "passed": passed,
        }
        checks.append(check_record)
        if check_record["required"] and not passed:
            issue_field = str(check["id"]) if field == "tools" else field
            missing.append(action_contract_issue(issue_field, "missing_or_incomplete", received=value))

    candidate_type = str(request_payload.get("candidate_type") or "")
    if candidate_type != "mcp":
        blockers.append(action_contract_issue("candidate_type", "must_be_mcp_for_this_checklist", received=candidate_type))

    permission_level = str(request_payload.get("permission_level") or "")
    if permission_level not in MCP_ADMISSION_ALLOWED_PERMISSION_LEVELS:
        blockers.append(action_contract_issue("permission_level", "not_in_enum", received=permission_level))

    noninteractive_policy = str(request_payload.get("noninteractive_policy") or "")
    if noninteractive_policy != "fail":
        blockers.append(
            action_contract_issue(
                "noninteractive_policy",
                "must_fail_closed_for_eve_admission",
                received=noninteractive_policy,
            )
        )

    tools = [item for item in request_payload.get("tools") or [] if isinstance(item, dict)]
    invalid_tools = [item for item in tools if not item.get("valid")]
    for item in invalid_tools:
        blockers.append(action_contract_issue("tools", "tool_missing_valid_risk_class", received=item.get("name")))
    destructive_tools = [str(item.get("name") or "") for item in tools if item.get("risk_class") == "destructive"]
    if destructive_tools and permission_level not in {"specific_approval_required", "blocked"}:
        blockers.append(
            action_contract_issue(
                "permission_level",
                "destructive_tools_require_specific_approval_or_blocked",
                received=", ".join(destructive_tools),
            )
        )
    if permission_level in {"operator_safe", "approval_gated"}:
        warnings.append(
            action_contract_issue(
                "permission_level",
                "admission_checklist_does_not_enable_tool",
                received=permission_level,
            )
        )

    status = "ready_for_admission_record" if not missing and not blockers else "blocked"
    now = utc_now()
    report = {
        "schema_id": MCP_ADMISSION_SCHEMA_ID,
        "id": str(uuid.uuid4()),
        "checked_at": now,
        "status": status,
        "ok": status == "ready_for_admission_record",
        "enabled_for_eve": False,
        "adds_chat_lane": False,
        "body_bus_layer": "openclaw_body_bus",
        "candidate": request_payload,
        "checks": checks,
        "missing": missing,
        "blockers": blockers,
        "warnings": warnings,
        "next_steps": build_mcp_admission_next_steps(status, request_payload, missing, blockers),
        "artifacts": {
            "latest": str(MCP_ADMISSION_CHECKLIST_PATH),
            "audit_log": str(MCP_ADMISSION_AUDIT_LOG_PATH),
        },
    }
    return report


def build_mcp_admission_next_steps(
    status: str,
    request_payload: Dict[str, object],
    missing: List[Dict[str, object]],
    blockers: List[Dict[str, object]],
) -> List[str]:
    if status == "ready_for_admission_record":
        return [
            "Create or review the OpenClaw admission record with the suggested command before enabling any MCP surface.",
            "Run the verification command and keep the resulting evidence attached to the admission record.",
            "Keep the MCP tool disabled for Eve until a pending_review record is explicitly approved.",
        ]
    steps: List[str] = []
    if missing:
        fields = ", ".join(str(item.get("field")) for item in missing[:6])
        steps.append(f"Fill missing checklist fields: {fields}.")
    if blockers:
        fields = ", ".join(str(item.get("field")) for item in blockers[:6])
        steps.append(f"Resolve blocking policy issues: {fields}.")
    if request_payload.get("admission_record"):
        steps.append("Do not create or approve the OpenClaw admission record until the checklist is ready.")
    return steps or ["Complete the MCP admission checklist before adding any new tool authority."]


def write_mcp_admission_report(report: Dict[str, object]) -> None:
    eve_store.write_json_dict(MCP_ADMISSION_CHECKLIST_PATH, report, indent=2, sort_keys=False)
    audit = {
        "id": report.get("id") or str(uuid.uuid4()),
        "checked_at": report.get("checked_at") or utc_now(),
        "schema_id": report.get("schema_id") or MCP_ADMISSION_SCHEMA_ID,
        "status": report.get("status"),
        "ok": bool(report.get("ok")),
        "candidate_id": (report.get("candidate") or {}).get("candidate_id") if isinstance(report.get("candidate"), dict) else "",
        "source": (report.get("candidate") or {}).get("source") if isinstance(report.get("candidate"), dict) else "",
        "missing_count": len(report.get("missing") or []),
        "blocker_count": len(report.get("blockers") or []),
        "enabled_for_eve": False,
        "adds_chat_lane": False,
    }
    append_jsonl_record(MCP_ADMISSION_AUDIT_LOG_PATH, audit)
    mirror_store_file_to_runtime(MCP_ADMISSION_CHECKLIST_PATH)
    mirror_store_file_to_runtime(MCP_ADMISSION_AUDIT_LOG_PATH)


def format_mcp_admission_report(report: Dict[str, object], *, full: bool = False) -> str:
    candidate = report.get("candidate") if isinstance(report.get("candidate"), dict) else {}
    lines = [
        "MCP admission checklist",
        f"status: {report.get('status')}",
        f"candidate: {candidate.get('candidate_id') or 'unknown'}",
        f"enabled_for_eve: {bool(report.get('enabled_for_eve'))}",
        f"adds_chat_lane: {bool(report.get('adds_chat_lane'))}",
        f"missing: {len(report.get('missing') or [])}",
        f"blockers: {len(report.get('blockers') or [])}",
        f"artifact: {MCP_ADMISSION_CHECKLIST_PATH}",
    ]
    tools = candidate.get("tools") if isinstance(candidate.get("tools"), list) else []
    if tools:
        lines.append("tools:")
        for item in tools:
            if not isinstance(item, dict):
                continue
            lines.append(f"- {item.get('name')}: {item.get('risk_class')}")
    if report.get("next_steps"):
        lines.append("next:")
        for step in report.get("next_steps") or []:
            lines.append(f"- {step}")
    if full:
        if report.get("missing"):
            lines.append("missing_fields:")
            for issue in report.get("missing") or []:
                lines.append(f"- {issue.get('field')}: {issue.get('problem')}")
        if report.get("blockers"):
            lines.append("policy_blockers:")
            for issue in report.get("blockers") or []:
                lines.append(f"- {issue.get('field')}: {issue.get('problem')}")
        if candidate.get("admission_record"):
            lines.append(f"suggested_openclaw_admission: {candidate.get('admission_record')}")
    return "\n".join(lines)


def cmd_mcp_admission(args: argparse.Namespace) -> int:
    payload = {
        "candidate_id": args.candidate_id,
        "name": args.name,
        "candidate_type": args.candidate_type,
        "source": args.source,
        "purpose": args.purpose,
        "permission_level": args.permission_level,
        "data_boundary": args.data_boundary,
        "filesystem_scope": args.filesystem_scope,
        "network_scope": args.network_scope,
        "credential_scope": args.credential_scope,
        "tools": args.tool or [],
        "logging_evidence": args.logging_evidence,
        "verification_command": args.verification_command,
        "rollback": args.rollback,
        "admission_record": args.admission_record,
        "noninteractive_policy": args.noninteractive_policy,
        "owner_review": args.owner_review,
    }
    report = evaluate_mcp_admission_request(payload)
    write_mcp_admission_report(report)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True))
    else:
        print(format_mcp_admission_report(report, full=args.full))
    return 0 if report.get("ok") else 1


