def built_in_access_layer_from_lab_layer(layer: Dict[str, object]) -> Dict[str, object]:
    layer_id = str(layer.get("id") or "unknown")
    status = str(layer.get("status") or "unknown")
    blocker = normalize_text_value(layer.get("blocker"), fallback="", limit=320)
    live_now = parse_boolish(layer.get("live_now"))
    authority = BUILT_IN_ACCESS_AUTHORITY.get(layer_id, str(layer.get("authority") or "local_project"))
    canary_access = layer_id == "model_inference_acceleration_mtp" and status == "canary_passed"
    local_ready_status = status in {"live", "ready", "passed", "verified", "staged_live", "canary_passed", "lab_ready", "lab_available"}
    full_local_access = bool(live_now or (local_ready_status and not blocker) or canary_access)
    if canary_access:
        built_in_status = "built_in_canary"
    elif full_local_access:
        built_in_status = "built_in"
    else:
        built_in_status = "unavailable"

    not_automatic: List[str] = []
    if layer_id == "model_inference_acceleration_mtp":
        not_automatic.append("live resident lane routing")
    elif layer_id == "frontier_api_lab":
        not_automatic.append("hosted model-provider calls")
    elif layer_id == "hermes_learning":
        not_automatic.append("direct canonical memory writes")
    elif layer_id == "dagster_evidence_orchestration":
        not_automatic.append("recurring scheduler authority")
    elif layer_id == "beads_work_graph":
        not_automatic.append("canonical task authority")
    elif layer_id == "openclaw_body_bus":
        not_automatic.append("unadmitted external/device actions")

    return {
        "id": layer_id,
        "built_in_status": built_in_status,
        "full_local_access": full_local_access,
        "authority": authority,
        "source_status": status,
        "source_live_now": live_now,
        "canary_access": canary_access,
        "summary": layer.get("summary") or "",
        "evidence": layer.get("evidence") if isinstance(layer.get("evidence"), dict) else {},
        "source_blocker": blocker,
        "runtime_access": BUILT_IN_ACCESS_RUNTIME_COMMANDS.get(layer_id, []),
        "not_automatic": not_automatic,
        "next_action": layer.get("next_action") or "",
    }


def build_builtin_access_report(
    config: Dict[str, object],
    *,
    prefer_runtime: bool = True,
    include_probes: bool = True,
) -> Dict[str, object]:
    generated_at = utc_now()
    activation = build_lab_live_activation_report(
        config,
        prefer_runtime=prefer_runtime,
        include_probes=include_probes,
    )
    source_layers = activation.get("layers") if isinstance(activation.get("layers"), list) else []
    layers = [
        built_in_access_layer_from_lab_layer(layer)
        for layer in source_layers
        if isinstance(layer, dict)
    ]
    unavailable = [layer["id"] for layer in layers if not layer.get("full_local_access")]
    canary_layers = [layer["id"] for layer in layers if layer.get("canary_access")]
    full_local_count = len(layers) - len(unavailable)
    if unavailable:
        status = "partial_local_access"
    elif canary_layers:
        status = "full_local_access_with_canaries"
    else:
        status = "full_local_access"

    return {
        "schema_id": "eve_built_in_access.v1",
        "generated_at": generated_at,
        "status": status,
        "principle": "Built-in means Eve has a first-class local/project command path and provenance for the organ; it does not invent external access or silently promote routing.",
        "local_full_access": not unavailable,
        "full_local_access_count": full_local_count,
        "layer_count": len(layers),
        "unavailable_layers": unavailable,
        "canary_layers": canary_layers,
        "non_local_stop_lines": BUILT_IN_ACCESS_NON_LOCAL_STOP_LINES,
        "source_lab_live_status": activation.get("status"),
        "source_lab_live_blocking": activation.get("blocking") if isinstance(activation.get("blocking"), list) else [],
        "layers": layers,
        "next_action": (
            "Repair unavailable local organs, then rerun `python3 eve.py access status --runtime --full`."
            if unavailable
            else "Use this access report as Eve's built-in local organ map; promote canary/runtime routing only when the evidence fields prove it changed."
        ),
        "artifacts": {
            "latest": str(BUILT_IN_ACCESS_PATH),
            "source_lab_live": str(LAB_LIVE_ACTIVATION_PATH),
            "activation_doc": str(ROOT / "docs" / "LAB_LIVE_ACTIVATION_2026_05_07.md"),
        },
    }


def save_builtin_access_report(report: Dict[str, object]) -> None:
    ensure_store()
    eve_store.write_json_dict(BUILT_IN_ACCESS_PATH, report, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(BUILT_IN_ACCESS_PATH)


def format_builtin_access_report(report: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "Eve built-in access",
        f"status: {report.get('status') or 'unknown'}",
        f"local_access: {report.get('full_local_access_count') or 0}/{report.get('layer_count') or 0}",
        "unavailable: " + (", ".join(str(item) for item in report.get("unavailable_layers", [])) if report.get("unavailable_layers") else "none"),
        "canary_access: " + (", ".join(str(item) for item in report.get("canary_layers", [])) if report.get("canary_layers") else "none"),
        f"source_lab_live: {report.get('source_lab_live_status') or 'unknown'}",
        f"next: {report.get('next_action') or ''}",
    ]
    layers = report.get("layers") if isinstance(report.get("layers"), list) else []
    if full:
        lines.append("layer_details:")
        for layer in layers:
            if not isinstance(layer, dict):
                continue
            not_auto = ", ".join(str(item) for item in layer.get("not_automatic", [])) or "none"
            lines.append(
                f"- {layer.get('id')}: {layer.get('built_in_status')} | "
                f"full_local={'yes' if layer.get('full_local_access') else 'no'} | authority={layer.get('authority')}"
            )
            if layer.get("summary"):
                lines.append(f"  summary: {layer.get('summary')}")
            commands = layer.get("runtime_access") if isinstance(layer.get("runtime_access"), list) else []
            if commands:
                lines.append("  commands: " + " ; ".join(str(item) for item in commands[:3]))
            lines.append(f"  not_automatic: {not_auto}")
            if layer.get("source_blocker"):
                lines.append(f"  source_blocker: {layer.get('source_blocker')}")
    stop_lines = report.get("non_local_stop_lines") if isinstance(report.get("non_local_stop_lines"), list) else []
    if full and stop_lines:
        lines.append("non_local_stop_lines:")
        lines.extend(f"- {item}" for item in stop_lines)
    artifacts = report.get("artifacts") if isinstance(report.get("artifacts"), dict) else {}
    if artifacts:
        lines.append(f"artifact: {artifacts.get('latest')}")
    return "\n".join(lines)


def cmd_access_status(args: argparse.Namespace) -> int:
    config = load_config()
    report = build_builtin_access_report(
        config,
        prefer_runtime=bool(args.runtime),
        include_probes=not bool(args.no_probes),
    )
    if not bool(args.no_save):
        save_builtin_access_report(report)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True, sort_keys=False))
        return 0
    print(format_builtin_access_report(report, full=bool(args.full)))
    return 0 if report.get("local_full_access") else 1


def cmd_lab_live_status(args: argparse.Namespace) -> int:
    config = load_config()
    report = build_lab_live_activation_report(
        config,
        prefer_runtime=bool(args.runtime),
        include_probes=not bool(args.no_probes),
    )
    if not bool(args.no_save):
        save_lab_live_activation_report(report)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True, sort_keys=False))
        return 0
    print(format_lab_live_activation_report(report, full=bool(args.full)))
    return 0 if report.get("status") in {"passed", "live_with_gates"} else 1


def eval_gap_component_advice(component: str) -> Dict[str, str]:
    normalized = normalize_whole_system_missing_components([component])
    key = normalized[0] if normalized else "test_needed"
    fallback = EVAL_GAP_COMPONENT_ADVICE["test_needed"]
    advice = EVAL_GAP_COMPONENT_ADVICE.get(key, fallback)
    return {
        "component": key,
        "meaning": str(advice.get("meaning") or fallback["meaning"]),
        "repair_type": str(advice.get("repair_type") or fallback["repair_type"]),
        "recommended_command": str(advice.get("recommended_command") or fallback["recommended_command"]),
    }


def normalize_eval_gap_record(payload: Dict[str, object]) -> Dict[str, object]:
    status = normalize_whole_system_status(payload.get("status"))
    missing_components = normalize_whole_system_missing_components(payload.get("missing_components") or payload.get("missing_component") or [])
    if status != "passed" and not missing_components:
        missing_components = ["test_needed"]
    return {
        "id": normalize_text_value(payload.get("id"), fallback=str(uuid.uuid4()), limit=120),
        "created_at": normalize_text_value(payload.get("created_at") or payload.get("finished_at") or payload.get("timestamp"), fallback=utc_now(), limit=40),
        "eval_id": normalize_text_value(payload.get("eval_id"), fallback="", limit=120),
        "test_id": normalize_text_value(payload.get("test_id"), fallback="unknown", limit=120),
        "layer": normalize_text_value(payload.get("layer"), fallback="unknown", limit=80),
        "status": status,
        "missing_components": missing_components,
        "owner": normalize_whole_system_owner(payload.get("owner")),
        "next_action": normalize_text_value(payload.get("next_action"), fallback="", limit=260),
        "evidence": payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {},
    }


def eval_gap_priority(record: Dict[str, object]) -> str:
    status = normalize_whole_system_status(record.get("status"))
    components = set(normalize_whole_system_missing_components(record.get("missing_components") or []))
    layer = normalize_text_value(record.get("layer"), fallback="", limit=80)
    if status == "blocked" or components.intersection({"new_runtime_needed", "permission_needed", "human_decision_needed"}):
        return "critical"
    if status == "failed" or components.intersection({"new_model_needed", "tool_grounding_needed", "runtime_tuning_needed", "new_thread_needed"}):
        return "high"
    if layer in {"runtime_infrastructure", "model_lanes", "action_grounding"} and status in {"degraded", "inconclusive"}:
        return "high"
    if status in {"degraded", "inconclusive"} or components:
        return "medium"
    return "low"


def classify_eval_gap(record: Dict[str, object]) -> Dict[str, object]:
    normalized = normalize_eval_gap_record(record)
    primary_component = (normalized.get("missing_components") or ["test_needed"])[0]
    advice = eval_gap_component_advice(str(primary_component))
    classified = dict(normalized)
    classified.update(
        {
            "primary_missing_component": advice["component"],
            "priority": eval_gap_priority(normalized),
            "component_advice": advice["meaning"],
            "repair_type": advice["repair_type"],
            "recommended_command": advice["recommended_command"],
        }
    )
    return classified


def eval_gap_sort_key(record: Dict[str, object]) -> Tuple[int, float, str]:
    priority = str(record.get("priority") or eval_gap_priority(record))
    created_at = parse_iso_datetime(record.get("created_at"))
    newest_first = -(created_at.timestamp() if created_at else 0.0)
    return (EVAL_GAP_PRIORITY_ORDER.get(priority, 9), newest_first, str(record.get("test_id") or ""))


def filter_eval_gap_records(
    records: List[Dict[str, object]],
    *,
    status: Optional[str] = None,
    component: Optional[str] = None,
    owner: Optional[str] = None,
) -> List[Dict[str, object]]:
    status_filter = normalize_whole_system_status(status) if status else None
    component_filter = normalize_whole_system_missing_components([component])[0] if component else None
    owner_filter = normalize_whole_system_owner(owner) if owner else None
    filtered: List[Dict[str, object]] = []
    for record in records:
        normalized = normalize_eval_gap_record(record)
        if status_filter and normalized.get("status") != status_filter:
            continue
        if component_filter and component_filter not in normalized.get("missing_components", []):
            continue
        if owner_filter and normalized.get("owner") != owner_filter:
            continue
        filtered.append(normalized)
    return filtered


def latest_eval_gap_records(records: List[Dict[str, object]]) -> List[Dict[str, object]]:
    if not records:
        return []
    sorted_records = sorted(records, key=lambda item: str(item.get("created_at") or ""), reverse=True)
    latest_eval_id = next((str(item.get("eval_id") or "") for item in sorted_records if item.get("eval_id")), "")
    if latest_eval_id:
        return [item for item in sorted_records if str(item.get("eval_id") or "") == latest_eval_id]
    latest_created_at = str(sorted_records[0].get("created_at") or "")
    return [item for item in sorted_records if str(item.get("created_at") or "") == latest_created_at]


def eval_gap_superseded_by_latest_whole_system(record: Dict[str, object], latest_whole_system: Dict[str, object]) -> bool:
    if record.get("superseded_at"):
        return True
    test_id = normalize_text_value(record.get("test_id"), fallback="", limit=120)
    if not test_id:
        return False
    passed = {str(item) for item in latest_whole_system.get("passed_test_ids", []) if item}
    if test_id not in passed:
        return False
    latest_finished = parse_iso_datetime(latest_whole_system.get("finished_at"))
    created = parse_iso_datetime(record.get("created_at"))
    if latest_finished is not None and created is not None and created >= latest_finished:
        return False
    return True


def read_eval_gap_records(
    *,
    limit: Optional[int] = 20,
    since_days: Optional[int] = None,
    status: Optional[str] = None,
    component: Optional[str] = None,
    owner: Optional[str] = None,
    prefer_runtime: bool = False,
    latest_only: bool = True,
    suppress_superseded_by_latest: bool = False,
) -> List[Dict[str, object]]:
    read_path = resolve_store_read_path(EVAL_GAPS_PATH, prefer_runtime=prefer_runtime)
    records = [
        normalize_eval_gap_record(item)
        for item in filter_records_by_days(read_jsonl_records(read_path), "created_at", since_days)
        if not item.get("superseded_at")
    ]
    if suppress_superseded_by_latest:
        latest_whole_system = summarize_latest_whole_system_for_roadmap(prefer_runtime=prefer_runtime)
        records = [
            item
            for item in records
            if not eval_gap_superseded_by_latest_whole_system(item, latest_whole_system)
        ]
    records = filter_eval_gap_records(records, status=status, component=component, owner=owner)
    records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    if latest_only:
        records = latest_eval_gap_records(records)
    classified = [classify_eval_gap(item) for item in records]
    classified.sort(key=eval_gap_sort_key)
    if limit is not None:
        return classified[: max(0, limit)]
    return classified


def eval_gap_records_from_latest_whole_system(*, prefer_runtime: bool = False) -> List[Dict[str, object]]:
    record, _ = read_whole_system_json_artifact(WHOLE_SYSTEM_LATEST_EVAL_PATH, prefer_runtime=prefer_runtime)
    checks = record.get("checks") if isinstance(record.get("checks"), list) else []
    gaps: List[Dict[str, object]] = []
    for check in checks:
        if not isinstance(check, dict) or check.get("status") == "passed":
            continue
        gaps.append(
            normalize_eval_gap_record(
                {
                    "id": f"latest:{check.get('test_id') or uuid.uuid4()}",
                    "created_at": record.get("finished_at") or utc_now(),
                    "eval_id": record.get("id"),
                    "test_id": check.get("test_id"),
                    "layer": check.get("layer"),
                    "status": check.get("status"),
                    "missing_components": check.get("missing_components"),
                    "owner": check.get("owner"),
                    "next_action": check.get("next_action"),
                    "evidence": check.get("evidence") if isinstance(check.get("evidence"), dict) else {},
                }
            )
        )
    return gaps


def count_eval_gap_values(gaps: List[Dict[str, object]], field: str) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for gap in gaps:
        values = gap.get(field)
        items = values if isinstance(values, list) else [values]
        for value in items:
            text = normalize_text_value(value, fallback="", limit=100)
            if not text:
                continue
            counts[text] = counts.get(text, 0) + 1
    return dict(sorted(counts.items(), key=lambda item: (-item[1], item[0])))


def summarize_eval_gaps(gaps: List[Dict[str, object]]) -> Dict[str, object]:
    classified = [classify_eval_gap(item) for item in gaps]
    classified.sort(key=eval_gap_sort_key)
    return {
        "generated_at": utc_now(),
        "gap_count": len(classified),
        "latest_eval_id": next((str(item.get("eval_id") or "") for item in classified if item.get("eval_id")), ""),
        "component_counts": count_eval_gap_values(classified, "missing_components"),
        "owner_counts": count_eval_gap_values(classified, "owner"),
        "status_counts": count_eval_gap_values(classified, "status"),
        "priority_counts": count_eval_gap_values(classified, "priority"),
        "layer_counts": count_eval_gap_values(classified, "layer"),
        "top_next_actions": unique_compact([str(item.get("next_action") or "") for item in classified], limit=6),
        "gaps": classified,
    }


def format_eval_gap_summary(summary: Dict[str, object], *, full: bool = False) -> str:
    gaps = summary.get("gaps") if isinstance(summary.get("gaps"), list) else []
    lines = [
        "Eval gaps",
        f"records: {summary.get('gap_count') or 0}",
        f"eval_id: {summary.get('latest_eval_id') or 'unknown'}",
    ]
    for label, field in [
        ("components", "component_counts"),
        ("priorities", "priority_counts"),
        ("owners", "owner_counts"),
        ("statuses", "status_counts"),
    ]:
        counts = summary.get(field) if isinstance(summary.get(field), dict) else {}
        lines.append(f"{label}: " + (", ".join(f"{key}={value}" for key, value in counts.items()) if counts else "none"))
    top_next_actions = summary.get("top_next_actions") if isinstance(summary.get("top_next_actions"), list) else []
    if top_next_actions:
        lines.append("top_next_actions:")
        lines.extend(f"- {action}" for action in top_next_actions)
    if gaps:
        lines.append("gaps:")
        for gap in gaps if full else gaps[:8]:
            if not isinstance(gap, dict):
                continue
            missing = ", ".join(str(item) for item in (gap.get("missing_components") or [])) or "none"
            lines.append(f"- [{gap.get('priority')}] {gap.get('layer')}.{gap.get('test_id')} status={gap.get('status')} owner={gap.get('owner')} missing={missing}")
            if gap.get("next_action"):
                lines.append(f"  next: {gap.get('next_action')}")
            if full:
                lines.append(f"  means: {gap.get('component_advice')}")
                lines.append(f"  repair_type: {gap.get('repair_type')}")
                lines.append(f"  try: {gap.get('recommended_command')}")
    else:
        lines.append("No open evaluation gaps found.")
    return "\n".join(lines)


def roadmap_normalized_key(value: object, *, limit: int = 120) -> str:
    text = normalize_text_value(value, fallback="", limit=limit).lower()
    text = re.sub(r"[^a-z0-9]+", " ", text)
    return " ".join(text.split())


def roadmap_record_label(record: Dict[str, object], fields: List[str]) -> str:
    for field in fields:
        text = normalize_text_value(record.get(field), fallback="", limit=220)
        if text:
            return text
    return normalize_text_value(record.get("id"), fallback="unknown", limit=80)


def roadmap_record_text(record: Dict[str, object], fields: List[str]) -> str:
    parts = [normalize_text_value(record.get(field), fallback="", limit=220) for field in fields]
    return " ".join(part for part in parts if part)


def roadmap_duplicate_groups(
    records: List[Dict[str, object]],
    *,
    fields: List[str],
    limit: int = 8,
    key_overrides: Optional[Callable[[Dict[str, object]], str]] = None,
) -> List[Dict[str, object]]:
    groups: Dict[str, List[Dict[str, object]]] = {}
    for record in records:
        key = key_overrides(record) if key_overrides else roadmap_normalized_key(roadmap_record_label(record, fields))
        if not key:
            continue
        groups.setdefault(key, []).append(record)
    duplicates: List[Dict[str, object]] = []
    for key, items in groups.items():
        if len(items) < 2:
            continue
        duplicates.append(
            {
                "key": key,
                "count": len(items),
                "ids": [str(item.get("id") or "") for item in items[:8]],
                "sample": roadmap_record_label(items[-1], fields),
            }
        )
    duplicates.sort(key=lambda item: (-int(item.get("count") or 0), str(item.get("key") or "")))
    return duplicates[:limit]


def roadmap_capability_gap_key(record: Dict[str, object]) -> str:
    text = roadmap_record_text(record, ["goal", "commitment_text", "inbound_body", "draft_response"]).lower()
    text = " ".join(text.split())
    if "calendar" in text:
        return "calendar_control"
    if "slack" in text:
        return "slack_control"
    return roadmap_normalized_key(text, limit=140)


def roadmap_extract_section_items(text: str, heading: str, *, limit: int = 8) -> List[str]:
    pattern = re.compile(rf"^##\s+{re.escape(heading)}\s*$", re.MULTILINE)
    match = pattern.search(text)
    if not match:
        return []
    next_heading = re.search(r"^##\s+", text[match.end() :], flags=re.MULTILINE)
    section = text[match.end() : match.end() + next_heading.start()] if next_heading else text[match.end() :]
    items: List[str] = []
    for line in section.splitlines():
        stripped = line.strip()
        item_match = re.match(r"^(?:[-*]|\d+\.)\s+(.*)$", stripped)
        if not item_match:
            continue
        item = normalize_text_value(item_match.group(1), fallback="", limit=220)
        if item:
            items.append(item)
        if len(items) >= limit:
            break
    return items


def summarize_roadmap_doc(doc_id: str, title: str, path: Path) -> Dict[str, object]:
    if not path.exists():
        return {
            "id": doc_id,
            "title": title,
            "path": str(path),
            "status": "missing",
            "heading_count": 0,
            "active_mentions": 0,
            "next_items": [],
        }
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        return {
            "id": doc_id,
            "title": title,
            "path": str(path),
            "status": "unreadable",
            "error": str(exc),
            "heading_count": 0,
            "active_mentions": 0,
            "next_items": [],
        }
    headings = re.findall(r"^#{1,3}\s+(.+)$", text, flags=re.MULTILINE)
    next_items = roadmap_extract_section_items(text, "First Execution Slice", limit=8)
    if not next_items:
        next_items = roadmap_extract_section_items(text, "What To Build Next", limit=6)
    if not next_items:
        next_items = roadmap_extract_section_items(text, "Recommended Next Roadmap", limit=6)
    return {
        "id": doc_id,
        "title": title,
        "path": str(path),
        "status": "present",
        "heading_count": len(headings),
        "active_mentions": len(re.findall(r"\bactive\b", text, flags=re.IGNORECASE)),
        "next_items": next_items,
    }


def summarize_latest_whole_system_for_roadmap(*, prefer_runtime: bool = False) -> Dict[str, object]:
    record, path = read_whole_system_json_artifact(WHOLE_SYSTEM_LATEST_EVAL_PATH, prefer_runtime=prefer_runtime)
    checks = record.get("checks") if isinstance(record.get("checks"), list) else []
    failing = [item for item in checks if isinstance(item, dict) and item.get("status") != "passed"]
    passed_test_ids = [
        normalize_text_value(item.get("test_id"), fallback="", limit=120)
        for item in checks
        if isinstance(item, dict) and item.get("status") == "passed"
    ]
    failing_test_ids = [
        normalize_text_value(item.get("test_id"), fallback="", limit=120)
        for item in failing
        if isinstance(item, dict)
    ]
    return {
        "artifact": path,
        "status": record.get("status") or "missing",
        "average_score": record.get("average_score"),
        "finished_at": record.get("finished_at"),
        "check_count": record.get("check_count") or len(checks),
        "failing_check_count": record.get("failing_check_count") or len(failing),
        "passed_test_ids": [item for item in passed_test_ids if item],
        "failing_test_ids": [item for item in failing_test_ids if item],
        "top_next_actions": record.get("top_next_actions") if isinstance(record.get("top_next_actions"), list) else [],
    }


def roadmap_superseded_eval_gap_candidates(
    all_gaps: List[Dict[str, object]],
    latest_whole_system: Dict[str, object],
    *,
    limit: int = 8,
) -> List[Dict[str, object]]:
    candidates: List[Dict[str, object]] = []
    for gap in all_gaps:
        if gap.get("superseded_at"):
            continue
        if not eval_gap_superseded_by_latest_whole_system(gap, latest_whole_system):
            continue
        test_id = normalize_text_value(gap.get("test_id"), fallback="", limit=120)
        if not test_id:
            continue
        candidates.append(
            {
                "id": gap.get("id"),
                "test_id": test_id,
                "layer": gap.get("layer"),
                "created_at": gap.get("created_at"),
                "reason": "latest whole-system check now passes this test_id",
            }
        )
    candidates.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
    return candidates[:limit]


def roadmap_bucket_signals(
    bucket: Dict[str, object],
    *,
    eval_gaps: List[Dict[str, object]],
    capability_gaps: List[Dict[str, object]],
    duplicate_counts: Dict[str, int],
    stale_count: int,
    latest_whole_system: Dict[str, object],
) -> List[str]:
    keywords = [str(item).lower() for item in bucket.get("keywords", []) if str(item).strip()]
    signals: List[str] = []
    if bucket.get("priority") == 0:
        if stale_count:
            signals.append(f"{stale_count} older eval gap(s) look superseded by newer evidence")
        if duplicate_counts.get("proposal"):
            signals.append(f"{duplicate_counts['proposal']} duplicate proposal group(s)")
        if duplicate_counts.get("task"):
            signals.append(f"{duplicate_counts['task']} duplicate/open task group(s)")
    for gap in eval_gaps:
        haystack = " ".join(
            [
                str(gap.get("layer") or ""),
                str(gap.get("test_id") or ""),
                " ".join(str(item) for item in (gap.get("missing_components") or [])),
                str(gap.get("next_action") or ""),
            ]
        ).lower()
        if bucket.get("priority") == 4 and not any(
            token in haystack for token in ["tools_capabilities", "new_tool_needed", "permission_needed"]
        ):
            continue
        if any(keyword in haystack for keyword in keywords):
            signals.append(f"eval gap: {gap.get('layer')}.{gap.get('test_id')}")
    for gap in capability_gaps:
        haystack = roadmap_record_text(gap, ["goal", "commitment_text", "inbound_body"]).lower()
        if any(keyword in haystack for keyword in keywords):
            signals.append(f"capability gap: {gap.get('id')}")
    if bucket.get("priority") == 2 and latest_whole_system.get("status") in {"degraded", "failed", "blocked"}:
        signals.append(f"whole-system status: {latest_whole_system.get('status')}")
    return unique_compact(signals, limit=6)


def build_roadmap_eval_report(*, prefer_runtime: bool = False) -> Dict[str, object]:
    roadmap_docs = [summarize_roadmap_doc(doc_id, title, path) for doc_id, title, path in ROADMAP_SOURCE_DOCS]
    latest_whole_system = summarize_latest_whole_system_for_roadmap(prefer_runtime=prefer_runtime)
    latest_eval_gaps = read_eval_gap_records(
        limit=None,
        prefer_runtime=prefer_runtime,
        latest_only=True,
        suppress_superseded_by_latest=True,
    )
    all_eval_gaps = read_eval_gap_records(
        limit=None,
        prefer_runtime=prefer_runtime,
        latest_only=False,
        suppress_superseded_by_latest=True,
    )
    raw_eval_gaps = read_jsonl_records(resolve_store_read_path(EVAL_GAPS_PATH, prefer_runtime=prefer_runtime))
    capability_gaps = [
        item
        for item in read_capability_gaps(limit=None, prefer_runtime=prefer_runtime)
        if capability_gap_is_active(item)
    ]
    proposals = read_proposals(limit=None, prefer_runtime=prefer_runtime)
    active_proposals = [
        item
        for item in proposals
        if str(item.get("status") or "").lower() not in {"applied", "archived", "rejected"}
    ]
    open_tasks = read_system_tasks(
        limit=None,
        status=["planned", "in_progress", "blocked"],
        since_days=30,
        prefer_runtime=prefer_runtime,
    )
    proposal_duplicates = roadmap_duplicate_groups(active_proposals, fields=["title", "summary"])
    task_duplicates = roadmap_duplicate_groups(open_tasks, fields=["title", "summary"])
    capability_duplicates = roadmap_duplicate_groups(
        capability_gaps,
        fields=["goal", "commitment_text", "inbound_body"],
        key_overrides=roadmap_capability_gap_key,
    )
    superseded_candidates = roadmap_superseded_eval_gap_candidates(raw_eval_gaps, latest_whole_system)
    duplicate_counts = {
        "proposal": len(proposal_duplicates),
        "task": len(task_duplicates),
        "capability": len(capability_duplicates),
    }
    priority_queue = []
    for bucket in ROADMAP_PRIORITY_BUCKETS:
        signals = roadmap_bucket_signals(
            bucket,
            eval_gaps=latest_eval_gaps,
            capability_gaps=capability_gaps,
            duplicate_counts=duplicate_counts,
            stale_count=len(superseded_candidates),
            latest_whole_system=latest_whole_system,
        )
        status = "active" if signals else "watch"
        priority_queue.append(
            {
                "priority": bucket.get("priority"),
                "id": bucket.get("id"),
                "title": bucket.get("title"),
                "status": status,
                "signals": signals,
                "next_action": bucket.get("next_action"),
            }
        )
    priority_queue.sort(key=lambda item: int(item.get("priority") or 0))
    first_active = next((item for item in priority_queue if item.get("status") == "active"), priority_queue[0])
    warnings = []
    if proposal_duplicates:
        warnings.append(f"{len(proposal_duplicates)} duplicate proposal group(s) need merge/archive review")
    if task_duplicates:
        warnings.append(f"{len(task_duplicates)} duplicate/open task group(s) need merge/archive review")
    if capability_duplicates:
        warnings.append(f"{len(capability_duplicates)} duplicate capability-gap group(s) need staged merge")
    if superseded_candidates:
        warnings.append(f"{len(superseded_candidates)} older eval gap(s) may be superseded by current whole-system evidence")
    if latest_eval_gaps:
        warnings.append(f"{len(latest_eval_gaps)} latest eval gap(s) remain active")
    return {
        "schema_version": ROADMAP_EVAL_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "status": "degraded" if warnings else "passed",
        "recommended_first_priority": first_active,
        "roadmap_docs": roadmap_docs,
        "whole_system": latest_whole_system,
        "backlog": {
            "active_proposals": len(active_proposals),
            "open_system_tasks": len(open_tasks),
            "open_capability_gaps": len(capability_gaps),
            "latest_eval_gaps": len(latest_eval_gaps),
            "all_eval_gaps": len(all_eval_gaps),
        },
        "duplicates": {
            "proposals": proposal_duplicates,
            "system_tasks": task_duplicates,
            "capability_gaps": capability_duplicates,
        },
        "superseded_eval_gap_candidates": superseded_candidates,
        "priority_queue": priority_queue,
        "warnings": warnings,
        "next_commands": [
            "python3 eve.py eval roadmap --full",
            "python3 eve.py eval gaps --full",
            "python3 eve.py capabilities gaps --full",
            "python3 eve.py eval whole-system --full",
        ],
    }


def format_roadmap_eval_report(report: Dict[str, object], *, full: bool = False, limit: int = 8) -> str:
    backlog = report.get("backlog") if isinstance(report.get("backlog"), dict) else {}
    whole = report.get("whole_system") if isinstance(report.get("whole_system"), dict) else {}
    first = report.get("recommended_first_priority") if isinstance(report.get("recommended_first_priority"), dict) else {}
    lines = [
        "Roadmap eval",
        f"status: {report.get('status') or 'unknown'}",
        f"generated_at: {report.get('generated_at') or 'unknown'}",
        f"first_priority: P{first.get('priority')} {first.get('title') or 'unknown'}",
        f"whole_system: {whole.get('status') or 'missing'} avg={whole.get('average_score') if whole.get('average_score') is not None else 'n/a'}/5 failing={whole.get('failing_check_count') or 0}",
        (
            "backlog: "
            f"active_proposals={backlog.get('active_proposals') or 0}, "
            f"open_tasks={backlog.get('open_system_tasks') or 0}, "
            f"open_capability_gaps={backlog.get('open_capability_gaps') or 0}, "
            f"latest_eval_gaps={backlog.get('latest_eval_gaps') or 0}"
        ),
    ]
    warnings = report.get("warnings") if isinstance(report.get("warnings"), list) else []
    if warnings:
        lines.append("warnings:")
        lines.extend(f"- {warning}" for warning in warnings[:limit])
    priority_queue = report.get("priority_queue") if isinstance(report.get("priority_queue"), list) else []
    if priority_queue:
        lines.append("priority_queue:")
        for item in priority_queue:
            if not isinstance(item, dict):
                continue
            signals = item.get("signals") if isinstance(item.get("signals"), list) else []
            lines.append(f"- P{item.get('priority')} [{item.get('status')}] {item.get('title')}")
            if signals:
                lines.append(f"  signals: {'; '.join(str(signal) for signal in signals[:4])}")
            if full and item.get("next_action"):
                lines.append(f"  next: {item.get('next_action')}")
    duplicates = report.get("duplicates") if isinstance(report.get("duplicates"), dict) else {}
    if full:
        for label, field in [
            ("duplicate_proposals", "proposals"),
            ("duplicate_system_tasks", "system_tasks"),
            ("duplicate_capability_gaps", "capability_gaps"),
        ]:
            groups = duplicates.get(field) if isinstance(duplicates.get(field), list) else []
            if not groups:
                continue
            lines.append(f"{label}:")
            for group in groups[:limit]:
                ids = ", ".join(str(item) for item in (group.get("ids") or [])[:4])
                lines.append(f"- {group.get('key')} count={group.get('count')} ids={ids}")
                if group.get("sample"):
                    lines.append(f"  sample: {group.get('sample')}")
        superseded = report.get("superseded_eval_gap_candidates") if isinstance(report.get("superseded_eval_gap_candidates"), list) else []
        if superseded:
            lines.append("superseded_eval_gap_candidates:")
            for item in superseded[:limit]:
                lines.append(f"- {item.get('test_id')} gap={item.get('id')} created_at={item.get('created_at')}")
                if item.get("reason"):
                    lines.append(f"  reason: {item.get('reason')}")
        docs = report.get("roadmap_docs") if isinstance(report.get("roadmap_docs"), list) else []
        lines.append("roadmap_docs:")
        for doc in docs:
            if not isinstance(doc, dict):
                continue
            lines.append(f"- [{doc.get('status')}] {doc.get('title')} ({doc.get('path')})")
            next_items = doc.get("next_items") if isinstance(doc.get("next_items"), list) else []
            for next_item in next_items[:2]:
                lines.append(f"  item: {next_item}")
    next_commands = report.get("next_commands") if isinstance(report.get("next_commands"), list) else []
    if next_commands:
        lines.append("next_commands:")
        lines.extend(f"- {command}" for command in next_commands[:limit])
    return "\n".join(lines)


def roadmap_record_timestamp(record: Dict[str, object]) -> float:
    for field in ["updated_at", "created_at", "finished_at", "timestamp"]:
        parsed = parse_iso_datetime(record.get(field))
        if parsed is not None:
            return parsed.timestamp()
    return 0.0


def roadmap_status_active(record: Dict[str, object], inactive_statuses: Set[str]) -> bool:
    status = str(record.get("status") or "").strip().lower()
    return status not in inactive_statuses


def roadmap_cleanup_duplicate_groups(
    records: List[Dict[str, object]],
    *,
    fields: List[str],
    inactive_statuses: Set[str],
    key_overrides: Optional[Callable[[Dict[str, object]], str]] = None,
) -> List[Dict[str, object]]:
    grouped: Dict[str, List[Dict[str, object]]] = {}
    for record in records:
        if not roadmap_status_active(record, inactive_statuses):
            continue
        key = key_overrides(record) if key_overrides else roadmap_normalized_key(roadmap_record_label(record, fields))
        if not key:
            continue
        grouped.setdefault(key, []).append(record)
    groups: List[Dict[str, object]] = []
    for key, items in grouped.items():
        if len(items) < 2:
            continue
        canonical = max(
            items,
            key=lambda item: (
                roadmap_record_timestamp(item),
                str(item.get("id") or ""),
            ),
        )
        canonical_id = str(canonical.get("id") or "")
        archive_ids = [
            str(item.get("id") or "")
            for item in items
            if str(item.get("id") or "") and str(item.get("id") or "") != canonical_id
        ]
        if not archive_ids:
            continue
        groups.append(
            {
                "key": key,
                "count": len(items),
                "canonical_id": canonical_id,
                "archive_ids": archive_ids,
                "sample": roadmap_record_label(canonical, fields),
            }
        )
    groups.sort(key=lambda item: (-int(item.get("count") or 0), str(item.get("key") or "")))
    return groups


def roadmap_cleanup_summary(plan: Dict[str, object]) -> Dict[str, int]:
    proposal_groups = plan.get("proposal_duplicate_groups") if isinstance(plan.get("proposal_duplicate_groups"), list) else []
    task_groups = plan.get("system_task_duplicate_groups") if isinstance(plan.get("system_task_duplicate_groups"), list) else []
    capability_groups = plan.get("capability_gap_duplicate_groups") if isinstance(plan.get("capability_gap_duplicate_groups"), list) else []
    eval_candidates = plan.get("superseded_eval_gap_candidates") if isinstance(plan.get("superseded_eval_gap_candidates"), list) else []
    return {
        "proposal_groups": len(proposal_groups),
        "proposals_to_archive": sum(len(group.get("archive_ids") or []) for group in proposal_groups if isinstance(group, dict)),
        "system_task_groups": len(task_groups),
        "system_tasks_to_archive": sum(len(group.get("archive_ids") or []) for group in task_groups if isinstance(group, dict)),
        "capability_gap_groups": len(capability_groups),
        "capability_gaps_to_archive": sum(len(group.get("archive_ids") or []) for group in capability_groups if isinstance(group, dict)),
        "eval_gaps_to_supersede": len(eval_candidates),
    }


def build_roadmap_cleanup_plan(*, prefer_runtime: bool = False) -> Dict[str, object]:
    proposals = read_jsonl_records(resolve_store_read_path(PROPOSALS_PATH, prefer_runtime=prefer_runtime))
    system_tasks = read_jsonl_records(resolve_store_read_path(SYSTEM_TASKS_PATH, prefer_runtime=prefer_runtime))
    capability_gaps = [
        item
        for item in read_jsonl_records(resolve_store_read_path(CAPABILITY_GAPS_PATH, prefer_runtime=prefer_runtime))
        if not capability_gap_resolved_by_supported_action(item)
    ]
    eval_gaps = read_jsonl_records(resolve_store_read_path(EVAL_GAPS_PATH, prefer_runtime=prefer_runtime))
    latest_whole_system = summarize_latest_whole_system_for_roadmap(prefer_runtime=prefer_runtime)
    plan = {
        "schema_version": ROADMAP_EVAL_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "proposal_duplicate_groups": roadmap_cleanup_duplicate_groups(
            proposals,
            fields=["title", "summary"],
            inactive_statuses={"applied", "archived", "rejected"},
        ),
        "system_task_duplicate_groups": roadmap_cleanup_duplicate_groups(
            system_tasks,
            fields=["title", "summary"],
            inactive_statuses={"completed", "archived", "skipped"},
        ),
        "capability_gap_duplicate_groups": roadmap_cleanup_duplicate_groups(
            capability_gaps,
            fields=["goal", "commitment_text", "inbound_body"],
            inactive_statuses={"resolved", "completed", "archived", "rejected"},
            key_overrides=roadmap_capability_gap_key,
        ),
        "superseded_eval_gap_candidates": roadmap_superseded_eval_gap_candidates(
            eval_gaps,
            latest_whole_system,
            limit=200,
        ),
    }
    plan["summary"] = roadmap_cleanup_summary(plan)
    return plan


def roadmap_cleanup_group_lookup(groups: List[Dict[str, object]]) -> Tuple[Dict[str, str], Dict[str, str]]:
    archive_to_canonical: Dict[str, str] = {}
    archive_to_key: Dict[str, str] = {}
    for group in groups:
        if not isinstance(group, dict):
            continue
        canonical_id = str(group.get("canonical_id") or "")
        key = str(group.get("key") or "")
        for archive_id in group.get("archive_ids") or []:
            archive_to_canonical[str(archive_id)] = canonical_id
            archive_to_key[str(archive_id)] = key
    return archive_to_canonical, archive_to_key


def roadmap_archive_duplicate_records(
    path: Path,
    groups: List[Dict[str, object]],
    *,
    record_kind: str,
    result_field: Optional[str] = None,
    prefer_runtime: bool = False,
) -> int:
    archive_to_canonical, archive_to_key = roadmap_cleanup_group_lookup(groups)
    if not archive_to_canonical:
        return 0
    changed = 0
    now = utc_now()
    write_path = resolve_store_read_path(path, prefer_runtime=prefer_runtime)
    with store_lock(write_path):
        records = read_jsonl_records(write_path)
        for record in records:
            record_id = str(record.get("id") or "")
            canonical_id = archive_to_canonical.get(record_id)
            if not canonical_id:
                continue
            if str(record.get("status") or "").strip().lower() == "archived":
                continue
            metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
            record["status"] = "archived"
            record["updated_at"] = now
            record["archived_at"] = now
            record["archived_by"] = "roadmap_cleanup"
            record["merged_into"] = canonical_id
            record["metadata"] = {
                **metadata,
                "roadmap_cleanup_key": archive_to_key.get(record_id, ""),
                "merged_into": canonical_id,
                "archived_by": "roadmap_cleanup",
            }
            if result_field:
                record[result_field] = normalize_text_value(
                    record.get(result_field),
                    fallback=f"Archived duplicate {record_kind} into {canonical_id}.",
                    limit=320,
                )
            changed += 1
        write_jsonl_records(write_path, records)
    mirror_authoritative_store_file(write_path, path)
    return changed


def roadmap_supersede_eval_gap_records(candidates: List[Dict[str, object]], *, prefer_runtime: bool = False) -> int:
    candidate_ids = {str(item.get("id") or "") for item in candidates if isinstance(item, dict) and item.get("id")}
    if not candidate_ids:
        return 0
    candidate_by_id = {str(item.get("id") or ""): item for item in candidates if isinstance(item, dict)}
    changed = 0
    now = utc_now()
    write_path = resolve_store_read_path(EVAL_GAPS_PATH, prefer_runtime=prefer_runtime)
    with store_lock(write_path):
        records = read_jsonl_records(write_path)
        for record in records:
            record_id = str(record.get("id") or "")
            if record_id not in candidate_ids or record.get("superseded_at"):
                continue
            candidate = candidate_by_id.get(record_id, {})
            record["superseded_at"] = now
            record["superseded_by"] = "latest_whole_system_eval"
            record["superseded_reason"] = normalize_text_value(
                candidate.get("reason"),
                fallback="A newer whole-system check now passes this test_id.",
                limit=220,
            )
            changed += 1
        write_jsonl_records(write_path, records)
    mirror_authoritative_store_file(write_path, EVAL_GAPS_PATH)
    return changed


def apply_roadmap_cleanup_plan(plan: Dict[str, object], *, prefer_runtime: bool = False) -> Dict[str, object]:
    proposal_groups = plan.get("proposal_duplicate_groups") if isinstance(plan.get("proposal_duplicate_groups"), list) else []
    task_groups = plan.get("system_task_duplicate_groups") if isinstance(plan.get("system_task_duplicate_groups"), list) else []
    capability_groups = plan.get("capability_gap_duplicate_groups") if isinstance(plan.get("capability_gap_duplicate_groups"), list) else []
    eval_candidates = plan.get("superseded_eval_gap_candidates") if isinstance(plan.get("superseded_eval_gap_candidates"), list) else []
    applied = {
        "proposals_archived": roadmap_archive_duplicate_records(
            PROPOSALS_PATH,
            proposal_groups,
            record_kind="proposal",
            prefer_runtime=prefer_runtime,
        ),
        "system_tasks_archived": roadmap_archive_duplicate_records(
            SYSTEM_TASKS_PATH,
            task_groups,
            record_kind="system task",
            result_field="result_summary",
            prefer_runtime=prefer_runtime,
        ),
        "capability_gaps_archived": roadmap_archive_duplicate_records(
            CAPABILITY_GAPS_PATH,
            capability_groups,
            record_kind="capability gap",
            prefer_runtime=prefer_runtime,
        ),
        "eval_gaps_superseded": roadmap_supersede_eval_gap_records(eval_candidates, prefer_runtime=prefer_runtime),
    }
    audit_record = {
        "id": str(uuid.uuid4()),
        "timestamp": utc_now(),
        "source": "eval_roadmap_cleanup",
        "summary": applied,
        "plan_summary": plan.get("summary") if isinstance(plan.get("summary"), dict) else {},
        "plan": plan,
    }
    audit_path = resolve_store_read_path(ROADMAP_CLEANUP_AUDIT_LOG_PATH, prefer_runtime=prefer_runtime)
    append_jsonl_record(audit_path, audit_record)
    mirror_authoritative_store_file(audit_path, ROADMAP_CLEANUP_AUDIT_LOG_PATH)
    return applied


def format_roadmap_cleanup_plan(plan: Dict[str, object], *, applied: Optional[Dict[str, object]] = None, full: bool = False, limit: int = 8) -> str:
    summary = plan.get("summary") if isinstance(plan.get("summary"), dict) else {}
    mode = "applied" if applied is not None else "dry-run"
    lines = [
        "Roadmap cleanup",
        f"mode: {mode}",
        (
            "planned: "
            f"proposal_groups={summary.get('proposal_groups') or 0}, "
            f"proposals_to_archive={summary.get('proposals_to_archive') or 0}, "
            f"task_groups={summary.get('system_task_groups') or 0}, "
            f"tasks_to_archive={summary.get('system_tasks_to_archive') or 0}, "
            f"capability_gap_groups={summary.get('capability_gap_groups') or 0}, "
            f"capability_gaps_to_archive={summary.get('capability_gaps_to_archive') or 0}, "
            f"eval_gaps_to_supersede={summary.get('eval_gaps_to_supersede') or 0}"
        ),
    ]
    if applied is not None:
        lines.append(
            "applied: "
            + ", ".join(f"{key}={value}" for key, value in applied.items())
        )
    if full:
        for label, field in [
            ("proposal_duplicate_groups", "proposal_duplicate_groups"),
            ("system_task_duplicate_groups", "system_task_duplicate_groups"),
            ("capability_gap_duplicate_groups", "capability_gap_duplicate_groups"),
        ]:
            groups = plan.get(field) if isinstance(plan.get(field), list) else []
            if not groups:
                continue
            lines.append(f"{label}:")
            for group in groups[:limit]:
                archive_ids = ", ".join(str(item) for item in (group.get("archive_ids") or [])[:4])
                lines.append(
                    f"- {group.get('key')} keep={group.get('canonical_id')} archive={len(group.get('archive_ids') or [])} ids={archive_ids}"
                )
        candidates = plan.get("superseded_eval_gap_candidates") if isinstance(plan.get("superseded_eval_gap_candidates"), list) else []
        if candidates:
            lines.append("superseded_eval_gap_candidates:")
            for item in candidates[:limit]:
                lines.append(f"- {item.get('test_id')} gap={item.get('id')}")
    if applied is None:
        lines.append("Run with --apply to archive/mark these records. No records were changed.")
    return "\n".join(lines)


def tracker_stable_id(source_kind: str, source_id: object) -> str:
    key = f"eve-tracker:{source_kind}:{source_id}"
    return str(uuid.uuid5(uuid.NAMESPACE_URL, key))


def tracker_priority_label(value: object, fallback: str = "P3") -> str:
    text = str(value or "").strip().upper()
    if re.fullmatch(r"P[0-6]", text):
        return text
    try:
        number = int(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return fallback
    return f"P{max(0, min(6, number))}"


def tracker_eval_gap_priority(record: Dict[str, object]) -> str:
    priority = str(record.get("priority") or "").lower()
    return {
        "critical": "P0",
        "high": "P1",
        "medium": "P2",
        "low": "P4",
    }.get(priority, "P2")


def tracker_eval_gap_status(record: Dict[str, object]) -> str:
    status = str(record.get("status") or "").lower()
    if status == "blocked":
        return "blocked"
    if status in {"failed", "degraded"}:
        return "needs_fix"
    if status == "inconclusive":
        return "needs_evidence"
    if status == "passed":
        return "done"
    return status or "needs_review"


def tracker_item(
    *,
    source_kind: str,
    source_id: object,
    title: object,
    description: object = "",
    status: object = "todo",
    priority: object = "P3",
    lane: object = "",
    component: object = "",
    owner: object = "codex",
    labels: Optional[List[str]] = None,
    next_action: object = "",
    verification_command: object = "",
    source_path: object = "",
    source_paths: Optional[List[str]] = None,
    updated_at: object = "",
    evidence: Optional[Dict[str, object]] = None,
    external_refs: Optional[Dict[str, object]] = None,
    permission_boundary: object = "",
) -> Dict[str, object]:
    normalized_source_kind = normalize_text_value(source_kind, fallback="unknown", limit=80)
    normalized_source_id = normalize_text_value(source_id, fallback=normalized_source_kind, limit=180)
    return {
        "id": tracker_stable_id(normalized_source_kind, normalized_source_id),
        "schema_version": TRACKER_EXPORT_SCHEMA_VERSION,
        "source_kind": normalized_source_kind,
        "source_id": normalized_source_id,
        "title": normalize_text_value(title, fallback="Untitled tracker item", limit=180),
        "description": normalize_text_value(description, fallback="", limit=700),
        "status": normalize_text_value(status, fallback="todo", limit=60),
        "priority": tracker_priority_label(priority),
        "lane": normalize_text_value(lane, fallback="", limit=80),
        "component": normalize_text_value(component, fallback="", limit=120),
        "owner": normalize_text_value(owner, fallback="codex", limit=80),
        "labels": unique_compact(labels or [], limit=12),
        "next_action": normalize_text_value(next_action, fallback="", limit=360),
        "verification_command": normalize_text_value(verification_command, fallback="", limit=240),
        "source_path": normalize_text_value(source_path, fallback="", limit=260),
        "source_paths": unique_compact(source_paths or [], limit=8),
        "updated_at": normalize_text_value(updated_at, fallback=utc_now(), limit=40),
        "evidence": evidence or {},
        "external_refs": external_refs or {},
        "permission_boundary": normalize_text_value(permission_boundary, fallback="", limit=240),
    }


def tracker_items_from_roadmap(report: Dict[str, object]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    priority_queue = report.get("priority_queue") if isinstance(report.get("priority_queue"), list) else []
    for entry in priority_queue:
        if not isinstance(entry, dict):
            continue
        priority_number = int(entry.get("priority") or 0)
        signals = entry.get("signals") if isinstance(entry.get("signals"), list) else []
        items.append(
            tracker_item(
                source_kind="roadmap_priority",
                source_id=entry.get("id") or f"P{priority_number}",
                title=f"P{priority_number}: {entry.get('title') or 'Roadmap priority'}",
                description="; ".join(str(signal) for signal in signals[:8]),
                status="active" if entry.get("status") == "active" else "watch",
                priority=f"P{priority_number}",
                component=entry.get("id") or "",
                owner="codex",
                labels=["roadmap", f"p{priority_number}", str(entry.get("status") or "watch")],
                next_action=entry.get("next_action") or "",
                verification_command="python3 eve.py eval roadmap --full",
                source_path=str(ROOT / "docs" / "MASTER_ROADMAP.md"),
                updated_at=report.get("generated_at") or utc_now(),
                evidence={"signals": signals},
            )
        )
    return items


def tracker_items_from_eval_gaps(gaps: List[Dict[str, object]]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    for gap in gaps:
        test_id = normalize_text_value(gap.get("test_id"), fallback=str(gap.get("id") or "eval_gap"), limit=140)
        components = normalize_text_list(gap.get("missing_components"), limit=8)
        primary_component = normalize_text_value(gap.get("primary_missing_component"), fallback=(components[0] if components else ""), limit=100)
        items.append(
            tracker_item(
                source_kind="eval_gap",
                source_id=gap.get("id") or test_id,
                title=f"Fix eval gap: {test_id}",
                description=gap.get("component_advice") or gap.get("next_action") or "",
                status=tracker_eval_gap_status(gap),
                priority=tracker_eval_gap_priority(gap),
                component=normalize_text_value(gap.get("layer"), fallback=primary_component or "eval", limit=120),
                owner=gap.get("owner") or "codex",
                labels=["eval-gap", primary_component or "test_needed", str(gap.get("priority") or "medium")],
                next_action=gap.get("next_action") or "",
                verification_command=gap.get("recommended_command") or "python3 eve.py eval gaps --full",
                source_path=str(resolve_store_read_path(EVAL_GAPS_PATH, prefer_runtime=False)),
                updated_at=gap.get("created_at") or utc_now(),
                evidence={
                    "status": gap.get("status"),
                    "missing_components": components,
                    "repair_type": gap.get("repair_type"),
                },
            )
        )
    return items


def tracker_items_from_capability_gaps(gaps: List[Dict[str, object]]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    for gap in gaps:
        title = gap.get("goal") or gap.get("commitment_text") or "Capability gap"
        items.append(
            tracker_item(
                source_kind="capability_gap",
                source_id=gap.get("id") or title,
                title=f"Stage capability: {title}",
                description=gap.get("commitment_text") or gap.get("inbound_body") or "",
                status=gap.get("status") or "open",
                priority="P4",
                component=roadmap_capability_gap_key(gap) or "capability",
                owner="codex",
                labels=["capability-gap", "permissioned-tool"],
                next_action="Create or verify a bounded capability path before Eve claims completion.",
                verification_command="python3 eve.py capabilities gaps --full",
                source_path=str(resolve_store_read_path(CAPABILITY_GAPS_PATH, prefer_runtime=False)),
                updated_at=gap.get("updated_at") or gap.get("created_at") or utc_now(),
                evidence={
                    "proposal_id": gap.get("proposal_id"),
                    "source": gap.get("source"),
                    "known_tools": gap.get("known_tools") if isinstance(gap.get("known_tools"), list) else [],
                },
                permission_boundary="Capability work must remain staged, permissioned, and evidence-backed before live use.",
            )
        )
    return items


def tracker_items_from_system_tasks(tasks: List[Dict[str, object]]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    for task in tasks:
        priority_number = clamp_int(task.get("priority"), 3, minimum=1, maximum=5) - 1
        components = normalize_text_list(task.get("components"), limit=8)
        items.append(
            tracker_item(
                source_kind="system_task",
                source_id=task.get("id") or task.get("title"),
                title=task.get("title") or "System task",
                description=task.get("summary") or task.get("blocked_reason") or "",
                status=task.get("status") or "planned",
                priority=f"P{priority_number}",
                lane=task.get("lane") or "",
                component=components[0] if components else "",
                owner="eve",
                labels=["system-task", str(task.get("kind") or "task"), *(components[:4])],
                next_action=task.get("blocked_reason") or task.get("result_summary") or "",
                verification_command="python3 eve.py task list --full",
                source_path=str(SYSTEM_TASKS_PATH),
                updated_at=task.get("updated_at") or task.get("created_at") or utc_now(),
                evidence={"dedupe_key": task.get("dedupe_key"), "depends_on": task.get("depends_on") or []},
            )
        )
    return items


def tracker_items_from_proposals(proposals: List[Dict[str, object]]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    for proposal in proposals:
        metadata = proposal.get("metadata") if isinstance(proposal.get("metadata"), dict) else {}
        items.append(
            tracker_item(
                source_kind="proposal",
                source_id=proposal.get("id") or proposal.get("title"),
                title=proposal.get("title") or "Proposal",
                description=proposal.get("summary") or proposal.get("body") or "",
                status=proposal.get("status") or "draft",
                priority="P3",
                component=normalize_text_value(metadata.get("evidence_key"), fallback="", limit=120),
                owner="codex",
                labels=["proposal", str(proposal.get("status") or "draft")],
                next_action="Review, accept, archive, or convert into a verified system task.",
                verification_command="python3 eve.py proposal list --full",
                source_path=str(PROPOSALS_PATH),
                updated_at=proposal.get("updated_at") or proposal.get("created_at") or utc_now(),
                evidence={"source": proposal.get("source"), "metadata": metadata},
            )
        )
    return items


def tracker_items_from_research_lab_runs(runs: List[Dict[str, object]]) -> List[Dict[str, object]]:
    items: List[Dict[str, object]] = []
    latest_recovery_by_kind: Dict[str, str] = {}
    for run in runs:
        kind = str(run.get("kind") or "experiment")
        decision = str(run.get("decision") or "unknown")
        finished_at = str(run.get("finished_at") or "")
        if decision not in {"blocked", "discard"} and finished_at >= latest_recovery_by_kind.get(kind, ""):
            latest_recovery_by_kind[kind] = finished_at
    for run in runs:
        decision = str(run.get("decision") or "unknown")
        kind = str(run.get("kind") or "experiment")
        if decision in {"blocked", "discard"} and latest_recovery_by_kind.get(kind, "") > str(run.get("finished_at") or ""):
            continue
        priority = "P2" if decision in {"blocked", "discard"} else "P6"
        status = "needs_fix" if decision in {"blocked", "discard"} else "watch"
        title = f"Research lab: {kind} -> {decision}"
        items.append(
            tracker_item(
                source_kind="research_lab_run",
                source_id=run.get("id") or title,
                title=title,
                description=run.get("decision_reason") or run.get("hypothesis") or "",
                status=status,
                priority=priority,
                component="research_lab",
                owner="codex",
                labels=["research-lab", kind, decision],
                next_action=(
                    "Diagnose the failed command or regression before repeating this experiment."
                    if decision in {"blocked", "discard"}
                    else "Keep the result as lab evidence; only promote behavior after lane-specific/live verification."
                ),
                verification_command="python3 eve.py lab latest --full",
                source_path=str(RESEARCH_LAB_RESULTS_JSONL_PATH),
                updated_at=run.get("finished_at") or utc_now(),
                evidence={
                    "metric": run.get("metric"),
                    "score_delta": run.get("score_delta"),
                    "issue_delta": run.get("issue_delta"),
                    "artifacts": run.get("artifacts") if isinstance(run.get("artifacts"), dict) else {},
                },
                permission_boundary="Lab runs are bounded evidence; they cannot silently change live routing or install providers.",
            )
        )
    return items


def tracker_export_summary(items: List[Dict[str, object]]) -> Dict[str, object]:
    by_kind: Dict[str, int] = {}
    by_status: Dict[str, int] = {}
    by_priority: Dict[str, int] = {}
    for item in items:
        kind = str(item.get("source_kind") or "unknown")
        status = str(item.get("status") or "unknown")
        priority = str(item.get("priority") or "P3")
        by_kind[kind] = by_kind.get(kind, 0) + 1
        by_status[status] = by_status.get(status, 0) + 1
        by_priority[priority] = by_priority.get(priority, 0) + 1
    return {
        "total_items": len(items),
        "by_kind": dict(sorted(by_kind.items())),
        "by_status": dict(sorted(by_status.items())),
        "by_priority": dict(sorted(by_priority.items())),
    }


def build_tracker_export(*, prefer_runtime: bool = False, target: str = "local") -> Dict[str, object]:
    roadmap_report = build_roadmap_eval_report(prefer_runtime=prefer_runtime)
    latest_eval_gaps = read_eval_gap_records(
        limit=None,
        prefer_runtime=prefer_runtime,
        latest_only=True,
        suppress_superseded_by_latest=True,
    )
    capability_gaps = [
        item
        for item in read_capability_gaps(limit=None, prefer_runtime=prefer_runtime)
        if capability_gap_is_active(item)
    ]
    open_tasks = read_system_tasks(limit=None, status=["planned", "in_progress", "blocked"], since_days=30)
    active_proposals = [
        item
        for item in read_proposals(limit=None)
        if str(item.get("status") or "").lower() not in {"applied", "archived", "rejected"}
    ]
    research_lab_runs = read_research_lab_runs(limit=10, prefer_runtime=prefer_runtime)
    items: List[Dict[str, object]] = []
    items.extend(tracker_items_from_roadmap(roadmap_report))
    items.extend(tracker_items_from_eval_gaps(latest_eval_gaps))
    items.extend(tracker_items_from_capability_gaps(capability_gaps))
    items.extend(tracker_items_from_system_tasks(open_tasks))
    items.extend(tracker_items_from_proposals(active_proposals))
    items.extend(tracker_items_from_research_lab_runs(research_lab_runs))
    items.sort(key=lambda item: (str(item.get("priority") or "P9"), str(item.get("source_kind") or ""), str(item.get("title") or "")))
    first_priority = roadmap_report.get("recommended_first_priority") if isinstance(roadmap_report.get("recommended_first_priority"), dict) else {}
    return {
        "schema_version": TRACKER_EXPORT_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "target": normalize_text_value(target, fallback="local", limit=40),
        "source_of_truth": "Eve .eve state plus docs/MASTER_ROADMAP.md",
        "status": "ready",
        "external_sync": {
            "mode": "local_first",
            "configured": False,
            "note": "Use this artifact as the adapter boundary before connecting Plane, GitHub Projects, or OpenProject.",
        },
        "recommended_first_priority": first_priority,
        "summary": tracker_export_summary(items),
        "items": items,
        "artifacts": {
            "json": str(TRACKER_EXPORT_PATH),
            "jsonl": str(TRACKER_ITEMS_PATH),
        },
        "next_commands": [
            "python3 eve.py tracker export --full",
            "python3 eve.py lab latest --full",
            "python3 eve.py eval roadmap --full",
            "python3 eve.py eval gaps --full",
        ],
    }


def save_tracker_export(export: Dict[str, object]) -> Dict[str, str]:
    items = export.get("items") if isinstance(export.get("items"), list) else []
    export_payload = dict(export)
    export_payload["items"] = items
    eve_store.write_json_dict(TRACKER_EXPORT_PATH, export_payload)
    write_jsonl_records(TRACKER_ITEMS_PATH, [item for item in items if isinstance(item, dict)])
    mirror_store_file_to_runtime(TRACKER_EXPORT_PATH)
    mirror_store_file_to_runtime(TRACKER_ITEMS_PATH)
    return {"json": str(TRACKER_EXPORT_PATH), "jsonl": str(TRACKER_ITEMS_PATH)}


def format_tracker_export(export: Dict[str, object], *, full: bool = False, limit: int = 20) -> str:
    summary = export.get("summary") if isinstance(export.get("summary"), dict) else {}
    first = export.get("recommended_first_priority") if isinstance(export.get("recommended_first_priority"), dict) else {}
    artifacts = export.get("artifacts") if isinstance(export.get("artifacts"), dict) else {}
    lines = [
        "Tracker export",
        f"status: {export.get('status') or 'unknown'}",
        f"generated_at: {export.get('generated_at') or 'unknown'}",
        f"target: {export.get('target') or 'local'}",
        f"items: {summary.get('total_items') or 0}",
        f"first_priority: P{first.get('priority')} {first.get('title') or 'unknown'}",
        f"artifacts: {artifacts.get('json') or TRACKER_EXPORT_PATH}, {artifacts.get('jsonl') or TRACKER_ITEMS_PATH}",
    ]
    for label, key in [("by_kind", "by_kind"), ("by_status", "by_status"), ("by_priority", "by_priority")]:
        values = summary.get(key) if isinstance(summary.get(key), dict) else {}
        if values:
            lines.append(f"{label}: " + ", ".join(f"{name}={count}" for name, count in values.items()))
    items = export.get("items") if isinstance(export.get("items"), list) else []
    if items:
        lines.append("top_items:")
        for item in items[:limit]:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- {item.get('priority')} [{item.get('status')}] {item.get('title')} ({item.get('source_kind')})"
            )
            if full and item.get("next_action"):
                lines.append(f"  next: {item.get('next_action')}")
            if full and item.get("verification_command"):
                lines.append(f"  verify: {item.get('verification_command')}")
    lines.append("external_sync: local-first artifact is ready; no external tracker was modified.")
    return "\n".join(lines)


def tracker_external_priority(priority: object, *, target: str) -> str:
    label = tracker_priority_label(priority)
    if target == "plane":
        return {
            "P0": "urgent",
            "P1": "high",
            "P2": "medium",
            "P3": "medium",
            "P4": "low",
            "P5": "low",
            "P6": "none",
        }.get(label, "medium")
    if target == "openproject":
        return {
            "P0": "Immediate",
            "P1": "High",
            "P2": "Normal",
            "P3": "Normal",
            "P4": "Low",
            "P5": "Low",
            "P6": "Low",
        }.get(label, "Normal")
    return label


def tracker_external_state(status: object, *, target: str) -> str:
    normalized = normalize_text_value(status, fallback="todo", limit=60).lower()
    if normalized in {"active", "in_progress", "generating"}:
        return "In Progress"
    if normalized in {"blocked", "permission_needed"}:
        return "Blocked"
    if normalized in {"done", "passed", "completed", "applied", "resolved"}:
        return "Done"
    if normalized in {"watch", "draft", "planned", "needs_fix", "needs_evidence", "needs_review"}:
        return "Todo"
    return "Todo"


def tracker_operation_description(item: Dict[str, object]) -> str:
    parts = []
    if item.get("description"):
        parts.append(str(item.get("description")))
    if item.get("next_action"):
        parts.append(f"Next action: {item.get('next_action')}")
    if item.get("verification_command"):
        parts.append(f"Verification: `{item.get('verification_command')}`")
    if item.get("source_path"):
        parts.append(f"Source: `{item.get('source_path')}`")
    if item.get("permission_boundary"):
        parts.append(f"Permission boundary: {item.get('permission_boundary')}")
    parts.append(f"Eve tracker id: `{item.get('id')}`")
    parts.append(f"Eve source: `{item.get('source_kind')}:{item.get('source_id')}`")
    return "\n\n".join(parts)


def tracker_sync_operation(item: Dict[str, object], *, target: str, project: str) -> Dict[str, object]:
    labels = normalize_text_list(item.get("labels"), limit=12)
    normalized_target = target if target in TRACKER_SYNC_TARGETS else "local"
    base = {
        "operation": "upsert_issue",
        "external_key": f"eve:{item.get('id')}",
        "target": normalized_target,
        "project": project,
        "title": item.get("title"),
        "description": tracker_operation_description(item),
        "state": tracker_external_state(item.get("status"), target=normalized_target),
        "priority": tracker_external_priority(item.get("priority"), target=normalized_target),
        "labels": unique_compact([*(labels or []), f"eve-source:{item.get('source_kind')}"], limit=16),
        "source": {
            "tracker_id": item.get("id"),
            "source_kind": item.get("source_kind"),
            "source_id": item.get("source_id"),
            "source_path": item.get("source_path"),
        },
        "metadata": {
            "eve_priority": item.get("priority"),
            "eve_status": item.get("status"),
            "lane": item.get("lane"),
            "component": item.get("component"),
            "owner": item.get("owner"),
            "verification_command": item.get("verification_command"),
        },
    }
    if normalized_target == "plane":
        base["adapter_payload"] = {
            "name": item.get("title"),
            "description_html": html_escape(str(base["description"])).replace("\n", "<br>"),
            "priority": base["priority"],
            "state_name": base["state"],
            "labels": base["labels"],
            "external_id": base["external_key"],
        }
    elif normalized_target == "github":
        base["adapter_payload"] = {
            "title": item.get("title"),
            "body": base["description"],
            "labels": base["labels"],
            "metadata": base["metadata"],
        }
    elif normalized_target == "openproject":
        base["adapter_payload"] = {
            "subject": item.get("title"),
            "description": {"format": "markdown", "raw": base["description"]},
            "priority_name": base["priority"],
            "status_name": base["state"],
            "custom_fields": base["metadata"],
        }
    else:
        base["adapter_payload"] = {
            "title": item.get("title"),
            "description": base["description"],
            "status": item.get("status"),
            "priority": item.get("priority"),
            "labels": base["labels"],
        }
    return base


def build_tracker_sync_plan(
    *,
    target: str = "plane",
    project: str = "Eve Master Roadmap",
    prefer_runtime: bool = False,
    limit: Optional[int] = None,
    include_watch: bool = True,
) -> Dict[str, object]:
    normalized_target = target if target in TRACKER_SYNC_TARGETS else "local"
    export = build_tracker_export(prefer_runtime=prefer_runtime, target=normalized_target)
    raw_items = export.get("items") if isinstance(export.get("items"), list) else []
    items = [item for item in raw_items if isinstance(item, dict)]
    if not include_watch:
        items = [item for item in items if str(item.get("status") or "").lower() != "watch"]
    if limit is not None:
        items = items[: max(0, limit)]
    operations = [tracker_sync_operation(item, target=normalized_target, project=project) for item in items]
    auth_requirements = {
        "local": [],
        "plane": ["PLANE_API_KEY", "PLANE_WORKSPACE_SLUG", "PLANE_PROJECT_ID"],
        "github": ["GITHUB_TOKEN", "GITHUB_REPOSITORY"],
        "openproject": ["OPENPROJECT_BASE_URL", "OPENPROJECT_API_TOKEN", "OPENPROJECT_PROJECT_ID"],
    }
    available_auth = {
        name: bool(os.environ.get(name))
        for name in auth_requirements.get(normalized_target, [])
    }
    return {
        "schema_version": TRACKER_SYNC_SCHEMA_VERSION,
        "generated_at": utc_now(),
        "status": "dry_run_ready",
        "mode": "dry-run",
        "target": normalized_target,
        "project": project,
        "source_export_generated_at": export.get("generated_at"),
        "source_of_truth": export.get("source_of_truth"),
        "operation_count": len(operations),
        "auth_requirements": auth_requirements.get(normalized_target, []),
        "available_auth": available_auth,
        "external_write_enabled": False,
        "external_write_note": "This command intentionally writes local sync artifacts only. Add a target adapter and explicit credentials before external writes.",
        "artifacts": {
            "plan": str(TRACKER_SYNC_PLAN_PATH),
            "operations_jsonl": str(TRACKER_SYNC_ITEMS_PATH),
            "csv": str(TRACKER_SYNC_CSV_PATH),
        },
        "operations": operations,
        "summary": {
            "by_state": tracker_sync_count_by_field(operations, "state"),
            "by_priority": tracker_sync_count_by_field(operations, "priority"),
            "by_source_kind": tracker_sync_count_by_source_kind(operations),
        },
    }


def tracker_sync_count_by_field(operations: List[Dict[str, object]], field: str) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for operation in operations:
        value = normalize_text_value(operation.get(field), fallback="unknown", limit=80)
        counts[value] = counts.get(value, 0) + 1
    return dict(sorted(counts.items()))


def tracker_sync_count_by_source_kind(operations: List[Dict[str, object]]) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for operation in operations:
        source = operation.get("source") if isinstance(operation.get("source"), dict) else {}
        value = normalize_text_value(source.get("source_kind"), fallback="unknown", limit=80)
        counts[value] = counts.get(value, 0) + 1
    return dict(sorted(counts.items()))


def tracker_sync_csv_text(operations: List[Dict[str, object]]) -> str:
    output = io.StringIO()
    writer = csv.DictWriter(
        output,
        fieldnames=[
            "external_key",
            "title",
            "description",
            "state",
            "priority",
            "labels",
            "source_kind",
            "source_id",
            "verification_command",
        ],
    )
    writer.writeheader()
    for operation in operations:
        source = operation.get("source") if isinstance(operation.get("source"), dict) else {}
        metadata = operation.get("metadata") if isinstance(operation.get("metadata"), dict) else {}
        writer.writerow(
            {
                "external_key": operation.get("external_key") or "",
                "title": operation.get("title") or "",
                "description": operation.get("description") or "",
                "state": operation.get("state") or "",
                "priority": operation.get("priority") or "",
                "labels": ", ".join(str(label) for label in (operation.get("labels") or [])),
                "source_kind": source.get("source_kind") or "",
                "source_id": source.get("source_id") or "",
                "verification_command": metadata.get("verification_command") or "",
            }
        )
    return output.getvalue()


def save_tracker_sync_plan(plan: Dict[str, object]) -> Dict[str, str]:
    operations = plan.get("operations") if isinstance(plan.get("operations"), list) else []
    eve_store.write_json_dict(TRACKER_SYNC_PLAN_PATH, plan)
    write_jsonl_records(TRACKER_SYNC_ITEMS_PATH, [item for item in operations if isinstance(item, dict)])
    eve_store.atomic_write_text(TRACKER_SYNC_CSV_PATH, tracker_sync_csv_text([item for item in operations if isinstance(item, dict)]))
    mirror_store_file_to_runtime(TRACKER_SYNC_PLAN_PATH)
    mirror_store_file_to_runtime(TRACKER_SYNC_ITEMS_PATH)
    mirror_store_file_to_runtime(TRACKER_SYNC_CSV_PATH)
    return {
        "plan": str(TRACKER_SYNC_PLAN_PATH),
        "operations_jsonl": str(TRACKER_SYNC_ITEMS_PATH),
        "csv": str(TRACKER_SYNC_CSV_PATH),
    }


def format_tracker_sync_plan(plan: Dict[str, object], *, full: bool = False, limit: int = 20) -> str:
    summary = plan.get("summary") if isinstance(plan.get("summary"), dict) else {}
    artifacts = plan.get("artifacts") if isinstance(plan.get("artifacts"), dict) else {}
    lines = [
        "Tracker sync",
        f"status: {plan.get('status') or 'unknown'}",
        f"mode: {plan.get('mode') or 'dry-run'}",
        f"target: {plan.get('target') or 'unknown'}",
        f"project: {plan.get('project') or 'unknown'}",
        f"operations: {plan.get('operation_count') or 0}",
        f"artifacts: {artifacts.get('plan') or TRACKER_SYNC_PLAN_PATH}, {artifacts.get('operations_jsonl') or TRACKER_SYNC_ITEMS_PATH}, {artifacts.get('csv') or TRACKER_SYNC_CSV_PATH}",
        "external_write: disabled",
    ]
    auth_requirements = plan.get("auth_requirements") if isinstance(plan.get("auth_requirements"), list) else []
    if auth_requirements:
        available_auth = plan.get("available_auth") if isinstance(plan.get("available_auth"), dict) else {}
        auth_status = ", ".join(f"{name}={'set' if available_auth.get(name) else 'missing'}" for name in auth_requirements)
        lines.append(f"auth: {auth_status}")
    for label, key in [("by_state", "by_state"), ("by_priority", "by_priority"), ("by_source_kind", "by_source_kind")]:
        values = summary.get(key) if isinstance(summary.get(key), dict) else {}
        if values:
            lines.append(f"{label}: " + ", ".join(f"{name}={count}" for name, count in values.items()))
    operations = plan.get("operations") if isinstance(plan.get("operations"), list) else []
    if operations:
        lines.append("top_operations:")
        for operation in operations[:limit]:
            if not isinstance(operation, dict):
                continue
            lines.append(f"- {operation.get('operation')} {operation.get('priority')} [{operation.get('state')}] {operation.get('title')}")
            if full:
                lines.append(f"  key: {operation.get('external_key')}")
                metadata = operation.get("metadata") if isinstance(operation.get("metadata"), dict) else {}
                if metadata.get("verification_command"):
                    lines.append(f"  verify: {metadata.get('verification_command')}")
    lines.append("note: no external tracker was modified; this is a bounded one-way sync plan.")
    return "\n".join(lines)


def model_suitability_float(value: object, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def model_suitability_signal(
    *,
    signal_id: str,
    severity: str,
    category: str,
    summary: str,
    evidence: Optional[Dict[str, object]] = None,
    recommendation: str,
) -> Dict[str, object]:
    normalized_severity = severity if severity in MODEL_SUITABILITY_SIGNAL_ORDER else "info"
    return {
        "id": signal_id,
        "severity": normalized_severity,
        "category": normalize_text_value(category, fallback="more_evidence", limit=80),
        "summary": normalize_text_value(summary, fallback="", limit=260),
        "evidence": evidence or {},
        "recommendation": normalize_text_value(recommendation, fallback="", limit=260),
    }


def model_suitability_signal_sort_key(signal: Dict[str, object]) -> Tuple[int, str]:
    return (
        MODEL_SUITABILITY_SIGNAL_ORDER.get(str(signal.get("severity") or "info"), 9),
        str(signal.get("id") or ""),
    )


def build_model_suitability_lane_inventory(
    config: Dict[str, object],
    watchdog: Dict[str, object],
    exercise: Dict[str, object],
    bakeoff: Dict[str, object],
) -> List[Dict[str, object]]:
    loaded_models = watchdog.get("loaded_models") if isinstance(watchdog.get("loaded_models"), list) else []
    loaded_by_name = {
        normalize_model_name(item.get("name")): item
        for item in loaded_models
        if isinstance(item, dict) and normalize_model_name(item.get("name"))
    }
    probes = watchdog.get("probes") if isinstance(watchdog.get("probes"), dict) else {}
    exercise_lanes = exercise.get("lanes") if isinstance(exercise.get("lanes"), list) else []
    exercise_by_lane = {
        normalize_text_value(item.get("lane"), fallback="", limit=80): item
        for item in exercise_lanes
        if isinstance(item, dict)
    }
    bakeoff_totals = bakeoff.get("totals") if isinstance(bakeoff.get("totals"), dict) else {}
    profile_specs = {
        str(spec.get("profile") or ""): spec
        for spec in llama_cpp_profile_specs(config)
    }
    lanes: List[Dict[str, object]] = []
    for lane_record in model_lane_records(config, watchdog_status=watchdog):
        profile = normalize_text_value(lane_record.get("lane"), fallback="unknown", limit=80)
        substrate_profile = normalize_text_value(
            lane_record.get("substrate_profile"), fallback=profile, limit=80
        )
        spec = profile_specs.get(substrate_profile, {})
        alias = normalize_model_name(lane_record.get("model")) or profile
        loaded = loaded_by_name.get(alias) if isinstance(loaded_by_name.get(alias), dict) else {}
        probe = probes.get(alias) if isinstance(probes.get(alias), dict) else {}
        exercise_lane = exercise_by_lane.get(profile) if isinstance(exercise_by_lane.get(profile), dict) else {}
        bakeoff_total = bakeoff_totals.get(alias) if isinstance(bakeoff_totals.get(alias), dict) else {}
        lanes.append(
            {
                "profile": profile,
                "model": alias,
                "nominal_model": lane_record.get("nominal_model"),
                "topology_mode": lane_record.get("topology_mode"),
                "substrate_profile": substrate_profile,
                "shared_substrate_lanes": lane_record.get("shared_substrate_lanes"),
                "host": lane_record.get("host") or spec.get("host"),
                "ctx_size": spec.get("ctx_size"),
                "threads": spec.get("threads"),
                "threads_batch": spec.get("threads_batch"),
                "ubatch_size": spec.get("ubatch_size"),
                "cache_reuse": spec.get("cache_reuse"),
                "parallel_slots": spec.get("parallel_slots"),
                "loaded": bool(loaded),
                "size_vram_bytes": loaded.get("size_vram") if isinstance(loaded, dict) else None,
                "probe_ok": parse_boolish(probe.get("ok")) if probe else None,
                "probe_signal": normalize_text_value(probe.get("signal"), fallback="", limit=80) if probe else "",
                "probe_wall_ms": probe.get("wall_ms") if probe else None,
                "exercise_status": normalize_text_value(exercise_lane.get("status"), fallback="", limit=80) if exercise_lane else "",
                "exercise_duration_ms": exercise_lane.get("duration_ms") if exercise_lane else None,
                "bakeoff_total_score": bakeoff_total.get("total_score") if bakeoff_total else None,
                "bakeoff_failures": bakeoff_total.get("failures") if bakeoff_total else None,
                "bakeoff_avg_duration_ms": bakeoff_total.get("avg_duration_ms") if bakeoff_total else None,
            }
        )
    return lanes


def summarize_model_suitability_gaps(gaps: List[Dict[str, object]]) -> Dict[str, int]:
    counts: Dict[str, int] = {}
    for gap in gaps:
        for component in gap.get("missing_components", []) if isinstance(gap.get("missing_components"), list) else []:
            text = normalize_text_value(component, fallback="", limit=80)
            if text:
                counts[text] = counts.get(text, 0) + 1
    return dict(sorted(counts.items(), key=lambda item: (-item[1], item[0])))


def build_model_suitability_signals(
    *,
    watchdog: Dict[str, object],
    exercise: Dict[str, object],
    bakeoff: Dict[str, object],
    gaps: List[Dict[str, object]],
    lanes: List[Dict[str, object]],
) -> List[Dict[str, object]]:
    signals: List[Dict[str, object]] = []
    gap_counts = summarize_model_suitability_gaps(gaps)

    if not watchdog:
        signals.append(
            model_suitability_signal(
                signal_id="watchdog.missing",
                severity="high",
                category="more_evidence",
                summary="No model watchdog artifact was available.",
                evidence={},
                recommendation="Run the model watchdog or `python3 eve.py model exercise --full` before changing models.",
            )
        )
    else:
        unloaded = [lane for lane in lanes if not lane.get("loaded")]
        if unloaded:
            signals.append(
                model_suitability_signal(
                    signal_id="watchdog.unloaded_lanes",
                    severity="high",
                    category="runtime_tuning",
                    summary=f"{len(unloaded)} configured lane(s) are not resident.",
                    evidence={"lanes": [lane.get("profile") for lane in unloaded]},
                    recommendation="Restart/reprobe llama.cpp lanes before changing model sizes.",
                )
            )
        failed_probes = [lane for lane in lanes if lane.get("probe_ok") is False]
        if failed_probes:
            signals.append(
                model_suitability_signal(
                    signal_id="watchdog.failed_probes",
                    severity="high",
                    category="runtime_tuning",
                    summary=f"{len(failed_probes)} lane probe(s) failed or returned empty output.",
                    evidence={"lanes": [lane.get("profile") for lane in failed_probes], "signals": {str(lane.get("profile")): lane.get("probe_signal") for lane in failed_probes}},
                    recommendation="Fix probe/runtime reliability first; an empty probe is not evidence that Eve needs a bigger model.",
                )
            )
        slow_probes = [lane for lane in lanes if model_suitability_float(lane.get("probe_wall_ms")) > 5000 and lane.get("probe_ok") is not False]
        if slow_probes:
            signals.append(
                model_suitability_signal(
                    signal_id="watchdog.slow_probes",
                    severity="medium",
                    category="runtime_tuning",
                    summary=f"{len(slow_probes)} successful probe(s) are slower than 5s.",
                    evidence={"lanes": {str(lane.get("profile")): lane.get("probe_wall_ms") for lane in slow_probes}},
                    recommendation="Tune cache/context/runtime knobs before increasing model size.",
                )
            )

    if not exercise:
        signals.append(
            model_suitability_signal(
                signal_id="exercise.missing",
                severity="medium",
                category="more_evidence",
                summary="No all-lane model exercise artifact was available.",
                evidence={},
                recommendation="Run `python3 eve.py model exercise --full` before moving live routes.",
            )
        )
    else:
        if not exercise.get("passed"):
            signals.append(
                model_suitability_signal(
                    signal_id="exercise.not_passed",
                    severity="high",
                    category="model_routing",
                    summary="The latest all-lane model exercise did not pass cleanly.",
                    evidence={"summary": exercise.get("summary"), "errors": exercise.get("errors") if isinstance(exercise.get("errors"), list) else []},
                    recommendation="Repair lane routing or prompt contracts before trying a larger model.",
                )
            )
        slow_exercise_lanes = [lane for lane in lanes if model_suitability_float(lane.get("exercise_duration_ms")) > 15000]
        if slow_exercise_lanes:
            signals.append(
                model_suitability_signal(
                    signal_id="exercise.slow_lanes",
                    severity="medium",
                    category="smaller_faster_model",
                    summary=f"{len(slow_exercise_lanes)} exercised lane(s) took longer than 15s.",
                    evidence={"lanes": {str(lane.get("profile")): lane.get("exercise_duration_ms") for lane in slow_exercise_lanes}},
                    recommendation="Trial smaller/faster candidates for hot-path lanes while keeping eve-deep large.",
                )
            )

    if not bakeoff:
        signals.append(
            model_suitability_signal(
                signal_id="bakeoff.missing",
                severity="medium",
                category="more_evidence",
                summary="No model bakeoff artifact was available.",
                evidence={},
                recommendation="Run `python3 eve.py model bakeoff --full` before swapping live lane models.",
            )
        )
    else:
        totals = bakeoff.get("totals") if isinstance(bakeoff.get("totals"), dict) else {}
        baseline = normalize_model_name(bakeoff.get("baseline_model"))
        winner = normalize_model_name(bakeoff.get("winner"))
        failures = sum(int(model_suitability_float(item.get("failures"))) for item in totals.values() if isinstance(item, dict))
        if failures:
            signals.append(
                model_suitability_signal(
                    signal_id="bakeoff.failures",
                    severity="high",
                    category="prompt_or_schema",
                    summary=f"The latest bakeoff had {failures} failure(s).",
                    evidence={"totals": totals},
                    recommendation="Fix schema/prompt reliability before using bakeoff scores as model-selection evidence.",
                )
            )
        elif baseline and winner and winner != baseline:
            winner_score = model_suitability_float((totals.get(winner) or {}).get("total_score")) if isinstance(totals.get(winner), dict) else 0.0
            baseline_score = model_suitability_float((totals.get(baseline) or {}).get("total_score")) if isinstance(totals.get(baseline), dict) else 0.0
            if winner_score - baseline_score >= 3:
                signals.append(
                    model_suitability_signal(
                        signal_id="bakeoff.candidate_won",
                        severity="medium",
                        category="new_model_candidate",
                        summary=f"{winner} beat baseline {baseline} by {winner_score - baseline_score:.0f} point(s).",
                        evidence={"winner": winner, "baseline": baseline, "totals": totals},
                        recommendation="Run a larger bakeoff on real failing prompts before changing live routing.",
                    )
                )
        elif baseline and winner == baseline:
            signals.append(
                model_suitability_signal(
                    signal_id="bakeoff.baseline_holds",
                    severity="info",
                    category="keep_current",
                    summary=f"Baseline {baseline} held the latest bakeoff.",
                    evidence={"winner": winner, "totals": totals},
                    recommendation="Do not swap models without a fresher candidate win.",
                )
            )

    if gap_counts.get("new_model_needed"):
        signals.append(
            model_suitability_signal(
                signal_id="gaps.new_model_needed",
                severity="high",
                category="bigger_model_or_candidate",
                summary=f"{gap_counts['new_model_needed']} current gap(s) explicitly request a new model.",
                evidence={"gap_counts": gap_counts},
                recommendation="Run a targeted bakeoff against the failing task before increasing resident model size.",
            )
        )
    if gap_counts.get("new_specialist_brain_needed"):
        signals.append(
            model_suitability_signal(
                signal_id="gaps.specialist_brain_needed",
                severity="high",
                category="specialist_brain",
                summary=f"{gap_counts['new_specialist_brain_needed']} gap(s) request a specialist brain.",
                evidence={"gap_counts": gap_counts},
                recommendation="Design a specialist module/lane only after proving the task is not solved by routing or tools.",
            )
        )
    if gap_counts.get("model_routing_needed"):
        signals.append(
            model_suitability_signal(
                signal_id="gaps.model_routing_needed",
                severity="high",
                category="model_routing",
                summary=f"{gap_counts['model_routing_needed']} gap(s) point to model routing.",
                evidence={"gap_counts": gap_counts},
                recommendation="Fix lane selection before changing model sizes.",
            )
        )
    if gap_counts.get("runtime_tuning_needed"):
        signals.append(
            model_suitability_signal(
                signal_id="gaps.runtime_tuning_needed",
                severity="high",
                category="runtime_tuning",
                summary=f"{gap_counts['runtime_tuning_needed']} gap(s) point to runtime tuning.",
                evidence={"gap_counts": gap_counts},
                recommendation="Tune serving, cache, context, SQLite/runtime, or lane health before changing models.",
            )
        )
    non_model_gaps = {
        key: value
        for key, value in gap_counts.items()
        if key in {"new_tool_needed", "tool_grounding_needed", "new_thread_needed", "permission_needed", "human_decision_needed"}
    }
    if non_model_gaps:
        signals.append(
            model_suitability_signal(
                signal_id="gaps.non_model_blockers",
                severity="info",
                category="tool_or_action",
                summary="Some current blockers are not model-size problems.",
                evidence={"gap_counts": non_model_gaps},
                recommendation="Fix tools, verification, and autonomy follow-through without swapping models.",
            )
        )

    signals.sort(key=model_suitability_signal_sort_key)
    return signals


def build_model_suitability_decision(signals: List[Dict[str, object]]) -> Dict[str, object]:
    categories = {str(signal.get("category") or "") for signal in signals}
    severities = {str(signal.get("severity") or "") for signal in signals}
    blocking_severities = {"critical", "high"}
    blocking_categories = {
        str(signal.get("category") or "")
        for signal in signals
        if str(signal.get("severity") or "") in blocking_severities
    }
    needs_bigger_model = "bigger_model_or_candidate" in categories
    needs_smaller_faster_model = "smaller_faster_model" in categories
    needs_specialist_brain = "specialist_brain" in categories
    needs_routing_change = "model_routing" in categories
    needs_runtime_tuning = "runtime_tuning" in categories
    needs_prompt_schema_fix = "prompt_or_schema" in categories
    needs_more_evidence = "more_evidence" in categories
    if needs_bigger_model:
        verdict = "targeted_model_bakeoff_needed"
        summary = "There is explicit evidence for testing a new model, but Eve should still bake it off on the failing task before changing live routes."
    elif "runtime_tuning" in blocking_categories:
        verdict = "runtime_tuning_first"
        summary = "Current evidence points to runtime/lane reliability before a model-size change."
    elif "model_routing" in blocking_categories or "prompt_or_schema" in blocking_categories:
        verdict = "routing_or_schema_first"
        summary = "Current evidence points to lane routing, prompt, or schema repair before a model-size change."
    elif needs_smaller_faster_model:
        verdict = "smaller_faster_trial"
        summary = "Current evidence supports trialing smaller/faster hot-path models while preserving the larger deep lane."
    elif needs_specialist_brain:
        verdict = "specialist_design_needed"
        summary = "Current evidence suggests a specialist module may be more appropriate than a general model swap."
    elif needs_runtime_tuning or needs_routing_change or needs_prompt_schema_fix:
        verdict = "watch_current_models"
        summary = "Current evidence is advisory: keep the live models, monitor lane latency, and avoid treating nonblocking warnings as a model-size failure."
    elif needs_more_evidence:
        verdict = "more_evidence_needed"
        summary = "There is not enough fresh model evidence to recommend a model or runtime change."
    else:
        verdict = "keep_current_models"
        summary = "No current evidence requires a model swap."
    status = "action_needed" if severities.intersection(blocking_severities) else "watch" if "medium" in severities else "stable"
    return {
        "status": status,
        "verdict": verdict,
        "summary": summary,
        "needs_bigger_model": needs_bigger_model,
        "needs_smaller_faster_model": needs_smaller_faster_model,
        "needs_specialist_brain": needs_specialist_brain,
        "needs_routing_change": needs_routing_change,
        "needs_runtime_tuning": needs_runtime_tuning,
        "needs_prompt_schema_fix": needs_prompt_schema_fix,
        "needs_more_evidence": needs_more_evidence,
    }


def build_model_suitability_report_from_artifacts(
    config: Dict[str, object],
    *,
    watchdog: Dict[str, object],
    exercise: Dict[str, object],
    bakeoff: Dict[str, object],
    gaps: List[Dict[str, object]],
    artifact_paths: Optional[Dict[str, str]] = None,
    source: str = "manual",
) -> Dict[str, object]:
    lanes = build_model_suitability_lane_inventory(config, watchdog, exercise, bakeoff)
    signals = build_model_suitability_signals(watchdog=watchdog, exercise=exercise, bakeoff=bakeoff, gaps=gaps, lanes=lanes)
    decision = build_model_suitability_decision(signals)
    return {
        "id": str(uuid.uuid4()),
        "schema_version": MODEL_SUITABILITY_SCHEMA_VERSION,
        "tested_at": utc_now(),
        "source": source,
        "status": decision["status"],
        "verdict": decision["verdict"],
        "summary": decision["summary"],
        "decision": decision,
        "gap_counts": summarize_model_suitability_gaps(gaps),
        "signals": signals,
        "recommendations": unique_compact([str(signal.get("recommendation") or "") for signal in signals], limit=8),
        "lanes": lanes,
        "input_artifacts": artifact_paths or {},
    }


def build_model_suitability_report(config: Dict[str, object], *, prefer_runtime: bool = True, source: str = "manual") -> Dict[str, object]:
    watchdog, watchdog_path = read_whole_system_json_artifact(MODEL_WATCHDOG_STATUS_PATH, prefer_runtime=prefer_runtime)
    exercise, exercise_path = read_whole_system_json_artifact(APP_DIR / "model_exercises" / "latest_model_exercise.json", prefer_runtime=prefer_runtime)
    bakeoff, bakeoff_path = read_whole_system_json_artifact(APP_DIR / "model_bakeoffs" / "latest_model_bakeoff.json", prefer_runtime=prefer_runtime)
    gaps = read_eval_gap_records(
        limit=None,
        prefer_runtime=prefer_runtime,
        latest_only=True,
        suppress_superseded_by_latest=True,
    )
    return build_model_suitability_report_from_artifacts(
        config,
        watchdog=watchdog,
        exercise=exercise,
        bakeoff=bakeoff,
        gaps=gaps,
        artifact_paths={
            "watchdog": watchdog_path,
            "model_exercise": exercise_path,
            "model_bakeoff": bakeoff_path,
            "eval_gaps": str(resolve_store_read_path(EVAL_GAPS_PATH, prefer_runtime=prefer_runtime)),
        },
        source=source,
    )


def save_model_suitability_report(record: Dict[str, object]) -> Dict[str, str]:
    ensure_store()
    MODEL_SUITABILITY_DIR.mkdir(parents=True, exist_ok=True)
    MODEL_SUITABILITY_HISTORY_DIR.mkdir(parents=True, exist_ok=True)
    history_path = MODEL_SUITABILITY_HISTORY_DIR / timestamp_filename("model_suitability")
    artifacts = {"latest": str(MODEL_SUITABILITY_LATEST_PATH), "history": str(history_path)}
    record["artifacts"] = artifacts
    content = json.dumps(record, ensure_ascii=True, indent=2) + "\n"
    MODEL_SUITABILITY_LATEST_PATH.write_text(content, encoding="utf-8")
    history_path.write_text(content, encoding="utf-8")
    if not running_from_runtime_bundle():
        try:
            RUNTIME_MODEL_SUITABILITY_DIR.mkdir(parents=True, exist_ok=True)
            RUNTIME_MODEL_SUITABILITY_HISTORY_DIR.mkdir(parents=True, exist_ok=True)
            shutil.copy2(MODEL_SUITABILITY_LATEST_PATH, RUNTIME_MODEL_SUITABILITY_LATEST_PATH)
            shutil.copy2(history_path, RUNTIME_MODEL_SUITABILITY_HISTORY_DIR / history_path.name)
        except OSError:
            pass
    return artifacts


def format_model_suitability_report(record: Dict[str, object], *, full: bool = False) -> str:
    decision = record.get("decision") if isinstance(record.get("decision"), dict) else {}
    lines = [
        "Model suitability",
        f"status: {record.get('status') or 'unknown'}",
        f"verdict: {record.get('verdict') or 'unknown'}",
        f"summary: {record.get('summary') or 'No summary.'}",
        (
            "decision: "
            f"bigger_model={'yes' if decision.get('needs_bigger_model') else 'no'}, "
            f"smaller_faster={'yes' if decision.get('needs_smaller_faster_model') else 'no'}, "
            f"specialist={'yes' if decision.get('needs_specialist_brain') else 'no'}, "
            f"routing={'yes' if decision.get('needs_routing_change') else 'no'}, "
            f"runtime={'yes' if decision.get('needs_runtime_tuning') else 'no'}, "
            f"schema={'yes' if decision.get('needs_prompt_schema_fix') else 'no'}"
        ),
    ]
    gap_counts = record.get("gap_counts") if isinstance(record.get("gap_counts"), dict) else {}
    lines.append("gap_counts: " + (", ".join(f"{key}={value}" for key, value in gap_counts.items()) if gap_counts else "none"))
    recommendations = record.get("recommendations") if isinstance(record.get("recommendations"), list) else []
    if recommendations:
        lines.append("recommendations:")
        lines.extend(f"- {item}" for item in recommendations)
    lanes = record.get("lanes") if isinstance(record.get("lanes"), list) else []
    if lanes:
        lines.append("lanes:")
        for lane in lanes:
            if not isinstance(lane, dict):
                continue
            probe = "unknown" if lane.get("probe_ok") is None else ("ok" if lane.get("probe_ok") else "failed")
            exercise_status = lane.get("exercise_status") or "unknown"
            lines.append(
                f"- {lane.get('profile')}: {lane.get('model')} loaded={'yes' if lane.get('loaded') else 'no'} "
                f"probe={probe} {format_duration_ms(lane.get('probe_wall_ms'))} "
                f"exercise={exercise_status} {format_duration_ms(lane.get('exercise_duration_ms'))}"
            )
    if full:
        signals = record.get("signals") if isinstance(record.get("signals"), list) else []
        if signals:
            lines.append("signals:")
            for signal in signals:
                if not isinstance(signal, dict):
                    continue
                lines.append(f"- [{signal.get('severity')}] {signal.get('category')}.{signal.get('id')}: {signal.get('summary')}")
                if signal.get("recommendation"):
                    lines.append(f"  next: {signal.get('recommendation')}")
        input_artifacts = record.get("input_artifacts") if isinstance(record.get("input_artifacts"), dict) else {}
        if input_artifacts:
            lines.append("input_artifacts:")
            lines.extend(f"- {key}: {value}" for key, value in input_artifacts.items())
    artifacts = record.get("artifacts") if isinstance(record.get("artifacts"), dict) else {}
    if artifacts:
        lines.append(f"latest_artifact: {artifacts.get('latest')}")
        lines.append(f"history_artifact: {artifacts.get('history')}")
    return "\n".join(lines)


def normalize_capability_matrix_record(payload: Dict[str, object]) -> Dict[str, object]:
    capability_id = normalize_text_value(payload.get("id"), fallback=str(uuid.uuid4()), limit=120)
    name = normalize_text_value(payload.get("name"), fallback=capability_id, limit=160)
    category = normalize_text_value(payload.get("category"), fallback="general", limit=80)
    last_result = normalize_text_value(payload.get("last_result"), fallback="", limit=220)
    next_step = normalize_text_value(payload.get("next_acquisition_step"), fallback="", limit=260)
    missing_dependency = normalize_text_value(payload.get("missing_dependency"), fallback="", limit=160)
    return {
        "id": capability_id,
        "name": name,
        "category": category,
        "available": bool(payload.get("available")),
        "callable": bool(payload.get("callable")),
        "verified": bool(payload.get("verified")),
        "safe_for_autonomy": bool(payload.get("safe_for_autonomy")),
        "needs_permission": bool(payload.get("needs_permission")),
        "missing_dependency": missing_dependency,
        "last_tried": normalize_text_value(payload.get("last_tried"), fallback="", limit=40),
        "last_result": last_result,
        "next_acquisition_step": next_step,
        "evidence": payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {},
    }


def latest_action_execution_by_action(actions: List[Dict[str, object]]) -> Dict[str, Dict[str, object]]:
    latest: Dict[str, Dict[str, object]] = {}
    for action in actions:
        action_name = normalize_text_value(action.get("action") or action.get("supported_action"), fallback="", limit=100)
        if action_name and action_name not in latest:
            latest[action_name] = action
    return latest


def action_execution_failure_text(action: Dict[str, object]) -> str:
    fields = [
        action.get("error"),
        action.get("stderr"),
        action.get("summary"),
        action.get("result_summary"),
        action.get("execution_summary"),
    ]
    text = " ".join(normalize_text_value(field, fallback="", limit=500) for field in fields if field)
    lowered = text.lower()
    for marker in ["traceback", "exception", "failed", "error:", "timed out", "timeout"]:
        if marker in lowered:
            return marker
    return ""


def action_execution_verified(action: Dict[str, object]) -> bool:
    if action_execution_failure_text(action):
        return False
    tree_status = str(action.get("tree_status") or action.get("execution_tree_status") or "").upper()
    if tree_status in {"BLOCKED", "FAILURE", "FAILED", "ERROR"}:
        return False
    has_execution_record = bool(normalize_text_value(action.get("id") or action.get("execution_id"), fallback="", limit=120))
    if not has_execution_record:
        return False
    return action_result_explicit_verification(action) is True


def action_execution_verification_value(action: Dict[str, object]) -> object:
    return action_result_explicit_verification(action)


def explicit_verification_value_present(value: object) -> bool:
    if isinstance(value, bool):
        return True
    if isinstance(value, (int, float)):
        return value in {0, 1}
    text = str(value or "").strip().lower()
    return text in {
        "true",
        "false",
        "1",
        "0",
        "yes",
        "no",
        "y",
        "n",
        "on",
        "off",
        "ok",
        "verified",
        "unverified",
        "success",
        "failure",
        "failed",
        "passed",
    }


def action_execution_has_verification_metadata(action: Dict[str, object]) -> bool:
    has_execution_record = bool(normalize_text_value(action.get("id") or action.get("execution_id"), fallback="", limit=120))
    if not has_execution_record:
        return False
    if explicit_verification_value_present(action_execution_verification_value(action)):
        return True
    steps = action.get("steps") if isinstance(action.get("steps"), list) else []
    for step in steps:
        if not isinstance(step, dict):
            continue
        phase = normalize_text_value(step.get("phase") or step.get("name"), fallback="", limit=40).lower()
        if "verify" in phase and "ok" in step and step.get("ok") is not None:
            return True
    return False


def whole_system_action_grounding_check(action_executions: List[Dict[str, object]]) -> Dict[str, object]:
    latest_action = action_executions[0] if action_executions else {}
    latest_action_verified = action_execution_verified(latest_action) if latest_action else False
    has_verification_metadata = action_execution_has_verification_metadata(latest_action) if latest_action else False
    if not latest_action:
        status = "inconclusive"
        score = 2
        missing_components = ["tool_grounding_needed"]
        next_action = "Record a verified action execution before claiming operational action success."
    elif has_verification_metadata:
        status = "passed"
        score = 5
        missing_components = []
        next_action = (
            "Keep treating explicit failed verification as grounded failure, not completion."
            if not latest_action_verified
            else "Keep requiring a verified execution record before Eve reports an action as completed."
        )
    else:
        status = "degraded"
        score = 3
        missing_components = ["tool_grounding_needed"]
        next_action = "Require explicit verification metadata before Eve reports an action as completed."
    return whole_system_fitness_check(
        test_id="action.latest_verification",
        layer="action_grounding",
        title="Latest operational action has verification metadata",
        status=status,
        score=score,
        evidence={
            "action_count": len(action_executions),
            "latest_action": latest_action.get("action"),
            "latest_execution_id": latest_action.get("id") or latest_action.get("execution_id"),
            "latest_tree_status": latest_action.get("tree_status") or latest_action.get("execution_tree_status"),
            "latest_verification_ok": action_execution_verification_value(latest_action),
            "latest_has_verification_metadata": has_verification_metadata,
            "latest_summary": latest_action.get("summary"),
            "completion_claimable": latest_action_verified,
        },
        attribution="deterministic_tool",
        missing_components=missing_components,
        next_action=next_action,
        owner="codex",
        critical=True,
    )


def capability_last_result_from_action(action: Dict[str, object]) -> str:
    if not action:
        return ""
    status = "verified" if action_execution_verified(action) else "unverified"
    summary = normalize_text_value(action.get("summary") or action.get("result_summary") or action.get("execution_summary"), fallback="", limit=160)
    return f"{status}: {summary}" if summary else status


def capability_matrix_record(
    *,
    capability_id: str,
    name: str,
    category: str,
    available: bool,
    callable: bool,
    verified: bool,
    safe_for_autonomy: bool,
    needs_permission: bool = False,
    missing_dependency: str = "",
    last_tried: str = "",
    last_result: str = "",
    next_acquisition_step: str = "",
    evidence: Optional[Dict[str, object]] = None,
) -> Dict[str, object]:
    return normalize_capability_matrix_record(
        {
            "id": capability_id,
            "name": name,
            "category": category,
            "available": available,
            "callable": callable,
            "verified": verified,
            "safe_for_autonomy": safe_for_autonomy,
            "needs_permission": needs_permission,
            "missing_dependency": missing_dependency,
            "last_tried": last_tried,
            "last_result": last_result,
            "next_acquisition_step": next_acquisition_step,
            "evidence": evidence or {},
        }
    )


