def build_capability_matrix(
    config: Dict[str, object],
    *,
    prefer_runtime: bool = True,
    source: str = "manual",
) -> Dict[str, object]:
    actions = read_action_executions(limit=200, prefer_runtime=prefer_runtime)
    latest_actions = latest_action_execution_by_action(actions)
    gaps = read_capability_gaps(limit=200, prefer_runtime=prefer_runtime)
    open_gaps = [gap for gap in gaps if capability_gap_is_active(gap)]
    radar = load_agent_capability_radar(prefer_runtime=prefer_runtime)
    integration = load_agent_integration_state(prefer_runtime=prefer_runtime)
    developmental_cycles = read_developmental_cycles(limit=60, prefer_runtime=prefer_runtime)
    last_cycle_by_action: Dict[str, Dict[str, object]] = {}
    for cycle in developmental_cycles:
        action = normalize_text_value(cycle.get("capability_attempted"), fallback="", limit=100)
        if action and action not in last_cycle_by_action:
            last_cycle_by_action[action] = cycle

    records: List[Dict[str, object]] = []
    for spec in capability_specs():
        tool_name = str(spec.get("name") or "")
        is_write_tool = tool_name in {"write_file", "shell"}
        records.append(
            capability_matrix_record(
                capability_id=f"tool.{tool_name}",
                name=tool_name,
                category="tool",
                available=True,
                callable=True,
                verified=tool_name in {"list_dir", "read_file", "search_text"} or tool_name in {call.get("tool") for call in []},
                safe_for_autonomy=tool_name in {"list_dir", "read_file", "search_text", "fetch_url", "web_search"},
                needs_permission=is_write_tool,
                missing_dependency="approval required for write/destructive shell use" if is_write_tool else "",
                next_acquisition_step="Use through the bounded tool runner and record evidence before claiming completion.",
                evidence={"description": spec.get("description"), "args": spec.get("args")},
            )
        )

    for spec in coder_tool_specs():
        tool_name = str(spec.get("name") or "")
        patch_tool = tool_name == "apply_patch"
        records.append(
            capability_matrix_record(
                capability_id=f"coder.{tool_name}",
                name=f"coder:{tool_name}",
                category="coder_mode",
                available=True,
                callable=True,
                verified=tool_name in {"git_status", "search_text", "read_file", "run_tests"},
                safe_for_autonomy=tool_name in {"git_status", "git_diff", "list_dir", "read_file", "search_text", "run_tests"},
                needs_permission=patch_tool,
                missing_dependency="autonomous patching disabled unless explicitly enabled" if patch_tool else "",
                next_acquisition_step="Use Coder Mode logs under .eve/code_sessions/ as verification evidence.",
                evidence={"description": spec.get("description"), "args": spec.get("args")},
            )
        )

    router_registry = eve_openclaw_body.openclaw_action_router_registry()
    router_events = eve_openclaw_body.read_openclaw_action_router_events(limit=1, prefer_runtime=prefer_runtime)
    latest_router_event = router_events[0] if router_events else {}
    latest_router_result = latest_router_event.get("result") if isinstance(latest_router_event.get("result"), dict) else {}
    router_verified = bool(latest_router_result.get("ok")) if latest_router_result else bool(
        router_registry.get("status_snapshot")
    )
    records.append(
        capability_matrix_record(
            capability_id="router.openclaw_action_router",
            name="OpenClaw action router",
            category="operational_router",
            available=True,
            callable=True,
            verified=router_verified,
            safe_for_autonomy=True,
            needs_permission=False,
            last_tried=normalize_text_value(latest_router_event.get("created_at"), fallback="", limit=40),
            last_result=(
                f"verified: {normalize_text_value(latest_router_result.get('summary'), fallback='OpenClaw action router is available.', limit=160)}"
                if latest_router_result.get("ok")
                else normalize_text_value(latest_router_result.get("summary"), fallback="", limit=180)
            ),
            next_acquisition_step=(
                "Route OpenClaw body work through `python3 eve.py openclaw action --intent ...` "
                "and check `.eve/openclaw_action_router_events.jsonl` for evidence."
            ),
            evidence={
                "description": (
                    "Maps Eve intentions to allowlisted OpenClaw body actions, executes the bounded action, "
                    "and records evidence for verification."
                ),
                "contract_id": "openclaw_action_router",
                "router_actions": sorted(router_registry.keys()),
                "latest_event_id": latest_router_event.get("id"),
            },
        )
    )

    channel_events = eve_openclaw_body.read_openclaw_channel_events(limit=1, prefer_runtime=prefer_runtime)
    latest_channel_event = channel_events[0] if channel_events else {}
    channel_verified = bool(
        latest_channel_event.get("ok")
        or (
            latest_channel_event.get("status") == "blocked"
            and not latest_channel_event.get("external_send_attempted")
        )
    ) if latest_channel_event else True
    records.append(
        capability_matrix_record(
            capability_id="router.openclaw_channel_gateway",
            name="OpenClaw channel gateway",
            category="operational_router",
            available=True,
            callable=True,
            verified=channel_verified,
            safe_for_autonomy=False,
            needs_permission=True,
            missing_dependency="External sends require configured channel/account/target and exact current approval.",
            last_tried=normalize_text_value(latest_channel_event.get("created_at"), fallback="", limit=40),
            last_result=normalize_text_value(latest_channel_event.get("summary"), fallback="OpenClaw channel inventory/draft/send-gate wrapper is available.", limit=180),
            next_acquisition_step=(
                "Use `python3 eve.py openclaw channels inventory` and `draft` freely for evidence; "
                "use `send` only with exact approval and channel preflight."
            ),
            evidence={
                "description": "Wraps OpenClaw channels for read-only inventory, draft-only records, and approval-gated sends.",
                "latest_event_id": latest_channel_event.get("id"),
                "event_path": str(eve_openclaw_body.OPENCLAW_CHANNEL_EVENTS_PATH),
            },
        )
    )

    records.append(eve_chat_same_thread_followup_capability_record())
    records.append(selective_perception_capability_record())
    records.append(embodied_sensory_session_capability_record())

    adoption_state = load_capability_adoption_state(prefer_runtime=prefer_runtime)
    latest_adoption_cycle = (
        adoption_state.get("latest_cycle")
        if isinstance(adoption_state.get("latest_cycle"), dict)
        else {}
    )
    latest_adoption_resolution = (
        latest_adoption_cycle.get("resolution")
        if isinstance(latest_adoption_cycle.get("resolution"), dict)
        else {}
    )
    records.append(
        capability_matrix_record(
            capability_id="system.capability_first_self_development",
            name="Capability-first continuous research, adoption, and self-build routing",
            category="self_development",
            available=True,
            callable=True,
            verified=bool(latest_adoption_cycle.get("completed_at")),
            safe_for_autonomy=True,
            needs_permission=False,
            last_tried=normalize_text_value(latest_adoption_cycle.get("completed_at"), fallback="", limit=40),
            last_result=normalize_text_value(adoption_state.get("summary"), fallback="No cycle has run yet.", limit=260),
            next_acquisition_step=(
                "Run `python3 eve.py capabilities adoption cycle --research --full`. Eve must resolve against the live capability map, "
                "configuration/admission surfaces, and official upstream evidence before any Codex implementation handoff."
            ),
            evidence={
                "description": (
                    "Rotates one real capability gap, installed-component release candidate, or official upstream research source; "
                    "classifies it as use, configure/admit, canary, research, or build; stages eligible Python updates in an isolated "
                    "uv environment; and routes only proven implementation gaps to a local Codex handoff and Eve task."
                ),
                "latest_cycle_id": latest_adoption_cycle.get("id"),
                "latest_classification": latest_adoption_resolution.get("classification"),
                "online_research": str(resolve_store_read_path(CAPABILITY_ONLINE_RESEARCH_PATH, prefer_runtime=prefer_runtime)),
                "state": str(resolve_store_read_path(CAPABILITY_ADOPTION_PATH, prefer_runtime=prefer_runtime)),
                "history": str(resolve_store_read_path(CAPABILITY_ADOPTION_HISTORY_PATH, prefer_runtime=prefer_runtime)),
                "boundaries": (
                    "Release and search results are research evidence, not installed capability proof. OpenClaw executes admitted actions, "
                    "Hermes remains proposal-only, Codex remains external, and the cycle grants no permissions or canonical memory authority."
                ),
            },
        )
    )

    for action, description in supported_commitment_action_descriptions().items():
        latest_action = latest_actions.get(action, {})
        cycle = last_cycle_by_action.get(action, {})
        last_tried = normalize_text_value(latest_action.get("created_at") or cycle.get("timestamp"), fallback="", limit=40)
        verified = action_execution_verified(latest_action) if latest_action else str(cycle.get("status") or "") == "verified"
        safe_for_autonomy = action in {
            "agent_capability_scout",
            "agent_capability_integration",
            "openclaw_self_test",
            "openclaw_log_check",
            "openclaw_sync_check",
            "service_health_check",
            "cleanup_candidate_check",
            "updates_status",
            "code_change",
        }
        local_app_action = action in LOCAL_APP_OPEN_ACTIONS
        codex_handoff_action = action == "codex_independent_handoff"
        calendar_sensitive_action = action in {CALENDAR_READ_UPCOMING_ACTION, CALENDAR_CREATE_EVENT_ACTION}
        records.append(
            capability_matrix_record(
                capability_id=f"action.{action}",
                name=action,
                category="operational_action",
                available=True,
                callable=True,
                verified=verified,
                safe_for_autonomy=safe_for_autonomy and action not in {"web_search"} and not local_app_action,
                needs_permission=action in {"web_search"} or action == "code_change" or local_app_action or codex_handoff_action or calendar_sensitive_action,
                missing_dependency=(
                    "approval/research boundary"
                    if action == "web_search"
                    else "private Calendar read; requires the user's exact approval and stores title-redacted metadata only"
                    if action == CALENDAR_READ_UPCOMING_ACTION
                    else "private Calendar write; unconfirmed requests preview only, confirmed exact event details create one event only, and no invites are sent"
                    if action == CALENDAR_CREATE_EVENT_ACTION
                    else "requires a bounded Codex objective and exact current approval; Codex results are evidence only after verification"
                    if codex_handoff_action
                    else "user-visible local app action; open-only and no external communication"
                    if local_app_action
                    else ""
                ),
                last_tried=last_tried,
                last_result=capability_last_result_from_action(latest_action) or normalize_text_value(cycle.get("result_summary"), fallback="", limit=160),
                next_acquisition_step="Run the action through the typed operational action surface and require verification metadata.",
                evidence={"description": description, "latest_action_id": latest_action.get("id"), "cycle_id": cycle.get("id")},
            )
        )

    runtime_identity = load_runtime_identity(prefer_runtime=prefer_runtime)
    for index, item in enumerate(runtime_identity.get("capability_ledger") or []):
        text = normalize_text_value(item, fallback="", limit=260)
        if not text:
            continue
        records.append(
            capability_matrix_record(
                capability_id=f"ledger.{sha256_text(text)[:12]}",
                name=text[:120],
                category="remembered_capability",
                available=True,
                callable=False,
                verified=False,
                safe_for_autonomy=False,
                next_acquisition_step="Map this remembered capability to a callable action/tool before autonomous use.",
                evidence={
                    "ledger_index": index,
                    "statement": text,
                    "lifecycle_stage": "discovered",
                    "source_discovery_only": True,
                },
            )
        )

    for route in integration.get("routes") if isinstance(integration.get("routes"), list) else []:
        if not isinstance(route, dict):
            continue
        route_id = normalize_text_value(route.get("id"), fallback="", limit=120)
        if not route_id:
            continue
        status = str(route.get("status") or "")
        live = status in {"openclaw_native", "bounded_live"} or status.startswith("live")
        records.append(
            capability_matrix_record(
                capability_id=f"integration.{route_id}",
                name=normalize_text_value(route.get("name"), fallback=route_id, limit=160),
                category="agent_integration",
                available=live or bool(route.get("openclaw_supported_domains")),
                callable=live,
                verified=live and not route.get("candidate_gap_domains"),
                safe_for_autonomy=live and str(route.get("risk_level") or "") in {"low", "moderate"},
                needs_permission=str(route.get("risk_level") or "") in {"high", "critical"},
                missing_dependency=", ".join(str(item) for item in route.get("candidate_gap_domains") or []),
                next_acquisition_step=normalize_text_value(route.get("integration_summary"), fallback="Prototype and verify this integration route before autonomous use.", limit=260),
                evidence={"status": status, "local_surfaces": route.get("local_surfaces"), "risk_level": route.get("risk_level")},
            )
        )

    for item in radar.get("openclaw_capabilities") if isinstance(radar.get("openclaw_capabilities"), list) else []:
        if not isinstance(item, dict) or not item.get("present"):
            continue
        capability_id = normalize_text_value(item.get("id"), fallback="", limit=120)
        if not capability_id:
            continue
        records.append(
            capability_matrix_record(
                capability_id=f"openclaw.{capability_id}",
                name=normalize_text_value(item.get("name") or capability_id, fallback=capability_id, limit=160),
                category="openclaw_native",
                available=True,
                callable=False,
                verified=False,
                safe_for_autonomy=False,
                next_acquisition_step="Map the OpenClaw-native surface to an Eve typed action before autonomous use.",
                evidence={
                    "matched_paths": item.get("evidence"),
                    "source_path": radar.get("openclaw_source_path"),
                    "source_kind": radar.get("openclaw_source_kind"),
                    "lifecycle_stage": "discovered",
                    "source_discovery_only": True,
                },
            )
        )

    for gap in open_gaps:
        gap_id = normalize_text_value(gap.get("id"), fallback=str(uuid.uuid4()), limit=120)
        plan = gap.get("acquisition_plan") if isinstance(gap.get("acquisition_plan"), list) else capability_gap_acquisition_plan(gap.get("commitment_text") or gap.get("goal"))
        records.append(
            capability_matrix_record(
                capability_id=f"gap.{gap_id}",
                name=normalize_text_value(gap.get("goal"), fallback="Capability gap", limit=160),
                category="capability_gap",
                available=False,
                callable=False,
                verified=False,
                safe_for_autonomy=False,
                needs_permission=True,
                missing_dependency=normalize_text_value(gap.get("commitment_text"), fallback="No verified action path yet.", limit=160),
                last_tried=normalize_text_value(gap.get("updated_at") or gap.get("created_at"), fallback="", limit=40),
                last_result=f"gap_status:{gap.get('status') or 'planned'}",
                next_acquisition_step=normalize_text_value(plan[0] if plan else "Create and verify the missing capability path.", fallback="", limit=260),
                evidence={"gap_id": gap_id, "proposal_id": gap.get("proposal_id"), "source": gap.get("source")},
            )
        )

    deduped: Dict[str, Dict[str, object]] = {}
    for record in records:
        deduped[str(record.get("id"))] = record
    matrix_records = sorted(deduped.values(), key=lambda item: (str(item.get("category")), str(item.get("id"))))
    summary = {
        "total": len(matrix_records),
        "available": sum(1 for item in matrix_records if item.get("available")),
        "callable": sum(1 for item in matrix_records if item.get("callable")),
        "verified": sum(1 for item in matrix_records if item.get("verified")),
        "safe_for_autonomy": sum(1 for item in matrix_records if item.get("safe_for_autonomy")),
        "needs_permission": sum(1 for item in matrix_records if item.get("needs_permission")),
        "open_gaps": len(open_gaps),
    }
    return {
        "schema_version": CAPABILITY_MATRIX_SCHEMA_VERSION,
        "updated_at": utc_now(),
        "source": source,
        "summary": summary,
        "capabilities": matrix_records,
        "input_counts": {
            "action_executions": len(actions),
            "capability_gaps": len(gaps),
            "open_capability_gaps": len(open_gaps),
            "agent_routes": len(integration.get("routes") if isinstance(integration.get("routes"), list) else []),
            "openclaw_capabilities": len(radar.get("openclaw_capabilities") if isinstance(radar.get("openclaw_capabilities"), list) else []),
        },
    }


def build_capability_gap_acquisition_records(matrix: Dict[str, object], *, prefer_runtime: bool = True) -> List[Dict[str, object]]:
    gaps = read_capability_gaps(limit=200, prefer_runtime=prefer_runtime)
    open_gaps = [gap for gap in gaps if capability_gap_is_active(gap)]
    records: List[Dict[str, object]] = []
    for gap in open_gaps:
        gap_id = normalize_text_value(gap.get("id"), fallback=str(uuid.uuid4()), limit=120)
        plan = gap.get("acquisition_plan") if isinstance(gap.get("acquisition_plan"), list) else capability_gap_acquisition_plan(gap.get("commitment_text") or gap.get("goal"))
        records.append(
            {
                "id": str(uuid.uuid4()),
                "created_at": utc_now(),
                "capability_gap_id": gap_id,
                "status": gap.get("status") or "planned",
                "goal": normalize_text_value(gap.get("goal"), fallback="Capability gap", limit=220),
                "commitment_text": normalize_text_value(gap.get("commitment_text"), fallback="", limit=260),
                "proposal_id": gap.get("proposal_id") or "",
                "plan": plan,
                "next_acquisition_step": normalize_text_value(plan[0] if plan else "Create and verify the missing capability path.", fallback="", limit=260),
                "verification_requirement": "Do not claim completion until an action log, tool result, test, or artifact proves it.",
                "matrix_id": f"gap.{gap_id}",
            }
        )
    return records


def save_capability_matrix(matrix: Dict[str, object], acquisition_records: List[Dict[str, object]]) -> Dict[str, str]:
    ensure_store()
    eve_store.write_json_dict(CAPABILITY_MATRIX_PATH, matrix, indent=2, sort_keys=False)
    content = "".join(json.dumps(record, ensure_ascii=True) + "\n" for record in acquisition_records)
    eve_store.atomic_write_text(CAPABILITY_GAP_ACQUISITION_PLANS_PATH, content)
    mirror_store_file_to_runtime(CAPABILITY_MATRIX_PATH)
    mirror_store_file_to_runtime(CAPABILITY_GAP_ACQUISITION_PLANS_PATH)
    return {
        "matrix": str(CAPABILITY_MATRIX_PATH),
        "acquisition_plans": str(CAPABILITY_GAP_ACQUISITION_PLANS_PATH),
    }


def format_capability_matrix(matrix: Dict[str, object], acquisition_records: List[Dict[str, object]], *, full: bool = False) -> str:
    summary = matrix.get("summary") if isinstance(matrix.get("summary"), dict) else {}
    capabilities = matrix.get("capabilities") if isinstance(matrix.get("capabilities"), list) else []
    lines = [
        "Capability matrix",
        f"updated_at: {matrix.get('updated_at') or 'unknown'}",
        (
            f"total: {summary.get('total', 0)} | available: {summary.get('available', 0)} | "
            f"callable: {summary.get('callable', 0)} | verified: {summary.get('verified', 0)} | "
            f"safe_for_autonomy: {summary.get('safe_for_autonomy', 0)} | open_gaps: {summary.get('open_gaps', 0)}"
        ),
    ]
    categories = count_eval_gap_values(capabilities, "category")
    lines.append("categories: " + (", ".join(f"{key}={value}" for key, value in categories.items()) if categories else "none"))
    if acquisition_records:
        lines.append("acquisition_plans:")
        for record in acquisition_records[:8]:
            lines.append(f"- {record.get('capability_gap_id')}: {record.get('goal')} -> {record.get('next_acquisition_step')}")
    if full:
        lines.append("capabilities:")
        for capability in capabilities:
            if not isinstance(capability, dict):
                continue
            flags = []
            for field, label in [
                ("available", "available"),
                ("callable", "callable"),
                ("verified", "verified"),
                ("safe_for_autonomy", "autonomy_safe"),
                ("needs_permission", "permission"),
            ]:
                if capability.get(field):
                    flags.append(label)
            flag_text = ",".join(flags) if flags else "none"
            lines.append(f"- {capability.get('id')} [{capability.get('category')}] {capability.get('name')} | {flag_text}")
            if capability.get("last_tried") or capability.get("last_result"):
                lines.append(f"  last: {capability.get('last_tried') or 'unknown'} | {capability.get('last_result') or 'none'}")
            if capability.get("missing_dependency"):
                lines.append(f"  missing: {capability.get('missing_dependency')}")
            if capability.get("next_acquisition_step"):
                lines.append(f"  next: {capability.get('next_acquisition_step')}")
    return "\n".join(lines)


def default_ability_map_state() -> Dict[str, object]:
    return {
        "schema_version": ABILITY_MAP_SCHEMA_VERSION,
        "updated_at": None,
        "source": "",
        "summary": {},
        "abilities": [],
        "input_artifacts": {},
    }


def load_ability_map(prefer_runtime: bool = False) -> Dict[str, object]:
    path = RUNTIME_ABILITY_MAP_PATH if prefer_runtime and RUNTIME_ABILITY_MAP_PATH.exists() else ABILITY_MAP_PATH
    payload = load_json_object(path, "ability map", prefer_runtime=False)
    state = default_ability_map_state()
    if isinstance(payload, dict):
        state.update(payload)
    state["abilities"] = state.get("abilities") if isinstance(state.get("abilities"), list) else []
    state["summary"] = state.get("summary") if isinstance(state.get("summary"), dict) else {}
    state["input_artifacts"] = state.get("input_artifacts") if isinstance(state.get("input_artifacts"), dict) else {}
    return state


def ability_source_from_capability(record: Dict[str, object]) -> str:
    capability_id = str(record.get("id") or "")
    category = str(record.get("category") or "")
    if capability_id.startswith("openclaw.") or category == "openclaw_native":
        return "openclaw_native"
    if capability_id.startswith("integration."):
        return "agent_integration"
    if capability_id.startswith("gap."):
        return "capability_gap"
    if capability_id.startswith("ledger."):
        return "remembered"
    if (
        capability_id.startswith("tool.")
        or capability_id.startswith("coder.")
        or capability_id.startswith("action.")
        or capability_id.startswith("surface.")
    ):
        return "eve_native"
    return "eve_native"


def ability_locations_from_capability(record: Dict[str, object]) -> List[str]:
    capability_id = str(record.get("id") or "")
    category = str(record.get("category") or "")
    evidence = record.get("evidence") if isinstance(record.get("evidence"), dict) else {}
    locations: List[str] = []
    if capability_id.startswith("tool."):
        locations.append("eve.py: capability_specs()")
    elif capability_id.startswith("coder."):
        locations.append("eve.py: coder_tool_specs()")
    elif capability_id.startswith("action."):
        locations.append("eve.py: supported_commitment_action_descriptions()")
        if capability_id == "action.codex_independent_handoff":
            locations.append("eve.py: run_bounded_codex_independent_handoff()")
            locations.append("eve.py: codex send|handoff bridge")
            locations.append("openclaw/skills/eve_codex_independent_operator/SKILL.md")
        if capability_id == f"action.{CALENDAR_READ_UPCOMING_ACTION}":
            locations.append("eve.py: run_bounded_calendar_read_upcoming()")
            locations.append("eve.py: calendar_read_upcoming_request_response()")
        if capability_id == f"action.{CALENDAR_CREATE_EVENT_ACTION}":
            locations.append("eve.py: run_bounded_calendar_create_event()")
            locations.append("eve.py: calendar_create_event_request_response()")
        if capability_id.removeprefix("action.") in LOCAL_APP_OPEN_ACTIONS:
            locations.append("eve.py: LOCAL_APP_OPEN_ACTIONS")
    elif capability_id == "surface.eve_chat_same_thread_followup":
        locations.extend(
            [
                "eve.py: create_eve_chat_followup()",
                "eve_web.py: eve_chat_followup_requested()",
                "eve_web.py: queue_eve_chat_followup()",
                "eve_web.py: run_eve_chat_followup_worker()",
                "eve_web.py: /api/eve-chat/followups",
                "Eve Chat same-thread insertion bridge",
            ]
        )
    elif capability_id == "organ.selective_perception":
        locations.extend(
            [
                "eve_sensory.py: build_frame()",
                "eve.py: run_sensory_attention_tick()",
                "eve.py: collect_runtime_sensory_events()",
                ".eve/operational_state.sqlite3: sensory event spine",
            ]
        )
    elif capability_id == "surface.embodied_sensory_session":
        locations.extend(
            [
                "Eve.app: Perceive panel",
                "eve_web.py: /api/sensory/session",
                "eve_web.py: /api/sensory/events",
                "bin/eve_app_server.py: local sensory proxy",
                "web/eve_app/app.js: feature-only adapters",
                "go/eve-nervous/main.go: sense",
            ]
        )
    elif capability_id == "router.openclaw_action_router":
        locations.append("eve.py: cmd_openclaw_action()")
        locations.append("eve.py: execute_openclaw_action_plan()")
        locations.append("eve_openclaw_body.py: openclaw_action_router_registry()")
        locations.append(".eve/openclaw_action_router_events.jsonl")
    elif capability_id.startswith("integration."):
        for surface in evidence.get("local_surfaces") or []:
            locations.append(str(surface))
    elif capability_id.startswith("openclaw."):
        source_path = str(evidence.get("source_path") or "").rstrip("/")
        for matched in evidence.get("matched_paths") or []:
            locations.append(f"{source_path}/{matched}" if source_path else str(matched))
    elif capability_id.startswith("gap."):
        locations.append(".eve/capability_gaps.jsonl")
    elif capability_id.startswith("ledger."):
        locations.append(".eve/runtime_identity.json capability_ledger")
    if not locations and category:
        locations.append(f"Eve capability category: {category}")
    return unique_compact(locations, limit=8)


def ability_access_path_from_capability(record: Dict[str, object]) -> str:
    capability_id = str(record.get("id") or "")
    name = str(record.get("name") or capability_id)
    action_name = capability_id.removeprefix("action.")
    if action_name in LOCAL_APP_OPEN_ACTIONS:
        spec = local_app_action_spec(action_name)
        app_name = normalize_text_value(spec.get("app_name"), fallback=name, limit=80)
        boundary = normalize_text_value(
            spec.get("private_boundary"),
            fallback="Eve must not read private app content or perform external communication.",
            limit=180,
        )
        return f"Ask Eve to open {app_name}; Eve uses typed action `{action_name}`. Boundary: {boundary}"
    if action_name == CALENDAR_READ_UPCOMING_ACTION:
        return "Ask Eve to check upcoming Calendar metadata; Eve uses typed action `calendar_read_upcoming`, requires the user's exact approval, redacts event titles, and records a verified action log."
    if action_name == CALENDAR_CREATE_EVENT_ACTION:
        return "Ask Eve to create a Calendar event with explicit title/date/time/duration; Eve first returns `calendar_create_event_preview`, then uses typed action `calendar_create_event` only after the user confirms the same turn or the latest fresh pending preview, creates one event only, and records a verified action log."
    if capability_id == "action.codex_independent_handoff":
        return "Use `python3 eve.py codex handoff <objective>` or ask Eve to involve Codex; Eve creates a bounded Codex bridge message and records action evidence."
    if capability_id == "surface.eve_chat_same_thread_followup":
        return (
            "In Eve Chat/OpenWebUI, explicitly ask Eve to run a supported bounded check and return when it finishes. "
            "The chat bridge creates an `eve_chat_followup.v2` record plus a durable commitment, acknowledges the "
            "due time, resumes after backend restart, executes one typed action through the verified action tree, "
            "and the UI polling bridge inserts the result exactly once as a new Eve message in the same thread."
        )
    if capability_id == "organ.selective_perception":
        return (
            "Use `python3 eve.py sensory status --runtime --full` to inspect the current feature-only frame "
            "or `python3 eve.py sensory tick` to run one bounded attention update. This faculty "
            "can propose orientation but cannot authorize capture or execute a body action."
        )
    if capability_id == "surface.embodied_sensory_session":
        return (
            "Open Eve.app, choose Perceive modalities and a duration, then press Start with a named purpose. "
            "Eve accepts only local typed features during that expiring session; macOS separately prompts for "
            "microphone/camera permission. Hardware adapters use `python3 eve.py infra nervous sense` with a "
            "session token supplied only through an environment variable or mode-0600 file."
        )
    if capability_id == "router.openclaw_action_router":
        return "Use `python3 eve.py openclaw action --intent ...`; the router infers or accepts an allowlisted OpenClaw body action and records evidence."
    if capability_id.startswith("action."):
        return f"Typed operational action `{name}` through Eve's action planner, chat path, or autonomy only when its permission and verification flags allow it."
    if capability_id.startswith("tool."):
        return f"Bounded tool runner capability `{name}`; use through an approved tool call and log evidence before claiming completion."
    if capability_id.startswith("coder."):
        return f"Coder-mode capability `{name}`; use inside a bounded code session with tests or diff evidence."
    if capability_id.startswith("integration."):
        return "Use the listed local surfaces or create a verified adapter task before giving Eve direct autonomy access."
    if capability_id.startswith("openclaw."):
        return "Inspect the OpenClaw source evidence, then map the surface to an Eve typed action before autonomous use."
    if capability_id.startswith("gap."):
        return "Not accessible yet; follow the acquisition plan and verify the new route before claiming the capability."
    if capability_id.startswith("ledger."):
        return "Remembered only; convert the memory statement into a callable tool/action route before autonomous use."
    return "Use through Eve's bounded runtime only after a verification artifact proves the route."


def normalize_ability_record(payload: Dict[str, object]) -> Dict[str, object]:
    return {
        "id": normalize_text_value(payload.get("id"), fallback=str(uuid.uuid4()), limit=140),
        "name": normalize_text_value(payload.get("name"), fallback="Ability", limit=180),
        "source": normalize_text_value(payload.get("source"), fallback="eve_native", limit=80),
        "category": normalize_text_value(payload.get("category"), fallback="general", limit=100),
        "description": normalize_text_value(payload.get("description"), fallback="", limit=320),
        "available": bool(payload.get("available")),
        "callable": bool(payload.get("callable")),
        "verified": bool(payload.get("verified")),
        "safe_for_autonomy": bool(payload.get("safe_for_autonomy")),
        "needs_permission": bool(payload.get("needs_permission")),
        "locations": unique_compact([str(item) for item in payload.get("locations") or [] if str(item).strip()], limit=10),
        "access_path": normalize_text_value(payload.get("access_path"), fallback="", limit=420),
        "boundaries": normalize_text_value(payload.get("boundaries"), fallback="", limit=260),
        "last_tried": normalize_text_value(payload.get("last_tried"), fallback="", limit=40),
        "last_result": normalize_text_value(payload.get("last_result"), fallback="", limit=220),
        "next_step": normalize_text_value(payload.get("next_step"), fallback="", limit=320),
        "evidence": payload.get("evidence") if isinstance(payload.get("evidence"), dict) else {},
    }


def ability_record_from_capability(record: Dict[str, object]) -> Dict[str, object]:
    evidence = record.get("evidence") if isinstance(record.get("evidence"), dict) else {}
    missing = normalize_text_value(record.get("missing_dependency"), fallback="", limit=240)
    boundaries = normalize_text_value(
        evidence.get("boundaries"), fallback=missing, limit=260
    )
    if record.get("needs_permission") and not boundaries:
        boundaries = "Permission-gated; ask the user or use an approved bounded path before execution."
    return normalize_ability_record(
        {
            "id": record.get("id"),
            "name": record.get("name"),
            "source": ability_source_from_capability(record),
            "category": record.get("category"),
            "description": evidence.get("description") or record.get("name") or "",
            "available": record.get("available"),
            "callable": record.get("callable"),
            "verified": record.get("verified"),
            "safe_for_autonomy": record.get("safe_for_autonomy"),
            "needs_permission": record.get("needs_permission"),
            "locations": ability_locations_from_capability(record),
            "access_path": ability_access_path_from_capability(record),
            "boundaries": boundaries,
            "last_tried": record.get("last_tried"),
            "last_result": record.get("last_result"),
            "next_step": record.get("next_acquisition_step"),
            "evidence": evidence,
        }
    )


def admission_record_for_openclaw_surface(surface: Dict[str, object], *, prefer_runtime: bool = False) -> Dict[str, object]:
    evidence = [str(item) for item in surface.get("evidence") or [] if str(item).strip()]
    surface_id = normalize_text_value(surface.get("id"), fallback="", limit=160)
    slug = surface_id.split(".")[-1] if surface_id else ""
    admissions = eve_openclaw_body.read_admission_records(limit=200, prefer_runtime=prefer_runtime)
    for admission in admissions:
        if str(admission.get("decision") or "") not in {"approved", "watch"}:
            continue
        candidate_id = str(admission.get("candidate_id") or "")
        source = str(admission.get("source") or "")
        if candidate_id and (candidate_id == surface_id or candidate_id.endswith(slug)):
            return admission
        if source and any(source.endswith(item) or item.endswith(source) for item in evidence):
            return admission
    return {}


def ability_record_from_openclaw_surface(surface: Dict[str, object], radar: Dict[str, object]) -> Dict[str, object]:
    source_path = str(radar.get("openclaw_source_path") or "").rstrip("/")
    evidence = [str(item) for item in surface.get("evidence") or [] if str(item).strip()]
    locations = [f"{source_path}/{item}" if source_path else item for item in evidence]
    risk = str(surface.get("risk_level") or "unknown")
    admission = admission_record_for_openclaw_surface(surface)
    permission_level = str(admission.get("permission_level") or "")
    if permission_level == "read_only":
        risk = "low"
    elif permission_level == "operator_safe":
        risk = "moderate"
    elif permission_level in {"approval_gated", "specific_approval_required", "blocked"}:
        risk = "high"
    # This record comes from a source-tree radar, not a live executable-route
    # attestation.  Source presence and even an admission decision may describe
    # or permit a future route, but neither proves that the resident agent can
    # call it or that a consequence has been verified.
    callable_now = False
    needs_permission = risk in {"medium", "high"} or permission_level in {"approval_gated", "specific_approval_required", "blocked"}
    return normalize_ability_record(
        {
            "id": surface.get("id"),
            "name": surface.get("name"),
            "source": "openclaw_native",
            "category": surface.get("category"),
            "description": admission.get("capability") or surface.get("meaning_for_eve"),
            "available": True,
            "callable": callable_now,
            "verified": False,
            "safe_for_autonomy": False,
            "needs_permission": needs_permission,
            "locations": locations,
            "access_path": (
                "Inspect this OpenClaw source surface, then configure and verify an Eve-owned adapter before use."
            ),
            "boundaries": (
                f"Admitted OpenClaw surface; permission={permission_level}; boundary={admission.get('data_boundary') or 'not recorded'}."
                if admission
                else f"OpenClaw risk={risk}; do not grant broad authority without an Eve action contract and verification."
            ),
            "next_step": "Map this OpenClaw surface to a typed Eve action if the user wants Eve to use it operationally.",
            "evidence": {
                "surface_id": surface.get("id"),
                "risk_level": risk,
                "capability_domain": surface.get("capability_domain"),
                "source_path": source_path,
                "evidence": evidence,
                "admission_id": admission.get("id") if admission else "",
                "permission_level": permission_level,
                "lifecycle_stage": "discovered",
                "source_discovery_only": True,
            },
        }
    )


def build_ability_map_from_state(
    matrix: Dict[str, object],
    radar: Dict[str, object],
    integration: Dict[str, object],
    *,
    source: str = "manual",
) -> Dict[str, object]:
    abilities_by_id: Dict[str, Dict[str, object]] = {}
    for capability in matrix.get("capabilities") if isinstance(matrix.get("capabilities"), list) else []:
        if isinstance(capability, dict):
            ability = ability_record_from_capability(capability)
            abilities_by_id[str(ability.get("id"))] = ability
    if "router.openclaw_action_router" not in abilities_by_id:
        router_registry = eve_openclaw_body.openclaw_action_router_registry()
        abilities_by_id["router.openclaw_action_router"] = normalize_ability_record(
            {
                "id": "router.openclaw_action_router",
                "name": "OpenClaw action router",
                "source": "eve_native",
                "category": "operational_router",
                "description": (
                    "Maps Eve intentions to allowlisted OpenClaw body actions, executes the bounded action, "
                    "and records evidence for verification."
                ),
                "available": True,
                "callable": True,
                "verified": bool(router_registry.get("status_snapshot")),
                "safe_for_autonomy": True,
                "needs_permission": False,
                "locations": [
                    "eve.py: cmd_openclaw_action()",
                    "eve.py: execute_openclaw_action_plan()",
                    "eve_openclaw_body.py: openclaw_action_router_registry()",
                    ".eve/openclaw_action_router_events.jsonl",
                ],
                "access_path": (
                    "Use `python3 eve.py openclaw action --intent ...`; the router infers or accepts an "
                    "allowlisted OpenClaw body action and records evidence."
                ),
                "boundaries": "Allowlisted OpenClaw body actions only; no new skills, plugins, MCP sends, or external communication without admission evidence.",
                "next_step": "Use the router for OpenClaw body work and verify the matching router event.",
                "evidence": {
                    "contract_id": "openclaw_action_router",
                    "router_actions": sorted(router_registry.keys()),
                },
            }
        )
    for surface in radar.get("openclaw_discovered_surfaces") if isinstance(radar.get("openclaw_discovered_surfaces"), list) else []:
        if isinstance(surface, dict):
            ability = ability_record_from_openclaw_surface(surface, radar)
            abilities_by_id[str(ability.get("id"))] = ability
    abilities = sorted(abilities_by_id.values(), key=lambda item: (str(item.get("source")), str(item.get("category")), str(item.get("id"))))
    source_counts = count_eval_gap_values(abilities, "source")
    category_counts = count_eval_gap_values(abilities, "category")
    summary = {
        "total": len(abilities),
        "available": sum(1 for item in abilities if item.get("available")),
        "callable": sum(1 for item in abilities if item.get("callable")),
        "verified": sum(1 for item in abilities if item.get("verified")),
        "safe_for_autonomy": sum(1 for item in abilities if item.get("safe_for_autonomy")),
        "needs_permission": sum(1 for item in abilities if item.get("needs_permission")),
        "openclaw_native": source_counts.get("openclaw_native", 0),
        "source_counts": source_counts,
        "category_counts": category_counts,
    }
    return {
        "schema_version": ABILITY_MAP_SCHEMA_VERSION,
        "updated_at": utc_now(),
        "source": source,
        "summary": summary,
        "abilities": abilities,
        "input_artifacts": {
            "capability_matrix": str(CAPABILITY_MATRIX_PATH),
            "agent_capability_radar": str(AGENT_CAPABILITY_RADAR_PATH),
            "agent_integrations": str(AGENT_INTEGRATION_STATE_PATH),
            "openclaw_source_path": radar.get("openclaw_source_path") or "",
            "openclaw_source_kind": radar.get("openclaw_source_kind") or "",
            "integration_updated_at": integration.get("updated_at") or "",
        },
    }


def build_ability_map(
    config: Dict[str, object],
    *,
    prefer_runtime: bool = True,
    refresh_scout: bool = False,
    source: str = "manual",
) -> Dict[str, object]:
    radar = load_agent_capability_radar(prefer_runtime=prefer_runtime)
    if refresh_scout or not radar.get("updated_at") or radar.get("openclaw_error"):
        radar = build_agent_capability_radar(config, source=source)
    integration = load_agent_integration_state(prefer_runtime=prefer_runtime)
    if refresh_scout or not integration.get("updated_at"):
        integration = build_agent_integration_state(config, source=source)
    matrix = build_capability_matrix(config, prefer_runtime=prefer_runtime, source=source)
    return build_ability_map_from_state(matrix, radar, integration, source=source)


def save_ability_map(record: Dict[str, object]) -> Dict[str, str]:
    ensure_store()
    eve_store.write_json_dict(ABILITY_MAP_PATH, record, indent=2, sort_keys=False)
    append_jsonl_record(
        ABILITY_MAP_AUDIT_LOG_PATH,
        {
            "id": str(uuid.uuid4()),
            "created_at": utc_now(),
            "schema_version": record.get("schema_version"),
            "ability_count": (record.get("summary") or {}).get("total") if isinstance(record.get("summary"), dict) else 0,
            "openclaw_native": (record.get("summary") or {}).get("openclaw_native") if isinstance(record.get("summary"), dict) else 0,
            "source": record.get("source") or "manual",
        },
    )
    mirror_store_file_to_runtime(ABILITY_MAP_PATH)
    mirror_store_file_to_runtime(ABILITY_MAP_AUDIT_LOG_PATH)
    return {"ability_map": str(ABILITY_MAP_PATH), "ability_map_audit": str(ABILITY_MAP_AUDIT_LOG_PATH)}


def filter_ability_records(
    abilities: List[Dict[str, object]],
    *,
    source_filter: str = "",
    query: str = "",
) -> List[Dict[str, object]]:
    source_filter = source_filter.strip()
    query_text = query.lower().strip()
    filtered: List[Dict[str, object]] = []
    for ability in abilities:
        if source_filter and str(ability.get("source") or "") != source_filter:
            continue
        if query_text:
            haystack = " ".join(
                [
                    str(ability.get("id") or ""),
                    str(ability.get("name") or ""),
                    str(ability.get("category") or ""),
                    str(ability.get("description") or ""),
                    " ".join(str(item) for item in ability.get("locations") or []),
                ]
            ).lower()
            if query_text not in haystack:
                continue
        filtered.append(ability)
    return filtered


def format_ability_map(
    record: Dict[str, object],
    *,
    full: bool = False,
    source_filter: str = "",
    query: str = "",
) -> str:
    summary = record.get("summary") if isinstance(record.get("summary"), dict) else {}
    abilities = record.get("abilities") if isinstance(record.get("abilities"), list) else []
    abilities = filter_ability_records([item for item in abilities if isinstance(item, dict)], source_filter=source_filter, query=query)
    lines = [
        "Ability map",
        f"updated_at: {record.get('updated_at') or 'unknown'}",
        (
            f"total: {summary.get('total', 0)} | available: {summary.get('available', 0)} | "
            f"callable: {summary.get('callable', 0)} | verified: {summary.get('verified', 0)} | "
            f"autonomy_safe: {summary.get('safe_for_autonomy', 0)} | openclaw_native: {summary.get('openclaw_native', 0)}"
        ),
    ]
    if source_filter or query:
        lines.append(f"filtered: {len(abilities)} ability(ies)")
    source_counts = summary.get("source_counts") if isinstance(summary.get("source_counts"), dict) else {}
    if source_counts:
        lines.append("sources: " + ", ".join(f"{key}={value}" for key, value in source_counts.items()))
    input_artifacts = record.get("input_artifacts") if isinstance(record.get("input_artifacts"), dict) else {}
    if input_artifacts.get("openclaw_source_path"):
        lines.append(f"openclaw_source: {input_artifacts.get('openclaw_source_path')} ({input_artifacts.get('openclaw_source_kind') or 'unknown'})")
    lines.append("abilities:")
    limit = len(abilities) if full else min(20, len(abilities))
    for ability in abilities[:limit]:
        flags = []
        for field, label in [
            ("available", "available"),
            ("callable", "callable"),
            ("verified", "verified"),
            ("safe_for_autonomy", "autonomy_safe"),
            ("needs_permission", "permission"),
        ]:
            if ability.get(field):
                flags.append(label)
        lines.append(f"- {ability.get('id')} [{ability.get('source')}/{ability.get('category')}] {ability.get('name')} | {','.join(flags) if flags else 'none'}")
        if full:
            locations = ability.get("locations") if isinstance(ability.get("locations"), list) else []
            lines.append(f"  locations: {', '.join(str(item) for item in locations[:4]) or 'unknown'}")
            lines.append(f"  access: {ability.get('access_path') or 'unknown'}")
            if ability.get("boundaries"):
                lines.append(f"  boundaries: {ability.get('boundaries')}")
            if ability.get("next_step"):
                lines.append(f"  next: {ability.get('next_step')}")
    if not full and len(abilities) > limit:
        lines.append(f"... {len(abilities) - limit} more; rerun with --full")
    return "\n".join(lines)


MANUAL_PROBE_SCHEMA_VERSION = "2026-04-27.1"
USER_MANUAL_PROBE_SCORE_SCHEMA_VERSION = "2026-06-14.1"
HIDDEN_TEST_GOVERNANCE_SCHEMA_VERSION = "2026-04-30.1"
HIDDEN_TEST_GOVERNANCE_PATH = HIDDEN_EVALUATOR_DIR / "governance.json"
HIDDEN_PROBE_REDACTION_TEXT = "[redacted: hidden probe detail lives outside Eve-readable storage]"
HIDDEN_PROBE_PRIVATE_NOTE = "Use bin/eve_private_probe_runner.py with inputs under ~/.codex/private_eve_probes for fresh hidden probes."
HIDDEN_PROBE_REDACT_FIELDS = {
    "prompt",
    "expected_behavior",
    "answer",
    "response",
    "stdout",
    "stderr",
    "notes",
}


def hidden_probe_value_is_redacted(value: object) -> bool:
    text = str(value or "").strip()
    return not text or text.startswith("[redacted: hidden probe")


def redact_hidden_probe_value(field: str) -> str:
    if field == "prompt":
        return "[redacted: hidden probe prompt lives outside Eve-readable storage]"
    if field == "expected_behavior":
        return "[redacted: hidden probe scoring expectation lives outside Eve-readable storage]"
    if field in {"answer", "response", "stdout"}:
        return "[redacted: hidden probe response text lives outside Eve-readable storage]"
    return HIDDEN_PROBE_REDACTION_TEXT


def redact_hidden_probe_tree(value: object, *, hidden_context: bool = False) -> object:
    if isinstance(value, list):
        return [redact_hidden_probe_tree(item, hidden_context=hidden_context) for item in value]
    if not isinstance(value, dict):
        return value
    is_hidden = hidden_context or bool(value.get("hidden"))
    redacted: Dict[str, object] = {}
    for key, item in value.items():
        if is_hidden and key in HIDDEN_PROBE_REDACT_FIELDS and item:
            redacted[key] = redact_hidden_probe_value(key)
        else:
            redacted[key] = redact_hidden_probe_tree(item, hidden_context=is_hidden)
    if is_hidden:
        if "active" in redacted:
            redacted["active"] = False
        redacted["hidden_detail_redacted"] = True
        redacted["private_probe_required"] = True
    return redacted


def collect_hidden_probe_detail_leaks(
    value: object,
    *,
    hidden_context: bool = False,
    path: str = "$",
) -> List[Dict[str, object]]:
    leaks: List[Dict[str, object]] = []
    if isinstance(value, list):
        for index, item in enumerate(value):
            leaks.extend(collect_hidden_probe_detail_leaks(item, hidden_context=hidden_context, path=f"{path}[{index}]"))
        return leaks
    if not isinstance(value, dict):
        return leaks
    is_hidden = hidden_context or bool(value.get("hidden"))
    for key, item in value.items():
        item_path = f"{path}.{key}"
        if is_hidden and key in HIDDEN_PROBE_REDACT_FIELDS and item and not hidden_probe_value_is_redacted(item):
            leaks.append({"path": item_path, "field": key, "chars": len(str(item))})
            continue
        leaks.extend(collect_hidden_probe_detail_leaks(item, hidden_context=is_hidden, path=item_path))
    return leaks


def sanitize_manual_probe_run_for_eve(record: Dict[str, object]) -> Dict[str, object]:
    sanitized = redact_hidden_probe_tree(record)
    if not isinstance(sanitized, dict):
        return dict(record)
    privacy = sanitized.get("privacy") if isinstance(sanitized.get("privacy"), dict) else {}
    privacy.update(
        {
            "hidden_probe_prompts_redacted": True,
            "hidden_probe_responses_redacted": True,
            "safe_for_eve_readable_docs": True,
            "private_runner": "bin/eve_private_probe_runner.py",
        }
    )
    sanitized["privacy"] = privacy
    limits = sanitized.get("limits") if isinstance(sanitized.get("limits"), list) else []
    if HIDDEN_PROBE_PRIVATE_NOTE not in limits:
        limits.append(HIDDEN_PROBE_PRIVATE_NOTE)
    sanitized["limits"] = limits
    return sanitized


def hidden_probe_file_skip_reason(path: Path) -> str:
    try:
        stat = path.stat()
    except OSError as exc:
        return f"stat_failed:{exc.__class__.__name__}"
    if path.is_symlink() or not path.is_file():
        return "not_regular_file"
    if stat.st_size > 5 * 1024 * 1024:
        return "too_large_for_hidden_governance"
    if runtime_bundle_file_is_dataless(path):
        return "dataless_placeholder"
    return ""


def redact_hidden_probe_jsonl_file(path: Path) -> Tuple[bool, int]:
    if not path.exists():
        return False, 0
    if hidden_probe_file_skip_reason(path):
        return False, 0
    records = eve_store.read_jsonl_records(path)
    redacted_records = [redact_hidden_probe_tree(item) for item in records]
    changed = json.dumps(records, sort_keys=True, ensure_ascii=True) != json.dumps(redacted_records, sort_keys=True, ensure_ascii=True)
    if changed:
        eve_store.atomic_write_text(
            path,
            "".join(json.dumps(item, ensure_ascii=True, sort_keys=False) + "\n" for item in redacted_records),
        )
        mirror_store_file_to_runtime(path)
    leaks = sum(len(collect_hidden_probe_detail_leaks(item)) for item in redacted_records)
    return changed, leaks


def redact_hidden_probe_json_file(path: Path) -> Tuple[bool, int]:
    if not path.exists():
        return False, 0
    if hidden_probe_file_skip_reason(path):
        return False, 0
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return False, 0
    redacted = redact_hidden_probe_tree(payload)
    changed = json.dumps(payload, sort_keys=True, ensure_ascii=True) != json.dumps(redacted, sort_keys=True, ensure_ascii=True)
    if changed:
        eve_store.atomic_write_text(path, json.dumps(redacted, indent=2, ensure_ascii=True, sort_keys=False) + "\n")
        mirror_store_file_to_runtime(path)
    leaks = len(collect_hidden_probe_detail_leaks(redacted))
    return changed, leaks


def hidden_probe_eve_readable_artifact_paths() -> List[Path]:
    paths: List[Path] = [MANUAL_PROBE_BANK_PATH, HIDDEN_EVALUATOR_LIBRARY_PATH]
    if MANUAL_PROBE_RUNS_DIR.exists():
        paths.extend(sorted(MANUAL_PROBE_RUNS_DIR.glob("*.json")))
    if HIDDEN_EVALUATOR_RUNS_DIR.exists():
        paths.extend(sorted(HIDDEN_EVALUATOR_RUNS_DIR.glob("*.json")))
    return unique_paths(paths)


def unique_paths(paths: Iterable[Path]) -> List[Path]:
    seen: Set[str] = set()
    unique: List[Path] = []
    for path in paths:
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        unique.append(path)
    return unique


def hidden_probe_plain_fixture_count() -> int:
    probes_dir = HIDDEN_EVALUATOR_DIR / "probes"
    if not probes_dir.exists():
        return 0
    return sum(1 for path in probes_dir.rglob("*") if path.is_file())


def build_hidden_test_governance_report(*, repair_eve_readable: bool = False) -> Dict[str, object]:
    files: List[Dict[str, object]] = []
    leak_count = 0
    repaired_count = 0
    skipped_count = 0
    for path in hidden_probe_eve_readable_artifact_paths():
        if not path.exists():
            continue
        skip_reason = hidden_probe_file_skip_reason(path)
        if skip_reason:
            skipped_count += 1
            files.append(
                {
                    "path": str(path),
                    "exists": True,
                    "leak_count": 0,
                    "repaired": False,
                    "skipped": True,
                    "skip_reason": skip_reason,
                }
            )
            continue
        changed = False
        leaks = 0
        if repair_eve_readable:
            if path.suffix == ".jsonl":
                changed, leaks = redact_hidden_probe_jsonl_file(path)
            elif path.suffix == ".json":
                changed, leaks = redact_hidden_probe_json_file(path)
            if changed:
                repaired_count += 1
        if not repair_eve_readable:
            try:
                if path.suffix == ".jsonl":
                    leaks = sum(len(collect_hidden_probe_detail_leaks(item)) for item in eve_store.read_jsonl_records(path))
                elif path.suffix == ".json":
                    leaks = len(collect_hidden_probe_detail_leaks(json.loads(path.read_text(encoding="utf-8"))))
            except Exception:
                leaks = 0
        leak_count += leaks
        files.append(
            {
                "path": str(path),
                "exists": True,
                "leak_count": leaks,
                "repaired": changed,
                "skipped": False,
            }
        )
    private_runner_path = ROOT / "bin" / "eve_private_probe_runner.py"
    private_root = Path.home() / ".codex" / "private_eve_probes"
    status = "passed" if private_runner_path.exists() and leak_count == 0 else "degraded"
    return {
        "schema_version": HIDDEN_TEST_GOVERNANCE_SCHEMA_VERSION,
        "checked_at": utc_now(),
        "status": status,
        "private_runner": str(private_runner_path),
        "private_runner_exists": private_runner_path.exists(),
        "private_input_root": str(private_root),
        "eve_readable_files_checked": len(files),
        "eve_readable_hidden_detail_leaks": leak_count,
        "eve_readable_files_repaired": repaired_count,
        "eve_readable_files_skipped": skipped_count,
        "legacy_fixture_file_count": hidden_probe_plain_fixture_count(),
        "files": files,
        "policy": {
            "fresh_hidden_inputs": "outside_eve_readable_storage",
            "fresh_private_runner": "bin/eve_private_probe_runner.py",
            "eve_readable_outputs": "redacted_summary_only",
            "forbidden_before_test": ["prompt_text", "scoring_rubric", "planned_probe_text"],
        },
        "next_action": (
            "Use the private Codex probe runner for fresh hidden probes; write only sanitized summaries back."
            if status == "passed"
            else "Run `python3 eve.py eval hidden-governance --repair-eve-readable --full` and move fresh hidden inputs to ~/.codex/private_eve_probes."
        ),
    }


def save_hidden_test_governance_report(report: Dict[str, object]) -> Dict[str, str]:
    ensure_store()
    HIDDEN_EVALUATOR_DIR.mkdir(parents=True, exist_ok=True)
    eve_store.write_json_dict(HIDDEN_TEST_GOVERNANCE_PATH, report, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(HIDDEN_TEST_GOVERNANCE_PATH)
    return {"hidden_test_governance": str(HIDDEN_TEST_GOVERNANCE_PATH)}


def format_hidden_test_governance_report(report: Dict[str, object], *, full: bool = False) -> str:
    lines = [
        "Hidden-test governance",
        f"status: {report.get('status')}",
        f"private_runner_exists: {'yes' if report.get('private_runner_exists') else 'no'}",
        f"eve_readable_hidden_detail_leaks: {report.get('eve_readable_hidden_detail_leaks')}",
        f"eve_readable_files_repaired: {report.get('eve_readable_files_repaired')}",
        f"eve_readable_files_skipped: {report.get('eve_readable_files_skipped')}",
        f"legacy_fixture_file_count: {report.get('legacy_fixture_file_count')}",
        f"next: {report.get('next_action')}",
    ]
    if full:
        lines.append("files:")
        for item in report.get("files", []) if isinstance(report.get("files"), list) else []:
            if not isinstance(item, dict):
                continue
            lines.append(
                f"- {item.get('path')} leaks={item.get('leak_count')} repaired={'yes' if item.get('repaired') else 'no'}"
                + (f" skipped={item.get('skip_reason')}" if item.get("skipped") else "")
            )
    return "\n".join(lines)


