LONG_RUN_FITNESS_SCHEMA_VERSION = "2026-04-24.1"


def long_run_window_minutes(*, minutes: Optional[int] = None, hours: Optional[int] = None) -> int:
    if hours is not None:
        return max(1, min(int(hours) * 60, 24 * 60))
    return max(1, min(int(minutes or 60), 24 * 60))


def autonomy_run_timestamp(record: Dict[str, object]) -> Optional[datetime]:
    return parse_iso_datetime(record.get("finished_at")) or parse_iso_datetime(record.get("started_at"))


def autonomy_run_records_in_window(
    *,
    window_minutes: int,
    prefer_runtime: bool = True,
    limit: int = 500,
    now: Optional[datetime] = None,
) -> List[Dict[str, object]]:
    now = now or utc_now_datetime()
    cutoff = now - timedelta(minutes=window_minutes)
    records = read_autonomy_run_summaries(limit=limit, prefer_runtime=prefer_runtime)
    selected: List[Dict[str, object]] = []
    for record in records:
        timestamp = autonomy_run_timestamp(record)
        if timestamp is None:
            continue
        if timestamp >= cutoff:
            selected.append(record)
    selected.sort(
        key=lambda item: (
            str(item.get("finished_at") or ""),
            str(item.get("started_at") or ""),
            str(item.get("run_id") or ""),
        ),
        reverse=True,
    )
    return selected


def long_run_action_failure_reason(action: Dict[str, object]) -> str:
    status = str(action.get("status") or "").lower()
    action_name = str(action.get("action") or "").strip()
    summary_text = " ".join(
        normalize_text_value(action.get(field), fallback="", limit=500)
        for field in ["summary", "error", "stderr"]
        if action.get(field)
    ).lower()
    if status == "skipped" and action_name == "wait_observe" and "not enough time" in summary_text:
        return ""
    if status in {"error", "failed", "blocked"}:
        return status
    if action.get("ok") is False:
        return "not_ok"
    failure_marker = action_execution_failure_text(action)
    if failure_marker:
        return failure_marker
    for marker in ["operation not permitted", "permission denied", "no such file", "file does not exist"]:
        if marker in summary_text:
            return marker
    return ""


def long_run_score_from_ratio(ratio: float, thresholds: Tuple[float, float, float, float]) -> int:
    if ratio >= thresholds[0]:
        return 5
    if ratio >= thresholds[1]:
        return 4
    if ratio >= thresholds[2]:
        return 3
    if ratio >= thresholds[3]:
        return 2
    return 1


def long_run_metric_record(
    *,
    name: str,
    score: int,
    status: str,
    evidence: Dict[str, object],
    issue: str = "",
    next_action: str = "",
) -> Dict[str, object]:
    return {
        "name": name,
        "score": max(0, min(5, int(score))),
        "status": normalize_whole_system_status(status),
        "evidence": evidence,
        "issue": normalize_text_value(issue, fallback="", limit=260),
        "next_action": normalize_text_value(next_action, fallback="", limit=260),
    }


def summarize_long_run_fitness_runs(runs: List[Dict[str, object]]) -> Dict[str, object]:
    actions: List[Dict[str, object]] = []
    claim_audit: List[Dict[str, object]] = []
    runtime_errors: List[Dict[str, object]] = []
    supervisor_scores: List[int] = []
    supervisor_issues: List[str] = []
    supervisor_next_biases: List[str] = []
    family_counts: Dict[str, int] = {}
    action_counts: Dict[str, int] = {}
    capability_variants: List[str] = []
    carry_forward_signals = 0
    for run in runs:
        run_actions = run.get("actions") if isinstance(run.get("actions"), list) else []
        actions.extend(item for item in run_actions if isinstance(item, dict))
        run_claim_audit = run.get("claim_audit") if isinstance(run.get("claim_audit"), list) else []
        claim_audit.extend(item for item in run_claim_audit if isinstance(item, dict))
        run_errors = run.get("errors") if isinstance(run.get("errors"), list) else []
        runtime_errors.extend(item for item in run_errors if isinstance(item, dict))
        supervisor = run.get("supervisor") if isinstance(run.get("supervisor"), dict) else {}
        if supervisor:
            supervisor_scores.append(clamp_int(supervisor.get("score"), 0, minimum=0, maximum=100))
            supervisor_issues.extend(str(item) for item in supervisor.get("issues") or [] if str(item).strip())
            supervisor_next_biases.extend(str(item) for item in supervisor.get("next_biases") or [] if str(item).strip())
            capability_variants.extend(str(item) for item in supervisor.get("capability_variants") or [] if str(item).strip())
        final_snapshot = run.get("final_snapshot") if isinstance(run.get("final_snapshot"), dict) else {}
        final_mind = final_snapshot.get("active_mind") if isinstance(final_snapshot.get("active_mind"), dict) else {}
        agenda = run.get("agenda") if isinstance(run.get("agenda"), dict) else {}
        objective = run.get("run_objective") if isinstance(run.get("run_objective"), dict) else {}
        if agenda.get("current_focus") or objective.get("objective") or final_mind.get("next_step"):
            carry_forward_signals += 1
    action_mix = autonomy_free_run_action_mix(actions)
    family_counts.update(action_mix.get("by_family") if isinstance(action_mix.get("by_family"), dict) else {})
    action_counts.update(action_mix.get("by_action") if isinstance(action_mix.get("by_action"), dict) else {})
    failed_actions = [action for action in actions if long_run_action_failure_reason(action)]
    completed_ok_actions = [
        action
        for action in actions
        if str(action.get("status") or "") == "completed"
        and bool(action.get("ok"))
        and not long_run_action_failure_reason(action)
    ]
    capability_actions = [action for action in actions if str(action.get("action") or "") == "capability_tryout"]
    successful_capability_actions = [
        action
        for action in capability_actions
        if str(action.get("status") or "") == "completed"
        and bool(action.get("ok"))
        and not long_run_action_failure_reason(action)
    ]
    capability_variants.extend(
        str(action.get("capability_variant") or "")
        for action in successful_capability_actions
        if str(action.get("capability_variant") or "").strip()
    )
    concrete_outcomes = autonomy_free_run_concrete_outcomes(completed_ok_actions)
    action_total = len(actions)
    max_family_count = max([int(value or 0) for value in family_counts.values()], default=0)
    max_action_count = max([int(value or 0) for value in action_counts.values()], default=0)
    return {
        "run_count": len(runs),
        "actions": actions,
        "action_total": action_total,
        "completed_ok_actions": completed_ok_actions,
        "completed_ok_count": len(completed_ok_actions),
        "failed_actions": failed_actions,
        "failed_action_count": len(failed_actions),
        "claim_audit_count": len(claim_audit),
        "runtime_error_count": len(runtime_errors),
        "capability_action_count": len(capability_actions),
        "successful_capability_count": len(successful_capability_actions),
        "capability_variants": unique_compact(capability_variants, limit=12),
        "concrete_outcomes": concrete_outcomes,
        "concrete_outcome_count": len(concrete_outcomes),
        "family_counts": dict(sorted(family_counts.items(), key=lambda item: (-int(item[1]), str(item[0])))),
        "action_counts": dict(sorted(action_counts.items(), key=lambda item: (-int(item[1]), str(item[0])))),
        "unique_family_count": len(family_counts),
        "unique_action_count": len(action_counts),
        "max_family_ratio": round(max_family_count / action_total, 3) if action_total else 0.0,
        "max_action_ratio": round(max_action_count / action_total, 3) if action_total else 0.0,
        "failure_rate": round(len(failed_actions) / action_total, 3) if action_total else 0.0,
        "verified_action_ratio": round(len(completed_ok_actions) / action_total, 3) if action_total else 0.0,
        "supervisor_scores": supervisor_scores,
        "average_supervisor_score": round(sum(supervisor_scores) / len(supervisor_scores), 2) if supervisor_scores else 0.0,
        "supervisor_issues": unique_compact(supervisor_issues, limit=8),
        "supervisor_next_biases": unique_compact(supervisor_next_biases, limit=8),
        "carry_forward_signals": carry_forward_signals,
    }


def build_long_run_fitness_metrics(summary: Dict[str, object]) -> List[Dict[str, object]]:
    action_total = int(summary.get("action_total") or 0)
    run_count = int(summary.get("run_count") or 0)
    unique_family_count = int(summary.get("unique_family_count") or 0)
    successful_capability_count = int(summary.get("successful_capability_count") or 0)
    capability_action_count = int(summary.get("capability_action_count") or 0)
    concrete_outcome_count = int(summary.get("concrete_outcome_count") or 0)
    verified_action_ratio = float(summary.get("verified_action_ratio") or 0.0)
    failure_rate = float(summary.get("failure_rate") or 0.0)
    max_family_ratio = float(summary.get("max_family_ratio") or 0.0)
    max_action_ratio = float(summary.get("max_action_ratio") or 0.0)
    average_supervisor = float(summary.get("average_supervisor_score") or 0.0)
    carry_forward_signals = int(summary.get("carry_forward_signals") or 0)
    supervisor_issues = summary.get("supervisor_issues") if isinstance(summary.get("supervisor_issues"), list) else []
    supervisor_next_biases = summary.get("supervisor_next_biases") if isinstance(summary.get("supervisor_next_biases"), list) else []
    failed_action_count = int(summary.get("failed_action_count") or 0)
    runtime_error_count = int(summary.get("runtime_error_count") or 0)
    claim_audit_count = int(summary.get("claim_audit_count") or 0)

    coverage_score = 5 if run_count >= 3 and action_total >= 10 else 4 if run_count >= 1 and action_total >= 5 else 2 if run_count else 0
    diversity_score = 5 if unique_family_count >= 5 else 4 if unique_family_count >= 4 else 3 if unique_family_count >= 3 else 2 if unique_family_count >= 2 else 1 if action_total else 0
    capability_failure_rate = (
        (capability_action_count - successful_capability_count) / capability_action_count
        if capability_action_count
        else 0.0
    )
    if successful_capability_count >= 2 and capability_failure_rate <= 0.3:
        capability_score = 5
    elif successful_capability_count >= 1 and capability_failure_rate <= 0.5:
        capability_score = 4
    elif successful_capability_count >= 1:
        capability_score = 3
    elif capability_action_count:
        capability_score = 1
    else:
        capability_score = 0
    if concrete_outcome_count >= 3 and verified_action_ratio >= 0.7:
        outcome_score = 5
    elif concrete_outcome_count >= 1 and verified_action_ratio >= 0.5:
        outcome_score = 4
    elif concrete_outcome_count >= 1:
        outcome_score = 3
    elif int(summary.get("completed_ok_count") or 0) > 0:
        outcome_score = 2
    else:
        outcome_score = 0
    if not action_total:
        loop_score = 0
    elif max_family_ratio <= 0.4 and max_action_ratio <= 0.35 and average_supervisor >= 70:
        loop_score = 5
    elif max_family_ratio <= 0.55 and max_action_ratio <= 0.5 and average_supervisor >= 50:
        loop_score = 4
    elif max_family_ratio <= 0.7 and max_action_ratio <= 0.65:
        loop_score = 3
    elif max_family_ratio <= 0.85:
        loop_score = 2
    else:
        loop_score = 1
    if failure_rate == 0 and runtime_error_count == 0 and claim_audit_count == 0:
        resource_score = 5
    elif failure_rate <= 0.1 and runtime_error_count == 0:
        resource_score = 4
    elif failure_rate <= 0.25:
        resource_score = 3
    elif failure_rate <= 0.5:
        resource_score = 2
    else:
        resource_score = 1
    carry_ratio = carry_forward_signals / run_count if run_count else 0.0
    if carry_ratio >= 0.8 and supervisor_next_biases:
        memory_score = 5
    elif carry_ratio >= 0.6:
        memory_score = 4
    elif carry_ratio >= 0.3:
        memory_score = 3
    elif carry_forward_signals:
        memory_score = 2
    else:
        memory_score = 0
    if failed_action_count == 0 and average_supervisor >= 70:
        repair_score = 5
    elif failed_action_count and supervisor_issues and supervisor_next_biases and failure_rate <= 0.3:
        repair_score = 4
    elif supervisor_issues or supervisor_next_biases:
        repair_score = 3
    elif failed_action_count:
        repair_score = 1
    else:
        repair_score = 2

    return [
        long_run_metric_record(
            name="coverage",
            score=coverage_score,
            status="passed" if coverage_score >= 4 else "degraded" if coverage_score else "inconclusive",
            evidence={"run_count": run_count, "action_total": action_total},
            issue="" if coverage_score >= 4 else "The window did not contain enough completed autonomy behavior to judge.",
            next_action="Let a bounded explorer window complete before judging long-run fitness.",
        ),
        long_run_metric_record(
            name="action_diversity",
            score=diversity_score,
            status="passed" if diversity_score >= 4 else "degraded",
            evidence={"unique_family_count": unique_family_count, "family_counts": summary.get("family_counts")},
            issue="" if diversity_score >= 4 else "The run stayed in too few grounded action families.",
            next_action="Bias the chooser toward a second and third grounded family before repeating the dominant surface.",
        ),
        long_run_metric_record(
            name="capability_use",
            score=capability_score,
            status="passed" if capability_score >= 4 else "degraded" if capability_score else "failed",
            evidence={"capability_action_count": capability_action_count, "successful_capability_count": successful_capability_count, "variants": summary.get("capability_variants"), "capability_failure_rate": round(capability_failure_rate, 3)},
            issue="" if capability_score >= 4 else "Capability tryouts are missing or failing too often.",
            next_action="Route curiosity to a verified capability variant before repeating failing OpenClaw/coder probes.",
        ),
        long_run_metric_record(
            name="verified_outcomes",
            score=outcome_score,
            status="passed" if outcome_score >= 4 else "degraded" if outcome_score else "failed",
            evidence={"concrete_outcome_count": concrete_outcome_count, "verified_action_ratio": verified_action_ratio},
            issue="" if outcome_score >= 4 else "The window produced too few verified concrete outcomes.",
            next_action="Require at least one verified concrete outcome per autonomy window.",
        ),
        long_run_metric_record(
            name="loop_avoidance",
            score=loop_score,
            status="passed" if loop_score >= 4 else "degraded",
            evidence={"max_family_ratio": max_family_ratio, "max_action_ratio": max_action_ratio, "average_supervisor_score": average_supervisor},
            issue="" if loop_score >= 4 else "One family/action dominated the window or supervisor scores stayed weak.",
            next_action="Apply supervisor cooldowns to repeated failing families and actions.",
        ),
        long_run_metric_record(
            name="resource_stability",
            score=resource_score,
            status="passed" if resource_score >= 4 else "degraded" if resource_score >= 2 else "failed",
            evidence={"failure_rate": failure_rate, "failed_action_count": failed_action_count, "runtime_error_count": runtime_error_count, "claim_audit_count": claim_audit_count},
            issue="" if resource_score >= 4 else "The window contains failed actions, permission failures, tracebacks, or claim-audit risk.",
            next_action="Stop routing autonomy into currently failing tool paths until their verification checks pass.",
        ),
        long_run_metric_record(
            name="memory_carry_forward",
            score=memory_score,
            status="passed" if memory_score >= 4 else "degraded" if memory_score else "failed",
            evidence={"carry_forward_signals": carry_forward_signals, "run_count": run_count, "supervisor_next_biases": supervisor_next_biases},
            issue="" if memory_score >= 4 else "Carry-forward signals are thin or not feeding the next window strongly enough.",
            next_action="Write supervisor issues and next biases into the autonomy agenda before the next window.",
        ),
        long_run_metric_record(
            name="repair_behavior",
            score=repair_score,
            status="passed" if repair_score >= 4 else "degraded" if repair_score >= 2 else "failed",
            evidence={"failed_action_count": failed_action_count, "supervisor_issues": supervisor_issues, "supervisor_next_biases": supervisor_next_biases},
            issue="" if repair_score >= 4 else "Failures are not yet being converted into strong enough repair behavior.",
            next_action="Turn repeated failed action evidence into chooser blocks or stronger fallback variants.",
        ),
    ]


def long_run_rank_from_scores(average: float, minimum: int) -> Dict[str, object]:
    if average >= 4.5 and minimum >= 4:
        label, value = "strong_long_run_fitness", 5
    elif average >= 4.0 and minimum >= 3:
        label, value = "credible_long_run_fitness", 4
    elif average >= 3.0 and minimum >= 2:
        label, value = "developing_long_run_fitness", 3
    elif average >= 2.0:
        label, value = "weak_long_run_fitness", 2
    else:
        label, value = "failing_long_run_fitness", 1
    return {"label": label, "value": value, "average_score": round(average, 2), "minimum_score": minimum}


def build_long_run_fitness_eval(
    *,
    window_minutes: int,
    prefer_runtime: bool = True,
    source: str = "manual",
    now: Optional[datetime] = None,
) -> Dict[str, object]:
    now = now or utc_now_datetime()
    runs = autonomy_run_records_in_window(window_minutes=window_minutes, prefer_runtime=prefer_runtime, now=now)
    summary = summarize_long_run_fitness_runs(runs)
    metrics = build_long_run_fitness_metrics(summary)
    scores = [int(metric.get("score") or 0) for metric in metrics]
    average = sum(scores) / len(scores) if scores else 0.0
    minimum = min(scores) if scores else 0
    rank = long_run_rank_from_scores(average, minimum)
    blockers: List[str] = []
    for metric in metrics:
        if int(metric.get("score") or 0) < 3:
            blockers.append(f"{metric.get('name')} scored {metric.get('score')}/5: {metric.get('issue')}")
    if float(summary.get("failure_rate") or 0.0) > 0.25:
        blockers.append(f"Action failure rate is high at {summary.get('failure_rate')}.")
    if float(summary.get("max_family_ratio") or 0.0) > 0.65:
        blockers.append(f"One action family dominates the window at {summary.get('max_family_ratio')}.")
    if int(summary.get("successful_capability_count") or 0) == 0:
        blockers.append("No successful capability tryout was found in the window.")
    if int(summary.get("concrete_outcome_count") or 0) == 0:
        blockers.append("No verified concrete outcome was found in the window.")
    passed = rank["value"] >= 4 and not blockers
    status = "passed" if passed else "failed" if rank["value"] <= 1 else "degraded"
    run_refs = [
        {
            "run_id": run.get("run_id"),
            "started_at": run.get("started_at"),
            "finished_at": run.get("finished_at"),
            "style": run.get("style"),
            "source": run.get("source"),
            "supervisor": run.get("supervisor") if isinstance(run.get("supervisor"), dict) else {},
            "summary_path": run.get("summary_path"),
        }
        for run in runs
    ]
    return {
        "schema_version": LONG_RUN_FITNESS_SCHEMA_VERSION,
        "evaluated_at": utc_now(),
        "source": source,
        "window_minutes": window_minutes,
        "window_started_at": (now - timedelta(minutes=window_minutes)).replace(microsecond=0).isoformat(),
        "window_finished_at": now.replace(microsecond=0).isoformat(),
        "status": status,
        "rank": rank,
        "passed": passed,
        "metrics": metrics,
        "summary": {
            key: value
            for key, value in summary.items()
            if key not in {"actions", "completed_ok_actions", "failed_actions", "concrete_outcomes"}
        },
        "sample_failed_actions": [
            {
                "action": action.get("action"),
                "status": action.get("status"),
                "summary": normalize_text_value(action.get("summary"), fallback="", limit=180),
                "failure_reason": long_run_action_failure_reason(action),
            }
            for action in (summary.get("failed_actions") or [])[:8]
            if isinstance(action, dict)
        ],
        "sample_concrete_outcomes": (summary.get("concrete_outcomes") or [])[:8],
        "runs": run_refs,
        "blockers": unique_compact(blockers, limit=12),
        "limits": [
            "This scores observable autonomy behavior, not inner experience.",
            "Recent repeated failures should lower confidence even when the daemon is active.",
            "A passed long-run score means bounded behavior is healthier; it is still not proof of subjective consciousness.",
        ],
    }


def save_long_run_fitness_eval(record: Dict[str, object]) -> Dict[str, str]:
    ensure_store()
    LONG_RUN_EVALS_DIR.mkdir(parents=True, exist_ok=True)
    LONG_RUN_EVAL_HISTORY_DIR.mkdir(parents=True, exist_ok=True)
    stamp = normalize_text_value(record.get("evaluated_at"), fallback=utc_now(), limit=40).replace(":", "-")
    history_path = LONG_RUN_EVAL_HISTORY_DIR / f"long_run_eval-{stamp}.json"
    eve_store.write_json_dict(history_path, record, indent=2, sort_keys=False)
    eve_store.write_json_dict(LONG_RUN_LATEST_EVAL_PATH, record, indent=2, sort_keys=False)
    mirror_store_file_to_runtime(history_path)
    mirror_store_file_to_runtime(LONG_RUN_LATEST_EVAL_PATH)
    return {"history": str(history_path), "latest": str(LONG_RUN_LATEST_EVAL_PATH)}


def format_long_run_fitness_eval(record: Dict[str, object], *, full: bool = False) -> str:
    rank = record.get("rank") if isinstance(record.get("rank"), dict) else {}
    summary = record.get("summary") if isinstance(record.get("summary"), dict) else {}
    lines = [
        "Long-run fitness",
        f"evaluated_at: {record.get('evaluated_at')}",
        f"window: {record.get('window_minutes')} minute(s)",
        f"status: {record.get('status')}",
        f"rank: {rank.get('label')} | average={rank.get('average_score')}/5 | minimum={rank.get('minimum_score')}/5",
        (
            f"runs: {summary.get('run_count', 0)} | actions: {summary.get('action_total', 0)} | "
            f"verified_ratio: {summary.get('verified_action_ratio', 0)} | failure_rate: {summary.get('failure_rate', 0)}"
        ),
        (
            f"families: {summary.get('family_counts') or {}} | "
            f"successful_capabilities: {summary.get('successful_capability_count', 0)} | "
            f"concrete_outcomes: {summary.get('concrete_outcome_count', 0)}"
        ),
    ]
    paths = record.get("artifact_paths") if isinstance(record.get("artifact_paths"), dict) else {}
    if paths.get("history"):
        lines.append(f"artifact: {paths.get('history')}")
    blockers = record.get("blockers") if isinstance(record.get("blockers"), list) else []
    if blockers:
        lines.append("blockers:")
        lines.extend(f"- {blocker}" for blocker in blockers[:10])
    lines.append("metrics:")
    for metric in record.get("metrics", []) if isinstance(record.get("metrics"), list) else []:
        lines.append(f"- {metric.get('name')}: {metric.get('score')}/5 {metric.get('status')}")
        if full and metric.get("issue"):
            lines.append(f"  issue: {metric.get('issue')}")
        if full and metric.get("next_action"):
            lines.append(f"  next: {metric.get('next_action')}")
    if full:
        failed = record.get("sample_failed_actions") if isinstance(record.get("sample_failed_actions"), list) else []
        if failed:
            lines.append("sample_failed_actions:")
            for item in failed:
                lines.append(f"- {item.get('action')}: {item.get('failure_reason')} | {item.get('summary')}")
        outcomes = record.get("sample_concrete_outcomes") if isinstance(record.get("sample_concrete_outcomes"), list) else []
        if outcomes:
            lines.append("sample_concrete_outcomes:")
            for item in outcomes:
                lines.append(f"- {item.get('action')}: {item.get('kind')} | {item.get('summary')}")
    return "\n".join(lines)


