def cmd_eval_gaps(args: argparse.Namespace) -> int:
    gaps = read_eval_gap_records(
        limit=None if args.full else args.limit,
        since_days=args.days,
        status=args.status,
        component=args.component,
        owner=args.owner,
        prefer_runtime=bool(args.runtime),
        latest_only=not args.all,
        suppress_superseded_by_latest=not args.all,
    )
    source = "gap_log"
    if not gaps:
        fallback_gaps = eval_gap_records_from_latest_whole_system(prefer_runtime=bool(args.runtime))
        fallback_gaps = filter_eval_gap_records(fallback_gaps, status=args.status, component=args.component, owner=args.owner)
        if not args.all:
            fallback_gaps = latest_eval_gap_records(fallback_gaps)
        gaps = [classify_eval_gap(item) for item in fallback_gaps]
        gaps.sort(key=eval_gap_sort_key)
        if not args.full and args.limit is not None:
            gaps = gaps[: max(0, args.limit)]
        source = "latest_whole_system_artifact"
    summary = summarize_eval_gaps(gaps)
    summary["source"] = source
    if args.json:
        print(json.dumps(summary, indent=2, ensure_ascii=True))
        return 0
    print(format_eval_gap_summary(summary, full=args.full))
    print(f"source: {source}")
    return 0


