def cmd_eval_manual_probe(args: argparse.Namespace) -> int:
    if getattr(args, "record_user_result", None):
        try:
            payload = load_user_manual_probe_result_payload(str(args.record_user_result))
            record = record_user_manual_probe_result(payload)
        except (OSError, ValueError) as exc:
            print(f"Could not record user manual-probe result: {exc}", file=sys.stderr)
            return 2
        if args.json:
            print(json.dumps({"record": record, "ledger": str(MANUAL_PROBE_MANUAL_SCORES_PATH)}, indent=2, ensure_ascii=True))
            return 0
        print(format_user_manual_probe_score_record(record))
        return 0
