def cmd_eval_scorecard(args: argparse.Namespace) -> int:
    evaluations = read_evaluations(
        limit=args.limit,
        target_kind=args.target_kind,
        target_id=args.target_id,
        evaluator=args.evaluator,
        thread_id=args.thread,
        since_days=args.days,
    )
    outcomes = read_outcomes(
        limit=args.limit,
        target_kind=args.target_kind,
        target_id=args.target_id,
        thread_id=args.thread,
        since_days=args.days,
    )
    scorecard = summarize_scorecard(evaluations)
    outcome_summary = summarize_outcomes(outcomes)
    print("Scorecard")
    print(f"reviews: {scorecard['review_count']}")
    print(f"overall: {format_score_average(scorecard['overall'])}")
    for field in SCORECARD_FIELDS:
        print(f"{field}: {format_score_average(scorecard['averages'][field])}")
    weak_fields = [SCORECARD_LABELS[field] for field in scorecard["weak_fields"]]
    print(f"fragile_dimensions: {', '.join(weak_fields) if weak_fields else 'none recorded'}")
    print(f"reviewed_targets: {format_target_breakdown(scorecard['by_target_kind'])}")
    print()
    print("Outcome signals")
    print(f"positive: {outcome_summary['counts']['positive']}")
    print(f"mixed: {outcome_summary['counts']['mixed']}")
    print(f"neutral: {outcome_summary['counts']['neutral']}")
    print(f"negative: {outcome_summary['counts']['negative']}")
    print(f"outcome_targets: {format_target_breakdown(outcome_summary['by_target_kind'])}")
    if scorecard["recent_notes"]:
        print(f"recent_evaluation_notes: {'; '.join(scorecard['recent_notes'])}")
    if outcome_summary["recent_summaries"]:
        print(f"recent_outcomes: {'; '.join(outcome_summary['recent_summaries'])}")
    return 0


