def cmd_failure_review(args: argparse.Namespace) -> int:
    config = load_config()
    if args.days:
        config["failure_review_days"] = args.days
    if args.threshold:
        config["failure_review_score_threshold"] = args.threshold
    if args.max_clusters:
        config["failure_review_max_clusters"] = args.max_clusters
    clusters = review_failure_patterns(config, source="manual")
    if not clusters:
        print("No failure clusters found in the current review window.")
        return 0
    print(f"Reviewed {len(clusters)} failure cluster{'s' if len(clusters) != 1 else ''}.")
    print()
    for cluster in clusters:
        print(f"{cluster['id']} [{cluster['status']}] {cluster['title']}")
        print(f"summary: {cluster['summary']}")
        print(f"root_cause: {cluster['suspected_root_cause']}")
        print(f"repair: {cluster['exact_repair']}")
        print()
    return 0


