def cmd_failure_update(args: argparse.Namespace) -> int:
    changes: Dict[str, object] = {}
    if args.status:
        changes["status"] = args.status
    if args.summary:
        changes["summary"] = args.summary
    if args.root_cause:
        changes["suspected_root_cause"] = args.root_cause
    if args.repair:
        changes["exact_repair"] = args.repair
    if args.resolution_note:
        evidence = []
        try:
            clusters = read_jsonl_records(FAILURE_CLUSTERS_PATH)
            cluster = clusters[find_record_index(clusters, args.id)]
            evidence = list(cluster.get("evidence") or [])
        except SystemExit:
            evidence = []
        evidence = unique_compact([*evidence, args.resolution_note], limit=5)
        changes["evidence"] = evidence
    if not changes:
        raise SystemExit("Provide at least one update field.")
    cluster = update_failure_cluster_record(args.id, **changes)
    print(f"Updated failure cluster {cluster['id']} -> {cluster.get('status') or 'open'}")
    return 0


