def cmd_review_request(args: argparse.Namespace) -> int:
    config = load_config()
    reviewer = normalize_reviewer_name(args.reviewer)
    via = args.via or default_review_request_via(reviewer)
    packet = build_review_packet(
        config,
        reviewer=reviewer,
        kind=args.kind,
        days=args.days or int(config["review_packet_days"]),
        context_limit=args.context or int(config["review_packet_context_limit"]),
    )
    if via == "manual":
        update_review_packet_record(packet["id"], status="requested", request_via=via)
        print(f"Prepared review packet {packet['id']}")
        print(packet["path"])
        print()
        print(f"Recorded a manual review request for {reviewer}.")
        print("Capture the reply with `python3 eve.py review add --reviewer ...` when it comes back.")
        return 0
    if via != "claude":
        raise SystemExit(f"Unsupported review transport: {via}")
    if reviewer_token(reviewer, fallback="") != CLAUDE_PARTICIPANT:
        raise SystemExit("The Claude bridge can only queue review requests for Claude. Use --via manual for Codex or other reviewers.")
    subject = args.subject or f"Eve review request {packet['id'][:8]}"
    message = create_message(
        sender="eve",
        recipient=CLAUDE_PARTICIPANT,
        subject=subject,
        body=build_external_review_request(packet),
        kind="review_request",
        status="unread",
        metadata=claude_message_metadata(
            direction="eve_to_claude",
            review_packet_id=packet["id"],
            review_kind=packet["kind"],
            review_transport=via,
            review_reviewer=reviewer,
        ),
    )
    update_review_packet_record(packet["id"], status="requested", request_message_id=message["id"], request_via=via)
    print(f"Prepared review packet {packet['id']}")
    print(packet["path"])
    print()
    print(f"Queued {reviewer} review request {message['id']} via Claude bridge")
    return 0


def cmd_review_request_claude(args: argparse.Namespace) -> int:
    alias_args = argparse.Namespace(**vars(args), reviewer=CLAUDE_LABEL, via="claude")
    return cmd_review_request(alias_args)


def cmd_review_capture(args: argparse.Namespace) -> int:
    if args.via != "claude":
        raise SystemExit(f"Unsupported review capture transport: {args.via}")
    messages = read_jsonl_records(MESSAGES_PATH)
    index = find_record_index(messages, args.message_id)
    message = messages[index]
    if not message_is_for_claude(message) or str(message.get("sender")) != CLAUDE_PARTICIPANT:
        raise SystemExit("The target message is not a Claude reply.")
    packet = review_packet_from_reply_message(message)
    packet_id = str(packet.get("id")) if packet else ""
    note = create_review_note(
        reviewer=normalize_reviewer_name(args.reviewer or CLAUDE_LABEL),
        body=str(message.get("body") or ""),
        source="claude_bridge",
        packet_id=packet_id,
        message_id=str(message["id"]),
        summary_override=args.summary or "",
        status="active",
    )
    if packet_id:
        update_review_packet_record(packet_id, status="reviewed", review_message_id=message["id"])
    print(f"Captured review note {note['id']}")
    print(f"summary: {note['summary']}")
    return 0


