def cmd_updates_mirror(args: argparse.Namespace) -> int:
    config = load_config()
    watchlist = component_watchlist(config)
    selected = [item for item in watchlist if item.get("repository")] if args.all else [item for item in watchlist if str(item.get("id") or "") == args.component]
    if not selected:
        raise SystemExit(f"No component matched `{args.component}`.")
    for component in selected:
        result = mirror_component_upstream(config, component, timeout=args.timeout)
        print(f"{component.get('id')}: {'ok' if result.get('ok') else 'failed'} {result.get('action') or ''} {result.get('path') or ''}")
        if result.get("error"):
            print(f"  {result['error']}")
    state = check_component_updates(config, mirror=False, timeout=min(args.timeout, 120))
    print()
    print(state.get("summary") or "Component mirrors refreshed.")
    return 0


