def cmd_task_refresh(args: argparse.Namespace) -> int:
    delegated = delegate_cli_to_runtime(
        [
            "task",
            "refresh",
            *(["--run-cpu"] if args.run_cpu else []),
            *(["--cpu-limit", str(args.cpu_limit)] if args.cpu_limit is not None else []),
        ],
        timeout_seconds=120,
    )
    if delegated is not None:
        return delegated
    config = load_config()
    state = load_state()
    snapshot = load_system_snapshot(prefer_runtime=True)
    if not snapshot:
        raise SystemExit("No system snapshot is available yet. Wait for the observer or run it once first.")
    created = refresh_system_tasks_from_snapshot(snapshot, state, source="manual", config=config)
    state["last_system_task_refresh_at"] = utc_now()
    completed: List[Dict[str, object]] = []
    maintenance: List[Dict[str, object]] = []
    if args.run_cpu:
        completed = run_pending_cpu_system_tasks(config, state, snapshot, source="manual", limit=args.cpu_limit)
        maintenance = run_pending_safe_maintenance_tasks(config, state, snapshot, source="manual", limit=max(1, min(args.cpu_limit, 3)))
    save_state(state)
    print(f"created_or_updated: {len(created)}")
    if created:
        for task in created:
            print(f"- {task['id']} {task['title']} [{task['lane']}]")
    if args.run_cpu:
        print(f"cpu_completed: {len(completed)}")
        for task in completed:
            print(f"- {task['id']} {task['title']}")
        print(f"maintenance_processed: {len(maintenance)}")
        for task in maintenance:
            print(f"- {task['id']} {task['title']} [{task['status']}]")
    return 0


def cmd_task_run(args: argparse.Namespace) -> int:
    delegated = delegate_cli_to_runtime(
        ["task", "run", "--limit", str(args.limit)],
        timeout_seconds=120,
    )
    if delegated is not None:
        return delegated
    config = load_config()
    state = load_state()
    snapshot = load_system_snapshot(prefer_runtime=True)
    if not snapshot:
        raise SystemExit("No system snapshot is available yet. Wait for the observer or run it once first.")
    completed = run_pending_cpu_system_tasks(config, state, snapshot, source="manual", limit=args.limit)
    maintenance = run_pending_safe_maintenance_tasks(config, state, snapshot, source="manual", limit=max(1, min(args.limit, 3)))
    save_state(state)
    if not completed and not maintenance:
        print("No planned CPU or maintenance tasks were ready.")
        return 0
    print(f"cpu_completed: {len(completed)}")
    for task in completed:
        print(f"- {task['id']} {task['title']}")
        if task.get("result_summary"):
            print(f"  {task['result_summary']}")
    print(f"maintenance_processed: {len(maintenance)}")
    for task in maintenance:
        print(f"- {task['id']} {task['title']} [{task['status']}]")
        if task.get("result_summary"):
            print(f"  {task['result_summary']}")
    return 0


