def format_beads_task_bridge(report: Dict[str, object], *, full: bool = False) -> str:
    parity = report.get("parity") if isinstance(report.get("parity"), dict) else {}
    operations = report.get("operations") if isinstance(report.get("operations"), dict) else {}
    projection = report.get("projection") if isinstance(report.get("projection"), dict) else {}
    lines = [
        "Eve -> Beads task bridge",
        f"status: {report.get('status') or 'unknown'}",
        f"mode: {'apply' if report.get('apply') else 'preview'}",
        f"generated_at: {report.get('generated_at') or 'unknown'}",
        (
            f"projection: active={projection.get('active_task_count', 0)} | "
            f"tasks={projection.get('selected_task_count', 0)} | edges={len(projection.get('edges') or [])}"
        ),
        (
            f"parity: {'ok' if parity.get('ok') else 'not_verified'} | "
            f"tasks={parity.get('observed_task_count', 0)}/{parity.get('expected_task_count', 0)} | "
            f"edges={parity.get('observed_edge_count', 0)}/{parity.get('expected_edge_count', 0)} | "
            f"ready={parity.get('observed_ready_count', 0)}/{parity.get('expected_ready_count', 0)}"
        ),
        (
            "operations: "
            f"created={operations.get('created', 0)}, updated={operations.get('updated', 0)}, "
            f"retired={operations.get('retired', 0)}, dependencies_added={operations.get('dependencies_added', 0)}, "
            f"dependencies_removed={operations.get('dependencies_removed', 0)}"
        ),
        "authority: one-way Eve-to-Beads projection; Eve remains task, memory, permission, goal, and scheduler authority.",
    ]
    if report.get("apply"):
        lines.append(f"artifact: {BEADS_BRIDGE_PATH}")
    if report.get("blockers"):
        lines.append("blockers:")
        lines.extend(f"- {item}" for item in report.get("blockers") or [])
    if full and parity:
        for key in (
            "missing_task_ids",
            "status_mismatches",
            "missing_edges",
            "extra_edges",
            "ready_missing",
            "ready_extra",
            "observation_errors",
        ):
            values = parity.get(key) if isinstance(parity.get(key), list) else []
            if values:
                lines.append(f"{key}: {json.dumps(values, sort_keys=True)}")
    return "\n".join(lines)


def cmd_task_beads(args: argparse.Namespace) -> int:
    delegated = delegate_cli_to_runtime(
        [
            "task",
            "beads",
            *(["--apply"] if args.apply else []),
            "--max-tasks",
            str(args.max_tasks),
            "--timeout",
            str(args.timeout),
            *(["--full"] if args.full else []),
        ],
        timeout_seconds=max(60, int(args.timeout or 15) * max(4, int(args.max_tasks or 80))),
    )
    if delegated is not None:
        return delegated
    report = run_beads_task_bridge(
        apply=bool(args.apply),
        max_tasks=max(1, int(args.max_tasks or 80)),
        timeout=max(3, int(args.timeout or 15)),
    )
    print(format_beads_task_bridge(report, full=bool(args.full)))
    return 0 if str(report.get("status") or "") in {"preview", "verified"} else 1


