def cmd_maintenance_update(args: argparse.Namespace) -> int:
    delegated = delegate_cli_to_runtime(
        [
            "maintenance",
            "update",
            str(args.id),
            *(["--status", str(args.status)] if args.status else []),
            *(["--blocked-reason", str(args.blocked_reason)] if args.blocked_reason is not None else []),
            *(["--result-summary", str(args.result_summary)] if args.result_summary is not None else []),
        ],
        timeout_seconds=30,
    )
    if delegated is not None:
        return delegated
    changes: Dict[str, object] = {}
    if args.status:
        changes["status"] = args.status
    if args.blocked_reason is not None:
        changes["blocked_reason"] = args.blocked_reason
    if args.result_summary is not None:
        changes["result_summary"] = args.result_summary
    if not changes:
        raise SystemExit("Provide at least one update field.")
    action = update_maintenance_action_record(args.id, **changes)
    state = load_state()
    recompute_maintenance_action_summary(state)
    save_state(state)
    print(f"Updated maintenance action {action['id']} -> {action['status']}")
    return 0


def cmd_maintenance_run(args: argparse.Namespace) -> int:
    delegated = delegate_cli_to_runtime(
        ["maintenance", "run", "--limit", str(args.limit)],
        timeout_seconds=120,
    )
    if delegated is not None:
        return delegated
    config = load_config()
    state = load_state()
    processed = run_approved_maintenance_actions(config, state, source="manual", limit=args.limit)
    save_state(state)
    if not processed:
        print("No approved maintenance actions were ready.")
        return 0
    print(f"maintenance_executed: {len(processed)}")
    for action in processed:
        print(f"- {action['id']} {action['title']} [{action['status']}]")
        if action.get("result_summary"):
            print(f"  {action['result_summary']}")
    return 0


