def cmd_codex_handoff(args: argparse.Namespace) -> int:
    config = dict(load_config())
    config["_codex_handoff_objective"] = args.objective
    config["_codex_handoff_subject"] = args.subject or "Bounded Codex independent-operator handoff"
    config["_codex_handoff_repository"] = args.repository or str(ROOT)
    config["_codex_handoff_mode"] = "diagnosis_only" if args.diagnosis_only else args.mode
    if args.acceptance:
        config["_codex_handoff_acceptance"] = args.acceptance
    if args.constraints:
        config["_codex_handoff_constraints"] = args.constraints
    result = run_operational_action_tree(
        "codex_independent_handoff",
        config,
        source="manual_codex_handoff",
    )
    if args.json:
        # This is an explicit command response requested with --json, not a log record.
        # codeql[py/clear-text-logging-sensitive-data]
        print(json.dumps(result, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(result.get("response") or result.get("summary") or "Codex handoff finished.")
        if result.get("message_id"):
            print(f"message_id: {result.get('message_id')}")
        if result.get("execution_id"):
            print(f"action_execution_id: {result.get('execution_id')}")
    return 0 if action_result_verified_for_completion(result) else 1


