def cmd_talk(args: argparse.Namespace) -> int:
    config = load_config()
    thread_id = str(uuid.uuid4())
    print("Eve talk session started. Type `/quit` to exit.")
    if args.first:
        first_message = create_message(
            sender="user",
            recipient="eve",
            subject=args.subject or "Talk session",
            body=args.first,
            kind="user_message",
            thread_id=thread_id,
            status="sent",
        )
        reply = generate_eve_reply(config, first_message, recipient="user", counterpart_label="the user")
        print()
        print("eve>")
        print(reply["body"])
    while True:
        try:
            user_text = input("\nyou> ").strip()
        except EOFError:
            print()
            break
        if not user_text:
            continue
        if user_text in {"/quit", "/exit"}:
            break
        user_message = create_message(
            sender="user",
            recipient="eve",
            subject=args.subject or "Talk session",
            body=user_text,
            kind="user_message",
            thread_id=thread_id,
            status="sent",
        )
        reply = generate_eve_reply(config, user_message, recipient="user", counterpart_label="the user")
        print()
        print("eve>")
        print(reply["body"])
    print("Talk session ended.")
    return 0


def cmd_code_ask(args: argparse.Namespace) -> int:
    config = load_config()
    ensure_version_snapshot(source="code_runtime")
    apply_transient_model_override(config, args.model)
    session_id = normalize_code_session_id(args.session or "")
    try:
        result = run_eve_coder_agent(
            config,
            args.request,
            session_id=session_id,
            model_override=args.model,
            max_tokens=args.max_tokens,
            require_tool_use=not args.no_require_tool,
        )
    except SystemExit as exc:
        append_code_session_event(
            session_id,
            "error",
            {"request": args.request, "error": normalize_text_value(exc, fallback="Coder mode failed.", limit=500)},
        )
        raise
    print(str(result.get("response") or "").strip())
    if args.show_session:
        print()
        print(f"session_id: {session_id}")
        print(f"session_log: {code_session_path(session_id)}")
    return 0


def cmd_code_session(args: argparse.Namespace) -> int:
    config = load_config()
    ensure_version_snapshot(source="code_session_runtime")
    apply_transient_model_override(config, args.model)
    session_id = normalize_code_session_id(args.session or "")
    print(f"Eve coder session started: {session_id}. Type `/quit` to exit.")

    def run_turn(request_text: str) -> None:
        try:
            result = run_eve_coder_agent(
                config,
                request_text,
                session_id=session_id,
                model_override=args.model,
                max_tokens=args.max_tokens,
                require_tool_use=not args.no_require_tool,
            )
            print()
            print("eve-code>")
            print(str(result.get("response") or "").strip())
        except SystemExit as exc:
            append_code_session_event(
                session_id,
                "error",
                {"request": request_text, "error": normalize_text_value(exc, fallback="Coder mode failed.", limit=500)},
            )
            print()
            print("eve-code-error>")
            print(str(exc))

    if args.first:
        run_turn(args.first)
    while True:
        try:
            user_text = input("\nyou-code> ").strip()
        except EOFError:
            print()
            break
        if not user_text:
            continue
        if user_text in {"/quit", "/exit"}:
            break
        run_turn(user_text)
    print(f"Coder session ended. Log: {code_session_path(session_id)}")
    return 0


