def cmd_code_open(args: argparse.Namespace) -> int:
    events = read_code_session_events(args.session, limit=args.limit)
    if not events:
        raise SystemExit(f"No coder session found for `{args.session}`.")
    for event in events:
        print(f"{event.get('timestamp')} [{event.get('type')}] {event.get('id')}")
        if args.full:
            print(json.dumps(event, indent=2, ensure_ascii=True))
        else:
            if event.get("request"):
                print(f"request: {normalize_text_value(event.get('request'), fallback='', limit=260)}")
            if event.get("tool"):
                result = event.get("result") if isinstance(event.get("result"), dict) else {}
                print(f"tool: {event.get('tool')} | ok: {result.get('ok')}")
            if event.get("response"):
                print(normalize_text_value(event.get("response"), fallback="", limit=500))
            if event.get("error"):
                print(f"error: {normalize_text_value(event.get('error'), fallback='', limit=500)}")
        print()
    return 0


def cmd_code_compact(args: argparse.Namespace) -> int:
    max_bytes = max(1, int(args.max_mb)) * 1024 * 1024
    head_bytes = max(0, int(args.head_kb)) * 1024
    tail_bytes = max(1, int(args.tail_kb)) * 1024
    results = compact_code_session_logs(
        include_runtime=bool(args.runtime),
        apply=bool(args.apply),
        max_bytes=max_bytes,
        head_bytes=head_bytes,
        tail_bytes=tail_bytes,
    )
    oversized = [result for result in results if result.get("status") in {"would_compact", "compacted"}]
    reclaimed = sum(int(result.get("reclaimed_bytes") or 0) for result in results)
    print("Coder session log compaction")
    print(f"mode: {'apply' if args.apply else 'dry-run'}")
    print(f"include_runtime: {'yes' if args.runtime else 'no'}")
    print(f"logs_checked: {len(results)}")
    print(f"oversized: {len(oversized)}")
    if args.apply:
        print(f"reclaimed: {format_bytes_compact(reclaimed)}")
    for result in oversized[: int(args.limit)]:
        original_size = format_bytes_compact(int(result.get("original_size_bytes") or 0))
        status = normalize_text_value(result.get("status"), fallback="unknown", limit=80)
        line = f"- {status}: {result.get('path')} ({original_size})"
        if result.get("reclaimed_bytes"):
            line += f" reclaimed={format_bytes_compact(int(result.get('reclaimed_bytes') or 0))}"
        print(line)
    if len(oversized) > int(args.limit):
        print(f"... {len(oversized) - int(args.limit)} more oversized log(s)")
    if not args.apply and oversized:
        print("Run again with `--apply` to compact oversized logs while preserving first/latest complete JSONL lines.")
    return 0


def cmd_self_repair_plan(args: argparse.Namespace) -> int:
    try:
        plan = build_self_repair_plan(
            args.objective,
            files=[str(item) for item in (args.file or [])],
            tests=[str(item) for item in (args.test or [])],
            diagnosis_only=bool(args.diagnosis_only),
            prefer_runtime=bool(args.runtime),
        )
        if not bool(args.no_save):
            plan = save_self_repair_plan_artifact(plan)
        if bool(args.queue):
            queue_self_repair_code_patch_proposal(plan)
            if not bool(args.no_save):
                plan = save_self_repair_plan_artifact(plan)
        if bool(args.codex_handoff):
            create_self_repair_codex_handoff(plan, diagnosis_only=bool(args.diagnosis_only))
            if not bool(args.no_save):
                plan = save_self_repair_plan_artifact(plan)
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    if args.json:
        # This is an explicit command response requested with --json, not a log record.
        # codeql[py/clear-text-logging-sensitive-data]
        print(json.dumps(plan, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_self_repair_plan(plan, full=bool(args.full)))
    return 0 if str(plan.get("status") or "") != "blocked" else 1


def cmd_economy(args: argparse.Namespace) -> int:
    runtime_app_dir = RUNTIME_APP_DIR if bool(getattr(args, "runtime", False)) else None
    command = normalize_text_value(getattr(args, "economy_command", ""), fallback="", limit=80)
    filename = ""
    if command == "resources":
        record = eve_economy.build_resource_plan(ROOT, runtime_app_dir=runtime_app_dir, source="eve.py")
        filename = "resource_plan.json"
    elif command == "value-map":
        record = eve_economy.build_value_map(ROOT, runtime_app_dir=runtime_app_dir, source="eve.py")
        filename = "value_map.json"
    elif command == "opportunity":
        record = eve_economy.build_opportunity_card(
            normalize_text_value(getattr(args, "idea", ""), fallback="", limit=500),
            ROOT,
            runtime_app_dir=runtime_app_dir,
            source="eve.py",
        )
        filename = "latest_opportunity.json"
    elif command == "experiment":
        record = eve_economy.build_experiment_plan(
            normalize_text_value(getattr(args, "opportunity", ""), fallback="", limit=500),
            ROOT,
            runtime_app_dir=runtime_app_dir,
            source="eve.py",
        )
        filename = "latest_experiment.json"
    elif command == "outreach-draft":
        record = eve_economy.build_outreach_draft(
            normalize_text_value(getattr(args, "opportunity", ""), fallback="", limit=500),
            normalize_text_value(getattr(args, "channel", ""), fallback="", limit=120),
            ROOT,
            runtime_app_dir=runtime_app_dir,
            source="eve.py",
        )
        filename = "latest_outreach_draft.json"
    elif command == "ledger":
        record = eve_economy.build_revenue_ledger(ROOT, source="eve.py")
        filename = "ledger_summary.json"
    else:
        raise SystemExit(f"unknown economy command: {command}")
    if not bool(getattr(args, "no_save", False)):
        path = eve_economy.save_record(ROOT, filename, record)
        artifacts = record.setdefault("artifacts", {})
        if isinstance(artifacts, dict):
            artifacts["latest"] = str(path)
    print(
        eve_economy.json_or_text(
            record,
            as_json=bool(getattr(args, "json", False)),
            full=bool(getattr(args, "full", False)),
        )
    )
    return 0


