def cmd_proposal_suggest(args: argparse.Namespace) -> int:
    config = load_config()
    apply_transient_model_override(config, args.model)
    max_tokens = args.max_tokens or int(config["proposal_max_tokens"])
    record = suggest_proposal(config, source="manual", max_tokens=max_tokens)
    print(f"Saved proposal {record['id']}")
    print(f"title: {record['title']}")
    print()
    print(record["body"])
    return 0


def cmd_proposal_list(args: argparse.Namespace) -> int:
    proposals = read_proposals(limit=args.limit, status=args.status)
    if not proposals:
        print("No proposals found.")
        return 0
    for proposal in proposals:
        print(f"{proposal['id']} [{proposal['status']}] {proposal['created_at']}")
        print(f"title: {proposal['title']}")
        print(f"source: {proposal['source']}")
        print(f"summary: {proposal['summary']}")
        if args.full:
            print()
            print(proposal["body"])
        print()
    return 0


def cmd_proposal_update(args: argparse.Namespace) -> int:
    changes: Dict[str, object] = {}
    if args.status:
        changes["status"] = args.status
    if args.title:
        changes["title"] = args.title
    if args.summary:
        changes["summary"] = args.summary
    if args.body:
        changes["body"] = args.body
    if not changes:
        raise SystemExit("Provide at least one proposal update field.")
    proposal = update_proposal_record(args.id, **changes)
    apply_result: Dict[str, object] = {"applied": False}
    retire_result: Dict[str, object] = {"retired": False}
    if args.status == "approved":
        apply_result = apply_bounded_success_pattern_repair_proposal(proposal, source="manual_proposal_update")
        proposal = apply_result.get("proposal") if apply_result.get("proposal") else proposal
    elif args.status in {"rejected", "archived"}:
        retire_result = retire_applied_repair_for_proposal(proposal, source=f"proposal_status:{args.status}")
    append_entry(
        "proposal_updated",
        f"{proposal['title']} -> {proposal['status']}",
        metadata={"proposal_id": proposal["id"], "status": proposal["status"]},
    )
    print(f"Updated proposal {proposal['id']}")
    if apply_result.get("applied"):
        application = apply_result.get("application") if isinstance(apply_result.get("application"), dict) else {}
        print(
            "Applied bounded repair overlay "
            f"{application.get('id') or 'unknown'} -> "
            f"{', '.join(application.get('prompt_targets') or []) or 'reply'}."
        )
    elif args.status == "approved" and apply_result.get("reason"):
        print(f"Approval recorded, but no bounded apply path ran: {apply_result['reason']}")
    if retire_result.get("retired"):
        print(f"Retired {retire_result.get('count') or 0} bounded repair overlay(s).")
    return 0


def launchctl_domain() -> str:
    if not eve_platform.is_macos():
        raise SystemExit(
            "launchd is only available on macOS. On this platform, run `eve.py daemon run` under your own supervisor for now."
        )
    result = run_local_command(["id", "-u"], timeout=10)
    if result.returncode != 0:
        raise SystemExit(result.stderr.strip() or "Could not determine uid.")
    return f"gui/{result.stdout.strip()}"


def launchctl_target() -> str:
    return f"{launchctl_domain()}/{LAUNCH_AGENT_LABEL}"


def model_warm_launchctl_target() -> str:
    return f"{launchctl_domain()}/{MODEL_WARM_LABEL}"


def model_watchdog_launchctl_target() -> str:
    return f"{launchctl_domain()}/{MODEL_WATCHDOG_LABEL}"


def run_launchctl(args: List[str], allow_failure: bool = False) -> subprocess.CompletedProcess:
    if not eve_platform.is_macos():
        result = subprocess.CompletedProcess(
            ["launchctl", *args],
            127,
            stdout="",
            stderr="launchctl is not available on this platform",
        )
        if not allow_failure:
            raise SystemExit(
                "Automatic daemon install/start/stop currently supports macOS launchd only. "
                "Use `eve.py daemon run` under systemd, Task Scheduler, or another supervisor for now."
            )
        return result
    result = run_local_command(["launchctl", *args], timeout=30)
    if result.returncode != 0 and not allow_failure:
        message = result.stderr.strip() or result.stdout.strip() or "launchctl command failed."
        raise SystemExit(message)
    return result


def native_service_manager_name() -> str:
    return eve_platform.service_manager()


def require_native_service_install_support() -> None:
    if eve_platform.native_service_install_supported():
        return
    manager = native_service_manager_name()
    raise SystemExit(
        "Automatic daemon install/start/stop is not available on this machine. "
        f"Detected platform service manager: {manager}. "
        "Use `eve.py daemon run` under your OS supervisor for now."
    )


def run_systemctl_user(args: List[str], allow_failure: bool = False) -> subprocess.CompletedProcess:
    if not eve_platform.is_linux():
        result = subprocess.CompletedProcess(
            ["systemctl", "--user", *args],
            127,
            stdout="",
            stderr="systemctl --user is not available on this platform",
        )
        if not allow_failure:
            raise SystemExit(result.stderr)
        return result
    result = run_local_command(["systemctl", "--user", *args], timeout=30)
    if result.returncode != 0 and not allow_failure:
        message = result.stderr.strip() or result.stdout.strip() or "systemctl command failed."
        raise SystemExit(message)
    return result


def run_schtasks(args: List[str], allow_failure: bool = False) -> subprocess.CompletedProcess:
    if not eve_platform.is_windows():
        result = subprocess.CompletedProcess(
            ["schtasks", *args],
            127,
            stdout="",
            stderr="schtasks is not available on this platform",
        )
        if not allow_failure:
            raise SystemExit(result.stderr)
