def systemd_service_unit_name(label: str) -> str:
    return f"{label}.service"


def systemd_timer_unit_name(label: str) -> str:
    return f"{label}.timer"


def task_scheduler_task_name(label: str) -> str:
    return label


def build_systemd_service_unit(
    *,
    description: str,
    exec_start: List[str],
    working_directory: Path,
    restart: str = "always",
    restart_sec: int = 5,
    extra_environment: Optional[Dict[str, str]] = None,
) -> str:
    lines = [
        "[Unit]",
        f"Description={description}",
        "After=network-online.target",
        "",
        "[Service]",
        "Type=simple",
        f"WorkingDirectory={working_directory}",
        f"ExecStart={' '.join(shlex.quote(part) for part in exec_start)}",
        f"Restart={restart}",
    ]
    if restart != "no":
        lines.append(f"RestartSec={restart_sec}")
    lines.append("Environment=PYTHONUNBUFFERED=1")
    lines.append("Environment=PATH=/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin")
    for key, value in (extra_environment or {}).items():
        lines.append(f"Environment={key}={value}")
    lines.extend(["", "[Install]", "WantedBy=default.target", ""])
    return "\n".join(lines)


def build_systemd_timer_unit(*, description: str, service_label: str, interval_seconds: int) -> str:
    lines = [
        "[Unit]",
        f"Description={description}",
        "",
        "[Timer]",
        "OnBootSec=30s",
        f"OnUnitActiveSec={max(30, int(interval_seconds))}s",
        f"Unit={systemd_service_unit_name(service_label)}",
        "",
        "[Install]",
        "WantedBy=timers.target",
        "",
    ]
    return "\n".join(lines)


def windows_interval_iso8601(interval_seconds: int) -> str:
    minutes = max(1, int(interval_seconds // 60))
    return f"PT{minutes}M"


def build_windows_task_xml(
    *,
    description: str,
    command: str,
    arguments: List[str],
    working_directory: Path,
    trigger: str,
    repetition_interval_seconds: Optional[int] = None,
) -> str:
    start_boundary = datetime.now().replace(microsecond=0).isoformat()
    trigger_body = ""
    if trigger == "logon":
        trigger_body = "<LogonTrigger><Enabled>true</Enabled></LogonTrigger>"
    else:
        repetition_xml = ""
        if repetition_interval_seconds is not None:
            repetition_xml = (
                "<Repetition>"
                f"<Interval>{windows_interval_iso8601(repetition_interval_seconds)}</Interval>"
                "<StopAtDurationEnd>false</StopAtDurationEnd>"
                "</Repetition>"
            )
        trigger_body = (
            "<TimeTrigger>"
            f"<StartBoundary>{html_escape(start_boundary)}</StartBoundary>"
            f"{repetition_xml}"
            "<Enabled>true</Enabled>"
            "</TimeTrigger>"
        )
    arguments_text = " ".join(subprocess.list2cmdline([part]) for part in arguments).strip()
    return textwrap.dedent(
        f"""\
        <?xml version="1.0" encoding="UTF-16"?>
        <Task version="1.4" xmlns="http://schemas.microsoft.com/windows/2004/02/mit/task">
          <RegistrationInfo>
            <Description>{html_escape(description)}</Description>
          </RegistrationInfo>
          <Triggers>
            {trigger_body}
          </Triggers>
          <Principals>
            <Principal id="Author">
              <LogonType>InteractiveToken</LogonType>
              <RunLevel>LeastPrivilege</RunLevel>
            </Principal>
          </Principals>
          <Settings>
            <MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy>
            <DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries>
            <StopIfGoingOnBatteries>false</StopIfGoingOnBatteries>
            <AllowHardTerminate>true</AllowHardTerminate>
            <StartWhenAvailable>true</StartWhenAvailable>
            <RunOnlyIfNetworkAvailable>false</RunOnlyIfNetworkAvailable>
            <IdleSettings>
              <StopOnIdleEnd>false</StopOnIdleEnd>
              <RestartOnIdle>false</RestartOnIdle>
            </IdleSettings>
            <AllowStartOnDemand>true</AllowStartOnDemand>
            <Enabled>true</Enabled>
            <Hidden>false</Hidden>
            <RunOnlyIfIdle>false</RunOnlyIfIdle>
            <WakeToRun>false</WakeToRun>
            <ExecutionTimeLimit>PT0S</ExecutionTimeLimit>
            <Priority>7</Priority>
          </Settings>
          <Actions Context="Author">
            <Exec>
              <Command>{html_escape(command)}</Command>
              <Arguments>{html_escape(arguments_text)}</Arguments>
              <WorkingDirectory>{html_escape(str(working_directory))}</WorkingDirectory>
            </Exec>
          </Actions>
        </Task>
        """
    ).strip() + "\n"


