def runtime_bundle_temp_path(source: Path, destination: Path) -> Path:
    suffix = ".py" if source.suffix == ".py" else ""
    return destination.with_name(f".{destination.name}.tmp.{os.getpid()}.{threading.get_ident()}{suffix}")


def runtime_bundle_source_signature(path: Path) -> Tuple[int, int]:
    stat = path.stat()
    return stat.st_mtime_ns, stat.st_size


APFS_DATALESS_FILE_FLAG = 0x40000000


def runtime_bundle_file_is_dataless(path: Path) -> bool:
    try:
        flags = int(getattr(path.stat(), "st_flags", 0) or 0)
    except OSError:
        return False
    return bool(flags & APFS_DATALESS_FILE_FLAG)


def runtime_bundle_destination_matches_source_metadata(source: Path, destination: Path) -> bool:
    if not destination.exists():
        return False
    try:
        return runtime_bundle_source_signature(source) == runtime_bundle_source_signature(destination)
    except OSError:
        return False


def skip_or_refuse_dataless_runtime_source(source: Path, destination: Path) -> bool:
    if not runtime_bundle_file_is_dataless(source):
        return False
    if runtime_bundle_destination_matches_source_metadata(source, destination):
        return True
    refuse_runtime_bundle_candidate(
        destination,
        f"{source} is a dataless placeholder; hydrate the source file before runtime sync",
    )
    return True


def copy_runtime_bundle_file_bytes(source: Path, destination: Path) -> None:
    with source.open("rb") as source_file, destination.open("wb") as destination_file:
        shutil.copyfileobj(source_file, destination_file, length=1024 * 1024)
    stat = source.stat()
    try:
        destination.chmod(stat.st_mode & 0o777)
    except OSError:
        pass
    try:
        os.utime(destination, ns=(stat.st_atime_ns, stat.st_mtime_ns))
    except OSError:
        pass


def validate_runtime_python_candidate(path: Path) -> Tuple[bool, str]:
    compiled_path = path.with_name(f".{path.name}.pyc.{os.getpid()}.{threading.get_ident()}")
    try:
        py_compile.compile(str(path), cfile=str(compiled_path), doraise=True)
    except py_compile.PyCompileError as exc:
        return False, str(exc)
    except OSError as exc:
        return False, str(exc)
    finally:
        try:
            if compiled_path.exists():
                compiled_path.unlink()
        except OSError:
            pass
    return True, ""


def refuse_runtime_bundle_candidate(destination: Path, reason: str) -> bool:
    if destination.exists():
        print(
            f"Warning: runtime bundle refused candidate for {destination}: {reason}",
            file=sys.stderr,
        )
        return False
    raise RuntimeError(f"Runtime bundle refused candidate for {destination}: {reason}")


def copy_runtime_bundle_file(source: Path, destination: Path, executable: bool = False) -> bool:
    try:
        if destination.exists() and source.resolve() == destination.resolve():
            return False
    except FileNotFoundError:
        pass
    destination.parent.mkdir(parents=True, exist_ok=True)
    if runtime_bundle_destination_matches_source_metadata(source, destination):
        if executable:
            destination.chmod(0o755)
        return False
    if skip_or_refuse_dataless_runtime_source(source, destination):
        return False
    temp_path = runtime_bundle_temp_path(source, destination)
    try:
        source_signature = runtime_bundle_source_signature(source)
        copy_runtime_bundle_file_bytes(source, temp_path)
        if runtime_bundle_source_signature(source) != source_signature:
            return refuse_runtime_bundle_candidate(destination, f"{source} changed while copying")
        if source.suffix == ".py":
            valid_python, validation_error = validate_runtime_python_candidate(temp_path)
            if not valid_python:
                return refuse_runtime_bundle_candidate(destination, f"invalid Python: {validation_error}")
        temp_path.replace(destination)
        if executable:
            destination.chmod(0o755)
        return True
    finally:
        try:
            if temp_path.exists():
                temp_path.unlink()
        except OSError:
            pass


def copy_runtime_bundle_data_file_preserving_newer_runtime(source: Path, destination: Path) -> bool:
    try:
        if destination.exists() and source.resolve() == destination.resolve():
            return False
    except FileNotFoundError:
        pass
    if destination.exists():
        try:
            if destination.stat().st_mtime >= source.stat().st_mtime:
                return False
        except OSError:
            pass
    destination.parent.mkdir(parents=True, exist_ok=True)
    if runtime_bundle_destination_matches_source_metadata(source, destination):
        return False
    if skip_or_refuse_dataless_runtime_source(source, destination):
        return False
    temp_path = runtime_bundle_temp_path(source, destination)
    try:
        source_signature = runtime_bundle_source_signature(source)
        copy_runtime_bundle_file_bytes(source, temp_path)
        if runtime_bundle_source_signature(source) != source_signature:
            return refuse_runtime_bundle_candidate(destination, f"{source} changed while copying")
        temp_path.replace(destination)
        return True
    finally:
        try:
            if temp_path.exists():
                temp_path.unlink()
        except OSError:
            pass


def copy_runtime_bundle_tree(source_dir: Path, destination_dir: Path) -> None:
    for current_root, dirnames, filenames in os.walk(source_dir):
        current_path = Path(current_root)
        try:
            relative_path = current_path.relative_to(source_dir)
        except ValueError:
            continue
        target_dir = destination_dir / relative_path if str(relative_path) != "." else destination_dir
        target_dir.mkdir(parents=True, exist_ok=True)
        for dirname in list(dirnames):
            if (current_path / dirname).is_symlink():
                dirnames.remove(dirname)
        for filename in filenames:
            source_path = current_path / filename
            if not source_path.is_file():
                continue
            copy_runtime_bundle_file(source_path, target_dir / filename)


