def start_launch_agent() -> None:
    clear_daemon_runtime_cache()
    install_launch_agent()
    if eve_platform.is_linux():
        run_systemctl_user(["enable", "--now", systemd_service_unit_name(LAUNCH_AGENT_LABEL)])
        clear_daemon_runtime_cache()
        return
    if eve_platform.is_windows():
        run_schtasks(["/Run", "/TN", task_scheduler_task_name(LAUNCH_AGENT_LABEL)], allow_failure=True)
        clear_daemon_runtime_cache()
        return
    run_launchctl(["enable", launchctl_target()], allow_failure=True)
    run_launchctl(["bootout", launchctl_domain(), str(LAUNCH_AGENT_PATH)], allow_failure=True)
    run_launchctl(["bootstrap", launchctl_domain(), str(LAUNCH_AGENT_PATH)])
    clear_daemon_runtime_cache()


