def cmd_capabilities_intelligence(args: argparse.Namespace) -> int:
    command = str(getattr(args, "intelligence_command", "status") or "status")
    prefer_runtime = bool(getattr(args, "runtime", False) or daemon_runtime_running())
    if command == "history":
        records = read_capability_intelligence_history(
            limit=int(getattr(args, "limit", 20) or 20),
            prefer_runtime=prefer_runtime,
        )
        if getattr(args, "json", False):
            print(json.dumps(records, indent=2, ensure_ascii=True))
            return 0
        if not records:
            print("No capability-intelligence history found.")
            return 0
        for record in reversed(records):
            changes = record.get("changes") if isinstance(record.get("changes"), dict) else {}
            counts = changes.get("counts") if isinstance(changes.get("counts"), dict) else {}
            print(
                f"{record.get('generated_at') or 'unknown'} | {record.get('source') or 'unknown'} | "
                f"material_change={'yes' if changes.get('material_change') else 'no'} | "
                f"changes={sum(int(value or 0) for value in counts.values())} | "
                f"opportunities={len(record.get('opportunities') or [])} | "
                f"adoption_candidates={int((record.get('feature_review_summary') or {}).get('candidate_count') or 0)}"
            )
            if getattr(args, "full", False):
                print(f"  summary: {record.get('summary') or ''}")
                print(f"  versions: {json.dumps(record.get('versions') or {}, ensure_ascii=True, sort_keys=True)}")
                print(f"  release_heads: {json.dumps(record.get('release_heads') or {}, ensure_ascii=True, sort_keys=True)}")
                print(f"  adoption_candidates: {json.dumps(record.get('adoption_candidates') or [], ensure_ascii=True, sort_keys=True)}")
        return 0

    if command in {"refresh", "attest"}:
        config = load_config()
        refresh_all = bool(getattr(args, "all", False))
        snapshot = run_capability_intelligence(
            config,
            source="manual_effective_attestation" if command == "attest" else "manual",
            refresh_upstream=bool(command == "refresh" and (refresh_all or getattr(args, "upstream", False))),
            refresh_hermes=bool(command == "refresh" and (refresh_all or getattr(args, "hermes", False))),
            refresh_components=bool(command == "refresh" and (refresh_all or getattr(args, "components", False))),
            timeout=int(getattr(args, "timeout", 45) or 45),
        )
    else:
        snapshot = load_capability_intelligence(prefer_runtime=prefer_runtime)
    if getattr(args, "json", False):
        print(json.dumps(snapshot, indent=2, ensure_ascii=True))
        return 0
    print(
        eve_capability_intelligence.format_snapshot(
            snapshot,
            full=bool(getattr(args, "full", False)),
        )
    )
    print(f"briefing: {resolve_store_read_path(CAPABILITY_INTELLIGENCE_REPORT_PATH, prefer_runtime=prefer_runtime)}")
    print(f"history: {resolve_store_read_path(CAPABILITY_INTELLIGENCE_HISTORY_PATH, prefer_runtime=prefer_runtime)}")
    return 0


def cmd_capabilities_adoption(args: argparse.Namespace) -> int:
    config = load_config()
    command = str(getattr(args, "capability_adoption_command", "status") or "status")
    prefer_runtime = bool(getattr(args, "runtime", False))
    if command == "history":
        records = read_capability_adoption_history(
            limit=int(getattr(args, "limit", 20) or 20),
            prefer_runtime=prefer_runtime,
        )
        if getattr(args, "json", False):
            print(json.dumps(records, indent=2, ensure_ascii=True, sort_keys=True))
        elif not records:
            print("No capability-adoption cycles found.")
        else:
            for record in records:
                print(eve_capability_adoption.format_cycle(record, full=bool(getattr(args, "full", False))))
                print()
        return 0
    if command == "resolve":
        resolution = resolve_capability_first_for_objective(
            config,
            getattr(args, "objective", ""),
            prefer_runtime=prefer_runtime,
            source="manual_capability_resolution",
        )
        if getattr(args, "json", False):
            print(json.dumps(resolution, indent=2, ensure_ascii=True, sort_keys=True))
        else:
            print(eve_capability_adoption.format_resolution(resolution, full=bool(getattr(args, "full", False))))
        return 0
    if command == "cycle":
        cycle = run_capability_adoption_cycle(
            config,
            objective=getattr(args, "objective", "") or "",
            source="manual_capability_adoption",
            prefer_runtime=prefer_runtime,
            include_online_research=bool(getattr(args, "research", False)),
            include_discovery=bool(getattr(args, "discover", False)),
            run_canary=not bool(getattr(args, "no_canary", False)),
            create_build_handoff=not bool(getattr(args, "no_handoff", False)),
            timeout=int(getattr(args, "timeout", 300) or 300),
        )
        if getattr(args, "json", False):
            print(json.dumps(cycle, indent=2, ensure_ascii=True, sort_keys=True))
        else:
            print(eve_capability_adoption.format_cycle(cycle, full=bool(getattr(args, "full", False))))
        return 0 if cycle.get("status") != "attention" else 2
    state = load_capability_adoption_state(prefer_runtime=prefer_runtime)
    if getattr(args, "json", False):
        print(json.dumps(state, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        latest = state.get("latest_cycle") if isinstance(state.get("latest_cycle"), dict) else {}
        if latest:
            print(eve_capability_adoption.format_cycle(latest, full=bool(getattr(args, "full", False))))
        else:
            print(state.get("summary") or "No capability-first self-development cycle has run yet.")
        counts = state.get("counts") if isinstance(state.get("counts"), dict) else {}
        if counts:
            print("counts: " + ", ".join(f"{key}={value}" for key, value in sorted(counts.items())))
        print(f"state: {resolve_store_read_path(CAPABILITY_ADOPTION_PATH, prefer_runtime=prefer_runtime)}")
        print(f"history: {resolve_store_read_path(CAPABILITY_ADOPTION_HISTORY_PATH, prefer_runtime=prefer_runtime)}")
        print(f"online_research: {resolve_store_read_path(CAPABILITY_ONLINE_RESEARCH_PATH, prefer_runtime=prefer_runtime)}")
    return 0


