def cmd_capabilities_research(args: argparse.Namespace) -> int:
    report = build_capability_research_report(
        args.subject,
        prompt=args.prompt or args.subject,
        prefer_runtime=bool(args.runtime),
        write=bool(args.write),
    )
    if args.write:
        append_eve_event_ledger_event(
            oss_integration_event(report, source="capability_research", event_type="OrganPulseEvent")
        )
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True))
        return 0

    capabilities = report.get("capabilities") if isinstance(report.get("capabilities"), list) else []
    next_builds = report.get("next_builds") if isinstance(report.get("next_builds"), list) else []
    artifacts = report.get("artifacts") if isinstance(report.get("artifacts"), dict) else {}
    print("Eve capability research")
    print(f"subject: {report.get('subject')}")
    print(f"status: {report.get('status')}")
    print(f"sources: {report.get('source_count')}")
    if artifacts:
        print(f"artifact: {artifacts.get('latest')}")
    print("capabilities:")
    if not capabilities:
        print("- none learned yet")
    for capability in capabilities:
        if not isinstance(capability, dict):
            continue
        print(
            "- "
            + normalize_text_value(capability.get("name"), fallback="Capability", limit=80)
            + ": "
            + normalize_text_value(capability.get("current_eve_status"), fallback="", limit=220)
        )
        if args.full:
            matched = capability.get("matched_keywords") if isinstance(capability.get("matched_keywords"), list) else []
            refs = capability.get("source_refs") if isinstance(capability.get("source_refs"), list) else []
            print(f"  matched: {', '.join(str(item) for item in matched) if matched else 'none'}")
            print(f"  source_refs: {', '.join(str(item) for item in refs) if refs else 'none'}")
    print("next:")
    for item in next_builds:
        if not isinstance(item, dict):
            continue
        print(
            "- "
            + normalize_text_value(item.get("build"), fallback="Next capability step", limit=120)
            + ": "
            + normalize_text_value(item.get("why"), fallback="", limit=240)
        )
    return 0


def cmd_capabilities_test(args: argparse.Namespace) -> int:
    config = load_config()
    ensure_version_snapshot(source="capabilities_runtime")
    apply_transient_model_override(config, args.model)
    artifact_path = APP_DIR / "capability_tests" / "latest_self_test.txt"
    artifact_content = f"Eve capability self-test artifact generated at {utc_now()}."
    prompt = build_capability_self_test_prompt(artifact_path, artifact_content)
    messages = [
        *build_eve_identity_system_messages(include_human_context=False, include_active_mind=False),
        {"role": "user", "content": prompt},
    ]
    max_tokens = args.max_tokens or max(int(config["chat_max_tokens"]), 420)
    agent_result = run_eve_agent(
        config,
        messages,
        max_tokens=max_tokens,
        allow_tools=True,
        require_tool_use=True,
        model_role="capabilities",
    )
    tool_calls = agent_result["tool_calls"]
    problems = capability_test_problems(tool_calls, artifact_path, artifact_content)
    summary = str(agent_result["response"]).strip()
    metadata = {
        "model": agent_result["model"],
        "tool_call_count": len(tool_calls),
        "tools_used": [call["tool"] for call in tool_calls],
        "artifact_path": str(artifact_path),
        "passed": not problems,
    }
    if problems:
        append_entry(
            "capability_test_failed",
            "; ".join(problems),
            metadata=metadata,
        )
        raise SystemExit(
            "Eve capability self-test failed.\n"
            + "\n".join(f"- {problem}" for problem in problems)
            + "\n\nEve's report:\n"
            + summary
        )
    append_entry(
        "capability_test_passed",
        summary or "Capability self-test passed.",
        metadata=metadata,
    )
    print(summary)
    return 0


def cmd_awareness(args: argparse.Namespace) -> int:
    config = load_config()
    apply_transient_model_override(config, args.model)
    delegate_timeout = int(config.get("self_awareness_timeout_seconds") or DEFAULT_CONFIG["self_awareness_timeout_seconds"]) + 30
    if args.refresh:
        delegate_timeout += int(config.get("human_context_timeout_seconds") or DEFAULT_CONFIG["human_context_timeout_seconds"])
    delegated = delegate_cli_to_runtime(
        [
            "awareness",
            *(["--model", args.model] if args.model else []),
            *(["--max-tokens", str(args.max_tokens)] if args.max_tokens else []),
            *(["--refresh"] if args.refresh else []),
        ],
        timeout_seconds=delegate_timeout,
    )
    if delegated is not None:
        return delegated
    max_tokens = args.max_tokens or int(config["self_awareness_max_tokens"])
    record = run_self_awareness_test(
        config,
        source="manual",
        max_tokens=max_tokens,
        force_refresh=args.refresh,
    )
    report = format_self_awareness_report(record)
    if not record.get("passed"):
        if record.get("failure_kind") == "infrastructure":
            raise SystemExit("Eve self-awareness infrastructure failed.\n\n" + report)
        raise SystemExit("Eve self-awareness check failed.\n\n" + report)
    print(report)
    return 0


def cmd_awareness_battery(args: argparse.Namespace) -> int:
    config = load_config()
    apply_transient_model_override(config, args.model)
    delegate_timeout = (
        int(config.get("self_awareness_timeout_seconds") or DEFAULT_CONFIG["self_awareness_timeout_seconds"])
        + int(
            config.get("human_analog_self_awareness_timeout_seconds")
            or DEFAULT_CONFIG["human_analog_self_awareness_timeout_seconds"]
        )
        + 45
    )
    if args.refresh:
        delegate_timeout += int(config.get("human_context_timeout_seconds") or DEFAULT_CONFIG["human_context_timeout_seconds"])
    delegated = delegate_cli_to_runtime(
        [
            "awareness-battery",
            *(["--model", args.model] if args.model else []),
            *(["--max-tokens", str(args.max_tokens)] if args.max_tokens else []),
            *(["--refresh"] if args.refresh else []),
        ],
        timeout_seconds=delegate_timeout,
    )
    if delegated is not None:
        return delegated
    open_book_max_tokens = args.max_tokens or int(config["self_awareness_max_tokens"])
    human_analog_max_tokens = args.max_tokens or int(
        config.get("human_analog_self_awareness_max_tokens")
        or DEFAULT_CONFIG["human_analog_self_awareness_max_tokens"]
    )
    record = run_self_awareness_battery(
        config,
        source="manual",
        open_book_max_tokens=open_book_max_tokens,
        human_analog_max_tokens=human_analog_max_tokens,
        force_refresh=args.refresh,
    )
    report = format_self_awareness_battery_report(record)
    if not record.get("passed"):
        if record.get("failure_kind") == "infrastructure":
            raise SystemExit("Eve self-awareness battery hit infrastructure problems.\n\n" + report)
        raise SystemExit("Eve self-awareness battery failed.\n\n" + report)
    print(report)
    return 0


def cmd_awareness_perturb(args: argparse.Namespace) -> int:
    config = load_config()
    apply_transient_model_override(config, args.model)
    delegate_timeout = (
        int(
            config.get("self_awareness_perturbation_timeout_seconds")
            or DEFAULT_CONFIG["self_awareness_perturbation_timeout_seconds"]
        )
        + 30
    )
    if args.refresh:
        delegate_timeout += int(config.get("human_context_timeout_seconds") or DEFAULT_CONFIG["human_context_timeout_seconds"])
    delegated = delegate_cli_to_runtime(
        [
            "awareness-perturb",
            *(["--model", args.model] if args.model else []),
            *(["--max-tokens", str(args.max_tokens)] if args.max_tokens else []),
            *(["--refresh"] if args.refresh else []),
        ],
        timeout_seconds=delegate_timeout,
    )
    if delegated is not None:
        return delegated
    max_tokens = args.max_tokens or int(
        config.get("self_awareness_perturbation_max_tokens")
        or DEFAULT_CONFIG["self_awareness_perturbation_max_tokens"]
    )
    record = run_self_awareness_perturbation_test(
        config,
        source="manual",
        max_tokens=max_tokens,
        force_refresh=args.refresh,
    )
    report = format_self_awareness_perturbation_report(record)
    if not record.get("passed"):
        if record.get("failure_kind") == "infrastructure":
            raise SystemExit("Eve perturbation self-awareness battery hit infrastructure problems.\n\n" + report)
        raise SystemExit("Eve perturbation self-awareness battery failed.\n\n" + report)
    print(report)
    return 0


