def cmd_model_certify(args: argparse.Namespace) -> int:
    config = load_config()
    baseline_model = args.baseline or resolve_model(config, "general")
    candidate_model = args.candidate
    probe_max_tokens = args.max_tokens or int(config["chat_max_tokens"])
    record = generate_model_certification_report(
        config,
        baseline_model=baseline_model,
        candidate_model=candidate_model,
        probe_max_tokens=probe_max_tokens,
        skip_capabilities=args.skip_capabilities,
        skip_awareness=args.skip_awareness,
    )
    append_entry(
        "model_certification_passed" if record.get("passed") else "model_certification_failed",
        str(record.get("summary") or "Model certification completed."),
        metadata={
            "baseline_model": baseline_model,
            "candidate_model": candidate_model,
            "artifact_path": record.get("artifact_paths", {}).get("history"),
            "passed": bool(record.get("passed")),
            "regressions": record.get("regressions", []),
            "improvements": record.get("improvements", []),
        },
    )
    report = format_model_certification_report(record, full=args.full)
    if not record.get("passed"):
        raise SystemExit("Eve model certification failed.\n\n" + report)
    print(report)
    return 0


def cmd_perf_summary(args: argparse.Namespace) -> int:
    events = read_perf_events(
        limit=args.limit,
        since_minutes=args.minutes,
        category=args.category,
        name=args.name,
        ok=False if args.failures else None,
    )
    if not events:
        print("No matching perf events found.")
        return 0

    print("Perf events")
    print(f"- total: {len(events)}")
    if args.minutes is not None:
        print(f"- window_minutes: {args.minutes}")
    if args.category:
        print(f"- category: {args.category}")
    if args.name:
        print(f"- name: {args.name}")
    if args.failures:
        print("- failures_only: yes")
    print()
    print(format_perf_summary_rows(summarize_perf_events(events)))

    if not args.failures:
        recent_failures = read_perf_events(
            limit=args.failure_limit,
            since_minutes=args.minutes,
            category=args.category,
            name=args.name,
            ok=False,
        )
        if recent_failures:
            print()
            print("Recent failures")
            print(format_perf_failure_events(recent_failures, limit=args.failure_limit))
    return 0


def cmd_perf_probe(args: argparse.Namespace) -> int:
    repeat = max(1, int(args.repeat))
    base_url = f"http://{args.host}:{args.port}"
    results: List[Dict[str, object]] = []
    thread_detail_attempted = False

    for _ in range(repeat):
        results.append(probe_json_endpoint("status", f"{base_url}/api/status", timeout=args.timeout))
        user_threads_result = probe_json_endpoint(
            "threads_user",
            f"{base_url}/api/threads?limit=40&audience=user",
            timeout=args.timeout,
        )
        results.append(user_threads_result)
        results.append(
            probe_json_endpoint(
                "threads_agent",
                f"{base_url}/api/threads?limit=40&audience=agent",
                timeout=args.timeout,
            )
        )
        results.append(probe_json_endpoint("thoughts", f"{base_url}/api/thoughts?limit=80", timeout=args.timeout))

        payload = user_threads_result.get("payload")
        data = payload.get("data") if isinstance(payload, dict) else None
        if isinstance(data, list) and data and isinstance(data[0], dict) and data[0].get("thread_id"):
            thread_detail_attempted = True
            results.append(
                probe_json_endpoint(
                    "thread_detail_user",
                    f"{base_url}/api/thread/{data[0]['thread_id']}",
                    timeout=args.timeout,
                )
            )

    print(f"Probed {base_url} {repeat} time(s).")
    print()
    print(format_perf_summary_rows(summarize_perf_events(results)))
    if not thread_detail_attempted:
        print()
        print("Note: skipped `thread_detail_user` because no user thread was available.")

    failures = [item for item in results if not bool(item.get("ok", True))]
    if failures:
        print()
        print("Probe failures")
        print(format_perf_failure_events(failures, limit=args.failure_limit))
        return 1
    return 0


def request_text_url(url: str, timeout: int = 10, headers: Optional[Dict[str, str]] = None) -> str:
    req = request.Request(url, headers=headers or {}, method="GET")
    with request.urlopen(req, timeout=timeout) as resp:
        return resp.read().decode("utf-8", errors="replace")


def collect_llama_cpp_metrics(config: Dict[str, object], timeout: int = 3) -> List[Dict[str, object]]:
    records: List[Dict[str, object]] = []
    headers = llama_cpp_request_headers(config)
    for spec in llama_cpp_profile_specs(config, active_only=True):
        host = normalize_text_value(spec.get("host"), fallback="", limit=200).rstrip("/")
        profile = normalize_text_value(spec.get("profile"), fallback="unknown", limit=40)
        if not host:
            continue
        url = host + "/metrics"
        try:
            raw = request_text_url(url, timeout=timeout, headers=headers or None)
            metrics = eve_tracing.parse_prometheus_metrics(raw)
            records.append(
                eve_db.record_llama_cpp_metrics(
                    OPERATIONAL_DB_PATH,
                    profile=profile,
                    host=host,
                    ok=True,
                    metrics=metrics,
                    raw_excerpt=eve_tracing.metrics_excerpt(raw),
                )
            )
        except Exception as exc:
            records.append(
                eve_db.record_llama_cpp_metrics(
                    OPERATIONAL_DB_PATH,
                    profile=profile,
                    host=host,
                    ok=False,
                    metrics={},
                    raw_excerpt="",
                    error=str(exc),
                )
            )
    return records


def cmd_infra_status(_: argparse.Namespace) -> int:
    config = load_config()
    status = eve_db.database_status(OPERATIONAL_DB_PATH)
    recent_events = read_perf_events(
        limit=250,
        since_minutes=int(config.get("model_governor_failure_window_minutes") or 20),
    )
    governor = eve_model_governor.summarize(recent_events, config)
    live_notes = build_memory_retrieval_notes(prefer_runtime=True)
    print("Infrastructure substrate")
    print(
        f"- db: {status.get('path')}\n"
        f"- exists: {'yes' if status.get('exists') else 'no'}\n"
        f"- journal_mode: {status.get('journal_mode') or 'unknown'}\n"
        f"- python_sqlite: {status.get('sqlite_version') or 'unknown'}\n"
        f"- wal_warning: {status.get('wal_warning') or 'none'}\n"
        f"- memory_note_sources_now: {len(live_notes)}\n"
        f"- governor_enabled: {'yes' if governor.get('enabled') else 'no'}\n"
        f"- governor_enforce: {'yes' if governor.get('enforce') else 'no'}\n"
        f"- recent_model_failures: {governor.get('failure_count') or 0}"
    )
    tables = status.get("tables") if isinstance(status.get("tables"), dict) else {}
    if tables:
        print("tables:")
        for table, count in tables.items():
            print(f"- {table}: {count}")
    failures_by_family = governor.get("failures_by_family") if isinstance(governor.get("failures_by_family"), dict) else {}
    if failures_by_family:
        print("governor_failure_families:")
        for family, count in sorted(failures_by_family.items()):
            print(f"- {family}: {count}")
    return 0


def cmd_infra_metrics(args: argparse.Namespace) -> int:
    config = load_config()
    timeout = max(1, int(args.timeout or 3))
    records = collect_llama_cpp_metrics(config, timeout=timeout)
    ok_count = sum(1 for item in records if item.get("ok"))
    eve_db.record_event(
        OPERATIONAL_DB_PATH,
        kind="infra.metrics.scraped",
        source="eve.py infra metrics",
        actor="eve",
        stream="system",
        subject="llama_cpp_metrics",
        payload={
            "configured_lanes": len(records),
            "ok_lanes": ok_count,
            "failed_lanes": max(0, len(records) - ok_count),
        },
        metadata={"timeout_seconds": timeout},
    )
    print(f"Collected llama.cpp metrics from {ok_count}/{len(records)} configured lane(s).")
    for record in records:
        metrics = record.get("metrics") if isinstance(record.get("metrics"), dict) else {}
        error_text = normalize_text_value(record.get("error"), fallback="", limit=160)
        status = "ok" if record.get("ok") else "failed"
        print(
            f"- {record.get('profile')}: {status} | {record.get('host')} | "
            f"metrics={len(metrics)}"
            + (f" | error={error_text}" if error_text else "")
        )
        if args.full and metrics:
            for name, value in list(metrics.items())[:20]:
                print(f"  {name}: {value}")
    return 0 if ok_count else 1


def trace_span_kind_for_openinference(span: Dict[str, object]) -> str:
    category = normalize_text_value(span.get("category"), fallback="general", limit=80).lower()
    name = normalize_text_value(span.get("name"), fallback="", limit=120).lower()
    if "memory" in category or "retrieve" in name:
        return "RETRIEVER"
    if "tool" in category or "action" in category or "tool." in name or "action." in name:
        return "TOOL"
    if "eval" in category or "training" in category or "score" in name:
        return "EVALUATOR"
    if "reply" in category or "model" in category or "lane" in name or "synthesize" in name:
        return "LLM"
    return "CHAIN"


def stable_openinference_id(value: object, *, length: int) -> str:
    return sha256_text(str(value or ""))[:length]


def trace_span_to_openinference(span: Dict[str, object], *, exported_at: Optional[str] = None) -> Dict[str, object]:
    attributes = span.get("attributes") if isinstance(span.get("attributes"), dict) else {}
    trace_id = normalize_text_value(span.get("trace_id"), fallback=span.get("id") or "", limit=200)
    span_id_source = normalize_text_value(span.get("id"), fallback=trace_id, limit=200)
    parent_id = normalize_text_value(span.get("parent_id"), fallback="", limit=200)
    openinference_attributes = {
        "openinference.span.kind": trace_span_kind_for_openinference(span),
        "eve.span.id": span_id_source,
        "eve.trace.id": trace_id,
        "eve.category": normalize_text_value(span.get("category"), fallback="general", limit=80),
        "eve.duration_ms": float(span.get("duration_ms") or 0.0),
        "eve.ok": bool(span.get("ok", True)),
        **{f"eve.attr.{key}": value for key, value in attributes.items()},
    }
    return {
        "schema_version": "eve_openinference_span.v1",
        "exported_at": exported_at or utc_now(),
        "name": normalize_text_value(span.get("name"), fallback="span", limit=240),
        "context": {
            "trace_id": stable_openinference_id(trace_id, length=32),
            "span_id": stable_openinference_id(span_id_source, length=16),
            "parent_id": stable_openinference_id(parent_id, length=16) if parent_id else "",
            "original_trace_id": trace_id,
            "original_span_id": span_id_source,
        },
        "start_time": normalize_text_value(span.get("started_at"), fallback="", limit=80),
        "end_time": normalize_text_value(span.get("ended_at"), fallback="", limit=80),
        "status_code": "OK" if bool(span.get("ok", True)) else "ERROR",
        "attributes": openinference_attributes,
    }


def build_openinference_trace_export(
    *,
    limit: int = 200,
    trace_id: str = "",
    category: str = "",
    prefer_runtime: bool = False,
) -> Tuple[Dict[str, object], List[Dict[str, object]]]:
    db_path = RUNTIME_OPERATIONAL_DB_PATH if prefer_runtime and RUNTIME_OPERATIONAL_DB_PATH.exists() else OPERATIONAL_DB_PATH
    spans = eve_db.read_trace_spans(
        db_path,
        limit=max(1, int(limit or 200)),
        trace_id=normalize_text_value(trace_id, fallback="", limit=200),
        category=normalize_text_value(category, fallback="", limit=80),
    )
    exported_at = utc_now()
    records = [trace_span_to_openinference(span, exported_at=exported_at) for span in spans]
    kind_counts: Dict[str, int] = {}
    for record in records:
        attrs = record.get("attributes") if isinstance(record.get("attributes"), dict) else {}
        kind = normalize_text_value(attrs.get("openinference.span.kind"), fallback="UNKNOWN", limit=40)
        kind_counts[kind] = kind_counts.get(kind, 0) + 1
    report = {
        "schema_version": "eve_openinference_export.v1",
        "exported_at": exported_at,
        "status": "ready" if records else "empty",
        "format": "openinference_jsonl",
        "db_path": str(db_path),
        "runtime_preferred": bool(prefer_runtime),
        "span_count": len(records),
        "kind_counts": kind_counts,
        "trace_id_filter": normalize_text_value(trace_id, fallback="", limit=200),
        "category_filter": normalize_text_value(category, fallback="", limit=80),
        "privacy": {
            "local_only": True,
            "hidden_probes_excluded_by_policy": True,
            "collector_required": False,
        },
    }
    return report, records


def save_openinference_trace_export(
    records: List[Dict[str, object]],
    *,
    output_path: Optional[Path] = None,
) -> Path:
    ensure_store()
    path = output_path or TRACE_EXPORT_LATEST_PATH
    path = path.expanduser()
    path.parent.mkdir(parents=True, exist_ok=True)
    eve_store.atomic_write_text(path, training_jsonl_text(records))
    if runtime_store_path(path) is not None:
        mirror_store_file_to_runtime(path)
    return path


def format_trace_export_report(report: Dict[str, object], *, output_path: Optional[Path] = None, full: bool = False) -> str:
    kinds = report.get("kind_counts") if isinstance(report.get("kind_counts"), dict) else {}
    lines = [
        "OpenInference trace export",
        f"status: {report.get('status')}",
        f"exported_at: {report.get('exported_at')}",
        f"spans: {report.get('span_count')}",
        "kinds: " + (", ".join(f"{key}={value}" for key, value in sorted(kinds.items())) if kinds else "none"),
    ]
    if output_path is not None:
        lines.append(f"output: {output_path}")
    if full:
        lines.append(f"db_path: {report.get('db_path')}")
        lines.append("privacy: local_only; no collector required; hidden probes remain outside Eve-readable exports")
    return "\n".join(lines)


def cmd_infra_trace_export(args: argparse.Namespace) -> int:
    report, records = build_openinference_trace_export(
        limit=args.limit,
        trace_id=args.trace_id or "",
        category=args.category or "",
        prefer_runtime=args.runtime,
    )
    output_path: Optional[Path] = None
    if not args.no_save:
        output_path = save_openinference_trace_export(
            records,
            output_path=Path(args.output).expanduser() if args.output else None,
        )
        report["output_path"] = str(output_path)
    if args.json:
        print(json.dumps(report, indent=2, ensure_ascii=True, sort_keys=True))
        return 0
    print(format_trace_export_report(report, output_path=output_path, full=args.full))
    return 0


