def governance_ledger_paths(*, prefer_runtime: bool = False) -> List[Tuple[str, Path]]:
    specs: List[Tuple[str, Path]] = [
        ("action_executions", resolve_store_read_path(ACTION_EXECUTIONS_PATH, prefer_runtime=prefer_runtime)),
        ("evidence_ledger", resolve_store_read_path(EVIDENCE_LEDGER_PATH, prefer_runtime=prefer_runtime)),
        ("experience_events", resolve_store_read_path(EXPERIENCE_EVENTS_PATH, prefer_runtime=prefer_runtime)),
        ("commitment_ledger", resolve_store_read_path(COMMITMENT_LEDGER_PATH, prefer_runtime=prefer_runtime)),
        (
            "openclaw_evidence_events",
            eve_openclaw_body.RUNTIME_OPENCLAW_EVIDENCE_EVENTS_PATH
            if prefer_runtime
            else eve_openclaw_body.OPENCLAW_EVIDENCE_EVENTS_PATH,
        ),
        (
            "openclaw_action_router_events",
            eve_openclaw_body.RUNTIME_OPENCLAW_ACTION_ROUTER_EVENTS_PATH
            if prefer_runtime
            else eve_openclaw_body.OPENCLAW_ACTION_ROUTER_EVENTS_PATH,
        ),
        (
            "openclaw_routine_events",
            eve_openclaw_body.RUNTIME_OPENCLAW_ROUTINE_EVENTS_PATH
            if prefer_runtime
            else eve_openclaw_body.OPENCLAW_ROUTINE_EVENTS_PATH,
        ),
        (
            "openclaw_worker_events",
            eve_openclaw_body.RUNTIME_OPENCLAW_WORKER_EVENTS_PATH
            if prefer_runtime
            else eve_openclaw_body.OPENCLAW_WORKER_EVENTS_PATH,
        ),
        (
            "openclaw_channel_events",
            eve_openclaw_body.RUNTIME_OPENCLAW_CHANNEL_EVENTS_PATH
            if prefer_runtime
            else eve_openclaw_body.OPENCLAW_CHANNEL_EVENTS_PATH,
        ),
        ("developmental_cycles", resolve_store_read_path(DEVELOPMENTAL_CYCLES_PATH, prefer_runtime=prefer_runtime)),
        ("reply_turn_replays", resolve_store_read_path(REPLY_TURN_REPLAYS_PATH, prefer_runtime=prefer_runtime)),
        ("reply_council_turns", resolve_store_read_path(REPLY_COUNCIL_TURNS_PATH, prefer_runtime=prefer_runtime)),
    ]
    return specs


def read_governance_events(
    *,
    limit: int = 40,
    prefer_runtime: bool = False,
    include_payload: bool = False,
) -> List[Dict[str, object]]:
    ensure_store()
    normalized: List[Dict[str, object]] = []
    per_ledger_limit = max(1, min(20, int(limit or 40)))
    governance_event_path = resolve_store_read_path(GOVERNANCE_EVENTS_PATH, prefer_runtime=prefer_runtime)
    for item in read_jsonl_tail_records(governance_event_path, per_ledger_limit):
        if not isinstance(item, dict):
            continue
        if item.get("schema_version") == eve_governance.EVENT_SCHEMA_VERSION:
            normalized.append(dict(item))
        else:
            normalized.append(
                eve_governance.normalize_ledger_event(
                    "governance_events",
                    item,
                    path=governance_event_path,
                    include_payload=include_payload,
                )
            )
    for ledger_id, path in governance_ledger_paths(prefer_runtime=prefer_runtime):
        records = read_jsonl_tail_records(path, per_ledger_limit)
        normalized.extend(
            eve_governance.normalize_ledger_records(
                ledger_id,
                records,
                path=path,
                include_payload=include_payload,
            )
        )
    normalized.sort(key=lambda item: str(item.get("timestamp") or ""), reverse=True)
    return normalized[: max(1, int(limit or 40))]


def local_event_ledger_path_for(anchor_path: Path) -> Path:
    if anchor_path.parent != APP_DIR:
        return anchor_path.parent / EVENT_LEDGER_PATH.name
    return EVENT_LEDGER_PATH


def append_eve_event_ledger_event(event: Dict[str, object], *, path: Optional[Path] = None) -> Dict[str, object]:
    ledger_path = path or EVENT_LEDGER_PATH
    saved = append_jsonl_record(ledger_path, event)
    if ledger_path == EVENT_LEDGER_PATH:
        mirror_store_file_to_runtime(EVENT_LEDGER_PATH)
    return saved


def governance_proposal_event(proposal: Dict[str, object], *, source_action: str) -> Dict[str, object]:
    proposal_id = str(proposal.get("id") or "")
    proposal_type = str(proposal.get("type") or "")
    review = proposal.get("review") if isinstance(proposal.get("review"), dict) else {}
    payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
    try:
        risk_level = int(proposal.get("risk_level") or 0)
    except (TypeError, ValueError):
        risk_level = 0
    return eve_governance.event_envelope(
        eve_governance.proposal_event_type(proposal_type),
        source=source_action,
        actor=str(proposal.get("source") or "eve"),
        payload={
            "proposal_id": proposal_id,
            "proposal_type": proposal_type,
            "proposal_source": proposal.get("source"),
            "review_decision": review.get("decision") or proposal.get("review_status"),
            "requires_approval": proposal.get("requires_approval"),
            "payload_summary": eve_governance.event_payload_summary(payload),
        },
        input_value=proposal,
        output_value=review or proposal,
        risk_level=risk_level,
        permissions_used=[str(item) for item in (proposal.get("permissions_used") or []) if str(item)],
        correlation_id=proposal_id,
        causation_id=proposal_id,
        human_visible=True,
        confidence=1.0,
        provenance=[f"governance_proposal:{proposal_id}"],
        cik_zone=str(proposal.get("cik_zone") or eve_governance.CIK_UNKNOWN),
        stream="governance",
        review_status=str(review.get("decision") or proposal.get("review_status") or "queued"),
    )


def append_governance_event(event: Dict[str, object]) -> Dict[str, object]:
    saved = append_jsonl_record(GOVERNANCE_EVENTS_PATH, event)
    append_eve_event_ledger_event(saved, path=local_event_ledger_path_for(GOVERNANCE_EVENTS_PATH))
    mirror_store_file_to_runtime(GOVERNANCE_EVENTS_PATH)
    return saved


def read_governance_proposals(
    *,
    limit: Optional[int] = 40,
    decision: Optional[str] = None,
    proposal_type: Optional[str] = None,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(GOVERNANCE_PROPOSALS_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_records(path)
    reviewed: List[Dict[str, object]] = []
    for item in records:
        if not isinstance(item, dict):
            continue
        proposal = eve_governance.reviewed_proposal(item)
        review = proposal.get("review") if isinstance(proposal.get("review"), dict) else {}
        proposal_decision = str(review.get("decision") or proposal.get("review_status") or "").strip()
        if decision and proposal_decision != decision:
            continue
        if proposal_type and str(proposal.get("type") or "") != proposal_type:
            continue
        reviewed.append(proposal)
    reviewed.sort(key=lambda item: str(item.get("timestamp") or ""), reverse=True)
    return reviewed[:limit] if limit is not None else reviewed


def append_governance_proposal(proposal: Dict[str, object]) -> Dict[str, object]:
    saved = append_jsonl_record(GOVERNANCE_PROPOSALS_PATH, proposal)
    append_eve_event_ledger_event(
        governance_proposal_event(saved, source_action="governance_proposal_queue"),
        path=local_event_ledger_path_for(GOVERNANCE_PROPOSALS_PATH),
    )
    return saved


def read_eve_event_ledger(
    *,
    limit: int = 40,
    prefer_runtime: bool = False,
) -> List[Dict[str, object]]:
    path = resolve_store_read_path(EVENT_LEDGER_PATH, prefer_runtime=prefer_runtime)
    records = read_jsonl_tail_records(path, max(1, int(limit or 40)))
    events = [dict(item) for item in records if isinstance(item, dict)]
    events.sort(key=lambda item: str(item.get("timestamp") or item.get("created_at") or ""), reverse=True)
    return events[: max(1, int(limit or 40))]


def eve_event_ledger_status(*, limit: int = 20, prefer_runtime: bool = False) -> Dict[str, object]:
    path = resolve_store_read_path(EVENT_LEDGER_PATH, prefer_runtime=prefer_runtime)
    events = read_eve_event_ledger(limit=limit, prefer_runtime=prefer_runtime)
    by_type: Dict[str, int] = {}
    by_source: Dict[str, int] = {}
    by_zone: Dict[str, int] = {}
    for event in events:
        event_type = str(event.get("type") or "unknown")
        source = str(event.get("source") or "unknown")
        zone = str(event.get("cik_zone") or "unknown")
        by_type[event_type] = by_type.get(event_type, 0) + 1
        by_source[source] = by_source.get(source, 0) + 1
        by_zone[zone] = by_zone.get(zone, 0) + 1
    return {
        "schema_version": "eve_event_ledger_status.v1",
        "generated_at": utc_now(),
        "path": str(path),
        "exists": path.exists(),
        "record_count": count_jsonl_records(path) if path.exists() else 0,
        "sample_count": len(events),
        "type_counts": dict(sorted(by_type.items())),
        "source_counts": dict(sorted(by_source.items())),
        "cik_zone_counts": dict(sorted(by_zone.items())),
        "latest": events[:5],
    }


def rebuild_eve_event_ledger(*, limit: int = 500, dry_run: bool = False) -> Dict[str, object]:
    bounded_limit = max(1, int(limit or 500))
    existing_events = read_eve_event_ledger(limit=bounded_limit)
    existing_queue_proposal_ids = {
        str(event.get("correlation_id") or "")
        for event in existing_events
        if str(event.get("source") or "") == "governance_proposal_queue"
    }
    proposal_events: List[Dict[str, object]] = []
    for proposal in read_governance_proposals(limit=bounded_limit):
        proposal_id = str(proposal.get("id") or "")
        if not proposal_id or proposal_id in existing_queue_proposal_ids:
            continue
        event = governance_proposal_event(proposal, source_action="governance_proposal_queue")
        event["id"] = "evt_proposal_" + hashlib.sha256(proposal_id.encode("utf-8")).hexdigest()[:24]
        event["timestamp"] = str(proposal.get("timestamp") or event.get("timestamp") or utc_now())
        proposal_events.append(event)
    normalized_events = [
        *existing_events,
        *proposal_events,
        *read_governance_events(limit=bounded_limit, include_payload=True),
    ]
    seen: Set[str] = set()
    rebuilt: List[Dict[str, object]] = []
    for event in reversed(normalized_events):
        event_id = str(event.get("id") or "")
        if not event_id or event_id in seen:
            continue
        seen.add(event_id)
        rebuilt.append(dict(event))
    rebuilt.sort(key=lambda item: str(item.get("timestamp") or item.get("created_at") or ""))
    if not dry_run:
        write_jsonl_records(EVENT_LEDGER_PATH, rebuilt)
        mirror_store_file_to_runtime(EVENT_LEDGER_PATH)
    return {
        "schema_version": "eve_event_ledger_rebuild.v1",
        "path": str(EVENT_LEDGER_PATH),
        "dry_run": bool(dry_run),
        "source_event_count": len(normalized_events),
        "written_event_count": len(rebuilt) if not dry_run else 0,
        "would_write_event_count": len(rebuilt),
        "latest_event_id": rebuilt[-1].get("id") if rebuilt else "",
    }


def governance_review_artifact_path(kind: str) -> Path:
    safe_kind = re.sub(r"[^a-z0-9_-]+", "-", str(kind or "review").lower()).strip("-") or "review"
    return GOVERNANCE_REVIEWS_DIR / f"{safe_kind}-{utc_timestamp_for_filename()}.json"


def save_governance_review_artifact(record: Dict[str, object], *, kind: str) -> Dict[str, object]:
    GOVERNANCE_REVIEWS_DIR.mkdir(parents=True, exist_ok=True)
    artifact_path = governance_review_artifact_path(kind)
    latest_path = GOVERNANCE_REVIEWS_DIR / f"latest_{kind}.json"
    record["artifact_path"] = str(artifact_path)
    record["latest_path"] = str(latest_path)
    eve_store.write_json_dict(artifact_path, record, indent=2, sort_keys=True)
    eve_store.write_json_dict(latest_path, record, indent=2, sort_keys=True)
    mirror_store_file_to_runtime(artifact_path)
    mirror_store_file_to_runtime(latest_path)
    return record


def governance_lifecycle_counts(proposals: List[Dict[str, object]]) -> Dict[str, object]:
    by_type: Dict[str, int] = {}
    by_decision: Dict[str, int] = {}
    by_approval: Dict[str, int] = {}
    by_canary: Dict[str, int] = {}
    by_application: Dict[str, int] = {}
    for proposal in proposals:
        review = proposal.get("review") if isinstance(proposal.get("review"), dict) else {}
        proposal_type = str(proposal.get("type") or "unknown")
        decision = str(review.get("decision") or proposal.get("review_status") or "pending")
        approval = governance_proposal_approval_status(proposal)
        canary = governance_proposal_canary_status(proposal)
        application = governance_proposal_application_status(proposal)
        by_type[proposal_type] = by_type.get(proposal_type, 0) + 1
        by_decision[decision] = by_decision.get(decision, 0) + 1
        by_approval[approval] = by_approval.get(approval, 0) + 1
        by_canary[canary] = by_canary.get(canary, 0) + 1
        by_application[application] = by_application.get(application, 0) + 1
    return {
        "by_type": dict(sorted(by_type.items())),
        "by_decision": dict(sorted(by_decision.items())),
        "by_approval": dict(sorted(by_approval.items())),
        "by_canary": dict(sorted(by_canary.items())),
        "by_application": dict(sorted(by_application.items())),
    }


def governance_status_from_severity(max_severity: int, *, warnings: int = 0) -> str:
    if max_severity >= 4:
        return "blocking"
    if max_severity >= 3:
        return "review"
    if max_severity >= 1 or warnings:
        return "watch"
    return "clean"


def build_governance_daily_review(*, limit: int = 80, save: bool = True) -> Dict[str, object]:
    ensure_store()
    bounded_limit = max(1, int(limit or 80))
    proposals = read_governance_proposals(limit=bounded_limit)
    events = read_eve_event_ledger(limit=bounded_limit)
    event_status = eve_event_ledger_status(limit=min(40, bounded_limit))
    watchers = eve_governance.watcher_report(proposals, events=events[:20])
    lifecycle = governance_lifecycle_counts(proposals)
    blocking_warnings = governance_watcher_blocking_warnings(watchers, min_severity=4)
    review_warnings = governance_watcher_blocking_warnings(watchers, min_severity=3)
    unreviewed = [proposal for proposal in proposals if governance_proposal_approval_status(proposal) == "unreviewed"]
    canary_pending = [
        proposal
        for proposal in proposals
        if str(proposal.get("type") or "") in {"SkillPatchProposal", "CodePatchProposal", "CapabilityPatchProposal"}
        and governance_proposal_canary_status(proposal) != "passed"
    ]
    queued_skill_candidates = [proposal for proposal in proposals if str(proposal.get("type") or "") == "SkillPatchProposal"]
    recommendations: List[str] = []
    if not bool(event_status.get("exists")) or int(event_status.get("record_count") or 0) == 0:
        recommendations.append("Run `python3 eve.py governance event-ledger --rebuild --limit 300` before trusting review summaries.")
    if blocking_warnings:
        recommendations.append("Resolve watcher blocking warnings before approving, canarying, or applying additional proposals.")
    elif review_warnings:
        recommendations.append("Inspect watcher review-severity warnings before promoting any proposal.")
    if unreviewed:
        recommendations.append(f"Review {len(unreviewed)} unreviewed proposal(s) with `python3 eve.py governance queue --full`.")
    if canary_pending:
        recommendations.append(f"Record canary evidence for {len(canary_pending)} skill/code/capability proposal(s) before any enablement path.")
    if queued_skill_candidates:
        recommendations.append("Keep skill proposals lab-only until a separate enablement path proves purpose, tests, watcher gate, and rollback.")
    if not recommendations:
        recommendations.append("No blocking governance work found in the current sample; keep collecting ledger evidence.")

    record: Dict[str, object] = {
        "schema_version": "eve_governance_daily_review.v1",
        "generated_at": utc_now(),
        "limit": bounded_limit,
        "status": governance_status_from_severity(
            int(watchers.get("max_severity") or 0),
            warnings=int(watchers.get("total_warnings") or 0),
        ),
        "event_ledger": event_status,
        "proposal_count": len(proposals),
        "event_sample_count": len(events),
        "lifecycle_counts": lifecycle,
        "watchers": watchers,
        "blocking_warning_count": len(blocking_warnings),
        "review_warning_count": len(review_warnings),
        "unreviewed_proposal_ids": [str(item.get("id") or "") for item in unreviewed[:12]],
        "canary_pending_proposal_ids": [str(item.get("id") or "") for item in canary_pending[:12]],
        "skill_candidate_ids": [str(item.get("id") or "") for item in queued_skill_candidates[:12]],
        "recommendations": recommendations,
    }
    if save:
        save_governance_review_artifact(record, kind="daily_review")
        event = eve_governance.event_envelope(
            "ReflectionEvent",
            source="governance_daily_review",
            actor="eve",
            payload={
                "status": record.get("status"),
                "proposal_count": record.get("proposal_count"),
                "event_sample_count": record.get("event_sample_count"),
                "blocking_warning_count": record.get("blocking_warning_count"),
                "recommendations": recommendations[:6],
                "artifact_path": record.get("artifact_path"),
            },
            output_value=record,
            risk_level=1,
            permissions_used=["governance_review"],
            human_visible=True,
            confidence=1.0,
            provenance=[f"artifact:{record.get('artifact_path')}"] if record.get("artifact_path") else [],
            cik_zone=eve_governance.CIK_KNOWLEDGE,
            stream="governance",
            review_status=str(record.get("status") or "watch"),
        )
        saved_event = append_governance_event(event)
        record["governance_event_id"] = saved_event.get("id")
        save_governance_review_artifact(record, kind="daily_review")
    return record


def build_governance_skill_audit(*, limit: int = 120, save: bool = True) -> Dict[str, object]:
    ensure_store()
    bounded_limit = max(1, int(limit or 120))
    proposals = read_governance_proposals(limit=bounded_limit, proposal_type="SkillPatchProposal")
    findings: List[Dict[str, object]] = []
    audited: List[Dict[str, object]] = []
    max_severity = 0
    for proposal in proposals:
        payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
        proposal_id = str(proposal.get("id") or "")
        approval = governance_proposal_approval_status(proposal)
        canary = governance_proposal_canary_status(proposal)
        application = governance_proposal_application_status(proposal)
        enabled = bool(payload.get("enabled_for_eve"))
        adds_chat_lane = bool(payload.get("adds_chat_lane"))
        tests = normalize_text_list(payload.get("tests"), limit=12)
        skill_name = normalize_text_value(payload.get("skill_name"), fallback=proposal_id, limit=160)

        def add_finding(code: str, severity: int, message: str) -> None:
            nonlocal max_severity
            max_severity = max(max_severity, severity)
            findings.append(
                {
                    "proposal_id": proposal_id,
                    "skill_name": skill_name,
                    "code": code,
                    "severity": severity,
                    "message": message,
                }
            )

        if adds_chat_lane:
            add_finding("skill_attempts_chat_lane", 4, "Skill proposals must not add a sixth always-on Eve lane.")
        if enabled and (approval != "approved" or canary != "passed"):
            add_finding("enabled_without_completed_gate", 4, "Enabled skill lacks completed approval and canary gates.")
        if not tests:
            add_finding("missing_skill_tests", 3, "Skill proposal lacks required smoke or regression tests.")
        if approval != "approved":
            add_finding("approval_pending", 2, "Skill proposal has not been explicitly approved.")
        if canary != "passed":
            add_finding("canary_pending", 2, "Skill proposal has not passed canary evidence.")
        if approval == "approved" and canary == "passed" and not enabled:
            add_finding("approved_lab_only_not_enabled", 1, "Skill is admitted for lab review only and remains disabled for Eve.")

        audited.append(
            {
                "proposal_id": proposal_id,
                "skill_name": skill_name,
                "approval": approval,
                "canary": canary,
                "application": application,
                "enabled_for_eve": enabled,
                "adds_chat_lane": adds_chat_lane,
                "tests": tests,
                "permission_class": payload.get("permission_class"),
            }
        )

    status = governance_status_from_severity(max_severity, warnings=len(findings))
    recommendations: List[str] = []
    if max_severity >= 4:
        recommendations.append("Block skill enablement until high-severity audit findings are resolved.")
    if any(str(finding.get("code")) == "missing_skill_tests" for finding in findings):
        recommendations.append("Add or rerun the required skill smoke/regression tests before admission.")
    if any(str(finding.get("code")) == "approval_pending" for finding in findings):
        recommendations.append("Record explicit approval or rejection for pending skill proposals.")
    if any(str(finding.get("code")) == "canary_pending" for finding in findings):
        recommendations.append("Record canary status with evidence before treating a skill as admissible.")
    if any(str(finding.get("code")) == "approved_lab_only_not_enabled" for finding in findings):
        recommendations.append("Approved/canaried skills remain lab-only until a separate enablement path is built and reviewed.")
    if not proposals:
        recommendations.append("No skill proposals found in the sampled governance queue.")
    elif not recommendations:
        recommendations.append("No blocking skill-audit issues found; keep skills proposal-only unless separately enabled.")

    record: Dict[str, object] = {
        "schema_version": "eve_governance_skill_audit.v1",
        "generated_at": utc_now(),
        "limit": bounded_limit,
        "status": status,
        "skill_proposal_count": len(proposals),
        "audited_skills": audited,
        "finding_count": len(findings),
        "max_severity": max_severity,
        "findings": findings,
        "recommendations": recommendations,
        "enables_any_skill": any(bool(item.get("enabled_for_eve")) for item in audited),
        "adds_chat_lane_count": sum(1 for item in audited if bool(item.get("adds_chat_lane"))),
    }
    if save:
        save_governance_review_artifact(record, kind="skill_audit")
        event = eve_governance.event_envelope(
            "EvalResultEvent",
            source="governance_skill_audit",
            actor="eve",
            payload={
                "status": record.get("status"),
                "skill_proposal_count": record.get("skill_proposal_count"),
                "finding_count": record.get("finding_count"),
                "max_severity": record.get("max_severity"),
                "recommendations": recommendations[:6],
                "artifact_path": record.get("artifact_path"),
            },
            output_value=record,
            risk_level=1,
            permissions_used=["governance_skill_audit"],
            human_visible=True,
            confidence=1.0,
            provenance=[f"artifact:{record.get('artifact_path')}"] if record.get("artifact_path") else [],
            cik_zone=eve_governance.CIK_CAPABILITY,
            stream="governance",
            review_status=status,
        )
        saved_event = append_governance_event(event)
        record["governance_event_id"] = saved_event.get("id")
        save_governance_review_artifact(record, kind="skill_audit")
    return record


APPLIABLE_KNOWLEDGE_PROPOSAL_TYPES = {
    "MemoryPatchProposal": "governance_memory_patch",
    "UserModelPatchProposal": "governance_user_model_patch",
}

MEMORY_REVIEW_APPLY_PROPOSAL_TYPES = {"MemoryPatchProposal", "UserModelPatchProposal"}
GOVERNANCE_APPROVAL_DECISIONS = {"approved", "rejected"}
GOVERNANCE_CANARY_STATUSES = {"planned", "running", "passed", "failed", "cancelled"}


def find_governance_proposal_record(proposal_id: str) -> Dict[str, object]:
    records = read_jsonl_records(GOVERNANCE_PROPOSALS_PATH)
    index = find_record_index(records, proposal_id)
    return dict(records[index])


def update_governance_proposal_record(proposal_id: str, **changes: object) -> Dict[str, object]:
    with store_lock(GOVERNANCE_PROPOSALS_PATH):
        records = read_jsonl_records(GOVERNANCE_PROPOSALS_PATH)
        index = find_record_index(records, proposal_id)
        record = dict(records[index])
        record.update(changes)
        record["updated_at"] = utc_now()
        records[index] = record
        write_jsonl_records(GOVERNANCE_PROPOSALS_PATH, records)
    mirror_store_file_to_runtime(GOVERNANCE_PROPOSALS_PATH)
    return record


def governance_proposal_application_status(proposal: Dict[str, object]) -> str:
    application = proposal.get("application") if isinstance(proposal.get("application"), dict) else {}
    return str(application.get("status") or "queued")


def governance_proposal_approval_status(proposal: Dict[str, object]) -> str:
    approval = proposal.get("approval") if isinstance(proposal.get("approval"), dict) else {}
    return str(approval.get("status") or "unreviewed")


def governance_proposal_canary_status(proposal: Dict[str, object]) -> str:
    canary = proposal.get("canary") if isinstance(proposal.get("canary"), dict) else {}
    return str(canary.get("status") or "not_started")


def governance_proposal_claim(proposal: Dict[str, object]) -> str:
    payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
    for key in ["claim", "summary", "preference", "fact", "learning", "memory", "text", "title"]:
        claim = normalize_text_value(payload.get(key), fallback="", limit=500)
        if claim:
            return claim
    return ""


def governance_proposal_summary(proposal: Dict[str, object], claim: str) -> str:
    payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
    summary = normalize_text_value(payload.get("summary"), fallback="", limit=500)
    if summary:
        return summary
    return claim


def governance_proposal_confidence(proposal: Dict[str, object]) -> float:
    payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
    for key in ["confidence", "confidence_score"]:
        try:
            return max(0.0, min(1.0, float(payload.get(key))))
        except (TypeError, ValueError):
            continue
    return 0.75


def governance_proposal_ttl_hours(proposal: Dict[str, object]) -> int:
    payload = proposal.get("payload") if isinstance(proposal.get("payload"), dict) else {}
    try:
        return max(24, int(payload.get("ttl_hours") or 8760))
    except (TypeError, ValueError):
        return 8760


def governance_watcher_blocking_warnings(report: Dict[str, object], *, min_severity: int = 4) -> List[Dict[str, object]]:
    return [
        warning
        for watcher in report.get("watchers", [])
        if isinstance(watcher, dict)
        for warning in (watcher.get("warnings") or [])
        if isinstance(warning, dict) and int(warning.get("severity") or 0) >= min_severity
    ]


def governance_watcher_gate(proposal: Dict[str, object], *, min_severity: int = 4) -> Dict[str, object]:
    reviewed = eve_governance.reviewed_proposal(proposal)
    report = eve_governance.watcher_report([reviewed])
    blocking = governance_watcher_blocking_warnings(report, min_severity=min_severity)
    return {
        "schema_version": "eve_governance_watcher_gate.v1",
        "proposal_id": str(reviewed.get("id") or ""),
        "min_blocking_severity": int(min_severity),
        "watchers": report,
        "blocking_warnings": blocking,
        "can_pass": not blocking,
    }


def governance_apply_plan(proposal: Dict[str, object]) -> Dict[str, object]:
    reviewed = eve_governance.reviewed_proposal(proposal)
    review = reviewed.get("review") if isinstance(reviewed.get("review"), dict) else {}
    proposal_type = str(reviewed.get("type") or "")
    proposal_id = str(reviewed.get("id") or "")
    target_zone = str(reviewed.get("cik_zone") or "")
    evidence_refs = [str(item) for item in (reviewed.get("evidence") or []) if str(item)]
    claim = governance_proposal_claim(reviewed)
    approval_status = governance_proposal_approval_status(reviewed)
    reasons: List[str] = []

    if governance_proposal_application_status(reviewed) == "applied":
        reasons.append("proposal_already_applied")
    if proposal_type not in APPLIABLE_KNOWLEDGE_PROPOSAL_TYPES:
        reasons.append("unsupported_apply_type")
    if target_zone != eve_governance.CIK_KNOWLEDGE:
        reasons.append("target_zone_not_knowledge")
    if str(review.get("decision") or "") != "accept":
        reasons.append(f"review_decision_{review.get('decision') or 'unknown'}")
    if bool(reviewed.get("requires_approval")) and approval_status != "approved":
        reasons.append("explicit_approval_required")
    if approval_status == "rejected":
        reasons.append("approval_rejected")
    try:
        if int(reviewed.get("risk_level") or 0) > 2:
            reasons.append("risk_level_too_high")
    except (TypeError, ValueError):
        reasons.append("invalid_risk_level")
    if not evidence_refs:
        reasons.append("missing_evidence")
    if not claim:
        reasons.append("missing_claim")

    watcher_gate = governance_watcher_gate(reviewed, min_severity=3)
    watcher_report = watcher_gate["watchers"] if isinstance(watcher_gate.get("watchers"), dict) else {}
    watcher_blocking = watcher_gate.get("blocking_warnings") if isinstance(watcher_gate.get("blocking_warnings"), list) else []
    if watcher_blocking:
        reasons.append("watcher_review_required")
    memory_integrity_warnings = [
        warning
        for watcher in watcher_report.get("watchers", [])
        if isinstance(watcher, dict) and watcher.get("id") == "memory_integrity"
        for warning in (watcher.get("warnings") or [])
        if isinstance(warning, dict) and warning.get("code") == "memory_state_change"
    ]
    if (
        proposal_type in MEMORY_REVIEW_APPLY_PROPOSAL_TYPES
        and memory_integrity_warnings
        and approval_status != "approved"
    ):
        reasons.append("memory_integrity_approval_required")

    return {
        "schema_version": "eve_governance_apply_plan.v1",
        "proposal": reviewed,
        "proposal_id": proposal_id,
        "proposal_type": proposal_type,
        "approval_status": approval_status,
        "claim": claim,
        "summary": governance_proposal_summary(reviewed, claim),
        "evidence_refs": evidence_refs,
        "target_kind": APPLIABLE_KNOWLEDGE_PROPOSAL_TYPES.get(proposal_type, ""),
        "watchers": watcher_report,
        "watcher_gate": watcher_gate,
        "memory_integrity_warnings": memory_integrity_warnings,
        "can_apply": not reasons,
        "reasons": reasons,
    }


