def cmd_governance_ingest_hermes(args: argparse.Namespace) -> int:
    try:
        payload = parse_governance_json_source(
            payload_json=str(args.payload_json or ""),
            file_path=str(args.file or ""),
        )
        proposals = eve_governance.proposal_envelopes_from_adapter_payload(
            payload,
            default_source=str(args.source or "hermes"),
        )
    except (OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    reviewed = [eve_governance.reviewed_proposal(proposal) for proposal in proposals]
    saved = reviewed
    if not bool(args.dry_run):
        saved = [append_governance_proposal(proposal) for proposal in reviewed]
        mirror_store_file_to_runtime(GOVERNANCE_PROPOSALS_PATH)
    report = eve_governance.watcher_report(saved)
    payload_out = {
        "schema_version": "eve_governance_ingest.v1",
        "source": str(args.source or "hermes"),
        "stored": not bool(args.dry_run),
        "proposal_count": len(saved),
        "proposals": saved,
        "watchers": report,
    }
    if args.json:
        print(json.dumps(payload_out, indent=2, ensure_ascii=True, sort_keys=True))
        return 0
    mode = "dry-run" if args.dry_run else "stored"
    print(
        f"Ingested {len(saved)} Hermes-style proposal(s) into governance ({mode}); "
        f"watchers={report.get('status')} warnings={report.get('total_warnings')}"
    )
    for proposal in saved:
        print(format_governance_proposal(proposal, full=bool(args.full)))
    return 0


