def cmd_governance_code_lifecycle(args: argparse.Namespace) -> int:
    try:
        stored = True
        if str(getattr(args, "payload_json", "") or "").strip() or str(getattr(args, "file", "") or "").strip():
            payload = parse_governance_json_source(
                payload_json=str(args.payload_json or ""),
                file_path=str(args.file or ""),
            )
            proposals = eve_governance.proposal_envelopes_from_adapter_payload(
                payload,
                default_source=str(args.source or "codex"),
            )
            if len(proposals) != 1 or str(proposals[0].get("type") or "") != "CodePatchProposal":
                raise ValueError("Provide exactly one CodePatchProposal for code-lifecycle payload mode.")
            proposal = eve_governance.reviewed_proposal(proposals[0])
            stored = False
        elif str(args.proposal_id or "").strip():
            proposal = find_governance_proposal_record(str(args.proposal_id))
        else:
            raise ValueError("Provide a proposal id, --payload-json, or --file.")
        plan = governance_code_patch_lifecycle_plan(proposal, stored=stored)
    except (OSError, IndexError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 2
    if args.json:
        print(json.dumps(plan, indent=2, ensure_ascii=True, sort_keys=True))
    else:
        print(format_governance_code_lifecycle(plan, full=bool(args.full)))
    return 0 if str(plan.get("status") or "") != "blocked" else 1


